<?php

declare(strict_types=1);

namespace MathPHP\Solver;

use MathPHP\Ast\BinaryOperationNode;
use MathPHP\Ast\BinaryOperator;
use MathPHP\Ast\ConstantNode;
use MathPHP\Ast\FactorialNode;
use MathPHP\Ast\FunctionCallNode;
use MathPHP\Ast\GroupingNode;
use MathPHP\Ast\Node;
use MathPHP\Ast\NumberNode;
use MathPHP\Ast\RationalLiteral;
use MathPHP\Ast\UnaryOperationNode;
use MathPHP\Ast\UnaryOperator;
use MathPHP\Ast\VariableNode;
use MathPHP\Configuration\EvaluationOptions;
use MathPHP\Configuration\ResourceLimits;
use MathPHP\Evaluator\Environment;
use MathPHP\Evaluator\Evaluator;
use MathPHP\Exception\EvaluationException;
use MathPHP\Exception\LexicalException;
use MathPHP\Exception\MathException;
use MathPHP\Exception\ParseException;
use MathPHP\Function\SpecialFunctions;
use MathPHP\Parser\Lexer;
use MathPHP\Parser\Parser;
use MathPHP\Source\SourceSpan;

final class EquationSolver
{
    // The first negative lobe's Taylor upper bound is below 0.22 in magnitude;
    // subsequent negative lobes have strictly larger denominators.
    private const SINC_GLOBAL_LOWER_BOUND = -11.0 / 50.0;

    private const BESSEL_J0_MONOTONE_LIMIT = 3.8;

    private const MAX_ROOT_DEGREE_SCAN_WORK = 65_536;

    private const MAX_HIGH_VARIATION_INTERVAL_WORK = 1_000_000;

    private const MAX_DOMAIN_BOUNDARY_PROBES = 32_768;

    private const MAX_DOMAIN_TRANSITION_REFINEMENTS = 256;

    private const MAX_DOMAIN_TRANSITION_BISECTIONS = 128;

    private const MAX_BESSEL_DOMAIN_SEGMENTS = 256;

    private const MAX_DOMAIN_RECOVERY_DEPTH = 16;

    private const MAX_MODULO_SCAN_WORK = 65_536;

    private const MAX_PERIODIC_ROOTS = 65_536;

    private const MAX_PERIODIC_SUM_TERMS = 512;

    private const MAX_PERIODIC_SUM_PRODUCT_PAIRS = 256;

    private const MAX_ADAPTIVE_SCAN_STEPS = SolverOptions::MAX_SCAN_STEPS;

    private const MAX_POLYNOMIAL_PHASE_SAMPLE_POSITIONS = 65_536;

    private const MAX_PRIMARY_POLYNOMIAL_PHASE_SAMPLE_POSITIONS = 2_048;

    private int $finiteRationalTrigonometricReductionDepth = 0;

    private const MAX_NESTED_INVERSE_SOLVES = 256;

    /** @var array<string, list<string>> */
    private const INVERSE_COMPOSITION_PAIRS = [
        'exp' => ['ln'],
        'expm1' => ['log1p'],
        'sin' => ['asin', 'arcsin'],
        'cos' => ['acos', 'arccos'],
        'tanh' => ['atanh', 'arctanh'],
        'cosh' => ['acosh', 'arccosh'],
        'sech' => ['asech'],
        'csch' => ['acsch'],
        'coth' => ['acoth'],
        'sinh' => ['asinh', 'arcsinh'],
        'tan' => ['atan', 'arctan'],
        'ln' => ['exp'],
        'log1p' => ['expm1'],
        'asinh' => ['sinh'],
        'arcsinh' => ['sinh'],
        'atanh' => ['tanh'],
        'arctanh' => ['tanh'],
        'acosh' => ['cosh'],
        'arccosh' => ['cosh'],
        'asech' => ['sech'],
        'acsch' => ['csch'],
        'acoth' => ['coth'],
        'erf' => ['erfinv'],
        'erfc' => ['erfcinv'],
        'erfinv' => ['erf'],
        'erfcinv' => ['erfc'],
        'asin' => ['sin'],
        'arcsin' => ['sin'],
        'acos' => ['cos'],
        'arccos' => ['cos'],
        'atan' => ['tan'],
        'arctan' => ['tan'],
        'asec' => ['sec'],
        'acsc' => ['csc'],
        'acot' => ['cot'],
    ];

    /** @var list<string> */
    private const TOP_LEVEL_INVERSE_COMPOSITION_OUTERS = [
        'sinh', 'tan', 'ln', 'log1p', 'asinh', 'arcsinh', 'atanh', 'arctanh',
        'acosh', 'arccosh', 'asech', 'acsch', 'acoth', 'erf', 'erfc', 'erfinv', 'erfcinv',
        'asin', 'arcsin', 'acos', 'arccos', 'atan', 'arctan',
        'asec', 'acsc', 'acot',
    ];

    private const MAX_DISCRETE_INTERVAL_COMBINATIONS = 4096;

    private const MAX_BESSEL_INTERVAL_ORDERS = 64;

    private const MAX_CUBE_ROOT_RESULTANT_TERMS = 6;

    private const MAX_SQUARE_ROOT_RESULTANT_TERMS = 8;

    private const MAX_ROOT_PAIR_EXTENSION_DEGREE = 8;

    private const MAX_SMALL_ROOT_EXPANSION_TERMS = 16_384;

    private const MAX_SMALL_ROOT_TOTAL_DEGREE = 40;

    private static ?ExactRationalInterval $inverseTrigPiEnclosure = null;

    private ?int $nestedInverseSolveBudget = null;

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>
     */
    public function solve(
        string $equation,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            $position = $evaluationOptions->limits->maxExpressionLength;
            throw new LexicalException(
                'Equation exceeds the configured byte limit',
                'limit.expression_length',
                new SourceSpan($position, $position + 1),
            );
        }

        if (
            \preg_match('/\A[A-Za-z_][A-Za-z0-9_]*\z/D', $variable) !== 1
            || \in_array($variable, ['pi', 'e', 'tau', 'phi', 'eulerGamma', 'catalan', 'apery'], true)
        ) {
            throw new \InvalidArgumentException(
                'The solved variable must be a non-reserved ASCII identifier.',
            );
        }

        if (\array_key_exists($variable, $parameters)) {
            throw new \InvalidArgumentException(
                'The solved variable cannot also be supplied as a parameter.',
            );
        }

        if (
            \is_nan($lowerBound)
            || \is_nan($upperBound)
            || $lowerBound > $upperBound
            || $lowerBound === \INF
            || $upperBound === -\INF
        ) {
            throw new \InvalidArgumentException(
                'The solving interval must have nondecreasing bounds with infinities only at its open ends.',
            );
        }

        if (\substr_count($equation, '=') > 1) {
            return $this->solveChainedEquality(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }

        [$leftExpression, $rightExpression, $rightOffset] = $this->splitEquation($equation);
        $left = $this->parseSide($leftExpression, 0, $evaluationOptions);
        $right = $this->parseSide($rightExpression, $rightOffset, $evaluationOptions);
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $functionSide = $this->unwrapGrouping($functionSide);
            if (
                !$functionSide instanceof FunctionCallNode
                || !\in_array($functionSide->name, ['atanh', 'arctanh'], true)
                || \count($functionSide->arguments) !== 1
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionSide->arguments[0]);
            if (!$argument instanceof VariableNode || $argument->name !== $variable) {
                continue;
            }
            $targetCoefficients = (new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            ))->extract($targetSide);
            if (
                $targetCoefficients === null
                || \count($targetCoefficients) !== 1
                || !\is_finite($targetCoefficients[0])
                || \abs($targetCoefficients[0]) < 8.0
            ) {
                continue;
            }
            $target = $targetCoefficients[0];
            $inverseCandidate = \tanh($target);
            $candidateResidualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            if (
                \abs($inverseCandidate) < 1.0
                && $inverseCandidate >= $lowerBound
                && $inverseCandidate <= $upperBound
            ) {
                $residual = $candidateResidualAt($inverseCandidate);
                if ($residual !== null) {
                    return [new EquationSolution($inverseCandidate, \abs($residual), 0)];
                }
            }
            $representableCandidate = $this->bestRepresentableInverseCandidate(
                'atanh',
                $inverseCandidate,
                $target,
                null,
                $lowerBound,
                $upperBound,
                $candidateResidualAt,
            );
            if ($representableCandidate !== null) {
                return [new EquationSolution(
                    $representableCandidate[0],
                    \abs($representableCandidate[1]),
                    0,
                )];
            }
        }
        $exactLinearSolutions = $this->solveExactLinearRationalEquation(
            $left,
            $right,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($exactLinearSolutions !== null) {
            return $exactLinearSolutions;
        }
        $boundaryTargetExtractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $periodicBoundarySolutions = $this->solvePeriodicBoundaryTargetEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $boundaryTargetExtractor,
        );
        if ($periodicBoundarySolutions !== null) {
            return $periodicBoundarySolutions;
        }
        $earlyExtractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if (
            $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $earlyExtractor,
            )
            || $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $earlyExtractor,
            )
            || $this->containsEverywhereUndefinedSquareRoot(
                $left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $earlyExtractor,
                $evaluationOptions,
                $solverOptions,
            )
            || $this->containsEverywhereUndefinedSquareRoot(
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $earlyExtractor,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            return [];
        }
        if (
            \is_finite($lowerBound)
            && \is_finite($upperBound)
            && $lowerBound < $upperBound
            && $this->isSafeForElementaryRangePruning($left)
            && $this->isSafeForElementaryRangePruning($right)
            && (
                $this->hasReciprocalTrigonometricPhase($left, $variable, $earlyExtractor)
                || $this->hasReciprocalTrigonometricPhase($right, $variable, $earlyExtractor)
            )
            && (
                ($this->containsNamedFunction($left, 'exp') && $this->containsVariable($left, $variable))
                || ($this->containsNamedFunction($right, 'exp') && $this->containsVariable($right, $variable))
            )
        ) {
            $leftRange = $this->boundedExpressionRange(
                $left,
                $earlyExtractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            $rightRange = $this->boundedExpressionRange(
                $right,
                $earlyExtractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $leftRange !== null
                && $rightRange !== null
                && \is_finite($leftRange[0])
                && \is_finite($leftRange[1])
                && \is_finite($rightRange[0])
                && \is_finite($rightRange[1])
            ) {
                $scale = \max(
                    \abs($leftRange[0]),
                    \abs($leftRange[1]),
                    \abs($rightRange[0]),
                    \abs($rightRange[1]),
                    \PHP_FLOAT_MIN,
                );
                $separation = \max(
                    $leftRange[0] - $rightRange[1],
                    $rightRange[0] - $leftRange[1],
                );
                if ($separation > 32.0 * \PHP_FLOAT_EPSILON * $scale) {
                    return [];
                }
            }
        }
        $earlyLeft = $this->unwrapGrouping($left);
        $earlyRight = $this->unwrapGrouping($right);
        foreach ([[$earlyLeft, $right, $leftExpression], [$earlyRight, $left, $rightExpression]]
            as [$functionNode, $constantNode, $functionSource]
        ) {
            if (
                $functionNode instanceof FunctionCallNode
                && \in_array($functionNode->name, ['sin', 'cos'], true)
                && \count($functionNode->arguments) === 1
                && !$this->containsVariable($constantNode, $variable)
            ) {
                $phase = $this->unwrapGrouping($functionNode->arguments[0]);
                if ($phase instanceof BinaryOperationNode) {
                    $reciprocalProductSolutions = $this->solveReciprocalSineProductLevel(
                        $functionNode,
                        $functionSource,
                        0,
                        $phase,
                        $constantNode,
                        $earlyExtractor,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        fn (float $value): ?float => $this->residualAt(
                            $left,
                            $right,
                            $rightOffset,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                        fn (float $value): ?float => $this->residualScaleAt(
                            $left,
                            $right,
                            $rightOffset,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                    );
                    if ($reciprocalProductSolutions !== null) {
                        return $reciprocalProductSolutions;
                    }
                    $unreachablePeriodicSolutions = $this->rejectUnreachableNestedPeriodicLevels(
                        $functionNode,
                        $phase,
                        $constantNode,
                        $earlyExtractor,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($unreachablePeriodicSolutions !== null) {
                        return $unreachablePeriodicSolutions;
                    }
                }
            }
        }
        if (
            (($earlyLeft instanceof FunctionCallNode && $earlyLeft->name === 'sec')
                && !$this->containsVariable($right, $variable))
            || (($earlyRight instanceof FunctionCallNode && $earlyRight->name === 'sec')
                && !$this->containsVariable($left, $variable))
        ) {
            $secantLevelSolutions = $this->solveInvertiblePolynomialLevelEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $earlyExtractor,
                fn (float $value): ?float => $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                ),
                fn (float $value): ?float => $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                ),
            );
            if ($secantLevelSolutions !== null) {
                return $secantLevelSolutions;
            }
        }
        if ($lowerBound === $upperBound) {
            if (
                !$this->containsVariable($left, $variable)
                && !$this->containsVariable($right, $variable)
                && !$this->containsImplicitVariableProduct($left, $variable, $evaluationOptions)
                && !$this->containsImplicitVariableProduct($right, $variable, $evaluationOptions)
            ) {
                throw new \InvalidArgumentException(
                    \sprintf('Equation does not contain the solved variable "%s".', $variable),
                );
            }

            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $lowerBound,
                $parameters,
                $evaluationOptions,
            );
            if ($residual === null) {
                return [];
            }
            $residualScale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $lowerBound,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residualScale === null
                || !$this->isResidualAcceptableAt(
                    $lowerBound,
                    $residual,
                    static fn (float $value): float => $residualScale,
                    $solverOptions,
                )
            ) {
                return [];
            }

            return [new EquationSolution($lowerBound, \abs($residual), 0)];
        }
        if (
            \is_finite($lowerBound)
            && \is_finite($upperBound)
            && (
                $this->containsVariable($left, $variable)
                || $this->containsVariable($right, $variable)
                || $this->containsImplicitVariableProduct($left, $variable, $evaluationOptions)
                || $this->containsImplicitVariableProduct($right, $variable, $evaluationOptions)
            )
            && (
                $this->containsEvenIntegerPower($left, $parameters, $evaluationOptions)
                || $this->containsEvenIntegerPower($right, $parameters, $evaluationOptions)
                || $this->containsSignClassifiableFunction($left, $evaluationOptions)
                || $this->containsSignClassifiableFunction($right, $evaluationOptions)
            )
        ) {
            $leftSign = $this->expressionSignOnInterval(
                $left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $rightSign = $this->expressionSignOnInterval(
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                ($leftSign['positive'] && $rightSign['nonpositive'])
                || ($leftSign['nonnegative'] && $rightSign['negative'])
                || ($leftSign['negative'] && $rightSign['nonnegative'])
                || ($leftSign['nonpositive'] && $rightSign['positive'])
            ) {
                return [];
            }
        }
        $symbolicReduction = $this->solveAfterExactSymbolicReduction(
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($symbolicReduction !== null) {
            return $symbolicReduction;
        }
        $cotangentReduction = $this->solveAdditiveCotangentEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($cotangentReduction !== null) {
            return $cotangentReduction;
        }
        $nestedInverseLevelSolutions = $this->solveNestedInverseLevelIdentity(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($nestedInverseLevelSolutions !== null) {
            return $nestedInverseLevelSolutions;
        }
        if (
            \is_finite($lowerBound)
            && \is_finite($upperBound)
            && \max(\abs($lowerBound), \abs($upperBound)) > 1.0E100
        ) {
            $wideExactPolynomial = (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $evaluationOptions,
            ))->difference($left, $right);
            if ($wideExactPolynomial !== null && \count($wideExactPolynomial) === 3) {
                $coefficients = [];
                foreach ($wideExactPolynomial as $coefficient) {
                    $value = (float) $coefficient;
                    if (!\is_finite($value) || ($coefficient !== '0' && $value === 0.0)) {
                        $coefficients = [];
                        break;
                    }
                    $coefficients[] = $value;
                }
                $coefficientScale = $coefficients === []
                    ? 0.0
                    : \max(\abs($coefficients[0]), \abs($coefficients[1]), \abs($coefficients[2]));
                if ($coefficients !== [] && $coefficientScale > 0.0 && \is_finite($coefficientScale)) {
                    foreach ($coefficients as $index => $coefficient) {
                        $coefficients[$index] = $coefficient / $coefficientScale;
                        if ($coefficient !== 0.0 && $coefficients[$index] === 0.0) {
                            $coefficients = [];
                            break;
                        }
                    }
                }
                if ($coefficients !== [] && $coefficients[2] !== 0.0) {
                    $polynomialSolver = new PolynomialSolver();
                    $polynomialResidualAt = static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($coefficients, $value);
                    $polynomialScaleAt = static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($coefficients, $value);
                    $polynomialSolutions = $polynomialSolver->solve(
                        $coefficients,
                        $lowerBound,
                        $upperBound,
                        $polynomialResidualAt,
                        $solverOptions,
                        $polynomialScaleAt,
                    );
                    if ($polynomialSolutions !== null) {
                        $verifiedSolutions = [];
                        $allSolutionsVerified = true;
                        $wideResidualAt = fn (float $candidate): ?float => $this->residualAt(
                            $left,
                            $right,
                            $rightOffset,
                            $variable,
                            $candidate,
                            $parameters,
                            $evaluationOptions,
                        );
                        foreach ($polynomialSolutions as $solution) {
                            $value = $solution->value;
                            $residual = $this->residualAt(
                                $left,
                                $right,
                                $rightOffset,
                                $variable,
                                $value,
                                $parameters,
                                $evaluationOptions,
                            );
                            $scale = $this->residualScaleAt(
                                $left,
                                $right,
                                $rightOffset,
                                $variable,
                                $value,
                                $parameters,
                                $evaluationOptions,
                            );
                            if (
                                $residual !== null
                                && ($scale === null || !$this->isResidualAcceptableAt(
                                    $value,
                                    $residual,
                                    static fn (float $_): float => $scale ?? 1.0,
                                    $solverOptions,
                                ))
                            ) {
                                $value = $this->refineVerifiedEquationCandidate(
                                    $value,
                                    $residual,
                                    $wideResidualAt,
                                    $solution->value,
                                    $lowerBound,
                                    $upperBound,
                                    $solverOptions,
                                );
                                $residual = $wideResidualAt($value);
                                $scale = $this->residualScaleAt(
                                    $left,
                                    $right,
                                    $rightOffset,
                                    $variable,
                                    $value,
                                    $parameters,
                                    $evaluationOptions,
                                );
                            }
                            if ($residual === null || $scale === null || !$this->isResidualAcceptableAt(
                                $value,
                                $residual,
                                static fn (float $_): float => $scale ?? 1.0,
                                $solverOptions,
                            )) {
                                [$value, $residual] = $this->bestRepresentableResidualCandidate(
                                    $value,
                                    $residual,
                                    $lowerBound,
                                    $upperBound,
                                    $wideResidualAt,
                                );
                                $scale = $this->residualScaleAt(
                                    $left,
                                    $right,
                                    $rightOffset,
                                    $variable,
                                    $value,
                                    $parameters,
                                    $evaluationOptions,
                                );
                            }
                            if (
                                $residual === null
                                || $scale === null
                                || !$this->isResidualAcceptableAt(
                                    $value,
                                    $residual,
                                    static fn (float $_): float => $scale,
                                    $solverOptions,
                                )
                            ) {
                                $allSolutionsVerified = false;
                                break;
                            }
                            $verifiedSolutions[] = new EquationSolution(
                                $value,
                                \abs($residual),
                                $solution->iterations,
                            );
                        }
                        if ($allSolutionsVerified) {
                            return $verifiedSolutions;
                        }
                    }
                }
            }
        }
        $selfQuotientSolutions = $this->solveSelfQuotientLevelEquation(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($selfQuotientSolutions !== null) {
            return $selfQuotientSolutions;
        }
        if ($lowerBound < $upperBound) {
            $principalInverseSolutions = $this->solveRationalPrincipalInverseCompositionEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($principalInverseSolutions !== null) {
                return $principalInverseSolutions;
            }
        }
