                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $solutions = [];
            foreach ($intervals as $interval) {
                if ($interval->lowerBound < $interval->upperBound) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                $solutions[] = new EquationSolution($interval->lowerBound, 0.0, 0);
            }

            return $solutions;
        }
        $useExactScaledPolynomial = !$hasLargeOffsetInterval
            && !$hasTranslatedPolynomialPower
            && !$hasAdditiveNonlinearPolynomialPower
            && $approximateExactCoefficients !== null
            && ($hasUnderflowedExactCoefficient || $hasExtremeExactCoefficientRange);
        $normalizedEquation = $hasUnderflowedLiteral || $useExactScaledPolynomial
            ? null
            : $this->normalizeAdditiveEquation(
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
            );
        $normalizedEquation ??= $this->normalizeReciprocalEquation(
            $leftExpression,
            $rightExpression,
            $left,
            $right,
            $rightOffset,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($normalizedEquation !== null) {
            $normalizedSolutions = $this->solve(
                $normalizedEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $solutions = [];
            foreach ($normalizedSolutions as $solution) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $solution->value,
                    $parameters,
                    $evaluationOptions,
                );
                if ($residual === null) {
                    continue;
                }
                $solutions[] = new EquationSolution(
                    $solution->value,
                    \abs($residual),
                    $solution->iterations,
                );
            }

            if (
                $solutions !== []
                || !$this->hasExactRationalRootInInterval(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $solverOptions,
                    $evaluationOptions,
                    $lowerBound,
                    $upperBound,
                )
            ) {
                return $solutions;
            }
        }

        $normalizedPowerEquations = $hasUnderflowedLiteral || $useExactScaledPolynomial
            ? null
            : $this->normalizeIntegerPowerEquation(
                $leftExpression,
                $rightExpression,
                $left,
                $right,
                $rightOffset,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
        if ($normalizedPowerEquations !== null) {
            $solutions = [];
            $zeroPowerBase = null;
            $powerExtractor = new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
            $leftPowerPolynomial = $this->extractPolynomial($powerExtractor, $left, 0);
            $rightPowerPolynomial = $this->extractPolynomial($powerExtractor, $right, $rightOffset);
            $zeroPowerSide = $rightPowerPolynomial === [0.0]
                ? $left
                : ($leftPowerPolynomial === [0.0] ? $right : null);
            if ($zeroPowerSide !== null) {
                $zeroPower = $this->extractZeroPowerFactor($zeroPowerSide, $powerExtractor);
                if ($zeroPower !== null) {
                    $zeroPowerExponent = $powerExtractor->extract($zeroPower->right);
                    if (
                        $zeroPowerExponent !== null
                        && \count($zeroPowerExponent) === 1
                        && \is_finite($zeroPowerExponent[0])
                        && $zeroPowerExponent[0] > 0.0
                        && \floor($zeroPowerExponent[0]) === $zeroPowerExponent[0]
                    ) {
                        $zeroPowerBase = $zeroPower->left;
                    }
                }
            }
            foreach ($normalizedPowerEquations as $normalizedPowerEquation) {
                foreach (
                    $this->solve(
                        $normalizedPowerEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ) as $solution
                ) {
                    $value = $zeroPowerBase === null
                        ? $solution->value
                        : $this->refineRootCandidateByFloatSearch(
                            $zeroPowerBase,
                            $solution->value,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                        );
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $value,
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($residual === null) {
                        continue;
                    }
                    $alreadyIncluded = false;
                    foreach ($solutions as $included) {
                        if ($included->value === $value) {
                            $alreadyIncluded = true;
                            break;
                        }
                    }
                    if (!$alreadyIncluded) {
                        $solutions[] = new EquationSolution(
                            $value,
                            \abs($residual),
                            $solution->iterations,
                        );
                    }
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        if (
            !$this->containsVariable($left, $variable)
            && !$this->containsVariable($right, $variable)
            && !$this->containsImplicitVariableProduct($left, $variable, $evaluationOptions)
            && !$this->containsImplicitVariableProduct($right, $variable, $evaluationOptions)
        ) {
            throw new \InvalidArgumentException(
                \sprintf('Equation does not contain the solved variable "%s".', $variable),
            );
        }

        if (
            \is_finite($lowerBound)
            && \is_finite($upperBound)
            && $this->trigonometricEquationIsOutsidePositiveExponentialRange(
                $left,
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            $endpointSolutions = [];
            foreach (\array_unique([$lowerBound, $upperBound], SORT_REGULAR) as $endpoint) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $endpoint,
                    $parameters,
                    $evaluationOptions,
                );
                $scale = $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $endpoint,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $scale !== null
                    && $this->isResidualAcceptableAt(
                        $endpoint,
                        $residual,
                        static fn (float $_): float => $scale,
                        $solverOptions,
                    )
                ) {
                    $endpointSolutions[] = new EquationSolution($endpoint, \abs($residual), 0);
                }
            }

            return $endpointSolutions;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($this->isPositiveTrigammaExponentialReciprocalSineWithoutZero(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        ) || $this->isNegativeDigammaExponentialReciprocalProductSineWithoutZero(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        )) {
            return [];
        }
        $removableGammaLogSolutions = $this->solvePeriodicLogAbsoluteGammaAtRemovableHoles(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $extractor,
        );
        if ($removableGammaLogSolutions !== null) {
            return $removableGammaLogSolutions;
        }
        if ($this->containsGammaOutsideSupportedArgumentRange(
            $left,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
        ) || $this->containsGammaOutsideSupportedArgumentRange(
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
        )) {
            return [];
        }
        $this->throwIfPeriodicRationalArgumentHasPole(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $evaluationOptions,
            $parameters,
        );

        foreach ([[$left, $right], [$right, $left]] as [$candidateFunction, $candidateTarget]) {
            $candidateFunction = $this->unwrapGrouping($candidateFunction);
            if (
                !$candidateFunction instanceof FunctionCallNode
                || !\in_array($candidateFunction->name, ['erfi', 'erfcx'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidateFunction->name)
                || \count($candidateFunction->arguments) !== 1
                || $this->containsVariable($candidateTarget, $variable)
            ) {
                continue;
            }
            if (
                $candidateTarget instanceof FunctionCallNode
                && $candidateTarget->name === $candidateFunction->name
            ) {
                continue;
            }
            $target = $extractor->extract($candidateTarget);
            $argument = $extractor->extract($candidateFunction->arguments[0]);
            if (
                $target === null
                || \count($target) !== 1
                || $argument === null
                || \count($argument) < 2
                || !\is_finite($target[0])
            ) {
                continue;
            }
            if (\count($argument) === 2 && $argument[1] === 0.0) {
                continue;
            }
            try {
                $level = match ($candidateFunction->name) {
                    'erfi' => SpecialFunctions::inverseErfi($target[0]),
                    'erfcx' => SpecialFunctions::inverseErfcx($target[0]),
                };
            } catch (\DomainException | \OverflowException) {
                continue;
            }
            $polynomialCoefficients = $argument;
            $polynomialCoefficients[0] -= $level;
            $polynomialSolver = new PolynomialSolver();
            $polynomialResidualAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($polynomialCoefficients, $value);
            $polynomialScaleAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($polynomialCoefficients, $value);
            try {
                $polynomialRoots = $polynomialSolver->solve(
                    $polynomialCoefficients,
                    $lowerBound,
                    $upperBound,
                    $polynomialResidualAt,
                    $solverOptions,
                    $polynomialScaleAt,
                );
            } catch (\DomainException) {
                continue;
            }
            if ($polynomialRoots === null) {
                continue;
            }
            $solutions = [];
            foreach ($polynomialRoots as $polynomialRoot) {
                $root = $polynomialRoot->value;
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $root,
                    $parameters,
                    $evaluationOptions,
                );
                $scale = $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $root,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual === null
                    || $scale === null
                    || !$this->isResidualAcceptableAt(
                        $root,
                        $residual,
                        static fn (float $_): float => $scale,
                        $solverOptions,
                    )
                ) {
                    $solutions = [];
                    break;
                }
                $solutions[] = new EquationSolution($root, \abs($residual), $polynomialRoot->iterations);
            }
            if ($solutions !== []) {
                return $solutions;
            }
        }

        $factorialOperand = $this->findPolynomialFactorialOperand(
            $left,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $factorialOperandSource = $leftExpression;
        if ($factorialOperand === null) {
            $factorialOperand = $this->findPolynomialFactorialOperand(
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
            $factorialOperandSource = $rightExpression;
        }
        if ($factorialOperand !== null) {
            return $this->solvePolynomialFactorialDomain(
                $left,
                $right,
                $rightOffset,
                $variable,
                $factorialOperand['node'],
                $factorialOperandSource,
                $factorialOperand['coefficients'],
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }

        $customDomainFailurePositions = [];
        $residualAt = function (float $value) use (
            $left,
            $right,
            $rightOffset,
            $variable,
            $parameters,
            $evaluationOptions,
            &$customDomainFailurePositions,
        ): ?float {
            return $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
                $customDomainFailurePositions,
            );
        };
        $isCustomDomainFailureAt = function (float $value) use (&$customDomainFailurePositions): bool {
            return isset($customDomainFailurePositions[$this->samplePositionKey($value)]);
        };
        $residualScaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $affineLogarithmicTrigSolutions = $this->solveAffineLogarithmicTrigonometricEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($affineLogarithmicTrigSolutions !== null) {
            return $affineLogarithmicTrigSolutions;
        }
        $finiteQuantizerSolutions = $this->solveFiniteQuantizerAgainstExpression(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($finiteQuantizerSolutions !== null) {
            return $finiteQuantizerSolutions;
        }
        $earlyOuter = $this->unwrapGrouping($left);
        $earlyOpposite = $this->unwrapGrouping($right);
        if (
            !$earlyOuter instanceof FunctionCallNode
            || !\in_array($earlyOuter->name, ['sin', 'cos'], true)
            || \count($earlyOuter->arguments) !== 1
            || !$this->unwrapGrouping($earlyOuter->arguments[0]) instanceof FunctionCallNode
        ) {
            $earlyOuter = $earlyOpposite;
        }
        $earlyNestedTrigonometricSolutions = $earlyOuter instanceof FunctionCallNode
            && \in_array($earlyOuter->name, ['sin', 'cos'], true)
            && \count($earlyOuter->arguments) === 1
            && $this->unwrapGrouping($earlyOuter->arguments[0]) instanceof FunctionCallNode
            ? $this->solveBoundedTrigonometricComposition(
                $equation,
                $left,
                $right,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $residualScaleAt,
            )
            : null;
        if ($earlyNestedTrigonometricSolutions !== null && $earlyNestedTrigonometricSolutions !== []) {
            return $earlyNestedTrigonometricSolutions;
        }
        $earlyAbsoluteValueSolutions = $this->solveAbsoluteValueEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            static fn (float $_): float => 1.0,
        );
        if ($earlyAbsoluteValueSolutions !== null) {
            return $earlyAbsoluteValueSolutions;
        }
        $lambertWSelfSolutions = $this->solvePrincipalLambertWSelfEquation(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($lambertWSelfSolutions !== null) {
            return $lambertWSelfSolutions;
        }
        $lambertWBranchPointSolutions = $this->solvePrincipalLambertWSumBranchPoint(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $extractor,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($lambertWBranchPointSolutions !== null) {
            return $lambertWBranchPointSolutions;
        }
        $leftSign = 1.0;
        $leftCall = $left;
        while (true) {
            $leftCall = $this->unwrapGrouping($leftCall);
            if (!$leftCall instanceof UnaryOperationNode) {
                break;
            }
            if ($leftCall->operator === UnaryOperator::Minus) {
                $leftSign *= -1.0;
            }
            $leftCall = $leftCall->operand;
        }
        $rightSign = 1.0;
        $rightCall = $right;
        while (true) {
            $rightCall = $this->unwrapGrouping($rightCall);
            if (!$rightCall instanceof UnaryOperationNode) {
                break;
            }
            if ($rightCall->operator === UnaryOperator::Minus) {
                $rightSign *= -1.0;
            }
            $rightCall = $rightCall->operand;
        }
        if (
            $leftCall instanceof FunctionCallNode
            && $rightCall instanceof FunctionCallNode
            && \in_array([$leftCall->name, $rightCall->name], [['cosh', 'sech'], ['sech', 'cosh']], true)
            && \count($leftCall->arguments) === 1
            && \count($rightCall->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('cosh')
            && $evaluationOptions->functions->isBuiltIn('sech')
        ) {
            $argumentSources = [];
            foreach (
                [[$leftCall, $leftExpression, 0], [$rightCall, $rightExpression, 0]]
                as [$call, $source, $sourceOffset]
            ) {
                $span = $call->arguments[0]->span();
                $argumentSources[] = \substr(
                    $source,
                    $span->start - $sourceOffset,
                    $span->end - $span->start,
                );
            }
            $zeroSets = [];
            foreach ($argumentSources as $argumentSource) {
                try {
                    $zeroSets[] = $this->solve(
                        '(' . $argumentSource . ')=0',
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (InfiniteSolutionSetException) {
                    $zeroSets[] = null;
                }
            }
            $finiteZeroSets = \array_values(\array_filter(
                $zeroSets,
                static fn (?array $set): bool => $set !== null,
            ));
            if ($finiteZeroSets === []) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
            $commonRoots = \array_shift($finiteZeroSets);
            foreach ($finiteZeroSets as $zeroSet) {
                $intersection = [];
                foreach ($commonRoots as $candidate) {
                    foreach ($zeroSet as $other) {
                        if (
                            \abs($candidate->value - $other->value)
                            <= $solverOptions->positionTolerance($candidate->value, $other->value)
                        ) {
                            $this->addSolution(
                                $intersection,
                                new EquationSolution(
                                    ($candidate->value + $other->value) / 2.0,
                                    \max($candidate->residual, $other->residual),
                                    \max($candidate->iterations, $other->iterations),
                                ),
                                $solverOptions,
                            );
                            break;
                        }
                    }
                }
                $commonRoots = $intersection;
            }
            $solutions = [];
            foreach ($commonRoots as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $residualScaleAt,
                        $solverOptions,
                    )
                ) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }

            return $solutions;
        }
        $leftErfcxCall = $this->unwrapGrouping($left);
        $rightErfcxCall = $this->unwrapGrouping($right);
        if (
            $leftErfcxCall instanceof FunctionCallNode
            && $rightErfcxCall instanceof FunctionCallNode
            && $leftErfcxCall->name === 'erfcx'
            && $rightErfcxCall->name === 'erfcx'
            && \count($leftErfcxCall->arguments) === 1
            && \count($rightErfcxCall->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('erfcx')
        ) {
            $sameErfcxSolutions = $this->solveSameInjectiveFunctionEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $residualScaleAt,
            );
            if ($sameErfcxSolutions !== null) {
                return $sameErfcxSolutions;
            }
        }
        $shapeSwappedBetaSolutions = $this->solveShapeSwappedBetaQuantileSumEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($shapeSwappedBetaSolutions !== null) {
            return $shapeSwappedBetaSolutions;
        }
        $reciprocalTrigBetaSolutions = $this->solveReciprocalTrigBetaZeroEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($reciprocalTrigBetaSolutions !== null) {
            return $reciprocalTrigBetaSolutions;
        }
        $samePhaseTrigBetaSolutions = $this->solveSamePhaseTrigBetaZeroEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($samePhaseTrigBetaSolutions !== null) {
            return $samePhaseTrigBetaSolutions;
        }
        $periodicBetaSolutions = $this->solveTwoHarmonicBetaZeroEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
        );
        if ($periodicBetaSolutions !== null) {
            return $periodicBetaSolutions;
        }
        $generalBetaSolutions = $this->solveGeneralBetaZeroLevelEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
        );
        if ($generalBetaSolutions !== null) {
            return $generalBetaSolutions;
        }
        $exactPolynomialCoefficients = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->difference($left, $right);
        if ($this->isSimpleLinearProductEquation($left, $right, $rightOffset, $extractor, $solverOptions)) {
            $linearProductSolutions = $this->solveZeroProductEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
            );
            if ($linearProductSolutions !== null) {
                return $linearProductSolutions;
            }
        }
        if (
            $this->containsVariableFactorial($left, $variable)
            || $this->containsVariableFactorial($right, $variable)
        ) {
            $intervals = (new EquationSetSolver())->solve(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $solutions = [];
            foreach ($intervals as $interval) {
                if ($interval->lowerBound < $interval->upperBound) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                $value = $interval->lowerBound;
                $residual = $residualAt($value);
                if ($residual !== null && $residual !== 0.0) {
                    $value = $this->refineVerifiedEquationCandidate(
                        $value,
                        $residual,
                        $residualAt,
                        $value,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    $residual = $residualAt($value);
                }
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $value,
                        $residual,
                        $residualScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $solutions[] = new EquationSolution($value, \abs($residual), 0);
            }

            return $solutions;
        }
        if (
            $exactPolynomialCoefficients !== null
            && \count($exactPolynomialCoefficients) >= 4
            && \count($exactPolynomialCoefficients) <= 13
            && \max(\abs($lowerBound), \abs($upperBound)) <= 1.0E6
        ) {
            $leftFloatPolynomial = $extractor->extract($left);
            $rightFloatPolynomial = $extractor->extract($right);
            $finiteCoefficients = $leftFloatPolynomial !== null && $rightFloatPolynomial !== null;
            $coefficientCount = \max(
                \count($leftFloatPolynomial ?? []),
                \count($rightFloatPolynomial ?? []),
            );
            $differencePolynomial = [];
            for ($degree = 0; $degree < $coefficientCount; ++$degree) {
                $differencePolynomial[] = ($leftFloatPolynomial[$degree] ?? 0.0)
                    - ($rightFloatPolynomial[$degree] ?? 0.0);
            }
            $severeCancellationAt = function (float $value) use (
                $differencePolynomial,
                $finiteCoefficients,
                $residualScaleAt,
            ): bool {
                if (!$finiteCoefficients) {
                    return false;
                }
                $expandedScale = 0.0;
                $power = 1.0;
                foreach ($differencePolynomial as $coefficient) {
                    $termMagnitude = \abs($coefficient) * $power;
                    if (!\is_finite($termMagnitude)) {
                        return false;
                    }
                    $expandedScale += $termMagnitude;
                    if (!\is_finite($expandedScale)) {
                        return false;
                    }
                    $power *= \abs($value);
                }
                $originalScale = $residualScaleAt($value);

                return $originalScale !== null
                    && $originalScale > 0.0
                    && $expandedScale / $originalScale > 1.0E12;
            };
            $midpoint = ($lowerBound / 2.0) + ($upperBound / 2.0);
            $midpointScale = $residualScaleAt($midpoint);
            $severeCancellation = $severeCancellationAt($midpoint);
            if (
                !$severeCancellation
                && $finiteCoefficients
                && $hasTranslatedPolynomialPower
                && $midpointScale !== null
                && $midpointScale > 0.0
            ) {
                $derivative = [];
                foreach ($differencePolynomial as $degree => $coefficient) {
                    if ($degree > 0) {
                        $derivative[] = $degree * $coefficient;
                    }
                }
                while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                    \array_pop($derivative);
                }
                if (\count($derivative) > 1) {
                    $polynomialSolver = new PolynomialSolver();
                    $criticalPoints = $polynomialSolver->solve(
                        $derivative,
                        $lowerBound,
                        $upperBound,
                        fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($derivative, $value),
                        $solverOptions,
                        fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                            $derivative,
                            $value,
                        ),
                    );
                    if ($criticalPoints === null) {
                        $severeCancellation = true;
                    } else {
                        foreach ($criticalPoints as $criticalPoint) {
                            if ($severeCancellationAt($criticalPoint->value)) {
                                $severeCancellation = true;
                                break;
                            }
                        }
                    }
                }
            }
            $exactIntervals = ($severeCancellation || $exactPolynomialCoefficients !== null)
                ? (new PolynomialRootCountingSolver())->isolate(
                    $equation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    256,
                    '1/1000000000000000000',
                )
                : null;
            if ($exactIntervals !== null) {
                $solutions = [];
                foreach ($exactIntervals as $interval) {
                    $low = (float) $interval->lowerNumerator / (float) $interval->lowerDenominator;
                    $high = (float) $interval->upperNumerator / (float) $interval->upperDenominator;
                    $value = $interval->isExactRoot ? $low : ($low / 2.0) + ($high / 2.0);
                    $residual = $residualAt($value);
                    if ($residual === null || !\is_finite($residual)) {
                        $solutions = [];
                        break;
                    }
                    $solutions[] = new EquationSolution($value, \abs($residual), 0);
                }
                $solutions = $this->includeClosedIntervalEndpointRoots(
                    $solutions,
                    $lowerBound,
                    $upperBound,
                    $exactPolynomialCoefficients,
                );
                if ($solutions !== []) {
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
                if ($exactIntervals === []) {
                    return [];
                }
            }
        }
        $containsBesselJ = $this->containsNamedFunction($left, 'besselj')
            || $this->containsNamedFunction($right, 'besselj');
        $containsBeta = $this->containsNamedFunction($left, 'beta')
            || $this->containsNamedFunction($right, 'beta');
        $candidateScaleAt = function (float $value) use (
            $residualScaleAt,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $containsBesselJ,
            $containsBeta,
        ): ?float {
            if ($containsBeta) {
                return $residualScaleAt($value);
            }

            $scale = $this->candidateResidualScaleAt(
                $residualScaleAt,
                $value,
                $lowerBound,
                $upperBound,
                $solverOptions->scanSteps,
            );
            if (!$containsBesselJ || $scale === null) {
                return $scale;
            }

            $probeDistance = 0.02 * \max(1.0, \abs($value));
            foreach ([-1.0, 1.0] as $direction) {
                $probe = $value + ($direction * $probeDistance);
                if ($probe <= $lowerBound || $probe >= $upperBound) {
                    continue;
                }
                $probeScale = $residualScaleAt($probe);
                if ($probeScale !== null) {
                    $scale = \max($scale, $probeScale);
                }
            }

            return $scale;
        };
        $hasVariableDenominator = $this->variableDenominators($left, $leftExpression, $variable) !== []
            || $this->variableDenominators($right, $rightExpression, $variable) !== [];
        $earlyZeroPowerSolutions = $hasVariableDenominator
            ? null
            : $this->solveZeroPowerEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
            );
        if ($earlyZeroPowerSolutions !== null) {
            return $earlyZeroPowerSolutions;
        }
        $earlyZeroProductSolutions = !$hasVariableDenominator
            ? null
            : $this->solveZeroProductEquation(
                $left,
                $right,
                $leftExpression,
                $rightExpression,
                $rightOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
            );
        if ($earlyZeroProductSolutions !== null) {
            return $this->includeClosedIntervalEndpointRoots(
                $earlyZeroProductSolutions,
                $lowerBound,
                $upperBound,
                $exactPolynomialCoefficients,
            );
        }
        $selfExponentialSolutions = $this->solveExponentialMinusAffineEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($selfExponentialSolutions !== null) {
            return $selfExponentialSolutions;
        }
        $nearUnityPowerSolutions = $this->solveUnityBasePowerEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($nearUnityPowerSolutions !== null) {
            return $nearUnityPowerSolutions;
        }
        $oddUnityBasePowerSolutions = $this->solveOddUnityBasePowerEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($oddUnityBasePowerSolutions !== null) {
            return $oddUnityBasePowerSolutions;
        }
        $leftAbsoluteCall = $this->unwrapGrouping($left);
        $rightAbsoluteCall = $this->unwrapGrouping($right);
        if (
            $leftAbsoluteCall instanceof FunctionCallNode
            && $rightAbsoluteCall instanceof FunctionCallNode
            && $leftAbsoluteCall->name === 'abs'
            && $rightAbsoluteCall->name === 'abs'
            && \count($leftAbsoluteCall->arguments) === 1
            && \count($rightAbsoluteCall->arguments) === 1
        ) {
            $leftInnerCall = $this->unwrapGrouping($leftAbsoluteCall->arguments[0]);
            $rightInnerCall = $this->unwrapGrouping($rightAbsoluteCall->arguments[0]);
            if (
                $leftInnerCall instanceof FunctionCallNode
                && $rightInnerCall instanceof FunctionCallNode
            ) {
                $oddFunctionAliases = [
                    'sinh' => 'sinh',
                    'tanh' => 'tanh',
                    'asinh' => 'asinh',
                    'arcsinh' => 'asinh',
                    'atan' => 'atan',
                    'arctan' => 'atan',
                    'asin' => 'asin',
                    'arcsin' => 'asin',
                    'atanh' => 'atanh',
                    'arctanh' => 'atanh',
                    'erfinv' => 'erfinv',
                    'erfcinv' => 'erfcinv',
                    'acot' => 'acot',
                    'acos' => 'acos',
                    'arccos' => 'acos',
                    'acosh' => 'acosh',
                    'arccosh' => 'acosh',
                    'asec' => 'asec',
                    'asech' => 'asech',
                    'sqrt' => 'sqrt',
                    'acsc' => 'acsc',
                    'erf' => 'erf',
                    'erfi' => 'erfi',
                    'cbrt' => 'cbrt',
                    'csch' => 'csch',
                    'coth' => 'coth',
                    'acsch' => 'acsch',
                    'acoth' => 'acoth',
                ];
                $leftOddFunction = $oddFunctionAliases[$leftInnerCall->name] ?? null;
                $rightOddFunction = $oddFunctionAliases[$rightInnerCall->name] ?? null;
                $oddFunctionHasRestrictedDomain = \in_array(
                    $leftOddFunction,
                    [
                        'asin', 'atanh', 'erfinv', 'erfcinv', 'acos', 'acosh', 'asec', 'asech', 'acsc',
                        'sqrt', 'csch', 'coth', 'acsch', 'acoth',
                    ],
                    true,
                );
                if (
                    $leftOddFunction !== null
                    && $leftOddFunction === $rightOddFunction
                    && \count($leftInnerCall->arguments) === 1
                    && \count($rightInnerCall->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn($leftInnerCall->name)
                    && $evaluationOptions->functions->isBuiltIn($rightInnerCall->name)
                ) {
                    $leftArgumentSpan = $leftInnerCall->arguments[0]->span();
                    $rightArgumentSpan = $rightInnerCall->arguments[0]->span();
                    $leftArgumentSource = \substr(
                        $leftExpression,
                        $leftArgumentSpan->start,
                        $leftArgumentSpan->end - $leftArgumentSpan->start,
                    );
                    $rightArgumentSource = \substr(
                        $rightExpression,
                        $rightArgumentSpan->start,
                        $rightArgumentSpan->end - $rightArgumentSpan->start,
                    );
                    $oddAbsoluteSolutions = [];
                    $oddAbsoluteBranchesHandled = true;
                    $argumentRelations = match ($leftOddFunction) {
                        'erfcinv' => ['equal', 'complement'],
                        'acot', 'acos', 'acosh', 'asec', 'asech', 'sqrt' => ['equal'],
                        default => ['equal', 'opposite'],
                    };
                    foreach ($argumentRelations as $argumentRelation) {
                        $rightArgument = match ($argumentRelation) {
                            'opposite' => '-(' . $rightArgumentSource . ')',
                            'complement' => '2-(' . $rightArgumentSource . ')',
                            default => '(' . $rightArgumentSource . ')',
                        };
                        $argumentEquation = '(' . $leftArgumentSource . ')= ' . $rightArgument;
                        if (\strlen($argumentEquation) > $evaluationOptions->limits->maxExpressionLength) {
                            $oddAbsoluteBranchesHandled = false;
                            break;
                        }
                        try {
                            $argumentSolutions = $this->solve(
                                $argumentEquation,
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $solverOptions,
                            );
                        } catch (InfiniteRootAccumulationException) {
                            $oddAbsoluteBranchesHandled = false;
                            break;
                        } catch (InfiniteSolutionSetException $exception) {
                            if ($oddFunctionHasRestrictedDomain) {
                                if ($leftArgumentSource === $rightArgumentSource) {
                                    $domainIntervals = $this->functionArgumentDomainIntervals(
                                        $leftOddFunction,
                                        $leftArgumentSource,
                                        null,
                                        $variable,
                                        $lowerBound,
                                        $upperBound,
                                        $parameters,
                                        $evaluationOptions,
                                        $solverOptions,
                                    );
                                    if ($domainIntervals !== null) {
                                        $hasDefinedIntervalPoint = false;
                                        foreach ($domainIntervals as $domainInterval) {
                                            if ($domainInterval->lowerBound < $domainInterval->upperBound) {
                                                $samples = [
                                                    $domainInterval->lowerBound,
                                                    $domainInterval->lowerBound
                                                        + (
                                                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                                                            * 0.25
                                                        ),
                                                    $domainInterval->lowerBound
                                                        + (
                                                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                                                            * 0.5
                                                        ),
                                                    $domainInterval->lowerBound
                                                        + (
                                                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                                                            * 0.75
                                                        ),
                                                    $domainInterval->upperBound,
                                                ];
                                                foreach ($samples as $sample) {
                                                    if (
                                                        $residualAt($sample) !== null
                                                        && $this->isLocallyContinuous(
                                                            $leftAbsoluteCall,
                                                            $sample,
                                                            $evaluationOptions,
                                                            $parameters,
                                                            $variable,
                                                        )
                                                    ) {
                                                        $hasDefinedIntervalPoint = true;
                                                        break 2;
                                                    }
                                                }
                                            }
                                        }
                                        if ($hasDefinedIntervalPoint) {
                                            throw $exception;
                                        }

                                        $domainSolutions = [];
                                        foreach ($domainIntervals as $domainInterval) {
                                            $point = $domainInterval->lowerBound;
                                            $residual = $residualAt($point);
                                            if (
                                                $residual === null
                                                || !$this->isResidualAcceptableAt(
                                                    $point,
                                                    $residual,
                                                    $candidateScaleAt,
                                                    $solverOptions,
                                                )
                                            ) {
                                                continue;
                                            }
                                            $this->addSolution(
                                                $domainSolutions,
                                                new EquationSolution($point, \abs($residual), 0),
                                                $solverOptions,
                                            );
                                        }

                                        if ($domainSolutions !== []) {
                                            return $domainSolutions;
                                        }
                                    }
                                }

                                $hasDefinedInteriorSample = false;
                                foreach ($this->intervalProbePositions($lowerBound, $upperBound) as $sample) {
                                    if (
                                        $sample > $lowerBound
                                        && $sample < $upperBound
                                        && $residualAt($sample) !== null
                                    ) {
                                        $hasDefinedInteriorSample = true;
                                        break;
                                    }
                                }
                                if ($hasDefinedInteriorSample) {
                                    throw $exception;
                                }
                                $oddAbsoluteBranchesHandled = false;
                                break;
                            }
                            throw $exception;
                        } catch (\DomainException) {
                            $oddAbsoluteBranchesHandled = false;
                            break;
                        }
                        foreach ($argumentSolutions as $candidate) {
                            $residual = $residualAt($candidate->value);
                            if (
                                $residual === null
                                || !$this->isResidualAcceptableAt(
                                    $candidate->value,
                                    $residual,
                                    $candidateScaleAt,
                                    $solverOptions,
                                )
                            ) {
                                continue;
                            }
                            $this->addSolution(
                                $oddAbsoluteSolutions,
                                new EquationSolution(
                                    $candidate->value,
                                    \abs($residual),
                                    $candidate->iterations,
                                ),
                                $solverOptions,
                            );
                        }
                    }
                    if ($oddAbsoluteBranchesHandled) {
                        \usort(
                            $oddAbsoluteSolutions,
                            static fn (EquationSolution $first, EquationSolution $second): int =>
                                $first->value <=> $second->value,
                        );

                        return $oddAbsoluteSolutions;
                    }
                }

                $functionPair = [$leftInnerCall->name, $rightInnerCall->name];
                $isPolygammaAliasPair = \in_array(
                    $functionPair,
                    [
                        ['polygamma', 'digamma'], ['digamma', 'polygamma'],
                        ['polygamma', 'trigamma'], ['trigamma', 'polygamma'],
                        ['polygamma', 'tetragamma'], ['tetragamma', 'polygamma'],
                    ],
                    true,
                );
                $functionPairMatches = $leftInnerCall->name === $rightInnerCall->name
                    || $isPolygammaAliasPair;
                $recognizedFunctions = ['gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma', 'polygamma'];
                $argumentRequirements = [];
                foreach ([$leftInnerCall, $rightInnerCall] as $innerCall) {
                    if (!\in_array($innerCall->name, $recognizedFunctions, true)) {
                        $argumentRequirements = [];
                        break;
                    }
                    $argumentIndex = 0;
                    $minimumArgument = 0.0;
                    $strictMinimum = false;
                    if ($innerCall->name === 'gamma' || $innerCall->name === 'digamma') {
                        $minimumArgument = 1.5;
                    } elseif ($innerCall->name === 'lgamma') {
                        $minimumArgument = 2.0;
                    } elseif ($innerCall->name === 'polygamma') {
                        if (\count($innerCall->arguments) !== 2) {
                            $argumentRequirements = [];
                            break;
                        }
                        try {
                            $order = $extractor->extract($innerCall->arguments[0]);
                        } catch (EvaluationException) {
                            $argumentRequirements = [];
                            break;
                        }
                        if (
                            $order === null
                            || \count($order) !== 1
                            || !\is_finite($order[0])
                            || \floor($order[0]) !== $order[0]
                            || $order[0] < 0.0
                            || $order[0] > SpecialFunctions::MAX_POLYGAMMA_ORDER
                        ) {
                            $argumentRequirements = [];
                            break;
                        }
                        $argumentIndex = 1;
                        if ($order[0] === 0.0) {
                            $minimumArgument = 1.5;
                        } else {
                            $strictMinimum = true;
                        }
                    } else {
                        $strictMinimum = true;
                    }
                    $argument = $innerCall->arguments[$argumentIndex] ?? null;
                    if (!$argument instanceof Node || !$evaluationOptions->functions->isBuiltIn($innerCall->name)) {
                        $argumentRequirements = [];
                        break;
                    }
                    $argumentRequirements[] = [$argument, $minimumArgument, $strictMinimum];
                }
                $argumentsAreMonotone = $functionPairMatches && \count($argumentRequirements) === 2;
                foreach ($argumentRequirements as [$argument, $minimumArgument, $strictMinimum]) {
                    $argumentRange = $this->boundedExpressionRange(
                        $argument,
                        $extractor,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    if (
                        $argumentRange === null
                        || ($strictMinimum
                            ? $argumentRange[0] <= $minimumArgument
                            : $argumentRange[0] < $minimumArgument)
                    ) {
                        $argumentsAreMonotone = false;
                        break;
                    }
                }
                if ($argumentsAreMonotone) {
                    $absoluteMonotoneSolutions = $this->solveSameInjectiveFunctionEquation(
                        $leftInnerCall,
                        $rightInnerCall,
                        $leftExpression,
                        $rightExpression,
                        $variable,
                        $extractor,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        $residualAt,
                        $candidateScaleAt,
                    );
                    if ($absoluteMonotoneSolutions !== null) {
                        return $absoluteMonotoneSolutions;
                    }
                }
            }
        }
        $nestedInverseSolutions = $this->solveNestedInverseFunctionLevelEquation(
            $left,
            $right,
            $leftExpression,
            $rightExpression,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $extractor,
            $residualAt,
            $candidateScaleAt,
        );
        if ($nestedInverseSolutions !== null) {
            if ($nestedInverseSolutions !== []) {
                return $nestedInverseSolutions;
            }
            $affinePowerArgument = null;
            if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
                $affinePowerArgument = $left->arguments[0] ?? null;
            } elseif ($right instanceof FunctionCallNode && !$this->containsVariable($left, $variable)) {
                $affinePowerArgument = $right->arguments[0] ?? null;
            }
            if (
                $affinePowerArgument === null
                || $this->solveAffinePowerLevelCandidates(
                    $affinePowerArgument,
                    0.0,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                ) === null
            ) {
                return $nestedInverseSolutions;
            }
        }
        $leftEarlyInverseLevel = $this->unwrapGrouping($left);
        $rightEarlyInverseLevel = $this->unwrapGrouping($right);
        $earlyInverseFunctions = [
            'ln', 'log10', 'log2', 'log', 'acosh', 'asech', 'asec', 'acos', 'sqrt', 'asin', 'acsc', 'acoth',
            'atanh', 'arctanh',
        ];
        $leftInverseTarget = $extractor->extract($right);
        $rightInverseTarget = $extractor->extract($left);
        $leftEarlyInverseLevelIsSupported = $leftEarlyInverseLevel instanceof FunctionCallNode
            && \in_array($leftEarlyInverseLevel->name, $earlyInverseFunctions, true)
            && $leftEarlyInverseLevel->arguments !== []
            && $extractor->extract($leftEarlyInverseLevel->arguments[0]) !== null
            && $leftInverseTarget !== null
            && \count($leftInverseTarget) === 1
            && (
                $leftInverseTarget[0] === 0.0
                || $this->isStableLogarithmicTarget(
                    $leftEarlyInverseLevel->name,
                    $leftInverseTarget[0],
                )
                && $this->hasUnitOffsetPolynomialArgument(
                    $leftEarlyInverseLevel->arguments[0],
                    $extractor,
                    $variable,
                )
                || $this->hasStableUnitBoundaryArgument(
                    $leftEarlyInverseLevel->name,
                    $leftInverseTarget[0],
                    $leftEarlyInverseLevel->arguments[0],
                    $extractor,
                    $variable,
                )
                || ($leftEarlyInverseLevel->name === 'sqrt' && $leftInverseTarget[0] === 1.0)
                || (\in_array($leftEarlyInverseLevel->name, ['atanh', 'arctanh'], true)
                    && \abs($leftInverseTarget[0]) >= 8.0
                    && \abs($leftInverseTarget[0]) <= 36.0)
                || (
                    \in_array($leftEarlyInverseLevel->name, ['asin', 'acsc'], true)
                    && $leftInverseTarget[0] === (\M_PI / 2.0)
                )
            )
            && !$this->containsVariable($right, $variable);
        $rightEarlyInverseLevelIsSupported = $rightEarlyInverseLevel instanceof FunctionCallNode
            && \in_array($rightEarlyInverseLevel->name, $earlyInverseFunctions, true)
            && $rightEarlyInverseLevel->arguments !== []
            && $extractor->extract($rightEarlyInverseLevel->arguments[0]) !== null
            && $rightInverseTarget !== null
            && \count($rightInverseTarget) === 1
            && (
                $rightInverseTarget[0] === 0.0
                || $this->isStableLogarithmicTarget(
                    $rightEarlyInverseLevel->name,
                    $rightInverseTarget[0],
                )
                && $this->hasUnitOffsetPolynomialArgument(
                    $rightEarlyInverseLevel->arguments[0],
                    $extractor,
                    $variable,
                )
                || $this->hasStableUnitBoundaryArgument(
                    $rightEarlyInverseLevel->name,
                    $rightInverseTarget[0],
                    $rightEarlyInverseLevel->arguments[0],
                    $extractor,
                    $variable,
                )
                || ($rightEarlyInverseLevel->name === 'sqrt' && $rightInverseTarget[0] === 1.0)
                || (\in_array($rightEarlyInverseLevel->name, ['atanh', 'arctanh'], true)
                    && \abs($rightInverseTarget[0]) >= 8.0
                    && \abs($rightInverseTarget[0]) <= 36.0)
                || (
                    \in_array($rightEarlyInverseLevel->name, ['asin', 'acsc'], true)
                    && $rightInverseTarget[0] === (\M_PI / 2.0)
                )
            )
            && !$this->containsVariable($left, $variable);
        if ($leftEarlyInverseLevelIsSupported || $rightEarlyInverseLevelIsSupported) {
            $earlyInverseSolutions = $this->solveInvertiblePolynomialLevelEquation(
