                $this->addDistinctRepresentableSolution(
                    $solutions,
                    new EquationSolution($solutionValue, \abs($solutionResidual), $candidate->iterations),
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function isStableLogarithmicTarget(string $function, float $target): bool
    {
        return \in_array($function, ['ln', 'log10', 'log2', 'log'], true)
            && \abs($target) < 1.0E-4;
    }

    private function compareExactRationalToPiMultiple(
        ExactRationalInterval $target,
        int $numerator,
        int $denominator,
    ): ?int {
        if ($denominator <= 0) {
            throw new \InvalidArgumentException('A pi multiple denominator must be positive.');
        }
        if (self::$inverseTrigPiEnclosure === null) {
            $five = new ExactRationalInterval(['1', '5'], ['1', '5']);
            $twoHundredThirtyNine = new ExactRationalInterval(['1', '239'], ['1', '239']);
            self::$inverseTrigPiEnclosure = $five->atan()->multiply(
                new ExactRationalInterval(['16', '1'], ['16', '1']),
            )
                ->subtract($twoHundredThirtyNine->atan()->multiply(
                    new ExactRationalInterval(['4', '1'], ['4', '1']),
                ));
        }
        $boundary = self::$inverseTrigPiEnclosure->multiply(new ExactRationalInterval(
            [(string) $numerator, (string) $denominator],
            [(string) $numerator, (string) $denominator],
        ));
        if ($target->compareLowerToRational($boundary->lower[0], $boundary->lower[1]) < 0) {
            return -1;
        }
        if ($target->compareLowerToRational($boundary->upper[0], $boundary->upper[1]) > 0) {
            return 1;
        }

        return null;
    }

    /** @return array{unit: float, subtractFromUnit: bool, offset: float}|null */
    private function stableUnitBoundaryOffset(string $function, float $target): ?array
    {
        if ($target <= 0.0 || $target >= 1.0E-4) {
            if (
                $function !== 'asin'
                && $function !== 'acsc'
                && $function !== 'acos'
                && $function !== 'asec'
                && $function !== 'acoth'
            ) {
                return null;
            }
        }

        if ($function === 'acosh' && $target < 1.0E-4) {
            return ['unit' => 1.0, 'subtractFromUnit' => false, 'offset' => 2.0 * (\sinh($target / 2.0) ** 2)];
        }
        if ($function === 'acoth' && $target > 8.0 && $target <= 36.0) {
            return [
                'unit' => 1.0,
                'subtractFromUnit' => false,
                'offset' => 2.0 / \expm1(2.0 * $target),
            ];
        }
        if ($function === 'acoth' && $target < -8.0 && $target >= -36.0) {
            return [
                'unit' => -1.0,
                'subtractFromUnit' => true,
                'offset' => 2.0 / \expm1(-2.0 * $target),
            ];
        }
        if ($function === 'asech' && $target > 0.0 && $target < 1.0E-4) {
            return [
                'unit' => 1.0,
                'subtractFromUnit' => true,
                'offset' => (2.0 * (\sinh($target / 2.0) ** 2)) / \cosh($target),
            ];
        }
        if ($function === 'asec' && $target > 0.0 && $target < 1.0E-4) {
            return [
                'unit' => 1.0,
                'subtractFromUnit' => false,
                'offset' => (2.0 * (\sin($target / 2.0) ** 2)) / \cos($target),
            ];
        }
        if ($function === 'acos' && $target > 0.0 && $target < 1.0E-4) {
            return [
                'unit' => 1.0,
                'subtractFromUnit' => true,
                'offset' => 2.0 * (\sin($target / 2.0) ** 2),
            ];
        }
        if ($function === 'asin' && $target < (\M_PI / 2.0)) {
            $complement = (\M_PI / 2.0) - $target;
            if ($complement > 0.0 && $complement < 1.0E-4) {
                return [
                    'unit' => 1.0,
                    'subtractFromUnit' => true,
                    'offset' => 2.0 * (\sin($complement / 2.0) ** 2),
                ];
            }
        }
        if ($function === 'acsc' && $target < (\M_PI / 2.0)) {
            $complement = (\M_PI / 2.0) - $target;
            if ($complement > 0.0 && $complement < 1.0E-4) {
                return [
                    'unit' => 1.0,
                    'subtractFromUnit' => false,
                    'offset' => (2.0 * (\sin($complement / 2.0) ** 2)) / \sin($target),
                ];
            }
        }
        if ($function === 'acos' && $target > (\M_PI - 1.0E-4)) {
            $complement = \M_PI - $target;
            if ($complement > 0.0 && $complement < 1.0E-4) {
                return [
                    'unit' => -1.0,
                    'subtractFromUnit' => false,
                    'offset' => 2.0 * (\sin($complement / 2.0) ** 2),
                ];
            }
        }
        if ($function === 'asin' && $target > (-\M_PI / 2.0)) {
            $complement = $target + (\M_PI / 2.0);
            if ($complement > 0.0 && $complement < 1.0E-4) {
                return [
                    'unit' => -1.0,
                    'subtractFromUnit' => false,
                    'offset' => 2.0 * (\sin($complement / 2.0) ** 2),
                ];
            }
        }
        if ($function === 'asec' && $target > (\M_PI - 1.0E-4)) {
            $complement = \M_PI - $target;
            if ($complement > 0.0) {
                return [
                    'unit' => -1.0,
                    'subtractFromUnit' => true,
                    'offset' => (2.0 * (\sin($complement / 2.0) ** 2)) / \cos($complement),
                ];
            }
        }
        if ($function === 'acsc' && $target < ((-\M_PI / 2.0) + 1.0E-4)) {
            $complement = $target + (\M_PI / 2.0);
            if ($complement > 0.0) {
                return [
                    'unit' => -1.0,
                    'subtractFromUnit' => true,
                    'offset' => (2.0 * (\sin($complement / 2.0) ** 2)) / \cos($complement),
                ];
            }
        }

        return null;
    }

    private function hasStableUnitBoundaryArgument(
        string $function,
        float $target,
        Node $argument,
        PolynomialExtractor $extractor,
        string $variable,
    ): bool {
        $boundary = $this->stableUnitBoundaryOffset($function, $target);

        return $boundary !== null
            && $this->hasUnitOffsetPolynomialArgument(
                $argument,
                $extractor,
                $variable,
                $boundary['subtractFromUnit'],
                $boundary['unit'],
            );
    }

    /** @param array{unit: float, subtractFromUnit: bool, offset: float} $boundary */
    private function stableUnitBoundaryResidualBound(string $function, array $boundary): float
    {
        if ($function === 'acoth' && $boundary['offset'] > 0.0) {
            return 2.0 * \PHP_FLOAT_EPSILON / $boundary['offset'];
        }

        return \sqrt(2.0 * \PHP_FLOAT_EPSILON);
    }

    private function hasUnitOffsetPolynomialArgument(
        Node $argument,
        PolynomialExtractor $extractor,
        string $variable,
        bool $subtractFromUnit = false,
        float $unitValue = 1.0,
    ): bool {
        $argument = $this->unwrapGrouping($argument);
        $operator = $subtractFromUnit ? BinaryOperator::Subtract : BinaryOperator::Add;
        if (!$argument instanceof BinaryOperationNode || $argument->operator !== $operator) {
            return false;
        }

        $unitOffsetTerms = $subtractFromUnit
            ? [[$argument->left, $argument->right]]
            : [[$argument->left, $argument->right], [$argument->right, $argument->left]];
        foreach ($unitOffsetTerms as [$unit, $polynomial]) {
            if (
                $this->containsVariable($unit, $variable)
                || $extractor->extract($unit) !== [$unitValue]
                || $extractor->extract($polynomial) === null
            ) {
                continue;
            }

            return true;
        }

        return false;
    }

    private function unitOffsetPolynomialSource(
        Node $argument,
        string $source,
        PolynomialExtractor $extractor,
        string $variable,
        bool $subtractFromUnit = false,
        float $unitValue = 1.0,
    ): ?string {
        $argumentNode = $this->unwrapGrouping($argument);
        $operator = $subtractFromUnit ? BinaryOperator::Subtract : BinaryOperator::Add;
        if (!$argumentNode instanceof BinaryOperationNode || $argumentNode->operator !== $operator) {
            return null;
        }

        $unitOffsetTerms = $subtractFromUnit
            ? [[$argumentNode->left, $argumentNode->right]]
            : [
                [$argumentNode->left, $argumentNode->right],
                [$argumentNode->right, $argumentNode->left],
            ];
        foreach ($unitOffsetTerms as [$unit, $polynomial]) {
            if (
                $this->containsVariable($unit, $variable)
                || $extractor->extract($unit) !== [$unitValue]
                || $extractor->extract($polynomial) === null
            ) {
                continue;
            }
            $offset = $polynomial->span()->start - $argument->span()->start;
            $length = $polynomial->span()->end - $polynomial->span()->start;
            $polynomialSource = \substr($source, $offset, $length);

            return $polynomialSource === '' ? null : $polynomialSource;
        }

        return null;
    }

    private function isInvertiblePolynomialLevelFunctionCall(FunctionCallNode $call): bool
    {
        if (
            \in_array(
                $call->name,
                [
                    'exp', 'expm1', 'ln', 'lgamma', 'log10', 'log2', 'log1p', 'sqrt', 'cbrt', 'abs',
                    'digamma', 'trigamma', 'tetragamma', 'sinh', 'cosh', 'tanh', 'asinh', 'arcsinh', 'acosh',
                    'arccosh', 'atanh', 'arctanh', 'asin', 'arcsin', 'acos', 'arccos', 'atan', 'arctan', 'sech',
                    'sec', 'csch', 'coth', 'asec', 'acsc', 'acot', 'asech', 'acsch', 'acoth',
                    'erf', 'erfc', 'erfcx', 'erfi', 'erfinv', 'erfcinv', 'dawson', 'zeta',
                ],
                true,
            )
        ) {
            return \count($call->arguments) === 1;
        }

        return match ($call->name) {
            'root', 'log' => \count($call->arguments) === 2,
            'lambertw' => \in_array(\count($call->arguments), [1, 2], true),
            'gammainc', 'gammaincc', 'gammaincinv', 'gammainccinv' => \count($call->arguments) === 2,
            'betainc', 'betaincc', 'betaincinv', 'betainccinv' => \count($call->arguments) === 3,
            'polygamma', 'besseli' => \count($call->arguments) === 2,
            default => false,
        };
    }

    private function supportsNonPolynomialInvertibleLevelArgument(string $function): bool
    {
        return \in_array(
            $function,
            [
                'exp', 'expm1', 'ln', 'lgamma', 'log', 'log10', 'log2', 'log1p', 'root', 'sqrt', 'cbrt',
                'sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth', 'asinh', 'acosh', 'atanh',
                'asin', 'acos', 'atan', 'asec', 'acsc', 'acot', 'asech', 'acsch', 'acoth',
                'besseli', 'erf', 'erfc', 'erfcx', 'erfi', 'erfinv', 'erfcinv', 'dawson', 'zeta',
                'gammainc', 'gammaincc', 'gammaincinv', 'gammainccinv',
                'betainc', 'betaincc', 'betaincinv', 'betainccinv',
                'digamma', 'trigamma', 'tetragamma', 'polygamma', 'lambertw',
            ],
            true,
        );
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveInvertiblePolynomialLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $nestedInverseSolutions = $this->solveNestedInverseFunctionLevelEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $extractor,
            $residualAt,
            $candidateScaleAt,
        );
        if ($nestedInverseSolutions !== null) {
            if ($nestedInverseSolutions !== []) {
                return $nestedInverseSolutions;
            }
            $affinePowerArgument = null;
            if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
                $affinePowerArgument = $left->arguments[0] ?? null;
            } elseif ($right instanceof FunctionCallNode && !$this->containsVariable($left, $variable)) {
                $affinePowerArgument = $right->arguments[0] ?? null;
            }
            if (
                $affinePowerArgument === null
                || $this->solveAffinePowerLevelCandidates(
                    $affinePowerArgument,
                    0.0,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                ) === null
            ) {
                return $nestedInverseSolutions;
            }
        }
        if (
            $left instanceof FunctionCallNode
            && $this->isInvertiblePolynomialLevelFunctionCall($left)
            && !$this->containsVariable($right, $variable)
        ) {
            $functionCall = $left;
            $constant = $right;
            $source = $leftSource;
            $sourceOffset = 0;
        } elseif (
            $right instanceof FunctionCallNode
            && $this->isInvertiblePolynomialLevelFunctionCall($right)
            && !$this->containsVariable($left, $variable)
        ) {
            $functionCall = $right;
            $constant = $left;
            $source = $rightSource;
            $sourceOffset = 0;
        } else {
            return null;
        }
        $function = match ($functionCall->name) {
            'arcsin' => 'asin',
            'arccos' => 'acos',
            'arctan' => 'atan',
            'arcsinh' => 'asinh',
            'arccosh' => 'acosh',
            'arctanh' => 'atanh',
            default => $functionCall->name,
        };
        if (!$evaluationOptions->functions->isBuiltIn($function)) {
            return null;
        }

        $constantCoefficients = $extractor->extract($constant);
        if ($constantCoefficients === null || \count($constantCoefficients) !== 1) {
            return null;
        }
        $target = $constantCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }
        $rootDegree = null;
        $logBase = null;
        $lambertWBranch = 0.0;
        if ($function === 'root') {
            $degreeCoefficients = $extractor->extract($functionCall->arguments[1]);
            if ($degreeCoefficients === null || \count($degreeCoefficients) !== 1) {
                return null;
            }
            $normalizedDegree = $this->normalizedIntegerRootDegree($degreeCoefficients[0]);
            if ($normalizedDegree === null) {
                return [];
            }
            $rootDegree = (float) $normalizedDegree;
        } elseif ($function === 'log') {
            if ($this->containsVariable($functionCall->arguments[1], $variable)) {
                return null;
            }
            $baseCoefficients = $extractor->extract($functionCall->arguments[1]);
            if ($baseCoefficients === null || \count($baseCoefficients) !== 1) {
                return null;
            }
            $logBase = $baseCoefficients[0];
            if (!\is_finite($logBase) || $logBase <= 0.0 || $logBase === 1.0) {
                return [];
            }
        } elseif ($function === 'lambertw' && \count($functionCall->arguments) === 2) {
            $branchCoefficients = $extractor->extract($functionCall->arguments[1]);
            if ($branchCoefficients === null || \count($branchCoefficients) !== 1) {
                return null;
            }
            $lambertWBranch = $branchCoefficients[0];
            if ($lambertWBranch !== 0.0 && $lambertWBranch !== -1.0) {
                return [];
            }
        }
        if (
            ($function === 'exp' && $target <= 0.0)
            || ($function === 'expm1' && $target <= -1.0)
            || ($function === 'sqrt' && $target < 0.0)
            || ($function === 'abs' && $target < 0.0)
            || ($function === 'sec' && \abs($target) < 1.0)
            || ($function === 'cosh' && $target < 1.0)
            || ($function === 'tanh' && \abs($target) >= 1.0)
            || ($function === 'sech' && ($target <= 0.0 || $target > 1.0))
            || ($function === 'csch' && $target === 0.0)
            || ($function === 'coth' && \abs($target) <= 1.0)
            || ($function === 'asech' && $target < 0.0)
            || ($function === 'acsch' && $target === 0.0)
            || ($function === 'acoth' && $target === 0.0)
            || ($function === 'erf' && \abs($target) >= 1.0)
            || ($function === 'erfc' && ($target <= 0.0 || $target >= 2.0))
            || ($function === 'erfcx' && $target <= 0.0)
            || ($function === 'asin' && \abs($target) > (\M_PI / 2.0))
            || ($function === 'acos' && ($target < 0.0 || $target > \M_PI))
            || ($function === 'atan' && \abs($target) >= (\M_PI / 2.0))
            || ($function === 'asec' && ($target < 0.0 || $target > \M_PI || $target === (\M_PI / 2.0)))
            || ($function === 'acsc' && (\abs($target) > (\M_PI / 2.0) || $target === 0.0))
            || ($function === 'acot' && ($target <= 0.0 || $target >= \M_PI))
            || ($function === 'acosh' && $target < 0.0)
            || ($function === 'lambertw' && $lambertWBranch === 0.0 && $target < -1.0)
            || ($function === 'lambertw' && $lambertWBranch === -1.0 && $target > -1.0)
            || ($function === 'root' && \fmod(\abs($rootDegree ?? 1.0), 2.0) === 0.0 && $target < 0.0)
            || ($function === 'root' && ($rootDegree ?? 1.0) < 0.0 && $target == 0.0)
        ) {
            return [];
        }

        $argumentIndex = match ($function) {
            'polygamma', 'besseli' => 1,
            'gammainc', 'gammaincc', 'gammaincinv', 'gammainccinv' => 1,
            'betainc', 'betaincc', 'betaincinv', 'betainccinv' => 2,
            default => 0,
        };
        $specialFunctionShapes = [];
        for ($shapeIndex = 0; $shapeIndex < $argumentIndex; ++$shapeIndex) {
            if ($this->containsVariable($functionCall->arguments[$shapeIndex], $variable)) {
                return null;
            }
            $shapeCoefficients = $extractor->extract($functionCall->arguments[$shapeIndex]);
            if (
                $shapeCoefficients === null
                || \count($shapeCoefficients) !== 1
                || !\is_finite($shapeCoefficients[0])
                || ($function === 'polygamma' && $shapeCoefficients[0] < 0.0)
                || (
                    !\in_array($function, ['polygamma', 'besseli'], true)
                    && $shapeCoefficients[0] <= 0.0
                )
            ) {
                return null;
            }
            $specialFunctionShapes[] = $shapeCoefficients[0];
        }
        if (
            $function === 'polygamma'
            && (
                \floor($specialFunctionShapes[0]) !== $specialFunctionShapes[0]
                || $specialFunctionShapes[0] < 0.0
                || $specialFunctionShapes[0] > SpecialFunctions::MAX_POLYGAMMA_ORDER
            )
        ) {
            return [];
        }
        if (
            $function === 'besseli'
            && (
                \floor($specialFunctionShapes[0]) !== $specialFunctionShapes[0]
                || \abs($specialFunctionShapes[0]) > SpecialFunctions::MAX_BESSEL_ORDER
            )
        ) {
            return [];
        }
        $argument = $functionCall->arguments[$argumentIndex];
        $argumentCoefficients = $extractor->extract($argument);
        if (
            (!$this->supportsNonPolynomialInvertibleLevelArgument($function)
                && $argumentCoefficients === null)
            || ($argumentCoefficients !== null && \count($argumentCoefficients) < 2)
        ) {
            return null;
        }
        $levelArgument = $this->unwrapGrouping($argument);
        $levelSource = \substr(
            $source,
            $argument->span()->start - $sourceOffset,
            $argument->span()->end - $argument->span()->start,
        );
        if ($function === 'sec') {
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                return null;
            }
            $argumentRange = $this->polynomialRange(
                $argumentCoefficients ?? [],
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($argumentRange === null) {
                return null;
            }
            $principal = \acos(1.0 / $target);
            $period = 2.0 * \M_PI;
            $levels = [];
            foreach ([$principal, -$principal] as $base) {
                $firstPeriod = (int) \ceil(($argumentRange[0] - $base) / $period);
                $lastPeriod = (int) \floor(($argumentRange[1] - $base) / $period);
                if ($lastPeriod - $firstPeriod + 1 > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                    $levels[] = $base + ($periodIndex * $period);
                }
            }
            $levels = \array_values(\array_unique($levels, SORT_REGULAR));
        } elseif (\in_array($function, ['gammaincinv', 'gammainccinv'], true)) {
            if ($target < 0.0) {
                return [];
            }
            $level = $function === 'gammaincinv'
                ? SpecialFunctions::regularizedGammaP($specialFunctionShapes[0], $target)
                : SpecialFunctions::regularizedGammaQ($specialFunctionShapes[0], $target);
            $levels = [$level];
        } elseif (\in_array($function, ['betaincinv', 'betainccinv'], true)) {
            if ($target < 0.0 || $target > 1.0) {
                return [];
            }
            $level = $function === 'betaincinv'
                ? SpecialFunctions::regularizedBeta(
                    $specialFunctionShapes[0],
                    $specialFunctionShapes[1],
                    $target,
                )
                : SpecialFunctions::regularizedBetaComplement(
                    $specialFunctionShapes[0],
                    $specialFunctionShapes[1],
                    $target,
                );
            $levels = [$level];
        } elseif (\in_array($function, ['gammainc', 'gammaincc', 'betainc', 'betaincc'], true)) {
            if ($target < 0.0 || $target > 1.0) {
                return [];
            }
            if ($function === 'gammainc' && $target === 1.0) {
                return [];
            }
            if ($function === 'gammaincc' && $target === 0.0) {
                return [];
            }
            if ($target === 0.0 || $target === 1.0) {
                $endpoint = match ($function) {
                    'gammainc', 'betainc' => $target === 0.0 ? 0.0 : 1.0,
                    'gammaincc', 'betaincc' => $target === 1.0 ? 0.0 : 1.0,
                };
                $levels = [$endpoint];
            } else {
                try {
                    $inverseLevel = match ($function) {
                        'gammainc' => SpecialFunctions::inverseRegularizedGammaP(
                            $specialFunctionShapes[0],
                            $target,
                        ),
                        'gammaincc' => SpecialFunctions::inverseRegularizedGammaQ(
                            $specialFunctionShapes[0],
                            $target,
                        ),
                        'betainc' => SpecialFunctions::inverseRegularizedBeta(
                            $specialFunctionShapes[0],
                            $specialFunctionShapes[1],
                            $target,
                        ),
                        'betaincc' => SpecialFunctions::inverseRegularizedBetaComplement(
                            $specialFunctionShapes[0],
                            $specialFunctionShapes[1],
                            $target,
                        ),
                    };
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
                if (!\is_finite($inverseLevel)) {
                    return null;
                }
                $levels = [$inverseLevel];
            }
        } elseif ($function === 'zeta') {
            $argumentRange = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($argumentRange === null) {
                return null;
            }
            if (
                $argumentRange[0] < -64.0
                || $argumentRange[1] > 64.0
                || ($argumentRange[0] <= 1.0 && $argumentRange[1] >= 1.0)
            ) {
                return null;
            }
            $zetaDefinition = $evaluationOptions->functions->find('zeta');
            if ($zetaDefinition === null) {
                return null;
            }
            $zetaAt = static fn (float $value): float =>
                (float) $zetaDefinition->invoke([$value]);
            $levels = $this->invertZetaFunctionLevels(
                $target,
                $argumentRange[0],
                $argumentRange[1],
                $zetaAt,
                $solverOptions,
            );
            if ($levels === null) {
                return null;
            }
        } elseif ($function === 'lgamma') {
            $argumentRange = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $argumentRange === null
                || $argumentRange[0] < -171.0
            ) {
                return null;
            }
            $lgammaDefinition = $evaluationOptions->functions->find('lgamma');
            if ($lgammaDefinition === null) {
                return null;
            }
            $lgammaAt = static fn (float $value): float =>
                (float) $lgammaDefinition->invoke([$value]);
            $levels = $this->invertLogGammaFunctionLevels(
                $target,
                $argumentRange[0],
                $argumentRange[1],
                $lgammaAt,
                $solverOptions,
            );
            if ($levels === null) {
                return null;
            }
        } elseif (\in_array($function, ['digamma', 'trigamma', 'tetragamma', 'polygamma'], true)) {
            $argumentRange = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($argumentRange === null) {
                return null;
            }
            $polygammaOrder = match ($function) {
                'digamma' => 0,
                'trigamma' => 1,
                'tetragamma' => 2,
                default => (int) $specialFunctionShapes[0],
            };
            if ($argumentRange[0] < 0.0) {
                $levels = $this->invertNegativePolygammaFunctionLevels(
                    $target,
                    $argumentRange[0],
                    $argumentRange[1],
                    $polygammaOrder,
                    $solverOptions,
                );
                if ($levels === null) {
                    return null;
                }
            } else {
                $rangeScale = \max(1.0, \abs($argumentRange[0]), \abs($argumentRange[1]));
                if ($argumentRange[0] <= 64.0 * \PHP_FLOAT_EPSILON * $rangeScale) {
                    return null;
                }
                $inverseLevel = $this->invertMonotoneFunctionLevel(
                    $target,
                    $argumentRange[0],
                    $argumentRange[1],
                    static fn (float $value): float => SpecialFunctions::polygamma($polygammaOrder, $value),
                    ($polygammaOrder & 1) === 0,
                    $solverOptions->maxIterations,
                );
                if ($inverseLevel === null) {
                    return null;
                }
                $levels = [$inverseLevel];
            }
        } elseif ($function === 'besseli') {
            $order = (int) $specialFunctionShapes[0];
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                try {
                    $levels = SpecialFunctions::inverseBesselI($order, $target);
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
            } elseif (($order === 0 && $target === 1.0) || ($order !== 0 && $target === 0.0)) {
                $levels = [0.0];
            } else {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if (
                    $argumentRange === null
                    || !\is_finite($argumentRange[0])
                    || !\is_finite($argumentRange[1])
                    || $argumentRange[0] < -SpecialFunctions::MAX_BESSEL_I_ARGUMENT
                    || $argumentRange[1] > SpecialFunctions::MAX_BESSEL_I_ARGUMENT
                ) {
                    return null;
                }
                $besselIAt = static fn (float $value): float => SpecialFunctions::besselI($order, $value);
                if (($order & 1) === 1) {
                    $inverseLevel = $this->invertMonotoneFunctionLevel(
                        $target,
                        $argumentRange[0],
                        $argumentRange[1],
                        $besselIAt,
                        true,
                        $solverOptions->maxIterations,
                    );
                    if ($inverseLevel === null) {
                        return null;
                    }
                    $levels = [$inverseLevel];
                } else {
                    $levels = [];
                    $branches = [];
                    if ($argumentRange[0] < 0.0) {
                        $branches[] = [$argumentRange[0], \min(0.0, $argumentRange[1]), false];
                    }
                    if ($argumentRange[1] > 0.0) {
                        $branches[] = [\max(0.0, $argumentRange[0]), $argumentRange[1], true];
                    }
                    foreach ($branches as [$branchLower, $branchUpper, $increasing]) {
                        $lowerValue = $besselIAt($branchLower);
                        $upperValue = $besselIAt($branchUpper);
                        $branchMinimum = \min($lowerValue, $upperValue);
                        $branchMaximum = \max($lowerValue, $upperValue);
                        if ($target < $branchMinimum || $target > $branchMaximum) {
                            continue;
                        }
                        $inverseLevel = $this->invertMonotoneFunctionLevel(
                            $target,
                            $branchLower,
                            $branchUpper,
                            $besselIAt,
                            $increasing,
                            $solverOptions->maxIterations,
                        );
                        if ($inverseLevel === null) {
                            return null;
                        }
                        $levels[] = $inverseLevel;
                    }
                }
            }
        } elseif ($function === 'erfcx') {
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                if ($target <= 0.0) {
                    return [];
                }
                try {
                    $levels = [SpecialFunctions::inverseErfcx($target)];
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
            } else {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                try {
                    $lowerValue = SpecialFunctions::erfcx($argumentRange[0]);
                    $upperValue = SpecialFunctions::erfcx($argumentRange[1]);
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
                if ($target > $lowerValue || $target < $upperValue) {
                    return [];
                }
                $inverseLevel = $this->invertMonotoneFunctionLevel(
                    $target,
                    $argumentRange[0],
                    $argumentRange[1],
                    SpecialFunctions::erfcx(...),
                    false,
                    $solverOptions->maxIterations,
                );
                if ($inverseLevel === null) {
                    return null;
                }
                $levels = [$inverseLevel];
            }
        } elseif ($function === 'erfi') {
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                try {
                    $levels = [SpecialFunctions::inverseErfi($target)];
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
            } else {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                try {
                    $lowerValue = SpecialFunctions::erfi($argumentRange[0]);
                    $upperValue = SpecialFunctions::erfi($argumentRange[1]);
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
                if ($target < $lowerValue || $target > $upperValue) {
                    return [];
                }
                $inverseLevel = $this->invertMonotoneFunctionLevel(
                    $target,
                    $argumentRange[0],
                    $argumentRange[1],
                    SpecialFunctions::erfi(...),
                    true,
                    $solverOptions->maxIterations,
                );
                if ($inverseLevel === null) {
                    return null;
                }
                $levels = [$inverseLevel];
            }
        } elseif ($function === 'dawson') {
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                try {
                    $levels = SpecialFunctions::inverseDawson($target);
                } catch (\DomainException | \OverflowException) {
                    return null;
                }
            } else {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $maximumArgument = $this->dawsonMaximumArgument();
                $dawsonAt = SpecialFunctions::dawson(...);
                $branches = [];
                $negativeDecreasingUpper = \min($argumentRange[1], -$maximumArgument);
                if ($argumentRange[0] <= $negativeDecreasingUpper) {
                    $branches[] = [$argumentRange[0], $negativeDecreasingUpper, false];
                }
                $increasingLower = \max($argumentRange[0], -$maximumArgument);
                $increasingUpper = \min($argumentRange[1], $maximumArgument);
                if ($increasingLower <= $increasingUpper) {
                    $branches[] = [$increasingLower, $increasingUpper, true];
                }
                $positiveDecreasingLower = \max($argumentRange[0], $maximumArgument);
                if ($positiveDecreasingLower <= $argumentRange[1]) {
                    $branches[] = [$positiveDecreasingLower, $argumentRange[1], false];
                }
                $levels = [];
                foreach ($branches as [$branchLower, $branchUpper, $increasing]) {
                    $lowerValue = $dawsonAt($branchLower);
                    $upperValue = $dawsonAt($branchUpper);
                    $branchMinimum = \min($lowerValue, $upperValue);
                    $branchMaximum = \max($lowerValue, $upperValue);
                    if ($target < $branchMinimum || $target > $branchMaximum) {
                        continue;
                    }
                    $inverseLevel = $this->invertMonotoneFunctionLevel(
                        $target,
                        $branchLower,
                        $branchUpper,
                        $dawsonAt,
                        $increasing,
                        $solverOptions->maxIterations,
                    );
                    if ($inverseLevel === null) {
                        return null;
                    }
                    $levels[] = $inverseLevel;
                }
            }
        } elseif ($function === 'erfi') {
            try {
                $levels = [SpecialFunctions::inverseErfi($target)];
            } catch (\DomainException | \OverflowException) {
                return [];
            }
        } elseif (\in_array($function, ['erf', 'erfc', 'erfinv', 'erfcinv'], true)) {
            $inverse = match ($function) {
                'erf' => $this->inverseErrorFunctionLevel($target),
                'erfc' => $this->inverseComplementaryErrorFunctionLevel($target),
                'erfinv' => SpecialFunctions::erf($target),
                'erfcinv' => SpecialFunctions::erfc($target),
            };
            if ($inverse === null) {
                return [];
            }
            $levels = [$inverse];
        } else {
            $levels = match ($function) {
                'exp' => [\log($target)],
                'expm1' => [\log1p($target)],
                'ln' => [\exp($target)],
                'log' => [\pow($logBase ?? 10.0, $target)],
                'lambertw' => [$target * \exp($target)],
                'log10' => [10.0 ** $target],
                'log2' => [2.0 ** $target],
                'log1p' => [\expm1($target)],
                'sqrt' => [$target * $target],
                'cbrt' => [$target * $target * $target],
                'root' => [\pow($target, $rootDegree ?? 1.0)],
                'abs' => $target === 0.0 ? [0.0] : [$target, -$target],
                'sinh' => [\asinh($target)],
                'cosh' => $target === 1.0 ? [0.0] : [\acosh($target), -\acosh($target)],
                'tanh' => [\atanh($target)],
                'sech' => $target === 1.0
                ? [0.0]
                : [$this->inverseSechLevel($target), -$this->inverseSechLevel($target)],
                'csch' => [$this->inverseCschLevel($target)],
                'coth' => [\atanh(1.0 / $target)],
                'asech' => [$this->hyperbolicSecantLevel($target)],
                'acsch' => [$this->hyperbolicCosecantLevel($target)],
                'acoth' => [$this->hyperbolicCotangentLevel($target)],
                'asinh' => [\sinh($target)],
                'acosh' => [\cosh($target)],
                'atanh' => [\tanh($target)],
                'asin' => [\sin($target)],
                'acos' => [$target === (\M_PI / 2.0) ? 0.0 : \cos($target)],
                'atan' => [\tan($target)],
                'asec' => [$this->inverseSecantLevel($target)],
                'acsc' => [$this->inverseCosecantLevel($target)],
                'acot' => [$this->inverseCotangentLevel($target)],
                default => throw new \LogicException('Unsupported inverse function.'),
            };
        }
        if (\count(\array_filter($levels, static fn (float $level): bool => !\is_finite($level))) > 0) {
            return [];
        }

        $levelSign = 1.0;
        if (
            $function === 'exp'
            && $levelArgument instanceof UnaryOperationNode
            && $levelArgument->operator === UnaryOperator::Minus
        ) {
            $levelArgument = $this->unwrapGrouping($levelArgument->operand);
            $operand = $levelArgument;
            $operandSourceSpan = $operand->span();
            $levelSource = \substr(
                $source,
                $operandSourceSpan->start - $sourceOffset,
                $operandSourceSpan->end - $operandSourceSpan->start,
            );
            $levelSign = -1.0;
        }
        $levelCoefficients = $extractor->extract($levelArgument);
        if (
            (!$this->supportsNonPolynomialInvertibleLevelArgument($function)
                && $levelCoefficients === null)
            || ($levelCoefficients !== null && \count($levelCoefficients) < 2)
        ) {
            return null;
        }

        $solutions = [];
        foreach ($levels as $level) {
            if (\in_array($function, ['log10', 'log2', 'log'], true) && $level === 0.0) {
                continue;
            }
            $levelEquation = $levelSource . '=' . \sprintf('%.17g', $level * $levelSign);
            if ($this->isStableLogarithmicTarget($function, $target)) {
                $logarithmScale = match ($function) {
                    'ln' => 1.0,
                    'log10' => \log(10.0),
                    'log2' => \log(2.0),
                    'log' => \log($logBase ?? 10.0),
                    default => throw new \LogicException('Unexpected stable logarithm.'),
                };
                $levelOffset = \expm1($target * $logarithmScale);
                if (!\is_finite($levelOffset)) {
                    return [];
                }
                $unitOffsetSource = $this->unitOffsetPolynomialSource(
                    $argument,
                    $levelSource,
                    $extractor,
                    $variable,
                );
                if ($unitOffsetSource !== null) {
                    $levelEquation = $unitOffsetSource . '='
                        . \json_encode(
                            $levelOffset,
                            \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR,
                        );
                }
            } elseif (($stableBoundary = $this->stableUnitBoundaryOffset($function, $target)) !== null) {
                $unitOffsetSource = $this->unitOffsetPolynomialSource(
                    $argument,
                    $levelSource,
                    $extractor,
                    $variable,
                    $stableBoundary['subtractFromUnit'],
                    $stableBoundary['unit'],
                );
                if ($unitOffsetSource === null) {
                    return null;
                }
                if (!\is_finite($stableBoundary['offset'])) {
                    return [];
                }
                $levelEquation = $unitOffsetSource . '='
                    . \json_encode(
                        $stableBoundary['offset'],
                        \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR,
                    );
            }
            $candidates = null;
            $affinePowerCandidates = $this->solveAffinePowerLevelCandidates(
                $levelArgument,
                $level * $levelSign,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $extractor,
                $lowerBound,
                $upperBound,
            );
            if ($affinePowerCandidates !== null) {
                $candidates = $affinePowerCandidates;
            }
            if ($function === 'erfi' && $levelCoefficients !== null) {
                $polynomialCoefficients = $levelCoefficients;
                $polynomialCoefficients[0] -= $level;
                $polynomialSolver = new PolynomialSolver();
                $polynomialResidualAt = static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomialCoefficients, $value);
                $polynomialScaleAt = static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($polynomialCoefficients, $value);
                $candidates = $polynomialSolver->solve(
                    $polynomialCoefficients,
                    $lowerBound,
                    $upperBound,
                    $polynomialResidualAt,
                    $solverOptions,
                    $polynomialScaleAt,
                );
            }
            if ($candidates === null) {
                $candidates = $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }
            foreach ($candidates as $candidate) {
                $solutionValue = $candidate->value;
                if (
                    \in_array($function, ['atanh', 'acoth'], true)
                    && $levelCoefficients !== null
                    && \count($levelCoefficients) === 2
                    && $levelCoefficients[1] !== 0.0
                ) {
                    $boundary = 1.0;
                    $argumentValue = $this->polynomialValue($levelCoefficients, $solutionValue);
                    if ($argumentValue !== null && \abs($argumentValue) === $boundary) {
                        $argumentDirection = ($argumentValue > 0.0 ? 1 : -1)
                            * ($levelCoefficients[1] > 0.0 ? 1 : -1);
                        $variableDirection = $function === 'atanh'
                            ? -$argumentDirection
                            : $argumentDirection;
                        for ($step = 0; $step < 2; ++$step) {
                            $neighbor = $this->adjacentFloat($solutionValue, $variableDirection);
                            if (
                                $neighbor === null
                                || $neighbor < $lowerBound
                                || $neighbor > $upperBound
                            ) {
                                break;
                            }
                            $neighborArgument = $this->polynomialValue($levelCoefficients, $neighbor);
                            if (
                                $neighborArgument === null
                                || ($function === 'atanh' && \abs($neighborArgument) >= 1.0)
                                || ($function === 'acoth' && \abs($neighborArgument) <= 1.0)
                            ) {
                                break;
                            }
                            $solutionValue = $neighbor;
                        }
                    }
                }
                $residual = $residualAt($solutionValue);
                if ($residual === null) {
                    continue;
                }
                $solutionResidual = $residual;
                $stableBoundary = $this->stableUnitBoundaryOffset($function, $target);
                $residualAccepted = $this->isResidualAcceptableAt(
                    $solutionValue,
                    $solutionResidual,
                    $candidateScaleAt,
                    $solverOptions,
                ) || (
                    $stableBoundary !== null
                    && $this->hasUnitOffsetPolynomialArgument(
                        $argument,
                        $extractor,
                        $variable,
                        $stableBoundary['subtractFromUnit'],
                        $stableBoundary['unit'],
                    )
                    && \abs($solutionResidual)
                        <= $this->stableUnitBoundaryResidualBound($function, $stableBoundary)
                );
                if (
                    !$residualAccepted
                    && \in_array($function, ['atanh', 'acoth'], true)
                    && $argument instanceof VariableNode
                    && $argument->name === $variable
                    && $candidate->value === ($level * $levelSign)
                ) {
                    $bestRepresentableCandidate = $this->bestRepresentableInverseCandidate(
                        $function,
                        $candidate->value,
                        $target,
                        $solutionResidual,
                        $lowerBound,
                        $upperBound,
                        $residualAt,
                    );
                    if ($bestRepresentableCandidate !== null) {
                        [$solutionValue, $solutionResidual] = $bestRepresentableCandidate;
                        $residualAccepted = true;
                    }
                }
                if (!$residualAccepted) {
                    foreach ([-1, 1] as $direction) {
                        $position = $candidate->value;
                        for ($step = 0; $step < 16; ++$step) {
                            $neighbor = $this->adjacentFloat($position, $direction);
                            if (
                                $neighbor === null
                                || $neighbor < $lowerBound
                                || $neighbor > $upperBound
                            ) {
                                break;
                            }
                            $neighborResidual = $residualAt($neighbor);
                            if (
                                $neighborResidual === null
                                || \abs($neighborResidual) >= \abs($solutionResidual)
                            ) {
                                break;
                            }
                            $solutionValue = $neighbor;
                            $solutionResidual = $neighborResidual;
                            $position = $neighbor;
                        }
                    }
                    $residualAccepted = $this->isCandidateAtFloatingPointRootResolution(
                        $solutionValue,
                        $solutionResidual,
                        $residualAt,
                    );
                }
                if (!$residualAccepted) {
                    continue;
                }
                $this->addDistinctRepresentableSolution(
                    $solutions,
                    new EquationSolution($solutionValue, \abs($solutionResidual), $candidate->iterations),
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve an integer power of an affine expression without expanding its center.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveAffinePowerLevelCandidates(
        Node $expression,
        float $level,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
    ): ?array {
        $expression = $this->unwrapGrouping($expression);
        $power = 1.0;
        $baseNode = $expression;
        if ($expression instanceof BinaryOperationNode && $expression->operator === BinaryOperator::Power) {
            $power = $this->constantNodeValue($expression->right, $parameters, $evaluationOptions) ?? \NAN;
            $baseNode = $expression->left;
        }
        if (
            !\is_finite($power)
            || $power < 1.0
            || $power > $solverOptions->maxPolynomialDegree
            || \floor($power) !== $power
        ) {
            return null;
        }
        $base = $extractor->extract($baseNode);
        if ($base === null) {
            return null;
        }
        while (\count($base) > 1 && $base[\array_key_last($base)] === 0.0) {
            \array_pop($base);
        }
        if (\count($base) !== 2 || !\is_finite($base[0]) || !\is_finite($base[1]) || $base[1] === 0.0) {
            return null;
        }
        $evenPower = \fmod($power, 2.0) === 0.0;
        if ($evenPower && $level < 0.0) {
            return [];
        }

        $baseLevel = $evenPower
            ? \sqrt($level)
            : ($level < 0.0 ? -(\abs($level) ** (1.0 / $power)) : ($level ** (1.0 / $power)));
        if (!\is_finite($baseLevel)) {
            return null;
        }
        $center = -($base[0] / $base[1]);
        if (!\is_finite($center)) {
            return null;
        }

        $baseLevels = $evenPower && $level !== 0.0
            ? [$baseLevel, -$baseLevel]
            : [$baseLevel];
        $candidates = [];
        foreach ($baseLevels as $signedBaseLevel) {
            $root = $center + ($signedBaseLevel / $base[1]);
            if (!\is_finite($root) || $root < $lowerBound || $root > $upperBound) {
                continue;
            }
            $candidates[] = new EquationSolution($root == 0.0 ? 0.0 : $root, 0.0, 0);
        }

        return $candidates;
    }

    /** @return list<float>|null */
    private function invertNegativePolygammaFunctionLevels(
        float $target,
        float $lowerBound,
        float $upperBound,
        int $order,
        SolverOptions $options,
    ): ?array {
        if ($order < 0 || $order > SpecialFunctions::MAX_POLYGAMMA_ORDER || $lowerBound < -171.0) {
            return null;
        }
        $function = static fn (float $value): float => SpecialFunctions::polygamma($order, $value);
        $levels = [];
        $addMonotoneInterval = function (
            float $lower,
            float $upper,
            bool $increasing,
        ) use (
            $target,
            $function,
            $options,
            &$levels,
        ): bool {
            if ($lower > $upper) {
                return true;
            }
            $finiteInterval = $this->finiteFunctionInterval($lower, $upper, $function);
            if ($finiteInterval === null) {
                return false;
            }
            [$lower, $lowerValue, $upper, $upperValue] = $finiteInterval;
            if (
                $target < \min($lowerValue, $upperValue)
                || $target > \max($lowerValue, $upperValue)
            ) {
                return true;
            }
            $level = $this->invertMonotoneFunctionLevel(
                $target,
                $lower,
                $upper,
                $function,
                $increasing,
                $options->maxIterations,
            );
            if ($level === null) {
                return false;
            }
            if (!\in_array($level, $levels, true)) {
                $levels[] = $level;
            }

            return true;
        };

        if ($lowerBound < 0.0) {
            $negativeUpper = \min($upperBound, 0.0);
            $firstStrip = (int) \floor($lowerBound);
            $lastStrip = (int) \ceil($negativeUpper) - 1;
            for ($integer = $firstStrip; $integer <= $lastStrip; ++$integer) {
                if ($integer >= 0) {
                    continue;
                }
                $pole = (float) $integer;
                $nextPole = (float) ($integer + 1);
                $stripLower = \max(
                    $lowerBound,
                    $this->adjacentFloat($pole, 1) ?? $lowerBound,
                );
                $insideUpper = $nextPole === 0.0
                    ? ($order === 0 ? -1.0E-150 : -1.0E-100)
                    : ($this->adjacentFloat($nextPole, -1) ?? $negativeUpper);
                $stripUpper = \min($negativeUpper, $insideUpper);
                if ($stripLower > $stripUpper) {
                    continue;
                }
                if (($order & 1) === 0) {
                    if (!$addMonotoneInterval($stripLower, $stripUpper, true)) {
                        return null;
                    }
                    continue;
                }
                $minimumArgument = $this->invertMonotoneFunctionLevel(
                    0.0,
                    $pole + 0.25,
                    $pole + 0.75,
                    static fn (float $value): float => SpecialFunctions::polygamma($order + 1, $value),
                    true,
                    $options->maxIterations,
                );
                if ($minimumArgument === null) {
                    return null;
                }
                $leftUpper = \min($stripUpper, $minimumArgument);
                if (
                    $stripLower <= $leftUpper
                    && !$addMonotoneInterval($stripLower, $leftUpper, false)
                ) {
                    return null;
                }
                $rightLower = \max($stripLower, $minimumArgument);
                if (
                    $rightLower <= $stripUpper
                    && !$addMonotoneInterval($rightLower, $stripUpper, true)
                ) {
                    return null;
                }
            }
        }

        if ($upperBound > 0.0) {
            $positiveLower = \max($lowerBound, $order === 0 ? 1.0E-150 : 1.0E-100);
            if (!$addMonotoneInterval($positiveLower, $upperBound, ($order & 1) === 0)) {
                return null;
            }
        }
        \sort($levels, \SORT_NUMERIC);

        return $levels;
    }

    /**
     * Find the finite portion of an interval when function values overflow near its boundaries.
     *
     * @param callable(float): float $function
     * @return array{float, float, float, float}|null
     */
    private function finiteFunctionInterval(
        float $lowerBound,
        float $upperBound,
        callable $function,
    ): ?array {
        $evaluate = static function (float $value) use ($function): ?float {
            try {
                $result = $function($value);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }

            return \is_finite($result) ? $result : null;
        };
        $lowerValue = $evaluate($lowerBound);
        $upperValue = $evaluate($upperBound);
        $interior = null;
        $interiorValue = null;
        if ($lowerValue !== null) {
            $interior = $lowerBound;
            $interiorValue = $lowerValue;
        } elseif ($upperValue !== null) {
            $interior = $upperBound;
            $interiorValue = $upperValue;
        } else {
            for ($step = 1; $step <= 16; ++$step) {
                $fraction = 1.0 / (2 ** $step);
                foreach ([$fraction, 1.0 - $fraction] as $positionFraction) {
                    $candidate = $lowerBound
                        + (($upperBound - $lowerBound) * $positionFraction);
                    $candidateValue = $evaluate($candidate);
                    if ($candidateValue !== null) {
                        $interior = $candidate;
                        $interiorValue = $candidateValue;
                        break 2;
                    }
                }
            }
        }
        if ($interior === null || $interiorValue === null) {
            return null;
        }

        $finiteLower = $lowerBound;
        $finiteLowerValue = $lowerValue;
        if ($finiteLowerValue === null) {
            $invalid = $lowerBound;
            $valid = $interior;
            $validValue = $interiorValue;
            for ($iteration = 0; $iteration < 64; ++$iteration) {
                $middle = $invalid + (($valid - $invalid) / 2.0);
                if ($middle === $invalid || $middle === $valid) {
                    break;
                }
                $middleValue = $evaluate($middle);
                if ($middleValue === null) {
                    $invalid = $middle;
                } else {
                    $valid = $middle;
                    $validValue = $middleValue;
                }
            }
            $finiteLower = $valid;
            $finiteLowerValue = $validValue;
        }

        $finiteUpper = $upperBound;
        $finiteUpperValue = $upperValue;
        if ($finiteUpperValue === null) {
            $invalid = $upperBound;
            $valid = $interior;
            $validValue = $interiorValue;
            for ($iteration = 0; $iteration < 64; ++$iteration) {
                $middle = $valid + (($invalid - $valid) / 2.0);
                if ($middle === $valid || $middle === $invalid) {
                    break;
                }
                $middleValue = $evaluate($middle);
                if ($middleValue === null) {
                    $invalid = $middle;
                } else {
                    $valid = $middle;
                    $validValue = $middleValue;
                }
            }
            $finiteUpper = $valid;
            $finiteUpperValue = $validValue;
        }

        return [$finiteLower, $finiteLowerValue, $finiteUpper, $finiteUpperValue];
    }

    private function invertLogGammaFunctionLevels(
        float $target,
        float $lowerBound,
        float $upperBound,
        callable $function,
        SolverOptions $options,
    ): ?array {
        $levels = [];
        $addMonotoneInterval = function (
            float $lower,
            float $upper,
            bool $increasing,
        ) use (
            $target,
            $function,
            $options,
            &$levels,
        ): bool {
            if ($lower > $upper) {
                return true;
            }
            try {
                $lowerValue = $function($lower);
                $upperValue = $function($upper);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return false;
            }
            if (
                !\is_finite($lowerValue)
                || !\is_finite($upperValue)
                || $target < \min($lowerValue, $upperValue)
                || $target > \max($lowerValue, $upperValue)
            ) {
                return true;
            }
            $level = $this->invertMonotoneFunctionLevel(
                $target,
                $lower,
                $upper,
                $function,
                $increasing,
                $options->maxIterations,
            );
            if ($level === null) {
                return false;
            }
            if (!\in_array($level, $levels, true)) {
                $levels[] = $level;
            }

            return true;
        };

        if ($upperBound > 0.0) {
            $positiveLower = $lowerBound > 0.0 ? $lowerBound : \PHP_FLOAT_MIN;
            $minimumArgument = $this->invertMonotoneFunctionLevel(
                0.0,
                1.0,
                2.0,
                SpecialFunctions::digamma(...),
                true,
                $options->maxIterations,
            );
            if ($minimumArgument === null) {
                return null;
            }
            $leftUpper = \min($upperBound, $minimumArgument);
            if (
                $positiveLower <= $leftUpper
                && !$addMonotoneInterval($positiveLower, $leftUpper, false)
            ) {
                return null;
            }
            $rightLower = \max($positiveLower, $minimumArgument);
            if (
                $rightLower <= $upperBound
                && !$addMonotoneInterval($rightLower, $upperBound, true)
            ) {
                return null;
            }
        }

        $negativeUpper = \min($upperBound, 0.0);
        if ($lowerBound < $negativeUpper) {
            $firstStrip = (int) \floor($lowerBound);
            $lastStrip = (int) \ceil($negativeUpper) - 1;
            for ($integer = $firstStrip; $integer <= $lastStrip; ++$integer) {
                if ($integer >= 0) {
                    continue;
                }
                $pole = (float) $integer;
                $nextPole = (float) ($integer + 1);
                $stripLower = \max(
                    $lowerBound,
                    $this->adjacentFloat($pole, 1) ?? $lowerBound,
                );
                $insideUpper = $nextPole === 0.0
                    ? -\PHP_FLOAT_MIN
                    : ($this->adjacentFloat($nextPole, -1) ?? $negativeUpper);
                $stripUpper = \min($negativeUpper, $insideUpper);
                if ($stripLower > $stripUpper) {
                    continue;
                }

                $digammaLower = SpecialFunctions::digamma($pole + 0.25);
                $digammaUpper = SpecialFunctions::digamma($pole + 0.75);
                if ($digammaLower === 0.0 || $digammaUpper === 0.0) {
                    return null;
                }
                if (($digammaLower < 0.0) === ($digammaUpper < 0.0)) {
                    if (!$addMonotoneInterval($stripLower, $stripUpper, $digammaLower > 0.0)) {
                        return null;
                    }
                    continue;
                }

                $criticalPoint = $this->invertMonotoneFunctionLevel(
                    0.0,
                    $pole + 0.25,
                    $pole + 0.75,
                    SpecialFunctions::digamma(...),
                    true,
                    $options->maxIterations,
                );
                if ($criticalPoint === null) {
                    return null;
                }
                $leftUpper = \min($stripUpper, $criticalPoint);
                if (
                    $stripLower <= $leftUpper
                    && !$addMonotoneInterval($stripLower, $leftUpper, $digammaLower > 0.0)
                ) {
                    return null;
                }
                $rightLower = \max($stripLower, $criticalPoint);
                if (
                    $rightLower <= $stripUpper
                    && !$addMonotoneInterval($rightLower, $stripUpper, $digammaUpper > 0.0)
                ) {
                    return null;
                }
            }
        }

        \sort($levels, \SORT_NUMERIC);

        return $levels;
    }

    /**
     * @param callable(float): float $function
     * @return list<float>|null
     */
    private function invertNegativeGammaFunctionLevels(
        float $target,
        float $lowerBound,
        float $upperBound,
        callable $function,
        SolverOptions $options,
    ): ?array {
        if ($lowerBound >= 0.0 || $upperBound > 0.0) {
            return null;
        }

        $levels = [];
        $addMonotoneInterval = function (float $lower, float $upper, bool $increasing) use (
            $target,
            $function,
            $options,
            &$levels,
        ): bool {
            if ($lower > $upper) {
                return true;
            }
            try {
                $lowerValue = $function($lower);
                $upperValue = $function($upper);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return false;
            }
            if (
                !\is_finite($lowerValue)
                || !\is_finite($upperValue)
                || $target < \min($lowerValue, $upperValue)
                || $target > \max($lowerValue, $upperValue)
            ) {
                return true;
            }
            $level = $this->invertMonotoneFunctionLevel(
                $target,
                $lower,
                $upper,
                $function,
                $increasing,
                $options->maxIterations,
            );
            if ($level === null) {
                return false;
            }
            if (!\in_array($level, $levels, true)) {
                $levels[] = $level;
            }

            return true;
        };

        $firstStrip = (int) \floor($lowerBound);
        $lastStrip = (int) \ceil($upperBound) - 1;
        for ($integer = $firstStrip; $integer <= $lastStrip; ++$integer) {
            if ($integer >= 0) {
                continue;
            }
            $pole = (float) $integer;
            $nextPole = (float) ($integer + 1);
            $stripLower = \max($lowerBound, $this->adjacentFloat($pole, 1) ?? $lowerBound);
            $stripUpper = $nextPole === 0.0
                ? \min($upperBound, -\PHP_FLOAT_MIN)
                : \min($upperBound, $this->adjacentFloat($nextPole, -1) ?? $upperBound);
            if ($stripLower > $stripUpper) {
                continue;
            }

            $digammaLower = SpecialFunctions::digamma($pole + 0.25);
            $digammaUpper = SpecialFunctions::digamma($pole + 0.75);
            if ($digammaLower === 0.0 || $digammaUpper === 0.0) {
                return null;
            }
            if (($digammaLower < 0.0) === ($digammaUpper < 0.0)) {
                try {
                    $midpointValue = $function($pole + 0.5);
                } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                    return null;
                }
                if (!\is_finite($midpointValue) || $midpointValue === 0.0) {
                    return null;
                }
                $increasing = ($midpointValue < 0.0) === ($digammaLower < 0.0);
                if (!$addMonotoneInterval($stripLower, $stripUpper, $increasing)) {
                    return null;
                }
                continue;
            }

            $criticalPoint = $this->invertMonotoneFunctionLevel(
                0.0,
                $pole + 0.25,
                $pole + 0.75,
                SpecialFunctions::digamma(...),
                true,
                $options->maxIterations,
            );
            if ($criticalPoint === null) {
                return null;
            }
            try {
                $criticalValue = $function($criticalPoint);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            if (!\is_finite($criticalValue)) {
                return null;
            }
            $positiveLobe = $criticalValue > 0.0;
            $leftUpper = \min($stripUpper, $criticalPoint);
            if (
                $stripLower <= $leftUpper
                && !$addMonotoneInterval($stripLower, $leftUpper, !$positiveLobe)
            ) {
                return null;
            }
            $rightLower = \max($stripLower, $criticalPoint);
            if (
                $rightLower <= $stripUpper
                && !$addMonotoneInterval($rightLower, $stripUpper, $positiveLobe)
            ) {
                return null;
            }
        }

        \sort($levels, \SORT_NUMERIC);

        return $levels;
    }

    /**
     * @param callable(float): float $function
     * @return list<float>|null
     */
    private function invertGammaFunctionLevels(
        float $target,
        float $lowerBound,
        float $upperBound,
        callable $function,
        SolverOptions $options,
    ): ?array {
        if (
            $lowerBound < -171.0
            || $upperBound > 171.0
            || $lowerBound > $upperBound
        ) {
            return null;
        }

        $levels = [];
        if ($lowerBound < 0.0) {
            $negativeLevels = $this->invertNegativeGammaFunctionLevels(
                $target,
                $lowerBound,
                \min($upperBound, 0.0),
                $function,
                $options,
            );
            if ($negativeLevels === null) {
                return null;
            }
            $levels = $negativeLevels;
        }

        if ($upperBound > 0.0) {
            $minimumArgument = $this->invertMonotoneFunctionLevel(
                0.0,
                1.0,
                2.0,
                SpecialFunctions::digamma(...),
                true,
                $options->maxIterations,
            );
            if ($minimumArgument === null) {
                return null;
            }

            $positiveLower = \max($lowerBound, \PHP_FLOAT_MIN);
            $decreasingUpper = \min($upperBound, $minimumArgument);
            if ($positiveLower <= $decreasingUpper) {
                if ($lowerBound <= 0.0) {
                    try {
                        $upperValue = $function($decreasingUpper);
                    } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                        return null;
                    }
                    if ($target >= $upperValue) {
                        $bracketLower = $decreasingUpper;
                        for ($iteration = 0; $iteration < 1_100; ++$iteration) {
                            $candidate = $bracketLower / 2.0;
                            if ($candidate === 0.0) {
                                return null;
                            }
                            try {
                                $candidateValue = $function($candidate);
                            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                                return null;
                            }
                            $bracketLower = $candidate;
                            if ($candidateValue >= $target) {
                                break;
                            }
                        }
                        try {
                            $bracketValue = $function($bracketLower);
                        } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                            return null;
                        }
                        if ($bracketValue < $target) {
                            return null;
                        }
                        $level = $this->invertMonotoneFunctionLevel(
                            $target,
                            $bracketLower,
                            $decreasingUpper,
                            $function,
                            false,
                            $options->maxIterations,
                        );
                        if ($level === null) {
                            return null;
                        }
                        $levels[] = $level;
                    }
                } else {
                    $lowerValue = $function($positiveLower);
                    $upperValue = $function($decreasingUpper);
                    if ($target >= \min($lowerValue, $upperValue) && $target <= \max($lowerValue, $upperValue)) {
                        $level = $this->invertMonotoneFunctionLevel(
                            $target,
                            $positiveLower,
                            $decreasingUpper,
                            $function,
                            false,
                            $options->maxIterations,
                        );
                        if ($level === null) {
                            return null;
                        }
                        $levels[] = $level;
                    }
                }
            }

            $increasingLower = \max($positiveLower, $minimumArgument);
            if ($increasingLower <= $upperBound) {
                try {
                    $lowerValue = $function($increasingLower);
                    $upperValue = $function($upperBound);
                } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                    return null;
                }
                if ($target >= \min($lowerValue, $upperValue) && $target <= \max($lowerValue, $upperValue)) {
                    $level = $this->invertMonotoneFunctionLevel(
                        $target,
                        $increasingLower,
                        $upperBound,
                        $function,
                        true,
                        $options->maxIterations,
                    );
                    if ($level === null) {
                        return null;
                    }
                    $levels[] = $level;
                }
            }
        }

        \sort($levels, \SORT_NUMERIC);

        return \array_values(\array_unique($levels, SORT_REGULAR));
    }

    /**
     * @param callable(float): float $function
     * @return list<float>|null
     */
    private function invertZetaFunctionLevels(
        float $target,
        float $lowerBound,
        float $upperBound,
        callable $function,
        SolverOptions $options,
    ): ?array {
        if ($lowerBound === $upperBound) {
            try {
                return $function($lowerBound) === $target ? [$lowerBound] : [];
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
        }

        $segmentCount = (int) \ceil(($upperBound - $lowerBound) * 4.0);
        if ($segmentCount < 1 || $segmentCount > 512) {
            return null;
        }
        $derivativeAt = static fn (float $value): ?float =>
            SpecialFunctions::riemannZetaDerivative($value);
        $criticalPoints = [$lowerBound, $upperBound];
        $previousPosition = $lowerBound;
        $previousDerivative = $derivativeAt($previousPosition);
        if ($previousDerivative === null) {
            return null;
        }

        for ($index = 1; $index <= $segmentCount; ++$index) {
            $position = $index === $segmentCount
                ? $upperBound
                : $lowerBound + (($upperBound - $lowerBound) * ($index / $segmentCount));
            $derivative = $derivativeAt($position);
            if ($derivative === null) {
                return null;
            }
            if ($derivative === 0.0) {
                $criticalPoints[] = $position;
            } elseif ($previousDerivative === 0.0) {
                $criticalPoints[] = $previousPosition;
            } elseif ($this->hasOppositeSigns($previousDerivative, $derivative)) {
                $left = $previousPosition;
                $right = $position;
                $leftDerivative = $previousDerivative;
                for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
                    $middle = $left + (($right - $left) / 2.0);
                    if ($middle === $left || $middle === $right) {
                        break;
                    }
                    $middleDerivative = $derivativeAt($middle);
                    if ($middleDerivative === null) {
                        return null;
                    }
                    if ($middleDerivative === 0.0) {
                        $left = $middle;
                        $right = $middle;
                        break;
                    }
                    if ($this->hasOppositeSigns($leftDerivative, $middleDerivative)) {
                        $right = $middle;
                    } else {
                        $left = $middle;
                        $leftDerivative = $middleDerivative;
                    }
                }
                $criticalPoints[] = $left + (($right - $left) / 2.0);
            }
            $previousPosition = $position;
            $previousDerivative = $derivative;
        }

        \sort($criticalPoints, \SORT_NUMERIC);
        $criticalPoints = \array_values(\array_unique($criticalPoints, \SORT_REGULAR));
        $levels = [];
        for ($index = 1, $count = \count($criticalPoints); $index < $count; ++$index) {
            $segmentLower = $criticalPoints[$index - 1];
            $segmentUpper = $criticalPoints[$index];
            try {
                $lowerValue = $function($segmentLower);
                $upperValue = $function($segmentUpper);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            if (
                !\is_finite($lowerValue)
                || !\is_finite($upperValue)
                || $target < \min($lowerValue, $upperValue)
                || $target > \max($lowerValue, $upperValue)
            ) {
                continue;
            }
            $level = $this->invertMonotoneFunctionLevel(
                $target,
                $segmentLower,
                $segmentUpper,
                $function,
                $upperValue >= $lowerValue,
                $options->maxIterations,
            );
            if ($level === null) {
                return null;
            }
            if ($levels === [] || $levels[\count($levels) - 1] !== $level) {
                $levels[] = $level;
            }
        }

        return $levels;
    }

    /** @return list<EquationSolution>|null */
    private function solveIntegerShapeBetaEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $beta = null;
        $targetNode = null;
        if (
            $left instanceof FunctionCallNode
            && $left->name === 'beta'
            && \count($left->arguments) === 2
            && !$this->containsVariable($right, $variable)
        ) {
            $beta = $left;
            $targetNode = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && $right->name === 'beta'
            && \count($right->arguments) === 2
            && !$this->containsVariable($left, $variable)
        ) {
            $beta = $right;
            $targetNode = $left;
        }
        if ($beta === null || $targetNode === null) {
            return null;
        }

        $target = $this->extractPolynomial(
            $extractor,
            $targetNode,
            $targetNode->span()->start,
        );
        if ($target === null || \count($target) !== 1 || !\is_finite($target[0])) {
            return null;
        }
        foreach ([[$beta->arguments[0], $beta->arguments[1]], [$beta->arguments[1], $beta->arguments[0]]] as [$argument, $shapeNode]) {
            $shape = $this->extractPolynomial(
                $extractor,
                $shapeNode,
                $shapeNode->span()->start,
            );
            if (
                $shape === null
                || \count($shape) !== 1
                || !\is_finite($shape[0])
                || $shape[0] < 1.0
                || $shape[0] > \min(64, $options->maxPolynomialDegree)
                || \floor($shape[0]) !== $shape[0]
            ) {
                continue;
            }
            $argumentPolynomial = $this->extractPolynomial(
                $extractor,
                $argument,
                $argument->span()->start,
            );
            if ($argumentPolynomial === null || \count($argumentPolynomial) < 2) {
                continue;
            }
            if ($target[0] === 0.0) {
                return [];
            }

            $shapeInteger = (int) $shape[0];
            $denominatorPolynomial = [1.0];
            for ($offset = 0; $offset < $shapeInteger; ++$offset) {
                $denominatorPolynomial = $this->multiplyPolynomials(
                    $denominatorPolynomial,
                    $this->addPolynomials($argumentPolynomial, [(float) $offset]),
                );
                foreach ($denominatorPolynomial as $coefficient) {
                    if (!\is_finite($coefficient)) {
                        return null;
                    }
                }
            }
            $numeratorConstant = 1.0;
            for ($factor = 2; $factor < $shapeInteger; ++$factor) {
                $numeratorConstant *= $factor;
                if (!\is_finite($numeratorConstant)) {
                    return null;
                }
            }
            $equationPolynomial = \array_map(
                static fn (float $coefficient): float => $target[0] * $coefficient,
                $denominatorPolynomial,
            );
            $equationPolynomial[0] -= $numeratorConstant;
            foreach ($equationPolynomial as $coefficient) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }

            $candidates = $this->solvePolynomialRootsInInterval(
                $equationPolynomial,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($candidates === null) {
                return null;
            }
            if (\count($equationPolynomial) > 2) {
                $derivative = [];
                foreach ($equationPolynomial as $degree => $coefficient) {
                    if ($degree > 0) {
                        $derivative[] = $degree * $coefficient;
                    }
                }
                $stationaryPoints = $this->solvePolynomialRootsInInterval(
                    $derivative,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($stationaryPoints === null) {
                    return null;
                }
                $polynomialSolver = new PolynomialSolver();
                foreach ($stationaryPoints as $stationaryPoint) {
                    $value = $stationaryPoint->value;
                    $polynomialResidual = $polynomialSolver->evaluatePolynomial(
                        $equationPolynomial,
                        $value,
                    );
                    $polynomialMagnitude = $polynomialSolver->evaluatePolynomialMagnitude(
                        $equationPolynomial,
                        $value,
                    );
                    if (
                        $polynomialResidual !== null
                        && $polynomialMagnitude !== null
                        && \abs($polynomialResidual)
                            <= 64.0 * \PHP_FLOAT_EPSILON * \max($polynomialMagnitude, \PHP_FLOAT_MIN)
                    ) {
                        $candidates[] = new EquationSolution(
                            $value,
                            \abs($polynomialResidual),
                            $stationaryPoint->iterations,
                        );
                    }
                }
            }
            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addDistinctRepresentableSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * @param callable(float): float $function
     */
    /**
     * Split affine beta equations at numerator and denominator gamma poles,
     * then certify each pole-free float interval independently.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineBetaEquationAcrossPoles(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound) || $lowerBound >= $upperBound) {
            return null;
        }
        foreach ([[$left, $right], [$right, $left]] as [$candidateSide, $targetSide]) {
            $beta = $this->unwrapGrouping($candidateSide);
            if (
                !$beta instanceof FunctionCallNode
                || $beta->name !== 'beta'
                || \count($beta->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
                || $this->containsVariable($targetSide, $variable)
            ) {
                continue;
            }
            $targetCoefficients = $extractor->extract($targetSide);
            if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
                continue;
            }

            foreach ([[$beta->arguments[0], $beta->arguments[1]], [$beta->arguments[1], $beta->arguments[0]]] as [$variableArgument, $constantArgument]) {
                if (
                    !$this->containsVariable($variableArgument, $variable)
                    || $this->containsVariable($constantArgument, $variable)
                ) {
                    continue;
                }
                $argumentCoefficients = $extractor->extract($variableArgument);
                $shape = $this->constantNodeValue($constantArgument, $parameters, $evaluationOptions);
                if (
                    $argumentCoefficients === null
                    || \count($argumentCoefficients) !== 2
                    || !\is_finite($argumentCoefficients[0])
                    || !\is_finite($argumentCoefficients[1])
                    || $argumentCoefficients[1] === 0.0
                    || $shape === null
                    || !\is_finite($shape)
                    || \floor($shape) === $shape
                ) {
                    continue;
                }
                $slope = $argumentCoefficients[1];
                $intercept = $argumentCoefficients[0];
                $argumentRange = [
                    ($slope * $lowerBound) + $intercept,
                    ($slope * $upperBound) + $intercept,
                ];
                $sumIntercept = $intercept + $shape;
                $sumRange = [
                    ($slope * $lowerBound) + $sumIntercept,
                    ($slope * $upperBound) + $sumIntercept,
                ];
                if (
                    !\is_finite($argumentRange[0])
                    || !\is_finite($argumentRange[1])
                    || !\is_finite($sumRange[0])
                    || !\is_finite($sumRange[1])
                    || \min($argumentRange) < -171.0
                ) {
                    continue;
                }

                $polePositions = [];
                $polePositionPadding = [];
                $supportCutPositions = [];
                foreach ([$intercept, $sumIntercept] as $offset) {
                    $range = [($slope * $lowerBound) + $offset, ($slope * $upperBound) + $offset];
                    $firstPole = (int) \max(-171.0, \ceil(\min($range)));
                    $lastPole = (int) \min(0.0, \floor(\max($range)));
                    for ($pole = $firstPole; $pole <= $lastPole; ++$pole) {
                        $position = ($pole - $offset) / $slope;
                        if (\is_finite($position) && $position >= $lowerBound && $position <= $upperBound) {
                            $key = \sprintf('%.17g', $position);
                            $polePositions[$key] = $position;
                            $padding = 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($position));
                            $argumentPadding = 16.0 * \PHP_FLOAT_EPSILON
                                * \max(1.0, \abs($pole), \abs($offset)) / \abs($slope);
                            if (!\is_finite($argumentPadding)) {
                                return null;
                            }
                            $polePositionPadding[$key] = \max(
                                $polePositionPadding[$key] ?? 0.0,
                                $padding,
                                $argumentPadding,
                            );
                        }
                    }
                    foreach ([-171.0, 171.0] as $supportBoundary) {
                        $position = ($supportBoundary - $offset) / $slope;
                        if (\is_finite($position) && $position > $lowerBound && $position < $upperBound) {
                            $supportCutPositions[] = $position;
                        }
                    }
                }
                $boundaries = \array_values(\array_unique([
                    $lowerBound,
                    ...\array_values($polePositions),
                    ...$supportCutPositions,
                    $upperBound,
                ], SORT_REGULAR));
                \sort($boundaries, SORT_NUMERIC);
                $solutions = [];
                foreach ([$lowerBound, $upperBound, ...\array_values($polePositions)] as $boundary) {
                    $positions = [$boundary];
                    $key = \sprintf('%.17g', $boundary);
                    if (isset($polePositions[$key])) {
                        $offset = $polePositionPadding[$key];
                        $positions[] = $boundary - $offset;
                        $positions[] = $boundary + $offset;
                    }
                    foreach ($positions as $position) {
                        if ($position < $lowerBound || $position > $upperBound) {
                            continue;
                        }
                        $residual = $residualAt($position);
                        if (
                            $residual !== null
                            && $this->isResidualAcceptableAt(
                                $position,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            $this->addDistinctRepresentableSolution(
                                $solutions,
                                new EquationSolution($position, \abs($residual), 0),
                                $solverOptions,
                            );
                        }
                    }
                }

                for ($index = 1, $count = \count($boundaries); $index < $count; ++$index) {
                    $lower = $boundaries[$index - 1];
                    $upper = $boundaries[$index];
                    $lowerKey = \sprintf('%.17g', $lower);
                    $upperKey = \sprintf('%.17g', $upper);
                    if (isset($polePositions[$lowerKey])) {
                        $lower += $polePositionPadding[$lowerKey];
                    }
                    if (isset($polePositions[$upperKey])) {
                        $upper -= $polePositionPadding[$upperKey];
                    }
                    if ($lower >= $upper) {
                        return null;
                    }
                    $midpoint = $lower + (($upper - $lower) / 2.0);
                    $argumentValue = ($slope * $midpoint) + $intercept;
                    $sumValue = $argumentValue + $shape;
                    if (
                        \abs($argumentValue) > 171.0
                        || \abs($shape) > 171.0
                        || \abs($sumValue) > 171.0
                        || ($argumentValue <= 0.0 && \floor($argumentValue) === $argumentValue)
                        || ($shape <= 0.0 && \floor($shape) === $shape)
                        || ($sumValue <= 0.0 && \floor($sumValue) === $sumValue)
                    ) {
                        continue;
                    }
                    $targetValue = $targetCoefficients[0];
                    if ($targetValue !== 0.0) {
                        $betaSign = $this->gammaSign($argumentValue)
                            * $this->gammaSign($shape)
                            * $this->gammaSign($sumValue);
                        if (($betaSign < 0.0) !== ($targetValue < 0.0)) {
                            continue;
                        }
                    }
                    $segmentSolutions = $this->solveCustomArithmeticIntervalEquation(
                        $left,
                        $right,
                        $variable,
                        $lower,
                        $upper,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        $residualAt,
                        includeBuiltInFunctions: true,
                        requireCompleteCertification: false,
                    );
                    if ($segmentSolutions === null) {
                        return null;
                    }
                    foreach ($segmentSolutions as $solution) {
                        $this->addDistinctRepresentableSolution($solutions, $solution, $solverOptions);
                    }
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }
        }

        return null;
    }

    private function gammaSign(float $value): float
    {
        if ($value > 0.0) {
            return 1.0;
        }
        $negativeInterval = (int) \ceil(-$value);

        return $negativeInterval % 2 === 0 ? 1.0 : -1.0;
    }

    /** @param callable(float): float $function */
    private function invertMonotoneFunctionLevel(
        float $target,
        float $lowerBound,
        float $upperBound,
        callable $function,
        bool $increasing,
        int $maxIterations,
    ): ?float {
        try {
            $lowerValue = $function($lowerBound);
            $upperValue = $function($upperBound);
        } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
            return null;
        }
        if (
            !\is_finite($lowerValue)
            || !\is_finite($upperValue)
            || !\is_finite($target)
            || !\is_finite($lowerBound)
            || !\is_finite($upperBound)
            || $lowerBound > $upperBound
            || ($increasing && ($target < $lowerValue || $target > $upperValue))
            || (!$increasing && ($target > $lowerValue || $target < $upperValue))
        ) {
            return null;
        }
        if ($target === $lowerValue || $lowerBound === $upperBound) {
            return $lowerBound;
        }
        if ($target === $upperValue) {
            return $upperBound;
        }

        $lower = $lowerBound;
        $upper = $upperBound;
        for ($iteration = 0; $iteration < $maxIterations; ++$iteration) {
            $middle = ($lower / 2.0) + ($upper / 2.0);
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            try {
                $value = $function($middle);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            if (!\is_finite($value)) {
                return null;
            }
            if ($value === $target) {
                return $middle;
            }
            if (($value < $target) === $increasing) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        try {
            $lowerResidual = \abs($function($lower) - $target);
            $upperResidual = \abs($function($upper) - $target);
        } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
            return null;
        }

        return $lowerResidual <= $upperResidual ? $lower : $upper;
    }

    /**
     * Prove that a rational-coefficient polynomial keeps a strict positive sign
     * on the interval by counting its exact roots and evaluating one interior point.
     *
     * @param array<string, int|float> $parameters
     */
    private function isStrictlyPositivePolynomialOnInterval(
        string $expression,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        try {
            $node = (new Parser(
                (new Lexer($expression, $evaluationOptions->limits))->tokenize(),
                $evaluationOptions->limits,
                $evaluationOptions->functions,
            ))->parse();
        } catch (MathException) {
            return false;
        }
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $coefficients = $extractor->integerCoefficients($extractor->polynomial($node));
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($coefficients === null || $lower === null || $upper === null) {
            return false;
        }

        $counter = new ExactPolynomialRootCounter();
        $rootCount = $counter->countOpenInterval(
            $coefficients,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        if (
            $rootCount !== 0
            || $counter->signAt($coefficients, $lower) !== 1
            || $counter->signAt($coefficients, $upper) !== 1
        ) {
            return false;
        }

        $middle = ($lowerBound / 2.0) + ($upperBound / 2.0);
        if ($middle === $lowerBound || $middle === $upperBound) {
            return false;
        }
        $middleRational = RationalLiteral::fromFloatAsStrings($middle);

        return $middleRational !== null
            && $counter->signAt($coefficients, $middleRational) === 1;
    }

    /** @param array<string, int|float> $parameters */
    private function trigonometricEquationIsOutsidePositiveExponentialRange(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        foreach ([[$left, $right], [$right, $left]] as [$trigonometric, $exponential]) {
            $trigonometric = $this->unwrapGrouping($trigonometric);
            $exponential = $this->unwrapGrouping($exponential);
            if (
                !$trigonometric instanceof FunctionCallNode
                || !\in_array($trigonometric->name, ['sin', 'cos'], true)
                || \count($trigonometric->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($trigonometric->name)
                || !$exponential instanceof FunctionCallNode
                || $exponential->name !== 'exp'
                || \count($exponential->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('exp')
            ) {
                continue;
            }
            $sign = $this->expressionSignOnInterval(
                $exponential->arguments[0],
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $sign['positive']
                || $this->polynomialIsPositiveOnOpenInterval(
                    $exponential->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
                || $this->isPositiveConstantOverSquareRootOfNonnegativePolynomial(
                    $exponential->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function constantIntegerExponentParity(
        Node $node,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?int {
        $exactFraction = RationalLiteral::fromNodeAsStrings($node);
        if ($exactFraction !== null) {
            if ($exactFraction[1] !== '1') {
                return null;
            }

            return (int) \substr($exactFraction[0], -1) % 2;
        }
        if ($node instanceof VariableNode && \array_key_exists($node->name, $parameters)) {
            $parameter = $parameters[$node->name];
            if (\is_int($parameter)) {
                return $parameter % 2 === 0 ? 0 : 1;
            }
            if (
                \is_finite($parameter)
                && \floor($parameter) === $parameter
                && \abs($parameter) >= 9_007_199_254_740_992.0
            ) {
                return 0;
            }
            if (\is_finite($parameter) && \floor($parameter) === $parameter) {
                return \fmod(\abs($parameter), 2.0) === 0.0 ? 0 : 1;
            }

            return null;
        }
        try {
            $exponent = $this->evaluateNode($node, $parameters, $evaluationOptions);
        } catch (EvaluationException) {
            return null;
        }

        return \is_int($exponent) ? ($exponent % 2 === 0 ? 0 : 1) : null;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function containsEvenIntegerPower(
        Node $node,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode) {
            if (
                $node->operator === BinaryOperator::Power
                && $this->constantIntegerExponentParity(
                    $node->right,
                    $parameters,
                    $evaluationOptions,
                ) === 0
            ) {
                return true;
            }

            return $this->containsEvenIntegerPower($node->left, $parameters, $evaluationOptions)
                || $this->containsEvenIntegerPower($node->right, $parameters, $evaluationOptions);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsEvenIntegerPower($node->operand, $parameters, $evaluationOptions);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsEvenIntegerPower($node->operand, $parameters, $evaluationOptions);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsEvenIntegerPower($argument, $parameters, $evaluationOptions)) {
                    return true;
                }
            }
        }

        return false;
    }

    private function containsSignClassifiableFunction(
        Node $node,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if (
                \in_array($node->name, ['abs', 'sqrt', 'hypot', 'cosh', 'sech'], true)
                && $evaluationOptions->functions->isBuiltIn($node->name)
            ) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsSignClassifiableFunction($argument, $evaluationOptions)) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsSignClassifiableFunction($node->expression, $evaluationOptions);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsSignClassifiableFunction($node->operand, $evaluationOptions);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsSignClassifiableFunction($node->left, $evaluationOptions)
                || $this->containsSignClassifiableFunction($node->right, $evaluationOptions);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsSignClassifiableFunction($node->operand, $evaluationOptions);
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function polynomialIsPositiveOnOpenInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $coefficients = $extractor->integerCoefficients($extractor->polynomial($node));
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($coefficients === null || $lower === null || $upper === null) {
            return false;
        }
        $counter = new ExactPolynomialRootCounter();
        if ($counter->countOpenInterval(
            $coefficients,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        ) !== 0) {
            return false;
        }

        $middle = ($lowerBound / 2.0) + ($upperBound / 2.0);
        if ($middle === $lowerBound || $middle === $upperBound) {
            return false;
        }
        $middleRational = RationalLiteral::fromFloatAsStrings($middle);

        return $middleRational !== null
            && $counter->signAt($coefficients, $middleRational) > 0;
    }

    /**
     * Classify signs conservatively on the closed interval.
     *
     * @param array<string, int|float> $parameters
     * @return array{positive: bool, nonnegative: bool, negative: bool, nonpositive: bool}
     */
    private function expressionSignOnInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        $unknown = ['positive' => false, 'nonnegative' => false, 'negative' => false, 'nonpositive' => false];
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $sign = $this->expressionSignOnInterval(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($node->operator === UnaryOperator::Plus) {
                return $sign;
            }

            return [
                'positive' => $sign['negative'],
                'nonnegative' => $sign['nonpositive'],
                'negative' => $sign['positive'],
                'nonpositive' => $sign['nonnegative'],
            ];
        }
        if ($node instanceof BinaryOperationNode) {
            $left = $this->expressionSignOnInterval(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $right = $this->expressionSignOnInterval(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($node->operator === BinaryOperator::Add) {
                return [
                    'positive' => $left['nonnegative'] && $right['nonnegative']
                        && ($left['positive'] || $right['positive']),
                    'nonnegative' => $left['nonnegative'] && $right['nonnegative'],
                    'negative' => $left['nonpositive'] && $right['nonpositive']
                        && ($left['negative'] || $right['negative']),
                    'nonpositive' => $left['nonpositive'] && $right['nonpositive'],
                ];
            }
            if ($node->operator === BinaryOperator::Subtract) {
                return $this->expressionSignOnInterval(
                    new BinaryOperationNode(
                        BinaryOperator::Add,
                        $node->left,
                        new UnaryOperationNode(UnaryOperator::Minus, $node->right, $node->right->span()),
                        $node->span(),
                    ),
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }
            if ($node->operator === BinaryOperator::Multiply) {
                $leftSigns = [
                    $left['positive'] || $left['nonnegative'],
                    $left['negative'] || $left['nonpositive'],
                ];
                $rightSigns = [
                    $right['positive'] || $right['nonnegative'],
                    $right['negative'] || $right['nonpositive'],
                ];
                $positive = ($left['positive'] && $right['positive'])
                    || ($left['negative'] && $right['negative']);
                $negative = ($left['positive'] && $right['negative'])
                    || ($left['negative'] && $right['positive']);
                $nonnegative = ($leftSigns[0] && $rightSigns[0])
                    || ($leftSigns[1] && $rightSigns[1]);
                $nonpositive = ($leftSigns[0] && $rightSigns[1])
                    || ($leftSigns[1] && $rightSigns[0]);

                return [
                    'positive' => $positive,
                    'nonnegative' => $nonnegative,
                    'negative' => $negative,
                    'nonpositive' => $nonpositive,
                ];
            }
            if ($node->operator === BinaryOperator::Divide) {
                $numeratorSigns = [
                    $left['positive'] || $left['nonnegative'],
                    $left['negative'] || $left['nonpositive'],
                ];
                $denominatorSigns = [
                    $right['positive'] || $right['nonnegative'],
                    $right['negative'] || $right['nonpositive'],
                ];
                $positiveDenominator = $right['positive'];
                $negativeDenominator = $right['negative'];
                $positive = ($left['positive'] && $positiveDenominator)
                    || ($left['negative'] && $negativeDenominator);
                $negative = ($left['positive'] && $negativeDenominator)
                    || ($left['negative'] && $positiveDenominator);
                $nonnegative = ($numeratorSigns[0] && $positiveDenominator)
                    || ($numeratorSigns[1] && $negativeDenominator);
                $nonpositive = ($numeratorSigns[0] && $negativeDenominator)
                    || ($numeratorSigns[1] && $positiveDenominator);

                return [
                    'positive' => $positive,
                    'nonnegative' => $nonnegative,
                    'negative' => $negative,
                    'nonpositive' => $nonpositive,
                ];
            }
            if ($node->operator === BinaryOperator::Power) {
                $exponentParity = $this->constantIntegerExponentParity(
                    $node->right,
                    $parameters,
                    $evaluationOptions,
                );
                if ($exponentParity === 0) {
                    return [
                        'positive' => $left['positive'] || $left['negative'],
                        'nonnegative' => true,
                        'negative' => false,
                        'nonpositive' => false,
                    ];
                }
                if ($exponentParity === 1) {
                    return $left;
                }
            }

            return $unknown;
        }
        if ($node instanceof FunctionCallNode && $evaluationOptions->functions->isBuiltIn($node->name)) {
            if ($node->name === 'exp' && \count($node->arguments) === 1) {
                return ['positive' => true, 'nonnegative' => true, 'negative' => false, 'nonpositive' => false];
            }
            if ($node->name === 'sqrt' && \count($node->arguments) === 1) {
                $argument = $this->expressionSignOnInterval(
                    $node->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );

                return [
                    'positive' => $argument['positive'],
                    'nonnegative' => true,
                    'negative' => false,
                    'nonpositive' => false,
                ];
            }
            if ($node->name === 'abs' && \count($node->arguments) === 1) {
                $argument = $this->expressionSignOnInterval(
                    $node->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );

                return [
                    'positive' => $argument['positive'] || $argument['negative'],
                    'nonnegative' => true,
                    'negative' => false,
                    'nonpositive' => false,
                ];
            }
            if (\in_array($node->name, ['cosh', 'sech'], true) && \count($node->arguments) === 1) {
                return ['positive' => true, 'nonnegative' => true, 'negative' => false, 'nonpositive' => false];
            }
            if ($node->name === 'hypot' && \count($node->arguments) === 2) {
                $first = $this->expressionSignOnInterval(
                    $node->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                $second = $this->expressionSignOnInterval(
                    $node->arguments[1],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );

                return [
                    'positive' => $first['positive'] || $first['negative']
                        || $second['positive'] || $second['negative'],
                    'nonnegative' => true,
                    'negative' => false,
                    'nonpositive' => false,
                ];
            }
        }

        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $polynomial = $exactExtractor->integerCoefficients($exactExtractor->polynomial($node));
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($polynomial === null || $lower === null || $upper === null) {
            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);
            if ($constant === null || !\is_finite($constant)) {
                return $unknown;
            }

            return [
                'positive' => $constant > 0.0,
                'nonnegative' => $constant >= 0.0,
                'negative' => $constant < 0.0,
                'nonpositive' => $constant <= 0.0,
            ];
        }
        if (\count($polynomial) === 1 && $polynomial[0] === '0') {
            return ['positive' => false, 'nonnegative' => true, 'negative' => false, 'nonpositive' => true];
        }
        $counter = new ExactPolynomialRootCounter();
        $rootCount = $counter->countOpenInterval(
            $polynomial,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        if ($rootCount !== 0) {
            return $unknown;
        }
        $lowerSign = $counter->signAt($polynomial, $lower);
        $upperSign = $counter->signAt($polynomial, $upper);
        $middle = ($lowerBound / 2.0) + ($upperBound / 2.0);
        $middleRational = RationalLiteral::fromFloatAsStrings($middle);
        $middleSign = $middleRational === null ? null : $counter->signAt($polynomial, $middleRational);
        if ($middleSign === null || $middleSign === 0) {
            return $unknown;
        }
        $positive = $middleSign > 0;
        $endpointsNonnegative = $lowerSign >= 0 && $upperSign >= 0;
        $endpointsNonpositive = $lowerSign <= 0 && $upperSign <= 0;

        return [
            'positive' => $positive && $lowerSign > 0 && $upperSign > 0,
            'nonnegative' => $positive && $endpointsNonnegative,
            'negative' => !$positive && $lowerSign < 0 && $upperSign < 0,
            'nonpositive' => !$positive && $endpointsNonpositive,
        ];
    }

    /** @param array<string, int|float> $parameters */
    private function isPositiveConstantOverSquareRootOfNonnegativePolynomial(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return false;
        }
        $numerator = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
        $denominator = $this->unwrapGrouping($node->right);
        if (
            $numerator === null
            || !\is_finite($numerator)
            || $numerator <= 0.0
            || !$denominator instanceof FunctionCallNode
            || $denominator->name !== 'sqrt'
            || \count($denominator->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn('sqrt')
        ) {
            return false;
        }
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $polynomial = $extractor->integerCoefficients($extractor->polynomial($denominator->arguments[0]));
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($polynomial === null || $lower === null || $upper === null) {
            return false;
        }

        $counter = new ExactPolynomialRootCounter();
        $rootCount = $counter->countOpenInterval(
            $polynomial,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        if ($rootCount === null) {
            return false;
        }
        if ($rootCount !== 0) {
            return false;
        }

        $lowerSign = $counter->signAt($polynomial, $lower);
        $upperSign = $counter->signAt($polynomial, $upper);
        $middle = ($lowerBound / 2.0) + ($upperBound / 2.0);
        $middleRational = RationalLiteral::fromFloatAsStrings($middle);
        if ($middleRational === null) {
            return false;
        }
        $middleSign = $counter->signAt($polynomial, $middleRational);

        return $lowerSign >= 0 && $upperSign >= 0 && $middleSign >= 0;
    }

    /**
     * Search either side of zero independently so each floating-point span is
     * finite, then verify numerator roots against the original equation.
     *
     * @param list<float> $coefficients
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>
     */
    private function solveWideIntervalPolynomialRoots(
        array $coefficients,
        string $equation,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        if ($coefficients === []) {
            throw new \InvalidArgumentException('A polynomial requires at least one coefficient.');
        }
        $leadingMagnitude = \abs($coefficients[\array_key_last($coefficients)]);
        if ($leadingMagnitude === 0.0) {
            throw new \InvalidArgumentException('The polynomial leading coefficient is zero.');
        }
        $degree = \count($coefficients) - 1;
        $maximumRootMagnitude = 0.0;
        foreach ($coefficients as $index => $coefficient) {
            if ($index === $degree || $coefficient === 0.0) {
                continue;
            }

            $logCoefficientMagnitude = \log(\abs($coefficient));
            $logLeadingMagnitude = \log($leadingMagnitude);
            $exponentGap = $degree - $index;
            $logRootBound = \log(2.0)
                + (($logCoefficientMagnitude - $logLeadingMagnitude) / $exponentGap);
            $logRootBound += (
                32.0 * \PHP_FLOAT_EPSILON
                * (1.0 + \abs($logCoefficientMagnitude) + \abs($logLeadingMagnitude))
                / $exponentGap
            ) + \log1p(16.0 * \PHP_FLOAT_EPSILON * $degree);
            if (!\is_finite($logRootBound) || $logRootBound > \log(\PHP_FLOAT_MAX)) {
                $maximumRootMagnitude = \INF;
                break;
            }

            $rootBound = \exp($logRootBound);
            if ($rootBound === 0.0) {
                $rootBound = $this->adjacentFloat(0.0, 1) ?? \PHP_FLOAT_MIN;
            }
            if (\is_finite($rootBound)) {
                $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
            } else {
                $rootBound = \INF;
            }
            $maximumRootMagnitude = \max($maximumRootMagnitude, $rootBound);
        }
        $intervalMagnitude = \max(\abs($lowerBound), \abs($upperBound));
        $rootBound = \min($intervalMagnitude, $maximumRootMagnitude);
        if (!\is_finite($rootBound)) {
            $rootBound = \PHP_FLOAT_MAX;
        }
        $searchLowerBound = \max($lowerBound, -$rootBound);
        $searchUpperBound = \min($upperBound, $rootBound);
        if ($searchLowerBound > $searchUpperBound) {
            return [];
        }

        $solutions = [];
        $segments = \is_finite($searchUpperBound - $searchLowerBound)
            ? [[$searchLowerBound, $searchUpperBound]]
            : [[$searchLowerBound, 0.0], [0.0, $searchUpperBound]];
        foreach ($segments as [$segmentLower, $segmentUpper]) {
            foreach (
                $this->solve(
                    $equation,
                    $variable,
                    $segmentLower,
                    $segmentUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                ) as $candidate
            ) {
                $alreadyIncluded = false;
                foreach ($solutions as $solution) {
                    if ($solution->value === $candidate->value) {
                        $alreadyIncluded = true;
                        break;
                    }
                }
                if (!$alreadyIncluded) {
                    $solutions[] = $candidate;
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int => $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function isRoundoffZero(float $residual, float $scale): bool
    {
        return $scale === 0.0
            ? $residual === 0.0
            : \abs($residual) <= 8.0 * \PHP_FLOAT_EPSILON * $scale;
    }

    /**
     * @param array<string, int|float> $variables
     */
    private function evaluateNode(
        Node $node,
        array $variables,
        EvaluationOptions $options,
        float $factorialRoundingUlps = 4.0,
        float $moduloRoundingUlps = 0.0,
    ): int|float {
        return (new Evaluator(
            new Environment($variables, $options->functions),
            $options->limits,
            factorialRoundingUlps: $factorialRoundingUlps,
            moduloRoundingUlps: $moduloRoundingUlps,
        ))->evaluate($node);
    }

    private function handleEvaluationError(
        EvaluationException $error,
        int $offset,
    ): null {
        if ($this->mustPropagateEvaluationError($error)) {
            throw $this->shiftException($error, $offset);
        }

        return null;
    }

    /**
     * @return list<float>|null
     */
    private function extractPolynomial(
        PolynomialExtractor $extractor,
        Node $node,
        int $offset,
    ): ?array {
        try {
            return $extractor->extract($node);
        } catch (EvaluationException $error) {
            if ($this->mustPropagateEvaluationError($error)) {
                throw $this->shiftException($error, $offset);
            }

            return null;
        }
    }

    /**
     * Reduce logarithms of positive-base powers to polynomial exponents.
     *
     * @return list<float>|null
     */
    private function extractMatchingLogarithmExponent(
        FunctionCallNode $logarithm,
        float $base,
        PolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        if (!\is_finite($base) || $base <= 0.0 || $base === 1.0) {
            return null;
        }

        return $this->extractLogarithmPowerExponent(
            $logarithm->arguments[0],
            $base,
            $extractor,
            $maxDegree,
        );
    }

    /**
     * @return list<float>|null
     */
    private function extractLogarithmPowerExponent(
        Node $value,
        float $base,
        PolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $value = $this->unwrapGrouping($value);
        $constant = $this->extractPolynomial(
            $extractor,
            $value,
            $value->span()->start,
        );
        if ($constant !== null && \count($constant) === 1) {
            return $constant[0] > 0.0
                ? [\log($constant[0], $base)]
                : null;
        }
        if (
            $value instanceof FunctionCallNode
            && $value->name === 'exp'
            && \count($value->arguments) === 1
        ) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $value->arguments[0],
                $value->arguments[0]->span()->start,
            );

            return $exponent === null
                ? null
                : $this->scalePolynomialCoefficients($exponent, \log(\M_E, $base));
        }
        if (!$value instanceof BinaryOperationNode) {
            return null;
        }

        if (
            $value->operator === BinaryOperator::Multiply
            || $value->operator === BinaryOperator::Divide
        ) {
            $left = $this->extractLogarithmPowerExponent(
                $value->left,
                $base,
                $extractor,
                $maxDegree,
            );
            $right = $this->extractLogarithmPowerExponent(
                $value->right,
                $base,
                $extractor,
                $maxDegree,
            );
            if ($left === null || $right === null) {
                return null;
            }

            return $this->combinePolynomialCoefficients(
                $left,
                $right,
                $value->operator === BinaryOperator::Multiply ? 1.0 : -1.0,
            );
        }
        if ($value->operator !== BinaryOperator::Power) {
            return null;
        }

        $powerBase = $this->extractPolynomial(
            $extractor,
            $value->left,
            $value->left->span()->start,
        );
        if ($powerBase !== null && \count($powerBase) === 1 && $powerBase[0] > 0.0) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $value->right,
                $value->right->span()->start,
            );

            return $exponent === null
                ? null
                : $this->scalePolynomialCoefficients(
                    $exponent,
                    \log($powerBase[0], $base),
                );
        }

        $innerExponent = $this->extractLogarithmPowerExponent(
            $value->left,
            $base,
            $extractor,
            $maxDegree,
        );
        $outerExponent = $this->extractPolynomial(
            $extractor,
            $value->right,
            $value->right->span()->start,
        );
        if ($innerExponent === null || $outerExponent === null) {
            return null;
        }

        return $this->multiplyPolynomialCoefficients(
            $innerExponent,
            $outerExponent,
            $maxDegree,
        );
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>|null
     */
    private function combinePolynomialCoefficients(
        array $left,
        array $right,
        float $rightScale,
    ): ?array {
        $length = \max(\count($left), \count($right));
        $combined = [];
        for ($degree = 0; $degree < $length; ++$degree) {
            $coefficient = ($left[$degree] ?? 0.0)
                + ($rightScale * ($right[$degree] ?? 0.0));
            if (!\is_finite($coefficient)) {
                return null;
            }
            $combined[] = $coefficient;
        }

        while (\count($combined) > 1 && $combined[\array_key_last($combined)] === 0.0) {
            \array_pop($combined);
        }

        return $combined;
    }

    /**
     * @param list<float> $coefficients
     * @return list<float>|null
     */
    private function scalePolynomialCoefficients(array $coefficients, float $factor): ?array
    {
        $scaled = [];
        foreach ($coefficients as $coefficient) {
            $value = $coefficient * $factor;
            if (!\is_finite($value)) {
                return null;
            }
            $scaled[] = $value;
        }

        return $scaled;
    }

    /** @return array{list<float>, list<float>}|null */
    private function extractAbsolutePolynomial(
        Node $node,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): ?array {
        $form = $extractor->extractRationalForm($node);
        if ($form === null || $form[1] === [0.0]) {
            return null;
        }
        $cancelledRoots = [];
        while (\count($form[1]) > 1) {
            $roots = $this->solvePolynomialRootsInInterval(
                $form[1],
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($roots === null) {
                return null;
            }
            $cancelled = false;
            foreach ($roots as $root) {
                $numerator = $this->dividePolynomialByLinearFactor($form[0], $root->value);
                $denominator = $this->dividePolynomialByLinearFactor($form[1], $root->value);
                if ($numerator !== null && $denominator !== null) {
                    $form = [$numerator, $denominator];
                    if ($root->value > $lowerBound && $root->value < $upperBound) {
                        $cancelledRoots[] = $root->value;
                    }
                    $cancelled = true;
                    break;
                }
            }
            if (!$cancelled) {
                return null;
            }
        }

        if ($form[1][0] === 0.0) {
            return null;
        }
        $polynomial = $this->scalePolynomialCoefficients($form[0], 1.0 / $form[1][0]);

        return $polynomial === null ? null : [$polynomial, $cancelledRoots];
    }

    /**
     * @return array{list<float>, list<float>}|null
     */
    private function rationalRootRadicandForm(
        Node $baseNode,
        PolynomialExtractor $extractor,
        float $sample,
    ): ?array {
        $baseNode = $this->unwrapGrouping($baseNode);
        if (
            !$baseNode instanceof FunctionCallNode
            || $baseNode->name !== 'abs'
            || \count($baseNode->arguments) !== 1
        ) {
            return $extractor->extractRationalForm($baseNode);
        }

        $form = $extractor->extractRationalForm($baseNode->arguments[0]);
        if ($form === null) {
            return null;
        }
        $polynomialSolver = new PolynomialSolver();
        $numerator = $polynomialSolver->evaluatePolynomial($form[0], $sample);
        $denominator = $polynomialSolver->evaluatePolynomial($form[1], $sample);
        if ($numerator === null || $denominator === null || $denominator === 0.0) {
            return null;
        }
        if (($numerator < 0.0) !== ($denominator < 0.0)) {
            $form[0] = $this->scalePolynomialCoefficients($form[0], -1.0);
            if ($form[0] === null) {
                return null;
            }
        }

        return $form;
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>|null
     */
    private function multiplyPolynomialCoefficients(
        array $left,
        array $right,
        int $maxDegree,
    ): ?array {
        $degree = \count($left) + \count($right) - 2;
        if ($degree > $maxDegree) {
            return null;
        }

        $product = [];
        for ($index = 0; $index <= $degree; ++$index) {
            $product[] = 0.0;
        }
        foreach ($left as $leftDegree => $leftCoefficient) {
            foreach ($right as $rightDegree => $rightCoefficient) {
                $index = $leftDegree + $rightDegree;
                $product[$index] += $leftCoefficient * $rightCoefficient;
                if (!\is_finite($product[$index])) {
                    return null;
                }
            }
        }

        while (\count($product) > 1 && $product[\array_key_last($product)] === 0.0) {
            \array_pop($product);
        }

        return \array_values($product);
    }

    /**
     * Solve exact sine/cosine contact identities without evaluating a
     * cancellation-dominated residual near their polynomial-phase roots.
     *
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solveTrigonometricContactIdentity(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $tangentAffineSolutions = $this->solveTangentAgainstAffineEquation(
            $left,
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($tangentAffineSolutions !== null) {
            return $tangentAffineSolutions;
        }

        $tangentTaylorSolutions = $this->solveTangentTaylorContactEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($tangentTaylorSolutions !== null) {
            return $tangentTaylorSolutions;
        }

        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $phase = null;
        $function = null;
        $functionSign = 0.0;
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $node = $this->unwrapGrouping($node);
            if (
                $node instanceof FunctionCallNode
                && \in_array($node->name, ['sin', 'cos'], true)
                && \count($node->arguments) === 1
            ) {
                if ($phase !== null) {
                    return null;
                }
                $phase = $this->extractPolynomial(
                    $extractor,
                    $node->arguments[0],
                    $node->arguments[0]->span()->start,
                );
                if ($phase === null) {
                    return null;
                }
                $function = $node->name;
                $functionSign = $sign;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($phase === null || $function === null || \abs($functionSign) !== 1.0) {
            return null;
        }

        $target = $this->scalePolynomialCoefficients($remainder, -1.0 / $functionSign);
        if ($target === null) {
            return null;
        }
        if ($function === 'sin') {
            if ($target !== $phase) {
                return null;
            }
        } else {
            $phaseSquared = $this->multiplyPolynomialCoefficients(
                $phase,
                $phase,
                $solverOptions->maxPolynomialDegree,
            );
            $expected = $phaseSquared === null
                ? null
                : $this->combinePolynomialCoefficients([1.0], $phaseSquared, -0.5);
            if ($expected === null || $target !== $expected) {
                return null;
            }
        }

        if ($phase === [0.0]) {
            throw new InfiniteSolutionSetException(
                'The trigonometric contact identity holds for every real value.',
            );
        }
        if (\count($phase) === 1) {
            return [];
        }
        $candidates = $this->solvePolynomialRootsInInterval(
            $phase,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Isolate a tangent's cubic Taylor contact when its fourth derivative has
     * constant sign throughout the requested phase interval.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveTangentTaylorContactEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $function = $this->unwrapGrouping($functionSide);
            if (
                !$function instanceof FunctionCallNode
                || $function->name !== 'tan'
                || \count($function->arguments) !== 1
            ) {
                continue;
            }
            $phase = $extractor->extract($function->arguments[0]);
            if ($phase === null || \count($phase) !== 2 || $phase[1] === 0.0) {
                continue;
            }
            $center = -$phase[0] / $phase[1];
            $phaseScale = 1.0 / $phase[1];
            if (!\is_finite($center) || !\is_finite($phaseScale)) {
                continue;
            }
            $target = $extractor->extractInAffineCoordinate(
                $targetSide,
                $center,
                $phaseScale,
            );
            if (
                $target === null
                || \count($target) !== 4
                || !\is_finite($target[0])
                || !\is_finite($target[1])
                || !\is_finite($target[2])
                || !\is_finite($target[3])
                || $target[3] <= (1.0 / 3.0)
            ) {
                continue;
            }

            $tangentSquared = (-4.0 + \sqrt(4.0 + (36.0 * $target[3]))) / 6.0;
            if (!\is_finite($tangentSquared) || $tangentSquared < 0.0) {
                continue;
            }
            $matched = null;
            foreach ([\sqrt($tangentSquared), -\sqrt($tangentSquared)] as $tangent) {
                $candidateCenter = (
                    ($tangent * (1.0 + $tangentSquared)) - $target[2]
                ) / (3.0 * $target[3]);
                if (!\is_finite($candidateCenter)) {
                    continue;
                }
                $candidateTangent = \tan($candidateCenter);
                if (
                    !\is_finite($candidateTangent)
                    || \abs($candidateTangent - $tangent)
                        > 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($tangent))
                ) {
                    continue;
                }

                $square = 1.0 + ($tangent * $tangent);
                $cubic = $target[3];
                $expected = [
                    $tangent
                        - ($candidateCenter * $square)
                        + (($candidateCenter ** 2) * $tangent * $square)
                        - (($candidateCenter ** 3) * $cubic),
                    $square
                        - (2.0 * $candidateCenter * $tangent * $square)
                        + (3.0 * ($candidateCenter ** 2) * $cubic),
                    ($tangent * $square) - (3.0 * $candidateCenter * $cubic),
                    $cubic,
                ];
                $coefficientsMatch = true;
                foreach ($expected as $degree => $coefficient) {
                    if (
                        !\is_finite($coefficient)
                        || \abs($target[$degree] - $coefficient)
                            > 64.0 * \PHP_FLOAT_EPSILON
                                * \max(1.0, \abs($target[$degree]), \abs($coefficient))
                    ) {
                        $coefficientsMatch = false;
                        break;
                    }
                }
                if ($coefficientsMatch) {
                    $matched = $candidateCenter;
                    break;
                }
            }
            if ($matched === null) {
                continue;
            }

            $phaseAtLower = $phase[0] + ($phase[1] * $lowerBound);
            $phaseAtUpper = $phase[0] + ($phase[1] * $upperBound);
            if (!\is_finite($phaseAtLower) || !\is_finite($phaseAtUpper)) {
                continue;
            }
            $minimumPhase = \min($phaseAtLower, $phaseAtUpper);
            $maximumPhase = \max($phaseAtLower, $phaseAtUpper);
            if (
                $minimumPhase <= 0.0 && $maximumPhase >= 0.0
                || (int) \floor($minimumPhase / \M_PI) !== (int) \floor($maximumPhase / \M_PI)
                || (int) \floor(($minimumPhase + (\M_PI / 2.0)) / \M_PI)
                    !== (int) \floor(($maximumPhase + (\M_PI / 2.0)) / \M_PI)
            ) {
                continue;
            }

            $root = ($matched - $phase[0]) / $phase[1];
            if (!\is_finite($root) || $root < $lowerBound || $root > $upperBound) {
                return [];
            }
            $residual = $residualAt($root);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($root, $residual, $candidateScaleAt, $options)
            ) {
                return null;
            }

            return [new EquationSolution($root, \abs($residual), 0)];
        }

        return null;
    }

    /**
     * Isolate tan(affine) against an affine target by partitioning its poles
     * and all critical points of the residual.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveTangentAgainstAffineEquation(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound) || $lowerBound >= $upperBound) {
            return null;
        }
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $function = $this->unwrapGrouping($functionSide);
            if (
                !$function instanceof FunctionCallNode
                || $function->name !== 'tan'
                || \count($function->arguments) !== 1
            ) {
                continue;
            }
            $phase = $extractor->extract($function->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                $phase === null
                || \count($phase) !== 2
                || $target === null
                || \count($target) !== 2
                || $phase[1] === 0.0
                || !\is_finite($phase[0])
                || !\is_finite($phase[1])
                || !\is_finite($target[0])
                || !\is_finite($target[1])
            ) {
                continue;
            }

            $phaseAtLower = $phase[0] + ($phase[1] * $lowerBound);
            $phaseAtUpper = $phase[0] + ($phase[1] * $upperBound);
            if (!\is_finite($phaseAtLower) || !\is_finite($phaseAtUpper)) {
                continue;
            }
            $phaseMinimum = \min($phaseAtLower, $phaseAtUpper);
            $phaseMaximum = \max($phaseAtLower, $phaseAtUpper);
            $firstPoleIndex = (int) \ceil(($phaseMinimum - (\M_PI / 2.0)) / \M_PI);
            $lastPoleIndex = (int) \floor(($phaseMaximum - (\M_PI / 2.0)) / \M_PI);
            if ($lastPoleIndex - $firstPoleIndex > 4096) {
                return null;
            }

            /** @var list<array{value: float, pole: bool}> $cuts */
            $cuts = [
                ['value' => $lowerBound, 'pole' => false],
                ['value' => $upperBound, 'pole' => false],
            ];
            for ($poleIndex = $firstPoleIndex; $poleIndex <= $lastPoleIndex; ++$poleIndex) {
                $poleValue = ((float) $poleIndex * \M_PI) + (\M_PI / 2.0);
                $position = ($poleValue - $phase[0]) / $phase[1];
                if ($position >= $lowerBound && $position <= $upperBound) {
                    $cuts[] = ['value' => $position, 'pole' => true];
                }
            }

            $criticalRatio = $phase[1] / $target[1];
            if (\is_finite($criticalRatio) && $criticalRatio > 0.0 && $criticalRatio < 1.0) {
                $criticalOffset = \acos(\sqrt($criticalRatio));
                $firstPeriod = (int) \floor($phaseMinimum / \M_PI) - 1;
                $lastPeriod = (int) \ceil($phaseMaximum / \M_PI) + 1;
                if ($lastPeriod - $firstPeriod > 4096) {
                    return null;
                }
                for ($period = $firstPeriod; $period <= $lastPeriod; ++$period) {
                    foreach ([
                        ((float) $period * \M_PI) - $criticalOffset,
                        ((float) $period * \M_PI) + $criticalOffset,
                    ] as $criticalPhase) {
                        if ($criticalPhase <= $phaseMinimum || $criticalPhase >= $phaseMaximum) {
                            continue;
                        }
                        $position = ($criticalPhase - $phase[0]) / $phase[1];
                        if ($position > $lowerBound && $position < $upperBound) {
                            $cuts[] = ['value' => $position, 'pole' => false];
                        }
                    }
                }
            }

            \usort(
                $cuts,
                static fn (array $first, array $second): int => $first['value'] <=> $second['value'],
            );
            $orderedCuts = [];
            foreach ($cuts as $cut) {
                $last = \array_key_last($orderedCuts);
                if ($last !== null && $orderedCuts[$last]['value'] === $cut['value']) {
                    $orderedCuts[$last]['pole'] = $orderedCuts[$last]['pole'] || $cut['pole'];
                } else {
                    $orderedCuts[] = $cut;
                }
            }

            $solutions = [];
            $boundarySample = function (array $cut, int $direction) use (
                $residualAt,
                $lowerBound,
                $upperBound,
            ): ?array {
                $position = $cut['value'];
                if ($cut['pole']) {
                    for ($step = 0; $step < 4096; ++$step) {
                        $next = $this->adjacentFloat($position, $direction);
                        if ($next === null || $next < $lowerBound || $next > $upperBound) {
                            return null;
                        }
                        $position = $next;
                        $residual = $residualAt($position);
                        if ($residual !== null && \is_finite($residual)) {
                            return [$position, $residual];
                        }
                    }

                    return null;
                }
                $residual = $residualAt($position);

                return $residual === null || !\is_finite($residual)
                    ? null
                    : [$position, $residual];
            };

            foreach ($orderedCuts as $index => $cut) {
                if ($cut['pole']) {
                    continue;
                }
                $sample = $boundarySample($cut, $index === 0 ? 1 : -1);
                if ($sample === null) {
                    continue;
                }
                [$position, $residual] = $sample;
                if (
                    $this->isResidualAcceptableAt($position, $residual, $candidateScaleAt, $options)
                ) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($position, \abs($residual), 0),
                        $options,
                    );
                }
            }

            for ($index = 0, $last = \count($orderedCuts) - 1; $index < $last; ++$index) {
                $lowerCut = $orderedCuts[$index];
                $upperCut = $orderedCuts[$index + 1];
                $lowerSample = $boundarySample($lowerCut, 1);
                $upperSample = $boundarySample($upperCut, -1);
                if ($lowerSample === null || $upperSample === null) {
                    return null;
                }
                [$segmentLower, $lowerResidual] = $lowerSample;
                [$segmentUpper, $upperResidual] = $upperSample;
                if ($segmentLower >= $segmentUpper) {
                    continue;
                }
                if (!$this->hasOppositeSigns($lowerResidual, $upperResidual)) {
                    continue;
                }
                foreach ($this->bisect(
                    $residualAt,
                    $segmentLower,
                    $lowerResidual,
                    $segmentUpper,
                    $options,
                    $candidateScaleAt,
                    static fn (float $_): bool => false,
                ) as $root) {
                    $this->addSolution($solutions, $root, $options);
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Classify rational-amplitude trigonometric terms on unbounded intervals.
     *
     * @param array<string, int|float> $parameters
     */
    private function classifyUnboundedRationalAmplitudeTrigonometricEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): void {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return;
        }

        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        /** @return array{bool, int, array{string, string}}|null */
        $rationalGrowth = function (Node $node) use ($exactExtractor): ?array {
            $form = $exactExtractor->rationalFunction($node);
            if ($form === null || $form[1] === []) {
                return null;
            }

            $numeratorIsZero = true;
            foreach ($form[0] as [$coefficient]) {
                if ($coefficient !== '0') {
                    $numeratorIsZero = false;
                    break;
                }
            }
            if ($numeratorIsZero) {
                return [true, 0, ['0', '1']];
            }

            $numeratorDegree = \count($form[0]) - 1;
            while ($numeratorDegree > 0 && $form[0][$numeratorDegree][0] === '0') {
                --$numeratorDegree;
            }
            $denominatorDegree = \count($form[1]) - 1;
            while ($denominatorDegree > 0 && $form[1][$denominatorDegree][0] === '0') {
                --$denominatorDegree;
            }
            $inverseLeadingDenominator = $exactExtractor->powerExactFraction(
                $form[1][$denominatorDegree],
                -1,
            );
            $leadingCoefficient = $inverseLeadingDenominator === null
                ? null
                : $exactExtractor->multiplyExactFractions(
                    $form[0][$numeratorDegree],
                    $inverseLeadingDenominator,
                );
            if ($leadingCoefficient === null) {
                return null;
            }

            return [false, $numeratorDegree - $denominatorDegree, $leadingCoefficient];
        };
        /** @return array{int, array{string, string}}|null */
        $sinusoidAmplitudeGrowth = function (Node $term) use (
            $exactExtractor,
            $evaluationOptions,
            $rationalGrowth,
        ): ?array {
            $trigonometricFactorFound = false;
            $degree = 0;
            $leadingCoefficient = ['1', '1'];
            foreach ($this->multiplicativeFactors($term) as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                    && \in_array($factor->name, ['sin', 'cos'], true)
                    && \count($factor->arguments) === 1
                ) {
                    if ($trigonometricFactorFound) {
                        return null;
                    }
                    $phaseGrowth = $rationalGrowth($factor->arguments[0]);
                    if ($phaseGrowth === null || $phaseGrowth[0] || $phaseGrowth[1] <= 0) {
                        return null;
                    }
                    $trigonometricFactorFound = true;
                    continue;
                }

                $growth = $rationalGrowth($factor);
                if ($growth === null || $growth[0]) {
                    return null;
                }
                $degree += $growth[1];
                $leadingCoefficient = $exactExtractor->multiplyExactFractions(
                    $leadingCoefficient,
                    $growth[2],
                );
                if ($leadingCoefficient === null) {
                    return null;
                }
            }

            return $trigonometricFactorFound ? [$degree, $leadingCoefficient] : null;
        };
        /** @return array{int, array{string, string}}|null */
        $reciprocalTrigonometricAmplitude = function (Node $term) use (
            $exactExtractor,
            $evaluationOptions,
            $rationalGrowth,
        ): ?array {
            $trigonometricFactorFound = false;
            $degree = 0;
            $leadingCoefficient = ['1', '1'];
            foreach ($this->multiplicativeFactors($term) as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                    && \in_array($factor->name, ['sec', 'csc'], true)
                    && \count($factor->arguments) === 1
                ) {
                    if ($trigonometricFactorFound) {
                        return null;
                    }
                    $phaseGrowth = $rationalGrowth($factor->arguments[0]);
                    if ($phaseGrowth === null || $phaseGrowth[0] || $phaseGrowth[1] <= 0) {
                        return null;
                    }
                    $trigonometricFactorFound = true;
                    continue;
                }

                $growth = $rationalGrowth($factor);
                if ($growth === null || $growth[0]) {
                    return null;
                }
                $degree += $growth[1];
                $leadingCoefficient = $exactExtractor->multiplyExactFractions(
                    $leadingCoefficient,
                    $growth[2],
                );
                if ($leadingCoefficient === null) {
                    return null;
                }
            }

            return $trigonometricFactorFound ? [$degree, $leadingCoefficient] : null;
        };
        $isSubdominantTerm = function (Node $term, int $dominantDegree) use (
            $rationalGrowth,
            $evaluationOptions,
        ): bool {
            $degree = 0;
            $zeroFactorFound = false;
            foreach ($this->multiplicativeFactors($term) as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                    && \in_array($factor->name, ['sin', 'cos'], true)
                    && \count($factor->arguments) === 1
                ) {
                    if ($rationalGrowth($factor->arguments[0]) === null) {
                        return false;
                    }
                    continue;
                }
                $growth = $rationalGrowth($factor);
                if ($growth === null) {
                    return false;
                }
                if ($growth[0]) {
                    $zeroFactorFound = true;
                    continue;
                }
                $degree += $growth[1];
            }

            return $zeroFactorFound || $degree < $dominantDegree;
        };
        $terms = [...$this->additiveTerms($left), ...$this->additiveTerms($right, -1)];
        $hasUnboundedPoleTerm = function (Node $term) use (
            $evaluationOptions,
            $rationalGrowth,
        ): bool {
            $poleFactorFound = false;
            foreach ($this->multiplicativeFactors($term) as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                    && \in_array($factor->name, ['tan', 'cot'], true)
                    && \count($factor->arguments) === 1
                ) {
                    if ($poleFactorFound) {
                        return false;
                    }
                    $phaseGrowth = $rationalGrowth($factor->arguments[0]);
                    if ($phaseGrowth === null || $phaseGrowth[0] || $phaseGrowth[1] <= 0) {
                        return false;
                    }
                    $poleFactorFound = true;
                    continue;
                }
                $growth = $rationalGrowth($factor);
                if ($growth === null || $growth[0]) {
                    return false;
                }
            }

            return $poleFactorFound;
        };
        $isContinuousOnUnboundedTail = function (Node $term) use (
            $rationalGrowth,
            $evaluationOptions,
        ): bool {
            foreach ($this->multiplicativeFactors($term) as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                    && \in_array($factor->name, ['sin', 'cos'], true)
                    && \count($factor->arguments) === 1
                ) {
                    if ($rationalGrowth($factor->arguments[0]) === null) {
                        return false;
                    }
                    continue;
                }
                if ($rationalGrowth($factor) === null) {
                    return false;
                }
            }

            return true;
        };
        foreach ($terms as $candidateIndex => [$candidate]) {
            if (!$hasUnboundedPoleTerm($candidate)) {
                continue;
            }
            foreach ($terms as $index => [$term]) {
                if ($index !== $candidateIndex && !$isContinuousOnUnboundedTail($term)) {
                    continue 2;
                }
            }

            throw new InfiniteSolutionSetException(
                'A rational-amplitude tangent or cotangent has infinitely many branches crossing zero on the unbounded interval.',
            );
        }

        foreach ($terms as $candidateIndex => [$candidate, $candidateSign]) {
            $candidateGrowth = $reciprocalTrigonometricAmplitude($candidate);
            if ($candidateGrowth === null) {
                continue;
            }
            [$degree, $amplitudeLeadingCoefficient] = $candidateGrowth;
            $sameOrderRationalCoefficient = null;
            $rationalRemainderNode = null;
            $rationalRemainderSupported = true;
            foreach ($terms as $index => [$term, $termSign]) {
                if ($index === $candidateIndex) {
                    continue;
                }
                $growth = $rationalGrowth($term);
                if ($growth === null) {
                    $rationalRemainderSupported = false;
                } else {
                    $signedTerm = $termSign < 0
                        ? new UnaryOperationNode(UnaryOperator::Minus, $term, $term->span())
                        : $term;
                    $rationalRemainderNode = $rationalRemainderNode === null
                        ? $signedTerm
                        : new BinaryOperationNode(
                            BinaryOperator::Add,
                            $rationalRemainderNode,
                            $signedTerm,
                            $rationalRemainderNode->span()->cover($signedTerm->span()),
                        );
                }
                if ($isSubdominantTerm($term, $degree)) {
                    continue;
                }
                if ($growth === null || $growth[0] || $growth[1] !== $degree) {
                    continue 2;
                }
                $signedCoefficient = $termSign < 0
                    ? $exactExtractor->powerExactFraction($growth[2], -1)
                    : $growth[2];
                if ($signedCoefficient === null) {
                    continue 2;
                }
                $sameOrderRationalCoefficient = $sameOrderRationalCoefficient === null
                    ? $signedCoefficient
                    : $exactExtractor->addExactFractions(
                        $sameOrderRationalCoefficient,
                        $signedCoefficient,
                    );
                if ($sameOrderRationalCoefficient === null) {
                    continue 2;
                }
            }
            if ($sameOrderRationalCoefficient === null) {
                continue;
            }
            $inverseAmplitude = $exactExtractor->powerExactFraction($amplitudeLeadingCoefficient, -1);
            $ratio = $inverseAmplitude === null
                ? null
                : $exactExtractor->multiplyExactFractions($sameOrderRationalCoefficient, $inverseAmplitude);
            if ($ratio === null) {
                continue;
            }
            $ratioMagnitudeComparison = (new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree))
                ->compareIntegerValues(\ltrim($ratio[0], '-'), \ltrim($ratio[1], '-'));
            if ($ratioMagnitudeComparison > 0) {
                throw new InfiniteSolutionSetException(
                    'A rational-amplitude secant or cosecant crosses its same-order rational offset on infinitely many pole branches.',
                );
            }
            if ($ratioMagnitudeComparison === 0 && $rationalRemainderSupported) {
                $amplitudeNode = $this->rationalAmplitudeNode(
                    $candidate,
                    ['sec', 'csc'],
                    $evaluationOptions,
                );
                $exactRatio = $rationalRemainderNode === null || $amplitudeNode === null
                    ? null
                    : $exactExtractor->rationalFunctionRatio($rationalRemainderNode, $amplitudeNode);
                if (
                    \is_array($exactRatio)
                    && (new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree))
                        ->compareIntegerValues(\ltrim($exactRatio[0], '-'), \ltrim($exactRatio[1], '-')) === 0
                ) {
                    throw new InfiniteSolutionSetException(
                        'An exact same-magnitude rational offset meets infinitely many secant or cosecant extrema.',
                    );
                }
                $targetNode = $rationalRemainderNode === null || $amplitudeNode === null
                    ? null
                    : new BinaryOperationNode(
                        BinaryOperator::Divide,
                        $rationalRemainderNode,
                        $amplitudeNode,
                        $candidate->span(),
                    );
                if ($targetNode !== null && $candidateSign > 0) {
                    $targetNode = new UnaryOperationNode(
                        UnaryOperator::Minus,
                        $targetNode,
                        $targetNode->span(),
                    );
                }
                $targetGrowth = $targetNode === null ? null : $rationalGrowth($targetNode);
                if ($targetGrowth !== null && !$targetGrowth[0] && $targetGrowth[1] === 0) {
                    $integerArithmetic = new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree);
                    $limitSign = $integerArithmetic->compareIntegerRatioToFraction(
                        $targetGrowth[2][0],
                        $targetGrowth[2][1],
                        '1',
                        '1',
                    ) === 0
                        ? 1
                        : ($integerArithmetic->compareIntegerRatioToFraction(
                            $targetGrowth[2][0],
                            $targetGrowth[2][1],
                            '-1',
                            '1',
                        ) === 0 ? -1 : 0);
                    if ($limitSign !== 0) {
                        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
                            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                                continue;
                            }
                            $differenceSign = $this->rationalFunctionDifferenceSignAtInfinity(
                                $exactExtractor,
                                $targetNode,
                                (float) $limitSign,
                                $direction,
                            );
                            if (
                                ($limitSign === 1 && $differenceSign === 1)
                                || ($limitSign === -1 && $differenceSign === -1)
                            ) {
                                throw new InfiniteSolutionSetException(
                        'A rational secant or cosecant target has infinitely many branches approaching a range boundary from outside on an unbounded tail.',
                                );
                            }
                        }
                    }
                }
            }

        }

        foreach ($terms as $candidateIndex => [$candidate, $candidateSign]) {
            $candidateGrowth = $sinusoidAmplitudeGrowth($candidate);
            if ($candidateGrowth === null) {
                continue;
            }
            [$degree, $amplitudeLeadingCoefficient] = $candidateGrowth;
            $sameOrderRationalCoefficient = null;
            $rationalRemainderNode = null;
            $rationalRemainderSupported = true;
            foreach ($terms as $index => [$term, $termSign]) {
                if ($index === $candidateIndex) {
                    continue;
                }
                $growth = $rationalGrowth($term);
                if ($growth === null) {
                    $rationalRemainderSupported = false;
                } else {
                    $signedTerm = $termSign < 0
                        ? new UnaryOperationNode(UnaryOperator::Minus, $term, $term->span())
                        : $term;
                    $rationalRemainderNode = $rationalRemainderNode === null
                        ? $signedTerm
                        : new BinaryOperationNode(
                            BinaryOperator::Add,
                            $rationalRemainderNode,
                            $signedTerm,
                            $rationalRemainderNode->span()->cover($signedTerm->span()),
                        );
                }
                if ($isSubdominantTerm($term, $degree)) {
                    continue;
                }
                if ($growth === null || $growth[0] || $growth[1] !== $degree) {
                    continue 2;
                }
                $signedCoefficient = $termSign < 0
                    ? $exactExtractor->powerExactFraction($growth[2], -1)
                    : $growth[2];
                if ($signedCoefficient === null) {
                    continue 2;
                }
                $sameOrderRationalCoefficient = $sameOrderRationalCoefficient === null
                    ? $signedCoefficient
                    : $exactExtractor->addExactFractions(
                        $sameOrderRationalCoefficient,
                        $signedCoefficient,
                    );
                if ($sameOrderRationalCoefficient === null) {
                    continue 2;
                }
            }
            if ($sameOrderRationalCoefficient !== null) {
                $inverseAmplitude = $exactExtractor->powerExactFraction($amplitudeLeadingCoefficient, -1);
                $ratio = $inverseAmplitude === null
                    ? null
                    : $exactExtractor->multiplyExactFractions($sameOrderRationalCoefficient, $inverseAmplitude);
                if ($ratio === null) {
                    continue;
                }
                $ratioMagnitudeComparison = (new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree))
                    ->compareIntegerValues(\ltrim($ratio[0], '-'), \ltrim($ratio[1], '-'));
                if ($ratioMagnitudeComparison > 0) {
                    return;
                }
                if ($ratioMagnitudeComparison === 0 && $rationalRemainderSupported) {
                    $amplitudeNode = $this->rationalAmplitudeNode(
                        $candidate,
                        ['sin', 'cos'],
                        $evaluationOptions,
                    );
                    $exactRatio = $rationalRemainderNode === null || $amplitudeNode === null
                        ? null
                        : $exactExtractor->rationalFunctionRatio($rationalRemainderNode, $amplitudeNode);
                    $integerArithmetic = new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree);
                    if (
                        \is_array($exactRatio)
                        && $integerArithmetic->compareIntegerValues(
                            \ltrim($exactRatio[0], '-'),
                            \ltrim($exactRatio[1], '-'),
                        ) === 0
                    ) {
                        throw new InfiniteSolutionSetException(
                            'An exact same-magnitude rational offset meets every extremum of an unbounded sinusoid phase.',
                        );
                    }
                    $targetNode = $rationalRemainderNode === null || $amplitudeNode === null
                        ? null
                        : new BinaryOperationNode(
                            BinaryOperator::Divide,
                            $rationalRemainderNode,
                            $amplitudeNode,
                            $candidate->span(),
                        );
                    if ($targetNode !== null && -$candidateSign < 0) {
                        $targetNode = new UnaryOperationNode(
                            UnaryOperator::Minus,
                            $targetNode,
                            $targetNode->span(),
                        );
                    }
                    $targetGrowth = $targetNode === null ? null : $rationalGrowth($targetNode);
                    if ($targetGrowth !== null && !$targetGrowth[0] && $targetGrowth[1] === 0) {
                        $limitSign = $integerArithmetic->compareIntegerRatioToFraction(
                            $targetGrowth[2][0],
                            $targetGrowth[2][1],
                            '1',
                            '1',
                        ) === 0
                            ? 1
                            : ($integerArithmetic->compareIntegerRatioToFraction(
                                $targetGrowth[2][0],
                                $targetGrowth[2][1],
                                '-1',
                                '1',
                            ) === 0 ? -1 : 0);
                        if ($limitSign !== 0) {
                            foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
                                if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                                    continue;
                                }
                                $differenceSign = $this->rationalFunctionDifferenceSignAtInfinity(
                                    $exactExtractor,
                                    $targetNode,
                                    (float) $limitSign,
                                    $direction,
                                );
                                if (
                                    ($limitSign === 1 && $differenceSign === -1)
                                    || ($limitSign === -1 && $differenceSign === 1)
                                ) {
                                    throw new InfiniteSolutionSetException(
                                        'A rational sinusoidal target has infinitely many roots while approaching a range boundary from inside on an unbounded tail.',
                                    );
                                }
                            }
                        }
                    }
                    continue;
                }
            }

            throw new InfiniteSolutionSetException(
                'A nonzero rational-amplitude sinusoid with an unbounded phase has infinitely many roots when its additive remainder is asymptotically smaller or its net same-order rational offset is strictly inside its amplitude envelope.',
            );
        }
    }

    /**
     * Find a repeated root witness for affine periodic equations with trigonometric poles.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     */
    private function hasInfiniteRootsFromPeriodicTrigonometricPoleEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
    ): bool {
        $polynomialExtractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $terms = [];
        if (
            !$this->collectPeriodicTrigonometricPhaseTerms(
                $left,
                $variable,
                $parameters,
                $evaluationOptions,
                $polynomialExtractor,
                $exactExtractor,
                $terms,
            )
            || !$this->collectPeriodicTrigonometricPhaseTerms(
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $polynomialExtractor,
                $exactExtractor,
                $terms,
            )
        ) {
            return false;
        }
        if ($terms === []) {
            return false;
        }
        $hasPoleFunction = false;
        $periodMultiplier = 1;
        foreach ($terms as $term) {
            if (\in_array($term['function'], ['tan', 'cot', 'sec', 'csc'], true)) {
                $hasPoleFunction = true;
            }
            $denominator = $term['frequencyDenominator'];
            $divisor = self::greatestCommonDivisor($periodMultiplier, $denominator);
            $factor = intdiv($denominator, $divisor);
            if ($factor < 1 || $periodMultiplier > \intdiv(4096, $factor)) {
                return false;
            }
            $periodMultiplier *= $factor;
        }
        if (!$hasPoleFunction || $periodMultiplier > 4096) {
            return false;
        }
        $period = \M_PI * $periodMultiplier;
        if (!\is_finite($period) || $period <= 0.0) {
            return false;
        }

        $boundaries = [0.0, $period];
        foreach ($terms as $term) {
            $function = $term['function'];
            if (!\in_array($function, ['tan', 'cot', 'sec', 'csc'], true)) {
                continue;
            }
            $offset = $term['offset'];
            $slope = $term['slope'];
            $endPhase = $offset + ($slope * $period);
            if (!\is_finite($endPhase)) {
                return false;
            }
            $minimumPhase = \min($offset, $endPhase);
            $maximumPhase = \max($offset, $endPhase);
            $poleOffset = \in_array($function, ['tan', 'sec'], true) ? \M_PI_2 : 0.0;
            $firstIndex = (int) \ceil(($minimumPhase - $poleOffset) / \M_PI);
            $lastIndex = (int) \floor(($maximumPhase - $poleOffset) / \M_PI);
            if ($lastIndex - $firstIndex > 8192) {
                return false;
            }
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $position = (($poleOffset + ($index * \M_PI)) - $offset) / $slope;
                if ($position > 0.0 && $position < $period && \is_finite($position)) {
                    $boundaries[] = $position;
                }
            }
        }
        \sort($boundaries, SORT_NUMERIC);
        $uniqueBoundaries = [];
        foreach ($boundaries as $boundary) {
            $previous = $uniqueBoundaries[\array_key_last($uniqueBoundaries)] ?? null;
            if (
                $previous === null
                || \abs($boundary - $previous)
                    > 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($boundary))
            ) {
                $uniqueBoundaries[] = $boundary;
            }
        }

        $probeFractions = [
            1.0E-6,
            1.0E-3,
            0.01,
            0.05,
            0.1,
            0.25,
            0.5,
            0.75,
            0.9,
            0.95,
            0.99,
            0.999,
            1.0 - 1.0E-6,
        ];
        for ($index = 0; $index + 1 < \count($uniqueBoundaries); ++$index) {
            $lower = $uniqueBoundaries[$index];
            $upper = $uniqueBoundaries[$index + 1];
            if ($lower >= $upper) {
                continue;
            }
            $previousResidual = null;
            foreach ($probeFractions as $fraction) {
                $position = $lower + (($upper - $lower) * $fraction);
                $residual = $residualAt($position);
                if ($residual === null || !\is_finite($residual)) {
                    continue;
                }
                if ($previousResidual !== null && $this->hasOppositeSigns($previousResidual, $residual)) {
                    return true;
                }
                $previousResidual = $residual;
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param list<array{function: string, offset: float, slope: float, frequencyDenominator: int}> $terms
     */
    private function collectPeriodicTrigonometricPhaseTerms(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        PolynomialExtractor $polynomialExtractor,
        ExactRationalPolynomialExtractor $exactExtractor,
        array &$terms,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if (!\in_array($node->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)) {
                return !$this->containsVariable($node, $variable)
                    && $this->constantNodeValue($node, $parameters, $evaluationOptions) !== null;
            }
            if (\count($node->arguments) !== 1) {
                return false;
            }
            $phase = $node->arguments[0];
            if (!$this->containsVariable($phase, $variable)) {
                return $this->constantNodeValue($node, $parameters, $evaluationOptions) !== null;
            }
            $phaseCoefficients = $polynomialExtractor->extract($phase);
            if ($phaseCoefficients === null) {
                return false;
            }
            while (
                \count($phaseCoefficients) > 1
                && $phaseCoefficients[\array_key_last($phaseCoefficients)] === 0.0
            ) {
                \array_pop($phaseCoefficients);
            }
            if (\count($phaseCoefficients) === 1) {
                return true;
            }
            if (\count($phaseCoefficients) !== 2 || $phaseCoefficients[1] === 0.0) {
                return false;
            }

            $nonconstantPhase = null;
            foreach ($this->additiveTerms($phase) as [$phaseTerm, $sign]) {
                if (!$this->containsVariable($phaseTerm, $variable)) {
                    continue;
                }
                $signedTerm = $sign < 0
                    ? new UnaryOperationNode(UnaryOperator::Minus, $phaseTerm, $phaseTerm->span())
                    : $phaseTerm;
                $nonconstantPhase = $nonconstantPhase === null
                    ? $signedTerm
                    : new BinaryOperationNode(
                        BinaryOperator::Add,
                        $nonconstantPhase,
                        $signedTerm,
                        $nonconstantPhase->span()->cover($signedTerm->span()),
                    );
            }
            if ($nonconstantPhase === null) {
                return false;
            }
            $exactCoefficients = $this->exactPolynomialCoefficients($nonconstantPhase, $exactExtractor);
            if ($exactCoefficients === null || \count($exactCoefficients) !== 2) {
                return false;
            }
            [$slopeNumerator, $slopeDenominator] = $exactCoefficients[1];
            if ($slopeNumerator === '0' || $slopeDenominator === '0') {
                return false;
            }
            $numerator = \abs((int) $slopeNumerator);
            $denominator = \abs((int) $slopeDenominator);
            if ($numerator < 1 || $numerator > 1_000_000 || $denominator < 1 || $denominator > 1_000_000) {
                return false;
            }
            if (!\in_array($node->name, ['tan', 'cot'], true)) {
                $denominator *= 2;
            }
            $divisor = self::greatestCommonDivisor($numerator, $denominator);
            $terms[] = [
                'function' => $node->name,
                'offset' => $phaseCoefficients[0],
                'slope' => $phaseCoefficients[1],
                'frequencyDenominator' => intdiv($denominator, $divisor),
            ];

            return true;
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->collectPeriodicTrigonometricPhaseTerms(
                $node->operand,
                $variable,
                $parameters,
                $evaluationOptions,
                $polynomialExtractor,
                $exactExtractor,
                $terms,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->collectPeriodicTrigonometricPhaseTerms(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $polynomialExtractor,
                    $exactExtractor,
                    $terms,
                )
                && $this->collectPeriodicTrigonometricPhaseTerms(
                    $node->right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $polynomialExtractor,
                    $exactExtractor,
                    $terms,
                );
        }

        return !$this->containsVariable($node, $variable)
            && $this->constantNodeValue($node, $parameters, $evaluationOptions) !== null;
    }

    /** @param array<string, int|float> $parameters */
    private function directTrigonometricConstantTargetIsOutOfRange(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        foreach ([[$left, $right], [$right, $left]] as [$function, $target]) {
            $function = $this->unwrapGrouping($function);
            if (
                !$function instanceof FunctionCallNode
                || !\in_array($function->name, ['sin', 'cos'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            $targetCoefficients = (new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
            ))->extract($target);
            if (
                $targetCoefficients !== null
                && \count($targetCoefficients) === 1
                && \abs($targetCoefficients[0]) > 1.0
            ) {
                return true;
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function directPolynomialTrigonometricRationalLimitIsOutsideRange(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $polynomialExtractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $integerArithmetic = new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree);
        foreach ([[$left, $right], [$right, $left]] as [$function, $target]) {
            $function = $this->unwrapGrouping($function);
            if (
                !$function instanceof FunctionCallNode
                || !\in_array($function->name, ['sin', 'cos'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            $phase = $polynomialExtractor->extract($function->arguments[0]);
            if ($phase === null || \count($phase) < 2) {
                continue;
            }
            $targetForm = $exactExtractor->rationalFunction($target);
            if ($targetForm === null) {
                continue;
            }
            [$numerator, $denominator] = $targetForm;
            while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
                \array_pop($numerator);
            }
            while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
                \array_pop($denominator);
            }
            $numeratorDegree = \array_key_last($numerator);
            $denominatorDegree = \array_key_last($denominator);
            if ($numeratorDegree > $denominatorDegree) {
                return true;
            }
            if ($numeratorDegree < $denominatorDegree) {
                continue;
            }
            $denominatorLeadingInverse = $exactExtractor->powerExactFraction(
                $denominator[$denominatorDegree],
                -1,
            );
            $limit = $denominatorLeadingInverse === null
                ? null
                : $exactExtractor->multiplyExactFractions(
                    $numerator[$numeratorDegree],
                    $denominatorLeadingInverse,
                );
            if (
                $limit !== null
                && $integerArithmetic->compareIntegerValues(
                    \ltrim($limit[0], '-'),
                    \ltrim($limit[1], '-'),
                ) > 0
            ) {
                return true;
            }
        }

        return false;
    }

    /** @return list<Node> */
    private function multiplicativeFactors(Node $node): array
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            return $this->multiplicativeFactors($node->operand);
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            return [...$this->multiplicativeFactors($node->left), ...$this->multiplicativeFactors($node->right)];
        }

        return [$node];
    }

    private function multiplicativeSign(Node $node): int
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $sign = $node->operator === UnaryOperator::Minus ? -1 : 1;

            return $sign * $this->multiplicativeSign($node->operand);
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            return $this->multiplicativeSign($node->left) * $this->multiplicativeSign($node->right);
        }

        return 1;
    }

    /**
     * @param list<string> $functions
     */
    private function rationalAmplitudeNode(
        Node $term,
        array $functions,
        EvaluationOptions $evaluationOptions,
    ): ?Node {
        $trigonometricFactorFound = false;
        $amplitudeFactors = [];
        foreach ($this->multiplicativeFactors($term) as $factor) {
            $factor = $this->unwrapGrouping($factor);
            if (
                $factor instanceof FunctionCallNode
                && $evaluationOptions->functions->isBuiltIn($factor->name)
                && \in_array($factor->name, $functions, true)
                && \count($factor->arguments) === 1
            ) {
                if ($trigonometricFactorFound) {
                    return null;
                }
                $trigonometricFactorFound = true;
                continue;
            }
            $amplitudeFactors[] = $factor;
        }
        if (!$trigonometricFactorFound) {
            return null;
        }
        if ($amplitudeFactors === []) {
            return new NumberNode(1, '1', $term->span());
        }

        $amplitude = \array_shift($amplitudeFactors);
        foreach ($amplitudeFactors as $factor) {
            $amplitude = new BinaryOperationNode(
                BinaryOperator::Multiply,
                $amplitude,
                $factor,
                $term->span(),
            );
        }

        return $this->multiplicativeSign($term) < 0
            ? new UnaryOperationNode(UnaryOperator::Minus, $amplitude, $term->span())
            : $amplitude;
    }

    /** @return list<array{Node, int}> */
    private function additiveTerms(Node $node, int $sign = 1): array
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            return $this->additiveTerms(
                $node->operand,
                $node->operator === UnaryOperator::Minus ? -$sign : $sign,
            );
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Add) {
            return [
                ...$this->additiveTerms($node->left, $sign),
                ...$this->additiveTerms($node->right, $sign),
            ];
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Subtract) {
            return [
                ...$this->additiveTerms($node->left, $sign),
                ...$this->additiveTerms($node->right, -$sign),
            ];
        }

        return [[$node, $sign]];
    }

    /**
     * Use the sine/cosine range to bound equations with one rational-amplitude term.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedRationalOffsetTrigonometricEquation(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $leftTerms = $this->additiveTerms($left);
        $rightTerms = $this->additiveTerms($right, -1);
        $terms = [...$leftTerms, ...$rightTerms];
        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $candidateIndex = null;
        $amplitude = null;
        foreach ($terms as $index => [$term]) {
            $candidateAmplitude = $this->rationalAmplitudeNode(
                $term,
                ['sin', 'cos'],
                $evaluationOptions,
            );
            if ($candidateAmplitude === null) {
                continue;
            }
            if (
                $candidateIndex !== null
                || $exactExtractor->rationalFunction($candidateAmplitude) === null
            ) {
                return null;
            }
            $candidateIndex = $index;
            $amplitude = $candidateAmplitude;
        }
        if (
            $candidateIndex === null
            || $amplitude === null
            || ($candidateIndex < \count($leftTerms) && \count($leftTerms) === 1)
            || ($candidateIndex >= \count($leftTerms) && \count($rightTerms) === 1)
        ) {
            return null;
        }

        $remainder = null;
        foreach ($terms as $index => [$term, $sign]) {
            if ($index === $candidateIndex) {
                continue;
            }
            if ($exactExtractor->rationalFunction($term) === null) {
                return null;
            }
            $signedTerm = $sign < 0
                ? new UnaryOperationNode(UnaryOperator::Minus, $term, $term->span())
                : $term;
            $remainder = $remainder === null
                ? $signedTerm
                : new BinaryOperationNode(
                    BinaryOperator::Add,
                    $remainder,
                    $signedTerm,
                    $remainder->span()->cover($signedTerm->span()),
                );
        }
        if ($remainder === null) {
            return null;
        }
        $remainderForm = $exactExtractor->rationalFunction($remainder);
        if ($remainderForm === null) {
            return null;
        }
        $remainderNumerator = $remainderForm[0];
        $remainderDenominator = $remainderForm[1];
        while (
            \count($remainderNumerator) > 1
            && $remainderNumerator[\array_key_last($remainderNumerator)][0] === '0'
        ) {
            \array_pop($remainderNumerator);
        }
        while (
            \count($remainderDenominator) > 1
            && $remainderDenominator[\array_key_last($remainderDenominator)][0] === '0'
        ) {
            \array_pop($remainderDenominator);
        }
        if (\count($remainderNumerator) <= \count($remainderDenominator)) {
            return null;
        }

        $candidateSign = $terms[$candidateIndex][1];
        $denominator = $candidateSign < 0
            ? new UnaryOperationNode(UnaryOperator::Minus, $amplitude, $amplitude->span())
            : $amplitude;
        $target = new BinaryOperationNode(
            BinaryOperator::Divide,
            new UnaryOperationNode(UnaryOperator::Minus, $remainder, $remainder->span()),
            $denominator,
            $remainder->span()->cover($denominator->span()),
        );
        $targetForm = $exactExtractor->rationalFunction($target);
        if ($targetForm === null) {
            return null;
        }
        $targetLimit = $this->rationalFunctionLimitAtInfinity($targetForm);
        if (
            $targetLimit !== null
            && $targetLimit >= -1.0
            && $targetLimit <= 1.0
            && (!\is_finite($lowerBound) || !\is_finite($upperBound))
        ) {
            return null;
        }

        return $this->solveUnboundedRationalTrigonometricTarget(
            $equation,
            $target,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            ),
        );
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialPhaseTrigonometricEquation(
        string $equation,
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $originalLeft = $left;
        $originalRight = $right;
        $leftSign = 1.0;
        $left = $this->unwrapGrouping($left);
        while ($left instanceof UnaryOperationNode) {
            if ($left->operator === UnaryOperator::Minus) {
                $leftSign *= -1.0;
            }
            $left = $this->unwrapGrouping($left->operand);
        }
        $rightSign = 1.0;
        $right = $this->unwrapGrouping($right);
        while ($right instanceof UnaryOperationNode) {
            if ($right->operator === UnaryOperator::Minus) {
                $rightSign *= -1.0;
            }
            $right = $this->unwrapGrouping($right->operand);
        }

        $periodicFunctions = ['sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'sinc', 'sincpi'];
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, $periodicFunctions, true)
            && \count($left->arguments) === 1
        ) {
            $function = $left;
            $target = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, $periodicFunctions, true)
            && \count($right->arguments) === 1
        ) {
            $function = $right;
            $target = $left;
        } else {
            return null;
        }

        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $phaseForm = $exactExtractor->rationalFunction($function->arguments[0]);
        if (
            \in_array($function->name, ['sin', 'cos'], true)
            && (!\is_finite($lowerBound) || !\is_finite($upperBound))
        ) {
            foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
                if (($direction < 0 && \is_finite($bound)) || ($direction > 0 && \is_finite($bound))) {
                    continue;
                }
                $phaseLimit = $this->certifiedElementaryLimitAtInfinity(
                    $function->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($phaseLimit === null || !\is_infinite($phaseLimit)) {
                    continue;
                }
                $targetLimit = $this->rationalExponentialSumLimitAtInfinity(
                    $target,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                $targetLimit = $targetLimit === null ? null : ($leftSign * $rightSign * $targetLimit);
                if ($targetLimit !== null && $targetLimit > -1.0 && $targetLimit < 1.0) {
                    throw new InfiniteSolutionSetException(
                        'An unbounded sine or cosine phase intersects an interior-limit target infinitely many times.',
                    );
                }
            }
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $target,
            $target->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $targetValue = ($leftSign * $rightSign) * $targetCoefficients[0];
        if (!\is_finite($targetValue)) {
            return null;
        }

        $targetIsInRange = match ($function->name) {
            'sin', 'cos' => \abs($targetValue) <= 1.0,
            'sec', 'csc' => \abs($targetValue) >= 1.0,
            'sinc', 'sincpi' => $targetValue >= self::SINC_GLOBAL_LOWER_BOUND && $targetValue <= 1.0,
            'tan', 'cot' => true,
            default => false,
        };
        if (!$targetIsInRange) {
            return [];
        }

        $hasNonconstantPhase = null;
        if ($phaseForm !== null && \count($phaseForm[1]) === 1 && $phaseForm[1][0][0] !== '0') {
            $hasNonconstantPhase = false;
            foreach ($phaseForm[0] as $degree => [$coefficient]) {
                if ($degree > 0 && $coefficient !== '0') {
                    $hasNonconstantPhase = true;
                    break;
                }
            }
        }
        $phaseIsPolynomial = true;
        if ($hasNonconstantPhase === null) {
            $phaseCoefficients = $this->extractPolynomial(
                $extractor,
                $function->arguments[0],
                $function->arguments[0]->span()->start,
            );
            if ($phaseCoefficients === null) {
                $phaseIsPolynomial = false;
            } else {
                $hasNonconstantPhase = false;
                foreach ($phaseCoefficients as $degree => $coefficient) {
                    if ($degree > 0 && $coefficient !== 0.0) {
                        $hasNonconstantPhase = true;
                        break;
                    }
                }
                if (
                    !$hasNonconstantPhase
                    && $this->containsVariable($function->arguments[0], $variable)
                ) {
                    return null;
                }
            }
        }
        if ($hasNonconstantPhase) {
            if (\in_array($function->name, ['sinc', 'sincpi'], true)) {
                if ($targetValue === 0.0) {
                    throw new InfiniteSolutionSetException(
                        'A nonconstant polynomial sinc phase has infinitely many zero levels.',
                    );
                }

                $phaseCoefficients = $this->extractPolynomial(
                    $extractor,
                    $function->arguments[0],
                    $function->arguments[0]->span()->start,
                );
                if ($phaseCoefficients === null) {
                    return null;
                }
                $phaseBound = 1.0 / (\abs($targetValue)
                    * ($function->name === 'sincpi' ? \M_PI : 1.0));
                $phaseLevels = $this->sincTargetPhases(
                    $function->name,
                    $targetValue,
                    -$phaseBound,
                    $phaseBound,
                    $solverOptions,
                );
                if ($phaseLevels === null) {
                    return null;
                }

                $polynomialSolver = new PolynomialSolver();
                $solutions = [];
                foreach ($phaseLevels as $phaseLevel) {
                    $levelCoefficients = $this->subtractScaledPolynomials(
                        $phaseCoefficients,
                        [$phaseLevel],
                        1.0,
                    );
                    if ($levelCoefficients === null) {
                        return null;
                    }
                    $levelSolutions = $polynomialSolver->solve(
                        $levelCoefficients,
                        $lowerBound,
                        $upperBound,
                        fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                            $levelCoefficients,
                            $value,
                        ),
                        $solverOptions,
                        fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                            $levelCoefficients,
                            $value,
                        ),
                    );
                    if ($levelSolutions === null) {
                        return null;
                    }

                    foreach ($levelSolutions as $candidate) {
                        $residual = $this->residualAt(
                            $originalLeft,
                            $originalRight,
                            $rightOffset,
                            $variable,
                            $candidate->value,
                            $parameters,
                            $evaluationOptions,
                        );
                        $candidateScale = fn (float $value): ?float => $this->residualScaleAt(
                            $originalLeft,
                            $originalRight,
                            $rightOffset,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        );
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScale,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution(
                                $candidate->value,
                                \abs($residual),
                                $candidate->iterations,
                            ),
                            $solverOptions,
                        );
                    }
                }

                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }

            throw new InfiniteSolutionSetException(
                'The unbounded polynomial phase produces infinitely many trigonometric roots.',
            );
        }

        $phaseNode = $this->unwrapGrouping($function->arguments[0]);
        if (
            $this->reciprocalLogarithmicPhaseDivergesOnUnboundedTail(
                $phaseNode,
                $extractor,
                $evaluationOptions,
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $lowerBound,
                $upperBound,
            )
        ) {
            throw new InfiniteSolutionSetException(
                'The reciprocal logarithmic trigonometric phase diverges and has infinitely many roots.',
            );
        }
        $logArgument = null;
        $logDivergesAtZero = false;
        if (
            $phaseNode instanceof FunctionCallNode
            && \count($phaseNode->arguments) === 1
            && \in_array($phaseNode->name, ['ln', 'log1p', 'log2', 'log10'], true)
            && $evaluationOptions->functions->isBuiltIn($phaseNode->name)
        ) {
            $logArgument = $phaseNode->arguments[0];
            $logDivergesAtZero = $phaseNode->name !== 'log1p';
        } elseif (
            $phaseNode instanceof FunctionCallNode
            && $phaseNode->name === 'log'
            && \count($phaseNode->arguments) === 2
            && $evaluationOptions->functions->isBuiltIn('log')
        ) {
            $logBase = $this->extractPolynomial(
                $extractor,
                $phaseNode->arguments[1],
                $phaseNode->arguments[1]->span()->start,
            );
            if (
                $logBase !== null
                && \count($logBase) === 1
                && \is_finite($logBase[0])
                && $logBase[0] > 0.0
                && $logBase[0] !== 1.0
            ) {
                $logArgument = $phaseNode->arguments[0];
                $logDivergesAtZero = true;
            }
        }
        if ($logArgument !== null) {
            $logArgumentTerms = $this->extractPolynomialExponentialPhaseTerms(
                $logArgument,
                $extractor,
            );
            if ($logArgumentTerms !== null) {
                foreach ([[$upperBound, 1], [$lowerBound, -1]] as [$bound, $direction]) {
                    if (
                        ($direction > 0 && $bound !== \INF)
                        || ($direction < 0 && $bound !== -\INF)
                    ) {
                        continue;
                    }
                    $logArgumentTailSign = $this->polynomialExponentialPhaseTailSign(
                        $logArgumentTerms[0],
                        $logArgumentTerms[1],
                        $direction,
                    );
                    if (
                        $logArgumentTailSign === 1
                        || ($logDivergesAtZero
                            && $this->polynomialExponentialPhaseZeroSide(
                                $logArgumentTerms[0],
                                $logArgumentTerms[1],
                                $direction,
                            ) === 1)
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The logarithmic trigonometric phase diverges and has infinitely many roots.',
                        );
                    }
                }
            }
        }

        $polynomialExponentialPhase = $this->extractPolynomialExponentialPhaseTerms(
            $function->arguments[0],
            $extractor,
        );
        if ($polynomialExponentialPhase !== null) {
            $unboundedDirections = [];
            if ($upperBound === \INF) {
                $unboundedDirections[] = 1;
            }
            if ($lowerBound === -\INF) {
                $unboundedDirections[] = -1;
            }
            foreach ($unboundedDirections as $direction) {
                if (
                    $this->polynomialExponentialPhaseTailSign(
                        $polynomialExponentialPhase[0],
                        $polynomialExponentialPhase[1],
                        $direction,
                    ) !== null
                ) {
                    throw new InfiniteSolutionSetException(
                        'The exponential-polynomial phase is unbounded and produces infinitely many '
                        . 'trigonometric roots.',
                    );
                }
            }
        }

        $exponentialPhase = $this->extractPolynomialExponentialPhaseForm(
            $function->arguments[0],
            $extractor,
        );
        $growsAtUpper = $exponentialPhase !== null
            && $upperBound === \INF
            && $this->polynomialTendsToPositiveInfinity($exponentialPhase[2], 1);
        $growsAtLower = $exponentialPhase !== null
            && $lowerBound === -\INF
            && $this->polynomialTendsToPositiveInfinity($exponentialPhase[2], -1);
        if ($growsAtUpper || $growsAtLower) {
            throw new InfiniteSolutionSetException(
                'The exponential phase is unbounded and produces infinitely many trigonometric roots.',
            );
        }
        if ($exponentialPhase !== null && ($upperBound === \INF || $lowerBound === -\INF)) {
            $finiteEndpoint = $upperBound === \INF
                ? ($lowerBound === -\INF ? \NAN : $lowerBound)
                : $upperBound;
            $solutions = $this->solveDecayingExponentialPolynomialTrigonometricEquation(
                $function->name,
                $targetValue,
                $exponentialPhase,
                $finiteEndpoint,
                $lowerBound,
                $upperBound,
                $originalLeft,
                $originalRight,
                $rightOffset,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($solutions !== null) {
                return $solutions;
            }
        }
        if (!$phaseIsPolynomial) {
            if (
                $phaseForm !== null
                && \count($phaseForm[1]) > 1
                && $this->containsVariable($function->arguments[0], $variable)
            ) {
                $this->throwIfPeriodicRationalArgumentHasPole(
                    $originalLeft,
                    $originalRight,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                    $evaluationOptions,
                    $parameters,
                );

                $phaseNumeratorDegree = \count($phaseForm[0]) - 1;
                while (
                    $phaseNumeratorDegree > 0
                    && $phaseForm[0][$phaseNumeratorDegree][0] === '0'
                ) {
                    --$phaseNumeratorDegree;
                }
                $phaseDenominatorDegree = \count($phaseForm[1]) - 1;
                while (
                    $phaseDenominatorDegree > 0
                    && $phaseForm[1][$phaseDenominatorDegree][0] === '0'
                ) {
                    --$phaseDenominatorDegree;
                }
                if (
                    (($upperBound === \INF) || ($lowerBound === -\INF))
                    && $phaseNumeratorDegree > $phaseDenominatorDegree
                ) {
                    throw new InfiniteSolutionSetException(
                        'The rational trigonometric phase grows without bound on an unbounded tail.',
                    );
                }

                $rationalPeriodicSolutions = $this->solveRationalPeriodicFunction(
                    $function,
                    new NumberNode(
                        $targetValue,
                        \sprintf('%.17g', $targetValue),
                        $target->span(),
                    ),
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                    fn (float $value): ?float => $this->residualAt(
                        $originalLeft,
                        $originalRight,
                        $rightOffset,
                        $variable,
                        $value,
                        $parameters,
                        $evaluationOptions,
                    ),
                    fn (float $value): ?float => $this->residualScaleAt(
                        $originalLeft,
                        $originalRight,
                        $rightOffset,
                        $variable,
                        $value,
                        $parameters,
                        $evaluationOptions,
                    ) ?? 1.0,
                );
                if ($rationalPeriodicSolutions !== null) {
                    return $rationalPeriodicSolutions;
                }
            }

            return null;
        }

        $variables = [...$parameters, $variable => 0.0];
        try {
            $leftValue = (float) $this->evaluateNode($originalLeft, $variables, $evaluationOptions);
            $rightValue = (float) $this->evaluateNode($originalRight, $variables, $evaluationOptions);
        } catch (EvaluationException) {
            return [];
        }
        if (!\is_finite($leftValue) || !\is_finite($rightValue)) {
            return [];
        }
        $residual = $leftValue - $rightValue;
        $scale = \max(1.0, \abs($leftValue), \abs($rightValue));
        if (\abs($residual) <= $solverOptions->residualTolerance * $scale) {
            throw new InfiniteSolutionSetException(
                'The unbounded equation is an identity and has infinitely many solutions.',
            );
        }

        return [];
    }

    /**
     * Certify limits for rational functions and selected compositions of standard real functions.
     */
    private function certifiedElementaryLimitAtInfinity(
        Node $node,
        string $variable,
        int $direction,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?float {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $form = $extractor->rationalFunction($node);
        if ($form !== null) {
            $limit = $this->rationalFunctionLimitAtInfinity($form);
            if ($limit !== null) {
                return $limit;
            }
            $data = $this->rationalFunctionAsymptoticData($form);
            if ($data === null || $data[0] <= 0) {
                return null;
            }
            $sign = $data[1];
            if ($direction < 0 && $data[0] % 2 !== 0) {
                $sign *= -1;
            }

            return $sign > 0 ? \INF : -\INF;
        }
        if (!$this->containsVariable($node, $variable)) {
            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $constant !== null && \is_finite($constant) ? $constant : null;
        }

        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $limit = $this->certifiedElementaryLimitAtInfinity(
                $node->operand,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );

            return $node->operator === UnaryOperator::Minus && $limit !== null ? -$limit : $limit;
        }
        if ($node instanceof BinaryOperationNode && \in_array(
            $node->operator,
            [BinaryOperator::Add, BinaryOperator::Subtract],
            true,
        )) {
            $leftLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->left,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $rightLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->right,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($leftLimit === null || $rightLimit === null) {
                return null;
            }
            if ($node->operator === BinaryOperator::Subtract) {
                $rightLimit = -$rightLimit;
            }
            if (\is_infinite($leftLimit) || \is_infinite($rightLimit)) {
                if (\is_infinite($leftLimit) && \is_infinite($rightLimit) && $leftLimit !== $rightLimit) {
                    return null;
                }

                return \is_infinite($leftLimit) ? $leftLimit : $rightLimit;
            }

            $limit = $leftLimit + $rightLimit;

            return \is_finite($limit) ? $limit : null;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array(
                $node->operator,
                [BinaryOperator::Multiply, BinaryOperator::Divide, BinaryOperator::Power],
                true,
            )
        ) {
            $leftNode = $this->unwrapGrouping($node->left);
            $rightNode = $this->unwrapGrouping($node->right);
            if (
                \in_array($node->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
                &&
                $leftNode instanceof FunctionCallNode
                && $leftNode->name === 'exp'
                && \count($leftNode->arguments) === 1
                && $rightNode instanceof FunctionCallNode
                && $rightNode->name === 'exp'
                && \count($rightNode->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn('exp')
            ) {
                $combinedExponent = new BinaryOperationNode(
                    $node->operator === BinaryOperator::Multiply ? BinaryOperator::Add : BinaryOperator::Subtract,
                    $leftNode->arguments[0],
                    $rightNode->arguments[0],
                    $leftNode->arguments[0]->span()->cover($rightNode->arguments[0]->span()),
                );

                return $this->certifiedElementaryLimitAtInfinity(
                    new FunctionCallNode('exp', [$combinedExponent], $leftNode->nameSpan, $node->span()),
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }

            $leftIsExponential = $leftNode instanceof FunctionCallNode
                && $leftNode->name === 'exp'
                && \count($leftNode->arguments) === 1;
            $rightIsExponential = $rightNode instanceof FunctionCallNode
                && $rightNode->name === 'exp'
                && \count($rightNode->arguments) === 1;
            if (
                $leftIsExponential !== $rightIsExponential
                && $node->operator !== BinaryOperator::Power
                && $evaluationOptions->functions->isBuiltIn('exp')
            ) {
                $exponentialNode = $leftIsExponential ? $leftNode : $rightNode;
                $rationalNode = $leftIsExponential ? $node->right : $node->left;
                $exponentLimit = $this->certifiedElementaryLimitAtInfinity(
                    $exponentialNode->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                $rationalForm = $extractor->rationalFunction($rationalNode);
                $rationalData = $rationalForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($rationalForm);
                if ($rationalData !== null && \is_infinite($exponentLimit ?? 0.0)) {
                    $rationalSign = $rationalData[1];
                    if ($direction < 0 && $rationalData[0] % 2 !== 0) {
                        $rationalSign *= -1;
                    }
                    if ($rationalData[1] === 0) {
                        if ($node->operator === BinaryOperator::Multiply || $rightIsExponential) {
                            return 0.0;
                        }

                        return null;
                    }
                    if ($node->operator === BinaryOperator::Divide && $rightIsExponential) {
                        return $exponentLimit > 0.0
                            ? 0.0
                            : ($rationalSign > 0 ? \INF : -\INF);
                    }
                    if ($exponentLimit < 0.0) {
                        return 0.0;
                    }
                    if ($rationalSign !== 0) {
                        return $rationalSign > 0 ? \INF : -\INF;
                    }
                }
            }

            if ($node->operator === BinaryOperator::Power) {
                if (
                    $leftNode instanceof FunctionCallNode
                    && $leftNode->name === 'exp'
                    && \count($leftNode->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn('exp')
                ) {
                    $combinedExponent = new BinaryOperationNode(
                        BinaryOperator::Multiply,
                        $leftNode->arguments[0],
                        $node->right,
                        $leftNode->arguments[0]->span()->cover($node->right->span()),
                    );

                    return $this->certifiedElementaryLimitAtInfinity(
                        new FunctionCallNode('exp', [$combinedExponent], $leftNode->nameSpan, $node->span()),
                        $variable,
                        $direction,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                }
                $baseLimit = $this->certifiedElementaryLimitAtInfinity(
                    $node->left,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                $exponentLimit = $this->certifiedElementaryLimitAtInfinity(
                    $node->right,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($baseLimit === null || $exponentLimit === null) {
                    return null;
                }
                if (\is_infinite($exponentLimit)) {
                    if ($baseLimit === \INF) {
                        return $exponentLimit > 0.0 ? \INF : 0.0;
                    }
                    if (
                        $baseLimit === 0.0
                        && $this->isCertifiedEventuallyPositiveAtInfinity(
                            $node->left,
                            $variable,
                            $direction,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        )
                    ) {
                        return $exponentLimit > 0.0 ? 0.0 : \INF;
                    }
                    if (\is_finite($baseLimit) && $baseLimit > 0.0 && $baseLimit !== 1.0) {
                        return ($baseLimit > 1.0) === ($exponentLimit > 0.0) ? \INF : 0.0;
                    }

                    return null;
                }
                if (
                    !$this->containsVariable($node->right, $variable)
                    && $exponentLimit === 0.0
                    && $this->constantNodeValue($node->right, $parameters, $evaluationOptions) === 0.0
                ) {
                    return 1.0;
                }
                if ($baseLimit === \INF) {
                    if ($exponentLimit > 0.0) {
                        return \INF;
                    }
                    if ($exponentLimit < 0.0) {
                        return 0.0;
                    }

                    return null;
                }
                if ($baseLimit === -\INF || $baseLimit < 0.0) {
                    if ($this->containsVariable($node->right, $variable)) {
                        return null;
                    }
                    $constantExponent = $this->constantNodeValue(
                        $node->right,
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $constantExponent === null
                        || !\is_finite($constantExponent)
                        || \floor($constantExponent) !== $constantExponent
                    ) {
                        return null;
                    }
                    if (\abs($constantExponent) > 9_007_199_254_740_991.0) {
                        return null;
                    }
                    if ($baseLimit === -\INF && $constantExponent > 0.0) {
                        return ((int) $constantExponent % 2) === 0 ? \INF : -\INF;
                    }
                    if ($baseLimit === -\INF && $constantExponent < 0.0) {
                        return 0.0;
                    }
                    if ($baseLimit < 0.0) {
                        $limit = \pow($baseLimit, $constantExponent);

                        return \is_finite($limit) && ($limit !== 0.0 || $baseLimit === 0.0)
                            ? $limit
                            : null;
                    }
                }
                if ($baseLimit === 0.0) {
                    if (!$this->isCertifiedEventuallyPositiveAtInfinity(
                        $node->left,
                        $variable,
                        $direction,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    )) {
                        return null;
                    }
                    if ($exponentLimit > 0.0) {
                        return 0.0;
                    }
                    if ($exponentLimit < 0.0) {
                        return \INF;
                    }

                    return null;
                }
                if ($baseLimit > 0.0 && \is_finite($baseLimit)) {
                    $limit = \pow($baseLimit, $exponentLimit);

                    return \is_finite($limit) && ($limit !== 0.0 || $baseLimit === 0.0)
                        ? $limit
                        : null;
                }

                return null;
            }

            $leftLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->left,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $rightLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->right,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($leftLimit === null || $rightLimit === null) {
                return null;
            }
            if ($node->operator === BinaryOperator::Multiply) {
                if (
                    (\is_infinite($leftLimit) && $rightLimit === 0.0)
                    || (\is_infinite($rightLimit) && $leftLimit === 0.0)
                ) {
                    return null;
                }
                if (!\is_infinite($leftLimit) && !\is_infinite($rightLimit)) {
                    $limit = $leftLimit * $rightLimit;

                    return \is_finite($limit) ? $limit : null;
                }
                $limit = $leftLimit * $rightLimit;

                return \is_infinite($limit) ? $limit : null;
            }
            if ($rightLimit === 0.0 || (\is_infinite($leftLimit) && \is_infinite($rightLimit))) {
                return null;
            }
            if (\is_infinite($rightLimit)) {
                return 0.0;
            }
            $limit = $leftLimit / $rightLimit;

            return \is_finite($limit) ? $limit : null;
        }
        if (!$node instanceof FunctionCallNode) {
            return null;
        }
        $name = $node->name;
        if (!$evaluationOptions->functions->isBuiltIn($name)) {
            return null;
        }
        if ($name === 'log' && \count($node->arguments) === 2) {
            $valueLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->arguments[0],
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $baseLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->arguments[1],
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $valueLimit === \INF
                && $baseLimit !== null
                && \is_finite($baseLimit)
                && $baseLimit > 0.0
                && $baseLimit !== 1.0
            ) {
                return $baseLimit > 1.0 ? \INF : -\INF;
            }
            if (
                \in_array($valueLimit, [0.0, \INF], true)
                && \in_array($baseLimit, [0.0, \INF], true)
            ) {
                $valueForm = $extractor->rationalFunction($node->arguments[0]);
                $baseForm = $extractor->rationalFunction($node->arguments[1]);
                $valueData = $valueForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($valueForm);
                $baseData = $baseForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($baseForm);
                $valueSign = $valueData[1] ?? 0;
                $baseSign = $baseData[1] ?? 0;
                if ($direction < 0) {
                    if ($valueData !== null && $valueData[0] % 2 !== 0) {
                        $valueSign *= -1;
                    }
                    if ($baseData !== null && $baseData[0] % 2 !== 0) {
                        $baseSign *= -1;
                    }
                }
                if (
                    $valueData !== null
                    && $baseData !== null
                    && $valueData[0] !== 0
                    && $baseData[0] !== 0
                    && $valueSign > 0
                    && $baseSign > 0
                ) {
                    return $valueData[0] / $baseData[0];
                }
            }
            if ($valueLimit === \INF && $baseLimit === 1.0) {
                $one = new NumberNode(1, '1', $node->arguments[1]->span());
                $baseOffset = new BinaryOperationNode(
                    BinaryOperator::Subtract,
                    $node->arguments[1],
                    $one,
                    $node->arguments[1]->span(),
                );
                $baseOffsetForm = $extractor->rationalFunction($baseOffset);
                $baseOffsetData = $baseOffsetForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($baseOffsetForm);
                if ($baseOffsetData !== null && $baseOffsetData[0] < 0) {
                    $offsetSign = $baseOffsetData[1];
                    if ($direction < 0 && $baseOffsetData[0] % 2 !== 0) {
                        $offsetSign *= -1;
                    }

                    return $offsetSign > 0 ? \INF : -\INF;
                }
            }
            $valueNode = $this->unwrapGrouping($node->arguments[0]);
            $baseNode = $this->unwrapGrouping($node->arguments[1]);
            if (
                $valueNode instanceof FunctionCallNode
                && $valueNode->name === 'exp'
                && \count($valueNode->arguments) === 1
                && $baseNode instanceof FunctionCallNode
                && $baseNode->name === 'exp'
                && \count($baseNode->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn('exp')
                && $this->certifiedElementaryLimitAtInfinity(
                    $baseNode->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                ) === \INF
            ) {
                $quotient = new BinaryOperationNode(
                    BinaryOperator::Divide,
                    $valueNode->arguments[0],
                    $baseNode->arguments[0],
                    $valueNode->arguments[0]->span()->cover($baseNode->arguments[0]->span()),
                );
                $quotientForm = $extractor->rationalFunction($quotient);
                $quotientData = $quotientForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($quotientForm);
                if ($quotientData !== null && $quotientData[0] > 0) {
                    $quotientSign = $quotientData[1];
                    if ($direction < 0 && $quotientData[0] % 2 !== 0) {
                        $quotientSign *= -1;
                    }

                    return $quotientSign > 0 ? \INF : -\INF;
                }
            }
            if (($valueLimit === \INF || $valueLimit === 0.0) && $baseLimit === \INF) {
                $valueNode = $this->unwrapGrouping($node->arguments[0]);
                $baseForm = $extractor->rationalFunction($node->arguments[1]);
                if (
                    $valueNode instanceof FunctionCallNode
                    && $valueNode->name === 'exp'
                    && \count($valueNode->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn('exp')
                    && $baseForm !== null
                ) {
                    $baseData = $this->rationalFunctionAsymptoticData($baseForm);
                    $exponentLimit = $this->certifiedElementaryLimitAtInfinity(
                        $valueNode->arguments[0],
                        $variable,
                        $direction,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    $exponentForm = $extractor->rationalFunction($valueNode->arguments[0]);
                    $exponentData = $exponentForm === null
                        ? null
                        : $this->rationalFunctionAsymptoticData($exponentForm);
                    $baseSign = $baseData[1] ?? 0;
                    if ($direction < 0 && $baseData !== null && $baseData[0] % 2 !== 0) {
                        $baseSign *= -1;
                    }
                    if (
                        $baseData !== null
                        && $baseData[0] > 0
                        && $baseSign > 0
                        && $exponentData !== null
                        && $exponentData[0] > 0
                        && \is_infinite($exponentLimit ?? 0.0)
                    ) {
                        return $exponentLimit > 0.0 ? \INF : -\INF;
                    }
                }
            }

            return null;
        }
        if (\count($node->arguments) !== 1) {
            return null;
        }
        $argumentLimit = $this->certifiedElementaryLimitAtInfinity(
            $node->arguments[0],
            $variable,
            $direction,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($argumentLimit === null) {
            return null;
        }
        if ($name === 'exp') {
            if ($argumentLimit === \INF) {
                return \INF;
            }
            if ($argumentLimit === -\INF) {
                return 0.0;
            }
            $limit = \exp($argumentLimit);

            return \is_finite($limit) ? $limit : null;
        }
        if ($name === 'sqrt') {
            if ($argumentLimit === \INF) {
                return \INF;
            }
            if (\is_finite($argumentLimit) && $argumentLimit > 0.0) {
                return \sqrt($argumentLimit);
            }
            if (
                $argumentLimit === 0.0
                && $this->isCertifiedEventuallyPositiveAtInfinity(
                    $node->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
            ) {
                return 0.0;
            }

            return null;
        }

        return match ($name) {
            'ln', 'log', 'log1p', 'log2', 'log10' => $argumentLimit === \INF ? \INF : null,
            'asinh', 'arcsinh', 'sinh' => \is_infinite($argumentLimit)
                ? ($name === 'sinh' ? $argumentLimit : ($argumentLimit > 0.0 ? \INF : -\INF))
                : null,
            'cosh' => \is_infinite($argumentLimit) ? \INF : null,
            'acosh', 'arccosh', 'lambertw' => $argumentLimit === \INF ? \INF : null,
            default => null,
        };
    }

    private function isCertifiedEventuallyPositiveAtInfinity(
        Node $node,
        string $variable,
        int $direction,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $form = $extractor->rationalFunction($node);
        if ($form !== null) {
            $data = $this->rationalFunctionAsymptoticData($form);
            if ($data === null || $data[1] === 0) {
                return false;
            }
            $sign = $data[1];
            if ($direction < 0 && $data[0] % 2 !== 0) {
                $sign *= -1;
            }

            return $sign > 0;
        }
        if (!$this->containsVariable($node, $variable)) {
            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $constant !== null && \is_finite($constant) && $constant > 0.0;
        }
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'exp'
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('exp')
        ) {
            return true;
        }
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'sqrt'
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('sqrt')
        ) {
            $argumentLimit = $this->certifiedElementaryLimitAtInfinity(
                $node->arguments[0],
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );

            return $argumentLimit !== null
                && $argumentLimit >= 0.0
                && ($argumentLimit > 0.0 || $this->isCertifiedEventuallyPositiveAtInfinity(
                    $node->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                ));
        }

        return false;
    }

    private function rationalExponentialSumLimitAtInfinity(
        Node $node,
        string $variable,
        int $direction,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?float {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $terms = [];
        $this->flattenAdditiveTerms($node, 1.0, $terms);
        $sum = 0.0;
        foreach ($terms as [$term, $sign]) {
            $term = $this->unwrapGrouping($term);
            $factors = $term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Multiply
                ? [[$term->left, $term->right], [$term->right, $term->left]]
                : [[null, $term]];
            $termLimit = null;
            foreach ($factors as [$amplitude, $exponential]) {
                $exponential = $this->unwrapGrouping($exponential);
                if (
                    !$exponential instanceof FunctionCallNode
                    || $exponential->name !== 'exp'
                    || \count($exponential->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn('exp')
                ) {
                    continue;
                }
                $amplitude ??= new NumberNode(1, '1', new SourceSpan(0, 1));
                $amplitudeForm = $extractor->rationalFunction($amplitude);
                if ($amplitudeForm === null) {
                    return null;
                }
                $amplitudeLimit = $this->rationalFunctionLimitAtInfinity($amplitudeForm);
                $phaseLimit = $this->certifiedElementaryLimitAtInfinity(
                    $exponential->arguments[0],
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($amplitudeLimit === null || $phaseLimit === null) {
                    return null;
                }
                if ($phaseLimit === -\INF) {
                    $termLimit = 0.0;
                } elseif ($phaseLimit === \INF) {
                    if ($amplitudeLimit === 0.0) {
                        return null;
                    }
                    $termLimit = $amplitudeLimit > 0.0 ? \INF : -\INF;
                } else {
                    $termLimit = $amplitudeLimit * \exp($phaseLimit);
                }
                break;
            }
            if ($termLimit === null) {
                $form = $extractor->rationalFunction($term);
                $termLimit = $form === null ? null : $this->rationalFunctionLimitAtInfinity($form);
            }
            if ($termLimit === null || !\is_finite($termLimit)) {
                return null;
            }
            $sum += $sign * $termLimit;
        }

        return \is_finite($sum) ? $sum : null;
    }

    private function reciprocalLogarithmicPhaseDivergesOnUnboundedTail(
        Node $phase,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        float $lowerBound,
        float $upperBound,
    ): bool {
        if (!$phase instanceof BinaryOperationNode || $phase->operator !== BinaryOperator::Divide) {
            return false;
        }

        $numerator = $this->extractPolynomial($extractor, $phase->left, $phase->left->span()->start);
        $logarithm = $this->unwrapGrouping($phase->right);
        if (
            $numerator === null
            || \count($numerator) !== 1
            || $numerator[0] === 0.0
            || !\is_finite($numerator[0])
            || !$logarithm instanceof FunctionCallNode
        ) {
            return false;
        }

        $argument = null;
        $subtractOne = false;
        if (
            \count($logarithm->arguments) === 1
            && \in_array($logarithm->name, ['ln', 'log1p', 'log2', 'log10'], true)
            && $evaluationOptions->functions->isBuiltIn($logarithm->name)
        ) {
            $argument = $logarithm->arguments[0];
            $subtractOne = $logarithm->name !== 'log1p';
        } elseif (
            $logarithm->name === 'log'
            && \count($logarithm->arguments) === 2
            && $evaluationOptions->functions->isBuiltIn('log')
        ) {
            $base = $this->extractPolynomial(
                $extractor,
                $logarithm->arguments[1],
                $logarithm->arguments[1]->span()->start,
            );
            if (
                $base !== null
                && \count($base) === 1
                && \is_finite($base[0])
                && $base[0] > 0.0
                && $base[0] !== 1.0
            ) {
                $argument = $logarithm->arguments[0];
                $subtractOne = true;
            }
        }
        if ($argument === null) {
            return false;
        }

        $argumentTerms = $this->extractPolynomialExponentialPhaseTerms($argument, $extractor);
        if ($argumentTerms !== null) {
            [$terms, $remainder] = $argumentTerms;
            if ($subtractOne) {
                $remainder[0] = ($remainder[0] ?? 0.0) - 1.0;
            }

            foreach ([[$upperBound, 1], [$lowerBound, -1]] as [$bound, $direction]) {
                if (
                    ($direction > 0 && $bound !== \INF)
                    || ($direction < 0 && $bound !== -\INF)
                ) {
                    continue;
                }
                if ($this->polynomialExponentialPhaseZeroSide($terms, $remainder, $direction) !== null) {
                    return true;
                }
            }
        }

        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $limitLevel = $subtractOne ? 1.0 : 0.0;
        foreach ([[$upperBound, 1], [$lowerBound, -1]] as [$bound, $direction]) {
            if (
                ($direction > 0 && $bound !== \INF)
                || ($direction < 0 && $bound !== -\INF)
            ) {
                continue;
            }
            $difference = $exactExtractor->rationalDifference(
                $argument,
                new NumberNode($limitLevel, $limitLevel === 1.0 ? '1' : '0', $argument->span()),
            );
            if ($difference === null) {
                continue;
            }
            [$numerator, $denominator] = $difference;
            while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
                \array_pop($numerator);
            }
            while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === '0') {
                \array_pop($denominator);
            }
            if (
                $denominator === []
                || $denominator[\array_key_last($denominator)] === '0'
                || $numerator === ['0']
                || \count($numerator) >= \count($denominator)
            ) {
                continue;
            }
            if (
                $this->rationalFunctionDifferenceSignAtInfinity(
                    $exactExtractor,
                    $argument,
                    $limitLevel,
                    $direction,
                ) !== null
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extract sum(a_i*exp(P_i(x))) + Q(x), where all P_i and Q are polynomials.
     *
     * @return array{list<array{float, list<float>}>, list<float>}|null
     */
    private function extractPolynomialExponentialPhaseTerms(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->extractPolynomialExponentialPhaseTerms($node->operand, $extractor);
            if ($form === null) {
                return null;
            }
            $sign = $node->operator === UnaryOperator::Minus ? -1.0 : 1.0;

            return [
                \array_map(
                    static fn (array $term): array => [$sign * $term[0], $term[1]],
                    $form[0],
                ),
                \array_map(static fn (float $coefficient): float => $sign * $coefficient, $form[1]),
            ];
        }

        if ($node instanceof FunctionCallNode && $node->name === 'exp' && \count($node->arguments) === 1) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $node->arguments[0],
                $node->arguments[0]->span()->start,
            );
            if ($exponent === null || \count($exponent) < 2) {
                return null;
            }

            return [[[1.0, $exponent]], [0.0]];
        }

        $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
        if ($polynomial !== null) {
            return [[], $polynomial];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $left = $this->extractPolynomialExponentialPhaseTerms($node->left, $extractor);
        $right = $this->extractPolynomialExponentialPhaseTerms($node->right, $extractor);
        if ($left === null || $right === null) {
            return null;
        }
        if ($node->operator === BinaryOperator::Add || $node->operator === BinaryOperator::Subtract) {
            $rightSign = $node->operator === BinaryOperator::Add ? 1.0 : -1.0;
            $degree = \max(\count($left[1]), \count($right[1]));
            $remainder = [];
            for ($index = 0; $index < $degree; ++$index) {
                $remainder[] = ($left[1][$index] ?? 0.0) + $rightSign * ($right[1][$index] ?? 0.0);
            }

            return $this->finitePolynomialExponentialPhaseTerms(
                [
                    ...$left[0],
                    ...\array_map(
                        static fn (array $term): array => [$rightSign * $term[0], $term[1]],
                        $right[0],
                    ),
                ],
                $remainder,
            );
        }

        if ($node->operator === BinaryOperator::Multiply) {
            if ($left[0] !== [] && $right[0] === [] && \count($right[1]) === 1) {
                $scale = $right[1][0];
                return $this->finitePolynomialExponentialPhaseTerms(
                    \array_map(
                        static fn (array $term): array => [$term[0] * $scale, $term[1]],
                        $left[0],
                    ),
                    \array_map(static fn (float $value): float => $value * $scale, $left[1]),
                );
            }
            if ($right[0] !== [] && $left[0] === [] && \count($left[1]) === 1) {
                $scale = $left[1][0];
                return $this->finitePolynomialExponentialPhaseTerms(
                    \array_map(
                        static fn (array $term): array => [$term[0] * $scale, $term[1]],
                        $right[0],
                    ),
                    \array_map(static fn (float $value): float => $value * $scale, $right[1]),
                );
            }
        }

        if ($node->operator === BinaryOperator::Divide && $left[0] !== [] && $right[0] === []) {
            $divisor = \count($right[1]) === 1 ? $right[1][0] : 0.0;
            if ($divisor !== 0.0 && \is_finite($divisor)) {
                return $this->finitePolynomialExponentialPhaseTerms(
                    \array_map(
                        static fn (array $term): array => [$term[0] / $divisor, $term[1]],
                        $left[0],
                    ),
                    \array_map(static fn (float $value): float => $value / $divisor, $left[1]),
                );
            }
        }

        return null;
    }

    /**
     * @param list<array{float, list<float>}> $terms
     * @param list<float> $remainder
     * @return array{list<array{float, list<float>}>, list<float>}|null
     */
    private function finitePolynomialExponentialPhaseTerms(array $terms, array $remainder): ?array
    {
        foreach ($terms as [$scale, $exponent]) {
            if (!\is_finite($scale)) {
                return null;
            }
            foreach ($exponent as $coefficient) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }
        }
        foreach ($remainder as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        return [$terms, $remainder];
    }

    /**
     * Return the eventual sign of an unbounded exponential-polynomial phase tail.
     *
     * @param list<array{float, list<float>}> $terms
     * @param list<float> $remainder
     */
    private function polynomialExponentialPhaseTailSign(
        array $terms,
        array $remainder,
        int $direction,
    ): ?int {
        $growingTerms = \array_values(\array_filter(
            $terms,
            fn (array $term): bool => $term[0] !== 0.0
                && $this->polynomialTendsToPositiveInfinity($term[1], $direction),
        ));

        while ($growingTerms !== []) {
            $dominant = $growingTerms[0][1];
            foreach (\array_slice($growingTerms, 1) as [, $exponent]) {
                if ($exponent === $dominant) {
                    continue;
                }
                $difference = $this->subtractScaledPolynomials($exponent, $dominant, 1.0);
                if ($difference === null) {
                    return null;
                }
                if ($this->polynomialTendsToPositiveInfinity($difference, $direction)) {
                    $dominant = $exponent;
                    continue;
                }
                $reverseDifference = $this->subtractScaledPolynomials($dominant, $exponent, 1.0);
                if (
                    $reverseDifference === null
                    || (!$this->polynomialTendsToPositiveInfinity($reverseDifference, $direction)
                        && !$this->polynomialExponentsDifferByConstant($exponent, $dominant))
                ) {
                    return null;
                }
            }

            $equivalentTerms = [];
            foreach ($growingTerms as [$scale, $exponent]) {
                if ($this->polynomialExponentsDifferByConstant($exponent, $dominant)) {
                    $equivalentTerms[] = [$scale, $exponent];
                }
            }
            $equivalentScales = [];
            foreach ($equivalentTerms as [$scale, $exponent]) {
                $matchedIndex = null;
                foreach ($equivalentScales as $index => [$sum, $matchedExponent]) {
                    if ($matchedExponent === $exponent) {
                        $matchedIndex = $index;
                        $equivalentScales[$index] = [$sum + $scale, $matchedExponent];
                        break;
                    }
                }
                if ($matchedIndex === null) {
                    $equivalentScales[] = [$scale, $exponent];
                }
            }
            foreach ($equivalentScales as [$scale]) {
                if (!\is_finite($scale)) {
                    return null;
                }
            }
            $equivalentScales = \array_values(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] !== 0.0,
            ));
            if ($equivalentScales === []) {
                $growingTerms = \array_values(\array_filter(
                    $growingTerms,
                    fn (array $term): bool => !$this->polynomialExponentsDifferByConstant(
                        $term[1],
                        $dominant,
                    ),
                ));
                continue;
            }
            $allPositive = \count(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] > 0.0,
            )) === \count($equivalentScales);
            $allNegative = \count(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] < 0.0,
            )) === \count($equivalentScales);
            if (!$allPositive && !$allNegative) {
                return null;
            }

            return $allPositive ? 1 : -1;
        }

        while (\count($remainder) > 1 && $remainder[\array_key_last($remainder)] === 0.0) {
            \array_pop($remainder);
        }
        if (\count($remainder) < 2 || $remainder[\array_key_last($remainder)] === 0.0) {
            return null;
        }
        $leadingCoefficient = $remainder[\array_key_last($remainder)];
        if ($direction < 0 && (\count($remainder) - 1) % 2 === 1) {
            $leadingCoefficient *= -1.0;
        }

        return $leadingCoefficient > 0.0 ? 1 : -1;
    }

    /**
     * Return the side from which a finite exponential-polynomial sum tends to zero.
     *
     * @param list<array{float, list<float>}> $terms
     * @param list<float> $remainder
     */
    private function polynomialExponentialPhaseZeroSide(
        array $terms,
        array $remainder,
        int $direction,
    ): ?int {
        while (\count($remainder) > 1 && $remainder[\array_key_last($remainder)] === 0.0) {
            \array_pop($remainder);
        }
        if (\count($remainder) !== 1 || $remainder[0] !== 0.0) {
            return null;
        }

        $decayingTerms = [];
        foreach ($terms as $term) {
            if ($term[0] === 0.0) {
                continue;
            }
            if ($this->polynomialTendsToPositiveInfinity($term[1], $direction)) {
                return null;
            }
            if (
                $this->polynomialTendsToPositiveInfinity(
                    \array_map(static fn (float $coefficient): float => -$coefficient, $term[1]),
                    $direction,
                )
            ) {
                $decayingTerms[] = $term;
            } else {
                return null;
            }
        }
        if ($decayingTerms === []) {
            return null;
        }

        while ($decayingTerms !== []) {
            $dominant = $decayingTerms[0][1];
            foreach (\array_slice($decayingTerms, 1) as [, $exponent]) {
                if ($this->polynomialExponentsDifferByConstant($exponent, $dominant)) {
                    continue;
                }
                $difference = $this->subtractScaledPolynomials($exponent, $dominant, 1.0);
                if ($difference === null) {
                    return null;
                }
                if ($this->polynomialTendsToPositiveInfinity($difference, $direction)) {
                    $dominant = $exponent;
                    continue;
                }
                $reverseDifference = $this->subtractScaledPolynomials($dominant, $exponent, 1.0);
                if (
                    $reverseDifference === null
                    || !$this->polynomialTendsToPositiveInfinity($reverseDifference, $direction)
                ) {
                    return null;
                }
            }

            $equivalentTerms = [];
            foreach ($decayingTerms as [$scale, $exponent]) {
                if ($this->polynomialExponentsDifferByConstant($exponent, $dominant)) {
                    $equivalentTerms[] = [$scale, $exponent];
                }
            }
            $equivalentScales = [];
            foreach ($equivalentTerms as [$scale, $exponent]) {
                $matched = false;
                foreach ($equivalentScales as $index => [$sum, $matchedExponent]) {
                    if ($matchedExponent === $exponent) {
                        $equivalentScales[$index] = [$sum + $scale, $matchedExponent];
                        $matched = true;
                        break;
                    }
                }
                if (!$matched) {
                    $equivalentScales[] = [$scale, $exponent];
                }
            }
            foreach ($equivalentScales as [$scale]) {
                if (!\is_finite($scale)) {
                    return null;
                }
            }
            $equivalentScales = \array_values(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] !== 0.0,
            ));
            if ($equivalentScales === []) {
                $decayingTerms = \array_values(\array_filter(
                    $decayingTerms,
                    fn (array $term): bool => !$this->polynomialExponentsDifferByConstant(
                        $term[1],
                        $dominant,
                    ),
                ));
                continue;
            }

            $allPositive = \count(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] > 0.0,
            )) === \count($equivalentScales);
            $allNegative = \count(\array_filter(
                $equivalentScales,
                static fn (array $term): bool => $term[0] < 0.0,
            )) === \count($equivalentScales);

            return $allPositive ? 1 : ($allNegative ? -1 : null);
        }

        return null;
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     */
    private function polynomialExponentsDifferByConstant(array $left, array $right): bool
    {
        $degree = \max(\count($left), \count($right));
        for ($power = 1; $power < $degree; ++$power) {
            if (($left[$power] ?? 0.0) !== ($right[$power] ?? 0.0)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Extract a*exp(P(x)) + b where P is a nonconstant polynomial.
     *
     * @return array{float, float, list<float>}|null Scale, offset, exponent polynomial.
     */
    private function extractPolynomialExponentialPhaseForm(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->extractPolynomialExponentialPhaseForm($node->operand, $extractor);
            if ($form === null) {
                return null;
            }
            $sign = $node->operator === UnaryOperator::Minus ? -1.0 : 1.0;

            return $this->finitePolynomialExponentialPhaseForm(
                $sign * $form[0],
                $sign * $form[1],
                $form[2],
            );
        }

        if ($node instanceof FunctionCallNode && $node->name === 'exp' && \count($node->arguments) === 1) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $node->arguments[0],
                $node->arguments[0]->span()->start,
            );
            if ($exponent === null) {
                return null;
            }
            while (\count($exponent) > 1 && $exponent[\array_key_last($exponent)] === 0.0) {
                \array_pop($exponent);
            }
            if (\count($exponent) < 2) {
                return null;
            }
            foreach (\array_slice($exponent, 1) as $coefficient) {
                if ($coefficient !== 0.0 && \is_finite($coefficient)) {
                    return $this->finitePolynomialExponentialPhaseForm(1.0, 0.0, $exponent);
                }
            }

            return null;
        }

        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $leftForm = $this->extractPolynomialExponentialPhaseForm($node->left, $extractor);
        $rightForm = $this->extractPolynomialExponentialPhaseForm($node->right, $extractor);
        $leftConstant = $this->extractPolynomial($extractor, $node->left, $node->left->span()->start);
        $rightConstant = $this->extractPolynomial($extractor, $node->right, $node->right->span()->start);
        $leftValue = $leftConstant !== null && \count($leftConstant) === 1 ? $leftConstant[0] : null;
        $rightValue = $rightConstant !== null && \count($rightConstant) === 1 ? $rightConstant[0] : null;

        if ($node->operator === BinaryOperator::Add) {
            if ($leftForm !== null && $rightValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    $leftForm[0],
                    $leftForm[1] + $rightValue,
                    $leftForm[2],
                );
            }
            if ($rightForm !== null && $leftValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    $rightForm[0],
                    $rightForm[1] + $leftValue,
                    $rightForm[2],
                );
            }
        } elseif ($node->operator === BinaryOperator::Subtract) {
            if ($leftForm !== null && $rightValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    $leftForm[0],
                    $leftForm[1] - $rightValue,
                    $leftForm[2],
                );
            }
            if ($rightForm !== null && $leftValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    -$rightForm[0],
                    $leftValue - $rightForm[1],
                    $rightForm[2],
                );
            }
        } elseif ($node->operator === BinaryOperator::Multiply) {
            if ($leftForm !== null && $rightValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    $leftForm[0] * $rightValue,
                    $leftForm[1] * $rightValue,
                    $leftForm[2],
                );
            }
            if ($rightForm !== null && $leftValue !== null) {
                return $this->finitePolynomialExponentialPhaseForm(
                    $rightForm[0] * $leftValue,
                    $rightForm[1] * $leftValue,
                    $rightForm[2],
                );
            }
        } elseif ($node->operator === BinaryOperator::Divide && $leftForm !== null && $rightValue !== null) {
            if ($rightValue === 0.0) {
                return null;
            }

            return $this->finitePolynomialExponentialPhaseForm(
                $leftForm[0] / $rightValue,
                $leftForm[1] / $rightValue,
                $leftForm[2],
            );
        }

        return null;
    }

    /**
     * @param list<float> $exponent
     * @return array{float, float, list<float>}|null
     */
    private function finitePolynomialExponentialPhaseForm(
        float $scale,
        float $offset,
        array $exponent,
    ): ?array {
        if (!\is_finite($scale) || !\is_finite($offset) || $scale === 0.0 || \count($exponent) < 2) {
            return null;
        }
        foreach ($exponent as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        return [$scale, $offset, $exponent];
    }

    /**
     * @param array{float, float, list<float>} $phase
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveDecayingExponentialPolynomialTrigonometricEquation(
        string $function,
        float $target,
        array $phase,
        float $finiteEndpoint,
        float $lowerBound,
        float $upperBound,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        $maximumExponentResult = $this->polynomialMaximumOnInterval(
            $phase[2],
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($maximumExponentResult === null) {
            return null;
        }
        [$maximumExponent, $criticalPoints] = $maximumExponentResult;
        $exponentialMaximum = \exp($maximumExponent);
        $phaseAtMaximum = ($phase[0] * $exponentialMaximum) + $phase[1];
        if (!\is_finite($phaseAtMaximum) || \abs($phaseAtMaximum) > 1.0E12) {
            return null;
        }
        $phaseMinimum = \min($phase[1], $phaseAtMaximum);
        $phaseMaximum = \max($phase[1], $phaseAtMaximum);
        $periodicTarget = match ($function) {
            'sec', 'csc' => 1.0 / $target,
            default => $target,
        };
        if (!\is_finite($periodicTarget)) {
            return [];
        }

        $bases = [];
        $period = 2.0 * \M_PI;
        if ($function === 'sin' || $function === 'csc') {
            if (\abs($periodicTarget) > 1.0) {
                return [];
            }
            $principal = \asin($periodicTarget);
            $bases = [$principal, \M_PI - $principal];
        } elseif ($function === 'cos' || $function === 'sec') {
            if (\abs($periodicTarget) > 1.0) {
                return [];
            }
            $principal = \acos($periodicTarget);
            $bases = [$principal, -$principal];
        } elseif ($function === 'tan') {
            $period = \M_PI;
            $bases = [\atan($periodicTarget)];
        } elseif ($function === 'cot') {
            $period = \M_PI;
            $bases = [$periodicTarget === 0.0 ? \M_PI / 2.0 : \atan(1.0 / $periodicTarget)];
        } else {
            return null;
        }

        $solutions = [];
        $residualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $candidateScaleAt = function (float $value) use (
            $left,
            $right,
            $rightOffset,
            $variable,
            $parameters,
            $evaluationOptions,
        ): ?float {
            $scale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );

            return $scale === null ? null : \max(1.0, $scale);
        };
        if (\is_finite($finiteEndpoint)) {
            $endpointResidual = $residualAt($finiteEndpoint);
            if (
                $endpointResidual !== null
                && $this->isResidualAcceptableAt(
                    $finiteEndpoint,
                    $endpointResidual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                $this->addSolution(
                    $solutions,
                    new EquationSolution($finiteEndpoint, \abs($endpointResidual), 0),
                    $options,
                );
            }
        }
        $enumeratedLevels = 0;
        foreach ($bases as $base) {
            $firstPeriod = \ceil(($phaseMinimum - $base) / $period);
            $lastPeriod = \floor(($phaseMaximum - $base) / $period);
            if (
                !\is_finite($firstPeriod)
                || !\is_finite($lastPeriod)
                || \abs($firstPeriod) > 4_503_599_627_370_496.0
                || \abs($lastPeriod) > 4_503_599_627_370_496.0
                || $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
            ) {
                return null;
            }
            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                if (++$enumeratedLevels > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $level = $base + ($periodIndex * $period);
                $exponentialLevel = ($level - $phase[1]) / $phase[0];
                if ($exponentialLevel <= 0.0 || !\is_finite($exponentialLevel)) {
                    continue;
                }
                $matchedCriticalExponent = null;
                $polynomialSolver = new PolynomialSolver();
                foreach ($criticalPoints as $criticalPoint) {
                    $criticalExponent = $polynomialSolver->evaluatePolynomial($phase[2], $criticalPoint);
                    if ($criticalExponent === null || !\is_finite($criticalExponent)) {
                        continue;
                    }
                    $criticalPhase = ($phase[0] * \exp($criticalExponent)) + $phase[1];
                    if (
                        !\is_finite($criticalPhase)
                        || \abs($criticalPhase - $level)
                            > 64.0 * \PHP_FLOAT_EPSILON
                                * \max(1.0, \abs($criticalPhase), \abs($level))
                    ) {
                        continue;
                    }
                    $criticalResidual = $residualAt($criticalPoint);
                    if (
                        $criticalResidual !== null
                        && $this->isResidualAcceptableAt(
                            $criticalPoint,
                            $criticalResidual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($criticalPoint, \abs($criticalResidual), 0),
                            $options,
                        );
                        $matchedCriticalExponent ??= $criticalExponent;
                    }
                }
                $targetExponent = $matchedCriticalExponent ?? \log($exponentialLevel);
                if (!\is_finite($targetExponent)) {
                    continue;
                }
                $levelPolynomial = $this->addPolynomials(
                    $phase[2],
                    [$targetExponent],
                    -1.0,
                );
                $rootInterval = $this->polynomialRootSearchInterval(
                    $levelPolynomial,
                    $lowerBound,
                    $upperBound,
                );
                if ($rootInterval === null) {
                    return null;
                }
                $roots = $rootInterval[0] > $rootInterval[1]
                    ? []
                    : $this->solvePolynomialRootsInInterval(
                        $levelPolynomial,
                        $rootInterval[0],
                        $rootInterval[1],
                        $options,
                    );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    $residual = $residualAt($root->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $root->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($root->value, \abs($residual), $root->iterations),
                        $options,
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /** @param list<float> $polynomial */
    private function polynomialTendsToPositiveInfinity(array $polynomial, int $direction): bool
    {
        $degree = \count($polynomial) - 1;
        if ($degree < 1) {
            return false;
        }
        $leadingCoefficient = $polynomial[$degree];
        if ($direction < 0 && $degree % 2 === 1) {
            $leadingCoefficient *= -1.0;
        }

        return $leadingCoefficient > 0.0;
    }

    /**
     * @param list<float> $polynomial
     * @return array{float, list<float>}|null
     */
    private function polynomialMaximumOnInterval(
        array $polynomial,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        $degree = \count($polynomial) - 1;
        if ($degree < 1) {
            return null;
        }
        $derivative = [];
        for ($index = 1; $index <= $degree; ++$index) {
            $derivative[] = $index * $polynomial[$index];
        }
        if (\count($derivative) < 2) {
            $criticalPoints = [];
        } else {
            $criticalInterval = $this->polynomialRootSearchInterval($derivative, $lowerBound, $upperBound);
            if ($criticalInterval === null) {
                return null;
            }
            if ($criticalInterval[0] > $criticalInterval[1]) {
                $criticalPoints = [];
            } else {
                $criticalPoints = $this->solvePolynomialRootsInInterval(
                    $derivative,
                    $criticalInterval[0],
                    $criticalInterval[1],
                    $options,
                );
            }
        }
        if ($criticalPoints === null) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $values = [];
        foreach ([$lowerBound, $upperBound] as $endpoint) {
            if (!\is_finite($endpoint)) {
                continue;
            }
            $value = $polynomialSolver->evaluatePolynomial($polynomial, $endpoint);
            if ($value === null || !\is_finite($value)) {
                return null;
            }
            $values[] = $value;
        }
        foreach ($criticalPoints as $criticalPoint) {
            $value = $polynomialSolver->evaluatePolynomial($polynomial, $criticalPoint->value);
            if ($value === null || !\is_finite($value)) {
                return null;
            }
            $values[] = $value;
        }

        return match (\count($values)) {
            0 => null,
            1 => [$values[0], \array_map(
                static fn (EquationSolution $root): float => $root->value,
                $criticalPoints,
            )],
            default => [\max(...$values), \array_map(
                static fn (EquationSolution $root): float => $root->value,
                $criticalPoints,
            )],
        };
    }

    /**
     * @param list<float> $polynomial
     * @return array{float, float}|null
     */
    private function polynomialRootSearchInterval(
        array $polynomial,
        float $lowerBound,
        float $upperBound,
    ): ?array {
        if (\count($polynomial) < 2) {
            return null;
        }
        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if (!\is_finite($searchLowerBound) || !\is_finite($searchUpperBound)) {
            $leadingMagnitude = \abs($polynomial[\array_key_last($polynomial)]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumCoefficientRatio = 0.0;
            foreach ($polynomial as $index => $coefficient) {
                if ($index === \array_key_last($polynomial)) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumCoefficientRatio = \max($maximumCoefficientRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumCoefficientRatio * (1.0 + 16.0 * \PHP_FLOAT_EPSILON));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $searchLowerBound = \max($searchLowerBound, -$rootBound);
            $searchUpperBound = \min($searchUpperBound, $rootBound);
        }

        return [$searchLowerBound, $searchUpperBound];
    }

    private function invertPositiveBesselJLevel(
        int $order,
        float $target,
        float $maximumArgument,
        float $maximumValue,
    ): float {
        if ($target === 0.0 && $order > 0) {
            return 0.0;
        }
        if ($order === 0 && $target === 1.0) {
            return 0.0;
        }
        if ($target === $maximumValue) {
            return $maximumArgument;
        }

        $lower = 0.0;
        $upper = $maximumArgument;
        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $midpoint = $lower + (($upper - $lower) / 2.0);
            if ($midpoint === $lower || $midpoint === $upper) {
                break;
            }
            $value = SpecialFunctions::besselJ($order, $midpoint);
            if (($order === 0 && $value > $target) || ($order > 0 && $value < $target)) {
                $lower = $midpoint;
            } else {
                $upper = $midpoint;
            }
        }

        return $lower + (($upper - $lower) / 2.0);
    }

    /**
     * Isolate order-zero Bessel levels for affine phases using monotone segments.
     *
     * The brackets are centered at the standard asymptotics for J0/Y0 zeros
     * and their extrema. Extrema partition the positive axis into monotone
     * segments, where each constant level has at most one root.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null Null means the equation shape is unsupported here.
     */
    private function solveOrderZeroBesselLevel(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }

        $leftCall = $this->unwrapGrouping($left);
        $rightCall = $this->unwrapGrouping($right);
        $function = $leftCall instanceof FunctionCallNode
            && \in_array($leftCall->name, ['besselj', 'bessely'], true)
            ? $leftCall
            : ($rightCall instanceof FunctionCallNode
                && \in_array($rightCall->name, ['besselj', 'bessely'], true)
                ? $rightCall
                : null);
        if (
            !$function instanceof FunctionCallNode
            || \count($function->arguments) !== 2
            || !$evaluationOptions->functions->isBuiltIn($function->name)
        ) {
            return null;
        }
        $target = $function === $leftCall ? $right : $left;
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $order = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        $phase = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
        if (
            $targetCoefficients === null
            && !$this->containsVariable($target, $variable)
            && !$this->containsImplicitVariableProduct($target, $variable, $evaluationOptions)
        ) {
            try {
                $targetCoefficients = [(float) $this->evaluateNode($target, $parameters, $evaluationOptions)];
            } catch (EvaluationException) {
                return null;
            }
        }
        if (
            $order !== [0.0]
            || $phase === null
            || \count($phase) < 2
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
            || !\is_finite($targetCoefficients[0])
        ) {
            return null;
        }
        $targetValue = $targetCoefficients[0];

        $phaseRange = $this->polynomialRange($phase, $lowerBound, $upperBound, $solverOptions);
        if ($phaseRange === null) {
            return null;
        }
        $argumentLower = $phaseRange[0];
        $argumentUpper = $phaseRange[1];
        if ($function->name === 'bessely') {
            $argumentLower = \max($argumentLower, \PHP_FLOAT_MIN);
            $argumentUpper = \min($argumentUpper, SpecialFunctions::MAX_BESSEL_Y_ARGUMENT);
        } else {
            $argumentLower = \max($argumentLower, -SpecialFunctions::MAX_BESSEL_J_ARGUMENT);
            $argumentUpper = \min($argumentUpper, SpecialFunctions::MAX_BESSEL_J_ARGUMENT);
        }
        if ($argumentLower > $argumentUpper) {
            return [];
        }

        $maximumPositiveArgument = \max(0.0, $argumentUpper, -$argumentLower);
        $positiveLower = $function->name === 'bessely'
            ? $argumentLower
            : 0.0;
        $positiveUpper = $function->name === 'besselj'
            ? \max(0.0, $argumentUpper, -$argumentLower)
            : $argumentUpper;
        $maximumIndex = (int) \ceil($maximumPositiveArgument / \M_PI) + 2;
        $extrema = [];
        for ($index = 1; $index <= $maximumIndex; ++$index) {
            $center = ($index + ($function->name === 'besselj' ? 0.25 : -0.25)) * \M_PI;
            $bracketLower = \max(0.0, $center - (\M_PI / 4.0));
            $bracketUpper = $center + (\M_PI / 4.0);
            if ($bracketLower > $positiveUpper) {
                continue;
            }
            $fullBracketUpper = $bracketUpper;
            $bracketUpper = \min($bracketUpper, $positiveUpper);
            $extremum = $this->bisectOrderZeroBesselRoot(
                $function->name,
                1,
                0.0,
                $bracketLower,
                $bracketUpper,
            );
            if ($extremum === null) {
                if ($bracketUpper < $fullBracketUpper) {
                    continue;
                }

                return null;
            }
            if ($extremum > $positiveLower && $extremum < $positiveUpper) {
                $extrema[] = $extremum;
            }
        }

        $positivePoints = [$positiveLower, ...$extrema, $positiveUpper];
        \sort($positivePoints, SORT_NUMERIC);
        $positivePoints = \array_values(\array_unique($positivePoints, SORT_REGULAR));
        $positiveLevelRoots = [];
        $levelTolerance = 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($targetValue));
        if (\count($positivePoints) === 1) {
            try {
                if (
                    $this->evaluateOrderZeroBesselLevel($function->name, $positivePoints[0])
                    === $targetValue
                ) {
                    $positiveLevelRoots[] = $positivePoints[0];
                }
            } catch (\DomainException | \OverflowException) {
                return null;
            }
        }
        for ($index = 1, $pointCount = \count($positivePoints); $index < $pointCount; ++$index) {
            $segmentLower = $positivePoints[$index - 1];
            $segmentUpper = $positivePoints[$index];
            try {
                $lowerDifference = $this->evaluateOrderZeroBesselLevel(
                    $function->name,
                    $segmentLower,
                ) - $targetValue;
                $upperDifference = $this->evaluateOrderZeroBesselLevel(
                    $function->name,
                    $segmentUpper,
                ) - $targetValue;
            } catch (\DomainException | \OverflowException) {
                return null;
            }

            $lowerIsExtremum = $index > 1;
            $upperIsExtremum = $index < $pointCount - 1;
            if ($lowerIsExtremum && \abs($lowerDifference) <= $levelTolerance) {
                $positiveLevelRoots[] = $segmentLower;
                continue;
            }
            if ($upperIsExtremum && \abs($upperDifference) <= $levelTolerance) {
                $positiveLevelRoots[] = $segmentUpper;
                continue;
            }
            if ($lowerDifference === 0.0) {
                $positiveLevelRoots[] = $segmentLower;
            }
            if ($upperDifference === 0.0) {
                $positiveLevelRoots[] = $segmentUpper;
            }
            if ($this->hasOppositeSigns($lowerDifference, $upperDifference)) {
                $root = $this->bisectOrderZeroBesselRoot(
                    $function->name,
                    0,
                    $targetValue,
                    $segmentLower,
                    $segmentUpper,
                );
                if ($root === null) {
                    return null;
                }
                $positiveLevelRoots[] = $root;
            }
        }

        $solutions = [];
        foreach ($positiveLevelRoots as $positiveLevelRoot) {
            $argumentLevels = [$positiveLevelRoot];
            if ($function->name === 'besselj' && $positiveLevelRoot !== 0.0) {
                $argumentLevels[] = -$positiveLevelRoot;
            }
            foreach ($argumentLevels as $argumentLevel) {
                if (\count($phase) === 2) {
                    $candidate = ($argumentLevel - $phase[0]) / $phase[1];
                    $this->addOrderZeroBesselCandidate(
                        $solutions,
                        $candidate,
                        $lowerBound,
                        $upperBound,
                        $residualAt,
                        $residualScaleAt,
                        $solverOptions,
                    );
                    continue;
                }

                $phaseLevel = $phase;
                $phaseLevel[0] -= $argumentLevel;
                $polynomialSolver = new PolynomialSolver();
                $phaseRoots = $polynomialSolver->solve(
                    $phaseLevel,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($phaseLevel, $value),
                    $solverOptions,
                    fn (float $value): ?float => $this->polynomialCandidateScaleAt(
                        $phaseLevel,
                        static fn (float $candidate): float => 1.0,
                        $value,
                    ),
                );
                if ($phaseRoots === null) {
                    return null;
                }
                foreach ($phaseRoots as $phaseRoot) {
                    $this->addOrderZeroBesselCandidate(
                        $solutions,
                        $phaseRoot->value,
                        $lowerBound,
                        $upperBound,
                        $residualAt,
                        $residualScaleAt,
                        $solverOptions,
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Isolate integer-order J/Y zeros outside the root-free interval through x=n.
     *
     * For positive integer order, J_n and Y_n have no positive zero on (0,n].
     * Above n, Sturm comparison bounds consecutive zero spacing from below
     * by pi, so unit-width sign brackets cannot skip a positive zero.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null Null means the equation shape is unsupported here.
     */
    private function solvePositiveIntegerOrderBesselZeros(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $leftCall = $this->unwrapGrouping($left);
        $rightCall = $this->unwrapGrouping($right);
        $function = $leftCall instanceof FunctionCallNode
            && \in_array($leftCall->name, ['besselj', 'bessely'], true)
            ? $leftCall
            : ($rightCall instanceof FunctionCallNode
                && \in_array($rightCall->name, ['besselj', 'bessely'], true)
                ? $rightCall
                : null);
        if (
            !$function instanceof FunctionCallNode
            || \count($function->arguments) !== 2
            || !$evaluationOptions->functions->isBuiltIn($function->name)
        ) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $order = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        $phase = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        $target = $function === $leftCall ? $right : $left;
        $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
        if (
            $order === null
            || \count($order) !== 1
            || !\is_finite($order[0])
            || \floor($order[0]) !== $order[0]
            || $order[0] === 0.0
            || \abs($order[0]) > SpecialFunctions::MAX_BESSEL_ORDER
            || $phase === null
            || \count($phase) < 2
            || $targetCoefficients !== [0.0]
        ) {
            return null;
        }

        $canonicalOrder = \abs((int) $order[0]);
        $phaseRange = $this->polynomialRange($phase, $lowerBound, $upperBound, $solverOptions);
        if ($phaseRange === null) {
            return null;
        }
        $phaseLower = $function->name === 'bessely'
            ? \max($phaseRange[0], \PHP_FLOAT_MIN)
            : \max($phaseRange[0], -SpecialFunctions::MAX_BESSEL_J_ARGUMENT);
        $phaseUpper = $function->name === 'bessely'
            ? \min($phaseRange[1], SpecialFunctions::MAX_BESSEL_Y_ARGUMENT)
            : \min($phaseRange[1], SpecialFunctions::MAX_BESSEL_J_ARGUMENT);
        if ($phaseLower > $phaseUpper) {
            return [];
        }

        $maximumPositiveArgument = $function->name === 'bessely'
            ? $phaseUpper
            : \max(0.0, $phaseUpper, -$phaseLower);
        $positiveZeros = [];
        if (
            $function->name === 'besselj'
            && $phaseLower <= 0.0
            && $phaseUpper >= 0.0
        ) {
            $positiveZeros[] = 0.0;
        }
        if ($maximumPositiveArgument > $canonicalOrder) {
            $scanStart = \max((float) $canonicalOrder, $phaseLower);
            $steps = (int) \ceil($maximumPositiveArgument - $scanStart);
            $previousArgument = $scanStart;
            $previousValue = $function->name === 'besselj'
                ? SpecialFunctions::besselJ($canonicalOrder, $previousArgument)
                : SpecialFunctions::besselY($canonicalOrder, $previousArgument);
            for ($step = 1; $step <= $steps; ++$step) {
                $argument = \min(
                    $maximumPositiveArgument,
                    $scanStart + (float) $step,
                );
                $value = $function->name === 'besselj'
                    ? SpecialFunctions::besselJ($canonicalOrder, $argument)
                    : SpecialFunctions::besselY($canonicalOrder, $argument);
                if ($value === 0.0) {
                    $positiveZeros[] = $argument;
                } elseif ($this->hasOppositeSigns($previousValue, $value)) {
                    $zero = $this->bisectOrderZeroBesselRoot(
                        $function->name,
                        $canonicalOrder,
                        0.0,
                        $previousArgument,
                        $argument,
                    );
                    if ($zero === null) {
                        return null;
                    }
                    $positiveZeros[] = $zero;
                }
                $previousArgument = $argument;
                $previousValue = $value;
            }
        }

        $levels = [];
        foreach ($positiveZeros as $zero) {
            if ($zero >= $phaseLower && $zero <= $phaseUpper) {
                $levels[] = $zero;
            }
            if (
                $function->name === 'besselj'
                && $zero !== 0.0
                && -$zero >= $phaseLower
                && -$zero <= $phaseUpper
            ) {
                $levels[] = -$zero;
            }
        }

        $solutions = [];
        foreach ($levels as $level) {
            if (\count($phase) === 2) {
                if ($phase[1] === 0.0) {
                    return null;
                }
                $candidates = [($level - $phase[0]) / $phase[1]];
            } else {
                $levelCoefficients = $phase;
                $levelCoefficients[0] -= $level;
                $polynomialSolver = new PolynomialSolver();
                $phaseRoots = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($levelCoefficients, $value),
                    $solverOptions,
                    fn (float $value): ?float => $this->polynomialCandidateScaleAt(
                        $levelCoefficients,
                        static fn (float $candidate): float => 1.0,
                        $value,
                    ),
                );
                if ($phaseRoots === null) {
                    return null;
                }
                $candidates = \array_map(
                    static fn (EquationSolution $root): float => $root->value,
                    $phaseRoots,
                );
            }
            foreach ($candidates as $candidate) {
                $this->addOrderZeroBesselCandidate(
                    $solutions,
                    $candidate,
                    $lowerBound,
                    $upperBound,
                    $residualAt,
                    $residualScaleAt,
                    $solverOptions,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function bisectOrderZeroBesselRoot(
        string $name,
        int $order,
        float $target,
        float $lower,
        float $upper,
    ): ?float {
        $function = static fn (float $value): float => $name === 'besselj'
            ? SpecialFunctions::besselJ($order, $value) - $target
            : SpecialFunctions::besselY($order, $value) - $target;
        try {
            $lowerValue = $function($lower);
            $upperValue = $function($upper);
        } catch (\DomainException | \OverflowException) {
            return null;
        }
        if ($lowerValue === 0.0) {
            return $lower;
        }
        if ($upperValue === 0.0) {
            return $upper;
        }
        if (!$this->hasOppositeSigns($lowerValue, $upperValue)) {
            return null;
        }

        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $midpoint = $lower + (($upper - $lower) / 2.0);
            if ($midpoint === $lower || $midpoint === $upper) {
                break;
            }
            try {
                $midpointValue = $function($midpoint);
            } catch (\DomainException | \OverflowException) {
                return null;
            }
            if ($midpointValue === 0.0) {
                return $midpoint;
            }
            if ($this->hasOppositeSigns($lowerValue, $midpointValue)) {
                $upper = $midpoint;
                $upperValue = $midpointValue;
            } else {
                $lower = $midpoint;
                $lowerValue = $midpointValue;
            }
        }

        return $lower + (($upper - $lower) / 2.0);
    }

    private function evaluateOrderZeroBesselLevel(string $name, float $argument): float
    {
        return $name === 'besselj'
            ? SpecialFunctions::besselJ(0, $argument)
            : SpecialFunctions::besselY(0, $argument);
    }

    /**
     * @param list<EquationSolution> $solutions
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     */
    private function addOrderZeroBesselCandidate(
        array &$solutions,
        float $candidate,
        float $lowerBound,
        float $upperBound,
        callable $residualAt,
        callable $residualScaleAt,
        SolverOptions $solverOptions,
    ): void {
        if ($candidate < $lowerBound || $candidate > $upperBound || !\is_finite($candidate)) {
            return;
        }
        $residual = $residualAt($candidate);
        $scale = $residualScaleAt($candidate);
        if (
            $residual === null
            || $scale === null
            || !$this->isResidualAcceptableAt(
                $candidate,
                $residual,
                static fn (float $value): float => \max(1.0, $scale),
                $solverOptions,
            )
        ) {
            return;
        }
        $this->addSolution(
            $solutions,
            new EquationSolution($candidate, \abs($residual), 0),
            $solverOptions,
        );
    }

    /**
     * Isolate integer-order Bessel J levels on certified monotone input ranges.
     * J0 is even and strictly decreasing on [0, 3.8], by the alternating
     * series lower bound for J1. For n >= 1, keeping the first derivative
     * series term ratio t(n+2)/(n(n+1)) <= 1, where t=x^2/4, makes the
     * alternating derivative series positive. Parity handles negative inputs
     * and negative integer orders. The Bessel differential equation also
     * gives positivity and increase through x=n for n>0, extending the
     * monotone interval when n exceeds the alternating-series bound.
     * Inverting the level reduces the equation to polynomial level equations.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveFiniteBesselJPolynomialLevel(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $leftCall = $this->unwrapGrouping($left);
        $rightCall = $this->unwrapGrouping($right);
        $leftBesselPhaseDependsOnVariable = $leftCall instanceof FunctionCallNode
            && $leftCall->name === 'besselj'
            && isset($leftCall->arguments[1])
            && $this->containsVariable($leftCall->arguments[1], $variable);
        $rightBesselPhaseDependsOnVariable = $rightCall instanceof FunctionCallNode
            && $rightCall->name === 'besselj'
            && isset($rightCall->arguments[1])
            && $this->containsVariable($rightCall->arguments[1], $variable);
        $function = $leftBesselPhaseDependsOnVariable && !$rightBesselPhaseDependsOnVariable
            ? $leftCall
            : ($rightBesselPhaseDependsOnVariable && !$leftBesselPhaseDependsOnVariable
                ? $rightCall
                : ($leftBesselPhaseDependsOnVariable
                    ? null
                    : ($leftCall instanceof FunctionCallNode && $leftCall->name === 'besselj'
                        ? $leftCall
                        : ($rightCall instanceof FunctionCallNode && $rightCall->name === 'besselj'
                            ? $rightCall
                            : null))));
        if (
            !$function instanceof FunctionCallNode
            || \count($function->arguments) !== 2
            || !$evaluationOptions->functions->isBuiltIn('besselj')
        ) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $order = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        $phase = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        $target = $function === $leftCall ? $right : $left;
        $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
        if (
            $targetCoefficients === null
            && !$this->containsVariable($target, $variable)
            && !$this->containsImplicitVariableProduct($target, $variable, $evaluationOptions)
        ) {
            try {
                $targetCoefficients = [(float) $this->evaluateNode($target, $parameters, $evaluationOptions)];
            } catch (EvaluationException) {
                return null;
            }
        }
        if (
            $order === null
            || \count($order) !== 1
            || !\is_finite($order[0])
            || \floor($order[0]) !== $order[0]
            || \abs($order[0]) > SpecialFunctions::MAX_BESSEL_ORDER
            || $phase === null
            || \count($phase) < 2
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
            || !\is_finite($targetCoefficients[0])
        ) {
            return null;
        }

        $integerOrder = (int) $order[0];
        $canonicalOrder = \abs($integerOrder);
        $orderSign = $integerOrder < 0 && ($canonicalOrder & 1) === 1 ? -1.0 : 1.0;

        $phaseRange = $this->polynomialRange($phase, $lowerBound, $upperBound, $solverOptions);
        if ($phaseRange === null) {
            return null;
        }
        $phaseMinimum = $phaseRange[0];
        $phaseMaximum = $phaseRange[1];
        $seriesMonotoneLimit = $canonicalOrder === 0
            ? self::BESSEL_J0_MONOTONE_LIMIT
            : (2.0 * \sqrt(
                ($canonicalOrder * ($canonicalOrder + 1.0)) / ($canonicalOrder + 2.0),
            )) * (1.0 - (16.0 * \PHP_FLOAT_EPSILON));
        $monotoneLimit = \max($seriesMonotoneLimit, (float) $canonicalOrder);
        if ($phaseMinimum < -$monotoneLimit || $phaseMaximum > $monotoneLimit) {
            return null;
        }

        $maximumMagnitude = \max(\abs($phaseMinimum), \abs($phaseMaximum));
        if ($maximumMagnitude === 0.0) {
            return null;
        }
        $targetValue = $targetCoefficients[0] * $orderSign;
        $maximumBesselValue = SpecialFunctions::besselJ($canonicalOrder, $maximumMagnitude);
        if ($canonicalOrder === 0) {
            if ($targetValue > 1.0 || $targetValue < $maximumBesselValue) {
                return [];
            }
            $levelMagnitude = $this->invertPositiveBesselJLevel(
                $canonicalOrder,
                $targetValue,
                $maximumMagnitude,
                $maximumBesselValue,
            );
            $levelValues = $levelMagnitude === 0.0
                ? [0.0]
                : [$levelMagnitude, -$levelMagnitude];
        } elseif (($canonicalOrder & 1) === 1) {
            $targetMagnitude = \abs($targetValue);
            if ($targetMagnitude > $maximumBesselValue) {
                return [];
            }
            $levelMagnitude = $this->invertPositiveBesselJLevel(
                $canonicalOrder,
                $targetMagnitude,
                $maximumMagnitude,
                $maximumBesselValue,
            );
            $levelValues = [$targetValue < 0.0 ? -$levelMagnitude : $levelMagnitude];
        } else {
            if ($targetValue < 0.0 || $targetValue > $maximumBesselValue) {
                return [];
            }
            $levelMagnitude = $this->invertPositiveBesselJLevel(
                $canonicalOrder,
                $targetValue,
                $maximumMagnitude,
                $maximumBesselValue,
            );
            $levelValues = $levelMagnitude === 0.0
                ? [0.0]
                : [$levelMagnitude, -$levelMagnitude];
        }
        $solutions = [];
        $polynomialSolver = new PolynomialSolver();
        foreach ($levelValues as $levelValue) {
            $equationCoefficients = $phase;
            $equationCoefficients[0] -= $levelValue;
            if (\count(\array_filter($equationCoefficients, static fn (float $value): bool => $value !== 0.0)) === 0) {
                return null;
            }
            $phaseRoots = $polynomialSolver->solve(
                $equationCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $this->polynomialValue($equationCoefficients, $value),
                $solverOptions,
                fn (float $value): ?float => $this->polynomialCandidateScaleAt(
                    $equationCoefficients,
                    static fn (float $candidate): float => 1.0,
                    $value,
                ),
            );
            if ($phaseRoots === null) {
                return null;
            }
            foreach ($phaseRoots as $phaseRoot) {
                $residual = $residualAt($phaseRoot->value);
                $residualScale = $residualScaleAt($phaseRoot->value);
                if (
                    $residual === null
                    || $residualScale === null
                    || !$this->isResidualAcceptableAt(
                        $phaseRoot->value,
                        $residual,
                        static fn (float $value): float => \max(
                            $residualScale,
                            \abs($targetValue),
                            1.0,
                        ),
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $phaseRoot->value == 0.0 ? 0.0 : $phaseRoot->value,
                        \abs($residual),
                        $phaseRoot->iterations,
                    ),
                    $solverOptions,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve Bessel J/Y zero levels over the finite domain of their evaluators.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null Null means the equation shape is unsupported here.
     */
    private function solveUnboundedBesselZeroEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $leftSource,
        string $rightSource,
        string $equation,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $leftCall = $this->unwrapGrouping($left);
        while ($leftCall instanceof UnaryOperationNode) {
            $leftCall = $this->unwrapGrouping($leftCall->operand);
        }
        $rightCall = $this->unwrapGrouping($right);
        while ($rightCall instanceof UnaryOperationNode) {
            $rightCall = $this->unwrapGrouping($rightCall->operand);
        }
        if (
            $leftCall instanceof FunctionCallNode
            && \in_array($leftCall->name, ['besselj', 'bessely'], true)
        ) {
            $function = $leftCall;
            $target = $right;
        } elseif (
            $rightCall instanceof FunctionCallNode
            && \in_array($rightCall->name, ['besselj', 'bessely'], true)
        ) {
            $function = $rightCall;
            $target = $left;
        } else {
            return null;
        }
        if (
            \count($function->arguments) !== 2
            || !$evaluationOptions->functions->isBuiltIn($function->name)
        ) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $target,
            $target->span()->start,
        );
        $orderCoefficients = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        $phaseCoefficients = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        if (
            $targetCoefficients !== [0.0]
            || $orderCoefficients === null
            || \count($orderCoefficients) !== 1
            || !\is_finite($orderCoefficients[0])
            || \floor($orderCoefficients[0]) !== $orderCoefficients[0]
            || \abs($orderCoefficients[0]) > SpecialFunctions::MAX_BESSEL_ORDER
            || $phaseCoefficients === null
        ) {
            return null;
        }

        while (\count($phaseCoefficients) > 1 && $phaseCoefficients[\array_key_last($phaseCoefficients)] === 0.0) {
            \array_pop($phaseCoefficients);
        }
        $degree = \count($phaseCoefficients) - 1;
        if ($degree === 0) {
            $probe = \is_finite($lowerBound)
                ? $lowerBound
                : (\is_finite($upperBound) ? $upperBound : 0.0);
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $probe,
                $parameters,
                $evaluationOptions,
            );
            if ($residual === null) {
                return [];
            }
            $scale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $probe,
                $parameters,
                $evaluationOptions,
            );
            if (
                $scale !== null
                && $this->isResidualAcceptableAt(
                    $probe,
                    $residual,
                    static fn (float $value): float => $scale,
                    $solverOptions,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'The unbounded Bessel equation is an identity and has infinitely many solutions.',
                );
            }

            return [];
        }

        $leadingCoefficient = $phaseCoefficients[$degree] ?? null;
        if ($leadingCoefficient === null) {
            return null;
        }
        if (!\is_finite($leadingCoefficient) || $leadingCoefficient === 0.0) {
            return null;
        }
        $functionIsLeft = $leftCall === $function;
        $functionSource = $functionIsLeft ? $leftSource : $rightSource;
        $functionSourceOffset = $functionIsLeft ? 0 : $rightOffset;
        $phase = $function->arguments[1];
        $phaseSpan = $phase->span();
        $phaseSource = \substr(
            $functionSource,
            $phaseSpan->start - $functionSourceOffset,
            $phaseSpan->end - $phaseSpan->start,
        );
        if ($phaseSource === '') {
            return null;
        }

        $minimumArgument = $function->name === 'besselj' ? -SpecialFunctions::MAX_BESSEL_J_ARGUMENT : 0.0;
        $maximumArgument = $function->name === 'besselj'
            ? SpecialFunctions::MAX_BESSEL_J_ARGUMENT
            : SpecialFunctions::MAX_BESSEL_Y_ARGUMENT;
        $maximumRootBound = 0.0;
        foreach ([$minimumArgument, $maximumArgument] as $level) {
            $boundaryCoefficients = $phaseCoefficients;
            $boundaryCoefficients[0] -= $level;
            $leadingMagnitude = \abs($boundaryCoefficients[\array_key_last($boundaryCoefficients)]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumRatio = 0.0;
            foreach ($boundaryCoefficients as $degree => $coefficient) {
                if ($degree === \array_key_last($boundaryCoefficients)) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $maximumRootBound = \max($maximumRootBound, $rootBound);
        }

        $searchLowerBound = \max($lowerBound, -$maximumRootBound);
        $searchUpperBound = \min($upperBound, $maximumRootBound);
        if ($searchLowerBound > $searchUpperBound) {
            return [];
        }
        if ($searchLowerBound === $searchUpperBound) {
            return $this->solve(
                $equation,
                $variable,
                $searchLowerBound,
                $searchUpperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }

        $inequalitySolver = new InequalitySolver();
        $aboveMinimum = $inequalitySolver->solve(
            '(' . $phaseSource . ')' . ($function->name === 'bessely' ? '>' : '>=')
                . \sprintf('%.17g', $minimumArgument),
            $variable,
            $searchLowerBound,
            $searchUpperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        $belowMaximum = $inequalitySolver->solve(
            '(' . $phaseSource . ')<=' . \sprintf('%.17g', $maximumArgument),
            $variable,
            $searchLowerBound,
            $searchUpperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );

        $solutions = [];
        foreach ($aboveMinimum as $minimumInterval) {
            foreach ($belowMaximum as $maximumInterval) {
                $intervalLower = \max($minimumInterval->lowerBound, $maximumInterval->lowerBound);
                $intervalUpper = \min($minimumInterval->upperBound, $maximumInterval->upperBound);
                $includesLower = ($intervalLower !== $minimumInterval->lowerBound
                        || $minimumInterval->includesLowerBound)
                    && ($intervalLower !== $maximumInterval->lowerBound
                        || $maximumInterval->includesLowerBound);
                $includesUpper = ($intervalUpper !== $minimumInterval->upperBound
                        || $minimumInterval->includesUpperBound)
                    && ($intervalUpper !== $maximumInterval->upperBound
                        || $maximumInterval->includesUpperBound);
                if (
                    $intervalLower > $intervalUpper
                    || ($intervalLower === $intervalUpper && (!$includesLower || !$includesUpper))
                ) {
                    continue;
                }
                foreach (
                    $this->solve(
                        $equation,
                        $variable,
                        $intervalLower,
                        $intervalUpper,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ) as $solution
                ) {
                    $this->addSolution($solutions, $solution, $solverOptions);
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reuse inverse-level reductions before rejecting non-rational unbounded equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null Null means the equation shape is unsupported here.
     */
    /**
     * Isolate roots of logarithms of polynomial arguments by partitioning at
     * argument zeros and every critical point of the logarithmic residual.
     *
     * @param list<float> $argument
     * @param list<float> $target
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @param list<float> $positiveDomainBoundaries
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialLogTarget(
        array $argument,
        array $target,
        float $logarithmScale,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
        bool $positiveDomainCertified = false,
        array $positiveDomainBoundaries = [],
        bool $discardCandidatesOutsideOriginalDomain = false,
    ): ?array {
        if (!\is_finite($logarithmScale) || $logarithmScale === 0.0) {
            return null;
        }
        while (\count($argument) > 1 && $argument[\array_key_last($argument)] === 0.0) {
            \array_pop($argument);
        }
        while (\count($target) > 1 && $target[\array_key_last($target)] === 0.0) {
            \array_pop($target);
        }
        if (\count($argument) < 2 || $target === []) {
            return null;
        }

        $domainLower = $lowerBound;
        $domainUpper = $upperBound;
        $domainBoundary = null;
        if (\count($argument) === 2) {
            $slope = $argument[1];
            $domainBoundary = -$argument[0] / $slope;
            if (!\is_finite($domainBoundary)) {
                return null;
            }
            if ($slope > 0.0) {
                $domainLower = \max($domainLower, $domainBoundary);
            } else {
                $domainUpper = \min($domainUpper, $domainBoundary);
            }
        } elseif (!$positiveDomainCertified) {
            $argumentDegree = \count($argument) - 1;
            $argumentLeadingMagnitude = \abs($argument[$argumentDegree]);
            if ($argumentLeadingMagnitude === 0.0 || !\is_finite($argumentLeadingMagnitude)) {
                return null;
            }
            $argumentMaximumRatio = 0.0;
            foreach ($argument as $degree => $coefficient) {
                if ($degree === $argumentDegree) {
                    continue;
                }
                $ratio = \abs($coefficient) / $argumentLeadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $argumentMaximumRatio = \max($argumentMaximumRatio, $ratio);
            }
            $argumentRootBound = 1.0 + ($argumentMaximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
            if (!\is_finite($argumentRootBound)) {
                return null;
            }
            $argumentRootBound = $this->adjacentFloat($argumentRootBound, 1) ?? $argumentRootBound;
            $argumentSolver = new PolynomialSolver();
            $argumentRoots = $argumentSolver->solve(
                $argument,
                -$argumentRootBound,
                $argumentRootBound,
                static fn (float $value): ?float =>
                    $argumentSolver->evaluatePolynomial($argument, $value),
                $solverOptions,
                static fn (float $value): ?float =>
                    $argumentSolver->evaluatePolynomialMagnitude($argument, $value),
            );
            if ($argumentRoots === null) {
                return null;
            }
            $positiveDomainBoundaries = \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $argumentRoots,
            );
            $partitionPoints = [-\INF, ...$positiveDomainBoundaries, \INF];
            $domainSolutions = [];
            for ($index = 1, $count = \count($partitionPoints); $index < $count; ++$index) {
                $segmentLower = $partitionPoints[$index - 1];
                $segmentUpper = $partitionPoints[$index];
                $sample = match (true) {
                    \is_infinite($segmentLower) && \is_infinite($segmentUpper) => 0.0,
                    \is_infinite($segmentLower) => $segmentUpper - \max(1.0, 0.5 * \abs($segmentUpper)),
                    \is_infinite($segmentUpper) => $segmentLower + \max(1.0, 0.5 * \abs($segmentLower)),
                    default => (0.5 * $segmentLower) + (0.5 * $segmentUpper),
                };
                $sampleValue = $argumentSolver->evaluatePolynomial($argument, $sample);
                if ($sampleValue === null || $sampleValue <= 0.0) {
                    continue;
                }
                $segmentLower = \max($segmentLower, $lowerBound);
                $segmentUpper = \min($segmentUpper, $upperBound);
                if ($segmentLower >= $segmentUpper) {
                    continue;
                }
                $segmentSolutions = $this->solveUnboundedPolynomialLogTarget(
                    $argument,
                    $target,
                    $logarithmScale,
                    $variable,
                    $segmentLower,
                    $segmentUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $residualAt,
                    $candidateScaleAt,
                    true,
                    $positiveDomainBoundaries,
                    $discardCandidatesOutsideOriginalDomain,
                );
                if ($segmentSolutions === null) {
                    return null;
                }
                foreach ($segmentSolutions as $solution) {
                    $this->addSolution($domainSolutions, $solution, $solverOptions);
                }
            }
            \usort(
                $domainSolutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $domainSolutions;
        }
        if ($domainLower > $domainUpper) {
            return [];
        }

        $argumentDerivative = $this->polynomialDerivative($argument);
        $targetDerivative = $this->polynomialDerivative($target);
        $argumentTimesDerivative = $this->multiplyPolynomials($argument, $targetDerivative);
        $scaledProduct = $this->scalePolynomialCoefficients(
            $argumentTimesDerivative,
            $logarithmScale,
        );
        if ($scaledProduct === null) {
            return null;
        }
        $criticalPolynomial = $this->subtractScaledPolynomials(
            $argumentDerivative,
            $scaledProduct,
            1.0,
        );
        if ($criticalPolynomial === null) {
            return null;
        }
        while (
            \count($criticalPolynomial) > 1
            && $criticalPolynomial[\array_key_last($criticalPolynomial)] === 0.0
        ) {
            \array_pop($criticalPolynomial);
        }
        if ($criticalPolynomial === [0.0]) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $criticalPoints = [];
        if (\count($criticalPolynomial) > 1) {
            $leadingMagnitude = \abs($criticalPolynomial[\array_key_last($criticalPolynomial)]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumRatio = 0.0;
            foreach ($criticalPolynomial as $degree => $coefficient) {
                if ($degree === \array_key_last($criticalPolynomial)) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
            $rootLower = \is_finite($domainLower) ? \max($domainLower, -$rootBound) : -$rootBound;
            $rootUpper = \is_finite($domainUpper) ? \min($domainUpper, $rootBound) : $rootBound;
            if ($rootLower <= $rootUpper) {
                $polynomialSolver = new PolynomialSolver();
                $criticalSolutions = $polynomialSolver->solve(
                    $criticalPolynomial,
                    $rootLower,
                    $rootUpper,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($criticalPolynomial, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($criticalPolynomial, $value),
                );
                if ($criticalSolutions === null) {
                    return null;
                }
                foreach ($criticalSolutions as $criticalSolution) {
                    $value = $criticalSolution->value;
                    if (
                        $value <= $domainLower
                        || $value >= $domainUpper
                        || ($argumentValue = $polynomialSolver->evaluatePolynomial($argument, $value)) === null
                        || $argumentValue <= 0.0
                    ) {
                        continue;
                    }
                    $criticalPoints[] = $value;
                }
            }
        }

        \sort($criticalPoints, SORT_NUMERIC);
        $distinctCriticalPoints = [];
        foreach ($criticalPoints as $point) {
            $previous = \array_key_last($distinctCriticalPoints);
            if (
                $previous !== null
                && \abs($point - $distinctCriticalPoints[$previous])
                    <= $solverOptions->positionTolerance($point, $distinctCriticalPoints[$previous])
            ) {
                continue;
            }
            $distinctCriticalPoints[] = $point;
        }

        $logResidualAt = function (float $value) use (
            $argument,
            $target,
            $logarithmScale,
            $polynomialSolver,
        ): ?float {
            $argumentValue = $polynomialSolver->evaluatePolynomial($argument, $value);
            $targetValue = $polynomialSolver->evaluatePolynomial($target, $value);
            if (
                $argumentValue === null
                || $argumentValue <= 0.0
                || !\is_finite($argumentValue)
                || $targetValue === null
            ) {
                return null;
            }
            $residual = (\log($argumentValue) / $logarithmScale) - $targetValue;

            return \is_finite($residual) ? $residual : null;
        };
        $logResidualScaleAt = function (float $value) use (
            $argument,
            $target,
            $logarithmScale,
            $polynomialSolver,
        ): ?float {
            $argumentValue = $polynomialSolver->evaluatePolynomial($argument, $value);
            $targetValue = $polynomialSolver->evaluatePolynomial($target, $value);
            if (
                $argumentValue === null
                || $argumentValue <= 0.0
                || !\is_finite($argumentValue)
                || $targetValue === null
            ) {
                return null;
            }

            return \max(1.0, \abs(\log($argumentValue) / $logarithmScale), \abs($targetValue));
        };
        $tailSign = static function (int $direction) use ($target, $logarithmScale): int {
            $degree = \count($target) - 1;
            if ($degree === 0) {
                return $logarithmScale > 0.0 ? 1 : -1;
            }
            $polynomialSign = $target[$degree] > 0.0 ? 1 : -1;
            if ($direction < 0 && $degree % 2 !== 0) {
                $polynomialSign *= -1;
            }

            return -$polynomialSign;
        };
        $boundarySign = $logarithmScale > 0.0 ? -1 : 1;
        $makeEndpoint = function (float $value) use (
            $domainBoundary,
            $positiveDomainBoundaries,
            $boundarySign,
            $tailSign,
            $logResidualAt,
        ): ?array {
            if (\is_infinite($value)) {
                $direction = $value < 0.0 ? -1 : 1;

                return [
                    'value' => $value,
                    'residual' => $tailSign($direction) * \PHP_FLOAT_MAX,
                    'sign' => $tailSign($direction),
                    'kind' => 'tail',
                ];
            }
            if (
                $value === $domainBoundary
                || \in_array($value, $positiveDomainBoundaries, true)
            ) {
                return [
                    'value' => $value,
                    'residual' => $boundarySign * \PHP_FLOAT_MAX,
                    'sign' => $boundarySign,
                    'kind' => 'boundary',
                ];
            }
            $residual = $logResidualAt($value);
            if ($residual === null) {
                return null;
            }

            return [
                'value' => $value,
                'residual' => $residual,
                'sign' => $residual <=> 0.0,
                'kind' => 'finite',
            ];
        };

        $points = [$domainLower, ...$distinctCriticalPoints, $domainUpper];
        $endpoints = [];
        foreach ($points as $point) {
            $endpoint = $makeEndpoint($point);
            if ($endpoint === null) {
                return null;
            }
            $endpoints[] = $endpoint;
        }

        $solutions = [];
        $addOriginalCandidate = function (
            float $value,
            int $iterations,
        ) use (
            &$solutions,
            $residualAt,
            $candidateScaleAt,
            $lowerBound,
            $upperBound,
            $solverOptions,
        ): bool {
            $residual = $residualAt($value);
            if ($residual === null) {
                return false;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $solverOptions)
            ) {
                return false;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $iterations),
                $solverOptions,
            );

            return true;
        };

        foreach ($endpoints as $endpoint) {
            if ($endpoint['kind'] === 'finite' && $endpoint['residual'] === 0.0) {
                $addOriginalCandidate($endpoint['value'], 0);
            }
        }
        foreach ($distinctCriticalPoints as $criticalPoint) {
            $criticalResidual = $logResidualAt($criticalPoint);
            $criticalScale = $logResidualScaleAt($criticalPoint);
            if (
                $criticalResidual !== null
                && $criticalScale !== null
                && \abs($criticalResidual)
                    <= $solverOptions->residualTolerance * $criticalScale
            ) {
                $addOriginalCandidate($criticalPoint, 0);
            }
        }

        for ($index = 1, $count = \count($endpoints); $index < $count; ++$index) {
            $left = $endpoints[$index - 1];
            $right = $endpoints[$index];
            if ($left['sign'] === 0 || $right['sign'] === 0 || $left['sign'] === $right['sign']) {
                continue;
            }
            if ($left['kind'] === 'tail' || $right['kind'] === 'tail') {
                if ($left['kind'] === 'tail' && $right['kind'] === 'tail') {
                    $centerResidual = $logResidualAt(0.0);
                    if ($centerResidual === null) {
                        return null;
                    }
                    $centerSign = $centerResidual <=> 0.0;
                    if ($centerSign === 0) {
                        $addOriginalCandidate(0.0, 0);
                        continue;
                    }
                    $tail = $centerSign === $left['sign'] ? $right : $left;
                    $finite = [
                        'value' => 0.0,
                        'residual' => $centerResidual,
                        'sign' => $centerSign,
                        'kind' => 'finite',
                    ];
                } else {
                    $tail = $left['kind'] === 'tail' ? $left : $right;
                    $finite = $left['kind'] === 'tail' ? $right : $left;
                }
                $direction = $tail['value'] < 0.0 ? -1 : 1;
                $cursor = $finite['value'];
                $cursorResidual = $finite['residual'];
                $cursorSign = $finite['sign'];
                $step = $finite['kind'] === 'boundary'
                    ? \max(1.0E-8, 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($cursor)))
                    : \max(1.0, 0.5 * \abs($cursor));
                $bracket = null;
                for ($iteration = 0; $iteration < $solverOptions->maxIterations; ++$iteration) {
                    $next = $cursor + ($direction * $step);
                    if (!\is_finite($next) || $next === $cursor) {
                        break;
                    }
                    $nextResidual = $logResidualAt($next);
                    if ($nextResidual === null) {
                        $step *= 0.5;
                        continue;
                    }
                    $nextSign = $nextResidual <=> 0.0;
                    if ($nextSign === 0 || $nextSign !== $cursorSign) {
                        $bracket = [$cursor, $cursorResidual, $next, $nextResidual];
                        break;
                    }
                    if ($nextSign === $tail['sign']) {
                        break;
                    }
                    $cursor = $next;
                    $cursorResidual = $nextResidual;
                    $cursorSign = $nextSign;
                    $step *= 2.0;
                }
                if ($bracket === null) {
                    continue;
                }
                [$bracketLeft, $bracketLeftResidual, $bracketRight, $bracketRightResidual] = $bracket;
                if ($bracketLeft > $bracketRight) {
                    [$bracketLeft, $bracketRight] = [$bracketRight, $bracketLeft];
                    [$bracketLeftResidual, $bracketRightResidual] = [$bracketRightResidual, $bracketLeftResidual];
                }
            } else {
                $bracketLeft = $left['value'];
                $bracketLeftResidual = $left['residual'];
                $bracketRight = $right['value'];
                $bracketRightResidual = $right['residual'];
            }

            $hasExactBracketRoot = false;
            $bracketEndpoints = [
                [$bracketLeft, $bracketLeftResidual],
                [$bracketRight, $bracketRightResidual],
            ];
            foreach ($bracketEndpoints as [$bracketValue, $bracketResidual]) {
                if ($bracketResidual !== 0.0) {
                    continue;
                }
                if (!$addOriginalCandidate($bracketValue, 0)) {
                    return null;
                }
                $hasExactBracketRoot = true;
            }
            if ($hasExactBracketRoot) {
                continue;
            }
            if (!$this->hasOppositeSigns($bracketLeftResidual, $bracketRightResidual)) {
                continue;
            }
            $bracketSolutions = $this->bisect(
                $logResidualAt,
                $bracketLeft,
                $bracketLeftResidual,
                $bracketRight,
                $solverOptions,
                $logResidualScaleAt,
                static fn (float $value): bool => false,
            );
            if ($bracketSolutions === []) {
                return null;
            }
            foreach ($bracketSolutions as $bracketSolution) {
                if (!$addOriginalCandidate($bracketSolution->value, $bracketSolution->iterations)) {
                    if (!$discardCandidatesOutsideOriginalDomain) {
                        return null;
                    }
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveMonotoneAffineLogRationalTarget(
        Node $argument,
        Node $target,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
        float $logarithmScale = 1.0,
        float $argumentOffset = 0.0,
    ): ?array {
        $argumentCoefficients = $extractor->extract($argument);
        $targetForm = $extractor->extractRationalForm($target);
        $maximumRationalDegree = \min(16, \intdiv($options->maxPolynomialDegree, 2));
        if (
            $argumentCoefficients === null
            || \count($argumentCoefficients) !== 2
            || $argumentCoefficients[1] === 0.0
            || !\is_finite($argumentCoefficients[0])
            || !\is_finite($argumentCoefficients[1])
            || !\is_finite($logarithmScale)
            || $logarithmScale === 0.0
            || !\is_finite($argumentOffset)
            || $targetForm === null
            || \count($targetForm[0]) > $maximumRationalDegree + 1
            || \count($targetForm[1]) > $maximumRationalDegree + 1
        ) {
            return null;
        }
        $argumentCoefficients[0] += $argumentOffset;
        if (!\is_finite($argumentCoefficients[0])) {
            return null;
        }

        [$numerator, $denominator] = $targetForm;
        foreach ($numerator as $degree => $coefficient) {
            $numerator[$degree] = $coefficient * $logarithmScale;
            if (!\is_finite($numerator[$degree])) {
                return null;
            }
        }
        if (\count(\array_filter($denominator, static fn (float $coefficient): bool => $coefficient !== 0.0)) === 0) {
            return null;
        }
        $domainBoundary = -$argumentCoefficients[0] / $argumentCoefficients[1];
        if (!\is_finite($domainBoundary)) {
            return null;
        }
        $increasingArgument = $argumentCoefficients[1] > 0.0;
        $intervalLowerBound = $increasingArgument
            ? \max($lowerBound, $domainBoundary)
            : $lowerBound;
        $intervalUpperBound = $increasingArgument
            ? $upperBound
            : \min($upperBound, $domainBoundary);
        if ($intervalLowerBound > $intervalUpperBound) {
            return [];
        }

        $endpointSolutions = [];
        foreach ([$lowerBound, $upperBound] as $endpoint) {
            if (
                !\is_finite($endpoint)
                || $endpoint < $intervalLowerBound
                || $endpoint > $intervalUpperBound
            ) {
                continue;
            }
            $residual = $residualAt($endpoint);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($endpoint, $residual, $candidateScaleAt, $options)
            ) {
                continue;
            }
            $this->addSolution(
                $endpointSolutions,
                new EquationSolution($endpoint == 0.0 ? 0.0 : $endpoint, \abs($residual), 0),
                $options,
            );
        }

        $denominatorRoots = $this->realPolynomialRootsInInterval(
            $denominator,
            $intervalLowerBound,
            $intervalUpperBound,
            $options,
        );
        if ($denominatorRoots === null) {
            return null;
        }
        $interiorPoles = \array_values(\array_filter(
            $denominatorRoots,
            static fn (float $root): bool => $root > $intervalLowerBound && $root < $intervalUpperBound,
        ));
        if ($interiorPoles !== []) {
            \sort($interiorPoles, SORT_NUMERIC);
            $cuts = [$intervalLowerBound, ...$interiorPoles, $intervalUpperBound];
            $solutions = [];
            for ($index = 0, $last = \count($cuts) - 1; $index < $last; ++$index) {
                $segmentSolutions = $this->solveMonotoneAffineLogRationalTarget(
                    $argument,
                    $target,
                    $variable,
                    $extractor,
                    $cuts[$index],
                    $cuts[$index + 1],
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                    $logarithmScale,
                    $argumentOffset,
                );
                if ($segmentSolutions === null) {
                    return null;
                }
                foreach ($segmentSolutions as $solution) {
                    $this->addSolution($solutions, $solution, $options);
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $numeratorDerivative = \array_fill(0, \max(1, \count($numerator) - 1), 0.0);
        foreach ($numerator as $degree => $coefficient) {
            if ($degree > 0) {
                $numeratorDerivative[$degree - 1] = $degree * $coefficient;
            }
        }
        $denominatorDerivative = \array_fill(0, \max(1, \count($denominator) - 1), 0.0);
        foreach ($denominator as $degree => $coefficient) {
            if ($degree > 0) {
                $denominatorDerivative[$degree - 1] = $degree * $coefficient;
            }
        }
        $targetDerivativeNumerator = $this->subtractScaledPolynomials(
            $this->multiplyPolynomials($numeratorDerivative ?: [0.0], $denominator),
            $this->multiplyPolynomials($numerator, $denominatorDerivative ?: [0.0]),
            1.0,
        );
        if ($targetDerivativeNumerator === null) {
            return null;
        }
        $denominatorSquare = $this->multiplyPolynomials($denominator, $denominator);
        $argumentDerivativeTerm = \array_map(
            fn (float $coefficient): float => $argumentCoefficients[1] * $coefficient,
            $denominatorSquare,
        );
        $targetDerivativeTerm = \array_fill(
            0,
            \count($argumentCoefficients) + \count($targetDerivativeNumerator) - 1,
            0.0,
        );
        foreach ($argumentCoefficients as $argumentDegree => $argumentCoefficient) {
            foreach ($targetDerivativeNumerator as $targetDegree => $targetCoefficient) {
                $targetDerivativeTerm[$argumentDegree + $targetDegree] += $argumentCoefficient * $targetCoefficient;
            }
        }
        $derivativeNumerator = $this->subtractScaledPolynomials(
            $argumentDerivativeTerm,
            $targetDerivativeTerm,
            1.0,
        );
        if ($derivativeNumerator === null) {
            return null;
        }
        while (
            \count($derivativeNumerator) > 1
            && $derivativeNumerator[\array_key_last($derivativeNumerator)] === 0.0
        ) {
            \array_pop($derivativeNumerator);
        }
        if ($derivativeNumerator === [0.0]) {
            return null;
        }

        $criticalPoints = $this->realPolynomialRootsInInterval(
            $derivativeNumerator,
            $intervalLowerBound,
            $intervalUpperBound,
            $options,
        );
        if ($criticalPoints === null) {
            return null;
        }
        $interiorCriticalPoints = [];
        foreach ($criticalPoints as $criticalPoint) {
            if (!\is_finite($criticalPoint)) {
                return null;
            }
            if ($criticalPoint > $intervalLowerBound && $criticalPoint < $intervalUpperBound) {
                $interiorCriticalPoints[] = $criticalPoint;
            }
        }
        if ($interiorCriticalPoints !== []) {
            \sort($interiorCriticalPoints, SORT_NUMERIC);
            $interiorCriticalPoints = \array_values(\array_unique($interiorCriticalPoints, SORT_REGULAR));
            $cuts = [$intervalLowerBound, ...$interiorCriticalPoints, $intervalUpperBound];
            $solutions = [];
            foreach ($interiorCriticalPoints as $criticalPoint) {
                $residual = $residualAt($criticalPoint);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $criticalPoint,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $criticalPoint == 0.0 ? 0.0 : $criticalPoint,
                            \abs($residual),
                            0,
                        ),
                        $options,
                    );
                }
            }
            for ($index = 0, $last = \count($cuts) - 1; $index < $last; ++$index) {
                $segmentSolutions = $this->solveMonotoneAffineLogRationalTarget(
                    $argument,
                    $target,
                    $variable,
                    $extractor,
                    $cuts[$index],
                    $cuts[$index + 1],
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                    $logarithmScale,
                    $argumentOffset,
                );
                if ($segmentSolutions === null) {
                    return null;
                }
                foreach ($segmentSolutions as $solution) {
                    $this->addSolution($solutions, $solution, $options);
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $evaluate = function (float $value) use (
            $argumentCoefficients,
            $numerator,
            $denominator,
        ): ?float {
            $argumentValue = $argumentCoefficients[0] + ($argumentCoefficients[1] * $value);
            if ($argumentValue <= 0.0 || !\is_finite($argumentValue)) {
                return null;
            }
            $numeratorValue = $this->polynomialValue($numerator, $value);
            $denominatorValue = $this->polynomialValue($denominator, $value);
            if ($numeratorValue === null || $denominatorValue === null) {
                return null;
            }
            if ($denominatorValue === 0.0 || \is_nan($numeratorValue) || \is_nan($denominatorValue)) {
                return null;
            }
            $value = \log($argumentValue) - ($numeratorValue / $denominatorValue);

            return \is_nan($value) ? null : $value;
        };

        $lowerDenominatorValue = $this->polynomialValue($denominator, $intervalLowerBound);
        if (
            ($increasingArgument && $intervalLowerBound === $domainBoundary)
            || \in_array($intervalLowerBound, $denominatorRoots, true)
            || $lowerDenominatorValue === 0.0
        ) {
            $left = $intervalLowerBound;
            $leftValue = null;
            for ($probe = 0; $probe < 4096; ++$probe) {
                $left = $this->adjacentFloat($left, 1);
                if ($left === null || $left > $intervalUpperBound) {
                    return [];
                }
                $leftValue = $evaluate($left);
                if ($leftValue !== null) {
                    break;
                }
            }
            if ($leftValue === null) {
                return null;
            }
        } else {
            $left = $intervalLowerBound;
            $leftValue = $evaluate($left);
            if ($leftValue === null) {
                return null;
            }
        }
        if ($leftValue === 0.0) {
            $residual = $residualAt($left);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($left, $residual, $candidateScaleAt, $options)
            ) {
                return null;
            }

            return [new EquationSolution($left == 0.0 ? 0.0 : $left, \abs($residual), 0)];
        }

        if (\is_finite($intervalUpperBound)) {
            $right = $intervalUpperBound;
            if (
                \in_array($right, $denominatorRoots, true)
                || $this->polynomialValue($denominator, $right) === 0.0
                || (!$increasingArgument && $right === $domainBoundary)
            ) {
                $rightValue = null;
                for ($probe = 0; $probe < 4096; ++$probe) {
                    $right = $this->adjacentFloat($right, -1);
                    if ($right === null || $right < $left) {
                        return [];
                    }
                    $rightValue = $evaluate($right);
                    if ($rightValue !== null) {
                        break;
                    }
                }
                if ($rightValue === null) {
                    return null;
                }
            } else {
                $rightValue = $evaluate($right);
            }
            if ($rightValue === null) {
                return null;
            }
        } else {
            $numeratorDegree = \count($numerator) - 1;
            $denominatorDegree = \count($denominator) - 1;
            $rightLimitSign = $numeratorDegree > $denominatorDegree
                && (($numerator[$numeratorDegree] < 0.0) !== ($denominator[$denominatorDegree] < 0.0))
                    ? 1
                    : ($numeratorDegree > $denominatorDegree ? -1 : 1);
            if (($leftValue > 0.0 ? 1 : -1) === $rightLimitSign) {
                return [];
            }
            $step = \max(1.0, \abs($left) * 0.25);
            $right = $left;
            $rightValue = $leftValue;
            for ($iteration = 0; $iteration < 1024; ++$iteration) {
                $candidate = $left + $step;
                if (!\is_finite($candidate) || $candidate === $right) {
                    return null;
                }
                $candidateValue = $evaluate($candidate);
                if ($candidateValue !== null && ($candidateValue > 0.0 ? 1 : -1) === $rightLimitSign) {
                    $right = $candidate;
                    $rightValue = $candidateValue;
                    break;
                }
                $right = $candidate;
                $rightValue = $candidateValue ?? $rightValue;
                $step *= 2.0;
                if (!\is_finite($step)) {
                    return null;
                }
            }
            if (($rightValue > 0.0 ? 1 : -1) !== $rightLimitSign) {
                return null;
            }
        }

        if ($leftValue === 0.0) {
            $candidates = [[$left, 0]];
        } elseif ($rightValue === 0.0) {
            $candidates = [[$right, 0]];
        } elseif (($leftValue > 0.0) === ($rightValue > 0.0)) {
            return $endpointSolutions;
        } else {
            $candidates = [];
            $iterationsPerformed = 0;
            for ($iteration = 0; $iteration < 1024; ++$iteration) {
                $iterationsPerformed = $iteration + 1;
                $middle = ($left / 2.0) + ($right / 2.0);
                if ($middle === $left || $middle === $right) {
                    break;
                }
                $middleValue = $evaluate($middle);
                if ($middleValue === null) {
                    return null;
                }
                $residual = $residualAt($middle);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt($middle, $residual, $candidateScaleAt, $options)
                ) {
                    $candidates[] = [$middle, $iterationsPerformed];
                    break;
                }
                if (($middleValue > 0.0) === ($leftValue > 0.0)) {
                    $left = $middle;
                    $leftValue = $middleValue;
                } else {
                    $right = $middle;
                    $rightValue = $middleValue;
                }
            }
            if ($candidates === []) {
                $middle = ($left / 2.0) + ($right / 2.0);
                $residual = $residualAt($middle);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt($middle, $residual, $candidateScaleAt, $options)
                ) {
                    return null;
                }
                $candidates[] = [$middle, $iterationsPerformed];
            }
        }

        $solutions = [];
        foreach ($candidates as [$root, $iterations]) {
            $residual = $residualAt($root);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($root, $residual, $candidateScaleAt, $options)
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root == 0.0 ? 0.0 : $root, \abs($residual), $iterations),
                $options,
            );
        }

        foreach ($endpointSolutions as $endpointSolution) {
            $this->addSolution($solutions, $endpointSolution, $options);
        }

        return $solutions;
    }

    private function reflectVariableInExpression(
        string $expression,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): ?string {
        $tokens = (new Lexer($expression, $evaluationOptions->limits))->tokenize();
        $replacements = [];
        foreach ($tokens as $index => $token) {
            if (
                $token->type !== \MathPHP\Parser\TokenType::Identifier
                || $token->lexeme !== $variable
                || ($tokens[$index + 1]->type ?? null) === \MathPHP\Parser\TokenType::LeftParenthesis
            ) {
                continue;
            }
            $replacements[] = [$token->span->start, $token->span->end];
        }
        foreach (\array_reverse($replacements) as [$start, $end]) {
            $expression = \substr($expression, 0, $start)
                . '(-' . $variable . ')'
                . \substr($expression, $end);
        }

        return $expression;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedLogarithmicEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0, 0],
                [$right, $left, $rightSource, $leftSource, 0, 0],
            ] as [
                $functionNode,
                $targetNode,
                $functionSource,
                $targetSource,
                $functionSourceOffset,
                $targetSourceOffset,
            ]
        ) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || !$evaluationOptions->functions->isBuiltIn($functionNode->name)
            ) {
                continue;
            }

            $argument = null;
            $logarithmScale = 1.0;
            if (
                \count($functionNode->arguments) === 1
                && \in_array($functionNode->name, ['ln', 'log1p'], true)
            ) {
                $argument = $functionNode->arguments[0];
            } elseif (
                \count($functionNode->arguments) === 1
                && \in_array($functionNode->name, ['log2', 'log10'], true)
            ) {
                $argument = $functionNode->arguments[0];
                $logarithmScale = $functionNode->name === 'log2' ? \log(2.0) : \log(10.0);
            } elseif (
                $functionNode->name === 'log'
                && \count($functionNode->arguments) === 2
            ) {
                $base = $this->extractPolynomial(
                    $extractor,
                    $functionNode->arguments[1],
                    $functionNode->arguments[1]->span()->start,
                );
                if (
                    $base === null
                    || \count($base) !== 1
                    || !\is_finite($base[0])
                    || $base[0] <= 0.0
                    || $base[0] === 1.0
                ) {
                    continue;
                }
                $argument = $functionNode->arguments[0];
                $logarithmScale = \log($base[0]);
            } else {
                continue;
            }

            if ($functionNode->name === 'ln') {
                $argumentForm = $extractor->extractRationalForm($argument);
                $targetForm = $extractor->extractRationalForm($targetNode);
                if (
                    $argumentForm !== null
                    && $targetForm !== null
                    && \count($targetForm[0]) <= \count($targetForm[1])
                ) {
                    $targetNumeratorDegree = \count($targetForm[0]) - 1;
                    $targetDenominatorDegree = \count($targetForm[1]) - 1;
                    $additiveLevel = 0.0;
                    if ($targetNumeratorDegree === $targetDenominatorDegree) {
                        $additiveLevel = $targetForm[0][$targetNumeratorDegree]
                            / $targetForm[1][$targetDenominatorDegree];
                    }
                    $adjustedTargetNumerator = $this->subtractScaledPolynomials(
                        $targetForm[0],
                        $targetForm[1],
                        $additiveLevel,
                    );
                    $productNumerator = $adjustedTargetNumerator === null
                        ? null
                        : $this->multiplyPolynomials($argumentForm[0], $adjustedTargetNumerator);
                    $productDenominator = $this->multiplyPolynomials(
                        $argumentForm[1],
                        $targetForm[1],
                    );
                    $productLevel = $productNumerator === null || $productDenominator === null
                        ? null
                        : $this->proportionalPolynomialRatio($productNumerator, $productDenominator);
                    $lambertArgument = $productLevel === null
                        ? null
                        : $productLevel * \exp(-$additiveLevel);
                    if (
                        $productLevel !== null
                        && \is_finite($productLevel)
                        && $lambertArgument !== null
                        && \is_finite($lambertArgument)
                    ) {
                        $argumentCoefficients = $extractor->extract($argument);
                        $lambertW = $evaluationOptions->functions->find('lambertw');
                        if (
                            $argumentCoefficients !== null
                            && \count($argumentCoefficients) === 2
                            && $argumentCoefficients[1] !== 0.0
                            && $lambertW !== null
                        ) {
                            $branchPoint = -1.0 / \M_E;
                            $branchTolerance = 8.0 * \PHP_FLOAT_EPSILON
                                * \max(1.0, \abs($lambertArgument), \abs($branchPoint));
                            if ($lambertArgument < $branchPoint - $branchTolerance) {
                                return [];
                            }

                            $branches = \abs($lambertArgument - $branchPoint) <= $branchTolerance
                                ? [null]
                                : ($lambertArgument < 0.0 ? [0, -1] : [0]);
                            $solutions = [];
                            foreach ($branches as $branch) {
                                try {
                                    $lambertValue = $branch === null
                                        ? -1.0
                                        : (float) $lambertW->invoke(
                                            $branch === 0
                                                ? [$lambertArgument]
                                                : [$lambertArgument, $branch],
                                        );
                                } catch (\DomainException) {
                                    continue;
                                }
                                $argumentLevel = \exp($additiveLevel + $lambertValue);
                                $root = ($argumentLevel - $argumentCoefficients[0])
                                    / $argumentCoefficients[1];
                                if (!\is_finite($root)) {
                                    continue;
                                }
                                if ($root < $lowerBound) {
                                    $endpointTolerance = 16.0 * \PHP_FLOAT_EPSILON
                                        * \max(1.0, \abs($root), \abs($lowerBound));
                                    if ($lowerBound - $root > $endpointTolerance) {
                                        continue;
                                    }
                                    $root = $lowerBound;
                                } elseif ($root > $upperBound) {
                                    $endpointTolerance = 16.0 * \PHP_FLOAT_EPSILON
                                        * \max(1.0, \abs($root), \abs($upperBound));
                                    if ($root - $upperBound > $endpointTolerance) {
                                        continue;
                                    }
                                    $root = $upperBound;
                                }
                                $residual = $residualAt($root);
                                if (
                                    $residual === null
                                    || !$this->isResidualAcceptableAt(
                                        $root,
                                        $residual,
                                        $candidateScaleAt,
                                        $solverOptions,
                                    )
                                ) {
                                    continue;
                                }
                                $this->addSolution(
                                    $solutions,
                                    new EquationSolution($root == 0.0 ? 0.0 : $root, \abs($residual), 0),
                                    $solverOptions,
                                );
                            }
                            if (\is_finite($lowerBound) && \is_finite($upperBound)) {
                                foreach ([$lowerBound, $upperBound] as $endpoint) {
                                    $residual = $residualAt($endpoint);
                                    if (
                                        $residual === null
                                        || !$this->isResidualAcceptableAt(
                                            $endpoint,
                                            $residual,
                                            $candidateScaleAt,
                                            $solverOptions,
                                        )
                                    ) {
                                        continue;
                                    }
                                    $this->addSolution(
                                        $solutions,
                                        new EquationSolution($endpoint == 0.0 ? 0.0 : $endpoint, \abs($residual), 0),
                                        $solverOptions,
                                    );
                                }
                            }
                            \usort(
                                $solutions,
                                static fn (EquationSolution $first, EquationSolution $second): int =>
                                    $first->value <=> $second->value,
                            );

                            return $solutions;
                        }
                    }
                }

                $monotoneRationalSolutions = $this->solveMonotoneAffineLogRationalTarget(
                    $argument,
                    $targetNode,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                    $residualAt,
                    $candidateScaleAt,
                );
                if ($monotoneRationalSolutions !== null) {
                    return $monotoneRationalSolutions;
                }
            }

            if (\in_array($functionNode->name, ['log1p', 'log2', 'log10', 'log'], true)) {
                $monotoneRationalSolutions = $this->solveMonotoneAffineLogRationalTarget(
                    $argument,
                    $targetNode,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                    $residualAt,
                    $candidateScaleAt,
                    $logarithmScale,
                    $functionNode->name === 'log1p' ? 1.0 : 0.0,
                );
                if ($monotoneRationalSolutions !== null) {
                    return $monotoneRationalSolutions;
                }
            }

            $argumentCoefficients = $extractor->extract($argument);
            if (
                $argumentCoefficients !== null
                && \count($argumentCoefficients) === 2
                && $argumentCoefficients[1] < 0.0
                && $extractor->extractRationalForm($targetNode) !== null
            ) {
                $reflectedFunction = $this->reflectVariableInExpression(
                    $functionSource,
                    $variable,
                    $evaluationOptions,
                );
                $reflectedTarget = $this->reflectVariableInExpression(
                    $targetSource,
                    $variable,
                    $evaluationOptions,
                );
                if ($reflectedFunction === null || $reflectedTarget === null) {
                    continue;
                }
                $reflectedEquation = '(' . $reflectedFunction . ')=(' . $reflectedTarget . ')';
                if (\strlen($reflectedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    continue;
                }
                $reflectedSolutions = $this->solve(
                    $reflectedEquation,
                    $variable,
                    -$upperBound,
                    -$lowerBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                $solutions = [];
                foreach ($reflectedSolutions as $solution) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(-$solution->value, $solution->residual, $solution->iterations),
                        $solverOptions,
                    );
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }

            $targetCoefficients = $this->extractPolynomial(
                $extractor,
                $targetNode,
                $targetNode->span()->start,
            );
            $argumentCoefficients = $this->extractPolynomial(
                $extractor,
                $argument,
                $argument->span()->start,
            );
            if ($targetCoefficients === null || $argumentCoefficients === null) {
                continue;
            }

            $isIdentityShape = false;
            if ($functionNode->name === 'log1p') {
                $isIdentityShape = $argumentCoefficients === $targetCoefficients;
            } elseif (
                ($functionNode->name === 'ln' || $functionNode->name === 'log')
                && $logarithmScale === 1.0
            ) {
                $difference = $this->subtractScaledPolynomials(
                    $argumentCoefficients,
                    $targetCoefficients,
                    1.0,
                );
                $isIdentityShape = $difference === [1.0];
            }
            $targetSpan = $targetNode->span();
            $targetExpression = \substr(
                $targetSource,
                $targetSpan->start - $targetSourceOffset,
                $targetSpan->end - $targetSpan->start,
            );
            if ($isIdentityShape) {
                $rootEquation = '(' . $targetExpression . ')=0';
                if (\strlen($rootEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }

                return $this->solve(
                    $rootEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }

            if (\count($targetCoefficients) > 2 || \count($argumentCoefficients) > 2) {
                $effectiveArgumentCoefficients = $argumentCoefficients;
                if ($functionNode->name === 'log1p') {
                    $effectiveArgumentCoefficients[0] = ($effectiveArgumentCoefficients[0] ?? 0.0) + 1.0;
                }
                $polynomialLogSolutions = $this->solveUnboundedPolynomialLogTarget(
                    $effectiveArgumentCoefficients,
                    $targetCoefficients,
                    $logarithmScale,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $residualAt,
                    $candidateScaleAt,
                );
                if ($polynomialLogSolutions !== null) {
                    return $polynomialLogSolutions;
                }
            }

            if (
                \count($targetCoefficients) > 2
                || \count($argumentCoefficients) > 2
                || !\is_finite($logarithmScale)
                || $logarithmScale === 0.0
            ) {
                continue;
            }
            $argumentSpan = $argument->span();
            $argumentExpression = \substr(
                $functionSource,
                $argumentSpan->start - $functionSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            if ($argumentExpression === '') {
                continue;
            }
            $scaledTarget = $logarithmScale === 1.0
                ? '(' . $targetExpression . ')'
                : '((' . $targetExpression . ')*' . \sprintf('%.17g', $logarithmScale) . ')';
            $transformedRight = $functionNode->name === 'log1p'
                ? '((' . $argumentExpression . ')+1)'
                : '(' . $argumentExpression . ')';
            $transformedEquation = 'exp(' . $scaledTarget . ')=' . $transformedRight;
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                $candidates = $this->solve(
                    $transformedEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (\InvalidArgumentException | \DomainException) {
                continue;
            }
            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $solverOptions,
                );
            }

            return $solutions;
        }

        return null;
    }

    /**
     * @return array{FunctionCallNode, float}|null
     */
    private function extractConstantMultipleFunctionCall(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            return [$node, 1.0];
        }
        if ($node instanceof UnaryOperationNode) {
            $extracted = $this->extractConstantMultipleFunctionCall($node->operand, $extractor);
            if ($extracted === null) {
                return null;
            }
            [$function, $coefficient] = $extracted;

            return [
                $function,
                $coefficient * ($node->operator === UnaryOperator::Minus ? -1.0 : 1.0),
            ];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        if ($node->operator === BinaryOperator::Multiply) {
            $leftFunction = $this->extractConstantMultipleFunctionCall($node->left, $extractor);
            if ($leftFunction !== null) {
                $coefficient = $this->extractPolynomial($extractor, $node->right, $node->right->span()->start);
                if ($coefficient !== null && \count($coefficient) === 1) {
                    return [$leftFunction[0], $leftFunction[1] * $coefficient[0]];
                }
            }
            $rightFunction = $this->extractConstantMultipleFunctionCall($node->right, $extractor);
            if ($rightFunction !== null) {
                $coefficient = $this->extractPolynomial($extractor, $node->left, $node->left->span()->start);
                if ($coefficient !== null && \count($coefficient) === 1) {
                    return [$rightFunction[0], $rightFunction[1] * $coefficient[0]];
                }
            }

            return null;
        }
        if ($node->operator === BinaryOperator::Divide) {
            $numeratorFunction = $this->extractConstantMultipleFunctionCall($node->left, $extractor);
            $denominator = $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            );
            if (
                $numeratorFunction === null
                || $denominator === null
                || \count($denominator) !== 1
                || $denominator[0] === 0.0
            ) {
                return null;
            }

            return [$numeratorFunction[0], $numeratorFunction[1] / $denominator[0]];
        }

        return null;
    }

    /**
     * @param array{
     *     coefficients: list<float>,
     *     denominator: list<float>,
     *     sign: float,
     *     absolute: bool,
     *     piecewiseAbsolute: bool,
     *     piecewiseAbsoluteSign: float
     * } $argument
     */
    private function isPolynomialLogArgumentDefinedAt(
        array $argument,
        float $value,
        PolynomialSolver $polynomialSolver,
    ): bool {
        $numeratorValue = $polynomialSolver->evaluatePolynomial($argument['coefficients'], $value);
        $denominatorValue = $polynomialSolver->evaluatePolynomial($argument['denominator'], $value);
        if (
            $numeratorValue === null
            || $denominatorValue === null
            || !\is_finite($numeratorValue)
            || !\is_finite($denominatorValue)
            || $denominatorValue === 0.0
        ) {
            return false;
        }
        if ($argument['piecewiseAbsolute']) {
            return $argument['piecewiseAbsoluteSign'] > 0.0
                || \abs($numeratorValue) < \abs($denominatorValue);
        }
        if ($numeratorValue === 0.0) {
            return false;
        }
        if ($argument['absolute']) {
            return true;
        }

        return ($numeratorValue > 0.0) === ($denominatorValue > 0.0);
    }

    /**
     * @param list<float> $coefficients
     * @return list<float>|null
     */
    private function realPolynomialRootsInInterval(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): ?array {
        $degree = \count($coefficients) - 1;
        if ($degree < 1) {
            return [];
        }
        $leading = \abs($coefficients[$degree]);
        if ($leading === 0.0 || !\is_finite($leading)) {
            return null;
        }
        $maximumRatio = 0.0;
        foreach ($coefficients as $coefficientIndex => $coefficient) {
            if ($coefficientIndex === $degree) {
                continue;
            }
            $ratio = \abs($coefficient) / $leading;
            if (!\is_finite($ratio)) {
                return null;
            }
            $maximumRatio = \max($maximumRatio, $ratio);
        }
        $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
        if (!\is_finite($rootBound)) {
            return null;
        }
        $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
        $rootLower = \max($lowerBound, -$rootBound);
        $rootUpper = \min($upperBound, $rootBound);
        if ($rootLower > $rootUpper) {
            return [];
        }

        $polynomialSolver = new PolynomialSolver();
        $roots = $polynomialSolver->solve(
            $coefficients,
            $rootLower,
            $rootUpper,
            static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($coefficients, $value),
            $solverOptions,
            static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($coefficients, $value),
        );
        if ($roots === null) {
            return null;
        }

        $values = [];
        foreach ($roots as $root) {
            if ($root->value >= $lowerBound && $root->value <= $upperBound) {
                $values[] = $root->value;
            }
        }

        return $values;
    }

    /**
     * Isolate signed same-base logarithm sums by partitioning at roots of their derivative.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedSignedAffineLogPolynomialEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
        bool $splitPolynomialDomains = true,
        bool $lowerOpenBoundary = false,
        bool $upperOpenBoundary = false,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$logarithmSide, $targetSide]) {
            $terms = [];
            $this->flattenAdditiveTerms($logarithmSide, 1.0, $terms);
            if ($terms === []) {
                continue;
            }

            /**
             * @var list<array{
             *     coefficients: list<float>,
             *     denominator: list<float>,
             *     sign: float,
             *     absolute: bool,
             *     piecewiseAbsolute: bool,
             *     piecewiseAbsoluteSign: float
             * }> $arguments
             */
            $arguments = [];
            $logarithmScale = null;
            $hasSubtraction = false;
            $hasNonUnitWeight = false;
            $hasAbsoluteArgument = false;
            foreach ($terms as [$term, $sign]) {
                $weightedFunction = $this->extractConstantMultipleFunctionCall($term, $extractor);
                if ($weightedFunction === null) {
                    continue 2;
                }
                [$function, $coefficient] = $weightedFunction;
                $weight = $sign * $coefficient;
                if ($weight === 0.0) {
                    continue;
                }
                $hasNonUnitWeight = $hasNonUnitWeight || ($weight !== 1.0 && $weight !== -1.0);
                if (!\is_finite($weight)) {
                    continue 2;
                }
                $argument = null;
                $scale = 1.0;
                if (
                    \count($function->arguments) === 1
                    && \in_array($function->name, ['ln', 'log1p'], true)
                ) {
                    $argument = $function->arguments[0];
                } elseif (
                    \count($function->arguments) === 1
                    && \in_array($function->name, ['log2', 'log10'], true)
                ) {
                    $argument = $function->arguments[0];
                    $scale = $function->name === 'log2' ? \log(2.0) : \log(10.0);
                } elseif ($function->name === 'log' && \count($function->arguments) === 2) {
                    $base = $this->extractPolynomial(
                        $extractor,
                        $function->arguments[1],
                        $function->arguments[1]->span()->start,
                    );
                    if (
                        $base === null
                        || \count($base) !== 1
                        || !\is_finite($base[0])
                        || $base[0] <= 0.0
                        || $base[0] === 1.0
                    ) {
                        continue 2;
                    }
                    $argument = $function->arguments[0];
                    $scale = \log($base[0]);
                } else {
                    continue 2;
                }
                if ($logarithmScale !== null && $logarithmScale !== $scale) {
                    continue 2;
                }
                $logarithmScale = $scale;
                $absoluteArgument = false;
                $piecewiseAbsoluteArgument = false;
                $piecewiseAbsoluteSign = 1.0;
                $argumentExpression = $argument;
                $absoluteExpression = $this->unwrapGrouping($argumentExpression);
                if (
                    $function->name === 'log1p'
                    && $absoluteExpression instanceof UnaryOperationNode
                    && $absoluteExpression->operator === UnaryOperator::Minus
                ) {
                    $piecewiseAbsoluteSign = -1.0;
                    $absoluteExpression = $this->unwrapGrouping($absoluteExpression->operand);
                }
                $absoluteCall = $absoluteExpression;
                if (
                    $absoluteCall instanceof FunctionCallNode
                    && $absoluteCall->name === 'abs'
                    && \count($absoluteCall->arguments) === 1
                ) {
                    $hasAbsoluteArgument = true;
                    $piecewiseAbsoluteArgument = $function->name === 'log1p';
                    $absoluteArgument = !$piecewiseAbsoluteArgument;
                    $argumentExpression = $absoluteCall->arguments[0];
                    while (true) {
                        $nestedAbsoluteCall = $this->unwrapGrouping($argumentExpression);
                        if (
                            !$nestedAbsoluteCall instanceof FunctionCallNode
                            || $nestedAbsoluteCall->name !== 'abs'
                            || \count($nestedAbsoluteCall->arguments) !== 1
                        ) {
                            break;
                        }
                        $argumentExpression = $nestedAbsoluteCall->arguments[0];
                    }
                }
                $denominatorCoefficients = [1.0];
                if ($function->name === 'log1p') {
                    $rationalForm = $extractor->extractRationalForm($argumentExpression);
                    if ($rationalForm === null) {
                        continue 2;
                    }
                    [$argumentNumerator, $denominatorCoefficients] = $rationalForm;
                    if ($piecewiseAbsoluteArgument) {
                        $coefficients = $argumentNumerator;
                    } else {
                        $coefficients = $this->combinePolynomialCoefficients(
                            $argumentNumerator,
                            $denominatorCoefficients,
                            1.0,
                        );
                        if ($coefficients === null) {
                            continue 2;
                        }
                    }
                } else {
                    $rationalForm = $extractor->extractRationalForm($argumentExpression);
                    if ($rationalForm === null) {
                        continue 2;
                    }
                    [$coefficients, $denominatorCoefficients] = $rationalForm;
                }
                while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
                    \array_pop($coefficients);
                }
                $arguments[] = [
                    'coefficients' => $coefficients,
                    'denominator' => $denominatorCoefficients,
                    'sign' => $weight,
                    'absolute' => $absoluteArgument,
                    'piecewiseAbsolute' => $piecewiseAbsoluteArgument,
                    'piecewiseAbsoluteSign' => $piecewiseAbsoluteSign,
                ];
                $hasSubtraction = $hasSubtraction || $weight < 0.0;
            }
            if (
                $logarithmScale === null
                || (
                    \count($arguments) > 1
                    && !$hasSubtraction
                    && !$hasNonUnitWeight
                    && !$hasAbsoluteArgument
                )
            ) {
                continue;
            }
            $target = $this->extractPolynomial(
                $extractor,
                $targetSide,
                $targetSide->span()->start,
            );
            if ($target === null || \count($target) < 2) {
                continue;
            }

            if ($splitPolynomialDomains) {
                $polynomialSolver = new PolynomialSolver();
                $domainRoots = [];
                $piecewiseBreakpoints = [];
                foreach ($arguments as $argument) {
                    $factors = $argument['piecewiseAbsolute']
                        ? [[$argument['coefficients'], true], [$argument['denominator'], false]]
                        : [[$argument['coefficients'], false], [$argument['denominator'], false]];
                    if ($argument['piecewiseAbsolute'] && $argument['piecewiseAbsoluteSign'] < 0.0) {
                        foreach ([1.0, -1.0] as $direction) {
                            $boundaryPolynomial = $this->combinePolynomialCoefficients(
                                $argument['denominator'],
                                $argument['coefficients'],
                                $direction,
                            );
                            if ($boundaryPolynomial === null) {
                                continue 3;
                            }
                            $factors[] = [$boundaryPolynomial, false];
                        }
                    }
                    foreach ($factors as [$factorCoefficients, $isPiecewiseNumerator]) {
                        $roots = $this->realPolynomialRootsInInterval(
                            $factorCoefficients,
                            $lowerBound,
                            $upperBound,
                            $solverOptions,
                        );
                        if ($roots === null) {
                            continue 3;
                        }
                        if ($isPiecewiseNumerator) {
                            \array_push($piecewiseBreakpoints, ...$roots);
                        } else {
                            \array_push($domainRoots, ...$roots);
                        }
                    }
                }
                \sort($domainRoots, SORT_NUMERIC);
                $domainRoots = \array_values(\array_unique($domainRoots, SORT_REGULAR));
                $boundaries = [...$domainRoots, ...$piecewiseBreakpoints];
                \sort($boundaries, SORT_NUMERIC);
                $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
                \array_unshift($boundaries, $lowerBound);
                $boundaries[] = $upperBound;
                $validIntervals = [];
                foreach ($boundaries as $boundaryIndex => $boundary) {
                    if ($boundaryIndex === 0) {
                        continue;
                    }
                    $intervalLower = $boundaries[$boundaryIndex - 1];
                    $intervalUpper = $boundary;
                    $intervalLowerIsOpen = \in_array($intervalLower, $domainRoots, true);
                    $intervalUpperIsOpen = \in_array($intervalUpper, $domainRoots, true);
                    if ($intervalLower >= $intervalUpper) {
                        continue;
                    }
                    if ($intervalLower === -\INF && $intervalUpper === \INF) {
                        $sample = 0.0;
                    } elseif ($intervalLower === -\INF) {
                        $sample = $intervalUpper - \max(1.0, \abs($intervalUpper) * 0.5);
                        if (!\is_finite($sample)) {
                            $sample = (-\PHP_FLOAT_MAX / 2.0) + ($intervalUpper / 2.0);
                        }
                    } elseif ($intervalUpper === \INF) {
                        $sample = $intervalLower + \max(1.0, \abs($intervalLower) * 0.5);
                        if (!\is_finite($sample)) {
                            $sample = ($intervalLower / 2.0) + (\PHP_FLOAT_MAX / 2.0);
                        }
                    } else {
                        $sample = ($intervalLower / 2.0) + ($intervalUpper / 2.0);
                    }
                    $isValid = true;
                    foreach ($arguments as $argument) {
                        if (!$this->isPolynomialLogArgumentDefinedAt($argument, $sample, $polynomialSolver)) {
                            $isValid = false;
                            break;
                        }
                    }
                    if (!$isValid) {
                        continue;
                    }
                    if ($intervalLowerIsOpen) {
                        $outside = $intervalLower;
                        $inside = $sample;
                        for ($iteration = 0; $iteration < 80; ++$iteration) {
                            $middle = ($outside / 2.0) + ($inside / 2.0);
                            if ($middle === $outside || $middle === $inside) {
                                break;
                            }
                            $positive = true;
                            foreach ($arguments as $argument) {
                                if (!$this->isPolynomialLogArgumentDefinedAt($argument, $middle, $polynomialSolver)) {
                                    $positive = false;
                                    break;
                                }
                            }
                            if ($positive) {
                                $inside = $middle;
                            } else {
                                $outside = $middle;
                            }
                        }
                        $intervalLower = $inside;
                    }
                    if ($intervalUpperIsOpen) {
                        $inside = $sample;
                        $outside = $intervalUpper;
                        for ($iteration = 0; $iteration < 80; ++$iteration) {
                            $middle = ($inside / 2.0) + ($outside / 2.0);
                            if ($middle === $inside || $middle === $outside) {
                                break;
                            }
                            $positive = true;
                            foreach ($arguments as $argument) {
                                if (!$this->isPolynomialLogArgumentDefinedAt($argument, $middle, $polynomialSolver)) {
                                    $positive = false;
                                    break;
                                }
                            }
                            if ($positive) {
                                $inside = $middle;
                            } else {
                                $outside = $middle;
                            }
                        }
                        $intervalUpper = $inside;
                    }
                    if ($intervalLower < $intervalUpper) {
                        $validIntervals[] = [
                            $intervalLower,
                            $intervalUpper,
                            $intervalLowerIsOpen,
                            $intervalUpperIsOpen,
                        ];
                    }
                }
                $domainSolutions = [];
                foreach ($validIntervals as $validInterval) {
                    [
                        $intervalLower,
                        $intervalUpper,
                        $intervalLowerIsOpen,
                        $intervalUpperIsOpen,
                    ] = $validInterval;
                    $intervalSolutions = $this->solveUnboundedSignedAffineLogPolynomialEquation(
                        $left,
                        $right,
                        $variable,
                        $extractor,
                        $intervalLower,
                        $intervalUpper,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        $residualAt,
                        $candidateScaleAt,
                        false,
                        $intervalLowerIsOpen,
                        $intervalUpperIsOpen,
                    );
                    if ($intervalSolutions === null) {
                        continue 2;
                    }
                    foreach ($intervalSolutions as $solution) {
                        $this->addSolution($domainSolutions, $solution, $solverOptions);
                    }
                }
                \usort(
                    $domainSolutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $domainSolutions;
            }

            $domainLower = $lowerBound;
            $domainUpper = $upperBound;
            $polynomialSolver = new PolynomialSolver();

            foreach ($arguments as &$argument) {
                if (!$argument['piecewiseAbsolute']) {
                    continue;
                }
                if ($domainLower === -\INF && $domainUpper === \INF) {
                    $sample = 0.0;
                } elseif ($domainLower === -\INF) {
                    $sample = $domainUpper - \max(1.0, \abs($domainUpper) * 0.5);
                } elseif ($domainUpper === \INF) {
                    $sample = $domainLower + \max(1.0, \abs($domainLower) * 0.5);
                } else {
                    $sample = ($domainLower / 2.0) + ($domainUpper / 2.0);
                }
                $numeratorValue = $polynomialSolver->evaluatePolynomial($argument['coefficients'], $sample);
                $denominatorValue = $polynomialSolver->evaluatePolynomial($argument['denominator'], $sample);
                if ($numeratorValue === null || $denominatorValue === null || $denominatorValue === 0.0) {
                    continue 2;
                }
                $direction = ($numeratorValue > 0.0) === ($denominatorValue > 0.0) ? 1.0 : -1.0;
                $signedNumerator = $this->combinePolynomialCoefficients(
                    $argument['denominator'],
                    $argument['coefficients'],
                    $direction * $argument['piecewiseAbsoluteSign'],
                );
                if ($signedNumerator === null) {
                    continue 2;
                }
                $argument['coefficients'] = $signedNumerator;
                $argument['absolute'] = true;
                $argument['piecewiseAbsolute'] = false;
            }
            unset($argument);

            $product = [1.0];
            foreach ($arguments as $argument) {
                foreach ([$argument['coefficients'], $argument['denominator']] as $factorCoefficients) {
                    $product = $this->multiplyPolynomials($product, $factorCoefficients);
                    $productIsFinite = true;
                    foreach ($product as $coefficient) {
                        $productIsFinite = $productIsFinite && \is_finite($coefficient);
                    }
                    if (\count($product) - 1 > $solverOptions->maxPolynomialDegree || !$productIsFinite) {
                        continue 3;
                    }
                }
            }
            $logDerivativeNumerator = [0.0];
            foreach ($arguments as $index => $argument) {
                foreach (['coefficients', 'denominator'] as $factorName) {
                    $argumentDerivative = $this->polynomialDerivative($argument[$factorName]);
                    if ($argumentDerivative === [0.0]) {
                        continue;
                    }
                    $otherProduct = [1.0];
                    foreach ($arguments as $otherIndex => $otherArgument) {
                        foreach (['coefficients', 'denominator'] as $otherFactorName) {
                            if ($otherIndex === $index && $otherFactorName === $factorName) {
                                continue;
                            }
                            $otherProduct = $this->multiplyPolynomials(
                                $otherProduct,
                                $otherArgument[$otherFactorName],
                            );
                        }
                    }
                    $factorSign = $factorName === 'coefficients' ? 1.0 : -1.0;
                    $scaledOtherProduct = $this->scalePolynomialCoefficients(
                        $this->multiplyPolynomials($argumentDerivative, $otherProduct),
                        $argument['sign'] * $factorSign,
                    );
                    if ($scaledOtherProduct === null) {
                        continue 3;
                    }
                    $combinedDerivative = $this->combinePolynomialCoefficients(
                        $logDerivativeNumerator,
                        $scaledOtherProduct,
                        1.0,
                    );
                    if ($combinedDerivative === null) {
                        continue 3;
                    }
                    $logDerivativeNumerator = $combinedDerivative;
                }
            }
            $targetDerivativeProduct = $this->multiplyPolynomials(
                $product,
                $this->polynomialDerivative($target),
            );
            $scaledTargetDerivative = $this->scalePolynomialCoefficients(
                $targetDerivativeProduct,
                $logarithmScale,
            );
            if ($scaledTargetDerivative === null) {
                continue;
            }
            $criticalPolynomial = $this->subtractScaledPolynomials(
                $logDerivativeNumerator,
                $scaledTargetDerivative,
                1.0,
            );
            if (
                $criticalPolynomial === null
                || \count($criticalPolynomial) - 1 > $solverOptions->maxPolynomialDegree
            ) {
                continue;
            }
            while (
                \count($criticalPolynomial) > 1
                && $criticalPolynomial[\array_key_last($criticalPolynomial)] === 0.0
            ) {
                \array_pop($criticalPolynomial);
            }
            if ($criticalPolynomial === [0.0]) {
                continue;
            }

            $polynomialSolver = new PolynomialSolver();
            $reducedResidualAt = function (float $value) use (
                $arguments,
                $target,
                $logarithmScale,
                $polynomialSolver,
            ): ?float {
                $logarithmSum = 0.0;
                foreach ($arguments as $argument) {
                    $numeratorValue = $polynomialSolver->evaluatePolynomial($argument['coefficients'], $value);
                    $denominatorValue = $polynomialSolver->evaluatePolynomial($argument['denominator'], $value);
                    if (
                        $numeratorValue === null
                        || $denominatorValue === null
                        || !\is_finite($numeratorValue)
                        || !\is_finite($denominatorValue)
                        || $denominatorValue === 0.0
                        || (!$argument['absolute'] && (($numeratorValue > 0.0) !== ($denominatorValue > 0.0)))
                    ) {
                        return null;
                    }
                    if ($numeratorValue === 0.0) {
                        return null;
                    }
                    $logArgumentValue = \log(\abs($numeratorValue)) - \log(\abs($denominatorValue));
                    $logarithmSum += $argument['sign'] * $logArgumentValue;
                }
                $targetValue = $polynomialSolver->evaluatePolynomial($target, $value);
                if ($targetValue === null) {
                    return null;
                }
                $residual = ($logarithmSum / $logarithmScale) - $targetValue;

                return \is_finite($residual) ? $residual : null;
            };

            $criticalPoints = [];
            if (\count($criticalPolynomial) > 1) {
                $leading = \abs($criticalPolynomial[\array_key_last($criticalPolynomial)]);
                if ($leading === 0.0 || !\is_finite($leading)) {
                    continue;
                }
                $maximumRatio = 0.0;
                foreach ($criticalPolynomial as $degree => $coefficient) {
                    if ($degree === \array_key_last($criticalPolynomial)) {
                        continue;
                    }
                    $ratio = \abs($coefficient) / $leading;
                    if (!\is_finite($ratio)) {
                        continue 2;
                    }
                    $maximumRatio = \max($maximumRatio, $ratio);
                }
                $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
                if (!\is_finite($rootBound)) {
                    continue;
                }
                $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
                $rootLower = \is_finite($domainLower) ? \max($domainLower, -$rootBound) : -$rootBound;
                $rootUpper = \is_finite($domainUpper) ? \min($domainUpper, $rootBound) : $rootBound;
                if ($rootLower <= $rootUpper) {
                    $roots = $polynomialSolver->solve(
                        $criticalPolynomial,
                        $rootLower,
                        $rootUpper,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomial($criticalPolynomial, $value),
                        $solverOptions,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomialMagnitude($criticalPolynomial, $value),
                    );
                    if ($roots === null) {
                        continue;
                    }
                    foreach ($roots as $root) {
                        $value = $root->value;
                        if ($value <= $domainLower || $value >= $domainUpper) {
                            continue;
                        }
                        if (
                            ($lowerOpenBoundary && $value - $domainLower <= $solverOptions->absoluteTolerance)
                            || ($upperOpenBoundary && $domainUpper - $value <= $solverOptions->absoluteTolerance)
                        ) {
                            continue;
                        }
                        if ($reducedResidualAt($value) !== null) {
                            $criticalPoints[] = $value;
                        }
                    }
                }
            }
            \sort($criticalPoints, SORT_NUMERIC);
            $interiorPoints = $criticalPoints;
            if ($domainLower === -\INF && $domainUpper === \INF && $interiorPoints === []) {
                $interiorPoints[] = 0.0;
            }
            $points = [$domainLower, ...$interiorPoints, $domainUpper];
            $tailSign = static function (int $direction) use ($target): int {
                $degree = \count($target) - 1;
                $sign = $target[$degree] > 0.0 ? 1 : -1;
                if ($direction < 0 && $degree % 2 !== 0) {
                    $sign *= -1;
                }

                return -$sign;
            };
            $boundarySign = function (float $value) use ($arguments, $target, $logarithmScale): ?int {
                $vanishingSign = 0.0;
                $vanishingLogSlope = 0.0;
                $limit = -((new PolynomialSolver())->evaluatePolynomial($target, $value) ?? 0.0);
                foreach ($arguments as $argument) {
                    $coefficients = $argument['coefficients'];
                    $denominatorCoefficients = $argument['denominator'];
                    $constant = $coefficients[0] ?? 0.0;
                    $slope = $coefficients[1] ?? 0.0;
                    $denominatorConstant = $denominatorCoefficients[0] ?? 0.0;
                    $denominatorSlope = $denominatorCoefficients[1] ?? 0.0;
                    $argumentValue = (new PolynomialSolver())->evaluatePolynomial($coefficients, $value);
                    $denominatorValue = (new PolynomialSolver())->evaluatePolynomial(
                        $denominatorCoefficients,
                        $value,
                    );
                    if (
                        $argumentValue === null
                        || $denominatorValue === null
                        || !\is_finite($argumentValue)
                        || !\is_finite($denominatorValue)
                    ) {
                        return null;
                    }
                    $tolerance = 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($constant), \abs($slope * $value));
                    $denominatorTolerance = 16.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($denominatorConstant), \abs($denominatorSlope * $value));
                    if (\abs($argumentValue) <= $tolerance) {
                        $vanishingSign += $argument['sign'];
                        if ($slope !== 0.0) {
                            $vanishingLogSlope += $argument['sign'] * \log(\abs($slope));
                        }
                    }
                    if (\abs($denominatorValue) <= $denominatorTolerance) {
                        $vanishingSign -= $argument['sign'];
                        if ($denominatorSlope !== 0.0) {
                            $vanishingLogSlope -= $argument['sign'] * \log(\abs($denominatorSlope));
                        }
                    }
                    if (
                        \abs($argumentValue) > $tolerance
                        && \abs($denominatorValue) > $denominatorTolerance
                    ) {
                        $limit += ($argument['sign']
                            * (\log(\abs($argumentValue)) - \log(\abs($denominatorValue))))
                            / $logarithmScale;
                    }
                }
                if ($vanishingSign !== 0.0) {
                    return ($vanishingSign / $logarithmScale) > 0.0 ? -1 : 1;
                }
                $limit += $vanishingLogSlope / $logarithmScale;

                return $limit === 0.0 ? null : ($limit > 0.0 ? 1 : -1);
            };
            $endpoint = function (float $value) use (
                $domainLower,
                $domainUpper,
                $lowerOpenBoundary,
                $upperOpenBoundary,
                $tailSign,
                $boundarySign,
                $reducedResidualAt,
            ): ?array {
                if (\is_infinite($value)) {
                    $sign = $tailSign($value < 0.0 ? -1 : 1);

                    return [
                        'value' => $value,
                        'residual' => $sign * \PHP_FLOAT_MAX,
                        'sign' => $sign,
                        'kind' => 'tail',
                    ];
                }
                $residual = $reducedResidualAt($value);
                if (
                    ($value === $domainLower && $lowerOpenBoundary)
                    || ($value === $domainUpper && $upperOpenBoundary)
                ) {
                    return $residual === null ? null : [
                        'value' => $value,
                        'residual' => $residual,
                        'sign' => $residual <=> 0.0,
                        'kind' => 'boundary',
                    ];
                }
                if (
                    $residual === null
                    && ($value === $domainLower || $value === $domainUpper)
                ) {
                    $sign = $boundarySign($value);
                    return [
                        'value' => $value,
                        'residual' => ($sign ?? 0) * \PHP_FLOAT_MAX,
                        'sign' => $sign ?? 0,
                        'kind' => 'boundary',
                    ];
                }

                return $residual === null ? null : [
                    'value' => $value,
                    'residual' => $residual,
                    'sign' => $residual <=> 0.0,
                    'kind' => 'finite',
                ];
            };
            $endpoints = [];
            foreach ($points as $point) {
                $value = $endpoint($point);
                if ($value === null) {
                    continue 2;
                }
                $endpoints[] = $value;
            }
            foreach ($endpoints as $index => &$candidateEndpoint) {
                if ($candidateEndpoint['kind'] !== 'boundary') {
                    continue;
                }
                $isOpenBoundary = ($index === 0 && $lowerOpenBoundary)
                    || ($index === \count($endpoints) - 1 && $upperOpenBoundary);
                if (
                    !$isOpenBoundary
                    || \abs($candidateEndpoint['residual']) > $solverOptions->residualTolerance
                ) {
                    continue;
                }
                $neighbor = $index === 0 ? $endpoints[1] : $endpoints[$index - 1];
                if (\is_infinite($neighbor['value'])) {
                    $direction = $neighbor['value'] < 0.0 ? -1.0 : 1.0;
                    $step = \max(1.0, \abs($candidateEndpoint['value']) * 0.5);
                    $probeResidual = null;
                    for ($probeIteration = 0; $probeIteration < 32; ++$probeIteration) {
                        $probeResidual = $reducedResidualAt(
                            $candidateEndpoint['value'] + ($direction * $step),
                        );
                        if ($probeResidual !== null && $probeResidual !== 0.0) {
                            break;
                        }
                        $step *= 0.5;
                    }
                } else {
                    $probe = ($candidateEndpoint['value'] / 2.0) + ($neighbor['value'] / 2.0);
                    $probeResidual = null;
                    for ($probeIteration = 0; $probeIteration < 32; ++$probeIteration) {
                        $probeResidual = $reducedResidualAt($probe);
                        if ($probeResidual !== null && $probeResidual !== 0.0) {
                            break;
                        }
                        $probe = ($candidateEndpoint['value'] / 2.0) + ($probe / 2.0);
                    }
                }
                if ($probeResidual !== null && $probeResidual !== 0.0) {
                    $candidateEndpoint['sign'] = $probeResidual <=> 0.0;
                    $candidateEndpoint['residual'] = $candidateEndpoint['sign'] * \PHP_FLOAT_MAX;
                    $candidateEndpoint['kind'] = 'open-boundary';
                }
            }
            unset($candidateEndpoint);

            $solutions = [];
            $addCandidate = function (
                float $value,
                int $iterations,
            ) use (
                &$solutions,
                $residualAt,
                $candidateScaleAt,
                $solverOptions,
                $lowerBound,
                $upperBound,
            ): void {
                $residual = $residualAt($value);
                if ($residual === null) {
                    return;
                }
                $value = $this->refineVerifiedEquationCandidate(
                    $value,
                    $residual,
                    $residualAt,
                    $value,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                $residual = $residualAt($value);
                $scale = $candidateScaleAt($value);
                if (
                    $residual === null
                    || $scale === null
                    || \abs($residual) > $solverOptions->residualTolerance * \max(1.0, $scale)
                ) {
                    return;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($value, \abs($residual), $iterations),
                    $solverOptions,
                );
            };
            foreach ($endpoints as $candidateEndpoint) {
                if (
                    $candidateEndpoint['kind'] === 'finite'
                    && $candidateEndpoint['residual'] === 0.0
                ) {
                    $addCandidate($candidateEndpoint['value'], 0);
                }
            }
            foreach ($criticalPoints as $criticalPoint) {
                $residual = $reducedResidualAt($criticalPoint);
                if (
                    $residual !== null
                    && \abs($residual) <= $solverOptions->residualTolerance
                ) {
                    $addCandidate($criticalPoint, 0);
                }
            }
            for ($index = 1, $count = \count($endpoints); $index < $count; ++$index) {
                $first = $endpoints[$index - 1];
                $second = $endpoints[$index];
                if ($first['sign'] === 0 || $second['sign'] === 0 || $first['sign'] === $second['sign']) {
                    continue;
                }
                if ($first['kind'] === 'tail' || $second['kind'] === 'tail') {
                    $tail = $first['kind'] === 'tail' ? $first : $second;
                    $finite = $first['kind'] === 'tail' ? $second : $first;
                    $direction = $tail['value'] < 0.0 ? -1 : 1;
                    $cursor = $finite['value'];
                    $cursorResidual = $finite['residual'];
                    $cursorSign = $finite['sign'];
                    $step = \in_array($finite['kind'], ['boundary', 'open-boundary'], true)
                        ? \max(1.0E-8, 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($cursor)))
                        : \max(1.0, 0.5 * \abs($cursor));
                    $bracket = null;
                    for ($iteration = 0; $iteration < $solverOptions->maxIterations; ++$iteration) {
                        $next = $cursor + ($direction * $step);
                        if (!\is_finite($next) || $next === $cursor) {
                            break;
                        }
                        $nextResidual = $reducedResidualAt($next);
                        if ($nextResidual === null) {
                            $step *= 0.5;
                            continue;
                        }
                        $nextSign = $nextResidual <=> 0.0;
                        if ($nextSign === 0 || $nextSign !== $cursorSign) {
                            $bracket = [$cursor, $cursorResidual, $next, $nextResidual];
                            break;
                        }
                        if ($nextSign === $tail['sign']) {
                            break;
                        }
                        $cursor = $next;
                        $cursorResidual = $nextResidual;
                        $cursorSign = $nextSign;
                        $step *= 2.0;
                    }
                    if ($bracket === null) {
                        continue;
                    }
                    [$firstValue, $firstResidual, $secondValue, $secondResidual] = $bracket;
                    if ($firstValue > $secondValue) {
                        [$firstValue, $secondValue] = [$secondValue, $firstValue];
                        [$firstResidual, $secondResidual] = [$secondResidual, $firstResidual];
                    }
                } else {
                    $firstValue = $first['value'];
                    $firstResidual = $first['residual'];
                    $secondValue = $second['value'];
                    $secondResidual = $second['residual'];
                }
                $hasExactBracketRoot = false;
                foreach ([[$firstValue, $firstResidual], [$secondValue, $secondResidual]] as [$root, $value]) {
                    if ($value !== 0.0) {
                        continue;
                    }
                    $addCandidate($root, 0);
                    $hasExactBracketRoot = true;
                }
                if ($hasExactBracketRoot) {
                    continue;
                }
                if (!$this->hasOppositeSigns($firstResidual, $secondResidual)) {
                    continue;
                }
                $bracketSolutions = $this->bisect(
                    $reducedResidualAt,
                    $firstValue,
                    $firstResidual,
                    $secondValue,
                    $solverOptions,
                    static fn (float $value): float => 1.0,
                    static fn (float $value): bool => false,
                );
                if ($bracketSolutions === []) {
                    continue 2;
                }
                foreach ($bracketSolutions as $bracketSolution) {
                    $addCandidate($bracketSolution->value, $bracketSolution->iterations);
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Reduce sums of same-base logarithms to one logarithm of a polynomial product.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedLogarithmSumPolynomialEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0, 0],
                [$right, $left, $rightSource, $leftSource, 0, 0],
            ] as [
                $logarithmSide,
                $targetSide,
                $logarithmSource,
                $targetSource,
                $logarithmSourceOffset,
                $targetSourceOffset,
            ]
        ) {
            $terms = [];
            $this->flattenAdditiveTerms($logarithmSide, 1.0, $terms);
            if (\count($terms) < 2) {
                continue;
            }

            $product = [1.0];
            $numeratorSources = [];
            $denominatorSources = [];
            $logarithmScale = null;
            foreach ($terms as [$term, $sign]) {
                if ($sign !== 1.0 && $sign !== -1.0) {
                    continue 2;
                }
                $function = $this->unwrapGrouping($term);
                if (!$function instanceof FunctionCallNode) {
                    continue 2;
                }

                $argument = null;
                $scale = 1.0;
                if (
                    \count($function->arguments) === 1
                    && \in_array($function->name, ['ln', 'log1p'], true)
                ) {
                    $argument = $function->arguments[0];
                } elseif (
                    \count($function->arguments) === 1
                    && \in_array($function->name, ['log2', 'log10'], true)
                ) {
                    $argument = $function->arguments[0];
                    $scale = $function->name === 'log2' ? \log(2.0) : \log(10.0);
                } elseif ($function->name === 'log' && \count($function->arguments) === 2) {
                    $base = $this->extractPolynomial(
                        $extractor,
                        $function->arguments[1],
                        $function->arguments[1]->span()->start,
                    );
                    if (
                        $base === null
                        || \count($base) !== 1
                        || !\is_finite($base[0])
                        || $base[0] <= 0.0
                        || $base[0] === 1.0
                    ) {
                        continue 2;
                    }
                    $argument = $function->arguments[0];
                    $scale = \log($base[0]);
                } else {
                    continue 2;
                }
                if ($logarithmScale !== null && $scale !== $logarithmScale) {
                    continue 2;
                }
                $logarithmScale = $scale;

                $argumentCoefficients = $this->extractPolynomial(
                    $extractor,
                    $argument,
                    $argument->span()->start,
                );
                if ($argumentCoefficients === null) {
                    continue 2;
                }
                if ($function->name === 'log1p') {
                    $argumentCoefficients[0] = ($argumentCoefficients[0] ?? 0.0) + 1.0;
                }
                $argumentSpan = $argument->span();
                $argumentSource = \substr(
                    $logarithmSource,
                    $argumentSpan->start - $logarithmSourceOffset,
                    $argumentSpan->end - $argumentSpan->start,
                );
                if ($argumentSource === '') {
                    continue 2;
                }
                if ($function->name === 'log1p') {
                    $argumentSource = '((' . $argumentSource . ')+1)';
                }
                if ($sign > 0.0) {
                    $numeratorSources[] = '(' . $argumentSource . ')';
                } else {
                    $denominatorSources[] = '(' . $argumentSource . ')';
                }
                if (
                    \count($product) + \count($argumentCoefficients) - 2
                    > $solverOptions->maxPolynomialDegree
                ) {
                    continue 2;
                }
                $product = $this->multiplyPolynomials($product, $argumentCoefficients);
                foreach ($product as $coefficient) {
                    if (!\is_finite($coefficient)) {
                        continue 3;
                    }
                }
            }

            $target = $this->extractPolynomial(
                $extractor,
                $targetSide,
                $targetSide->span()->start,
            );
            if ($target === null) {
                continue;
            }
            if ($denominatorSources !== []) {
                $targetSpan = $targetSide->span();
                $targetExpression = \substr(
                    $targetSource,
                    $targetSpan->start - $targetSourceOffset,
                    $targetSpan->end - $targetSpan->start,
                );
                if ($targetExpression === '') {
                    continue;
                }
                $numerator = $numeratorSources === [] ? '1' : \implode('*', $numeratorSources);
                $denominator = \implode('*', $denominatorSources);
                $scaledTarget = $logarithmScale === 1.0
                    ? '(' . $targetExpression . ')'
                    : '((' . $targetExpression . ')*' . \sprintf('%.17g', $logarithmScale) . ')';
                $transformedEquation = 'exp(' . $scaledTarget . ')=('
                    . $numerator . ')/(' . $denominator . ')';
                if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $candidates = $this->solve(
                        $transformedEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (\InvalidArgumentException | \DomainException) {
                    continue;
                }
                $solutions = [];
                $logarithmCandidateScaleAt = static function (float $value) use ($candidateScaleAt): ?float {
                    $scale = $candidateScaleAt($value);

                    return $scale === null ? null : \max(1.0, $scale);
                };
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $logarithmCandidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }

                return $solutions;
            }
            $logarithmCandidateScaleAt = static function (float $value) use ($candidateScaleAt): ?float {
                $scale = $candidateScaleAt($value);

                return $scale === null ? null : \max(1.0, $scale);
            };
            $solutions = $this->solveUnboundedPolynomialLogTarget(
                $product,
                $target,
                $logarithmScale,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $logarithmCandidateScaleAt,
                false,
                [],
                true,
            );
            if ($solutions !== null) {
                return $solutions;
            }
        }

        return null;
    }

    /**
     * Reduce absolute levels of invertible functions to their positive and negative branches.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAbsoluteInvertibleFunctionLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $residualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );

        foreach (
            [
                [$left, $right, $leftSource, 0, true],
                [$right, $left, $rightSource, $rightOffset, false],
            ] as [$absoluteSide, $targetSide, $absoluteSource, $absoluteSourceOffset, $absoluteOnLeft]
        ) {
            $absolute = $this->unwrapGrouping($absoluteSide);
            if (
                !$absolute instanceof FunctionCallNode
                || $absolute->name !== 'abs'
                || \count($absolute->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('abs')
            ) {
                continue;
            }
            $function = $this->unwrapGrouping($absolute->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                !$function instanceof FunctionCallNode
                || !$this->isInvertiblePolynomialLevelFunctionCall($function)
                || $target === null
                || \count($target) !== 1
                || !\is_finite($target[0])
            ) {
                continue;
            }
            if ($target[0] < 0.0) {
                return [];
            }

            $span = $function->span();
            $functionSource = \substr(
                $absoluteSource,
                $span->start - $absoluteSourceOffset,
                $span->end - $span->start,
            );
            if ($functionSource === '') {
                return null;
            }
            $levels = [$target[0]];
            if ($target[0] !== 0.0) {
                $levels[] = -$target[0];
            }
            $solutions = [];
            foreach ($levels as $level) {
                $levelSource = \sprintf('%.17g', $level);
                $equation = $absoluteOnLeft
                    ? '(' . $functionSource . ')=(' . $levelSource . ')'
                    : '(' . $levelSource . ')=(' . $functionSource . ')';
                $candidates = $this->solve(
                    $equation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /** @return list<float>|null */
    private function extractAdditivePolynomialAfterCancellation(
        Node $first,
        Node $second,
        PolynomialExtractor $extractor,
    ): ?array {
        $terms = [];
        $collect = function (Node $node, float $sign) use (&$collect, &$terms): void {
            $node = $this->unwrapGrouping($node);
            if ($node instanceof UnaryOperationNode) {
                $collect(
                    $node->operand,
                    $node->operator === UnaryOperator::Minus ? -$sign : $sign,
                );
                return;
            }
            if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Add) {
                $collect($node->left, $sign);
                $collect($node->right, $sign);
                return;
            }
            if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Subtract) {
                $collect($node->left, $sign);
                $collect($node->right, -$sign);
                return;
            }
            $terms[] = [$node, $sign];
        };
        $collect($first, 1.0);
        $collect($second, 1.0);

        $removed = [];
        foreach ($terms as $firstIndex => [$firstTerm, $firstSign]) {
            if (isset($removed[$firstIndex])) {
                continue;
            }
            foreach ($terms as $secondIndex => [$secondTerm, $secondSign]) {
                if (
                    $secondIndex <= $firstIndex
                    || isset($removed[$secondIndex])
                    || $firstSign === $secondSign
                    || !$this->sameExpression($firstTerm, $secondTerm)
                ) {
                    continue;
                }
                $removed[$firstIndex] = true;
                $removed[$secondIndex] = true;
                break;
            }
        }

        $polynomial = [0.0];
        foreach ($terms as $index => [$term, $sign]) {
            if (isset($removed[$index])) {
                continue;
            }
            $coefficients = $this->extractPolynomial($extractor, $term, $term->span()->start);
            if ($coefficients === null) {
                return null;
            }
            $polynomial = $this->addPolynomials($polynomial, $coefficients, $sign);
        }
        while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)] === 0.0) {
            \array_pop($polynomial);
        }

        return $polynomial;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedInvertibleFunctionLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $absoluteSolutions = $this->solveUnboundedAbsoluteInvertibleFunctionLevelEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($absoluteSolutions !== null) {
            return $absoluteSolutions;
        }

        $leftSign = 1.0;
        $leftCall = $left;
        $leftHasUnarySign = false;
        while (true) {
            $leftCall = $this->unwrapGrouping($leftCall);
            if (!$leftCall instanceof UnaryOperationNode) {
                break;
            }
            $leftHasUnarySign = true;
            if ($leftCall->operator === UnaryOperator::Minus) {
                $leftSign *= -1.0;
            }
            $leftCall = $leftCall->operand;
        }
        $rightSign = 1.0;
        $rightCall = $right;
        $rightHasUnarySign = false;
        while (true) {
            $rightCall = $this->unwrapGrouping($rightCall);
            if (!$rightCall instanceof UnaryOperationNode) {
                break;
            }
            $rightHasUnarySign = true;
            if ($rightCall->operator === UnaryOperator::Minus) {
                $rightSign *= -1.0;
            }
            $rightCall = $rightCall->operand;
        }
        if (
            $leftCall instanceof FunctionCallNode
            && $this->isInvertiblePolynomialLevelFunctionCall($leftCall)
            && !$this->containsVariable($right, $variable)
        ) {
            $function = $leftCall;
            $functionSign = $leftSign;
            $functionHasUnarySign = $leftHasUnarySign;
            $functionSourceSide = $leftSource;
            $functionSourceOffset = 0;
            $otherSource = $rightSource;
            $functionIsLeft = true;
        } elseif (
            $rightCall instanceof FunctionCallNode
            && $this->isInvertiblePolynomialLevelFunctionCall($rightCall)
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $rightCall;
            $functionSign = $rightSign;
            $functionHasUnarySign = $rightHasUnarySign;
            $functionSourceSide = $rightSource;
            $functionSourceOffset = 0;
            $otherSource = $leftSource;
            $functionIsLeft = false;
        } else {
            return null;
        }
        if ($functionHasUnarySign) {
            $span = $function->span();
            $functionSource = \substr(
                $functionSourceSide,
                $span->start,
                $span->end - $span->start,
            );
            if ($functionSource === '') {
                return null;
            }
            $signedOtherSource = $functionSign < 0.0
                ? '(-1)*(' . $otherSource . ')'
                : '(' . $otherSource . ')';
            $normalizedEquation = $functionIsLeft
                ? $functionSource . '=' . $signedOtherSource
                : $signedOtherSource . '=' . $functionSource;
            $normalizedSolutions = $this->solve(
                $normalizedEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($normalizedSolutions as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $solutions[] = new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                );
            }

            return $solutions;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $residualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );

        return $this->solveInvertiblePolynomialLevelEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $extractor,
            $residualAt,
            $candidateScaleAt,
        );
    }

    /**
     * Solve exponentials of polynomial phases against polynomial targets when log reduction applies.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null Null means the equation shape is unsupported here.
     */
    private function solveUnboundedAffineExponentialEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $leftSign = 1.0;
        $leftCall = $left;
        while (true) {
            $leftCall = $this->unwrapGrouping($leftCall);
            if (!$leftCall instanceof UnaryOperationNode) {
                break;
            }
            if ($leftCall->operator === UnaryOperator::Minus) {
                $leftSign *= -1.0;
            }
            $leftCall = $leftCall->operand;
        }
        $rightSign = 1.0;
        $rightCall = $right;
        while (true) {
            $rightCall = $this->unwrapGrouping($rightCall);
            if (!$rightCall instanceof UnaryOperationNode) {
                break;
            }
            if ($rightCall->operator === UnaryOperator::Minus) {
                $rightSign *= -1.0;
            }
            $rightCall = $rightCall->operand;
        }
        if (
            $leftCall instanceof FunctionCallNode
            && $leftCall->name === 'exp'
            && \count($leftCall->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('exp')
        ) {
            $exponential = $leftCall;
            $exponentialSign = $leftSign;
            $linear = $right;
        } elseif (
            $rightCall instanceof FunctionCallNode
            && $rightCall->name === 'exp'
            && \count($rightCall->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('exp')
        ) {
            $exponential = $rightCall;
            $exponentialSign = $rightSign;
            $linear = $left;
        } else {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $exponent = $extractor->extract($exponential->arguments[0]);
        $line = $extractor->extract($linear);
        if (
            $exponent === null
            || $line === null
        ) {
            return null;
        }
        if ($exponentialSign !== 1.0) {
            $line = \array_map(
                static fn (float $coefficient): float => -$coefficient,
                $line,
            );
        }

        if (\count($exponent) > 2 || \count($line) > 2) {
            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );

            return $this->solveUnboundedPolynomialLogTarget(
                $line,
                $exponent,
                1.0,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
            );
        }

        $a = $exponent[1] ?? 0.0;
        $b = $exponent[0] ?? 0.0;
        $c = $line[1] ?? 0.0;
        $d = $line[0] ?? 0.0;
        if (!\is_finite($a) || !\is_finite($b) || !\is_finite($c) || !\is_finite($d)) {
            return null;
        }
        if ($a === 0.0) {
            if ($c === 0.0) {
                return null;
            }
            $root = (\exp($b) - $d) / $c;
            return $this->verifiedAffineExponentialRoots(
                [$root],
                $left,
                $right,
                $rightOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }
        if ($c === 0.0) {
            return null;
        }

        $ratio = $a / $c;
        $logMagnitude = \log(\abs($ratio)) + $b - ($ratio * $d);
        if (!\is_finite($ratio) || !\is_finite($logMagnitude)) {
            return null;
        }
        $lambertBranches = [];
        if ($ratio > 0.0) {
            if ($logMagnitude > -1.0 + (8.0 * \PHP_FLOAT_EPSILON)) {
                return [];
            }
            if (\abs($logMagnitude + 1.0) <= 8.0 * \PHP_FLOAT_EPSILON) {
                $lambertBranches[] = [-1.0, -1.0 / \M_E];
            } else {
                $lambertArgument = -\exp($logMagnitude);
                if ($lambertArgument < 0.0 && \is_finite($lambertArgument)) {
                    $lambertBranches[] = [0.0, $lambertArgument];
                }
                if ($logMagnitude < -100.0) {
                    $lambertBranches[] = [
                        $this->negativeLambertWMinusOneFromLog($logMagnitude),
                        null,
                    ];
                } elseif ($lambertArgument < 0.0 && \is_finite($lambertArgument)) {
                    $lambertBranches[] = [-1.0, $lambertArgument];
                }
            }
        } else {
            if ($logMagnitude > \log(\PHP_FLOAT_MAX)) {
                $lambertBranches[] = [$this->positiveLambertWFromLog($logMagnitude), null];
            } else {
                $lambertArgument = \exp($logMagnitude);
                if ($lambertArgument === 0.0) {
                    return [];
                }
                $lambertBranches[] = [null, $lambertArgument];
            }
        }

        $lambertW = $evaluationOptions->functions->find('lambertw');
        if ($lambertW === null) {
            return null;
        }
        $roots = [];
        foreach ($lambertBranches as [$knownW, $lambertArgument]) {
            if ($knownW === null) {
                try {
                    $w = (float) $lambertW->invoke([$lambertArgument, 0]);
                } catch (EvaluationException | \DomainException) {
                    continue;
                }
            } elseif ($lambertArgument !== null) {
                try {
                    $w = (float) $lambertW->invoke([$lambertArgument, (int) $knownW]);
                } catch (EvaluationException | \DomainException) {
                    continue;
                }
            } else {
                $w = $knownW;
            }
            $root = (-$w / $a) - ($d / $c);
            if (\is_finite($root)) {
                $roots[] = $root;
            }
        }

        return $this->verifiedAffineExponentialRoots(
            $roots,
            $left,
            $right,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
    }

    /**
     * Find verified roots at polynomial-phase extrema for integer trig powers.
     *
     * This supplements, but does not replace, general interval scanning: a variable
     * target can also intersect a trig-power branch away from its extrema.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<float>|null
     */
    private function trigonometricPowerExtremumPositions(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $allPositions = [];
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if ($powerParts === null) {
                continue;
            }
            $phaseCoefficients = $extractor->extract($powerParts[0]->arguments[0]);
            if ($phaseCoefficients === null || \count($phaseCoefficients) < 2) {
                continue;
            }
            $phaseSolver = new PolynomialSolver();
            $derivative = [];
            foreach ($phaseCoefficients as $degree => $coefficient) {
                if ($degree > 0) {
                    $derivative[] = $degree * $coefficient;
                }
            }
            while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                \array_pop($derivative);
            }
            $criticalRoots = $phaseSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($derivative, $value),
                $solverOptions,
                static fn (float $value): ?float => $phaseSolver->evaluatePolynomialMagnitude($derivative, $value),
            );
            if ($criticalRoots === null) {
                return null;
            }
            $phaseRangePositions = [$lowerBound, $upperBound];
            foreach ($criticalRoots as $criticalRoot) {
                if ($criticalRoot->value > $lowerBound && $criticalRoot->value < $upperBound) {
                    $phaseRangePositions[] = $criticalRoot->value;
                }
            }
            $phaseValues = [];
            foreach ($phaseRangePositions as $position) {
                $phaseValue = $phaseSolver->evaluatePolynomial($phaseCoefficients, $position);
                if ($phaseValue === null || !\is_finite($phaseValue)) {
                    return null;
                }
                $phaseValues[] = $phaseValue;
            }
            $minimumPhase = \min($phaseValues);
            $maximumPhase = \max($phaseValues);
            $period = \M_PI;
            $offset = $powerParts[0]->name === 'sin' ? \M_PI / 2.0 : 0.0;
            $firstIndexValue = \ceil(($minimumPhase - $offset) / $period) - 1.0;
            $lastIndexValue = \floor(($maximumPhase - $offset) / $period) + 1.0;
            if (
                !\is_finite($firstIndexValue)
                || !\is_finite($lastIndexValue)
                || \abs($firstIndexValue) >= (float) \PHP_INT_MAX
                || \abs($lastIndexValue) >= (float) \PHP_INT_MAX
                || $lastIndexValue - $firstIndexValue + 1.0 > self::MAX_PERIODIC_ROOTS
            ) {
                return null;
            }

            $positions = [];
            for ($index = (int) $firstIndexValue; $index <= (int) $lastIndexValue; ++$index) {
                $levelPolynomial = $phaseCoefficients;
                $levelPolynomial[0] -= $offset + ($period * $index);
                $roots = $phaseSolver->solve(
                    $levelPolynomial,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($levelPolynomial, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $phaseSolver->evaluatePolynomialMagnitude($levelPolynomial, $value),
                );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    $residual = $residualAt($root->value);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $root->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        $positions[] = $root->value;
                    }
                }
            }

            array_push($allPositions, ...$positions);
        }

        return \array_values(\array_unique($allPositions));
    }

    /**
     * Solve finite-interval integer sine/cosine powers with constant transformed targets.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveFiniteTrigonometricPowerLevelEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if ($powerParts === null || $powerParts[1] >= 0) {
                continue;
            }
            $powerTarget = $this->normalizeEvenPowerTarget($targetSide, $powerParts);
            $targetValue = $this->constantNodeValue($powerTarget, $parameters, $evaluationOptions);
            if ($targetValue === null || !\is_finite($targetValue)) {
                continue;
            }
            $minimum = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
            if ($targetValue < $minimum || $targetValue > 1.0) {
                return [];
            }
            $magnitude = \abs($powerParts[1]);
            $baseMagnitude = $targetValue === 0.0
                ? 0.0
                : \exp(\log(\abs($targetValue)) / $magnitude);
            $baseLevels = $powerParts[1] % 2 === 0
                ? ($baseMagnitude === 0.0 ? [0.0] : [$baseMagnitude, -$baseMagnitude])
                : [$targetValue < 0.0 ? -$baseMagnitude : $baseMagnitude];
            $phase = $powerParts[0]->arguments[0];
            $phaseCoefficients = $extractor->extract($phase);
            if ($phaseCoefficients === null || \count($phaseCoefficients) < 2) {
                continue;
            }

            $phaseSolver = new PolynomialSolver();
            $derivative = [];
            foreach ($phaseCoefficients as $degree => $coefficient) {
                if ($degree > 0) {
                    $derivative[] = $degree * $coefficient;
                }
            }
            while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                \array_pop($derivative);
            }
            $criticalRoots = $phaseSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($derivative, $value),
                $solverOptions,
                static fn (float $value): ?float => $phaseSolver->evaluatePolynomialMagnitude($derivative, $value),
            );
            if ($criticalRoots === null) {
                return null;
            }
            $phasePositions = [$lowerBound, $upperBound];
            foreach ($criticalRoots as $criticalRoot) {
                if ($criticalRoot->value > $lowerBound && $criticalRoot->value < $upperBound) {
                    $phasePositions[] = $criticalRoot->value;
                }
            }
            $phaseValues = [];
            foreach ($phasePositions as $position) {
                $phaseValue = $phaseSolver->evaluatePolynomial($phaseCoefficients, $position);
                if ($phaseValue === null || !\is_finite($phaseValue)) {
                    return null;
                }
                $phaseValues[] = $phaseValue;
            }
            $minimumPhase = \min($phaseValues);
            $maximumPhase = \max($phaseValues);
            $periodicLevels = [];
            foreach ($baseLevels as $baseLevel) {
                $principal = $powerParts[0]->name === 'sin'
                    ? \asin($baseLevel)
                    : \acos($baseLevel);
                $offsets = $powerParts[0]->name === 'sin'
                    ? [$principal, \M_PI - $principal]
                    : [$principal, -$principal];
                foreach ($offsets as $offset) {
                    $period = 2.0 * \M_PI;
                    $firstIndexValue = \ceil(($minimumPhase - $offset) / $period) - 1.0;
                    $lastIndexValue = \floor(($maximumPhase - $offset) / $period) + 1.0;
                    if (
                        !\is_finite($firstIndexValue)
                        || !\is_finite($lastIndexValue)
                        || \abs($firstIndexValue) > 4_503_599_627_370_496.0
                        || \abs($lastIndexValue) > 4_503_599_627_370_496.0
                        || $lastIndexValue - $firstIndexValue + 1.0 > self::MAX_PERIODIC_ROOTS
                    ) {
                        return null;
                    }
                    $firstIndex = (int) $firstIndexValue;
                    $lastIndex = (int) $lastIndexValue;
                    for ($periodIndex = $firstIndex; $periodIndex <= $lastIndex; ++$periodIndex) {
                        $periodicLevels[] = $offset + ($periodIndex * $period);
                        if (\count($periodicLevels) > self::MAX_PERIODIC_ROOTS) {
                            return null;
                        }
                    }
                }
            }

            $solutions = [];
            foreach (\array_unique($periodicLevels) as $level) {
                $levelPolynomial = $phaseCoefficients;
                $levelPolynomial[0] -= $level;
                $phaseRoots = $phaseSolver->solve(
                    $levelPolynomial,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($levelPolynomial, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $phaseSolver->evaluatePolynomialMagnitude($levelPolynomial, $value),
                );
                if ($phaseRoots === null) {
                    return null;
                }
                foreach ($phaseRoots as $phaseRoot) {
                    $residual = $residualAt($phaseRoot->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $phaseRoot->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($phaseRoot->value, \abs($residual), $phaseRoot->iterations),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve reciprocal-square trig identities that reduce to tan(t)^2 = t^2.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveReciprocalTrigonometricQuadraticIdentity(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $powerParts === null
                || $powerParts[1] !== -2
                || $powerParts[2] !== 1.0
                || $powerParts[3] !== 0.0
                || $powerParts[4] !== null
                || !\in_array($powerParts[0]->name, ['sin', 'cos'], true)
            ) {
                continue;
            }
            $phase = $extractor->extract($powerParts[0]->arguments[0]);
            $target = $extractor->extract($targetSide);
            if ($phase === null || $target === null) {
                continue;
            }
            $centeredPhase = $phase;
            if ($powerParts[0]->name === 'sin') {
                $centeredPhase[0] -= \M_PI_2;
            }
            $phaseSquare = $this->multiplyPolynomialCoefficients(
                $centeredPhase,
                $centeredPhase,
                $solverOptions->maxPolynomialDegree,
            );
            if ($phaseSquare === null) {
                continue;
            }
            $expectedTarget = $this->combinePolynomialCoefficients([1.0], $phaseSquare, 1.0);
            if ($expectedTarget === null || \count($expectedTarget) !== \count($target)) {
                continue;
            }
            $matches = true;
            foreach ($expectedTarget as $degree => $coefficient) {
                $actual = $target[$degree] ?? 0.0;
                if (
                    \abs($actual - $coefficient)
                    > 128.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($actual), \abs($coefficient))
                ) {
                    $matches = false;
                    break;
                }
            }
            if (!$matches) {
                continue;
            }

            $phaseSolver = new PolynomialSolver();
            $derivative = [];
            foreach ($centeredPhase as $degree => $coefficient) {
                if ($degree > 0) {
                    $derivative[] = $degree * $coefficient;
                }
            }
            while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                \array_pop($derivative);
            }
            $criticalPoints = [];
            if (\count($derivative) > 1) {
                $criticalRoots = $phaseSolver->solve(
                    $derivative,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($derivative, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $phaseSolver->evaluatePolynomialMagnitude($derivative, $value),
                );
                if ($criticalRoots === null) {
                    return null;
                }
                foreach ($criticalRoots as $root) {
                    $criticalPoints[] = $root->value;
                }
            }
            $phasePositions = [$lowerBound, $upperBound, ...$criticalPoints];
            foreach ($phasePositions as $position) {
                $value = $phaseSolver->evaluatePolynomial($centeredPhase, $position);
                if ($value === null || \abs($value) >= \M_PI_2) {
                    return null;
                }
            }

            $roots = $phaseSolver->solve(
                $centeredPhase,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float => $phaseSolver->evaluatePolynomial($centeredPhase, $value),
                $solverOptions,
                static fn (float $value): ?float =>
                    $phaseSolver->evaluatePolynomialMagnitude($centeredPhase, $value),
            );
            if ($roots === null) {
                return null;
            }
            $solutions = [];
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $solverOptions,
                );
            }

            return $solutions;
        }

        return null;
    }

    /**
     * Clear matching negative powers of sine and cosine while preserving their poles.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveReciprocalTrigonometricPowerEquality(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $leftParts = $this->trigonometricPowerParts($left, $parameters, $evaluationOptions);
        $rightParts = $this->trigonometricPowerParts($right, $parameters, $evaluationOptions);
        if (
            $leftParts === null
            || $rightParts === null
            || $leftParts[1] >= 0
            || $leftParts[1] !== $rightParts[1]
            || $leftParts[2] !== 1.0
            || $rightParts[2] !== 1.0
            || $leftParts[3] !== 0.0
            || $rightParts[3] !== 0.0
            || $leftParts[4] !== null
            || $rightParts[4] !== null
            || !\in_array($leftParts[0]->name, ['sin', 'cos'], true)
            || !\in_array($rightParts[0]->name, ['sin', 'cos'], true)
            || $leftParts[0]->name === $rightParts[0]->name
            || !$this->sameExpression($leftParts[0]->arguments[0], $rightParts[0]->arguments[0])
        ) {
            return null;
        }

        [$leftSource, $rightSource] = $this->splitEquation($equation);
        $leftFunctionSource = $this->trigonometricPowerBaseSource($leftParts[0], $leftSource);
        $rightFunctionSource = $this->trigonometricPowerBaseSource($rightParts[0], $rightSource);
        if ($leftFunctionSource === null || $rightFunctionSource === null) {
            return null;
        }
        $positivePower = \abs($leftParts[1]);
        $leftExpression = $positivePower === 1
            ? $leftFunctionSource
            : '(' . $leftFunctionSource . ')^' . $positivePower;
        $rightExpression = $positivePower === 1
            ? $rightFunctionSource
            : '(' . $rightFunctionSource . ')^' . $positivePower;

        ++$this->finiteRationalTrigonometricReductionDepth;
        try {
            $candidates = $this->solve(
                $leftExpression . '=' . $rightExpression,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } finally {
            --$this->finiteRationalTrigonometricReductionDepth;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }

        return $solutions;
    }

    private function trigonometricPowerBaseSource(FunctionCallNode $base, string $sideSource): ?string
    {
        $argumentSpan = $base->arguments[0]->span();
        $argumentSource = \substr(
            $sideSource,
            $argumentSpan->start,
            $argumentSpan->end - $argumentSpan->start,
        );
        if ($argumentSource === '') {
            return null;
        }

        return $base->name . '(' . $argumentSource . ')';
    }

    /**
     * Restrict rationally scaled trig powers to their finite feasible regions.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveFiniteRationalTrigonometricPowerTarget(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        [$leftSource, $rightSource, $rightOffset] = $this->splitEquation($equation);
        foreach (
            [[$left, $right, $leftSource], [$right, $left, $rightSource]]
            as [$functionSide, $targetSide, $functionSource]
        ) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if ($powerParts === null) {
                continue;
            }
            $target = $this->normalizeEvenPowerTarget($targetSide, $powerParts);
            $targetForm = $exactExtractor->rationalFunction($target);
            if (
                $this->constantNodeValue($target, $parameters, $evaluationOptions) !== null
                || $targetForm === null
            ) {
                continue;
            }
            $normalizedEquation = $this->normalizedTrigonometricPowerEquationSource(
                $powerParts[0],
                $powerParts[1],
                $target,
                $functionSource,
                $variable,
                $exactExtractor,
            );
            if ($normalizedEquation === null) {
                continue;
            }
            $reductionEquation = $powerParts[1] < 0 ? $normalizedEquation : $equation;

            ++$this->finiteRationalTrigonometricReductionDepth;
            try {
                $solutions = $this->solveUnboundedRationalTrigonometricTarget(
                    $reductionEquation,
                    $target,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    true,
                    $powerParts[1] % 2 === 0 ? 0.0 : -1.0,
                    1.0,
                );
            } finally {
                --$this->finiteRationalTrigonometricReductionDepth;
            }
            if ($solutions !== null) {
                $verifiedSolutions = [];
                foreach ($solutions as $solution) {
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    $scale = $this->residualScaleAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $residual === null
                        || $scale === null
                        || !$this->isResidualAcceptableAt(
                            $solution->value,
                            $residual,
                            static fn (float $_): float => $scale,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $verifiedSolutions[] = new EquationSolution(
                        $solution->value,
                        \abs($residual),
                        $solution->iterations,
                    );
                }

                return $this->deduplicateSortedEquationSolutions($verifiedSolutions, $solverOptions);
            }
        }

        return null;
    }

    /**
     * Reduce inverse-function levels against bounded functions to finite polynomial intervals.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialBoundedFunctionEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0, 0],
                [$right, $left, $rightSource, $leftSource, 0, 0],
            ] as [
                $radicalSide,
                $boundedSide,
                $radicalSource,
                $boundedSourceSide,
                $radicalSourceOffset,
                $boundedSourceOffset,
            ]
        ) {
            $radical = $this->unwrapGrouping($radicalSide);
            $isLogarithm = $radical instanceof FunctionCallNode
                && \in_array($radical->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true);
            $isInverseTrigonometric = $radical instanceof FunctionCallNode
                && \in_array($radical->name, ['asin', 'arcsin', 'acos', 'arccos'], true);
            $isInverseHyperbolic = $radical instanceof FunctionCallNode
                && \in_array(
                    $radical->name,
                    ['asinh', 'arcsinh', 'acosh', 'arccosh', 'atanh', 'arctanh'],
                    true,
                );
            $isHyperbolicSine = $radical instanceof FunctionCallNode
                && $radical->name === 'sinh';
            $isHyperbolicCosine = $radical instanceof FunctionCallNode
                && $radical->name === 'cosh';
            $isExponential = $radical instanceof FunctionCallNode && $radical->name === 'exp';
            if (
                !$radical instanceof FunctionCallNode
                || !\in_array(
                    $radical->name,
                    [
                        'sqrt', 'cbrt', 'root', 'abs', 'ln', 'log', 'log10', 'log2', 'log1p',
                        'asin', 'arcsin', 'acos', 'arccos',
                        'asinh', 'arcsinh', 'acosh', 'arccosh', 'atanh', 'arctanh',
                        'sinh', 'cosh',
                        'exp',
                    ],
                    true,
                )
                || !\in_array(\count($radical->arguments), [1, 2], true)
                || (\in_array($radical->name, ['sqrt', 'cbrt', 'abs'], true)
                    && \count($radical->arguments) !== 1)
                || ($radical->name === 'root' && \count($radical->arguments) !== 2)
                || (\in_array($radical->name, ['ln', 'log10', 'log2', 'log1p'], true)
                    && \count($radical->arguments) !== 1)
                || ($radical->name === 'log' && \count($radical->arguments) !== 2)
                || ($isInverseTrigonometric && \count($radical->arguments) !== 1)
                || ($isInverseHyperbolic && \count($radical->arguments) !== 1)
                || (($isHyperbolicSine || $isHyperbolicCosine) && \count($radical->arguments) !== 1)
                || ($isExponential && \count($radical->arguments) !== 1)
                || !$evaluationOptions->functions->isBuiltIn($radical->name)
                || !$this->isContinuousBoundedFunctionTree($boundedSide, $evaluationOptions)
            ) {
                continue;
            }

            $degree = match ($radical->name) {
                'sqrt' => 2.0,
                'cbrt' => 3.0,
                'root' => $this->constantNodeValue(
                    $radical->arguments[1],
                    $parameters,
                    $evaluationOptions,
                ),
                'abs', 'ln', 'log', 'log10', 'log2', 'log1p', 'asin', 'arcsin', 'acos', 'arccos',
                'asinh', 'arcsinh', 'acosh', 'arccosh', 'atanh', 'arctanh', 'sinh', 'cosh', 'exp' => null,
            };
            if ($radical->name === 'root' && $degree !== null) {
                $normalizedDegree = $this->normalizedIntegerRootDegree($degree);
                $degree = $normalizedDegree === null ? null : (float) $normalizedDegree;
            }
            $isAbsoluteValue = $radical->name === 'abs';
            $logarithmBase = match ($radical->name) {
                'ln', 'log1p' => \M_E,
                'log2' => 2.0,
                'log10' => 10.0,
                'log' => $this->constantNodeValue($radical->arguments[1], $parameters, $evaluationOptions),
                default => null,
            };
            if (
                (!$isAbsoluteValue && !$isLogarithm && !$isInverseTrigonometric && !$isInverseHyperbolic
                    && !$isHyperbolicSine && !$isHyperbolicCosine && !$isExponential && (
                    $degree === null
                    || $degree < 2.0
                    || $degree > 64.0
                ))
                || ($isLogarithm && (
                    $logarithmBase === null
                    || !\is_finite($logarithmBase)
                    || $logarithmBase <= 0.0
                    || $logarithmBase === 1.0
                ))
            ) {
                continue;
            }

            $range = $this->boundedTrigonometricExpressionRange(
                $boundedSide,
                $parameters,
                $evaluationOptions,
            );
            if ($isExponential) {
                $periodicRange = $this->extractAffinePeriodicTarget(
                    $boundedSide,
                    $variable,
                    $extractor,
                    $parameters,
                    $evaluationOptions,
                );
                if ($periodicRange !== null && $periodicRange['isPeriodic']) {
                    $range = [$periodicRange['minimum'], $periodicRange['maximum']];
                }
            }
            $polynomial = $extractor->extract($radical->arguments[0]);
            if (
                $range === null
                || $polynomial === null
                || \count($polynomial) < 2
                || !\is_finite($range[0])
                || !\is_finite($range[1])
            ) {
                continue;
            }

            $maximumMagnitude = \max(\abs($range[0]), \abs($range[1]));
            $logarithmLevels = null;
            $inverseHyperbolicLevels = null;
            $hyperbolicLevels = null;
            $exponentialLevels = null;
            $exponentialUsesOriginalEquation = false;
            if ($isLogarithm) {
                if ($radical->name === 'log1p') {
                    $logarithmLevels = [\expm1($range[0]), \expm1($range[1])];
                } else {
                    $logarithmLevels = [
                        \pow($logarithmBase, $range[0]),
                        \pow($logarithmBase, $range[1]),
                    ];
                }
                if (!\is_finite($logarithmLevels[0]) || !\is_finite($logarithmLevels[1])) {
                    continue;
                }
                \sort($logarithmLevels, SORT_NUMERIC);
            }
            if ($isInverseHyperbolic) {
                $inverseHyperbolicLevels = match ($radical->name) {
                    'asinh', 'arcsinh' => [\sinh($range[0]), \sinh($range[1])],
                    'acosh', 'arccosh' => $range[1] < 0.0
                        ? null
                        : [\cosh(\max(0.0, $range[0])), \cosh($range[1])],
                    'atanh', 'arctanh' => [\tanh($range[0]), \tanh($range[1])],
                };
                if ($inverseHyperbolicLevels === null) {
                    return [];
                }
                if (
                    !\is_finite($inverseHyperbolicLevels[0])
                    || !\is_finite($inverseHyperbolicLevels[1])
                ) {
                    continue;
                }
                \sort($inverseHyperbolicLevels, SORT_NUMERIC);
            }
            if ($isHyperbolicSine) {
                $hyperbolicLevels = [\asinh($range[0]), \asinh($range[1])];
            } elseif ($isHyperbolicCosine) {
                if ($range[1] < 1.0) {
                    return [];
                }
                $maximumArgument = \acosh($range[1]);
                $hyperbolicLevels = [-$maximumArgument, $maximumArgument];
            }
            if ($isExponential) {
                if ($range[0] <= 0.0) {
                    if ($range[1] <= 0.0) {
                        return [];
                    }
                    $polynomialDegree = \count($polynomial) - 1;
                    $leadingCoefficient = $polynomial[$polynomialDegree];
                    if ($polynomialDegree % 2 !== 0 || $leadingCoefficient <= 0.0) {
                        continue;
                    }
                    $exponentialLevels = [-\INF, \log($range[1])];
                    $exponentialUsesOriginalEquation = true;
                } else {
                    $exponentialLevels = [\log($range[0]), \log($range[1])];
                }
            }
            if ($isAbsoluteValue) {
                $maximumPower = $maximumMagnitude;
            } elseif (
                $isLogarithm
                || $isInverseTrigonometric
                || $isInverseHyperbolic
                || $isHyperbolicSine
                || $isHyperbolicCosine
                || $isExponential
            ) {
                $maximumPower = 0.0;
            } elseif ($degree !== null) {
                $maximumPower = \pow($maximumMagnitude, $degree);
            } else {
                continue;
            }
            $isEvenRoot = !$isAbsoluteValue && !$isLogarithm && !$isInverseTrigonometric && !$isInverseHyperbolic
                && !$isHyperbolicSine && !$isHyperbolicCosine
                && !$isExponential
                && ((int) $degree % 2 === 0);
            if (
                !$isAbsoluteValue
                && !$isLogarithm
                && !$isInverseTrigonometric
                && !$isInverseHyperbolic
                && !$isHyperbolicSine
                && !$isHyperbolicCosine
                && !$isExponential
                && !\is_finite($maximumPower)
            ) {
                continue;
            }

            $radicand = $radical->arguments[0];
            $radicandSpan = $radicand->span();
            $boundedSpan = $boundedSide->span();
            $radicandSource = \substr(
                $radicalSource,
                $radicandSpan->start - $radicalSourceOffset,
                $radicandSpan->end - $radicandSpan->start,
            );
            $boundedSource = \substr(
                $boundedSourceSide,
                $boundedSpan->start - $boundedSourceOffset,
                $boundedSpan->end - $boundedSpan->start,
            );
            if ($radicandSource === '' || $boundedSource === '') {
                return null;
            }

            $transformedEquation = match (true) {
                $isAbsoluteValue => '((' . $radicandSource . ')^2)=((' . $boundedSource . ')^2)',
                $isLogarithm && $radical->name === 'ln' =>
                    '(' . $radicandSource . ')=exp(' . $boundedSource . ')',
                $isLogarithm && $radical->name === 'log1p' =>
                    '(' . $radicandSource . ')=(exp(' . $boundedSource . ')-1)',
                $isLogarithm => '((' . \sprintf('%.17g', $logarithmBase) . ')^('
                    . $boundedSource . '))=(' . $radicandSource . ')',
                $isInverseTrigonometric && \in_array($radical->name, ['asin', 'arcsin'], true) =>
                    '(' . $radicandSource . ')=sin(' . $boundedSource . ')',
                $isInverseTrigonometric =>
                    '(' . $radicandSource . ')=cos(' . $boundedSource . ')',
                $isInverseHyperbolic && \in_array($radical->name, ['asinh', 'arcsinh'], true) =>
                    '(' . $radicandSource . ')=sinh(' . $boundedSource . ')',
                $isInverseHyperbolic && \in_array($radical->name, ['acosh', 'arccosh'], true) =>
                    '(' . $radicandSource . ')=cosh(' . $boundedSource . ')',
                $isInverseHyperbolic =>
                    '(' . $radicandSource . ')=tanh(' . $boundedSource . ')',
                $isHyperbolicSine =>
                    '(' . $radicandSource . ')=asinh(' . $boundedSource . ')',
                $isHyperbolicCosine =>
                    '(' . $radicandSource . ')=acosh(' . $boundedSource . ')',
                $isExponential =>
                    $exponentialUsesOriginalEquation
                        ? 'exp(' . $radicandSource . ')=(' . $boundedSource . ')'
                        : '(' . $radicandSource . ')=ln(' . $boundedSource . ')',
                default => '(' . $radicandSource . ')=(' . $boundedSource . ')^'
                    . (string) (int) $degree,
            };
            $transformedEquations = ($isHyperbolicCosine || $isExponential)
                ? ['(' . $leftSource . ')=(' . $rightSource . ')']
                : [$transformedEquation];
            foreach ($transformedEquations as $candidateEquation) {
                if (\strlen($candidateEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
            }

            $boundaryRoots = [];
            $polynomialSolver = new PolynomialSolver();
            $boundaryLevels = match (true) {
                $isLogarithm => $logarithmLevels,
                $isInverseTrigonometric => [-1.0, 1.0],
                $isInverseHyperbolic => $inverseHyperbolicLevels,
                $isHyperbolicSine, $isHyperbolicCosine => $hyperbolicLevels,
                $isExponential => $exponentialLevels,
                $isAbsoluteValue => [-$maximumPower, $maximumPower],
                $isEvenRoot => [0.0, $maximumPower],
                default => [-$maximumPower, $maximumPower],
            };
            if ($boundaryLevels === null) {
                continue;
            }
            foreach ($boundaryLevels as $level) {
                if (!\is_finite($level)) {
                    continue;
                }
                $boundaryPolynomial = $polynomial;
                $boundaryPolynomial[0] -= $level;
                while (
                    \count($boundaryPolynomial) > 1
                    && $boundaryPolynomial[\array_key_last($boundaryPolynomial)] === 0.0
                ) {
                    \array_pop($boundaryPolynomial);
                }
                if (\count($boundaryPolynomial) < 2) {
                    continue;
                }

                $leading = \abs($boundaryPolynomial[\array_key_last($boundaryPolynomial)]);
                if ($leading === 0.0 || !\is_finite($leading)) {
                    return null;
                }
                $maximumRatio = 0.0;
                foreach ($boundaryPolynomial as $degree => $coefficient) {
                    if ($degree === \array_key_last($boundaryPolynomial)) {
                        continue;
                    }
                    $ratio = \abs($coefficient) / $leading;
                    if (!\is_finite($ratio)) {
                        return null;
                    }
                    $maximumRatio = \max($maximumRatio, $ratio);
                }
                $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
                if (!\is_finite($rootBound)) {
                    return null;
                }
                $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
                $roots = $polynomialSolver->solve(
                    $boundaryPolynomial,
                    -$rootBound,
                    $rootBound,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($boundaryPolynomial, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($boundaryPolynomial, $value),
                );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    if ($root->value >= $lowerBound && $root->value <= $upperBound) {
                        $boundaryRoots[] = $root->value;
                    }
                }
            }

            \sort($boundaryRoots, SORT_NUMERIC);
            $uniqueRoots = [];
            foreach ($boundaryRoots as $root) {
                $previous = $uniqueRoots[\array_key_last($uniqueRoots)] ?? null;
                if (
                    $previous === null
                    || \abs($root - $previous) > $solverOptions->positionTolerance($root, $previous)
                ) {
                    $uniqueRoots[] = $root;
                }
            }
            if (\count($uniqueRoots) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                return null;
            }

            $boundaries = $uniqueRoots;
            if (\is_finite($lowerBound)) {
                $boundaries[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $boundaries[] = $upperBound;
            }
            \sort($boundaries, SORT_NUMERIC);
            $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
            $intervals = [];
            foreach ($boundaries as $boundary) {
                if ($boundary >= $lowerBound && $boundary <= $upperBound) {
                    $intervals[] = [$boundary, $boundary];
                }
            }

            $partition = $boundaries;
            if ($lowerBound === -\INF) {
                \array_unshift($partition, -\INF);
            }
            if ($upperBound === \INF) {
                $partition[] = \INF;
            }
            for ($index = 0; $index + 1 < \count($partition); ++$index) {
                $intervalLower = $partition[$index];
                $intervalUpper = $partition[$index + 1];
                if ($intervalLower >= $intervalUpper) {
                    continue;
                }
                $sample = match (true) {
                    $intervalLower === -\INF && $intervalUpper === \INF => 0.0,
                    $intervalLower === -\INF => $intervalUpper - \max(1.0, 0.5 * \abs($intervalUpper)),
                    $intervalUpper === \INF => $intervalLower + \max(1.0, 0.5 * \abs($intervalLower)),
                    default => ($intervalLower / 2.0) + ($intervalUpper / 2.0),
                };
                $sampleValue = $polynomialSolver->evaluatePolynomial($polynomial, $sample);
                if (
                    $sampleValue === null
                    || $sampleValue < \min($boundaryLevels)
                    || $sampleValue > \max($boundaryLevels)
                ) {
                    continue;
                }
                if (!\is_finite($intervalLower) || !\is_finite($intervalUpper)) {
                    return null;
                }
                $intervals[] = [$intervalLower, $intervalUpper];
            }

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($intervals as [$intervalLower, $intervalUpper]) {
                $candidates = [];
                foreach ($transformedEquations as $candidateEquation) {
                    try {
                        $branchCandidates = $this->solve(
                            $candidateEquation,
                            $variable,
                            $intervalLower,
                            $intervalUpper,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (\InvalidArgumentException) {
                        return null;
                    }
                    \array_push($candidates, ...$branchCandidates);
                }
                if (
                    $isHyperbolicCosine
                    || ($isInverseHyperbolic
                        && \in_array($radical->name, ['asinh', 'arcsinh', 'atanh', 'arctanh'], true))
                ) {
                    $zeroLevelRoots = $polynomialSolver->solve(
                        $polynomial,
                        $intervalLower,
                        $intervalUpper,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomial($polynomial, $value),
                        $solverOptions,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomialMagnitude($polynomial, $value),
                    );
                    if ($zeroLevelRoots === null) {
                        return null;
                    }
                    foreach ($zeroLevelRoots as $root) {
                        $candidates[] = new EquationSolution($root->value, 0.0, $root->iterations);
                    }
                }
                foreach ($candidates as $candidate) {
                    $candidateValue = $candidate->value;
                    $residual = $residualAt($candidateValue);
                    if ($residual !== null) {
                        $candidateValue = $this->refineVerifiedEquationCandidate(
                            $candidateValue,
                            $residual,
                            $residualAt,
                            $candidateValue,
                            $intervalLower,
                            $intervalUpper,
                            $solverOptions,
                        );
                        $residual = $residualAt($candidateValue);
                    }
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidateValue,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidateValue,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve unbounded equations where an integer sine/cosine power meets a rational target.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedTrigonometricPowerEquation(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        [$leftSource, $rightSource, $rightOffset] = $this->splitEquation($equation);
        foreach (
            [
                [$left, $right, $leftSource],
                [$right, $left, $rightSource],
            ] as [$functionSide, $targetSide, $functionSource]
        ) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if ($powerParts === null) {
                continue;
            }
            $normalizedTarget = $this->normalizeEvenPowerTarget($targetSide, $powerParts);
            $minimumTarget = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
            $exactExtractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $evaluationOptions,
            );
            if (
                (!\is_finite($lowerBound) || !\is_finite($upperBound))
                && (
                $this->hasInfiniteRootsFromTrigonometricPowerAtRangeBoundary(
                    $functionSide,
                    $targetSide,
                    $exactExtractor,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                )
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'The trigonometric power equation has infinitely many roots approaching a range boundary.',
                );
            }
            $targetForm = $exactExtractor->rationalFunction($normalizedTarget);
            $constantTarget = $this->constantNodeValue($normalizedTarget, $parameters, $evaluationOptions);
            $targetLimit = $targetForm === null
                ? $constantTarget
                : $this->rationalFunctionLimitAtInfinity($targetForm);
            $phase = $exactExtractor->polynomial($powerParts[0]->arguments[0]);
            if (
                (!\is_finite($lowerBound) || !\is_finite($upperBound))
                && (
                $targetLimit !== null
                && $targetLimit > $minimumTarget
                && $targetLimit < 1.0
                && $phase !== null
                && \count($phase) > 1
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'The trigonometric power equation has infinitely many roots approaching an interior target.',
                );
            }
            if (
                (!\is_finite($lowerBound) || !\is_finite($upperBound))
                && $constantTarget !== null
                && $targetLimit !== null
                && $targetLimit >= $minimumTarget
                && $targetLimit <= 1.0
                && $phase !== null
                && \count($phase) > 1
            ) {
                throw new InfiniteSolutionSetException(
                    'The trigonometric power equation has infinitely many roots at a constant feasible target.',
                );
            }
            $normalizedEquation = $this->normalizedTrigonometricPowerEquationSource(
                $powerParts[0],
                $powerParts[1],
                $normalizedTarget,
                $functionSource,
                $variable,
                $exactExtractor,
            ) ?? $equation;
            $solutions = $this->solveUnboundedRationalTrigonometricTarget(
                $normalizedEquation,
                $normalizedTarget,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $extractor,
                true,
                $minimumTarget,
                1.0,
            );
            if ($solutions !== null) {
                $verifiedSolutions = [];
                foreach ($solutions as $solution) {
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    $scale = $this->residualScaleAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $residual === null
                        || $scale === null
                        || !$this->isResidualAcceptableAt(
                            $solution->value,
                            $residual,
                            static fn (float $_): float => $scale,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $verifiedSolutions[] = new EquationSolution(
                        $solution->value,
                        \abs($residual),
                        $solution->iterations,
                    );
                }

                return $this->deduplicateSortedEquationSolutions($verifiedSolutions, $solverOptions);
            }
        }

        return null;
    }

    /**
     * Classify absolute sine and cosine levels with nonconstant polynomial phases.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAbsolutePeriodicLevelEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$periodicSide, $targetSide]) {
            $absolute = $this->unwrapGrouping($periodicSide);
            if (
                !$absolute instanceof FunctionCallNode
                || $absolute->name !== 'abs'
                || \count($absolute->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('abs')
            ) {
                continue;
            }
            $periodic = $this->unwrapGrouping($absolute->arguments[0]);
            if (
                !$periodic instanceof FunctionCallNode
                || !\in_array($periodic->name, ['sin', 'cos'], true)
                || \count($periodic->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($periodic->name)
            ) {
                continue;
            }
            $phase = $extractor->extract($periodic->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                $phase === null
                || \count($phase) < 2
                || $target === null
                || \count($target) !== 1
                || !\is_finite($target[0])
            ) {
                continue;
            }
            if ($target[0] < 0.0 || $target[0] > 1.0) {
                return [];
            }

            throw new InfiniteSolutionSetException(
                'An absolute sine or cosine with a nonconstant polynomial phase reaches each value in [0, 1] '
                . 'infinitely many times on an unbounded interval.',
            );
        }

        return null;
    }

    /**
     * Resolve reciprocal sinc identities by reducing them to sine levels.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedSincReciprocalEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );

        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $quotientSide]) {
            $function = $this->unwrapGrouping($functionSide);
            $functionSign = 1.0;
            while ($function instanceof UnaryOperationNode) {
                if ($function->operator === UnaryOperator::Minus) {
                    $functionSign *= -1.0;
                }
                $function = $this->unwrapGrouping($function->operand);
            }
            $quotient = $this->unwrapGrouping($quotientSide);
            $quotientSign = 1.0;
            while ($quotient instanceof UnaryOperationNode) {
                if ($quotient->operator === UnaryOperator::Minus) {
                    $quotientSign *= -1.0;
                }
                $quotient = $this->unwrapGrouping($quotient->operand);
            }
            if (
                !$function instanceof FunctionCallNode
                || !\in_array($function->name, ['sinc', 'sincpi'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }

            $phaseForm = $extractor->extractRationalForm(
                $function->arguments[0],
            );
            if ($phaseForm === null) {
                continue;
            }
            $sineTarget = null;
            $quotientMultiplier = 1.0;
            $quotientSinc = $this->sincQuotientFunction(
                $quotient,
                $extractor,
                $quotientMultiplier,
            );
            if ($quotientSinc !== null) {
                $quotientSign *= $quotientMultiplier;
                $quotientPhaseForm = $extractor->extractRationalForm(
                    $quotientSinc->arguments[0],
                );
                $scaledPhaseNumerator = $function->name === 'sincpi'
                    ? $this->multiplyPolynomialCoefficients(
                        $phaseForm[0],
                        [\M_PI],
                        $solverOptions->maxPolynomialDegree,
                    )
                    : $phaseForm[0];
                if ($quotientPhaseForm !== null && $scaledPhaseNumerator !== null) {
                    $leftCrossProduct = $this->multiplyPolynomialCoefficients(
                        $quotientPhaseForm[0],
                        $phaseForm[1],
                        $solverOptions->maxPolynomialDegree,
                    );
                    $rightCrossProduct = $this->multiplyPolynomialCoefficients(
                        $scaledPhaseNumerator,
                        $quotientPhaseForm[1],
                        $solverOptions->maxPolynomialDegree,
                    );
                    if ($leftCrossProduct !== null && $rightCrossProduct !== null) {
                        $phaseRatio = $this->proportionalPolynomialRatio(
                            $leftCrossProduct,
                            $rightCrossProduct,
                        );
                        if ($phaseRatio === 1.0 || $phaseRatio === -1.0) {
                            if ($functionSign === $quotientSign) {
                                throw new InfiniteSolutionSetException(
                                    'The sinc equation is an identity on its shared domain.',
                                );
                            }
                            if (
                                $lowerBound === -\INF
                                || $upperBound === \INF
                                || $this->rationalPhaseHasPoleInInterval(
                                    $phaseForm,
                                    $lowerBound,
                                    $upperBound,
                                    $solverOptions,
                                )
                            ) {
                                $sineTarget = 0.0;
                            }
                        } elseif (
                            $phaseRatio !== null
                            && \abs($phaseRatio) > 0.0
                            && \abs($phaseRatio) !== 1.0
                            && $this->hasRationalPhaseRatio(
                                $phaseRatio,
                                $quotientSinc->arguments[0],
                                $function->arguments[0],
                                $function->name === 'sincpi',
                                $variable,
                                $parameters,
                                $evaluationOptions,
                                $solverOptions->maxPolynomialDegree,
                            )
                            && (
                                $lowerBound === -\INF
                                || $upperBound === \INF
                                || $this->rationalPhaseHasPoleInInterval(
                                    $phaseForm,
                                    $lowerBound,
                                    $upperBound,
                                    $solverOptions,
                                )
                            )
                        ) {
                            $sineTarget = 0.0;
                        }
                    }
                }
            }

            if ($sineTarget === null) {
                $quotientForm = $extractor->extractRationalForm($quotient);
                if ($quotientForm === null || $quotientForm[1] === [0.0]) {
                    continue;
                }
                $phaseTimesNumerator = $this->multiplyPolynomialCoefficients(
                    $phaseForm[0],
                    $quotientForm[0],
                    $solverOptions->maxPolynomialDegree,
                );
                $combinedDenominator = $this->multiplyPolynomialCoefficients(
                    $phaseForm[1],
                    $quotientForm[1],
                    $solverOptions->maxPolynomialDegree,
                );
                if ($phaseTimesNumerator === null || $combinedDenominator === null) {
                    continue;
                }
                $constantTarget = $this->proportionalPolynomialRatio(
                    $phaseTimesNumerator,
                    $combinedDenominator,
                );
                if ($constantTarget === null) {
                    continue;
                }
                $constantTarget *= $functionSign * $quotientSign;

                $sineTarget = $function->name === 'sincpi'
                    ? $constantTarget * \M_PI
                    : $constantTarget;
                if (!\is_finite($sineTarget)) {
                    return [];
                }
                if (\abs($sineTarget) > 1.0) {
                    return [];
                }
            }

            $phaseNumerator = $phaseForm[0];
            $phaseDenominator = $phaseForm[1];
            while (\count($phaseNumerator) > 1 && $phaseNumerator[\array_key_last($phaseNumerator)] === 0.0) {
                \array_pop($phaseNumerator);
            }
            while (
                \count($phaseDenominator) > 1
                && $phaseDenominator[\array_key_last($phaseDenominator)] === 0.0
            ) {
                \array_pop($phaseDenominator);
            }
            if (\count($phaseDenominator) === 1) {
                if (\count($phaseNumerator) < 2) {
                    continue;
                }

                if ($lowerBound === -\INF || $upperBound === \INF) {
                    throw new InfiniteSolutionSetException(
                        'The reciprocal sinc identity reduces to a nonconstant polynomial sine phase.',
                    );
                }
            }
            if (
                \count($phaseNumerator) > \count($phaseDenominator)
                && ($lowerBound === -\INF || $upperBound === \INF)
            ) {
                throw new InfiniteSolutionSetException(
                    'The reciprocal sinc identity has an unbounded rational sine phase.',
                );
            }

            $sinePhase = $function->arguments[0];
            if ($function->name === 'sincpi') {
                $pi = new NumberNode(
                    \M_PI,
                    \sprintf('%.17g', \M_PI),
                    $sinePhase->span(),
                );
                $sinePhase = new BinaryOperationNode(
                    BinaryOperator::Multiply,
                    $pi,
                    $sinePhase,
                    $sinePhase->span(),
                );
            }
            $sineFunction = new FunctionCallNode(
                'sin',
                [$sinePhase],
                $function->nameSpan,
                $function->span(),
            );
            $sineTargetNode = new NumberNode(
                $sineTarget,
                \sprintf('%.17g', $sineTarget),
                $quotient->span(),
            );
            $this->throwIfPeriodicRationalArgumentHasPole(
                $sineFunction,
                $sineTargetNode,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $evaluationOptions,
                $parameters,
            );
            $solutions = $this->solveRationalPeriodicFunction(
                $sineFunction,
                $sineTargetNode,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
            );
            if ($solutions !== null) {
                return $solutions;
            }

            return null;
        }

        return null;
    }

    private function isUnboundedAffineTrigonometricPair(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): bool {
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            while ($side instanceof UnaryOperationNode) {
                $side = $this->unwrapGrouping($side->operand);
            }
            if (
                !$side instanceof FunctionCallNode
                || !\in_array($side->name, ['sin', 'cos'], true)
                || \count($side->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($side->name)
            ) {
                return false;
            }
            $phase = $this->extractPolynomial(
                $extractor,
                $side->arguments[0],
                $side->arguments[0]->span()->start,
            );
            if ($phase === null || \count($phase) !== 2 || $phase[1] === 0.0) {
                return false;
            }
        }

        return true;
    }

    /**
     * The real Gamma function has no zeros, so gamma(f(x)) = 0 has no roots.
     *
     * @param array<string, int|float> $parameters
     */
    private function isGammaZeroLevelEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$function, $target]) {
            $function = $this->unwrapGrouping($function);
            if (
                !$function instanceof FunctionCallNode
                || $function->name !== 'gamma'
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            $targetDifference = $extractor->rationalDifference(
                $target,
                new NumberNode(0, '0', $target->span()),
            );
            if (
                $targetDifference !== null
                && \count($targetDifference[0]) === 1
                && $targetDifference[0][0] === '0'
            ) {
                return true;
            }
        }

        return false;
    }

    private function isPositiveTrigammaExponentialReciprocalSineWithoutZero(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if (!\is_finite($lowerBound) || $lowerBound >= 0.0 || $upperBound !== 0.0) {
            return false;
        }

        foreach ([[$left, $right], [$right, $left]] as [$periodicNode, $targetNode]) {
            $periodicNode = $this->unwrapGrouping($periodicNode);
            if (
                !$periodicNode instanceof FunctionCallNode
                || $periodicNode->name !== 'sin'
                || \count($periodicNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('sin')
            ) {
                continue;
            }
            try {
                if ((float) $this->constantNodeValue($targetNode, $parameters, $evaluationOptions) !== 0.0) {
                    continue;
                }
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            $trigamma = $this->unwrapGrouping($periodicNode->arguments[0]);
            if (
                !$trigamma instanceof FunctionCallNode
                || $trigamma->name !== 'trigamma'
                || \count($trigamma->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('trigamma')
            ) {
                continue;
            }
            $exponential = $this->unwrapGrouping($trigamma->arguments[0]);
            if (
                !$exponential instanceof FunctionCallNode
                || $exponential->name !== 'exp'
                || \count($exponential->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('exp')
            ) {
                continue;
            }
            $exponent = $this->unwrapGrouping($exponential->arguments[0]);
            if (!$exponent instanceof BinaryOperationNode || $exponent->operator !== BinaryOperator::Divide) {
                continue;
            }
            $numerator = $this->unwrapGrouping($exponent->left);
            $denominator = $this->unwrapGrouping($exponent->right);
            if (
                !$numerator instanceof UnaryOperationNode
                || $numerator->operator !== UnaryOperator::Minus
                || !$denominator instanceof VariableNode
                || $denominator->name !== $variable
            ) {
                continue;
            }
            try {
                $positiveNumerator = $this->constantNodeValue(
                    $numerator->operand,
                    $parameters,
                    $evaluationOptions,
                );
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            if ($positiveNumerator <= 0.0 || !\is_finite($positiveNumerator)) {
                continue;
            }

            $minimumExponent = $positiveNumerator / -$lowerBound;
            $minimumArgument = \exp($minimumExponent);
            $trigammaUpperBound = $minimumArgument === \INF
                ? 0.0
                : (1.0 / $minimumArgument) + (1.0 / ($minimumArgument * $minimumArgument));
            if ($trigammaUpperBound < \M_PI) {
                return true;
            }
        }

        return false;
    }

    private function isNegativeDigammaExponentialReciprocalProductSineWithoutZero(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if (!\is_finite($lowerBound) || $lowerBound >= 0.0 || $upperBound !== 0.0) {
            return false;
        }
        foreach ([[$left, $right], [$right, $left]] as [$periodicNode, $targetNode]) {
            $periodicNode = $this->unwrapGrouping($periodicNode);
            if (
                !$periodicNode instanceof FunctionCallNode
                || $periodicNode->name !== 'sin'
                || \count($periodicNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('sin')
            ) {
                continue;
            }
            try {
                if ((float) $this->constantNodeValue($targetNode, $parameters, $evaluationOptions) !== 0.0) {
                    continue;
                }
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            $phase = $this->unwrapGrouping($periodicNode->arguments[0]);
            if (!$phase instanceof BinaryOperationNode || $phase->operator !== BinaryOperator::Multiply) {
                continue;
            }
            foreach ([[$phase->left, $phase->right], [$phase->right, $phase->left]] as [$variableNode, $digammaNode]) {
                $variableNode = $this->unwrapGrouping($variableNode);
                $digammaNode = $this->unwrapGrouping($digammaNode);
                if (
                    !$variableNode instanceof VariableNode
                    || $variableNode->name !== $variable
                    || !$digammaNode instanceof FunctionCallNode
                    || $digammaNode->name !== 'digamma'
                    || \count($digammaNode->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn('digamma')
                ) {
                    continue;
                }
                $exponential = $this->unwrapGrouping($digammaNode->arguments[0]);
                if (
                    !$exponential instanceof FunctionCallNode
                    || $exponential->name !== 'exp'
                    || \count($exponential->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn('exp')
                ) {
                    continue;
                }
                $exponent = $this->unwrapGrouping($exponential->arguments[0]);
                if (!$exponent instanceof BinaryOperationNode || $exponent->operator !== BinaryOperator::Divide) {
                    continue;
                }
                $numerator = $this->unwrapGrouping($exponent->left);
                $denominator = $this->unwrapGrouping($exponent->right);
                if (
                    !$numerator instanceof UnaryOperationNode
                    || $numerator->operator !== UnaryOperator::Minus
                    || !$denominator instanceof VariableNode
                    || $denominator->name !== $variable
                ) {
                    continue;
                }
                try {
                    $scale = (float) $this->constantNodeValue(
                        $numerator->operand,
                        $parameters,
                        $evaluationOptions,
                    );
                } catch (EvaluationException | \DomainException | \OverflowException) {
                    continue;
                }
                if ($scale <= 0.0 || $scale >= \M_PI || !\is_finite($scale)) {
                    continue;
                }
                $minimumArgument = \exp($scale / -$lowerBound);
                if ($minimumArgument === \INF) {
                    return true;
                }
                try {
                    if (SpecialFunctions::digamma($minimumArgument) > 0.0) {
                        return true;
                    }
                } catch (\DomainException | \OverflowException) {
                    continue;
                }
            }
        }

        return false;
    }

    /** @return list<EquationSolution>|null */
    private function solvePeriodicLogAbsoluteGammaAtRemovableHoles(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$periodicNode, $targetNode]) {
            $periodicNode = $this->unwrapGrouping($periodicNode);
            if (
                !$periodicNode instanceof FunctionCallNode
                || $periodicNode->name !== 'sin'
                || \count($periodicNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('sin')
            ) {
                continue;
            }
            try {
                if ((float) $this->constantNodeValue($targetNode, $parameters, $evaluationOptions) !== 0.0) {
                    continue;
                }
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            $logarithm = $this->unwrapGrouping($periodicNode->arguments[0]);
            if (
                !$logarithm instanceof FunctionCallNode
                || $logarithm->name !== 'ln'
                || \count($logarithm->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('ln')
            ) {
                continue;
            }
            $absolute = $this->unwrapGrouping($logarithm->arguments[0]);
            if (
                !$absolute instanceof FunctionCallNode
                || $absolute->name !== 'abs'
                || \count($absolute->arguments) !== 1
            ) {
                continue;
            }
            $gamma = $this->unwrapGrouping($absolute->arguments[0]);
            if (
                !$gamma instanceof FunctionCallNode
                || $gamma->name !== 'gamma'
                || \count($gamma->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('gamma')
            ) {
                continue;
            }
            $absolutePolynomial = $this->extractAbsolutePolynomial(
                $gamma->arguments[0],
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($absolutePolynomial === null || $absolutePolynomial[1] === []) {
                continue;
            }
            [$coefficients, $holes] = $absolutePolynomial;
            $argumentRange = $this->polynomialRange(
                $coefficients,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($argumentRange === null) {
                continue;
            }
            $gammaRange = $this->gammaIntervalRange($argumentRange, $evaluationOptions);
            if ($gammaRange === null || ($gammaRange[0] <= 0.0 && $gammaRange[1] >= 0.0)) {
                continue;
            }
            if ($gammaRange[0] > 0.0) {
                $minimumAbsoluteGamma = $gammaRange[0];
                $maximumAbsoluteGamma = $gammaRange[1];
                $gammaLevel = 1.0;
            } else {
                $minimumAbsoluteGamma = -$gammaRange[1];
                $maximumAbsoluteGamma = -$gammaRange[0];
                $gammaLevel = -1.0;
            }
            if (
                $minimumAbsoluteGamma <= \exp(-\M_PI)
                || $maximumAbsoluteGamma >= \exp(\M_PI)
            ) {
                continue;
            }
            $argumentSource = $this->polynomialCoefficientsSource($coefficients, $variable);
            if ($argumentSource === null) {
                continue;
            }
            try {
                $levelSolutions = $this->solve(
                    'gamma(' . $argumentSource . ')=' . \sprintf('%.17g', $gammaLevel),
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (RootSearchLimitException | InfiniteRootAccumulationException | \DomainException) {
                continue;
            }
            foreach ($levelSolutions as $solution) {
                $isExcludedHole = false;
                foreach ($holes as $hole) {
                    $holeTolerance = 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($hole));
                    if (\abs($solution->value - $hole) <= $holeTolerance) {
                        $isExcludedHole = true;
                        break;
                    }
                }
                if (!$isExcludedHole) {
                    return null;
                }
            }

            return [];
        }

        return null;
    }

    /**
     * Enumerate real trivial zeros of zeta along an affine phase.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedZetaTrivialZeros(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $targetNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || $functionNode->name !== 'zeta'
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('zeta')
            ) {
                continue;
            }
            $targetCoefficients = $extractor->extract($targetNode);
            if ($targetCoefficients !== [0.0]) {
                continue;
            }
            $phase = $extractor->extract($functionNode->arguments[0]);
            if ($phase === null) {
                return null;
            }
            while (\count($phase) > 1 && $phase[\array_key_last($phase)] === 0.0) {
                \array_pop($phase);
            }
            if (\count($phase) === 1) {
                $constant = $phase[0];
                if ($constant < 0.0 && $constant / 2.0 === \floor($constant / 2.0)) {
                    throw new InfiniteSolutionSetException(
                        'The zeta function is zero for every input in the requested interval.',
                    );
                }

                return [];
            }

            $phaseRange = $this->polynomialRangeWithInfiniteBounds(
                $phase,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($phaseRange === null) {
                return null;
            }
            [$phaseLower, $phaseUpper] = $phaseRange;
            if ($phaseLower === -\INF) {
                throw new InfiniteSolutionSetException(
                    'The interval contains infinitely many negative even zeta zeros.',
                );
            }
            if (!\is_finite($phaseLower) || \is_nan($phaseUpper)) {
                return null;
            }
            $firstIndex = $phaseUpper === \INF
                ? 1.0
                : \max(1.0, \ceil(-$phaseUpper / 2.0));
            $lastIndex = \floor(-$phaseLower / 2.0);
            if ($lastIndex < $firstIndex) {
                return [];
            }
            if (
                $firstIndex > 4_503_599_627_370_496.0
                || $lastIndex > 4_503_599_627_370_496.0
                || $lastIndex - $firstIndex + 1.0 > self::MAX_PERIODIC_ROOTS
            ) {
                throw new RootSearchLimitException(
                    \sprintf(
                        'The interval contains more than %d enumerable zeta zeros.',
                        self::MAX_PERIODIC_ROOTS,
                    ),
                );
            }

            $solutions = [];
            $polynomialSolver = new PolynomialSolver();
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $levelCoefficients = $phase;
                $levelCoefficients[0] += 2.0 * $index;
                $levelSolutions = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($levelCoefficients, $value),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value),
                );
                if ($levelSolutions === null) {
                    return null;
                }
                foreach ($levelSolutions as $levelSolution) {
                    $solutions[] = new EquationSolution(
                        $levelSolution->value,
                        0.0,
                        $levelSolution->iterations,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Return a polynomial's range on an interval with finite or infinite bounds.
     *
     * @param list<float> $coefficients
     * @return array{float, float}|null
     */
    private function polynomialRangeWithInfiniteBounds(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): ?array {
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) === 1) {
            return [$coefficients[0], $coefficients[0]];
        }
        $degree = \count($coefficients) - 1;
        $leadingCoefficient = $coefficients[$degree];
        if (!\is_finite($leadingCoefficient) || $leadingCoefficient === 0.0) {
            return null;
        }
        $lowerValue = $lowerBound === -\INF
            ? (($degree % 2 === 0 ? 1.0 : -1.0) * $leadingCoefficient < 0.0 ? -\INF : \INF)
            : $this->polynomialValue($coefficients, $lowerBound);
        $upperValue = $upperBound === \INF
            ? ($leadingCoefficient < 0.0 ? -\INF : \INF)
            : $this->polynomialValue($coefficients, $upperBound);
        if ($lowerValue === null || $upperValue === null) {
            return null;
        }
        $values = [$lowerValue, $upperValue];
        $derivative = [];
        for ($power = 1; $power <= $degree; ++$power) {
            $coefficient = $power * $coefficients[$power];
            if (!\is_finite($coefficient)) {
                return null;
            }
            $derivative[] = $coefficient;
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }
        if (\count($derivative) > 1) {
            $polynomialSolver = new PolynomialSolver();
            $criticalLowerBound = $lowerBound;
            $criticalUpperBound = $upperBound;
            if (!\is_finite($criticalLowerBound) || !\is_finite($criticalUpperBound)) {
                $leadingMagnitude = \abs($derivative[\array_key_last($derivative)]);
                if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                    return null;
                }
                $maximumRatio = 0.0;
                foreach (\array_slice($derivative, 0, -1) as $coefficient) {
                    $ratio = \abs($coefficient) / $leadingMagnitude;
                    if (!\is_finite($ratio)) {
                        $ratio = \PHP_FLOAT_MAX;
                    }
                    $maximumRatio = \max($maximumRatio, $ratio);
                }
                $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
                if (!\is_finite($rootBound)) {
                    $rootBound = \PHP_FLOAT_MAX;
                }
                $criticalLowerBound = \max($criticalLowerBound, -$rootBound);
                $criticalUpperBound = \min($criticalUpperBound, $rootBound);
            }
            if ($criticalLowerBound > $criticalUpperBound) {
                return null;
            }
            $criticalPoints = $polynomialSolver->solve(
                $derivative,
                $criticalLowerBound,
                $criticalUpperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($derivative, $value),
                $solverOptions,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($derivative, $value),
            );
            if ($criticalPoints === null) {
                return null;
            }
            foreach ($criticalPoints as $criticalPoint) {
                $value = $polynomialSolver->evaluatePolynomial($coefficients, $criticalPoint->value);
                if ($value === null) {
                    return null;
                }
                $values[] = $value;
            }
        }

        return [\min(...$values), \max(...$values)];
    }

    /**
     * Solve Dawson intersections with a line through the origin on unbounded intervals.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedDawsonLinearEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $targetNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || $functionNode->name !== 'dawson'
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('dawson')
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            if (!$argument instanceof VariableNode || $argument->name !== $variable) {
                continue;
            }
            $targetCoefficients = $this->extractPolynomial(
                $extractor,
                $targetNode,
                $targetNode->span()->start,
            );
            if (
                $targetCoefficients === null
                || \count($targetCoefficients) > 2
                || ($targetCoefficients[0] ?? 0.0) !== 0.0
            ) {
                continue;
            }

            $slope = $targetCoefficients[1] ?? 0.0;
            $roots = [new EquationSolution(0.0, 0.0, 0)];
            if ($slope > 0.0 && $slope < 1.0) {
                $estimate = \sqrt(1.5 * (1.0 - $slope));
                $lower = $estimate / 2.0;
                $upper = \max($estimate * 2.0, 2.0 / \sqrt($slope));
                if (!\is_finite($upper) || $upper <= $lower) {
                    return null;
                }
                $residualAt = static fn (float $value): float =>
                    SpecialFunctions::dawson($value) - ($slope * $value);
                $lowerResidual = $residualAt($lower);
                $upperResidual = $residualAt($upper);
                if ($lowerResidual <= 0.0 || $upperResidual >= 0.0) {
                    return null;
                }
                $root = null;
                $rootResidual = null;
                $iterations = 0;
                for ($iterations = 1; $iterations <= $solverOptions->maxIterations; ++$iterations) {
                    $midpoint = $lower + (($upper - $lower) / 2.0);
                    if ($midpoint === $lower || $midpoint === $upper) {
                        break;
                    }
                    $midpointResidual = $residualAt($midpoint);
                    if ($midpointResidual > 0.0) {
                        $lower = $midpoint;
                    } else {
                        $upper = $midpoint;
                    }
                    $root = $midpoint;
                    $rootResidual = $midpointResidual;
                    if (
                        ($upper - $lower)
                        <= $solverOptions->positionTolerance($lower, $upper)
                    ) {
                        break;
                    }
                }
                if ($root === null || $rootResidual === null) {
                    return null;
                }
                $rootScale = \max(
                    \abs(SpecialFunctions::dawson($root)),
                    \abs($slope * $root),
                );
                if ($rootScale === 0.0) {
                    $rootScale = 1.0;
                }
                if (
                    \abs($rootResidual / $rootScale)
                    > $solverOptions->residualTolerance + (8.0 * \PHP_FLOAT_EPSILON)
                ) {
                    return null;
                }
                $roots[] = new EquationSolution($root, \abs($rootResidual), $iterations);
                $roots[] = new EquationSolution(-$root, \abs($rootResidual), $iterations);
            }
            $roots = \array_values(\array_filter(
                $roots,
                static fn (EquationSolution $solution): bool =>
                    $solution->value >= $lowerBound && $solution->value <= $upperBound,
            ));
            \usort(
                $roots,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $roots;
        }

        return null;
    }

    /**
     * Solve erfi intersections with a line through the origin on unbounded intervals.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedErfiLinearEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $targetNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || $functionNode->name !== 'erfi'
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('erfi')
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            if (!$argument instanceof VariableNode || $argument->name !== $variable) {
                continue;
            }
            $targetCoefficients = $this->extractPolynomial(
                $extractor,
                $targetNode,
                $targetNode->span()->start,
            );
            if (
                $targetCoefficients === null
                || \count($targetCoefficients) > 2
                || ($targetCoefficients[0] ?? 0.0) !== 0.0
            ) {
                continue;
            }

            $slope = $targetCoefficients[1] ?? 0.0;
            $roots = [new EquationSolution(0.0, 0.0, 0)];
            $smallArgumentSlope = 2.0 / \sqrt(\M_PI);
            if ($slope > $smallArgumentSlope) {
                $estimate = \sqrt(3.0 * (($slope / $smallArgumentSlope) - 1.0));
                if (!\is_finite($estimate)) {
                    return null;
                }
                $lower = \min($estimate / 2.0, 0.5);
                $residualAt = static function (float $value) use ($slope): ?float {
                    try {
                        return SpecialFunctions::erfi($value) - ($slope * $value);
                    } catch (\DomainException | \OverflowException) {
                        return null;
                    }
                };
                $lowerResidual = $residualAt($lower);
                $attempt = 0;
                while (
                    $lower > 0.0
                    && $lowerResidual !== null
                    && $lowerResidual >= 0.0
                    && $attempt < 64
                ) {
                    $lower /= 2.0;
                    $lowerResidual = $residualAt($lower);
                    ++$attempt;
                }
                if ($lowerResidual === null || $lowerResidual >= 0.0) {
                    return null;
                }
                $upper = 1.0;
                $upperResidual = $residualAt($upper);
                $attempt = 0;
                while (
                    $upperResidual !== null
                    && $upperResidual <= 0.0
                    && $attempt < 128
                ) {
                    $upper *= 2.0;
                    if (!\is_finite($upper)) {
                        return null;
                    }
                    $upperResidual = $residualAt($upper);
                    ++$attempt;
                }
                if ($upperResidual === null || $upperResidual <= 0.0) {
                    return null;
                }

                $root = null;
                $rootResidual = null;
                $iterations = 0;
                for ($iterations = 1; $iterations <= $solverOptions->maxIterations; ++$iterations) {
                    $midpoint = $lower + (($upper - $lower) / 2.0);
                    if ($midpoint === $lower || $midpoint === $upper) {
                        break;
                    }
                    $midpointResidual = $residualAt($midpoint);
                    if ($midpointResidual === null) {
                        return null;
                    }
                    if ($midpointResidual < 0.0) {
                        $lower = $midpoint;
                    } else {
                        $upper = $midpoint;
                    }
                    $root = $midpoint;
                    $rootResidual = $midpointResidual;
                    $midpointScale = \max(
                        SpecialFunctions::erfi($midpoint),
                        \abs($slope * $midpoint),
                    );
                    if (
                        ($upper - $lower)
                        <= $solverOptions->positionTolerance($lower, $upper)
                        && $midpointScale > 0.0
                        && \abs($midpointResidual / $midpointScale)
                            <= $solverOptions->residualTolerance
                    ) {
                        break;
                    }
                }
                if ($root === null || $rootResidual === null) {
                    return null;
                }
                $rootFunctionValue = SpecialFunctions::erfi($root);
                $rootScale = \max($rootFunctionValue, \abs($slope * $root));
                if (
                    $rootScale === 0.0
                    || \abs($rootResidual / $rootScale)
                        > $solverOptions->residualTolerance + (8.0 * \PHP_FLOAT_EPSILON)
                ) {
                    return null;
                }
                $roots[] = new EquationSolution($root, \abs($rootResidual), $iterations);
                $roots[] = new EquationSolution(-$root, \abs($rootResidual), $iterations);
            }
            $roots = \array_values(\array_filter(
                $roots,
                static fn (EquationSolution $solution): bool =>
                    $solution->value >= $lowerBound && $solution->value <= $upperBound,
            ));
            \usort(
                $roots,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $roots;
        }

        return null;
    }

    /**
     * Solve inverse-function levels whose sinusoidal input decays under a positive quadratic.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedDecayingTrigonometricInverseLevel(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $leftSource, 0, $right, $rightSource],
                [$right, $rightSource, $rightOffset, $left, $leftSource],
            ] as [$functionNode, $functionSource, $functionSourceOffset, $targetNode, $targetSource]
        ) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || !$evaluationOptions->functions->isBuiltIn($functionNode->name)
                || !\in_array(
                    $functionNode->name,
                    ['erfinv', 'erfcinv', 'gammaincinv', 'gammainccinv', 'betaincinv', 'betainccinv'],
                    true,
                )
            ) {
                continue;
            }

            $arguments = $functionNode->arguments;
            $inputIndex = match ($functionNode->name) {
                'erfinv', 'erfcinv' => \count($arguments) === 1 ? 0 : null,
                'gammaincinv', 'gammainccinv' => \count($arguments) === 2 ? 1 : null,
                'betaincinv', 'betainccinv' => \count($arguments) === 3 ? 2 : null,
            };
            if ($inputIndex === null) {
                continue;
            }
            $input = $this->unwrapGrouping($arguments[$inputIndex]);
            if (
                !$input instanceof BinaryOperationNode
                || $input->operator !== BinaryOperator::Divide
            ) {
                continue;
            }
            $numeratorFactors = [];
            $flattenNumerator = function (Node $node) use (&$flattenNumerator, &$numeratorFactors): void {
                $node = $this->unwrapGrouping($node);
                if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
                    $flattenNumerator($node->left);
                    $flattenNumerator($node->right);

                    return;
                }
                $numeratorFactors[] = $node;
            };
            $flattenNumerator($input->left);
            $numerator = null;
            $phaseCoefficients = null;
            $amplitudeCoefficients = [1.0];
            foreach ($numeratorFactors as $factor) {
                $factor = $this->unwrapGrouping($factor);
                $factorSign = 1.0;
                while (
                    $factor instanceof UnaryOperationNode
                    && \in_array($factor->operator, [UnaryOperator::Minus, UnaryOperator::Plus], true)
                ) {
                    if ($factor->operator === UnaryOperator::Minus) {
                        $factorSign *= -1.0;
                    }
                    $factor = $this->unwrapGrouping($factor->operand);
                }
                if (
                    $factor instanceof FunctionCallNode
                    && \in_array($factor->name, ['sin', 'cos'], true)
                    && \count($factor->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn($factor->name)
                ) {
                    if ($numerator !== null) {
                        continue 2;
                    }
                    $numerator = $factor;
                    $phaseCoefficients = $extractor->extract($factor->arguments[0]);
                    if ($phaseCoefficients === null || $factorSign !== 1.0) {
                        if ($phaseCoefficients === null) {
                            continue 2;
                        }
                        foreach ($amplitudeCoefficients as $index => $coefficient) {
                            $amplitudeCoefficients[$index] = $coefficient * $factorSign;
                        }
                    }
                    if ($phaseCoefficients !== null) {
                        while (
                            \count($phaseCoefficients) > 1
                            && $phaseCoefficients[\array_key_last($phaseCoefficients)] === 0.0
                        ) {
                            \array_pop($phaseCoefficients);
                        }
                    }
                    continue;
                }
                $factorCoefficients = $extractor->extract($factor);
                if ($factorCoefficients === null) {
                    continue 2;
                }
                if ($factorSign !== 1.0) {
                    foreach ($factorCoefficients as $index => $coefficient) {
                        $factorCoefficients[$index] = $coefficient * $factorSign;
                    }
                }
                $product = \array_fill(
                    0,
                    \count($amplitudeCoefficients) + \count($factorCoefficients) - 1,
                    0.0,
                );
                foreach ($amplitudeCoefficients as $firstDegree => $firstCoefficient) {
                    foreach ($factorCoefficients as $secondDegree => $secondCoefficient) {
                        $product[$firstDegree + $secondDegree]
                            += $firstCoefficient * $secondCoefficient;
                    }
                }
                $amplitudeCoefficients = $product;
            }
            while (
                \count($amplitudeCoefficients) > 1
                && $amplitudeCoefficients[\array_key_last($amplitudeCoefficients)] === 0.0
            ) {
                \array_pop($amplitudeCoefficients);
            }
            if (
                !$numerator instanceof FunctionCallNode
                || $phaseCoefficients === null
                || \count($phaseCoefficients) < 2
                || \array_filter(
                    $phaseCoefficients,
                    static fn (float $coefficient): bool => !\is_finite($coefficient),
                ) !== []
                || !\is_finite(\array_sum(\array_map('abs', $amplitudeCoefficients)))
                || \array_sum(\array_map('abs', $amplitudeCoefficients)) === 0.0
            ) {
                continue;
            }
            $denominatorCoefficients = $extractor->extract($input->right);
            if (
                $denominatorCoefficients === null
            ) {
                continue;
            }
            while (
                \count($denominatorCoefficients) > 1
                && $denominatorCoefficients[\array_key_last($denominatorCoefficients)] === 0.0
            ) {
                \array_pop($denominatorCoefficients);
            }
            $denominatorDegree = \count($denominatorCoefficients) - 1;
            if ($denominatorDegree < 1 || $denominatorCoefficients[$denominatorDegree] === 0.0) {
                continue;
            }
            $amplitudeDegree = \count($amplitudeCoefficients) - 1;
            if ($amplitudeDegree >= $denominatorDegree) {
                continue;
            }
            $denominatorRemainderBound = 0.0;
            foreach (\array_slice($denominatorCoefficients, 0, $denominatorDegree) as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
                $denominatorRemainderBound += \abs($coefficient);
            }
            foreach ($amplitudeCoefficients as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
            }

            $shapeValues = [];
            $shapeCount = match ($functionNode->name) {
                'gammaincinv', 'gammainccinv' => 1,
                'betaincinv', 'betainccinv' => 2,
                default => 0,
            };
            $constantShapes = true;
            for ($index = 0; $index < $shapeCount; ++$index) {
                $shape = $this->constantNodeValue($arguments[$index], $parameters, $evaluationOptions);
                if ($shape === null || !\is_finite($shape) || $shape <= 0.0) {
                    $constantShapes = false;
                    break;
                }
                $shapeValues[] = $shape;
            }
            if (!$constantShapes) {
                continue;
            }
            $target = $this->constantNodeValue($targetNode, $parameters, $evaluationOptions);
            if ($target === null || !\is_finite($target)) {
                $targetCoefficients = $extractor->extract($targetNode);
                if ($targetCoefficients !== null && \count($targetCoefficients) > 1) {
                    if (
                        \in_array($functionNode->name, ['erfcinv', 'gammainccinv'], true)
                        && $this->polynomialTendsToPositiveInfinityOnRequestedTail(
                            $targetCoefficients,
                            $lowerBound,
                            $upperBound,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The inverse-function and decaying sinusoidal inputs cross infinitely many times '
                            . 'on an unbounded tail.',
                        );
                    }
                    if (\in_array($functionNode->name, ['erfcinv', 'gammainccinv'], true)) {
                        continue;
                    }

                    return $this->solveUnboundedDecayingTrigonometricInversePolynomialTarget(
                        $functionNode,
                        $functionSource,
                        $functionSourceOffset,
                        $targetCoefficients,
                        $numerator,
                        $amplitudeCoefficients,
                        $phaseCoefficients,
                        $denominatorCoefficients,
                        $denominatorRemainderBound,
                        $denominatorDegree,
                        $amplitudeDegree,
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                }
                continue;
            }

            try {
                $targetLevel = match ($functionNode->name) {
                    'erfinv' => SpecialFunctions::erf($target),
                    'erfcinv' => SpecialFunctions::erfc($target),
                    'gammaincinv' => $target < 0.0
                        ? null
                        : SpecialFunctions::regularizedGammaP($shapeValues[0], $target),
                    'gammainccinv' => $target < 0.0
                        ? null
                        : SpecialFunctions::regularizedGammaQ($shapeValues[0], $target),
                    'betaincinv' => $target < 0.0 || $target > 1.0
                        ? null
                        : SpecialFunctions::regularizedBeta($shapeValues[0], $shapeValues[1], $target),
                    'betainccinv' => $target < 0.0 || $target > 1.0
                        ? null
                        : SpecialFunctions::regularizedBetaComplement(
                            $shapeValues[0],
                            $shapeValues[1],
                            $target,
                        ),
                };
            } catch (\DomainException | \InvalidArgumentException) {
                continue;
            }
            if ($targetLevel === null) {
                return [];
            }
            if ($targetLevel === 0.0) {
                $hasInfiniteZeroLevelSolutions = match ($functionNode->name) {
                    'erfinv', 'gammaincinv', 'betaincinv' => $target === 0.0,
                    'betainccinv' => $target === 1.0,
                    default => false,
                };
                if (!$hasInfiniteZeroLevelSolutions) {
                    return [];
                }
                throw new InfiniteSolutionSetException(
                    'The zero sinusoidal input repeats at infinitely many points.',
                );
            }

            $levelMagnitude = \abs($targetLevel);
            $amplitudeCoefficientBound = \array_sum(\array_map('abs', $amplitudeCoefficients));
            $leadingMagnitude = \abs($denominatorCoefficients[$denominatorDegree]);
            $tailDominanceRadius = \max(1.0, (2.0 * $denominatorRemainderBound) / $leadingMagnitude);
            $rootRadiusPower = (2.0 * $amplitudeCoefficientBound) / ($levelMagnitude * $leadingMagnitude);
            if (
                !\is_finite($tailDominanceRadius)
                || !\is_finite($rootRadiusPower)
                || $rootRadiusPower < 0.0
            ) {
                return null;
            }
            $radius = \max(
                $tailDominanceRadius,
                \pow($rootRadiusPower, 1.0 / ($denominatorDegree - $amplitudeDegree)),
            );
            $radius = $this->adjacentFloat($radius, 1) ?? $radius;
            $finiteLower = \max($lowerBound, -$radius);
            $finiteUpper = \min($upperBound, $radius);
            if ($finiteLower > $finiteUpper) {
                return [];
            }

            $phaseSource = \substr(
                $functionSource,
                $numerator->arguments[0]->span()->start - $functionSourceOffset,
                $numerator->arguments[0]->span()->length(),
            );
            $amplitudeSource = $this->polynomialCoefficientsSource($amplitudeCoefficients, $variable);
            $denominatorSource = $this->polynomialCoefficientsSource($denominatorCoefficients, $variable);
            if ($phaseSource === '' || $amplitudeSource === null || $denominatorSource === null) {
                continue;
            }
            $transformedEquation = '(' . $amplitudeSource . ')*' . $numerator->name . '(' . $phaseSource . ') = ('
                . \sprintf('%.17g', $targetLevel) . ')*(' . $denominatorSource . ')';
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                $transformedSolutions = $this->solve(
                    $transformedEquation,
                    $variable,
                    $finiteLower,
                    $finiteUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (RootSearchLimitException | \InvalidArgumentException) {
                continue;
            }

            $originalResidualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $scaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($transformedSolutions as $solution) {
                $residual = $originalResidualAt($solution->value);
                if ($residual === null) {
                    continue;
                }
                $refinedValue = $this->refineVerifiedEquationCandidate(
                    $solution->value,
                    $residual,
                    $originalResidualAt,
                    $solution->value,
                    $finiteLower,
                    $finiteUpper,
                    $solverOptions,
                );
                $residual = $originalResidualAt($refinedValue);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt($refinedValue, $residual, $scaleAt, $solverOptions)
                ) {
                    $solutions[] = new EquationSolution($refinedValue, \abs($residual), $solution->iterations);
                }
            }

            return $this->deduplicateSortedEquationSolutions($solutions, $solverOptions);
        }

        return null;
    }

    /**
     * Determine whether a polynomial target tends to positive infinity on either requested unbounded tail.
     *
     * @param list<float> $coefficients
     */
    private function polynomialTendsToPositiveInfinityOnRequestedTail(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
    ): bool {
        $degree = \count($coefficients) - 1;
        if ($degree < 1) {
            return false;
        }
        $leadingCoefficient = $coefficients[$degree];
        if ($leadingCoefficient === 0.0 || !\is_finite($leadingCoefficient)) {
            return false;
        }

        return (!\is_finite($upperBound) && $leadingCoefficient > 0.0)
            || (!\is_finite($lowerBound) && ($degree % 2 === 0)
                === ($leadingCoefficient > 0.0));
    }

    /**
     * @param list<float> $coefficients
     */
    private function polynomialTendsToNegativeInfinityOnRequestedTail(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
    ): bool {
        foreach ($coefficients as $index => $coefficient) {
            $coefficients[$index] = -$coefficient;
        }

        return $this->polynomialTendsToPositiveInfinityOnRequestedTail(
            $coefficients,
            $lowerBound,
            $upperBound,
        );
    }

    /** @param array<string, int|float> $parameters */
    private function hasInfiniteRootsFromExponentialApproachToTrigonometricBoundary(
        Node $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        if ($this->hasInfiniteRootsFromRationalPhaseExponentialApproachToTrigonometricBoundary(
            $target,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        )) {
            return true;
        }
        if ($this->hasInfiniteRootsFromPolynomialExponentialApproachToTrigonometricBoundary(
            $target,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        )) {
            return true;
        }
        if ($this->hasInfiniteRootsFromDominantPolynomialAmplitudeExponentials(
            $target,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        )) {
            return true;
        }

        $terms = [];
        $this->flattenAdditiveTerms($target, 1.0, $terms);
        $constant = 0.0;
        $exponentials = [];
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ($terms as [$term, $sign]) {
            if (!$this->containsVariable($term, $variable)) {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                if ($value === null || !\is_finite($value)) {
                    return false;
                }
                $constant += $sign * $value;
                continue;
            }
            $term = $this->unwrapGrouping($term);
            $exponential = $term;
            $coefficient = $sign;
            if ($term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Multiply) {
                $exponential = null;
                foreach ([[$term->left, $term->right], [$term->right, $term->left]] as [$scaleNode, $functionNode]) {
                    $functionNode = $this->unwrapGrouping($functionNode);
                    if (
                        $functionNode instanceof FunctionCallNode
                        && $functionNode->name === 'exp'
                        && \count($functionNode->arguments) === 1
                        && !$this->containsVariable($scaleNode, $variable)
                    ) {
                        $scale = $this->constantNodeValue($scaleNode, $parameters, $evaluationOptions);
                        if ($scale !== null && \is_finite($scale)) {
                            $exponential = $functionNode;
                            $coefficient = $sign * $scale;
                            break;
                        }
                    }
                }
            }
            if (
                $exponential === $term
                && $term instanceof BinaryOperationNode
                && $term->operator === BinaryOperator::Divide
                && !$this->containsVariable($term->right, $variable)
            ) {
                $divisor = $this->constantNodeValue($term->right, $parameters, $evaluationOptions);
                $numerator = $this->unwrapGrouping($term->left);
                if (
                    $divisor !== null
                    && \is_finite($divisor)
                    && $divisor !== 0.0
                    && $numerator instanceof FunctionCallNode
                    && $numerator->name === 'exp'
                ) {
                    $exponential = $numerator;
                    $coefficient = $sign / $divisor;
                }
            }
            if (
                !$exponential instanceof FunctionCallNode
                || $exponential->name !== 'exp'
                || !$evaluationOptions->functions->isBuiltIn('exp')
                || \count($exponential->arguments) !== 1
                || $coefficient === 0.0
            ) {
                return false;
            }
            $phase = $this->unwrapGrouping($exponential->arguments[0]);
            $phaseCoefficients = $extractor->extract($phase);
            if ($phaseCoefficients === null || \count($phaseCoefficients) < 2) {
                return false;
            }
            $matched = false;
            foreach ($exponentials as &$existing) {
                if ($this->sameExpression($existing['phase'], $phase)) {
                    $existing['coefficient'] += $coefficient;
                    $matched = true;
                    break;
                }
            }
            unset($existing);
            if (!$matched) {
                $exponentials[] = [
                    'phase' => $phase,
                    'coefficients' => $phaseCoefficients,
                    'coefficient' => $coefficient,
                ];
            }
        }
        if ($exponentials === []) {
            return false;
        }
        $growthClasses = [];
        foreach ($exponentials as $exponential) {
            $coefficient = $exponential['coefficient'];
            if ($coefficient === 0.0) {
                continue;
            }
            $growthCoefficients = $exponential['coefficients'];
            $growthCoefficients[0] = 0.0;
            $matched = false;
            foreach ($growthClasses as &$growthClass) {
                if ($growthClass['coefficients'] !== $growthCoefficients) {
                    continue;
                }
                if ($growthClass['sign'] !== ($coefficient < 0.0 ? -1 : 1)) {
                    $growthClass['sign'] = null;
                }
                $matched = true;
                break;
            }
            unset($growthClass);
            if (!$matched) {
                $growthClasses[] = [
                    'coefficients' => $growthCoefficients,
                    'sign' => $coefficient < 0.0 ? -1 : 1,
                ];
            }
        }
        if ($growthClasses === []) {
            return false;
        }
        foreach ($growthClasses as $growthClass) {
            if ($growthClass['sign'] === null) {
                return false;
            }
        }
        $exponentials = $growthClasses;

        $tailDirections = [];
        if ($lowerBound === -\INF) {
            $tailDirections[] = -1;
        }
        if ($upperBound === \INF) {
            $tailDirections[] = 1;
        }
        foreach ($tailDirections as $direction) {
            $dominantIndex = null;
            foreach ($exponentials as $index => $candidate) {
                if ($candidate['sign'] === null) {
                    continue;
                }
                $dominatesAll = true;
                foreach ($exponentials as $otherIndex => $other) {
                    if (
                        $otherIndex === $index
                        || $other['sign'] === null
                        || $this->comparePolynomialAsymptoticGrowth(
                            $candidate['coefficients'],
                            $other['coefficients'],
                            $direction,
                        ) <= 0
                    ) {
                        if ($otherIndex !== $index && $other['sign'] !== null) {
                            $dominatesAll = false;
                            break;
                        }
                    }
                }
                if ($dominatesAll) {
                    $dominantIndex = $index;
                    break;
                }
            }
            if ($dominantIndex === null) {
                continue;
            }
            $dominant = $exponentials[$dominantIndex];
            if ($this->polynomialTendsToNegativeInfinityOnRequestedTail(
                $dominant['coefficients'],
                $direction < 0 ? -\INF : 0.0,
                $direction > 0 ? \INF : 0.0,
            )) {
                $approachesUpperBoundaryFromInside = $constant === 1.0
                    && $dominant['sign'] < 0;
                $approachesLowerBoundaryFromInside = $constant === -1.0
                    && $dominant['sign'] > 0;
                if ($approachesUpperBoundaryFromInside || $approachesLowerBoundaryFromInside) {
                    return true;
                }
            }
        }
        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function hasInfiniteRootsFromRationalPhaseExponentialApproachToTrigonometricBoundary(
        Node $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $terms = [];
        $this->flattenAdditiveTerms($target, 1.0, $terms);
        $constant = 0.0;
        $corrections = [];
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ($terms as [$term, $sign]) {
            if (!$this->containsVariable($term, $variable)) {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                if ($value === null || !\is_finite($value)) {
                    return false;
                }
                $constant += $sign * $value;
                continue;
            }
            $term = $this->unwrapGrouping($term);
            $factors = $term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Multiply
                ? [[$term->left, $term->right], [$term->right, $term->left]]
                : [[null, $term]];
            $correction = null;
            foreach ($factors as [$amplitude, $exponential]) {
                $exponential = $this->unwrapGrouping($exponential);
                if (
                    !$exponential instanceof FunctionCallNode
                    || $exponential->name !== 'exp'
                    || !$evaluationOptions->functions->isBuiltIn('exp')
                    || \count($exponential->arguments) !== 1
                ) {
                    continue;
                }
                $amplitude ??= new NumberNode(1, '1', new SourceSpan(0, 1));
                if ($sign < 0.0) {
                    $amplitude = new UnaryOperationNode(
                        UnaryOperator::Minus,
                        $amplitude,
                        new SourceSpan(0, 0),
                    );
                }
                $amplitudeForm = $extractor->rationalFunction($amplitude);
                $phaseNode = $exponential->arguments[0];
                $phaseForm = $extractor->rationalFunction($phaseNode);
                if ($amplitudeForm === null || $phaseForm === null) {
                    return false;
                }
                $amplitudeData = $this->rationalFunctionAsymptoticData($amplitudeForm);
                $phaseData = $this->rationalFunctionAsymptoticData($phaseForm);
                if ($amplitudeData === null || $phaseData === null) {
                    return false;
                }
                $correction = [
                    'phaseNode' => $phaseNode,
                    'phaseData' => $phaseData,
                    'amplitudeNode' => $amplitude,
                    'amplitudeDegree' => $amplitudeData[0],
                    'amplitudeSign' => $amplitudeData[1],
                ];
                break;
            }
            if ($correction === null) {
                return false;
            }
            $corrections[] = $correction;
        }
        if (($constant !== 1.0 && $constant !== -1.0) || $corrections === []) {
            return false;
        }

        $combinedCorrections = [];
        foreach ($corrections as $correction) {
            $matched = false;
            foreach ($combinedCorrections as &$existing) {
                if (!$this->polynomialPhasesAreEquivalent(
                    $existing['phaseNode'],
                    $correction['phaseNode'],
                    $extractor,
                )) {
                    continue;
                }
                $existing['amplitudeNode'] = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $existing['amplitudeNode'],
                    $correction['amplitudeNode'],
                    new SourceSpan(0, 0),
                );
                $combinedForm = $extractor->rationalFunction($existing['amplitudeNode']);
                $combinedData = $combinedForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($combinedForm);
                if ($combinedData === null) {
                    unset($existing);

                    return false;
                }
                $existing['amplitudeDegree'] = $combinedData[0];
                $existing['amplitudeSign'] = $combinedData[1];
                $matched = true;
                break;
            }
            unset($existing);
            if (!$matched) {
                $combinedCorrections[] = $correction;
            }
        }
        $combinedCorrections = \array_values(\array_filter(
            $combinedCorrections,
            static fn (array $correction): bool => $correction['amplitudeSign'] !== 0,
        ));
        if ($combinedCorrections === []) {
            return false;
        }

        $growthClasses = [];
        foreach ($combinedCorrections as $correction) {
            $matched = false;
            foreach ($growthClasses as &$growthClass) {
                if (
                    !$this->rationalPhasesHaveBoundedDifference(
                        $growthClass['phaseNode'],
                        $correction['phaseNode'],
                        $extractor,
                    )
                    || $growthClass['amplitudeDegree'] !== $correction['amplitudeDegree']
                ) {
                    continue;
                }
                if ($growthClass['amplitudeSign'] !== $correction['amplitudeSign']) {
                    $growthClass['amplitudeSign'] = null;
                }
                $matched = true;
                break;
            }
            unset($growthClass);
            if (!$matched) {
                $growthClasses[] = [
                    'phaseNode' => $correction['phaseNode'],
                    'phaseData' => $correction['phaseData'],
                    'amplitudeDegree' => $correction['amplitudeDegree'],
                    'amplitudeSign' => $correction['amplitudeSign'],
                ];
            }
        }
        foreach ($growthClasses as $growthClass) {
            if ($growthClass['amplitudeSign'] === null) {
                return false;
            }
        }

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            $dominantIndex = null;
            foreach ($growthClasses as $index => $candidate) {
                $dominatesAll = true;
                foreach ($growthClasses as $otherIndex => $other) {
                    if ($index !== $otherIndex) {
                        $comparison = $this->comparePolynomialPhaseGrowth(
                            $candidate['phaseNode'],
                            $other['phaseNode'],
                            $direction,
                            $extractor,
                            [],
                            [],
                        );
                        if ($comparison === 0) {
                            $comparison = $candidate['amplitudeDegree'] <=> $other['amplitudeDegree'];
                        }
                        if ($comparison <= 0) {
                            $dominatesAll = false;
                            break;
                        }
                    }
                }
                if ($dominatesAll) {
                    $dominantIndex = $index;
                    break;
                }
            }
            if ($dominantIndex === null) {
                continue;
            }
            $dominant = $growthClasses[$dominantIndex];
            $phaseSign = $dominant['phaseData'][1];
            if ($direction < 0 && \abs($dominant['phaseData'][0]) % 2 === 1) {
                $phaseSign *= -1;
            }
            if ($dominant['phaseData'][0] <= 0 || $phaseSign >= 0) {
                continue;
            }
            $amplitudeSign = $dominant['amplitudeSign'];
            if ($direction < 0 && \abs($dominant['amplitudeDegree']) % 2 === 1) {
                $amplitudeSign *= -1;
            }
            if (($constant === 1.0 && $amplitudeSign < 0)
                || ($constant === -1.0 && $amplitudeSign > 0)
            ) {
                return true;
            }
        }

        return false;
    }

    private function rationalPhasesHaveBoundedDifference(
        Node $left,
        Node $right,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        $difference = $extractor->rationalDifference($left, $right);
        if ($difference === null) {
            return $this->sameExpression($left, $right);
        }
        [$numerator, $denominator] = $difference;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === '0') {
            \array_pop($denominator);
        }
        if ($denominator === [] || $denominator === ['0']) {
            return false;
        }
        if ($numerator === [] || $numerator === ['0']) {
            return true;
        }

        return \count($numerator) <= \count($denominator);
    }

    /** @param array<string, int|float> $parameters */
    private function hasInfiniteRootsFromDominantPolynomialAmplitudeExponentials(
        Node $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $terms = [];
        $this->flattenAdditiveTerms($target, 1.0, $terms);
        $constant = 0.0;
        $corrections = [];
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $rationalExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ($terms as [$term, $sign]) {
            if (!$this->containsVariable($term, $variable)) {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                if ($value === null || !\is_finite($value)) {
                    return false;
                }
                $constant += $sign * $value;
                continue;
            }
            $term = $this->unwrapGrouping($term);
            $factors = $term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Multiply
                ? [[$term->left, $term->right], [$term->right, $term->left]]
                : [[null, $term]];
            $correction = null;
            foreach ($factors as [$amplitudeNode, $phaseNode]) {
                $phaseNode = $this->unwrapGrouping($phaseNode);
                if (
                    !$phaseNode instanceof FunctionCallNode
                    || $phaseNode->name !== 'exp'
                    || !$evaluationOptions->functions->isBuiltIn('exp')
                    || \count($phaseNode->arguments) !== 1
                ) {
                    continue;
                }
                $amplitudeNode ??= new NumberNode(1, '1', new SourceSpan(0, 1));
                if ($sign < 0.0) {
                    $amplitudeNode = new UnaryOperationNode(
                        UnaryOperator::Minus,
                        $amplitudeNode,
                        new SourceSpan(0, 0),
                    );
                }
                $amplitudeForm = $rationalExtractor->rationalFunction($amplitudeNode);
                $phaseCoefficients = $extractor->extract($phaseNode->arguments[0]);
                if (
                    $amplitudeForm === null
                    || $phaseCoefficients === null
                    || \count($phaseCoefficients) < 2
                ) {
                    return false;
                }
                $phaseCoefficients[0] = 0.0;
                $amplitudeData = $this->rationalFunctionAsymptoticData($amplitudeForm);
                if ($amplitudeData === null) {
                    return false;
                }
                $correction = [
                    'phase' => $phaseCoefficients,
                    'phaseNode' => $phaseNode->arguments[0],
                    'amplitudeNode' => $amplitudeNode,
                    'amplitudeDegree' => $amplitudeData[0],
                    'amplitudeSign' => $amplitudeData[1],
                ];
                break;
            }
            if ($correction === null) {
                return false;
            }
            $corrections[] = $correction;
        }
        if ($constant !== 1.0 && $constant !== -1.0 || \count($corrections) < 2) {
            return false;
        }

        $combinedCorrections = [];
        foreach ($corrections as $correction) {
            $matched = false;
            foreach ($combinedCorrections as &$existing) {
                if (!$this->polynomialPhasesAreEquivalent(
                    $existing['phaseNode'],
                    $correction['phaseNode'],
                    $rationalExtractor,
                )) {
                    continue;
                }
                $existing['amplitudeNode'] = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $existing['amplitudeNode'],
                    $correction['amplitudeNode'],
                    new SourceSpan(0, 0),
                );
                $combinedForm = $rationalExtractor->rationalFunction($existing['amplitudeNode']);
                $combinedData = $combinedForm === null
                    ? null
                    : $this->rationalFunctionAsymptoticData($combinedForm);
                if ($combinedData === null) {
                    unset($existing);

                    return false;
                }
                $existing['amplitudeDegree'] = $combinedData[0];
                $existing['amplitudeSign'] = $combinedData[1];
                $matched = true;
                break;
            }
            unset($existing);
            if (!$matched) {
                $combinedCorrections[] = $correction;
            }
        }
        $corrections = \array_values(\array_filter(
            $combinedCorrections,
            static fn (array $correction): bool => $correction['amplitudeSign'] !== 0,
        ));
        if ($corrections === []) {
            return false;
        }
        $growthClasses = [];
        foreach ($corrections as $correction) {
            $matched = false;
            foreach ($growthClasses as &$growthClass) {
                if (
                    !$this->polynomialPhasesHaveSameNonconstantPart(
                        $growthClass['phaseNode'],
                        $correction['phaseNode'],
                        $rationalExtractor,
                        $growthClass['phase'],
                        $correction['phase'],
                    )
                    || $growthClass['amplitudeDegree'] !== $correction['amplitudeDegree']
                ) {
                    continue;
                }
                if ($growthClass['amplitudeSign'] !== $correction['amplitudeSign']) {
                    $growthClass['amplitudeSign'] = null;
                }
                $matched = true;
                break;
            }
            unset($growthClass);
            if (!$matched) {
                $growthClasses[] = [
                    'phase' => $correction['phase'],
                    'phaseNode' => $correction['phaseNode'],
                    'amplitudeDegree' => $correction['amplitudeDegree'],
                    'amplitudeSign' => $correction['amplitudeSign'],
                ];
            }
        }
        foreach ($growthClasses as $growthClass) {
            if ($growthClass['amplitudeSign'] === null) {
                return false;
            }
        }
        $corrections = $growthClasses;

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            $dominantIndex = null;
            foreach ($corrections as $index => $candidate) {
                $dominatesAll = true;
                foreach ($corrections as $otherIndex => $other) {
                    if ($otherIndex === $index) {
                        continue;
                    }
                    $comparison = $this->comparePolynomialPhaseGrowth(
                        $candidate['phaseNode'],
                        $other['phaseNode'],
                        $direction,
                        $rationalExtractor,
                        $candidate['phase'],
                        $other['phase'],
                    );
                    if ($comparison === 0) {
                        $comparison = $candidate['amplitudeDegree'] <=> $other['amplitudeDegree'];
                    }
                    if ($comparison === 0) {
                        $dominatesAll = false;
                        break;
                    }
                    if ($comparison < 0) {
                        $dominatesAll = false;
                        break;
                    }
                }
                if ($dominatesAll) {
                    $dominantIndex = $index;
                    break;
                }
            }
            if ($dominantIndex === null) {
                continue;
            }
            $dominant = $corrections[$dominantIndex];
            if (!$this->polynomialPhaseTendsToNegativeInfinity(
                $dominant['phaseNode'],
                $direction,
                $rationalExtractor,
                $dominant['phase'],
            )) {
                continue;
            }
            $amplitudeSign = $dominant['amplitudeSign'];
            if ($direction < 0 && \abs($dominant['amplitudeDegree']) % 2 === 1) {
                $amplitudeSign *= -1;
            }
            $correctionSign = $amplitudeSign;
            if (($constant === 1.0 && $correctionSign < 0.0)
                || ($constant === -1.0 && $correctionSign > 0.0)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     * @return array{int, int}|null Degree difference and eventual sign coefficient.
     */
    private function rationalFunctionAsymptoticData(array $form): ?array
    {
        [$numerator, $denominator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
            \array_pop($denominator);
        }
        if ($numerator === [] || $denominator === [] || $denominator === [['0', '1']]) {
            return null;
        }
        if ($numerator === [['0', '1']]) {
            return [0, 0];
        }
        $numeratorLeading = $numerator[\array_key_last($numerator)][0];
        $denominatorLeading = $denominator[\array_key_last($denominator)][0];

        return [
            \count($numerator) - \count($denominator),
            ($numeratorLeading[0] === '-' ? -1 : 1)
                * ($denominatorLeading[0] === '-' ? -1 : 1),
        ];
    }

    private function polynomialPhasesAreEquivalent(
        Node $left,
        Node $right,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        $difference = $extractor->rationalDifference($left, $right);
        if ($difference === null) {
            return $this->sameExpression($left, $right);
        }
        foreach ($difference[0] as $coefficient) {
            if ($coefficient !== '0') {
                return false;
            }
        }

        return true;
    }

    private function polynomialPhasesHaveSameNonconstantPart(
        Node $left,
        Node $right,
        ExactRationalPolynomialExtractor $extractor,
        array $leftApproximation,
        array $rightApproximation,
    ): bool {
        $difference = $extractor->rationalDifference($left, $right);
        if ($difference === null) {
            $leftApproximation[0] = 0.0;
            $rightApproximation[0] = 0.0;

            return $leftApproximation === $rightApproximation;
        }
        foreach ($difference[0] as $degree => $coefficient) {
            if ($degree > 0 && $coefficient !== '0') {
                return false;
            }
        }

        return true;
    }

    private function comparePolynomialPhaseGrowth(
        Node $left,
        Node $right,
        int $direction,
        ExactRationalPolynomialExtractor $extractor,
        array $leftApproximation,
        array $rightApproximation,
    ): int {
        $difference = $extractor->rationalDifference($left, $right);
        if ($difference === null) {
            return $this->comparePolynomialAsymptoticGrowth(
                $leftApproximation,
                $rightApproximation,
                $direction,
            );
        }
        [$numerator, $denominator] = $difference;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === '0') {
            \array_pop($denominator);
        }
        if ($numerator === [] || $denominator === [] || $denominator === ['0']) {
            return 0;
        }
        $degree = \count($numerator) - \count($denominator);
        if ($degree <= 0 || $numerator === ['0']) {
            return 0;
        }
        $numeratorLeading = $numerator[\array_key_last($numerator)];
        $denominatorLeading = $denominator[\array_key_last($denominator)];
        $sign = ($numeratorLeading[0] === '-' ? -1 : 1)
            * ($denominatorLeading[0] === '-' ? -1 : 1);
        if ($direction < 0 && \abs($degree) % 2 === 1) {
            $sign *= -1;
        }

        return $sign;
    }

    private function polynomialPhaseTendsToNegativeInfinity(
        Node $phase,
        int $direction,
        ExactRationalPolynomialExtractor $extractor,
        array $approximation,
    ): bool {
        $form = $extractor->rationalFunction($phase);
        $asymptoticData = $form === null
            ? null
            : $this->rationalFunctionAsymptoticData($form);
        if ($asymptoticData === null) {
            return $this->polynomialTendsToNegativeInfinityOnRequestedTail(
                $approximation,
                $direction < 0 ? -\INF : 0.0,
                $direction > 0 ? \INF : 0.0,
            );
        }
        if ($asymptoticData[0] <= 0) {
            return false;
        }
        $sign = $asymptoticData[1];
        if ($direction < 0 && \abs($asymptoticData[0]) % 2 === 1) {
            $sign *= -1;
        }

        return $sign < 0;
    }

    /** @param array<string, int|float> $parameters */
    private function hasInfiniteRootsFromPolynomialExponentialApproachToTrigonometricBoundary(
        Node $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $terms = [];
        $this->flattenAdditiveTerms($target, 1.0, $terms);
        $constant = 0.0;
        $amplitudeCoefficients = null;
        $phaseCoefficients = null;
        $termSign = 0.0;
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ($terms as [$term, $sign]) {
            if (!$this->containsVariable($term, $variable)) {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                if ($value === null || !\is_finite($value)) {
                    return false;
                }
                $constant += $sign * $value;
                continue;
            }
            if ($amplitudeCoefficients !== null || $termSign !== 0.0) {
                return false;
            }
            $term = $this->unwrapGrouping($term);
            if (!$term instanceof BinaryOperationNode || $term->operator !== BinaryOperator::Multiply) {
                return false;
            }
            foreach ([[$term->left, $term->right], [$term->right, $term->left]] as [$amplitude, $exponential]) {
                $exponential = $this->unwrapGrouping($exponential);
                if (
                    !$exponential instanceof FunctionCallNode
                    || $exponential->name !== 'exp'
                    || !$evaluationOptions->functions->isBuiltIn('exp')
                    || \count($exponential->arguments) !== 1
                ) {
                    continue;
                }
                $amplitude = $this->unwrapGrouping($amplitude);
                if (!$this->containsVariable($amplitude, $variable)) {
                    continue;
                }
                $amplitudeCoefficients = $extractor->extract($amplitude);
                $phaseCoefficients = $extractor->extract($exponential->arguments[0]);
                if (
                    $amplitudeCoefficients === null
                    || $phaseCoefficients === null
                    || \count($amplitudeCoefficients) < 2
                    || \count($phaseCoefficients) < 2
                ) {
                    return false;
                }
                $termSign = $sign;
                break;
            }
            if ($amplitudeCoefficients === null || $phaseCoefficients === null) {
                return false;
            }
        }
        if (
            $amplitudeCoefficients === null
            || $phaseCoefficients === null
            || $constant !== 1.0 && $constant !== -1.0
        ) {
            return false;
        }
        while (\count($amplitudeCoefficients) > 1
            && $amplitudeCoefficients[\array_key_last($amplitudeCoefficients)] === 0.0
        ) {
            \array_pop($amplitudeCoefficients);
        }
        $degree = \count($amplitudeCoefficients) - 1;
        $leadingCoefficient = $amplitudeCoefficients[$degree];
        if ($degree < 1 || $leadingCoefficient === 0.0 || !\is_finite($leadingCoefficient)) {
            return false;
        }

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            if (!$this->polynomialTendsToNegativeInfinityOnRequestedTail(
                $phaseCoefficients,
                $direction < 0 ? -\INF : 0.0,
                $direction > 0 ? \INF : 0.0,
            )) {
                continue;
            }
            $amplitudeSign = $leadingCoefficient < 0.0 ? -1 : 1;
            if ($direction < 0 && $degree % 2 === 1) {
                $amplitudeSign *= -1;
            }
            $correctionSign = $termSign * $amplitudeSign;
            if (($constant === 1.0 && $correctionSign < 0.0)
                || ($constant === -1.0 && $correctionSign > 0.0)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Compare polynomial growth toward a tail. Equal results include identical leading asymptotic terms.
     *
     * @param list<float> $left
     * @param list<float> $right
     */
    private function comparePolynomialAsymptoticGrowth(array $left, array $right, int $direction): int
    {
        $degree = \max(\count($left), \count($right)) - 1;
        for ($power = $degree; $power >= 0; $power--) {
            $leftCoefficient = $left[$power] ?? 0.0;
            $rightCoefficient = $right[$power] ?? 0.0;
            if ($direction < 0 && $power % 2 === 1) {
                $leftCoefficient = -$leftCoefficient;
                $rightCoefficient = -$rightCoefficient;
            }
            if ($leftCoefficient !== $rightCoefficient) {
                return $leftCoefficient <=> $rightCoefficient;
            }
        }

        return 0;
    }

    /**
     * Find the finite maximum of a polynomial when every requested infinite tail tends to negative infinity.
     *
     * @param list<float> $coefficients
     */
    private function polynomialMaximumOnUnboundedInterval(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): ?float {
        if (
            (\is_finite($lowerBound) && \is_finite($upperBound))
            || $this->polynomialTendsToPositiveInfinityOnRequestedTail(
                $coefficients,
                $lowerBound,
                $upperBound,
            )
        ) {
            return null;
        }

        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        $degree = \count($coefficients) - 1;
        if ($degree < 1) {
            return null;
        }
        $values = [];
        foreach ([$lowerBound, $upperBound] as $bound) {
            if (!\is_finite($bound)) {
                continue;
            }
            $value = $this->polynomialValue($coefficients, $bound);
            if ($value === null) {
                return null;
            }
            $values[] = $value;
        }

        $derivative = [];
        for ($power = 1; $power <= $degree; ++$power) {
            $coefficient = $power * $coefficients[$power];
            if (!\is_finite($coefficient)) {
                return null;
            }
            $derivative[] = $coefficient;
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }
        if (\count($derivative) > 1) {
            $leadingCoefficient = \abs($derivative[\array_key_last($derivative)]);
            $maximumRatio = 0.0;
            foreach (\array_slice($derivative, 0, -1) as $coefficient) {
                $ratio = \abs($coefficient) / $leadingCoefficient;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $criticalBound = 1.0 + $maximumRatio;
            if (!\is_finite($criticalBound)) {
                return null;
            }
            $criticalLower = \max($lowerBound, -$criticalBound);
            $criticalUpper = \min($upperBound, $criticalBound);
            if ($criticalLower <= $criticalUpper) {
                $polynomialSolver = new PolynomialSolver();
                $criticalPoints = $polynomialSolver->solve(
                    $derivative,
                    $criticalLower,
                    $criticalUpper,
                    static fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $derivative,
                        $value,
                    ),
                    $solverOptions,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($derivative, $value),
                );
                if ($criticalPoints === null) {
                    return null;
                }
                foreach ($criticalPoints as $criticalPoint) {
                    $value = $this->polynomialValue($coefficients, $criticalPoint->value);
                    if ($value === null) {
                        return null;
                    }
                    $values[] = $value;
                }
            }
        }
        if ($values === []) {
            return null;
        }

        $maximum = \max($values);

        return $this->adjacentFloat($maximum, 1) ?? $maximum;
    }

    /**
     * Bound inverse outputs on decaying sinusoidal tails to isolate polynomial target ranges.
     *
     * @param list<float> $targetCoefficients
     * @param list<float> $amplitudeCoefficients
     * @param list<float> $phaseCoefficients
     * @param list<float> $denominatorCoefficients
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedDecayingTrigonometricInversePolynomialTarget(
        FunctionCallNode $functionNode,
        string $functionSource,
        int $functionSourceOffset,
        array $targetCoefficients,
        FunctionCallNode $numerator,
        array $amplitudeCoefficients,
        array $phaseCoefficients,
        array $denominatorCoefficients,
        float $denominatorRemainderBound,
        int $denominatorDegree,
        int $amplitudeDegree,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $function = $functionNode->name;
        $shapeValues = [];
        $shapeCount = match ($function) {
            'gammaincinv' => 1,
            'betaincinv', 'betainccinv' => 2,
            default => 0,
        };
        for ($index = 0; $index < $shapeCount; ++$index) {
            $shape = $this->constantNodeValue(
                $functionNode->arguments[$index],
                $parameters,
                $evaluationOptions,
            );
            if ($shape === null || !\is_finite($shape) || $shape <= 0.0) {
                return null;
            }
            $shapeValues[] = $shape;
        }

        $amplitudeBound = \array_sum(\array_map('abs', $amplitudeCoefficients));
        $leadingMagnitude = \abs($denominatorCoefficients[$denominatorDegree]);
        $tailBaseRadius = \max(1.0, (2.0 * $denominatorRemainderBound) / $leadingMagnitude);
        $tailInputRadiusPower = (4.0 * $amplitudeBound) / $leadingMagnitude;
        if (!\is_finite($tailBaseRadius) || !\is_finite($tailInputRadiusPower)) {
            return null;
        }
        $tailRadius = \max(
            $tailBaseRadius,
            \pow($tailInputRadiusPower, 1.0 / ($denominatorDegree - $amplitudeDegree)),
        );
        $tailRadius = $this->adjacentFloat($tailRadius, 1) ?? $tailRadius;
        if (!\is_finite($tailRadius)) {
            return null;
        }

        try {
            $targetRange = match ($function) {
                'erfinv' => [-SpecialFunctions::inverseErf(0.5), SpecialFunctions::inverseErf(0.5)],
                'gammaincinv' => [0.0, SpecialFunctions::inverseRegularizedGammaP($shapeValues[0], 0.5)],
                'betaincinv' => [0.0, SpecialFunctions::inverseRegularizedBeta(
                    $shapeValues[0],
                    $shapeValues[1],
                    0.5,
                )],
                'betainccinv' => [SpecialFunctions::inverseRegularizedBetaComplement(
                    $shapeValues[0],
                    $shapeValues[1],
                    0.5,
                ), 1.0],
                default => null,
            };
        } catch (\DomainException | \InvalidArgumentException) {
            return null;
        }
        if ($targetRange === null) {
            return null;
        }

        $targetIntervals = $this->polynomialRangeDomainIntervals(
            $targetCoefficients,
            $targetRange[0],
            $targetRange[1],
            $solverOptions,
        );
        if ($targetIntervals === null) {
            return null;
        }
        $searchIntervals = [[-$tailRadius, $tailRadius]];
        foreach ($targetIntervals as [$intervalLower, $intervalUpper]) {
            $padding = 4.0 * $solverOptions->positionTolerance($intervalLower, $intervalUpper);
            $searchIntervals[] = [$intervalLower - $padding, $intervalUpper + $padding];
        }
        \usort(
            $searchIntervals,
            static fn (array $first, array $second): int => $first[0] <=> $second[0],
        );
        $mergedIntervals = [];
        foreach ($searchIntervals as [$intervalLower, $intervalUpper]) {
            $intervalLower = \max($lowerBound, $intervalLower);
            $intervalUpper = \min($upperBound, $intervalUpper);
            if ($intervalLower > $intervalUpper) {
                continue;
            }
            $previousIndex = \array_key_last($mergedIntervals);
            if ($previousIndex !== null && $intervalLower <= $mergedIntervals[$previousIndex][1]) {
                $mergedIntervals[$previousIndex][1] = \max(
                    $mergedIntervals[$previousIndex][1],
                    $intervalUpper,
                );
                continue;
            }
            $mergedIntervals[] = [$intervalLower, $intervalUpper];
        }
        if ($mergedIntervals === []) {
            return [];
        }

        $targetSource = $this->polynomialCoefficientsSource($targetCoefficients, $variable);
        if ($targetSource === null) {
            return null;
        }
        if ($function !== 'erfinv') {
            $mergedIntervals = $this->intersectInverseTargetDomainIntervals(
                $targetSource,
                \in_array($function, ['betaincinv', 'betainccinv'], true),
                $variable,
                $mergedIntervals,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($mergedIntervals === null) {
                return null;
            }
            if ($mergedIntervals === []) {
                return [];
            }
        }

        $amplitudeSource = $this->polynomialCoefficientsSource($amplitudeCoefficients, $variable);
        $denominatorSource = $this->polynomialCoefficientsSource($denominatorCoefficients, $variable);
        $phaseSource = \substr(
            $functionSource,
            $numerator->arguments[0]->span()->start - $functionSourceOffset,
            $numerator->arguments[0]->span()->length(),
        );
        if (
            $targetSource === null
            || $amplitudeSource === null
            || $denominatorSource === null
            || $phaseSource === ''
        ) {
            return null;
        }
        $forwardCall = match ($function) {
            'erfinv' => 'erf(' . $targetSource . ')',
            'gammaincinv' => 'gammainc(' . \sprintf('%.17g', $shapeValues[0]) . ',' . $targetSource . ')',
            'betaincinv' => 'betainc(' . \sprintf('%.17g', $shapeValues[0]) . ','
                . \sprintf('%.17g', $shapeValues[1]) . ',' . $targetSource . ')',
            'betainccinv' => 'betaincc(' . \sprintf('%.17g', $shapeValues[0]) . ','
                . \sprintf('%.17g', $shapeValues[1]) . ',' . $targetSource . ')',
            default => throw new \InvalidArgumentException(
                \sprintf('Unsupported inverse function "%s".', $function),
            ),
        };
        $transformedEquation = '(' . $amplitudeSource . ')*' . $numerator->name . '(' . $phaseSource . ') = ('
            . $forwardCall . ')*(' . $denominatorSource . ')';
        if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }

        $originalResidualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $scaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $solutions = [];
        foreach ($mergedIntervals as [$intervalLower, $intervalUpper]) {
            try {
                $intervalSolutions = $this->solve(
                    $transformedEquation,
                    $variable,
                    $intervalLower,
                    $intervalUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (RootSearchLimitException | \InvalidArgumentException) {
                return null;
            }
            foreach ($intervalSolutions as $solution) {
                $residual = $originalResidualAt($solution->value);
                if ($residual === null) {
                    continue;
                }
                $refinedValue = $this->refineVerifiedEquationCandidate(
                    $solution->value,
                    $residual,
                    $originalResidualAt,
                    $solution->value,
                    $intervalLower,
                    $intervalUpper,
                    $solverOptions,
                );
                $residual = $originalResidualAt($refinedValue);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt($refinedValue, $residual, $scaleAt, $solverOptions)
                ) {
                    $solutions[] = new EquationSolution($refinedValue, \abs($residual), $solution->iterations);
                }
            }
        }

        return $this->deduplicateSortedEquationSolutions($solutions, $solverOptions);
    }

    /**
     * Transform inverse error-function polynomial levels to forward equations.

    /**
     * Transform inverse error-function polynomial levels to forward equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedInverseErrorFunctionPolynomialTargets(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $rightSource],
                [$right, $leftSource],
            ] as [$functionNode, $targetSource]
        ) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || !\in_array($functionNode->name, ['erfinv', 'erfcinv'], true)
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($functionNode->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            $argumentCoefficients = $extractor->extract($argument);
            if ($argumentCoefficients === null || \count($argumentCoefficients) < 2) {
                continue;
            }
            $argumentExpression = $this->polynomialCoefficientsSource($argumentCoefficients, $variable);
            if ($argumentExpression === null) {
                return null;
            }

            $targetExpression = '(' . $targetSource . ')';

            $domainLower = $functionNode->name === 'erfinv' ? -1.0 : 0.0;
            $domainUpper = $functionNode->name === 'erfinv' ? 1.0 : 2.0;
            $domainIntervals = $this->polynomialRangeDomainIntervals(
                $argumentCoefficients,
                $domainLower,
                $domainUpper,
                $solverOptions,
            );
            if ($domainIntervals === null) {
                continue;
            }
            if ($domainIntervals === []) {
                return [];
            }
            $finiteIntervals = [];
            foreach ($domainIntervals as [$intervalLower, $intervalUpper]) {
                $finiteLower = \max($lowerBound, $intervalLower);
                $finiteUpper = \min($upperBound, $intervalUpper);
                if ($finiteLower <= $finiteUpper) {
                    $finiteIntervals[] = [$finiteLower, $finiteUpper];
                }
            }
            if ($finiteIntervals === []) {
                return [];
            }

            $forwardFunction = $functionNode->name === 'erfinv' ? 'erf' : 'erfc';
            $transformedEquation = $forwardFunction . '(' . $targetExpression . ') = ' . $argumentExpression;
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $transformedCandidates = [];
            foreach ($finiteIntervals as [$finiteLower, $finiteUpper]) {
                $intervalSolutions = $this->solve(
                    $transformedEquation,
                    $variable,
                    $finiteLower,
                    $finiteUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($intervalSolutions as $solution) {
                    $transformedCandidates[] = [$solution, $finiteLower, $finiteUpper];
                }
            }
            $solutions = [];
            foreach ($transformedCandidates as [$solution, $finiteLower, $finiteUpper]) {
                $originalResidualAt = fn (float $value): ?float => $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                );
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $solution->value,
                    $parameters,
                    $evaluationOptions,
                );
                if ($residual === null) {
                    return null;
                }
                $refinedValue = $this->refineVerifiedEquationCandidate(
                    $solution->value,
                    $residual,
                    $originalResidualAt,
                    $solution->value,
                    $finiteLower,
                    $finiteUpper,
                    $solverOptions,
                );
                $residual = $originalResidualAt($refinedValue);
                $scaleAt = fn (float $value): ?float => $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $refinedValue,
                        $residual,
                        $scaleAt,
                        $solverOptions,
                    )
                ) {
                    return null;
                }
                $solutions[] = new EquationSolution(
                    $refinedValue,
                    \abs($residual),
                    $solution->iterations,
                );
            }
            $solutions = $this->deduplicateSortedEquationSolutions($solutions, $solverOptions);

            return $solutions;
        }

        return null;
    }

    /**
     * Transform inverse regularized-gamma polynomial levels to forward equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedInverseRegularizedGammaPolynomialTargets(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $leftSource, 0, $rightSource],
                [$right, $rightSource, 0, $leftSource],
            ] as [$functionNode, $functionSource, $functionSourceOffset, $targetSource]
        ) {
            $functionNode = $this->unwrapGrouping($functionNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || !\in_array($functionNode->name, ['gammaincinv', 'gammainccinv'], true)
                || \count($functionNode->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($functionNode->name)
            ) {
                continue;
            }
            $shapeNode = $this->unwrapGrouping($functionNode->arguments[0]);
            $shapeSource = \substr(
                $functionSource,
                $shapeNode->span()->start - $functionSourceOffset,
                $shapeNode->span()->length(),
            );
            if ($shapeSource === '') {
                continue;
            }
            $probability = $this->unwrapGrouping($functionNode->arguments[1]);
            $probabilityCoefficients = $extractor->extract($probability);
            if (
                $probabilityCoefficients === null
                || \count($probabilityCoefficients) < 2
            ) {
                continue;
            }
            $probabilityExpression = $this->polynomialCoefficientsSource($probabilityCoefficients, $variable);
            $probabilityIntervals = $this->polynomialRangeDomainIntervals(
                $probabilityCoefficients,
                0.0,
                1.0,
                $solverOptions,
            );
            if ($probabilityExpression === null || $probabilityIntervals === null) {
                continue;
            }
            if ($probabilityIntervals === []) {
                return [];
            }
            $targetExpression = '(' . $targetSource . ')';

            $finiteIntervals = [];
            foreach ($probabilityIntervals as [$intervalLower, $intervalUpper]) {
                $finiteLower = \max($lowerBound, $intervalLower);
                $finiteUpper = \min($upperBound, $intervalUpper);
                if ($finiteLower <= $finiteUpper) {
                    $finiteIntervals[] = [$finiteLower, $finiteUpper];
                }
            }
            if ($finiteIntervals === []) {
                return [];
            }
            $finiteIntervals = $this->intersectInverseTargetDomainIntervals(
                $targetExpression,
                false,
                $variable,
                $finiteIntervals,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($finiteIntervals === null) {
                return null;
            }
            if ($finiteIntervals === []) {
                return [];
            }
            $finiteIntervals = $this->intersectPositiveExpressionDomainIntervals(
                $shapeSource,
                $variable,
                $finiteIntervals,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($finiteIntervals === null) {
                return null;
            }
            if ($finiteIntervals === []) {
                return [];
            }
            $forwardFunction = $functionNode->name === 'gammaincinv'
                ? 'gammainc'
                : 'gammaincc';
            $transformedEquation = $forwardFunction . '(' . $shapeSource . ','
                . $targetExpression . ') = ' . $probabilityExpression;
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $transformedCandidates = [];
            foreach ($finiteIntervals as [$finiteLower, $finiteUpper]) {
                $intervalSolutions = $this->solve(
                    $transformedEquation,
                    $variable,
                    $finiteLower,
                    $finiteUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($intervalSolutions as $solution) {
                    $transformedCandidates[] = [$solution, $finiteLower, $finiteUpper];
                }
            }
            $solutions = [];
            $originalResidualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $scaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            foreach ($transformedCandidates as [$solution, $finiteLower, $finiteUpper]) {
                $residual = $originalResidualAt($solution->value);
                if ($residual === null) {
                    continue;
                }
                $refinedValue = $this->refineVerifiedEquationCandidate(
                    $solution->value,
                    $residual,
                    $originalResidualAt,
                    $solution->value,
                    $finiteLower,
                    $finiteUpper,
                    $solverOptions,
                );
                $residual = $originalResidualAt($refinedValue);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $refinedValue,
                        $residual,
                        $scaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $solutions[] = new EquationSolution(
                    $refinedValue,
                    \abs($residual),
                    $solution->iterations,
                );
            }

            $solutions = $this->deduplicateSortedEquationSolutions($solutions, $solverOptions);

            return $solutions;
        }

        return null;
    }

