    /**
     * @param list<array{float, float}> $intervals
     * @param array<string, int|float> $parameters
     * @return list<array{float, float}>|null
     */
    private function intersectInverseTargetDomainIntervals(
        string $targetExpression,
        bool $unitInterval,
        string $variable,
        array $intervals,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $inequalitySolver = new InequalitySolver();
        $targetNode = $this->parseSide($targetExpression, 0, $evaluationOptions);
        $domainPointIsValid = function (float $point) use (
            $targetNode,
            $unitInterval,
            $variable,
            $parameters,
            $evaluationOptions,
        ): bool {
            try {
                $variables = [...$parameters, $variable => $point];
                $targetValue = (float) $this->evaluateNode($targetNode, $variables, $evaluationOptions);
                if (
                    !\is_finite($targetValue)
                    || $targetValue < 0.0
                    || ($unitInterval && $targetValue > 1.0)
                ) {
                    return false;
                }

                return true;
            } catch (EvaluationException) {
                return false;
            }
        };
        $intersections = [];
        foreach ($intervals as [$lowerBound, $upperBound]) {
            if ($lowerBound === $upperBound) {
                if ($domainPointIsValid($lowerBound)) {
                    $intersections[] = [$lowerBound, $upperBound];
                }
                continue;
            }
            $validIntervals = [[$lowerBound, $upperBound]];
            $constraints = ['(' . $targetExpression . ') >= 0'];
            if ($unitInterval) {
                $constraints[] = '(' . $targetExpression . ') <= 1';
            }
            try {
                foreach ($constraints as $constraint) {
                    $constraintIntervals = $inequalitySolver->solve(
                        $constraint,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    $nextIntervals = [];
                    foreach ($validIntervals as [$validLower, $validUpper]) {
                        foreach ($constraintIntervals as $constraintInterval) {
                            $intersectionLower = \max($validLower, $constraintInterval->lowerBound);
                            $intersectionUpper = \min($validUpper, $constraintInterval->upperBound);
                            if ($intersectionLower <= $intersectionUpper) {
                                $nextIntervals[] = [$intersectionLower, $intersectionUpper];
                            }
                        }
                    }
                    $validIntervals = $nextIntervals;
                    if ($validIntervals === []) {
                        break;
                    }
                }
            } catch (InfiniteRootAccumulationException | InfiniteSolutionSetException | \DomainException) {
                return null;
            }
            foreach ($validIntervals as [$lower, $upper]) {
                if (!$domainPointIsValid($lower)) {
                    $adjacent = $this->adjacentFloat($lower, 1);
                    if ($adjacent === null) {
                        continue;
                    }
                    $lower = $adjacent;
                }
                if (!$domainPointIsValid($upper)) {
                    $adjacent = $this->adjacentFloat($upper, -1);
                    if ($adjacent === null) {
                        continue;
                    }
                    $upper = $adjacent;
                }
                if (
                    $lower <= $upper
                    && $domainPointIsValid($lower)
                    && $domainPointIsValid($upper)
                ) {
                    $intersections[] = [$lower, $upper];
                }
            }
        }

        return $intersections;
    }

    /**
     * Restrict intervals to where an expression is strictly positive.
     *
     * @param list<array{float, float}> $intervals
     * @param array<string, int|float> $parameters
     * @return list<array{float, float}>|null
     */
    private function intersectPositiveExpressionDomainIntervals(
        string $expression,
        string $variable,
        array $intervals,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $positiveIntervals = $this->intersectInverseTargetDomainIntervals(
            $expression,
            false,
            $variable,
            $intervals,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($positiveIntervals === null || $positiveIntervals === []) {
            return $positiveIntervals;
        }
        $node = $this->parseSide($expression, 0, $evaluationOptions);
        $isPositiveAt = function (float $point) use (
            $node,
            $variable,
            $parameters,
            $evaluationOptions,
        ): bool {
            try {
                return $this->evaluateNode(
                    $node,
                    [...$parameters, $variable => $point],
                    $evaluationOptions,
                ) > 0.0;
            } catch (EvaluationException | \DomainException | \OverflowException) {
                return false;
            }
        };
        $strictIntervals = [];
        foreach ($positiveIntervals as [$lower, $upper]) {
            if ($lower === $upper) {
                if ($isPositiveAt($lower)) {
                    $strictIntervals[] = [$lower, $upper];
                }
                continue;
            }
            for ($step = 0; $step < 128 && !$isPositiveAt($lower); ++$step) {
                $next = $this->adjacentFloat($lower, 1);
                if ($next === null || $next > $upper) {
                    break;
                }
                $lower = $next;
            }
            for ($step = 0; $step < 128 && !$isPositiveAt($upper); ++$step) {
                $next = $this->adjacentFloat($upper, -1);
                if ($next === null || $next < $lower) {
                    break;
                }
                $upper = $next;
            }
            if ($lower <= $upper && $isPositiveAt($lower) && $isPositiveAt($upper)) {
                $strictIntervals[] = [$lower, $upper];
            }
        }

        return $strictIntervals;
    }

    /**
     * Find finite intervals where a nonconstant polynomial lies in [0, 1].
     *
     * @param list<float> $coefficients
     * @return list<array{float, float}>|null
     */
    private function polynomialRangeDomainIntervals(
        array $coefficients,
        float $rangeLower,
        float $rangeUpper,
        SolverOptions $solverOptions,
    ): ?array {
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) < 2) {
            return null;
        }

        $solver = new PolynomialSolver();
        $boundaries = [];
        foreach ([$rangeLower, $rangeUpper] as $level) {
            $levelPolynomial = $coefficients;
            $levelPolynomial[0] -= $level;
            $roots = $this->solvePolynomialRootsInInterval(
                $levelPolynomial,
                -\INF,
                \INF,
                $solverOptions,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $boundaries[] = $root->value;
            }
        }
        \sort($boundaries, SORT_NUMERIC);
        $distinctBoundaries = [];
        foreach ($boundaries as $boundary) {
            if (
                $distinctBoundaries === []
                || \abs($boundary - $distinctBoundaries[\array_key_last($distinctBoundaries)])
                    > $solverOptions->positionTolerance(
                        $boundary,
                        $distinctBoundaries[\array_key_last($distinctBoundaries)],
                    )
            ) {
                $distinctBoundaries[] = $boundary;
            }
        }

        $intervals = [];
        for ($index = 0, $count = \count($distinctBoundaries) - 1; $index < $count; ++$index) {
            $lower = $distinctBoundaries[$index];
            $upper = $distinctBoundaries[$index + 1];
            if ($lower >= $upper || !\is_finite($lower) || !\is_finite($upper)) {
                continue;
            }
            $sample = ($lower / 2.0) + ($upper / 2.0);
            $probability = $solver->evaluatePolynomial($coefficients, $sample);
            if ($probability !== null && $probability >= $rangeLower && $probability <= $rangeUpper) {
                $intervals[] = [$lower, $upper];
            }
        }
        foreach ($distinctBoundaries as $boundary) {
            $probability = $solver->evaluatePolynomial($coefficients, $boundary);
            if ($probability === null || $probability < $rangeLower || $probability > $rangeUpper) {
                continue;
            }
            $covered = false;
            foreach ($intervals as [$lower, $upper]) {
                if ($boundary >= $lower && $boundary <= $upper) {
                    $covered = true;
                    break;
                }
            }
            if (!$covered) {
                $intervals[] = [$boundary, $boundary];
            }
        }
        \usort(
            $intervals,
            static fn (array $first, array $second): int => $first[0] <=> $second[0],
        );

        return $intervals;
    }

    /**
     * Merge duplicate roots returned by adjacent closed probability intervals.
     *
     * @param list<EquationSolution> $solutions
     * @return list<EquationSolution>
     */
    private function deduplicateSortedEquationSolutions(
        array $solutions,
        SolverOptions $solverOptions,
    ): array {
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );
        $distinct = [];
        foreach ($solutions as $solution) {
            $previous = $distinct[\array_key_last($distinct)] ?? null;
            if (
                $previous instanceof EquationSolution
                && \abs($solution->value - $previous->value)
                    <= $solverOptions->positionTolerance($solution->value, $previous->value)
            ) {
                if ($solution->residual < $previous->residual) {
                    $distinct[\array_key_last($distinct)] = $solution;
                }
                continue;
            }
            $distinct[] = $solution;
        }

        return $distinct;
    }

    /** @param list<float> $coefficients */
    private function polynomialCoefficientsSource(array $coefficients, string $variable): ?string
    {
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        $terms = [];
        foreach ($coefficients as $power => $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
            if ($coefficient === 0.0) {
                continue;
            }
            $coefficientSource = \sprintf('%.17g', $coefficient);
            if ($power === 0) {
                $terms[] = $coefficientSource;
                continue;
            }
            $variablePower = $power === 1 ? $variable : '(' . $variable . '^' . $power . ')';
            $terms[] = '(' . $coefficientSource . ')*(' . $variablePower . ')';
        }

        return $terms === [] ? '0' : '(' . \implode('+', $terms) . ')';
    }

    /**
     * Classify direct acosh intersections with y = x and y = -x.
     *
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAcoshFixedPoints(
        Node $left,
        Node $right,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $targetNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            $targetNode = $this->unwrapGrouping($targetNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || $functionNode->name !== 'acosh'
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('acosh')
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            if (!$argument instanceof VariableNode || $argument->name !== $variable) {
                continue;
            }
            if (
                $targetNode instanceof UnaryOperationNode
                && \in_array($targetNode->operator, [UnaryOperator::Minus, UnaryOperator::Plus], true)
            ) {
                $targetNode = $this->unwrapGrouping($targetNode->operand);
            }
            if ($targetNode instanceof VariableNode && $targetNode->name === $variable) {
                return [];
            }
        }

        return null;
    }

    /**
     * Recognize built-ins whose intersections with y = x and y = -x occur only at zero.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedUniqueZeroFixedPoint(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $singleIntersectionFunctions = [
            'sin',
            'sinh',
            'tanh',
            'atan',
            'arctan',
            'asin',
            'arcsin',
            'asinh',
            'arcsinh',
            'atanh',
            'arctanh',
            'dawson',
            'erfi',
            'lambertw',
            'expm1',
            'log1p',
        ];
        $affineOnePlusFunctions = ['ln', 'exp'];
        foreach ([[$left, $right], [$right, $left]] as [$function, $target]) {
            $function = $this->unwrapGrouping($function);
            $target = $this->unwrapGrouping($target);
            if (
                !$function instanceof FunctionCallNode
                || (
                    !\in_array($function->name, $singleIntersectionFunctions, true)
                    && !\in_array($function->name, $affineOnePlusFunctions, true)
                    && $function->name !== 'erf'
                )
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($function->arguments[0]);
            $targetIsVariable = $target instanceof VariableNode && $target->name === $variable;
            $targetOperand = $target instanceof UnaryOperationNode
                && $target->operator === UnaryOperator::Minus
                ? $this->unwrapGrouping($target->operand)
                : null;
            $targetIsNegativeVariable = $target instanceof UnaryOperationNode
                && $target->operator === UnaryOperator::Minus
                && $targetOperand instanceof VariableNode
                && $targetOperand->name === $variable;
            $targetIsSignedVariable = $targetIsVariable || $targetIsNegativeVariable;
            $targetAffineOneSign = $this->onePlusOrMinusVariableSign($target, $variable);
            $argumentIsVariable = $argument instanceof VariableNode && $argument->name === $variable;
            $argumentIsSineOfVariable = $argument instanceof FunctionCallNode
                && $argument->name === 'sin'
                && \count($argument->arguments) === 1
                && $argument->arguments[0] instanceof VariableNode
                && $argument->arguments[0]->name === $variable
                && $evaluationOptions->functions->isBuiltIn($argument->name);
            $argumentAffineOneSign = $this->onePlusOrMinusVariableSign($argument, $variable);
            $sameArgumentTarget = $this->sameExpression($argument, $target);
            $isErfSlopeTangent = false;
            if ($function->name === 'erf' && $evaluationOptions->functions->isBuiltIn('erf')) {
                $extractor = new PolynomialExtractor(
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions->maxPolynomialDegree,
                );
                $argumentCoefficients = $extractor->extract($argument);
                $targetCoefficients = $extractor->extract($target);
                if ($argumentCoefficients !== null && $targetCoefficients !== null) {
                    while (\count($argumentCoefficients) > 1 && $argumentCoefficients[\array_key_last($argumentCoefficients)] === 0.0) {
                        \array_pop($argumentCoefficients);
                    }
                    while (\count($targetCoefficients) > 1 && $targetCoefficients[\array_key_last($targetCoefficients)] === 0.0) {
                        \array_pop($targetCoefficients);
                    }
                    $tangentSlope = 2.0 / \sqrt(\M_PI);
                    $isErfSlopeTangent = \count($argumentCoefficients) === \count($targetCoefficients);
                    foreach ($argumentCoefficients as $degree => $coefficient) {
                        $expected = $coefficient * $tangentSlope;
                        $actual = $targetCoefficients[$degree] ?? \NAN;
                        if (
                            !\is_finite($expected)
                            || !\is_finite($actual)
                            || \abs($actual - $expected)
                                > 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($expected))
                        ) {
                            $isErfSlopeTangent = false;
                            break;
                        }
                    }
                }
            }
            $isUniqueZeroIntersection = \in_array($function->name, $singleIntersectionFunctions, true)
                && (($argumentIsVariable && $targetIsSignedVariable) || $sameArgumentTarget)
                || $isErfSlopeTangent;
            $isStrictSineContractionFixedPoint = \in_array($function->name, ['tanh', 'atan', 'arctan'], true)
                && $argumentIsSineOfVariable
                && $targetIsVariable;
            $isLogarithmicOnePlusIntersection = $function->name === 'ln'
                && $argumentAffineOneSign !== null
                && $targetIsSignedVariable;
            $isExponentialOnePlusIntersection = $function->name === 'exp'
                && $argumentIsVariable
                && $targetAffineOneSign !== null;
            if (
                !$isUniqueZeroIntersection
                && !$isStrictSineContractionFixedPoint
                && !$isLogarithmicOnePlusIntersection
                && !$isExponentialOnePlusIntersection
            ) {
                continue;
            }
            if (
                $isLogarithmicOnePlusIntersection
                || $isExponentialOnePlusIntersection
                || $isStrictSineContractionFixedPoint
            ) {
                if ($lowerBound > 0.0 || $upperBound < 0.0) {
                    return [];
                }
                $candidateValues = [0.0];
            } elseif ($argumentIsVariable) {
                if ($lowerBound > 0.0 || $upperBound < 0.0) {
                    return [];
                }
                $candidateValues = [0.0];
            } else {
                $coefficients = (new PolynomialExtractor(
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions->maxPolynomialDegree,
                ))->extract($argument);
                if ($coefficients === null) {
                    return null;
                }
                while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
                    \array_pop($coefficients);
                }
                if (\count($coefficients) === 1) {
                    if ($coefficients[0] === 0.0 && $lowerBound < $upperBound) {
                        throw new InfiniteSolutionSetException(
                            'The function and target coincide throughout the interval.',
                        );
                    }

                    return [];
                }
                $argumentRoots = $this->solvePolynomialRootsInInterval(
                    $coefficients,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($argumentRoots === null) {
                    return null;
                }
                $candidateValues = \array_map(
                    static fn (EquationSolution $root): float => $root->value,
                    $argumentRoots,
                );
            }
            $solutions = [];
            foreach ($candidateValues as $candidateValue) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidateValue,
                    $parameters,
                    $evaluationOptions,
                );
                if ($residual !== null && \is_finite($residual)) {
                    $solutions[] = new EquationSolution($candidateValue, \abs($residual), 0);
                }
            }

            return $solutions;
        }

        return null;
    }

    /**
     * Solve atanh of an affine argument against a polynomial on its open domain.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAtanhPolynomialTargetEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$inverse, $target]) {
            $inverse = $this->unwrapGrouping($inverse);
            if (
                !$inverse instanceof FunctionCallNode
                || !\in_array($inverse->name, ['atanh', 'arctanh'], true)
                || \count($inverse->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inverse->name)
            ) {
                continue;
            }
            $argument = $this->extractPolynomial(
                $extractor,
                $inverse->arguments[0],
                $inverse->arguments[0]->span()->start,
            );
            $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
            if (
                $argument === null
                || $targetCoefficients === null
                || \count($argument) > 2
            ) {
                continue;
            }
            $argumentIntercept = $argument[0] ?? 0.0;
            $argumentSlope = $argument[1] ?? 0.0;
            if (
                !\is_finite($argumentIntercept)
                || !\is_finite($argumentSlope)
                || $argumentSlope === 0.0
            ) {
                continue;
            }

            $domainA = (-1.0 - $argumentIntercept) / $argumentSlope;
            $domainB = (1.0 - $argumentIntercept) / $argumentSlope;
            if (!\is_finite($domainA) || !\is_finite($domainB)) {
                continue;
            }
            $domainLower = \min($domainA, $domainB);
            $domainUpper = \max($domainA, $domainB);
            $lowerBoundaryArgument = $argumentSlope > 0.0 ? -1.0 : 1.0;
            $upperBoundaryArgument = -$lowerBoundaryArgument;
            $insideLowerArgument = $this->adjacentFloat(
                $lowerBoundaryArgument,
                $argumentSlope > 0.0 ? 1 : -1,
            );
            $insideUpperArgument = $this->adjacentFloat(
                $upperBoundaryArgument,
                $argumentSlope > 0.0 ? -1 : 1,
            );
            if ($insideLowerArgument !== null) {
                $domainLower = ($insideLowerArgument - $argumentIntercept) / $argumentSlope;
            }
            if ($insideUpperArgument !== null) {
                $domainUpper = ($insideUpperArgument - $argumentIntercept) / $argumentSlope;
            }
            for ($step = 0; $step < 64 && $argumentSlope * $domainLower + $argumentIntercept <= -1.0; ++$step) {
                $domainLower = $this->adjacentFloat($domainLower, 1) ?? $domainLower;
            }
            for ($step = 0; $step < 64 && $argumentSlope * $domainUpper + $argumentIntercept >= 1.0; ++$step) {
                $domainUpper = $this->adjacentFloat($domainUpper, -1) ?? $domainUpper;
            }
            if (
                !($argumentSlope * $domainLower + $argumentIntercept > -1.0)
                || !($argumentSlope * $domainUpper + $argumentIntercept < 1.0)
            ) {
                continue;
            }
            $intervalLower = \max($domainLower, $lowerBound);
            $intervalUpper = \min($domainUpper, $upperBound);
            if ($intervalLower > $intervalUpper) {
                return [];
            }

            $argumentComplementSquare = [
                1.0 - ($argumentIntercept * $argumentIntercept),
                -2.0 * $argumentIntercept * $argumentSlope,
                -($argumentSlope * $argumentSlope),
            ];
            $derivativeNumerator = $this->subtractScaledPolynomials(
                [$argumentSlope],
                $this->multiplyPolynomials(
                    $this->polynomialDerivative($targetCoefficients),
                    $argumentComplementSquare,
                ),
                1.0,
            );
            if ($derivativeNumerator === null) {
                return null;
            }
            foreach ($derivativeNumerator as $coefficient) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }
            $criticalSolutions = $this->solvePolynomialRootsInInterval(
                $derivativeNumerator,
                $intervalLower,
                $intervalUpper,
                $solverOptions,
            );
            if ($criticalSolutions === null) {
                return null;
            }
            $criticalPoints = \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $criticalSolutions,
            );
            \sort($criticalPoints, SORT_NUMERIC);
            $criticalPoints = \array_values(\array_unique($criticalPoints, SORT_REGULAR));
            $points = [$intervalLower, ...$criticalPoints];
            if ($intervalUpper > $intervalLower) {
                $points[] = $intervalUpper;
            }
            $solutions = [];
            $iterations = 0;
            $acceptPoint = function (
                float $point,
                bool $refineNeighbors = true,
            ) use (
                &$solutions,
                &$iterations,
                $intervalLower,
                $intervalUpper,
                $residualAt,
                $residualScaleAt,
                $solverOptions,
            ): ?float {
                $residual = $residualAt($point);
                if ($residual === null || !\is_finite($residual)) {
                    return null;
                }
                [$candidate, $bestResidual] = $refineNeighbors
                    ? $this->bestRepresentableResidualCandidate(
                        $point,
                        $residual,
                        $intervalLower,
                        $intervalUpper,
                        $residualAt,
                    )
                    : [$point, $residual];
                if (
                    $bestResidual !== null
                    && $this->isResidualAcceptableAt($candidate, $bestResidual, $residualScaleAt, $solverOptions)
                ) {
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($bestResidual), $iterations),
                    );
                }

                return $residual;
            };
            $residuals = [];
            foreach ($points as $point) {
                $residuals[] = $acceptPoint($point, !\in_array($point, $criticalPoints, true));
            }
            for ($index = 0, $last = \count($points) - 1; $index < $last; ++$index) {
                $leftResidual = $residuals[$index];
                $rightResidual = $residuals[$index + 1];
                if (
                    ($leftResidual !== null
                        && \in_array($points[$index], $criticalPoints, true)
                        && $this->isResidualAtNumericalZero($points[$index], $leftResidual, $residualScaleAt))
                    || ($rightResidual !== null
                        && \in_array($points[$index + 1], $criticalPoints, true)
                        && $this->isResidualAtNumericalZero($points[$index + 1], $rightResidual, $residualScaleAt))
                ) {
                    continue;
                }
                if (
                    $leftResidual === null
                    || $rightResidual === null
                    || !$this->hasOppositeSigns($leftResidual, $rightResidual)
                ) {
                    continue;
                }
                [$root, $count] = $this->bisectMonotoneRoot(
                    static fn (float $value): float => $residualAt($value) ?? \NAN,
                    $points[$index],
                    $points[$index + 1],
                    $leftResidual < 0.0 ? -1 : 1,
                );
                $iterations = $count;
                $acceptPoint($root);
            }
            \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

            return $solutions;
        }

        return null;
    }

    /**
     * Isolate roots of affine hyperbolic and inverse-hyperbolic equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    /**
     * Solve asin/acos of an affine argument against a polynomial on its finite domain.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveInverseSinePolynomialTargetEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$inverse, $target]) {
            $inverse = $this->unwrapGrouping($inverse);
            if (
                !$inverse instanceof FunctionCallNode
                || !\in_array(
                    $inverse->name,
                    ['asin', 'arcsin', 'acos', 'arccos', 'atan', 'arctan', 'acot', 'arccot'],
                    true,
                )
                || \count($inverse->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inverse->name)
            ) {
                continue;
            }
            $argument = $this->extractPolynomial(
                $extractor,
                $inverse->arguments[0],
                $inverse->arguments[0]->span()->start,
            );
            $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
            if ($argument === null || $targetCoefficients === null) {
                continue;
            }
            if (\count($targetCoefficients) === 1) {
                continue;
            }
            foreach ($argument as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
            }
            while (\count($argument) > 1 && $argument[\array_key_last($argument)] === 0.0) {
                \array_pop($argument);
            }
            $argumentDerivative = $this->polynomialDerivative($argument);
            if ($argumentDerivative === [0.0]) {
                continue;
            }

            $argumentAt = fn (float $value): ?float => $this->polynomialValue($argument, $value);
            $isAcot = \in_array($inverse->name, ['acot', 'arccot'], true);
            $isAtan = \in_array($inverse->name, ['atan', 'arctan'], true);
            $domainIntervals = [];
            if ($isAcot || $isAtan) {
                $intervalLower = $lowerBound;
                $intervalUpper = $upperBound;
                if (!\is_finite($intervalLower) || !\is_finite($intervalUpper)) {
                    if (\count($targetCoefficients) === 1) {
                        continue;
                    }
                    $rangeLower = $isAcot ? 0.0 : -\M_PI_2;
                    $rangeUpper = $isAcot ? \M_PI : \M_PI_2;
                    $lowerTargetBoundary = $targetCoefficients;
                    $lowerTargetBoundary[0] = ($lowerTargetBoundary[0] ?? 0.0) - $rangeLower;
                    $upperTargetBoundary = $targetCoefficients;
                    $upperTargetBoundary[0] = ($upperTargetBoundary[0] ?? 0.0) - $rangeUpper;
                    $lowerTargetRoots = $this->solvePolynomialRootsInInterval(
                        $lowerTargetBoundary,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    $upperTargetRoots = $this->solvePolynomialRootsInInterval(
                        $upperTargetBoundary,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($lowerTargetRoots === null || $upperTargetRoots === null) {
                        return null;
                    }
                    $rangeBoundaryRoots = [...$lowerTargetRoots, ...$upperTargetRoots];
                    if ($rangeBoundaryRoots === []) {
                        return [];
                    }
                    $rangeBoundaryValues = \array_map(
                        static fn (EquationSolution $root): float => $root->value,
                        $rangeBoundaryRoots,
                    );
                    if (!\is_finite($intervalLower)) {
                        $intervalLower = \min($rangeBoundaryValues);
                    }
                    if (!\is_finite($intervalUpper)) {
                        $intervalUpper = \max($rangeBoundaryValues);
                    }
                    if ($intervalLower > $intervalUpper) {
                        return [];
                    }
                }
                $domainIntervals = [[$intervalLower, $intervalUpper]];
            } else {
                if (\count($argument) > 2) {
                    $lowerBoundary = $argument;
                    $lowerBoundary[0] = ($lowerBoundary[0] ?? 0.0) + 1.0;
                    $upperBoundary = $argument;
                    $upperBoundary[0] = ($upperBoundary[0] ?? 0.0) - 1.0;
                    $lowerRoots = $this->solvePolynomialRootsInInterval(
                        $lowerBoundary,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    $upperRoots = $this->solvePolynomialRootsInInterval(
                        $upperBoundary,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($lowerRoots === null || $upperRoots === null) {
                        return null;
                    }
                    $boundaryRoots = [...$lowerRoots, ...$upperRoots];
                    if ((!\is_finite($lowerBound) || !\is_finite($upperBound)) && $boundaryRoots === []) {
                        return [];
                    }
                    $effectiveLower = \is_finite($lowerBound)
                        ? $lowerBound
                        : \min(\array_map(static fn (EquationSolution $root): float => $root->value, $boundaryRoots));
                    $effectiveUpper = \is_finite($upperBound)
                        ? $upperBound
                        : \max(\array_map(static fn (EquationSolution $root): float => $root->value, $boundaryRoots));
                    if ($effectiveLower > $effectiveUpper) {
                        return [];
                    }
                    $knots = [$effectiveLower, $effectiveUpper];
                    foreach ($boundaryRoots as $boundaryRoot) {
                        if ($boundaryRoot->value >= $effectiveLower && $boundaryRoot->value <= $effectiveUpper) {
                            $knots[] = $boundaryRoot->value;
                        }
                    }
                    \sort($knots, SORT_NUMERIC);
                    $knots = \array_values(\array_unique($knots, SORT_REGULAR));
                    $validIntervals = [];
                    for ($index = 0, $last = \count($knots) - 1; $index < $last; ++$index) {
                        $start = $knots[$index];
                        $end = $knots[$index + 1];
                        $middle = $start + (($end - $start) / 2.0);
                        $middleArgument = $argumentAt($middle);
                        if ($middleArgument !== null && \abs($middleArgument) < 1.0) {
                            $validIntervals[] = [$start, $end];
                        }
                    }
                    foreach ($knots as $knot) {
                        $knotArgument = $argumentAt($knot);
                        if ($knotArgument !== null && \abs($knotArgument) <= 1.0) {
                            $covered = false;
                            foreach ($validIntervals as [$start, $end]) {
                                if ($knot >= $start && $knot <= $end) {
                                    $covered = true;
                                    break;
                                }
                            }
                            if (!$covered) {
                                $validIntervals[] = [$knot, $knot];
                            }
                        }
                    }
                    \usort($validIntervals, static fn (array $first, array $second): int => $first[0] <=> $second[0]);
                    $mergedIntervals = [];
                    foreach ($validIntervals as [$start, $end]) {
                        $lastInterval = \array_key_last($mergedIntervals);
                        if ($lastInterval !== null && $start <= $mergedIntervals[$lastInterval][1]) {
                            $mergedIntervals[$lastInterval][1] = \max($mergedIntervals[$lastInterval][1], $end);
                        } else {
                            $mergedIntervals[] = [$start, $end];
                        }
                    }
                    $domainIntervals = $mergedIntervals;
                } else {
                    $argumentIntercept = $argument[0] ?? 0.0;
                    $argumentSlope = $argumentDerivative[0] ?? 0.0;
                    $domainA = (-1.0 - $argumentIntercept) / $argumentSlope;
                    $domainB = (1.0 - $argumentIntercept) / $argumentSlope;
                    if (!\is_finite($domainA) || !\is_finite($domainB)) {
                        continue;
                    }
                    $domainLower = \min($domainA, $domainB);
                    $domainUpper = \max($domainA, $domainB);
                    $intervalLower = \max($lowerBound, $domainLower);
                    $intervalUpper = \min($upperBound, $domainUpper);
                    if ($intervalLower <= $intervalUpper) {
                        $domainIntervals = [[$intervalLower, $intervalUpper]];
                    }
                }
                if ($domainIntervals === []) {
                    return [];
                }
            }

            $solutions = [];
            foreach ($domainIntervals as [$intervalLower, $intervalUpper]) {
                if (!$isAcot && !$isAtan) {
                    for ($step = 0; $step < 64 && \abs($argumentAt($intervalLower) ?? \INF) > 1.0; ++$step) {
                        $intervalLower = $this->adjacentFloat($intervalLower, 1) ?? $intervalLower;
                    }
                    for ($step = 0; $step < 64 && \abs($argumentAt($intervalUpper) ?? \INF) > 1.0; ++$step) {
                        $intervalUpper = $this->adjacentFloat($intervalUpper, -1) ?? $intervalUpper;
                    }
                    if (
                        $intervalLower > $intervalUpper
                        || \abs($argumentAt($intervalLower) ?? \INF) > 1.0
                        || \abs($argumentAt($intervalUpper) ?? \INF) > 1.0
                    ) {
                        continue;
                    }
                }

                $argumentSquare = $this->multiplyPolynomials($argument, $argument);
                if ($isAcot || $isAtan) {
                    $argumentDerivativeDenominator = $argumentSquare;
                    $argumentDerivativeDenominator[0] = ($argumentDerivativeDenominator[0] ?? 0.0) + 1.0;
                } else {
                    $argumentDerivativeDenominator = $this->subtractScaledPolynomials([1.0], $argumentSquare, 1.0);
                }
                if ($argumentDerivativeDenominator === null) {
                    return null;
                }
                if ($isAcot || $isAtan) {
                    $argumentDerivativeDenominator = $this->multiplyPolynomials(
                        $argumentDerivativeDenominator,
                        $argumentDerivativeDenominator,
                    );
                }
                $targetDerivative = $this->polynomialDerivative($targetCoefficients);
                $criticalPolynomial = $this->subtractScaledPolynomials(
                    $this->multiplyPolynomials(
                        $this->multiplyPolynomials($targetDerivative, $targetDerivative),
                        $argumentDerivativeDenominator,
                    ),
                    $this->multiplyPolynomials($argumentDerivative, $argumentDerivative),
                    1.0,
                );
                if ($criticalPolynomial === null) {
                    return null;
                }
                foreach ($criticalPolynomial as $coefficient) {
                    if (!\is_finite($coefficient)) {
                        return null;
                    }
                }
                $criticalSolutions = $this->solvePolynomialRootsInInterval(
                    $criticalPolynomial,
                    $intervalLower,
                    $intervalUpper,
                    $solverOptions,
                );
                if ($criticalSolutions === null) {
                    return null;
                }
                $isAsin = \in_array($inverse->name, ['asin', 'arcsin'], true);
                $criticalPoints = [];
                foreach ($criticalSolutions as $criticalSolution) {
                    $critical = $criticalSolution->value;
                    $argumentValue = $argumentAt($critical);
                    $argumentDerivativeValue = $this->polynomialValue($argumentDerivative, $critical);
                    $targetDerivativeValue = $this->polynomialValue($targetDerivative, $critical);
                    if ($argumentDerivativeValue === 0.0 && $targetDerivativeValue === 0.0) {
                        $criticalPoints[] = $critical;
                        continue;
                    }
                    if (
                        $argumentValue === null
                        || !\is_finite($argumentValue)
                        || (!($isAcot || $isAtan) && \abs($argumentValue) >= 1.0)
                        || $argumentDerivativeValue === null
                        || $targetDerivativeValue === null
                        || ($argumentDerivativeValue === 0.0)
                        || ($targetDerivativeValue
                            * $argumentDerivativeValue
                            * (($isAcot || (!$isAsin && !$isAtan)) ? -1.0 : 1.0) <= 0.0)
                    ) {
                        continue;
                    }
                    $inverseDerivative = $isAcot
                        ? -$argumentDerivativeValue / (1.0 + ($argumentValue * $argumentValue))
                        : ($isAtan
                            ? $argumentDerivativeValue / (1.0 + ($argumentValue * $argumentValue))
                            : (($isAsin ? $argumentDerivativeValue : -$argumentDerivativeValue)
                                / \sqrt((1.0 - $argumentValue) * (1.0 + $argumentValue))));
                    $criticalDerivative = $inverseDerivative - $targetDerivativeValue;
                    if (
                        \is_finite($criticalDerivative)
                        && \abs($criticalDerivative) <= 1.0E-7 * \max(1.0, \abs($argumentDerivativeValue))
                    ) {
                        $criticalPoints[] = $critical;
                    }
                }
                \sort($criticalPoints, SORT_NUMERIC);
                $criticalPoints = \array_values(\array_unique($criticalPoints, SORT_REGULAR));
                $points = [$intervalLower, ...$criticalPoints];
                if ($intervalUpper > $intervalLower) {
                    $points[] = $intervalUpper;
                }
                $acceptPoint = function (
                    float $point,
                    int $iterations,
                    bool $refineNeighbors = true,
                ) use (
                    &$solutions,
                    $intervalLower,
                    $intervalUpper,
                    $residualAt,
                    $residualScaleAt,
                    $solverOptions,
                ): ?float {
                    $residual = $residualAt($point);
                    if ($residual === null || !\is_finite($residual)) {
                        return null;
                    }
                    [$candidate, $candidateResidual] = $refineNeighbors
                        ? $this->bestRepresentableResidualCandidate(
                            $point,
                            $residual,
                            $intervalLower,
                            $intervalUpper,
                            $residualAt,
                        )
                        : [$point, $residual];
                    if (
                        $candidateResidual !== null
                        && $this->isResidualAcceptableAt(
                            $candidate,
                            $candidateResidual,
                            $residualScaleAt,
                            $solverOptions,
                        )
                    ) {
                        $this->addDistinctSolution(
                            $solutions,
                            new EquationSolution($candidate, \abs($candidateResidual), $iterations),
                        );
                    }

                    return $residual;
                };
                $residuals = [];
                foreach ($points as $point) {
                    $residuals[] = $acceptPoint($point, 0, !\in_array($point, $criticalPoints, true));
                }
                for ($index = 0, $last = \count($points) - 1; $index < $last; ++$index) {
                    $leftResidual = $residuals[$index];
                    $rightResidual = $residuals[$index + 1];
                    if (
                        ($leftResidual !== null
                            && \in_array($points[$index], $criticalPoints, true)
                            && $this->isResidualAtNumericalZero($points[$index], $leftResidual, $residualScaleAt))
                        || ($rightResidual !== null
                            && \in_array($points[$index + 1], $criticalPoints, true)
                            && $this->isResidualAtNumericalZero(
                                $points[$index + 1],
                                $rightResidual,
                                $residualScaleAt,
                            ))
                    ) {
                        continue;
                    }
                    if (
                        $leftResidual === null
                        || $rightResidual === null
                        || !$this->hasOppositeSigns($leftResidual, $rightResidual)
                    ) {
                        continue;
                    }
                    [$root, $iterations] = $this->bisectMonotoneRoot(
                        static fn (float $value): float => $residualAt($value) ?? \NAN,
                        $points[$index],
                        $points[$index + 1],
                        $leftResidual < 0.0 ? -1 : 1,
                    );
                    $acceptPoint($root, $iterations);
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve asinh of an affine argument against a polynomial on the real line.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAsinhPolynomialTargetEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$inverse, $target]) {
            $inverse = $this->unwrapGrouping($inverse);
            if (
                !$inverse instanceof FunctionCallNode
                || !\in_array($inverse->name, ['asinh', 'arcsinh'], true)
                || \count($inverse->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inverse->name)
            ) {
                continue;
            }
            $argument = $this->extractPolynomial(
                $extractor,
                $inverse->arguments[0],
                $inverse->arguments[0]->span()->start,
            );
            $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
            if ($argument === null || $targetCoefficients === null || \count($argument) > 2) {
                continue;
            }
            $argumentIntercept = $argument[0] ?? 0.0;
            $argumentSlope = $argument[1] ?? 0.0;
            if (
                !\is_finite($argumentIntercept)
                || !\is_finite($argumentSlope)
                || $argumentSlope === 0.0
            ) {
                continue;
            }

            $argumentSquare = [
                1.0 + ($argumentIntercept * $argumentIntercept),
                2.0 * $argumentIntercept * $argumentSlope,
                $argumentSlope * $argumentSlope,
            ];
            $targetDerivative = $this->polynomialDerivative($targetCoefficients);
            $criticalPolynomial = $this->subtractScaledPolynomials(
                $this->multiplyPolynomials(
                    $this->multiplyPolynomials($targetDerivative, $targetDerivative),
                    $argumentSquare,
                ),
                [$argumentSlope * $argumentSlope],
                1.0,
            );
            if ($criticalPolynomial === null) {
                return null;
            }
            foreach ($criticalPolynomial as $coefficient) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }
            if (\count($criticalPolynomial) === 1) {
                $criticalSolutions = [];
            } else {
                $leadingCoefficient = \abs($criticalPolynomial[\array_key_last($criticalPolynomial)]);
                if ($leadingCoefficient === 0.0 || !\is_finite($leadingCoefficient)) {
                    return null;
                }
                $rootBound = 1.0;
                foreach (\array_slice($criticalPolynomial, 0, -1) as $coefficient) {
                    $ratio = \abs($coefficient) / $leadingCoefficient;
                    if (!\is_finite($ratio)) {
                        return null;
                    }
                    $rootBound = \max($rootBound, 1.0 + $ratio);
                }
                if (!\is_finite($rootBound)) {
                    return null;
                }
                $criticalLower = \max($lowerBound, -$rootBound);
                $criticalUpper = \min($upperBound, $rootBound);
                $criticalSolutions = $criticalLower > $criticalUpper
                    ? []
                    : $this->solvePolynomialRootsInInterval(
                        $criticalPolynomial,
                        $criticalLower,
                        $criticalUpper,
                        $solverOptions,
                    );
                if ($criticalSolutions === null) {
                    return null;
                }
            }
            $criticalPoints = [];
            foreach ($criticalSolutions as $criticalSolution) {
                $critical = $criticalSolution->value;
                $argumentValue = ($argumentSlope * $critical) + $argumentIntercept;
                $targetDerivativeValue = $this->polynomialValue($targetDerivative, $critical);
                if (
                    !\is_finite($argumentValue)
                    || $targetDerivativeValue === null
                    || ($argumentSlope > 0.0 && $targetDerivativeValue <= 0.0)
                    || ($argumentSlope < 0.0 && $targetDerivativeValue >= 0.0)
                ) {
                    continue;
                }
                $criticalDerivative = ($argumentSlope / \hypot(1.0, $argumentValue)) - $targetDerivativeValue;
                if (!\is_finite($criticalDerivative)) {
                    continue;
                }
                if (\abs($criticalDerivative) <= 1.0E-7 * \max(1.0, \abs($argumentSlope))) {
                    $criticalPoints[] = $critical;
                }
            }
            \sort($criticalPoints, SORT_NUMERIC);
            $criticalPoints = \array_values(\array_unique($criticalPoints, SORT_REGULAR));

            $inverseOnLeft = $inverse === $this->unwrapGrouping($left);
            $degree = \count($targetCoefficients) - 1;
            if ($degree === 0) {
                $leftTailSign = $argumentSlope > 0.0 ? -1 : 1;
                $rightTailSign = -$leftTailSign;
            } else {
                $leadingCoefficient = $targetCoefficients[$degree];
                if ($leadingCoefficient === 0.0) {
                    return null;
                }
                $rightTailSign = $leadingCoefficient > 0.0 ? -1 : 1;
                $leftTailSign = $degree % 2 === 0 ? $rightTailSign : -$rightTailSign;
            }
            if (!$inverseOnLeft) {
                $leftTailSign *= -1;
                $rightTailSign *= -1;
            }

            $findTailEndpoint = static function (
                float $initial,
                int $direction,
                int $expectedSign,
            ) use ($residualAt): ?float {
                $point = $initial;
                $step = \max(1.0, \abs($point));
                for ($iteration = 0; $iteration < 1024; ++$iteration) {
                    $residual = $residualAt($point);
                    if ($residual === null || !\is_finite($residual)) {
                        return null;
                    }
                    if (
                        ($expectedSign < 0 && $residual <= 0.0)
                        || ($expectedSign > 0 && $residual >= 0.0)
                    ) {
                        return $point;
                    }
                    $next = $point + ($direction * $step);
                    if (!\is_finite($next) || $next === $point) {
                        return null;
                    }
                    $point = $next;
                    $step *= 2.0;
                    if (!\is_finite($step)) {
                        return null;
                    }
                }

                return null;
            };
            $intervalLower = $lowerBound;
            if ($intervalLower === -\INF) {
                $anchor = $criticalPoints === []
                    ? -1.0
                    : $criticalPoints[0] - \max(1.0, \abs($criticalPoints[0]));
                $intervalLower = $findTailEndpoint($anchor, -1, $leftTailSign);
                if ($intervalLower === null) {
                    return null;
                }
            }
            $intervalUpper = $upperBound;
            if ($intervalUpper === \INF) {
                $lastCritical = $criticalPoints === []
                    ? 0.0
                    : $criticalPoints[\array_key_last($criticalPoints)];
                $anchor = \max($intervalLower, $lastCritical)
                    + \max(1.0, \abs(\max($intervalLower, $lastCritical)));
                $intervalUpper = $findTailEndpoint($anchor, 1, $rightTailSign);
                if ($intervalUpper === null) {
                    return null;
                }
            }
            if ($intervalLower > $intervalUpper) {
                return [];
            }
            $criticalPoints = \array_values(\array_filter(
                $criticalPoints,
                static fn (float $point): bool => $point > $intervalLower && $point < $intervalUpper,
            ));
            $points = [$intervalLower, ...$criticalPoints];
            if ($intervalUpper > $intervalLower) {
                $points[] = $intervalUpper;
            }
            $solutions = [];
            $acceptPoint = function (
                float $point,
                int $iterations,
                bool $refineNeighbors = true,
            ) use (
                &$solutions,
                $intervalLower,
                $intervalUpper,
                $residualAt,
                $residualScaleAt,
                $solverOptions,
            ): ?float {
                $residual = $residualAt($point);
                if ($residual === null || !\is_finite($residual)) {
                    return null;
                }
                [$candidate, $candidateResidual] = $refineNeighbors
                    ? $this->bestRepresentableResidualCandidate(
                        $point,
                        $residual,
                        $intervalLower,
                        $intervalUpper,
                        $residualAt,
                    )
                    : [$point, $residual];
                if (
                    $candidateResidual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate,
                        $candidateResidual,
                        $residualScaleAt,
                        $solverOptions,
                    )
                ) {
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($candidateResidual), $iterations),
                    );
                }

                return $residual;
            };
            $residuals = [];
            foreach ($points as $point) {
                $residuals[] = $acceptPoint($point, 0, !\in_array($point, $criticalPoints, true));
            }
            for ($index = 0, $last = \count($points) - 1; $index < $last; ++$index) {
                $leftResidual = $residuals[$index];
                $rightResidual = $residuals[$index + 1];
                if (
                    ($leftResidual !== null
                        && \in_array($points[$index], $criticalPoints, true)
                        && $this->isResidualAtNumericalZero($points[$index], $leftResidual, $residualScaleAt))
                    || ($rightResidual !== null
                        && \in_array($points[$index + 1], $criticalPoints, true)
                        && $this->isResidualAtNumericalZero(
                            $points[$index + 1],
                            $rightResidual,
                            $residualScaleAt,
                        ))
                ) {
                    continue;
                }
                if (
                    $leftResidual === null
                    || $rightResidual === null
                    || !$this->hasOppositeSigns($leftResidual, $rightResidual)
                ) {
                    continue;
                }
                [$root, $iterations] = $this->bisectMonotoneRoot(
                    static fn (float $value): float => $residualAt($value) ?? \NAN,
                    $points[$index],
                    $points[$index + 1],
                    $leftResidual < 0.0 ? -1 : 1,
                );
                $acceptPoint($root, $iterations);
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function solveUnboundedAffineHyperbolicEquation(
        string $equation,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$hyperbolic, $linear]) {
            $hyperbolic = $this->unwrapGrouping($hyperbolic);
            if (
                !$hyperbolic instanceof FunctionCallNode
                || !\in_array($hyperbolic->name, ['sinh', 'cosh', 'asinh', 'arcsinh', 'acosh', 'arccosh'], true)
                || \count($hyperbolic->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($hyperbolic->name)
            ) {
                continue;
            }
            $phaseCoefficients = $this->extractPolynomial(
                $extractor,
                $hyperbolic->arguments[0],
                $hyperbolic->arguments[0]->span()->start,
            );
            $linearCoefficients = $this->extractPolynomial($extractor, $linear, $linear->span()->start);
            if (
                $phaseCoefficients === null
                || $linearCoefficients === null
                || \count($phaseCoefficients) > 2
                || \count($linearCoefficients) > 2
            ) {
                return null;
            }
            $phaseIntercept = $phaseCoefficients[0] ?? 0.0;
            $phaseSlope = $phaseCoefficients[1] ?? 0.0;
            $targetSlope = $linearCoefficients[1] ?? 0.0;
            if (
                !\is_finite($phaseIntercept)
                || !\is_finite($phaseSlope)
                || !\is_finite($targetSlope)
                || $phaseSlope === 0.0
            ) {
                return null;
            }

            $domainLowerBound = -\INF;
            $domainUpperBound = \INF;
            if (\in_array($hyperbolic->name, ['acosh', 'arccosh'], true)) {
                $domainBoundary = (1.0 - $phaseIntercept) / $phaseSlope;
                if (!\is_finite($domainBoundary)) {
                    return null;
                }
                if ($phaseSlope > 0.0) {
                    $domainLowerBound = $domainBoundary;
                } else {
                    $domainUpperBound = $domainBoundary;
                }
            }

            $criticalPoints = [];
            $slopeRatio = $targetSlope / $phaseSlope;
            if (!\is_finite($slopeRatio)) {
                return null;
            }
            if ($hyperbolic->name === 'sinh') {
                if ($slopeRatio >= 1.0) {
                    $criticalPhase = \acosh($slopeRatio);
                    foreach ([-$criticalPhase, $criticalPhase] as $phase) {
                        $critical = ($phase - $phaseIntercept) / $phaseSlope;
                        if (!\is_finite($critical)) {
                            return null;
                        }
                        $criticalPoints[] = $critical;
                    }
                }
            } elseif (\in_array($hyperbolic->name, ['acosh', 'arccosh'], true)) {
                if ($slopeRatio > 0.0) {
                    $criticalPhase = \hypot(1.0, 1.0 / $slopeRatio);
                    $critical = ($criticalPhase - $phaseIntercept) / $phaseSlope;
                    if (!\is_finite($criticalPhase) || !\is_finite($critical)) {
                        return null;
                    }
                    $criticalPoints[] = $critical;
                }
            } elseif (\in_array($hyperbolic->name, ['asinh', 'arcsinh'], true)) {
                if ($slopeRatio > 0.0 && $slopeRatio <= 1.0) {
                    $criticalPhase = \sqrt((1.0 - $slopeRatio) * (1.0 + $slopeRatio)) / $slopeRatio;
                    if (!\is_finite($criticalPhase)) {
                        return null;
                    }
                    foreach ([-$criticalPhase, $criticalPhase] as $phase) {
                        $critical = ($phase - $phaseIntercept) / $phaseSlope;
                        if (!\is_finite($critical)) {
                            return null;
                        }
                        $criticalPoints[] = $critical;
                    }
                }
            } else {
                $criticalPhase = \asinh($slopeRatio);
                $critical = ($criticalPhase - $phaseIntercept) / $phaseSlope;
                if (!\is_finite($critical)) {
                    return null;
                }
                $criticalPoints[] = $critical;
            }
            \sort($criticalPoints, SORT_NUMERIC);
            $criticalPoints = \array_values(\array_unique($criticalPoints, SORT_REGULAR));

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $residualScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $hyperbolicOnLeft = $hyperbolic === $this->unwrapGrouping($left);
            if (\in_array($hyperbolic->name, ['acosh', 'arccosh'], true)) {
                $leftHyperbolicSign = $targetSlope > 0.0 ? 1 : ($targetSlope < 0.0 ? -1 : 1);
                $rightHyperbolicSign = $targetSlope > 0.0 ? -1 : ($targetSlope < 0.0 ? 1 : 1);
            } elseif (\in_array($hyperbolic->name, ['asinh', 'arcsinh'], true)) {
                $leftHyperbolicSign = $targetSlope > 0.0
                    ? 1
                    : ($targetSlope < 0.0 ? -1 : ($phaseSlope > 0.0 ? -1 : 1));
                $rightHyperbolicSign = $targetSlope > 0.0
                    ? -1
                    : ($targetSlope < 0.0 ? 1 : ($phaseSlope > 0.0 ? 1 : -1));
            } else {
                $leftHyperbolicSign = $hyperbolic->name === 'cosh'
                    ? 1
                    : ($phaseSlope > 0.0 ? -1 : 1);
                $rightHyperbolicSign = $hyperbolic->name === 'cosh'
                    ? 1
                    : ($phaseSlope > 0.0 ? 1 : -1);
            }
            $leftTailSign = $hyperbolicOnLeft ? $leftHyperbolicSign : -$leftHyperbolicSign;
            $rightTailSign = $hyperbolicOnLeft ? $rightHyperbolicSign : -$rightHyperbolicSign;

            $findTailEndpoint = static function (
                float $initial,
                int $direction,
                int $expectedSign,
            ) use ($residualAt): ?float {
                $point = $initial;
                $step = \max(1.0, \abs($point));
                for ($iteration = 0; $iteration < 128; ++$iteration) {
                    $residual = $residualAt($point);
                    if ($residual === null || !\is_finite($residual)) {
                        return null;
                    }
                    if (
                        ($expectedSign < 0 && $residual <= 0.0)
                        || ($expectedSign > 0 && $residual >= 0.0)
                    ) {
                        return $point;
                    }
                    $next = $point + ($direction * $step);
                    if (!\is_finite($next) || $next === $point) {
                        return null;
                    }
                    $point = $next;
                    $step *= 2.0;
                    if (!\is_finite($step)) {
                        return null;
                    }
                }

                return null;
            };

            $leftEndpoint = \max($lowerBound, $domainLowerBound);
            $rightEndpoint = \min($upperBound, $domainUpperBound);
            if ($leftEndpoint > $rightEndpoint) {
                return [];
            }
            if ($leftEndpoint === -\INF) {
                $leftAnchor = $criticalPoints === []
                    ? (\in_array($hyperbolic->name, ['acosh', 'arccosh'], true)
                        ? $rightEndpoint - \max(1.0, \abs($rightEndpoint))
                        : -1.0)
                    : $criticalPoints[0] - \max(1.0, \abs($criticalPoints[0]));
                $leftEndpoint = $findTailEndpoint($leftAnchor, -1, $leftTailSign);
                if ($leftEndpoint === null) {
                    return null;
                }
            }
            if ($rightEndpoint === \INF) {
                $lastCritical = $criticalPoints === []
                    ? (\in_array($hyperbolic->name, ['acosh', 'arccosh'], true) ? $leftEndpoint : 0.0)
                    : $criticalPoints[\array_key_last($criticalPoints)];
                $rightAnchor = \max($leftEndpoint, $lastCritical)
                    + \max(1.0, \abs(\max($leftEndpoint, $lastCritical)));
                $rightEndpoint = $findTailEndpoint($rightAnchor, 1, $rightTailSign);
                if ($rightEndpoint === null) {
                    return null;
                }
            }
            if ($leftEndpoint > $rightEndpoint) {
                return [];
            }

            $points = [$leftEndpoint];
            foreach ($criticalPoints as $criticalPoint) {
                if ($criticalPoint > $leftEndpoint && $criticalPoint < $rightEndpoint) {
                    $points[] = $criticalPoint;
                }
            }
            $points[] = $rightEndpoint;
            $solutions = [];
            $acceptPoint = function (
                float $point,
                int $iterations,
                bool $refineNeighbors = true,
            ) use (
                &$solutions,
                $leftEndpoint,
                $rightEndpoint,
                $residualAt,
                $residualScaleAt,
                $solverOptions,
            ): ?float {
                $residual = $residualAt($point);
                if ($residual === null || !\is_finite($residual)) {
                    return null;
                }
                [$candidate, $candidateResidual] = $refineNeighbors
                    ? $this->bestRepresentableResidualCandidate(
                        $point,
                        $residual,
                        $leftEndpoint,
                        $rightEndpoint,
                        $residualAt,
                    )
                    : [$point, $residual];
                if (
                    $candidateResidual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate,
                        $candidateResidual,
                        $residualScaleAt,
                        $solverOptions,
                    )
                ) {
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($candidateResidual), $iterations),
                    );
                }

                return $residual;
            };
            $residuals = [];
            foreach ($points as $point) {
                $residuals[] = $acceptPoint(
                    $point,
                    0,
                    !\in_array($point, $criticalPoints, true),
                );
            }
            for ($index = 0, $last = \count($points) - 1; $index < $last; ++$index) {
                $leftResidual = $residuals[$index];
                $rightResidual = $residuals[$index + 1];
                if (
                    $leftResidual === null
                    || $rightResidual === null
                    || !$this->hasOppositeSigns($leftResidual, $rightResidual)
                ) {
                    continue;
                }
                [$root, $iterations] = $this->bisectMonotoneRoot(
                    static fn (float $value): float => $residualAt($value) ?? \NAN,
                    $points[$index],
                    $points[$index + 1],
                    $leftResidual < 0.0 ? -1 : 1,
                );
                $acceptPoint($root, $iterations);
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Isolate affine inverse-hyperbolic equations on their real domain branches.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAffineInverseFunctionEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$inverse, $target]) {
            $inverse = $this->unwrapGrouping($inverse);
            if (
                !$inverse instanceof FunctionCallNode
                || !\in_array($inverse->name, ['acoth', 'acsch', 'asech', 'asec', 'acsc'], true)
                || \count($inverse->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inverse->name)
            ) {
                continue;
            }
            $argument = $this->extractPolynomial(
                $extractor,
                $inverse->arguments[0],
                $inverse->arguments[0]->span()->start,
            );
            $targetCoefficients = $this->extractPolynomial($extractor, $target, $target->span()->start);
            if (
                $argument === null
                || $targetCoefficients === null
                || \count($argument) > 2
                || \count($targetCoefficients) > 2
            ) {
                continue;
            }
            $argumentIntercept = $argument[0] ?? 0.0;
            $argumentSlope = $argument[1] ?? 0.0;
            $targetIntercept = $targetCoefficients[0] ?? 0.0;
            $targetSlope = $targetCoefficients[1] ?? 0.0;
            if (
                !\is_finite($argumentIntercept)
                || !\is_finite($argumentSlope)
                || !\is_finite($targetIntercept)
                || !\is_finite($targetSlope)
                || $argumentSlope === 0.0
            ) {
                continue;
            }

            if (\in_array($inverse->name, ['acoth', 'asec', 'acsc'], true)) {
                $leftPole = (-1.0 - $argumentIntercept) / $argumentSlope;
                $rightPole = (1.0 - $argumentIntercept) / $argumentSlope;
                if (!\is_finite($leftPole) || !\is_finite($rightPole)) {
                    continue;
                }
                $domainBranches = $argumentSlope > 0.0
                    ? [[-\INF, $leftPole, -1], [$rightPole, \INF, 1]]
                    : [[-\INF, $rightPole, 1], [$leftPole, \INF, -1]];
            } elseif ($inverse->name === 'acsch') {
                $pole = -$argumentIntercept / $argumentSlope;
                if (!\is_finite($pole)) {
                    continue;
                }
                $domainBranches = $argumentSlope > 0.0
                    ? [[-\INF, $pole, -1], [$pole, \INF, 1]]
                    : [[-\INF, $pole, 1], [$pole, \INF, -1]];
            } else {
                $zeroPole = -$argumentIntercept / $argumentSlope;
                $unitPole = (1.0 - $argumentIntercept) / $argumentSlope;
                if (!\is_finite($zeroPole) || !\is_finite($unitPole)) {
                    continue;
                }
                $domainBranches = $argumentSlope > 0.0
                    ? [[$zeroPole, $unitPole, 1]]
                    : [[$unitPole, $zeroPole, 1]];
            }
            $isInDomainAt = static function (float $value) use (
                $inverse,
                $argumentSlope,
                $argumentIntercept,
            ): bool {
                $argumentValue = ($argumentSlope * $value) + $argumentIntercept;

                return match ($inverse->name) {
                    'acoth' => \abs($argumentValue) > 1.0,
                    'acsch' => $argumentValue !== 0.0,
                    'asec', 'acsc' => \abs($argumentValue) >= 1.0,
                    default => $argumentValue > 0.0 && $argumentValue <= 1.0,
                };
            };
            $isOpenBoundaryAt = static function (float $value) use (
                $inverse,
                $argumentSlope,
                $argumentIntercept,
            ): bool {
                if (\in_array($inverse->name, ['asec', 'acsc'], true)) {
                    return false;
                }
                if ($inverse->name === 'asech') {
                    return ($argumentSlope * $value + $argumentIntercept) === 0.0;
                }

                return true;
            };
            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $residualScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $inverseOnLeft = $inverse === $this->unwrapGrouping($left);
            $solutions = [];
            foreach ($domainBranches as [$branchLower, $branchUpper, $argumentSign]) {
                $openLower = \is_finite($branchLower);
                $openUpper = \is_finite($branchUpper);
                $intervalLower = \max($branchLower, $lowerBound);
                $intervalUpper = \min($branchUpper, $upperBound);
                if ($openLower && $isOpenBoundaryAt($branchLower) && $intervalLower === $branchLower) {
                    $intervalLower = $this->adjacentFloat($intervalLower, 1) ?? $intervalLower;
                    for (
                        $step = 0;
                        $step < 64 && !$isInDomainAt($intervalLower);
                        ++$step
                    ) {
                        $intervalLower = $this->adjacentFloat($intervalLower, 1) ?? $intervalLower;
                    }
                }
                if ($openUpper && $isOpenBoundaryAt($branchUpper) && $intervalUpper === $branchUpper) {
                    $intervalUpper = $this->adjacentFloat($intervalUpper, -1) ?? $intervalUpper;
                    for (
                        $step = 0;
                        $step < 64 && !$isInDomainAt($intervalUpper);
                        ++$step
                    ) {
                        $intervalUpper = $this->adjacentFloat($intervalUpper, -1) ?? $intervalUpper;
                    }
                }
                if (
                    $intervalLower > $intervalUpper
                    || (\is_finite($intervalLower) && !$isInDomainAt($intervalLower))
                    || (\is_finite($intervalUpper) && !$isInDomainAt($intervalUpper))
                ) {
                    continue;
                }

                $criticalPoints = [];
                if ($targetSlope !== 0.0 && $inverse->name === 'acoth') {
                    $argumentSquare = 1.0 - ($argumentSlope / $targetSlope);
                    if ($argumentSquare > 1.0 && \is_finite($argumentSquare)) {
                        $criticalArgument = \sqrt($argumentSquare);
                        $critical = ($argumentSign * $criticalArgument - $argumentIntercept) / $argumentSlope;
                        if (\is_finite($critical) && $critical > $intervalLower && $critical < $intervalUpper) {
                            $criticalPoints[] = $critical;
                        }
                    }
                } elseif ($targetSlope !== 0.0 && $inverse->name === 'acsch') {
                    $slopeRatio = -$argumentSlope / $targetSlope;
                    if ($slopeRatio > 0.0 && \is_finite($slopeRatio)) {
                        $criticalArgument = (\sqrt(2.0) * $slopeRatio)
                            / \sqrt(\hypot(1.0, 2.0 * $slopeRatio) + 1.0);
                        $critical = ($argumentSign * $criticalArgument - $argumentIntercept) / $argumentSlope;
                        if (\is_finite($critical) && $critical > $intervalLower && $critical < $intervalUpper) {
                            $criticalPoints[] = $critical;
                        }
                    }
                } elseif ($targetSlope !== 0.0 && $inverse->name === 'asech') {
                    $slopeRatio = -$argumentSlope / $targetSlope;
                    if ($slopeRatio > 0.0 && $slopeRatio <= 0.5) {
                        $discriminant = \sqrt((1.0 - 2.0 * $slopeRatio) * (1.0 + 2.0 * $slopeRatio));
                        $lowerCriticalArgument = (\sqrt(2.0) * $slopeRatio)
                            / \sqrt(1.0 + $discriminant);
                        $upperCriticalArgument = \sqrt((1.0 + $discriminant) / 2.0);
                        foreach ([$lowerCriticalArgument, $upperCriticalArgument] as $criticalArgument) {
                            $critical = ($criticalArgument - $argumentIntercept) / $argumentSlope;
                            if (\is_finite($critical) && $critical > $intervalLower && $critical < $intervalUpper) {
                                $criticalPoints[] = $critical;
                            }
                        }
                    }
                } elseif ($targetSlope !== 0.0) {
                    $slopeRatio = ($inverse->name === 'asec' ? $argumentSlope : -$argumentSlope)
                        / $targetSlope;
                    if ($slopeRatio > 0.0 && \is_finite($slopeRatio)) {
                        $criticalArgument = \sqrt((1.0 + \hypot(1.0, 2.0 * $slopeRatio)) / 2.0);
                        $critical = ($argumentSign * $criticalArgument - $argumentIntercept) / $argumentSlope;
                        if (\is_finite($critical) && $critical > $intervalLower && $critical < $intervalUpper) {
                            $criticalPoints[] = $critical;
                        }
                    }
                }
                \sort($criticalPoints, SORT_NUMERIC);
                $criticalPoints = \array_values(\array_unique($criticalPoints, SORT_REGULAR));

                $leftExpectedSign = $targetSlope > 0.0
                    ? 1
                    : ($targetSlope < 0.0
                        ? -1
                        : $this->inverseFunctionTailSign($inverse->name, $targetIntercept, $argumentSign));
                $rightExpectedSign = $targetSlope > 0.0
                    ? -1
                    : ($targetSlope < 0.0
                        ? 1
                        : $this->inverseFunctionTailSign($inverse->name, $targetIntercept, $argumentSign));
                if (!$inverseOnLeft) {
                    $leftExpectedSign *= -1;
                    $rightExpectedSign *= -1;
                }
                $findTailEndpoint = static function (
                    float $initial,
                    int $direction,
                    int $expectedSign,
                ) use ($residualAt): ?float {
                    $point = $initial;
                    $step = \max(1.0, \abs($point));
                    for ($iteration = 0; $iteration < 128; ++$iteration) {
                        $residual = $residualAt($point);
                        if ($residual === null || !\is_finite($residual)) {
                            return null;
                        }
                        if (($expectedSign < 0 && $residual < 0.0) || ($expectedSign > 0 && $residual > 0.0)) {
                            return $point;
                        }
                        $next = $point + ($direction * $step);
                        if (!\is_finite($next) || $next === $point) {
                            return null;
                        }
                        $point = $next;
                        $step *= 2.0;
                        if (!\is_finite($step)) {
                            return null;
                        }
                    }

                    return null;
                };
                if ($intervalLower === -\INF) {
                    $anchor = $criticalPoints === []
                        ? $intervalUpper - \max(1.0, \abs($intervalUpper))
                        : $criticalPoints[0] - \max(1.0, \abs($criticalPoints[0]));
                    $intervalLower = $findTailEndpoint($anchor, -1, $leftExpectedSign) ?? \NAN;
                }
                if ($intervalUpper === \INF) {
                    $anchor = $criticalPoints === []
                        ? $intervalLower + \max(1.0, \abs($intervalLower))
                        : $criticalPoints[\array_key_last($criticalPoints)]
                            + \max(1.0, \abs($criticalPoints[\array_key_last($criticalPoints)]));
                    $intervalUpper = $findTailEndpoint($anchor, 1, $rightExpectedSign) ?? \NAN;
                }
                if (!\is_finite($intervalLower) || !\is_finite($intervalUpper) || $intervalLower > $intervalUpper) {
                    return null;
                }
                $criticalPoints = \array_values(\array_filter(
                    $criticalPoints,
                    static fn (float $point): bool => $point > $intervalLower && $point < $intervalUpper,
                ));
                $points = [$intervalLower, ...$criticalPoints, $intervalUpper];
                $acceptPoint = function (
                    float $point,
                    int $iterations,
                    bool $refineNeighbors = true,
                ) use (
                    &$solutions,
                    $intervalLower,
                    $intervalUpper,
                    $residualAt,
                    $residualScaleAt,
                    $solverOptions,
                ): ?float {
                    $residual = $residualAt($point);
                    if ($residual === null || !\is_finite($residual)) {
                        return null;
                    }
                    [$candidate, $candidateResidual] = $refineNeighbors
                        ? $this->bestRepresentableResidualCandidate(
                            $point,
                            $residual,
                            $intervalLower,
                            $intervalUpper,
                            $residualAt,
                        )
                        : [$point, $residual];
                    if (
                        $candidateResidual !== null
                        && $this->isResidualAcceptableAt(
                            $candidate,
                            $candidateResidual,
                            $residualScaleAt,
                            $solverOptions,
                        )
                    ) {
                        $this->addDistinctSolution(
                            $solutions,
                            new EquationSolution($candidate, \abs($candidateResidual), $iterations),
                        );
                    }

                    return $residual;
                };
                $residuals = [];
                foreach ($points as $point) {
                    $residuals[] = $acceptPoint(
                        $point,
                        0,
                        !\in_array($point, $criticalPoints, true),
                    );
                }
                for ($index = 0, $last = \count($points) - 1; $index < $last; ++$index) {
                    $leftResidual = $residuals[$index];
                    $rightResidual = $residuals[$index + 1];
                    if (
                        ($leftResidual !== null
                            && \in_array($points[$index], $criticalPoints, true)
                            && $this->isResidualAtNumericalZero(
                                $points[$index],
                                $leftResidual,
                                $residualScaleAt,
                            ))
                        || ($rightResidual !== null
                            && \in_array($points[$index + 1], $criticalPoints, true)
                            && $this->isResidualAtNumericalZero(
                                $points[$index + 1],
                                $rightResidual,
                                $residualScaleAt,
                            ))
                    ) {
                        continue;
                    }
                    if (
                        $leftResidual === null
                        || $rightResidual === null
                        || !$this->hasOppositeSigns($leftResidual, $rightResidual)
                    ) {
                        continue;
                    }
                    [$root, $iterations] = $this->bisectMonotoneRoot(
                        static fn (float $value): float => $residualAt($value) ?? \NAN,
                        $points[$index],
                        $points[$index + 1],
                        $leftResidual < 0.0 ? -1 : 1,
                    );
                    $acceptPoint($root, $iterations);
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value,
            );

            return $solutions;
        }

        return null;
    }

    private function inverseFunctionTailSign(string $function, float $target, int $argumentSign): int
    {
        $limit = $function === 'asec' ? (\M_PI / 2.0) : 0.0;
        if ($target !== $limit) {
            return $limit > $target ? 1 : -1;
        }

        return $function === 'asec' ? -$argumentSign : $argumentSign;
    }

    private function onePlusOrMinusVariableSign(Node $node, string $variable): ?int
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $left = $this->unwrapGrouping($node->left);
        $right = $this->unwrapGrouping($node->right);
        if (
            $node->operator === BinaryOperator::Add
            && $left instanceof NumberNode
            && $left->value == 1
            && $right instanceof VariableNode
            && $right->name === $variable
        ) {
            return 1;
        }
        if (
            $node->operator === BinaryOperator::Add
            && $right instanceof NumberNode
            && $right->value == 1
            && $left instanceof VariableNode
            && $left->name === $variable
        ) {
            return 1;
        }
        if (
            $node->operator === BinaryOperator::Subtract
            && $left instanceof NumberNode
            && $left->value == 1
            && $right instanceof VariableNode
            && $right->name === $variable
        ) {
            return -1;
        }

        return null;
    }

    private function isHyperbolicInverseCompositionIdentity(
        Node $left,
        Node $right,
        string $variable,
        EvaluationOptions $evaluationOptions,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        SolverOptions $solverOptions,
    ): ?bool {
        if ($lowerBound >= $upperBound) {
            return false;
        }
        $inverseToBase = [
            'asinh' => 'sinh',
            'arcsinh' => 'sinh',
            'acosh' => 'cosh',
            'arccosh' => 'cosh',
            'atanh' => 'tanh',
            'arctanh' => 'tanh',
            'acsch' => 'csch',
            'acoth' => 'coth',
        ];
        foreach ([[$left, $right], [$right, $left]] as [$composition, $target]) {
            $composition = $this->unwrapGrouping($composition);
            if (
                !$composition instanceof FunctionCallNode
                || !isset($inverseToBase[$composition->name])
                || \count($composition->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($composition->name)
                || !$this->containsVariable($target, $variable)
            ) {
                continue;
            }
            $base = $this->unwrapGrouping($composition->arguments[0]);
            if (
                $base instanceof FunctionCallNode
                && $base->name === $inverseToBase[$composition->name]
                && \count($base->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn($base->name)
            ) {
                $argument = $base->arguments[0];
                if (
                    \in_array($composition->name, ['acsch', 'acoth'], true)
                    && $this->sameExpression($argument, $target)
                ) {
                    $coefficients = $this->extractPolynomial(
                        new PolynomialExtractor(
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions->maxPolynomialDegree,
                        ),
                        $argument,
                        $argument->span()->start,
                    );
                    if (
                        $coefficients !== null
                        && \count(\array_filter(
                            $coefficients,
                            static fn (float $coefficient): bool => $coefficient !== 0.0,
                        )) > 0
                    ) {
                        return true;
                    }
                    continue;
                }
                if (
                    $composition->name !== 'acosh'
                    && $composition->name !== 'arccosh'
                    && $this->sameExpression($argument, $target)
                ) {
                    return true;
                }
                if (
                    ($composition->name === 'acosh' || $composition->name === 'arccosh')
                    && $this->isAbsoluteValueOf($target, $argument)
                ) {
                    return true;
                }
                if ($composition->name !== 'acosh' && $composition->name !== 'arccosh') {
                    continue;
                }
                $positiveBranch = $this->sameExpression($argument, $target);
                $negativeBranch = $target instanceof UnaryOperationNode
                    && $target->operator === UnaryOperator::Minus
                    && $this->sameExpression($target->operand, $argument);
                if ($positiveBranch || $negativeBranch) {
                    $coefficients = $this->extractPolynomial(
                        new PolynomialExtractor(
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions->maxPolynomialDegree,
                        ),
                        $argument,
                        $argument->span()->start,
                    );
                    if ($coefficients !== null) {
                        $hasSignRegion = $this->polynomialExpressionHasPositiveWidthSignRegion(
                            $coefficients,
                            $argument,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lowerBound,
                            $upperBound,
                            $positiveBranch,
                            $solverOptions,
                        );
                        if ($hasSignRegion === null) {
                            return null;
                        }
                        if ($hasSignRegion) {
                            return true;
                        }
                    } else {
                        $hasRationalSignRegion = $this->rationalExpressionHasPositiveWidthSignRegion(
                            $argument,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lowerBound,
                            $upperBound,
                            $positiveBranch,
                            $solverOptions,
                        );
                        if ($hasRationalSignRegion === null) {
                            return null;
                        }
                        if ($hasRationalSignRegion) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    /** @param list<float> $coefficients */
    private function polynomialExpressionHasPositiveWidthSignRegion(
        array $coefficients,
        Node $expression,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        float $lowerBound,
        float $upperBound,
        bool $nonnegative,
        SolverOptions $solverOptions,
    ): ?bool {
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        $exactCoefficients = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->difference(
            $expression,
            new NumberNode(0, '0', $expression->span()),
        );
        if ($exactCoefficients === null) {
            return null;
        }
        while (
            \count($exactCoefficients) > 1
            && $exactCoefficients[\array_key_last($exactCoefficients)] === '0'
        ) {
            \array_pop($exactCoefficients);
        }
        $integerArithmetic = new IntegerPolynomialExtractor('', []);
        if (\count($exactCoefficients) !== \count($coefficients)) {
            return null;
        }
        if (\count($coefficients) === 1) {
            if (\count($exactCoefficients) === 1 && $exactCoefficients[0] === '0') {
                return true;
            }
            return $this->polynomialHasRequestedSign(
                $exactCoefficients,
                0.0,
                $nonnegative,
                $integerArithmetic,
            );
        }
        if (\count($coefficients) > 2) {
            $polynomialSolver = new PolynomialSolver();
            $derivative = [];
            foreach ($coefficients as $degree => $coefficient) {
                if ($degree > 0) {
                    $derivative[] = $degree * $coefficient;
                }
            }
            while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                \array_pop($derivative);
            }
            $criticalPoints = $polynomialSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($derivative, $value),
                $solverOptions,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($derivative, $value),
            );
            if ($criticalPoints === null) {
                return null;
            }

            $criticalValues = \array_map(
                static fn (EquationSolution $criticalPoint): float => $criticalPoint->value,
                $criticalPoints,
            );
            \sort($criticalValues, SORT_NUMERIC);
            $partitionPoints = $criticalValues;
            if (\is_finite($lowerBound)) {
                $partitionPoints[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $partitionPoints[] = $upperBound;
            }
            \sort($partitionPoints, SORT_NUMERIC);
            $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
            $uncertainSign = false;
            foreach ($partitionPoints as $point) {
                $hasRequestedSign = $this->polynomialHasRequestedSign(
                    $exactCoefficients,
                    $point,
                    $nonnegative,
                    $integerArithmetic,
                );
                if ($hasRequestedSign === true) {
                    return true;
                }
                $uncertainSign = $uncertainSign || $hasRequestedSign === null;
            }
            $left = $lowerBound;
            foreach ($partitionPoints as $point) {
                $sample = $this->sampleInsideInterval($left, $point);
                if ($sample !== null) {
                    $hasRequestedSign = $this->polynomialHasRequestedSign(
                        $exactCoefficients,
                        $sample,
                        $nonnegative,
                        $integerArithmetic,
                    );
                    if ($hasRequestedSign === true) {
                        return true;
                    }
                    $uncertainSign = $uncertainSign || $hasRequestedSign === null;
                }
                $left = $point;
            }
            $sample = $this->sampleInsideInterval($left, $upperBound);
            if ($sample !== null) {
                $hasRequestedSign = $this->polynomialHasRequestedSign(
                    $exactCoefficients,
                    $sample,
                    $nonnegative,
                    $integerArithmetic,
                );
                if ($hasRequestedSign === true) {
                    return true;
                }
                $uncertainSign = $uncertainSign || $hasRequestedSign === null;
            }
            if ($lowerBound === -\INF) {
                $degree = \count($coefficients) - 1;
                $leadingCoefficient = $coefficients[\array_key_last($coefficients)];
                $leftTailIsPositive = $degree % 2 === 0
                    ? $leadingCoefficient > 0.0
                    : $leadingCoefficient < 0.0;
                if ($nonnegative === $leftTailIsPositive) {
                    return true;
                }
            }
            if ($upperBound === \INF) {
                $rightTailIsPositive = $coefficients[\array_key_last($coefficients)] > 0.0;
                if ($nonnegative === $rightTailIsPositive) {
                    return true;
                }
            }

            return $uncertainSign ? null : false;
        }

        $root = -$coefficients[0] / $coefficients[1];
        if (!\is_finite($root)) {
            $rootIsPositiveInfinity = $root > 0.0;
            $positiveRegionIsUnbounded = $rootIsPositiveInfinity
                ? $coefficients[1] < 0.0
                : $coefficients[1] > 0.0;
            return $nonnegative === $positiveRegionIsUnbounded && $upperBound > $lowerBound;
        }
        if ($nonnegative) {
            return $coefficients[1] > 0.0
                ? $upperBound > \max($lowerBound, $root)
                : $lowerBound < \min($upperBound, $root);
        }

        return $coefficients[1] > 0.0
            ? $lowerBound < \min($upperBound, $root)
            : $upperBound > \max($lowerBound, $root);
    }

    private function sampleInsideInterval(float $lowerBound, float $upperBound): ?float
    {
        if ($lowerBound < $upperBound) {
            if ($lowerBound === -\INF) {
                return \is_finite($upperBound)
                    ? $upperBound - \max(1.0, \abs($upperBound))
                    : 0.0;
            }
            if ($upperBound === \INF) {
                return $lowerBound + \max(1.0, \abs($lowerBound));
            }

            return ($lowerBound / 2.0) + ($upperBound / 2.0);
        }

        return null;
    }

    /**
     * @param list<string> $coefficients
     */
    private function polynomialHasRequestedSign(
        array $coefficients,
        float $value,
        bool $nonnegative,
        IntegerPolynomialExtractor $integerArithmetic,
    ): ?bool {
        $sign = $this->integerPolynomialSignAtFloat($coefficients, $value, $integerArithmetic);
        if ($sign === null) {
            return null;
        }
        if ($sign === 0) {
            return false;
        }

        return $nonnegative === ($sign > 0);
    }

    /**
     * @param list<string> $coefficients
     */
    private function integerPolynomialSignAtFloat(
        array $coefficients,
        float $value,
        IntegerPolynomialExtractor $integerArithmetic,
    ): ?int {
        $point = RationalLiteral::fromFloatAsStrings($value);
        if ($point === null || $coefficients === []) {
            return null;
        }
        [$numerator, $denominator] = $point;
        $accumulator = $coefficients[\array_key_last($coefficients)];
        $denominatorPower = $denominator;
        for ($degree = \count($coefficients) - 2; $degree >= 0; --$degree) {
            $accumulator = $integerArithmetic->addIntegerValues(
                $integerArithmetic->multiplyIntegerValues($accumulator, $numerator),
                $integerArithmetic->multiplyIntegerValues($coefficients[$degree], $denominatorPower),
            );
            $denominatorPower = $integerArithmetic->multiplyIntegerValues(
                $denominatorPower,
                $denominator,
            );
        }
        return $integerArithmetic->sign($accumulator);
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function rationalExpressionHasPositiveWidthSignRegion(
        Node $expression,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        float $lowerBound,
        float $upperBound,
        bool $nonnegative,
        SolverOptions $solverOptions,
    ): ?bool {
        $form = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->rationalDifference(
            $expression,
            new NumberNode(0, '0', $expression->span()),
        );
        if ($form === null) {
            return null;
        }
        [$numerator, $denominator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === '0') {
            \array_pop($denominator);
        }
        if (\count($denominator) === 1 && $denominator[0] === '0') {
            return null;
        }
        if (\count($numerator) === 1 && $numerator[0] === '0') {
            return true;
        }
        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if ($lowerBound === -\INF || $upperBound === \INF) {
            $rootBound = 1.0;
            foreach ([$numerator, $denominator] as $polynomial) {
                if (\count($polynomial) < 2) {
                    continue;
                }
                $leadingCoefficient = (float) $polynomial[\array_key_last($polynomial)];
                if (!\is_finite($leadingCoefficient) || $leadingCoefficient === 0.0) {
                    return null;
                }
                foreach (\array_slice($polynomial, 0, -1) as $coefficient) {
                    $ratio = \abs((float) $coefficient / $leadingCoefficient);
                    if (!\is_finite($ratio)) {
                        return null;
                    }
                    $rootBound = \max($rootBound, 1.0 + $ratio);
                }
            }
            $rootBound *= 2.0;
            if (!\is_finite($rootBound)) {
                return null;
            }
            $searchLowerBound = \max($lowerBound, -$rootBound);
            $searchUpperBound = \min($upperBound, $rootBound);
        }

        $formatPolynomial = static function (array $polynomial) use ($variable): string {
            $terms = [];
            foreach ($polynomial as $degree => $coefficient) {
                if ($coefficient === '0') {
                    continue;
                }
                $term = '(' . $coefficient . ')';
                if ($degree > 0) {
                    $term .= '*' . $variable;
                    if ($degree > 1) {
                        $term .= '^' . $degree;
                    }
                }
                $terms[] = $term;
            }

            return \implode('+', $terms);
        };
        $rootIntervals = [];
        foreach ([$numerator, $denominator] as $polynomial) {
            if (\count($polynomial) < 2 || $searchLowerBound >= $searchUpperBound) {
                continue;
            }
            $rootEquation = $formatPolynomial($polynomial) . '=0';
            if (\strlen($rootEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $isolated = (new PolynomialRootCountingSolver())->isolate(
                $rootEquation,
                $variable,
                $searchLowerBound,
                $searchUpperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                256,
                '1/1000000000000',
            );
            if ($isolated === null) {
                return null;
            }
            \array_push($rootIntervals, ...$isolated);
        }
        $integerArithmetic = new IntegerPolynomialExtractor('', []);
        $rootCounter = new ExactPolynomialRootCounter();
        $compareFractions = static fn (array $first, array $second): int =>
            $integerArithmetic->compareIntegerValues(
                $integerArithmetic->multiplyIntegerValues($first[0], $second[1]),
                $integerArithmetic->multiplyIntegerValues($second[0], $first[1]),
            );
        \usort(
            $rootIntervals,
            static fn (RationalRootInterval $first, RationalRootInterval $second): int =>
                $compareFractions(
                    [$first->lowerNumerator, $first->lowerDenominator],
                    [$second->lowerNumerator, $second->lowerDenominator],
                ),
        );
        $barriers = [];
        $commonPolynomial = null;
        $commonPolynomialComputed = false;
        foreach ($rootIntervals as $rootInterval) {
            $barrierLower = (float) $rootInterval->lowerNumerator / (float) $rootInterval->lowerDenominator;
            $barrierUpper = (float) $rootInterval->upperNumerator / (float) $rootInterval->upperDenominator;
            if (!\is_finite($barrierLower) || !\is_finite($barrierUpper)) {
                return null;
            }
            $lowerFraction = [$rootInterval->lowerNumerator, $rootInterval->lowerDenominator];
            $upperFraction = [$rootInterval->upperNumerator, $rootInterval->upperDenominator];
            $lastBarrier = $barriers[\array_key_last($barriers)] ?? null;
            if ($lastBarrier !== null) {
                $lowerToLastUpper = $compareFractions($lowerFraction, $lastBarrier['upperFraction']);
                if ($lowerToLastUpper < 0) {
                    if (
                        $lowerFraction === $lastBarrier['lowerFraction']
                        && $upperFraction === $lastBarrier['upperFraction']
                    ) {
                        continue;
                    }
                    if (!$commonPolynomialComputed) {
                        $commonPolynomial = $rootCounter->greatestCommonDivisor($numerator, $denominator);
                        $commonPolynomialComputed = true;
                    }
                    if ($commonPolynomial === null) {
                        return null;
                    }

                    $lastRootLowerFraction = [
                        $lastBarrier['rootInterval']->lowerNumerator,
                        $lastBarrier['rootInterval']->lowerDenominator,
                    ];
                    $lastRootUpperFraction = [
                        $lastBarrier['rootInterval']->upperNumerator,
                        $lastBarrier['rootInterval']->upperDenominator,
                    ];
                    $intersectionLower = $compareFractions(
                        $lowerFraction,
                        $lastRootLowerFraction,
                    ) >= 0
                        ? $lowerFraction
                        : $lastRootLowerFraction;
                    $intersectionUpper = $compareFractions(
                        $upperFraction,
                        $lastRootUpperFraction,
                    ) <= 0
                        ? $upperFraction
                        : $lastRootUpperFraction;
                    $intersectionOrder = $compareFractions($intersectionLower, $intersectionUpper);
                    if ($intersectionOrder > 0) {
                        return null;
                    }
                    if ($intersectionOrder === 0) {
                        $sharedRoot = $rootCounter->isRootAt($commonPolynomial, $intersectionLower);
                    } else {
                        $commonRootCount = $rootCounter->countOpenInterval(
                            $commonPolynomial,
                            $intersectionLower[0],
                            $intersectionLower[1],
                            $intersectionUpper[0],
                            $intersectionUpper[1],
                        );
                        if ($commonRootCount === null) {
                            return null;
                        }
                        $sharedRoot = $commonRootCount > 0
                            || $rootCounter->isRootAt($commonPolynomial, $intersectionLower) === true
                            || $rootCounter->isRootAt($commonPolynomial, $intersectionUpper) === true;
                    }
                    if ($sharedRoot !== true) {
                        return null;
                    }
                    $barriers[\array_key_last($barriers)]['upper'] = \max(
                        $lastBarrier['upper'],
                        $barrierUpper,
                    );
                    if ($compareFractions($upperFraction, $lastBarrier['upperFraction']) > 0) {
                        $barriers[\array_key_last($barriers)]['upperFraction'] = $upperFraction;
                    }
                    $barriers[\array_key_last($barriers)]['rootInterval'] = $rootInterval;

                    continue;
                }
                if ($barrierLower === $lastBarrier['upper'] && $lowerToLastUpper !== 0) {
                    return null;
                }
            }
            $barriers[] = [
                'lower' => $barrierLower,
                'upper' => $barrierUpper,
                'lowerFraction' => $lowerFraction,
                'upperFraction' => $upperFraction,
                'rootInterval' => $rootInterval,
            ];
        }

        $intervals = [];
        $cursor = $lowerBound;
        foreach ($barriers as $barrier) {
            $barrierLower = $barrier['lower'];
            $barrierUpper = $barrier['upper'];
            if ($barrierLower > $cursor) {
                $intervals[] = [$cursor, $barrierLower];
            }
            $cursor = \max($cursor, $barrierUpper);
        }
        if ($cursor < $upperBound) {
            $intervals[] = [$cursor, $upperBound];
        }
        foreach ($intervals as [$intervalLower, $intervalUpper]) {
            $sample = $this->sampleInsideInterval($intervalLower, $intervalUpper);
            if ($sample === null) {
                continue;
            }
            $numeratorSign = $this->integerPolynomialSignAtFloat($numerator, $sample, $integerArithmetic);
            $denominatorSign = $this->integerPolynomialSignAtFloat($denominator, $sample, $integerArithmetic);
            if ($numeratorSign === null || $denominatorSign === null || $denominatorSign === 0) {
                return null;
            }
            $sign = $numeratorSign * $denominatorSign;
            if ($sign !== 0 && $nonnegative === ($sign > 0)) {
                return true;
            }
        }

        return false;
    }

    private function isAbsoluteValueOf(Node $node, Node $argument): bool
    {
        $node = $this->unwrapGrouping($node);
        return $node instanceof FunctionCallNode
            && $node->name === 'abs'
            && \count($node->arguments) === 1
            && $this->sameExpression($node->arguments[0], $argument);
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveAcoshCoshBoundaryEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$composition, $target]) {
            $composition = $this->unwrapGrouping($composition);
            if (
                !$composition instanceof FunctionCallNode
                || !\in_array($composition->name, ['acosh', 'arccosh'], true)
                || \count($composition->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($composition->name)
            ) {
                continue;
            }
            $base = $this->unwrapGrouping($composition->arguments[0]);
            if (
                $base instanceof FunctionCallNode
                && $base->name === 'cosh'
                && \count($base->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn($base->name)
            ) {
                $argument = $base->arguments[0];
                $matchesArgument = $this->sameExpression($target, $argument);
                $matchesNegativeArgument = $target instanceof UnaryOperationNode
                    && $target->operator === UnaryOperator::Minus
                    && $this->sameExpression($target->operand, $argument);
                $absoluteTarget = $this->unwrapGrouping($target);
                $matchesAbsoluteArgument = $absoluteTarget instanceof FunctionCallNode
                    && $absoluteTarget->name === 'abs'
                    && \count($absoluteTarget->arguments) === 1
                    && $this->sameExpression($absoluteTarget->arguments[0], $argument)
                    && $evaluationOptions->functions->isBuiltIn($absoluteTarget->name);
                if ($matchesAbsoluteArgument) {
                    if ($lowerBound < $upperBound) {
                        throw new InfiniteSolutionSetException(
                            'acosh(cosh(g(x))) equals abs(g(x)) throughout the real domain.',
                        );
                    }
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $lowerBound,
                        $parameters,
                        $evaluationOptions,
                    );

                    return $residual === null
                        ? []
                        : [new EquationSolution($lowerBound, \abs($residual), 0)];
                }
                if (!$matchesArgument && !$matchesNegativeArgument) {
                    continue;
                }
                $coefficients = $this->extractPolynomial(
                    new PolynomialExtractor(
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions->maxPolynomialDegree,
                    ),
                    $argument,
                    $argument->span()->start,
                );
                if ($coefficients === null) {
                    return $this->solveAcoshCoshRationalBoundaryEquation(
                        $left,
                        $right,
                        $rightOffset,
                        $argument,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                }
                $exactCoefficients = (new ExactRationalPolynomialExtractor(
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    $evaluationOptions,
                ))->difference(
                    $argument,
                    new NumberNode(0, '0', $argument->span()),
                );
                if ($exactCoefficients === null) {
                    return null;
                }
                while (
                    \count($coefficients) > 1
                    && $coefficients[\array_key_last($coefficients)] === 0.0
                ) {
                    \array_pop($coefficients);
                }
                if (\count($coefficients) === 1) {
                    return [];
                }
                while (
                    \count($exactCoefficients) > 1
                    && $exactCoefficients[\array_key_last($exactCoefficients)] === '0'
                ) {
                    \array_pop($exactCoefficients);
                }
                if (\count($exactCoefficients) !== \count($coefficients)) {
                    return null;
                }

                $searchLowerBound = $lowerBound;
                $searchUpperBound = $upperBound;
                if ($lowerBound === -\INF || $upperBound === \INF) {
                    $leadingCoefficient = $coefficients[\array_key_last($coefficients)];
                    $rootBound = 1.0;
                    foreach (\array_slice($coefficients, 0, -1) as $coefficient) {
                        $ratio = \abs($coefficient / $leadingCoefficient);
                        if (!\is_finite($ratio)) {
                            return null;
                        }
                        $rootBound = \max($rootBound, 1.0 + $ratio);
                    }
                    $rootBound *= 2.0;
                    if (!\is_finite($rootBound)) {
                        return null;
                    }
                    $searchLowerBound = \max($lowerBound, -$rootBound);
                    $searchUpperBound = \min($upperBound, $rootBound);
                    if ($searchLowerBound > $searchUpperBound) {
                        return [];
                    }
                }

                $terms = [];
                foreach ($exactCoefficients as $degree => $coefficient) {
                    if ($coefficient === '0') {
                        continue;
                    }
                    $term = '(' . $coefficient . ')';
                    if ($degree > 0) {
                        $term .= '*' . $variable;
                        if ($degree > 1) {
                            $term .= '^' . $degree;
                        }
                    }
                    $terms[] = $term;
                }
                $polynomialEquation = \implode('+', $terms) . '=0';
                if (\strlen($polynomialEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $rootIntervals = (new PolynomialRootCountingSolver())->isolate(
                    $polynomialEquation,
                    $variable,
                    $searchLowerBound,
                    $searchUpperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    256,
                    '1/1000000000000',
                );
                if ($rootIntervals === null) {
                    return null;
                }

                $solutions = [];
                foreach ($rootIntervals as $rootInterval) {
                    $rootLower = (float) $rootInterval->lowerNumerator / (float) $rootInterval->lowerDenominator;
                    $rootUpper = (float) $rootInterval->upperNumerator / (float) $rootInterval->upperDenominator;
                    $rootValue = $rootInterval->isExactRoot
                        ? $rootLower
                        : ($rootLower / 2.0) + ($rootUpper / 2.0);
                    $rootValue = $this->refineRootCandidateByFloatSearch(
                        $argument,
                        $rootValue,
                        $variable,
                        $searchLowerBound,
                        $searchUpperBound,
                        $parameters,
                        $evaluationOptions,
                    );
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $rootValue,
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($residual === null || !\is_finite($residual)) {
                        return null;
                    }
                    $solutions[] = new EquationSolution($rootValue, \abs($residual), 0);
                }

                $solutions = $this->includeClosedIntervalEndpointRoots(
                    $solutions,
                    $searchLowerBound,
                    $searchUpperBound,
                    $exactCoefficients,
                );

                $verifiedSolutions = [];
                foreach ($solutions as $solution) {
                    $residual = $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    $residualScale = $this->residualScaleAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $solution->value,
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $residual === null
                        || !\is_finite($residual)
                        || $residualScale === null
                        || !\is_finite($residualScale)
                        || !$this->isResidualAcceptableAt(
                            $solution->value,
                            $residual,
                            static fn (float $value): float => \max(1.0, $residualScale),
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $verifiedSolutions[] = new EquationSolution(
                        $solution->value,
                        \abs($residual),
                        $solution->iterations,
                    );
                }

                return $verifiedSolutions;
            }
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveAcoshCoshRationalBoundaryEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        Node $argument,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $form = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->rationalDifference(
            $argument,
            new NumberNode(0, '0', $argument->span()),
        );
        if ($form === null) {
            return null;
        }
        [$numerator, $denominator] = $form;
        foreach ([0, 1] as $index) {
            while (
                \count($form[$index]) > 1
                && $form[$index][\array_key_last($form[$index])] === '0'
            ) {
                \array_pop($form[$index]);
            }
        }
        [$numerator, $denominator] = $form;
        if (\count($denominator) === 1 && $denominator[0] === '0') {
            throw new \InvalidArgumentException('The rational expression is undefined for every real input.');
        }
        if (\count($numerator) === 1 && $numerator[0] === '0') {
            throw new InfiniteSolutionSetException(
                'The inverse hyperbolic composition is an identity throughout its defined rational domain.',
            );
        }

        $leadingCoefficient = (float) $numerator[\array_key_last($numerator)];
        if (!\is_finite($leadingCoefficient) || $leadingCoefficient === 0.0) {
            return null;
        }
        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if ($lowerBound === -\INF || $upperBound === \INF) {
            $rootBound = 1.0;
            foreach (\array_slice($numerator, 0, -1) as $coefficient) {
                $ratio = \abs((float) $coefficient / $leadingCoefficient);
                if (!\is_finite($ratio)) {
                    return null;
                }
                $rootBound = \max($rootBound, 1.0 + $ratio);
            }
            $rootBound *= 2.0;
            if (!\is_finite($rootBound)) {
                return null;
            }
            $searchLowerBound = \max($lowerBound, -$rootBound);
            $searchUpperBound = \min($upperBound, $rootBound);
            if ($searchLowerBound >= $searchUpperBound) {
                return [];
            }
        }

        $formatPolynomial = static function (array $polynomial) use ($variable): string {
            $terms = [];
            foreach ($polynomial as $degree => $coefficient) {
                if ($coefficient === '0') {
                    continue;
                }
                $term = '(' . $coefficient . ')';
                if ($degree > 0) {
                    $term .= '*' . $variable;
                    if ($degree > 1) {
                        $term .= '^' . $degree;
                    }
                }
                $terms[] = $term;
            }

            return \implode('+', $terms);
        };
        $rootEquation = '(' . $formatPolynomial($numerator) . ')/('
            . $formatPolynomial($denominator)
            . ')=0';
        if (\strlen($rootEquation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        $rootIntervals = (new PolynomialRootCountingSolver())->isolate(
            $rootEquation,
            $variable,
            $searchLowerBound,
            $searchUpperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            256,
            '1/1000000000000',
        );
        if ($rootIntervals === null) {
            return null;
        }

        $solutions = [];
        foreach ($rootIntervals as $rootInterval) {
            $rootLower = (float) $rootInterval->lowerNumerator / (float) $rootInterval->lowerDenominator;
            $rootUpper = (float) $rootInterval->upperNumerator / (float) $rootInterval->upperDenominator;
            $rootValue = $rootInterval->isExactRoot
                ? $rootLower
                : ($rootLower / 2.0) + ($rootUpper / 2.0);
            $rootValue = $this->refineRootCandidateByFloatSearch(
                $argument,
                $rootValue,
                $variable,
                $searchLowerBound,
                $searchUpperBound,
                $parameters,
                $evaluationOptions,
            );
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $rootValue,
                $parameters,
                $evaluationOptions,
            );
            if ($residual === null || !\is_finite($residual)) {
                return null;
            }
            $residualScale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $rootValue,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residualScale !== null
                && \is_finite($residualScale)
                && $this->isResidualAcceptableAt(
                    $rootValue,
                    $residual,
                    static fn (float $value): float => \max(1.0, $residualScale),
                    $solverOptions,
                )
            ) {
                $solutions[] = new EquationSolution($rootValue, \abs($residual), 0);
            }
        }

        $rootCounter = new ExactPolynomialRootCounter();
        foreach ([$searchLowerBound, $searchUpperBound] as $endpoint) {
            $fraction = RationalLiteral::fromFloatAsStrings($endpoint);
            if (
                $fraction === null
                || $rootCounter->isRootAt($numerator, $fraction) !== true
                || $rootCounter->isRootAt($denominator, $fraction) === true
            ) {
                continue;
            }
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $endpoint,
                $parameters,
                $evaluationOptions,
            );
            if ($residual === null || !\is_finite($residual)) {
                return null;
            }
            $residualScale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $endpoint,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residualScale !== null
                && \is_finite($residualScale)
                && $this->isResidualAcceptableAt(
                    $endpoint,
                    $residual,
                    static fn (float $value): float => \max(1.0, $residualScale),
                    $solverOptions,
                )
            ) {
                $solutions[] = new EquationSolution($endpoint, \abs($residual), 0);
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /** @param array<string, int|float> $parameters
     *  @return list<EquationSolution>|null
     */
    private function solveRationalPrincipalInverseCompositionEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $branches = [
            'asin:sin' => [-\M_PI_2, \M_PI_2, true, true],
            'arcsin:sin' => [-\M_PI_2, \M_PI_2, true, true],
            'acos:cos' => [0.0, \M_PI, true, true],
            'arccos:cos' => [0.0, \M_PI, true, true],
            'atan:tan' => [-\M_PI_2, \M_PI_2, false, false],
            'arctan:tan' => [-\M_PI_2, \M_PI_2, false, false],
            'asec:sec' => [0.0, \M_PI, true, true],
            'acsc:csc' => [-\M_PI_2, \M_PI_2, true, true],
            'acot:cot' => [0.0, \M_PI, false, false],
        ];
        foreach (
            [[$left, $right, $rightSource], [$right, $left, $leftSource]]
            as [$composition, $target, $targetSource]
        ) {
            $composition = $this->unwrapGrouping($composition);
            $target = $this->unwrapGrouping($target);
            if (
                !$composition instanceof FunctionCallNode
                || \count($composition->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($composition->name)
            ) {
                continue;
            }
            $inner = $this->unwrapGrouping($composition->arguments[0]);
            if (
                !$inner instanceof FunctionCallNode
                || \count($inner->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inner->name)
            ) {
                continue;
            }
            $branch = $branches[$composition->name . ':' . $inner->name] ?? null;
            if (
                $branch === null
                || !$this->sameExpression($inner->arguments[0], $target)
                || !$this->containsVariable($target, $variable)
            ) {
                continue;
            }
            $rationalForm = (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalFunction($target);
            if ($rationalForm === null) {
                return $this->solveBoundedNonRationalPrincipalInverseComposition(
                    $left,
                    $right,
                    $targetSource,
                    $rightOffset,
                    $target,
                    $composition->name,
                    $branch,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }
            $toFloatCoefficients = static function (array $fractions): ?array {
                $coefficients = [];
                foreach ($fractions as [$numerator, $denominator]) {
                    $numeratorValue = (float) $numerator;
                    $denominatorValue = (float) $denominator;
                    if (!\is_finite($numeratorValue) || !\is_finite($denominatorValue) || $denominatorValue === 0.0) {
                        return null;
                    }
                    $coefficient = $numeratorValue / $denominatorValue;
                    if (!\is_finite($coefficient)) {
                        return null;
                    }
                    $coefficients[] = $coefficient;
                }

                return $coefficients;
            };
            [$numeratorFractions, $denominatorFractions] = $rationalForm;
            $numerator = $toFloatCoefficients($numeratorFractions);
            $denominator = $toFloatCoefficients($denominatorFractions);
            if ($numerator === null || $denominator === null) {
                return null;
            }
            while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === 0.0) {
                \array_pop($numerator);
            }
            while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === 0.0) {
                \array_pop($denominator);
            }
            [$branchLower, $branchUpper, $includesBranchLower, $includesBranchUpper] = $branch;
            if (\count($denominator) === 1 && $denominator[0] === 0.0) {
                return null;
            }
            if (\count($numerator) === 1 && \count($denominator) === 1) {
                $value = $numerator[0] / $denominator[0];
                $inBranch = ($value > $branchLower || ($includesBranchLower && $value === $branchLower))
                    && ($value < $branchUpper || ($includesBranchUpper && $value === $branchUpper))
                    && !(($composition->name === 'asec' && $value === \M_PI_2)
                        || ($composition->name === 'acsc' && $value === 0.0));
                if (!$inBranch) {
                    return [];
                }
                throw new InfiniteSolutionSetException(
                    'Inverse and forward trigonometric functions agree on the rational-function principal branch.',
                );
            }
            $partitionPoints = [$lowerBound, $upperBound];
            if (\count($denominator) > 1) {
                $denominatorRoots = $this->solvePolynomialRootsInInterval(
                    $denominator,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($denominatorRoots === null) {
                    return null;
                }
                foreach ($denominatorRoots as $root) {
                    $partitionPoints[] = $root->value;
                }
            }
            $boundaryRoots = [];
            foreach ([$branchLower, $branchUpper] as $level) {
                $levelPolynomial = [];
                $coefficientCount = \max(\count($numerator), \count($denominator));
                for ($degree = 0; $degree < $coefficientCount; ++$degree) {
                    $levelPolynomial[] = ($numerator[$degree] ?? 0.0)
                        - ($level * ($denominator[$degree] ?? 0.0));
                }
                $roots = $this->solvePolynomialRootsInInterval(
                    $levelPolynomial,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    $partitionPoints[] = $root->value;
                    if (
                        ($level === $branchLower && $includesBranchLower)
                        || ($level === $branchUpper && $includesBranchUpper)
                    ) {
                        $boundaryRoots[] = $root;
                    }
                }
            }
            \sort($partitionPoints, SORT_NUMERIC);
            $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
            for ($index = 1, $count = \count($partitionPoints); $index < $count; ++$index) {
                $cellLower = $partitionPoints[$index - 1];
                $cellUpper = $partitionPoints[$index];
                if ($cellLower >= $cellUpper) {
                    continue;
                }
                $probes = $this->interiorProbePositions($cellLower, $cellUpper);
                if ($probes === []) {
                    continue;
                }
                foreach ($probes as $probe) {
                    $numeratorValue = $this->polynomialValue($numerator, $probe);
                    $denominatorValue = $this->polynomialValue($denominator, $probe);
                    $value = $numeratorValue === null || $denominatorValue === null || $denominatorValue === 0.0
                        ? null
                        : $numeratorValue / $denominatorValue;
                    if (
                        $value !== null
                        && \is_finite($value)
                        && ($value > $branchLower || ($includesBranchLower && $value === $branchLower))
                        && ($value < $branchUpper || ($includesBranchUpper && $value === $branchUpper))
                        && !(($composition->name === 'asec' && $value === \M_PI_2)
                            || ($composition->name === 'acsc' && $value === 0.0))
                    ) {
                        throw new InfiniteSolutionSetException(
                            'Inverse and forward trigonometric functions agree on a nonempty rational branch interval.',
                        );
                    }
                }
            }
            $solutions = [];
            foreach ($boundaryRoots as $root) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $root->value,
                    $parameters,
                    $evaluationOptions,
                );
                $scale = $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $root->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $scale !== null
                    && $this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        static fn (float $value): float => $scale,
                        $solverOptions,
                    )
                ) {
                    $solutions[] = new EquationSolution($root->value, \abs($residual), $root->iterations);
                }
            }

            return $this->deduplicateSortedEquationSolutions($solutions, $solverOptions);
        }

        return null;
    }

    /** @param array{float, float, bool, bool} $branch
     *  @param array<string, int|float> $parameters
     *  @return list<EquationSolution>|null
     */
    private function solveBoundedNonRationalPrincipalInverseComposition(
        Node $left,
        Node $right,
        string $targetSource,
        int $rightOffset,
        Node $target,
        string $inverse,
        array $branch,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        [$branchLower, $branchUpper, $includesBranchLower, $includesBranchUpper] = $branch;
        $targetDomainIntervals = null;
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            if ($target instanceof FunctionCallNode) {
                $argumentSources = [];
                foreach ($target->arguments as $argument) {
                    $span = $argument->span();
                    $argumentSources[] = \substr(
                        $targetSource,
                        $span->start,
                        $span->length(),
                    );
                }
                if (
                    $argumentSources !== []
                    && !\in_array('', $argumentSources, true)
                ) {
                    $targetDomainIntervals = $this->functionArgumentDomainIntervals(
                        $target->name,
                        $argumentSources[0],
                        $argumentSources[1] ?? null,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    if ($targetDomainIntervals !== null && $targetDomainIntervals === []) {
                        return [];
                    }
                }
            }
        }
        $range = $this->evaluateIntervalExpression(
            $target,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($range !== null && (
            $range[1] < $branchLower
            || $range[0] > $branchUpper
            || ($range[1] === $branchLower && !$includesBranchLower)
            || ($range[0] === $branchUpper && !$includesBranchUpper)
            || ($inverse === 'asec' && $range[0] === \M_PI_2 && $range[1] === \M_PI_2)
            || ($inverse === 'acsc' && $range[0] === 0.0 && $range[1] === 0.0)
        )) {
            return [];
        }

        $domainSingletonSolutions = [];
        $hasPositiveWidthDomainInterval = false;
        $domainProbes = [];
        foreach ($targetDomainIntervals ?? [] as $interval) {
            if ($interval->lowerBound < $interval->upperBound) {
                $hasPositiveWidthDomainInterval = true;
                \array_push(
                    $domainProbes,
                    ...$this->interiorProbePositions($interval->lowerBound, $interval->upperBound),
                );
                continue;
            }
            if (!$interval->includesLowerBound || !$interval->includesUpperBound) {
                continue;
            }
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $interval->lowerBound,
                $parameters,
                $evaluationOptions,
            );
            $scale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $interval->lowerBound,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residual !== null
                && $scale !== null
                && $this->isResidualAcceptableAt(
                    $interval->lowerBound,
                    $residual,
                    static fn (float $value): float => $scale,
                    $solverOptions,
                )
            ) {
                $domainSingletonSolutions[] = new EquationSolution(
                    $interval->lowerBound,
                    \abs($residual),
                    0,
                );
            }
        }
        if ($targetDomainIntervals !== null && !$hasPositiveWidthDomainInterval) {
            return $this->deduplicateSortedEquationSolutions($domainSingletonSolutions, $solverOptions);
        }

        $probes = $this->interiorProbePositions($lowerBound, $upperBound);
        \array_push($probes, ...$domainProbes);
        $probes = \array_values(\array_unique($probes, SORT_REGULAR));
        if ($probes === []) {
            return null;
        }
        foreach ($probes as $probe) {
            if (!$this->isLocallyContinuous($target, $probe, $evaluationOptions, $parameters, $variable)) {
                continue;
            }
            try {
                $value = (float) $this->evaluateNode(
                    $target,
                    [...$parameters, $variable => $probe],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            if (
                !\is_finite($value)
                || $value <= $branchLower
                || $value >= $branchUpper
                || ($inverse === 'asec' && $value === \M_PI_2)
                || ($inverse === 'acsc' && $value === 0.0)
            ) {
                continue;
            }

            throw new InfiniteSolutionSetException(
                'Inverse and forward trigonometric functions agree on a nonempty continuous branch interval.',
            );
        }

        if (
            $range !== null
            &&
            $range[0] === $range[1]
            && ($range[0] > $branchLower || ($includesBranchLower && $range[0] === $branchLower))
            && ($range[1] < $branchUpper || ($includesBranchUpper && $range[1] === $branchUpper))
        ) {
            $probe = $probes[0];
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $probe,
                $parameters,
                $evaluationOptions,
            );
            if ($residual !== null && \abs($residual) <= $solverOptions->residualTolerance) {
                throw new InfiniteSolutionSetException(
                    'The constant principal-branch composition has infinitely many solutions.',
                );
            }

            return [];
        }

        return null;
    }

    private function isPrincipalInverseCompositionIdentity(
        Node $left,
        Node $right,
        string $variable,
        EvaluationOptions $evaluationOptions,
        float $lowerBound,
        float $upperBound,
    ): bool {
        $ranges = [
            'asin:sin' => [-\M_PI_2, \M_PI_2],
            'arcsin:sin' => [-\M_PI_2, \M_PI_2],
            'acos:cos' => [0.0, \M_PI],
            'arccos:cos' => [0.0, \M_PI],
            'atan:tan' => [-\M_PI_2, \M_PI_2],
            'arctan:tan' => [-\M_PI_2, \M_PI_2],
            'asec:sec' => [0.0, \M_PI],
            'acsc:csc' => [-\M_PI_2, \M_PI_2],
            'acot:cot' => [0.0, \M_PI],
        ];
        foreach ([[$left, $right], [$right, $left]] as [$composition, $target]) {
            $composition = $this->unwrapGrouping($composition);
            $target = $this->unwrapGrouping($target);
            if (
                !$composition instanceof FunctionCallNode
                || \count($composition->arguments) !== 1
                || !$target instanceof VariableNode
                || $target->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn($composition->name)
            ) {
                continue;
            }
            $inner = $this->unwrapGrouping($composition->arguments[0]);
            if (
                !$inner instanceof FunctionCallNode
                || \count($inner->arguments) !== 1
                || !$this->sameExpression($inner->arguments[0], $target)
            ) {
                continue;
            }
            $key = $composition->name . ':' . $inner->name;
            if (!isset($ranges[$key]) || !$evaluationOptions->functions->isBuiltIn($inner->name)) {
                continue;
            }
            [$branchLower, $branchUpper] = $ranges[$key];
            $overlapLower = \max($lowerBound, $branchLower);
            $overlapUpper = \min($upperBound, $branchUpper);
            if ($overlapLower < $overlapUpper) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function hasRootInCommonAffineTangentPeriod(
        string $equation,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        Node $left,
        Node $right,
    ): ?bool {
        $phases = [];
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            while ($side instanceof UnaryOperationNode) {
                $side = $this->unwrapGrouping($side->operand);
            }
            if (
                !$side instanceof FunctionCallNode
                || $side->name !== 'tan'
                || \count($side->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('tan')
            ) {
                return null;
            }
            $phase = $this->extractPolynomial(
                $extractor,
                $side->arguments[0],
                $side->arguments[0]->span()->start,
            );
            if ($phase === null || \count($phase) !== 2 || $phase[1] === 0.0) {
                return null;
            }
            $phases[] = $phase;
        }

        $referenceSlope = \abs($phases[0][1]);
        $ratio = $this->rationalHarmonicOrders(
            \abs($phases[1][1]) / $referenceSlope,
            $solverOptions->maxPolynomialDegree,
        );
        if ($ratio === null) {
            return null;
        }
        $fundamentalSlope = $referenceSlope / $ratio[1];
        $period = (2.0 * \M_PI) / $fundamentalSlope;
        if (!\is_finite($period) || $period <= 0.0) {
            return null;
        }

        try {
            return $this->solve(
                $equation,
                $variable,
                0.0,
                $period,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            ) !== [];
        } catch (\InvalidArgumentException) {
            return null;
        }
    }

    private function hasRootInCommonAffineTrigonometricPeriod(
        string $equation,
        string $variable,
        int $rightOffset,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        Node $left,
        Node $right,
    ): ?bool {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $leftForm = $this->flattenAffineTrigonometricTerms($left, $extractor, true);
        $rightForm = $this->flattenAffineTrigonometricTerms($right, $extractor, true);
        if ($leftForm === null || $rightForm === null) {
            return null;
        }
        $terms = [
            ...$leftForm['terms'],
            ...$this->scaledTrigonometricTerms($rightForm['terms'], -1.0),
        ];
        if ($terms === []) {
            return null;
        }

        $arguments = [];
        foreach ($terms as $term) {
            $argument = $this->extractPolynomial(
                $extractor,
                $term['call']->arguments[0],
                $term['call']->arguments[0]->span()->start,
            );
            if ($argument === null || \count($argument) !== 2 || $argument[1] === 0.0) {
                return null;
            }
            $arguments[] = $argument;
        }

        $referenceSlope = \abs($arguments[0][1]);
        $commonDenominator = 1;
        $ratios = [];
        foreach ($arguments as $argument) {
            $ratio = $this->rationalHarmonicOrders(
                \abs($argument[1]) / $referenceSlope,
                $solverOptions->maxPolynomialDegree,
            );
            if ($ratio === null) {
                return null;
            }
            $ratios[] = $ratio;
            $gcdLeft = $commonDenominator;
            $gcdRight = $ratio[1];
            while ($gcdRight !== 0) {
                [$gcdLeft, $gcdRight] = [$gcdRight, $gcdLeft % $gcdRight];
            }
            $commonDenominator = intdiv($commonDenominator, $gcdLeft) * $ratio[1];
            if ($commonDenominator > 1024) {
                return null;
            }
        }

        $orders = [];
        $orderGcd = 0;
        foreach ($ratios as [$numerator, $denominator]) {
            $order = $numerator * intdiv($commonDenominator, $denominator);
            $orders[] = $order;
            $gcdLeft = $orderGcd;
            $gcdRight = $order;
            while ($gcdRight !== 0) {
                [$gcdLeft, $gcdRight] = [$gcdRight, $gcdLeft % $gcdRight];
            }
            $orderGcd = $gcdLeft;
        }
        if ($orderGcd < 1) {
            return null;
        }
        $fundamentalSlope = $referenceSlope / intdiv($commonDenominator, $orderGcd);
        $period = (2.0 * \M_PI) / $fundamentalSlope;
        if (!\is_finite($period) || $period <= 0.0) {
            return null;
        }

        try {
            $candidates = $this->solve(
                $equation,
                $variable,
                0.0,
                $period,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($candidates as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                $scale = $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $scale !== null
                    && \is_finite($residual)
                    && \abs($residual)
                        <= \max(1.0E-10, $solverOptions->residualTolerance) * \max(1.0, $scale)
                ) {
                    return true;
                }
            }

            return false;
        } catch (\InvalidArgumentException) {
            return null;
        }
    }

    private function hasRationalPhaseRatio(
        float $value,
        Node $quotientPhase,
        Node $functionPhase,
        bool $isSincPi,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxDegree,
    ): bool {
        $ratioNode = new NumberNode(
            $value,
            \sprintf('%.17g', $value),
            $quotientPhase->span(),
        );
        $scaledPhase = $functionPhase;
        if ($isSincPi) {
            $pi = new NumberNode(\M_PI, \sprintf('%.17g', \M_PI), $functionPhase->span());
            $scaledPhase = new BinaryOperationNode(
                BinaryOperator::Multiply,
                $pi,
                $functionPhase,
                $functionPhase->span(),
            );
        }
        $expectedQuotientPhase = new BinaryOperationNode(
            BinaryOperator::Multiply,
            $ratioNode,
            $scaledPhase,
            $functionPhase->span(),
        );
        $exactDifference = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxDegree,
            $evaluationOptions,
        ))->rationalDifference($quotientPhase, $expectedQuotientPhase);
        if ($exactDifference !== null && $exactDifference[0] === ['0']) {
            return true;
        }

        $fraction = RationalLiteral::fromFloatAsStrings($value);
        if ($fraction !== null && (int) $fraction[1] <= 100_000_000_000_000) {
            return true;
        }

        if (\abs($value) > 1_000_000.0) {
            return false;
        }

        $remainder = \abs($value);
        $previousNumerator = 0;
        $numerator = 1;
        $previousDenominator = 1;
        $denominator = 0;
        for ($iteration = 0; $iteration < 32; ++$iteration) {
            $integerPart = (int) \floor($remainder);
            $nextNumerator = ($integerPart * $numerator) + $previousNumerator;
            $nextDenominator = ($integerPart * $denominator) + $previousDenominator;
            if ($nextDenominator > 1_000_000) {
                break;
            }
            if (
                \abs($value - ($nextNumerator / $nextDenominator))
                <= 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($value))
            ) {
                return true;
            }
            $previousNumerator = $numerator;
            $numerator = $nextNumerator;
            $previousDenominator = $denominator;
            $denominator = $nextDenominator;
            $fractionalPart = $remainder - $integerPart;
            if ($fractionalPart === 0.0) {
                break;
            }
            $remainder = 1.0 / $fractionalPart;
        }

        return false;
    }

    /** @param array{list<float>, list<float>} $phaseForm */
    private function rationalPhaseHasPoleInInterval(
        array $phaseForm,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): bool {
        if (\count($phaseForm[1]) < 2) {
            return false;
        }

        $polynomialSolver = new PolynomialSolver();
        $roots = $polynomialSolver->solve(
            $phaseForm[1],
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $phaseForm[1],
                $value,
            ),
            $options,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                $phaseForm[1],
                $value,
            ),
        );
        if ($roots === null) {
            return false;
        }

        foreach ($roots as $root) {
            if (
                $this->polynomialRootMultiplicity($phaseForm[1], $root->value)
                > $this->polynomialRootMultiplicity($phaseForm[0], $root->value)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Reduce hypot(sin(x), cos(x))=x using the exact unit-circle identity.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveTrigonometricHypotenuseFixedPoint(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$hypotenuse, $target]) {
            $hypotenuse = $this->unwrapGrouping($hypotenuse);
            $target = $this->unwrapGrouping($target);
            if (
                !$hypotenuse instanceof FunctionCallNode
                || $hypotenuse->name !== 'hypot'
                || \count($hypotenuse->arguments) !== 2
                || !$target instanceof VariableNode
                || $target->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn('hypot')
            ) {
                continue;
            }
            $first = $this->unwrapGrouping($hypotenuse->arguments[0]);
            $second = $this->unwrapGrouping($hypotenuse->arguments[1]);
            $validPair = false;
            foreach ([[$first, $second], [$second, $first]] as [$sine, $cosine]) {
                if (
                    $sine instanceof FunctionCallNode
                    && $sine->name === 'sin'
                    && \count($sine->arguments) === 1
                    && $sine->arguments[0] instanceof VariableNode
                    && $sine->arguments[0]->name === $variable
                    && $cosine instanceof FunctionCallNode
                    && $cosine->name === 'cos'
                    && \count($cosine->arguments) === 1
                    && $cosine->arguments[0] instanceof VariableNode
                    && $cosine->arguments[0]->name === $variable
                ) {
                    $validPair = true;
                    break;
                }
            }
            if (!$validPair) {
                continue;
            }
            if (1.0 < $lowerBound || 1.0 > $upperBound) {
                return [];
            }
            $residual = $this->residualAt(
                $left,
                $right,
                0,
                $variable,
                1.0,
                $parameters,
                $evaluationOptions,
            );

            return $residual !== null
                && $this->isResidualAcceptableAt(
                    1.0,
                    $residual,
                    fn (float $value): ?float => $this->residualScaleAt(
                        $left,
                        $right,
                        0,
                        $variable,
                        $value,
                        $parameters,
                        $evaluationOptions,
                    ),
                    $solverOptions,
                )
                ? [new EquationSolution(1.0, \abs($residual), 0)]
                : [];
        }

        return null;
    }

    /**
     * Solve quadrant-II atan2 fixed points after converting them to tangent equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAtan2BoundedCoordinates(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        foreach (
            [[$left, $right, $leftSource], [$right, $left, $rightSource]]
            as [$functionNode, $target, $source]
        ) {
            $functionNode = $this->unwrapGrouping($functionNode);
            $target = $this->unwrapGrouping($target);
            if (
                !$functionNode instanceof FunctionCallNode
                || $functionNode->name !== 'atan2'
                || \count($functionNode->arguments) !== 2
                || !$target instanceof VariableNode
                || $target->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn('atan2')
            ) {
                continue;
            }
            $yRange = $this->boundedTrigonometricExpressionRange(
                $functionNode->arguments[0],
                $parameters,
                $evaluationOptions,
            );
            $xRange = $this->boundedTrigonometricExpressionRange(
                $functionNode->arguments[1],
                $parameters,
                $evaluationOptions,
            );
            if (
                $yRange === null
                || $xRange === null
                || $yRange[0] < 0.0
                || $xRange[1] >= 0.0
            ) {
                continue;
            }
            $angleLower = \atan2($yRange[1], $xRange[1]);
            $angleUpper = \atan2($yRange[0], $xRange[0]);
            $solveLower = \max($lowerBound, $angleLower);
            $solveUpper = \min($upperBound, $angleUpper);
            if ($solveLower > $solveUpper) {
                return [];
            }
            $ySpan = $functionNode->arguments[0]->span();
            $xSpan = $functionNode->arguments[1]->span();
            $ySource = \substr($source, $ySpan->start, $ySpan->end - $ySpan->start);
            $xSource = \substr($source, $xSpan->start, $xSpan->end - $xSpan->start);
            if ($ySource === '' || $xSource === '') {
                return null;
            }
            $candidates = $this->solve(
                'tan(' . $variable . ')=(' . $ySource . ')/(' . $xSource . ')',
                $variable,
                $solveLower,
                $solveUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    0,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        fn (float $value): ?float => $this->residualScaleAt(
                            $left,
                            $right,
                            0,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                        $solverOptions,
                    )
                ) {
                    $solutions[] = new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    );
                }
            }

            return $solutions;
        }

        return null;
    }

    /**
     * Reduce sinc fixed points to bounded sine-polynomial equations.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedSincFixedPoint(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$sinc, $target]) {
            $sinc = $this->unwrapGrouping($sinc);
            $target = $this->unwrapGrouping($target);
            if (
                !$sinc instanceof FunctionCallNode
                || !\in_array($sinc->name, ['sinc', 'sincpi'], true)
                || \count($sinc->arguments) !== 1
                || !$sinc->arguments[0] instanceof VariableNode
                || $sinc->arguments[0]->name !== $variable
                || !$target instanceof VariableNode
                || $target->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn($sinc->name)
            ) {
                continue;
            }
            $scale = $sinc->name === 'sinc' ? 1.0 : \M_PI;
            $radius = 1.0 / \sqrt($scale);
            $solveLower = \max($lowerBound, -$radius);
            $solveUpper = \min($upperBound, $radius);
            if ($solveLower > $solveUpper) {
                return [];
            }
            $argument = $sinc->name === 'sinc'
                ? $variable
                : '(pi*' . $variable . ')';
            $equation = 'sin(' . $argument . ')=('
                . \sprintf('%.17g', $scale) . '*(' . $variable . '^2))';
            $candidates = $this->solve(
                $equation,
                $variable,
                $solveLower,
                $solveUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    0,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        fn (float $value): ?float => $this->residualScaleAt(
                            $left,
                            $right,
                            0,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                        $solverOptions,
                    )
                ) {
                    $solutions[] = new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    );
                }
            }

            return $solutions;
        }

        return null;
    }

    /**
     * Solve tan(sin(x))=x on its bounded feasible interval by sign brackets.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveTangentSineFixedPoints(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $matches = false;
        foreach ([[$left, $right], [$right, $left]] as [$tangent, $target]) {
            $tangent = $this->unwrapGrouping($tangent);
            $target = $this->unwrapGrouping($target);
            if (
                $tangent instanceof FunctionCallNode
                && $tangent->name === 'tan'
                && \count($tangent->arguments) === 1
                && $target instanceof VariableNode
                && $target->name === $variable
            ) {
                $sine = $this->unwrapGrouping($tangent->arguments[0]);
                if (
                    $sine instanceof FunctionCallNode
                    && $sine->name === 'sin'
                    && \count($sine->arguments) === 1
                    && $sine->arguments[0] instanceof VariableNode
                    && $sine->arguments[0]->name === $variable
                    && $evaluationOptions->functions->isBuiltIn('tan')
                    && $evaluationOptions->functions->isBuiltIn('sin')
                ) {
                    $matches = true;
                    break;
                }
            }
        }
        if (!$matches) {
            return null;
        }

        $domainLower = \max($lowerBound, -\tan(1.0));
        $domainUpper = \min($upperBound, \tan(1.0));
        if ($domainLower > $domainUpper) {
            return [];
        }
        $residualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            0,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $scaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            0,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $segments = 4096;
        $solutions = [];
        $previousPosition = $domainLower;
        $previousResidual = $residualAt($previousPosition);
        if ($previousResidual !== null && $this->isResidualAcceptableAt($previousPosition, $previousResidual, $scaleAt, $solverOptions)) {
            $solutions[] = new EquationSolution($previousPosition, \abs($previousResidual), 0);
        }
        for ($index = 1; $index <= $segments; ++$index) {
            $position = $index === $segments
                ? $domainUpper
                : $domainLower + (($domainUpper - $domainLower) * ($index / $segments));
            $residual = $residualAt($position);
            if ($residual !== null) {
                if ($this->isResidualAcceptableAt($position, $residual, $scaleAt, $solverOptions)) {
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($position, \abs($residual), 0),
                    );
                } elseif (
                    $previousResidual !== null
                    && $this->hasOppositeSigns($previousResidual, $residual)
                ) {
                    foreach ($this->bisect(
                        $residualAt,
                        $previousPosition,
                        $previousResidual,
                        $position,
                        $solverOptions,
                        $scaleAt,
                        static fn (float $_): bool => false,
                    ) as $root) {
                        $this->addDistinctSolution($solutions, $root);
                    }
                }
                $previousPosition = $position;
                $previousResidual = $residual;
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce sqrt(sin(x)^2)=x/2 on its proven feasible domain [0, 2].
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedSquareRootTrigonometricLinearTarget(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $matched = false;
        foreach ([[$left, $right], [$right, $left]] as [$radical, $target]) {
            $radical = $this->unwrapGrouping($radical);
            if (
                !$radical instanceof FunctionCallNode
                || $radical->name !== 'sqrt'
                || \count($radical->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('sqrt')
            ) {
                continue;
            }
            $square = $this->unwrapGrouping($radical->arguments[0]);
            if (
                !$square instanceof BinaryOperationNode
                || $square->operator !== BinaryOperator::Power
                || $this->constantNodeValue($square->right, $parameters, $evaluationOptions) !== 2.0
            ) {
                continue;
            }
            $sine = $this->unwrapGrouping($square->left);
            if (
                !$sine instanceof FunctionCallNode
                || $sine->name !== 'sin'
                || \count($sine->arguments) !== 1
                || !$sine->arguments[0] instanceof VariableNode
                || $sine->arguments[0]->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn('sin')
            ) {
                continue;
            }
            $coefficients = $extractor->extract($target);
            while (
                $coefficients !== null
                && \count($coefficients) > 1
                && $coefficients[\array_key_last($coefficients)] === 0.0
            ) {
                \array_pop($coefficients);
            }
            if ($coefficients !== [0.0, 0.5]) {
                continue;
            }
            $matched = true;
            break;
        }
        if (!$matched) {
            return null;
        }

        $solveLower = \max($lowerBound, 0.0);
        $solveUpper = \min($upperBound, 2.0);
        if ($solveLower > $solveUpper) {
            return [];
        }
        $candidates = $this->solve(
            'sin(' . $variable . ')=(' . $variable . ')/2',
            $variable,
            $solveLower,
            $solveUpper,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $this->residualAt(
                $left,
                $right,
                0,
                $variable,
                $candidate->value,
                $parameters,
                $evaluationOptions,
            );
            if ($residual !== null) {
                $solutions[] = new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                );
            }
        }

        return $solutions;
    }

    /**
     * Certify the unique triple contact in exp(x)=2+sin(x)-cos(x).
     *
     * The right-hand side has range [2-sqrt(2), 2+sqrt(2)], restricting x
     * to an interval where sin(x+pi/4)>0. The third derivative of the
     * residual is therefore strictly positive, while its first three
     * Taylor data through degree two vanish at zero.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveExponentialSinusoidalCubicContact(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$exponential, $target]) {
            $exponential = $this->unwrapGrouping($exponential);
            if (
                !$exponential instanceof FunctionCallNode
                || $exponential->name !== 'exp'
                || \count($exponential->arguments) !== 1
                || !$exponential->arguments[0] instanceof VariableNode
                || $exponential->arguments[0]->name !== $variable
                || !$evaluationOptions->functions->isBuiltIn('exp')
            ) {
                continue;
            }

            $constant = 0.0;
            $sineCoefficient = 0.0;
            $cosineCoefficient = 0.0;
            $valid = true;
            foreach ($this->additiveTerms($target) as [$term, $sign]) {
                $term = $this->unwrapGrouping($term);
                if (
                    $term instanceof FunctionCallNode
                    && \in_array($term->name, ['sin', 'cos'], true)
                    && \count($term->arguments) === 1
                    && $term->arguments[0] instanceof VariableNode
                    && $term->arguments[0]->name === $variable
                    && $evaluationOptions->functions->isBuiltIn($term->name)
                ) {
                    if ($term->name === 'sin') {
                        $sineCoefficient += (float) $sign;
                    } else {
                        $cosineCoefficient += (float) $sign;
                    }
                    continue;
                }
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                if ($value === null || !\is_finite($value)) {
                    $valid = false;
                    break;
                }
                $constant += $sign * $value;
            }
            if (
                !$valid
                || $constant !== 2.0
                || $sineCoefficient !== 1.0
                || $cosineCoefficient !== -1.0
            ) {
                continue;
            }

            return $lowerBound <= 0.0 && $upperBound >= 0.0
                ? [new EquationSolution(0.0, 0.0, 0)]
                : [];
        }

        return null;
    }

    /**
     * Isolate the double root and the finite positive root of log1p(x)=sin(x).
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedLog1pSineIdentity(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $forms = [[$left, $right], [$right, $left]];
        $matches = false;
        foreach ($forms as [$logarithm, $sine]) {
            $directLogSine =
                !$logarithm instanceof FunctionCallNode
                ? false
                : $logarithm->name === 'log1p'
                    && \count($logarithm->arguments) === 1
                    && $logarithm->arguments[0] instanceof VariableNode
                    && $logarithm->arguments[0]->name === $variable
                    && $sine instanceof FunctionCallNode
                    && $sine->name === 'sin'
                    && \count($sine->arguments) === 1
                    && $sine->arguments[0] instanceof VariableNode
                    && $sine->arguments[0]->name === $variable
                    && $evaluationOptions->functions->isBuiltIn($logarithm->name)
                    && $evaluationOptions->functions->isBuiltIn($sine->name);
            $expm1Sine = $logarithm instanceof FunctionCallNode
                && $logarithm->name === 'expm1'
                && \count($logarithm->arguments) === 1
                && ($innerSine = $this->unwrapGrouping($logarithm->arguments[0])) instanceof FunctionCallNode
                && $innerSine->name === 'sin'
                && \count($innerSine->arguments) === 1
                && $innerSine->arguments[0] instanceof VariableNode
                && $innerSine->arguments[0]->name === $variable
                && $sine instanceof VariableNode
                && $sine->name === $variable
                && $evaluationOptions->functions->isBuiltIn('expm1')
                && $evaluationOptions->functions->isBuiltIn('sin');
            if (!$directLogSine && !$expm1Sine) {
                continue;
            }
            $matches = true;
            break;
        }
        if (!$matches) {
            return null;
        }

        // On (-1, 0), ln(1+x) < x < sin(x), so there are no negative roots.
        // On (0, 0.01], ln(1+x) <= x - x^2/(2(1+x)) < x - x^3/6 <= sin(x).
        // Also sin(x) <= 1 confines every nonnegative root to x <= e - 1.
        $solutions = [];
        if ($lowerBound <= 0.0 && $upperBound >= 0.0) {
            $solutions[] = new EquationSolution(0.0, 0.0, 0);
        }
        $positiveLower = \max($lowerBound, 0.01);
        $positiveUpper = \min($upperBound, \M_E - 1.0);
        if ($positiveLower <= $positiveUpper) {
            $candidates = $this->solve(
                'log1p(' . $variable . ')=sin(' . $variable . ')',
                $variable,
                $positiveLower,
                $positiveUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($candidates as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    0,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        fn (float $value): ?float => $this->residualScaleAt(
                            $left,
                            $right,
                            0,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                        $solverOptions,
                    )
                ) {
                    $solutions[] = new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce inverse-function self-equations whose real roots follow from exact ranges.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedInverseTrigonometricIdentity(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && \in_array(
                $left->name,
                ['asin', 'arcsin', 'acos', 'arccos', 'asinh', 'arcsinh', 'atanh', 'arctanh', 'sinh', 'atan2'],
                true,
            )
        ) {
            $function = $left;
            $target = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array(
                $right->name,
                ['asin', 'arcsin', 'acos', 'arccos', 'asinh', 'arcsinh', 'atanh', 'arctanh', 'sinh', 'atan2'],
                true,
            )
        ) {
            $function = $right;
            $target = $left;
        } else {
            return null;
        }

        $replacement = null;
        $onlyZeroRoot = false;
        $solveLower = $lowerBound;
        $solveUpper = $upperBound;
        if (
            $function instanceof FunctionCallNode
            && \in_array($function->name, ['acos', 'arccos'], true)
            && \count($function->arguments) === 1
            && ($sineArgument = $this->unwrapGrouping($function->arguments[0])) instanceof FunctionCallNode
            && $sineArgument->name === 'sin'
            && \count($sineArgument->arguments) === 1
            && $sineArgument->arguments[0] instanceof VariableNode
            && $sineArgument->arguments[0]->name === $variable
            && $target instanceof VariableNode
            && $target->name === $variable
            && $evaluationOptions->functions->isBuiltIn($function->name)
            && $evaluationOptions->functions->isBuiltIn('sin')
        ) {
            $replacement = 'cos(' . $variable . ')=sin(' . $variable . ')';
            $solveLower = \max($solveLower, 0.0);
            $solveUpper = \min($solveUpper, \M_PI);
        } elseif (
            $function instanceof FunctionCallNode
            && \in_array(
                $function->name,
                ['asin', 'arcsin', 'asinh', 'arcsinh', 'atanh', 'arctanh', 'sinh'],
                true,
            )
            && \count($function->arguments) === 1
            && $function->arguments[0] instanceof VariableNode
            && $function->arguments[0]->name === $variable
            && $target instanceof FunctionCallNode
            && $target->name === 'sin'
            && \count($target->arguments) === 1
            && $target->arguments[0] instanceof VariableNode
            && $target->arguments[0]->name === $variable
            && $evaluationOptions->functions->isBuiltIn($function->name)
            && $evaluationOptions->functions->isBuiltIn($target->name)
        ) {
            $onlyZeroRoot = true;
        } elseif (
            $function instanceof FunctionCallNode
            && \in_array($function->name, ['acos', 'arccos'], true)
            && \count($function->arguments) === 1
            && $function->arguments[0] instanceof VariableNode
            && $function->arguments[0]->name === $variable
            && $target instanceof VariableNode
            && $target->name === $variable
            && $evaluationOptions->functions->isBuiltIn($function->name)
        ) {
            $replacement = 'cos(' . $variable . ')=' . $variable;
            $solveLower = \max($solveLower, 0.0);
            $solveUpper = \min($solveUpper, 1.0);
        } elseif (
            $function instanceof FunctionCallNode
            && $function->name === 'atan2'
            && \count($function->arguments) === 2
            && $function->arguments[0] instanceof VariableNode
            && $function->arguments[0]->name === $variable
            && $target instanceof VariableNode
            && $target->name === $variable
            && $this->constantNodeValue(
                $function->arguments[1],
                $parameters,
                $evaluationOptions,
            ) === 1.0
            && $evaluationOptions->functions->isBuiltIn($function->name)
        ) {
            $replacement = 'atan(' . $variable . ')=' . $variable;
        } else {
            return null;
        }

        if ($solveLower > $solveUpper) {
            return [];
        }
        $candidates = $onlyZeroRoot
            ? ($lowerBound <= 0.0 && $upperBound >= 0.0
                ? [new EquationSolution(0.0, 0.0, 0)]
                : [])
            : $this->solve(
                $replacement,
                $variable,
                $solveLower,
                $solveUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $this->residualAt(
                $left,
                $right,
                0,
                $variable,
                $candidate->value,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    fn (float $value): ?float => $this->residualScaleAt(
                        $left,
                        $right,
                        0,
                        $variable,
                        $value,
                        $parameters,
                        $evaluationOptions,
                    ),
                    $solverOptions,
                )
            ) {
                continue;
            }
            $solutions[] = new EquationSolution(
                $candidate->value,
                \abs($residual),
                $candidate->iterations,
            );
        }

        return $solutions;
    }

    /**
     * Reduce unbounded equations when a bounded trig range confines polynomial targets.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedTrigonometricRangeEquation(
        string $equation,
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );

        foreach ([[$left, $right], [$right, $left]] as [$trigonometricSide, $targetSide]) {
            $trigonometricSide = $this->unwrapGrouping($trigonometricSide);
            if (
                !$trigonometricSide instanceof FunctionCallNode
                || !\in_array($trigonometricSide->name, ['sin', 'cos'], true)
                || !$evaluationOptions->functions->isBuiltIn($trigonometricSide->name)
                || \count($trigonometricSide->arguments) !== 1
            ) {
                continue;
            }
            $phase = $extractor->extract($trigonometricSide->arguments[0]);
            if (
                $phase === null
                || \count($phase) < 2
            ) {
                continue;
            }

            if ($this->isEverywhereWithinUnitInterval($targetSide, $variable, $parameters, $evaluationOptions)) {
                throw new InfiniteSolutionSetException(
                    'A nonconstant polynomial-phase sine or cosine intersects a globally unit-bounded '
                        . 'continuous expression infinitely many times.',
                );
            }
            foreach ([[$lowerBound, -1.0], [$upperBound, 1.0]] as [$bound, $direction]) {
                if (($direction < 0.0 && $bound !== -\INF) || ($direction > 0.0 && $bound !== \INF)) {
                    continue;
                }
                $limit = $this->continuousExpressionLimitAtInfinity(
                    $targetSide,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $limit !== null
                    && \is_finite($limit)
                    && \abs($limit) < 1.0 - (64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($limit)))
                ) {
                    throw new InfiniteSolutionSetException(
                        'A polynomial-phase sine or cosine intersects a continuous target whose limit '
                            . 'lies strictly inside its range on an unbounded tail.',
                    );
                }
            }
            if (
                $this->hasInfiniteRootsFromExponentialApproachToTrigonometricBoundary(
                    $targetSide,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'An exponentially approaching target crosses an attained trigonometric boundary '
                        . 'infinitely many times.',
                );
            }
        }

        foreach ([[$left, $right], [$right, $left]] as [$boundedSide, $targetSide]) {
            if (!$this->containsFunctionCall($boundedSide)) {
                continue;
            }
            $range = $this->boundedTrigonometricExpressionRange(
                $boundedSide,
                $parameters,
                $evaluationOptions,
            );
            $target = $this->constantNodeValue($targetSide, $parameters, $evaluationOptions);
            if (
                $range !== null
                && $target !== null
                && \is_finite($target)
                && ($target < $range[0] || $target > $range[1])
            ) {
                return [];
            }
        }

        $radicalSolutions = $this->solveUnboundedPolynomialBoundedFunctionEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $extractor,
        );
        if ($radicalSolutions !== null) {
            return $radicalSolutions;
        }

        foreach ([[$left, $right], [$right, $left]] as [$boundedSide, $polynomialSide]) {
            if (!$this->containsFunctionCall($boundedSide)) {
                continue;
            }
            $range = $this->boundedTrigonometricExpressionRange(
                $boundedSide,
                $parameters,
                $evaluationOptions,
            );
            $polynomial = $extractor->extract($polynomialSide);
            if (
                $range === null
                || $polynomial === null
                || \count($polynomial) < 2
            ) {
                continue;
            }

            $boundedSolutions = $this->solveUnboundedTrigonometricPolynomialTarget(
                $equation,
                $polynomial,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $range[0],
                $range[1],
            );
            if ($boundedSolutions !== null) {
                return $boundedSolutions;
            }
        }

        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $powerParts = $this->trigonometricPowerParts(
                $functionSide,
                $parameters,
                $evaluationOptions,
            );
            if ($powerParts !== null && $powerParts[1] < 0) {
                $minimumPowerTarget = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
                $boundedPowerSolutions = $this->solveUnboundedRationalTrigonometricTarget(
                    $equation,
                    $this->normalizeEvenPowerTarget($targetSide, $powerParts),
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    false,
                    $minimumPowerTarget,
                    1.0,
                );
                if ($boundedPowerSolutions !== null) {
                    return $boundedPowerSolutions;
                }
            }

            if (
                $this->trigonometricPowerHasNoFeasibleRationalTargetOnUnboundedTails(
                    $functionSide,
                    $targetSide,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
            ) {
                if ($powerParts !== null) {
                    $minimumPowerTarget = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
                    $boundedPowerSolutions = $this->solveUnboundedRationalTrigonometricTarget(
                        $equation,
                        $this->normalizeEvenPowerTarget($targetSide, $powerParts),
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        $extractor,
                        true,
                        $minimumPowerTarget,
                        1.0,
                    );
                    if ($boundedPowerSolutions !== null) {
                        return $boundedPowerSolutions;
                    }
                }
            }

            if (
                $this->trigonometricPowerHasGloballyOutOfRangeRationalTarget(
                    $functionSide,
                    $targetSide,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                )
            ) {
                return [];
            }

            $scaledFunction = $this->extractAffineTrigonometricFunction(
                $functionSide,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if ($scaledFunction === null) {
                $combination = $this->extractSharedPhaseSineCosineCombination(
                    $functionSide,
                    $extractor,
                    $parameters,
                    $evaluationOptions,
                );
                if ($combination !== null && $combination[3] !== null) {
                    $amplitude = \hypot($combination[0], $combination[1]);
                    if ($amplitude > 0.0 && \is_finite($amplitude)) {
                        $scaledFunction = [$amplitude, $combination[2], $combination[3]];
                    }
                }
            }
            if (
                $scaledFunction === null
                && $this->hasInfinitelyManyRootsFromCommensurateTrigonometricSum(
                    $functionSide,
                    $targetSide,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'A periodic polynomial-phase trigonometric sum crosses a rational limit '
                    . 'infinitely many times.',
                );
            }
            if ($scaledFunction === null && $this->containsFunctionCall($functionSide)) {
                $functionRange = $this->boundedTrigonometricExpressionRange(
                    $functionSide,
                    $parameters,
                    $evaluationOptions,
                );
                $exactRationalExtractor = new ExactRationalPolynomialExtractor(
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    $evaluationOptions,
                );
                $rationalTarget = $exactRationalExtractor->rationalFunction($targetSide);
                if ($functionRange !== null && $rationalTarget !== null) {
                    $targetLimit = $this->rationalFunctionLimitAtInfinity($rationalTarget);
                    $targetHasInfiniteLimit = \count($rationalTarget[0]) > \count($rationalTarget[1]);
                    if (
                        $targetHasInfiniteLimit
                        || ($targetLimit !== null
                            && ($targetLimit < $functionRange[0] || $targetLimit > $functionRange[1]))
                    ) {
                        $boundedSolutions = $this->solveUnboundedRationalTrigonometricTarget(
                            $equation,
                            $targetSide,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                            $extractor,
                            true,
                            $functionRange[0],
                            $functionRange[1],
                        );
                        if ($boundedSolutions !== null) {
                            return $boundedSolutions;
                        }
                    }
                }
            }
            if (
                $scaledFunction === null
            ) {
                continue;
            }
            [$functionScale, $functionOffset, $function] = $scaledFunction;
            if (
                !\in_array($function->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
                || $functionScale === 0.0
                || !\is_finite($functionScale)
            ) {
                continue;
            }
            $phase = $extractor->extract($function->arguments[0]);
            if ($phase === null || \count($phase) < 2) {
                continue;
            }
            $phaseGrows = ($upperBound === \INF
                    && ($this->polynomialTendsToPositiveInfinity($phase, 1)
                        || $this->polynomialTendsToPositiveInfinity(
                            $this->scalePolynomialCoefficients($phase, -1.0) ?? [],
                            1,
                        )))
                || ($lowerBound === -\INF
                    && ($this->polynomialTendsToPositiveInfinity($phase, -1)
                        || $this->polynomialTendsToPositiveInfinity(
                            $this->scalePolynomialCoefficients($phase, -1.0) ?? [],
                            -1,
                        )));
            if (!$phaseGrows) {
                continue;
            }

            $rationalExtractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $evaluationOptions,
            );
            $normalizedTarget = $targetSide;
            if ($functionOffset !== null) {
                $normalizedTarget = new BinaryOperationNode(
                    BinaryOperator::Subtract,
                    $normalizedTarget,
                    $functionOffset,
                    $targetSide->span(),
                );
            }
            if ($functionScale !== 1.0) {
                $scaleNode = new NumberNode(
                    $functionScale,
                    \sprintf('%.17g', $functionScale),
                    $targetSide->span(),
                );
                $normalizedTarget = new BinaryOperationNode(
                    BinaryOperator::Divide,
                    $normalizedTarget,
                    $scaleNode,
                    $targetSide->span(),
                );
            }
            $rationalForm = $rationalExtractor->rationalFunction($normalizedTarget);
            if (
                \in_array($function->name, ['tan', 'cot'], true)
            ) {
                if ($rationalForm !== null && $phaseGrows) {
                    throw new InfiniteSolutionSetException(
                        'An unbounded tangent or cotangent phase intersects a rational target '
                        . 'on infinitely many branches.',
                    );
                }

                continue;
            }
            $isReciprocalTrigonometric = \in_array($function->name, ['sec', 'csc'], true);
            $targetLimit = $rationalForm === null
                ? null
                : $this->rationalFunctionLimitAtInfinity($rationalForm);
            if ($isReciprocalTrigonometric) {
                $targetHasInfiniteLimit = $rationalForm !== null
                    && \count($rationalForm[0]) > \count($rationalForm[1]);
                if (
                    ($targetLimit !== null && \abs($targetLimit) > 1.0)
                    || $targetHasInfiniteLimit
                ) {
                    throw new InfiniteSolutionSetException(
                        'An unbounded secant or cosecant phase intersects a rational target '
                        . 'outside the unit interval on infinitely many branches.',
                    );
                }
                if ($targetLimit === 1.0 || $targetLimit === -1.0) {
                    foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
                        if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                            continue;
                        }
                        $phaseGrowsOnTail = $this->polynomialTendsToPositiveInfinity($phase, $direction)
                            || $this->polynomialTendsToPositiveInfinity(
                                $this->scalePolynomialCoefficients($phase, -1.0) ?? [],
                                $direction,
                            );
                        if (!$phaseGrowsOnTail) {
                            continue;
                        }
                        $differenceSign = $this->rationalFunctionDifferenceSignAtInfinity(
                            $rationalExtractor,
                            $normalizedTarget,
                            $targetLimit,
                            $direction,
                        );
                        if (
                            $differenceSign === 0
                            || ($targetLimit === 1.0 && $differenceSign === 1)
                            || ($targetLimit === -1.0 && $differenceSign === -1)
                        ) {
                            throw new InfiniteSolutionSetException(
                                'An unbounded secant or cosecant phase intersects a rational target '
                                . 'approaching its range boundary infinitely many times.',
                            );
                        }
                    }
                }

                $rationalTargetSolutions = $this->solveUnboundedRationalTrigonometricTarget(
                    $equation,
                    $normalizedTarget,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    false,
                );
                if ($rationalTargetSolutions !== null) {
                    return $rationalTargetSolutions;
                }

                continue;
            }
            if ($targetLimit !== null && $targetLimit > -1.0 && $targetLimit < 1.0) {
                throw new InfiniteSolutionSetException(
                    'An unbounded polynomial trigonometric phase crosses a rational target '
                    . 'with an interior finite asymptote infinitely many times.',
                );
            }
            if ($targetLimit === 1.0 || $targetLimit === -1.0) {
                foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
                    if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                        continue;
                    }
                    $phaseGrowsOnTail = $this->polynomialTendsToPositiveInfinity($phase, $direction)
                        || $this->polynomialTendsToPositiveInfinity(
                            $this->scalePolynomialCoefficients($phase, -1.0) ?? [],
                            $direction,
                        );
                    if (!$phaseGrowsOnTail) {
                        continue;
                    }
                    $differenceSign = $this->rationalFunctionDifferenceSignAtInfinity(
                        $rationalExtractor,
                        $normalizedTarget,
                        $targetLimit,
                        $direction,
                    );
                    if (
                        $differenceSign === 0
                        || ($targetLimit === 1.0 && $differenceSign === -1)
                        || ($targetLimit === -1.0 && $differenceSign === 1)
                    ) {
                        throw new InfiniteSolutionSetException(
                            'An unbounded polynomial trigonometric phase crosses a rational target '
                            . 'approaching its range boundary infinitely many times.',
                        );
                    }
                }
            }

            if (
                $targetLimit === null
                || $targetLimit < -1.0
                || $targetLimit > 1.0
                || $targetLimit === -1.0
                || $targetLimit === 1.0
            ) {
                $rationalTargetSolutions = $this->solveUnboundedRationalTrigonometricTarget(
                    $equation,
                    $normalizedTarget,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                );
                if ($rationalTargetSolutions !== null) {
                    return $rationalTargetSolutions;
                }
            }
        }

        foreach (
            [
                [$left, $right, $leftSource, $rightSource],
                [$right, $left, $rightSource, $leftSource],
            ] as [$functionSide, $targetSide, $functionSource, $targetSource]
        ) {
            $functionScale = 1.0;
            $functionOffset = [0.0];
            $function = $functionSide;
            while (true) {
                $function = $this->unwrapGrouping($function);
                if ($function instanceof UnaryOperationNode) {
                    if ($function->operator === UnaryOperator::Minus) {
                        $functionScale *= -1.0;
                        $functionOffset = $this->scalePolynomialCoefficients($functionOffset, -1.0)
                            ?? [\NAN];
                    }
                    $function = $function->operand;
                    continue;
                }

                if ($function instanceof BinaryOperationNode) {
                    $leftConstant = $this->constantNodeValue(
                        $function->left,
                        $parameters,
                        $evaluationOptions,
                    );
                    $rightConstant = $this->constantNodeValue(
                        $function->right,
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $function->operator === BinaryOperator::Multiply
                        && $leftConstant !== null
                        && $rightConstant === null
                    ) {
                        $functionScale *= $leftConstant;
                        $functionOffset = $this->scalePolynomialCoefficients(
                            $functionOffset,
                            $leftConstant,
                        ) ?? [\NAN];
                        $function = $function->right;
                        continue;
                    }
                    if (
                        $function->operator === BinaryOperator::Multiply
                        && $rightConstant !== null
                        && $leftConstant === null
                    ) {
                        $functionScale *= $rightConstant;
                        $functionOffset = $this->scalePolynomialCoefficients(
                            $functionOffset,
                            $rightConstant,
                        ) ?? [\NAN];
                        $function = $function->left;
                        continue;
                    }
                    if (
                        $function->operator === BinaryOperator::Divide
                        && $leftConstant === null
                        && $rightConstant !== null
                        && $rightConstant !== 0.0
                    ) {
                        $functionScale /= $rightConstant;
                        $functionOffset = $this->scalePolynomialCoefficients(
                            $functionOffset,
                            1.0 / $rightConstant,
                        ) ?? [\NAN];
                        $function = $function->left;
                        continue;
                    }

                    if (\in_array($function->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                        $leftPolynomial = $extractor->extract($function->left);
                        $rightPolynomial = $extractor->extract($function->right);
                        if ($leftPolynomial === null && $rightPolynomial !== null) {
                            $scaledRightPolynomial = $this->scalePolynomialCoefficients(
                                $rightPolynomial,
                                $functionScale,
                            );
                            if ($scaledRightPolynomial === null) {
                                break;
                            }
                            $functionOffset = $this->combinePolynomialCoefficients(
                                $functionOffset,
                                $scaledRightPolynomial,
                                $function->operator === BinaryOperator::Add ? 1.0 : -1.0,
                            ) ?? [\NAN];
                            $function = $function->left;
                            continue;
                        }
                        if ($rightPolynomial === null && $leftPolynomial !== null) {
                            $scaledLeftPolynomial = $this->scalePolynomialCoefficients(
                                $leftPolynomial,
                                $functionScale,
                            );
                            if ($scaledLeftPolynomial === null) {
                                break;
                            }
                            if ($function->operator === BinaryOperator::Subtract) {
                                $functionScale *= -1.0;
                                $functionOffset = $this->combinePolynomialCoefficients(
                                    $functionOffset,
                                    $scaledLeftPolynomial,
                                    1.0,
                                ) ?? [\NAN];
                            } else {
                                $functionOffset = $this->combinePolynomialCoefficients(
                                    $functionOffset,
                                    $scaledLeftPolynomial,
                                    1.0,
                                ) ?? [\NAN];
                            }
                            $function = $function->right;
                            continue;
                        }
                    }
                }

                break;
            }
            if (
                !$function instanceof FunctionCallNode
                || !\in_array($function->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            if ($functionScale === 0.0 || !\is_finite($functionScale)) {
                continue;
            }
            foreach ($functionOffset as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
            }
            $phase = $extractor->extract($function->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                $phase === null
                || $target === null
                || \count($target) > $solverOptions->maxPolynomialDegree + 1
                || !\is_finite($target[0])
                || (isset($target[1]) && !\is_finite($target[1]))
            ) {
                continue;
            }
            foreach ($target as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
            }

            $target = $this->combinePolynomialCoefficients($target, $functionOffset, -1.0);
            if ($target === null) {
                continue;
            }
            if ($functionScale !== 1.0) {
                foreach ($target as &$coefficient) {
                    $coefficient /= $functionScale;
                }
                unset($coefficient);
            }
            foreach ($target as $coefficient) {
                if (!\is_finite($coefficient)) {
                    continue 2;
                }
            }

            $targetSlope = $target[1] ?? 0.0;
            $hasNonconstantPhase = false;
            foreach ($phase as $degree => $coefficient) {
                if ($degree > 0 && $coefficient !== 0.0) {
                    $hasNonconstantPhase = true;
                    break;
                }
            }
            $hasNonconstantTarget = false;
            foreach ($target as $degree => $coefficient) {
                if ($degree > 0 && $coefficient !== 0.0) {
                    $hasNonconstantTarget = true;
                    break;
                }
            }
            if (
                \in_array($function->name, ['tan', 'cot', 'sec', 'csc'], true)
                && $hasNonconstantTarget
                && $hasNonconstantPhase
            ) {
                throw new InfiniteSolutionSetException(
                    'A nonconstant polynomial target has roots on infinitely many branches '
                    . 'of the unbounded trigonometric function.',
                );
            }
            if (!\in_array($function->name, ['sin', 'cos'], true) || $targetSlope === 0.0) {
                if (
                    !\in_array($function->name, ['sin', 'cos'], true)
                    || ($targetSlope === 0.0 && \count($target) < 3)
                ) {
                    continue;
                }
            }

            if (\count($target) > 2) {
                $polynomialSolutions = $this->solveUnboundedTrigonometricPolynomialTarget(
                    $equation,
                    $target,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($polynomialSolutions !== null) {
                    return $polynomialSolutions;
                }

                continue;
            }

            $firstBoundary = (-1.0 - $target[0]) / $targetSlope;
            $secondBoundary = (1.0 - $target[0]) / $targetSlope;
            if (!\is_finite($firstBoundary) || !\is_finite($secondBoundary)) {
                continue;
            }
            $feasibleLower = \max($lowerBound, \min($firstBoundary, $secondBoundary));
            $feasibleUpper = \min($upperBound, \max($firstBoundary, $secondBoundary));
            if ($feasibleLower > $feasibleUpper) {
                return [];
            }
            if (!\is_finite($feasibleLower) || !\is_finite($feasibleUpper)) {
                continue;
            }

            return $this->solve(
                $equation,
                $variable,
                $feasibleLower,
                $feasibleUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }

        return null;
    }

    /**
     * Extract a constant-coefficient sum of sine and cosine terms sharing one
     * polynomial phase, together with any function-free offset.
     *
     * @param array<string, int|float> $parameters
     * @return array{float, float, Node|null, FunctionCallNode|null, list<float>|null}|null
     */
    private function extractSharedPhaseSineCosineCombination(
        Node $node,
        PolynomialExtractor $extractor,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->extractSharedPhaseSineCosineCombination(
                $node->operand,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null || $node->operator === UnaryOperator::Plus) {
                return $form;
            }

            return [
                -$form[0],
                -$form[1],
                $this->scaleTrigonometricOffset($form[2], -1.0, $node),
                $form[3],
                $form[4],
            ];
        }

        if ($node instanceof FunctionCallNode) {
            if (
                $evaluationOptions->functions->isBuiltIn($node->name)
                && \in_array($node->name, ['sin', 'cos'], true)
                && \count($node->arguments) === 1
            ) {
                $phase = $extractor->extract($node->arguments[0]);
                if ($phase === null) {
                    return null;
                }
                while (\count($phase) > 1 && $phase[\array_key_last($phase)] === 0.0) {
                    \array_pop($phase);
                }

                return [
                    $node->name === 'sin' ? 1.0 : 0.0,
                    $node->name === 'cos' ? 1.0 : 0.0,
                    null,
                    $node,
                    $phase,
                ];
            }

            if ($this->containsFunctionCall($node)) {
                return null;
            }
        }

        if (!$this->containsFunctionCall($node)) {
            return [0.0, 0.0, $node, null, null];
        }

        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            $left = $this->extractSharedPhaseSineCosineCombination(
                $node->left,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            $right = $this->extractSharedPhaseSineCosineCombination(
                $node->right,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($left === null || $right === null) {
                return null;
            }
            if ($left[4] !== null && $right[4] !== null && $left[4] !== $right[4]) {
                return null;
            }

            $rightSign = $node->operator === BinaryOperator::Add ? 1.0 : -1.0;
            $rightOffset = $right[2];
            if ($rightOffset !== null && $rightSign < 0.0) {
                $rightOffset = new UnaryOperationNode(
                    UnaryOperator::Minus,
                    $rightOffset,
                    $node->span(),
                );
            }

            return [
                $left[0] + ($rightSign * $right[0]),
                $left[1] + ($rightSign * $right[1]),
                $this->combineTrigonometricOffsets(
                    $left[2],
                    $rightOffset,
                    BinaryOperator::Add,
                    $node,
                ),
                $left[3] ?? $right[3],
                $left[4] ?? $right[4],
            ];
        }

        if ($node->operator === BinaryOperator::Multiply) {
            $leftScale = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
            $rightScale = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($leftScale !== null && !$this->containsFunctionCall($node->right)) {
                // The right operand is an offset, not a trigonometric form.
                return null;
            }
            if ($rightScale !== null && !$this->containsFunctionCall($node->left)) {
                return null;
            }
            $scale = $leftScale ?? $rightScale;
            $operand = $leftScale !== null ? $node->right : $node->left;
            if ($scale === null || !$this->containsFunctionCall($operand)) {
                return null;
            }
            $form = $this->extractSharedPhaseSineCosineCombination(
                $operand,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null) {
                return null;
            }

            return [
                $form[0] * $scale,
                $form[1] * $scale,
                $this->scaleTrigonometricOffset($form[2], $scale, $node),
                $form[3],
                $form[4],
            ];
        }

        if ($node->operator === BinaryOperator::Divide) {
            $denominator = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($denominator === null || $denominator === 0.0) {
                return null;
            }
            $form = $this->extractSharedPhaseSineCosineCombination(
                $node->left,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null) {
                return null;
            }

            return [
                $form[0] / $denominator,
                $form[1] / $denominator,
                $this->scaleTrigonometricOffset($form[2], 1.0 / $denominator, $node),
                $form[3],
                $form[4],
            ];
        }

        return null;
    }

    /**
     * Check whether every requested unbounded tail is eventually outside the
     * range of an integer sine/cosine power.
     *
     * @param array<string, int|float> $parameters
     */
    private function trigonometricPowerHasNoFeasibleRationalTargetOnUnboundedTails(
        Node $functionSide,
        Node $targetSide,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return false;
        }
        $powerParts = $this->trigonometricPowerParts(
            $functionSide,
            $parameters,
            $evaluationOptions,
        );
        if ($powerParts === null) {
            return false;
        }
        $target = $this->normalizeEvenPowerTarget($targetSide, $powerParts);
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $targetForm = $extractor->rationalFunction($target);
        if ($targetForm === null) {
            return false;
        }
        $minimumTarget = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
        $targetLimit = $this->rationalFunctionLimitAtInfinity($targetForm);

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            if ($targetLimit !== null && ($targetLimit < $minimumTarget || $targetLimit > 1.0)) {
                continue;
            }
            if ($targetLimit !== null && $targetLimit > $minimumTarget && $targetLimit < 1.0) {
                return false;
            }

            $belowZero = $this->rationalFunctionDifferenceSignAtInfinity(
                $extractor,
                $target,
                $minimumTarget,
                $direction,
            );
            $aboveOne = $this->rationalFunctionDifferenceSignAtInfinity(
                $extractor,
                $target,
                1.0,
                $direction,
            );
            if ($belowZero !== -1 && $aboveOne !== 1) {
                return false;
            }
            if ($targetLimit === $minimumTarget && $belowZero !== -1) {
                return false;
            }
            if ($targetLimit === 1.0 && $aboveOne !== 1) {
                return false;
            }
        }

        return true;
    }

    /**
     * Prove that an integer trigonometric power cannot equal a rational target
     * that stays strictly outside the power range over the full real line.
     *
     * @param array<string, int|float> $parameters
     */
    private function trigonometricPowerHasGloballyOutOfRangeRationalTarget(
        Node $functionSide,
        Node $targetSide,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $powerParts = $this->trigonometricPowerParts(
            $functionSide,
            $parameters,
            $evaluationOptions,
        );
        if ($powerParts === null) {
            return false;
        }

        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        $normalizedTarget = $this->normalizeEvenPowerTarget($targetSide, $powerParts);
        $form = $extractor->rationalFunction($normalizedTarget);
        if ($form === null || $form[0] === [] || $form[1] === []) {
            return false;
        }
        if (
            !$this->exactRationalPolynomialHasNoRealRoots(
                $form[0],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
            || !$this->exactRationalPolynomialHasNoRealRoots(
                $form[1],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            return false;
        }

        $minimumTarget = $powerParts[1] % 2 === 0 ? 0.0 : -1.0;
        $minimumNode = new NumberNode(
            $minimumTarget,
            \sprintf('%.17g', $minimumTarget),
            $normalizedTarget->span(),
        );
        $belowMinimum = $extractor->rationalFunction(new BinaryOperationNode(
            BinaryOperator::Subtract,
            $normalizedTarget,
            $minimumNode,
            $normalizedTarget->span(),
        ));
        if (
            $belowMinimum !== null
            && $this->exactRationalPolynomialHasNoRealRoots(
                $belowMinimum[0],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
            && $this->exactRationalPolynomialHasNoRealRoots(
                $belowMinimum[1],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
            && (\str_starts_with($belowMinimum[0][0][0], '-')
                !== \str_starts_with($belowMinimum[1][0][0], '-'))
        ) {
            return true;
        }

        $one = new NumberNode(1.0, '1', $normalizedTarget->span());
        $aboveOne = new BinaryOperationNode(
            BinaryOperator::Subtract,
            $normalizedTarget,
            $one,
            $normalizedTarget->span(),
        );
        $aboveOneForm = $extractor->rationalFunction($aboveOne);
        if (
            $aboveOneForm === null
            || !$this->exactRationalPolynomialHasNoRealRoots(
                $aboveOneForm[0],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
            || !$this->exactRationalPolynomialHasNoRealRoots(
                $aboveOneForm[1],
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            return false;
        }
        $aboveOneIsPositive = \str_starts_with($aboveOneForm[0][0][0], '-')
            === \str_starts_with($aboveOneForm[1][0][0], '-');

        return $aboveOneIsPositive;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array<string, int|float> $parameters
     */
    private function exactRationalPolynomialHasNoRealRoots(
        array $polynomial,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        if ($polynomial === []) {
            return false;
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0][0] !== '0';
        }
        $source = $this->exactRationalPolynomialSource($polynomial, $variable);
        if ($source === null) {
            return false;
        }
        $rootCount = (new PolynomialRootCountingSolver())->countAllReal(
            '(' . $source . ')=0',
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );

        return $rootCount === 0;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{FunctionCallNode, int, float, float, Node|null}|null
     */
    private function trigonometricPowerParts(
        Node $node,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $scale = 1.0;
        $offset = 0.0;
        $rationalScale = null;
        $hasVariableScale = false;
        while (true) {
            $node = $this->unwrapGrouping($node);
            if ($node instanceof UnaryOperationNode) {
                if ($node->operator === UnaryOperator::Minus) {
                    $scale *= -1.0;
                }
                $node = $node->operand;
                continue;
            }
            if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
                $leftScale = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
                $rightScale = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
                if ($leftScale !== null) {
                    $scale *= $leftScale;
                    $node = $node->right;
                    continue;
                }
                if ($rightScale !== null) {
                    $scale *= $rightScale;
                    $node = $node->left;
                    continue;
                }
                $leftHasFunction = $this->containsFunctionCall($node->left);
                $rightHasFunction = $this->containsFunctionCall($node->right);
                if ($leftHasFunction && !$rightHasFunction) {
                    $rationalScale = $this->combineTrigonometricPowerScaleNode(
                        $rationalScale,
                        BinaryOperator::Multiply,
                        $node->right,
                        $node,
                    );
                    $hasVariableScale = true;
                    $node = $node->left;
                    continue;
                }
                if ($rightHasFunction && !$leftHasFunction) {
                    $rationalScale = $this->combineTrigonometricPowerScaleNode(
                        $rationalScale,
                        BinaryOperator::Multiply,
                        $node->left,
                        $node,
                    );
                    $hasVariableScale = true;
                    $node = $node->right;
                    continue;
                }
            }
            if (
                $node instanceof BinaryOperationNode
                && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
            ) {
                $leftConstant = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
                $rightConstant = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
                if ($leftConstant !== null) {
                    if ($hasVariableScale && $leftConstant !== 0.0) {
                        return null;
                    }
                    if ($node->operator === BinaryOperator::Subtract) {
                        $offset += $scale * $leftConstant;
                        $scale *= -1.0;
                    } else {
                        $offset += $scale * $leftConstant;
                    }
                    $node = $node->right;
                    continue;
                }
                if ($rightConstant !== null) {
                    if ($hasVariableScale && $rightConstant !== 0.0) {
                        return null;
                    }
                    $offset += $scale * ($node->operator === BinaryOperator::Add
                        ? $rightConstant
                        : -$rightConstant);
                    $node = $node->left;
                    continue;
                }
            }
            if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
                $denominator = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
                if ($denominator !== null && $denominator !== 0.0) {
                    $scale /= $denominator;
                    $node = $node->left;
                    continue;
                }
                if (!$this->containsFunctionCall($node->right) && $this->containsFunctionCall($node->left)) {
                    $rationalScale = $this->combineTrigonometricPowerScaleNode(
                        $rationalScale,
                        BinaryOperator::Divide,
                        $node->right,
                        $node,
                    );
                    $hasVariableScale = true;
                    $node = $node->left;
                    continue;
                }
            }
            break;
        }

        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['sec', 'csc'], true)
            && \count($node->arguments) === 1
        ) {
            $base = new FunctionCallNode(
                $node->name === 'sec' ? 'cos' : 'sin',
                $node->arguments,
                $node->nameSpan,
                $node->span,
            );
            $power = -1.0;
        } elseif ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $base = $this->unwrapGrouping($node->left);
            $exponent = $this->unwrapGrouping($node->right);
            $power = $this->constantNodeValue($exponent, $parameters, $evaluationOptions);
        } else {
            return null;
        }
        if (
            !$base instanceof FunctionCallNode
            || !\in_array($base->name, ['sin', 'cos'], true)
            || \count($base->arguments) !== 1
            || $power === null
            || !\is_finite($scale)
            || !\is_finite($offset)
            || $scale === 0.0
        ) {
            return null;
        }
        if (
            !\is_finite($power)
            || $power === 0.0
            || \floor(\abs($power)) !== \abs($power)
            || \abs($power) > \PHP_INT_MAX
        ) {
            return null;
        }

        return [$base, (int) $power, $scale, $offset, $rationalScale];
    }

    private function combineTrigonometricPowerScaleNode(
        ?Node $scale,
        BinaryOperator $operator,
        Node $factor,
        Node $context,
    ): Node {
        $unit = $scale ?? new NumberNode(1.0, '1', $context->span());

        return new BinaryOperationNode($operator, $unit, $factor, $context->span());
    }

    /** @param array{FunctionCallNode, int, float, float, Node|null} $powerParts */
    private function normalizeEvenPowerTarget(Node $target, array $powerParts): Node
    {
        $normalized = $this->subtractEvenPowerOffset($target, $powerParts[3]);
        if ($powerParts[4] !== null) {
            $normalized = new BinaryOperationNode(
                BinaryOperator::Divide,
                $normalized,
                $powerParts[4],
                $target->span(),
            );
        }
        if ($powerParts[2] !== 1.0) {
            $scaleValue = \abs($powerParts[2]);
            $scale = new NumberNode(
                $scaleValue,
                \sprintf('%.17g', $scaleValue),
                $target->span(),
            );
            if ($powerParts[2] < 0.0) {
                $normalized = new UnaryOperationNode(
                    UnaryOperator::Minus,
                    $normalized,
                    $normalized->span(),
                );
            }
            $normalized = new BinaryOperationNode(
                BinaryOperator::Divide,
                $normalized,
                $scale,
                $target->span(),
            );
        }

        if ($powerParts[1] < 0) {
            $one = new NumberNode(1.0, '1', $target->span());
            $normalized = new BinaryOperationNode(
                BinaryOperator::Divide,
                $one,
                $normalized,
                $target->span(),
            );
        }

        return $normalized;
    }

    /** Rewrite an integer sine/cosine power using its exact rational target. */
    private function normalizedTrigonometricPowerEquationSource(
        FunctionCallNode $base,
        int $power,
        Node $target,
        string $functionSource,
        string $variable,
        ExactRationalPolynomialExtractor $extractor,
    ): ?string {
        $argumentSpan = $base->arguments[0]->span();
        $argumentSource = \substr(
            $functionSource,
            $argumentSpan->start,
            $argumentSpan->end - $argumentSpan->start,
        );
        if ($argumentSource === '') {
            return null;
        }
        $targetForm = $extractor->rationalFunction($target);
        if ($targetForm === null) {
            return null;
        }
        [$numerator, $denominator] = $targetForm;
        $numeratorSource = $this->exactRationalPolynomialSource($numerator, $variable);
        $denominatorSource = $this->exactRationalPolynomialSource($denominator, $variable);
        if ($numeratorSource === null || $denominatorSource === null || $denominatorSource === '0') {
            return null;
        }

        $baseSource = $base->name . '(' . $argumentSource . ')';
        $positivePower = \abs($power);
        $functionExpression = $positivePower === 1
            ? $baseSource
            : '(' . $baseSource . ')^' . $positivePower;

        return $functionExpression . '=(' . $numeratorSource . ')/(' . $denominatorSource . ')';
    }

    private function subtractEvenPowerOffset(Node $target, float $offset): Node
    {
        if ($offset === 0.0) {
            return $target;
        }
        $offsetNode = new NumberNode(
            $offset,
            \sprintf('%.17g', $offset),
            $target->span(),
        );

        return new BinaryOperationNode(
            BinaryOperator::Subtract,
            $target,
            $offsetNode,
            $target->span(),
        );
    }

    /** @param list<array{string, string}> $polynomial */
    private function exactRationalPolynomialSource(array $polynomial, string $variable): ?string
    {
        $terms = [];
        foreach ($polynomial as $degree => [$numerator, $denominator]) {
            if ($denominator === '0') {
                return null;
            }
            if ($numerator === '0') {
                continue;
            }
            $term = '(' . $numerator . '/' . $denominator . ')';
            if ($degree > 0) {
                $term .= '*' . $variable . '^' . $degree;
            }
            $terms[] = $term;
        }

        return $terms === [] ? '0' : \implode('+', $terms);
    }

    /**
     * Prove infinitely many roots by finding actual points of a periodic sum
     * on both sides of a finite rational target limit.
     *
     * @param array<string, int|float> $parameters
     */
    private function hasInfinitelyManyRootsFromCommensurateTrigonometricSum(
        Node $functionSide,
        Node $targetSide,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
        ?float $targetLimitAtInfinity = null,
    ): bool {
        $rationalExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        if (
            $this->hasInfiniteRootsFromTrigonometricPowerAtRangeBoundary(
                $functionSide,
                $targetSide,
                $rationalExtractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            )
        ) {
            return true;
        }

        $form = $this->extractPolynomialPhaseTrigonometricSum(
            $functionSide,
            $extractor,
            $parameters,
            $evaluationOptions,
        );
        if ($form === null || $form[0] === []) {
            return false;
        }
        [$terms, $offset] = $form;
        $harmonics = $this->commensurateTrigonometricHarmonics($terms, $rationalExtractor);
        if ($harmonics === null) {
            return false;
        }
        [$basePhase, $periodicTerms] = $harmonics;

        $normalizedTarget = $targetSide;
        if ($offset !== 0.0) {
            $offsetNode = new NumberNode(
                $offset,
                \sprintf('%.17g', $offset),
                $targetSide->span(),
            );
            $normalizedTarget = new BinaryOperationNode(
                BinaryOperator::Subtract,
                $normalizedTarget,
                $offsetNode,
                $targetSide->span(),
            );
        }
        if ($targetLimitAtInfinity === null) {
            $targetForm = $rationalExtractor->rationalFunction($normalizedTarget);
            if ($targetForm === null) {
                return false;
            }
            $targetLimit = $this->rationalFunctionLimitAtInfinity($targetForm);
            if ($targetLimit === null) {
                return false;
            }
        } else {
            $targetLimit = $targetLimitAtInfinity - $offset;
        }
        if (!\is_finite($targetLimit)) {
            return false;
        }

        $phaseGrowsOnTail = false;
        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            $negativePhase = $this->scalePolynomialCoefficients($basePhase, -1.0);
            if (
                $this->polynomialTendsToPositiveInfinity($basePhase, $direction)
                || ($negativePhase !== null
                    && $this->polynomialTendsToPositiveInfinity($negativePhase, $direction))
            ) {
                $phaseGrowsOnTail = true;
                break;
            }
        }
        if (!$phaseGrowsOnTail) {
            return false;
        }

        $maximumHarmonic = 1;
        $coefficientMagnitude = 0.0;
        foreach ($periodicTerms as [$coefficient, $function, $harmonic, $phaseOffset]) {
            $maximumHarmonic = \max($maximumHarmonic, \abs($harmonic));
            $coefficientMagnitude += \abs($coefficient);
        }
        if (!\is_finite($coefficientMagnitude)) {
            return false;
        }
        $sampleCount = \min(4096, \max(64, 16 * $maximumHarmonic));
        $sampleMinimum = \INF;
        $sampleMaximum = -\INF;
        $maximumArgumentMagnitude = 0.0;
        $quadrantalValues = [];
        $quadrantalStride = \intdiv($sampleCount, 4);
        for ($sample = 0; $sample < $sampleCount; ++$sample) {
            $phaseValue = (2.0 * \M_PI * $sample) / $sampleCount;
            $value = 0.0;
            foreach ($periodicTerms as [$coefficient, $function, $harmonic, $phaseOffset]) {
                $argument = ($harmonic * $phaseValue) + $phaseOffset;
                if (!\is_finite($argument) || \abs($argument) > 1.0E12) {
                    return false;
                }
                $maximumArgumentMagnitude = \max($maximumArgumentMagnitude, \abs($argument));
                $value += $coefficient * ($function === 'sin' ? \sin($argument) : \cos($argument));
            }
            if (!\is_finite($value)) {
                return false;
            }
            $sampleMinimum = \min($sampleMinimum, $value);
            $sampleMaximum = \max($sampleMaximum, $value);
            if ($sample % $quadrantalStride === 0) {
                $quadrantalValue = $this->trigonometricSumValueAtQuadrantalPhase(
                    $periodicTerms,
                    \intdiv($sample, $quadrantalStride),
                );
                if ($quadrantalValue !== null) {
                    $quadrantalValues[] = $quadrantalValue;
                }
            }
        }

        $margin = 64.0 * \PHP_FLOAT_EPSILON * \max(
            1.0,
            \abs($targetLimit),
            $coefficientMagnitude,
            $coefficientMagnitude * \max(1.0, $maximumArgumentMagnitude),
            \abs($sampleMinimum),
            \abs($sampleMaximum),
        );

        if ($sampleMinimum + $margin < $targetLimit && $targetLimit < $sampleMaximum - $margin) {
            return true;
        }
        if ($targetLimitAtInfinity === 0.0 && $sampleMaximum > $targetLimit + $margin) {
            foreach ($quadrantalValues as $quadrantalValue) {
                if ($quadrantalValue === $targetLimit) {
                    return true;
                }
            }
        }

        return $this->hasInfinitelyManyRootsAtSingleHarmonicBoundary(
            $periodicTerms,
            $targetLimit,
            $normalizedTarget,
            $rationalExtractor,
            $lowerBound,
            $upperBound,
        );
    }

    /**
     * Evaluate a quadrantal trigonometric sum exactly at a multiple of pi/2.
     *
     * @param list<array{float, string, int, float}> $terms
     */
    private function trigonometricSumValueAtQuadrantalPhase(array $terms, int $quadrant): ?float
    {
        $sineValues = [0.0, 1.0, 0.0, -1.0];
        $cosineValues = [1.0, 0.0, -1.0, 0.0];
        $value = 0.0;
        foreach ($terms as [$coefficient, $function, $harmonic, $phaseOffset]) {
            $phaseOffsetQuarterTurns = $this->quadrantalPhaseOffset($phaseOffset);
            if ($phaseOffsetQuarterTurns === null) {
                return null;
            }
            $quarterTurn = (($harmonic * $quadrant + $phaseOffsetQuarterTurns) % 4 + 4) % 4;
            $trigonometricValue = $function === 'sin'
                ? $sineValues[$quarterTurn]
                : $cosineValues[$quarterTurn];
            $value += $coefficient * $trigonometricValue;
        }

        return \is_finite($value) ? $value : null;
    }

    private function quadrantalPhaseOffset(float $phaseOffset): ?int
    {
        if (!\is_finite($phaseOffset)) {
            return null;
        }
        $quarterTurns = (int) \round((2.0 * $phaseOffset) / \M_PI);
        if (\abs($quarterTurns) > 8192) {
            return null;
        }

        return $phaseOffset === ($quarterTurns * \M_PI / 2.0) ? $quarterTurns : null;
    }

    /**
     * Prove repeated crossings at an endpoint of an integer sine/cosine
     * power's range along an unbounded polynomial phase.
     */
    private function hasInfiniteRootsFromTrigonometricPowerAtRangeBoundary(
        Node $functionSide,
        Node $target,
        ExactRationalPolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $powerParts = $this->trigonometricPowerParts(
            $functionSide,
            $parameters,
            $evaluationOptions,
        );
        if ($powerParts === null) {
            return false;
        }

        [$base, $power] = $powerParts;
        $minimumTarget = $power % 2 === 0 ? 0.0 : -1.0;
        $target = $this->normalizeEvenPowerTarget($target, $powerParts);
        $targetForm = $extractor->rationalFunction($target);
        $targetLimit = $targetForm === null
            ? null
            : $this->rationalFunctionLimitAtInfinity($targetForm);
        if ($targetLimit !== $minimumTarget && $targetLimit !== 1.0) {
            return false;
        }
        $phase = $extractor->polynomial($base->arguments[0]);
        if (
            $phase === null
            || \count($phase) < 2
            || $phase[\array_key_last($phase)][0] === '0'
        ) {
            return false;
        }
        if ($lowerBound !== -\INF && $upperBound !== \INF) {
            return false;
        }

        $boundaryNode = new NumberNode(
            $targetLimit,
            \sprintf('%.17g', $targetLimit),
            $target->span(),
        );
        $boundaryDifference = $extractor->rationalDifference($target, $boundaryNode);
        if (
            $boundaryDifference !== null
            && \count(\array_filter(
                $boundaryDifference[0],
                static fn (string $coefficient): bool => $coefficient !== '0',
            )) === 0
        ) {
            return true;
        }

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            $targetSign = $this->rationalFunctionDifferenceSignAtInfinity(
                $extractor,
                $target,
                $targetLimit,
                $direction,
            );
            if (
                ($targetLimit === $minimumTarget && $targetSign === 1)
                || ($targetLimit === 1.0 && $targetSign === -1)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Handle an asymptote at an exact range boundary of a single zero-shift harmonic.
     *
     * @param list<array{float, string, int, float}> $terms
     */
    private function hasInfinitelyManyRootsAtSingleHarmonicBoundary(
        array $terms,
        float $targetLimit,
        Node $target,
        ExactRationalPolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
    ): bool {
        $harmonic = null;
        $sineCoefficient = 0.0;
        $cosineCoefficient = 0.0;
        foreach ($terms as [$coefficient, $function, $frequency, $phaseOffset]) {
            if ($phaseOffset !== 0.0 || ($harmonic !== null && \abs($frequency) !== $harmonic)) {
                return false;
            }
            $harmonic = \abs($frequency);
            $direction = $frequency < 0 ? -1.0 : 1.0;
            if ($function === 'sin') {
                $sineCoefficient += $coefficient * $direction;
            } else {
                $cosineCoefficient += $coefficient;
            }
        }
        if ($harmonic === null || $harmonic === 0) {
            return false;
        }
        $amplitude = \hypot($sineCoefficient, $cosineCoefficient);
        if (!\is_finite($amplitude) || $amplitude === 0.0) {
            return false;
        }
        $twiceAmplitude = 2.0 * $amplitude;
        if (
            !\is_finite($twiceAmplitude)
            || \abs($twiceAmplitude - \round($twiceAmplitude)) > 0.0
        ) {
            return false;
        }
        if ($targetLimit !== -$amplitude && $targetLimit !== $amplitude) {
            return false;
        }

        foreach ([[-1, $lowerBound], [1, $upperBound]] as [$direction, $bound]) {
            if (($direction < 0 && $bound !== -\INF) || ($direction > 0 && $bound !== \INF)) {
                continue;
            }
            $differenceSign = $this->rationalFunctionDifferenceSignAtInfinity(
                $extractor,
                $target,
                $targetLimit,
                $direction,
            );
            if (
                $differenceSign === 0
                || ($targetLimit === -$amplitude && $differenceSign === 1)
                || ($targetLimit === $amplitude && $differenceSign === -1)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extract a sum of sine/cosine calls with a constant offset.
     *
     * @param array<string, int|float> $parameters
     * @return array{list<array{float, string, list<float>, Node}>, float}|null
     */
    private function extractPolynomialPhaseTrigonometricSum(
        Node $node,
        PolynomialExtractor $extractor,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->extractPolynomialPhaseTrigonometricSum(
                $node->operand,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null || $node->operator === UnaryOperator::Plus) {
                return $form;
            }
            foreach ($form[0] as &$term) {
                $term[0] *= -1.0;
            }
            unset($term);

            return [$form[0], -$form[1]];
        }

        if ($node instanceof FunctionCallNode) {
            if (
                $evaluationOptions->functions->isBuiltIn($node->name)
                && \in_array($node->name, ['sin', 'cos'], true)
                && \count($node->arguments) === 1
            ) {
                $phase = $extractor->extract($node->arguments[0]);
                if ($phase === null) {
                    return null;
                }
                while (\count($phase) > 1 && $phase[\array_key_last($phase)] === 0.0) {
                    \array_pop($phase);
                }
                if (\count($phase) < 2) {
                    $value = $this->constantNodeValue($node, $parameters, $evaluationOptions);

                    return $value === null ? null : [[], $value];
                }

                return [[[1.0, $node->name, $phase, $node->arguments[0]]], 0.0];
            }
        }

        if (!$this->containsFunctionCall($node)) {
            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $constant === null || !\is_finite($constant) ? null : [[], $constant];
        }

        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            $left = $this->extractPolynomialPhaseTrigonometricSum(
                $node->left,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            $right = $this->extractPolynomialPhaseTrigonometricSum(
                $node->right,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($left === null || $right === null) {
                return null;
            }
            $sign = $node->operator === BinaryOperator::Add ? 1.0 : -1.0;
            $terms = $left[0];
            foreach ($right[0] as $term) {
                $term[0] *= $sign;
                $terms[] = $term;
            }
            if (\count($terms) > self::MAX_PERIODIC_SUM_TERMS) {
                return null;
            }

            return [$terms, $left[1] + ($sign * $right[1])];
        }

        if ($node->operator === BinaryOperator::Multiply) {
            $leftScale = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
            $rightScale = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($leftScale !== null && $this->containsFunctionCall($node->right)) {
                $scale = $leftScale;
                $operand = $node->right;
            } elseif ($rightScale !== null && $this->containsFunctionCall($node->left)) {
                $scale = $rightScale;
                $operand = $node->left;
            } else {
                $leftForm = $this->extractPolynomialPhaseTrigonometricSum(
                    $node->left,
                    $extractor,
                    $parameters,
                    $evaluationOptions,
                );
                $rightForm = $this->extractPolynomialPhaseTrigonometricSum(
                    $node->right,
                    $extractor,
                    $parameters,
                    $evaluationOptions,
                );

                return $leftForm === null || $rightForm === null
                    ? null
                    : $this->multiplyPolynomialPhaseTrigonometricSums(
                        $leftForm,
                        $rightForm,
                        $extractor,
                        $parameters,
                        $evaluationOptions,
                    );
            }
            $form = $this->extractPolynomialPhaseTrigonometricSum(
                $operand,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null) {
                return null;
            }
            foreach ($form[0] as &$term) {
                $term[0] *= $scale;
            }
            unset($term);

            return [$form[0], $form[1] * $scale];
        }

        if ($node->operator === BinaryOperator::Power) {
            $exponent = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if (
                $exponent === null
                || $exponent < 0.0
                || \floor($exponent) !== $exponent
                || $exponent > 16.0
            ) {
                return null;
            }
            $base = $this->extractPolynomialPhaseTrigonometricSum(
                $node->left,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($base === null) {
                return null;
            }
            $result = [[], 1.0];
            for ($power = 0; $power < (int) $exponent; ++$power) {
                $result = $this->multiplyPolynomialPhaseTrigonometricSums(
                    $result,
                    $base,
                    $extractor,
                    $parameters,
                    $evaluationOptions,
                );
                if ($result === null) {
                    return null;
                }
            }

            return $result;
        }

        if ($node->operator === BinaryOperator::Divide) {
            $denominator = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($denominator === null || $denominator === 0.0) {
                return null;
            }
            $form = $this->extractPolynomialPhaseTrigonometricSum(
                $node->left,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null) {
                return null;
            }
            foreach ($form[0] as &$term) {
                $term[0] /= $denominator;
            }
            unset($term);

            return [$form[0], $form[1] / $denominator];
        }

        return null;
    }

    /**
     * Multiply two finite sine/cosine sums using product-to-sum identities.
     *
     * @param array{list<array{float, string, list<float>, Node}>, float} $left
     * @param array{list<array{float, string, list<float>, Node}>, float} $right
     * @param array<string, int|float> $parameters
     * @return array{list<array{float, string, list<float>, Node}>, float}|null
     */
    private function multiplyPolynomialPhaseTrigonometricSums(
        array $left,
        array $right,
        PolynomialExtractor $extractor,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $leftTermCount = \count($left[0]);
        $rightTermCount = \count($right[0]);
        if (
            ($leftTermCount > 0
                && $rightTermCount > \intdiv(self::MAX_PERIODIC_SUM_PRODUCT_PAIRS, $leftTermCount))
            || $leftTermCount + $rightTermCount
                + (2 * $leftTermCount * $rightTermCount) > self::MAX_PERIODIC_SUM_TERMS
        ) {
            return null;
        }

        $terms = [];
        $offset = $left[1] * $right[1];
        foreach ($left[0] as [$coefficient, $function, $phase, $phaseNode]) {
            $scaledCoefficient = $coefficient * $right[1];
            if (!\is_finite($scaledCoefficient)) {
                return null;
            }
            if ($scaledCoefficient !== 0.0) {
                $terms[] = [$scaledCoefficient, $function, $phase, $phaseNode];
            }
        }
        foreach ($right[0] as [$coefficient, $function, $phase, $phaseNode]) {
            $scaledCoefficient = $coefficient * $left[1];
            if (!\is_finite($scaledCoefficient)) {
                return null;
            }
            if ($scaledCoefficient !== 0.0) {
                $terms[] = [$scaledCoefficient, $function, $phase, $phaseNode];
            }
        }
        if (!\is_finite($offset)) {
            return null;
        }

        $addProductTerm = function (
            string $function,
            Node $phaseNode,
            float $coefficient,
        ) use (
            $extractor,
            $parameters,
            $evaluationOptions,
            &$terms,
            &$offset,
        ): bool {
            if (!\is_finite($coefficient)) {
                return false;
            }
            if ($coefficient === 0.0) {
                return true;
            }
            $phase = $extractor->extract($phaseNode);
            if ($phase === null) {
                return false;
            }
            while (\count($phase) > 1 && $phase[\array_key_last($phase)] === 0.0) {
                \array_pop($phase);
            }
            if (\count($phase) < 2) {
                $phaseValue = $phase[0] ?? 0.0;
                $offset += $coefficient * ($function === 'sin' ? \sin($phaseValue) : \cos($phaseValue));

                return \is_finite($offset);
            }

            $terms[] = [$coefficient, $function, $phase, $phaseNode];

            return true;
        };

        foreach ($left[0] as [$leftCoefficient, $leftFunction, , $leftPhase]) {
            foreach ($right[0] as [$rightCoefficient, $rightFunction, , $rightPhase]) {
                $span = $leftPhase->span()->cover($rightPhase->span());
                $sumPhase = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $leftPhase,
                    $rightPhase,
                    $span,
                );
                $differencePhase = new BinaryOperationNode(
                    BinaryOperator::Subtract,
                    $leftPhase,
                    $rightPhase,
                    $span,
                );
                $halfProduct = 0.5 * $leftCoefficient * $rightCoefficient;
                if ($leftFunction === 'sin' && $rightFunction === 'sin') {
                    if (
                        !$addProductTerm('cos', $differencePhase, $halfProduct)
                        || !$addProductTerm('cos', $sumPhase, -$halfProduct)
                    ) {
                        return null;
                    }
                } elseif ($leftFunction === 'sin') {
                    if (
                        !$addProductTerm('sin', $sumPhase, $halfProduct)
                        || !$addProductTerm('sin', $differencePhase, $halfProduct)
                    ) {
                        return null;
                    }
                } elseif ($rightFunction === 'sin') {
                    if (
                        !$addProductTerm('sin', $sumPhase, $halfProduct)
                        || !$addProductTerm('sin', $differencePhase, -$halfProduct)
                    ) {
                        return null;
                    }
                } elseif (
                    !$addProductTerm('cos', $differencePhase, $halfProduct)
                    || !$addProductTerm('cos', $sumPhase, $halfProduct)
                ) {
                    return null;
                }
            }
        }

        return [$terms, $offset];
    }

    /**
     * Express each phase as an integer harmonic of one polynomial base phase.
     *
     * @param list<array{float, string, list<float>, Node}> $terms
     * @return array{list<float>, list<array{float, string, int, float}>}|null
     */
    private function commensurateTrigonometricHarmonics(
        array $terms,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $terms = \array_values(\array_filter(
            $terms,
            static fn (array $term): bool => $term[0] !== 0.0,
        ));
        foreach ($terms as $baseTerm) {
            $basePhase = $this->exactPolynomialCoefficients($baseTerm[3], $extractor);
            if ($basePhase === null) {
                continue;
            }
            $candidateTerms = [];
            $harmonicRatios = [];
            $valid = true;
            foreach ($terms as [$coefficient, $function, $phase, $phaseNode]) {
                $phaseCoefficients = $this->exactPolynomialCoefficients($phaseNode, $extractor);
                if ($phaseCoefficients === null) {
                    $valid = false;
                    break;
                }
                $maximumDegree = \max(\count($basePhase), \count($phaseCoefficients)) - 1;
                $referenceDegree = null;
                for ($degree = 1; $degree <= $maximumDegree; ++$degree) {
                    if (($basePhase[$degree] ?? ['0', '1'])[0] !== '0') {
                        $referenceDegree = $degree;
                        break;
                    }
                }
                if (
                    $referenceDegree === null
                    || ($phaseCoefficients[$referenceDegree] ?? ['0', '1'])[0] === '0'
                ) {
                    $valid = false;
                    break;
                }
                $ratio = $extractor->multiplyExactFractions(
                    $phaseCoefficients[$referenceDegree],
                    [
                        $basePhase[$referenceDegree][1],
                        $basePhase[$referenceDegree][0],
                    ],
                );
                if ($ratio === null) {
                    $valid = false;
                    break;
                }
                $ratioValue = (float) $ratio[0] / (float) $ratio[1];
                if (!\is_finite($ratioValue) || \abs($ratioValue) > 4096.0) {
                    $valid = false;
                    break;
                }
                $integerRatio = null;
                for ($denominator = 1; $denominator <= 64; ++$denominator) {
                    $numerator = (int) \round($ratioValue * $denominator);
                    if ($numerator === 0 || \abs($numerator) > 4096) {
                        continue;
                    }
                    $candidateRatio = $extractor->multiplyExactFractions(
                        [(string) $numerator, (string) $denominator],
                        ['1', '1'],
                    );
                    if ($candidateRatio === $ratio) {
                        $integerRatio = [$numerator, $denominator];
                        break;
                    }
                }
                if (
                    $integerRatio === null
                ) {
                    $valid = false;
                    break;
                }
                for ($degree = 1; $degree <= $maximumDegree; ++$degree) {
                    $expected = $extractor->multiplyExactFractions(
                        $basePhase[$degree] ?? ['0', '1'],
                        [(string) $integerRatio[0], (string) $integerRatio[1]],
                    );
                    $actual = $extractor->multiplyExactFractions(
                        $phaseCoefficients[$degree] ?? ['0', '1'],
                        ['1', '1'],
                    );
                    if ($expected === null || $actual === null || $expected !== $actual) {
                        $valid = false;
                        break;
                    }
                }
                if (!$valid) {
                    break;
                }
                $harmonicRatios[] = $integerRatio;
                $candidateTerms[] = [$coefficient, $function, 0, $phase[0] ?? 0.0];
            }
            if ($valid) {
                $commonDenominator = 1;
                foreach ($harmonicRatios as [, $denominator]) {
                    $greatestCommonDivisor = self::greatestCommonDivisor(
                        $commonDenominator,
                        $denominator,
                    );
                    if ($commonDenominator > \intdiv(4096, $denominator)) {
                        $valid = false;
                        break;
                    }
                    $commonDenominator = \intdiv($commonDenominator, $greatestCommonDivisor)
                        * $denominator;
                }
                if (!$valid) {
                    continue;
                }
                foreach ($candidateTerms as $index => [$coefficient, $function, $unusedHarmonic, $phaseOffset]) {
                    $candidateTerms[$index][2] = $harmonicRatios[$index][0]
                        * \intdiv($commonDenominator, $harmonicRatios[$index][1]);
                    if (\abs($candidateTerms[$index][2]) > 4096) {
                        $valid = false;
                        break;
                    }
                }
                if (!$valid) {
                    continue;
                }
                $baseFloatPhase = $baseTerm[2];
                $baseFloatPhase[0] = 0.0;
                $baseFloatPhase = $this->scalePolynomialCoefficients(
                    $baseFloatPhase,
                    1.0 / $commonDenominator,
                );
                if ($baseFloatPhase !== null) {
                    return [$baseFloatPhase, $candidateTerms];
                }
            }
        }

        foreach ($terms as [$baseCoefficient, $baseFunction, $basePhase]) {
            $baseDegree = \count($basePhase) - 1;
            while ($baseDegree > 0 && $basePhase[$baseDegree] === 0.0) {
                --$baseDegree;
            }
            $referenceDegree = null;
            for ($degree = 1; $degree <= $baseDegree; ++$degree) {
                if ($basePhase[$degree] !== 0.0) {
                    $referenceDegree = $degree;
                    break;
                }
            }
            if ($referenceDegree === null) {
                continue;
            }

            $candidateTerms = [];
            $harmonicRatios = [];
            $valid = true;
            foreach ($terms as [$coefficient, $function, $phase]) {
                $termDegree = \count($phase) - 1;
                while ($termDegree > 0 && $phase[$termDegree] === 0.0) {
                    --$termDegree;
                }
                if ($termDegree !== $baseDegree || ($phase[$referenceDegree] ?? 0.0) === 0.0) {
                    $valid = false;
                    break;
                }
                $ratio = $phase[$referenceDegree] / $basePhase[$referenceDegree];
                if (!\is_finite($ratio) || $ratio === 0.0 || \abs($ratio) > 4096.0) {
                    $valid = false;
                    break;
                }
                $integerRatio = null;
                for ($denominator = 1; $denominator <= 64; ++$denominator) {
                    $numerator = (int) \round($ratio * $denominator);
                    if ($numerator === 0 || \abs($numerator) > 4096) {
                        continue;
                    }
                    $candidateRatio = $numerator / $denominator;
                    if (
                        \abs($ratio - $candidateRatio)
                        <= 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($ratio))
                    ) {
                        $integerRatio = [$numerator, $denominator];
                        break;
                    }
                }
                if ($integerRatio === null) {
                    $valid = false;
                    break;
                }
                for ($degree = 1; $degree <= $baseDegree; ++$degree) {
                    $expected = $basePhase[$degree] * $ratio;
                    $actual = $phase[$degree] ?? 0.0;
                    if (
                        \abs($actual - $expected)
                        > 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($actual), \abs($expected))
                    ) {
                        $valid = false;
                        break;
                    }
                }
                if (!$valid) {
                    break;
                }
                $harmonicRatios[] = $integerRatio;
                $candidateTerms[] = [$coefficient, $function, 0, $phase[0] ?? 0.0];
            }
            if (!$valid) {
                continue;
            }

            $commonDenominator = 1;
            foreach ($harmonicRatios as [, $denominator]) {
                $greatestCommonDivisor = self::greatestCommonDivisor($commonDenominator, $denominator);
                if ($commonDenominator > \intdiv(4096, $denominator)) {
                    $valid = false;
                    break;
                }
                $commonDenominator = \intdiv($commonDenominator, $greatestCommonDivisor) * $denominator;
            }
            if (!$valid) {
                continue;
            }
            foreach ($candidateTerms as $index => [$coefficient, $function, $unusedHarmonic, $phaseOffset]) {
                $candidateTerms[$index][2] = $harmonicRatios[$index][0]
                    * \intdiv($commonDenominator, $harmonicRatios[$index][1]);
                if (\abs($candidateTerms[$index][2]) > 4096) {
                    $valid = false;
                    break;
                }
            }
            if (!$valid) {
                continue;
            }
            $baseFloatPhase = $basePhase;
            $baseFloatPhase[0] = 0.0;
            $baseFloatPhase = $this->scalePolynomialCoefficients($baseFloatPhase, 1.0 / $commonDenominator);
            if ($baseFloatPhase !== null) {
                return [$baseFloatPhase, $candidateTerms];
            }
        }

        return null;
    }

    /**
     * @return list<array{string, string}>|null
     */
    private function exactPolynomialCoefficients(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $form = $extractor->rationalPolynomialForm($node);
        if ($form === null) {
            return null;
        }
        [$numerator, $denominator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
            \array_pop($denominator);
        }
        if (\count($denominator) !== 1 || $denominator[0][0] === '0') {
            return null;
        }
        $reciprocalDenominator = [$denominator[0][1], $denominator[0][0]];
        $coefficients = [];
        foreach ($numerator as $coefficient) {
            $exactCoefficient = $extractor->multiplyExactFractions(
                $coefficient,
                $reciprocalDenominator,
            );
            if ($exactCoefficient === null) {
                return null;
            }
            $coefficients[] = $exactCoefficient;
        }

        return $coefficients;
    }

    private static function greatestCommonDivisor(int $first, int $second): int
    {
        while ($second !== 0) {
            [$first, $second] = [$second, $first % $second];
        }

        return $first;
    }

    /**
     * Extract a constant affine transform of a direct trigonometric call.
     *
     * @param array<string, int|float> $parameters
     * @return array{float, Node|null, FunctionCallNode}|null
     */
    private function extractAffineTrigonometricFunction(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->extractAffineTrigonometricFunction(
                $node->operand,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if ($form === null || $node->operator === UnaryOperator::Plus) {
                return $form;
            }

            return [
                -$form[0],
                $this->combineTrigonometricOffsets(
                    null,
                    $form[1],
                    BinaryOperator::Subtract,
                    $node,
                ),
                $form[2],
            ];
        }
        if (!$node instanceof BinaryOperationNode) {
            if (
                !$node instanceof FunctionCallNode
                || !\in_array($node->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
            ) {
                return null;
            }

            return [1.0, null, $node];
        }

        if ($node->operator === BinaryOperator::Multiply) {
            $leftConstant = $this->constantNodeValue($node->left, $parameters, $evaluationOptions);
            $rightConstant = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($leftConstant !== null) {
                $form = $this->extractAffineTrigonometricFunction(
                    $node->right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
                if ($form !== null) {
                    return [
                        $leftConstant * $form[0],
                        $this->scaleTrigonometricOffset($form[1], $leftConstant, $node),
                        $form[2],
                    ];
                }
            }
            if ($rightConstant !== null) {
                $form = $this->extractAffineTrigonometricFunction(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
                if ($form !== null) {
                    return [
                        $rightConstant * $form[0],
                        $this->scaleTrigonometricOffset($form[1], $rightConstant, $node),
                        $form[2],
                    ];
                }
            }
        }
        if ($node->operator === BinaryOperator::Divide) {
            $denominator = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($denominator !== null && $denominator !== 0.0) {
                $form = $this->extractAffineTrigonometricFunction(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
                if ($form !== null) {
                    return [
                        $form[0] / $denominator,
                        $this->scaleTrigonometricOffset($form[1], 1.0 / $denominator, $node),
                        $form[2],
                    ];
                }
            }
        }
        if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            $leftForm = $this->extractAffineTrigonometricFunction(
                $node->left,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            $rightForm = $this->extractAffineTrigonometricFunction(
                $node->right,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if (
                $leftForm !== null
                && $rightForm === null
                && !$this->containsFunctionCall($node->right)
            ) {
                return [
                    $leftForm[0],
                    $this->combineTrigonometricOffsets(
                        $leftForm[1],
                        $node->right,
                        $node->operator,
                        $node,
                    ),
                    $leftForm[2],
                ];
            }
            if (
                $rightForm !== null
                && $leftForm === null
                && !$this->containsFunctionCall($node->left)
            ) {
                if ($node->operator === BinaryOperator::Add) {
                    return [
                        $rightForm[0],
                        $this->combineTrigonometricOffsets(
                            $node->left,
                            $rightForm[1],
                            BinaryOperator::Add,
                            $node,
                        ),
                        $rightForm[2],
                    ];
                }

                return [
                    -$rightForm[0],
                    $this->combineTrigonometricOffsets(
                        $node->left,
                        $rightForm[1],
                        BinaryOperator::Subtract,
                        $node,
                    ),
                    $rightForm[2],
                ];
            }
        }

        return null;
    }

    private function scaleTrigonometricOffset(?Node $offset, float $scale, Node $context): ?Node
    {
        if ($offset === null || $scale === 0.0) {
            return null;
        }

        $scaleNode = new NumberNode(
            $scale,
            \sprintf('%.17g', $scale),
            $context->span(),
        );

        return new BinaryOperationNode(
            BinaryOperator::Multiply,
            $scaleNode,
            $offset,
            $context->span(),
        );
    }

    private function combineTrigonometricOffsets(
        ?Node $left,
        ?Node $right,
        BinaryOperator $operator,
        Node $context,
    ): ?Node {
        if ($left === null) {
            if ($operator === BinaryOperator::Subtract && $right !== null) {
                return new UnaryOperationNode(UnaryOperator::Minus, $right, $context->span());
            }

            return $right;
        }
        if ($right === null) {
            return $left;
        }

        return new BinaryOperationNode($operator, $left, $right, $context->span());
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     */
    private function rationalFunctionLimitAtInfinity(array $form): ?float
    {
        [$numerator, $denominator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
            \array_pop($denominator);
        }
        if ($denominator === [] || $denominator[\array_key_last($denominator)][0] === '0') {
            return null;
        }
        if (\count($numerator) < \count($denominator)) {
            return 0.0;
        }
        if (\count($numerator) > \count($denominator)) {
            return null;
        }

        $numeratorLeading = $numerator[\array_key_last($numerator)];
        $denominatorLeading = $denominator[\array_key_last($denominator)];
        $numeratorValue = (float) $numeratorLeading[0] / (float) $numeratorLeading[1];
        $denominatorValue = (float) $denominatorLeading[0] / (float) $denominatorLeading[1];
        if (!\is_finite($numeratorValue) || !\is_finite($denominatorValue) || $denominatorValue === 0.0) {
            return null;
        }

        $limit = $numeratorValue / $denominatorValue;

        return \is_finite($limit) ? $limit : null;
    }

    /**
     * Restrict a rational target to its bounded intersection with a sine or cosine range.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null Null means the finite feasible regions could not be isolated.
     */
    private function solveUnboundedRationalTrigonometricTarget(
        string $equation,
        Node $targetSide,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        PolynomialExtractor $extractor,
        bool $insideUnitInterval = true,
        float $minimumTarget = -1.0,
        float $maximumTarget = 1.0,
    ): ?array {
        $exactExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $options->maxPolynomialDegree,
            $evaluationOptions,
        );
        $reducedForm = $exactExtractor->reducedRationalFunction($targetSide);
        if ($reducedForm === null) {
            return null;
        }
        [$exactNumerator, $exactDenominator, $exactOriginalDenominator] = $reducedForm;
        $toFloatCoefficients = static function (array $polynomial): ?array {
            $coefficients = [];
            foreach ($polynomial as [$numerator, $denominator]) {
                $value = (float) $numerator / (float) $denominator;
                if (!\is_finite($value)) {
                    return null;
                }
                $coefficients[] = $value;
            }

            return $coefficients;
        };
        $numerator = $toFloatCoefficients($exactNumerator);
        $denominator = $toFloatCoefficients($exactDenominator);
        $originalDenominator = $toFloatCoefficients($exactOriginalDenominator);
        if (
            $numerator === null
            || $denominator === null
            || $denominator === [0.0]
            || $originalDenominator === null
        ) {
            return null;
        }
        [$leftSource, $rightSource, $rightSourceOffset] = $this->splitEquation($equation);
        $leftNode = $this->parseSide($leftSource, 0, $evaluationOptions);
        $rightNode = $this->parseSide($rightSource, $rightSourceOffset, $evaluationOptions);
        $numeratorSource = $this->exactRationalPolynomialSource($exactNumerator, $variable);
        $denominatorSource = $this->exactRationalPolynomialSource($exactDenominator, $variable);
        if ($numeratorSource === null || $denominatorSource === null) {
            return null;
        }
        if ($this->sameExpression($this->unwrapGrouping($targetSide), $this->unwrapGrouping($leftNode))) {
            $normalizedEquation = '(' . $numeratorSource . ')/(' . $denominatorSource . ')='
                . $rightSource;
        } elseif ($this->sameExpression($this->unwrapGrouping($targetSide), $this->unwrapGrouping($rightNode))) {
            $normalizedEquation = $leftSource . '=('
                . $numeratorSource . ')/(' . $denominatorSource . ')';
        } else {
            $normalizedEquation = $equation;
        }
        $rangeBoundaries = [
            $this->combinePolynomialCoefficients($numerator, $denominator, -$minimumTarget),
            $this->combinePolynomialCoefficients($numerator, $denominator, -$maximumTarget),
            $originalDenominator,
        ];
        if (\in_array(null, $rangeBoundaries, true)) {
            return null;
        }

        $rootBound = 1.0;
        foreach ($rangeBoundaries as $polynomial) {
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)] === 0.0) {
                \array_pop($polynomial);
            }
            if (\count($polynomial) < 2) {
                continue;
            }
            $leading = \abs($polynomial[\array_key_last($polynomial)]);
            if ($leading === 0.0) {
                return null;
            }
            $ratio = 0.0;
            foreach ($polynomial as $degree => $coefficient) {
                if ($degree !== \array_key_last($polynomial)) {
                    $ratio = \max($ratio, \abs($coefficient) / $leading);
                }
            }
            $candidateBound = 1.0 + $ratio;
            if (!\is_finite($candidateBound)) {
                return null;
            }
            $rootBound = \max($rootBound, $candidateBound);
        }
        $rootBound += 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, $rootBound);
        if (!\is_finite($rootBound)) {
            return null;
        }
        $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            $searchLower = $lowerBound;
            $searchUpper = $upperBound;
        } else {
            $searchLower = \is_finite($lowerBound) ? \max($lowerBound, -$rootBound) : -$rootBound;
            $searchUpper = \is_finite($upperBound) ? \min($upperBound, $rootBound) : $rootBound;
        }
        if ($searchLower > $searchUpper) {
            return [];
        }

        $boundaries = [$searchLower, $searchUpper];
        $excludedRoots = [];
        foreach ($rangeBoundaries as $polynomial) {
            $roots = $this->solvePolynomialRootsInInterval(
                $polynomial,
                $searchLower,
                $searchUpper,
                $options,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $boundaries[] = $root->value;
                if ($polynomial === $originalDenominator) {
                    $excludedRoots[] = $root->value;
                }
            }
        }
        \sort($boundaries, SORT_NUMERIC);
        $uniqueBoundaries = [];
        foreach ($boundaries as $boundary) {
            $previous = $uniqueBoundaries[\array_key_last($uniqueBoundaries)] ?? null;
            if (
                $previous === null
                || \abs($boundary - $previous) > $options->positionTolerance($boundary, $previous)
            ) {
                $uniqueBoundaries[] = $boundary;
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $addRootsInFeasibleInterval = function (
            float $lower,
            float $upper,
        ) use (
            $equation,
            $variable,
            $parameters,
            $evaluationOptions,
            $options,
            $normalizedEquation,
            $leftNode,
            $rightNode,
            $rightSourceOffset,
            $numerator,
            $denominator,
            $originalDenominator,
            $polynomialSolver,
            $insideUnitInterval,
            $minimumTarget,
            $maximumTarget,
            $excludedRoots,
            &$solutions,
        ): bool {
            $targetValueAt = static function (float $value) use (
                $numerator,
                $denominator,
                $polynomialSolver,
            ): ?float {
                $top = $polynomialSolver->evaluatePolynomial($numerator, $value);
                $bottom = $polynomialSolver->evaluatePolynomial($denominator, $value);
                if ($top === null || $bottom === null || $bottom === 0.0) {
                    return null;
                }

                $target = $top / $bottom;

                return \is_finite($target) ? $target : null;
            };
            if ($lower === $upper) {
                $solveLower = $lower;
                $solveUpper = $upper;
                foreach ($excludedRoots as $excludedRoot) {
                    if (\abs($lower - $excludedRoot) <= $options->positionTolerance($lower, $excludedRoot)) {
                        return true;
                    }
                }
                if ($polynomialSolver->evaluatePolynomial($originalDenominator, $lower) === 0.0) {
                    return true;
                }
                $target = $targetValueAt($lower);
                if (
                    $target === null
                    || ($insideUnitInterval && ($target < $minimumTarget || $target > $maximumTarget))
                    || (!$insideUnitInterval && \abs($target) < 1.0)
                ) {
                    return true;
                }
                $roots = $this->solve(
                    $normalizedEquation,
                    $variable,
                    $lower,
                    $upper,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
            } else {
                $middle = $lower + (($upper - $lower) / 2.0);
                $target = $targetValueAt($middle);
                if ($target === null) {
                    return false;
                }
                if (
                    ($insideUnitInterval && ($target < $minimumTarget || $target > $maximumTarget))
                    || (!$insideUnitInterval && \abs($target) < 1.0)
                ) {
                    return true;
                }
                $solveLower = $lower;
                $solveUpper = $upper;
                foreach ($excludedRoots as $excludedRoot) {
                    if (\abs($lower - $excludedRoot) <= $options->positionTolerance($lower, $excludedRoot)) {
                        $solveLower = $this->adjacentFloat($excludedRoot, 1) ?? $solveLower;
                    }
                    if (\abs($upper - $excludedRoot) <= $options->positionTolerance($upper, $excludedRoot)) {
                        $solveUpper = $this->adjacentFloat($excludedRoot, -1) ?? $solveUpper;
                    }
                }
                if ($solveLower >= $solveUpper) {
                    return true;
                }
                $roots = $this->solve(
                    $normalizedEquation,
                    $variable,
                    $solveLower,
                    $solveUpper,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
            }
            foreach ($roots as $root) {
                $isExcluded = false;
                foreach ($excludedRoots as $excludedRoot) {
                    if (\abs($root->value - $excludedRoot) <= $options->positionTolerance($root->value, $excludedRoot)) {
                        $isExcluded = true;
                        break;
                    }
                }
                if (
                    $isExcluded
                    || $polynomialSolver->evaluatePolynomial($originalDenominator, $root->value) === 0.0
                ) {
                    continue;
                }
                $residual = $this->residualAt(
                    $leftNode,
                    $rightNode,
                    $rightSourceOffset,
                    $variable,
                    $root->value,
                    $parameters,
                    $evaluationOptions,
                );
                $scale = $this->residualScaleAt(
                    $leftNode,
                    $rightNode,
                    $rightSourceOffset,
                    $variable,
                    $root->value,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $residual !== null
                    && ($scale === null || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        static fn (float $_): float => $scale ?? 1.0,
                        $options,
                    ))
                ) {
                    $rootValue = $this->refineVerifiedEquationCandidate(
                        $root->value,
                        $residual,
                        fn (float $value): ?float => $this->residualAt(
                            $leftNode,
                            $rightNode,
                            $rightSourceOffset,
                            $variable,
                            $value,
                            $parameters,
                            $evaluationOptions,
                        ),
                        $root->value,
                        $solveLower,
                        $solveUpper,
                        $options,
                    );
                    $residual = $this->residualAt(
                        $leftNode,
                        $rightNode,
                        $rightSourceOffset,
                        $variable,
                        $rootValue,
                        $parameters,
                        $evaluationOptions,
                    );
                    $scale = $this->residualScaleAt(
                        $leftNode,
                        $rightNode,
                        $rightSourceOffset,
                        $variable,
                        $rootValue,
                        $parameters,
                        $evaluationOptions,
                    );
                    $root = new EquationSolution(
                        $rootValue,
                        $residual === null ? $root->residual : \abs($residual),
                        $root->iterations,
                    );
                }
                if (
                    $residual === null
                    || $scale === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        static fn (float $_): float => $scale,
                        $options,
                    )
                ) {
                    continue;
                }
                $root = new EquationSolution($root->value, \abs($residual), $root->iterations);
                $this->addSolution($solutions, $root, $options);
            }

            return true;
        };

        foreach ($uniqueBoundaries as $boundary) {
            if (!$addRootsInFeasibleInterval($boundary, $boundary)) {
                return null;
            }
        }
        for ($index = 0; $index + 1 < \count($uniqueBoundaries); ++$index) {
            if (!$addRootsInFeasibleInterval($uniqueBoundaries[$index], $uniqueBoundaries[$index + 1])) {
                return null;
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function rationalFunctionDifferenceSignAtInfinity(
        ExactRationalPolynomialExtractor $extractor,
        Node $node,
        float $level,
        int $direction,
    ): ?int {
        $levelNode = new NumberNode(
            \abs($level),
            \sprintf('%.17g', \abs($level)),
            $node->span(),
        );
        if ($level < 0.0) {
            $levelNode = new UnaryOperationNode(
                UnaryOperator::Minus,
                $levelNode,
                $node->span(),
            );
        }
        $difference = $extractor->rationalDifference($node, $levelNode);
        if ($difference === null) {
            return null;
        }
        [$numerator, $denominator] = $difference;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === '0') {
            \array_pop($denominator);
        }
        $numeratorLeading = $numerator[\array_key_last($numerator)] ?? '0';
        $denominatorLeading = $denominator[\array_key_last($denominator)] ?? '0';
        if ($denominatorLeading === '0') {
            return null;
        }
        if ($numeratorLeading === '0') {
            return 0;
        }

        $numeratorSign = \str_starts_with($numeratorLeading, '-') ? -1 : 1;
        $denominatorSign = \str_starts_with($denominatorLeading, '-') ? -1 : 1;
        if ($direction < 0 && (\count($numerator) - 1) % 2 === 1) {
            $numeratorSign *= -1;
        }
        if ($direction < 0 && (\count($denominator) - 1) % 2 === 1) {
            $denominatorSign *= -1;
        }

        return $numeratorSign * $denominatorSign;
    }

    /**
     * Restrict a polynomial trig target to its finite inverse-range intervals.
     *
     * @param list<float> $target
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedTrigonometricPolynomialTarget(
        string $equation,
        array $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        float $minimumTarget = -1.0,
        float $maximumTarget = 1.0,
        ?array $excludedDenominator = null,
    ): ?array {
        $polynomialSolver = new PolynomialSolver();
        $boundaries = [];
        foreach ([$minimumTarget, $maximumTarget] as $level) {
            $coefficients = $target;
            $coefficients[0] -= $level;
            while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
                \array_pop($coefficients);
            }
            if (\count($coefficients) < 2) {
                continue;
            }
            $leading = \abs($coefficients[\array_key_last($coefficients)]);
            $maximumRatio = 0.0;
            foreach ($coefficients as $index => $coefficient) {
                if ($index === \array_key_last($coefficients)) {
                    continue;
                }
                $maximumRatio = \max($maximumRatio, \abs($coefficient) / $leading);
            }
            $bound = 1.0 + $maximumRatio;
            if (!\is_finite($bound)) {
                return null;
            }
            $roots = $polynomialSolver->solve(
                $coefficients,
                -$bound,
                $bound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($coefficients, $value),
                $solverOptions,
                fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($coefficients, $value),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                if ($root->value >= $lowerBound && $root->value <= $upperBound) {
                    $boundaries[] = $root->value;
                }
            }
        }
        if ($excludedDenominator !== null && \count($excludedDenominator) > 1) {
            $denominatorRoots = $this->solvePolynomialRootsInInterval(
                $excludedDenominator,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($denominatorRoots === null) {
                return null;
            }
            foreach ($denominatorRoots as $root) {
                $boundaries[] = $root->value;
            }
        }
        if (\is_finite($lowerBound)) {
            $boundaries[] = $lowerBound;
        }
        if (\is_finite($upperBound)) {
            $boundaries[] = $upperBound;
        }
        \sort($boundaries, SORT_NUMERIC);
        $uniqueBoundaries = [];
        foreach ($boundaries as $boundary) {
            $previous = $uniqueBoundaries[\array_key_last($uniqueBoundaries)] ?? null;
            if (
                $previous === null
                || \abs($boundary - $previous) > $solverOptions->positionTolerance($boundary, $previous)
            ) {
                $uniqueBoundaries[] = $boundary;
            }
        }
        if ($uniqueBoundaries === []) {
            return [];
        }

        $candidateIntervals = [];
        foreach ($uniqueBoundaries as $boundary) {
            $candidateIntervals[] = [$boundary, $boundary];
        }
        for ($index = 0; $index + 1 < \count($uniqueBoundaries); ++$index) {
            $lower = $uniqueBoundaries[$index];
            $upper = $uniqueBoundaries[$index + 1];
            $middle = ($lower / 2.0) + ($upper / 2.0);
            $targetValue = $polynomialSolver->evaluatePolynomial($target, $middle);
            if (
                $targetValue !== null
                && $targetValue >= $minimumTarget
                && $targetValue <= $maximumTarget
            ) {
                $candidateIntervals[] = [$lower, $upper];
            }
        }

        $solutions = [];
        foreach ($candidateIntervals as [$lower, $upper]) {
            $solveLower = $lower;
            $solveUpper = $upper;
            if ($excludedDenominator !== null) {
                if ($polynomialSolver->evaluatePolynomial($excludedDenominator, $lower) === 0.0) {
                    $solveLower = $this->adjacentFloat($lower, 1) ?? $lower;
                }
                if ($polynomialSolver->evaluatePolynomial($excludedDenominator, $upper) === 0.0) {
                    $solveUpper = $this->adjacentFloat($upper, -1) ?? $upper;
                }
                if ($lower === $upper && $solveLower !== $lower) {
                    continue;
                }
                if ($solveLower > $solveUpper) {
                    continue;
                }
            }
            $roots = $this->solve(
                $equation,
                $variable,
                $solveLower,
                $solveUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($roots as $root) {
                if (
                    $excludedDenominator !== null
                    && $polynomialSolver->evaluatePolynomial($excludedDenominator, $root->value) === 0.0
                ) {
                    continue;
                }
                $this->addSolution($solutions, $root, $solverOptions);
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Conservatively bound arithmetic expressions built from bounded real functions.
     *
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function boundedTrigonometricExpressionRange(
        Node $node,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $range = $this->boundedTrigonometricExpressionRange(
                $node->operand,
                $parameters,
                $evaluationOptions,
            );
            if ($range === null || $node->operator === UnaryOperator::Plus) {
                return $range;
            }

            return [-$range[1], -$range[0]];
        }

        if ($node instanceof FunctionCallNode) {
            if ($evaluationOptions->functions->isBuiltIn($node->name)) {
                if ($node->name === 'atan2' && \count($node->arguments) === 2) {
                    $verticalRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[0],
                        $parameters,
                        $evaluationOptions,
                    );
                    $horizontalRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[1],
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($verticalRange === null || $horizontalRange === null) {
                        return [-\M_PI, \M_PI];
                    }
                    if (
                        ($horizontalRange[0] <= 0.0 && $horizontalRange[1] >= 0.0
                            && $verticalRange[0] <= 0.0 && $verticalRange[1] >= 0.0)
                        || ($horizontalRange[1] < 0.0
                            && $verticalRange[0] <= 0.0
                            && $verticalRange[1] >= 0.0)
                    ) {
                        return [-\M_PI, \M_PI];
                    }

                    $angles = [];
                    foreach ($verticalRange as $vertical) {
                        foreach ($horizontalRange as $horizontal) {
                            $angles[] = \atan2($vertical, $horizontal);
                        }
                    }
                    if (
                        $horizontalRange[0] <= 0.0
                        && $horizontalRange[1] >= 0.0
                        && $verticalRange[0] > 0.0
                    ) {
                        $angles[] = \M_PI / 2.0;
                    } elseif (
                        $horizontalRange[0] <= 0.0
                        && $horizontalRange[1] >= 0.0
                        && $verticalRange[1] < 0.0
                    ) {
                        $angles[] = -\M_PI / 2.0;
                    }
                    if (
                        $verticalRange[0] <= 0.0
                        && $verticalRange[1] >= 0.0
                        && $horizontalRange[0] > 0.0
                    ) {
                        $angles[] = 0.0;
                    }

                    $range = [\min(...$angles), \max(...$angles)];

                    return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
                }
                if (
                    \in_array($node->name, ['gammainc', 'gammaincc'], true)
                    && \count($node->arguments) === 2
                ) {
                    return [0.0, 1.0];
                }
                if (
                    \in_array($node->name, ['betainc', 'betaincc'], true)
                    && \count($node->arguments) === 3
                ) {
                    return [0.0, 1.0];
                }
                if ($node->name === 'log' && \count($node->arguments) === 2) {
                    $valueRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[0],
                        $parameters,
                        $evaluationOptions,
                    );
                    $baseRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[1],
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $valueRange !== null
                        && $baseRange !== null
                        && $valueRange[0] > 0.0
                        && $baseRange[0] > 0.0
                        && ($baseRange[1] < 1.0 || $baseRange[0] > 1.0)
                    ) {
                        $values = [];
                        foreach ($valueRange as $value) {
                            foreach ($baseRange as $base) {
                                $values[] = \log($value, $base);
                            }
                        }
                        $range = [\min(...$values), \max(...$values)];

                        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
                    }
                }
                if (\in_array($node->name, ['min', 'max'], true)) {
                    $argumentRanges = [];
                    foreach ($node->arguments as $argument) {
                        $argumentRange = $this->boundedTrigonometricExpressionRange(
                            $argument,
                            $parameters,
                            $evaluationOptions,
                        );
                        if ($argumentRange === null) {
                            return null;
                        }
                        $argumentRanges[] = $argumentRange;
                    }
                    if ($argumentRanges !== []) {
                        $range = $node->name === 'min'
                            ? [
                                \min(...\array_column($argumentRanges, 0)),
                                \min(...\array_column($argumentRanges, 1)),
                            ]
                            : [
                                \max(...\array_column($argumentRanges, 0)),
                                \max(...\array_column($argumentRanges, 1)),
                            ];

                        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
                    }
                }
                if ($node->name === 'hypot' && \count($node->arguments) === 2) {
                    $first = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[0],
                        $parameters,
                        $evaluationOptions,
                    );
                    $second = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[1],
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($first === null || $second === null) {
                        return null;
                    }
                    $firstMinimum = $first[0] <= 0.0 && $first[1] >= 0.0
                        ? 0.0
                        : \min(\abs($first[0]), \abs($first[1]));
                    $secondMinimum = $second[0] <= 0.0 && $second[1] >= 0.0
                        ? 0.0
                        : \min(\abs($second[0]), \abs($second[1]));
                    $range = [
                        \hypot($firstMinimum, $secondMinimum),
                        \hypot(
                            \max(\abs($first[0]), \abs($first[1])),
                            \max(\abs($second[0]), \abs($second[1])),
                        ),
                    ];

                    return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
                }
                if ($node->name === 'root' && \count($node->arguments) === 2) {
                    $baseRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[0],
                        $parameters,
                        $evaluationOptions,
                    );
                    $degreeRange = $this->boundedTrigonometricExpressionRange(
                        $node->arguments[1],
                        $parameters,
                        $evaluationOptions,
                    );
                    if (
                        $baseRange !== null
                        && $degreeRange !== null
                        && $degreeRange[0] === $degreeRange[1]
                        && \floor($degreeRange[0]) === $degreeRange[0]
                        && $degreeRange[0] !== 0.0
                        && \abs($degreeRange[0]) <= 9_007_199_254_740_991.0
                    ) {
                        $degree = (int) $degreeRange[0];
                        $absoluteDegree = \abs($degree);
                        if (
                            ($absoluteDegree % 2 === 0 && $baseRange[0] < 0.0)
                            || ($degree < 0 && $baseRange[0] <= 0.0 && $baseRange[1] >= 0.0)
                        ) {
                            return null;
                        }
                        $rootAt = static function (float $value) use ($degree, $absoluteDegree): float {
                            $root = \pow(\abs($value), 1.0 / $absoluteDegree);
                            if ($value < 0.0) {
                                $root *= -1.0;
                            }
                            if ($degree < 0) {
                                $root = 1.0 / $root;
                            }

                            return $root;
                        };
                        $range = $degree < 0
                            ? [$rootAt($baseRange[1]), $rootAt($baseRange[0])]
                            : [$rootAt($baseRange[0]), $rootAt($baseRange[1])];

                        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
                    }
                }
            }
            if (\count($node->arguments) === 1 && $evaluationOptions->functions->isBuiltIn($node->name)) {
                if (\in_array($node->name, ['sin', 'cos'], true)) {
                    return [-1.0, 1.0];
                }
                if (\in_array($node->name, ['tanh', 'erf'], true)) {
                    return [-1.0, 1.0];
                }
                if (\in_array($node->name, ['asin', 'arcsin'], true)) {
                    return [-\M_PI / 2.0, \M_PI / 2.0];
                }
                if (\in_array($node->name, ['acos', 'arccos'], true)) {
                    return [0.0, \M_PI];
                }
                if (\in_array($node->name, ['asec', 'acot'], true)) {
                    return [0.0, \M_PI];
                }
                if ($node->name === 'acsc') {
                    return [-\M_PI / 2.0, \M_PI / 2.0];
                }
                if ($node->name === 'erfc') {
                    return [0.0, 2.0];
                }
                if ($node->name === 'sech') {
                    return [0.0, 1.0];
                }
                if (\in_array($node->name, ['atan', 'arctan'], true)) {
                    return [
                        $this->adjacentFloat(-\M_PI / 2.0, -1) ?? -\M_PI / 2.0,
                        $this->adjacentFloat(\M_PI / 2.0, 1) ?? \M_PI / 2.0,
                    ];
                }
                $argumentRange = $this->boundedTrigonometricExpressionRange(
                    $node->arguments[0],
                    $parameters,
                    $evaluationOptions,
                );
                if ($argumentRange !== null) {
                    [$minimum, $maximum] = $argumentRange;
                    $range = match ($node->name) {
                        'sign' => [
                            $minimum < 0.0 ? -1.0 : ($minimum === 0.0 ? 0.0 : 1.0),
                            $maximum > 0.0 ? 1.0 : ($maximum === 0.0 ? 0.0 : -1.0),
                        ],
                        'abs' => $minimum <= 0.0 && $maximum >= 0.0
                            ? [0.0, \max(\abs($minimum), \abs($maximum))]
                            : [\min(\abs($minimum), \abs($maximum)), \max(\abs($minimum), \abs($maximum))],
                        'cbrt' => [self::realCubeRoot($minimum), self::realCubeRoot($maximum)],
                        'sqrt' => $minimum >= 0.0
                            ? [\sqrt($minimum), \sqrt($maximum)]
                            : null,
                        'asin', 'arcsin' => $minimum >= -1.0 && $maximum <= 1.0
                            ? [\asin($minimum), \asin($maximum)]
                            : null,
                        'acos', 'arccos' => $minimum >= -1.0 && $maximum <= 1.0
                            ? [\acos($maximum), \acos($minimum)]
                            : null,
                        'tanh' => [\tanh($minimum), \tanh($maximum)],
                        'atan', 'arctan' => [\atan($minimum), \atan($maximum)],
                        'asinh', 'arcsinh' => [\asinh($minimum), \asinh($maximum)],
                        'sinh' => [\sinh($minimum), \sinh($maximum)],
                        'exp' => [\exp($minimum), \exp($maximum)],
                        'expm1' => [\expm1($minimum), \expm1($maximum)],
                        'erf' => [SpecialFunctions::erf($minimum), SpecialFunctions::erf($maximum)],
                        'erfc' => [SpecialFunctions::erfc($maximum), SpecialFunctions::erfc($minimum)],
                        'ln' => $minimum > 0.0
                            ? [\log($minimum), \log($maximum)]
                            : null,
                        'log2' => $minimum > 0.0
                            ? [\log($minimum, 2.0), \log($maximum, 2.0)]
                            : null,
                        'log10' => $minimum > 0.0
                            ? [\log10($minimum), \log10($maximum)]
                            : null,
                        'log1p' => $minimum > -1.0
                            ? [\log1p($minimum), \log1p($maximum)]
                            : null,
                        'cosh' => [
                            $minimum <= 0.0 && $maximum >= 0.0
                                ? 1.0
                                : \min(\cosh($minimum), \cosh($maximum)),
                            \max(\cosh($minimum), \cosh($maximum)),
                        ],
                        'sech' => [
                            1.0 / \max(\cosh($minimum), \cosh($maximum)),
                            $minimum <= 0.0 && $maximum >= 0.0
                                ? 1.0
                                : 1.0 / \min(\cosh($minimum), \cosh($maximum)),
                        ],
                        'tan' => $this->boundedTangentRange($minimum, $maximum),
                        'sinc' => $this->sincIntervalRange($minimum, $maximum, 1.0),
                        'sincpi' => $this->sincIntervalRange($minimum, $maximum, \M_PI),
                        'cot' => $this->boundedCotangentRange($minimum, $maximum),
                        'sec' => $this->boundedSecantRange($minimum, $maximum),
                        'csc' => $this->boundedCosecantRange($minimum, $maximum),
                        'csch', 'coth' => $minimum > 0.0 || $maximum < 0.0
                            ? [
                                $node->name === 'csch'
                                    ? 1.0 / \sinh($maximum)
                                    : 1.0 / \tanh($maximum),
                                $node->name === 'csch'
                                    ? 1.0 / \sinh($minimum)
                                    : 1.0 / \tanh($minimum),
                            ]
                            : null,
                        'floor' => [(float) \floor($minimum), (float) \floor($maximum)],
                        'ceil' => [(float) \ceil($minimum), (float) \ceil($maximum)],
                        'trunc' => [
                            $minimum < 0.0 ? \ceil($minimum) : \floor($minimum),
                            $maximum < 0.0 ? \ceil($maximum) : \floor($maximum),
                        ],
                        'round' => [(float) \round($minimum), (float) \round($maximum)],
                        default => null,
                    };
                    if (
                        $range !== null
                        && \is_finite($range[0])
                        && \is_finite($range[1])
                    ) {
                        return $range;
                    }
                }
            }

            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $constant !== null && \is_finite($constant)
                ? [$constant, $constant]
                : null;
        }

        if (!$node instanceof BinaryOperationNode) {
            $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $constant !== null && \is_finite($constant)
                ? [$constant, $constant]
                : null;
        }

        $left = $this->boundedTrigonometricExpressionRange(
            $node->left,
            $parameters,
            $evaluationOptions,
        );
        $right = $this->boundedTrigonometricExpressionRange(
            $node->right,
            $parameters,
            $evaluationOptions,
        );
        if ($left === null || $right === null) {
            return null;
        }

        if ($node->operator === BinaryOperator::Add) {
            $range = [$left[0] + $right[0], $left[1] + $right[1]];
        } elseif ($node->operator === BinaryOperator::Subtract) {
            $range = [$left[0] - $right[1], $left[1] - $right[0]];
        } elseif ($node->operator === BinaryOperator::Multiply) {
            $products = [
                $left[0] * $right[0],
                $left[0] * $right[1],
                $left[1] * $right[0],
                $left[1] * $right[1],
            ];
            $range = [\min(...$products), \max(...$products)];
        } elseif ($node->operator === BinaryOperator::Divide) {
            if ($right[0] <= 0.0 && $right[1] >= 0.0) {
                return null;
            }
            $reciprocals = [1.0 / $right[0], 1.0 / $right[1]];
            $quotients = [
                $left[0] * $reciprocals[0],
                $left[0] * $reciprocals[1],
                $left[1] * $reciprocals[0],
                $left[1] * $reciprocals[1],
            ];
            $range = [\min(...$quotients), \max(...$quotients)];
        } elseif (
            $node->operator === BinaryOperator::Power
            && $right[0] === $right[1]
            && \floor($right[0]) === $right[0]
            && \abs($right[0]) <= 1024.0
        ) {
            $exponent = (int) $right[0];
            if ($exponent < 0 && $left[0] <= 0.0 && $left[1] >= 0.0) {
                return null;
            }
            $positiveExponent = \abs($exponent);
            if ($positiveExponent % 2 === 0) {
                $maximumMagnitude = \max(\abs($left[0]), \abs($left[1])) ** $positiveExponent;
                $minimumMagnitude = $left[0] <= 0.0 && $left[1] >= 0.0
                    ? 0.0
                    : \min(\abs($left[0]), \abs($left[1])) ** $positiveExponent;
                $range = [$minimumMagnitude, $maximumMagnitude];
            } else {
                $powered = [
                    $left[0] ** $positiveExponent,
                    $left[1] ** $positiveExponent,
                ];
                $range = [\min(...$powered), \max(...$powered)];
            }
            if ($exponent < 0) {
                $reciprocals = [1.0 / $range[0], 1.0 / $range[1]];
                $range = [\min(...$reciprocals), \max(...$reciprocals)];
            }
        } elseif (
            $node->operator === BinaryOperator::Power
            && $right[0] === $right[1]
            && $left[0] >= 0.0
        ) {
            $exponent = $right[0];
            if ($exponent < 0.0 && $left[0] <= 0.0) {
                return null;
            }
            $powered = [$left[0] ** $exponent, $left[1] ** $exponent];
            $range = [\min(...$powered), \max(...$powered)];
        } else {
            return null;
        }

        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
    }

    /** @return array{float, float}|null */
    private function boundedTangentRange(float $lower, float $upper): ?array
    {
        if ($this->containsPeriodicLevel($lower, $upper, \M_PI / 2.0, \M_PI)) {
            return null;
        }

        $range = [\tan($lower), \tan($upper)];

        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
    }

    /** @return array{float, float}|null */
    private function boundedCotangentRange(float $lower, float $upper): ?array
    {
        if ($this->containsPeriodicLevel($lower, $upper, 0.0, \M_PI)) {
            return null;
        }

        $range = [\cos($upper) / \sin($upper), \cos($lower) / \sin($lower)];

        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
    }

    /** @return array{float, float}|null */
    private function boundedSecantRange(float $lower, float $upper): ?array
    {
        if ($this->containsPeriodicLevel($lower, $upper, \M_PI / 2.0, \M_PI)) {
            return null;
        }

        $cosineValues = [\cos($lower), \cos($upper)];
        if ($this->containsPeriodicLevel($lower, $upper, 0.0, 2.0 * \M_PI)) {
            $cosineValues[] = 1.0;
        }
        if ($this->containsPeriodicLevel($lower, $upper, \M_PI, 2.0 * \M_PI)) {
            $cosineValues[] = -1.0;
        }
        $minimumCosine = \min(...$cosineValues);
        $maximumCosine = \max(...$cosineValues);
        if ($minimumCosine <= 0.0 && $maximumCosine >= 0.0) {
            return null;
        }

        $reciprocals = [1.0 / $minimumCosine, 1.0 / $maximumCosine];
        $range = [\min(...$reciprocals), \max(...$reciprocals)];

        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
    }

    /** @return array{float, float}|null */
    private function boundedCosecantRange(float $lower, float $upper): ?array
    {
        if ($this->containsPeriodicLevel($lower, $upper, 0.0, \M_PI)) {
            return null;
        }

        $sineValues = [\sin($lower), \sin($upper)];
        if ($this->containsPeriodicLevel($lower, $upper, \M_PI / 2.0, 2.0 * \M_PI)) {
            $sineValues[] = 1.0;
        }
        if ($this->containsPeriodicLevel($lower, $upper, -\M_PI / 2.0, 2.0 * \M_PI)) {
            $sineValues[] = -1.0;
        }
        $minimumSine = \min(...$sineValues);
        $maximumSine = \max(...$sineValues);
        if ($minimumSine <= 0.0 && $maximumSine >= 0.0) {
            return null;
        }

        $reciprocals = [1.0 / $minimumSine, 1.0 / $maximumSine];
        $range = [\min(...$reciprocals), \max(...$reciprocals)];

        return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
    }

    private function containsPeriodicLevel(
        float $lower,
        float $upper,
        float $offset,
        float $period,
    ): bool {
        if (\max(\abs($lower), \abs($upper)) > 1.0E12) {
            return true;
        }

        $firstIndex = \ceil(($lower - $offset) / $period);
        $lastIndex = \floor(($upper - $offset) / $period);

        return $firstIndex <= $lastIndex;
    }

    private function positiveLambertWFromLog(float $logArgument): float
    {
        $value = \max(1.0, $logArgument - \log(\max(1.0, $logArgument)));
        for ($iteration = 0; $iteration < 32; ++$iteration) {
            $correction = ($value + \log($value) - $logArgument) / (1.0 + (1.0 / $value));
            $next = $value - $correction;
            if (!\is_finite($next) || $next <= 0.0 || $next === $value) {
                break;
            }
            $value = $next;
        }

        return $value;
    }

    private function negativeLambertWMinusOneFromLog(float $logAbsoluteArgument): float
    {
        $target = -$logAbsoluteArgument;
        $magnitude = $target + \log($target);
        for ($iteration = 0; $iteration < 32; ++$iteration) {
            $correction = ($magnitude - \log($magnitude) - $target) / (1.0 - (1.0 / $magnitude));
            $next = $magnitude - $correction;
            if (!\is_finite($next) || $next <= 1.0 || $next === $magnitude) {
                break;
            }
            $magnitude = $next;
        }

        return -$magnitude;
    }

    /**
     * @param list<float> $roots
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>
     */
    private function verifiedAffineExponentialRoots(
        array $roots,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        $solutions = [];
        foreach ($roots as $root) {
            if (!\is_finite($root) || $root < $lowerBound || $root > $upperBound) {
                continue;
            }
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $root,
                $parameters,
                $evaluationOptions,
            );
            $scale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $root,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residual === null
                || $scale === null
                || !$this->isResidualAcceptableAt(
                    $root,
                    $residual,
                    static fn (float $value): float => $scale,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution($solutions, new EquationSolution($root, \abs($residual), 0), $solverOptions);
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int => $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce full-line min/max levels of a polynomial-phase periodic function.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPiecewisePeriodicLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if ($lowerBound !== -\INF || $upperBound !== \INF) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $leftSource, $right, $rightSource, 0],
                [$right, $rightSource, $left, $leftSource, $rightSourceOffset],
            ] as [
                $piecewiseSide,
                $piecewiseSource,
                $targetSide,
                $targetSource,
                $piecewiseSourceOffset,
            ]
        ) {
            $piecewiseSide = $this->unwrapGrouping($piecewiseSide);
            if (
                !$piecewiseSide instanceof FunctionCallNode
                || !\in_array($piecewiseSide->name, ['min', 'max'], true)
                || \count($piecewiseSide->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($piecewiseSide->name)
            ) {
                continue;
            }

            $targetCoefficients = $this->extractPolynomial(
                $extractor,
                $targetSide,
                $targetSide->span()->start,
            );
            if (
                $targetCoefficients === null
                || \count($targetCoefficients) !== 1
                || !\is_finite($targetCoefficients[0])
            ) {
                continue;
            }
            $target = $targetCoefficients[0];

            foreach ([[0, 1], [1, 0]] as [$periodicIndex, $constantIndex]) {
                $periodicExpression = $this->unwrapGrouping($piecewiseSide->arguments[$periodicIndex]);
                $periodic = $periodicExpression;
                $absolutePeriodic = false;
                if (
                    $periodic instanceof FunctionCallNode
                    && $periodic->name === 'abs'
                    && \count($periodic->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn('abs')
                ) {
                    $absolutePeriodic = true;
                    $periodic = $this->unwrapGrouping($periodic->arguments[0]);
                }
                if (
                    !$periodic instanceof FunctionCallNode
                    || !\in_array($periodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                    || \count($periodic->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn($periodic->name)
                ) {
                    continue;
                }
                $phase = $this->extractPolynomial(
                    $extractor,
                    $periodic->arguments[0],
                    $periodic->arguments[0]->span()->start,
                );
                $constantCoefficients = $this->extractPolynomial(
                    $extractor,
                    $piecewiseSide->arguments[$constantIndex],
                    $piecewiseSide->arguments[$constantIndex]->span()->start,
                );
                if (
                    $phase === null
                    || \count($phase) < 2
                    || $constantCoefficients === null
                    || \count($constantCoefficients) !== 1
                    || !\is_finite($constantCoefficients[0])
                ) {
                    continue;
                }

                $constant = $constantCoefficients[0];
                if ($target === $constant) {
                    [$minimum, $maximum] = match ($periodic->name) {
                        'sin', 'cos' => $absolutePeriodic ? [0.0, 1.0] : [-1.0, 1.0],
                        'tan', 'cot' => $absolutePeriodic ? [0.0, \INF] : [-\INF, \INF],
                        'sec', 'csc' => $absolutePeriodic ? [1.0, \INF] : [-\INF, \INF],
                    };
                    $hasSolutions = $piecewiseSide->name === 'min'
                        ? $constant <= $maximum
                        : $constant >= $minimum;
                    if (!$hasSolutions) {
                        return [];
                    }

                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions on the requested unbounded interval.',
                    );
                }

                $periodicLevelIsFeasible = $piecewiseSide->name === 'min'
                    ? $target < $constant
                    : $target > $constant;
                if (!$periodicLevelIsFeasible) {
                    return [];
                }

                if ($absolutePeriodic) {
                    $levelIsInRange = match ($periodic->name) {
                        'sin', 'cos' => $target >= 0.0 && $target <= 1.0,
                        'tan', 'cot' => $target >= 0.0,
                        'sec', 'csc' => $target >= 1.0,
                    };
                    if (!$levelIsInRange) {
                        return [];
                    }

                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions on the requested unbounded interval.',
                    );
                }

                $periodicSpan = $periodicExpression->span();
                $periodicSource = \substr(
                    $piecewiseSource,
                    $periodicSpan->start - $piecewiseSourceOffset,
                    $periodicSpan->end - $periodicSpan->start,
                );
                if ($periodicSource === '') {
                    return null;
                }
                $levelEquation = '(' . $periodicSource . ')=(' . $targetSource . ')';
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }

                return $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }
        }

        return null;
    }

    /**
     * Reduce absolute levels of built-in min/max polynomial expressions to signed branches.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAbsolutePiecewisePolynomial(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        foreach (
            [
                [$left, $right, $leftSource, $rightSource, true, 0],
                [$right, $left, $rightSource, $leftSource, false, 0],
            ] as [
                $absoluteSide,
                $targetSide,
                $absoluteSource,
                $targetSource,
                $absoluteOnLeft,
                $absoluteSourceOffset,
            ]
        ) {
            $absolute = $this->unwrapGrouping($absoluteSide);
            if (
                !$absolute instanceof FunctionCallNode
                || $absolute->name !== 'abs'
                || \count($absolute->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('abs')
            ) {
                continue;
            }
            $piecewise = $this->unwrapGrouping($absolute->arguments[0]);
            $targetRange = $this->boundedTrigonometricExpressionRange(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                !$piecewise instanceof FunctionCallNode
                || !\in_array($piecewise->name, ['min', 'max'], true)
                || \count($piecewise->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($piecewise->name)
                || $targetRange === null
                || !\is_finite($targetRange[0])
                || !\is_finite($targetRange[1])
                || $targetRange[0] < 0.0
            ) {
                continue;
            }

            $piecewiseSpan = $piecewise->span();
            $piecewiseSourceText = \substr(
                $absoluteSource,
                $piecewiseSpan->start - $absoluteSourceOffset,
                $piecewiseSpan->end - $piecewiseSpan->start,
            );
            if ($piecewiseSourceText === '') {
                return null;
            }

            $levels = [1.0];
            if ($targetRange[0] !== 0.0 || $targetRange[1] !== 0.0) {
                $levels[] = -1.0;
            }
            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($levels as $sign) {
                $signedTarget = $sign > 0.0
                    ? '(' . $targetSource . ')'
                    : '(-1)*(' . $targetSource . ')';
                $equation = $absoluteOnLeft
                    ? '(' . $piecewiseSourceText . ')=(' . $signedTarget . ')'
                    : '(' . $signedTarget . ')=(' . $piecewiseSourceText . ')';
                if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $candidates = $this->solve(
                    $equation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Partition min/max expressions with a polynomial and a continuous bounded-function branch.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPiecewisePolynomialBoundedBranch(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, true, 0],
                [$right, $left, $rightSource, $leftSource, false, $rightOffset],
            ] as [
                $piecewiseSide,
                $targetSide,
                $piecewiseSource,
                $targetSource,
                $piecewiseOnLeft,
                $piecewiseSourceOffset,
            ]
        ) {
            $piecewise = $this->unwrapGrouping($piecewiseSide);
            $targetRange = $this->boundedTrigonometricExpressionRange(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                !$piecewise instanceof FunctionCallNode
                || !\in_array($piecewise->name, ['min', 'max'], true)
                || \count($piecewise->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($piecewise->name)
                || $targetRange === null
                || !\is_finite($targetRange[0])
                || !\is_finite($targetRange[1])
            ) {
                continue;
            }

            foreach ([[0, 1], [1, 0]] as [$polynomialIndex, $boundedIndex]) {
                $polynomial = $extractor->extract($piecewise->arguments[$polynomialIndex]);
                $boundedBranch = $piecewise->arguments[$boundedIndex];
                $boundedRange = $this->boundedTrigonometricExpressionRange(
                    $boundedBranch,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    $polynomial === null
                    || \count($polynomial) < 2
                    || !$this->containsFunctionCall($boundedBranch)
                    || !$this->containsVariable($boundedBranch, $variable)
                    || $boundedRange === null
                    || !\is_finite($boundedRange[0])
                    || !\is_finite($boundedRange[1])
                    || !$this->isContinuousBoundedFunctionTree($boundedBranch, $evaluationOptions)
                ) {
                    continue;
                }

                $polynomialSpan = $piecewise->arguments[$polynomialIndex]->span();
                $boundedSpan = $piecewise->arguments[$boundedIndex]->span();
                $polynomialSource = \substr(
                    $piecewiseSource,
                    $polynomialSpan->start - $piecewiseSourceOffset,
                    $polynomialSpan->end - $polynomialSpan->start,
                );
                $boundedSource = \substr(
                    $piecewiseSource,
                    $boundedSpan->start - $piecewiseSourceOffset,
                    $boundedSpan->end - $boundedSpan->start,
                );
                if ($polynomialSource === '' || $boundedSource === '') {
                    return null;
                }

                $crossingEquation = '(' . $polynomialSource . ')=(' . $boundedSource . ')';
                if (\strlen($crossingEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $crossings = $this->solve(
                        $crossingEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (\InvalidArgumentException) {
                    continue;
                }

                $cuts = \array_map(static fn (EquationSolution $root): float => $root->value, $crossings);
                if (\is_finite($lowerBound)) {
                    $cuts[] = $lowerBound;
                }
                if (\is_finite($upperBound)) {
                    $cuts[] = $upperBound;
                }
                \sort($cuts, SORT_NUMERIC);
                $cuts = \array_values(\array_unique($cuts, SORT_REGULAR));
                if (\count($cuts) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                    return null;
                }

                $boundaries = $cuts;
                if ($lowerBound === -\INF) {
                    \array_unshift($boundaries, -\INF);
                }
                if ($upperBound === \INF) {
                    $boundaries[] = \INF;
                }
                if ($boundaries === []) {
                    $boundaries = [-\INF, \INF];
                }
                $intervals = [];
                for ($index = 0; $index + 1 < \count($boundaries); ++$index) {
                    $intervals[] = [$boundaries[$index], $boundaries[$index + 1]];
                }

                $residualAt = fn (float $value): ?float => $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                );
                $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $value,
                    $parameters,
                    $evaluationOptions,
                );
                $solutions = [];
                foreach ($intervals as [$intervalLower, $intervalUpper]) {
                    if ($intervalLower === -\INF && $intervalUpper === \INF) {
                        $sample = 0.0;
                    } elseif ($intervalLower === -\INF) {
                        $sample = $intervalUpper - \max(1.0, \abs($intervalUpper) * 0.5);
                    } elseif ($intervalUpper === \INF) {
                        $sample = $intervalLower + \max(1.0, \abs($intervalLower) * 0.5);
                    } else {
                        $sample = ($intervalLower / 2.0) + ($intervalUpper / 2.0);
                    }
                    $variables = [...$parameters, $variable => $sample];
                    try {
                        $firstValue = (float) $this->evaluateNode(
                            $piecewise->arguments[0],
                            $variables,
                            $evaluationOptions,
                        );
                        $secondValue = (float) $this->evaluateNode(
                            $piecewise->arguments[1],
                            $variables,
                            $evaluationOptions,
                        );
                    } catch (EvaluationException) {
                        return null;
                    }
                    if (!\is_finite($firstValue) || !\is_finite($secondValue)) {
                        return null;
                    }
                    $firstIsActive = $piecewise->name === 'min'
                        ? $firstValue <= $secondValue
                        : $firstValue >= $secondValue;
                    $activeIndex = $firstIsActive ? 0 : 1;
                    $activeSource = $activeIndex === $polynomialIndex ? $polynomialSource : $boundedSource;
                    $activePolynomial = $activeIndex === $polynomialIndex;
                    $activeEquation = $piecewiseOnLeft
                        ? '(' . $activeSource . ')=(' . $targetSource . ')'
                        : '(' . $targetSource . ')=(' . $activeSource . ')';
                    if (\strlen($activeEquation) > $evaluationOptions->limits->maxExpressionLength) {
                        return null;
                    }

                    $solveLowerBound = $intervalLower;
                    $solveUpperBound = $intervalUpper;
                    if (
                        $activePolynomial
                        && (!\is_finite($intervalLower) || !\is_finite($intervalUpper))
                    ) {
                        $rangeBoundaryRoots = [];
                        foreach (\array_unique($targetRange, SORT_REGULAR) as $rangeBoundary) {
                            $boundaryEquation = '(' . $polynomialSource . ')=('
                                . \sprintf('%.17g', $rangeBoundary) . ')';
                            try {
                                $boundaryRoots = $this->solve(
                                    $boundaryEquation,
                                    $variable,
                                    $lowerBound,
                                    $upperBound,
                                    $parameters,
                                    $evaluationOptions,
                                    $solverOptions,
                                );
                            } catch (\InvalidArgumentException) {
                                return null;
                            }
                            foreach ($boundaryRoots as $boundaryRoot) {
                                $rangeBoundaryRoots[] = $boundaryRoot->value;
                            }
                        }
                        if ($rangeBoundaryRoots === []) {
                            continue;
                        }
                        $solveLowerBound = \max($intervalLower, \min($rangeBoundaryRoots));
                        $solveUpperBound = \min($intervalUpper, \max($rangeBoundaryRoots));
                        if ($solveLowerBound > $solveUpperBound) {
                            continue;
                        }
                    }

                    try {
                        $candidates = $this->solve(
                            $activeEquation,
                            $variable,
                            $solveLowerBound,
                            $solveUpperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (\InvalidArgumentException) {
                        return null;
                    }
                    foreach ($candidates as $candidate) {
                        $residual = $residualAt($candidate->value);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                            $solverOptions,
                        );
                    }
                }
                foreach ($cuts as $cut) {
                    $residual = $residualAt($cut);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt($cut, $residual, $candidateScaleAt, $solverOptions)
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($cut, \abs($residual), 0),
                        $solverOptions,
                    );
                }

                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }
        }

        return null;
    }

    private function isContinuousBoundedFunctionTree(
        Node $node,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof NumberNode || $node instanceof ConstantNode || $node instanceof VariableNode) {
            return true;
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->isContinuousBoundedFunctionTree($node->operand, $evaluationOptions);
        }
        if ($node instanceof BinaryOperationNode) {
            return \in_array(
                $node->operator,
                [BinaryOperator::Add, BinaryOperator::Subtract, BinaryOperator::Multiply],
                true,
            ) && $this->isContinuousBoundedFunctionTree($node->left, $evaluationOptions)
                && $this->isContinuousBoundedFunctionTree($node->right, $evaluationOptions);
        }
        if (!$node instanceof FunctionCallNode || !$evaluationOptions->functions->isBuiltIn($node->name)) {
            return false;
        }
        if (\in_array($node->name, ['min', 'max', 'hypot'], true) && $node->arguments !== []) {
            foreach ($node->arguments as $argument) {
                if (!$this->isContinuousBoundedFunctionTree($argument, $evaluationOptions)) {
                    return false;
                }
            }

            return true;
        }
        if (
            !\in_array(
                $node->name,
                ['sin', 'cos', 'tanh', 'atan', 'arctan', 'erf', 'erfc', 'abs', 'asin', 'arcsin', 'acos', 'arccos'],
                true,
            )
            || \count($node->arguments) !== 1
        ) {
            return false;
        }

        return $this->isContinuousBoundedFunctionTree($node->arguments[0], $evaluationOptions);
    }

    /**
     * Solve min/max expressions that switch between polynomial branches against bounded targets.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPiecewisePolynomialBoundedTarget(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0, true],
                [$right, $left, $rightSource, $leftSource, 0, false],
            ] as [
                $piecewiseSide,
                $targetSide,
                $piecewiseSource,
                $targetSource,
                $piecewiseSourceOffset,
                $piecewiseOnLeft,
            ]
        ) {
            $piecewise = $this->unwrapGrouping($piecewiseSide);
            $targetRange = $this->boundedTrigonometricExpressionRange(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                !$piecewise instanceof FunctionCallNode
                || !\in_array($piecewise->name, ['min', 'max'], true)
                || \count($piecewise->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($piecewise->name)
                || $targetRange === null
                || !\is_finite($targetRange[0])
                || !\is_finite($targetRange[1])
            ) {
                continue;
            }

            $firstPolynomial = $extractor->extract($piecewise->arguments[0]);
            $secondPolynomial = $extractor->extract($piecewise->arguments[1]);
            if (
                $firstPolynomial === null
                || $secondPolynomial === null
                || (\count($firstPolynomial) < 2 && \count($secondPolynomial) < 2)
            ) {
                continue;
            }
            $firstSpan = $piecewise->arguments[0]->span();
            $secondSpan = $piecewise->arguments[1]->span();
            $branchSources = [
                \substr(
                    $piecewiseSource,
                    $firstSpan->start - $piecewiseSourceOffset,
                    $firstSpan->end - $firstSpan->start,
                ),
                \substr(
                    $piecewiseSource,
                    $secondSpan->start - $piecewiseSourceOffset,
                    $secondSpan->end - $secondSpan->start,
                ),
            ];
            if ($branchSources[0] === '' || $branchSources[1] === '') {
                return null;
            }

            $difference = $this->subtractScaledPolynomials($firstPolynomial, $secondPolynomial, 1.0);
            if ($difference === null) {
                continue;
            }
            $crossings = [];
            if (\count($difference) > 1) {
                $crossingEquation = '(' . $branchSources[0] . ')=(' . $branchSources[1] . ')';
                if (\strlen($crossingEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $crossings = $this->solve(
                    $crossingEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            }
            $cuts = \array_map(static fn (EquationSolution $root): float => $root->value, $crossings);
            if (\is_finite($lowerBound)) {
                $cuts[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $cuts[] = $upperBound;
            }
            \sort($cuts, SORT_NUMERIC);
            $cuts = \array_values(\array_unique($cuts, SORT_REGULAR));
            if (\count($cuts) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                return null;
            }

            $boundaries = $cuts;
            if ($lowerBound === -\INF) {
                \array_unshift($boundaries, -\INF);
            }
            if ($upperBound === \INF) {
                $boundaries[] = \INF;
            }
            if ($boundaries === []) {
                $boundaries = [-\INF, \INF];
            }
            $intervals = [];
            for ($index = 0; $index + 1 < \count($boundaries); ++$index) {
                $intervals[] = [$boundaries[$index], $boundaries[$index + 1]];
            }

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($intervals as [$intervalLower, $intervalUpper]) {
                if ($intervalLower === -\INF && $intervalUpper === \INF) {
                    $sample = 0.0;
                } elseif ($intervalLower === -\INF) {
                    $sample = $intervalUpper - \max(1.0, \abs($intervalUpper) * 0.5);
                } elseif ($intervalUpper === \INF) {
                    $sample = $intervalLower + \max(1.0, \abs($intervalLower) * 0.5);
                } else {
                    $sample = ($intervalLower / 2.0) + ($intervalUpper / 2.0);
                }
                $firstValue = $this->polynomialValue($firstPolynomial, $sample);
                $secondValue = $this->polynomialValue($secondPolynomial, $sample);
                if ($firstValue === null || $secondValue === null) {
                    return null;
                }
                $firstIsActive = $piecewise->name === 'min'
                    ? $firstValue <= $secondValue
                    : $firstValue >= $secondValue;
                $activeIndex = $firstIsActive ? 0 : 1;
                $activeSource = $branchSources[$activeIndex];
                $activePolynomial = $activeIndex === 0 ? $firstPolynomial : $secondPolynomial;
                if (\count($activePolynomial) === 1 && !$this->containsVariable($targetSide, $variable)) {
                    try {
                        $targetValue = (float) $this->evaluateNode(
                            $targetSide,
                            $parameters,
                            $evaluationOptions,
                        );
                    } catch (EvaluationException) {
                        continue;
                    }
                    if (($activePolynomial[0] ?? 0.0) === $targetValue) {
                        throw new InfiniteSolutionSetException(
                            'A constant active min/max branch equals the target on an interval of solutions.',
                        );
                    }

                    continue;
                }
                if (
                    \strlen($activeSource) + \strlen($targetSource) + 5
                    > $evaluationOptions->limits->maxExpressionLength
                ) {
                    return null;
                }
                $activeEquation = $piecewiseOnLeft
                    ? '(' . $activeSource . ')=(' . $targetSource . ')'
                    : '(' . $targetSource . ')=(' . $activeSource . ')';
                $solveLowerBound = $intervalLower;
                $solveUpperBound = $intervalUpper;
                if (
                    (\count($activePolynomial) > 1)
                    && (!\is_finite($intervalLower) || !\is_finite($intervalUpper))
                ) {
                    $rangeBoundaryRoots = [];
                    foreach (\array_unique($targetRange, SORT_REGULAR) as $rangeBoundary) {
                        $boundaryEquation = '(' . $activeSource . ')=(' . \sprintf('%.17g', $rangeBoundary) . ')';
                        if (\strlen($boundaryEquation) > $evaluationOptions->limits->maxExpressionLength) {
                            return null;
                        }
                        $boundaryRoots = $this->solve(
                            $boundaryEquation,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                        foreach ($boundaryRoots as $boundaryRoot) {
                            $rangeBoundaryRoots[] = $boundaryRoot->value;
                        }
                    }
                    if ($rangeBoundaryRoots === []) {
                        continue;
                    }
                    $solveLowerBound = \max($intervalLower, \min($rangeBoundaryRoots));
                    $solveUpperBound = \min($intervalUpper, \max($rangeBoundaryRoots));
                    if ($solveLowerBound > $solveUpperBound) {
                        continue;
                    }
                }
                $candidates = $this->solve(
                    $activeEquation,
                    $variable,
                    $solveLowerBound,
                    $solveUpperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    $scale = $candidateScaleAt($candidate->value);
                    if (
                        $residual === null
                        || $scale === null
                        || (
                            !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                            && \abs($residual)
                                > $solverOptions->residualTolerance * \max(1.0, $scale)
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }
            foreach ($cuts as $cut) {
                $residual = $residualAt($cut);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt($cut, $residual, $candidateScaleAt, $solverOptions)
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($cut, \abs($residual), 0),
                    $solverOptions,
                );
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Enumerate finite integer modulo levels against strictly monotone bounded functions.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedModuloMonotoneLevels(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        foreach (
            [
                [$left, $right, $rightSource],
                [$right, $left, $leftSource],
            ] as [$moduloSide, $targetSide, $targetSource]
        ) {
            $modulo = $this->unwrapGrouping($moduloSide);
            $target = $this->unwrapGrouping($targetSide);
            if (
                !$modulo instanceof BinaryOperationNode
                || $modulo->operator !== BinaryOperator::Modulo
                || !$target instanceof FunctionCallNode
                || !\in_array($target->name, ['tanh', 'atan', 'arctan', 'erf', 'erfc'], true)
                || \count($target->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($target->name)
                || !$this->containsVariable($modulo->left, $variable)
                || $this->containsVariable($modulo->right, $variable)
                || !$this->containsVariable($target, $variable)
            ) {
                continue;
            }

            $extractor = new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
            $phase = $extractor->extract($target->arguments[0]);
            if ($phase === null || \count($phase) < 2) {
                continue;
            }
            try {
                $divisor = (float) $this->evaluateNode($modulo->right, $parameters, $evaluationOptions);
            } catch (EvaluationException) {
                continue;
            }
            $period = \abs($divisor);
            if (
                !\is_finite($period)
                || $period < 1.0
                || \floor($period) !== $period
                || $period > ((self::MAX_DISCRETE_INTERVAL_COMBINATIONS + 1) / 2)
            ) {
                continue;
            }

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            $maximumRemainder = (int) $period - 1;
            for ($remainder = -$maximumRemainder; $remainder <= $maximumRemainder; ++$remainder) {
                $levelEquation = '(' . $targetSource . ')=(' . $remainder . ')';
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $candidates = $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve polynomial sign levels against expressions with a bounded range.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    /**
     * Enumerate min/max and absolute-value branches, then verify roots against the original equation.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPiecewiseBranchEquations(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftExpanded = false;
        $rightExpanded = false;
        $leftBranches = $this->piecewiseBranchExpressions(
            $left,
            $leftSource,
            0,
            $evaluationOptions,
            $leftExpanded,
        );
        $rightBranches = $this->piecewiseBranchExpressions(
            $right,
            $rightSource,
            0,
            $evaluationOptions,
            $rightExpanded,
        );
        if (!$leftExpanded && !$rightExpanded) {
            return null;
        }
        if (
            $leftBranches === []
            || $rightBranches === []
            || \count($leftBranches) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS
            || \count($rightBranches) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS
            || \count($leftBranches) > intdiv(
                self::MAX_DISCRETE_INTERVAL_COMBINATIONS,
                \count($rightBranches),
            )
        ) {
            return null;
        }

        $leftBranches = \array_values(\array_unique($leftBranches));
        $rightBranches = \array_values(\array_unique($rightBranches));
        $solutions = [];
        $hasConstantIdentityBranch = false;
        foreach ($leftBranches as $leftBranch) {
            foreach ($rightBranches as $rightBranch) {
                $leftHasVariable = \preg_match(
                    '/(?<![A-Za-z0-9_])' . \preg_quote($variable, '/') . '(?![A-Za-z0-9_])/',
                    $leftBranch,
                ) === 1;
                $rightHasVariable = \preg_match(
                    '/(?<![A-Za-z0-9_])' . \preg_quote($variable, '/') . '(?![A-Za-z0-9_])/',
                    $rightBranch,
                ) === 1;
                if (!$leftHasVariable && !$rightHasVariable) {
                    try {
                        $leftValue = (float) $this->evaluateNode(
                            $this->parseSide($leftBranch, 0, $evaluationOptions),
                            $parameters,
                            $evaluationOptions,
                        );
                        $rightValue = (float) $this->evaluateNode(
                            $this->parseSide($rightBranch, 0, $evaluationOptions),
                            $parameters,
                            $evaluationOptions,
                        );
                    } catch (EvaluationException) {
                        return null;
                    }
                    if ($leftValue === $rightValue) {
                        $hasConstantIdentityBranch = true;
                    }

                    continue;
                }
                $branchEquation = '(' . $leftBranch . ')=(' . $rightBranch . ')';
                if (\strlen($branchEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $candidates = $this->solve(
                        $branchEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (
                    RootSearchLimitException
                    | EvaluationException
                    | ParseException
                    | \DomainException
                    | \InvalidArgumentException
                ) {
                    return null;
                }
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }
        }
        if ($hasConstantIdentityBranch) {
            $transitionCuts = [];
            foreach ([$leftBranches, $rightBranches] as $branches) {
                foreach ($branches as $branch) {
                    $branchNode = $this->parseSide($branch, 0, $evaluationOptions);
                    $branchForm = (new PolynomialExtractor(
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions->maxPolynomialDegree,
                    ))->extractRationalForm($branchNode);
                    if ($branchForm === null || $branchForm[1] === [0.0]) {
                        return null;
                    }
                    $poleRoots = $this->realPolynomialRootsInInterval(
                        $branchForm[1],
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($poleRoots === null) {
                        return null;
                    }
                    foreach ($poleRoots as $pole) {
                        $transitionCuts[] = $pole;
                    }
                }
                for ($firstIndex = 0; $firstIndex < \count($branches); ++$firstIndex) {
                    for ($secondIndex = $firstIndex + 1; $secondIndex < \count($branches); ++$secondIndex) {
                        $firstBranch = $branches[$firstIndex];
                        $secondBranch = $branches[$secondIndex];
                        if ($firstBranch === $secondBranch) {
                            continue;
                        }
                        $variablePattern = '/(?<![A-Za-z0-9_])'
                            . \preg_quote($variable, '/')
                            . '(?![A-Za-z0-9_])/';
                        if (
                            \preg_match($variablePattern, $firstBranch) !== 1
                            && \preg_match($variablePattern, $secondBranch) !== 1
                        ) {
                            continue;
                        }
                        try {
                            $crossings = $this->solve(
                                '(' . $firstBranch . ')=(' . $secondBranch . ')',
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $solverOptions,
                            );
                        } catch (RootSearchLimitException | \DomainException | \InvalidArgumentException) {
                            return null;
                        }
                        foreach ($crossings as $crossing) {
                            $transitionCuts[] = $crossing->value;
                        }
                    }
                }
            }
            if (\is_finite($lowerBound)) {
                $transitionCuts[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $transitionCuts[] = $upperBound;
            }
            \sort($transitionCuts, SORT_NUMERIC);
            $transitionCuts = \array_values(\array_unique($transitionCuts, SORT_REGULAR));
            if (\count($transitionCuts) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                return null;
            }
            $boundaries = $transitionCuts;
            if ($lowerBound === -\INF) {
                \array_unshift($boundaries, -\INF);
            }
            if ($upperBound === \INF) {
                $boundaries[] = \INF;
            }
            if ($boundaries === []) {
                $boundaries = [-\INF, \INF];
            }
            for ($index = 1; $index < \count($boundaries); ++$index) {
                $intervalLower = $boundaries[$index - 1];
                $intervalUpper = $boundaries[$index];
                if ($intervalLower >= $intervalUpper) {
                    continue;
                }
                $sample = match (true) {
                    $intervalLower === -\INF && $intervalUpper === \INF => 0.0,
                    $intervalLower === -\INF => $intervalUpper - \max(1.0, 0.5 * \abs($intervalUpper)),
                    $intervalUpper === \INF => $intervalLower + \max(1.0, 0.5 * \abs($intervalLower)),
                    default => ($intervalLower / 2.0) + ($intervalUpper / 2.0),
                };
                $residual = $residualAt($sample);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $sample,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    throw new InfiniteSolutionSetException(
                        'A constant active min/max or absolute-value branch equals the target on an interval.',
                    );
                }
            }
            foreach ($transitionCuts as $cut) {
                $residual = $residualAt($cut);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt($cut, $residual, $candidateScaleAt, $solverOptions)
                ) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($cut, \abs($residual), 0),
                        $solverOptions,
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return list<string>
     */
    private function piecewiseBranchExpressions(
        Node $node,
        string $source,
        int $sourceOffset,
        EvaluationOptions $evaluationOptions,
        bool &$expanded,
    ): array {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['min', 'max'], true)
            && \count($node->arguments) >= 2
            && $evaluationOptions->functions->isBuiltIn($node->name)
        ) {
            $expanded = true;
            $branches = [];
            foreach ($node->arguments as $argument) {
                $branches = [
                    ...$branches,
                    ...$this->piecewiseBranchExpressions(
                        $argument,
                        $source,
                        $sourceOffset,
                        $evaluationOptions,
                        $expanded,
                    ),
                ];
            }

            return $branches;
        }
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'abs'
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('abs')
        ) {
            $expanded = true;
            $branches = $this->piecewiseBranchExpressions(
                $node->arguments[0],
                $source,
                $sourceOffset,
                $evaluationOptions,
                $expanded,
            );
            $signedBranches = [];
            foreach ($branches as $branch) {
                $signedBranches[] = '(' . $branch . ')';
                $signedBranches[] = '-(' . $branch . ')';
            }

            return $signedBranches;
        }
        $span = $node->span();
        $expression = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);

        return $expression === '' ? [] : [$expression];
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialSignBoundedTarget(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0],
                [$right, $left, $rightSource, $leftSource, $rightOffset],
            ] as [$signSide, $targetSide, $signSource, $targetSource, $signSourceOffset]
        ) {
            $sign = $this->unwrapGrouping($signSide);
            if (
                !$sign instanceof FunctionCallNode
                || $sign->name !== 'sign'
                || \count($sign->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('sign')
                || !$this->containsVariable($targetSide, $variable)
            ) {
                continue;
            }
            $argument = $extractor->extract($sign->arguments[0]);
            $targetRange = $this->boundedTrigonometricExpressionRange(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $argument === null
                || \count($argument) < 2
                || $targetRange === null
                || !\is_finite($targetRange[0])
                || !\is_finite($targetRange[1])
            ) {
                continue;
            }

            $argumentSpan = $sign->arguments[0]->span();
            $argumentSource = \substr(
                $signSource,
                $argumentSpan->start - $signSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            if ($argumentSource === '') {
                return null;
            }
            $zeroEquation = '(' . $argumentSource . ')=0';
            if (\strlen($zeroEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $zeroRoots = $this->solve(
                $zeroEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            $cuts = \array_map(static fn (EquationSolution $root): float => $root->value, $zeroRoots);
            if (\is_finite($lowerBound)) {
                $cuts[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $cuts[] = $upperBound;
            }
            \sort($cuts, SORT_NUMERIC);
            $cuts = \array_values(\array_unique($cuts, SORT_REGULAR));
            if (\count($cuts) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                return null;
            }

            $boundaries = $cuts;
            if ($lowerBound === -\INF) {
                \array_unshift($boundaries, -\INF);
            }
            if ($upperBound === \INF) {
                $boundaries[] = \INF;
            }
            if ($boundaries === []) {
                $boundaries = [-\INF, \INF];
            }
            $intervals = [];
            for ($index = 0; $index + 1 < \count($boundaries); ++$index) {
                $intervals[] = [$boundaries[$index], $boundaries[$index + 1]];
            }

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            foreach ($intervals as [$intervalLower, $intervalUpper]) {
                if ($intervalLower === -\INF && $intervalUpper === \INF) {
                    $sample = 0.0;
                } elseif ($intervalLower === -\INF) {
                    $sample = $intervalUpper - \max(1.0, \abs($intervalUpper) * 0.5);
                } elseif ($intervalUpper === \INF) {
                    $sample = $intervalLower + \max(1.0, \abs($intervalLower) * 0.5);
                } else {
                    $sample = ($intervalLower / 2.0) + ($intervalUpper / 2.0);
                }
                $argumentValue = $this->polynomialValue($argument, $sample);
                if ($argumentValue === null) {
                    return null;
                }
                $level = $argumentValue <=> 0.0;
                if (
                    $level === 0
                    || $targetRange[0] > $level
                    || $targetRange[1] < $level
                ) {
                    continue;
                }
                $levelEquation = '(' . $targetSource . ')=(' . $level . ')';
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $candidates = $this->solve(
                    $levelEquation,
                    $variable,
                    $intervalLower,
                    $intervalUpper,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }
            foreach ($cuts as $cut) {
                $residual = $residualAt($cut);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt($cut, $residual, $candidateScaleAt, $solverOptions)
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($cut, \abs($residual), 0),
                    $solverOptions,
                );
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Enumerate finite quantizer levels and solve each level equation completely.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveFiniteQuantizerAgainstExpression(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }

        foreach (
            [[$left, $right, $leftSource, $rightSource], [$right, $left, $rightSource, $leftSource]]
            as [$quantizerSide, $targetSide, $quantizerSource, $targetSource]
        ) {
            $quantizer = $this->unwrapGrouping($quantizerSide);
            if (
                !$quantizer instanceof FunctionCallNode
                || !\in_array($quantizer->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || \count($quantizer->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($quantizer->name)
                || !$this->containsVariable($quantizer, $variable)
                || !$this->containsVariable($targetSide, $variable)
            ) {
                continue;
            }

            $extractor = new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
            $argumentRange = $this->boundedExpressionRange(
                $quantizer->arguments[0],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $argumentRange === null
                || !\is_finite($argumentRange[0])
                || !\is_finite($argumentRange[1])
                || \abs($argumentRange[0]) > 9_007_199_254_740_991.0
                || \abs($argumentRange[1]) > 9_007_199_254_740_991.0
            ) {
                continue;
            }

            $firstLevel = \floor($argumentRange[0]) - 1.0;
            $lastLevel = \ceil($argumentRange[1]) + 1.0;
            if (
                !\is_finite($firstLevel)
                || !\is_finite($lastLevel)
                || $lastLevel - $firstLevel + 1.0 > self::MAX_DOMAIN_BOUNDARY_PROBES
            ) {
                continue;
            }

            $definition = $evaluationOptions->functions->find($quantizer->name);
            if ($definition === null) {
                continue;
            }

            $solutions = [];
            for ($level = (int) $firstLevel; $level <= (int) $lastLevel; ++$level) {
                $levelSource = (string) $level;
                try {
                    $levelSolutions = $this->solve(
                        '(' . $targetSource . ')=(' . $levelSource . ')',
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (InfiniteSolutionSetException) {
                    return null;
                }

                foreach ($levelSolutions as $candidate) {
                    $candidateParameters = [$variable => $candidate->value] + $parameters;
                    try {
                        $argumentValue = (float) $this->evaluateNode(
                            $quantizer->arguments[0],
                            $candidateParameters,
                            $evaluationOptions,
                        );
                        $quantizedValue = $definition->invoke([$argumentValue]);
                    } catch (EvaluationException | \DomainException | \OverflowException | \InvalidArgumentException) {
                        continue;
                    }
                    if ((float) $quantizedValue !== (float) $level) {
                        continue;
                    }

                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $residualScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve polynomial or rational quantizers against constant integer targets on unbounded intervals.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialQuantizerConstantTarget(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach ([[$left, $right], [$right, $left]] as [$quantizerSide, $targetSide]) {
            $quantizer = $this->unwrapGrouping($quantizerSide);
            if (
                !$quantizer instanceof FunctionCallNode
                || !\in_array($quantizer->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || \count($quantizer->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($quantizer->name)
            ) {
                continue;
            }
            $argumentForm = $extractor->extractRationalForm($quantizer->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                $argumentForm === null
                || $target === null
                || \count($target) !== 1
                || !\is_finite($target[0])
                || $target[0] !== \round($target[0])
                || \abs($target[0]) > 9_007_199_254_740_991.0
            ) {
                continue;
            }

            [$numerator, $denominator] = $argumentForm;
            if ($denominator === [0.0]) {
                continue;
            }
            $level = $target[0];
            if (\count($numerator) === 1 && \count($denominator) === 1) {
                if ($denominator[0] === 0.0) {
                    continue;
                }
                $argumentValue = ($numerator[0] ?? 0.0) / $denominator[0];
                $quantizedValue = match ($quantizer->name) {
                    'floor' => \floor($argumentValue),
                    'ceil' => \ceil($argumentValue),
                    'round' => \round($argumentValue, 0, PHP_ROUND_HALF_UP),
                    'trunc' => $argumentValue < 0.0
                        ? \ceil($argumentValue)
                        : \floor($argumentValue),
                };
                if ($quantizedValue === $level) {
                    throw new InfiniteSolutionSetException(
                        'Constant polynomial quantizer equation is an identity on the requested interval.',
                    );
                }

                return [];
            }
            [$lowerLevel, $upperLevel] = match ($quantizer->name) {
                'floor' => [$level, $level + 1.0],
                'ceil' => [$level - 1.0, $level],
                'round' => [$level - 0.5, $level + 0.5],
                'trunc' => $level > 0.0
                    ? [$level, $level + 1.0]
                    : ($level < 0.0 ? [$level - 1.0, $level] : [-1.0, 1.0]),
            };
            $boundaries = [];
            foreach ([$lowerLevel, $upperLevel] as $argumentLevel) {
                $scaledDenominator = $this->scalePolynomialCoefficients($denominator, -$argumentLevel);
                if ($scaledDenominator === null) {
                    return null;
                }
                $levelPolynomial = $this->combinePolynomialCoefficients(
                    $numerator,
                    $scaledDenominator,
                    1.0,
                );
                if ($levelPolynomial === null) {
                    return null;
                }
                $roots = $this->realPolynomialRootsInInterval(
                    $levelPolynomial,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    $boundaries[] = $root;
                }
            }
            $poleRoots = $this->realPolynomialRootsInInterval(
                $denominator,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($poleRoots === null) {
                return null;
            }
            foreach ($poleRoots as $root) {
                $boundaries[] = $root;
            }
            \sort($boundaries, SORT_NUMERIC);
            $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));

            $intervalBoundaries = $boundaries;
            if ($lowerBound === -\INF) {
                \array_unshift($intervalBoundaries, -\INF);
            } else {
                $intervalBoundaries[] = $lowerBound;
                \sort($intervalBoundaries, SORT_NUMERIC);
            }
            if ($upperBound === \INF) {
                $intervalBoundaries[] = \INF;
            } else {
                $intervalBoundaries[] = $upperBound;
                \sort($intervalBoundaries, SORT_NUMERIC);
            }
            $intervalBoundaries = \array_values(\array_unique($intervalBoundaries, SORT_REGULAR));
            for ($index = 1, $count = \count($intervalBoundaries); $index < $count; ++$index) {
                $lower = $intervalBoundaries[$index - 1];
                $upper = $intervalBoundaries[$index];
                if ($lower >= $upper) {
                    continue;
                }
                $sample = match (true) {
                    $lower === -\INF && $upper === \INF => 0.0,
                    $lower === -\INF => $upper - \max(1.0, 0.5 * \abs($upper)),
                    $upper === \INF => $lower + \max(1.0, 0.5 * \abs($lower)),
                    default => ($lower / 2.0) + ($upper / 2.0),
                };
                $numeratorValue = $this->polynomialValue($numerator, $sample);
                $denominatorValue = $this->polynomialValue($denominator, $sample);
                if (
                    $numeratorValue === null
                    || $denominatorValue === null
                    || $denominatorValue === 0.0
                ) {
                    return null;
                }
                $argumentValue = $numeratorValue / $denominatorValue;
                if (!\is_finite($argumentValue)) {
                    return null;
                }
                $quantizedValue = match ($quantizer->name) {
                    'floor' => \floor($argumentValue),
                    'ceil' => \ceil($argumentValue),
                    'round' => \round($argumentValue, 0, PHP_ROUND_HALF_UP),
                    'trunc' => $argumentValue < 0.0
                        ? \ceil($argumentValue)
                        : \floor($argumentValue),
                };
                if ($quantizedValue === $level) {
                    throw new InfiniteSolutionSetException(
                        'Polynomial quantizer equation has infinitely many solutions on an open interval.',
                    );
                }
            }

            $solutions = [];
            foreach ($boundaries as $root) {
                $residual = $residualAt($root);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt($root, $residual, $candidateScaleAt, $solverOptions)
                ) {
                    continue;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($root, \abs($residual), 0),
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Enumerate polynomial quantizer levels when the opposite side has a bounded range.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    /**
     * Reduce pairs of symmetric quantizers whose arguments are negatives of each other.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedReflectedQuantizerPair(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $pairCases = [
            [$left, $right, $leftSource, 0],
            [$right, $left, $rightSource, $rightSourceOffset],
        ];
        foreach ($pairCases as [$pairSide, $targetSide, $pairSource, $pairSourceOffset]) {
            $pair = $this->unwrapGrouping($pairSide);
            if (
                !$pair instanceof BinaryOperationNode
                || !\in_array($pair->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
            ) {
                continue;
            }
            $first = $this->unwrapGrouping($pair->left);
            $second = $this->unwrapGrouping($pair->right);
            if (
                !$first instanceof FunctionCallNode
                || !$second instanceof FunctionCallNode
                || \count($first->arguments) !== 1
                || \count($second->arguments) !== 1
                || !\in_array($first->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || !\in_array($second->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || !$evaluationOptions->functions->isBuiltIn($first->name)
                || !$evaluationOptions->functions->isBuiltIn($second->name)
            ) {
                continue;
            }
            $target = $this->constantNodeValue($targetSide, $parameters, $evaluationOptions);
            if ($target === null || !\is_finite($target)) {
                continue;
            }
            $extractor = new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $options->maxPolynomialDegree,
            );
            $firstForm = $extractor->extractRationalForm($first->arguments[0]);
            $secondForm = $extractor->extractRationalForm($second->arguments[0]);
            if ($firstForm === null || $secondForm === null) {
                continue;
            }
            $firstProduct = $this->multiplyPolynomialCoefficients(
                $firstForm[0],
                $secondForm[1],
                $options->maxPolynomialDegree,
            );
            $secondProduct = $this->multiplyPolynomialCoefficients(
                $secondForm[0],
                $firstForm[1],
                $options->maxPolynomialDegree,
            );
            if ($firstProduct === null || $secondProduct === null) {
                continue;
            }
            $oppositeArguments = $this->trimPolynomialCoefficients(
                $this->combinePolynomialCoefficients($firstProduct, $secondProduct, 1.0) ?? [],
            );
            if ($oppositeArguments !== [0.0]) {
                continue;
            }
            $argumentSpan = $first->arguments[0]->span();
            $argumentSource = \substr(
                $pairSource,
                $argumentSpan->start - $pairSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            if ($argumentSource === '') {
                return null;
            }

            $secondName = match ($second->name) {
                'floor' => 'ceil',
                'ceil' => 'floor',
                'round' => 'round',
                'trunc' => 'trunc',
            };
            $firstCoefficient = 1.0;
            $secondCoefficient = $pair->operator === BinaryOperator::Add ? -1.0 : 1.0;
            $normalizedTarget = $target;

            if ($first->name === $secondName) {
                $coefficient = $firstCoefficient + $secondCoefficient;
                if ($coefficient === 0.0) {
                    if ($normalizedTarget === 0.0) {
                        throw new InfiniteSolutionSetException(
                            'Reflected quantizer values cancel identically on their defined domain.',
                        );
                    }

                    return [];
                }
                $level = $normalizedTarget / $coefficient;
                if (\floor($level) !== $level || \abs($level) > 9_007_199_254_740_991.0) {
                    return [];
                }
                $normalizedEquation = $first->name . '(' . $argumentSource . ')=' . \sprintf('%.0f', $level);
            } elseif (
                \in_array($first->name, ['floor', 'ceil'], true)
                && \in_array($secondName, ['floor', 'ceil'], true)
                && $first->name !== $secondName
                && $firstCoefficient === $secondCoefficient
            ) {
                $level = $normalizedTarget / $firstCoefficient;
                if (\floor($level) !== $level || \abs($level) > 9_007_199_254_740_991.0) {
                    return [];
                }
                $normalizedEquation = 'floor(' . $argumentSource . ')+ceil('
                    . $argumentSource . ')=' . \sprintf('%.0f', $level);
            } elseif (
                \in_array($first->name, ['floor', 'ceil'], true)
                && \in_array($secondName, ['floor', 'ceil'], true)
                && $first->name !== $secondName
                && $firstCoefficient === -$secondCoefficient
            ) {
                $integerLevels = $normalizedTarget === 0.0;
                $nonIntegerIntervals = $first->name === 'floor'
                    ? $normalizedTarget === -1.0
                    : $normalizedTarget === 1.0;
                if (!$integerLevels && !$nonIntegerIntervals) {
                    return [];
                }
                $argumentCoefficients = $extractor->extract($first->arguments[0]);
                if ($argumentCoefficients === null || \count($argumentCoefficients) < 2) {
                    if ($argumentCoefficients === null) {
                        return null;
                    }
                    $argumentValue = $argumentCoefficients[0] ?? 0.0;
                    $matches = $integerLevels
                        ? \floor($argumentValue) === $argumentValue
                        : \floor($argumentValue) !== $argumentValue;
                    if ($matches) {
                        throw new InfiniteSolutionSetException(
                            'Reflected quantizer equation holds throughout the requested unbounded interval.',
                        );
                    }

                    return [];
                }
                if ($integerLevels) {
                    throw new InfiniteSolutionSetException(
                        'A nonconstant polynomial reaches infinitely many integer quantizer levels.',
                    );
                }
                throw new InfiniteSolutionSetException(
                    'Reflected floor and ceiling values agree on infinitely many open intervals.',
                );
            } else {
                continue;
            }

            if (\strlen($normalizedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $levelSolutions = $this->solve(
                $normalizedEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            $solutions = [];
            foreach ($levelSolutions as $solution) {
                $residual = $residualAt($solution->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $solution->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($solution->value, \abs($residual), $solution->iterations),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedPolynomialQuantizerBoundedTarget(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $extractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0],
                [$right, $left, $rightSource, $leftSource, $rightOffset],
            ] as [
                $quantizerSide,
                $targetSide,
                $quantizerSource,
                $targetSource,
                $quantizerSourceOffset,
            ]
        ) {
            $quantizer = $this->unwrapGrouping($quantizerSide);
            if (
                !$quantizer instanceof FunctionCallNode
                || !\in_array($quantizer->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || \count($quantizer->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($quantizer->name)
                || !$this->containsVariable($targetSide, $variable)
            ) {
                continue;
            }
            $argument = $extractor->extract($quantizer->arguments[0]);
            $targetRange = $this->boundedTrigonometricExpressionRange(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $argument === null
                || \count($argument) < 2
                || $targetRange === null
                || !\is_finite($targetRange[0])
                || !\is_finite($targetRange[1])
            ) {
                continue;
            }
            if (!\is_finite($this->polynomialValue($argument, 0.0) ?? \NAN)) {
                continue;
            }

            $argumentSpan = $quantizer->arguments[0]->span();
            $argumentStart = $argumentSpan->start;
            $argumentLength = $argumentSpan->end - $argumentSpan->start;
            $argumentSource = \substr($quantizerSource, $argumentStart, $argumentLength);
            if ($argumentSource === '') {
                return null;
            }

            $firstLevel = \floor($targetRange[0]) - 1.0;
            $lastLevel = \ceil($targetRange[1]) + 1.0;
            $maximumExactInteger = 9_007_199_254_740_991.0;
            if (
                !\is_finite($firstLevel)
                || !\is_finite($lastLevel)
                || $firstLevel < -$maximumExactInteger
                || $lastLevel > $maximumExactInteger
                || $lastLevel - $firstLevel + 1 > self::MAX_DISCRETE_INTERVAL_COMBINATIONS
            ) {
                return null;
            }

            $residualAt = fn (float $value): ?float => $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $solutions = [];
            for ($level = (int) $firstLevel; $level <= (int) $lastLevel; ++$level) {
                [$lowerArgumentLevel, $upperArgumentLevel] = match ($quantizer->name) {
                    'floor' => [(float) $level, $level + 1.0],
                    'ceil' => [$level - 1.0, (float) $level],
                    'round' => [$level - 0.5, $level + 0.5],
                    'trunc' => $level > 0
                        ? [(float) $level, $level + 1.0]
                        : ($level < 0 ? [$level - 1.0, (float) $level] : [-1.0, 1.0]),
                };
                $cuts = [];
                foreach ([$lowerArgumentLevel, $upperArgumentLevel] as $boundaryLevel) {
                    $boundaryEquation = '(' . $argumentSource . ')=(' . \sprintf('%.17g', $boundaryLevel) . ')';
                    if (\strlen($boundaryEquation) > $evaluationOptions->limits->maxExpressionLength) {
                        return null;
                    }
                    $boundaryRoots = $this->solve(
                        $boundaryEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    foreach ($boundaryRoots as $root) {
                        $cuts[] = $root->value;
                    }
                }
                if (\is_finite($lowerBound)) {
                    $cuts[] = $lowerBound;
                }
                if (\is_finite($upperBound)) {
                    $cuts[] = $upperBound;
                }
                \sort($cuts, SORT_NUMERIC);
                $cuts = \array_values(\array_unique($cuts, SORT_REGULAR));
                if (\count($cuts) > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                    return null;
                }

                $levelEquation = '(' . $targetSource . ')=(' . $level . ')';
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $intervals = [];
                if ($lowerBound === -\INF && $upperBound === \INF && $cuts === []) {
                    $intervals[] = [-\INF, \INF];
                } else {
                    $boundaries = $cuts;
                    if ($lowerBound === -\INF) {
                        \array_unshift($boundaries, -\INF);
                    }
                    if ($upperBound === \INF) {
                        $boundaries[] = \INF;
                    }
                    for ($index = 0; $index + 1 < \count($boundaries); ++$index) {
                        $intervals[] = [$boundaries[$index], $boundaries[$index + 1]];
                    }
                    if (\count($boundaries) === 1 && $lowerBound !== -\INF && $upperBound !== \INF) {
                        $intervals[] = [$boundaries[0], $boundaries[0]];
                    }
                }
                foreach ($intervals as [$intervalLower, $intervalUpper]) {
                    if ($intervalLower === $intervalUpper) {
                        continue;
                    }
                    if ($intervalLower === -\INF && $intervalUpper === \INF) {
                        $sample = 0.0;
                    } elseif ($intervalLower === -\INF) {
                        $sample = $intervalUpper - \max(1.0, \abs($intervalUpper) * 0.5);
                    } elseif ($intervalUpper === \INF) {
                        $sample = $intervalLower + \max(1.0, \abs($intervalLower) * 0.5);
                    } else {
                        $sample = ($intervalLower / 2.0) + ($intervalUpper / 2.0);
                    }
                    $argumentValue = $this->polynomialValue($argument, $sample);
                    if ($argumentValue === null) {
                        return null;
                    }
                    $insideLevel = match ($quantizer->name) {
                        'floor' => $argumentValue >= $level && $argumentValue < $level + 1.0,
                        'ceil' => $argumentValue > $level - 1.0 && $argumentValue <= $level,
                        'round' => $argumentValue > $lowerArgumentLevel
                            && $argumentValue < $upperArgumentLevel,
                        'trunc' => $level > 0
                            ? $argumentValue >= $level && $argumentValue < $level + 1.0
                            : ($level < 0
                                ? $argumentValue > $level - 1.0 && $argumentValue <= $level
                                : $argumentValue > -1.0 && $argumentValue < 1.0),
                    };
                    if (!$insideLevel) {
                        continue;
                    }
                    if (!\is_finite($intervalLower) || !\is_finite($intervalUpper)) {
                        return null;
                    }
                    $candidates = $this->solve(
                        $levelEquation,
                        $variable,
                        $intervalLower,
                        $intervalUpper,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    foreach ($candidates as $candidate) {
                        $residual = $residualAt($candidate->value);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                            $solverOptions,
                        );
                    }
                }
                foreach ($cuts as $cut) {
                    $residual = $residualAt($cut);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt($cut, $residual, $candidateScaleAt, $solverOptions)
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($cut, \abs($residual), 0),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Classify fixed points of rounding functions when their polynomial argument is unbounded.
     *
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedQuantizedPolynomialIdentity(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$functionSide, $targetSide]) {
            $function = $this->unwrapGrouping($functionSide);
            if (
                !$function instanceof FunctionCallNode
                || !\in_array($function->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || \count($function->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($function->name)
            ) {
                continue;
            }
            $argumentCoefficients = $extractor->extract($function->arguments[0]);
            $targetCoefficients = $extractor->extract($targetSide);
            if ($argumentCoefficients === null || $targetCoefficients === null) {
                continue;
            }
            $difference = $this->subtractScaledPolynomials(
                $argumentCoefficients,
                $targetCoefficients,
                1.0,
            );
            if ($difference !== [0.0]) {
                continue;
            }
            if (\count($argumentCoefficients) > 1) {
                throw new InfiniteSolutionSetException(
                    'Rounding a nonconstant polynomial equals that polynomial at infinitely many points '
                    . 'on the requested unbounded interval.',
                );
            }
            $constant = $argumentCoefficients[0] ?? 0.0;
            if (\floor($constant) === $constant) {
                throw new InfiniteSolutionSetException(
                    'Rounding-function equation is an identity on the requested unbounded interval.',
                );
            }

            return [];
        }

        return null;
    }

    /**
     * Solve absolute-value equalities whose two branches are rational equations.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAbsoluteRationalEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, true, 0, $rightSourceOffset],
                [$right, $left, $rightSource, $leftSource, false, $rightSourceOffset, 0],
            ] as [
                $absoluteSide,
                $targetSide,
                $absoluteSource,
                $targetSource,
                $absoluteOnLeft,
                $absoluteSourceOffset,
                $targetSourceOffset,
            ]
        ) {
            $absoluteCall = $this->unwrapGrouping($absoluteSide);
            if (
                !$absoluteCall instanceof FunctionCallNode
                || $absoluteCall->name !== 'abs'
                || \count($absoluteCall->arguments) !== 1
            ) {
                continue;
            }
            $argument = $absoluteCall->arguments[0];
            $argumentCoefficients = $extractor->extract($argument);
            $targetCoefficients = $extractor->extract($targetSide);
            if ($argumentCoefficients !== null && $targetCoefficients !== null) {
                $positiveDifference = $this->subtractScaledPolynomials(
                    $argumentCoefficients,
                    $targetCoefficients,
                    1.0,
                );
                $negativeArgument = $this->scalePolynomialCoefficients($argumentCoefficients, -1.0);
                $negativeDifference = $negativeArgument === null
                    ? null
                    : $this->subtractScaledPolynomials($negativeArgument, $targetCoefficients, 1.0);
                if (
                    $positiveDifference === null
                    || $negativeDifference === null
                ) {
                    continue;
                }
                if ($positiveDifference === [0.0] || $negativeDifference === [0.0]) {
                    return $this->solveUnboundedAbsoluteRationalIdentity(
                        $targetCoefficients,
                        [1.0],
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                        $residualAt,
                        $candidateScaleAt,
                    );
                }
                $positiveRoots = $this->realPolynomialRootsInInterval(
                    $positiveDifference,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                $negativeRoots = $this->realPolynomialRootsInInterval(
                    $negativeDifference,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($positiveRoots !== null && $negativeRoots !== null) {
                    $solutions = [];
                    foreach ([...$positiveRoots, ...$negativeRoots] as $root) {
                        $residual = $residualAt($root);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $root,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($root, \abs($residual), 0),
                            $solverOptions,
                        );
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
            } else {
                $argumentRationalForm = $extractor->extractRationalForm($argument);
                $targetRationalForm = $extractor->extractRationalForm($targetSide);
                if ($argumentRationalForm === null || $targetRationalForm === null) {
                    continue;
                }
                $argumentProduct = $this->multiplyPolynomials(
                    $argumentRationalForm[0],
                    $targetRationalForm[1],
                );
                $targetProduct = $this->multiplyPolynomials(
                    $targetRationalForm[0],
                    $argumentRationalForm[1],
                );
                if ($argumentProduct === null || $targetProduct === null) {
                    continue;
                }
                $negativeArgumentProduct = $this->scalePolynomialCoefficients($argumentProduct, -1.0);
                $positiveDifference = $this->subtractScaledPolynomials(
                    $argumentProduct,
                    $targetProduct,
                    1.0,
                );
                $negativeDifference = $negativeArgumentProduct === null
                    ? null
                    : $this->subtractScaledPolynomials($negativeArgumentProduct, $targetProduct, 1.0);
                if (
                    $positiveDifference === null
                    || $negativeDifference === null
                ) {
                    continue;
                }
                if ($positiveDifference === [0.0] || $negativeDifference === [0.0]) {
                    return $this->solveUnboundedAbsoluteRationalIdentity(
                        $targetRationalForm[0],
                        $targetRationalForm[1],
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                        $residualAt,
                        $candidateScaleAt,
                    );
                }
                $positiveRoots = $this->realPolynomialRootsInInterval(
                    $positiveDifference,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                $negativeRoots = $this->realPolynomialRootsInInterval(
                    $negativeDifference,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($positiveRoots !== null && $negativeRoots !== null) {
                    $solutions = [];
                    foreach ([...$positiveRoots, ...$negativeRoots] as $root) {
                        $residual = $residualAt($root);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $root,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($root, \abs($residual), 0),
                            $solverOptions,
                        );
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
            }

            $argumentSpan = $argument->span();
            $targetSpan = $targetSide->span();
            $argumentExpression = \substr(
                $absoluteSource,
                $argumentSpan->start - $absoluteSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            $targetExpression = \substr(
                $targetSource,
                $targetSpan->start - $targetSourceOffset,
                $targetSpan->end - $targetSpan->start,
            );
            if ($argumentExpression === '' || $targetExpression === '') {
                continue;
            }
            $branchEquations = $absoluteOnLeft
                ? [
                    '(' . $argumentExpression . ')=(' . $targetExpression . ')',
                    '-(' . $argumentExpression . ')=(' . $targetExpression . ')',
                ]
                : [
                    '(' . $targetExpression . ')=(' . $argumentExpression . ')',
                    '(' . $targetExpression . ')=-(' . $argumentExpression . ')',
                ];
            $solutions = [];
            foreach ($branchEquations as $branchEquation) {
                if (\strlen($branchEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $candidates = $this->solve(
                        $branchEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (
                    InfiniteSolutionSetException
                    | EvaluationException
                    | \DomainException
                    | \InvalidArgumentException
                ) {
                    return null;
                }
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Classify an absolute-value equation when one signed branch is an identity.
     *
     * @param list<float> $targetNumerator
     * @param list<float> $targetDenominator
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedAbsoluteRationalIdentity(
        array $targetNumerator,
        array $targetDenominator,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        while (
            \count($targetNumerator) > 1
            && $targetNumerator[\array_key_last($targetNumerator)] === 0.0
        ) {
            \array_pop($targetNumerator);
        }
        while (
            \count($targetDenominator) > 1
            && $targetDenominator[\array_key_last($targetDenominator)] === 0.0
        ) {
            \array_pop($targetDenominator);
        }
        if ($targetDenominator === [0.0]) {
            return [];
        }
        if ($targetNumerator === [0.0]) {
            throw new InfiniteSolutionSetException(
                'Absolute-value equation is an identity on its defined real domain.',
            );
        }

        $targetRoots = $this->realPolynomialRootsInInterval(
            $targetNumerator,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        $poleRoots = $this->realPolynomialRootsInInterval(
            $targetDenominator,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        if ($targetRoots === null || $poleRoots === null) {
            return null;
        }
        $boundaries = [$lowerBound];
        foreach ([...$targetRoots, ...$poleRoots] as $root) {
            if ($root > $lowerBound && $root < $upperBound) {
                $boundaries[] = $root;
            }
        }
        $boundaries[] = $upperBound;
        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
        $polynomialSolver = new PolynomialSolver();
        for ($index = 1, $count = \count($boundaries); $index < $count; ++$index) {
            $lower = $boundaries[$index - 1];
            $upper = $boundaries[$index];
            if ($lower >= $upper) {
                continue;
            }
            $sample = match (true) {
                $lower === -\INF && $upper === \INF => 0.0,
                $lower === -\INF => $upper - \max(1.0, 0.5 * \abs($upper)),
                $upper === \INF => $lower + \max(1.0, 0.5 * \abs($lower)),
                default => ($lower / 2.0) + ($upper / 2.0),
            };
            $numerator = $polynomialSolver->evaluatePolynomial($targetNumerator, $sample);
            $denominator = $polynomialSolver->evaluatePolynomial($targetDenominator, $sample);
            if ($numerator === null || $denominator === null || $denominator === 0.0) {
                return null;
            }
            if (($numerator > 0.0) === ($denominator > 0.0)) {
                throw new InfiniteSolutionSetException(
                    'Absolute-value equation has infinitely many solutions where its target is positive.',
                );
            }
        }

        $solutions = [];
        foreach ($targetRoots as $root) {
            $residual = $residualAt($root);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($root, $residual, $candidateScaleAt, $solverOptions)
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root, \abs($residual), 0),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedHypotenuseEquation(
        string $equation,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        [$leftSource, $rightSource] = $this->splitEquation($equation);
        $function = $left instanceof FunctionCallNode && $left->name === 'hypot' ? $left : null;
        $target = $right;
        $functionSource = $leftSource;
        $targetSource = $rightSource;
        $functionSourceOffset = 0;
        $targetSourceOffset = $rightOffset;
        if ($function === null && $right instanceof FunctionCallNode && $right->name === 'hypot') {
            $function = $right;
            $target = $left;
            $functionSource = $rightSource;
            $targetSource = $leftSource;
            $functionSourceOffset = $rightOffset;
            $targetSourceOffset = 0;
        }
        if ($function === null || $function->arguments === []) {
            return null;
        }

        $target = $this->unwrapGrouping($target);
        if ($target instanceof UnaryOperationNode && $target->operator === UnaryOperator::Minus) {
            $exactPolynomialExtractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $solverOptions->maxPolynomialDegree,
                $evaluationOptions,
            );
            $positiveCoefficients = $exactPolynomialExtractor->difference(
                $target->operand,
                new NumberNode(0, '0', $target->span()),
            );
            if (
                $positiveCoefficients !== null
                && ($positiveCoefficients[0] ?? '0') !== '0'
                && ($positiveCoefficients[0][0] ?? '') !== '-'
                && $this->hasNonnegativeEvenPolynomialCoefficients($positiveCoefficients)
            ) {
                return [];
            }
        }

        $argumentSquares = [];
        foreach ($function->arguments as $argument) {
            $span = $argument->span();
            $argumentSquares[] = '(' . \substr(
                $functionSource,
                $span->start,
                $span->end - $span->start,
            ) . ')^2';
        }
        $targetSpan = $target->span();
        $targetText = \substr(
            $targetSource,
            $targetSpan->start,
            $targetSpan->end - $targetSpan->start,
        );
        $squaredEquation = \implode(' + ', $argumentSquares) . ' = (' . $targetText . ')^2';
        try {
            $squaredSolutions = $this->solve(
                $squaredEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException $exception) {
            throw $exception;
        } catch (\InvalidArgumentException) {
            return null;
        }

        $solutions = [];
        foreach ($squaredSolutions as $candidate) {
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $candidate->value,
                $parameters,
                $evaluationOptions,
            );
            $residualScale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $candidate->value,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residual === null
                || $residualScale === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    static fn (float $value): float => $residualScale,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addDistinctSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
            );
        }

        return $solutions;
    }

    /** @param list<string> $coefficients Exact integer-scaled coefficients. */
    private function hasNonnegativeEvenPolynomialCoefficients(array $coefficients): bool
    {
        foreach ($coefficients as $degree => $coefficient) {
            if (($coefficient[0] ?? '') === '-' || ($degree % 2 !== 0 && $coefficient !== '0')) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>
     */
    private function solveUnboundedRationalPolynomialEquation(
        string $equation,
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        $domainExtractor = new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if (
            $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $domainExtractor,
            )
            || $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $domainExtractor,
            )
            || $this->containsEverywhereUndefinedSquareRoot(
                $left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $domainExtractor,
                $evaluationOptions,
                $solverOptions,
            )
            || $this->containsEverywhereUndefinedSquareRoot(
                $right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $domainExtractor,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            return [];
        }

        $residualAt = fn (float $value): ?float => $this->residualAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $candidateScaleAt = fn (float $value): ?float => $this->residualScaleAt(
            $left,
            $right,
            $rightOffset,
            $variable,
            $value,
            $parameters,
            $evaluationOptions,
        );
        $logarithmPowerSolutions = $this->solveUnboundedLogarithmPowerEquation(
            $left,
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $parameters,
            $evaluationOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($logarithmPowerSolutions !== null) {
            return $logarithmPowerSolutions;
        }
        $exponentialPolynomialSolutions = $this->solveExponentialPolynomialEquation(
            $left,
            $right,
            new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            ),
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($exponentialPolynomialSolutions !== null) {
            return $exponentialPolynomialSolutions;
        }

        $rationalDifference = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->rationalDifference($left, $right);
        if ($rationalDifference === null) {
            throw new \InvalidArgumentException(
                'Unbounded intervals are supported only for exact rational-function equations.',
            );
        }

        [$numerator, $denominator] = $rationalDifference;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        if (\count(\array_filter($denominator, static fn (string $value): bool => $value !== '0')) === 0) {
            throw new \InvalidArgumentException('The rational equation is undefined for every real input.');
        }
        if (\count($numerator) === 1) {
            if ($numerator[0] === '0') {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions on its defined domain.',
                );
            }

            return [];
        }

        $integerArithmetic = new IntegerPolynomialExtractor('', [], $solverOptions->maxPolynomialDegree);
        $leadingDegree = \array_key_last($numerator);
        $leadingCoefficient = $numerator[$leadingDegree];
        $rootBound = 1.0;
        foreach ($numerator as $degree => $coefficient) {
            if ($degree === $leadingDegree) {
                continue;
            }
            $ratioUpperBound = $this->upperFloatBoundForIntegerRatio(
                \ltrim($coefficient, '-'),
                \ltrim($leadingCoefficient, '-'),
                $integerArithmetic,
            );
            if ($ratioUpperBound === null) {
                throw new \InvalidArgumentException(
                    'The exact polynomial root bound exceeds the finite floating-point range.',
                );
            }
            $candidateBound = 1.0 + $ratioUpperBound;
            $rootBound = \max(
                $rootBound,
                \is_finite($candidateBound) ? $candidateBound : \PHP_FLOAT_MAX,
            );
        }
        $outwardBound = $this->adjacentFloat($rootBound, 1);
        if ($outwardBound !== null) {
            $rootBound = $outwardBound;
        }

        $finiteLowerBound = \is_finite($lowerBound) ? \max($lowerBound, -$rootBound) : -$rootBound;
        $finiteUpperBound = \is_finite($upperBound) ? \min($upperBound, $rootBound) : $rootBound;
        if ($finiteLowerBound > $finiteUpperBound) {
            return [];
        }

        return $this->solve(
            $equation,
            $variable,
            $finiteLowerBound,
            $finiteUpperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
    }

    private function upperFloatBoundForIntegerRatio(
        string $numerator,
        string $denominator,
        IntegerPolynomialExtractor $integerArithmetic,
    ): ?float {
        if ($numerator === '0') {
            return 0.0;
        }

        $approximation = $integerArithmetic->ratio($numerator, $denominator);
        $candidate = match (true) {
            \is_float($approximation) => \abs($approximation),
            $approximation === false => $this->adjacentFloat(0.0, 1),
            default => \PHP_FLOAT_MAX,
        };
        if ($candidate === null) {
            return null;
        }

        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $candidateRatio = $this->positiveFloatAsExactRatio($candidate, $integerArithmetic);
            if ($candidateRatio === null) {
                return null;
            }
            $comparison = $integerArithmetic->compareIntegerRatioToFraction(
                $numerator,
                $denominator,
                $candidateRatio[0],
                $candidateRatio[1],
            );
            if ($comparison === null) {
                return null;
            }
            if ($comparison <= 0) {
                return $this->adjacentFloat($candidate, 1) ?? $candidate;
            }

            $candidate = $this->adjacentFloat($candidate, 1);
            if ($candidate === null) {
                return null;
            }
        }

        return null;
    }

    /**
     * @return array{string, string}|null Exact positive binary float as numerator/denominator.
     */
    private function positiveFloatAsExactRatio(
        float $value,
        IntegerPolynomialExtractor $integerArithmetic,
    ): ?array {
        if ($value < 0.0 || !\is_finite($value)) {
            return null;
        }
        if ($value === 0.0) {
            return ['0', '1'];
        }

        $packed = \unpack('Jvalue', \pack('E', $value));
        $bits = $packed['value'] ?? null;
        if (!\is_int($bits) || $bits < 0) {
            return null;
        }
        $exponent = ($bits >> 52) & 0x7ff;
        $fraction = $bits & 0x000fffffffffffff;
        $significand = $exponent === 0 ? $fraction : $fraction | (1 << 52);
        $binaryExponent = $exponent === 0 ? -1074 : $exponent - 1075;
        $powerOfTwo = '1';
        for ($power = 0; $power < \abs($binaryExponent); ++$power) {
            $powerOfTwo = $integerArithmetic->multiplyIntegerValues($powerOfTwo, '2');
        }

        $significandString = (string) $significand;

        return $binaryExponent >= 0
            ? [
                $integerArithmetic->multiplyIntegerValues($significandString, $powerOfTwo),
                '1',
            ]
            : [$significandString, $powerOfTwo];
    }

    /**
     * @param array{list<float>, list<float>} $baseForm
     * @return array{float, float}|null
     */
    private function logarithmBasePowerProduct(
        Node $node,
        array $baseForm,
        PolynomialExtractor $extractor,
        SolverOptions $options,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $form = $extractor->extractRationalForm($node);
            if ($form !== null) {
                $baseRatio = $this->approximatelyProportionalPolynomialRatio(
                    $this->multiplyPolynomials($form[0], $baseForm[1]),
                    $this->multiplyPolynomials($baseForm[0], $form[1]),
                );
                if ($baseRatio === 1.0) {
                    return [1.0, 1.0];
                }
            }

            $numerator = $this->logarithmBasePowerProduct(
                $node->left,
                $baseForm,
                $extractor,
                $options,
            );
            $denominator = $this->logarithmBasePowerProduct(
                $node->right,
                $baseForm,
                $extractor,
                $options,
            );
            if ($numerator === null || $denominator === null || $denominator[1] === 0.0) {
                return null;
            }
            $power = $numerator[0] - $denominator[0];
            $coefficient = $numerator[1] / $denominator[1];
            if (
                !\is_finite($power)
                || \abs($power) > $options->maxPolynomialDegree
                || !\is_finite($coefficient)
            ) {
                return null;
            }

            return [$power, $coefficient];
        }

        $factors = [];
        $this->flattenProductFactors($node, $factors);
        $power = 0.0;
        $powerMagnitude = 0.0;
        $coefficient = 1.0;
        foreach ($factors as $factor) {
            $factor = $this->unwrapGrouping($factor);
            $factorPower = null;
            $factorBaseNode = null;
            if ($factor instanceof BinaryOperationNode && $factor->operator === BinaryOperator::Power) {
                $exponent = $extractor->extract($factor->right);
                if (
                    $exponent === null
                    || \count($exponent) !== 1
                    || !\is_finite($exponent[0])
                    || $exponent[0] === 0.0
                    || \abs($exponent[0]) > $options->maxPolynomialDegree
                ) {
                    return null;
                }
                $factorPower = $exponent[0];
                $factorBaseNode = $factor->left;
            } elseif ($factor instanceof FunctionCallNode && $factor->name === 'sqrt') {
                if (\count($factor->arguments) !== 1) {
                    return null;
                }
                $factorPower = 0.5;
                $factorBaseNode = $factor->arguments[0];
            } elseif ($factor instanceof FunctionCallNode && $factor->name === 'cbrt') {
                if (\count($factor->arguments) !== 1) {
                    return null;
                }
                $factorPower = 1.0 / 3.0;
                $factorBaseNode = $factor->arguments[0];
            } elseif ($factor instanceof FunctionCallNode && $factor->name === 'root') {
                if (!isset($factor->arguments[0], $factor->arguments[1])) {
                    return null;
                }
                $degree = $extractor->extract($factor->arguments[1]);
                if (
                    $degree === null
                    || \count($degree) !== 1
                    || !\is_finite($degree[0])
                    || $degree[0] === 0.0
                ) {
                    return null;
                }
                $factorPower = 1.0 / $degree[0];
                $factorBaseNode = $factor->arguments[0];
            }

            if ($factorPower !== null) {
                if (\abs($factorPower) > $options->maxPolynomialDegree) {
                    return null;
                }
                $factorBase = $extractor->extractRationalForm($factorBaseNode);
                if ($factorBase === null) {
                    return null;
                }
                $baseRatio = $this->approximatelyProportionalPolynomialRatio(
                    $this->multiplyPolynomials($factorBase[0], $baseForm[1]),
                    $this->multiplyPolynomials($baseForm[0], $factorBase[1]),
                );
                if ($baseRatio === 1.0) {
                    if (\abs($factorPower) > $options->maxPolynomialDegree - $powerMagnitude) {
                        return null;
                    }
                    $power += $factorPower;
                    $powerMagnitude += \abs($factorPower);
                    continue;
                }
            }

            $form = $extractor->extractRationalForm($factor);
            if ($form === null) {
                return null;
            }
            $baseRatio = $this->approximatelyProportionalPolynomialRatio(
                $this->multiplyPolynomials($form[0], $baseForm[1]),
                $this->multiplyPolynomials($baseForm[0], $form[1]),
            );
            if ($baseRatio === 1.0) {
                if ($powerMagnitude >= $options->maxPolynomialDegree) {
                    return null;
                }
                $power += 1.0;
                $powerMagnitude += 1.0;
                continue;
            }

            $constantFactor = $this->proportionalPolynomialRatio($form[0], $form[1]);
            if ($constantFactor === null) {
                return null;
            }
            $coefficient *= $constantFactor;
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        return [$power, $coefficient];
    }

    private function logarithmPowersMatch(float $first, ?float $second): bool
    {
        if ($second === null) {
            return false;
        }

        return \abs($first - $second)
            <= 32.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($first), \abs($second));
    }

    /** @param list<array{Node, float}> $factors */
    private function flattenLogProductFactors(Node $node, float $sign, array &$factors): void
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Multiply) {
                $this->flattenLogProductFactors($node->left, $sign, $factors);
                $this->flattenLogProductFactors($node->right, $sign, $factors);

                return;
            }
            if (
                $node->operator === BinaryOperator::Divide
                && $this->containsLogarithmFactor($node->left)
            ) {
                $this->flattenLogProductFactors($node->left, $sign, $factors);
                $this->flattenLogProductFactors($node->right, -$sign, $factors);

                return;
            }
        }

        $factors[] = [$node, $sign];
    }

    private function containsLogarithmFactor(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode && \in_array($node->name, ['ln', 'log'], true)) {
            return true;
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Multiply
        ) {
            return $this->containsLogarithmFactor($node->left)
                || $this->containsLogarithmFactor($node->right);
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialTrigonometricEquality(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftSign = 1.0;
        $left = $this->unwrapGrouping($left);
        while ($left instanceof UnaryOperationNode) {
            if ($left->operator === UnaryOperator::Minus) {
                $leftSign *= -1.0;
            }
            $left = $this->unwrapGrouping($left->operand);
        }
        $rightSign = 1.0;
        $right = $this->unwrapGrouping($right);
        while ($right instanceof UnaryOperationNode) {
            if ($right->operator === UnaryOperator::Minus) {
                $rightSign *= -1.0;
            }
            $right = $this->unwrapGrouping($right->operand);
        }
        $relativeSign = $leftSign * $rightSign;
        $leftName = $left instanceof FunctionCallNode ? $left->name : '';
        $rightName = $right instanceof FunctionCallNode ? $right->name : '';
        $piPeriodicPair = \in_array($leftName, ['tan', 'cot'], true)
            && \in_array($rightName, ['tan', 'cot'], true);
        $samePiPeriodicPair = $piPeriodicPair && $leftName === $rightName;
        $mixedTangentCotangentPair = $piPeriodicPair && $leftName !== $rightName;
        $reciprocalTrigPair = \in_array($leftName, ['sec', 'csc'], true)
            && \in_array($rightName, ['sec', 'csc'], true);
        $directSinCosPair = \in_array($leftName, ['sin', 'cos'], true)
            && \in_array($rightName, ['sin', 'cos'], true);
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || (!$piPeriodicPair && !$reciprocalTrigPair && !$directSinCosPair)
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
            || (!$this->containsVariable($left, $variable)
                && !$this->containsVariable($right, $variable))
        ) {
            return null;
        }

        $leftArgument = $left->arguments[0];
        $rightArgument = $right->arguments[0];
        $leftForm = $extractor->extractRationalForm($leftArgument);
        $rightForm = $extractor->extractRationalForm($rightArgument);
        if ($leftForm === null || $rightForm === null) {
            return null;
        }

        $commonDenominator = $this->multiplyPolynomialCoefficients(
            $leftForm[1],
            $rightForm[1],
            $options->maxPolynomialDegree,
        );
        $leftProduct = $this->multiplyPolynomialCoefficients(
            $leftForm[0],
            $rightForm[1],
            $options->maxPolynomialDegree,
        );
        $rightProduct = $this->multiplyPolynomialCoefficients(
            $rightForm[0],
            $leftForm[1],
            $options->maxPolynomialDegree,
        );
        if ($commonDenominator === null || $leftProduct === null || $rightProduct === null) {
            return null;
        }
        $differenceNumerator = $this->combinePolynomialCoefficients($leftProduct, $rightProduct, -1.0);
        $sumNumerator = $this->combinePolynomialCoefficients($leftProduct, $rightProduct, 1.0);
        if ($differenceNumerator === null || $sumNumerator === null) {
            return null;
        }
        $difference = [$differenceNumerator, $commonDenominator];
        $sum = [$sumNumerator, $commonDenominator];

        $period = $piPeriodicPair ? \M_PI : 2.0 * \M_PI;
        if ($samePiPeriodicPair) {
            $families = $relativeSign > 0.0
                ? [[$difference, 0.0]]
                : [[$sum, 0.0]];
        } elseif ($mixedTangentCotangentPair) {
            if ($relativeSign > 0.0) {
                $families = [[$sum, \M_PI / 2.0]];
            } else {
                $differencePhase = $leftName === 'tan' ? -\M_PI / 2.0 : \M_PI / 2.0;
                $families = [[$difference, $differencePhase]];
            }
        } else {
            $leftPhaseFunction = match ($leftName) {
                'sec' => 'cos',
                'csc' => 'sin',
                default => $leftName,
            };
            $rightPhaseFunction = match ($rightName) {
                'sec' => 'cos',
                'csc' => 'sin',
                default => $rightName,
            };
            $mixedFunctions = $leftPhaseFunction !== $rightPhaseFunction;
            if ($mixedFunctions) {
                if ($leftPhaseFunction === 'sin') {
                    $differencePhase = $relativeSign > 0.0
                        ? \M_PI / 2.0
                        : -\M_PI / 2.0;
                } else {
                    $differencePhase = $relativeSign > 0.0
                        ? -\M_PI / 2.0
                        : \M_PI / 2.0;
                }
                $sumPhase = $relativeSign > 0.0 ? \M_PI / 2.0 : -\M_PI / 2.0;
            } elseif ($leftPhaseFunction === 'sin') {
                $differencePhase = $relativeSign > 0.0 ? 0.0 : \M_PI;
                $sumPhase = $relativeSign > 0.0 ? \M_PI : 0.0;
            } else {
                $differencePhase = $relativeSign > 0.0 ? 0.0 : \M_PI;
                $sumPhase = $relativeSign > 0.0 ? 0.0 : \M_PI;
            }
            $families = [
                [$difference, $differencePhase],
                [$sum, $sumPhase],
            ];
        }
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $levelCount = 0;
        foreach ($families as [$rationalForm, $phase]) {
            [$numerator, $denominator] = $rationalForm;
            $range = $this->rationalPolynomialRange(
                $numerator,
                $denominator,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($range === null) {
                return null;
            }
            [[$minimum, $maximum], $numerator, $denominator] = $range;
            $rangeTolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimum), \abs($maximum), \abs($phase));
            $firstPeriod = \ceil(($minimum - $phase - $rangeTolerance) / $period);
            $lastPeriod = \floor(($maximum - $phase + $rangeTolerance) / $period);
            if (
                !\is_finite($firstPeriod)
                || !\is_finite($lastPeriod)
                || \abs($firstPeriod) > 4_503_599_627_370_496.0
                || \abs($lastPeriod) > 4_503_599_627_370_496.0
                || $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS - $levelCount
            ) {
                return null;
            }

            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                ++$levelCount;
                $level = $phase + ($periodIndex * $period);
                $levelCoefficients = $this->combinePolynomialCoefficients(
                    $numerator,
                    $denominator,
                    -$level,
                );
                if ($levelCoefficients === null) {
                    return null;
                }
                try {
                    $levelSolutions = $polynomialSolver->solve(
                        $levelCoefficients,
                        $lowerBound,
                        $upperBound,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomial($levelCoefficients, $value),
                        $options,
                        static fn (float $value): ?float =>
                            $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value),
                    );
                } catch (\DomainException) {
                    if (
                        $this->rationalFormConstantValue($leftForm) !== null
                        && $this->rationalFormConstantValue($rightForm) !== null
                    ) {
                        $leftConstant = $this->rationalFormConstantValue($leftForm);
                        $rightConstant = $this->rationalFormConstantValue($rightForm);
                        if (
                            $leftConstant !== null
                            && $rightConstant !== null
                            && ($this->isTrigonometricPole($leftName, $leftConstant)
                                || $this->isTrigonometricPole($rightName, $rightConstant))
                        ) {
                            return [];
                        }
                        for ($sampleIndex = 1; $sampleIndex <= 257; ++$sampleIndex) {
                            $sample = $lowerBound
                                + (($upperBound - $lowerBound) * ($sampleIndex / 258.0));
                            $sampleVariables = [...$parameters, $variable => $sample];
                            try {
                                $leftValue = (float) $this->evaluateNode(
                                    $left,
                                    $sampleVariables,
                                    $evaluationOptions,
                                );
                                $rightValue = (float) $this->evaluateNode(
                                    $right,
                                    $sampleVariables,
                                    $evaluationOptions,
                                );
                            } catch (EvaluationException) {
                                continue;
                            }
                            if (
                                \is_finite($leftValue)
                                && \is_finite($rightValue)
                                && $this->isLocallyContinuous(
                                    $left,
                                    $sample,
                                    $evaluationOptions,
                                    $parameters,
                                    $variable,
                                )
                                && $this->isLocallyContinuous(
                                    $right,
                                    $sample,
                                    $evaluationOptions,
                                    $parameters,
                                    $variable,
                                )
                            ) {
                                throw new InfiniteSolutionSetException(
                                    'Equation has infinitely many solutions in the requested interval.',
                                );
                            }
                        }

                        return [];
                    }

                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                if ($levelSolutions === null) {
                    return null;
                }
                foreach ($levelSolutions as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if ($residual === null) {
                        continue;
                    }
                    if (
                        !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return null;
                    }
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                    );
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{base: Node, exponent: array{int, int}, coefficient: float, offset: float}|null
     */
    private function rationalPowerProductInfo(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $offset = 0.0;
        $coefficient = 0.0;
        $powerTerms = [];
        $terms = [[$node, 1.0]];
        while ($terms !== []) {
            [$term, $sign] = \array_pop($terms);
            $term = $this->unwrapGrouping($term);
            if ($term instanceof UnaryOperationNode) {
                $terms[] = [
                    $term->operand,
                    $sign * ($term->operator === UnaryOperator::Minus ? -1.0 : 1.0),
                ];
                continue;
            }
            if ($term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Add) {
                $terms[] = [$term->left, $sign];
                $terms[] = [$term->right, $sign];
                continue;
            }
            if ($term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Subtract) {
                $terms[] = [$term->left, $sign];
                $terms[] = [$term->right, -$sign];
                continue;
            }
            if ($term instanceof BinaryOperationNode && $term->operator === BinaryOperator::Multiply) {
                $leftContainsVariable = $this->containsVariable($term->left, $variable);
                $rightContainsVariable = $this->containsVariable($term->right, $variable);
                if ($leftContainsVariable !== $rightContainsVariable) {
                    $constantNode = $leftContainsVariable ? $term->right : $term->left;
                    try {
                        $constant = (float) $this->evaluateNode($constantNode, $parameters, $evaluationOptions);
                    } catch (MathException) {
                        return null;
                    }
                    $variableNode = $leftContainsVariable ? $term->left : $term->right;
                    $terms[] = [$variableNode, $sign * $constant];
                    continue;
                }
            }
            if (
                $term instanceof BinaryOperationNode
                && $term->operator === BinaryOperator::Divide
                && !$this->containsVariable($term->right, $variable)
            ) {
                try {
                    $divisor = (float) $this->evaluateNode($term->right, $parameters, $evaluationOptions);
                } catch (MathException) {
                    return null;
                }
                if ($divisor === 0.0 || !\is_finite($divisor)) {
                    return null;
                }
                $terms[] = [$term->left, $sign / $divisor];
                continue;
            }
            if ($this->containsVariable($term, $variable)) {
                $powerTerms[] = [$term, $sign];
                continue;
            }
            try {
                $offset += $sign * (float) $this->evaluateNode($term, $parameters, $evaluationOptions);
            } catch (MathException) {
                return null;
            }
            if (!\is_finite($offset)) {
                return null;
            }
        }
        if ($powerTerms === []) {
            return null;
        }
        $powerBase = null;
        $exponent = null;
        foreach ($powerTerms as [$powerTerm, $termCoefficient]) {
            $powerTerm = $this->unwrapGrouping($powerTerm);
            $powerInfo = $this->rationalPowerTermInfo($powerTerm);
            if (
                $powerInfo === null
                && $powerTerm instanceof BinaryOperationNode
                && $powerTerm->operator === BinaryOperator::Power
            ) {
                $rationalExponent = RationalLiteral::fromNode($powerTerm->right);
                if ($rationalExponent !== null) {
                    $powerInfo = ['base' => $powerTerm->left, 'exponent' => $rationalExponent];
                }
            }
            if ($powerInfo === null) {
                return null;
            }
            $termBase = $this->unwrapGrouping($powerInfo['base']);
            if (
                !$termBase instanceof VariableNode
                || $termBase->name !== $variable
                || ($powerBase !== null && $termBase->name !== $powerBase->name)
                || ($exponent !== null && $powerInfo['exponent'] !== $exponent)
            ) {
                return null;
            }
            $powerBase = $termBase;
            $exponent = $powerInfo['exponent'];
            $coefficient += $termCoefficient;
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        return $powerBase === null || $exponent === null
            ? null
            : [
                'base' => $powerBase,
                'exponent' => $exponent,
                'coefficient' => $coefficient,
                'offset' => $offset,
            ];
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedLogarithmPowerEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $matches = [[$left, $right], [$right, $left]];
        $degree = null;
        $logarithmOffset = 0.0;
        $zeroExponent = false;
        foreach ($matches as [$logarithm, $power]) {
            if (
                !$logarithm instanceof FunctionCallNode
            ) {
                continue;
            }
            $logarithmCoefficient = match ($logarithm->name) {
                'ln' => 1.0,
                'log2' => \log(2.0),
                'log10' => \log(10.0),
                default => null,
            };
            $logarithmArgument = null;
            if (
                \count($logarithm->arguments) === 1
                && $logarithm->arguments[0] instanceof VariableNode
                && $logarithm->arguments[0]->name === $variable
            ) {
                $logarithmArgument = $logarithm->arguments[0];
            } elseif (
                $logarithm->name === 'log'
                && \count($logarithm->arguments) === 2
                && $logarithm->arguments[0] instanceof VariableNode
                && $logarithm->arguments[0]->name === $variable
                && $logarithm->arguments[1] instanceof NumberNode
                && $logarithm->arguments[1]->value > 0.0
                && $logarithm->arguments[1]->value !== 1.0
            ) {
                $logarithmCoefficient = \log((float) $logarithm->arguments[1]->value);
                $logarithmArgument = $logarithm->arguments[0];
            }
            if ($logarithmArgument === null || $logarithmCoefficient === null) {
                continue;
            }
            $powerInfo = $this->rationalPowerProductInfo(
                $power,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            $powerBase = $powerInfo === null ? null : $this->unwrapGrouping($powerInfo['base']);
            $exponent = $powerInfo['exponent'] ?? null;
            if (
                !$powerBase instanceof VariableNode
                || $powerBase->name !== $variable
                || $exponent === null
            ) {
                continue;
            }
            $baseLogarithmCoefficient = $logarithmCoefficient;
            $logarithmCoefficient *= $powerInfo['coefficient'];
            $logarithmOffset = $powerInfo['offset'] * $baseLogarithmCoefficient;
            if (!\is_finite($logarithmCoefficient)) {
                continue;
            }
            if ($logarithmCoefficient === 0.0) {
                $zeroExponent = true;
                break;
            }
            [$numerator, $denominator] = $exponent;
            if ($numerator === 0) {
                $zeroExponent = true;
                break;
            }
            $degree = $denominator / $numerator;
            break;
        }
        if ($degree === null && !$zeroExponent) {
            return null;
        }
        if ($zeroExponent) {
            $candidateValues = [[\exp($logarithmCoefficient + $logarithmOffset), 0]];
        } elseif (!\is_finite($degree)) {
            return null;
        } elseif ($logarithmOffset !== 0.0) {
            $candidateValues = $this->solveLogarithmRationalPowerWithOffset(
                $degree,
                $logarithmCoefficient,
                $logarithmOffset,
                $evaluationOptions,
            );
            if ($candidateValues === null) {
                return null;
            }
        } elseif ($degree < 0.0) {
            if ($logarithmCoefficient < 0.0) {
                $absoluteCoefficient = -$logarithmCoefficient;
                $absoluteDegree = -$degree;
                $logRootParameter = \log($absoluteDegree) - \log($absoluteCoefficient);
                if (\abs($logRootParameter - 1.0) <= 64.0 * \PHP_FLOAT_EPSILON) {
                    return null;
                }
                if ($logRootParameter < 1.0) {
                    return [];
                }
                $transformedFunction = static fn (float $value): float =>
                    \log($value) - $value + $logRootParameter;
                $candidateValues = [];
                [$lowerTransformedRoot, $lowerIterations] = $this->bisectMonotoneRoot(
                    $transformedFunction,
                    0.0,
                    1.0,
                    -1,
                );
                $lowerLogarithmicValue = -$absoluteDegree * $lowerTransformedRoot;
                if ($lowerLogarithmicValue >= \log(\PHP_FLOAT_MIN * \PHP_FLOAT_EPSILON)) {
                    $candidateValues[] = [\exp($lowerLogarithmicValue), $lowerIterations];
                }
                $upperTransformedBound = 2.0;
                while ($transformedFunction($upperTransformedBound) > 0.0) {
                    $upperTransformedBound *= 2.0;
                    if (!\is_finite($upperTransformedBound)) {
                        return null;
                    }
                }
                [$upperTransformedRoot, $upperIterations] = $this->bisectMonotoneRoot(
                    $transformedFunction,
                    1.0,
                    $upperTransformedBound,
                    1,
                );
                $upperLogarithmicValue = -$absoluteDegree * $upperTransformedRoot;
                if ($upperLogarithmicValue >= \log(\PHP_FLOAT_MIN * \PHP_FLOAT_EPSILON)) {
                    $candidateValues[] = [\exp($upperLogarithmicValue), $upperIterations];
                }
            } else {
                $logarithmicRoot = $this->bisectMonotoneRoot(
                    static fn (float $value): float =>
                        $value - ($logarithmCoefficient * \exp($value / $degree)),
                    0.0,
                    $logarithmCoefficient,
                    -1,
                );
                $candidateValues = [[\exp($logarithmicRoot[0]), $logarithmicRoot[1]]];
            }
        } elseif ($degree === 0.0) {
            return null;
        } elseif ($logarithmCoefficient < 0.0) {
            $absoluteCoefficient = -$logarithmCoefficient;
            $logarithmicRoot = $this->bisectMonotoneRoot(
                static fn (float $value): float =>
                    $value - ($absoluteCoefficient * \exp(-$value / $degree)),
                0.0,
                $absoluteCoefficient,
                -1,
            );
            $candidateValues = [[\exp(-$logarithmicRoot[0]), $logarithmicRoot[1]]];
        } else {
            $rootParameter = $degree / $logarithmCoefficient;
            if (!\is_finite($rootParameter)) {
                return null;
            }
            if (\abs($rootParameter - \M_E) <= 64.0 * \PHP_FLOAT_EPSILON * \M_E) {
                return null;
            }
            if ($rootParameter < \M_E) {
                return [];
            }
            $criticalPoint = $rootParameter;
            $function = static fn (float $value): float => $value - ($rootParameter * \log($value));
            $upperTransformedBound = 2.0 * $rootParameter * \log($rootParameter);
            if (!\is_finite($upperTransformedBound) || $function($upperTransformedBound) <= 0.0) {
                return null;
            }
            $candidateValues = [];
            if ($degree >= (3.0 * $logarithmCoefficient)) {
                $logarithmicRoot = $this->bisectMonotoneRoot(
                    static fn (float $value): float =>
                        $value - ($logarithmCoefficient * \exp($value / $degree)),
                    0.0,
                    2.0 * $logarithmCoefficient,
                    -1,
                );
                $candidateValues[] = [\exp($logarithmicRoot[0]), $logarithmicRoot[1]];
            } else {
                [$transformedRoot, $iterations] = $this->bisectMonotoneRoot(
                    $function,
                    1.0,
                    $rootParameter,
                    1,
                );
                $logarithmicValue = $degree * \log($transformedRoot);
                if (\is_finite($logarithmicValue) && $logarithmicValue <= \log(\PHP_FLOAT_MAX)) {
                    $candidateValues[] = [\exp($logarithmicValue), $iterations];
                }
            }
            [$transformedRoot, $iterations] = $this->bisectMonotoneRoot(
                $function,
                $rootParameter,
                $upperTransformedBound,
                -1,
            );
            if ($degree * \log($transformedRoot) <= \log(\PHP_FLOAT_MAX)) {
                $logarithmicValue = $degree * \log($transformedRoot);
                $candidateValues[] = [\exp($logarithmicValue), $iterations];
            }
        }

        \usort(
            $candidateValues,
            static fn (array $left, array $right): int => $left[0] <=> $right[0],
        );
        $solutions = [];
        foreach ($candidateValues as [$value, $iterations]) {
            if (!\is_finite($value) || $value < $lowerBound || $value > $upperBound) {
                continue;
            }
            $residual = $residualAt($value);
            $scale = $candidateScaleAt($value);
            if (
                $residual !== null
                && $scale !== null
                && !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    static fn (float $_): float => $scale,
                    $options,
                )
            ) {
                [$value, $residual] = $this->bestRepresentableResidualCandidate(
                    $value,
                    $residual,
                    $lowerBound,
                    $upperBound,
                    $residualAt,
                );
                $scale = $candidateScaleAt($value);
            }
            if (
                $residual === null
                || $scale === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    static fn (float $candidate): float => $scale,
                    $options,
                )
            ) {
                continue;
            }
            $solutions[] = new EquationSolution($value, \abs($residual), $iterations);
        }

        return $solutions;
    }

    /**
     * @param callable(float): float $function
     * @return array{float, int}
     */
    private function bisectMonotoneRoot(callable $function, float $lower, float $upper, int $lowerSign): array
    {
        if ($lower < 0.0 && $upper > 0.0 && $function(0.0) === 0.0) {
            return [0.0, 1];
        }

        $iterations = 0;
        for (; $iterations < 256; ++$iterations) {
            $midpoint = ($lower / 2.0) + ($upper / 2.0);
            if ($midpoint === $lower || $midpoint === $upper) {
                break;
            }
            $value = $function($midpoint);
            if ($value === 0.0) {
                return [$midpoint, $iterations + 1];
            }
            if (($value < 0.0) === ($lowerSign < 0)) {
                $lower = $midpoint;
            } else {
                $upper = $midpoint;
            }
        }

        return [($lower / 2.0) + ($upper / 2.0), $iterations];
    }

    /**
     * Reduce zero-sums of odd, injective built-ins to their argument sums.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveOddInjectiveFunctionSum(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $erfcComplementSolutions = $this->solveErfcComplementSum(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($erfcComplementSolutions !== null) {
            return $erfcComplementSolutions;
        }
        $complementaryFunctionSolutions = $this->solveComplementaryFunctionSum(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightOffset,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $residualScaleAt,
        );
        if ($complementaryFunctionSolutions !== null) {
            return $complementaryFunctionSolutions;
        }

        $functionAliases = [
            'asinh' => 'asinh',
            'arcsinh' => 'asinh',
            'atan' => 'atan',
            'arctan' => 'atan',
            'asin' => 'asin',
            'arcsin' => 'asin',
            'atanh' => 'atanh',
            'arctanh' => 'atanh',
            'acot' => 'acot',
            'sinh' => 'sinh',
            'tanh' => 'tanh',
            'erf' => 'erf',
            'erfi' => 'erfi',
            'erfinv' => 'erfinv',
            'cbrt' => 'cbrt',
            'csch' => 'csch',
            'coth' => 'coth',
            'acsch' => 'acsch',
            'acoth' => 'acoth',
            'acsc' => 'acsc',
        ];
        $terms = [];
        $constantTerms = [];
        foreach (
                [[$left, 1.0, $leftSource, 0], [$right, -1.0, $rightSource, 0]]
            as [$side, $sideSign, $source, $sourceOffset]
        ) {
            $sideTerms = [];
            $this->flattenAdditiveTerms($side, $sideSign, $sideTerms);
            foreach ($sideTerms as [$term, $sign]) {
                try {
                    if (!$this->containsVariable($term, $variable)) {
                        $constantValue = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                        if ($constantValue !== null && $constantValue === 0.0) {
                            continue;
                        }
                    }
                } catch (EvaluationException) {
                    // Keep nonconstant or undefined terms for normal validation.
                }
                $call = $this->unwrapGrouping($term);
                if ($call instanceof FunctionCallNode && isset($functionAliases[$call->name])) {
                    $terms[] = [$term, $sign, $source, $sourceOffset];
                    continue;
                }
                try {
                    $constantValue = $this->constantNodeValue($term, $parameters, $evaluationOptions);
                } catch (EvaluationException) {
                    $constantValue = null;
                }
                if ($constantValue === null) {
                    return null;
                }
                $constantTerms[] = [$constantValue, $sign];
            }
        }
        if (\count($terms) !== 2 || \count($constantTerms) > 1 || $terms[0][1] !== $terms[1][1]) {
            return null;
        }

        $calls = [];
        $hasVariableArgument = false;
        foreach ($terms as [$term, , $source, $sourceOffset]) {
            $call = $this->unwrapGrouping($term);
            if (
                !$call instanceof FunctionCallNode
                || !isset($functionAliases[$call->name])
                || \count($call->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($call->name)
            ) {
                return null;
            }
            $argument = $call->arguments[0];
            $hasVariableArgument = $hasVariableArgument || $this->containsVariable($argument, $variable);
            $span = $argument->span();
            $argumentSource = \substr(
                $source,
                $span->start - $sourceOffset,
                $span->end - $span->start,
            );
            $calls[] = [$functionAliases[$call->name], $argument, $argumentSource];
        }
        if (!$hasVariableArgument || $calls[0][0] !== $calls[1][0]) {
            return null;
        }

        if ($calls[0][0] === 'acot') {
            if (
                \count($constantTerms) !== 1
                || $constantTerms[0][0] !== \M_PI
                || $constantTerms[0][1] === $terms[0][1]
            ) {
                return null;
            }
        } elseif ($constantTerms !== []) {
            return null;
        }

        $argumentEquation = '(' . $calls[0][2] . ')+(' . $calls[1][2] . ')=0';
        if (\strlen($argumentEquation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        try {
            $candidates = $this->solve(
                $argumentEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException | \DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $residualScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

        return $solutions;
    }

    /**
     * Reduce erfc(f) + erfc(g) = 2 using erfc(x) = 1 - erf(x).
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveErfcComplementSum(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $terms = [];
        foreach (
            [[$left, 1.0, $leftSource, 0], [$right, -1.0, $rightSource, $rightOffset]]
            as [$side, $sideSign, $source, $sourceOffset]
        ) {
            $sideTerms = [];
            $this->flattenAdditiveTerms($side, $sideSign, $sideTerms);
            foreach ($sideTerms as [$term, $sign]) {
                $terms[] = [$term, $sign, $source, $sourceOffset];
            }
        }
        if (\count($terms) !== 3) {
            return null;
        }

        $calls = [];
        $constant = null;
        foreach ($terms as [$term, $sign, $source, $sourceOffset]) {
            $call = $this->unwrapGrouping($term);
            if ($call instanceof FunctionCallNode && $call->name === 'erfc') {
                if (
                    \count($call->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn('erfc')
                ) {
                    return null;
                }
                $argument = $call->arguments[0];
                $span = $argument->span();
                $argumentSource = \substr(
                    $source,
                    $span->start,
                    $span->end - $span->start,
                );
                $calls[] = [$argument, $argumentSource, $sign];
                continue;
            }
            try {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
            } catch (EvaluationException) {
                return null;
            }
            if ($value === null || $constant !== null) {
                return null;
            }
            $constant = [$value, $sign];
        }
        if (
            \count($calls) !== 2
            || $constant === null
            || $calls[0][2] !== $calls[1][2]
            || $constant[1] !== -$calls[0][2]
            || $constant[0] !== 2.0
            || (!$this->containsVariable($calls[0][0], $variable)
                && !$this->containsVariable($calls[1][0], $variable))
        ) {
            return null;
        }

        $equation = 'erf((' . $calls[0][1] . '))+erf((' . $calls[1][1] . '))=0';
        if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        try {
            $candidates = $this->solve(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException | \DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $residualScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

        return $solutions;
    }

    /**
     * Reduce inverse sine/cosine equalities to Pythagorean argument equations.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveInverseSineCosineEquality(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $calls = [];
        foreach (
            [[$left, $leftSource, 0], [$right, $rightSource, 0]]
            as [$side, $source, $sourceOffset]
        ) {
            $call = $this->unwrapGrouping($side);
            if (
                !$call instanceof FunctionCallNode
                || \count($call->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($call->name)
            ) {
                return null;
            }
            $name = match ($call->name) {
                'arcsin' => 'asin',
                'arccos' => 'acos',
                'arcsinh' => 'asinh',
                'arccosh' => 'acosh',
                'arctanh' => 'atanh',
                default => $call->name,
            };
            $calls[] = [$name, $call->arguments[0], $source, $sourceOffset];
        }
        $isSameInversePair = $calls[0][0] === $calls[1][0]
            && \in_array(
                $calls[0][0],
                [
                    'asin', 'acos', 'atan', 'asec', 'acsc', 'acot',
                    'asinh', 'acosh', 'atanh', 'asech', 'acsch', 'acoth',
                ],
                true,
            );
        if (
            (!$isSameInversePair && !\in_array(
                [$calls[0][0], $calls[1][0]],
                [
                    ['asin', 'acos'], ['acos', 'asin'],
                    ['asin', 'asec'], ['asec', 'asin'],
                    ['asin', 'acsc'], ['acsc', 'asin'],
                    ['acos', 'acsc'], ['acsc', 'acos'],
                    ['acos', 'asec'], ['asec', 'acos'],
                    ['asin', 'acot'], ['acot', 'asin'],
                    ['acos', 'acot'], ['acot', 'acos'],
                    ['asin', 'atan'], ['atan', 'asin'],
                    ['acos', 'atan'], ['atan', 'acos'],
                    ['asec', 'atan'], ['atan', 'asec'],
                    ['acsc', 'atan'], ['atan', 'acsc'],
                    ['acot', 'atan'], ['atan', 'acot'],
                    ['asec', 'acot'], ['acot', 'asec'],
                    ['acsc', 'acot'], ['acot', 'acsc'],
                    ['asec', 'acsc'], ['acsc', 'asec'],
                    ['asinh', 'acosh'], ['acosh', 'asinh'],
                    ['asinh', 'acsch'], ['acsch', 'asinh'],
                    ['acosh', 'acsch'], ['acsch', 'acosh'],
                    ['acoth', 'acsch'], ['acsch', 'acoth'],
                    ['acoth', 'atanh'], ['atanh', 'acoth'],
                    ['acosh', 'atanh'], ['atanh', 'acosh'],
                    ['asech', 'atanh'], ['atanh', 'asech'],
                    ['acsch', 'atanh'], ['atanh', 'acsch'],
                    ['asinh', 'atanh'], ['atanh', 'asinh'],
                    ['acosh', 'acoth'], ['acoth', 'acosh'],
                    ['acoth', 'asech'], ['asech', 'acoth'],
                    ['asinh', 'acoth'], ['acoth', 'asinh'],
                    ['acosh', 'asech'], ['asech', 'acosh'],
                    ['acsch', 'asech'], ['asech', 'acsch'],
                    ['asinh', 'asech'], ['asech', 'asinh'],
                ],
                true,
            ))
            || (!$this->containsVariable($calls[0][1], $variable)
                && !$this->containsVariable($calls[1][1], $variable))
        ) {
            return null;
        }

        $arguments = [];
        foreach ($calls as [, $argument, $source, $sourceOffset]) {
            $span = $argument->span();
            $arguments[] = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);
        }
        $isReciprocalPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asec', 'acsc'], ['acsc', 'asec']],
            true,
        );
        $isSquaredReciprocalPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [
                ['asin', 'asec'], ['asec', 'asin'],
                ['acos', 'acsc'], ['acsc', 'acos'],
            ],
            true,
        );
        $isHyperbolicPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asinh', 'acosh'], ['acosh', 'asinh']],
            true,
        );
        $isProductIdentityPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [
                ['asinh', 'acsch'], ['acsch', 'asinh'],
                ['acosh', 'asech'], ['asech', 'acosh'],
                ['acot', 'atan'], ['atan', 'acot'],
                ['asin', 'acsc'], ['acsc', 'asin'],
                ['acos', 'asec'], ['asec', 'acos'],
            ],
            true,
        );
        $isCoshReciprocalPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acosh', 'acsch'], ['acsch', 'acosh']],
            true,
        );
        $isCosecantSechPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acsch', 'asech'], ['asech', 'acsch']],
            true,
        );
        $isCotanhCosecantPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acoth', 'acsch'], ['acsch', 'acoth']],
            true,
        );
        $isCotanhTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acoth', 'atanh'], ['atanh', 'acoth']],
            true,
        );
        $isCoshTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [
                ['acosh', 'atanh'], ['atanh', 'acosh'],
                ['acoth', 'asech'], ['asech', 'acoth'],
            ],
            true,
        );
        $isSineCotangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asin', 'acot'], ['acot', 'asin']],
            true,
        );
        $isCosineCotangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acos', 'acot'], ['acot', 'acos']],
            true,
        );
        $isSecantCotangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asec', 'acot'], ['acot', 'asec']],
            true,
        );
        $isCosecantCotangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acsc', 'acot'], ['acot', 'acsc']],
            true,
        );
        $isSineTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asin', 'atan'], ['atan', 'asin']],
            true,
        );
        $isCosineTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acos', 'atan'], ['atan', 'acos']],
            true,
        );
        $isSecantTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asec', 'atan'], ['atan', 'asec']],
            true,
        );
        $isCosecantArcTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acsc', 'atan'], ['atan', 'acsc']],
            true,
        );
        $isSinhTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asinh', 'atanh'], ['atanh', 'asinh']],
            true,
        );
        $isCosecantTangentPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acsch', 'atanh'], ['atanh', 'acsch']],
            true,
        );
        $isCoshCotanhPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['acosh', 'acoth'], ['acoth', 'acosh']],
            true,
        );
        $isSinhCotanhPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asinh', 'acoth'], ['acoth', 'asinh']],
            true,
        );
        $isSinhSechPair = \in_array(
            [$calls[0][0], $calls[1][0]],
            [['asinh', 'asech'], ['asech', 'asinh']],
            true,
        );
        $firstArgument = $isReciprocalPair ? '(1/(' . $arguments[0] . '))' : '(' . $arguments[0] . ')';
        $secondArgument = $isReciprocalPair ? '(1/(' . $arguments[1] . '))' : '(' . $arguments[1] . ')';
        if ($isSameInversePair) {
            $equation = '(' . $arguments[0] . ')=(' . $arguments[1] . ')';
        } elseif ($isProductIdentityPair || $isCotanhTangentPair) {
            $equation = '((' . $arguments[0] . ')*(' . $arguments[1] . '))=1';
        } elseif ($isSineTangentPair) {
            $asinArgumentIndex = $calls[0][0] === 'asin' ? 0 : 1;
            $atanArgumentIndex = 1 - $asinArgumentIndex;
            $equation = '((' . $arguments[$asinArgumentIndex] . ')^2)*(1+(('
                . $arguments[$atanArgumentIndex] . ')^2))=(('
                . $arguments[$atanArgumentIndex] . ')^2)';
        } elseif ($isCosineTangentPair) {
            $acosArgumentIndex = $calls[0][0] === 'acos' ? 0 : 1;
            $atanArgumentIndex = 1 - $acosArgumentIndex;
            $equation = '((' . $arguments[$acosArgumentIndex] . ')^2)*(1+(('
                . $arguments[$atanArgumentIndex] . ')^2))=1';
        } elseif ($isSecantTangentPair) {
            $asecArgumentIndex = $calls[0][0] === 'asec' ? 0 : 1;
            $atanArgumentIndex = 1 - $asecArgumentIndex;
            $equation = '((' . $arguments[$asecArgumentIndex] . ')^2)-(('
                . $arguments[$atanArgumentIndex] . ')^2)=1';
        } elseif ($isCosecantArcTangentPair) {
            $acscArgumentIndex = $calls[0][0] === 'acsc' ? 0 : 1;
            $atanArgumentIndex = 1 - $acscArgumentIndex;
            $equation = '((' . $arguments[$acscArgumentIndex] . ')^2)*(('
                . $arguments[$atanArgumentIndex] . ')^2)=1+(('
                . $arguments[$atanArgumentIndex] . ')^2)';
        } elseif ($isSineCotangentPair) {
            $asinArgumentIndex = $calls[0][0] === 'asin' ? 0 : 1;
            $acotArgumentIndex = 1 - $asinArgumentIndex;
            $equation = '((' . $arguments[$asinArgumentIndex] . ')^2)*(1+(('
                . $arguments[$acotArgumentIndex] . ')^2))=1';
        } elseif ($isCosineCotangentPair) {
            $acosArgumentIndex = $calls[0][0] === 'acos' ? 0 : 1;
            $acotArgumentIndex = 1 - $acosArgumentIndex;
            $equation = '((' . $arguments[$acosArgumentIndex] . ')^2)*(1+(('
                . $arguments[$acotArgumentIndex] . ')^2))=(('
                . $arguments[$acotArgumentIndex] . ')^2)';
        } elseif ($isSecantCotangentPair) {
            $asecArgumentIndex = $calls[0][0] === 'asec' ? 0 : 1;
            $acotArgumentIndex = 1 - $asecArgumentIndex;
            $equation = '((' . $arguments[$asecArgumentIndex] . ')^2)-(1/('
                . $arguments[$acotArgumentIndex] . '))^2=1';
        } elseif ($isCosecantCotangentPair) {
            $acscArgumentIndex = $calls[0][0] === 'acsc' ? 0 : 1;
            $acotArgumentIndex = 1 - $acscArgumentIndex;
            $equation = '((' . $arguments[$acscArgumentIndex] . ')^2)-(('
                . $arguments[$acotArgumentIndex] . ')^2)=1';
        } elseif ($isCotanhCosecantPair) {
            $acothArgumentIndex = $calls[0][0] === 'acoth' ? 0 : 1;
            $acschArgumentIndex = 1 - $acothArgumentIndex;
            $equation = '((' . $arguments[$acothArgumentIndex] . ')^2)-(('
                . $arguments[$acschArgumentIndex] . ')^2)=1';
        } elseif ($isSinhTangentPair) {
            $asinhArgumentIndex = $calls[0][0] === 'asinh' ? 0 : 1;
            $atanhArgumentIndex = 1 - $asinhArgumentIndex;
            $equation = '((' . $arguments[$asinhArgumentIndex] . ')^2)*(1-(('
                . $arguments[$atanhArgumentIndex] . ')^2))=(('
                . $arguments[$atanhArgumentIndex] . ')^2)';
        } elseif ($isCosecantTangentPair) {
            $acschArgumentIndex = $calls[0][0] === 'acsch' ? 0 : 1;
            $atanhArgumentIndex = 1 - $acschArgumentIndex;
            $equation = '((' . $arguments[$atanhArgumentIndex] . ')^2)*(1+(('
                . $arguments[$acschArgumentIndex] . ')^2))=1';
        } elseif ($isCoshTangentPair) {
            $firstArgumentIndex = \in_array($calls[0][0], ['acosh', 'acoth'], true) ? 0 : 1;
            $secondArgumentIndex = 1 - $firstArgumentIndex;
            $equation = '((' . $arguments[$firstArgumentIndex] . ')^2)*(1-(('
                . $arguments[$secondArgumentIndex] . ')^2))=1';
        } elseif ($isCoshCotanhPair) {
            $acoshArgumentIndex = $calls[0][0] === 'acosh' ? 0 : 1;
            $acothArgumentIndex = 1 - $acoshArgumentIndex;
            $equation = '((' . $arguments[$acoshArgumentIndex] . ')^2)*((('
                . $arguments[$acothArgumentIndex] . ')^2)-1)=(('
                . $arguments[$acothArgumentIndex] . ')^2)';
        } elseif ($isSinhCotanhPair) {
            $asinhArgumentIndex = $calls[0][0] === 'asinh' ? 0 : 1;
            $acothArgumentIndex = 1 - $asinhArgumentIndex;
            $equation = '((' . $arguments[$asinhArgumentIndex] . ')^2)*((('
                . $arguments[$acothArgumentIndex] . ')^2)-1)=1';
        } elseif ($isSinhSechPair) {
            $asinhArgumentIndex = $calls[0][0] === 'asinh' ? 0 : 1;
            $asechArgumentIndex = 1 - $asinhArgumentIndex;
            $equation = '((' . $arguments[$asechArgumentIndex] . ')^2)*(1+(('
                . $arguments[$asinhArgumentIndex] . ')^2))=1';
        } elseif ($isCosecantSechPair) {
            $acschArgumentIndex = $calls[0][0] === 'acsch' ? 0 : 1;
            $asechArgumentIndex = 1 - $acschArgumentIndex;
            $equation = '((' . $arguments[$acschArgumentIndex] . ')^2)-(('
                . $arguments[$asechArgumentIndex] . ')^2)=(('
                . $arguments[$acschArgumentIndex] . ')^2)*(('
                . $arguments[$asechArgumentIndex] . ')^2)';
        } elseif ($isCoshReciprocalPair) {
            $acoshArgumentIndex = $calls[0][0] === 'acosh' ? 0 : 1;
            $acschArgumentIndex = 1 - $acoshArgumentIndex;
            $equation = '((' . $arguments[$acoshArgumentIndex] . ')^2)-('
                . '(1/(' . $arguments[$acschArgumentIndex] . '))^2)=1';
        } elseif ($isHyperbolicPair) {
            $negativeArgumentIndex = $calls[0][0] === 'asinh' ? 0 : 1;
            $positiveArgumentIndex = 1 - $negativeArgumentIndex;
            $equation = '((' . $arguments[$positiveArgumentIndex] . ')^2)-('
                . '(' . $arguments[$negativeArgumentIndex] . ')^2)=1';
        } elseif ($isSquaredReciprocalPair) {
            $inverseTrigArgumentIndex = \in_array($calls[0][0], ['asin', 'acos'], true) ? 0 : 1;
            $reciprocalArgumentIndex = 1 - $inverseTrigArgumentIndex;
            $equation = '((' . $arguments[$inverseTrigArgumentIndex] . ')^2)+(1/('
                . $arguments[$reciprocalArgumentIndex] . '))^2=1';
        } else {
            $equation = '(' . $firstArgument . '^2)+(' . $secondArgument . '^2)=1';
        }
        if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        try {
            $candidates = $this->solve(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException | \DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $residualScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

        return $solutions;
    }

    /**
     * Reduce erf(f) + erfc(g) = 1 and atan(f) + acot(g) = pi/2 to f = g.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveComplementaryFunctionSum(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $terms = [];
        foreach (
            [[$left, 1.0, $leftSource, 0], [$right, -1.0, $rightSource, $rightOffset]]
            as [$side, $sideSign, $source, $sourceOffset]
        ) {
            $sideTerms = [];
            $this->flattenAdditiveTerms($side, $sideSign, $sideTerms);
            foreach ($sideTerms as [$term, $sign]) {
                $terms[] = [$term, $sign, $source, $sourceOffset];
            }
        }
        if (\count($terms) !== 3) {
            return null;
        }

        $calls = [];
        $constant = null;
        foreach ($terms as [$term, $sign, $source, $sourceOffset]) {
            $call = $this->unwrapGrouping($term);
            if ($call instanceof FunctionCallNode) {
                $canonicalName = match ($call->name) {
                    'arctan' => 'atan',
                    'arccos' => 'acos',
                    'arcsin' => 'asin',
                    default => $call->name,
                };
                if (
                    !\in_array(
                        $canonicalName,
                        ['erf', 'erfc', 'atan', 'acot', 'asin', 'acos', 'asec', 'acsc'],
                        true,
                    )
                    || \count($call->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn($call->name)
                ) {
                    return null;
                }
                $argument = $call->arguments[0];
                $span = $argument->span();
                $argumentSource = \substr(
                    $source,
                    $span->start,
                    $span->end - $span->start,
                );
                $calls[] = [$canonicalName, $argument, $argumentSource, $sign];
                continue;
            }
            try {
                $value = $this->constantNodeValue($term, $parameters, $evaluationOptions);
            } catch (EvaluationException) {
                return null;
            }
            if ($value === null || $constant !== null) {
                return null;
            }
            $constant = [$value, $sign];
        }

        if (
            \count($calls) !== 2
            || $constant === null
            || $calls[0][3] !== $calls[1][3]
            || $constant[1] !== -$calls[0][3]
            || (!$this->containsVariable($calls[0][1], $variable)
                && !$this->containsVariable($calls[1][1], $variable))
        ) {
            return null;
        }
        $functionPair = [$calls[0][0], $calls[1][0]];
        $target = match ($functionPair) {
            ['erf', 'erfc'], ['erfc', 'erf'] => 1.0,
            ['atan', 'acot'], ['acot', 'atan'] => \M_PI_2,
            ['asin', 'acos'], ['acos', 'asin'] => \M_PI_2,
            ['asec', 'acsc'], ['acsc', 'asec'] => \M_PI_2,
            ['acos', 'acos'], ['asec', 'asec'] => \M_PI,
            default => null,
        };
        if ($target === null || $constant[0] !== $target) {
            return null;
        }

        $equation = \in_array($functionPair, [['acos', 'acos'], ['asec', 'asec']], true)
            ? '(' . $calls[0][2] . ')+(' . $calls[1][2] . ')=0'
            : '(' . $calls[0][2] . ')=(' . $calls[1][2] . ')';
        if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        try {
            $candidates = $this->solve(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException | \DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $residualScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveIdenticalRestrictedFunctionDomain(
        Node $left,
        Node $right,
        string $leftExpression,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            !$this->sameExpression($left, $right)
            || !$this->containsVariable($left, $variable)
        ) {
            return null;
        }

        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $probes = [0.0];
            if (\is_finite($lowerBound)) {
                $probes[] = $lowerBound;
            }
            if (\is_finite($upperBound)) {
                $probes[] = $upperBound;
            }
            $probes[] = \PHP_FLOAT_MAX;
            $probes[] = -\PHP_FLOAT_MAX;
            for ($exponent = 0; $exponent <= 1023; ++$exponent) {
                $magnitude = 2.0 ** $exponent;
                $probes[] = $magnitude;
                $probes[] = -$magnitude;
                $probes[] = $magnitude + 0.25;
                $probes[] = -$magnitude - 0.25;
            }
            if ($left instanceof FunctionCallNode && isset($left->arguments[0])) {
                array_push(
                    $probes,
                    ...$this->polynomialCriticalPointCandidates(
                        $left->arguments[0],
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ),
                );
            }
            foreach ($probes as $probe) {
                if ($probe < $lowerBound || $probe > $upperBound) {
                    continue;
                }
                if (
                    $this->residualAt(
                        $left,
                        $right,
                        $rightOffset,
                        $variable,
                        $probe,
                        $parameters,
                        $evaluationOptions,
                    ) !== null
                    && $this->isLocallyContinuous(
                        $left,
                        $probe,
                        $evaluationOptions,
                        $parameters,
                        $variable,
                    )
                ) {
                    throw new InfiniteSolutionSetException(
                        'An identical expression is defined on a nonempty interval of the unbounded domain.',
                    );
                }
            }

            return null;
        }

        $functionCall = $left;
        if (
            $functionCall instanceof FunctionCallNode
            && $functionCall->name === 'abs'
            && \count($functionCall->arguments) === 1
        ) {
            $functionCall = $this->unwrapGrouping($functionCall->arguments[0]);
        }
        if (
            $functionCall instanceof FunctionCallNode
            && $functionCall->name === 'root'
            && $this->rootDegreeLiteral($functionCall) === 2
        ) {
            $functionCall = new FunctionCallNode(
                'sqrt',
                [$functionCall->arguments[0]],
                $functionCall->nameSpan,
                $functionCall->span,
            );
        }
        if (
            !$functionCall instanceof FunctionCallNode
            || (\count($functionCall->arguments) !== 1
                && !($functionCall->name === 'log' && \count($functionCall->arguments) === 2))
            || !$evaluationOptions->functions->isBuiltIn($functionCall->name)
        ) {
            return null;
        }

        $canonicalFunction = match ($functionCall->name) {
            'arcsin' => 'asin',
            'arctanh' => 'atanh',
            'arccos' => 'acos',
            'arccosh' => 'acosh',
            default => $functionCall->name,
        };
        $argumentSpan = $functionCall->arguments[0]->span();
        $argumentSource = \substr(
            $leftExpression,
            $argumentSpan->start,
            $argumentSpan->end - $argumentSpan->start,
        );
        $baseSource = null;
        if ($functionCall->name === 'log') {
            $baseArgument = $functionCall->arguments[1] ?? null;
            if (!$baseArgument instanceof Node) {
                return null;
            }
            $baseSpan = $baseArgument->span();
            $baseSource = \substr(
                $leftExpression,
                $baseSpan->start,
                $baseSpan->end - $baseSpan->start,
            );
        }
        $domainIntervals = $this->functionArgumentDomainIntervals(
            $canonicalFunction,
            $argumentSource,
            $baseSource,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        if ($domainIntervals === null) {
            return null;
        }

        $hasDefinedIntervalPoint = false;
        foreach ($domainIntervals as $domainInterval) {
            if ($domainInterval->lowerBound < $domainInterval->upperBound) {
                $samples = [
                    $domainInterval->lowerBound,
                    $domainInterval->lowerBound
                        + (
                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                            * 0.25
                        ),
                    $domainInterval->lowerBound
                        + (
                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                            * 0.5
                        ),
                    $domainInterval->lowerBound
                        + (
                            ($domainInterval->upperBound - $domainInterval->lowerBound)
                            * 0.75
                        ),
                    $domainInterval->upperBound,
                ];
                foreach ($samples as $sample) {
                    if (
                        $this->residualAt(
                            $left,
                            $right,
                            $rightOffset,
                            $variable,
                            $sample,
                            $parameters,
                            $evaluationOptions,
                        ) !== null
                        && $this->isLocallyContinuous(
                            $left,
                            $sample,
                            $evaluationOptions,
                            $parameters,
                            $variable,
                        )
                    ) {
                        $hasDefinedIntervalPoint = true;
                        break 2;
                    }
                }
            }
        }
        if ($hasDefinedIntervalPoint) {
            throw new InfiniteSolutionSetException(
                'Equation has infinitely many solutions in the requested interval.',
            );
        }

        $solutions = [];
        foreach ($domainIntervals as $domainInterval) {
            $point = $domainInterval->lowerBound;
            $residual = $this->residualAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $point,
                $parameters,
                $evaluationOptions,
            );
            $scale = $this->residualScaleAt(
                $left,
                $right,
                $rightOffset,
                $variable,
                $point,
                $parameters,
                $evaluationOptions,
            );
            if (
                $residual === null
                || $scale === null
                || !$this->isResidualAcceptableAt(
                    $point,
                    $residual,
                    static fn (float $value): float => $scale,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($point, \abs($residual), 0),
                $solverOptions,
            );
        }

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<float>
     */
    private function polynomialCriticalPointCandidates(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        $polynomial = (new PolynomialExtractor(
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        ))->extract($node);
        if ($polynomial === null || \count($polynomial) < 3) {
            return [];
        }

        $derivative = [];
        foreach ($polynomial as $power => $coefficient) {
            if ($power > 0) {
                $derivative[] = $power * $coefficient;
            }
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }
        if (\count($derivative) < 2) {
            return [];
        }

        $leadingMagnitude = \abs($derivative[\array_key_last($derivative)]);
        if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
            return [];
        }
        $maximumRatio = 0.0;
        foreach (\array_slice($derivative, 0, -1) as $coefficient) {
            $ratio = \abs($coefficient) / $leadingMagnitude;
            if (!\is_finite($ratio)) {
                return [];
            }
            $maximumRatio = \max($maximumRatio, $ratio);
        }
        $bound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
        if (!\is_finite($bound)) {
            return [];
        }

        $polynomialSolver = new PolynomialSolver();
        $roots = $polynomialSolver->solve(
            $derivative,
            -$bound,
            $bound,
            static fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($derivative, $value),
            $solverOptions,
            static fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude($derivative, $value),
        );
        if ($roots === null) {
            return [];
        }

        return \array_map(static fn (EquationSolution $root): float => $root->value, $roots);
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<InequalityInterval>|null
     */
    private function functionArgumentDomainIntervals(
        string $function,
        string $argument,
        ?string $secondArgument,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        /** @var list<list<array{string, string}>>|null $domainAlternatives */
        $domainAlternatives = match ($function) {
            'asin', 'acos' => [[[$argument, '>=-1'], [$argument, '<=1']]],
            'atanh', 'erfinv' => [[[$argument, '>-1'], [$argument, '<1']]],
            'erfcinv' => [[[$argument, '>0'], [$argument, '<2']]],
            'acosh' => [[[$argument, '>=1']]],
            'asec', 'acsc' => [[[$argument, '<=-1']], [[$argument, '>=1']]],
            'asech' => [[[$argument, '>0'], [$argument, '<=1']]],
            'sqrt' => [[[$argument, '>=0']]],
            'csch', 'coth', 'acsch' => [[[$argument, '<0']], [[$argument, '>0']]],
            'acoth' => [[[$argument, '<-1']], [[$argument, '>1']]],
            'ln', 'log10', 'log2' => [[[$argument, '>0']]],
            'log1p' => [[[$argument, '>-1']]],
            'log' => $secondArgument === null
                ? null
                : [
                    [[$argument, '>0'], [$secondArgument, '>0'], [$secondArgument, '<1']],
                    [[$argument, '>0'], [$secondArgument, '>1']],
                ],
            default => null,
        };
        if ($domainAlternatives === null) {
            return null;
        }

        $inequalitySolver = new InequalitySolver();
        /** @var list<InequalityInterval> $domainIntervals */
        $domainIntervals = [];
        try {
            foreach ($domainAlternatives as $constraints) {
                /** @var list<InequalityInterval>|null $intersection */
                $intersection = null;
                foreach ($constraints as [$expression, $operator]) {
                    $constraintNode = $this->parseSide($expression, 0, $evaluationOptions);
                    if (
                        $this->containsVariable($constraintNode, $variable)
                        || $this->containsImplicitVariableProduct($constraintNode, $variable, $evaluationOptions)
                    ) {
                        $intervals = $inequalitySolver->solve(
                            '(' . $expression . ')' . $operator,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } else {
                        try {
                            $constant = (float) $this->evaluateNode($constraintNode, $parameters, $evaluationOptions);
                        } catch (\Throwable) {
                            return null;
                        }
                        $satisfied = match ($operator) {
                            '>0' => $constant > 0.0,
                            '<1' => $constant < 1.0,
                            '>1' => $constant > 1.0,
                            '>=1' => $constant >= 1.0,
                            '<=1' => $constant <= 1.0,
                            '<=-1' => $constant <= -1.0,
                            '>=-1' => $constant >= -1.0,
                            '<-1' => $constant < -1.0,
                            '>-1' => $constant > -1.0,
                            default => throw new \LogicException('Unexpected function-domain comparison.'),
                        };
                        $intervals = $satisfied
                            ? [new InequalityInterval($lowerBound, $upperBound, true, true)]
                            : [];
                    }
                    if ($intersection === null) {
                        $intersection = $intervals;
                        continue;
                    }

                    $overlaps = [];
                    foreach ($intersection as $leftInterval) {
                        foreach ($intervals as $rightInterval) {
                            $lower = \max($leftInterval->lowerBound, $rightInterval->lowerBound);
                            $upper = \min($leftInterval->upperBound, $rightInterval->upperBound);
                            $includesLower = ($lower !== $leftInterval->lowerBound || $leftInterval->includesLowerBound)
                                && ($lower !== $rightInterval->lowerBound || $rightInterval->includesLowerBound);
                            $includesUpper = ($upper !== $leftInterval->upperBound || $leftInterval->includesUpperBound)
                                && ($upper !== $rightInterval->upperBound || $rightInterval->includesUpperBound);
                            if ($lower < $upper || ($lower === $upper && $includesLower && $includesUpper)) {
                                $overlaps[] = new InequalityInterval($lower, $upper, $includesLower, $includesUpper);
                            }
                        }
                    }
                    $intersection = $overlaps;
                    if ($intersection === []) {
                        break;
                    }
                }

                if ($intersection !== null) {
                    \array_push($domainIntervals, ...$intersection);
                }
            }
        } catch (InfiniteRootAccumulationException | InfiniteSolutionSetException | \DomainException) {
            return null;
        }

        return $domainIntervals;
    }

    /**
     * Cancel equal injective functions to avoid finite-precision plateaus
     * creating or hiding roots.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSameInjectiveFunctionEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $isComplementaryInversePair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && \in_array(
                [$left->name, $right->name],
                [
                    ['erfinv', 'erfcinv'],
                    ['erfcinv', 'erfinv'],
                    ['gammaincinv', 'gammainccinv'],
                    ['gammainccinv', 'gammaincinv'],
                    ['betaincinv', 'betainccinv'],
                    ['betainccinv', 'betaincinv'],
                ],
                true,
            )
            && $left->name !== $right->name;
        $polygammaAliasOrders = ['digamma' => 0.0, 'trigamma' => 1.0, 'tetragamma' => 2.0];
        $isPolygammaAliasPair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && (($left->name === 'polygamma' && \array_key_exists($right->name, $polygammaAliasOrders))
                || ($right->name === 'polygamma' && \array_key_exists($left->name, $polygammaAliasOrders)));
        $isLogarithmAliasPair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && \in_array(
                [$left->name, $right->name],
                [
                    ['ln', 'log'], ['log', 'ln'],
                    ['log10', 'log'], ['log', 'log10'],
                    ['log2', 'log'], ['log', 'log2'],
                ],
                true,
            );
        $isNaturalLogOnePlusPair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && \in_array(
                [$left->name, $right->name],
                [['ln', 'log1p'], ['log1p', 'ln']],
                true,
            );
        $isExponentialUnitShiftPair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && \in_array(
                [$left->name, $right->name],
                [['exp', 'expm1'], ['expm1', 'exp']],
                true,
            );
        $isEvenHyperbolicPair = $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && $left->name === $right->name
            && \in_array($left->name, ['cosh', 'sech'], true);
        $injectiveFunctions = [
            'exp', 'expm1', 'ln', 'log10', 'log2', 'log1p',
            'sqrt', 'cbrt', 'sinh', 'tanh', 'asinh', 'acosh', 'atanh',
            'asin', 'acos', 'atan', 'asec', 'acsc', 'acot',
            'csch', 'coth', 'asech', 'acsch', 'acoth', 'erf', 'erfc', 'erfcx', 'erfi',
            'erfinv', 'erfcinv',
            'gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma', 'lambertw',
            'gammaincinv', 'gammainccinv',
        ];
        $argumentIndex = 0;
        $requirePositiveArguments = false;
        $requireArgumentsAboveOne = false;
        $requireArgumentsAtLeastThreeHalves = false;
        $isBesselI = false;
        $isEvenBesselI = false;
        $isInverseQuantile = false;
        $leftArgument = null;
        $rightArgument = null;
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || ($left->name !== $right->name
                && !$isComplementaryInversePair
                && !$isPolygammaAliasPair
                && !$isLogarithmAliasPair
                && !$isNaturalLogOnePlusPair
                && !$isExponentialUnitShiftPair)
        ) {
            return null;
        }
        if (
            \in_array($left->name, ['erfcx', 'lambertw'], true)
            && !$evaluationOptions->functions->isBuiltIn($left->name)
        ) {
            return null;
        }
        if ($left->name === 'lambertw') {
            if (
                !\in_array(\count($left->arguments), [1, 2], true)
                || !\in_array(\count($right->arguments), [1, 2], true)
            ) {
                return null;
            }
            try {
                $leftBranch = \count($left->arguments) === 2
                    ? $extractor->extract($left->arguments[1])
                    : [0.0];
                $rightBranch = \count($right->arguments) === 2
                    ? $extractor->extract($right->arguments[1])
                    : [0.0];
            } catch (EvaluationException) {
                return null;
            }
            if (
                $leftBranch === null
                || $rightBranch === null
                || \count($leftBranch) !== 1
                || \count($rightBranch) !== 1
                || $leftBranch[0] !== $rightBranch[0]
                || !\in_array($leftBranch[0], [0.0, -1.0], true)
            ) {
                return null;
            }
        } elseif ($left->name === 'root') {
            if (\count($left->arguments) !== 2 || \count($right->arguments) !== 2) {
                return null;
            }
            if (
                !$this->sameSourceOrConstantArgument(
                    $left->arguments[1],
                    $right->arguments[1],
                    $leftSource,
                    $rightSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    0,
                    0,
                )
            ) {
                return null;
            }
        } elseif ($isLogarithmAliasPair) {
            $logCall = $left->name === 'log' ? $left : $right;
            $otherCall = $left->name === 'log' ? $right : $left;
            $expectedBase = match ($otherCall->name) {
                'ln' => \M_E,
                'log10' => 10.0,
                'log2' => 2.0,
                default => null,
            };
            if (
                \count($logCall->arguments) !== 2
                || \count($otherCall->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('log')
                || !$evaluationOptions->functions->isBuiltIn($otherCall->name)
                || $expectedBase === null
            ) {
                return null;
            }
            try {
                $base = $extractor->extract($logCall->arguments[1]);
            } catch (EvaluationException) {
                return null;
            }
            if ($base !== [$expectedBase]) {
                return null;
            }
        } elseif ($left->name === 'log') {
            if (\count($left->arguments) !== 2 || \count($right->arguments) !== 2) {
                return null;
            }
            if (
                !$this->sameSourceOrConstantArgument(
                    $left->arguments[1],
                    $right->arguments[1],
                    $leftSource,
                    $rightSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    0,
                    0,
                )
            ) {
                return null;
            }
        } elseif ($left->name === 'besseli') {
            if (
                \count($left->arguments) !== 2
                || \count($right->arguments) !== 2
            ) {
                return null;
            }
            $leftOrder = $extractor->extract($left->arguments[0]);
            $rightOrder = $extractor->extract($right->arguments[0]);
            if (
                $leftOrder === null
                || $rightOrder === null
                || \count($leftOrder) !== 1
                || \count($rightOrder) !== 1
                || !\is_finite($leftOrder[0])
                || !\is_finite($rightOrder[0])
                || \floor($leftOrder[0]) !== $leftOrder[0]
                || \floor($rightOrder[0]) !== $rightOrder[0]
                || \abs($leftOrder[0]) > SpecialFunctions::MAX_BESSEL_ORDER
                || \abs($rightOrder[0]) > SpecialFunctions::MAX_BESSEL_ORDER
                || \abs($leftOrder[0]) !== \abs($rightOrder[0])
            ) {
                return null;
            }
            $order = (int) $leftOrder[0];
            $isBesselI = true;
            $isEvenBesselI = ($order & 1) === 0;
            $argumentIndex = 1;
            $leftArgument = $left->arguments[1];
            $rightArgument = $right->arguments[1];
        } elseif (
            \in_array($left->name, ['gammaincinv', 'gammainccinv'], true)
            && \in_array($right->name, ['gammaincinv', 'gammainccinv'], true)
        ) {
            if (
                \count($left->arguments) !== 2
                || \count($right->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn($left->name)
                || !$evaluationOptions->functions->isBuiltIn($right->name)
                || !$this->sameSourceOrConstantArgument(
                    $left->arguments[0],
                    $right->arguments[0],
                    $leftSource,
                    $rightSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    0,
                    0,
                )
            ) {
                return null;
            }
            $argumentIndex = 1;
            $isInverseQuantile = true;
        } elseif (
            \in_array($left->name, ['betaincinv', 'betainccinv'], true)
            && \in_array($right->name, ['betaincinv', 'betainccinv'], true)
        ) {
            if (
                \count($left->arguments) !== 3
                || \count($right->arguments) !== 3
                || !$evaluationOptions->functions->isBuiltIn($left->name)
                || !$evaluationOptions->functions->isBuiltIn($right->name)
                || !$this->sameSourceOrConstantArgument(
                    $left->arguments[0],
                    $right->arguments[0],
                    $leftSource,
                    $rightSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    0,
                    0,
                )
                || !$this->sameSourceOrConstantArgument(
                    $left->arguments[1],
                    $right->arguments[1],
                    $leftSource,
                    $rightSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    0,
                    0,
                )
            ) {
                return null;
            }
            $argumentIndex = 2;
            $isInverseQuantile = true;
        } elseif ($isPolygammaAliasPair) {
            $polygammaCall = $left->name === 'polygamma' ? $left : $right;
            $aliasName = $left->name === 'polygamma' ? $right->name : $left->name;
            if (
                \count($polygammaCall->arguments) !== 2
                || \count(($left->name === 'polygamma' ? $right : $left)->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('polygamma')
                || !$evaluationOptions->functions->isBuiltIn($aliasName)
            ) {
                return null;
            }
            try {
                $order = $extractor->extract($polygammaCall->arguments[0]);
            } catch (EvaluationException) {
                return null;
            }
            $expectedOrder = $polygammaAliasOrders[$aliasName] ?? null;
            if ($expectedOrder === null || $order !== [$expectedOrder]) {
                return null;
            }
            $leftArgument = $left->name === 'polygamma' ? $left->arguments[1] : $left->arguments[0];
            $rightArgument = $right->name === 'polygamma' ? $right->arguments[1] : $right->arguments[0];
            $requirePositiveArguments = true;
        } elseif ($left->name === 'polygamma') {
            if (\count($left->arguments) !== 2 || \count($right->arguments) !== 2) {
                return null;
            }
            $leftOrder = $extractor->extract($left->arguments[0]);
            $rightOrder = $extractor->extract($right->arguments[0]);
            if (
                $leftOrder === null
                || $rightOrder === null
                || \count($leftOrder) !== 1
                || \count($rightOrder) !== 1
                || !\is_finite($leftOrder[0])
                || $leftOrder[0] !== $rightOrder[0]
                || \floor($leftOrder[0]) !== $leftOrder[0]
                || $leftOrder[0] < 0.0
                || $leftOrder[0] > SpecialFunctions::MAX_POLYGAMMA_ORDER
            ) {
                return null;
            }
            $argumentIndex = 1;
            $requirePositiveArguments = true;
        } elseif (
            $left->name === 'trigamma'
            && \count($left->arguments) === 1
            && \count($right->arguments) === 1
        ) {
            $requirePositiveArguments = true;
        } elseif (
            \in_array($left->name, ['digamma', 'trigamma', 'tetragamma'], true)
            && \count($left->arguments) === 1
            && \count($right->arguments) === 1
        ) {
            $requirePositiveArguments = true;
        } elseif (
            $left->name === 'zeta'
            && \count($left->arguments) === 1
            && \count($right->arguments) === 1
        ) {
            $requireArgumentsAboveOne = true;
        } elseif (
            \in_array($left->name, ['gamma', 'lgamma'], true)
            && \count($left->arguments) === 1
            && \count($right->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn($left->name)
        ) {
            $requireArgumentsAtLeastThreeHalves = true;
        } elseif (
            (!$isEvenHyperbolicPair && !\in_array($left->name, $injectiveFunctions, true))
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
        ) {
            return null;
        }

        if (!$isPolygammaAliasPair) {
            if ($left->name !== 'besseli') {
                $leftArgument = $left->arguments[$argumentIndex] ?? null;
                $rightArgument = $right->arguments[$argumentIndex] ?? null;
                if (!$leftArgument instanceof Node || !$rightArgument instanceof Node) {
                    return null;
                }
            } else {
                if (!$leftArgument instanceof Node || !$rightArgument instanceof Node) {
                    return null;
                }
                foreach ([$leftArgument, $rightArgument] as $argumentNode) {
                    $argumentRange = $this->boundedExpressionRange(
                        $argumentNode,
                        $extractor,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    if (
                        $argumentRange === null
                        || $argumentRange[0] < -SpecialFunctions::MAX_BESSEL_I_ARGUMENT
                        || $argumentRange[1] > SpecialFunctions::MAX_BESSEL_I_ARGUMENT
                    ) {
                        return null;
                    }
                }
            }
        }
        if (!$leftArgument instanceof Node || !$rightArgument instanceof Node) {
            return null;
        }
        $leftSpan = $leftArgument->span();
        $rightSpan = $rightArgument->span();
        $leftArgumentSource = \substr(
            $leftSource,
            $leftSpan->start,
            $leftSpan->end - $leftSpan->start,
        );
        $rightArgumentSource = \substr(
            $rightSource,
            $rightSpan->start,
            $rightSpan->end - $rightSpan->start,
        );
        if ($requirePositiveArguments) {
            foreach (
                [
                    [$leftArgument, $leftArgumentSource],
                    [$rightArgument, $rightArgumentSource],
                ] as [$argumentNode, $argumentSource]
            ) {
                $argumentRange = $this->boundedExpressionRange(
                    $argumentNode,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null || $argumentRange[0] <= 0.0) {
                    return null;
                }
                if (
                    $extractor->extract($argumentNode) !== null
                    && !$this->isStrictlyPositivePolynomialOnInterval(
                        $argumentSource,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    )
                ) {
                    return null;
                }
            }
        }
        if ($requireArgumentsAboveOne) {
            foreach (
                [
                    [$leftArgument, $leftArgumentSource],
                    [$rightArgument, $rightArgumentSource],
                ] as [$argumentNode, $argumentSource]
            ) {
                $argumentRange = $this->boundedExpressionRange(
                    $argumentNode,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null || $argumentRange[0] <= 1.0) {
                    return null;
                }
                if (
                    $extractor->extract($argumentNode) !== null
                    && !$this->isStrictlyPositivePolynomialOnInterval(
                        '(' . $argumentSource . ')-1',
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    )
                ) {
                    return null;
                }
            }
        }
        if ($requireArgumentsAtLeastThreeHalves) {
            foreach ([$leftArgument, $rightArgument] as $argumentNode) {
                $argumentRange = $this->boundedExpressionRange(
                    $argumentNode,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null || $argumentRange[0] < 1.5) {
                    return null;
                }
            }
        }
        if ($isComplementaryInversePair) {
            $argumentEquations = ['(' . $leftArgumentSource . ')+(' . $rightArgumentSource . ')=1'];
        } elseif ($isNaturalLogOnePlusPair && $left->name === 'ln') {
            $argumentEquations = ['(' . $leftArgumentSource . ')=(1+(' . $rightArgumentSource . '))'];
        } elseif ($isNaturalLogOnePlusPair) {
            $argumentEquations = ['(1+(' . $leftArgumentSource . '))=(' . $rightArgumentSource . ')'];
        } elseif ($isExponentialUnitShiftPair && $left->name === 'exp') {
            $argumentEquations = ['exp(' . $leftArgumentSource . ')+1=exp(' . $rightArgumentSource . ')'];
        } elseif ($isExponentialUnitShiftPair) {
            $argumentEquations = ['exp(' . $leftArgumentSource . ')-1=exp(' . $rightArgumentSource . ')'];
        } elseif ($isEvenHyperbolicPair) {
            $argumentEquations = [
                '(' . $leftArgumentSource . ')=(' . $rightArgumentSource . ')',
                '(' . $leftArgumentSource . ')=-(' . $rightArgumentSource . ')',
            ];
        } else {
            $argumentEquations = ['(' . $leftArgumentSource . ')=(' . $rightArgumentSource . ')'];
        }
        if ($isEvenBesselI) {
            $argumentEquations[] = '(' . $leftArgumentSource . ')=-(' . $rightArgumentSource . ')';
        }

        $candidates = [];
        foreach ($argumentEquations as $argumentEquation) {
            if (\strlen($argumentEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                array_push(
                    $candidates,
                    ...$this->solve(
                        $argumentEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ),
                );
            } catch (InfiniteSolutionSetException $exception) {
                if ($isBesselI || $isEvenHyperbolicPair) {
                    throw $exception;
                }
                return null;
            } catch (\DomainException) {
                return null;
            }
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            $gammaQuantileOutputsAreFinite = false;
            if ($isInverseQuantile) {
                $candidateParameters = [...$parameters, $variable => $candidate->value];
                try {
                    $leftValue = $this->evaluateNode($left, $candidateParameters, $evaluationOptions);
                    $rightValue = $this->evaluateNode($right, $candidateParameters, $evaluationOptions);
                    $gammaQuantileOutputsAreFinite = \is_finite($leftValue) && \is_finite($rightValue);
                } catch (EvaluationException | \DomainException | \OverflowException) {
                    $gammaQuantileOutputsAreFinite = false;
                }
            }
            $erfcxOutputOverflowed = false;
            if ($residual === null && $left->name === 'erfcx') {
                $candidateParameters = [...$parameters, $variable => $candidate->value];
                try {
                    $leftValue = $this->evaluateNode($leftArgument, $candidateParameters, $evaluationOptions);
                    $rightValue = $this->evaluateNode($rightArgument, $candidateParameters, $evaluationOptions);
                    $erfcxOutputOverflowed = \is_finite($leftValue) && \is_finite($rightValue);
                } catch (EvaluationException | \DomainException | \OverflowException) {
                    $erfcxOutputOverflowed = false;
                }
            }
            if ($residual === null) {
                if (!$gammaQuantileOutputsAreFinite && !$erfcxOutputOverflowed) {
                    continue;
                }
                $residual = 0.0;
            }
            if (
                !$erfcxOutputOverflowed
                && !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce betaincinv(a, b, p) + betainccinv(b, a, q) = 1 to p = q.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveShapeSwappedBetaQuantileSumEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $sides = [
            [$left, $right, $leftSource, $rightSource, 0, 0],
            [$right, $left, $rightSource, $leftSource, 0, 0],
        ];
        foreach (
            $sides as [
                $sumSide,
                $targetSide,
                $sumSource,
                $targetSource,
                $sumSourceOffset,
                $targetSourceOffset,
            ]
        ) {
            try {
                $targetCoefficients = $extractor->extract($targetSide);
            } catch (EvaluationException) {
                $targetCoefficients = null;
            }
            $sumSide = $this->unwrapGrouping($sumSide);
            $firstCallSource = $sumSource;
            $secondCallSource = $sumSource;
            $firstCallSourceOffset = $sumSourceOffset;
            $secondCallSourceOffset = $sumSourceOffset;
            if (
                $targetCoefficients === [1.0]
                && $sumSide instanceof BinaryOperationNode
                && $sumSide->operator === BinaryOperator::Add
            ) {
                $firstCall = $this->unwrapGrouping($sumSide->left);
                $secondCall = $this->unwrapGrouping($sumSide->right);
            } elseif ($sumSide instanceof FunctionCallNode) {
                $targetSide = $this->unwrapGrouping($targetSide);
                if (
                    !$targetSide instanceof BinaryOperationNode
                    || $targetSide->operator !== BinaryOperator::Subtract
                ) {
                    continue;
                }
                try {
                    $unit = $extractor->extract($targetSide->left);
                } catch (EvaluationException) {
                    continue;
                }
                $secondCall = $this->unwrapGrouping($targetSide->right);
                if ($unit !== [1.0] || !$secondCall instanceof FunctionCallNode) {
                    continue;
                }
                $firstCall = $sumSide;
                $secondCallSource = $targetSource;
                $secondCallSourceOffset = $targetSourceOffset;
            } else {
                continue;
            }
            if (
                !$firstCall instanceof FunctionCallNode
                || !$secondCall instanceof FunctionCallNode
                || !\in_array(
                    [$firstCall->name, $secondCall->name],
                    [
                        ['betaincinv', 'betainccinv'],
                        ['betainccinv', 'betaincinv'],
                        ['betaincinv', 'betaincinv'],
                        ['betainccinv', 'betainccinv'],
                    ],
                    true,
                )
                || \count($firstCall->arguments) !== 3
                || \count($secondCall->arguments) !== 3
                || !$evaluationOptions->functions->isBuiltIn($firstCall->name)
                || !$evaluationOptions->functions->isBuiltIn($secondCall->name)
                || !$this->sameSourceOrConstantArgument(
                    $firstCall->arguments[0],
                    $secondCall->arguments[1],
                    $firstCallSource,
                    $secondCallSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    $firstCallSourceOffset,
                    $secondCallSourceOffset,
                )
                || !$this->sameSourceOrConstantArgument(
                    $firstCall->arguments[1],
                    $secondCall->arguments[0],
                    $firstCallSource,
                    $secondCallSource,
                    $extractor,
                    $variable,
                    $parameters,
                    $solverOptions->maxPolynomialDegree,
                    $firstCallSourceOffset,
                    $secondCallSourceOffset,
                )
            ) {
                continue;
            }

            $firstProbability = $firstCall->arguments[2];
            $secondProbability = $secondCall->arguments[2];
            $firstSpan = $firstProbability->span();
            $secondSpan = $secondProbability->span();
            $firstSource = \substr(
                $firstCallSource,
                $firstSpan->start - $firstCallSourceOffset,
                $firstSpan->end - $firstSpan->start,
            );
            $secondSource = \substr(
                $secondCallSource,
                $secondSpan->start - $secondCallSourceOffset,
                $secondSpan->end - $secondSpan->start,
            );
            $probabilityEquation = $firstCall->name === $secondCall->name
                ? '(' . $firstSource . ')+(' . $secondSource . ')=1'
                : '(' . $firstSource . ')=(' . $secondSource . ')';
            if (\strlen($probabilityEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                $candidates = $this->solve(
                    $probabilityEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (InfiniteSolutionSetException | \DomainException) {
                return null;
            }

            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $solverOptions,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Isolate the defined zero levels of beta(sin(P(x)), cos(P(x))).
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSamePhaseTrigBetaZeroEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [[$left, $right, $leftSource, 0], [$right, $left, $rightSource, $rightOffset]]
            as [$candidate, $target, $source, $sourceOffset]
        ) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            try {
                if ($extractor->extract($target) !== [0.0]) {
                    continue;
                }
            } catch (EvaluationException) {
                continue;
            }
            $first = $this->unwrapGrouping($candidate->arguments[0]);
            $second = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                !$first instanceof FunctionCallNode
                || !$second instanceof FunctionCallNode
                || !\in_array($first->name, ['sin', 'cos'], true)
                || !\in_array($second->name, ['sin', 'cos'], true)
                || !$evaluationOptions->functions->isBuiltIn($first->name)
                || !$evaluationOptions->functions->isBuiltIn($second->name)
                || \count($first->arguments) !== 1
                || \count($second->arguments) !== 1
            ) {
                continue;
            }
            try {
                $phase = $extractor->extract($first->arguments[0]);
                $secondPhase = $extractor->extract($second->arguments[0]);
            } catch (EvaluationException) {
                continue;
            }
            if (
                $phase === null
                || $secondPhase === null
                || \count($phase) !== \count($secondPhase)
                || \count($phase) < 2
                || \array_slice($phase, 1) !== \array_slice($secondPhase, 1)
                || !$this->containsVariable($first->arguments[0], $variable)
                || !$this->containsVariable($second->arguments[0], $variable)
            ) {
                continue;
            }
            $phaseSpan = $first->arguments[0]->span();
            $phaseSource = \substr(
                $source,
                $phaseSpan->start - $sourceOffset,
                $phaseSpan->end - $phaseSpan->start,
            );
            $phaseRange = $this->boundedExpressionRange(
                $first->arguments[0],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($phaseRange === null) {
                return null;
            }
            if (\max(\abs($phaseRange[0]), \abs($phaseRange[1])) > 1.0E14) {
                return null;
            }

            $phaseDifference = $secondPhase[0] - $phase[0];
            $sineDifference = \sin($phaseDifference);
            $cosineDifference = \cos($phaseDifference);
            if ($first->name === 'sin' && $second->name === 'sin') {
                $sineCoefficient = 1.0 + $cosineDifference;
                $cosineCoefficient = $sineDifference;
            } elseif ($first->name === 'cos' && $second->name === 'cos') {
                $sineCoefficient = -$sineDifference;
                $cosineCoefficient = 1.0 + $cosineDifference;
            } elseif ($first->name === 'sin') {
                $sineCoefficient = 1.0 - $sineDifference;
                $cosineCoefficient = $cosineDifference;
            } else {
                $sineCoefficient = $cosineDifference;
                $cosineCoefficient = 1.0 + $sineDifference;
            }
            $amplitude = \sqrt(($sineCoefficient * $sineCoefficient) + ($cosineCoefficient * $cosineCoefficient));
            if ($amplitude <= 128.0 * \PHP_FLOAT_EPSILON) {
                return null;
            }
            $trigPhaseOffset = \atan2($cosineCoefficient, $sineCoefficient);
            $levelEquations = [];
            $levelTolerance = 64.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($phaseRange[0]), \abs($phaseRange[1]));
            $phasePeriod = 2.0 * \M_PI;
            $levelCount = 0;
            for ($integerLevel = 0; $integerLevel <= 2; ++$integerLevel) {
                $target = -$integerLevel / $amplitude;
                if (\abs($target) > 1.0 + (64.0 * \PHP_FLOAT_EPSILON)) {
                    continue;
                }
                $target = \max(-1.0, \min(1.0, $target));
                $principal = \asin($target);
                $phaseOffsets = [
                    $principal - $trigPhaseOffset,
                    \M_PI - $principal - $trigPhaseOffset,
                ];
                foreach ($phaseOffsets as $phaseOffset) {
                    $firstPeriod = \ceil(($phaseRange[0] - $phaseOffset - $levelTolerance) / $phasePeriod);
                    $lastPeriod = \floor(($phaseRange[1] - $phaseOffset + $levelTolerance) / $phasePeriod);
                    if ($lastPeriod < $firstPeriod) {
                        continue;
                    }
                    if (
                        !\is_finite($firstPeriod)
                        || !\is_finite($lastPeriod)
                        || \abs($firstPeriod) > 4_503_599_627_370_496.0
                        || \abs($lastPeriod) > 4_503_599_627_370_496.0
                    ) {
                        throw new RootSearchLimitException(
                            \sprintf(
                                'The equation requires more than %d periodic root levels.',
                                self::MAX_PERIODIC_ROOTS,
                            ),
                        );
                    }
                    for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                        $phaseLevel = $phaseOffset + ($periodIndex * $phasePeriod);
                        $duplicate = false;
                        foreach ($levelEquations as [$existingLevel, $existingIntegerLevel]) {
                            if (
                                $existingIntegerLevel === $integerLevel
                                && \abs($existingLevel - $phaseLevel) <= $levelTolerance
                            ) {
                                $duplicate = true;
                                break;
                            }
                        }
                        if ($duplicate) {
                            continue;
                        }
                        if (++$levelCount > self::MAX_PERIODIC_ROOTS) {
                            throw new RootSearchLimitException(
                                \sprintf(
                                    'The equation requires more than %d periodic root levels.',
                                    self::MAX_PERIODIC_ROOTS,
                                ),
                            );
                        }
                        $levelEquations[] = [$phaseLevel, $integerLevel];
                    }
                }
            }
            $solutions = [];
            $candidateCount = 0;
            foreach ($levelEquations as [$phaseLevel, $integerLevel]) {
                $equation = '(' . $phaseSource . ')=' . \sprintf('%.17g', $phaseLevel);
                if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $candidates = $this->solve(
                        $equation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (InfiniteSolutionSetException | \DomainException) {
                    return null;
                }
                foreach ($candidates as $candidateRoot) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        throw new RootSearchLimitException(
                            \sprintf(
                                'The equation requires more than %d periodic root candidates.',
                                self::MAX_PERIODIC_ROOTS,
                            ),
                        );
                    }
                    $candidateParameters = [...$parameters, $variable => $candidateRoot->value];
                    try {
                        $firstValue = (float) $this->evaluateNode($first, $candidateParameters, $evaluationOptions);
                        $secondValue = (float) $this->evaluateNode($second, $candidateParameters, $evaluationOptions);
                    } catch (EvaluationException | \DomainException | \OverflowException) {
                        continue;
                    }
                    $levelResidual = \abs($firstValue + $secondValue + $integerLevel);
                    $levelScale = \max(1.0, \abs($firstValue) + \abs($secondValue));
                    if (
                        !$this->isResidualAcceptableAt(
                            $candidateRoot->value,
                            $levelResidual,
                            static fn (float $value): float => $levelScale,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $residual = $residualAt($candidateRoot->value);
                    if (
                        $residual === null
                        || !\is_finite($residual)
                        || !$this->isResidualAcceptableAt(
                            $candidateRoot->value,
                            $residual,
                            static fn (float $value): float => 1.0,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidateRoot->value,
                            \abs($residual),
                            $candidateRoot->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve finite-interval beta zero levels for argument families without a specialized reducer.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solveGeneralBetaZeroLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
    ): ?array {
        foreach (
            [[$left, $right, $leftSource, 0], [$right, $left, $rightSource, $rightOffset]]
            as [$candidate, $target, $source, $sourceOffset]
        ) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            $isZeroTarget = $this->isIdenticallyZeroBetaTarget(
                $target,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if (!$isZeroTarget) {
                continue;
            }

            $first = $candidate->arguments[0];
            $second = $candidate->arguments[1];
            if (!$this->containsVariable($first, $variable) && !$this->containsVariable($second, $variable)) {
                continue;
            }
            $firstRange = $this->evaluateIntervalExpression(
                $first,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            $secondRange = $this->evaluateIntervalExpression(
                $second,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            if ($firstRange === null || $secondRange === null) {
                continue;
            }
            $sumRange = $this->widenInterval(
                $firstRange[0] + $secondRange[0],
                $firstRange[1] + $secondRange[1],
            );
            if ($sumRange === null || !\is_finite($sumRange[0]) || !\is_finite($sumRange[1])) {
                continue;
            }
            if ($sumRange[0] < -342.0) {
                continue;
            }

            $firstSpan = $first->span();
            $secondSpan = $second->span();
            $firstSource = \substr(
                $source,
                $firstSpan->start - $sourceOffset,
                $firstSpan->end - $firstSpan->start,
            );
            $secondSource = \substr(
                $source,
                $secondSpan->start - $sourceOffset,
                $secondSpan->end - $secondSpan->start,
            );
            $minimumLevel = (int) \max(0.0, \ceil(-$sumRange[1]));
            $maximumLevel = (int) \min(342.0, \floor(-$sumRange[0]));
            if ($minimumLevel > $maximumLevel) {
                return [];
            }
            $solutions = [];
            $differentiator = new ArithmeticDifferentiator();
            $polynomialExtractor = new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            );
            $sumPolynomial = $this->extractAdditivePolynomialAfterCancellation(
                $first,
                $second,
                $polynomialExtractor,
            );
            for ($level = $minimumLevel; $level <= $maximumLevel; ++$level) {
                $equation = '(' . $firstSource . ')+(' . $secondSource . ')=' . (-$level);
                if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                if ($sumPolynomial !== null) {
                    $levelPolynomial = $sumPolynomial;
                    $levelPolynomial[0] += $level;
                    $candidates = $this->solvePolynomialRootsInInterval(
                        $levelPolynomial,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($candidates === null) {
                        return null;
                    }
                    if (\count($levelPolynomial) > 2) {
                        $derivativePolynomial = [];
                        foreach ($levelPolynomial as $power => $coefficient) {
                            if ($power > 0) {
                                $derivativePolynomial[] = $power * $coefficient;
                            }
                        }
                        $criticalPoints = $this->solvePolynomialRootsInInterval(
                            $derivativePolynomial,
                            $lowerBound,
                            $upperBound,
                            $solverOptions,
                        );
                        foreach ($criticalPoints ?? [] as $criticalPoint) {
                            $criticalParameters = [$variable => $criticalPoint->value] + $parameters;
                            try {
                                $criticalLevel = (float) $this->evaluateNode(
                                    $first,
                                    $criticalParameters,
                                    $evaluationOptions,
                                ) + (float) $this->evaluateNode(
                                    $second,
                                    $criticalParameters,
                                    $evaluationOptions,
                                ) + $level;
                            } catch (EvaluationException | \DomainException | \OverflowException) {
                                continue;
                            }
                            if ($criticalLevel !== 0.0) {
                                continue;
                            }
                            $positionTolerance = 8.0 * \sqrt(\PHP_FLOAT_EPSILON)
                                * \max(1.0, \abs($criticalPoint->value));
                            $leftIndex = null;
                            $rightIndex = null;
                            foreach ($candidates as $candidateIndex => $candidate) {
                                $distance = $candidate->value - $criticalPoint->value;
                                if ($distance < 0.0 && \abs($distance) <= $positionTolerance) {
                                    $leftIndex = $candidateIndex;
                                } elseif ($distance > 0.0 && $distance <= $positionTolerance) {
                                    $rightIndex = $candidateIndex;
                                }
                            }
                            if ($leftIndex === null || $rightIndex === null) {
                                continue;
                            }
                            unset($candidates[$leftIndex], $candidates[$rightIndex]);
                            $candidates[] = new EquationSolution($criticalPoint->value, 0.0, 0);
                            $candidates = \array_values($candidates);
                        }
                    }
                } else {
                    try {
                        $candidates = $this->solve(
                            $equation,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (InfiniteSolutionSetException | \DomainException) {
                        return null;
                    }
                }
                foreach ($candidates as $root) {
                    $candidate = $root->value;
                    $bestCandidate = $candidate;
                    $bestLevelResidual = \INF;
                    for ($iteration = 0; $iteration < 12; ++$iteration) {
                        $candidateParameters = [$variable => $candidate] + $parameters;
                        try {
                            $firstValue = (float) $this->evaluateNode($first, $candidateParameters, $evaluationOptions);
                            $secondValue = (float) $this->evaluateNode($second, $candidateParameters, $evaluationOptions);
                        } catch (EvaluationException | \DomainException | \OverflowException) {
                            break;
                        }
                        $levelResidual = $firstValue + $secondValue + $level;
                        if (!\is_finite($levelResidual)) {
                            break;
                        }
                        if (\abs($levelResidual) < $bestLevelResidual) {
                            $bestLevelResidual = \abs($levelResidual);
                            $bestCandidate = $candidate;
                        }
                        $firstDerivative = $differentiator->differentiate(
                            $first,
                            $variable,
                            $candidate,
                            $parameters,
                            $evaluationOptions,
                        );
                        $secondDerivative = $differentiator->differentiate(
                            $second,
                            $variable,
                            $candidate,
                            $parameters,
                            $evaluationOptions,
                        );
                        if ($firstDerivative === null || $secondDerivative === null) {
                            break;
                        }
                        $slope = $firstDerivative + $secondDerivative;
                        if (!\is_finite($slope) || $slope === 0.0) {
                            break;
                        }
                        $nextCandidate = $candidate - ($levelResidual / $slope);
                        if (
                            !\is_finite($nextCandidate)
                            || $nextCandidate < $lowerBound
                            || $nextCandidate > $upperBound
                            || $nextCandidate === $candidate
                        ) {
                            break;
                        }
                        $candidate = $nextCandidate;
                    }
                    $candidate = $bestCandidate;
                    try {
                        $candidateParameters = [$variable => $candidate] + $parameters;
                        $firstValue = (float) $this->evaluateNode($first, $candidateParameters, $evaluationOptions);
                        $secondValue = (float) $this->evaluateNode($second, $candidateParameters, $evaluationOptions);
                    } catch (EvaluationException) {
                        continue;
                    }
                    $poleTolerance = 1.0E-8;
                    if (
                        (\round($firstValue) <= 0.0 && \abs($firstValue - \round($firstValue)) <= $poleTolerance)
                        || (\round($secondValue) <= 0.0 && \abs($secondValue - \round($secondValue)) <= $poleTolerance)
                    ) {
                        continue;
                    }
                    $residual = $residualAt($candidate);
                    if ($residual === null || !\is_finite($residual)) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($residual), $root->iterations),
                        $solverOptions,
                    );
                }
            }
            \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

            return $solutions;
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function isIdenticallyZeroBetaTarget(
        Node $target,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        if (!$this->containsVariable($target, $variable)) {
            try {
                return (float) $this->evaluateNode($target, $parameters, $evaluationOptions) === 0.0;
            } catch (EvaluationException) {
                return false;
            }
        }

        $zero = new NumberNode(0, '0', $target->span());
        $exactPolynomial = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        try {
            if ($exactPolynomial->difference($target, $zero) === ['0']) {
                return true;
            }
        } catch (EvaluationException) {
            // Leave unresolved targets to the general equation solver.
        }

        $target = $this->unwrapGrouping($target);
        if (!$target instanceof BinaryOperationNode) {
            return false;
        }
        if (
            $target->operator === BinaryOperator::Subtract
            && $this->isSineCosineSquareSum($target->left, $evaluationOptions)
            && $this->isOneNumber($target->right)
        ) {
            return true;
        }
        $left = $this->unwrapGrouping($target->left);
        $right = $this->unwrapGrouping($target->right);
        if ($target->operator === BinaryOperator::Subtract) {
            return $this->sameExpression($left, $right);
        }
        if ($target->operator !== BinaryOperator::Add) {
            return false;
        }

        return ($left instanceof UnaryOperationNode
                && $left->operator === UnaryOperator::Minus
                && $this->sameExpression($left->operand, $right))
            || ($right instanceof UnaryOperationNode
                && $right->operator === UnaryOperator::Minus
                && $this->sameExpression($right->operand, $left));
    }

    private function isSineCosineSquareSum(Node $node, EvaluationOptions $evaluationOptions): bool
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Add) {
            return false;
        }
        $first = $this->squaredTrigonometricCall($node->left, $evaluationOptions);
        $second = $this->squaredTrigonometricCall($node->right, $evaluationOptions);

        return $first !== null
            && $second !== null
            && $first[0] !== $second[0]
            && $this->sameExpression($first[1], $second[1]);
    }

    /** @return array{string, Node}|null */
    private function squaredTrigonometricCall(Node $node, EvaluationOptions $evaluationOptions): ?array
    {
        $node = $this->unwrapGrouping($node);
        if (
            !$node instanceof BinaryOperationNode
            || $node->operator !== BinaryOperator::Power
            || !$this->isTwoNumber($node->right)
        ) {
            return null;
        }
        $call = $this->unwrapGrouping($node->left);
        if (
            !$call instanceof FunctionCallNode
            || !\in_array($call->name, ['sin', 'cos'], true)
            || \count($call->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn($call->name)
        ) {
            return null;
        }

        return [$call->name, $call->arguments[0]];
    }

    private function isOneNumber(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);

        return $node instanceof NumberNode && (float) $node->value === 1.0;
    }

    private function isTwoNumber(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);

        return $node instanceof NumberNode && (float) $node->value === 2.0;
    }

    /**
     * Solve beta(sec(P(x)), csc(P(x))) = 0 through its exact sum-level equation.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveReciprocalTrigBetaZeroEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [[$left, $right, $leftSource, 0], [$right, $left, $rightSource, $rightOffset]]
            as [$candidate, $target, $source, $sourceOffset]
        ) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            try {
                if ($extractor->extract($target) !== [0.0]) {
                    continue;
                }
            } catch (EvaluationException) {
                continue;
            }
            $first = $this->unwrapGrouping($candidate->arguments[0]);
            $second = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                !$first instanceof FunctionCallNode
                || !$second instanceof FunctionCallNode
                || !\in_array([$first->name, $second->name], [['sec', 'csc'], ['csc', 'sec']], true)
                || !$evaluationOptions->functions->isBuiltIn($first->name)
                || !$evaluationOptions->functions->isBuiltIn($second->name)
                || \count($first->arguments) !== 1
                || \count($second->arguments) !== 1
            ) {
                continue;
            }
            try {
                $phase = $extractor->extract($first->arguments[0]);
                $secondPhase = $extractor->extract($second->arguments[0]);
            } catch (EvaluationException) {
                continue;
            }
            if (
                $phase === null
                || $phase !== $secondPhase
                || \count($phase) < 2
                || !$this->containsVariable($first->arguments[0], $variable)
                || !$this->containsVariable($second->arguments[0], $variable)
            ) {
                continue;
            }
            $firstSpan = $first->arguments[0]->span();
            $phaseSource = \substr(
                $source,
                $firstSpan->start - $sourceOffset,
                $firstSpan->end - $firstSpan->start,
            );
            $phaseRange = $this->boundedExpressionRange(
                $first->arguments[0],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($phaseRange === null) {
                return null;
            }
            $hasReciprocalPole = $this->containsPeriodicPhase(
                $phaseRange[0],
                $phaseRange[1],
                0.0,
                \M_PI / 2.0,
            );
            $firstIntegerLevel = 0;
            // beta() rejects either argument below -171 and sums below -171.
            $maximumIntegerLevel = 171;
            if (!$hasReciprocalPole) {
                $firstEndpointSum = 1.0 / \sin($phaseRange[0]) + 1.0 / \cos($phaseRange[0]);
                $secondEndpointSum = 1.0 / \sin($phaseRange[1]) + 1.0 / \cos($phaseRange[1]);
                $minimumReciprocalSum = \min($firstEndpointSum, $secondEndpointSum);
                $maximumReciprocalSum = \max($firstEndpointSum, $secondEndpointSum);
                $firstCriticalIndex = (int) \ceil(($phaseRange[0] - \M_PI / 4.0) / \M_PI);
                $lastCriticalIndex = (int) \floor(($phaseRange[1] - \M_PI / 4.0) / \M_PI);
                for (
                    $criticalIndex = $firstCriticalIndex;
                    $criticalIndex <= $lastCriticalIndex;
                    ++$criticalIndex
                ) {
                    $criticalPhase = \M_PI / 4.0 + ($criticalIndex * \M_PI);
                    $criticalSum = 1.0 / \sin($criticalPhase) + 1.0 / \cos($criticalPhase);
                    $minimumReciprocalSum = \min($minimumReciprocalSum, $criticalSum);
                    $maximumReciprocalSum = \max($maximumReciprocalSum, $criticalSum);
                }
                $levelTolerance = 16.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($minimumReciprocalSum), \abs($maximumReciprocalSum));
                $firstIntegerLevel = \max(0, (int) \ceil(-$maximumReciprocalSum - $levelTolerance));
                $maximumIntegerLevel = \min(
                    171,
                    \max(0, (int) \floor(-$minimumReciprocalSum + $levelTolerance)),
                );
            }
            if ($maximumIntegerLevel < $firstIntegerLevel) {
                return [];
            }
            $minimumPhaseValue = \sin($phaseRange[0]) + \cos($phaseRange[0]);
            $maximumPhaseValue = \sin($phaseRange[1]) + \cos($phaseRange[1]);
            $minimumSumLevel = \min($minimumPhaseValue, $maximumPhaseValue);
            $maximumSumLevel = \max($minimumPhaseValue, $maximumPhaseValue);
            if ($this->containsPeriodicPhase($phaseRange[0], $phaseRange[1], -3.0 * \M_PI / 4.0)) {
                $minimumSumLevel = -\sqrt(2.0);
            }
            if ($this->containsPeriodicPhase($phaseRange[0], $phaseRange[1], \M_PI / 4.0)) {
                $maximumSumLevel = \sqrt(2.0);
            }
            $rangeTolerance = 64.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimumSumLevel), \abs($maximumSumLevel));
            $solutions = [];
            $candidateCount = 0;
            $phaseDerivative = $this->polynomialDerivative($phase);
            $phaseSolver = new PolynomialSolver();
            for (
                $integerLevel = $firstIntegerLevel;
                $integerLevel <= $maximumIntegerLevel;
                ++$integerLevel
            ) {
                if ($integerLevel === 0) {
                    $phaseLevels = [0.0];
                } else {
                    $root = \sqrt(1.0 + ($integerLevel * $integerLevel));
                    $phaseLevels = [
                        $integerLevel / ($root + 1.0),
                        -($root + 1.0) / $integerLevel,
                    ];
                }
                foreach ($phaseLevels as $phaseLevel) {
                    if (
                        \abs($phaseLevel) > \sqrt(2.0)
                        || $phaseLevel < $minimumSumLevel - $rangeTolerance
                        || $phaseLevel > $maximumSumLevel + $rangeTolerance
                    ) {
                        continue;
                    }
                    $equation = 'sin((' . $phaseSource . ')) + cos((' . $phaseSource . '))='
                        . \sprintf('%.17g', $phaseLevel);
                    if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
                        return null;
                    }
                    try {
                        $candidates = $this->solve(
                            $equation,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (InfiniteSolutionSetException $exception) {
                        throw $exception;
                    } catch (\DomainException) {
                        return null;
                    }
                    foreach ($candidates as $candidateRoot) {
                        if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                            throw new RootSearchLimitException(
                                \sprintf(
                                    'The equation requires more than %d periodic root candidates.',
                                    self::MAX_PERIODIC_ROOTS,
                                ),
                            );
                        }
                        $rootValue = $candidateRoot->value;
                        for ($refinement = 0; $refinement < 8; ++$refinement) {
                            $rootParameters = [...$parameters, $variable => $rootValue];
                            try {
                                $phaseValue = $this->evaluateNode(
                                    $first->arguments[0],
                                    $rootParameters,
                                    $evaluationOptions,
                                );
                            } catch (EvaluationException | \DomainException | \OverflowException) {
                                break;
                            }
                            $phaseResidual = \sin($phaseValue) + \cos($phaseValue) - $phaseLevel;
                            $phaseSlope = $phaseSolver->evaluatePolynomial($phaseDerivative, $rootValue);
                            $derivative = (\cos($phaseValue) - \sin($phaseValue)) * $phaseSlope;
                            if ($derivative === 0.0 || !\is_finite($derivative)) {
                                break;
                            }
                            $nextValue = $rootValue - ($phaseResidual / $derivative);
                            if (
                                !\is_finite($nextValue)
                                || $nextValue < $lowerBound
                                || $nextValue > $upperBound
                                || $nextValue === $rootValue
                            ) {
                                break;
                            }
                            try {
                                $nextPhase = $this->evaluateNode(
                                    $first->arguments[0],
                                    [...$parameters, $variable => $nextValue],
                                    $evaluationOptions,
                                );
                            } catch (EvaluationException | \DomainException | \OverflowException) {
                                break;
                            }
                            $nextResidual = \sin($nextPhase) + \cos($nextPhase) - $phaseLevel;
                            if (\abs($nextResidual) >= \abs($phaseResidual)) {
                                break;
                            }
                            $rootValue = $nextValue;
                        }
                        $candidateParameters = [...$parameters, $variable => $rootValue];
                        try {
                            $firstValue = $this->evaluateNode(
                                $first,
                                $candidateParameters,
                                $evaluationOptions,
                            );
                            $secondValue = $this->evaluateNode(
                                $second,
                                $candidateParameters,
                                $evaluationOptions,
                            );
                        } catch (EvaluationException | \DomainException | \OverflowException) {
                            continue;
                        }
                        $levelResidual = \abs($firstValue + $secondValue + $integerLevel);
                        $levelScale = \max(
                            1.0,
                            \abs($firstValue) + \abs($secondValue),
                            (float) $integerLevel,
                        );
                        if (
                            !$this->isResidualAcceptableAt(
                                $rootValue,
                                $levelResidual,
                                static fn (float $value): float => $levelScale,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $residual = $residualAt($rootValue);
                        if ($residual === null || !\is_finite($residual)) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution(
                                $rootValue,
                                \abs($residual),
                                $candidateRoot->iterations,
                            ),
                            $solverOptions,
                        );
                    }
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * @param list<float> $coefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @param list<string>|null $exactCoefficients
     * @return list<EquationSolution>|null
     */
    private function recoverRealRootsFromComplexPolynomial(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        callable $residualAt,
        callable $candidateScaleAt,
        SolverOptions $options,
        ?array $exactCoefficients,
        bool $scaleAwarePosition = false,
        bool $allowSubnormalConvergence = false,
    ): ?array {
        $solution = (new ComplexPolynomialSolver())->solve($coefficients, $options, $exactCoefficients);
        if (
            (!$solution->converged && !$allowSubnormalConvergence)
            || $solution->degree !== \count($coefficients) - 1
        ) {
            return null;
        }

        $realRoots = [];
        foreach ($solution->roots as $root) {
            $positionScale = \max(\abs($root->real), \abs($root->imaginary));
            if ($scaleAwarePosition && !$solution->converged) {
                $minimumSubnormal = \PHP_FLOAT_MIN * \PHP_FLOAT_EPSILON;
                $representabilityResidual = $positionScale === 0.0
                    ? 1.0
                    : \min(1.0, (2.0 * $minimumSubnormal) / $positionScale);
                if ($root->residual > \max($options->residualTolerance, $representabilityResidual)) {
                    continue;
                }
            }
            $positionTolerance = $scaleAwarePosition
                ? \max(\PHP_FLOAT_EPSILON * $positionScale, $options->relativeTolerance * $positionScale)
                : $options->positionTolerance($root->real, $root->real);
            $imaginaryIsRootNoise = \abs($root->imaginary) <= $positionTolerance;
            if (
                !$imaginaryIsRootNoise
                && $scaleAwarePosition
                && $exactCoefficients !== null
                && \abs($root->imaginary) <= 1.0E-6 * \abs($root->real)
            ) {
                $candidateScale = \max(\abs($root->real), \abs($root->imaginary));
                $realnessRadius = \max(
                    2.0 * \sqrt(\PHP_FLOAT_EPSILON) * $candidateScale,
                    16.0 * \abs($root->imaginary),
                );
                $realnessLower = RationalLiteral::fromFloatAsStrings($root->real - $realnessRadius);
                $realnessUpper = RationalLiteral::fromFloatAsStrings($root->real + $realnessRadius);
                if ($realnessLower !== null && $realnessUpper !== null) {
                    $nearbyRealRootCount = (new ExactPolynomialRootCounter())->countOpenInterval(
                        $exactCoefficients,
                        $realnessLower[0],
                        $realnessLower[1],
                        $realnessUpper[0],
                        $realnessUpper[1],
                    );
                    $imaginaryIsRootNoise = $nearbyRealRootCount !== null && $nearbyRealRootCount > 0;
                }
            }
            if (
                !$imaginaryIsRootNoise
                || $root->real < $lowerBound
                || $root->real > $upperBound
            ) {
                continue;
            }
            $residual = $residualAt($root->real);
            $usedNormalizedResidual = $residual === null
                && $scaleAwarePosition
                && $exactCoefficients !== null
                && $root->residual <= $options->residualTolerance
                && $root->real >= $lowerBound
                && $root->real <= $upperBound;
            if ($usedNormalizedResidual) {
                $residual = $root->residual;
            }
            if (
                $residual === null
                || (!$usedNormalizedResidual && !$this->isResidualAcceptableAt(
                    $root->real,
                    $residual,
                    $candidateScaleAt,
                    $options,
                ))
            ) {
                continue;
            }

            $duplicate = false;
            foreach ($realRoots as $realRoot) {
                if (
                    \abs($realRoot->value - $root->real)
                        <= ($scaleAwarePosition
                            ? \max(
                                \PHP_FLOAT_EPSILON * \max(\abs($realRoot->value), \abs($root->real)),
                                $options->relativeTolerance * \max(\abs($realRoot->value), \abs($root->real)),
                            )
                            : $options->positionTolerance($realRoot->value, $root->real))
                ) {
                    $duplicate = true;
                    break;
                }
            }
            if (!$duplicate) {
                $realRoots[] = new EquationSolution(
                    $root->real,
                    \abs($residual),
                    $solution->iterations,
                );
            }
        }
        \usort(
            $realRoots,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );

        return $realRoots;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function sameSourceOrConstantArgument(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        PolynomialExtractor $extractor,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        int $leftSourceOffset = 0,
        int $rightSourceOffset = 0,
    ): bool {
        $leftSpan = $left->span();
        $rightSpan = $right->span();
        if (
            \substr(
                $leftSource,
                $leftSpan->start - $leftSourceOffset,
                $leftSpan->end - $leftSpan->start,
            )
            === \substr(
                $rightSource,
                $rightSpan->start - $rightSourceOffset,
                $rightSpan->end - $rightSpan->start,
            )
        ) {
            return true;
        }

        $integerExtractor = new IntegerPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
        );
        $leftIntegerPolynomial = $integerExtractor->extract($left);
        $rightIntegerPolynomial = $integerExtractor->extract($right);
        if (
            $leftIntegerPolynomial !== null
            && $leftIntegerPolynomial === $rightIntegerPolynomial
        ) {
            return true;
        }

        try {
            $leftValue = $extractor->extract($left);
            $rightValue = $extractor->extract($right);
        } catch (EvaluationException) {
            return false;
        }

        return $leftValue !== null
            && $rightValue !== null
            && \count($leftValue) === 1
            && \count($rightValue) === 1
            && \is_finite($leftValue[0])
            && \is_finite($rightValue[0])
            && $leftValue[0] === $rightValue[0];
    }

    /**
     * Reduce root(f(x), n) = g(x) to f(x) = g(x)^n for constant integer n.
     * Candidate verification against the original equation enforces the real
     * root's principal branch and excludes points outside its domain.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveIntegerRootEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && $left->name === 'root') {
            $function = $left;
            $functionSource = $leftSource;
            $targetSource = $rightSource;
            $target = $right;
        } elseif ($right instanceof FunctionCallNode && $right->name === 'root') {
            $function = $right;
            $functionSource = $rightSource;
            $targetSource = $leftSource;
            $target = $left;
        } else {
            return null;
        }
        if (\count($function->arguments) !== 2) {
            return null;
        }

        $degreeCoefficients = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        if ($degreeCoefficients === null || \count($degreeCoefficients) !== 1) {
            return null;
        }
        $normalizedDegree = $this->normalizedIntegerRootDegree($degreeCoefficients[0]);
        if ($normalizedDegree === null) {
            return null;
        }
        $degree = (float) $normalizedDegree;
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $target,
            $target->span()->start,
        );
        if (
            $targetCoefficients !== null
            && \count($targetCoefficients) === 1
            && (
                ($degree < 0.0 && $targetCoefficients[0] === 0.0)
                || (\fmod(\abs($degree), 2.0) === 0.0 && $targetCoefficients[0] < 0.0)
            )
        ) {
            return [];
        }
        $poweredTargetSource = null;
        if ($degree === 1.0) {
            $poweredTargetSource = '(' . $targetSource . ')';
        } elseif ($degree === -1.0) {
            $poweredTargetSource = '1 / (' . $targetSource . ')';
        } elseif (\abs($degree) > $evaluationOptions->limits->maxExponentMagnitude) {
            if (
                $targetCoefficients === null
                || \count($targetCoefficients) !== 1
                || !\is_finite($targetCoefficients[0])
            ) {
                return null;
            }
            $poweredTarget = \pow($targetCoefficients[0], $degree);
            if (
                !\is_finite($poweredTarget)
                || ($targetCoefficients[0] !== 0.0 && $poweredTarget === 0.0)
            ) {
                return [];
            }
            $poweredTargetSource = \sprintf('%.17g', $poweredTarget);
        }

        $argument = $function->arguments[0]->span();
        $argumentSource = \substr(
            $functionSource,
            $argument->start,
            $argument->end - $argument->start,
        );
        if ($argumentSource === '') {
            return null;
        }
        $transformedTarget = $poweredTargetSource
            ?? '(' . $targetSource . ')^(' . \sprintf('%.0f', $degree) . ')';
        $transformedEquation = '(' . $argumentSource . ')=(' . $transformedTarget . ')';
        if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }

        try {
            $candidates = $this->solve(
                $transformedEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteRootAccumulationException $error) {
            throw $error;
        } catch (InfiniteSolutionSetException) {
            return $this->resolveInfiniteIntegerRootTransform(
                $function->arguments[0],
                $target,
                $degree,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
                $extractor,
            );
        } catch (\DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if ($residual === null) {
                continue;
            }
            if (
                !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Resolve transformed identities while respecting the real-root branch.
     * For even positive roots, an isolated zero target can remain a finite root.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function resolveInfiniteIntegerRootTransform(
        Node $rootArgument,
        Node $target,
        float $degree,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
        PolynomialExtractor $extractor,
    ): ?array {
        $targetForm = $extractor->extractRationalForm($target);
        $argumentForm = $extractor->extractRationalForm($rootArgument);
        if ($targetForm === null || $argumentForm === null) {
            return null;
        }

        $targetNumeratorRoots = $this->solvePolynomialRootsInInterval(
            $targetForm[0],
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        $targetDenominatorRoots = $this->solvePolynomialRootsInInterval(
            $targetForm[1],
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        $argumentDenominatorRoots = $this->solvePolynomialRootsInInterval(
            $argumentForm[1],
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        if (
            $targetNumeratorRoots === null
            || $targetDenominatorRoots === null
            || $argumentDenominatorRoots === null
        ) {
            return null;
        }

        $boundaries = [$lowerBound, $upperBound];
        foreach ([...$targetNumeratorRoots, ...$targetDenominatorRoots, ...$argumentDenominatorRoots] as $root) {
            if ($root->value > $lowerBound && $root->value < $upperBound) {
                $boundaries[] = $root->value;
            }
        }
        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));

        $evenDegree = \fmod(\abs($degree), 2.0) === 0.0;
        for ($index = 0, $last = \count($boundaries) - 1; $index < $last; ++$index) {
            $left = $boundaries[$index];
            $right = $boundaries[$index + 1];
            if ($left >= $right) {
                continue;
            }
            $probe = ($left / 2.0) + ($right / 2.0);
            try {
                $targetValue = $this->evaluateNode(
                    $target,
                    $parameters + [$variable => $probe],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            $branchAllowsInterval = !$evenDegree
                ? ($degree > 0.0 || $targetValue != 0.0)
                : ($degree > 0.0 ? $targetValue >= 0.0 : $targetValue > 0.0);
            if (!$branchAllowsInterval) {
                continue;
            }
            $residual = $residualAt($probe);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $probe,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
        }

        if (!$evenDegree || $degree < 0.0) {
            return [];
        }

        $solutions = [];
        foreach ($targetNumeratorRoots as $root) {
            $residual = $residualAt($root->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $root->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root->value, \abs($residual), $root->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Split |f(x)| = c into the two signed level equations.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAbsoluteValueEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $this->sameExpression($left, $right)
            && $this->containsVariable($left, $variable)
            && $this->hasOnlyConstantFunctionArguments($left, $extractor, $variable)
        ) {
            try {
                $this->evaluateNode($left, [$variable => 0.0] + $parameters, $evaluationOptions);
            } catch (EvaluationException) {
                return [];
            }
            throw new InfiniteSolutionSetException(
                'An identical expression with constant function arguments is defined throughout the interval.',
            );
        }
        $absoluteFunctionSolutions = $this->solveAbsoluteEqualityOfInjectiveFunctions(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($absoluteFunctionSolutions !== null) {
            return $absoluteFunctionSolutions;
        }
        $absoluteSelfPowerSolutions = $this->solveAbsoluteSelfPowerEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($absoluteSelfPowerSolutions !== null) {
            return $absoluteSelfPowerSolutions;
        }
        if (
            $left instanceof FunctionCallNode
            && $left->name === 'abs'
            && \count($left->arguments) === 1
        ) {
            $absolute = $left;
            $constant = $right;
            $source = $leftSource;
            $sourceOffset = 0;
        } elseif (
            $right instanceof FunctionCallNode
            && $right->name === 'abs'
            && \count($right->arguments) === 1
        ) {
            $absolute = $right;
            $constant = $left;
            $source = $rightSource;
            $sourceOffset = 0;
        } else {
            return null;
        }

        if ($this->containsVariable($constant, $variable)) {
            $argument = $absolute->arguments[0];
            $span = $argument->span();
            $argumentSource = \substr($source, $span->start, $span->end - $span->start);
            $targetSource = $left === $absolute ? $rightSource : $leftSource;
            $solutions = [];
            foreach ([1.0, -1.0] as $sign) {
                $signedTarget = $sign < 0.0 ? '-(' . $targetSource . ')' : '(' . $targetSource . ')';
                $branchEquation = '(' . $argumentSource . ')=' . $signedTarget;
                if (\strlen($branchEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $branchSolutions = $this->solve(
                        $branchEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (InfiniteSolutionSetException) {
                    try {
                        $validTargetIntervals = (new InequalitySolver())->solve(
                            '(' . $targetSource . ') >= 0',
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (\DomainException) {
                        return null;
                    }
                    foreach ($validTargetIntervals as $interval) {
                        if ($interval->lowerBound < $interval->upperBound) {
                            throw new InfiniteSolutionSetException(
                                'Equation has infinitely many solutions in the requested interval.',
                            );
                        }
                        $residual = $residualAt($interval->lowerBound);
                        if (
                            $residual !== null
                            && $this->isResidualAcceptableAt(
                                $interval->lowerBound,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            $this->addSolution(
                                $solutions,
                                new EquationSolution($interval->lowerBound, \abs($residual), 0),
                                $solverOptions,
                            );
                        }
                    }
                    continue;
                } catch (ParseException) {
                    return null;
                } catch (\DomainException) {
                    return null;
                }
                foreach ($branchSolutions as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $target = $this->extractPolynomial($extractor, $constant, $constant->span()->start);
        if ($target === null || \count($target) !== 1) {
            return null;
        }
        if ($target[0] < 0.0) {
            return [];
        }
        $argument = $absolute->arguments[0];
        $levels = $target[0] === 0.0 ? [0.0] : [$target[0], -$target[0]];
        $solutions = [];
        foreach ($levels as $level) {
            $terms = [];
            $offset = 0.0;
            $flattened = $this->flattenAdditiveExpression(
                $argument,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                1.0,
                $terms,
                $offset,
            );
            if (!$flattened || $terms === []) {
                return null;
            }
            $branchEquation = '(' . \implode('+', $terms) . ')='
                . \sprintf('%.17g', $level - $offset);
            if (\strlen($branchEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            [$branchLeftSource, $branchRightSource, $branchRightOffset] = $this->splitEquation($branchEquation);
            $branchLeft = $this->parseSide($branchLeftSource, 0, $evaluationOptions);
            $branchRight = $this->parseSide($branchRightSource, $branchRightOffset, $evaluationOptions);
            $branchResidualAt = fn (float $value): ?float => $this->residualAt(
                $branchLeft,
                $branchRight,
                $branchRightOffset,
                $variable,
                $value,
                $parameters,
                $evaluationOptions,
            );
            $branchSolutions = $this->solve(
                $branchEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($branchSolutions as $candidate) {
                $residual = $residualAt($candidate->value);
                if ($residual === null) {
                    continue;
                }
                $residualAccepted = $this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    ) || $this->isCandidateAtFloatingPointRootResolution(
                        $candidate->value,
                        $candidate->residual,
                        $branchResidualAt,
                    );
                if (!$residualAccepted) {
                    continue;
                }
                $this->addDistinctRepresentableSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function hasOnlyConstantFunctionArguments(
        Node $node,
        PolynomialExtractor $extractor,
        string $variable,
    ): bool {
        if (!$this->containsVariable($node, $variable)) {
            return true;
        }
        $coefficients = $extractor->extract($node);
        if ($coefficients !== null && \count($coefficients) === 1) {
            return true;
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if (!$this->hasOnlyConstantFunctionArguments($argument, $extractor, $variable)) {
                    return false;
                }
            }

            return true;
        }
        if ($node instanceof GroupingNode) {
            return $this->hasOnlyConstantFunctionArguments($node->expression, $extractor, $variable);
        }
        if ($node instanceof UnaryOperationNode || $node instanceof FactorialNode) {
            return $this->hasOnlyConstantFunctionArguments($node->operand, $extractor, $variable);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->hasOnlyConstantFunctionArguments($node->left, $extractor, $variable)
                && $this->hasOnlyConstantFunctionArguments($node->right, $extractor, $variable);
        }

        return false;
    }

    /**
     * Solve equalities of absolute values of the same injective function by its two sign branches.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAbsoluteEqualityOfInjectiveFunctions(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || $left->name !== 'abs'
            || $right->name !== 'abs'
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn('abs')
        ) {
            return null;
        }
        $leftFunction = $this->unwrapGrouping($left->arguments[0]);
        $rightFunction = $this->unwrapGrouping($right->arguments[0]);
        if (
            !$leftFunction instanceof FunctionCallNode
            || !$rightFunction instanceof FunctionCallNode
            || \count($leftFunction->arguments) !== 1
            || \count($rightFunction->arguments) !== 1
        ) {
            return null;
        }

        $canonicalName = static fn (string $name): string => match ($name) {
            'arcsinh' => 'asinh',
            'arcsin' => 'asin',
            'arctan' => 'atan',
            'arctanh' => 'atanh',
            default => $name,
        };
        $function = $canonicalName($leftFunction->name);
        $injectiveFunctions = [
            'exp', 'expm1', 'ln', 'log10', 'log2', 'log1p', 'sqrt', 'cbrt',
            'sinh', 'cosh', 'sech', 'csch', 'coth', 'tanh',
            'asinh', 'acosh', 'atanh', 'asin', 'acos', 'atan', 'asec', 'acsc', 'acot',
            'asech', 'acsch', 'acoth', 'erf', 'erfc', 'erfcx', 'erfi', 'erfinv', 'erfcinv',
        ];
        if (
            $function !== $canonicalName($rightFunction->name)
            || !\in_array($function, $injectiveFunctions, true)
            || !$evaluationOptions->functions->isBuiltIn($leftFunction->name)
            || !$evaluationOptions->functions->isBuiltIn($rightFunction->name)
        ) {
            return null;
        }

        $leftArgument = $leftFunction->arguments[0];
        $rightArgument = $rightFunction->arguments[0];
        $leftArgumentPolynomial = $extractor->extract($leftArgument);
        $rightArgumentPolynomial = $extractor->extract($rightArgument);
        if (
            $leftArgumentPolynomial !== null
            && \count($leftArgumentPolynomial) === 1
            && $rightArgumentPolynomial === $leftArgumentPolynomial
            && (
                $this->containsVariable($leftArgument, $variable)
                || $this->containsVariable($rightArgument, $variable)
            )
        ) {
            try {
                $leftValue = $this->evaluateNode($leftFunction, [$variable => 0.0] + $parameters, $evaluationOptions);
                $rightValue = $this->evaluateNode($rightFunction, [$variable => 0.0] + $parameters, $evaluationOptions);
            } catch (EvaluationException) {
                return [];
            }
            if ($leftValue == $rightValue) {
                throw new InfiniteSolutionSetException(
                    'The absolute values of identical constant function levels agree throughout the interval.',
                );
            }
        }
        $leftSpan = $leftArgument->span();
        $rightSpan = $rightArgument->span();
        $leftArgumentSource = \substr($leftSource, $leftSpan->start, $leftSpan->end - $leftSpan->start);
        $rightArgumentSource = \substr($rightSource, $rightSpan->start, $rightSpan->end - $rightSpan->start);
        if ($leftArgumentSource === '' || $rightArgumentSource === '') {
            return null;
        }

        $leftCall = $function . '(' . $leftArgumentSource . ')';
        $rightCall = $function . '(' . $rightArgumentSource . ')';
        $branchEquations = [$leftCall . '=' . $rightCall];
        if (\in_array(
            $function,
            [
                'sinh', 'tanh', 'asinh', 'atanh', 'asin', 'atan', 'cbrt', 'csch', 'coth',
                'acsch', 'acoth', 'erf', 'erfi', 'erfinv',
            ],
            true,
        )) {
            $branchEquations[] = $leftCall . '=-(' . $rightCall . ')';
        } elseif ($function === 'erfcinv') {
            $branchEquations[] = '(' . $leftArgumentSource . ')+(' . $rightArgumentSource . ')=2';
        }

        $solutions = [];
        foreach ($branchEquations as $branchEquation) {
            if (\strlen($branchEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            foreach (
                $this->solve(
                    $branchEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                ) as $candidate
            ) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce |f(x)|^p = |f(x)| to the real levels of its shared nonnegative base.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAbsoluteSelfPowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && $right instanceof FunctionCallNode
            && $right->name === 'abs'
            && \count($right->arguments) === 1
            && $left->left instanceof FunctionCallNode
            && $left->left->name === 'abs'
            && \count($left->left->arguments) === 1
            && $this->sameExpression($left->left, $right)
            && $evaluationOptions->functions->isBuiltIn('abs')
        ) {
            $power = $left;
            $absolute = $left->left;
            $powerSource = $leftSource;
        } elseif (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && $left instanceof FunctionCallNode
            && $left->name === 'abs'
            && \count($left->arguments) === 1
            && $right->left instanceof FunctionCallNode
            && $right->left->name === 'abs'
            && \count($right->left->arguments) === 1
            && $this->sameExpression($right->left, $left)
            && $evaluationOptions->functions->isBuiltIn('abs')
        ) {
            $power = $right;
            $absolute = $right->left;
            $powerSource = $rightSource;
        } else {
            return null;
        }

        if (!$this->containsVariable($absolute->arguments[0], $variable)) {
            return null;
        }
        $exponent = $extractor->extract($power->right);
        if ($exponent === null || \count($exponent) !== 1 || !\is_finite($exponent[0]) || $exponent[0] === 1.0) {
            return null;
        }

        $argument = $absolute->arguments[0];
        $span = $argument->span();
        $argumentSource = \substr($powerSource, $span->start, $span->end - $span->start);
        if ($argumentSource === '') {
            return null;
        }
        $levels = $exponent[0] > 0.0 ? [0.0, 1.0, -1.0] : [1.0, -1.0];
        $solutions = [];
        foreach ($levels as $level) {
            $levelEquation = '(' . $argumentSource . ')=' . \sprintf('%.17g', $level);
            if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            foreach (
                $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                ) as $candidate
            ) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Invert a constant real base raised to a polynomial exponent.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveConstantBasePowerEquation(
        string $equation,
        string $leftExpression,
        string $rightExpression,
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && !$this->containsVariable($right, $variable)
        ) {
            $power = $left;
            $targetNode = $right;
            $powerSource = $leftExpression;
            $powerSourceOffset = 0;
        } elseif (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && !$this->containsVariable($left, $variable)
        ) {
            $power = $right;
            $targetNode = $left;
            $powerSource = $rightExpression;
            $powerSourceOffset = 0;
        } else {
            return null;
        }

        $base = $this->extractPolynomial($extractor, $power->left, $power->left->span()->start);
        $target = $this->extractPolynomial($extractor, $targetNode, $targetNode->span()->start);
        if ($target === null && !$this->containsVariable($targetNode, $variable)) {
            try {
                $targetValue = (float) $this->evaluateNode(
                    $targetNode,
                    $parameters,
                    $evaluationOptions,
                );
                if (\is_finite($targetValue)) {
                    $target = [$targetValue];
                }
            } catch (EvaluationException) {
                // Leave unsupported constant expressions to the general solver.
            }
        }
        if (
            $target === null
            || \count($target) !== 1
        ) {
            return null;
        }

        $baseSpan = $power->left->span();
        $baseSource = \substr(
            $powerSource,
            $baseSpan->start - $powerSourceOffset,
            $baseSpan->end - $baseSpan->start,
        );
        if ($base === null) {
            if ($target[0] === 0.0 && $this->containsVariable($power->left, $variable)) {
                return $this->solveGeneralBaseZeroPowerEquation(
                    $baseSource,
                    $power->right,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
            }

            return null;
        }
        if ($base === []) {
            return null;
        }

        $baseValue = $base[0];
        $targetValue = $target[0];
        $variableNegativeBase = \count($base) > 1;
        if (!\is_finite($baseValue) || !\is_finite($targetValue)) {
            return null;
        }
        if ($variableNegativeBase && $targetValue === 0.0) {
            return $this->solvePolynomialBaseZeroPowerEquation(
                $power->right,
                $base,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
        }
        $exponent = $this->extractPolynomial($extractor, $power->right, $power->right->span()->start);
        if (
            $exponent === null
            || \count($exponent) < 2
            || !$this->containsVariable($power->right, $variable)
        ) {
            if ($variableNegativeBase && $targetValue !== 0.0 && $this->containsVariable($power->right, $variable)) {
                $exponentSpan = $power->right->span();
                $exponentSource = \substr(
                    $powerSource,
                    $exponentSpan->start - $powerSourceOffset,
                    $exponentSpan->end - $exponentSpan->start,
                );

                return $this->solveNonPolynomialNegativeBasePowerEquation(
                    $power->right,
                    $exponentSource,
                    $base,
                    $targetValue,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
            }
            if ($this->containsVariable($power->right, $variable)) {
                $exponentSpan = $power->right->span();
                $exponentSource = \substr(
                    $powerSource,
                    $exponentSpan->start - $powerSourceOffset,
                    $exponentSpan->end - $exponentSpan->start,
                );
                if (!$variableNegativeBase && $baseValue === 0.0) {
                    if ($targetValue === 1.0) {
                        return $this->solveGeneralZeroExponentPowerEquation(
                            $exponentSource,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                        );
                    }
                    if ($targetValue === 0.0) {
                        return $this->solveGeneralZeroBaseZeroTargetPowerEquation(
                            $exponentSource,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                        );
                    }
                }
                if (!$variableNegativeBase && $baseValue > 0.0) {
                    if ($targetValue <= 0.0) {
                        return [];
                    }

                    return $this->solveGeneralConstantBasePowerEquation(
                        $exponentSource,
                        \log($targetValue) / \log($baseValue),
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                        $residualAt,
                        $candidateScaleAt,
                    );
                }
                if (!$variableNegativeBase && $baseValue < 0.0) {
                    return $this->solveGeneralNegativeConstantBasePowerEquation(
                        $exponentSource,
                        $baseValue,
                        $targetValue,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                        $residualAt,
                        $candidateScaleAt,
                    );
                }
            }

            return null;
        }
        $mixedSignPositiveTarget = false;
        if ($variableNegativeBase) {
            $baseRange = $this->polynomialRange($base, $lowerBound, $upperBound, $options);
            if ($baseRange === null) {
                return null;
            }
            if ($baseRange[1] >= 0.0 && $targetValue >= 0.0) {
                if ($targetValue > 0.0 && $baseRange[0] < 0.0) {
                    $mixedSignPositiveTarget = true;
                } else {
                    return null;
                }
            }
            if ($baseRange[0] >= 0.0 && $targetValue < 0.0) {
                return [];
            }
        }
        if (!$variableNegativeBase && $baseValue === 1.0) {
            if ($targetValue === 1.0) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }
        $levels = [];
        $zeroBaseUnitTarget = !$variableNegativeBase
            && $baseValue === 0.0
            && $targetValue === 1.0;
        if ($variableNegativeBase || $baseValue < 0.0) {
            $exponentRange = $this->polynomialRange(
                $exponent,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($exponentRange === null) {
                return null;
            }
            $maximumExactInteger = 9_007_199_254_740_991.0;
            if (
                $exponentRange[0] < -$maximumExactInteger
                || $exponentRange[1] > $maximumExactInteger
            ) {
                return null;
            }
            $integerTolerance = \min(
                0.25,
                4.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($exponentRange[0]), \abs($exponentRange[1])),
            );
            $firstInteger = (int) \ceil($exponentRange[0] - $integerTolerance);
            $lastInteger = (int) \floor($exponentRange[1] + $integerTolerance);
            if ($firstInteger > $lastInteger) {
                return [];
            }
            if ($lastInteger - $firstInteger + 1 > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                return null;
            }
            for ($integerLevel = $firstInteger; $integerLevel <= $lastInteger; ++$integerLevel) {
                if ($variableNegativeBase) {
                    $levels[] = (float) $integerLevel;
                    continue;
                }
                $value = \pow($baseValue, (float) $integerLevel);
                if (
                    \is_finite($value)
                    && \abs($value - $targetValue)
                        <= $options->residualTolerance
                            * \max(1.0, \abs($value), \abs($targetValue))
                ) {
                    $levels[] = (float) $integerLevel;
                }
            }
        } elseif ($baseValue === 0.0) {
            if ($targetValue === 0.0) {
                $exponentRange = $this->polynomialRange(
                    $exponent,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($exponentRange === null) {
                    return null;
                }
                $maximumExponent = (float) $evaluationOptions->limits->maxExponentMagnitude;
                if (
                    $exponentRange[1] > 0.0
                    && $exponentRange[0] <= $maximumExponent
                ) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }

                return [];
            }
            if ($targetValue !== 1.0) {
                return [];
            }

            $levels[] = 0.0;
        } elseif ($targetValue <= 0.0) {
            return [];
        } else {
            $level = \log($targetValue) / \log($baseValue);
            if (!\is_finite($level)) {
                return null;
            }
            $levels[] = $level;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ($levels as $level) {
            $levelCoefficients = $exponent;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $polynomialResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
            $polynomialResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
            $candidates = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $options,
                $polynomialResidualScaleAt,
            );
            if ($candidates === null) {
                return null;
            }
            $candidates = $polynomialSolver->recoverRepeatedRoots(
                $levelCoefficients,
                $candidates,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $polynomialResidualScaleAt,
                $options,
            );

            foreach ($candidates as $candidate) {
                if ($zeroBaseUnitTarget) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, 0.0, $candidate->iterations),
                        $options,
                    );
                    continue;
                }
                if ($variableNegativeBase || $baseValue < 0.0) {
                    try {
                        $actualExponent = $this->evaluateNode(
                            $power->right,
                            $parameters + [$variable => $candidate->value],
                            $evaluationOptions,
                        );
                    } catch (EvaluationException) {
                        continue;
                    }
                    $actualExponentFloat = (float) $actualExponent;
                    if (
                        !\is_finite($actualExponentFloat)
                        || \round($actualExponentFloat) !== $level
                        || \abs($actualExponentFloat - $level)
                            > \min(
                                1.0E-9,
                                4.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($level)),
                            )
                    ) {
                        continue;
                    }
                }

                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }
        if ($mixedSignPositiveTarget) {
            $baseResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($base, $value);
            $baseResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($base, $value);
            $baseRoots = $polynomialSolver->solve(
                $base,
                $lowerBound,
                $upperBound,
                $baseResidualAt,
                $options,
                $baseResidualScaleAt,
            );
            if ($baseRoots === null) {
                return null;
            }
            $baseRoots = $polynomialSolver->recoverRepeatedRoots(
                $base,
                $baseRoots,
                $lowerBound,
                $upperBound,
                $baseResidualAt,
                $baseResidualScaleAt,
                $options,
            );

            $boundaries = [$lowerBound];
            foreach ($baseRoots as $baseRoot) {
                $boundaries[] = $baseRoot->value;
                $residual = $residualAt($baseRoot->value);
                if (
                    $residual !== null
                    && $this->isResidualAcceptableAt(
                        $baseRoot->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $baseRoot->value,
                            \abs($residual),
                            $baseRoot->iterations,
                        ),
                        $options,
                    );
                }
            }
            $boundaries[] = $upperBound;
            \sort($boundaries, SORT_NUMERIC);
            for ($index = 0; $index < \count($boundaries) - 1; ++$index) {
                $segmentLower = $boundaries[$index];
                $segmentUpper = $boundaries[$index + 1];
                if ($segmentLower >= $segmentUpper) {
                    continue;
                }
                $midpoint = $segmentLower + (($segmentUpper - $segmentLower) / 2.0);
                if ($polynomialSolver->evaluatePolynomial($base, $midpoint) <= 0.0) {
                    continue;
                }
                foreach (
                    $this->solve(
                        $equation,
                        $variable,
                        $segmentLower,
                        $segmentUpper,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    ) as $candidate
                ) {
                    $this->addSolution($solutions, $candidate, $options);
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Isolate zero-base points where a polynomial exponent makes the power zero.
     *
     * @param list<float> $base
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialBaseZeroPowerEquation(
        Node $exponentNode,
        array $base,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        $polynomialSolver = new PolynomialSolver();
        $baseResidualAt = fn (float $value): ?float =>
            $polynomialSolver->evaluatePolynomial($base, $value);
        $baseResidualScaleAt = fn (float $value): ?float =>
            $polynomialSolver->evaluatePolynomialMagnitude($base, $value);
        $candidates = $polynomialSolver->solve(
            $base,
            $lowerBound,
            $upperBound,
            $baseResidualAt,
            $options,
            $baseResidualScaleAt,
        );
        if ($candidates === null) {
            return null;
        }
        $candidates = $polynomialSolver->recoverRepeatedRoots(
            $base,
            $candidates,
            $lowerBound,
            $upperBound,
            $baseResidualAt,
            $baseResidualScaleAt,
            $options,
        );

        $solutions = [];
        foreach ($candidates as $candidate) {
            try {
                $exponent = $this->evaluateNode(
                    $exponentNode,
                    $parameters + [$variable => $candidate->value],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            if (
                $exponent <= 0.0
                || \abs((float) $exponent) > $evaluationOptions->limits->maxExponentMagnitude
            ) {
                continue;
            }

            $baseResidual = $baseResidualAt($candidate->value);
            if ($baseResidual === null) {
                continue;
            }
            $residual = \pow(\abs($baseResidual), (float) $exponent);
            if (!\is_finite($residual)) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Isolate zeroes of a non-polynomial base before checking the exponent.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveGeneralBaseZeroPowerEquation(
        string $baseExpression,
        Node $exponentNode,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        if ($baseExpression === '' || \strlen($baseExpression) + 2 > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }

        try {
            $baseRoots = $this->solve(
                $baseExpression . '=0',
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
        } catch (\DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($baseRoots as $baseRoot) {
            try {
                $exponent = $this->evaluateNode(
                    $exponentNode,
                    $parameters + [$variable => $baseRoot->value],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            if (
                $exponent <= 0.0
                || \abs((float) $exponent) > $evaluationOptions->limits->maxExponentMagnitude
            ) {
                continue;
            }

            $residual = \pow(\abs($baseRoot->residual), (float) $exponent);
            if (!\is_finite($residual)) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($baseRoot->value, $residual, $baseRoot->iterations),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce a non-polynomial exponent for a positive constant-base power.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveGeneralConstantBasePowerEquation(
        string $exponentExpression,
        float $level,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            !\is_finite($level)
            || $exponentExpression === ''
            || \strlen($exponentExpression) + 24 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        $roots = $this->solveGeneralExponentLevelEquation(
            $exponentExpression,
            $level,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );
        if ($roots === null) {
            return null;
        }
        $solutions = [];
        foreach ($roots as $root) {
            $residual = $residualAt($root->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $root->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root->value, \abs($residual), $root->iterations),
                $options,
            );
        }

        return $solutions;
    }

    /**
     * Classify positive exponent regions for a zero constant base.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveGeneralZeroBaseZeroTargetPowerEquation(
        string $exponentExpression,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        if (
            $exponentExpression === ''
            || \strlen($exponentExpression) + 32 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        try {
            $exponentNode = $this->unwrapGrouping($this->parseSide($exponentExpression, 0, $evaluationOptions));
        } catch (MathException) {
            return null;
        }
        if (
            $exponentNode instanceof BinaryOperationNode
            && $exponentNode->operator === BinaryOperator::Subtract
            && $exponentNode->right instanceof FunctionCallNode
            && $exponentNode->right->name === 'sign'
            && \count($exponentNode->right->arguments) === 1
        ) {
            $extractor = new PolynomialExtractor($variable, $parameters, $evaluationOptions, $options->maxPolynomialDegree);
            $offset = $extractor->extract($exponentNode->left);
            if ($offset !== null && \count($offset) === 1 && $offset[0] === 1.0) {
                $argument = $exponentNode->right->arguments[0];
                $argumentSpan = $argument->span();
                $argumentSource = \substr(
                    $exponentExpression,
                    $argumentSpan->start,
                    $argumentSpan->end - $argumentSpan->start,
                );
                if ($argumentSource !== '') {
                    $nonpositive = (new InequalitySolver())->solve(
                        '(' . $argumentSource . ')<=0',
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                    $maximumExponent = (float) $evaluationOptions->limits->maxExponentMagnitude;
                    $solutions = [];
                    foreach ($nonpositive as $interval) {
                        if ($interval->lowerBound < $interval->upperBound) {
                            if ($maximumExponent >= 2.0) {
                                throw new InfiniteSolutionSetException(
                                    'Equation has infinitely many solutions in the requested interval.',
                                );
                            }
                            return null;
                        }
                        if (!$interval->includesLowerBound || !$interval->includesUpperBound) {
                            continue;
                        }
                        try {
                            $exponent = (float) $this->evaluateNode(
                                $exponentNode,
                                $parameters + [$variable => $interval->lowerBound],
                                $evaluationOptions,
                            );
                        } catch (EvaluationException) {
                            continue;
                        }
                        if ($exponent > 0.0 && $exponent <= $maximumExponent) {
                            $solutions[] = new EquationSolution($interval->lowerBound, 0.0, 0);
                        }
                    }

                    return $solutions;
                }
            }
        }

        $inequalitySolver = new InequalitySolver();
        $positive = $inequalitySolver->solve(
            $exponentExpression . '>0',
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );
        $withinLimit = $inequalitySolver->solve(
            $exponentExpression . '<=' . \sprintf(
                '%.17g',
                (float) $evaluationOptions->limits->maxExponentMagnitude,
            ),
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );

        $solutions = [];
        foreach ($positive as $positiveInterval) {
            foreach ($withinLimit as $limitInterval) {
                $lower = \max($positiveInterval->lowerBound, $limitInterval->lowerBound);
                $upper = \min($positiveInterval->upperBound, $limitInterval->upperBound);
                $includesLower = ($lower !== $positiveInterval->lowerBound
                        || $positiveInterval->includesLowerBound)
                    && ($lower !== $limitInterval->lowerBound || $limitInterval->includesLowerBound);
                $includesUpper = ($upper !== $positiveInterval->upperBound
                        || $positiveInterval->includesUpperBound)
                    && ($upper !== $limitInterval->upperBound || $limitInterval->includesUpperBound);
                if ($lower < $upper) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                if ($lower !== $upper || !$includesLower || !$includesUpper) {
                    continue;
                }

                $solutions[] = new EquationSolution($lower, 0.0, 0);
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve negative constant-base powers with a non-polynomial exponent.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveGeneralNegativeConstantBasePowerEquation(
        string $exponentExpression,
        float $base,
        float $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            $exponentExpression === ''
            || \strlen($exponentExpression) + 32 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        $maximumExponent = (float) $evaluationOptions->limits->maxExponentMagnitude;
        $levels = [];
        if (\abs($base) === 1.0) {
            if ($target !== 1.0 && $target !== -1.0) {
                return [];
            }
            if ($maximumExponent > (self::MAX_ROOT_DEGREE_SCAN_WORK - 1) / 2.0) {
                $range = $this->findGeneralIntegerExponentLevelRange(
                    $exponentExpression,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $maximumExponent,
                );
                if ($range === null) {
                    return null;
                }
                if ($range[0] === null || $range[1] === null || $range[0] > $range[1]) {
                    return [];
                }
                [$first, $last] = $range;
            } else {
                $first = (int) \ceil(-$maximumExponent);
                $last = (int) \floor($maximumExponent);
            }
            if ($last - $first + 1 > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                return null;
            }
            for ($level = $first; $level <= $last; ++$level) {
                if (($level % 2 === 0) === ($target > 0.0)) {
                    $levels[] = (float) $level;
                }
            }
        } else {
            if ($target === 0.0) {
                return [];
            }
            $unroundedLevel = \log(\abs($target)) / \log(\abs($base));
            if (!\is_finite($unroundedLevel)) {
                return null;
            }
            $level = \round($unroundedLevel);
            if (\abs($level) > $maximumExponent) {
                return [];
            }
            $value = \pow($base, $level);
            if (
                !\is_finite($value)
                || \abs($value - $target)
                    > $options->residualTolerance * \max(1.0, \abs($value), \abs($target))
            ) {
                return [];
            }
            $levels[] = $level;
        }

        $solutions = [];
        foreach ($levels as $level) {
            $levelSolutions = $this->solveGeneralExponentLevelEquation(
                $exponentExpression,
                $level,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            if ($levelSolutions === null) {
                return null;
            }
            foreach ($levelSolutions as $solution) {
                $residual = $residualAt($solution->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $solution->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $solution->value,
                        \abs($residual),
                        $solution->iterations,
                    ),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Find the lowest and highest integer levels attained by a general exponent.
     *
     * @param array<string, int|float> $parameters
     * @return array{?int, ?int}|null Null means the range could not be established.
     */
    private function findGeneralIntegerExponentLevelRange(
        string $exponentExpression,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        float $maximumExponent,
    ): ?array {
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if ($maximumExponent > $maximumExactInteger) {
            return null;
        }

        $firstAllowed = (int) \ceil(-$maximumExponent);
        $lastAllowed = (int) \floor($maximumExponent);
        $inequalitySolver = new InequalitySolver();
        $hasValueAtMost = function (int $level) use (
            $exponentExpression,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
            $inequalitySolver,
        ): bool {
            return $inequalitySolver->solve(
                $exponentExpression . '<=' . $level,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            ) !== [];
        };
        $hasValueAtLeast = function (int $level) use (
            $exponentExpression,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
            $inequalitySolver,
        ): bool {
            return $inequalitySolver->solve(
                $exponentExpression . '>=' . $level,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            ) !== [];
        };

        if (
            $firstAllowed > $lastAllowed
            || !$hasValueAtMost($lastAllowed)
            || !$hasValueAtLeast($firstAllowed)
        ) {
            return [null, null];
        }

        $low = $firstAllowed;
        $high = $lastAllowed;
        while ($low < $high) {
            $middle = $low + \intdiv($high - $low, 2);
            if ($hasValueAtMost($middle)) {
                $high = $middle;
            } else {
                $low = $middle + 1;
            }
        }
        $first = $low;

        $low = $firstAllowed;
        $high = $lastAllowed;
        while ($low < $high) {
            $middle = $low + \intdiv($high - $low + 1, 2);
            if ($hasValueAtLeast($middle)) {
                $low = $middle;
            } else {
                $high = $middle - 1;
            }
        }

        return [$first, $low];
    }

    /**
     * Solve a non-polynomial exponent over a polynomial negative base.
     *
     * @param array<int, int|float> $base
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNonPolynomialNegativeBasePowerEquation(
        Node $exponentNode,
        string $exponentSource,
        array $base,
        float $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $baseRange = $this->polynomialRange($base, $lowerBound, $upperBound, $options);
        if ($baseRange === null || $baseRange[1] >= 0.0 || $target === 0.0) {
            return null;
        }

        $minimumMagnitude = -$baseRange[1];
        $maximumMagnitude = -$baseRange[0];
        if (
            $minimumMagnitude <= 0.0
            || !\is_finite($maximumMagnitude)
        ) {
            return null;
        }

        $magnitudeContainsOne = $minimumMagnitude <= 1.0 && $maximumMagnitude >= 1.0;
        $firstInteger = null;
        $lastInteger = null;
        if ($magnitudeContainsOne) {
            $integerRange = $this->findGeneralIntegerExponentLevelRange(
                $exponentSource,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                (float) $evaluationOptions->limits->maxExponentMagnitude,
            );
            if ($integerRange === null) {
                return null;
            }
            [$firstInteger, $lastInteger] = $integerRange;
            if ($firstInteger === null || $lastInteger === null || $firstInteger > $lastInteger) {
                return [];
            }
        }

        if ($target === 1.0) {
            if ($magnitudeContainsOne) {
                return null;
            }
            try {
                $roundingCombination = $this->roundingSelfCombination(
                    $exponentNode,
                    $exponentSource,
                    $exponentNode->span()->start,
                    new PolynomialExtractor(
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $options->maxPolynomialDegree,
                    ),
                );
                $zeroLevelExponent = $this->unwrapGrouping($exponentNode);
                if (
                    $zeroLevelExponent instanceof FunctionCallNode
                    && $zeroLevelExponent->name === 'atan2'
                    && \count($zeroLevelExponent->arguments) === 2
                ) {
                    $horizontal = $this->constantNodeValue(
                        $zeroLevelExponent->arguments[1],
                        $parameters,
                        $evaluationOptions,
                    );
                    if ($horizontal !== null && $horizontal > 0.0) {
                        $zeroExponentSolutions = $this->solveGeneralExponentLevelEquation(
                            $exponentSource,
                            0.0,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                        );
                    } else {
                        $zeroExponentSolutions = $this->solveGeneralZeroExponentPowerEquation(
                            $exponentSource,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                        );
                    }
                } elseif ($roundingCombination !== null) {
                    $zeroExponentSolutions = $this->solveRoundingExponentLevel(
                        $exponentNode,
                        $roundingCombination,
                        0,
                        new PolynomialExtractor(
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $options->maxPolynomialDegree,
                        ),
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                } else {
                    $zeroExponentSolutions = $this->solveGeneralZeroExponentPowerEquation(
                        $exponentSource,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                }
            } catch (InfiniteSolutionSetException) {
                return null;
            } catch (RootSearchLimitException) {
                return null;
            }
            if ($zeroExponentSolutions === null) {
                return null;
            }

            return $this->filterNegativeBasePowerCandidates(
                $zeroExponentSolutions,
                $exponentNode,
                0.0,
                $variable,
                $base,
                $target,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        $logTarget = \log(\abs($target));
        if (!$magnitudeContainsOne) {
            $ratioA = $logTarget / \log($minimumMagnitude);
            $ratioB = $logTarget / \log($maximumMagnitude);
            if (!\is_finite($ratioA) || !\is_finite($ratioB)) {
                return null;
            }
            $baseFirstInteger = (int) \ceil(\min($ratioA, $ratioB) - 8.0 * \PHP_FLOAT_EPSILON);
            $baseLastInteger = (int) \floor(\max($ratioA, $ratioB) + 8.0 * \PHP_FLOAT_EPSILON);
            $firstInteger = $baseFirstInteger;
            $lastInteger = $baseLastInteger;
        }
        if ($lastInteger < $firstInteger
            || $lastInteger - $firstInteger + 1 > self::MAX_ROOT_DEGREE_SCAN_WORK) {
            return $lastInteger < $firstInteger ? [] : null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        for ($level = $firstInteger; $level <= $lastInteger; ++$level) {
            if ($level === 0) {
                continue;
            }
            $magnitude = \pow(\abs($target), 1.0 / $level);
            if (!\is_finite($magnitude) || $magnitude <= 0.0) {
                return null;
            }
            foreach ([-$magnitude, $magnitude] as $baseLevel) {
                $levelCoefficients = $base;
                $levelCoefficients[0] -= $baseLevel;
                $baseResidualAt = fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
                $baseScaleAt = fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
                $candidates = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    $baseResidualAt,
                    $options,
                    $baseScaleAt,
                );
                if ($candidates === null) {
                    return null;
                }
                foreach ($candidates as $candidate) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, 0.0, $candidate->iterations),
                        $options,
                    );
                }
            }
            if ($level === \PHP_INT_MAX) {
                break;
            }
        }

        $solutions = $this->filterNegativeBasePowerCandidates(
            $solutions,
            $exponentNode,
            null,
            $variable,
            $base,
            $target,
            $parameters,
            $evaluationOptions,
            $options,
            $residualAt,
            $candidateScaleAt,
        );

        return $solutions;
    }

    /**
     * @param list<EquationSolution> $candidates
     * @param array<int, int|float> $base
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>
     */
    private function filterNegativeBasePowerCandidates(
        array $candidates,
        Node $exponentNode,
        ?float $requiredLevel,
        string $variable,
        array $base,
        float $target,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): array {
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ($candidates as $candidate) {
            $baseValue = $polynomialSolver->evaluatePolynomial($base, $candidate->value);
            if ($baseValue === null || $baseValue >= 0.0) {
                continue;
            }
            try {
                $exponent = (float) $this->evaluateNode(
                    $exponentNode,
                    $parameters + [$variable => $candidate->value],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            $integerExponent = \round($exponent);
            if (
                !\is_finite($exponent)
                || \abs($exponent - $integerExponent)
                    > \min(1.0E-9, 4.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($exponent)))
                || \abs($integerExponent) > 9_007_199_254_740_991.0
            ) {
                continue;
            }
            if ($requiredLevel !== null && $integerExponent !== $requiredLevel) {
                continue;
            }
            $powerMagnitude = \pow(-$baseValue, $integerExponent);
            $signedPower = ((int) \abs($integerExponent)) % 2 === 1 ? -$powerMagnitude : $powerMagnitude;
            if (!\is_finite($signedPower) || \abs($signedPower - $target) >
                $options->residualTolerance * \max(1.0, \abs($signedPower), \abs($target))) {
                continue;
            }
            $residual = $residualAt($candidate->value);
            if ($residual === null || !$this->isResidualAcceptableAt(
                $candidate->value,
                $residual,
                $candidateScaleAt,
                $options,
            )) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }

        return $solutions;
    }

    /**
     * Solve a non-polynomial exponent's zero levels for a zero base and unit target.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveGeneralZeroExponentPowerEquation(
        string $exponentExpression,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        return $this->solveGeneralExponentLevelEquation(
            $exponentExpression,
            0.0,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );
    }

    /**
     * Isolate a general exponent level by intersecting its two inequality sides.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveGeneralExponentLevelEquation(
        string $exponentExpression,
        float $level,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        if (
            !\is_finite($level)
            || $exponentExpression === ''
            || \strlen($exponentExpression) + 32 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        $parsedExponent = null;
        try {
            $parsedExponent = $this->parseSide($exponentExpression, 0, $evaluationOptions);
        } catch (ParseException | LexicalException) {
            return null;
        }
        $parsedExponent = $this->unwrapGrouping($parsedExponent);
        if (
            $level === 0.0
            && $parsedExponent instanceof FunctionCallNode
            && $parsedExponent->name === 'atan2'
            && \count($parsedExponent->arguments) === 2
            && !$this->containsVariable($parsedExponent->arguments[1], $variable)
        ) {
            $horizontal = $this->constantNodeValue(
                $parsedExponent->arguments[1],
                $parameters,
                $evaluationOptions,
            );
            if ($horizontal !== null && $horizontal > 0.0) {
                $exactExtractor = new ExactRationalPolynomialExtractor(
                    $variable,
                    $parameters,
                    $options->maxPolynomialDegree,
                    $evaluationOptions,
                );
                $exactCoefficients = $exactExtractor->integerCoefficients(
                    $exactExtractor->polynomial($parsedExponent->arguments[0]),
                );
                $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
                $upper = RationalLiteral::fromFloatAsStrings($upperBound);
                if ($exactCoefficients === null || $lower === null || $upper === null) {
                    return null;
                }
                if ($exactCoefficients === ['0']) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                $counter = new ExactPolynomialRootCounter();
                $rootIntervals = $counter->isolateOpenInterval(
                    $exactCoefficients,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                    256,
                    ['1', '1000000000000'],
                );
                if ($rootIntervals === null) {
                    return null;
                }
                $roots = [];
                foreach ($rootIntervals as [$lowNumerator, $lowDenominator, $highNumerator, $highDenominator]) {
                    $low = $this->decimalRationalToFloat($lowNumerator, $lowDenominator);
                    $high = $this->decimalRationalToFloat($highNumerator, $highDenominator);
                    $roots[] = new EquationSolution(
                        $low === $high ? $low : ($low / 2.0) + ($high / 2.0),
                        0.0,
                        0,
                    );
                }

                foreach ([[$lowerBound, $lower], [$upperBound, $upper]] as [$bound, $fraction]) {
                    $isRoot = $counter->isRootAt($exactCoefficients, $fraction);
                    if ($isRoot === null) {
                        return null;
                    }
                    if ($isRoot) {
                        $roots[] = new EquationSolution($bound, 0.0, 0);
                    }
                }

                \usort(
                    $roots,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $roots;
            }
        }

        $levelSource = \sprintf('%.17g', $level);
        $inequalitySolver = new InequalitySolver();
        $atOrAbove = $inequalitySolver->solve(
            $exponentExpression . '>=' . $levelSource,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );
        $atOrBelow = $inequalitySolver->solve(
            $exponentExpression . '<=' . $levelSource,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );

        $solutions = [];
        foreach ($atOrAbove as $aboveInterval) {
            foreach ($atOrBelow as $belowInterval) {
                $lower = \max($aboveInterval->lowerBound, $belowInterval->lowerBound);
                $upper = \min($aboveInterval->upperBound, $belowInterval->upperBound);
                $includesLower = ($lower !== $aboveInterval->lowerBound
                        || $aboveInterval->includesLowerBound)
                    && ($lower !== $belowInterval->lowerBound || $belowInterval->includesLowerBound);
                $includesUpper = ($upper !== $aboveInterval->upperBound
                        || $aboveInterval->includesUpperBound)
                    && ($upper !== $belowInterval->upperBound || $belowInterval->includesUpperBound);
                if ($lower < $upper) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
                if ($lower !== $upper || !$includesLower || !$includesUpper) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($lower, 0.0, 0),
                    $options,
                );
            }
        }

        return $solutions;
    }

    /**
     * Invert polynomial-power exponential equations through Lambert W.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveLambertWProductEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $function = $evaluationOptions->functions->find('lambertw');
        if ($function === null) {
            return null;
        }

        $matches = [
            [$left, $leftSource, 0, $right],
            [$right, $rightSource, 0, $left],
        ];
        foreach ($matches as [$productNode, $productSource, $productSourceOffset, $targetNode]) {
            $product = $this->lambertWEquationProductForm(
                $productNode,
                $productSource,
                $productSourceOffset,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            $target = $extractor->extract($targetNode);
            if (
                $product === null
                || $target === null
                || \count($target) !== 1
                || $product['coefficient'] === 0.0
            ) {
                continue;
            }

            $normalizedTarget = ($target[0] - $product['offset']) / $product['coefficient'];
            if (!\is_finite($normalizedTarget)) {
                continue;
            }

            $solutions = [];
            if ($product['scale'] === 0.0) {
                $baseLevels = $this->realIntegerPowerLevels(
                    $normalizedTarget,
                    $product['power'],
                );
                if ($baseLevels === null) {
                    return null;
                }
            } else {
                $scaledArgument = \pow(
                    $product['scale'] / $product['power'],
                    $product['power'],
                ) * $normalizedTarget;
                if (
                    !\is_finite($scaledArgument)
                    || ($scaledArgument === 0.0 && $normalizedTarget !== 0.0)
                ) {
                    return null;
                }
                $lambertInputs = $this->realIntegerPowerLevels(
                    $scaledArgument,
                    $product['power'],
                );
                if ($lambertInputs === null) {
                    return null;
                }
                $baseLevels = [];
                foreach ($lambertInputs as $lambertInput) {
                    foreach ([0, -1] as $branch) {
                        if ($branch === -1 && $lambertInput >= 0.0) {
                            continue;
                        }
                        try {
                            $lambertValue = (float) $function->invoke([
                                $lambertInput,
                                $branch,
                            ]);
                        } catch (\DomainException) {
                            continue;
                        }
                        $baseLevel = ($product['power'] / $product['scale']) * $lambertValue;
                        if (!\is_finite($baseLevel)) {
                            return null;
                        }
                        $baseLevels[] = $baseLevel;
                    }
                }
            }

            foreach (\array_values(\array_unique($baseLevels, SORT_REGULAR)) as $baseLevel) {
                $levelEquation = $product['argumentSource'] . '=' . \sprintf('%.17g', $baseLevel);
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $roots = $this->solve(
                        $levelEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (\DomainException | \InvalidArgumentException) {
                    continue;
                }
                foreach ($roots as $root) {
                    $residual = $residualAt($root->value);
                    $lambertTermMagnitude = \abs($target[0] - $product['offset']);
                    $verificationScale = \max(
                        1.0,
                        \abs($target[0]),
                        \abs($product['offset']),
                        $lambertTermMagnitude,
                    );
                    if (
                        $residual === null
                        || (
                            !$this->isResidualAcceptableAt(
                                $root->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                            && (
                                !\is_finite($verificationScale)
                                || \abs($residual)
                                    > ($solverOptions->residualTolerance
                                        + (8.0 * \PHP_FLOAT_EPSILON)) * $verificationScale
                            )
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($root->value, \abs($residual), $root->iterations),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve an affine exponential equal to a nonconstant polynomial monomial via real Lambert W branches.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineExponentialMonomialEquation(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $lambertW = $evaluationOptions->functions->find('lambertw');
        if ($lambertW === null) {
            return null;
        }

        foreach ([[$left, $right], [$right, $left]] as [$exponentialNode, $monomialNode]) {
            $exponentialNode = $this->unwrapGrouping($exponentialNode);
            $slope = null;
            $offset = null;
            if (
                $exponentialNode instanceof FunctionCallNode
                && $exponentialNode->name === 'exp'
                && \count($exponentialNode->arguments) === 1
            ) {
                $exponent = $extractor->extract($exponentialNode->arguments[0]);
                if ($exponent !== null && \count($exponent) <= 2) {
                    $offset = $exponent[0] ?? 0.0;
                    $slope = $exponent[1] ?? 0.0;
                }
            } elseif (
                $exponentialNode instanceof BinaryOperationNode
                && $exponentialNode->operator === BinaryOperator::Power
            ) {
                $base = $extractor->extract($exponentialNode->left);
                $exponent = $extractor->extract($exponentialNode->right);
                if (
                    $base !== null
                    && \count($base) === 1
                    && $base[0] > 0.0
                    && $base[0] !== 1.0
                    && $exponent !== null
                    && \count($exponent) <= 2
                ) {
                    $logarithm = \log($base[0]);
                    $offset = ($exponent[0] ?? 0.0) * $logarithm;
                    $slope = ($exponent[1] ?? 0.0) * $logarithm;
                }
            }
            if (
                $slope === null
                || $offset === null
                || $slope === 0.0
                || !\is_finite($slope)
                || !\is_finite($offset)
            ) {
                continue;
            }

            $coefficients = $extractor->extract($monomialNode);
            if ($coefficients === null) {
                continue;
            }
            $nonzeroDegrees = [];
            foreach ($coefficients as $degree => $coefficient) {
                if ($coefficient !== 0.0) {
                    $nonzeroDegrees[] = $degree;
                }
            }
            if ($nonzeroDegrees === []) {
                return [];
            }
            if (\count($nonzeroDegrees) !== 1) {
                continue;
            }
            $degree = $nonzeroDegrees[0];
            if ($degree < 1 || $degree > $options->maxPolynomialDegree) {
                continue;
            }
            $coefficient = $coefficients[$degree];
            if (!\is_finite($coefficient)) {
                continue;
            }
            if ($degree % 2 === 0 && $coefficient < 0.0) {
                return [];
            }

            $signs = $degree % 2 === 0
                ? [-1, 1]
                : [$coefficient < 0.0 ? -1 : 1];
            $solutions = [];
            foreach ($signs as $sign) {
                $recordCandidate = function (float $candidate) use (
                    &$solutions,
                    $lowerBound,
                    $upperBound,
                    $residualAt,
                    $candidateScaleAt,
                    $options,
                ): void {
                    if (
                        !\is_finite($candidate)
                        || $candidate < $lowerBound
                        || $candidate > $upperBound
                    ) {
                        return;
                    }
                    $residual = $residualAt($candidate);
                    if (
                        $residual === null
                        || !\is_finite($residual)
                        || !$this->isResidualAcceptableAt(
                            $candidate,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($residual), 0),
                        $options,
                    );
                };
                $logarithmOfArgumentMagnitude = \log(\abs($slope)) - \log((float) $degree)
                    + ($offset / $degree)
                    - (\log(\abs($coefficient)) / $degree);
                if (!\is_finite($logarithmOfArgumentMagnitude)) {
                    continue;
                }
                if ($logarithmOfArgumentMagnitude > \log(\PHP_FLOAT_MAX)) {
                    if ($slope * $sign > 0.0) {
                        continue;
                    }

                    return null;
                }
                $argumentMagnitude = \exp($logarithmOfArgumentMagnitude);
                $argumentIsNegative = $slope * $sign > 0.0;
                if ($logarithmOfArgumentMagnitude < \log(\PHP_FLOAT_MIN)) {
                    $principalMagnitude = \exp(
                        ($offset / $degree)
                        - (\log(\abs($coefficient)) / $degree),
                    );
                    $recordCandidate($sign * $principalMagnitude);

                    if ($argumentIsNegative) {
                        $target = -$logarithmOfArgumentMagnitude;
                        $negativeLambertMagnitude = $target + \log($target);
                        for ($iteration = 0; $iteration < 8; ++$iteration) {
                            $residual = $negativeLambertMagnitude
                                - \log($negativeLambertMagnitude)
                                - $target;
                            $negativeLambertMagnitude -= $residual
                                / (1.0 - (1.0 / $negativeLambertMagnitude));
                        }
                        $logarithmOfMagnitude = \log((float) $degree)
                            - \log(\abs($slope))
                            + \log($negativeLambertMagnitude);
                        if ($logarithmOfMagnitude <= \log(\PHP_FLOAT_MAX)) {
                            $recordCandidate($sign * \exp($logarithmOfMagnitude));
                        }
                    }

                    continue;
                }
                if ($argumentIsNegative && $argumentMagnitude > (1.0 / \M_E)) {
                    if (
                        $argumentMagnitude - (1.0 / \M_E)
                        > 64.0 * \PHP_FLOAT_EPSILON / \M_E
                    ) {
                        continue;
                    }
                    $argumentMagnitude = 1.0 / \M_E;
                }
                $argument = $argumentIsNegative ? -$argumentMagnitude : $argumentMagnitude;
                $branches = $argumentIsNegative ? [0, -1] : [0];
                foreach ($branches as $branch) {
                    try {
                        $lambertValue = (float) $lambertW->invoke([$argument, $branch]);
                    } catch (\DomainException) {
                        continue;
                    }
                    if ($lambertValue === 0.0) {
                        continue;
                    }
                    $logarithmOfMagnitude = \log((float) $degree)
                        - \log(\abs($slope))
                        + \log(\abs($lambertValue));
                    if ($logarithmOfMagnitude > \log(\PHP_FLOAT_MAX)) {
                        continue;
                    }
                    $magnitude = \exp($logarithmOfMagnitude);
                    if (!\is_finite($magnitude) || $magnitude <= 0.0) {
                        continue;
                    }
                    $recordCandidate($sign * $magnitude);
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function solveExponentialPolynomialEquation(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftNode = $this->unwrapGrouping($left);
        $rightNode = $this->unwrapGrouping($right);
        if (
            $leftNode instanceof FunctionCallNode
            && \in_array($leftNode->name, ['sinh', 'cosh'], true)
            && \count($leftNode->arguments) === 1
            && \count($extractor->extract($right) ?? []) === 1
        ) {
            return null;
        }
        if (
            $rightNode instanceof FunctionCallNode
            && \in_array($rightNode->name, ['sinh', 'cosh'], true)
            && \count($rightNode->arguments) === 1
            && \count($extractor->extract($left) ?? []) === 1
        ) {
            return null;
        }
        $leftForm = $this->exponentialRationalForm($left, $extractor);
        $rightForm = $this->exponentialRationalForm($right, $extractor);
        if ($leftForm === null || $rightForm === null) {
            return null;
        }
        $leftTerms = $this->multiplyExponentialTerms(
            $leftForm['numerator'],
            $rightForm['denominator'],
        );
        $rightTerms = $this->multiplyExponentialTerms(
            $rightForm['numerator'],
            $leftForm['denominator'],
        );
        if ($leftTerms === null || $rightTerms === null || \count($leftTerms) + \count($rightTerms) > 256) {
            return null;
        }
        foreach ($rightTerms as &$term) {
            $term['coefficient'] *= -1.0;
        }
        unset($term);
        $terms = [...$leftTerms, ...$rightTerms];

        $slopes = [];
        foreach ($terms as $term) {
            if ($term['coefficient'] !== 0.0 && $term['slope'] !== 0.0) {
                $slopes[] = \abs($term['slope']);
            }
        }
        if ($slopes === []) {
            $constantValue = 0.0;
            foreach ($terms as $term) {
                if ($term['coefficient'] === 0.0) {
                    continue;
                }
                if ($term['slope'] !== 0.0) {
                    return null;
                }
                $constantTerm = $term['coefficient'] * \exp($term['offset']);
                if (!\is_finite($constantTerm)) {
                    return null;
                }
                $constantValue += $constantTerm;
                if (!\is_finite($constantValue)) {
                    return null;
                }
            }
            if ($constantValue === 0.0) {
                throw new InfiniteSolutionSetException(
                    'The exponential terms cancel to an identity over the requested interval.',
                );
            }

            return [];
        }

        $baseCandidates = [];
        foreach ($slopes as $slope) {
            for ($divisor = 1; $divisor <= $options->maxPolynomialDegree; ++$divisor) {
                $baseCandidates[] = $slope / $divisor;
            }
        }
        \rsort($baseCandidates, SORT_NUMERIC);
        $base = null;
        $frequencies = [];
        foreach (\array_unique($baseCandidates, SORT_REGULAR) as $candidate) {
            if ($candidate <= 0.0 || !\is_finite($candidate)) {
                continue;
            }
            $candidateFrequencies = [];
            $minimum = \PHP_INT_MAX;
            $maximum = \PHP_INT_MIN;
            $valid = true;
            foreach ($terms as $index => $term) {
                $frequency = $term['slope'] / $candidate;
                $nearest = \round($frequency);
                if (
                    !\is_finite($frequency)
                    || \abs($frequency - $nearest)
                        > 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($frequency))
                    || \abs($nearest) > $options->maxPolynomialDegree
                ) {
                    $valid = false;
                    break;
                }
                $candidateFrequencies[$index] = (int) $nearest;
                if ($term['coefficient'] !== 0.0) {
                    $minimum = \min($minimum, (int) $nearest);
                    $maximum = \max($maximum, (int) $nearest);
                }
            }
            if (
                $valid
                && $minimum !== \PHP_INT_MAX
                && $maximum - $minimum <= $options->maxPolynomialDegree
            ) {
                $base = $candidate;
                $frequencies = $candidateFrequencies;
                break;
            }
        }
        if ($base === null) {
            if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
                return $this->solveIncommensurateExponentialPolynomial(
                    $terms,
                    $lowerBound,
                    $upperBound,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
            }
            return $this->solveIncommensurateExponentialPolynomial(
                $terms,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        $minimumFrequency = \PHP_INT_MAX;
        $maximumFrequency = \PHP_INT_MIN;
        foreach ($terms as $index => $term) {
            if ($term['coefficient'] !== 0.0) {
                $minimumFrequency = \min($minimumFrequency, $frequencies[$index]);
                $maximumFrequency = \max($maximumFrequency, $frequencies[$index]);
            }
        }
        $degree = $maximumFrequency - $minimumFrequency;
        if ($degree === 0) {
            $constantFactor = 0.0;
            foreach ($terms as $term) {
                if ($term['coefficient'] === 0.0) {
                    continue;
                }
                $constantTerm = $term['coefficient'] * \exp($term['offset']);
                if (!\is_finite($constantTerm)) {
                    return null;
                }
                $constantFactor += $constantTerm;
                if (!\is_finite($constantFactor)) {
                    return null;
                }
            }
            if ($constantFactor === 0.0) {
                throw new InfiniteSolutionSetException(
                    'The exponential terms cancel to an identity over the requested interval.',
                );
            }

            return [];
        }
        if ($degree < 0 || $degree > $options->maxPolynomialDegree) {
            return null;
        }

        $coefficients = \array_fill(0, $degree + 1, 0.0);
        foreach ($terms as $index => $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            $constantFactor = \exp($term['offset']);
            $coefficient = $term['coefficient'] * $constantFactor;
            if (!\is_finite($coefficient) || ($coefficient === 0.0 && $term['coefficient'] !== 0.0)) {
                return null;
            }
            $position = $frequencies[$index] - $minimumFrequency;
            $coefficients[$position] += $coefficient;
            if (!\is_finite($coefficients[$position])) {
                return null;
            }
        }
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        $coefficients = \array_values($coefficients);
        if (\count($coefficients) === 1) {
            if ($coefficients[0] === 0.0) {
                throw new InfiniteSolutionSetException(
                    'The exponential terms cancel to an identity over the requested interval.',
                );
            }

            return [];
        }
        $unboundedInterval = !\is_finite($lowerBound) || !\is_finite($upperBound);
        $hasExtremeCoefficientScale = $unboundedInterval
            && $this->hasExtremePolynomialCoefficientScale($coefficients);
        if ($unboundedInterval) {
            $upperRootBound = $this->positivePolynomialRootBound($coefficients);
            if ($upperRootBound === null) {
                return null;
            }
            $firstBound = 0.0;
            $secondBound = $upperRootBound;
        } else {
            $lowerExponent = $base * $lowerBound;
            $upperExponent = $base * $upperBound;
            $firstBound = \exp(\min($lowerExponent, $upperExponent));
            $secondBound = \exp(\max($lowerExponent, $upperExponent));
            if (
                !\is_finite($firstBound)
                || !\is_finite($secondBound)
                || $firstBound <= 0.0
                || $secondBound <= $firstBound
            ) {
                return null;
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $hasExponentialDenominator = \count($leftForm['denominator']) > 1
            || \count($rightForm['denominator']) > 1;
        $useBoundedExactPrecision = !$hasExponentialDenominator && $degree >= 4 && $degree <= 32;
        $exactPhaseShift = $useBoundedExactPrecision
            ? $this->sharedExponentialPhaseShift($terms)
            : null;
        $exactIntegerCoefficients = $exactPhaseShift !== null
            ? $this->exactExponentialPolynomialIntegerCoefficients(
                $terms,
                $frequencies,
                $minimumFrequency,
                \count($coefficients),
                $exactPhaseShift,
            )
            : null;
        $exactLowerBound = $firstBound;
        $exactUpperBound = $secondBound;
        if ($exactIntegerCoefficients !== null && $exactPhaseShift !== 0.0) {
            $exactLowerBound = \exp($base * ($lowerBound + $exactPhaseShift));
            $exactUpperBound = \exp($base * ($upperBound + $exactPhaseShift));
            if (
                !\is_finite($exactLowerBound)
                || !\is_finite($exactUpperBound)
                || $exactLowerBound <= 0.0
                || $exactUpperBound <= $exactLowerBound
            ) {
                $exactIntegerCoefficients = null;
            }
        }
        $exactRoots = !$unboundedInterval && ($hasExponentialDenominator || $useBoundedExactPrecision)
            ? $this->exactExponentialPolynomialRoots(
                $coefficients,
                $exactLowerBound,
                $exactUpperBound,
                $base,
                $lowerBound,
                $upperBound,
                $options,
                $useBoundedExactPrecision,
                $exactIntegerCoefficients,
            )
            : null;
        $extremeQuadraticRoots = $hasExtremeCoefficientScale && \count($coefficients) === 3
            ? $this->scaledQuadraticRoots($coefficients)
            : null;
        if ($extremeQuadraticRoots !== null) {
            $polynomialRoots = \array_map(
                static fn (float $root): EquationSolution => new EquationSolution($root, 0.0, 0),
                $extremeQuadraticRoots,
            );
        } elseif ($exactRoots === null) {
            $polynomialRoots = $polynomialSolver->solve(
                $coefficients,
                $firstBound,
                $secondBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($coefficients, $value),
                $options,
                fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($coefficients, $value),
            );
        } else {
            $polynomialRoots = [];
            foreach ($exactRoots as $root) {
                $polynomialResidual = $polynomialSolver->evaluatePolynomial($coefficients, $root);
                if ($polynomialResidual === null) {
                    return null;
                }
                $polynomialRoots[] = new EquationSolution($root, \abs($polynomialResidual), 0);
            }
        }
        if ($polynomialRoots === null) {
            return null;
        }

        $solutions = [];
        $polynomialRootShift = $exactRoots !== null && $exactIntegerCoefficients !== null
            ? $exactPhaseShift
            : 0.0;
        foreach ($polynomialRoots as $polynomialRoot) {
            if ($polynomialRoot->value <= 0.0) {
                continue;
            }
            $root = (\log($polynomialRoot->value) / $base) - $polynomialRootShift;
            if (!\is_finite($root) || $root < $lowerBound || $root > $upperBound) {
                continue;
            }
            $residual = $residualAt($root);
            if ($residual === null) {
                continue;
            }
            $polynomialMagnitude = $polynomialSolver->evaluatePolynomialMagnitude(
                $coefficients,
                $polynomialRoot->value,
            );
            $residualAccepted = $polynomialMagnitude === null
                ? $this->isResidualAcceptableAt($root, $residual, $candidateScaleAt, $options)
                : \abs($residual) <= $options->residualTolerance * \max(1.0, $polynomialMagnitude);
            if (!$residualAccepted) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root, \abs($residual), $polynomialRoot->iterations),
                $options,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /** @param list<float> $coefficients */
    private function positivePolynomialRootBound(array $coefficients): ?float
    {
        $leading = \abs($coefficients[\array_key_last($coefficients)]);
        if ($leading === 0.0) {
            return null;
        }
        $maximumLogRatio = -\INF;
        foreach ($coefficients as $index => $coefficient) {
            if ($index === \array_key_last($coefficients) || $coefficient === 0.0) {
                continue;
            }
            $maximumLogRatio = \max($maximumLogRatio, \log(\abs($coefficient)) - \log($leading));
        }
        if ($maximumLogRatio === -\INF) {
            return 1.0;
        }
        $logBound = \max(0.0, $maximumLogRatio) + \log(2.0);
        if ($logBound > \log(\PHP_FLOAT_MAX)) {
            return null;
        }

        return \exp($logBound);
    }

    /** @param list<float> $coefficients @return list<float>|null */
    private function scaledQuadraticRoots(array $coefficients): ?array
    {
        [$constant, $linear, $quadratic] = $coefficients;
        if ($quadratic === 0.0) {
            return null;
        }
        $linearMagnitude = \abs($linear);
        if ($linearMagnitude === 0.0) {
            if ($constant === 0.0) {
                return [0.0];
            }
            $logRoot = 0.5 * (\log(\abs($constant)) - \log(\abs($quadratic)));
            if ($logRoot > \log(\PHP_FLOAT_MAX)) {
                return null;
            }
            $squareRoot = \exp($logRoot);
            if (!\is_finite($squareRoot)) {
                return null;
            }

            return (($constant < 0.0) !== ($quadratic < 0.0))
                ? [-$squareRoot, $squareRoot]
                : [];
        }
        $logRatio = $constant === 0.0
            ? -\INF
            : \log(\abs($constant)) + \log(\abs($quadratic)) - (2.0 * \log($linearMagnitude / 2.0));
        $productSign = $constant === 0.0 ? 0 : (($constant < 0.0) === ($quadratic < 0.0) ? 1 : -1);
        $discriminantCorrection = $logRatio < -745.0 ? 0.0 : \exp($logRatio);
        $normalizedDiscriminant = 1.0 - ($productSign * $discriminantCorrection);
        if ($normalizedDiscriminant < 0.0) {
            return [];
        }
        $sqrtDiscriminant = $linearMagnitude * \sqrt($normalizedDiscriminant);
        $signedRoot = $linear < 0.0 ? -$sqrtDiscriminant : $sqrtDiscriminant;
        $q = -0.5 * ($linear + $signedRoot);
        if ($q === 0.0) {
            $root = -$linear / (2.0 * $quadratic);

            return \is_finite($root) ? [$root] : null;
        }
        $roots = [$q / $quadratic, $constant / $q];
        if (!\is_finite($roots[0]) || !\is_finite($roots[1])) {
            return null;
        }
        \sort($roots, SORT_NUMERIC);

        return $roots[0] === $roots[1] ? [$roots[0]] : $roots;
    }

    /** @param list<float> $coefficients */
    private function hasExtremePolynomialCoefficientScale(array $coefficients): bool
    {
        $minimumLog = \INF;
        $maximumLog = -\INF;
        foreach ($coefficients as $coefficient) {
            $magnitude = \abs($coefficient);
            if ($magnitude === 0.0) {
                continue;
            }
            $logMagnitude = \log($magnitude);
            $minimumLog = \min($minimumLog, $logMagnitude);
            $maximumLog = \max($maximumLog, $logMagnitude);
        }

        return $maximumLog - $minimumLog > \log(1.0E12);
    }

    /**
     * Exactly isolate transformed polynomial roots when its float
     * coefficients have bounded rational representations.
     *
     * @param list<float> $coefficients
     * @return list<float>|null Null requests the floating-point fallback.
     */
    /** @param list<array{coefficient: float, slope: float, offset: float}> $terms */
    private function sharedExponentialPhaseShift(array $terms): ?float
    {
        $shift = null;
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            if ($term['slope'] === 0.0) {
                if ($term['offset'] !== 0.0) {
                    return null;
                }
                continue;
            }
            $candidate = $term['offset'] / $term['slope'];
            if (
                !\is_finite($candidate)
                || ($shift !== null && !$this->exponentialOffsetMatchesShift(
                    $term['slope'],
                    $term['offset'],
                    $shift,
                ))
            ) {
                return null;
            }
            $shift ??= $candidate;
        }

        return $shift ?? 0.0;
    }

    private function exactExponentialPolynomialIntegerCoefficients(
        array $terms,
        array $frequencies,
        int $minimumFrequency,
        int $coefficientCount,
        float $phaseShift,
    ): ?array {
        $fractions = [];
        $commonDenominator = '1';
        foreach ($terms as $index => $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            if (!$this->exponentialOffsetMatchesShift($term['slope'], $term['offset'], $phaseShift)) {
                return null;
            }
            $fraction = RationalLiteral::fromFloatExactAsStrings($term['coefficient']);
            $maximumFractionDigits = $coefficientCount <= 9 ? 400 : 32;
            if (
                $fraction === null
                || \strlen($fraction[0]) > $maximumFractionDigits
                || \strlen($fraction[1]) > $maximumFractionDigits
            ) {
                return null;
            }
            $fractions[] = [$frequencies[$index] - $minimumFrequency, $fraction];
            if (\strlen($fraction[1]) > \strlen($commonDenominator)) {
                $commonDenominator = $fraction[1];
            }
        }

        $arithmetic = new IntegerPolynomialExtractor('', []);
        $integerCoefficients = \array_fill(0, $coefficientCount, '0');
        foreach ($fractions as [$position, [$numerator, $denominator]]) {
            $factor = $arithmetic->divideIntegerValueExactly($commonDenominator, $denominator);
            if ($factor === null || !isset($integerCoefficients[$position])) {
                return null;
            }
            $integerCoefficients[$position] = $arithmetic->addIntegerValues(
                $integerCoefficients[$position],
                $arithmetic->multiplyIntegerValues($numerator, $factor),
            );
        }
        while (
            \count($integerCoefficients) > 1
            && $integerCoefficients[\array_key_last($integerCoefficients)] === '0'
        ) {
            \array_pop($integerCoefficients);
        }

        return $integerCoefficients === ['0'] ? null : $integerCoefficients;
    }

    private function exponentialOffsetMatchesShift(float $slope, float $offset, float $shift): bool
    {
        $expectedOffset = $slope * $shift;
        if (!\is_finite($expectedOffset)) {
            return false;
        }
        $tolerance = 2.0 * \PHP_FLOAT_EPSILON * \max(\abs($offset), \abs($expectedOffset));

        return \abs($offset - $expectedOffset) <= $tolerance;
    }

    private function exactExponentialPolynomialRoots(
        array $coefficients,
        float $lower,
        float $upper,
        float $base,
        float $variableLower,
        float $variableUpper,
        SolverOptions $options,
        bool $useBoundedExactPrecision = false,
        ?array $exactIntegerCoefficients = null,
    ): ?array {
        $arithmetic = new IntegerPolynomialExtractor('', []);
        $boundedExactPrecision = $useBoundedExactPrecision && \count($coefficients) >= 5;
        $integerCoefficients = $exactIntegerCoefficients;
        if ($integerCoefficients === null) {
            $fractions = [];
            $commonDenominator = '1';
            foreach ($coefficients as $coefficient) {
                if (
                    !\is_finite($coefficient)
                    || (
                        !$boundedExactPrecision
                        && (\abs($coefficient) > 1.0E15 || \floor($coefficient) !== $coefficient)
                    )
                ) {
                    return null;
                }
                $fraction = $boundedExactPrecision
                    ? RationalLiteral::fromFloatExactAsStrings($coefficient)
                    : RationalLiteral::fromFloatAsStrings($coefficient);
                if ($fraction === null) {
                    return null;
                }
                if ($boundedExactPrecision && (\strlen($fraction[0]) > 32 || \strlen($fraction[1]) > 32)) {
                    return null;
                }
                $fractions[] = $fraction;
                $gcd = $arithmetic->greatestCommonDivisorValues($commonDenominator, $fraction[1]);
                $reduced = $arithmetic->divideIntegerValueExactly($commonDenominator, $gcd);
                if ($reduced === null) {
                    return null;
                }
                $commonDenominator = $arithmetic->multiplyIntegerValues($reduced, $fraction[1]);
            }

            $integerCoefficients = [];
            foreach ($fractions as [$numerator, $denominator]) {
                $factor = $arithmetic->divideIntegerValueExactly($commonDenominator, $denominator);
                if ($factor === null) {
                    return null;
                }
                $integerCoefficients[] = $arithmetic->multiplyIntegerValues($numerator, $factor);
            }
        }

        $content = '0';
        foreach ($integerCoefficients as $coefficient) {
            $content = $arithmetic->greatestCommonDivisorValues($content, $coefficient);
        }
        if ($content !== '0' && $content !== '1') {
            foreach ($integerCoefficients as &$coefficient) {
                $coefficient = $arithmetic->divideIntegerValueExactly($coefficient, $content) ?? $coefficient;
            }
            unset($coefficient);
        }

        $translatedBinomialRoots = $this->exactTranslatedBinomialRoots(
            $integerCoefficients,
            $lower,
            $upper,
            $arithmetic,
        );
        if ($translatedBinomialRoots !== null) {
            return $translatedBinomialRoots;
        }

        $lowerFraction = $boundedExactPrecision
            ? RationalLiteral::fromFloatExactAsStrings($lower)
            : RationalLiteral::fromFloatAsStrings($lower);
        $upperFraction = $boundedExactPrecision
            ? RationalLiteral::fromFloatExactAsStrings($upper)
            : RationalLiteral::fromFloatAsStrings($upper);
        $targetWidth = \abs($base)
            * $options->positionTolerance($variableLower, $variableUpper)
            * $lower;
        $widthFraction = $boundedExactPrecision
            ? RationalLiteral::fromFloatExactAsStrings($targetWidth)
            : RationalLiteral::fromFloatAsStrings($targetWidth);
        if (
            $lowerFraction === null
            || $upperFraction === null
            || $widthFraction === null
            || $widthFraction[0] === '0'
        ) {
            return null;
        }

        $counter = new ExactPolynomialRootCounter();
        $rootCount = $boundedExactPrecision && \count($integerCoefficients) > 21
            ? $counter->countOpenInterval(
                $integerCoefficients,
                $lowerFraction[0],
                $lowerFraction[1],
                $upperFraction[0],
                $upperFraction[1],
            )
            : null;
        $intervals = $rootCount === 0
            ? []
            : $counter->isolateOpenInterval(
                $integerCoefficients,
                $lowerFraction[0],
                $lowerFraction[1],
                $upperFraction[0],
                $upperFraction[1],
                maxDepth: 512,
                maximumWidth: $widthFraction,
            );
        if ($intervals === null) {
            return null;
        }
        $intervals[] = [
            $lowerFraction[0],
            $lowerFraction[1],
            $lowerFraction[0],
            $lowerFraction[1],
        ];
        $intervals[] = [
            $upperFraction[0],
            $upperFraction[1],
            $upperFraction[0],
            $upperFraction[1],
        ];
        $roots = [];
        foreach ($intervals as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
            if ($lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator) {
                $isRoot = $counter->isRootAt($integerCoefficients, [$lowerNumerator, $lowerDenominator]);
                if ($isRoot === null) {
                    return null;
                }
                if (!$isRoot) {
                    continue;
                }
            }
            $rootLower = $arithmetic->ratio($lowerNumerator, $lowerDenominator);
            $rootUpper = $arithmetic->ratio($upperNumerator, $upperDenominator);
            if (!\is_float($rootLower) || !\is_float($rootUpper)) {
                return null;
            }
            $root = ($rootLower / 2.0) + ($rootUpper / 2.0);
            if ($root <= 0.0 || !\is_finite($root)) {
                return null;
            }
            $roots[] = $root;
        }

        \sort($roots, SORT_NUMERIC);
        $distinctRoots = [];
        foreach ($roots as $root) {
            $last = $distinctRoots[\array_key_last($distinctRoots)] ?? null;
            if ($last === null || $root !== $last) {
                $distinctRoots[] = $root;
            }
        }

        return $distinctRoots;
    }

    /**
     * Resolve exact even binomials after an integer translation, avoiding a
     * full Sturm sequence for high-multiplicity contacts and strict offsets.
     *
     * @param list<string> $coefficients
     * @return list<float>|null Null means the polynomial is not a translated binomial.
     */
    private function exactTranslatedBinomialRoots(
        array $coefficients,
        float $lower,
        float $upper,
        IntegerPolynomialExtractor $arithmetic,
    ): ?array {
        $degree = \count($coefficients) - 1;
        if ($degree < 4 || ($degree % 2) !== 0 || ($coefficients[$degree - 1] ?? '0') === '0') {
            return null;
        }
        $centerNumerator = $arithmetic->negateIntegerValue($coefficients[$degree - 1]);
        $centerDenominator = $arithmetic->multiplyIntegerValues((string) $degree, $coefficients[$degree]);
        $center = $arithmetic->divideIntegerValueExactly($centerNumerator, $centerDenominator);
        if ($center === null) {
            return null;
        }

        $translated = [$coefficients[$degree]];
        for ($power = $degree - 1; $power >= 0; --$power) {
            $next = \array_fill(0, \count($translated) + 1, '0');
            foreach ($translated as $translatedPower => $coefficient) {
                $next[$translatedPower] = $arithmetic->addIntegerValues(
                    $next[$translatedPower],
                    $arithmetic->multiplyIntegerValues($coefficient, $center),
                );
                $next[$translatedPower + 1] = $arithmetic->addIntegerValues(
                    $next[$translatedPower + 1],
                    $coefficient,
                );
            }
            $next[0] = $arithmetic->addIntegerValues($next[0], $coefficients[$power]);
            $translated = $next;
        }
        for ($power = 1; $power < $degree; ++$power) {
            if ($translated[$power] !== '0') {
                return null;
            }
        }
        $constantSign = $arithmetic->sign($translated[0]);
        $leadingSign = $arithmetic->sign($translated[$degree]);
        $centerFloat = $arithmetic->ratio($center, '1');
        if (!\is_float($centerFloat)) {
            return null;
        }
        if ($constantSign === 0) {
            return $centerFloat >= $lower && $centerFloat <= $upper ? [$centerFloat] : [];
        }
        if ($constantSign === $leadingSign) {
            return [];
        }

        $absoluteConstant = $constantSign < 0
            ? $arithmetic->negateIntegerValue($translated[0])
            : $translated[0];
        $absoluteLeading = $leadingSign < 0
            ? $arithmetic->negateIntegerValue($translated[$degree])
            : $translated[$degree];
        $constantToLeading = $arithmetic->ratio($absoluteConstant, $absoluteLeading);
        if (!\is_float($constantToLeading) || $constantToLeading <= 0.0) {
            return null;
        }
        $distance = \pow($constantToLeading, 1.0 / $degree);
        if (!\is_finite($distance)) {
            return null;
        }
        $roots = [];
        foreach ([$centerFloat - $distance, $centerFloat + $distance] as $root) {
            if ($root >= $lower && $root <= $upper) {
                $roots[] = $root;
            }
        }

        return $roots;
    }

    /**
     * Isolate all roots of a real exponential sum when its slopes do not share
     * an integer frequency, using recursive derivative roots and Rolle's theorem.
     *
     * @param list<array{coefficient: float, slope: float, offset: float}> $terms
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveIncommensurateExponentialPolynomial(
        array $terms,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $roots = (new ExponentialPolynomialSolver())->solve($terms, $lowerBound, $upperBound, $options);
        if ($roots === null) {
            return null;
        }

        $verificationScaleAt = function (float $value) use ($terms, $candidateScaleAt): ?float {
            $scale = $candidateScaleAt($value);
            $termScale = $this->exponentialTermScaleAt($terms, $value);
            if ($scale === null && $termScale === null) {
                return null;
            }

            return \max($scale ?? 0.0, $termScale ?? 0.0);
        };
        $solutions = [];
        foreach ($roots as $root) {
            $residual = $residualAt($root);
            if (
                $residual !== null
                && !$this->isResidualAcceptableAt($root, $residual, $verificationScaleAt, $options)
            ) {
                $refinedRoot = $this->refineVerifiedEquationCandidate(
                    $root,
                    $residual,
                    $residualAt,
                    $root,
                    $root - (16.0 * \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, \abs($root))),
                    $root + (16.0 * \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, \abs($root))),
                    $options,
                );
                if ($refinedRoot !== $root) {
                    $root = $refinedRoot;
                    $residual = $residualAt($root);
                }
            }
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($root, $residual, $verificationScaleAt, $options)
            ) {
                return null;
            }
            $solutions[] = new EquationSolution($root, \abs($residual), 0);
        }

        return $solutions;
    }

    /**
     * Sum absolute affine-exponential term magnitudes without intermediate overflow.
     *
     * @param list<array{coefficient: float, slope: float, offset: float}> $terms
     */
    private function exponentialTermScaleAt(array $terms, float $value): ?float
    {
        $logMagnitudes = [];
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            $logMagnitude = \log(\abs($term['coefficient'])) + $term['offset'] + ($term['slope'] * $value);
            if (!\is_finite($logMagnitude)) {
                return null;
            }
            $logMagnitudes[] = $logMagnitude;
        }
        if ($logMagnitudes === []) {
            return null;
        }

        $maximum = \max($logMagnitudes);
        $scaledSum = 0.0;
        foreach ($logMagnitudes as $logMagnitude) {
            $scaledSum += \exp($logMagnitude - $maximum);
        }
        $logScale = $maximum + \log($scaledSum);
        if ($logScale >= \log(\PHP_FLOAT_MAX)) {
            return \PHP_FLOAT_MAX;
        }
        if ($logScale <= \log(\PHP_FLOAT_MIN)) {
            return \PHP_FLOAT_MIN;
        }

        return \exp($logScale);
    }

    /**
     * @param list<array{coefficient: float, slope: float, offset: float}> $terms
     * @return array{float, float}|null
     */
    private function exponentialSumRootBounds(array $terms): ?array
    {
        return (new ExponentialPolynomialSolver())->rootBounds($terms);
    }

    /**
     * @return array{
     *   numerator: list<array{coefficient: float, slope: float, offset: float}>,
     *   denominator: list<array{coefficient: float, slope: float, offset: float}>
     * }|null
     */
    private function exponentialRationalForm(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->exponentialRationalForm($node->operand, $extractor);
            if ($form === null) {
                return null;
            }
            if ($node->operator === UnaryOperator::Minus) {
                foreach ($form['numerator'] as &$term) {
                    $term['coefficient'] *= -1.0;
                }
                unset($term);
            }

            return $form;
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Power) {
                $power = $extractor->extract($node->right);
                if (
                    $power === null
                    || \count($power) !== 1
                    || \floor($power[0]) !== $power[0]
                    || \abs($power[0]) < 1.0
                    || \abs($power[0]) > 9007199254740991.0
                ) {
                    return null;
                }
                $base = $this->exponentialRationalForm($node->left, $extractor);
                if ($base === null) {
                    return null;
                }
                if ($power[0] < 0.0) {
                    $base = [
                        'numerator' => $base['denominator'],
                        'denominator' => $base['numerator'],
                    ];
                }
                $remainingPower = (int) \abs($power[0]);
                $numerator = [['coefficient' => 1.0, 'slope' => 0.0, 'offset' => 0.0]];
                $denominator = [['coefficient' => 1.0, 'slope' => 0.0, 'offset' => 0.0]];
                $factorNumerator = $base['numerator'];
                $factorDenominator = $base['denominator'];
                while ($remainingPower > 0) {
                    if (($remainingPower % 2) === 1) {
                        $numerator = $this->multiplyExponentialTerms($numerator, $factorNumerator);
                        $denominator = $this->multiplyExponentialTerms($denominator, $factorDenominator);
                        if ($numerator === null || $denominator === null) {
                            return null;
                        }
                    }
                    $remainingPower = \intdiv($remainingPower, 2);
                    if ($remainingPower > 0) {
                        $factorNumerator = $this->multiplyExponentialTerms(
                            $factorNumerator,
                            $factorNumerator,
                        );
                        $factorDenominator = $this->multiplyExponentialTerms(
                            $factorDenominator,
                            $factorDenominator,
                        );
                        if ($factorNumerator === null || $factorDenominator === null) {
                            return null;
                        }
                    }
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }
            if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                $left = $this->exponentialRationalForm($node->left, $extractor);
                $right = $this->exponentialRationalForm($node->right, $extractor);
                if ($left === null || $right === null) {
                    return null;
                }
                $leftProduct = $this->multiplyExponentialTerms(
                    $left['numerator'],
                    $right['denominator'],
                );
                $rightProduct = $this->multiplyExponentialTerms(
                    $right['numerator'],
                    $left['denominator'],
                );
                if (
                    $leftProduct === null
                    || $rightProduct === null
                    || \count($leftProduct) + \count($rightProduct) > 256
                ) {
                    return null;
                }
                $sign = $node->operator === BinaryOperator::Subtract ? -1.0 : 1.0;
                foreach ($rightProduct as &$term) {
                    $term['coefficient'] *= $sign;
                }
                unset($term);
                $denominator = $this->multiplyExponentialTerms(
                    $left['denominator'],
                    $right['denominator'],
                );
                if ($denominator === null) {
                    return null;
                }

                return [
                    'numerator' => [...$leftProduct, ...$rightProduct],
                    'denominator' => $denominator,
                ];
            }
            if ($node->operator === BinaryOperator::Multiply) {
                $left = $this->exponentialRationalForm($node->left, $extractor);
                $right = $this->exponentialRationalForm($node->right, $extractor);
                if ($left === null || $right === null) {
                    return null;
                }
                $numerator = $this->multiplyExponentialTerms(
                    $left['numerator'],
                    $right['numerator'],
                );
                $denominator = $this->multiplyExponentialTerms(
                    $left['denominator'],
                    $right['denominator'],
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }
            if ($node->operator === BinaryOperator::Divide) {
                $left = $this->exponentialRationalForm($node->left, $extractor);
                $right = $this->exponentialRationalForm($node->right, $extractor);
                if ($left === null || $right === null) {
                    return null;
                }
                $numerator = $this->multiplyExponentialTerms(
                    $left['numerator'],
                    $right['denominator'],
                );
                $denominator = $this->multiplyExponentialTerms(
                    $left['denominator'],
                    $right['numerator'],
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['exp', 'sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth'], true)
            && \count($node->arguments) === 1
        ) {
            $exponent = $extractor->extract($node->arguments[0]);
            if ($exponent === null || \count($exponent) > 2) {
                return null;
            }
            $offset = $exponent[0] ?? 0.0;
            $slope = $exponent[1] ?? 0.0;
            if (!\is_finite($offset) || !\is_finite($slope)) {
                return null;
            }
            $positiveExponential = ['coefficient' => 1.0, 'slope' => $slope, 'offset' => $offset];
            $negativeExponential = ['coefficient' => 1.0, 'slope' => -$slope, 'offset' => -$offset];
            $unit = ['coefficient' => 1.0, 'slope' => 0.0, 'offset' => 0.0];
            $form = match ($node->name) {
                'exp' => ['numerator' => [$positiveExponential], 'denominator' => [$unit]],
                'sinh' => [
                    'numerator' => [
                        ['coefficient' => 0.5, 'slope' => $slope, 'offset' => $offset],
                        ['coefficient' => -0.5, 'slope' => -$slope, 'offset' => -$offset],
                    ],
                    'denominator' => [$unit],
                ],
                'cosh' => [
                    'numerator' => [
                        ['coefficient' => 0.5, 'slope' => $slope, 'offset' => $offset],
                        ['coefficient' => 0.5, 'slope' => -$slope, 'offset' => -$offset],
                    ],
                    'denominator' => [$unit],
                ],
                'tanh' => [
                    'numerator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        ['coefficient' => -1.0, 'slope' => 0.0, 'offset' => 0.0],
                    ],
                    'denominator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        $unit,
                    ],
                ],
                'sech' => [
                    'numerator' => [['coefficient' => 2.0, 'slope' => $slope, 'offset' => $offset]],
                    'denominator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        $unit,
                    ],
                ],
                'csch' => [
                    'numerator' => [['coefficient' => 2.0, 'slope' => $slope, 'offset' => $offset]],
                    'denominator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        ['coefficient' => -1.0, 'slope' => 0.0, 'offset' => 0.0],
                    ],
                ],
                'coth' => [
                    'numerator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        $unit,
                    ],
                    'denominator' => [
                        ['coefficient' => 1.0, 'slope' => 2.0 * $slope, 'offset' => 2.0 * $offset],
                        ['coefficient' => -1.0, 'slope' => 0.0, 'offset' => 0.0],
                    ],
                ],
            };
            foreach ([...$form['numerator'], ...$form['denominator']] as $term) {
                if (!\is_finite($term['slope']) || !\is_finite($term['offset'])) {
                    return null;
                }
            }

            return $form;
        }

        $constant = $extractor->extract($node);
        if ($constant === null || \count($constant) !== 1) {
            return null;
        }

        return [
            'numerator' => [['coefficient' => $constant[0], 'slope' => 0.0, 'offset' => 0.0]],
            'denominator' => [['coefficient' => 1.0, 'slope' => 0.0, 'offset' => 0.0]],
        ];
    }

    /**
     * @param list<array{coefficient: float, slope: float, offset: float}> $left
     * @param list<array{coefficient: float, slope: float, offset: float}> $right
     * @return list<array{coefficient: float, slope: float, offset: float}>|null
     */
    private function multiplyExponentialTerms(array $left, array $right): ?array
    {
        if ($left === [] || $right === [] || \count($left) * \count($right) > 256) {
            return null;
        }
        $product = [];
        foreach ($left as $first) {
            foreach ($right as $second) {
                $term = [
                    'coefficient' => $first['coefficient'] * $second['coefficient'],
                    'slope' => $first['slope'] + $second['slope'],
                    'offset' => $first['offset'] + $second['offset'],
                ];
                if (
                    !\is_finite($term['coefficient'])
                    || !\is_finite($term['slope'])
                    || !\is_finite($term['offset'])
                ) {
                    return null;
                }
                $product[] = $term;
            }
        }

        return $product;
    }

    /**
     * Reduce exponential sums with integer multiples of a shared polynomial phase.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialPhaseExponentialEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $gammaAffineSolutions = $this->solveGammaAgainstAffineEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($gammaAffineSolutions !== null) {
            return $gammaAffineSolutions;
        }

        $sinhPowerSolutions = $this->solveSinhAgainstMatchedPower(
            $left,
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($sinhPowerSolutions !== null) {
            return $sinhPowerSolutions;
        }

        $coshPowerSolutions = $this->solveCoshAgainstMatchedPower(
            $left,
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($coshPowerSolutions !== null) {
            return $coshPowerSolutions;
        }

        $matchedCosecantSolutions = $this->solveCschNegativeExponentialEquation(
            $left,
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($matchedCosecantSolutions !== null) {
            return $matchedCosecantSolutions;
        }

        $leftNode = $this->unwrapGrouping($left);
        $rightNode = $this->unwrapGrouping($right);
        $hyperbolicFunctions = ['sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth'];
        if (
            $leftNode instanceof FunctionCallNode
            && \in_array($leftNode->name, $hyperbolicFunctions, true)
            && \count($leftNode->arguments) === 1
            && \count($extractor->extract($right) ?? []) === 1
        ) {
            return null;
        }
        if (
            $rightNode instanceof FunctionCallNode
            && \in_array($rightNode->name, $hyperbolicFunctions, true)
            && \count($rightNode->arguments) === 1
            && \count($extractor->extract($left) ?? []) === 1
        ) {
            return null;
        }

        $leftParts = $this->polynomialPhaseExponentialRatioParts(
            $left,
            $extractor,
            $options->maxPolynomialDegree,
        );
        $rightParts = $this->polynomialPhaseExponentialRatioParts(
            $right,
            $extractor,
            $options->maxPolynomialDegree,
        );
        if ($leftParts === null || $rightParts === null) {
            return null;
        }
        $leftTerms = $this->multiplyPolynomialPhaseExponentialTerms(
            $leftParts['numerator'],
            $rightParts['denominator'],
        );
        $rightTerms = $this->multiplyPolynomialPhaseExponentialTerms(
            $rightParts['numerator'],
            $leftParts['denominator'],
        );
        if ($leftTerms === null || $rightTerms === null) {
            return null;
        }
        foreach ($rightTerms as &$term) {
            $term['coefficient'] *= -1.0;
        }
        unset($term);
        $terms = [...$leftTerms, ...$rightTerms];
        $positiveExponentialBoundSolutions = $this->solvePositiveExponentialPolynomialLowerBound(
            $terms,
        );
        if ($positiveExponentialBoundSolutions !== null) {
            return $positiveExponentialBoundSolutions;
        }
        $twoTermSolutions = $this->solveTwoTermPolynomialPhaseExponentialEquation(
            $terms,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($twoTermSolutions !== null) {
            return $twoTermSolutions;
        }
        $variablePhaseTermCount = 0;
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            foreach ($term['phase'] as $degree => $coefficient) {
                if ($degree > 0 && $coefficient !== 0.0) {
                    ++$variablePhaseTermCount;
                    break;
                }
            }
        }
        if ($variablePhaseTermCount < 2) {
            return null;
        }
        $firstActivePhase = null;
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            foreach ($term['phase'] as $degree => $coefficient) {
                if ($degree > 0 && $coefficient !== 0.0) {
                    $firstActivePhase = $term['phase'];
                    break 2;
                }
            }
        }
        if ($firstActivePhase === null) {
            return null;
        }

        $pivot = null;
        foreach ($firstActivePhase as $degree => $coefficient) {
            if ($degree > 0 && $coefficient !== 0.0) {
                $pivot = $degree;
                break;
            }
        }
        if ($pivot === null) {
            return null;
        }

        $phaseCandidates = [];
        for ($divisor = 1; $divisor <= $options->maxPolynomialDegree; ++$divisor) {
            $phaseCandidates[] = [
                'base' => $firstActivePhase[$pivot] / $divisor,
                'divisor' => $divisor,
            ];
        }
        $basePhase = null;
        $frequencies = [];
        foreach ($phaseCandidates as $candidate) {
            $candidateBase = [];
            foreach ($firstActivePhase as $degree => $coefficient) {
                $candidateBase[$degree] = $coefficient / $candidate['divisor'];
            }
            $candidateValid = true;
            $candidateFrequencies = [];
            $minimumFrequency = \PHP_INT_MAX;
            $maximumFrequency = \PHP_INT_MIN;
            foreach ($terms as $index => $term) {
                $pivotCoefficient = $term['phase'][$pivot] ?? 0.0;
                $frequency = $pivotCoefficient / $candidate['base'];
                $nearest = \round($frequency);
                if (
                    !\is_finite($frequency)
                    || \abs($frequency - $nearest)
                        > 32.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($frequency))
                    || \abs($nearest) > $options->maxPolynomialDegree
                ) {
                    $candidateValid = false;
                    break;
                }
                $candidateFrequencies[$index] = (int) $nearest;
                if ($term['coefficient'] !== 0.0) {
                    $minimumFrequency = \min($minimumFrequency, (int) $nearest);
                    $maximumFrequency = \max($maximumFrequency, (int) $nearest);
                }
                $phaseLength = \max(\count($term['phase']), \count($candidateBase));
                $phaseScale = 0.0;
                for ($degree = 1; $degree < $phaseLength; ++$degree) {
                    $actual = $term['phase'][$degree] ?? 0.0;
                    $expected = $nearest * ($candidateBase[$degree] ?? 0.0);
                    if (!\is_finite($actual) || !\is_finite($expected)) {
                        $candidateValid = false;
                        break 2;
                    }
                    $phaseScale = \max($phaseScale, \abs($actual), \abs($expected));
                }
                $phaseTolerance = 32.0 * \PHP_FLOAT_EPSILON * \max(\PHP_FLOAT_MIN, $phaseScale);
                for ($degree = 1; $degree < $phaseLength; ++$degree) {
                    $actual = $term['phase'][$degree] ?? 0.0;
                    $expected = $nearest * ($candidateBase[$degree] ?? 0.0);
                    if (\abs($actual - $expected) > $phaseTolerance) {
                        $candidateValid = false;
                        break 2;
                    }
                }
            }
            if (
                $candidateValid
                && $minimumFrequency !== \PHP_INT_MAX
                && $maximumFrequency - $minimumFrequency <= $options->maxPolynomialDegree
            ) {
                $basePhase = $candidateBase;
                $frequencies = $candidateFrequencies;
                break;
            }
        }
        if ($basePhase === null) {
            return $this->solveIncommensuratePolynomialPhaseExponentialEquation(
                $terms,
                $firstActivePhase,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        $minimumFrequency = \PHP_INT_MAX;
        $maximumFrequency = \PHP_INT_MIN;
        foreach ($terms as $index => $term) {
            if ($term['coefficient'] !== 0.0) {
                $minimumFrequency = \min($minimumFrequency, $frequencies[$index]);
                $maximumFrequency = \max($maximumFrequency, $frequencies[$index]);
            }
        }
        $degree = $maximumFrequency - $minimumFrequency;
        if ($degree < 1 || $degree > $options->maxPolynomialDegree) {
            return null;
        }

        $coefficients = \array_fill(0, $degree + 1, 0.0);
        foreach ($terms as $index => $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            $constantFactor = \exp($term['offset']);
            $coefficient = $term['coefficient'] * $constantFactor;
            if (!\is_finite($coefficient) || ($coefficient === 0.0 && $term['coefficient'] !== 0.0)) {
                return null;
            }
            $position = $frequencies[$index] - $minimumFrequency;
            $coefficients[$position] += $coefficient;
            if (!\is_finite($coefficients[$position])) {
                return null;
            }
        }
        while ($coefficients !== [] && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        while (\count($coefficients) > 1 && $coefficients[0] === 0.0) {
            \array_shift($coefficients);
        }
        $coefficients = \array_values($coefficients);
        if ($coefficients === []) {
            return null;
        }
        if (\count($coefficients) === 1) {
            return $coefficients[0] === 0.0 ? null : [];
        }

        $basePhase = \array_values($basePhase);
        $phaseLength = \count($basePhase);
        while ($phaseLength > 1 && $basePhase[$phaseLength - 1] === 0.0) {
            \array_pop($basePhase);
            --$phaseLength;
        }
        $phaseSolver = new PolynomialSolver();
        $phaseValue = fn (float $value): ?float =>
            $phaseSolver->evaluatePolynomial($basePhase, $value);
        $rangeValues = [
            $phaseValue($lowerBound),
            $phaseValue($upperBound),
        ];
        if ($rangeValues[0] === null || $rangeValues[1] === null) {
            return null;
        }
        $derivative = [];
        for ($power = 1; $power < $phaseLength; ++$power) {
            $derivative[] = $power * $basePhase[$power];
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }
        if (\count($derivative) > 1) {
            $criticalPoints = $phaseSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $phaseSolver->evaluatePolynomial($derivative, $value),
                $options,
                fn (float $value): ?float =>
                    $phaseSolver->evaluatePolynomialMagnitude($derivative, $value),
            );
            if ($criticalPoints === null) {
                return null;
            }
            foreach ($criticalPoints as $criticalPoint) {
                $value = $phaseValue($criticalPoint->value);
                if ($value === null) {
                    return null;
                }
                $rangeValues[] = $value;
            }
        }
        foreach ($rangeValues as $value) {
            if (!\is_finite($value)) {
                return null;
            }
        }
        $firstBound = \exp(\min($rangeValues));
        $secondBound = \exp(\max($rangeValues));
        if (
            !\is_finite($firstBound)
            || !\is_finite($secondBound)
            || $firstBound <= 0.0
            || $secondBound < $firstBound
        ) {
            return null;
        }

        $exponentialRoots = $phaseSolver->solve(
            $coefficients,
            $firstBound,
            $secondBound,
            fn (float $value): ?float => $phaseSolver->evaluatePolynomial($coefficients, $value),
            $options,
            fn (float $value): ?float =>
                $phaseSolver->evaluatePolynomialMagnitude($coefficients, $value),
        );
        if ($exponentialRoots === null) {
            return null;
        }

        $solutions = [];
        foreach ($exponentialRoots as $exponentialRoot) {
            if ($exponentialRoot->value <= 0.0) {
                continue;
            }
            $levelCoefficients = $basePhase;
            $levelCoefficients[0] -= \log($exponentialRoot->value);
            $phaseRoots = $phaseSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float =>
                    $phaseSolver->evaluatePolynomial($levelCoefficients, $value),
                $options,
                fn (float $value): ?float =>
                    $phaseSolver->evaluatePolynomialMagnitude($levelCoefficients, $value),
            );
            if ($phaseRoots === null) {
                return null;
            }
            foreach ($phaseRoots as $phaseRoot) {
                $residual = $residualAt($phaseRoot->value);
                if ($residual === null) {
                    continue;
                }
                if (
                    !$this->isResidualAcceptableAt(
                        $phaseRoot->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($phaseRoot->value, \abs($residual), $phaseRoot->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /** @return list<list<int>> */
    private function boundedRootExponentTuples(int $dimensions, int $maxTotal): array
    {
        /** @var list<list<int>> $tuples */
        $tuples = [[]];
        for ($dimension = 0; $dimension < $dimensions; ++$dimension) {
            $next = [];
            foreach ($tuples as $prefix) {
                $remaining = $maxTotal - \array_sum($prefix);
                for ($exponent = 0; $exponent <= $remaining; ++$exponent) {
                    $next[] = [...$prefix, $exponent];
                }
            }
            $tuples = $next;
        }

        return $tuples;
    }

    /**
     * @param list<int> $degrees
     * @return list<list<int>>
     */
    private function completeRootBasisTuples(array $degrees): array
    {
        /** @var list<list<int>> $tuples */
        $tuples = [[]];
        foreach ($degrees as $degree) {
            $next = [];
            foreach ($tuples as $prefix) {
                for ($exponent = 0; $exponent < $degree; ++$exponent) {
                    $next[] = [...$prefix, $exponent];
                }
            }
            $tuples = $next;
        }

        return $tuples;
    }

    /**
     * Solve exponential sums whose polynomial phases are real multiples of one
     * shared phase, including incommensurate frequency ratios.
     *
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $terms
     * @param list<float> $basePhase
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveIncommensuratePolynomialPhaseExponentialEquation(
        array $terms,
        array $basePhase,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if ($lowerBound >= $upperBound) {
            return null;
        }
        $twoTermSolutions = $this->solveTwoTermPolynomialPhaseExponentialEquation(
            $terms,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($twoTermSolutions !== null) {
            return $twoTermSolutions;
        }
        $pivot = null;
        foreach ($basePhase as $degree => $coefficient) {
            if ($degree > 0 && $coefficient !== 0.0) {
                $pivot = $degree;
                break;
            }
        }
        if ($pivot === null) {
            return null;
        }

        $exponentialTerms = [];
        foreach ($terms as $term) {
            $frequency = ($term['phase'][$pivot] ?? 0.0) / $basePhase[$pivot];
            if (!\is_finite($frequency)) {
                return null;
            }
            $phaseLength = \max(\count($term['phase']), \count($basePhase));
            $phaseScale = 0.0;
            for ($degree = 1; $degree < $phaseLength; ++$degree) {
                $actual = $term['phase'][$degree] ?? 0.0;
                $expected = $frequency * ($basePhase[$degree] ?? 0.0);
                if (
                    !\is_finite($actual)
                    || !\is_finite($expected)
                ) {
                    return null;
                }
                $phaseScale = \max($phaseScale, \abs($actual), \abs($expected));
            }
            $phaseTolerance = 64.0 * \PHP_FLOAT_EPSILON * \max(\PHP_FLOAT_MIN, $phaseScale);
            for ($degree = 1; $degree < $phaseLength; ++$degree) {
                $actual = $term['phase'][$degree] ?? 0.0;
                $expected = $frequency * ($basePhase[$degree] ?? 0.0);
                if (\abs($actual - $expected) > $phaseTolerance) {
                    return null;
                }
            }
            $exponentialTerms[] = [
                'coefficient' => $term['coefficient'],
                'slope' => $frequency,
                'offset' => $term['offset'],
            ];
        }

        $polynomialSolver = new PolynomialSolver();
        $basePhase[0] = 0.0;
        while (\count($basePhase) > 1 && $basePhase[\array_key_last($basePhase)] === 0.0) {
            \array_pop($basePhase);
        }
        $phaseValue = fn (float $value): ?float =>
            $polynomialSolver->evaluatePolynomial($basePhase, $value);
        $phaseSearchLowerBound = $lowerBound;
        $phaseSearchUpperBound = $upperBound;
        $phaseRoots = null;
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $phaseRoots = (new ExponentialPolynomialSolver())->solve(
                $exponentialTerms,
                -\INF,
                \INF,
                $options,
            );
            if ($phaseRoots === null) {
                return null;
            }
            if ($phaseRoots === []) {
                return [];
            }
            $phaseLower = min($phaseRoots);
            $phaseUpper = max($phaseRoots);
            $inverseRootCoefficients = \array_map('\abs', $basePhase);
            $inverseRootCoefficients[0] = \max(\abs($phaseLower), \abs($phaseUpper));
            $inverseRootBound = $this->positivePolynomialRootBound($inverseRootCoefficients);
            if ($inverseRootBound === null) {
                return null;
            }
            $phaseSearchLowerBound = \max($lowerBound, -$inverseRootBound);
            $phaseSearchUpperBound = \min($upperBound, $inverseRootBound);
            if ($phaseSearchLowerBound > $phaseSearchUpperBound) {
                return [];
            }
        } else {
            $range = [$phaseValue($lowerBound), $phaseValue($upperBound)];
            if ($range[0] === null || $range[1] === null) {
                return null;
            }
            $derivative = [];
            for ($degree = 1; $degree < \count($basePhase); ++$degree) {
                $derivative[] = $degree * $basePhase[$degree];
            }
            while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
                \array_pop($derivative);
            }
            if (\count($derivative) > 1) {
                $criticalPoints = $polynomialSolver->solve(
                    $derivative,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($derivative, $value),
                    $options,
                    fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomialMagnitude($derivative, $value),
                );
                if ($criticalPoints === null) {
                    return null;
                }
                foreach ($criticalPoints as $criticalPoint) {
                    $value = $phaseValue($criticalPoint->value);
                    if ($value === null || !\is_finite($value)) {
                        return null;
                    }
                    $range[] = $value;
                }
            }
            foreach ($range as $value) {
                if (!\is_finite($value)) {
                    return null;
                }
            }
            $phaseLower = \min($range);
            $phaseUpper = \max($range);
        }
        if ($phaseLower > $phaseUpper) {
            return [];
        }
        $phaseRoots ??= (new ExponentialPolynomialSolver())->solve(
            $exponentialTerms,
            $phaseLower,
            $phaseUpper,
            $options,
        );
        if ($phaseRoots === null) {
            return null;
        }
        if ($phaseRoots === []) {
            return [];
        }

        $solutions = [];
        foreach ($phaseRoots as $phaseRoot) {
            $level = $basePhase;
            $level[0] -= $phaseRoot;
            $roots = $polynomialSolver->solve(
                $level,
                $phaseSearchLowerBound,
                $phaseSearchUpperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($level, $value),
                $options,
                fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomialMagnitude($level, $value),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if ($residual === null) {
                    continue;
                }
                if (!$this->isResidualAcceptableAt($root->value, $residual, $candidateScaleAt, $options)) {
                    return null;
                }
                $candidate = new EquationSolution($root->value, \abs($residual), $root->iterations);
                $duplicateIndex = null;
                foreach ($solutions as $index => $solution) {
                    if ($solution->value === $candidate->value) {
                        $duplicateIndex = $index;
                        break;
                    }
                }
                if ($duplicateIndex === null) {
                    $solutions[] = $candidate;
                } elseif (
                    $candidate->residual < $solutions[$duplicateIndex]->residual
                    || (
                        $candidate->residual === $solutions[$duplicateIndex]->residual
                        && $candidate->iterations < $solutions[$duplicateIndex]->iterations
                    )
                ) {
                    $solutions[$duplicateIndex] = $candidate;
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve a gamma function of an affine argument against an affine target.
     * Gamma's second derivative has its sign on each pole-free branch, so the
     * residual has at most one stationary point on each such branch.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveGammaAgainstAffineEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound) || $lowerBound === $upperBound) {
            return null;
        }
        foreach ([[$left, $right, 1.0], [$right, $left, -1.0]] as [$gammaSide, $targetSide, $orientation]) {
            $gammaNode = $this->unwrapGrouping($gammaSide);
            if (
                !$gammaNode instanceof FunctionCallNode
                || $gammaNode->name !== 'gamma'
                || \count($gammaNode->arguments) !== 1
            ) {
                continue;
            }
            $argument = $extractor->extract($gammaNode->arguments[0]);
            $target = $extractor->extract($targetSide);
            if (
                $argument === null
                || \count($argument) > 2
                || $target === null
                || \count($target) > 2
            ) {
                continue;
            }
            $offset = $argument[0] ?? 0.0;
            $slope = $argument[1] ?? 0.0;
            $targetOffset = $target[0] ?? 0.0;
            $targetSlope = $target[1] ?? 0.0;
            if ($slope === 0.0 || !\is_finite($slope)) {
                continue;
            }
            $argumentAtLower = $offset + ($slope * $lowerBound);
            $argumentAtUpper = $offset + ($slope * $upperBound);
            if (
                !\is_finite($argumentAtLower)
                || !\is_finite($argumentAtUpper)
                || \min(\abs($argumentAtLower), \abs($argumentAtUpper)) > 170.0
                || \max(\abs($argumentAtLower), \abs($argumentAtUpper)) > 170.0
            ) {
                continue;
            }

            $gammaAt = function (float $value) use (
                $gammaNode,
                $parameters,
                $variable,
                $evaluationOptions,
            ): ?float {
                try {
                    $result = (float) $this->evaluateNode(
                        $gammaNode,
                        [...$parameters, $variable => $value],
                        $evaluationOptions,
                    );
                } catch (EvaluationException $error) {
                    if ($this->mustPropagateEvaluationError($error)) {
                        throw $error;
                    }

                    return null;
                }

                return \is_finite($result) ? $result : null;
            };
            $derivativeAt = function (float $value) use (
                $gammaAt,
                $offset,
                $slope,
                $targetSlope,
                $orientation,
            ): ?float {
                $gammaValue = $gammaAt($value);
                if ($gammaValue === null) {
                    return null;
                }
                $argumentValue = $offset + ($slope * $value);
                try {
                    $derivative = $orientation * (
                        ($gammaValue * SpecialFunctions::digamma($argumentValue) * $slope)
                        - $targetSlope
                    );
                } catch (\DomainException) {
                    return null;
                }

                return \is_nan($derivative) ? null : $derivative;
            };
            $signOf = static fn (?float $value): ?int => $value === null || \is_nan($value)
                ? null
                : ($value < 0.0 ? -1 : ($value > 0.0 ? 1 : 0));
            $orientationSign = $orientation < 0.0 ? -1 : 1;
            $slopeSign = $slope < 0.0 ? -1 : 1;
            $minimumArgument = \min($argumentAtLower, $argumentAtUpper);
            $maximumArgument = \max($argumentAtLower, $argumentAtUpper);
            $firstPoleIndex = \max(0, (int) \ceil(-$maximumArgument));
            $lastPoleIndex = (int) \floor(-$minimumArgument);
            if ($lastPoleIndex - $firstPoleIndex > 4096) {
                return null;
            }

            $boundaries = [
                ['value' => $lowerBound, 'pole' => null],
                ['value' => $upperBound, 'pole' => null],
            ];
            for ($poleIndex = $firstPoleIndex; $poleIndex <= $lastPoleIndex; ++$poleIndex) {
                $polePosition = (-((float) $poleIndex) - $offset) / $slope;
                if (
                    \is_finite($polePosition)
                    && $polePosition >= $lowerBound
                    && $polePosition <= $upperBound
                ) {
                    $boundaries[] = ['value' => $polePosition, 'pole' => $poleIndex];
                }
            }
            \usort(
                $boundaries,
                static fn (array $first, array $second): int => $first['value'] <=> $second['value'],
            );
            $orderedBoundaries = [];
            foreach ($boundaries as $boundary) {
                $last = \array_key_last($orderedBoundaries);
                if ($last !== null && $orderedBoundaries[$last]['value'] === $boundary['value']) {
                    $orderedBoundaries[$last]['pole'] ??= $boundary['pole'];
                } else {
                    $orderedBoundaries[] = $boundary;
                }
            }

            $solutions = [];
            $addRoot = function (float $value) use (
                &$solutions,
                $residualAt,
                $candidateScaleAt,
                $options,
            ): bool {
                $residual = $residualAt($value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $options)
                ) {
                    return false;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($value, \abs($residual), 0),
                    $options,
                );

                return true;
            };
            $bisectSegment = function (
                float $segmentLower,
                float $segmentUpper,
                int $lowerSign,
                int $upperSign,
            ) use (&$solutions, $residualAt, $candidateScaleAt, $options): ?bool {
                if ($lowerSign === 0 || $upperSign === 0 || $lowerSign === $upperSign) {
                    return true;
                }
                for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
                    $midpoint = $segmentLower + (($segmentUpper - $segmentLower) / 2.0);
                    if ($midpoint === $segmentLower || $midpoint === $segmentUpper) {
                        break;
                    }
                    $residual = $residualAt($midpoint);
                    if ($residual === null) {
                        $leftProbe = $segmentLower + (($midpoint - $segmentLower) / 2.0);
                        $rightProbe = $midpoint + (($segmentUpper - $midpoint) / 2.0);
                        $leftResidual = $residualAt($leftProbe);
                        $rightResidual = $residualAt($rightProbe);
                        if ($leftResidual === null || $rightResidual === null) {
                            return null;
                        }
                        $leftSign = $leftResidual < 0.0 ? -1 : ($leftResidual > 0.0 ? 1 : 0);
                        $rightSign = $rightResidual < 0.0 ? -1 : ($rightResidual > 0.0 ? 1 : 0);
                        if ($leftSign === 0 || $rightSign === 0) {
                            $root = $leftSign === 0 ? $leftProbe : $rightProbe;
                            $solutions[] = new EquationSolution($root, 0.0, $iteration + 1);

                            return true;
                        }
                        if ($leftSign === $lowerSign) {
                            $segmentLower = $leftProbe;
                            $lowerSign = $leftSign;
                        } elseif ($rightSign === $upperSign) {
                            $segmentUpper = $rightProbe;
                            $upperSign = $rightSign;
                        } else {
                            return null;
                        }
                        continue;
                    }
                    if ($residual === 0.0) {
                        $solutions[] = new EquationSolution($midpoint, 0.0, $iteration + 1);

                        return true;
                    }
                    $midpointSign = $residual < 0.0 ? -1 : 1;
                    if ($midpointSign === $lowerSign) {
                        $segmentLower = $midpoint;
                    } else {
                        $segmentUpper = $midpoint;
                        $upperSign = $midpointSign;
                    }
                    if (
                        ($segmentUpper - $segmentLower)
                        <= $options->positionTolerance($segmentLower, $segmentUpper)
                    ) {
                        $candidate = $segmentLower + (($segmentUpper - $segmentLower) / 2.0);
                        $candidateResidual = $residualAt($candidate);
                        if (
                            $candidateResidual !== null
                            && $this->isResidualAcceptableAt(
                                $candidate,
                                $candidateResidual,
                                $candidateScaleAt,
                                $options,
                            )
                        ) {
                            $solutions[] = new EquationSolution($candidate, \abs($candidateResidual), $iteration + 1);

                            return true;
                        }
                    }
                }

                foreach ([$segmentLower, $segmentUpper] as $candidate) {
                    $candidateResidual = $residualAt($candidate);
                    if (
                        $candidateResidual !== null
                        && $this->isResidualAcceptableAt(
                            $candidate,
                            $candidateResidual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        $solutions[] = new EquationSolution($candidate, \abs($candidateResidual), $options->maxIterations);

                        return true;
                    }
                }

                return null;
            };

            for ($index = 0; $index < \count($orderedBoundaries) - 1; ++$index) {
                $lowerBoundary = $orderedBoundaries[$index];
                $upperBoundary = $orderedBoundaries[$index + 1];
                $segmentLower = $lowerBoundary['value'];
                $segmentUpper = $upperBoundary['value'];
                if ($segmentLower >= $segmentUpper) {
                    continue;
                }
                $midpoint = $segmentLower + (($segmentUpper - $segmentLower) / 2.0);
                $gammaMidpoint = $gammaAt($midpoint);
                if ($gammaMidpoint === null || $gammaMidpoint === 0.0) {
                    return null;
                }
                $curvatureSign = ($gammaMidpoint < 0.0 ? -1 : 1) * $orientationSign;
                $lowerPoleSign = $lowerBoundary['pole'] === null
                    ? null
                    : (($lowerBoundary['pole'] % 2 === 0 ? 1 : -1) * $slopeSign * $orientationSign);
                $upperPoleSign = $upperBoundary['pole'] === null
                    ? null
                    : (-($upperBoundary['pole'] % 2 === 0 ? 1 : -1) * $slopeSign * $orientationSign);
                $lowerResidual = $lowerBoundary['pole'] === null ? $residualAt($segmentLower) : null;
                $upperResidual = $upperBoundary['pole'] === null ? $residualAt($segmentUpper) : null;
                if (
                    ($lowerBoundary['pole'] === null && $lowerResidual === null)
                    || ($upperBoundary['pole'] === null && $upperResidual === null)
                ) {
                    return null;
                }
                $lowerFunctionSign = $lowerPoleSign ?? $signOf($lowerResidual);
                $upperFunctionSign = $upperPoleSign ?? $signOf($upperResidual);
                if ($lowerFunctionSign === null || $upperFunctionSign === null) {
                    return null;
                }
                if ($lowerBoundary['pole'] === null && $lowerResidual !== null && $addRoot($segmentLower)) {
                    $lowerFunctionSign = 0;
                }
                if ($upperBoundary['pole'] === null && $upperResidual !== null && $addRoot($segmentUpper)) {
                    $upperFunctionSign = 0;
                }

                $lowerDerivative = $lowerBoundary['pole'] === null
                    ? $derivativeAt($segmentLower)
                    : (float) (-($lowerBoundary['pole'] % 2 === 0 ? 1 : -1) * $slopeSign * $orientationSign);
                $upperDerivative = $upperBoundary['pole'] === null
                    ? $derivativeAt($segmentUpper)
                    : (float) (-($upperBoundary['pole'] % 2 === 0 ? 1 : -1) * $slopeSign * $orientationSign);
                $lowerDerivativeSign = $signOf($lowerDerivative);
                $upperDerivativeSign = $signOf($upperDerivative);
                if ($lowerDerivativeSign === null || $upperDerivativeSign === null) {
                    return null;
                }
                $hasInteriorCriticalPoint = ($curvatureSign > 0
                        && $lowerDerivativeSign < 0
                        && $upperDerivativeSign > 0)
                    || ($curvatureSign < 0
                        && $lowerDerivativeSign > 0
                        && $upperDerivativeSign < 0);
                $criticalPoint = null;
                $criticalSign = null;
                if ($hasInteriorCriticalPoint) {
                    $criticalLower = $segmentLower;
                    $criticalUpper = $segmentUpper;
                    $criticalLowerSign = $lowerDerivativeSign;
                    for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
                        $criticalMidpoint = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                        if ($criticalMidpoint === $criticalLower || $criticalMidpoint === $criticalUpper) {
                            break;
                        }
                        $derivative = $derivativeAt($criticalMidpoint);
                        $derivativeSign = $signOf($derivative);
                        if ($derivativeSign === null) {
                            return null;
                        }
                        if ($derivativeSign === 0) {
                            $criticalLower = $criticalMidpoint;
                            $criticalUpper = $criticalMidpoint;
                            break;
                        }
                        if ($derivativeSign === $criticalLowerSign) {
                            $criticalLower = $criticalMidpoint;
                        } else {
                            $criticalUpper = $criticalMidpoint;
                        }
                        if (
                            ($criticalUpper - $criticalLower)
                            <= $options->positionTolerance($criticalLower, $criticalUpper)
                        ) {
                            break;
                        }
                    }
                    $criticalPoint = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                    $criticalResidual = $residualAt($criticalPoint);
                    if ($criticalResidual === null) {
                        return null;
                    }
                    $criticalSign = $criticalResidual < 0.0 ? -1 : ($criticalResidual > 0.0 ? 1 : 0);
                    if ($criticalSign !== 0 && $addRoot($criticalPoint)) {
                        $criticalSign = 0;
                    }
                }

                if ($criticalPoint === null) {
                    $result = $bisectSegment(
                        $segmentLower,
                        $segmentUpper,
                        $lowerFunctionSign,
                        $upperFunctionSign,
                    );
                    if ($result === null) {
                        return null;
                    }
                    continue;
                }
                $leftResult = $bisectSegment(
                    $segmentLower,
                    $criticalPoint,
                    $lowerFunctionSign,
                    $criticalSign,
                );
                $rightResult = $bisectSegment(
                    $criticalPoint,
                    $segmentUpper,
                    $criticalSign,
                    $upperFunctionSign,
                );
                if ($leftResult === null || $rightResult === null) {
                    return null;
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * Solve sinh(a*x) = c*(a*x)^n through the monotonic branches of its ratio.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSinhAgainstMatchedPower(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$sinhNode, $polynomialNode]) {
            $sinhNode = $this->unwrapGrouping($sinhNode);
            if (
                !$sinhNode instanceof FunctionCallNode
                || $sinhNode->name !== 'sinh'
                || \count($sinhNode->arguments) !== 1
            ) {
                continue;
            }
            $argument = $extractor->extract($sinhNode->arguments[0]);
            $polynomial = $extractor->extract($polynomialNode);
            if (
                $argument === null
                || \count($argument) !== 2
                || ($argument[0] ?? 0.0) !== 0.0
                || ($argument[1] ?? 0.0) === 0.0
                || $polynomial === null
            ) {
                continue;
            }
            while ($polynomial !== [] && $polynomial[\array_key_last($polynomial)] === 0.0) {
                \array_pop($polynomial);
            }
            $degree = \count($polynomial) - 1;
            if ($degree < 1 || $degree > $options->maxPolynomialDegree) {
                continue;
            }
            for ($power = 0; $power < $degree; ++$power) {
                if (($polynomial[$power] ?? 0.0) !== 0.0) {
                    continue 2;
                }
            }
            $slope = $argument[1];
            $slopePower = \pow($slope, $degree);
            if ($slopePower === 0.0 || !\is_finite($slopePower)) {
                continue;
            }
            $coefficient = $polynomial[$degree] / $slopePower;
            if (!\is_finite($coefficient)) {
                continue;
            }
            $solutions = [];
            if ($lowerBound <= 0.0 && $upperBound >= 0.0) {
                $residual = $residualAt(0.0);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(0.0, $residual, $candidateScaleAt, $options)
                ) {
                    return null;
                }
                $solutions[] = new EquationSolution(0.0, \abs($residual), 0);
            }
            if ($coefficient === 0.0) {
                return $solutions;
            }
            if (($degree % 2) === 1 && $coefficient < 0.0) {
                return $solutions;
            }

            $absoluteCoefficient = \abs($coefficient);
            $coefficientLevel = \log($absoluteCoefficient);
            if ($degree === 1) {
                if ($coefficient <= 1.0) {
                    return $solutions;
                }
                $critical = 0.0;
            } else {
                $criticalLower = 0.0;
                $criticalUpper = (float) $degree;
                for ($iteration = 0; $iteration < 128; ++$iteration) {
                    $midpoint = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                    if ($midpoint === $criticalLower || $midpoint === $criticalUpper) {
                        break;
                    }
                    if ($midpoint - ($degree * \tanh($midpoint)) < 0.0) {
                        $criticalLower = $midpoint;
                    } else {
                        $criticalUpper = $midpoint;
                    }
                }
                $critical = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                $minimumLevel = $this->logSinhPositive($critical)
                    - ($degree * \log($critical));
                $comparison = $coefficientLevel - $minimumLevel;
                $tangentTolerance = 128.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($coefficientLevel), \abs($minimumLevel));
                if ($comparison < -$tangentTolerance) {
                    return $solutions;
                }
                if ($comparison <= $tangentTolerance) {
                    return null;
                }
            }

            $ratioLog = fn (float $value): float =>
                $this->logSinhPositive($value) - ($degree * \log($value)) - $coefficientLevel;
            $positiveRoots = [];
            if ($degree === 1) {
                $leftLower = 0.0;
                $leftUpper = 1.0;
                for ($expansion = 0; $expansion < 1024 && $ratioLog($leftUpper) < 0.0; ++$expansion) {
                    $leftUpper *= 2.0;
                    if (!\is_finite($leftUpper)) {
                        return null;
                    }
                }
                if ($ratioLog($leftUpper) < 0.0) {
                    return null;
                }
            } else {
                $leftLower = 0.0;
                $leftUpper = $critical;
                for ($iteration = 0; $iteration < 128; ++$iteration) {
                    $midpoint = $leftLower + (($leftUpper - $leftLower) / 2.0);
                    if ($midpoint === $leftLower || $midpoint === $leftUpper) {
                        break;
                    }
                    if ($ratioLog($midpoint) > 0.0) {
                        $leftLower = $midpoint;
                    } else {
                        $leftUpper = $midpoint;
                    }
                }
            }
            $positiveRoots[] = $leftLower + (($leftUpper - $leftLower) / 2.0);

            if ($degree > 1) {
                $rightLower = $critical;
                $rightUpper = \max(2.0 * $critical, $critical + 1.0);
                for ($expansion = 0; $expansion < 1024 && $ratioLog($rightUpper) < 0.0; ++$expansion) {
                    $rightUpper *= 2.0;
                    if (!\is_finite($rightUpper)) {
                        return null;
                    }
                }
                if ($ratioLog($rightUpper) <= 0.0) {
                    return null;
                }
                for ($iteration = 0; $iteration < 128; ++$iteration) {
                    $midpoint = $rightLower + (($rightUpper - $rightLower) / 2.0);
                    if ($midpoint === $rightLower || $midpoint === $rightUpper) {
                        break;
                    }
                    if ($ratioLog($midpoint) < 0.0) {
                        $rightLower = $midpoint;
                    } else {
                        $rightUpper = $midpoint;
                    }
                }
                $positiveRoots[] = $rightLower + (($rightUpper - $rightLower) / 2.0);
            }

            $nonzeroSigns = ($degree % 2) === 1
                ? [1.0, -1.0]
                : [$coefficient > 0.0 ? 1.0 : -1.0];
            foreach ($positiveRoots as $positiveRoot) {
                foreach ($nonzeroSigns as $sign) {
                    $value = ($sign * $positiveRoot) / $slope;
                    if ($value < $lowerBound || $value > $upperBound || !\is_finite($value)) {
                        continue;
                    }
                    $residual = $residualAt($value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $options)
                    ) {
                        return null;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($value, \abs($residual), 0),
                        $options,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function logSinhPositive(float $value): float
    {
        if ($value < 20.0) {
            return \log(\sinh($value));
        }

        return $value + \log1p(-\exp(-2.0 * $value)) - \log(2.0);
    }

    /**
     * Solve cosh(a*x) = c*(a*x)^n by isolating its unique positive minimum.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveCoshAgainstMatchedPower(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$coshNode, $polynomialNode]) {
            $coshNode = $this->unwrapGrouping($coshNode);
            if (
                !$coshNode instanceof FunctionCallNode
                || $coshNode->name !== 'cosh'
                || \count($coshNode->arguments) !== 1
            ) {
                continue;
            }
            $argument = $extractor->extract($coshNode->arguments[0]);
            $polynomial = $extractor->extract($polynomialNode);
            if (
                $argument === null
                || \count($argument) !== 2
                || ($argument[0] ?? 0.0) !== 0.0
                || ($argument[1] ?? 0.0) === 0.0
                || $polynomial === null
            ) {
                continue;
            }
            while ($polynomial !== [] && $polynomial[\array_key_last($polynomial)] === 0.0) {
                \array_pop($polynomial);
            }
            $degree = \count($polynomial) - 1;
            if ($degree < 1 || $degree > $options->maxPolynomialDegree) {
                continue;
            }
            for ($power = 0; $power < $degree; ++$power) {
                if (($polynomial[$power] ?? 0.0) !== 0.0) {
                    continue 2;
                }
            }
            $slope = $argument[1];
            $slopePower = \pow($slope, $degree);
            if ($slopePower === 0.0 || !\is_finite($slopePower)) {
                continue;
            }
            $polynomialCoefficient = $polynomial[$degree];
            $coefficient = $polynomialCoefficient / $slopePower;
            if (!\is_finite($coefficient)) {
                continue;
            }
            if ($coefficient === 0.0) {
                return $polynomialCoefficient === 0.0 ? [] : null;
            }
            if ($coefficient < 0.0) {
                return [];
            }

            $criticalLower = 0.0;
            $criticalUpper = \max(1.0, (float) $degree + 1.0);
            for ($expansion = 0; $expansion < 1024; ++$expansion) {
                if (($criticalUpper * \tanh($criticalUpper)) >= $degree) {
                    break;
                }
                $criticalUpper *= 2.0;
                if (!\is_finite($criticalUpper)) {
                    return null;
                }
            }
            if (($criticalUpper * \tanh($criticalUpper)) < $degree) {
                return null;
            }
            for ($iteration = 0; $iteration < 128; ++$iteration) {
                $midpoint = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                if ($midpoint === $criticalLower || $midpoint === $criticalUpper) {
                    break;
                }
                if (($midpoint * \tanh($midpoint)) < $degree) {
                    $criticalLower = $midpoint;
                } else {
                    $criticalUpper = $midpoint;
                }
            }
            $critical = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
            $logCoshAtCritical = $this->logCoshValue($critical);
            $minimumLevel = $logCoshAtCritical - \log($coefficient) - ($degree * \log($critical));
            $tangentTolerance = 128.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($logCoshAtCritical), \abs(\log($coefficient)));
            if ($minimumLevel > $tangentTolerance) {
                return [];
            }
            if ($minimumLevel >= -$tangentTolerance) {
                return null;
            }

            $positiveRoots = [];
            $leftLower = 0.0;
            $leftUpper = $critical;
            for ($iteration = 0; $iteration < 128; ++$iteration) {
                $midpoint = $leftLower + (($leftUpper - $leftLower) / 2.0);
                if ($midpoint === $leftLower || $midpoint === $leftUpper) {
                    break;
                }
                if ($this->coshPowerLogDifference($midpoint, $coefficient, $degree) > 0.0) {
                    $leftLower = $midpoint;
                } else {
                    $leftUpper = $midpoint;
                }
            }
            $positiveRoots[] = $leftLower + (($leftUpper - $leftLower) / 2.0);

            $rightLower = $critical;
            $rightUpper = \max(2.0 * $critical, $critical + 1.0);
            for ($expansion = 0; $expansion < 1024; ++$expansion) {
                if ($this->coshPowerLogDifference($rightUpper, $coefficient, $degree) > 0.0) {
                    break;
                }
                $rightUpper *= 2.0;
                if (!\is_finite($rightUpper)) {
                    return null;
                }
            }
            if ($this->coshPowerLogDifference($rightUpper, $coefficient, $degree) <= 0.0) {
                return null;
            }
            for ($iteration = 0; $iteration < 128; ++$iteration) {
                $midpoint = $rightLower + (($rightUpper - $rightLower) / 2.0);
                if ($midpoint === $rightLower || $midpoint === $rightUpper) {
                    break;
                }
                if ($this->coshPowerLogDifference($midpoint, $coefficient, $degree) < 0.0) {
                    $rightLower = $midpoint;
                } else {
                    $rightUpper = $midpoint;
                }
            }
            $positiveRoots[] = $rightLower + (($rightUpper - $rightLower) / 2.0);

            $solutions = [];
            $rootSigns = ($degree % 2) === 0 ? [-1.0, 1.0] : [1.0];
            foreach ($positiveRoots as $positiveRoot) {
                foreach ($rootSigns as $sign) {
                    $value = ($sign * $positiveRoot) / $slope;
                    if ($value < $lowerBound || $value > $upperBound || !\is_finite($value)) {
                        continue;
                    }
                    $residual = $residualAt($value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $options)
                    ) {
                        return null;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($value, \abs($residual), 0),
                        $options,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function logCoshValue(float $value): float
    {
        $absolute = \abs($value);

        return $absolute + \log1p(\exp(-2.0 * $absolute)) - \log(2.0);
    }

    private function coshPowerLogDifference(float $value, float $coefficient, int $degree): float
    {
        if ($value === 0.0) {
            return \INF;
        }

        return $this->logCoshValue($value) - \log($coefficient) - ($degree * \log($value));
    }

    /**
     * Reduce csch(P(x)) = C exp(-P(x)) to one polynomial level equation.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveCschNegativeExponentialEquation(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$cschNode, $exponentialNode]) {
            $cschNode = $this->unwrapGrouping($cschNode);
            if (
                !$cschNode instanceof FunctionCallNode
                || $cschNode->name !== 'csch'
                || \count($cschNode->arguments) !== 1
            ) {
                continue;
            }
            $argument = $extractor->extract($cschNode->arguments[0]);
            if ($argument === null) {
                continue;
            }

            $exponentialNode = $this->unwrapGrouping($exponentialNode);
            $coefficient = 1.0;
            $exponential = null;
            if ($exponentialNode instanceof FunctionCallNode && $exponentialNode->name === 'exp') {
                $exponential = $exponentialNode;
            } elseif (
                $exponentialNode instanceof BinaryOperationNode
                && $exponentialNode->operator === BinaryOperator::Multiply
            ) {
                foreach (
                    [[$exponentialNode->left, $exponentialNode->right], [$exponentialNode->right, $exponentialNode->left]]
                    as [$factor, $coefficientNode]
                ) {
                    $factor = $this->unwrapGrouping($factor);
                    if (!$factor instanceof FunctionCallNode || $factor->name !== 'exp') {
                        continue;
                    }
                    $constant = $extractor->extract($coefficientNode);
                    if ($constant === null || \count($constant) !== 1 || !\is_finite($constant[0])) {
                        continue;
                    }
                    $coefficient = $constant[0];
                    $exponential = $factor;
                    break;
                }
            }
            if (
                !$exponential instanceof FunctionCallNode
                || \count($exponential->arguments) !== 1
                || !\is_finite($coefficient)
            ) {
                continue;
            }
            $exponentialArgument = $extractor->extract($exponential->arguments[0]);
            if ($exponentialArgument === null) {
                continue;
            }
            $length = \max(\count($argument), \count($exponentialArgument));
            $matchesNegativeArgument = true;
            for ($degree = 0; $degree < $length; ++$degree) {
                $expected = -($argument[$degree] ?? 0.0);
                $actual = $exponentialArgument[$degree] ?? 0.0;
                $tolerance = 32.0 * \PHP_FLOAT_EPSILON
                    * \max(\abs($expected), \abs($actual), \PHP_FLOAT_MIN);
                if (\abs($actual - $expected) > $tolerance) {
                    $matchesNegativeArgument = false;
                    break;
                }
            }
            if (!$matchesNegativeArgument) {
                continue;
            }

            if ($coefficient === 0.0 || ($coefficient > 0.0 && $coefficient <= 2.0)) {
                return [];
            }
            $levelRatio = $coefficient / ($coefficient - 2.0);
            if (!\is_finite($levelRatio) || $levelRatio <= 0.0) {
                return [];
            }
            $level = 0.5 * \log($levelRatio);
            $levelEquation = $argument;
            $levelEquation[0] = ($levelEquation[0] ?? 0.0) - $level;
            $polynomialSolver = new PolynomialSolver();
            $roots = $polynomialSolver->solve(
                $levelEquation,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($levelEquation, $value),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude($levelEquation, $value),
            );
            if ($roots === null) {
                return null;
            }

            $solutions = [];
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if ($residual === null) {
                    return null;
                }
                if (
                    !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $solutions[] = new EquationSolution($root->value, \abs($residual), $root->iterations);
            }

            return $solutions;
        }

        return null;
    }

    /**
     * Reduce a two-term exponential equation with unrelated polynomial phases
     * to one polynomial level equation when the exponential coefficients oppose.
     *
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $terms
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveTwoTermPolynomialPhaseExponentialEquation(
        array $terms,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return null;
        }

        $terms = \array_values(\array_filter(
            $terms,
            static fn (array $term): bool => $term['coefficient'] !== 0.0,
        ));
        if (\count($terms) !== 2) {
            return null;
        }
        [$first, $second] = $terms;
        if (($first['coefficient'] > 0.0) === ($second['coefficient'] > 0.0)) {
            return [];
        }

        $length = \max(\count($first['phase']), \count($second['phase']));
        $level = [];
        for ($degree = 0; $degree < $length; ++$degree) {
            $level[$degree] = ($first['phase'][$degree] ?? 0.0) - ($second['phase'][$degree] ?? 0.0);
        }
        if (\count($level) < 2) {
            return null;
        }
        $target = \log(\abs($second['coefficient']))
            - \log(\abs($first['coefficient']))
            + $second['offset']
            - $first['offset'];
        if (!\is_finite($target)) {
            return null;
        }
        $level[0] -= $target;
        while (\count($level) > 1 && $level[\array_key_last($level)] === 0.0) {
            \array_pop($level);
        }
        if (\count($level) < 2) {
            return null;
        }

        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $rootBound = $this->positivePolynomialRootBound(\array_map('\\abs', $level));
            if ($rootBound === null) {
                return null;
            }
            $searchLowerBound = \max($lowerBound, -$rootBound);
            $searchUpperBound = \min($upperBound, $rootBound);
            if ($searchLowerBound > $searchUpperBound) {
                return [];
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $roots = $polynomialSolver->solve(
            $level,
            $searchLowerBound,
            $searchUpperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($level, $value),
            $options,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude($level, $value),
        );
        if ($roots === null) {
            return null;
        }

        $solutions = [];
        foreach ($roots as $root) {
            $residual = $residualAt($root->value);
            $originalScale = $candidateScaleAt($root->value);
            $termScale = $this->exponentialPhaseTermScaleAt($terms, $root->value);
            if ($residual === null) {
                continue;
            }
            if (
                $originalScale === null
                || $termScale === null
                || !$this->isResidualAcceptableAt(
                    $root->value,
                    $residual,
                    static fn (float $value): float => \max($originalScale, $termScale),
                    $options,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root->value, \abs($residual), $root->iterations),
                $options,
            );
        }

        return $solutions;
    }

    /**
     * Prove that a positive exponential sum stays above constant negative terms.
     *
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $terms
     * @return list<EquationSolution>|null
     */
    private function solvePositiveExponentialPolynomialLowerBound(array $terms): ?array
    {
        $positiveTerms = [];
        $negativeLogMagnitudes = [];
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            $isConstantPhase = true;
            foreach ($term['phase'] as $degree => $coefficient) {
                if ($degree > 0 && $coefficient !== 0.0) {
                    $isConstantPhase = false;
                    break;
                }
            }
            if ($term['coefficient'] > 0.0) {
                $positiveTerms[] = $term;
                continue;
            }
            if (!$isConstantPhase) {
                return null;
            }
            $negativeLogMagnitudes[] = \log(-$term['coefficient'])
                + $term['offset']
                + ($term['phase'][0] ?? 0.0);
        }
        if ($positiveTerms === [] || $negativeLogMagnitudes === []) {
            return null;
        }

        $maximumNegativeLog = \max($negativeLogMagnitudes);
        $scaledNegativeSum = 0.0;
        foreach ($negativeLogMagnitudes as $logMagnitude) {
            $scaledNegativeSum += \exp($logMagnitude - $maximumNegativeLog);
        }
        $negativeLogSum = $maximumNegativeLog + \log($scaledNegativeSum);

        $positiveLogLowerBounds = [];
        $quadraticLowerBoundTerms = [];
        foreach ($positiveTerms as $term) {
            $phase = $term['phase'];
            $hasVariablePhase = false;
            for ($degree = 1; $degree < \count($phase); ++$degree) {
                if ($phase[$degree] !== 0.0) {
                    $hasVariablePhase = true;
                    break;
                }
            }
            if (!$hasVariablePhase) {
                $logWeight = \log($term['coefficient'])
                    + $term['offset']
                    + ($phase[0] ?? 0.0);
                $positiveLogLowerBounds[] = $logWeight;
                $quadraticLowerBoundTerms[] = [
                    'logWeight' => $logWeight,
                    'quadratic' => 0.0,
                    'residualPower' => 0,
                    'residualCoefficient' => 0.0,
                    'vertex' => 0.0,
                ];
                continue;
            }
            $lastDegree = \count($phase) - 1;
            while ($lastDegree > 0 && ($phase[$lastDegree] ?? 0.0) === 0.0) {
                --$lastDegree;
            }
            if ($lastDegree >= 4 && ($lastDegree % 2) === 0 && $phase[$lastDegree] > 0.0) {
                $power = $lastDegree;
                $monomialCoefficient = $phase[$power];
                $vertex = -($phase[$power - 1] / ($power * $monomialCoefficient));
                $monomialShape = \is_finite($vertex);
                $monomialShapeExact = $monomialShape;
                $binomial = 1.0;
                for ($degree = 0; $degree <= $power && $monomialShape; ++$degree) {
                    if ($degree > 0 && $degree < $power) {
                        $expected = $monomialCoefficient * $binomial
                            * \pow(-$vertex, $power - $degree);
                        $actual = $phase[$degree] ?? 0.0;
                        $shapeTolerance = 64.0 * \PHP_FLOAT_EPSILON
                            * \max(1.0, \abs($actual), \abs($expected));
                        if (!\is_finite($expected) || \abs($actual - $expected) > $shapeTolerance) {
                            $monomialShape = false;
                        }
                        if ($actual !== $expected) {
                            $monomialShapeExact = false;
                        }
                    }
                    if ($degree < $power) {
                        $binomial *= ($power - $degree) / ($degree + 1);
                    }
                }
                if ($monomialShape) {
                    $monomialDrop = $monomialCoefficient * \pow($vertex, $power);
                    $minimum = ($phase[0] ?? 0.0) + $term['offset'] - $monomialDrop;
                    $phaseEvaluationScale = \abs($term['offset']);
                    $vertexPower = 1.0;
                    for ($degree = 0; $degree < $power; ++$degree) {
                        $phaseEvaluationScale += \abs(($phase[$degree] ?? 0.0) * $vertexPower);
                        $vertexPower *= \abs($vertex);
                    }
                    $roundoff = 64.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, $phaseEvaluationScale, \abs($monomialDrop));
                    $exactLogWeight = \log($term['coefficient']) + $minimum;
                    $logWeight = $exactLogWeight - $roundoff;
                    if (\is_finite($logWeight)) {
                        $positiveLogLowerBounds[] = $logWeight;
                        $quadraticLowerBoundTerms[] = [
                            'logWeight' => $logWeight,
                            'quadratic' => 0.0,
                            'residualPower' => $power,
                            'residualCoefficient' => $monomialCoefficient,
                            'vertex' => $vertex,
                        ];
                    }

                    if (
                        $monomialShapeExact
                        &&
                        $minimum === 0.0
                        && $term['coefficient'] === 1.0
                        && $exactLogWeight === $negativeLogSum
                        && \count($positiveTerms) > 1
                    ) {
                        return [];
                    }
                } elseif ($lastDegree === 4) {
                    $quartic = $phase[4];
                    $cubicCorrection = ($phase[3] * $phase[3]) / (4.0 * $quartic);
                    $quadraticRoundoff = 32.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($phase[2] ?? 0.0), \abs($cubicCorrection));
                    $quadratic = ($phase[2] ?? 0.0) - $cubicCorrection - $quadraticRoundoff;
                    if (\is_finite($quadratic) && $quadratic > 0.0) {
                        $linear = $phase[1] ?? 0.0;
                        $totalConstant = ($phase[0] ?? 0.0) + $term['offset'];
                        $curvatureDrop = ($linear * $linear) / (4.0 * $quadratic);
                        $minimum = $totalConstant - $curvatureDrop;
                        $minimumRoundoff = 32.0 * \PHP_FLOAT_EPSILON
                            * \max(1.0, \abs($totalConstant), \abs($curvatureDrop));
                        $logWeight = \log($term['coefficient']) + $minimum - $minimumRoundoff;
                        $vertex = -$linear / (2.0 * $quadratic);
                        if (\is_finite($logWeight) && \is_finite($vertex)) {
                            $positiveLogLowerBounds[] = $logWeight;
                            $quadraticLowerBoundTerms[] = [
                                'logWeight' => $logWeight,
                                'quadratic' => $quadratic,
                                'residualPower' => 0,
                                'residualCoefficient' => 0.0,
                                'vertex' => $vertex,
                            ];
                        }
                    }
                }
                continue;
            }
            for ($degree = 3; $degree < \count($phase); ++$degree) {
                if ($phase[$degree] !== 0.0) {
                    continue 2;
                }
            }
            $quadratic = $phase[2] ?? 0.0;
            if (!\is_finite($quadratic) || $quadratic <= 0.0) {
                continue;
            }
            $linear = $phase[1] ?? 0.0;
            $constant = $phase[0] ?? 0.0;
            $totalConstant = $constant + $term['offset'];
            $curvatureDrop = ($linear * $linear) / (4.0 * $quadratic);
            $minimum = $totalConstant - $curvatureDrop;
            $exactPositiveLogLowerBound = \log($term['coefficient']) + $minimum;
            $minimumRoundoff = 16.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($totalConstant), \abs($curvatureDrop));
            $positiveLogLowerBound = $exactPositiveLogLowerBound - $minimumRoundoff;
            if (
                !\is_finite($positiveLogLowerBound)
                || !\is_finite($exactPositiveLogLowerBound)
                || !\is_finite($minimumRoundoff)
            ) {
                continue;
            }
            $positiveLogLowerBounds[] = $positiveLogLowerBound;
            $vertex = -$linear / (2.0 * $quadratic);
            if (\is_finite($vertex)) {
                $quadraticLowerBoundTerms[] = [
                    'logWeight' => $positiveLogLowerBound,
                    'quadratic' => $quadratic,
                    'residualPower' => 0,
                    'residualCoefficient' => 0.0,
                    'vertex' => $vertex,
                ];
            }

            $fourAc = 4.0 * $quadratic * $totalConstant;
            $linearSquared = $linear * $linear;
            $exactPerfectSquare = \is_finite($fourAc)
                && \is_finite($linearSquared)
                && $fourAc === $linearSquared
                && $minimum === 0.0
                && $term['coefficient'] === 1.0;
            if (
                $exactPerfectSquare
                && $exactPositiveLogLowerBound === $negativeLogSum
                && \count($positiveTerms) > 1
            ) {
                return [];
            }
        }

        if ($positiveLogLowerBounds !== []) {
            $maximumPositiveLog = \max($positiveLogLowerBounds);
            $scaledPositiveSum = 0.0;
            foreach ($positiveLogLowerBounds as $logMagnitude) {
                $scaledPositiveSum += \exp($logMagnitude - $maximumPositiveLog);
            }
            $positiveLogSum = $maximumPositiveLog + \log($scaledPositiveSum);
            $margin = 64.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($positiveLogSum), \abs($negativeLogSum));
            if ($positiveLogSum > $negativeLogSum + $margin) {
                return [];
            }
        }
        if (
            $this->positiveExponentialTaylorBoundExceedsNegative(
                $quadraticLowerBoundTerms,
                $negativeLogMagnitudes,
            )
        ) {
            return [];
        }

        return null;
    }

    /**
     * @param list<array{
     *     logWeight: float,
     *     quadratic: float,
     *     residualPower: int,
     *     residualCoefficient: float,
     *     vertex: float,
     * }> $positiveTerms
     * @param list<float> $negativeLogMagnitudes
     */
    private function positiveExponentialTaylorBoundExceedsNegative(
        array $positiveTerms,
        array $negativeLogMagnitudes,
    ): bool {
        if ($positiveTerms === [] || $negativeLogMagnitudes === []) {
            return false;
        }
        $scaleLogs = [...$negativeLogMagnitudes];
        foreach ($positiveTerms as $term) {
            if (!\is_finite($term['logWeight'])) {
                return false;
            }
            $scaleLogs[] = $term['logWeight'];
        }
        $normalizer = \max($scaleLogs);
        $negativeMass = 0.0;
        foreach ($negativeLogMagnitudes as $logMagnitude) {
            $negativeMass += \exp($logMagnitude - $normalizer);
        }

        $quadratic = 0.0;
        $linear = 0.0;
        $constant = 0.0;
        $powerTerms = [];
        foreach ($positiveTerms as $term) {
            $weight = \exp($term['logWeight'] - $normalizer);
            $curvature = $term['quadratic'];
            $vertex = $term['vertex'];
            if ($curvature === 0.0) {
                $constant += $weight;
                if ($term['residualPower'] >= 4 && $term['residualCoefficient'] > 0.0) {
                    $powerTerms[$term['residualPower']][] = [
                        'weight' => $weight * $term['residualCoefficient'],
                        'vertex' => $vertex,
                    ];
                }
                continue;
            }
            $weightedCurvature = $weight * $curvature;
            $vertexSquare = $vertex * $vertex;
            $quadratic += $weightedCurvature;
            $linear -= 2.0 * $weightedCurvature * $vertex;
            $constant += $weight + ($weightedCurvature * $vertexSquare);
            if (
                !\is_finite($quadratic)
                || !\is_finite($linear)
                || !\is_finite($constant)
            ) {
                return false;
            }
        }
        $curvatureDrop = $quadratic === 0.0
            ? 0.0
            : ($linear * $linear) / (4.0 * $quadratic);
        $lowerBound = $constant - $curvatureDrop;
        if (!\is_finite($lowerBound) || !\is_finite($curvatureDrop)) {
            return false;
        }
        $lowerBound -= 64.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($constant), \abs($curvatureDrop));

        foreach ($powerTerms as $power => $terms) {
            if (\count($terms) < 2) {
                continue;
            }
            $maximumWeight = \max(\array_column($terms, 'weight'));
            if (!\is_finite($maximumWeight) || $maximumWeight <= 0.0) {
                return false;
            }
            $weights = [];
            $weightSum = 0.0;
            foreach ($terms as $term) {
                $weight = $term['weight'] / $maximumWeight;
                $weights[] = $weight;
                $weightSum += $weight;
            }
            $variance = 0.0;
            $varianceScale = 0.0;
            for ($first = 0; $first < \count($terms); ++$first) {
                for ($second = $first + 1; $second < \count($terms); ++$second) {
                    $vertexDifference = $terms[$first]['vertex'] - $terms[$second]['vertex'];
                    $firstFraction = $weights[$first] / $weightSum;
                    $secondFraction = $weights[$second] / $weightSum;
                    $pairContribution = ($firstFraction * $secondFraction)
                        * ($vertexDifference * $vertexDifference);
                    if (!\is_finite($pairContribution)) {
                        return false;
                    }
                    $variance += $pairContribution;
                    $varianceScale += \abs($pairContribution);
                }
            }
            $variance = \max(
                0.0,
                $variance - 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, $varianceScale),
            );
            $powerMean = \pow($variance, $power / 2);
            $bonus = $maximumWeight * $weightSum * $powerMean;
            if (!\is_finite($bonus)) {
                return false;
            }
            $lowerBound += $bonus;
            if (!\is_finite($lowerBound)) {
                return false;
            }
        }
        $margin = 64.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($constant), \abs($curvatureDrop), \abs($negativeMass));

        return $lowerBound > $negativeMass + $margin;
    }

    /**
     * Sum absolute exponential-term magnitudes without intermediate overflow.
     *
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $terms
     */
    private function exponentialPhaseTermScaleAt(array $terms, float $value): ?float
    {
        $polynomialSolver = new PolynomialSolver();
        $logMagnitudes = [];
        foreach ($terms as $term) {
            if ($term['coefficient'] === 0.0) {
                continue;
            }
            $phase = $polynomialSolver->evaluatePolynomial($term['phase'], $value);
            if ($phase === null || !\is_finite($phase)) {
                return null;
            }
            $logMagnitude = \log(\abs($term['coefficient'])) + $term['offset'] + $phase;
            if (!\is_finite($logMagnitude)) {
                return null;
            }
            $logMagnitudes[] = $logMagnitude;
        }
        if ($logMagnitudes === []) {
            return null;
        }

        $maximum = \max($logMagnitudes);
        $scaledSum = 0.0;
        foreach ($logMagnitudes as $logMagnitude) {
            $scaledSum += \exp($logMagnitude - $maximum);
        }
        $logScale = $maximum + \log($scaledSum);
        if ($logScale > \log(\PHP_FLOAT_MAX) || $logScale < \log(\PHP_FLOAT_MIN)) {
            return null;
        }
        $scale = \exp($logScale);

        return \is_finite($scale) && $scale > 0.0 ? $scale : null;
    }

    /**
     * @return array{
     *     numerator: list<array{coefficient: float, phase: list<float>, offset: float}>,
     *     denominator: list<array{coefficient: float, phase: list<float>, offset: float}>,
     * }|null
     */
    private function polynomialPhaseExponentialRatioParts(
        Node $node,
        PolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $parts = $this->polynomialPhaseExponentialRatioParts(
                $node->operand,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($parts === null) {
                return null;
            }
            if ($node->operator === UnaryOperator::Minus) {
                foreach ($parts['numerator'] as &$term) {
                    $term['coefficient'] *= -1.0;
                }
                unset($term);
            }

            return $parts;
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth'], true)
            && \count($node->arguments) === 1
        ) {
            $argument = $extractor->extract($node->arguments[0]);
            if ($argument === null) {
                return null;
            }
            $offset = $argument[0] ?? 0.0;
            $phase = $argument;
            $phase[0] = 0.0;
            if (!\is_finite($offset)) {
                return null;
            }
            $positive = [[
                'coefficient' => 1.0,
                'phase' => $phase,
                'offset' => $offset,
            ]];
            $negativePhase = [];
            foreach ($phase as $degree => $coefficient) {
                $negativePhase[$degree] = -$coefficient;
            }
            $negative = [[
                'coefficient' => 1.0,
                'phase' => \array_values($negativePhase),
                'offset' => -$offset,
            ]];
            $unit = [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];
            $halfPositive = $positive;
            $halfPositive[0]['coefficient'] = 0.5;
            $halfNegative = $negative;
            $halfNegative[0]['coefficient'] = 0.5;
            $twiceUnit = $unit[0];
            $twiceUnit['coefficient'] = 2.0;

            $form = match ($node->name) {
                'sinh' => [
                    'numerator' => $this->addPolynomialPhaseExponentialTerms($halfPositive, $halfNegative, -1.0),
                    'denominator' => $unit,
                ],
                'cosh' => [
                    'numerator' => $this->addPolynomialPhaseExponentialTerms($halfPositive, $halfNegative),
                    'denominator' => $unit,
                ],
                'tanh' => [
                    'numerator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative, -1.0),
                    'denominator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative),
                ],
                'sech' => [
                    'numerator' => [$twiceUnit],
                    'denominator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative),
                ],
                'csch' => [
                    'numerator' => [$twiceUnit],
                    'denominator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative, -1.0),
                ],
                'coth' => [
                    'numerator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative),
                    'denominator' => $this->addPolynomialPhaseExponentialTerms($positive, $negative, -1.0),
                ],
            };
            foreach ([...$form['numerator'], ...$form['denominator']] as $term) {
                if (!\is_finite($term['coefficient']) || !\is_finite($term['offset'])) {
                    return null;
                }
                foreach ($term['phase'] as $phaseCoefficient) {
                    if (!\is_finite($phaseCoefficient)) {
                        return null;
                    }
                }
            }

            return $form;
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $exponent = $extractor->extract($node->right);
            if (
                $exponent !== null
                && \count($exponent) === 1
                && \floor($exponent[0]) === $exponent[0]
                && \abs($exponent[0]) <= $maxPolynomialDegree
            ) {
                $base = $this->polynomialPhaseExponentialRatioParts(
                    $node->left,
                    $extractor,
                    $maxPolynomialDegree,
                );
                if ($base === null) {
                    return null;
                }
                $power = (int) $exponent[0];
                if ($power === 0) {
                    $one = [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];

                    return ['numerator' => $one, 'denominator' => $one];
                }
                $numerator = $this->powerPolynomialPhaseExponentialTerms(
                    $power < 0 ? $base['denominator'] : $base['numerator'],
                    \abs($power),
                );
                $denominator = $this->powerPolynomialPhaseExponentialTerms(
                    $power < 0 ? $base['numerator'] : $base['denominator'],
                    \abs($power),
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }

            $numerator = $this->polynomialPhaseExponentialTerms(
                $node,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($numerator === null) {
                return null;
            }

            return [
                'numerator' => $numerator,
                'denominator' => [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]],
            ];
        }
        if ($node instanceof BinaryOperationNode) {
            $left = $this->polynomialPhaseExponentialRatioParts(
                $node->left,
                $extractor,
                $maxPolynomialDegree,
            );
            $right = $this->polynomialPhaseExponentialRatioParts(
                $node->right,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($left === null || $right === null) {
                return null;
            }

            if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                $leftNumerator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['numerator'],
                    $right['denominator'],
                );
                $rightNumerator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $right['numerator'],
                    $left['denominator'],
                );
                $denominator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['denominator'],
                    $right['denominator'],
                );
                if ($leftNumerator === null || $rightNumerator === null || $denominator === null) {
                    return null;
                }
                if ($node->operator === BinaryOperator::Subtract) {
                    foreach ($rightNumerator as &$term) {
                        $term['coefficient'] *= -1.0;
                    }
                    unset($term);
                }
                if (\count($leftNumerator) + \count($rightNumerator) > 256) {
                    return null;
                }

                return [
                    'numerator' => [...$leftNumerator, ...$rightNumerator],
                    'denominator' => $denominator,
                ];
            }
            if ($node->operator === BinaryOperator::Multiply) {
                $numerator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['numerator'],
                    $right['numerator'],
                );
                $denominator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['denominator'],
                    $right['denominator'],
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }
            if ($node->operator === BinaryOperator::Divide) {
                $numerator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['numerator'],
                    $right['denominator'],
                );
                $denominator = $this->multiplyPolynomialPhaseExponentialTerms(
                    $left['denominator'],
                    $right['numerator'],
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }

                return ['numerator' => $numerator, 'denominator' => $denominator];
            }
        }

        $numerator = $this->polynomialPhaseExponentialTerms(
            $node,
            $extractor,
            $maxPolynomialDegree,
        );
        if ($numerator === null) {
            return null;
        }

        return [
            'numerator' => $numerator,
            'denominator' => [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]],
        ];
    }

    /**
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $first
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $second
     * @return list<array{coefficient: float, phase: list<float>, offset: float}>
     */
    private function addPolynomialPhaseExponentialTerms(array $first, array $second, float $secondScale = 1.0): array
    {
        foreach ($second as &$term) {
            $term['coefficient'] *= $secondScale;
        }
        unset($term);

        return [...$first, ...$second];
    }

    /**
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $terms
     * @return list<array{coefficient: float, phase: list<float>, offset: float}>|null
     */
    private function powerPolynomialPhaseExponentialTerms(array $terms, int $power): ?array
    {
        $result = [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];
        $factor = $terms;
        while ($power > 0) {
            if ($power % 2 === 1) {
                $result = $this->multiplyPolynomialPhaseExponentialTerms($result, $factor);
                if ($result === null) {
                    return null;
                }
            }
            $power = \intdiv($power, 2);
            if ($power > 0) {
                $factor = $this->multiplyPolynomialPhaseExponentialTerms($factor, $factor);
                if ($factor === null) {
                    return null;
                }
            }
        }

        return $result;
    }

    /**
     * @return list<array{coefficient: float, phase: list<float>, offset: float}>|null
     */
    private function polynomialPhaseExponentialTerms(
        Node $node,
        PolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $terms = $this->polynomialPhaseExponentialTerms(
                $node->operand,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($terms === null) {
                return null;
            }
            if ($node->operator === UnaryOperator::Minus) {
                foreach ($terms as &$term) {
                    $term['coefficient'] *= -1.0;
                }
                unset($term);
            }

            return $terms;
        }
        if ($node instanceof BinaryOperationNode) {
            if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                $left = $this->polynomialPhaseExponentialTerms(
                    $node->left,
                    $extractor,
                    $maxPolynomialDegree,
                );
                $right = $this->polynomialPhaseExponentialTerms(
                    $node->right,
                    $extractor,
                    $maxPolynomialDegree,
                );
                if ($left === null || $right === null) {
                    return null;
                }
                if ($node->operator === BinaryOperator::Subtract) {
                    foreach ($right as &$term) {
                        $term['coefficient'] *= -1.0;
                    }
                    unset($term);
                }

                return [...$left, ...$right];
            }
            if ($node->operator === BinaryOperator::Multiply) {
                $left = $this->polynomialPhaseExponentialTerms(
                    $node->left,
                    $extractor,
                    $maxPolynomialDegree,
                );
                $right = $this->polynomialPhaseExponentialTerms(
                    $node->right,
                    $extractor,
                    $maxPolynomialDegree,
                );
                if ($left === null || $right === null) {
                    return null;
                }
                return $this->multiplyPolynomialPhaseExponentialTerms($left, $right);
            }
            if ($node->operator === BinaryOperator::Divide) {
                $numerator = $this->polynomialPhaseExponentialTerms(
                    $node->left,
                    $extractor,
                    $maxPolynomialDegree,
                );
                $denominator = $this->polynomialPhaseExponentialTerms(
                    $node->right,
                    $extractor,
                    $maxPolynomialDegree,
                );
                if (
                    $numerator === null
                    || $denominator === null
                    || \count($denominator) !== 1
                    || $denominator[0]['coefficient'] === 0.0
                ) {
                    return null;
                }
                foreach ($numerator as &$term) {
                    $term['coefficient'] /= $denominator[0]['coefficient'];
                    $length = \max(\count($term['phase']), \count($denominator[0]['phase']));
                    for ($degree = 0; $degree < $length; ++$degree) {
                        $term['phase'][$degree] = ($term['phase'][$degree] ?? 0.0)
                            - ($denominator[0]['phase'][$degree] ?? 0.0);
                    }
                    $term['phase'] = \array_values($term['phase']);
                    $term['offset'] -= $denominator[0]['offset'];
                    if (
                        !\is_finite($term['coefficient'])
                        || !\is_finite($term['offset'])
                    ) {
                        return null;
                    }
                    foreach ($term['phase'] as $phaseCoefficient) {
                        if (!\is_finite($phaseCoefficient)) {
                            return null;
                        }
                    }
                }
                unset($term);

                return $numerator;
            }
            if ($node->operator === BinaryOperator::Power) {
                $constantBase = $extractor->extract($node->left);
                $powerCoefficients = $extractor->extract($node->right);
                if (
                    $constantBase !== null
                    && \count($constantBase) === 1
                    && $constantBase[0] > 0.0
                    && $powerCoefficients !== null
                ) {
                    if ($constantBase[0] === 1.0) {
                        return [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];
                    }
                    $logarithmicBase = \log($constantBase[0]);
                    $offset = $logarithmicBase * ($powerCoefficients[0] ?? 0.0);
                    $phase = [];
                    foreach ($powerCoefficients as $degree => $coefficient) {
                        $phase[$degree] = $degree === 0 ? 0.0 : $logarithmicBase * $coefficient;
                        if (!\is_finite($phase[$degree])) {
                            return null;
                        }
                    }
                    if (!\is_finite($offset)) {
                        return null;
                    }

                    return [[
                        'coefficient' => 1.0,
                        'phase' => \array_values($phase),
                        'offset' => $offset,
                    ]];
                }

                $exponent = $powerCoefficients;
                if (
                    $exponent === null
                    || \count($exponent) !== 1
                    || \floor($exponent[0]) !== $exponent[0]
                    || \abs($exponent[0]) > $maxPolynomialDegree
                ) {
                    return null;
                }
                $base = $this->polynomialPhaseExponentialTerms(
                    $node->left,
                    $extractor,
                    $maxPolynomialDegree,
                );
                if ($base === null) {
                    return null;
                }
                $power = (int) $exponent[0];
                if ($power === 0) {
                    return [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];
                }
                if ($power < 0) {
                    if (\count($base) !== 1 || $base[0]['coefficient'] === 0.0) {
                        return null;
                    }
                    $term = $base[0];
                    $term['coefficient'] = \pow($term['coefficient'], $power);
                    foreach ($term['phase'] as &$phaseCoefficient) {
                        $phaseCoefficient *= $power;
                    }
                    unset($phaseCoefficient);
                    $term['offset'] *= $power;
                    if (
                        !\is_finite($term['coefficient'])
                        || $term['coefficient'] === 0.0
                        || !\is_finite($term['offset'])
                    ) {
                        return null;
                    }
                    foreach ($term['phase'] as $phaseCoefficient) {
                        if (!\is_finite($phaseCoefficient)) {
                            return null;
                        }
                    }

                    return [$term];
                }

                $result = [['coefficient' => 1.0, 'phase' => [0.0], 'offset' => 0.0]];
                $factor = $base;
                while ($power > 0) {
                    if ($power % 2 === 1) {
                        $result = $this->multiplyPolynomialPhaseExponentialTerms($result, $factor);
                        if ($result === null) {
                            return null;
                        }
                    }
                    $power = \intdiv($power, 2);
                    if ($power > 0) {
                        $factor = $this->multiplyPolynomialPhaseExponentialTerms($factor, $factor);
                        if ($factor === null) {
                            return null;
                        }
                    }
                }

                return $result;
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['exp', 'sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth'], true)
            && \count($node->arguments) === 1
        ) {
            $exponent = $extractor->extract($node->arguments[0]);
            if ($exponent === null) {
                return null;
            }
            $offset = $exponent[0] ?? 0.0;
            if (!\is_finite($offset)) {
                return null;
            }
            $phase = $exponent;
            $phase[0] = 0.0;

            return [[
                'coefficient' => 1.0,
                'phase' => $phase,
                'offset' => $offset,
            ]];
        }

        $constant = $extractor->extract($node);
        if ($constant === null || \count($constant) !== 1) {
            return null;
        }

        return [['coefficient' => $constant[0], 'phase' => [0.0], 'offset' => 0.0]];
    }

    /**
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $left
     * @param list<array{coefficient: float, phase: list<float>, offset: float}> $right
     * @return list<array{coefficient: float, phase: list<float>, offset: float}>|null
     */
    private function multiplyPolynomialPhaseExponentialTerms(array $left, array $right): ?array
    {
        if (\count($left) * \count($right) > 256) {
            return null;
        }
        $product = [];
        foreach ($left as $first) {
            foreach ($right as $second) {
                $length = \max(\count($first['phase']), \count($second['phase']));
                $phase = [];
                for ($degree = 0; $degree < $length; ++$degree) {
                    $phase[$degree] = ($first['phase'][$degree] ?? 0.0)
                        + ($second['phase'][$degree] ?? 0.0);
                }
                $term = [
                    'coefficient' => $first['coefficient'] * $second['coefficient'],
                    'phase' => \array_values($phase),
                    'offset' => $first['offset'] + $second['offset'],
                ];
                if (
                    !\is_finite($term['coefficient'])
                    || !\is_finite($term['offset'])
                ) {
                    return null;
                }
                foreach ($phase as $phaseCoefficient) {
                    if (!\is_finite($phaseCoefficient)) {
                        return null;
                    }
                }
                $product[] = $term;
            }
        }

        return $product;
    }

    /**
     * @return list<float>|null Null indicates that the requested root is not representable.
     */
    private function realIntegerPowerLevels(float $target, int $power): ?array
    {
        if ($power < 1 || !\is_finite($target)) {
            return null;
        }
        if ($target === 0.0) {
            return [0.0];
        }
        if ($power % 2 === 0 && $target < 0.0) {
            return [];
        }

        $magnitude = \pow(\abs($target), 1.0 / $power);
        if (!\is_finite($magnitude) || $magnitude === 0.0) {
            return null;
        }
        if ($power % 2 !== 0) {
            return [$target < 0.0 ? -$magnitude : $magnitude];
        }

        return [-$magnitude, $magnitude];
    }

    /**
     * @return array{
     *     argumentSource: string,
     *     coefficient: float,
     *     scale: float,
     *     power: int,
     *     offset: float,
     * }|null
     */
    private function lambertWEquationProductForm(
        Node $node,
        string $source,
        int $sourceOffset,
        PolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $product = $this->lambertWProductForm(
            $node,
            $source,
            $sourceOffset,
            $extractor,
            $maxPolynomialDegree,
        );
        if ($product !== null) {
            return [...$product, 'offset' => 0.0];
        }

        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->lambertWEquationProductForm(
                $node->operand,
                $source,
                $sourceOffset,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($form === null) {
                return null;
            }
            if ($node->operator === UnaryOperator::Minus) {
                $form['coefficient'] *= -1.0;
                $form['offset'] *= -1.0;
            }

            return $form;
        }
        if (
            !$node instanceof BinaryOperationNode
            || !\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return null;
        }

        $leftForm = $this->lambertWEquationProductForm(
            $node->left,
            $source,
            $sourceOffset,
            $extractor,
            $maxPolynomialDegree,
        );
        $rightConstant = $extractor->extract($node->right);
        if ($leftForm !== null && $rightConstant !== null && \count($rightConstant) === 1) {
            $leftForm['offset'] += $node->operator === BinaryOperator::Subtract
                ? -$rightConstant[0]
                : $rightConstant[0];

            return \is_finite($leftForm['offset']) ? $leftForm : null;
        }

        $rightForm = $this->lambertWEquationProductForm(
            $node->right,
            $source,
            $sourceOffset,
            $extractor,
            $maxPolynomialDegree,
        );
        $leftConstant = $extractor->extract($node->left);
        if ($rightForm === null || $leftConstant === null || \count($leftConstant) !== 1) {
            return null;
        }
        if ($node->operator === BinaryOperator::Add) {
            $rightForm['offset'] += $leftConstant[0];
        } else {
            $rightForm['coefficient'] *= -1.0;
            $rightForm['offset'] = $leftConstant[0] - $rightForm['offset'];
        }

        return \is_finite($rightForm['coefficient']) && \is_finite($rightForm['offset'])
            ? $rightForm
            : null;
    }

    /**
     * @return array{argumentSource: string, coefficient: float, scale: float, power: int}|null
     */
    private function lambertWProductForm(
        Node $node,
        string $source,
        int $sourceOffset,
        PolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $factors = [];
        $coefficient = 1.0;
        if (!$this->collectLambertProductFactors($node, $factors, $coefficient, $extractor)) {
            return null;
        }

        $exponential = null;
        $argumentFactors = [];
        $argumentCoefficients = [1.0];
        $argumentDenominatorCoefficients = [1.0];
        $argumentFactorSources = [];
        $symbolicArgument = null;
        $symbolicArgumentSource = null;
        foreach ($factors as $index => $factor) {
            $factor = $this->unwrapGrouping($factor);
            if (
                $factor instanceof FunctionCallNode
                && $factor->name === 'exp'
                && \count($factor->arguments) === 1
            ) {
                if ($exponential !== null) {
                    return null;
                }
                $exponential = $factor;
                continue;
            }

            $factorRationalForm = $extractor->extractRationalForm($factor);
            if ($factorRationalForm === null) {
                if ($symbolicArgument !== null) {
                    return null;
                }
                $symbolicArgument = $factor;
                $factorSpan = $factor->span();
                $symbolicArgumentSource = \substr(
                    $source,
                    $factorSpan->start - $sourceOffset,
                    $factorSpan->end - $factorSpan->start,
                );
                if (!\is_string($symbolicArgumentSource) || $symbolicArgumentSource === '') {
                    return null;
                }
                continue;
            }
            [$factorNumerator, $factorDenominator] = $factorRationalForm;
            if (\count($factorNumerator) === 1 && \count($factorDenominator) === 1) {
                if ($factorDenominator[0] === 0.0) {
                    return null;
                }
                $coefficient *= $factorNumerator[0] / $factorDenominator[0];
                continue;
            }
            $argumentCoefficients = $this->multiplyPolynomials($argumentCoefficients, $factorNumerator);
            $argumentDenominatorCoefficients = $this->multiplyPolynomials(
                $argumentDenominatorCoefficients,
                $factorDenominator,
            );
            if (
                \count($argumentCoefficients) - 1 > $maxPolynomialDegree
                || \count($argumentDenominatorCoefficients) - 1 > $maxPolynomialDegree
            ) {
                return null;
            }
            foreach ([...$argumentCoefficients, ...$argumentDenominatorCoefficients] as $argumentCoefficient) {
                if (!\is_finite($argumentCoefficient)) {
                    return null;
                }
            }
            $argumentFactors[] = $factor;
            $factorSpan = $factor->span();
            $factorSource = \substr(
                $source,
                $factorSpan->start - $sourceOffset,
                $factorSpan->end - $factorSpan->start,
            );
            if ($factorSource === '') {
                return null;
            }
            $argumentFactorSources[] = '(' . $factorSource . ')';
        }

        if (
            $exponential === null
            || ($argumentFactors === [] && $symbolicArgument === null)
        ) {
            return null;
        }
        if ($symbolicArgument !== null) {
            if ($argumentFactors !== []) {
                return null;
            }
            $relation = $this->lambertWSymbolicAffineRelation(
                $symbolicArgument,
                $exponential->arguments[0],
                $source,
                $sourceOffset,
                $extractor,
            );
            if ($relation === null) {
                return null;
            }
            $exponentialOffset = \exp($relation['offset']);
            if (!\is_finite($exponentialOffset) || $exponentialOffset === 0.0) {
                return null;
            }
            $coefficient *= $exponentialOffset;
            if (!\is_finite($coefficient)) {
                return null;
            }
            if (!\is_string($symbolicArgumentSource)) {
                return null;
            }

            return [
                'argumentSource' => $symbolicArgumentSource,
                'coefficient' => $coefficient,
                'scale' => $relation['scale'],
                'power' => 1,
            ];
        }
        $exponentRationalForm = $extractor->extractRationalForm($exponential->arguments[0]);
        if ($exponentRationalForm === null) {
            return null;
        }
        [$exponentNumerator, $exponentDenominator] = $exponentRationalForm;
        $baseNode = null;
        $baseSource = \implode('*', $argumentFactorSources);
        $basePower = 1;
        $relation = null;
        if (\count($argumentFactors) === 1) {
            $argumentFactor = $argumentFactors[0];
            $baseOptions = [[
                $argumentFactor,
                $argumentCoefficients,
                $argumentDenominatorCoefficients,
                1,
            ]];
            $unwrappedFactor = $this->unwrapGrouping($argumentFactor);
            if (
                $unwrappedFactor instanceof BinaryOperationNode
                && $unwrappedFactor->operator === BinaryOperator::Power
                && $argumentDenominatorCoefficients === [1.0]
            ) {
                $powerCoefficients = $extractor->extract($unwrappedFactor->right);
                $baseCoefficients = $extractor->extract($unwrappedFactor->left);
                if (
                    $powerCoefficients !== null
                    && \count($powerCoefficients) === 1
                    && $powerCoefficients[0] >= 2.0
                    && $powerCoefficients[0] <= 9007199254740991.0
                    && \floor($powerCoefficients[0]) === $powerCoefficients[0]
                    && $baseCoefficients !== null
                    && \count($baseCoefficients) > 1
                ) {
                    $baseOptions[] = [
                        $unwrappedFactor->left,
                        $baseCoefficients,
                        [1.0],
                        (int) $powerCoefficients[0],
                    ];
                }
            }
            foreach (
                $baseOptions as [
                    $candidateNode,
                    $candidateCoefficients,
                    $candidateDenominator,
                    $candidatePower,
                ]
            ) {
                $candidateRelation = $this->lambertWRationalAffineRelation(
                    $candidateCoefficients,
                    $candidateDenominator,
                    $exponentNumerator,
                    $exponentDenominator,
                );
                if ($candidateRelation === null) {
                    continue;
                }
                $baseNode = $candidateNode;
                $basePower = $candidatePower;
                $relation = $candidateRelation;
                break;
            }
            if ($baseNode !== null) {
                $baseSpan = $baseNode->span();
                $baseSource = \substr(
                    $source,
                    $baseSpan->start - $sourceOffset,
                    $baseSpan->end - $baseSpan->start,
                );
            }
        } else {
            $relation = $this->lambertWRationalAffineRelation(
                $argumentCoefficients,
                $argumentDenominatorCoefficients,
                $exponentNumerator,
                $exponentDenominator,
            );
        }
        if ($relation === null) {
            return null;
        }

        $exponentOffset = $relation['offset'];
        $exponentialOffset = \exp($exponentOffset);
        if (!\is_finite($exponentialOffset) || $exponentialOffset === 0.0) {
            return null;
        }
        $coefficient *= $exponentialOffset;
        if (
            $baseSource === ''
            || !\is_finite($coefficient)
        ) {
            return null;
        }

        return [
            'argumentSource' => $baseSource,
            'coefficient' => $coefficient,
            'scale' => $relation['scale'],
            'power' => $basePower,
        ];
    }

    /**
     * @return array{scale: float, offset: float}|null
     */
    private function lambertWSymbolicAffineRelation(
        Node $base,
        Node $exponent,
        string $source,
        int $sourceOffset,
        PolynomialExtractor $extractor,
    ): ?array {
        $base = $this->unwrapGrouping($base);
        $baseSpan = $base->span();
        $baseSource = \preg_replace(
            '/\s+/',
            '',
            \substr($source, $baseSpan->start - $sourceOffset, $baseSpan->end - $baseSpan->start),
        );
        if ($baseSource === null || $baseSource === '') {
            return null;
        }

        $terms = [];
        $this->flattenAdditiveTerms($exponent, 1.0, $terms);
        $scale = 0.0;
        $offset = 0.0;
        $matchedBase = false;
        foreach ($terms as [$term, $sign]) {
            $weightedFunction = $this->extractConstantMultipleFunctionCall($term, $extractor);
            if ($weightedFunction !== null) {
                [$function, $coefficient] = $weightedFunction;
                $functionSpan = $function->span();
                $functionSource = \preg_replace(
                    '/\s+/',
                    '',
                    \substr(
                        $source,
                        $functionSpan->start - $sourceOffset,
                        $functionSpan->end - $functionSpan->start,
                    ),
                );
                if ($functionSource === null) {
                    return null;
                }
                if ($functionSource === $baseSource) {
                    $scale += $sign * $coefficient;
                    $matchedBase = true;
                    continue;
                }
            }
            $constant = $this->extractPolynomial($extractor, $term, $term->span()->start);
            if ($constant === null || \count($constant) !== 1) {
                return null;
            }
            $offset += $sign * $constant[0];
        }
        if (!$matchedBase || !\is_finite($scale) || !\is_finite($offset)) {
            return null;
        }

        return ['scale' => $scale, 'offset' => $offset];
    }

    /**
     * @param list<float> $baseNumerator
     * @param list<float> $baseDenominator
     * @param list<float> $exponentNumerator
     * @param list<float> $exponentDenominator
     * @return array{scale: float, offset: float}|null
     */
    private function lambertWRationalAffineRelation(
        array $baseNumerator,
        array $baseDenominator,
        array $exponentNumerator,
        array $exponentDenominator,
    ): ?array {
        $exponentTimesBaseDenominator = $this->multiplyPolynomials(
            $exponentNumerator,
            $baseDenominator,
        );
        $baseTimesExponentDenominator = $this->multiplyPolynomials(
            $baseNumerator,
            $exponentDenominator,
        );
        $commonDenominator = $this->multiplyPolynomials(
            $exponentDenominator,
            $baseDenominator,
        );
        foreach (
            [
                ...$exponentTimesBaseDenominator,
                ...$baseTimesExponentDenominator,
                ...$commonDenominator,
            ] as $coefficient
        ) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        $length = \max(
            \count($exponentTimesBaseDenominator),
            \count($baseTimesExponentDenominator),
            \count($commonDenominator),
        );
        $scale = null;
        $offset = null;
        for ($first = 0; $first < $length && $scale === null; ++$first) {
            for ($second = $first + 1; $second < $length; ++$second) {
                $baseFirst = $baseTimesExponentDenominator[$first] ?? 0.0;
                $baseSecond = $baseTimesExponentDenominator[$second] ?? 0.0;
                $denominatorFirst = $commonDenominator[$first] ?? 0.0;
                $denominatorSecond = $commonDenominator[$second] ?? 0.0;
                $determinant = ($baseFirst * $denominatorSecond)
                    - ($baseSecond * $denominatorFirst);
                if ($determinant === 0.0 || !\is_finite($determinant)) {
                    continue;
                }
                $exponentFirst = $exponentTimesBaseDenominator[$first] ?? 0.0;
                $exponentSecond = $exponentTimesBaseDenominator[$second] ?? 0.0;
                $scale = (($exponentFirst * $denominatorSecond)
                    - ($exponentSecond * $denominatorFirst)) / $determinant;
                $offset = (($baseFirst * $exponentSecond)
                    - ($baseSecond * $exponentFirst)) / $determinant;
                if (!\is_finite($scale) || !\is_finite($offset)) {
                    return null;
                }
                break;
            }
        }
        if ($scale === null || $offset === null) {
            return null;
        }
        for ($degree = 0; $degree < $length; ++$degree) {
            if (
                ($exponentTimesBaseDenominator[$degree] ?? 0.0)
                !== (($baseTimesExponentDenominator[$degree] ?? 0.0) * $scale)
                    + (($commonDenominator[$degree] ?? 0.0) * $offset)
            ) {
                return null;
            }
        }

        return ['scale' => $scale, 'offset' => $offset];
    }

    /**
     * @param list<Node> $factors
     */
    private function collectLambertProductFactors(
        Node $node,
        array &$factors,
        float &$coefficient,
        PolynomialExtractor $extractor,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $operand = $this->unwrapGrouping($node->operand);
            if (
                !$operand instanceof BinaryOperationNode
                || !\in_array(
                    $operand->operator,
                    [BinaryOperator::Multiply, BinaryOperator::Divide],
                    true,
                )
            ) {
                $factors[] = $node;

                return true;
            }
            if ($node->operator === UnaryOperator::Minus) {
                $coefficient *= -1.0;
            }

            return $this->collectLambertProductFactors(
                $operand,
                $factors,
                $coefficient,
                $extractor,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Multiply
        ) {
            return $this->collectLambertProductFactors(
                $node->left,
                $factors,
                $coefficient,
                $extractor,
            ) && $this->collectLambertProductFactors(
                $node->right,
                $factors,
                $coefficient,
                $extractor,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Divide
        ) {
            $denominator = $extractor->extract($node->right);
            if ($denominator === null || \count($denominator) !== 1) {
                $factors[] = $node;

                return true;
            }
            if ($denominator[0] == 0.0) {
                return false;
            }
            $coefficient /= $denominator[0];

            return $this->collectLambertProductFactors(
                $node->left,
                $factors,
                $coefficient,
                $extractor,
            );
        }

        $factors[] = $node;

        return true;
    }

    /**
     * Reduce nonnegative-base variable powers with positive targets.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNonnegativeBasePowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && !$this->containsVariable($right, $variable)
        ) {
            $power = $left;
            $target = $right;
            $powerSource = $leftSource;
            $powerSourceOffset = 0;
        } elseif (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && !$this->containsVariable($left, $variable)
        ) {
            $power = $right;
            $target = $left;
            $powerSource = $rightSource;
            $powerSourceOffset = 0;
        } else {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $target,
            $target->span()->start,
        );
        if (
            $targetCoefficients === null
            || \count($targetCoefficients) !== 1
            || !\is_finite($targetCoefficients[0])
            || $targetCoefficients[0] <= 0.0
        ) {
            return null;
        }
        $targetValue = $targetCoefficients[0];
        if ($targetValue !== 1.0) {
            $baseCoefficients = $this->extractPolynomial(
                $extractor,
                $power->left,
                $power->left->span()->start,
            );
            if ($baseCoefficients !== null && \count($baseCoefficients) === 1 && $baseCoefficients[0] === 0.0) {
                return [];
            }
        }
        $baseRange = $this->boundedExpressionRange(
            $power->left,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        if ($baseRange === null || $baseRange[0] < 0.0) {
            return null;
        }

        $baseSpan = $power->left->span();
        $exponentSpan = $power->right->span();
        $baseSource = \substr(
            $powerSource,
            $baseSpan->start - $powerSourceOffset,
            $baseSpan->end - $baseSpan->start,
        );
        $exponentSource = \substr(
            $powerSource,
            $exponentSpan->start - $powerSourceOffset,
            $exponentSpan->end - $exponentSpan->start,
        );
        if ($baseSource === '' || $exponentSource === '') {
            return null;
        }

        if ($targetValue !== 1.0) {
            $constantExponent = $this->extractPolynomial(
                $extractor,
                $power->right,
                $power->right->span()->start,
            );
            if (
                $constantExponent !== null
                && \count($constantExponent) === 1
                && $constantExponent[0] !== 0.0
                && \is_finite($constantExponent[0])
            ) {
                $baseLevel = \exp(\log($targetValue) / $constantExponent[0]);
                if (\is_finite($baseLevel) && $baseLevel > 0.0) {
                    $baseLevelEquation = '(' . $baseSource . ')='
                        . \sprintf('%.17g', $baseLevel);
                    if (\strlen($baseLevelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                        return null;
                    }
                    try {
                        $baseLevelSolutions = $this->solve(
                                $baseLevelEquation,
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $options,
                            );
                    } catch (\InvalidArgumentException | \DomainException) {
                        return null;
                    }
                    $solutions = [];
                    foreach ($baseLevelSolutions as $candidate) {
                        $residual = $residualAt($candidate->value);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScaleAt,
                                $options,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution(
                                $candidate->value,
                                \abs($residual),
                                $candidate->iterations,
                            ),
                            $options,
                        );
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
            }

            $baseRationalForm = $extractor->extractRationalForm(
                $power->left,
            );
            $exponentCoefficients = $this->extractPolynomial(
                $extractor,
                $power->right,
                $exponentSpan->start,
            );
            if (
                $baseRationalForm !== null
                && $exponentCoefficients !== null
                && \count($exponentCoefficients) === 1
                && $exponentCoefficients[0] !== 0.0
                && \floor(\abs($exponentCoefficients[0])) === \abs($exponentCoefficients[0])
                && \max(
                    \count($baseRationalForm[0]) - 1,
                    \count($baseRationalForm[1]) - 1,
                ) * \abs($exponentCoefficients[0]) <= $options->maxPolynomialDegree
            ) {
                if ($this->extractPolynomial($extractor, $power->left, $baseSpan->start) !== null) {
                    return null;
                }

                $logBaseLevel = \log($targetValue) / $exponentCoefficients[0];
                $baseLevel = \exp($logBaseLevel);
                if (\is_finite($baseLevel) && $baseLevel > 0.0) {
                    $baseLevelEquation = '(' . $baseSource . ')='
                        . \sprintf('%.17g', $baseLevel);
                    if (
                        \strlen($baseLevelEquation)
                            <= $evaluationOptions->limits->maxExpressionLength
                    ) {
                        $baseLevelSolutions = $this->solve(
                            $baseLevelEquation,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                        );
                        $solutions = [];
                        foreach ($baseLevelSolutions as $candidate) {
                            $residual = $residualAt($candidate->value);
                            if (
                                $residual === null
                                || (
                                    !$this->isResidualAcceptableAt(
                                        $candidate->value,
                                        $residual,
                                        $candidateScaleAt,
                                        $options,
                                    )
                                    && !$this->isCandidateAtFloatingPointRootResolution(
                                        $candidate->value,
                                        $residual,
                                        $residualAt,
                                    )
                                )
                            ) {
                                continue;
                            }
                            $this->addSolution(
                                $solutions,
                                new EquationSolution(
                                    $candidate->value,
                                    \abs($residual),
                                    $candidate->iterations,
                                ),
                                $options,
                            );
                        }
                        \usort(
                            $solutions,
                            static fn (EquationSolution $first, EquationSolution $second): int =>
                                $first->value <=> $second->value,
                        );

                        return $solutions;
                    }
                }
            }

            $logTarget = \log($targetValue);
            if (!\is_finite($logTarget)) {
                return null;
            }
            $transformedEquation = '(' . $exponentSource . ')*ln(' . $baseSource . ')='
                . \sprintf('%.17g', $logTarget);
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $transformedSolutions = $this->solve(
                $transformedEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            $solutions = [];
            foreach ($transformedSolutions as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $baseSolutions = [];
        if ($this->containsVariable($power->left, $variable)) {
            try {
                $baseSolutions = $this->solveNestedFunctionLevels(
                    $baseSource,
                    [1.0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
            } catch (InfiniteSolutionSetException) {
                return null;
            }
        } else {
            try {
                if ((float) \MathPHP\Math::evaluate($baseSource, $parameters, $evaluationOptions) === 1.0) {
                    return null;
                }
            } catch (EvaluationException) {
                return null;
            }
        }

        $exponentSolutions = [];
        if ($this->containsVariable($power->right, $variable)) {
            try {
                $exponentSolutions = $this->solveNestedFunctionLevels(
                    $exponentSource,
                    [0.0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
            } catch (InfiniteSolutionSetException) {
                return null;
            }
        } else {
            try {
                if ((float) \MathPHP\Math::evaluate($exponentSource, $parameters, $evaluationOptions) === 0.0) {
                    return null;
                }
            } catch (EvaluationException) {
                return null;
            }
        }
        if ($baseSolutions === null || $exponentSolutions === null) {
            return null;
        }

        $solutions = [];
        foreach ([...$baseSolutions, ...$exponentSolutions] as $solution) {
            $this->addSolution($solutions, $solution, $options);
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveLogProductLevelEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);

        $baseForm = null;
        $baseNode = null;
        /** @var float|null $basePower */
        $basePower = null;
        $logarithmicCoefficient = 0.0;
        $linearCoefficient = 0.0;
        $constant = 0.0;
        $deferredVariableTerms = [];
        foreach ($terms as [$term, $sign]) {
            $factors = [];
            $this->flattenLogProductFactors($term, 1.0, $factors);
            $logarithmIndex = null;
            $logarithm = null;
            $naturalLogScale = 1.0;
            foreach ($factors as $index => [$factor, $factorSign]) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && (
                        ($factor->name === 'ln' && \count($factor->arguments) === 1)
                        || ($factor->name === 'log' && \count($factor->arguments) === 2)
                    )
                ) {
                    if ($logarithm !== null || $factorSign < 0.0) {
                        return null;
                    }
                    if ($factor->name === 'log') {
                        if (!isset($factor->arguments[1])) {
                            return null;
                        }
                        if ($this->containsVariable($factor->arguments[1], $variable)) {
                            return null;
                        }
                        $baseCoefficients = $extractor->extract($factor->arguments[1]);
                        if (
                            $baseCoefficients === null
                            || \count($baseCoefficients) !== 1
                            || $baseCoefficients[0] <= 0.0
                            || $baseCoefficients[0] === 1.0
                        ) {
                            return null;
                        }
                        $naturalLogScale = 1.0 / \log($baseCoefficients[0]);
                        if (!\is_finite($naturalLogScale)) {
                            return null;
                        }
                    }
                    $logarithmIndex = $index;
                    $logarithm = $factor;
                }
            }

            if ($logarithm !== null && $logarithmIndex !== null) {
                if ($baseForm !== null) {
                    return null;
                }
                $baseNode = $logarithm->arguments[0];
                $baseForm = $extractor->extractRationalForm($baseNode);
                if ($baseForm === null) {
                    return null;
                }
                $coefficient = 1.0;
                $totalPower = 0.0;
                $totalPowerMagnitude = 0.0;
                foreach ($factors as $index => [$factor, $factorSign]) {
                    if ($index === $logarithmIndex) {
                        continue;
                    }
                    $factorForm = $this->logarithmBasePowerProduct(
                        $factor,
                        $baseForm,
                        $extractor,
                        $options,
                    );
                    if ($factorForm === null) {
                        return null;
                    }
                    [$factorPower, $factorCoefficient] = $factorForm;
                    $factorPower *= $factorSign;
                    if ($factorSign < 0.0) {
                        $factorCoefficient = 1.0 / $factorCoefficient;
                    }
                    if (\abs($factorPower) > $options->maxPolynomialDegree - $totalPowerMagnitude) {
                        return null;
                    }
                    $totalPower += $factorPower;
                    $totalPowerMagnitude += \abs($factorPower);
                    $coefficient *= $factorCoefficient;
                }
                if ($totalPower === 0.0 || !\is_finite($coefficient)) {
                    return null;
                }
                $basePower = $totalPower;
                $logarithmicCoefficient += $sign * $coefficient * $naturalLogScale;
                continue;
            }

            if ($this->containsVariable($term, $variable)) {
                if ($baseForm === null) {
                    $deferredVariableTerms[] = [$term, $sign];
                    continue;
                }
                $basePowerForm = $this->logarithmBasePowerProduct(
                    $term,
                    $baseForm,
                    $extractor,
                    $options,
                );
                if (
                    $basePowerForm === null
                    || !$this->logarithmPowersMatch($basePowerForm[0], $basePower)
                ) {
                    return null;
                }
                $linearCoefficient += $sign * $basePowerForm[1];
                continue;
            }
            $constantCoefficients = $extractor->extract($term);
            if ($constantCoefficients === null || \count($constantCoefficients) !== 1) {
                return null;
            }
            $constant += $sign * $constantCoefficients[0];
        }

        if (
            $baseForm === null
            || $baseNode === null
            || $basePower === null
            || $basePower === 0.0
        ) {
            return null;
        }
        foreach ($deferredVariableTerms as [$term, $sign]) {
            $basePowerForm = $this->logarithmBasePowerProduct(
                $term,
                $baseForm,
                $extractor,
                $options,
            );
            if (
                $basePowerForm === null
                || !$this->logarithmPowersMatch($basePowerForm[0], $basePower)
            ) {
                return null;
            }
            $linearCoefficient += $sign * $basePowerForm[1];
        }

        if (
            $logarithmicCoefficient === 0.0
            || !\is_finite($logarithmicCoefficient)
            || !\is_finite($linearCoefficient)
            || !\is_finite($constant)
        ) {
            return null;
        }

        $linearShift = $linearCoefficient / $logarithmicCoefficient;
        $normalizedTarget = -$constant / $logarithmicCoefficient;
        $transformedTarget = $basePower * $normalizedTarget
            * \exp($basePower * $linearShift);
        if (!\is_finite($linearShift) || !\is_finite($transformedTarget)) {
            return null;
        }

        $range = $this->rationalPolynomialRange(
            $baseForm[0],
            $baseForm[1],
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($range === null) {
            return null;
        }
        [$rangeBounds, $numerator, $denominator] = $range;

        $branchPoint = -1.0 / \M_E;
        $branchTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($transformedTarget), \abs($branchPoint));
        if ($transformedTarget < $branchPoint - $branchTolerance) {
            return [];
        }

        $levels = [];
        if (\abs($transformedTarget - $branchPoint) <= $branchTolerance) {
            $levels[] = \exp((-1.0 / $basePower) - $linearShift);
        } else {
            $lambertW = $evaluationOptions->functions->find('lambertw');
            if ($lambertW === null) {
                return null;
            }
            $branches = $transformedTarget < 0.0 ? [0, -1] : [0];
            foreach ($branches as $branch) {
                $arguments = $branch === 0
                    ? [$transformedTarget]
                    : [$transformedTarget, $branch];
                $levels[] = \exp(
                    ($lambertW->invoke($arguments) / $basePower) - $linearShift,
                );
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ($levels as $level) {
            if (!\is_finite($level) || $level <= 0.0) {
                continue;
            }
            $levelPolynomial = $this->subtractScaledPolynomials(
                $numerator,
                $denominator,
                $level,
            );
            if ($levelPolynomial === null) {
                return null;
            }
            if ($levelPolynomial === [0.0]) {
                foreach ($this->intervalProbePositions($lowerBound, $upperBound) as $probe) {
                    $residual = $residualAt($probe);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $probe,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }
                }
                continue;
            }
            $polynomialResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelPolynomial, $value);
            $polynomialResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelPolynomial, $value);
            $candidates = $polynomialSolver->solve(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $options,
                $polynomialResidualScaleAt,
            );
            if ($candidates === null) {
                return null;
            }
            $candidates = $polynomialSolver->recoverRepeatedRoots(
                $levelPolynomial,
                $candidates,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $polynomialResidualScaleAt,
                $options,
            );
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalSelfPowerEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $baseForm = null;
        $scale = null;
        $constant = null;
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && !$this->containsVariable($right, $variable)
        ) {
            $baseForm = $extractor->extractRationalForm($left->left);
            $exponentForm = $extractor->extractRationalForm($left->right);
            $constant = $right;
            if ($baseForm !== null && $exponentForm !== null) {
                $exponentCrossProduct = $this->multiplyPolynomials(
                    $exponentForm[0],
                    $baseForm[1],
                );
                $baseCrossProduct = $this->multiplyPolynomials(
                    $baseForm[0],
                    $exponentForm[1],
                );
                $scale = $this->approximatelyProportionalPolynomialRatio(
                    $exponentCrossProduct,
                    $baseCrossProduct,
                );
                $exactScale = $this->exactPolynomialScale(
                    $left->left,
                    $left->right,
                    $variable,
                    $parameters,
                    $options,
                    $evaluationOptions,
                );
                if ($exactScale !== null) {
                    $scale = $exactScale;
                }
            }
        } elseif (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && !$this->containsVariable($left, $variable)
        ) {
            $baseForm = $extractor->extractRationalForm($right->left);
            $exponentForm = $extractor->extractRationalForm($right->right);
            $constant = $left;
            if ($baseForm !== null && $exponentForm !== null) {
                $exponentCrossProduct = $this->multiplyPolynomials(
                    $exponentForm[0],
                    $baseForm[1],
                );
                $baseCrossProduct = $this->multiplyPolynomials(
                    $baseForm[0],
                    $exponentForm[1],
                );
                $scale = $this->approximatelyProportionalPolynomialRatio(
                    $exponentCrossProduct,
                    $baseCrossProduct,
                );
                $exactScale = $this->exactPolynomialScale(
                    $right->left,
                    $right->right,
                    $variable,
                    $parameters,
                    $options,
                    $evaluationOptions,
                );
                if ($exactScale !== null) {
                    $scale = $exactScale;
                }
            }
        } elseif (
            $left instanceof FunctionCallNode
            && $left->name === 'exp'
            && \count($left->arguments) === 1
            && !$this->containsVariable($right, $variable)
        ) {
            $form = $this->rationalExponentialSelfPowerForm(
                $left,
                $variable,
                $extractor,
            );
            if ($form !== null) {
                [$baseForm, $scale] = $form;
                $constant = $right;
            }
        } elseif (
            $right instanceof FunctionCallNode
            && $right->name === 'exp'
            && \count($right->arguments) === 1
            && !$this->containsVariable($left, $variable)
        ) {
            $form = $this->rationalExponentialSelfPowerForm(
                $right,
                $variable,
                $extractor,
            );
            if ($form !== null) {
                [$baseForm, $scale] = $form;
                $constant = $left;
            }
        }

        if (
            $baseForm === null
            || $scale === null
            || $constant === null
            || \count($baseForm[1]) < 2
        ) {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }

        $range = $this->rationalPolynomialRange(
            $baseForm[0],
            $baseForm[1],
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($range === null || $range[0][0] <= 0.0) {
            return null;
        }
        [$rangeBounds, $numerator, $denominator] = $range;
        $target = $targetCoefficients[0];
        if ($scale === -1.0) {
            if ($target === 0.0) {
                return [];
            }
            $target = 1.0 / $target;
        } elseif ($scale !== 1.0) {
            if ($target <= 0.0) {
                return [];
            }
            $target = \exp(\log($target) / $scale);
            if ($target === 0.0 || !\is_finite($target)) {
                return [];
            }
        }
        if (!\is_finite($target) || $target <= 0.0) {
            return [];
        }

        $equationTarget = $targetCoefficients[0];
        $logTarget = \log($target);
        $branchPoint = -1.0 / \M_E;
        $branchTarget = \exp($branchPoint);
        $branchTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($logTarget), \abs($branchPoint));
        $levels = [];
        $scaledBranchTarget = \exp(-$scale / \M_E);
        if (\is_finite($scaledBranchTarget) && $scaledBranchTarget > 0.0) {
            $targetOffset = $equationTarget - $scaledBranchTarget;
            $constantNode = $this->unwrapGrouping($constant);
            $exponentialTarget = $constantNode instanceof FunctionCallNode
                && $constantNode->name === 'exp'
                && \count($constantNode->arguments) === 1;
            $targetTolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($equationTarget), \abs($scaledBranchTarget));
            if ($targetOffset === 0.0 || ($exponentialTarget && \abs($targetOffset) <= $targetTolerance)) {
                $levels[] = 1.0 / \M_E;
            } elseif (($scale > 0.0 && $targetOffset < 0.0) || ($scale < 0.0 && $targetOffset > 0.0)) {
                return [];
            } else {
                $logTarget = $branchPoint
                    + (\log1p($targetOffset / $scaledBranchTarget) / $scale);
            }
            if ($equationTarget === 1.0) {
                $logTarget = 0.0;
            }
        } elseif ($logTarget < $branchPoint - $branchTolerance) {
            return [];
        } elseif (\abs($logTarget - $branchPoint) <= $branchTolerance) {
            $levels[] = 1.0 / \M_E;
        }
        if ($levels === [] && $logTarget < 0.0) {
            $levels[] = $this->bisectSelfPowerLogLevel(
                $logTarget,
                0.0,
                1.0 / \M_E,
                decreasing: true,
            );
            $levels[] = $this->bisectSelfPowerLogLevel(
                $logTarget,
                1.0 / \M_E,
                1.0,
                decreasing: false,
            );
        } elseif ($levels === [] && $logTarget === 0.0) {
            $levels[] = 1.0;
        } elseif ($levels === []) {
            $upperLevel = \max(2.0, $logTarget + 2.0);
            while (
                $upperLevel * \log($upperLevel) < $logTarget
                && \is_finite($upperLevel * 2.0)
            ) {
                $upperLevel *= 2.0;
            }
            if (!\is_finite($upperLevel * \log($upperLevel))) {
                return null;
            }
            $levels[] = $this->bisectSelfPowerLogLevel(
                $logTarget,
                1.0,
                $upperLevel,
                decreasing: false,
            );
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ($levels as $level) {
            $levelPolynomial = $this->subtractScaledPolynomials(
                $numerator,
                $denominator,
                $level,
            );
            if ($levelPolynomial === null) {
                return null;
            }
            if ($levelPolynomial === [0.0]) {
                foreach ($this->intervalProbePositions($lowerBound, $upperBound) as $probe) {
                    $residual = $residualAt($probe);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $probe,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }
                }
                continue;
            }
            $polynomialResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelPolynomial, $value);
            $polynomialResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelPolynomial, $value);
            $candidates = $polynomialSolver->solve(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $options,
                $polynomialResidualScaleAt,
            );
            if ($candidates === null) {
                return null;
            }
            $candidates = $polynomialSolver->recoverRepeatedRoots(
                $levelPolynomial,
                $candidates,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $polynomialResidualScaleAt,
                $options,
            );
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $numerator
     * @param list<float> $denominator
     */
    /**
     * Return the exact constant ratio when two rational polynomials are proportional.
     *
     * @param array<string, int|float> $parameters
     */
    private function exactPolynomialScale(
        Node $base,
        Node $exponent,
        string $variable,
        array $parameters,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $options->maxPolynomialDegree,
            $evaluationOptions,
        );
        $baseCoefficients = $extractor->polynomial($base);
        $exponentCoefficients = $extractor->polynomial($exponent);
        if ($baseCoefficients === null || $exponentCoefficients === null) {
            return null;
        }

        $integerArithmetic = new IntegerPolynomialExtractor('', [], $options->maxPolynomialDegree);
        $length = \max(\count($baseCoefficients), \count($exponentCoefficients));
        $ratioNumerator = null;
        $ratioDenominator = null;
        for ($degree = 0; $degree < $length; ++$degree) {
            [$baseNumerator, $baseDenominator] = $baseCoefficients[$degree] ?? ['0', '1'];
            [$exponentNumerator, $exponentDenominator] = $exponentCoefficients[$degree] ?? ['0', '1'];
            if ($baseNumerator === '0') {
                if ($exponentNumerator !== '0') {
                    return null;
                }
                continue;
            }
            if ($exponentNumerator === '0') {
                return null;
            }
            $ratioNumerator = $integerArithmetic->multiplyIntegerValues(
                $exponentNumerator,
                $baseDenominator,
            );
            $ratioDenominator = $integerArithmetic->multiplyIntegerValues(
                $exponentDenominator,
                $baseNumerator,
            );
            break;
        }
        if ($ratioNumerator === null || $ratioDenominator === null || $ratioDenominator === '0') {
            return null;
        }

        for ($degree = 0; $degree < $length; ++$degree) {
            [$baseNumerator, $baseDenominator] = $baseCoefficients[$degree] ?? ['0', '1'];
            [$exponentNumerator, $exponentDenominator] = $exponentCoefficients[$degree] ?? ['0', '1'];
            if ($baseNumerator === '0') {
                if ($exponentNumerator !== '0') {
                    return null;
                }
                continue;
            }
            $left = $integerArithmetic->multiplyIntegerValues(
                $integerArithmetic->multiplyIntegerValues($exponentNumerator, $baseDenominator),
                $ratioDenominator,
            );
            $right = $integerArithmetic->multiplyIntegerValues(
                $ratioNumerator,
                $integerArithmetic->multiplyIntegerValues($exponentDenominator, $baseNumerator),
            );
            if ($integerArithmetic->compareIntegerValues($left, $right) !== 0) {
                return null;
            }
        }

        $ratio = $integerArithmetic->ratio($ratioNumerator, $ratioDenominator);

        return \is_float($ratio) && \is_finite($ratio) && $ratio !== 0.0 ? $ratio : null;
    }

    private function approximatelyProportionalPolynomialRatio(
        array $numerator,
        array $denominator,
    ): ?float {
        $length = \max(\count($numerator), \count($denominator));
        $ratio = null;
        for ($degree = $length - 1; $degree >= 0; --$degree) {
            $denominatorCoefficient = $denominator[$degree] ?? 0.0;
            $numeratorCoefficient = $numerator[$degree] ?? 0.0;
            if ($denominatorCoefficient === 0.0) {
                if ($numeratorCoefficient !== 0.0) {
                    continue;
                }
                continue;
            }
            $ratio = $numeratorCoefficient / $denominatorCoefficient;
            break;
        }
        if ($ratio === null || $ratio === 0.0 || !\is_finite($ratio)) {
            return null;
        }
        for ($degree = 0; $degree < $length; ++$degree) {
            if (
                !$this->approximatelyEqual(
                    $numerator[$degree] ?? 0.0,
                    $ratio * ($denominator[$degree] ?? 0.0),
                )
            ) {
                return null;
            }
        }

        return $ratio;
    }

    /**
     * @return array{array{list<float>, list<float>}, float}|null
     */
    private function rationalExponentialSelfPowerForm(
        FunctionCallNode $exponential,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $factors = [];
        $scale = 1.0;
        if (
            !$this->flattenSelfPowerProductFactors(
                $exponential->arguments[0],
                $extractor,
                $factors,
                $scale,
            )
        ) {
            return null;
        }
        $logarithm = null;
        foreach ($factors as $factor) {
            $factor = $this->unwrapGrouping($factor);
            if (
                $factor instanceof FunctionCallNode
                && $factor->name === 'ln'
                && \count($factor->arguments) === 1
                && $logarithm === null
            ) {
                $logarithm = $factor;
            }
        }
        if (!$logarithm instanceof FunctionCallNode) {
            return null;
        }
        $base = $extractor->extractRationalForm($logarithm->arguments[0]);
        if (
            $base === null
            || \count($base[1]) < 2
            || !$this->containsVariable($logarithm->arguments[0], $variable)
        ) {
            return null;
        }
        $baseFactorFound = false;
        foreach ($factors as $factor) {
            if ($this->unwrapGrouping($factor) === $logarithm) {
                continue;
            }
            $form = $extractor->extractRationalForm($factor);
            if ($form === $base && !$baseFactorFound) {
                $baseFactorFound = true;
                continue;
            }
            if ($form === null || \count($form[0]) !== 1 || \count($form[1]) !== 1) {
                return null;
            }
            $scale *= $form[0][0] / $form[1][0];
        }
        if (!$baseFactorFound || $scale === 0.0 || !\is_finite($scale)) {
            return null;
        }

        return [$base, $scale];
    }

    /**
     * Solve u^(s*u) = target by enumerating the real levels of u.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSelfPowerEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && $this->sameExpression($left->left, $left->right)
            && $this->sameExpression($left->left, $right)
        ) {
            return $this->solveSelfPowerEqualToBase(
                $left->left,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        if (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && $this->sameExpression($right->left, $right->right)
            && $this->sameExpression($right->left, $left)
        ) {
            return $this->solveSelfPowerEqualToBase(
                $right->left,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        $power = null;
        $constant = null;
        $baseCoefficients = null;
        $exponentCoefficients = null;
        $baseHasVariable = false;
        $exponentialForm = false;
        if (
            $left instanceof BinaryOperationNode
            && $left->operator === BinaryOperator::Power
            && !$this->containsVariable($right, $variable)
        ) {
            $power = $left;
            $constant = $right;
        } elseif (
            $right instanceof BinaryOperationNode
            && $right->operator === BinaryOperator::Power
            && !$this->containsVariable($left, $variable)
        ) {
            $power = $right;
            $constant = $left;
        } elseif (
            $left instanceof FunctionCallNode
            && $left->name === 'exp'
            && \count($left->arguments) === 1
            && !$this->containsVariable($right, $variable)
        ) {
            $constant = $right;
            $form = $this->exponentialSelfPowerForm(
                $left,
                $variable,
                $extractor,
            );
            if ($form === null) {
                return null;
            }
            $baseCoefficients = $form['base'];
            $exponentCoefficients = \array_map(
                static fn (float $coefficient): float =>
                    $form['scale'] * $coefficient,
                $form['base'],
            );
            $baseHasVariable = true;
            $exponentialForm = true;
        } elseif (
            $right instanceof FunctionCallNode
            && $right->name === 'exp'
            && \count($right->arguments) === 1
            && !$this->containsVariable($left, $variable)
        ) {
            $constant = $left;
            $form = $this->exponentialSelfPowerForm(
                $right,
                $variable,
                $extractor,
            );
            if ($form === null) {
                return null;
            }
            $baseCoefficients = $form['base'];
            $exponentCoefficients = \array_map(
                static fn (float $coefficient): float =>
                    $form['scale'] * $coefficient,
                $form['base'],
            );
            $baseHasVariable = true;
            $exponentialForm = true;
        } else {
            return null;
        }

        if ($power instanceof BinaryOperationNode) {
            $baseCoefficients = $this->extractPolynomial(
                $extractor,
                $power->left,
                $power->left->span()->start,
            );
            $exponentCoefficients = $this->extractPolynomial(
                $extractor,
                $power->right,
                $power->right->span()->start,
            );
            $baseHasVariable = $this->containsVariable($power->left, $variable);
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        $exponentScale = null;
        if ($baseCoefficients !== null && $exponentCoefficients !== null) {
            foreach ($baseCoefficients as $degree => $coefficient) {
                if ($coefficient !== 0.0) {
                    $exponentScale = ($exponentCoefficients[$degree] ?? 0.0) / $coefficient;
                    break;
                }
            }
            if (
                $exponentScale === null
                || $exponentScale === 0.0
                || !\is_finite($exponentScale)
            ) {
                $exponentScale = null;
            } else {
                $maximumDegree = \max(\count($baseCoefficients), \count($exponentCoefficients));
                for ($degree = 0; $degree < $maximumDegree; ++$degree) {
                    if (
                        !$this->approximatelyEqual(
                            $exponentCoefficients[$degree] ?? 0.0,
                            $exponentScale * ($baseCoefficients[$degree] ?? 0.0),
                        )
                    ) {
                        $exponentScale = null;
                        break;
                    }
                }
            }
            if ($power instanceof BinaryOperationNode) {
                $exactScale = $this->exactPolynomialScale(
                    $power->left,
                    $power->right,
                    $variable,
                    $parameters,
                    $options,
                    $evaluationOptions,
                );
                if ($exactScale !== null) {
                    $exponentScale = $exactScale;
                }
            }
        }
        if (
            $baseCoefficients === null
            || $exponentScale === null
            || !$baseHasVariable
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
        ) {
            return null;
        }

        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }
        $equationTarget = $target;
        if ($exponentScale === -1.0) {
            if ($target === 0.0) {
                return [];
            }
            $target = 1.0 / $target;
            if (!\is_finite($target)) {
                return null;
            }
        }

        if (\count($baseCoefficients) === 1) {
            $probe = $lowerBound + (($upperBound - $lowerBound) / 2.0);
            $residual = $residualAt($probe);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $probe,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }

        $range = $this->polynomialRange(
            $baseCoefficients,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($range === null) {
            return null;
        }
        if ($exponentialForm && $range[0] <= 0.0) {
            return null;
        }
        if ($exponentScale !== 1.0 && $exponentScale !== -1.0) {
            if ($range[0] <= 0.0) {
                return null;
            }
            if ($target <= 0.0) {
                return [];
            }
            $target = \exp(\log($target) / $exponentScale);
            if ($target === 0.0 || !\is_finite($target)) {
                return [];
            }
        }

        $levels = [];
        if ($target > 0.0) {
            $logTarget = \log($target);
            $branchPoint = -1.0 / \M_E;
            $branchTarget = \exp($branchPoint);
            $scaledBranchTarget = \exp(-$exponentScale / \M_E);
            $hasPositiveBaseLevels = true;
            if (\is_finite($scaledBranchTarget) && $scaledBranchTarget > 0.0) {
                $targetOffset = $equationTarget - $scaledBranchTarget;
                $constantNode = $this->unwrapGrouping($constant);
                $exponentialTarget = $constantNode instanceof FunctionCallNode
                    && $constantNode->name === 'exp'
                    && \count($constantNode->arguments) === 1;
                $targetTolerance = 8.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($equationTarget), \abs($scaledBranchTarget));
                if ($targetOffset === 0.0 || ($exponentialTarget && \abs($targetOffset) <= $targetTolerance)) {
                    $levels[] = 1.0 / \M_E;
                    $hasPositiveBaseLevels = false;
                } elseif (
                    ($exponentScale > 0.0 && $targetOffset < 0.0)
                    || ($exponentScale < 0.0 && $targetOffset > 0.0)
                ) {
                    $hasPositiveBaseLevels = false;
                } else {
                    $logTarget = $branchPoint
                        + (\log1p($targetOffset / $scaledBranchTarget) / $exponentScale);
                }
                if ($equationTarget === 1.0) {
                    $logTarget = 0.0;
                }
            } elseif ($target < $branchTarget) {
                $hasPositiveBaseLevels = false;
            } elseif ($target === $branchTarget) {
                $levels[] = 1.0 / \M_E;
            }
            if ($levels === [] && $hasPositiveBaseLevels && $logTarget < 0.0) {
                $levels[] = $this->bisectSelfPowerLogLevel(
                    $logTarget,
                    0.0,
                    1.0 / \M_E,
                    decreasing: true,
                );
                $levels[] = $this->bisectSelfPowerLogLevel(
                    $logTarget,
                    1.0 / \M_E,
                    1.0,
                    decreasing: false,
                );
            } elseif ($levels === [] && $hasPositiveBaseLevels && $logTarget === 0.0) {
                $levels[] = 1.0;
            } elseif ($levels === [] && $hasPositiveBaseLevels && $logTarget > 0.0) {
                $upperLevel = \max(2.0, $logTarget + 2.0);
                while (
                    $upperLevel * \log($upperLevel) < $logTarget
                    && \is_finite($upperLevel * 2.0)
                ) {
                    $upperLevel *= 2.0;
                }
                if (!\is_finite($upperLevel * \log($upperLevel))) {
                    return null;
                }
                $levels[] = $this->bisectSelfPowerLogLevel(
                    $logTarget,
                    1.0,
                    $upperLevel,
                    decreasing: false,
                );
            }
        }

        if ($target === 1.0 && $range[0] <= 0.0 && $range[1] >= 0.0) {
            $levels[] = 0.0;
        }

        $minimumExactInteger = -9_007_199_254_740_991.0;
        $firstNegativeInteger = \max(\ceil($range[0]), $minimumExactInteger);
        $lastNegativeInteger = \min(\floor($range[1]), -1.0);
        if ($firstNegativeInteger <= $lastNegativeInteger) {
            $negativeLevelCount = $lastNegativeInteger - $firstNegativeInteger + 1.0;
            if ($negativeLevelCount > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                return null;
            }
            for (
                $integerLevel = (int) $firstNegativeInteger;
                $integerLevel <= (int) $lastNegativeInteger;
                ++$integerLevel
            ) {
                $value = \pow((float) $integerLevel, (float) $integerLevel);
                if (
                    \is_finite($value)
                    && \abs($value - $target)
                        <= $options->residualTolerance * \max(1.0, \abs($value), \abs($target))
                ) {
                    $levels[] = (float) $integerLevel;
                }
            }
        }

        $levels = \array_values(\array_unique($levels, SORT_REGULAR));
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ($levels as $level) {
            $levelCoefficients = $baseCoefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $polynomialResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
            $polynomialResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
            $candidates = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $options,
                $polynomialResidualScaleAt,
            );
            if ($candidates === null) {
                return null;
            }
            $candidates = $polynomialSolver->recoverRepeatedRoots(
                $levelCoefficients,
                $candidates,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $polynomialResidualScaleAt,
                $options,
            );
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve u^u = u by reducing to the only real levels u = -1 and u = 1.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSelfPowerEqualToBase(
        Node $base,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $coefficients = $this->extractPolynomial($extractor, $base, $base->span()->start);
        if ($coefficients === null || \count($coefficients) < 2) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ([-1.0, 1.0] as $level) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $level;
            $levelResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
            $levelScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
            $candidates = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                $levelResidualAt,
                $options,
                $levelScaleAt,
            );
            if ($candidates === null) {
                return null;
            }
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if ($residual === null || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return array{base: list<float>, scale: float}|null
     */
    private function exponentialSelfPowerForm(
        FunctionCallNode $exponential,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $factors = [];
        $scale = 1.0;
        if (
            !$this->flattenSelfPowerProductFactors(
                $exponential->arguments[0],
                $extractor,
                $factors,
                $scale,
            )
        ) {
            return null;
        }
        $logarithm = null;
        foreach ($factors as $factor) {
            $factor = $this->unwrapGrouping($factor);
            if (
                $factor instanceof FunctionCallNode
                && $factor->name === 'ln'
                && \count($factor->arguments) === 1
                && $logarithm === null
            ) {
                $logarithm = $factor;
            }
        }
        if (!$logarithm instanceof FunctionCallNode) {
            return null;
        }

        $base = $this->extractPolynomial(
            $extractor,
            $logarithm->arguments[0],
            $logarithm->arguments[0]->span()->start,
        );
        if (
            $base === null
            || \count($base) === 1
            || !$this->containsVariable($logarithm->arguments[0], $variable)
        ) {
            return null;
        }

        $baseFactorFound = false;
        foreach ($factors as $factor) {
            if ($this->unwrapGrouping($factor) === $logarithm) {
                continue;
            }
            $coefficients = $this->extractPolynomial(
                $extractor,
                $factor,
                $factor->span()->start,
            );
            if ($coefficients === $base && !$baseFactorFound) {
                $baseFactorFound = true;
                continue;
            }
            if ($coefficients === null || \count($coefficients) !== 1) {
                return null;
            }
            $scale *= $coefficients[0];
        }
        if (!$baseFactorFound || $scale === 0.0 || !\is_finite($scale)) {
            return null;
        }

        return ['base' => $base, 'scale' => $scale];
    }

    /** @param list<Node> $factors */
    private function flattenSelfPowerProductFactors(
        Node $node,
        PolynomialExtractor $extractor,
        array &$factors,
        float &$scale,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            if ($node->operator === UnaryOperator::Minus) {
                $scale = -$scale;
            }

            return $this->flattenSelfPowerProductFactors(
                $node->operand,
                $extractor,
                $factors,
                $scale,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Multiply
        ) {
            return $this->flattenSelfPowerProductFactors(
                $node->left,
                $extractor,
                $factors,
                $scale,
            ) && $this->flattenSelfPowerProductFactors(
                $node->right,
                $extractor,
                $factors,
                $scale,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Divide
        ) {
            $denominator = $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            );
            if ($denominator === null || \count($denominator) !== 1) {
                $factors[] = $node;

                return true;
            }
            if ($denominator[0] === 0.0) {
                return false;
            }
            $scale /= $denominator[0];
            if (!\is_finite($scale)) {
                return false;
            }

            return $this->flattenSelfPowerProductFactors(
                $node->left,
                $extractor,
                $factors,
                $scale,
            );
        }

        $factors[] = $node;

        return true;
    }

    private function bisectSelfPowerLogLevel(
        float $target,
        float $lower,
        float $upper,
        bool $decreasing,
    ): float {
        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $middle = $lower + (($upper - $lower) / 2.0);
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            $value = $middle === 0.0 ? 0.0 : $middle * \log($middle);
            if (($value < $target) !== $decreasing) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return $lower + (($upper - $lower) / 2.0);
    }

    private function dawsonMaximumArgument(): float
    {
        $lower = 0.0;
        $upper = 2.0;
        for ($iteration = 0; $iteration < 64; ++$iteration) {
            $middle = $lower + (($upper - $lower) / 2.0);
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            $derivative = 1.0 - (2.0 * $middle * SpecialFunctions::dawson($middle));
            if ($derivative > 0.0) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return $lower + (($upper - $lower) / 2.0);
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveConstantPowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $irrationalPowerSolutions = $this->solveIrrationalConstantPowerEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($irrationalPowerSolutions !== null) {
            return $irrationalPowerSolutions;
        }

        $rootPowerSolutions = $this->solveSingleRationalRootPolynomialEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($rootPowerSolutions !== null) {
            return $rootPowerSolutions;
        }

        $multipleCubeRootSumSolutions = $this->solveMultipleCubeRootSumEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($multipleCubeRootSumSolutions !== null) {
            return $multipleCubeRootSumSolutions;
        }

        $threeCubeRootSumSolutions = $this->solveThreeCubeRootSumEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($threeCubeRootSumSolutions !== null) {
            return $threeCubeRootSumSolutions;
        }

        $mixedRadicalSumSolutions = $this->solveSquareCubeRootSumEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($mixedRadicalSumSolutions !== null) {
            return $mixedRadicalSumSolutions;
        }

        $cubeRootSumSolutions = $this->solveCubeRootSumEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($cubeRootSumSolutions !== null) {
            return $cubeRootSumSolutions;
        }

        $squareRootSumSolutions = $this->solveSquareRootSumEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($squareRootSumSolutions !== null) {
            return $squareRootSumSolutions;
        }

        $sharedBasePowerSolutions = $this->solveAdditiveSharedBaseRationalPowers(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($sharedBasePowerSolutions !== null) {
            return $sharedBasePowerSolutions;
        }

        $additiveRationalPowerSolutions = $this->solveAdditiveRationalPowerEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightSourceOffset,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($additiveRationalPowerSolutions !== null) {
            return $additiveRationalPowerSolutions;
        }

        $squareRootProductSolutions = $this->solveSquareRootProductEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($squareRootProductSolutions !== null) {
            return $squareRootProductSolutions;
        }

        $rationalPowerSolutions = $this->solveRationalPowerPolynomialEquation(
            $left,
            $right,
            $leftSource,
            $rightSource,
            $rightSourceOffset,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
            $residualAt,
            $candidateScaleAt,
        );
        if ($rationalPowerSolutions !== null) {
            return $rationalPowerSolutions;
        }

        $leftPower = $this->unwrapGrouping($left);
        $rightPower = $this->unwrapGrouping($right);
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $right,
            $right->span()->start,
        );
        if (
            $leftPower instanceof BinaryOperationNode
            && $leftPower->operator === BinaryOperator::Power
            && $targetCoefficients !== null
            && \count($targetCoefficients) === 1
        ) {
            $power = $leftPower;
            $baseSource = $leftSource;
            $baseSourceOffset = 0;
            $target = $targetCoefficients[0];
        } elseif (
            $rightPower instanceof BinaryOperationNode
            && $rightPower->operator === BinaryOperator::Power
            && ($targetCoefficients = $this->extractPolynomial(
                $extractor,
                $left,
                $left->span()->start,
            )) !== null
            && \count($targetCoefficients) === 1
        ) {
            $power = $rightPower;
            $baseSource = $rightSource;
            $baseSourceOffset = $rightSourceOffset;
            $target = $targetCoefficients[0];
        } else {
            return null;
        }

        $exponent = $this->extractPolynomial(
            $extractor,
            $power->right,
            $power->right->span()->start,
        );
        if (
            $exponent === null
            || \count($exponent) !== 1
            || $exponent[0] === 0.0
            || !$this->containsVariable($power->left, $variable)
        ) {
            return null;
        }
        $powerExponent = \abs($exponent[0]);
        $exactExponent = RationalLiteral::fromNode($power->right);
        $fractionalOddDenominator = $exactExponent !== null
            && $exactExponent[1] > 1
            && $exactExponent[1] % 2 !== 0;
        $fractionalOddNumerator = $exactExponent !== null
            && \abs($exactExponent[0]) % 2 !== 0;
        $targetIsNegative = $target < 0.0;
        $logMagnitude = $target === 0.0 ? -\INF : \log(\abs($target));
        if ($exponent[0] < 0.0) {
            if ($target === 0.0) {
                return [];
            }
            $logMagnitude = -$logMagnitude;
        }

        $terms = [];
        $constant = 0.0;
        $flattened = $this->flattenAdditiveExpression(
            $power->left,
            $baseSource,
            $baseSourceOffset,
            $variable,
            $extractor,
            1.0,
            $terms,
            $constant,
        );
        if (!$flattened || $terms === []) {
            return null;
        }
        $integerExponent = \floor($powerExponent) === $powerExponent;
        if (!$integerExponent && !$fractionalOddDenominator && $targetIsNegative) {
            return [];
        }
        $solutions = [];
        if ($integerExponent && \fmod($powerExponent, 2.0) === 0.0 && $targetIsNegative) {
            return [];
        }
        if ($target === 0.0) {
            $levels = [0.0];
        } else {
            $magnitude = \exp($logMagnitude / $powerExponent);
            if (!\is_finite($magnitude) || $magnitude === 0.0) {
                return null;
            }
            if ($integerExponent && \fmod($powerExponent, 2.0) === 1.0) {
                $levels = [$targetIsNegative ? -$magnitude : $magnitude];
            } elseif ($integerExponent && !$targetIsNegative) {
                $levels = [$magnitude, -$magnitude];
            } elseif ($fractionalOddDenominator) {
                if ($fractionalOddNumerator) {
                    $levels = [$targetIsNegative ? -$magnitude : $magnitude];
                } elseif ($targetIsNegative) {
                    return [];
                } else {
                    $levels = [$magnitude, -$magnitude];
                }
            } else {
                $levels = [$magnitude];
            }
        }
        foreach ($levels as $level) {
            $baseEquation = '(' . \implode('+', $terms) . ')='
                . \sprintf('%.17g', $level - $constant);
            if (\strlen($baseEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $baseSolutions = $this->solve(
                $baseEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($baseSolutions as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $solverOptions,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Eliminate four through six cube roots with polynomial radicands. The quotient
     * basis is capped at 243 elements; candidates are checked against the source
     * equation to remove complex branches introduced by the norms.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveMultipleCubeRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicands = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $radicand = $this->polynomialScaledCubeRootRadicand(
                $node,
                $sign,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($radicand !== null) {
                $radicands[] = $radicand;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        /** @var list<list<float>> $radicandRepresentatives */
        $radicandRepresentatives = [];
        /** @var list<float> $radicalScales */
        $radicalScales = [];
        foreach ($radicands as $radicand) {
            $matchedIndex = null;
            foreach ($radicandRepresentatives as $index => $representative) {
                $ratio = $this->proportionalPolynomialScale($radicand, $representative);
                if ($ratio === null) {
                    continue;
                }
                $scale = $ratio < 0.0
                    ? -\pow(-$ratio, 1.0 / 3.0)
                    : \pow($ratio, 1.0 / 3.0);
                if (!\is_finite($scale) || $scale * $scale * $scale !== $ratio) {
                    continue;
                }
                $radicalScales[$index] += $scale;
                $matchedIndex = $index;
                break;
            }
            if ($matchedIndex === null) {
                $radicandRepresentatives[] = $radicand;
                $radicalScales[] = 1.0;
            }
        }
        $distinctRadicands = [];
        foreach ($radicandRepresentatives as $index => $representative) {
            $scale = $radicalScales[$index];
            if ($scale === 0.0) {
                continue;
            }
            $scaledRadicand = $this->scalePolynomialCoefficients(
                $representative,
                $scale * $scale * $scale,
            );
            if ($scaledRadicand === null) {
                return null;
            }
            $distinctRadicands[] = $scaledRadicand;
        }
        $radicands = $distinctRadicands;

        if (
            \count($radicands) < 4
            || \count($radicands) > self::MAX_CUBE_ROOT_RESULTANT_TERMS
        ) {
            return null;
        }

        $maxDegree = $solverOptions->maxPolynomialDegree;
        $target = $this->scalePolynomialCoefficients($remainder, -1.0);
        if ($target === null) {
            return null;
        }
        $firstRadicands = \array_slice($radicands, 0, -1);
        $targetResidue = [0 => $target];
        foreach ($firstRadicands as $index => $_radicand) {
            $targetResidue[3 ** $index] = [-1.0];
        }
        $targetSquared = $this->multiplyCubeRootMultivariateResidues(
            $targetResidue,
            $targetResidue,
            $firstRadicands,
            $maxDegree,
        );
        $targetCubed = $targetSquared === null
            ? null
            : $this->multiplyCubeRootMultivariateResidues(
                $targetSquared,
                $targetResidue,
                $firstRadicands,
                $maxDegree,
            );
        $polynomial = $targetCubed === null
            ? null
            : $this->combineCubeRootMultivariateResidues(
                $targetCubed,
                [0 => $radicands[3]],
                -1.0,
            );
        if ($polynomial === null) {
            return null;
        }
        for ($index = \count($radicands) - 2; $index >= 0; --$index) {
            $polynomial = $this->cubeRootMultivariateNorm(
                $polynomial,
                $radicands[$index],
                \array_slice($radicands, 0, $index),
                $maxDegree,
            );
            if ($polynomial === null) {
                return null;
            }
        }
        $resultantCoefficients = $polynomial[0] ?? null;
        if ($resultantCoefficients === null) {
            return null;
        }
        if (\count($resultantCoefficients) === 1) {
            return $resultantCoefficients[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $resultantCoefficients,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($resultantCoefficients, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null || $candidates === []) {
            return null;
        }
        $candidates = $polynomialSolver->recoverRepeatedRoots(
            $resultantCoefficients,
            $candidates,
            $lowerBound,
            $upperBound,
            $residualAt,
            $candidateScaleAt,
            $solverOptions,
        );

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * Eliminate three cube roots with polynomial radicands through nested norms.
     * Resultant roots are checked against the original equation because the
     * algebraic norms include non-real cube-root branches.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveThreeCubeRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicands = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $radicand = $this->polynomialScaledCubeRootRadicand(
                $node,
                $sign,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($radicand !== null) {
                if (\count($radicands) >= 3) {
                    return null;
                }
                $radicands[] = $radicand;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if (\count($radicands) !== 3) {
            return null;
        }

        [$firstRadicand, $secondRadicand, $thirdRadicand] = $radicands;
        $maxDegree = $solverOptions->maxPolynomialDegree;
        $target = $this->scalePolynomialCoefficients($remainder, -1.0);
        if ($target === null) {
            return null;
        }
        $targetResidue = [$target, [-1.0], [0.0]];
        $targetSquared = $this->multiplyCubeRootResidues(
            $targetResidue,
            $targetResidue,
            $secondRadicand,
            $maxDegree,
        );
        $targetCubed = $targetSquared === null
            ? null
            : $this->multiplyCubeRootResidues(
                $targetSquared,
                $targetResidue,
                $secondRadicand,
                $maxDegree,
            );
        $firstAndThirdSum = $this->combinePolynomialCoefficients(
            $firstRadicand,
            $thirdRadicand,
            1.0,
        );
        // For T = target - v, reduce (T - u)^3 - thirdRadicand using u^3 = firstRadicand.
        $g0 = $targetCubed === null || $firstAndThirdSum === null
            ? null
            : $this->combineCubeRootResidues(
                $targetCubed,
                [$firstAndThirdSum, [0.0], [0.0]],
                -1.0,
            );
        $g1 = $targetSquared === null
            ? null
            : $this->scaleCubeRootResidue($targetSquared, -3.0);
        $g2 = $this->scaleCubeRootResidue($targetResidue, 3.0);
        if ($g0 === null || $g1 === null || $g2 === null) {
            return null;
        }
        $g0Squared = $this->multiplyCubeRootResidues($g0, $g0, $secondRadicand, $maxDegree);
        $g0Cubed = $g0Squared === null
            ? null
            : $this->multiplyCubeRootResidues($g0Squared, $g0, $secondRadicand, $maxDegree);
        $g1Squared = $this->multiplyCubeRootResidues($g1, $g1, $secondRadicand, $maxDegree);
        $g1Cubed = $g1Squared === null
            ? null
            : $this->multiplyCubeRootResidues($g1Squared, $g1, $secondRadicand, $maxDegree);
        $g2Squared = $this->multiplyCubeRootResidues(
            $g2,
            $g2,
            $secondRadicand,
            $maxDegree,
        );
        $g2Cubed = $g2Squared === null
            ? null
            : $this->multiplyCubeRootResidues($g2Squared, $g2, $secondRadicand, $maxDegree);
        $firstRadicandSquared = $this->multiplyPolynomialCoefficients(
            $firstRadicand,
            $firstRadicand,
            $maxDegree,
        );
        $firstRadicandTimesG1Cubed = $g1Cubed === null
            ? null
            : $this->multiplyCubeRootResidueByPolynomial(
                $g1Cubed,
                $firstRadicand,
                $maxDegree,
            );
        $firstRadicandSquaredTimesG2Cubed = $g2Cubed === null || $firstRadicandSquared === null
            ? null
            : $this->multiplyCubeRootResidueByPolynomial(
                $g2Cubed,
                $firstRadicandSquared,
                $maxDegree,
            );
        $g0g1 = $this->multiplyCubeRootResidues($g0, $g1, $secondRadicand, $maxDegree);
        $g0g1g2 = $g0g1 === null
            ? null
            : $this->multiplyCubeRootResidues($g0g1, $g2, $secondRadicand, $maxDegree);
        $firstRadicandTimesG0g1g2 = $g0g1g2 === null
            ? null
            : $this->multiplyCubeRootResidueByPolynomial(
                $g0g1g2,
                $firstRadicand,
                $maxDegree,
            );
        $lastNormTerm = $firstRadicandTimesG0g1g2 === null
            ? null
            : $this->scaleCubeRootResidue($firstRadicandTimesG0g1g2, -3.0);
        $firstNorm = $g0Cubed === null || $firstRadicandTimesG1Cubed === null
            ? null
            : $this->combineCubeRootResidues($g0Cubed, $firstRadicandTimesG1Cubed, 1.0);
        $firstNorm = $firstNorm === null || $firstRadicandSquaredTimesG2Cubed === null
            ? null
            : $this->combineCubeRootResidues(
                $firstNorm,
                $firstRadicandSquaredTimesG2Cubed,
                1.0,
            );
        $firstNorm = $firstNorm === null || $lastNormTerm === null
            ? null
            : $this->combineCubeRootResidues($firstNorm, $lastNormTerm, 1.0);
        if ($firstNorm === null) {
            return null;
        }

        // Take the remaining norm in v, where v^3 = secondRadicand.
        $h0 = $firstNorm[0];
        $h1 = $firstNorm[1];
        $h2 = $firstNorm[2];
        $h0Squared = $this->multiplyPolynomialCoefficients($h0, $h0, $maxDegree);
        $h0Cubed = $h0Squared === null
            ? null
            : $this->multiplyPolynomialCoefficients($h0Squared, $h0, $maxDegree);
        $h1Squared = $this->multiplyPolynomialCoefficients($h1, $h1, $maxDegree);
        $h1Cubed = $h1Squared === null
            ? null
            : $this->multiplyPolynomialCoefficients($h1Squared, $h1, $maxDegree);
        $secondRadicandTimesH1Cubed = $h1Cubed === null
            ? null
            : $this->multiplyPolynomialCoefficients($secondRadicand, $h1Cubed, $maxDegree);
        $h2Squared = $this->multiplyPolynomialCoefficients($h2, $h2, $maxDegree);
        $h2Cubed = $h2Squared === null
            ? null
            : $this->multiplyPolynomialCoefficients($h2Squared, $h2, $maxDegree);
        $secondRadicandSquared = $this->multiplyPolynomialCoefficients(
            $secondRadicand,
            $secondRadicand,
            $maxDegree,
        );
        $secondRadicandSquaredTimesH2Cubed = $secondRadicandSquared === null || $h2Cubed === null
            ? null
            : $this->multiplyPolynomialCoefficients(
                $secondRadicandSquared,
                $h2Cubed,
                $maxDegree,
            );
        $h0h1 = $this->multiplyPolynomialCoefficients($h0, $h1, $maxDegree);
        $h0h1h2 = $h0h1 === null
            ? null
            : $this->multiplyPolynomialCoefficients($h0h1, $h2, $maxDegree);
        $secondRadicandTimesTriple = $h0h1h2 === null
            ? null
            : $this->multiplyPolynomialCoefficients($secondRadicand, $h0h1h2, $maxDegree);
        $lastTerm = $secondRadicandTimesTriple === null
            ? null
            : $this->scalePolynomialCoefficients($secondRadicandTimesTriple, -3.0);
        $polynomial = $h0Cubed === null || $secondRadicandTimesH1Cubed === null
            ? null
            : $this->combinePolynomialCoefficients($h0Cubed, $secondRadicandTimesH1Cubed, 1.0);
        $polynomial = $polynomial === null || $secondRadicandSquaredTimesH2Cubed === null
            ? null
            : $this->combinePolynomialCoefficients(
                $polynomial,
                $secondRadicandSquaredTimesH2Cubed,
                1.0,
            );
        $polynomial = $polynomial === null || $lastTerm === null
            ? null
            : $this->combinePolynomialCoefficients($polynomial, $lastTerm, 1.0);
        if ($polynomial === null) {
            return null;
        }
        while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)] === 0.0) {
            \array_pop($polynomial);
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0] === 0.0 ? null : [];
        }

        $leadingDegree = \count($polynomial) - 1;
        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $leadingMagnitude = \abs($polynomial[$leadingDegree]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumRatio = 0.0;
            foreach ($polynomial as $degree => $coefficient) {
                if ($degree === $leadingDegree) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + 16.0 * \PHP_FLOAT_EPSILON));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
            $searchLowerBound = \is_finite($lowerBound)
                ? \max($lowerBound, -$rootBound)
                : -$rootBound;
            $searchUpperBound = \is_finite($upperBound)
                ? \min($upperBound, $rootBound)
                : $rootBound;
            if ($searchLowerBound > $searchUpperBound) {
                return [];
            }
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $searchLowerBound,
                $searchUpperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null || $candidates === []) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * @param array<int, list<float>> $left
     * @param array<int, list<float>> $right
     * @param list<list<float>> $radicands
     * @return array<int, list<float>>|null
     */
    private function multiplyCubeRootMultivariateResidues(
        array $left,
        array $right,
        array $radicands,
        int $maxDegree,
    ): ?array {
        $product = [];
        foreach ($left as $leftBasis => $leftCoefficient) {
            foreach ($right as $rightBasis => $rightCoefficient) {
                $coefficient = $this->multiplyPolynomialCoefficients(
                    $leftCoefficient,
                    $rightCoefficient,
                    $maxDegree,
                );
                if ($coefficient === null) {
                    return null;
                }
                $leftDigits = $leftBasis;
                $rightDigits = $rightBasis;
                $basis = 0;
                $stride = 1;
                foreach ($radicands as $radicand) {
                    $power = ($leftDigits % 3) + ($rightDigits % 3);
                    $leftDigits = \intdiv($leftDigits, 3);
                    $rightDigits = \intdiv($rightDigits, 3);
                    if ($power >= 3) {
                        $coefficient = $this->multiplyPolynomialCoefficients(
                            $coefficient,
                            $radicand,
                            $maxDegree,
                        );
                        if ($coefficient === null) {
                            return null;
                        }
                        $power -= 3;
                    }
                    $basis += $power * $stride;
                    $stride *= 3;
                }
                $sum = isset($product[$basis])
                    ? $this->combinePolynomialCoefficients($product[$basis], $coefficient, 1.0)
                    : $coefficient;
                if ($sum === null) {
                    return null;
                }
                $product[$basis] = $sum;
            }
        }

        return $product;
    }

    /**
     * @param array<int, list<float>> $left
     * @param array<int, list<float>> $right
     * @return array<int, list<float>>|null
     */
    private function combineCubeRootMultivariateResidues(
        array $left,
        array $right,
        float $rightScale,
    ): ?array {
        $sum = [];
        foreach (\array_unique([...\array_keys($left), ...\array_keys($right)]) as $basis) {
            $coefficient = $this->combinePolynomialCoefficients(
                $left[$basis] ?? [0.0],
                $right[$basis] ?? [0.0],
                $rightScale,
            );
            if ($coefficient === null) {
                return null;
            }
            $sum[$basis] = $coefficient;
        }

        return $sum;
    }

    /**
     * @param array<int, list<float>> $residue
     * @param list<float> $polynomial
     * @return array<int, list<float>>|null
     */
    private function multiplyCubeRootMultivariateResidueByPolynomial(
        array $residue,
        array $polynomial,
        int $maxDegree,
    ): ?array {
        $product = [];
        foreach ($residue as $basis => $coefficient) {
            $productCoefficient = $this->multiplyPolynomialCoefficients(
                $coefficient,
                $polynomial,
                $maxDegree,
            );
            if ($productCoefficient === null) {
                return null;
            }
            $product[$basis] = $productCoefficient;
        }

        return $product;
    }

    /**
     * Take the norm over the last cube-root generator in a residue ring.
     *
     * @param array<int, list<float>> $residue
     * @param list<float> $radicand
     * @param list<list<float>> $remainingRadicands
     * @return array<int, list<float>>|null
     */
    private function cubeRootMultivariateNorm(
        array $residue,
        array $radicand,
        array $remainingRadicands,
        int $maxDegree,
    ): ?array {
        $stride = 3 ** \count($remainingRadicands);
        $parts = [[0 => [0.0]], [0 => [0.0]], [0 => [0.0]]];
        foreach ($residue as $basis => $coefficient) {
            $power = \intdiv($basis, $stride);
            $parts[$power][$basis % $stride] = $coefficient;
        }

        $part0Squared = $this->multiplyCubeRootMultivariateResidues(
            $parts[0],
            $parts[0],
            $remainingRadicands,
            $maxDegree,
        );
        $part0Cubed = $part0Squared === null
            ? null
            : $this->multiplyCubeRootMultivariateResidues(
                $part0Squared,
                $parts[0],
                $remainingRadicands,
                $maxDegree,
            );
        $part1Squared = $this->multiplyCubeRootMultivariateResidues(
            $parts[1],
            $parts[1],
            $remainingRadicands,
            $maxDegree,
        );
        $part1Cubed = $part1Squared === null
            ? null
            : $this->multiplyCubeRootMultivariateResidues(
                $part1Squared,
                $parts[1],
                $remainingRadicands,
                $maxDegree,
            );
        $part1Term = $part1Cubed === null
            ? null
            : $this->multiplyCubeRootMultivariateResidueByPolynomial(
                $part1Cubed,
                $radicand,
                $maxDegree,
            );
        $part2Squared = $this->multiplyCubeRootMultivariateResidues(
            $parts[2],
            $parts[2],
            $remainingRadicands,
            $maxDegree,
        );
        $part2Cubed = $part2Squared === null
            ? null
            : $this->multiplyCubeRootMultivariateResidues(
                $part2Squared,
                $parts[2],
                $remainingRadicands,
                $maxDegree,
            );
        $radicandSquared = $this->multiplyPolynomialCoefficients(
            $radicand,
            $radicand,
            $maxDegree,
        );
        $part2Term = $part2Cubed === null || $radicandSquared === null
            ? null
            : $this->multiplyCubeRootMultivariateResidueByPolynomial(
                $part2Cubed,
                $radicandSquared,
                $maxDegree,
            );
        $part01 = $this->multiplyCubeRootMultivariateResidues(
            $parts[0],
            $parts[1],
            $remainingRadicands,
            $maxDegree,
        );
        $part012 = $part01 === null
            ? null
            : $this->multiplyCubeRootMultivariateResidues(
                $part01,
                $parts[2],
                $remainingRadicands,
                $maxDegree,
            );
        $tripleTerm = $part012 === null
            ? null
            : $this->multiplyCubeRootMultivariateResidueByPolynomial(
                $part012,
                $radicand,
                $maxDegree,
            );
        $tripleTerm = $tripleTerm === null
            ? null
            : $this->scaleCubeRootMultivariateResidue($tripleTerm, -3.0);

        $norm = $part0Cubed === null || $part1Term === null
            ? null
            : $this->combineCubeRootMultivariateResidues($part0Cubed, $part1Term, 1.0);
        $norm = $norm === null || $part2Term === null
            ? null
            : $this->combineCubeRootMultivariateResidues($norm, $part2Term, 1.0);

        return $norm === null || $tripleTerm === null
            ? null
            : $this->combineCubeRootMultivariateResidues($norm, $tripleTerm, 1.0);
    }

    /**
     * @param array<int, list<float>> $residue
     * @return array<int, list<float>>|null
     */
    private function scaleCubeRootMultivariateResidue(array $residue, float $scale): ?array
    {
        $scaled = [];
        foreach ($residue as $basis => $coefficient) {
            $scaledCoefficient = $this->scalePolynomialCoefficients($coefficient, $scale);
            if ($scaledCoefficient === null) {
                return null;
            }
            $scaled[$basis] = $scaledCoefficient;
        }

        return $scaled;
    }

    /**
     * @param array{list<float>, list<float>, list<float>} $left
     * @param array{list<float>, list<float>, list<float>} $right
     * @param list<float> $radicand
     * @return array{list<float>, list<float>, list<float>}|null
     */
    private function multiplyCubeRootResidues(
        array $left,
        array $right,
        array $radicand,
        int $maxDegree,
    ): ?array {
        $product = [[0.0], [0.0], [0.0]];
        foreach ($left as $leftPower => $leftCoefficient) {
            foreach ($right as $rightPower => $rightCoefficient) {
                $coefficient = $this->multiplyPolynomialCoefficients(
                    $leftCoefficient,
                    $rightCoefficient,
                    $maxDegree,
                );
                if ($coefficient === null) {
                    return null;
                }
                $power = $leftPower + $rightPower;
                if ($power >= 3) {
                    $coefficient = $this->multiplyPolynomialCoefficients(
                        $coefficient,
                        $radicand,
                        $maxDegree,
                    );
                    if ($coefficient === null) {
                        return null;
                    }
                    $power -= 3;
                }
                $combined = $this->combinePolynomialCoefficients(
                    $product[$power],
                    $coefficient,
                    1.0,
                );
                if ($combined === null) {
                    return null;
                }
                $product[$power] = $combined;
            }
        }

        return $product;
    }

    /**
     * @param array{list<float>, list<float>, list<float>} $left
     * @param array{list<float>, list<float>, list<float>} $right
     * @return array{list<float>, list<float>, list<float>}|null
     */
    private function combineCubeRootResidues(array $left, array $right, float $rightScale): ?array
    {
        $sum = $left;
        for ($power = 0; $power < 3; ++$power) {
            $coefficient = $this->combinePolynomialCoefficients(
                $left[$power],
                $right[$power],
                $rightScale,
            );
            if ($coefficient === null) {
                return null;
            }
            $sum[$power] = $coefficient;
        }

        return $sum;
    }

    /**
     * @param array{list<float>, list<float>, list<float>} $residue
     * @return array{list<float>, list<float>, list<float>}|null
     */
    private function scaleCubeRootResidue(array $residue, float $scale): ?array
    {
        $scaled = [];
        foreach ($residue as $coefficient) {
            $scaledCoefficient = $this->scalePolynomialCoefficients($coefficient, $scale);
            if ($scaledCoefficient === null) {
                return null;
            }
            $scaled[] = $scaledCoefficient;
        }

        return $scaled;
    }

    /**
     * @param array{list<float>, list<float>, list<float>} $residue
     * @param list<float> $polynomial
     * @return array{list<float>, list<float>, list<float>}|null
     */
    private function multiplyCubeRootResidueByPolynomial(
        array $residue,
        array $polynomial,
        int $maxDegree,
    ): ?array {
        $product = [];
        foreach ($residue as $coefficient) {
            $scaledCoefficient = $this->multiplyPolynomialCoefficients(
                $coefficient,
                $polynomial,
                $maxDegree,
            );
            if ($scaledCoefficient === null) {
                return null;
            }
            $product[] = $scaledCoefficient;
        }

        return $product;
    }

    /**
     * Eliminate one square root and one cube root with polynomial radicands.
     * Candidates are checked against the original equation to reject branches
     * introduced by eliminating the square root.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSquareCubeRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $squareRadicand = null;
        $cubeRadicand = null;
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $squareRadicandTerm = $this->polynomialScaledSquareRootRadicand(
                $node,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($squareRadicandTerm !== null) {
                if ($squareRadicand !== null) {
                    return null;
                }
                $squareRadicand = $squareRadicandTerm;
                continue;
            }

            $cubeRadicandTerm = $this->polynomialScaledCubeRootRadicand(
                $node,
                $sign,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($cubeRadicandTerm !== null) {
                if ($cubeRadicand !== null) {
                    return null;
                }
                $cubeRadicand = $cubeRadicandTerm;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($squareRadicand === null || $cubeRadicand === null) {
            return null;
        }

        $maxDegree = $solverOptions->maxPolynomialDegree;
        $target = $this->scalePolynomialCoefficients($remainder, -1.0);
        $targetSquared = $target === null
            ? null
            : $this->multiplyPolynomialCoefficients($target, $target, $maxDegree);
        $targetCubed = $targetSquared === null || $target === null
            ? null
            : $this->multiplyPolynomialCoefficients($targetSquared, $target, $maxDegree);
        $targetTimesSquareRadicand = $target === null
            ? null
            : $this->multiplyPolynomialCoefficients($target, $squareRadicand, $maxDegree);
        $threeTargetTimesSquareRadicand = $targetTimesSquareRadicand === null
            ? null
            : $this->scalePolynomialCoefficients($targetTimesSquareRadicand, 3.0);
        $constantPart = $targetCubed === null || $threeTargetTimesSquareRadicand === null
            ? null
            : $this->combinePolynomialCoefficients(
                $targetCubed,
                $threeTargetTimesSquareRadicand,
                1.0,
            );
        $constantPart = $constantPart === null
            ? null
            : $this->combinePolynomialCoefficients($constantPart, $cubeRadicand, -1.0);

        $threeTargetSquared = $targetSquared === null
            ? null
            : $this->scalePolynomialCoefficients($targetSquared, 3.0);
        $linearPart = $threeTargetSquared === null
            ? null
            : $this->combinePolynomialCoefficients($threeTargetSquared, $squareRadicand, 1.0);
        $constantPartSquared = $constantPart === null
            ? null
            : $this->multiplyPolynomialCoefficients($constantPart, $constantPart, $maxDegree);
        $linearPartSquared = $linearPart === null
            ? null
            : $this->multiplyPolynomialCoefficients($linearPart, $linearPart, $maxDegree);
        $radicandTimesLinearSquare = $linearPartSquared === null
            ? null
            : $this->multiplyPolynomialCoefficients(
                $squareRadicand,
                $linearPartSquared,
                $maxDegree,
            );
        $polynomial = $constantPartSquared === null || $radicandTimesLinearSquare === null
            ? null
            : $this->combinePolynomialCoefficients(
                $constantPartSquared,
                $radicandTimesLinearSquare,
                -1.0,
            );
        if ($polynomial === null) {
            return null;
        }
        while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)] === 0.0) {
            \array_pop($polynomial);
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0] === 0.0 ? null : [];
        }

        $leadingDegree = \count($polynomial) - 1;
        $searchLowerBound = $lowerBound;
        $searchUpperBound = $upperBound;
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $leadingMagnitude = \abs($polynomial[$leadingDegree]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumRatio = 0.0;
            foreach ($polynomial as $degree => $coefficient) {
                if ($degree === $leadingDegree) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + 16.0 * \PHP_FLOAT_EPSILON));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
            $searchLowerBound = \is_finite($lowerBound)
                ? \max($lowerBound, -$rootBound)
                : -$rootBound;
            $searchUpperBound = \is_finite($upperBound)
                ? \min($upperBound, $rootBound)
                : $rootBound;
            if ($searchLowerBound > $searchUpperBound) {
                return [];
            }
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $searchLowerBound,
                $searchUpperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null || $candidates === []) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * Reduce products of two rational roots by raising them to a common power.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalRootProductEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $boundaries = [$lowerBound, $upperBound];
        foreach ([[$left, $right], [$right, $left]] as [$product]) {
            $factors = [];
            $this->flattenProductFactors($product, $factors);
            foreach ($factors as $factor) {
                $radical = $this->polynomialScaledRationalRootTerm(
                    $factor,
                    $variable,
                    $extractor,
                    $solverOptions->maxPolynomialDegree,
                    true,
                );
                if ($radical === null) {
                    continue;
                }
                $base = $this->unwrapGrouping($radical[0]);
                if (
                    !$base instanceof FunctionCallNode
                    || $base->name !== 'abs'
                    || count($base->arguments) !== 1
                ) {
                    continue;
                }
                $form = $extractor->extractRationalForm($base->arguments[0]);
                if ($form === null) {
                    return null;
                }
                foreach ($form as $polynomial) {
                    $roots = $this->solvePolynomialRootsInInterval(
                        $polynomial,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($roots === null) {
                        return null;
                    }
                    foreach ($roots as $root) {
                        if ($root->value > $lowerBound && $root->value < $upperBound) {
                            $boundaries[] = $root->value;
                        }
                    }
                }
            }
        }

        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
        $hasAbsoluteRootBase = \count($boundaries) > 2;
        if (!$hasAbsoluteRootBase) {
            $sample = $lowerBound + (($upperBound - $lowerBound) / 2.0);

            return $this->solveRationalRootProductOnBranch(
                $left,
                $right,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
                $sample,
            );
        }

        $solutions = [];
        $recognizedBranch = false;
        for ($index = 0; $index < \count($boundaries) - 1; ++$index) {
            $branchLower = $boundaries[$index];
            $branchUpper = $boundaries[$index + 1];
            if ($branchLower >= $branchUpper) {
                continue;
            }
            $sample = $branchLower + (($branchUpper - $branchLower) / 2.0);
            if ($sample === $branchLower || $sample === $branchUpper) {
                continue;
            }
            $branchSolutions = $this->solveRationalRootProductOnBranch(
                $left,
                $right,
                $variable,
                $extractor,
                $branchLower,
                $branchUpper,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
                $sample,
            );
            if ($branchSolutions === null) {
                return null;
            }
            $recognizedBranch = true;
            foreach ($branchSolutions as $solution) {
                $this->addSolution($solutions, $solution, $solverOptions);
            }
        }
        if (!$recognizedBranch) {
            return null;
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Prove infinite crossings when an exponential decays against a recurring periodic range.
     *
     * @param array<string, int|float> $parameters
     */
    private function hasInfiniteRootsFromDecayingExponentialAgainstPeriodicTarget(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        foreach ([[$left, $right], [$right, $left]] as [$exponentialSide, $periodicSide]) {
            $exponential = $this->unwrapGrouping($exponentialSide);
            if (
                !$exponential instanceof FunctionCallNode
                || $exponential->name !== 'exp'
                || \count($exponential->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn('exp')
            ) {
                continue;
            }
            $exponent = $this->extractPolynomial(
                $extractor,
                $exponential->arguments[0],
                $exponential->arguments[0]->span()->start,
            );
            if ($exponent === null || \count($exponent) < 2) {
                continue;
            }
            $degree = \count($exponent) - 1;
            $leadingCoefficient = $exponent[$degree];
            $decaysAtNegativeInfinity = $lowerBound === -\INF
                && (($degree % 2 === 0 ? 1.0 : -1.0) * $leadingCoefficient) < 0.0;
            $decaysAtPositiveInfinity = $upperBound === \INF && $leadingCoefficient < 0.0;
            if (!$decaysAtNegativeInfinity && !$decaysAtPositiveInfinity) {
                continue;
            }

            $periodic = $this->extractAffinePeriodicTarget(
                $periodicSide,
                $variable,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if (
                $periodic !== null
                && $periodic['isPeriodic']
                && $periodic['minimum'] <= 0.0
                && $periodic['maximum'] > 0.0
            ) {
                return true;
            }
            if (
                $this->hasInfinitelyManyRootsFromCommensurateTrigonometricSum(
                    $periodicSide,
                    $exponentialSide,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $extractor,
                    0.0,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{
     *     minimum: float,
     *     maximum: float,
     *     isPeriodic: bool,
     *     harmonic: true,
     *     phaseKey: string,
     *     offset: float,
     *     sineCoefficient: float,
     *     cosineCoefficient: float
     * }|array{
     *     minimum: float,
     *     maximum: float,
     *     isPeriodic: bool,
     *     harmonic: false
     * }|null
     */
    private function extractAffinePeriodicTarget(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode && \in_array($node->name, ['sin', 'cos', 'tan', 'cot'], true)) {
            if (
                \count($node->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($node->name)
            ) {
                return null;
            }
            $phase = $this->extractPolynomial(
                $extractor,
                $node->arguments[0],
                $node->arguments[0]->span()->start,
            );

            if ($phase === null || \count($phase) < 2) {
                return null;
            }

            if (\in_array($node->name, ['tan', 'cot'], true)) {
                return [
                    'minimum' => -\INF,
                    'maximum' => \INF,
                    'isPeriodic' => true,
                    'harmonic' => false,
                ];
            }

            return $this->periodicHarmonicEnvelope(
                0.0,
                $node->name === 'sin' ? 1.0 : 0.0,
                $node->name === 'cos' ? 1.0 : 0.0,
                \serialize($phase),
            );
        }
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'abs'
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('abs')
        ) {
            $components = $this->extractAffinePeriodicTarget(
                $node->arguments[0],
                $variable,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($components === null) {
                return null;
            }
            if (!$components['isPeriodic']) {
                return [
                    'minimum' => \abs($components['minimum']),
                    'maximum' => \abs($components['maximum']),
                    'isPeriodic' => false,
                    'harmonic' => false,
                ];
            }
            $minimum = $components['minimum'] <= 0.0 && $components['maximum'] >= 0.0
                ? 0.0
                : \min(\abs($components['minimum']), \abs($components['maximum']));

            return [
                'minimum' => $minimum,
                'maximum' => \max(\abs($components['minimum']), \abs($components['maximum'])),
                'isPeriodic' => true,
                'harmonic' => false,
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            $components = $this->extractAffinePeriodicTarget(
                $node->operand,
                $variable,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($components === null || $node->operator === UnaryOperator::Plus) {
                return $components;
            }

            if ($components['harmonic']) {
                return $this->periodicHarmonicEnvelope(
                    -$components['offset'],
                    -$components['sineCoefficient'],
                    -$components['cosineCoefficient'],
                    $components['phaseKey'],
                );
            }

            return [
                'minimum' => -$components['maximum'],
                'maximum' => -$components['minimum'],
                'isPeriodic' => $components['isPeriodic'],
                'harmonic' => false,
            ];
        }
        if ($node instanceof BinaryOperationNode) {
            $left = $this->extractAffinePeriodicTarget(
                $node->left,
                $variable,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            $right = $this->extractAffinePeriodicTarget(
                $node->right,
                $variable,
                $extractor,
                $parameters,
                $evaluationOptions,
            );
            if ($left === null || $right === null) {
                return null;
            }
            $leftIsPeriodic = $left['isPeriodic'];
            $rightIsPeriodic = $right['isPeriodic'];
            if (\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                if ($leftIsPeriodic && $rightIsPeriodic) {
                    if (
                        $left['harmonic']
                        && $right['harmonic']
                        && $left['phaseKey'] === $right['phaseKey']
                    ) {
                        $direction = $node->operator === BinaryOperator::Subtract ? -1.0 : 1.0;

                        return $this->periodicHarmonicEnvelope(
                            $left['offset'] + ($direction * $right['offset']),
                            $left['sineCoefficient'] + ($direction * $right['sineCoefficient']),
                            $left['cosineCoefficient'] + ($direction * $right['cosineCoefficient']),
                            $left['phaseKey'],
                        );
                    }

                    return null;
                }
                if ($leftIsPeriodic) {
                    $rightConstant = $right['minimum'];
                    $direction = $node->operator === BinaryOperator::Subtract ? -1.0 : 1.0;
                    if ($left['harmonic']) {
                        return $this->periodicHarmonicEnvelope(
                            $left['offset'] + ($direction * $rightConstant),
                            $left['sineCoefficient'],
                            $left['cosineCoefficient'],
                            $left['phaseKey'],
                        );
                    }
                    return [
                        'minimum' => $left['minimum'] + ($direction * $rightConstant),
                        'maximum' => $left['maximum'] + ($direction * $rightConstant),
                        'isPeriodic' => true,
                        'harmonic' => false,
                    ];
                }
                if ($rightIsPeriodic && $node->operator === BinaryOperator::Subtract) {
                    if ($right['harmonic']) {
                        return $this->periodicHarmonicEnvelope(
                            $left['minimum'] - $right['offset'],
                            -$right['sineCoefficient'],
                            -$right['cosineCoefficient'],
                            $right['phaseKey'],
                        );
                    }
                    return [
                        'minimum' => $left['minimum'] - $right['maximum'],
                        'maximum' => $left['minimum'] - $right['minimum'],
                        'isPeriodic' => true,
                        'harmonic' => false,
                    ];
                }
                if ($rightIsPeriodic) {
                    if ($right['harmonic']) {
                        return $this->periodicHarmonicEnvelope(
                            $left['minimum'] + $right['offset'],
                            $right['sineCoefficient'],
                            $right['cosineCoefficient'],
                            $right['phaseKey'],
                        );
                    }
                    return [
                        'minimum' => $left['minimum'] + $right['minimum'],
                        'maximum' => $left['minimum'] + $right['maximum'],
                        'isPeriodic' => true,
                        'harmonic' => false,
                    ];
                }

                return [
                    'minimum' => $node->operator === BinaryOperator::Subtract
                        ? $left['minimum'] - $right['minimum']
                        : $left['minimum'] + $right['minimum'],
                    'maximum' => $node->operator === BinaryOperator::Subtract
                        ? $left['maximum'] - $right['maximum']
                        : $left['maximum'] + $right['maximum'],
                    'isPeriodic' => false,
                    'harmonic' => false,
                ];
            }
            if ($node->operator === BinaryOperator::Multiply) {
                if (!$leftIsPeriodic && !$rightIsPeriodic) {
                    return [
                        'minimum' => $left['minimum'] * $right['minimum'],
                        'maximum' => $left['maximum'] * $right['maximum'],
                        'isPeriodic' => false,
                        'harmonic' => false,
                    ];
                }
                if ($leftIsPeriodic && $rightIsPeriodic) {
                    return null;
                }
                $periodic = $leftIsPeriodic ? $left : $right;
                $constant = $leftIsPeriodic ? $right['minimum'] : $left['minimum'];
                if ($constant === 0.0) {
                    return [
                        'minimum' => 0.0,
                        'maximum' => 0.0,
                        'isPeriodic' => false,
                        'harmonic' => false,
                    ];
                }
                if ($periodic['harmonic']) {
                    return $this->periodicHarmonicEnvelope(
                        $periodic['offset'] * $constant,
                        $periodic['sineCoefficient'] * $constant,
                        $periodic['cosineCoefficient'] * $constant,
                        $periodic['phaseKey'],
                    );
                }
                $products = [
                    $periodic['minimum'] * $constant,
                    $periodic['maximum'] * $constant,
                ];

                return [
                    'minimum' => \min($products),
                    'maximum' => \max($products),
                    'isPeriodic' => true,
                    'harmonic' => false,
                ];
            }
            if ($node->operator === BinaryOperator::Power && $leftIsPeriodic && !$rightIsPeriodic) {
                $power = $right['minimum'];
                if ($power < 1.0 || $power > 64.0 || \floor($power) !== $power) {
                    return null;
                }
                $lowerPower = \pow($left['minimum'], $power);
                $upperPower = \pow($left['maximum'], $power);
                if (\is_nan($lowerPower) || \is_nan($upperPower)) {
                    return null;
                }
                if ((int) $power % 2 === 0) {
                    $minimumPower = $left['minimum'] <= 0.0 && $left['maximum'] >= 0.0
                        ? 0.0
                        : \min($lowerPower, $upperPower);
                    $maximumPower = \max($lowerPower, $upperPower);
                } else {
                    $minimumPower = $lowerPower;
                    $maximumPower = $upperPower;
                }

                return [
                    'minimum' => $minimumPower,
                    'maximum' => $maximumPower,
                    'isPeriodic' => true,
                    'harmonic' => false,
                ];
            }
        }

        $constant = $this->constantNodeValue($node, $parameters, $evaluationOptions);
        if ($constant !== null && \is_finite($constant)) {
            return [
                'minimum' => (float) $constant,
                'maximum' => (float) $constant,
                'isPeriodic' => false,
                'harmonic' => false,
            ];
        }

        return null;
    }

    /**
     * Invert a variable-independent non-rational power exponent on its real
     * domain. Such powers require a positive base unless the exponent is an
     * exact rational literal, which is handled by the rational-power solvers.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveIrrationalConstantPowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $orientations = [
            [$this->unwrapGrouping($left), $leftSource, $right],
            [$this->unwrapGrouping($right), $rightSource, $left],
        ];
        foreach ($orientations as [$power, $powerSource, $target]) {
            if (
                !$power instanceof BinaryOperationNode
                || $power->operator !== BinaryOperator::Power
                || $this->containsVariable($power->right, $variable)
                || (
                    !$this->containsVariable($power->left, $variable)
                    && !$this->containsImplicitVariableProduct(
                        $power->left,
                        $variable,
                        $evaluationOptions,
                    )
                )
                || RationalLiteral::fromNode($power->right) !== null
            ) {
                continue;
            }
            $exponentCoefficients = $this->extractPolynomial(
                $extractor,
                $power->right,
                $power->right->span()->start,
            );
            if (
                $exponentCoefficients === null
                || \count($exponentCoefficients) !== 1
                || !\is_finite($exponentCoefficients[0])
                || $exponentCoefficients[0] === 0.0
                || \floor($exponentCoefficients[0]) === $exponentCoefficients[0]
            ) {
                continue;
            }
            $baseSpan = $power->left->span();
            $baseSource = \substr(
                $powerSource,
                $baseSpan->start,
                $baseSpan->end - $baseSpan->start,
            );
            if ($baseSource === '') {
                return null;
            }
            if ($this->sameExpression($power->left, $target)) {
                $baseLevels = $exponentCoefficients[0] > 0.0 ? [0.0, 1.0] : [1.0];
                $solutions = [];
                foreach ($baseLevels as $baseLevel) {
                    try {
                        $levelCandidates = $this->solve(
                            '(' . $baseSource . ')=' . \sprintf('%.17g', $baseLevel),
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (InfiniteSolutionSetException | \DomainException) {
                        return null;
                    }
                    foreach ($levelCandidates as $candidate) {
                        $residual = $residualAt($candidate->value);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution(
                                $candidate->value,
                                \abs($residual),
                                $candidate->iterations,
                            ),
                            $solverOptions,
                        );
                    }
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }

            $targetCoefficients = $this->extractPolynomial(
                $extractor,
                $target,
                $target->span()->start,
            );
            if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
                continue;
            }
            $targetValue = $targetCoefficients[0];
            $exponent = $exponentCoefficients[0];
            if ($targetValue < 0.0 || ($targetValue === 0.0 && $exponent < 0.0)) {
                return [];
            }
            $baseTarget = $targetValue === 0.0
                ? 0.0
                : \exp(\log($targetValue) / $exponent);
            if (
                !\is_finite($baseTarget)
                || ($targetValue > 0.0 && $baseTarget === 0.0)
            ) {
                return null;
            }

            $transformedEquation = '(' . $baseSource . ')='
                . \sprintf('%.17g', $baseTarget);
            if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                $candidates = $this->solve(
                    $transformedEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (InfiniteSolutionSetException $exception) {
                throw $exception;
            } catch (\DomainException) {
                return null;
            }

            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $solverOptions,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * @return array{
     *     minimum: float,
     *     maximum: float,
     *     isPeriodic: bool,
     *     harmonic: true,
     *     phaseKey: string,
     *     offset: float,
     *     sineCoefficient: float,
     *     cosineCoefficient: float
     * }
     */
    private function periodicHarmonicEnvelope(
        float $offset,
        float $sineCoefficient,
        float $cosineCoefficient,
        string $phaseKey,
    ): array {
        $amplitude = \hypot($sineCoefficient, $cosineCoefficient);

        return [
            'minimum' => $offset - $amplitude,
            'maximum' => $offset + $amplitude,
            'isPeriodic' => $amplitude !== 0.0,
            'harmonic' => true,
            'phaseKey' => $phaseKey,
            'offset' => $offset,
            'sineCoefficient' => $sineCoefficient,
            'cosineCoefficient' => $cosineCoefficient,
        ];
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalRootProductOnBranch(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
        float $branchSample,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$product, $target]) {
            $factors = [];
            $this->flattenProductFactors($product, $factors);
            $radicals = [];
            $scaleNumerator = [1.0];
            $scaleDenominator = [1.0];
            foreach ($factors as $factor) {
                $radical = $this->polynomialScaledRationalRootTerm(
                    $factor,
                    $variable,
                    $extractor,
                    $solverOptions->maxPolynomialDegree,
                    true,
                );
                if ($radical !== null) {
                    [$baseNode, $coefficient, $degree, $numerator] = $radical;
                    $base = $this->rationalRootRadicandForm(
                        $baseNode,
                        $extractor,
                        $branchSample,
                    );
                    $coefficientPower = $this->powerPolynomialCoefficients(
                        $coefficient,
                        $degree,
                        $solverOptions->maxPolynomialDegree,
                    );
                    if (
                        $base === null
                        || $coefficientPower === null
                    ) {
                        continue 2;
                    }
                    $baseNumerator = [1.0];
                    $baseDenominator = [1.0];
                    for ($power = 0; $power < \abs($numerator); ++$power) {
                        $baseNumerator = $this->multiplyPolynomialCoefficients(
                            $baseNumerator,
                            $base[0],
                            $solverOptions->maxPolynomialDegree,
                        );
                        $baseDenominator = $this->multiplyPolynomialCoefficients(
                            $baseDenominator,
                            $base[1],
                            $solverOptions->maxPolynomialDegree,
                        );
                        if ($baseNumerator === null || $baseDenominator === null) {
                            continue 2;
                        }
                    }
                    if ($numerator < 0) {
                        [$baseNumerator, $baseDenominator] = [
                            $baseDenominator,
                            $baseNumerator,
                        ];
                    }
                    $baseNumerator = $this->multiplyPolynomialCoefficients(
                        $baseNumerator,
                        $coefficientPower,
                        $solverOptions->maxPolynomialDegree,
                    );
                    if ($baseNumerator === null) {
                        continue 2;
                    }
                    $radicals[] = [
                        'numerator' => $baseNumerator,
                        'denominator' => $baseDenominator,
                        'degree' => $degree,
                    ];
                    continue;
                }

                $scaleForm = $extractor->extractRationalForm($factor);
                if ($scaleForm === null) {
                    continue 2;
                }
                $scaleNumerator = $this->multiplyPolynomialCoefficients(
                    $scaleNumerator,
                    $scaleForm[0],
                    $solverOptions->maxPolynomialDegree,
                );
                $scaleDenominator = $this->multiplyPolynomialCoefficients(
                    $scaleDenominator,
                    $scaleForm[1],
                    $solverOptions->maxPolynomialDegree,
                );
                if ($scaleNumerator === null || $scaleDenominator === null) {
                    continue 2;
                }
            }
            if (
                \count($radicals) < 2
                || (\count($scaleNumerator) === 1 && $scaleNumerator[0] === 0.0)
            ) {
                continue;
            }

            $targetForm = $extractor->extractRationalForm($target);
            if ($targetForm === null) {
                continue;
            }
            $commonDegree = 1;
            foreach ($radicals as $radical) {
                $gcd = $this->positiveIntegerGcd($commonDegree, $radical['degree']);
                $multiple = intdiv($radical['degree'], $gcd);
                if ($commonDegree > intdiv(\PHP_INT_MAX, $multiple)) {
                    continue 2;
                }
                $commonDegree *= $multiple;
                if ($commonDegree > $solverOptions->maxPolynomialDegree) {
                    continue 2;
                }
            }

            $radicandNumerator = [1.0];
            $radicandDenominator = [1.0];
            foreach ($radicals as $radical) {
                $power = intdiv($commonDegree, $radical['degree']);
                for ($index = 0; $index < $power; ++$index) {
                    $radicandNumerator = $this->multiplyPolynomialCoefficients(
                        $radicandNumerator,
                        $radical['numerator'],
                        $solverOptions->maxPolynomialDegree,
                    );
                    $radicandDenominator = $this->multiplyPolynomialCoefficients(
                        $radicandDenominator,
                        $radical['denominator'],
                        $solverOptions->maxPolynomialDegree,
                    );
                    if ($radicandNumerator === null || $radicandDenominator === null) {
                        continue 3;
                    }
                }
            }
            $scaleNumeratorPower = $this->powerPolynomialCoefficients(
                $scaleNumerator,
                $commonDegree,
                $solverOptions->maxPolynomialDegree,
            );
            $scaleDenominatorPower = $this->powerPolynomialCoefficients(
                $scaleDenominator,
                $commonDegree,
                $solverOptions->maxPolynomialDegree,
            );
            if ($scaleNumeratorPower === null || $scaleDenominatorPower === null) {
                continue;
            }
            $radicandNumerator = $this->multiplyPolynomialCoefficients(
                $radicandNumerator,
                $scaleNumeratorPower,
                $solverOptions->maxPolynomialDegree,
            );
            $radicandDenominator = $this->multiplyPolynomialCoefficients(
                $radicandDenominator,
                $scaleDenominatorPower,
                $solverOptions->maxPolynomialDegree,
            );
            if ($radicandNumerator === null || $radicandDenominator === null) {
                continue;
            }

            $targetNumeratorPower = [1.0];
            $targetDenominatorPower = [1.0];
            for ($index = 0; $index < $commonDegree; ++$index) {
                $targetNumeratorPower = $this->multiplyPolynomialCoefficients(
                    $targetNumeratorPower,
                    $targetForm[0],
                    $solverOptions->maxPolynomialDegree,
                );
                $targetDenominatorPower = $this->multiplyPolynomialCoefficients(
                    $targetDenominatorPower,
                    $targetForm[1],
                    $solverOptions->maxPolynomialDegree,
                );
                if ($targetNumeratorPower === null || $targetDenominatorPower === null) {
                    continue 2;
                }
            }
            $leftProduct = $this->multiplyPolynomialCoefficients(
                $radicandNumerator,
                $targetDenominatorPower,
                $solverOptions->maxPolynomialDegree,
            );
            $rightProduct = $this->multiplyPolynomialCoefficients(
                $targetNumeratorPower,
                $radicandDenominator,
                $solverOptions->maxPolynomialDegree,
            );
            $polynomial = $leftProduct === null || $rightProduct === null
                ? null
                : $this->combinePolynomialCoefficients($leftProduct, $rightProduct, -1.0);
            if ($polynomial === null) {
                continue;
            }
            if (\count($polynomial) === 1) {
                if ($polynomial[0] !== 0.0) {
                    return [];
                }
                continue;
            }

            $polynomialSolver = new PolynomialSolver();
            try {
                $candidates = $polynomialSolver->solve(
                    $polynomial,
                    $lowerBound,
                    $upperBound,
                    static fn (float $value): ?float =>
                        $polynomialSolver->evaluatePolynomial($polynomial, $value),
                    $solverOptions,
                );
            } catch (\DomainException) {
                continue;
            }
            if ($candidates === null) {
                continue;
            }

            $solutions = [];
            foreach ($candidates as $candidate) {
                $value = $candidate->value;
                $residual = $residualAt($value);
                if ($residual === null) {
                    continue;
                }
                $value = $this->refineVerifiedEquationCandidate(
                    $value,
                    $residual,
                    $residualAt,
                    $candidate->value,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                $residual = $residualAt($value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($value, \abs($residual), $candidate->iterations),
                    $solverOptions,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /** @param list<Node> $factors */
    private function flattenProductFactors(Node $node, array &$factors): void
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            $this->flattenProductFactors($node->left, $factors);
            $this->flattenProductFactors($node->right, $factors);

            return;
        }

        $factors[] = $node;
    }

    /**
     * Eliminate small sums of rational-root terms through a quotient-algebra norm.
     * The source equation filters branches introduced by even root degrees.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSmallRationalRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        /** @var list<array{degree: int, defining: list<float>}> $radicals */
        $radicals = [];
        /** @var list<array{base: list<float>, coefficient: list<float>, degree: int, numerator: int}> $radicalGroups */
        $radicalGroups = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $term = $this->polynomialScaledRationalRootTerm(
                $node,
                $variable,
                $extractor,
                $options->maxPolynomialDegree,
            );
            if ($term === null) {
                $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
                if ($polynomial === null) {
                    return null;
                }
                $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
                if ($remainder === null) {
                    return null;
                }
                continue;
            }
            [$baseNode, $coefficient, $degree, $numerator] = $term;
            if (
                $degree < 2
                || $degree > $options->maxPolynomialDegree
                || $numerator < 1
                || $numerator > $options->maxPolynomialDegree
            ) {
                return null;
            }
            $base = $this->extractPolynomial($extractor, $baseNode, $baseNode->span()->start);
            if ($base === null) {
                return null;
            }
            $base = $this->trimPolynomialCoefficients($base);
            $groupIndex = null;
            /** @var array{base: list<float>, coefficient: list<float>, degree: int, numerator: int}|null $matchedGroup */
            $matchedGroup = null;
            foreach ($radicalGroups as $index => $group) {
                if (
                    $group['base'] === $base
                    && $group['degree'] === $degree
                    && $group['numerator'] === $numerator
                ) {
                    $groupIndex = $index;
                    $matchedGroup = $group;
                    break;
                }
            }
            if ($groupIndex === null) {
                $signedCoefficient = $this->scalePolynomialCoefficients($coefficient, $sign);
                if ($signedCoefficient === null) {
                    return null;
                }
                $radicalGroups[] = [
                    'base' => $base,
                    'coefficient' => $signedCoefficient,
                    'degree' => $degree,
                    'numerator' => $numerator,
                ];
            } else {
                if ($matchedGroup === null) {
                    return null;
                }
                $combinedCoefficient = $this->combinePolynomialCoefficients(
                    $matchedGroup['coefficient'],
                    $coefficient,
                    $sign,
                );
                if ($combinedCoefficient === null) {
                    return null;
                }
                $radicalGroups[$groupIndex] = [
                    'base' => $matchedGroup['base'],
                    'coefficient' => $combinedCoefficient,
                    'degree' => $matchedGroup['degree'],
                    'numerator' => $matchedGroup['numerator'],
                ];
            }
        }

        foreach ($radicalGroups as $group) {
            if (\count($group['coefficient']) === 1 && $group['coefficient'][0] === 0.0) {
                continue;
            }
            $coefficientPower = [1.0];
            for ($power = 0; $power < $group['degree']; ++$power) {
                $coefficientPower = $this->multiplyPolynomialCoefficients(
                    $coefficientPower,
                    $group['coefficient'],
                    $options->maxPolynomialDegree,
                );
                if ($coefficientPower === null) {
                    return null;
                }
            }
            $radicandPower = [1.0];
            for ($power = 0; $power < $group['numerator']; ++$power) {
                $radicandPower = $this->multiplyPolynomialCoefficients(
                    $radicandPower,
                    $group['base'],
                    $options->maxPolynomialDegree,
                );
                if ($radicandPower === null) {
                    return null;
                }
            }
            $definingPolynomial = $this->multiplyPolynomialCoefficients(
                $coefficientPower,
                $radicandPower,
                $options->maxPolynomialDegree,
            );
            if ($definingPolynomial === null) {
                return null;
            }
            $radicals[] = ['degree' => $group['degree'], 'defining' => $definingPolynomial];
        }
        if (\count($radicals) < 3 || \count($radicals) > 5) {
            return null;
        }
        \usort($radicals, static fn (array $a, array $b): int => $a['degree'] <=> $b['degree']);
        $last = \array_pop($radicals);
        $basisRadicals = $radicals;
        $basisDegrees = \array_column($basisRadicals, 'degree');
        $lastDegree = $last['degree'];
        $dimension = 1;
        foreach ($basisDegrees as $degree) {
            $dimension *= $degree;
        }
        $expansionTermCount = 1;
        $basisCount = \count($basisDegrees);
        for ($index = 1; $index <= $basisCount; ++$index) {
            $expansionTermCount = \intdiv(
                $expansionTermCount * ($lastDegree + $index),
                $index,
            );
            if ($expansionTermCount > self::MAX_SMALL_ROOT_EXPANSION_TERMS) {
                return null;
            }
        }
        if (
            $dimension > 16
            || \array_sum($basisDegrees) + $lastDegree > self::MAX_SMALL_ROOT_TOTAL_DEGREE
        ) {
            return null;
        }
        $maxDegree = $options->maxPolynomialDegree;
        /** @var list<list<float>> $remainderPowers */
        $remainderPowers = [[1.0]];
        for ($index = 1; $index <= $lastDegree; ++$index) {
            $next = $this->multiplyPolynomialCoefficients(
                $remainderPowers[$index - 1],
                $remainder,
                $maxDegree,
            );
            if ($next === null) {
                return null;
            }
            $remainderPowers[] = $next;
        }
        /** @var list<list<list<float>>> $basisPowers */
        $basisPowers = [];
        foreach ($basisRadicals as $basisIndex => $basisRadical) {
            $powers = [[1.0]];
            for ($index = 1; $index <= intdiv($lastDegree, $basisDegrees[$basisIndex]); ++$index) {
                $next = $this->multiplyPolynomialCoefficients(
                    $powers[$index - 1],
                    $basisRadical['defining'],
                    $maxDegree,
                );
                if ($next === null) {
                    return null;
                }
                $powers[] = $next;
            }
            $basisPowers[] = $powers;
        }

        /** @var array<int, list<float>|null> $element */
        $element = [];
        $factorial = [1.0];
        for ($index = 1; $index <= $lastDegree; ++$index) {
            $factorial[$index] = $factorial[$index - 1] * $index;
        }
        foreach ($this->boundedRootExponentTuples(\count($basisDegrees), $lastDegree) as $powers) {
            $remainderPower = $lastDegree - \array_sum($powers);
            $multinomialDenominator = $factorial[$remainderPower];
            foreach ($powers as $power) {
                $multinomialDenominator *= $factorial[$power];
            }
            $multinomial = $factorial[$lastDegree] / $multinomialDenominator;
            $term = $this->scalePolynomialCoefficients(
                $remainderPowers[$remainderPower],
                $multinomial * ((-1.0) ** $lastDegree),
            );
            if ($term === null) {
                return null;
            }
            $index = 0;
            foreach ($powers as $basisIndex => $power) {
                $reduction = intdiv($power, $basisDegrees[$basisIndex]);
                if ($reduction > 0) {
                    $term = $this->multiplyPolynomialCoefficients(
                        $term,
                        $basisPowers[$basisIndex][$reduction],
                        $maxDegree,
                    );
                    if ($term === null) {
                        return null;
                    }
                }
                $index = ($index * $basisDegrees[$basisIndex]) + ($power % $basisDegrees[$basisIndex]);
            }
            $element[$index] = isset($element[$index])
                ? $this->combinePolynomialCoefficients($element[$index], $term, 1.0)
                : $term;
            if ($element[$index] === null) {
                return null;
            }
        }
        $element[0] = $this->combinePolynomialCoefficients($element[0] ?? [0.0], $last['defining'], -1.0);
        if ($element[0] === null) {
            return null;
        }

        /** @var list<list<list<float>>> $matrix */
        $matrix = \array_fill(0, $dimension, \array_fill(0, $dimension, [0.0]));
        $basisTuples = $this->completeRootBasisTuples($basisDegrees);
        if (\count($basisTuples) !== $dimension) {
            return null;
        }
        foreach ($element as $elementIndex => $coefficient) {
            if ($coefficient === null) {
                return null;
            }
            $elementExponents = $basisTuples[$elementIndex] ?? null;
            if ($elementExponents === null) {
                return null;
            }
            foreach ($basisTuples as $column => $basisExponents) {
                $reduced = $coefficient;
                $row = 0;
                foreach ($basisExponents as $basisIndex => $basisExponent) {
                    $power = $elementExponents[$basisIndex] + $basisExponent;
                    $reduction = intdiv($power, $basisDegrees[$basisIndex]);
                    if ($reduction > 0) {
                        $reduced = $this->multiplyPolynomialCoefficients(
                            $reduced,
                            $basisPowers[$basisIndex][$reduction],
                            $maxDegree,
                        );
                        if ($reduced === null) {
                            return null;
                        }
                    }
                    $row = ($row * $basisDegrees[$basisIndex])
                        + ($power % $basisDegrees[$basisIndex]);
                }
                $matrixEntry = $this->combinePolynomialCoefficients(
                    $matrix[$row][$column],
                    $reduced,
                    1.0,
                );
                if ($matrixEntry === null) {
                    return null;
                }
                $matrix[$row][$column] = $matrixEntry;
            }
        }

        $determinants = [0 => [1.0]];
        $fullMask = (1 << $dimension) - 1;
        for ($row = 0; $row < $dimension; ++$row) {
            $next = [];
            foreach ($determinants as $mask => $partial) {
                for ($column = 0; $column < $dimension; ++$column) {
                    $bit = 1 << $column;
                    if (($mask & $bit) !== 0) {
                        continue;
                    }
                    $product = $this->multiplyPolynomialCoefficients(
                        $partial,
                        $matrix[$row][$column],
                        $maxDegree,
                    );
                    if ($product === null) {
                        return null;
                    }
                    if ((\substr_count(\decbin($mask >> ($column + 1)), '1') % 2) !== 0) {
                        $product = $this->scalePolynomialCoefficients($product, -1.0);
                        if ($product === null) {
                            return null;
                        }
                    }
                    $nextMask = $mask | $bit;
                    $next[$nextMask] = isset($next[$nextMask])
                        ? $this->combinePolynomialCoefficients($next[$nextMask], $product, 1.0)
                        : $product;
                    if ($next[$nextMask] === null) {
                        return null;
                    }
                }
            }
            $determinants = $next;
        }
        $polynomial = $determinants[$fullMask] ?? null;
        if ($polynomial === null) {
            return null;
        }
        while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)] === 0.0) {
            \array_pop($polynomial);
        }
        if (\count($polynomial) === 1) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $candidates = $polynomialSolver->solve(
            $polynomial,
            $lowerBound,
            $upperBound,
            static fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($polynomial, $value),
            $options,
        );
        if ($candidates === null) {
            return null;
        }
        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if ($residual === null) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $candidate->value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $options,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $options)
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $options,
            );
        }
        \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);
        if (\count($solutions) > 1) {
            $numericDifferentiator = new NumericalDifferentiator();
            $analyticDifferentiator = new ArithmeticDifferentiator();
            $merged = [];
            for ($index = 0; $index < \count($solutions); ++$index) {
                $first = $solutions[$index];
                $second = $solutions[$index + 1] ?? null;
                if ($second === null) {
                    $merged[] = $first;
                    break;
                }
                $pairScale = \max(1.0, \abs($first->value), \abs($second->value));
                $midpoint = $first->value + (($second->value - $first->value) / 2.0);
                $midpointResidual = $residualAt($midpoint);
                $leftSlope = $analyticDifferentiator->differentiate(
                    $left,
                    $variable,
                    $midpoint,
                    $parameters,
                    $evaluationOptions,
                );
                $rightSlope = $analyticDifferentiator->differentiate(
                    $right,
                    $variable,
                    $midpoint,
                    $parameters,
                    $evaluationOptions,
                );
                if (
                    \abs($second->value - $first->value)
                        <= \sqrt(\sqrt(\PHP_FLOAT_EPSILON)) * $pairScale
                    && $midpointResidual !== null
                    && $this->isRoundoffZeroAt($midpoint, $midpointResidual, $candidateScaleAt, 8.0)
                    && $leftSlope !== null
                    && $rightSlope !== null
                    && \abs($leftSlope - $rightSlope)
                        <= 64.0 * \PHP_FLOAT_EPSILON * $pairScale
                ) {
                    $merged[] = new EquationSolution(
                        $midpoint,
                        \abs($midpointResidual),
                        \max($first->iterations, $second->iterations),
                    );
                    ++$index;
                    continue;
                }
                $firstDerivative = $numericDifferentiator->differentiate($residualAt, $first->value);
                $secondDerivative = $numericDifferentiator->differentiate($residualAt, $second->value);
                if (
                    $firstDerivative === null
                    || $secondDerivative === null
                    || !$this->hasOppositeSigns($firstDerivative, $secondDerivative)
                ) {
                    $merged[] = $first;
                    continue;
                }
                $critical = $this->bisectDerivative(
                    $numericDifferentiator,
                    $residualAt,
                    $first->value,
                    $firstDerivative,
                    $second->value,
                    $options,
                );
                $criticalResidual = $critical === null ? null : $residualAt($critical);
                if (
                    $critical === null
                    || $criticalResidual === null
                    || !$this->isRoundoffZeroAt($critical, $criticalResidual, $candidateScaleAt, 8.0)
                ) {
                    $merged[] = $first;
                    continue;
                }
                $merged[] = new EquationSolution(
                    $critical,
                    \abs($criticalResidual),
                    \max($first->iterations, $second->iterations),
                );
                ++$index;
            }
            $solutions = $merged;
        }

        return $solutions === [] ? null : $solutions;
    }

    /**
     * Eliminate two rational roots using the determinant of multiplication in
     * the quotient by one root's defining polynomial.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalRootPairSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $boundaries = [$lowerBound, $upperBound];
        $cancelledRoots = [];
        foreach ([[$left, 1.0], [$right, -1.0]] as [$side, $sideSign]) {
            $terms = [];
            $this->flattenAdditiveTerms($side, $sideSign, $terms);
            foreach ($terms as [$node]) {
                $radical = $this->polynomialScaledRationalRootTerm(
                    $node,
                    $variable,
                    $extractor,
                    $solverOptions->maxPolynomialDegree,
                );
                if ($radical === null) {
                    continue;
                }
                $base = $this->unwrapGrouping($radical[0]);
                if (
                    !$base instanceof FunctionCallNode
                    || $base->name !== 'abs'
                    || \count($base->arguments) !== 1
                ) {
                    continue;
                }
                $absoluteForm = $this->extractAbsolutePolynomial(
                    $base->arguments[0],
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($absoluteForm === null) {
                    return null;
                }
                [$polynomial, $holes] = $absoluteForm;
                foreach ($holes as $hole) {
                    $cancelledRoots[] = $hole;
                    $boundaries[] = $hole;
                }
                $roots = $this->solvePolynomialRootsInInterval(
                    $polynomial,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    if ($root->value > $lowerBound && $root->value < $upperBound) {
                        $boundaries[] = $root->value;
                    }
                }
            }
        }

        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
        if (\count($boundaries) === 2) {
            return $this->solveRationalRootPairSumOnBranch(
                $left,
                $right,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
                $lowerBound + (($upperBound - $lowerBound) / 2.0),
                $lowerBound,
                $upperBound,
            );
        }

        $solutions = [];
        $recognizedBranch = false;
        for ($index = 0; $index < \count($boundaries) - 1; ++$index) {
            $branchLower = $boundaries[$index];
            $branchUpper = $boundaries[$index + 1];
            $sample = $branchLower + (($branchUpper - $branchLower) / 2.0);
            if ($sample === $branchLower || $sample === $branchUpper) {
                continue;
            }
            $branchSolutions = $this->solveRationalRootPairSumOnBranch(
                $left,
                $right,
                $variable,
                $extractor,
                $branchLower,
                $branchUpper,
                $solverOptions,
                $residualAt,
                $candidateScaleAt,
                $sample,
                $lowerBound,
                $upperBound,
            );
            if ($branchSolutions === null) {
                return null;
            }
            $recognizedBranch = true;
            foreach ($branchSolutions as $solution) {
                $nearHole = false;
                foreach ($cancelledRoots as $hole) {
                    if (
                        \abs($solution->value - $hole)
                        <= $solverOptions->positionTolerance($solution->value, $hole)
                    ) {
                        $nearHole = true;
                        break;
                    }
                }
                if (!$nearHole) {
                    $this->addSolution($solutions, $solution, $solverOptions);
                }
            }
        }
        if (!$recognizedBranch) {
            return null;
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalRootPairSumOnBranch(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
        float $branchSample,
        float $absoluteLowerBound,
        float $absoluteUpperBound,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicals = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $radical = $this->polynomialScaledRationalRootTerm(
                $node,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($radical !== null) {
                [$radicandNode, $coefficient, $degree, $numerator] = $radical;
                if (
                    \count($radicals) >= 2
                    || $degree > $solverOptions->maxPolynomialDegree
                    || $numerator < 1
                    || $numerator > $solverOptions->maxPolynomialDegree
                ) {
                    return null;
                }
                $baseNode = $this->unwrapGrouping($radicandNode);
                if (
                    $baseNode instanceof FunctionCallNode
                    && $baseNode->name === 'abs'
                    && \count($baseNode->arguments) === 1
                ) {
                    $radicand = null;
                    $absoluteForm = $this->extractAbsolutePolynomial(
                        $baseNode->arguments[0],
                        $extractor,
                        $absoluteLowerBound,
                        $absoluteUpperBound,
                        $solverOptions,
                    );
                    if ($absoluteForm !== null) {
                        [$radicand] = $absoluteForm;
                        $polynomialSolver = new PolynomialSolver();
                        $sampleValue = $polynomialSolver->evaluatePolynomial(
                            $radicand,
                            $branchSample,
                        );
                        if ($sampleValue === null) {
                            return null;
                        }
                        if ($sampleValue < 0.0) {
                            $radicand = $this->scalePolynomialCoefficients($radicand, -1.0);
                        }
                    }
                } else {
                    $radicand = $this->extractPolynomial(
                        $extractor,
                        $radicandNode,
                        $radicandNode->span()->start,
                    );
                }
                if ($radicand !== null) {
                    $base = [1.0];
                    for ($power = 0; $power < $numerator; ++$power) {
                        $base = $this->multiplyPolynomialCoefficients(
                            $base,
                            $radicand,
                            $solverOptions->maxPolynomialDegree,
                        );
                        if ($base === null) {
                            return null;
                        }
                    }
                    $radicand = $base;
                }
                $coefficientPower = [1.0];
                for ($power = 0; $power < $degree; ++$power) {
                    $coefficientPower = $this->multiplyPolynomialCoefficients(
                        $coefficientPower,
                        $coefficient,
                        $solverOptions->maxPolynomialDegree,
                    );
                    if ($coefficientPower === null) {
                        return null;
                    }
                }
                $radicand = $radicand === null
                    ? null
                    : $this->multiplyPolynomialCoefficients(
                        $radicand,
                        $coefficientPower,
                        $solverOptions->maxPolynomialDegree,
                    );
                $radicand = $radicand === null
                    ? null
                    : $this->scalePolynomialCoefficients(
                        $radicand,
                        $sign ** $degree,
                    );
                if ($radicand === null) {
                    return null;
                }
                $radicals[] = ['radicand' => $radicand, 'degree' => $degree];
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if (\count($radicals) !== 2) {
            return null;
        }
        \usort(
            $radicals,
            static fn (array $left, array $right): int => $left['degree'] <=> $right['degree'],
        );
        $basisRadicand = $radicals[0]['radicand'];
        $basisDegree = $radicals[0]['degree'];
        $otherRadicand = $radicals[1]['radicand'];
        $otherDegree = $radicals[1]['degree'];
        if ($basisDegree > self::MAX_ROOT_PAIR_EXTENSION_DEGREE) {
            return null;
        }
        $maxDegree = $solverOptions->maxPolynomialDegree;
        $target = $this->scalePolynomialCoefficients($remainder, -1.0);
        if ($target === null) {
            return null;
        }
        $targetPowers = [[1.0]];
        for ($power = 1; $power <= $otherDegree; ++$power) {
            $targetPower = $this->multiplyPolynomialCoefficients(
                $targetPowers[$power - 1],
                $target,
                $maxDegree,
            );
            if ($targetPower === null) {
                return null;
            }
            $targetPowers[] = $targetPower;
        }
        $otherPowers = [[1.0]];
        $binomial = 1.0;
        $otherPolynomial = [];
        for ($power = 0; $power <= $otherDegree; ++$power) {
            if ($power > 0) {
                $binomial *= ($otherDegree - $power + 1) / $power;
                if (!\is_finite($binomial)) {
                    return null;
                }
            }
            $term = $this->multiplyPolynomialCoefficients(
                $targetPowers[$otherDegree - $power],
                [1.0],
                $maxDegree,
            );
            if ($term === null) {
                return null;
            }
            $term = $this->scalePolynomialCoefficients($term, ($power % 2 === 0 ? 1.0 : -1.0) * $binomial);
            if ($term === null) {
                return null;
            }
            $otherPolynomial[] = $term;
        }
        $otherPolynomial[0] = $this->combinePolynomialCoefficients(
            $otherPolynomial[0],
            $otherRadicand,
            -1.0,
        );
        if ($otherPolynomial[0] === null) {
            return null;
        }
        $maximumBasisPower = intdiv($otherDegree + $basisDegree - 1, $basisDegree);
        for ($power = 1; $power <= $maximumBasisPower; ++$power) {
            $otherPower = $this->multiplyPolynomialCoefficients(
                $otherPowers[$power - 1],
                $basisRadicand,
                $maxDegree,
            );
            if ($otherPower === null) {
                return null;
            }
            $otherPowers[] = $otherPower;
        }

        $matrix = \array_fill(0, $basisDegree, []);
        for ($row = 0; $row < $basisDegree; ++$row) {
            $matrix[$row] = \array_fill(0, $basisDegree, [0.0]);
        }
        foreach ($otherPolynomial as $power => $coefficient) {
            for ($column = 0; $column < $basisDegree; ++$column) {
                $combinedPower = $power + $column;
                $row = $combinedPower % $basisDegree;
                $basisPower = intdiv($combinedPower, $basisDegree);
                $basisPolynomial = $otherPowers[$basisPower] ?? null;
                if ($coefficient === null || $basisPolynomial === null) {
                    return null;
                }
                $reduced = $this->multiplyPolynomialCoefficients(
                    $coefficient,
                    $basisPolynomial,
                    $maxDegree,
                );
                if ($reduced === null) {
                    return null;
                }
                $matrixEntry = $matrix[$row][$column] ?? null;
                if ($matrixEntry === null) {
                    return null;
                }
                $matrix[$row][$column] = $this->combinePolynomialCoefficients(
                    $matrixEntry,
                    $reduced,
                    1.0,
                );
                if ($matrix[$row][$column] === null) {
                    return null;
                }
            }
        }

        $determinants = [0 => [1.0]];
        $fullMask = (1 << $basisDegree) - 1;
        for ($row = 0; $row < $basisDegree; ++$row) {
            $next = [];
            foreach ($determinants as $mask => $partial) {
                for ($column = 0; $column < $basisDegree; ++$column) {
                    $bit = 1 << $column;
                    if (($mask & $bit) !== 0) {
                        continue;
                    }
                    $matrixEntry = $matrix[$row][$column] ?? null;
                    if ($matrixEntry === null) {
                        return null;
                    }
                    $product = $this->multiplyPolynomialCoefficients(
                        $partial,
                        $matrixEntry,
                        $maxDegree,
                    );
                    if ($product === null) {
                        return null;
                    }
                    $greaterColumns = $mask >> ($column + 1);
                    if ((\substr_count(\decbin($greaterColumns), '1') % 2) !== 0) {
                        $product = $this->scalePolynomialCoefficients($product, -1.0);
                        if ($product === null) {
                            return null;
                        }
                    }
                    $nextMask = $mask | $bit;
                    $next[$nextMask] = isset($next[$nextMask])
                        ? $this->combinePolynomialCoefficients($next[$nextMask], $product, 1.0)
                        : $product;
                    if ($next[$nextMask] === null) {
                        return null;
                    }
                }
            }
            $determinants = $next;
        }

        $polynomial = $determinants[$fullMask] ?? null;
        if ($polynomial === null) {
            return null;
        }
        if (\count($polynomial) === 1) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null) {
            return null;
        }
        if ($candidates === []) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if ($residual === null) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }

        return $solutions;
    }

    /**
     * @return array{Node, list<float>, int, int}|null
     */
    private function polynomialScaledRationalRootTerm(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
        int $maxDegree,
        bool $allowNegativeNumerator = false,
    ): ?array {
        $factors = [];
        $this->flattenProductFactors($node, $factors);
        $power = null;
        $coefficient = [1.0];
        foreach ($factors as $factor) {
            $candidate = $this->rationalPowerTermInfo($factor);
            if ($candidate !== null) {
                if ($power !== null) {
                    return null;
                }
                $power = $candidate;
                continue;
            }
            $polynomial = $this->extractPolynomial(
                $extractor,
                $factor,
                $factor->span()->start,
            );
            if ($polynomial === null) {
                return null;
            }
            $coefficient = $this->multiplyPolynomialCoefficients(
                $coefficient,
                $polynomial,
                $maxDegree,
            );
            if ($coefficient === null) {
                return null;
            }
        }
        if (
            $power === null
            || ($power['exponent'][0] < 1 && !$allowNegativeNumerator)
            || $power['exponent'][0] === \PHP_INT_MIN
            || $power['exponent'][1] < 2
            || \abs($power['exponent'][0]) > $maxDegree
            || $power['exponent'][1] > $maxDegree
            || !$this->containsVariable($power['base'], $variable)
        ) {
            return null;
        }

        return [
            $power['base'],
            $coefficient,
            $power['exponent'][1],
            $power['exponent'][0],
        ];
    }

    /**
     * Reduce a sum of two cube roots of polynomial radicands to a polynomial.
     * Resultant candidates are checked against the original equation because
     * the squared identity also admits roots from the other cube-root branches.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveCubeRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicands = [];
        $remainder = [0.0];
        $remainderContainsFunction = false;
        foreach ($terms as [$node, $sign]) {
            $radicand = $this->polynomialScaledCubeRootRadicand(
                $node,
                $sign,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($radicand !== null) {
                if (\count($radicands) >= 2) {
                    return null;
                }
                $radicands[] = $radicand;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainderContainsFunction = $remainderContainsFunction
                || $this->containsFunctionCall($node);
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($radicands === []) {
            return null;
        }

        if (\count($radicands) === 1) {
            if ($remainderContainsFunction) {
                return null;
            }
            foreach ($remainder as $leftCoefficient) {
                foreach ($remainder as $rightCoefficient) {
                    if (
                        $leftCoefficient !== 0.0
                        && $rightCoefficient !== 0.0
                        && $leftCoefficient * $rightCoefficient === 0.0
                    ) {
                        return null;
                    }
                }
            }
            $remainderSquared = $this->multiplyPolynomialCoefficients(
                $remainder,
                $remainder,
                $solverOptions->maxPolynomialDegree,
            );
            if ($remainderSquared === null) {
                return null;
            }
            foreach ($remainderSquared as $leftCoefficient) {
                foreach ($remainder as $rightCoefficient) {
                    if (
                        $leftCoefficient !== 0.0
                        && $rightCoefficient !== 0.0
                        && $leftCoefficient * $rightCoefficient === 0.0
                    ) {
                        return null;
                    }
                }
            }
            $remainderCubed = $this->multiplyPolynomialCoefficients(
                $remainderSquared,
                $remainder,
                $solverOptions->maxPolynomialDegree,
            );
            $polynomial = $remainderCubed === null
                ? null
                : $this->combinePolynomialCoefficients($radicands[0], $remainderCubed, 1.0);
        } elseif (\count($radicands) === 2) {
            [$firstRadicand, $secondRadicand] = $radicands;
            $maxDegree = $solverOptions->maxPolynomialDegree;
            $radicandSum = $this->combinePolynomialCoefficients(
                $firstRadicand,
                $secondRadicand,
                1.0,
            );
            $radicandDifference = $this->combinePolynomialCoefficients(
                $firstRadicand,
                $secondRadicand,
                -1.0,
            );
            $target = $this->scalePolynomialCoefficients($remainder, -1.0);
            $targetSquared = $target === null
                ? null
                : $this->multiplyPolynomialCoefficients($target, $target, $maxDegree);
            $targetCubed = $targetSquared === null || $target === null
                ? null
                : $this->multiplyPolynomialCoefficients($targetSquared, $target, $maxDegree);
            $differenceSquared = $radicandDifference === null
                ? null
                : $this->multiplyPolynomialCoefficients(
                    $radicandDifference,
                    $radicandDifference,
                    $maxDegree,
                );
            $targetCubedTimesDifferenceSquared = $targetCubed === null || $differenceSquared === null
                ? null
                : $this->multiplyPolynomialCoefficients(
                    $targetCubed,
                    $differenceSquared,
                    $maxDegree,
                );
            $firstTerm = $targetCubedTimesDifferenceSquared === null
                ? null
                : $this->scalePolynomialCoefficients($targetCubedTimesDifferenceSquared, 27.0);
            $scaledRadicandSum = $radicandSum === null
                ? null
                : $this->scalePolynomialCoefficients($radicandSum, 4.0);
            $firstFactor = $scaledRadicandSum === null || $targetCubed === null
                ? null
                : $this->combinePolynomialCoefficients(
                    $scaledRadicandSum,
                    $targetCubed,
                    -1.0,
                );
            $twiceTargetCubed = $targetCubed === null
                ? null
                : $this->scalePolynomialCoefficients($targetCubed, 2.0);
            $secondFactor = $radicandSum === null || $twiceTargetCubed === null
                ? null
                : $this->combinePolynomialCoefficients(
                    $twiceTargetCubed,
                    $radicandSum,
                    1.0,
                );
            $secondFactorSquared = $secondFactor === null
                ? null
                : $this->multiplyPolynomialCoefficients($secondFactor, $secondFactor, $maxDegree);
            $secondTerm = $firstFactor === null || $secondFactorSquared === null
                ? null
                : $this->multiplyPolynomialCoefficients($firstFactor, $secondFactorSquared, $maxDegree);
            $polynomial = $firstTerm === null || $secondTerm === null
                ? null
                : $this->combinePolynomialCoefficients($firstTerm, $secondTerm, -1.0);
        } else {
            return null;
        }
        if ($polynomial === null) {
            return null;
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * Reduce one rational power plus polynomial terms by raising both sides
     * to its denominator, then verify the original branch and domain.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSingleRationalRootPolynomialEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $rootTerm = null;
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $candidate = $this->polynomialScaledRationalRootTerm(
                $node,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($candidate !== null) {
                if ($rootTerm !== null) {
                    return null;
                }
                [$base, $coefficient, $degree, $numerator] = $candidate;
                $hasPolynomialCoefficient = \count($coefficient) > 1;
                if (
                    ($degree <= 3 && !$hasPolynomialCoefficient)
                    || $numerator <= 0
                    || $degree > $solverOptions->maxPolynomialDegree
                    || $numerator > $solverOptions->maxPolynomialDegree
                ) {
                    return null;
                }
                $polynomial = $this->extractPolynomial($extractor, $base, $base->span()->start);
                if ($polynomial === null) {
                    return null;
                }
                $rootTerm = [$polynomial, $coefficient, $sign, $degree, $numerator];
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null || $this->containsFunctionCall($node)) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($rootTerm === null) {
            return null;
        }

        [$base, $coefficient, $sign, $degree, $numerator] = $rootTerm;
        $maximumDegree = $solverOptions->maxPolynomialDegree;
        $scaledBase = $this->powerPolynomialCoefficients($base, $numerator, $maximumDegree);
        $coefficientPower = $this->powerPolynomialCoefficients($coefficient, $degree, $maximumDegree);
        $remainderPower = $this->powerPolynomialCoefficients($remainder, $degree, $maximumDegree);
        if (
            $scaledBase === null
            || $coefficientPower === null
            || $remainderPower === null
        ) {
            return null;
        }
        $scaledBase = $this->multiplyPolynomialCoefficients($scaledBase, $coefficientPower, $maximumDegree);
        $scaledBase = $scaledBase === null
            ? null
            : $this->scalePolynomialCoefficients($scaledBase, $sign ** $degree);
        $remainderScale = $degree % 2 === 0 ? -1.0 : 1.0;
        $polynomial = $scaledBase === null
            ? null
            : $this->combinePolynomialCoefficients($scaledBase, $remainderPower, $remainderScale);
        if ($polynomial === null || \count($polynomial) === 1) {
            return $polynomial !== null && $polynomial[0] !== 0.0 ? [] : null;
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $solverOptions)
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt($value, $residual, $candidateScaleAt, $solverOptions)
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * @param list<float> $polynomial
     * @return list<float>|null
     */
    private function powerPolynomialCoefficients(array $polynomial, int $power, int $maximumDegree): ?array
    {
        $result = [1.0];
        for ($exponent = 0; $exponent < $power; ++$exponent) {
            foreach ($result as $leftCoefficient) {
                foreach ($polynomial as $rightCoefficient) {
                    if (
                        $leftCoefficient !== 0.0
                        && $rightCoefficient !== 0.0
                        && $leftCoefficient * $rightCoefficient === 0.0
                    ) {
                        return null;
                    }
                }
            }
            $result = $this->multiplyPolynomialCoefficients($result, $polynomial, $maximumDegree);
            if ($result === null) {
                return null;
            }
        }

        return $result;
    }

    /**
     * Solve one product of scaled square roots plus polynomial terms.
     * Squaring can add roots with invalid signs or domains; verify each result
     * against the original expression before returning it.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSquareRootProductEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicals = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $productTerm = $this->scaledSquareRootProductTerm($node, $variable, $extractor);
            if ($productTerm !== null) {
                if (\count($radicals) === self::MAX_SQUARE_ROOT_RESULTANT_TERMS) {
                    return null;
                }
                [$radicandNodes, $coefficient] = $productTerm;
                $radicandProduct = [1.0];
                foreach ($radicandNodes as $radicandNode) {
                    $radicand = $this->extractPolynomial(
                        $extractor,
                        $radicandNode,
                        $radicandNode->span()->start,
                    );
                    $radicandProduct = $radicand === null
                        ? null
                        : $this->multiplyPolynomialCoefficients(
                            $radicandProduct,
                            $radicand,
                            $solverOptions->maxPolynomialDegree,
                        );
                    if ($radicandProduct === null) {
                        break;
                    }
                }
                $signedCoefficient = $sign * $coefficient;
                if ($radicandProduct === null || !\is_finite($signedCoefficient)) {
                    return null;
                }
                $radicals[] = [$radicandProduct, $signedCoefficient];
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($radicals === []) {
            return null;
        }

        $polynomial = $this->squareRootSumResultant(
            $radicals,
            $remainder,
            $solverOptions->maxPolynomialDegree,
        );
        if ($polynomial === null) {
            return null;
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null || $candidates === []) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $candidate->value;
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $value = $this->refineVerifiedEquationCandidate(
                $value,
                $residual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * Eliminate up to eight square roots with polynomial radicands. Squaring
     * creates extra algebraic branches, so candidates are checked against the
     * source equation and its original real-domain rules.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSquareRootSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $radicands = [];
        $radicandMergeKeys = [];
        $remainder = [0.0];
        $remainderContainsFunction = false;
        foreach ($terms as [$node, $sign]) {
            $squareRoot = $this->polynomialScaledRationalRootTerm(
                $node,
                $variable,
                $extractor,
                $solverOptions->maxPolynomialDegree,
            );
            if ($squareRoot !== null && $squareRoot[2] === 2 && $squareRoot[3] === 1) {
                [$radicandNode, $coefficientPolynomial] = $squareRoot;
                $radicand = $this->extractPolynomial(
                    $extractor,
                    $radicandNode,
                    $radicandNode->span()->start,
                );
                if ($radicand === null) {
                    return null;
                }
                if (\count($coefficientPolynomial) > 1) {
                    $coefficientSquare = $this->multiplyPolynomialCoefficients(
                        $coefficientPolynomial,
                        $coefficientPolynomial,
                        $solverOptions->maxPolynomialDegree,
                    );
                    $radicand = $coefficientSquare === null
                        ? null
                        : $this->multiplyPolynomialCoefficients(
                            $radicand,
                            $coefficientSquare,
                            $solverOptions->maxPolynomialDegree,
                        );
                    if ($radicand === null) {
                        return null;
                    }
                    $radicands[] = [$radicand, 1.0];
                    $radicandMergeKeys[] = \serialize($radicand) . '#' . \count($radicands);
                } else {
                    $radicands[] = [$radicand, $sign * $coefficientPolynomial[0]];
                    $radicandMergeKeys[] = \serialize($radicand);
                }
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainderContainsFunction = $remainderContainsFunction
                || $this->containsFunctionCall($node);
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($radicands === []) {
            return null;
        }

        /** @var list<array{list<float>, float}> $combinedRadicands */
        $combinedRadicands = [];
        /** @var array<string, int> $radicandIndices */
        $radicandIndices = [];
        foreach ($radicands as $termIndex => [$radicand, $coefficient]) {
            $key = $radicandMergeKeys[$termIndex];
            if (!\array_key_exists($key, $radicandIndices)) {
                $radicandIndices[$key] = \count($combinedRadicands);
                $combinedRadicands[] = [$radicand, $coefficient];
                continue;
            }
            $index = $radicandIndices[$key];
            $combinedCoefficient = $combinedRadicands[$index][1] + $coefficient;
            if (!\is_finite($combinedCoefficient)) {
                return null;
            }
            $combinedRadicands[$index] = [$combinedRadicands[$index][0], $combinedCoefficient];
        }
        /** @var list<array{list<float>, float}> $distinctRadicands */
        $distinctRadicands = [];
        foreach ($combinedRadicands as $term) {
            if ($term[1] !== 0.0) {
                $distinctRadicands[] = $term;
            }
        }
        $radicands = $distinctRadicands;
        if ($radicands === [] || \count($radicands) > self::MAX_SQUARE_ROOT_RESULTANT_TERMS) {
            return null;
        }

        if (\count($radicands) === 1) {
            if ($remainderContainsFunction) {
                return null;
            }
            [$radicand, $coefficient] = $radicands[0];
            $squaredCoefficient = $coefficient * $coefficient;
            if (!\is_finite($squaredCoefficient)) {
                return null;
            }
            foreach ($remainder as $leftCoefficient) {
                foreach ($remainder as $rightCoefficient) {
                    if (
                        $leftCoefficient !== 0.0
                        && $rightCoefficient !== 0.0
                        && $leftCoefficient * $rightCoefficient === 0.0
                    ) {
                        return null;
                    }
                }
            }
            $scaledRadicand = $this->scalePolynomialCoefficients($radicand, $squaredCoefficient);
            $squaredRemainder = $this->multiplyPolynomialCoefficients(
                $remainder,
                $remainder,
                $solverOptions->maxPolynomialDegree,
            );
            $polynomial = $scaledRadicand === null || $squaredRemainder === null
                ? null
                : $this->combinePolynomialCoefficients($scaledRadicand, $squaredRemainder, -1.0);
        } elseif (\count($radicands) > 2) {
            $maximumInputDegree = \count($remainder) - 1;
            foreach ($radicands as [$radicand]) {
                $maximumInputDegree = \max($maximumInputDegree, \count($radicand) - 1);
            }
            $maximumDegreeFactor = 1 << \count($radicands);
            if (
                $maximumInputDegree > 0
                && $maximumInputDegree > intdiv(
                    $solverOptions->maxPolynomialDegree,
                    $maximumDegreeFactor,
                )
            ) {
                return null;
            }
            $polynomial = $this->squareRootSumResultant(
                $radicands,
                $remainder,
                $solverOptions->maxPolynomialDegree,
            );
            if ($polynomial === null) {
                return null;
            }
        } else {
            [$firstRadicand, $firstCoefficient] = $radicands[0];
            [$secondRadicand, $secondCoefficient] = $radicands[1];
            $firstCoefficientSquare = $firstCoefficient * $firstCoefficient;
            $secondCoefficientSquare = $secondCoefficient * $secondCoefficient;
            $productCoefficient = -4.0 * $firstCoefficientSquare * $secondCoefficientSquare;
            if (!\is_finite($productCoefficient)) {
                return null;
            }
            $firstScaledRadicand = $this->scalePolynomialCoefficients(
                $firstRadicand,
                $firstCoefficientSquare,
            );
            $secondScaledRadicand = $this->scalePolynomialCoefficients(
                $secondRadicand,
                $secondCoefficientSquare,
            );
            $radicandSum = $firstScaledRadicand === null || $secondScaledRadicand === null
            ? null
            : $this->combinePolynomialCoefficients(
                $firstScaledRadicand,
                $secondScaledRadicand,
                1.0,
            );
            $product = $this->multiplyPolynomialCoefficients(
                $firstRadicand,
                $secondRadicand,
                $solverOptions->maxPolynomialDegree,
            );
            $squaredRemainder = $this->multiplyPolynomialCoefficients(
                $remainder,
                $remainder,
                $solverOptions->maxPolynomialDegree,
            );
            $difference = $radicandSum === null || $squaredRemainder === null
            ? null
            : $this->combinePolynomialCoefficients(
                $squaredRemainder,
                $radicandSum,
                -1.0,
            );
            $squaredDifference = $difference === null
            ? null
            : $this->multiplyPolynomialCoefficients(
                $difference,
                $difference,
                $solverOptions->maxPolynomialDegree,
            );
            $polynomial = $product === null || $squaredDifference === null
            ? null
            : $this->combinePolynomialCoefficients(
                $squaredDifference,
                $product,
                $productCoefficient,
            );
        }
        if ($polynomial === null) {
            return null;
        }
        if (\count($polynomial) === 1) {
            return $polynomial[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        try {
            $candidates = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomial, $value),
                $solverOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($candidates === null) {
            return null;
        }
        if ($candidates === []) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $candidateValue = $candidate->value;
            $candidateResidual = $residualAt($candidateValue);
            if ($candidateResidual === null) {
                continue;
            }
            $candidateValue = $this->refineVerifiedEquationCandidate(
                $candidateValue,
                $candidateResidual,
                $residualAt,
                $candidate->value,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            $residual = $residualAt($candidateValue);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidateValue,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidateValue, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions === [] ? null : $solutions;
    }

    /**
     * @param list<array{list<float>, float}> $radicals
     * @param list<float> $remainder
     * @return list<float>|null
     */
    private function squareRootSumResultant(
        array $radicals,
        array $remainder,
        int $maxDegree,
    ): ?array {
        $expression = [0 => $remainder];
        foreach ($radicals as $index => [, $coefficient]) {
            $mask = 1 << $index;
            $expression[$mask] = [$coefficient];
        }

        foreach ($radicals as $index => [$radicand]) {
            $withoutRadical = [];
            $withRadical = [];
            $mask = 1 << $index;
            foreach ($expression as $basis => $polynomial) {
                if (($basis & $mask) === 0) {
                    $withoutRadical[$basis] = $polynomial;
                } else {
                    $withRadical[$basis ^ $mask] = $polynomial;
                }
            }

            $withoutSquared = $this->multiplyMultiquadraticPolynomials(
                $withoutRadical,
                $withoutRadical,
                $radicals,
                $maxDegree,
            );
            $withSquared = $this->multiplyMultiquadraticPolynomials(
                $withRadical,
                $withRadical,
                $radicals,
                $maxDegree,
            );
            if ($withoutSquared === null || $withSquared === null) {
                return null;
            }
            $withSquaredScaled = [];
            foreach ($withSquared as $basis => $polynomial) {
                $product = $this->multiplyPolynomialCoefficients(
                    $polynomial,
                    $radicand,
                    $maxDegree,
                );
                if ($product === null) {
                    return null;
                }
                $withSquaredScaled[$basis] = $product;
            }
            $expression = $this->combineMultiquadraticPolynomials(
                $withoutSquared,
                $withSquaredScaled,
                -1.0,
            );
            if ($expression === null) {
                return null;
            }
        }

        return $expression[0] ?? null;
    }

    /**
     * @param array<int, list<float>> $left
     * @param array<int, list<float>> $right
     * @param list<array{list<float>, float}> $radicals
     * @return array<int, list<float>>|null
     */
    private function multiplyMultiquadraticPolynomials(
        array $left,
        array $right,
        array $radicals,
        int $maxDegree,
    ): ?array {
        $product = [];
        foreach ($left as $leftBasis => $leftPolynomial) {
            foreach ($right as $rightBasis => $rightPolynomial) {
                $coefficientProduct = $this->multiplyPolynomialCoefficients(
                    $leftPolynomial,
                    $rightPolynomial,
                    $maxDegree,
                );
                if ($coefficientProduct === null) {
                    return null;
                }

                $commonBasis = $leftBasis & $rightBasis;
                if ($commonBasis !== 0) {
                    $radicandProduct = [1.0];
                    foreach ($radicals as $index => [$radicand]) {
                        if (($commonBasis & (1 << $index)) === 0) {
                            continue;
                        }
                        $radicandProduct = $this->multiplyPolynomialCoefficients(
                            $radicandProduct,
                            $radicand,
                            $maxDegree,
                        );
                        if ($radicandProduct === null) {
                            return null;
                        }
                    }
                    $coefficientProduct = $this->multiplyPolynomialCoefficients(
                        $coefficientProduct,
                        $radicandProduct,
                        $maxDegree,
                    );
                    if ($coefficientProduct === null) {
                        return null;
                    }
                }

                $basis = $leftBasis ^ $rightBasis;
                $sum = $this->combinePolynomialCoefficients(
                    $product[$basis] ?? [0.0],
                    $coefficientProduct,
                    1.0,
                );
                if ($sum === null) {
                    return null;
                }
                $product[$basis] = $sum;
            }
        }

        return $product;
    }

    /**
     * @param array<int, list<float>> $left
     * @param array<int, list<float>> $right
     * @return array<int, list<float>>|null
     */
    private function combineMultiquadraticPolynomials(
        array $left,
        array $right,
        float $rightScale,
    ): ?array {
        $combined = [];
        foreach (\array_unique([...\array_keys($left), ...\array_keys($right)]) as $basis) {
            $polynomial = $this->combinePolynomialCoefficients(
                $left[$basis] ?? [0.0],
                $right[$basis] ?? [0.0],
                $rightScale,
            );
            if ($polynomial === null) {
                return null;
            }
            $combined[$basis] = $polynomial;
        }

        return $combined;
    }

    /** @return list<float>|null */
    private function polynomialScaledSquareRootRadicand(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $term = $this->polynomialScaledRationalRootTerm(
            $node,
            $variable,
            $extractor,
            $maxDegree,
        );
        if ($term === null || $term[2] !== 2 || $term[3] !== 1) {
            return null;
        }

        [$base, $coefficient] = $term;
        $radicand = $this->extractPolynomial($extractor, $base, $base->span()->start);
        $coefficientSquare = $this->powerPolynomialCoefficients($coefficient, 2, $maxDegree);
        if ($radicand === null || $coefficientSquare === null) {
            return null;
        }

        return $this->multiplyPolynomialCoefficients($radicand, $coefficientSquare, $maxDegree);
    }

    /** @return list<float>|null */
    private function polynomialScaledCubeRootRadicand(
        Node $node,
        float $sign,
        string $variable,
        PolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $term = $this->polynomialScaledRationalRootTerm(
            $node,
            $variable,
            $extractor,
            $maxDegree,
        );
        if ($term === null || $term[2] !== 3 || $term[3] !== 1) {
            return null;
        }

        [$base, $coefficient] = $term;
        $radicand = $this->extractPolynomial($extractor, $base, $base->span()->start);
        $coefficientCube = $this->powerPolynomialCoefficients($coefficient, 3, $maxDegree);
        if ($radicand === null || $coefficientCube === null) {
            return null;
        }
        $coefficientCube = $this->scalePolynomialCoefficients($coefficientCube, $sign);

        return $coefficientCube === null
            ? null
            : $this->multiplyPolynomialCoefficients($radicand, $coefficientCube, $maxDegree);
    }

    /**
     * Return the exact scalar ratio when one polynomial is a scalar multiple
     * of another.
     *
     * @param list<float> $polynomial
     * @param list<float> $reference
     */
    private function proportionalPolynomialScale(array $polynomial, array $reference): ?float
    {
        $pivotIndex = null;
        foreach ($reference as $index => $coefficient) {
            if ($coefficient !== 0.0) {
                $pivotIndex = $index;
                break;
            }
        }
        if ($pivotIndex === null) {
            return null;
        }

        $pivot = $reference[$pivotIndex];
        $ratio = ($polynomial[$pivotIndex] ?? 0.0) / $pivot;
        if (!\is_finite($ratio) || $ratio === 0.0) {
            return null;
        }
        for ($index = 0; $index < \max(\count($polynomial), \count($reference)); ++$index) {
            $left = ($polynomial[$index] ?? 0.0) * $pivot;
            $right = ($reference[$index] ?? 0.0) * $polynomial[$pivotIndex];
            if (!\is_finite($left) || !\is_finite($right) || $left !== $right) {
                return null;
            }
        }

        return $ratio;
    }

    /**
     * @return array{Node, float}|null
     */
    private function scaledSquareRootTerm(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        $radicand = null;
        $coefficientNode = null;
        $coefficient = 1.0;
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'sqrt'
            && \count($node->arguments) === 1
        ) {
            $radicand = $node->arguments[0];
        } elseif ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Multiply) {
                $left = $this->unwrapGrouping($node->left);
                $right = $this->unwrapGrouping($node->right);
                if (
                    $left instanceof FunctionCallNode
                    && $left->name === 'sqrt'
                    && \count($left->arguments) === 1
                ) {
                    $radicand = $left->arguments[0];
                    $coefficientNode = $node->right;
                } elseif (
                    $right instanceof FunctionCallNode
                    && $right->name === 'sqrt'
                    && \count($right->arguments) === 1
                ) {
                    $radicand = $right->arguments[0];
                    $coefficientNode = $node->left;
                }
            } elseif ($node->operator === BinaryOperator::Divide) {
                $numerator = $this->unwrapGrouping($node->left);
                if (
                    $numerator instanceof FunctionCallNode
                    && $numerator->name === 'sqrt'
                    && \count($numerator->arguments) === 1
                ) {
                    $radicand = $numerator->arguments[0];
                    $denominator = $this->extractPolynomial(
                        $extractor,
                        $node->right,
                        $node->right->span()->start,
                    );
                    if ($denominator === null || \count($denominator) !== 1 || $denominator[0] === 0.0) {
                        return null;
                    }
                    $coefficient = 1.0 / $denominator[0];
                }
            }
        }
        if (!$radicand instanceof Node || !$this->containsVariable($radicand, $variable)) {
            return null;
        }

        if ($coefficientNode !== null) {
            $coefficientPolynomial = $this->extractPolynomial(
                $extractor,
                $coefficientNode,
                $coefficientNode->span()->start,
            );
            if ($coefficientPolynomial === null || \count($coefficientPolynomial) !== 1) {
                return null;
            }
            $coefficient = $coefficientPolynomial[0];
        }
        if (!\is_finite($coefficient) || $coefficient === 0.0) {
            return null;
        }

        return [$radicand, $coefficient];
    }

    /**
     * @return array{list<Node>, float}|null
     */
    private function scaledSquareRootProductTerm(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        if ($node->operator === BinaryOperator::Multiply) {
            $first = $this->scaledSquareRootTerm($node->left, $variable, $extractor);
            $firstProduct = $first === null
                ? $this->scaledSquareRootProductTerm($node->left, $variable, $extractor)
                : [[$first[0]], $first[1]];
            $second = $this->scaledSquareRootTerm($node->right, $variable, $extractor);
            $secondProduct = $second === null
                ? $this->scaledSquareRootProductTerm($node->right, $variable, $extractor)
                : [[$second[0]], $second[1]];
            if ($firstProduct === null || $secondProduct === null) {
                return null;
            }
            $coefficient = $firstProduct[1] * $secondProduct[1];
            if (!\is_finite($coefficient)) {
                return null;
            }

            return [[...$firstProduct[0], ...$secondProduct[0]], $coefficient];
        }
        if ($node->operator === BinaryOperator::Divide) {
            $product = $this->scaledSquareRootProductTerm(
                $node->left,
                $variable,
                $extractor,
            );
            $denominator = $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            );
            if ($product === null || $denominator === null || \count($denominator) !== 1 || $denominator[0] === 0.0) {
                return null;
            }
            $coefficient = $product[1] / $denominator[0];
            if (!\is_finite($coefficient)) {
                return null;
            }

            return [$product[0], $coefficient];
        }

        return null;
    }

    /**
     * @return array{base: Node, exponent: array{int, int}}|null
     */
    private function rationalPowerTermInfo(
        Node $node,
    ): ?array {
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $exponent = RationalLiteral::fromNode($node->right);
            if ($exponent !== null && $exponent[1] > 1) {
                return ['base' => $node->left, 'exponent' => $exponent];
            }

            return null;
        }
        if (!$node instanceof FunctionCallNode) {
            return null;
        }
        if (
            \in_array($node->name, ['sqrt', 'cbrt'], true)
            && \count($node->arguments) === 1
        ) {
            return [
                'base' => $node->arguments[0],
                'exponent' => match ($node->name) {
                    'sqrt' => [1, 2],
                    'cbrt' => [1, 3],
                },
            ];
        }
        if ($node->name !== 'root' || \count($node->arguments) !== 2) {
            return null;
        }

        $degree = RationalLiteral::fromNode($node->arguments[1]);
        if ($degree === null || $degree[1] !== 1 || $degree[0] === 0 || $degree[0] === \PHP_INT_MIN) {
            return null;
        }

        return [
            'base' => $node->arguments[0],
            'exponent' => [$degree[0] < 0 ? -1 : 1, \abs($degree[0])],
        ];
    }

    /**
     * @param array<int, float> $coefficients
     * @return list<float>
     */
    private function densePolynomialCoefficients(int $degree, array $coefficients): array
    {
        $dense = [];
        for ($index = 0; $index <= $degree; ++$index) {
            $dense[] = $coefficients[$index] ?? 0.0;
        }

        return $dense;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAdditiveSharedBaseRationalPowers(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftTerms = [];
        $rightTerms = [];
        $this->flattenAdditiveTerms($left, 1.0, $leftTerms);
        $this->flattenAdditiveTerms($right, -1.0, $rightTerms);
        if (\count($leftTerms) + \count($rightTerms) < 3) {
            return null;
        }

        $terms = [];
        foreach ($leftTerms as [$node, $sign]) {
            $terms[] = [$node, $sign];
        }
        foreach ($rightTerms as [$node, $sign]) {
            $terms[] = [$node, $sign];
        }

        $rationalTerms = [];
        $basePolynomial = null;
        $otherConstant = 0.0;
        foreach ($terms as [$node, $sign]) {
            $power = $this->rationalPowerTermInfo($node);
            if ($power !== null && $this->containsVariable($node, $variable)) {
                $polynomial = $this->extractPolynomial(
                    $extractor,
                    $power['base'],
                    $power['base']->span()->start,
                );
                if ($polynomial === null) {
                    return null;
                }
                if ($basePolynomial === null) {
                    $basePolynomial = $polynomial;
                } elseif ($basePolynomial !== $polynomial) {
                    return null;
                }
                $rationalTerms[] = [$power['exponent'], $sign];
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null || \count($polynomial) !== 1) {
                return null;
            }
            $otherConstant += $sign * $polynomial[0];
            if (!\is_finite($otherConstant)) {
                return null;
            }
        }
        if (
            \count($rationalTerms) < 2
            || $basePolynomial === null
            || \count($basePolynomial) !== 2
            || $basePolynomial[1] === 0.0
        ) {
            return null;
        }

        $commonDenominator = 1;
        foreach ($rationalTerms as [$exponent]) {
            $denominator = $exponent[1];
            $gcd = $this->positiveIntegerGcd($commonDenominator, $denominator);
            $factor = intdiv($denominator, $gcd);
            if ($commonDenominator > intdiv(\PHP_INT_MAX, $factor)) {
                return null;
            }
            $commonDenominator *= $factor;
        }

        $integerPowers = [];
        $minimumPower = 0;
        foreach ($rationalTerms as [$exponent, $sign]) {
            $scale = intdiv($commonDenominator, $exponent[1]);
            if (\abs($exponent[0]) > intdiv(\PHP_INT_MAX, $scale)) {
                return null;
            }
            $power = $exponent[0] * $scale;
            $integerPowers[] = [$power, $sign];
            $minimumPower = \min($minimumPower, $power);
        }
        $baseShift = $minimumPower < 0
            ? intdiv(-$minimumPower, $commonDenominator)
                + ((-$minimumPower) % $commonDenominator === 0 ? 0 : 1)
            : 0;
        if ($baseShift > intdiv(\PHP_INT_MAX, $commonDenominator)) {
            return null;
        }
        $shiftedBasePower = $baseShift * $commonDenominator;
        $polynomialPowers = [];
        $maximumDegree = $shiftedBasePower;
        foreach ($integerPowers as [$power, $sign]) {
            if ($power > \PHP_INT_MAX - $shiftedBasePower) {
                return null;
            }
            $polynomialPower = $power + $shiftedBasePower;
            if ($polynomialPower > $solverOptions->maxPolynomialDegree) {
                return null;
            }
            $polynomialPowers[] = [$polynomialPower, $sign];
            $maximumDegree = \max($maximumDegree, $polynomialPower);
        }
        if ($maximumDegree > $solverOptions->maxPolynomialDegree) {
            return null;
        }

        $sparseCoefficients = [];
        foreach ($polynomialPowers as [$power, $sign]) {
            $sparseCoefficients[$power] = ($sparseCoefficients[$power] ?? 0.0) + $sign;
        }
        $sparseCoefficients[$shiftedBasePower] =
            ($sparseCoefficients[$shiftedBasePower] ?? 0.0) + $otherConstant;
        while (
            $maximumDegree > 0
            && ($sparseCoefficients[$maximumDegree] ?? 0.0) === 0.0
        ) {
            --$maximumDegree;
        }
        if ($maximumDegree === 0) {
            return ($sparseCoefficients[0] ?? 0.0) === 0.0 ? null : [];
        }
        $polynomialCoefficients = $this->densePolynomialCoefficients($maximumDegree, $sparseCoefficients);

        $baseConstant = $basePolynomial[0];
        $baseSlope = $basePolynomial[1];
        $baseAtLower = $baseConstant + ($baseSlope * $lowerBound);
        $baseAtUpper = $baseConstant + ($baseSlope * $upperBound);
        $rootExponent = 1.0 / $commonDenominator;
        if (\is_finite($baseAtLower) && \is_finite($baseAtUpper)) {
            $baseMinimum = \min($baseAtLower, $baseAtUpper);
            $baseMaximum = \max($baseAtLower, $baseAtUpper);
            if ($commonDenominator % 2 === 0) {
                if ($baseMaximum < 0.0) {
                    return [];
                }
                $rootLower = 0.0;
                $rootUpper = \pow(\max(0.0, $baseMaximum), $rootExponent);
            } else {
                $rootLower = $baseMinimum < 0.0
                    ? -\pow(-$baseMinimum, $rootExponent)
                    : \pow($baseMinimum, $rootExponent);
                $rootUpper = $baseMaximum < 0.0
                    ? -\pow(-$baseMaximum, $rootExponent)
                    : \pow($baseMaximum, $rootExponent);
            }
        } else {
            $leadingDegree = \count($polynomialCoefficients) - 1;
            $leadingMagnitude = \abs($polynomialCoefficients[$leadingDegree]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return null;
            }
            $maximumRatio = 0.0;
            foreach ($polynomialCoefficients as $degree => $coefficient) {
                if ($degree === $leadingDegree) {
                    continue;
                }
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + 16.0 * \PHP_FLOAT_EPSILON));
            if (!\is_finite($rootBound)) {
                return null;
            }
            $rootBound = $this->adjacentFloat($rootBound, 1) ?? $rootBound;
            $rootLower = $commonDenominator % 2 === 0 ? 0.0 : -$rootBound;
            $rootUpper = $rootBound;
        }
        if (
            !\is_finite($rootLower)
            || !\is_finite($rootUpper)
            || $rootLower >= $rootUpper
        ) {
            return null;
        }

        $scanSteps = \min(
            4096,
            \max($solverOptions->scanSteps, 256, $maximumDegree * 64),
        );
        $polynomialOptions = $scanSteps === $solverOptions->scanSteps
            ? $solverOptions
            : new SolverOptions(
                scanSteps: $scanSteps,
                maxIterations: $solverOptions->maxIterations,
                absoluteTolerance: $solverOptions->absoluteTolerance,
                relativeTolerance: $solverOptions->relativeTolerance,
                residualTolerance: $solverOptions->residualTolerance,
                maxPolynomialDegree: $solverOptions->maxPolynomialDegree,
            );
        $polynomialSolver = new PolynomialSolver();
        try {
            $rootCandidates = $polynomialSolver->solve(
                $polynomialCoefficients,
                $rootLower,
                $rootUpper,
                static fn (float $value): ?float =>
                    $polynomialSolver->evaluatePolynomial($polynomialCoefficients, $value),
                $polynomialOptions,
            );
        } catch (\DomainException) {
            return null;
        }
        if ($rootCandidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($rootCandidates as $rootCandidate) {
            $rootValue = $rootCandidate->value;
            $baseValue = \pow(\abs($rootValue), $commonDenominator);
            if ($commonDenominator % 2 !== 0 && $rootValue < 0.0) {
                $baseValue = -$baseValue;
            }
            if (!\is_finite($baseValue)) {
                continue;
            }
            $candidateValue = ($baseValue - $baseConstant) / $baseSlope;
            $positionTolerance = $solverOptions->positionTolerance($lowerBound, $upperBound);
            if (
                !\is_finite($candidateValue)
                || $candidateValue < $lowerBound - $positionTolerance
                || $candidateValue > $upperBound + $positionTolerance
            ) {
                continue;
            }
            $candidateValue = \min($upperBound, \max($lowerBound, $candidateValue));
            $residual = $residualAt($candidateValue);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidateValue,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidateValue, \abs($residual), $rootCandidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAdditiveRationalPowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftTerms = [];
        $rightTerms = [];
        $this->flattenAdditiveTerms($left, 1.0, $leftTerms);
        $this->flattenAdditiveTerms($right, -1.0, $rightTerms);
        if (\count($leftTerms) < 2 && \count($rightTerms) < 2) {
            return null;
        }

        $terms = [];
        foreach ($leftTerms as [$node, $sign]) {
            $terms[] = [$node, $sign, $leftSource, 0];
        }
        foreach ($rightTerms as [$node, $sign]) {
            $terms[] = [$node, $sign, $rightSource, $rightOffset];
        }

        $powerIndex = null;
        $powerBase = null;
        $powerExponent = null;
        $powerExpressionSource = null;
        foreach ($terms as $index => [$node, , $source, $sourceOffset]) {
            $powerSharesAdditiveSide = $index < \count($leftTerms)
                ? \count($leftTerms) > 1
                : \count($rightTerms) > 1;
            if (!$powerSharesAdditiveSide || !$this->containsVariable($node, $variable)) {
                continue;
            }

            $baseNode = null;
            $exponent = null;
            $nodeSpan = $node->span();
            $powerSource = \substr(
                $source,
                $nodeSpan->start - $sourceOffset,
                $nodeSpan->end - $nodeSpan->start,
            );
            if (
                $node instanceof BinaryOperationNode
                && $node->operator === BinaryOperator::Power
            ) {
                $baseNode = $node->left;
                $exponent = RationalLiteral::fromNode($node->right);
            } elseif ($node instanceof FunctionCallNode && $node->name === 'sqrt') {
                if (\count($node->arguments) !== 1) {
                    continue;
                }
                $baseNode = $node->arguments[0];
                $exponent = [1, 2];
                $powerSource = $this->rationalPowerSource($baseNode, $source, $exponent, $sourceOffset);
            } elseif ($node instanceof FunctionCallNode && $node->name === 'cbrt') {
                if (\count($node->arguments) !== 1) {
                    continue;
                }
                $baseNode = $node->arguments[0];
                $exponent = [1, 3];
                $powerSource = $this->rationalPowerSource($baseNode, $source, $exponent, $sourceOffset);
            } elseif ($node instanceof FunctionCallNode && $node->name === 'root') {
                if (\count($node->arguments) !== 2) {
                    continue;
                }
                $degree = RationalLiteral::fromNode($node->arguments[1]);
                if ($degree === null || $degree[1] !== 1 || $degree[0] === 0 || $degree[0] === \PHP_INT_MIN) {
                    continue;
                }
                $baseNode = $node->arguments[0];
                $exponent = [$degree[0] < 0 ? -1 : 1, \abs($degree[0])];
                $powerSource = $this->rationalPowerSource($baseNode, $source, $exponent, $sourceOffset);
            }
            if ($baseNode === null || $exponent === null || $exponent[1] <= 1) {
                continue;
            }
            if ($powerIndex !== null) {
                return null;
            }
            $powerIndex = $index;
            $powerBase = $baseNode;
            $powerExponent = $exponent;
            $powerExpressionSource = $powerSource;
        }
        if (
            $powerIndex === null
            || !$powerBase instanceof Node
            || $powerExponent === null
            || $powerExpressionSource === null
        ) {
            return null;
        }

        $basePolynomial = $this->extractPolynomial(
            $extractor,
            $powerBase,
            $powerBase->span()->start,
        );
        if ($basePolynomial === null) {
            return null;
        }

        $otherTerms = [];
        foreach ($terms as $index => [$node, $sign, $source, $sourceOffset]) {
            if ($index === $powerIndex) {
                continue;
            }
            if ($this->extractPolynomial($extractor, $node, $node->span()->start) === null) {
                return null;
            }
            $span = $node->span();
            $termSource = \substr(
                $source,
                $span->start - $sourceOffset,
                $span->end - $span->start,
            );
            $otherTerms[] = ($sign < 0.0 ? '-(' : '+(') . $termSource . ')';
        }
        $otherSide = '0' . \implode('', $otherTerms);
        [, $powerSign] = $terms[$powerIndex];
        $targetSide = $powerSign > 0.0
            ? '-(' . $otherSide . ')'
            : '(' . $otherSide . ')';
        $isolatedEquation = '(' . $powerExpressionSource . ')=(' . $targetSide . ')';
        if (\strlen($isolatedEquation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }

        $candidates = $this->solve(
            $isolatedEquation,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );
        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /** @param array{int, int} $exponent */
    private function rationalPowerSource(
        Node $base,
        string $source,
        array $exponent,
        int $sourceOffset = 0,
    ): string {
        $span = $base->span();
        $baseSource = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);

        return '(' . $baseSource . ')^(' . $exponent[0] . '/' . $exponent[1] . ')';
    }

    private function unboundedRationalPowerCallSource(
        Node $node,
        string $source,
        int $sourceOffset,
        EvaluationOptions $evaluationOptions,
    ): ?string {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof FunctionCallNode || !$evaluationOptions->functions->isBuiltIn($node->name)) {
            return null;
        }

        if ($node->name === 'sqrt' && \count($node->arguments) === 1) {
            $base = $node->arguments[0];
            $exponent = [1, 2];
        } elseif ($node->name === 'cbrt' && \count($node->arguments) === 1) {
            $base = $node->arguments[0];
            $exponent = [1, 3];
        } elseif ($node->name === 'root' && \count($node->arguments) === 2) {
            $degree = RationalLiteral::fromNode($node->arguments[1]);
            if (
                $degree === null
                || $degree[1] !== 1
                || $degree[0] === 0
                || $degree[0] === \PHP_INT_MIN
            ) {
                return null;
            }
            $base = $node->arguments[0];
            $exponent = [$degree[0] < 0 ? -1 : 1, \abs($degree[0])];
        } else {
            return null;
        }

        return $this->rationalPowerSource($base, $source, $exponent, $sourceOffset);
    }

    /**
     * @param list<array{Node, float}> $terms
     */
    private function flattenAdditiveTerms(Node $node, float $sign, array &$terms): void
    {
        if ($node instanceof GroupingNode) {
            $this->flattenAdditiveTerms($node->expression, $sign, $terms);

            return;
        }
        if ($node instanceof UnaryOperationNode) {
            $this->flattenAdditiveTerms(
                $node->operand,
                $sign * ($node->operator === UnaryOperator::Minus ? -1.0 : 1.0),
                $terms,
            );

            return;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $this->flattenAdditiveTerms($node->left, $sign, $terms);
            $this->flattenAdditiveTerms(
                $node->right,
                $sign * ($node->operator === BinaryOperator::Subtract ? -1.0 : 1.0),
                $terms,
            );

            return;
        }

        $terms[] = [$node, $sign];
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalPowerPolynomialEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $orientations = [
            [$this->unwrapGrouping($left), $leftSource, 0, $right, $rightSource],
            [$this->unwrapGrouping($right), $rightSource, $rightOffset, $left, $leftSource],
        ];
        foreach ($orientations as [$power, $powerSource, $powerSourceOffset, $target, $targetSource]) {
            if (
                !$power instanceof BinaryOperationNode
                || $power->operator !== BinaryOperator::Power
            ) {
                continue;
            }
            $exponent = RationalLiteral::fromNode($power->right);
            if (
                $exponent === null
                || $exponent[1] <= 1
                || $exponent[0] === 0
                || $exponent[0] === \PHP_INT_MIN
            ) {
                continue;
            }

            $numeratorPower = \abs($exponent[0]);
            $denominatorPower = $exponent[1];
            if (
                $numeratorPower > $solverOptions->maxPolynomialDegree
                || $denominatorPower > $solverOptions->maxPolynomialDegree
                || $numeratorPower > $evaluationOptions->limits->maxExponentMagnitude
                || $denominatorPower > $evaluationOptions->limits->maxExponentMagnitude
            ) {
                continue;
            }
            $basePolynomial = $this->extractPolynomial(
                $extractor,
                $power->left,
                $power->left->span()->start,
            );
            $targetPolynomial = $this->extractPolynomial(
                $extractor,
                $target,
                $target->span()->start,
            );
            if ($basePolynomial === null || $targetPolynomial === null) {
                continue;
            }
            $baseDegree = \count($basePolynomial) - 1;
            $targetDegree = \count($targetPolynomial) - 1;
            $transformedDegree = $exponent[0] > 0
                ? \max($baseDegree * $numeratorPower, $targetDegree * $denominatorPower)
                : ($baseDegree * $numeratorPower) + ($targetDegree * $denominatorPower);
            if ($transformedDegree > $solverOptions->maxPolynomialDegree) {
                continue;
            }

            $baseSpan = $power->left->span();
            $baseSource = \substr(
                $powerSource,
                $baseSpan->start - $powerSourceOffset,
                $baseSpan->end - $baseSpan->start,
            );
            $powerEquation = $exponent[0] > 0
                ? '(' . $baseSource . ')^' . $numeratorPower
                    . '=(' . $targetSource . ')^' . $denominatorPower
                : '((' . $baseSource . ')^' . $numeratorPower . ')*(('
                    . $targetSource . ')^' . $denominatorPower . ')=1';
            if (\strlen($powerEquation) > $evaluationOptions->limits->maxExpressionLength) {
                continue;
            }

            $polynomialScanSteps = \min(
                4096,
                \max($solverOptions->scanSteps, 256, $transformedDegree * 64),
            );
            $polynomialOptions = $polynomialScanSteps === $solverOptions->scanSteps
                ? $solverOptions
                : new SolverOptions(
                    scanSteps: $polynomialScanSteps,
                    maxIterations: $solverOptions->maxIterations,
                    absoluteTolerance: $solverOptions->absoluteTolerance,
                    relativeTolerance: $solverOptions->relativeTolerance,
                    residualTolerance: $solverOptions->residualTolerance,
                    maxPolynomialDegree: $solverOptions->maxPolynomialDegree,
                );
            $candidates = $this->solve(
                $powerEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $polynomialOptions,
            );
            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $solverOptions,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    /**
     * @param list<string> $terms
     */
    private function flattenAdditiveExpression(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $sign,
        array &$terms,
        float &$constant,
    ): bool {
        if ($node instanceof GroupingNode) {
            return $this->flattenAdditiveExpression(
                $node->expression,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $sign,
                $terms,
                $constant,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            $innerSign = $node->operator === \MathPHP\Ast\UnaryOperator::Minus ? -1.0 : 1.0;

            return $this->flattenAdditiveExpression(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $sign * $innerSign,
                $terms,
                $constant,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $rightSign = $node->operator === BinaryOperator::Add ? 1.0 : -1.0;
            $leftFlattened = $this->flattenAdditiveExpression(
                $node->left,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $sign,
                $terms,
                $constant,
            );
            $rightFlattened = $this->flattenAdditiveExpression(
                $node->right,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $sign * $rightSign,
                $terms,
                $constant,
            );

            return $leftFlattened && $rightFlattened;
        }
        if (!$this->containsVariable($node, $variable)) {
            $value = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($value === null || \count($value) !== 1 || !\is_finite($value[0])) {
                return false;
            }
            $constant += $sign * $value[0];

            return \is_finite($constant);
        }

        $span = $node->span();
        $term = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);
        $terms[] = $sign < 0.0 ? '-(' . $term . ')' : '(' . $term . ')';

        return true;
    }

    /**
     * Return true when one side is zero and the other is a product of affine
     * factors, allowing the roots to be solved without expanding the product.
     */
    private function isSimpleLinearProductEquation(
        Node $left,
        Node $right,
        int $rightOffset,
        PolynomialExtractor $extractor,
        SolverOptions $options,
    ): bool {
        $leftPolynomial = $this->extractPolynomial($extractor, $left, 0);
        $rightPolynomial = $this->extractPolynomial($extractor, $right, $rightOffset);
        if ($rightPolynomial === [0.0] && $leftPolynomial !== [0.0]) {
            $product = $left;
        } elseif ($leftPolynomial === [0.0] && $rightPolynomial !== [0.0]) {
            $product = $right;
        } else {
            return false;
        }

        $product = $this->unwrapGrouping($product);
        if (!$product instanceof BinaryOperationNode || $product->operator !== BinaryOperator::Multiply) {
            return false;
        }

        $factors = [];
        $this->flattenProductFactors($product, $factors);
        if (\count($factors) < 2) {
            return false;
        }

        $variableFactorCount = 0;
        $factorRoots = [];
        foreach ($factors as $factor) {
            $factor = $this->unwrapGrouping($factor);
            if (
                $factor instanceof BinaryOperationNode
                && $factor->operator === BinaryOperator::Power
            ) {
                $exponent = $extractor->extract($factor->right);
                if (
                    $exponent === null
                    || \count($exponent) !== 1
                    || $exponent[0] <= 0.0
                    || \floor($exponent[0]) !== $exponent[0]
                ) {
                    return false;
                }
                $factor = $this->unwrapGrouping($factor->left);
            }

            $coefficients = $extractor->extract($factor);
            if ($coefficients === null) {
                return false;
            }
            while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
                \array_pop($coefficients);
            }
            if (\count($coefficients) === 1) {
                if ($coefficients[0] === 0.0) {
                    return false;
                }
                continue;
            }
            if (\count($coefficients) !== 2 || $coefficients[1] === 0.0) {
                return false;
            }
            $root = -$coefficients[0] / $coefficients[1];
            if (!\is_finite($root)) {
                return false;
            }
            foreach ($factorRoots as $factorRoot) {
                if (\abs($factorRoot - $root) <= $options->positionTolerance($factorRoot, $root)) {
                    return false;
                }
            }
            $factorRoots[] = $root;
            ++$variableFactorCount;
        }

        return $variableFactorCount >= 2;
    }

    /**
     * Return a canonical exact root key for an affine polynomial factor.
     */
    private function exactLinearFactorRootKey(
        Node $factor,
        ExactRationalPolynomialExtractor $extractor,
    ): ?string {
        $coefficients = $extractor->polynomial($factor);
        if ($coefficients === null) {
            return null;
        }
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)][0] === '0') {
            \array_pop($coefficients);
        }
        if (\count($coefficients) !== 2 || $coefficients[1][0] === '0') {
            return null;
        }

        $integerArithmetic = new IntegerPolynomialExtractor('', [], 1);
        $numerator = $integerArithmetic->negateIntegerValue(
            $integerArithmetic->multiplyIntegerValues(
                $coefficients[0][0],
                $coefficients[1][1],
            ),
        );
        $denominator = $integerArithmetic->multiplyIntegerValues(
            $coefficients[0][1],
            $coefficients[1][0],
        );
        if ($denominator === '0') {
            return null;
        }
        if ($integerArithmetic->sign($denominator) < 0) {
            $numerator = $integerArithmetic->negateIntegerValue($numerator);
            $denominator = $integerArithmetic->negateIntegerValue($denominator);
        }
        $greatestCommonDivisor = $integerArithmetic->greatestCommonDivisorValues(
            $numerator,
            $denominator,
        );
        $numerator = $integerArithmetic->divideIntegerValueExactly($numerator, $greatestCommonDivisor);
        $denominator = $integerArithmetic->divideIntegerValueExactly($denominator, $greatestCommonDivisor);
        if ($numerator === null || $denominator === null) {
            return null;
        }

        return $numerator . '/' . $denominator;
    }

    /**
     * Check for an exact rational-polynomial root before retrying a failed
     * normalized equation through the original expression.
     *
     * @param array<string, int|float> $parameters
     */
    private function hasExactRationalRootInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        float $lowerBound,
        float $upperBound,
    ): bool {
        $form = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $options->maxPolynomialDegree,
            $evaluationOptions,
        ))->rationalDifference($left, $right);
        if ($form === null) {
            return false;
        }
        [$numerator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        if (\count($numerator) === 1 && $numerator[0] === '0') {
            return false;
        }

        $counter = new ExactPolynomialRootCounter();
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($lower === null || $upper === null) {
            return false;
        }
        $count = $counter->countOpenInterval(
            $numerator,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        if ($count === null) {
            return false;
        }
        if ($count > 0) {
            return true;
        }

        return $counter->isRootAt($numerator, $lower) === true
            || $counter->isRootAt($numerator, $upper) === true;
    }

    /**
     * Recover polynomial roots when floating-point isolation disagrees with
     * an exact Sturm count. A null result means certification was unavailable
     * or the approximate root count already matched.
     *
     * @param list<string> $coefficients
     * @param list<EquationSolution> $approximateSolutions
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function recoverPolynomialSolutionsFromExactIsolation(
        array $coefficients,
        array $approximateSolutions,
        float $lowerBound,
        float $upperBound,
        callable $residualAt,
    ): ?array {
        $lower = RationalLiteral::fromFloatAsStrings($lowerBound);
        $upper = RationalLiteral::fromFloatAsStrings($upperBound);
        if ($lower === null || $upper === null) {
            return null;
        }
        $counter = new ExactPolynomialRootCounter();
        $openCount = $counter->countOpenInterval(
            $coefficients,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        $lowerIsRoot = $counter->isRootAt($coefficients, $lower);
        $upperIsRoot = $counter->isRootAt($coefficients, $upper);
        if ($openCount === null || $lowerIsRoot === null || $upperIsRoot === null) {
            return null;
        }
        $exactCount = $openCount + (int) $lowerIsRoot + (int) $upperIsRoot;
        if ($exactCount === \count($approximateSolutions)) {
            return null;
        }

        $intervals = $counter->isolateOpenInterval(
            $coefficients,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
            512,
            ['1', '1000000000000000000'],
        );
        if ($intervals === null) {
            return null;
        }

        $rootValues = [];
        foreach ($intervals as [$lowNumerator, $lowDenominator, $highNumerator, $highDenominator]) {
            $low = $this->decimalRationalToFloat($lowNumerator, $lowDenominator);
            $high = $this->decimalRationalToFloat($highNumerator, $highDenominator);
            $rootValues[] = $low === $high ? $low : ($low / 2.0) + ($high / 2.0);
        }
        if ($lowerIsRoot) {
            $rootValues[] = $lowerBound;
        }
        if ($upperIsRoot) {
            $rootValues[] = $upperBound;
        }
        $rootValues = \array_values(\array_unique($rootValues, SORT_REGULAR));
        if (\count($rootValues) !== $exactCount) {
            return null;
        }
        \sort($rootValues, SORT_NUMERIC);

        $solutions = [];
        foreach ($rootValues as $value) {
            if (!\is_finite($value) || $value < $lowerBound || $value > $upperBound) {
                return null;
            }
            $residual = $residualAt($value);
            if ($residual === null || !\is_finite($residual)) {
                return null;
            }
            $solutions[] = new EquationSolution($value, \abs($residual), 0);
        }

        return $solutions;
    }

    private function decimalRationalToFloat(string $numerator, string $denominator): float
    {
        $negative = \str_starts_with($numerator, '-');
        $digits = \ltrim($numerator, '-');
        if ($digits === '0') {
            return 0.0;
        }
        $numeratorPrefix = \substr($digits, 0, 17);
        $denominatorPrefix = \substr($denominator, 0, 17);
        $numeratorMantissa = (float) $numeratorPrefix / (10 ** (\strlen($numeratorPrefix) - 1));
        $denominatorMantissa = (float) $denominatorPrefix / (10 ** (\strlen($denominatorPrefix) - 1));
        $exponent = \strlen($digits) - \strlen($denominator);
        $value = ($numeratorMantissa / $denominatorMantissa) * (10 ** $exponent);

        return $negative ? -$value : $value;
    }

    /**
     * Flatten a product into factors whose zero sets can be solved separately.
     * A null result means a zero constant or an unevaluable constant prevents
     * safe reduction to a finite union of factor roots.
     *
     * @return list<Node>|null
     */
    private function zeroProductFactors(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Multiply
        ) {
            $leftFactors = $this->zeroProductFactors($node->left, $variable, $extractor);
            $rightFactors = $this->zeroProductFactors($node->right, $variable, $extractor);
            if ($leftFactors === null || $rightFactors === null) {
                return null;
            }

            return [...$leftFactors, ...$rightFactors];
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Divide
        ) {
            return $this->zeroProductFactors($node->left, $variable, $extractor);
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Power
        ) {
            $exponent = $this->extractPolynomial($extractor, $node->right, 0);
            if (
                $exponent !== null
                && \count($exponent) === 1
                && $exponent[0] > 0.0
            ) {
                return $this->zeroProductFactors($node->left, $variable, $extractor);
            }

            if ($exponent !== null && \count($exponent) === 1 && $exponent[0] <= 0.0) {
                return [];
            }

            return [$node];
        }

        if (!$this->containsVariable($node, $variable)) {
            $constant = $this->extractPolynomial($extractor, $node, 0);
            if (
                $constant === null
                || (\count($constant) === 1 && $constant[0] === 0.0)
            ) {
                return null;
            }

            return [];
        }

        return [$node];
    }

    /**
     * @param list<EquationSolution> $solutions
     * @param list<string>|null $exactPolynomialCoefficients
     * @return list<EquationSolution>
     */
    private function includeClosedIntervalEndpointRoots(
        array $solutions,
        float $lowerBound,
        float $upperBound,
        ?array $exactPolynomialCoefficients,
    ): array {
        if ($exactPolynomialCoefficients === null) {
            return $solutions;
        }
        $rootCounter = new ExactPolynomialRootCounter();
        foreach ([$lowerBound, $upperBound] as $endpoint) {
            $fraction = RationalLiteral::fromFloatAsStrings($endpoint);
            if (
                $fraction === null
                || $rootCounter->isRootAt($exactPolynomialCoefficients, $fraction) !== true
            ) {
                continue;
            }
            foreach ($solutions as $solution) {
                if ($solution->value === $endpoint) {
                    continue 2;
                }
            }
            $solutions[] = new EquationSolution($endpoint, 0.0, 0);
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Recover polynomial roots with exact rational isolation after floating solvers fail.
     *
     * @param array<string, int|float> $parameters
     * @param list<string> $exactPolynomialCoefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null Null means exact isolation or float verification was inconclusive.
     */
    private function solvePolynomialByExactIsolation(
        string $equation,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        array $exactPolynomialCoefficients,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $rootCounter = new PolynomialRootCountingSolver();
        $allRealRoots = !\is_finite($lowerBound)
            || !\is_finite($upperBound)
            || !\is_finite($upperBound - $lowerBound);
        $intervals = $allRealRoots
            ? $rootCounter->isolateAllReal(
                $equation,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                4096,
                '1/1000000000000000000',
            )
            : $rootCounter->isolate(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                256,
                '1/1000000000000000000',
            );
        if ($intervals === null) {
            return null;
        }

        $integerArithmetic = new IntegerPolynomialExtractor(
            '',
            [],
            \count($exactPolynomialCoefficients) - 1,
        );
        $exactRootCounter = new ExactPolynomialRootCounter();
        $lowerBoundFraction = \is_finite($lowerBound)
            ? RationalLiteral::fromFloatAsStrings($lowerBound)
            : null;
        $upperBoundFraction = \is_finite($upperBound)
            ? RationalLiteral::fromFloatAsStrings($upperBound)
            : null;
        if (
            ($allRealRoots && \is_finite($lowerBound) && $lowerBoundFraction === null)
            || ($allRealRoots && \is_finite($upperBound) && $upperBoundFraction === null)
        ) {
            return null;
        }
        $solutions = [];
        foreach ($intervals as $interval) {
            if ($allRealRoots && $lowerBoundFraction !== null) {
                $comparison = $this->compareIsolatedRootToBound(
                    $interval,
                    $exactPolynomialCoefficients,
                    $lowerBoundFraction,
                    $exactRootCounter,
                    $integerArithmetic,
                );
                if ($comparison === null) {
                    return null;
                }
                if ($comparison < 0) {
                    continue;
                }
            }
            if ($allRealRoots && $upperBoundFraction !== null) {
                $comparison = $this->compareIsolatedRootToBound(
                    $interval,
                    $exactPolynomialCoefficients,
                    $upperBoundFraction,
                    $exactRootCounter,
                    $integerArithmetic,
                );
                if ($comparison === null) {
                    return null;
                }
                if ($comparison > 0) {
                    continue;
                }
            }
            $lower = $integerArithmetic->ratio(
                $interval->lowerNumerator,
                $interval->lowerDenominator,
            );
            $upper = $integerArithmetic->ratio(
                $interval->upperNumerator,
                $interval->upperDenominator,
            );
            if (!\is_float($lower) || !\is_float($upper)) {
                return null;
            }
            $value = $interval->isExactRoot ? $lower : ($lower / 2.0) + ($upper / 2.0);
            if (!\is_finite($value)) {
                return null;
            }
            if ($value < $lowerBound || $value > $upperBound) {
                if ($allRealRoots) {
                    $value = \max($lowerBound, \min($upperBound, $value));
                } else {
                    return null;
                }
            }
            $residual = $residualAt($value);
            if (
                $residual === null
                || !\is_finite($residual)
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                return null;
            }
            $solutions[] = new EquationSolution($value, \abs($residual), 0);
        }

        return $this->includeClosedIntervalEndpointRoots(
            $solutions,
            $lowerBound,
            $upperBound,
            $exactPolynomialCoefficients,
        );
    }

    /**
     * Compare an isolated exact root with a rational boundary.
     *
     * @param list<string> $coefficients
     * @param array{string, string} $bound
     */
    private function compareIsolatedRootToBound(
        RationalRootInterval $interval,
        array $coefficients,
        array $bound,
        ExactPolynomialRootCounter $rootCounter,
        IntegerPolynomialExtractor $integerArithmetic,
    ): ?int {
        $lowerComparison = $integerArithmetic->compareIntegerRatioToFraction(
            $interval->lowerNumerator,
            $interval->lowerDenominator,
            $bound[0],
            $bound[1],
        );
        $upperComparison = $integerArithmetic->compareIntegerRatioToFraction(
            $interval->upperNumerator,
            $interval->upperDenominator,
            $bound[0],
            $bound[1],
        );
        if ($lowerComparison === null || $upperComparison === null) {
            return null;
        }
        if ($interval->isExactRoot) {
            return $lowerComparison;
        }
        if ($lowerComparison >= 0) {
            return 1;
        }
        if ($upperComparison <= 0) {
            return -1;
        }

        $rootsBelowBoundary = $rootCounter->countOpenInterval(
            $coefficients,
            $interval->lowerNumerator,
            $interval->lowerDenominator,
            $bound[0],
            $bound[1],
        );
        if ($rootsBelowBoundary === null) {
            return null;
        }
        if ($rootsBelowBoundary > 0) {
            return -1;
        }

        $boundaryIsRoot = $rootCounter->isRootAt($coefficients, $bound);

        return $boundaryIsRoot === null ? null : ($boundaryIsRoot ? 0 : 1);
    }

    /**
     * Reduce a positive integer power equal to zero to its base equation.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveZeroPowerEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $leftPolynomial = $this->extractPolynomial($extractor, $left, 0);
        $rightPolynomial = $this->extractPolynomial($extractor, $right, $rightOffset);
        if ($rightPolynomial === [0.0]) {
            $powerSide = $left;
            $source = $leftSource;
            $sourceOffset = 0;
        } elseif ($leftPolynomial === [0.0]) {
            $powerSide = $right;
            $source = $rightSource;
            $sourceOffset = 0;
        } else {
            return null;
        }
        $power = $this->extractZeroPowerFactor($powerSide, $extractor);
        if (
            $power === null
            || !$this->containsVariable($power, $variable)
        ) {
            return null;
        }
        $exponent = $extractor->extract($power->right);
        if (
            $exponent === null
            || \count($exponent) !== 1
            || !\is_finite($exponent[0])
            || $exponent[0] <= 0.0
            || \floor($exponent[0]) !== $exponent[0]
        ) {
            return null;
        }
        $basePolynomial = $extractor->extract($power->left);
        if ($basePolynomial !== null && \count($basePolynomial) > 2) {
            return null;
        }
        $baseSpan = $power->left->span();
        $baseSource = \substr(
            $source,
            $baseSpan->start - $sourceOffset,
            $baseSpan->end - $baseSpan->start,
        );
        if (\strlen($baseSource) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }
        $baseEquation = '(' . $baseSource . ')=0';
        $candidates = [];
        try {
            $candidates = $this->solve(
                $baseEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        } catch (InfiniteSolutionSetException) {
            throw new InfiniteSolutionSetException(
                'A zero power has infinitely many solutions because its base equation is an identity.',
            );
        } catch (\DomainException) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $value = $this->refineRootCandidateByFloatSearch(
                $power->left,
                $candidate->value,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            $residual = $residualAt($value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $value,
                    $residual,
                    $candidateScaleAt,
                    $solverOptions,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($value, \abs($residual), $candidate->iterations),
                $solverOptions,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param bool $positivePowerOnly
     * @return list<EquationSolution>|null
     */
    private function solveZeroProductEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        bool $positivePowerOnly = false,
    ): ?array {
        $leftPolynomial = $this->extractPolynomial($extractor, $left, 0);
        $rightPolynomial = $this->extractPolynomial($extractor, $right, $rightOffset);
        $productSide = null;
        $productSource = '';
        if ($rightPolynomial === [0.0] && $leftPolynomial !== [0.0]) {
            $productSide = $left;
            $productSource = $leftSource;
        } elseif ($leftPolynomial === [0.0] && $rightPolynomial !== [0.0]) {
            $productSide = $right;
            $productSource = $rightSource;
        }
        $unwrappedProductSide = $productSide === null
            ? null
            : $this->unwrapGrouping($productSide);
        if (!($unwrappedProductSide instanceof BinaryOperationNode)) {
            return null;
        }
        if ($positivePowerOnly) {
            if (!$this->containsNonPolynomialPositivePowerFactor($productSide, $extractor)) {
                return null;
            }
        }
        if (
            !\in_array(
                $unwrappedProductSide->operator,
                [BinaryOperator::Multiply, BinaryOperator::Divide, BinaryOperator::Power],
                true,
            )
        ) {
            return null;
        }

        $factors = $this->zeroProductFactors($productSide, $variable, $extractor);
        if (
            $factors === null
            || (\count($factors) === 1 && $factors[0] === $unwrappedProductSide)
        ) {
            return null;
        }

        $domainHoleDenominators = [
            ...$this->variableDenominators($left, $leftSource, $variable),
            ...$this->variableDenominators($right, $rightSource, $variable),
        ];
        $domainHolePositions = [];
        $exactHoleExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ($domainHoleDenominators as $denominator) {
            try {
                foreach (
                    $this->solve(
                        $denominator['equation'],
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ) as $hole
                ) {
                    $domainHolePositions[] = [
                        'value' => $hole->value,
                        'exactCoefficients' => $exactHoleExtractor->integerCoefficients(
                            $exactHoleExtractor->polynomial($denominator['denominator']),
                        ),
                    ];
                }
            } catch (\DomainException | \InvalidArgumentException) {
                continue;
            }
        }
        $factorSolutions = [];
        $factorSolutionRootKeys = [];
        foreach ($factors as $factor) {
            $factorRootKey = $this->exactLinearFactorRootKey($factor, $exactHoleExtractor);
            $span = $factor->span();
            $factorSource = \substr(
                $productSource,
                $span->start,
                $span->end - $span->start,
            );
            foreach (
                $this->solve(
                    $factorSource . '=0',
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                ) as $candidate
            ) {
                $value = $this->refineRootCandidateByFloatSearch(
                    $factor,
                    $candidate->value,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                $coincidesWithDomainHole = false;
                foreach ($domainHolePositions as $domainHole) {
                    $distance = \abs($value - $domainHole['value']);
                    if ($distance > $solverOptions->positionTolerance($value, $domainHole['value'])) {
                        continue;
                    }
                    $exactCoefficients = $domainHole['exactCoefficients'];
                    if ($exactCoefficients === null) {
                        $coincidesWithDomainHole = true;
                        break;
                    }
                    $candidateFraction = RationalLiteral::fromFloatAsStrings($value);
                    if (
                        $value !== $domainHole['value']
                        && ($candidateFraction === null
                            || (new ExactPolynomialRootCounter())->isRootAt(
                                $exactCoefficients,
                                $candidateFraction,
                            ) !== true)
                    ) {
                        continue;
                    }
                    $coincidesWithDomainHole = true;
                    break;
                }
                if ($coincidesWithDomainHole) {
                    continue;
                }

                $residual = $residualAt($value);
                if ($residual === null) {
                    continue;
                }

                $factorSolution = new EquationSolution(
                    $value,
                    \abs($residual),
                    $candidate->iterations,
                );
                $duplicate = false;
                foreach ($factorSolutions as $index => $existing) {
                    $sameExactRoot = $factorRootKey !== null
                        && $factorRootKey === ($factorSolutionRootKeys[$index] ?? null);
                    if (!$sameExactRoot && $existing->value !== $factorSolution->value) {
                        continue;
                    }
                    if ($factorSolution->residual < $existing->residual) {
                        $factorSolutions[$index] = $factorSolution;
                    }
                    $duplicate = true;
                    break;
                }
                if (!$duplicate) {
                    $factorSolutions[] = $factorSolution;
                    $factorSolutionRootKeys[] = $factorRootKey;
                }
            }
        }
        \usort(
            $factorSolutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $factorSolutions;
    }

    private function containsNonPolynomialPositivePowerFactor(
        Node $node,
        PolynomialExtractor $extractor,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return false;
        }

        if ($node->operator === BinaryOperator::Power) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            );
            $base = $this->extractPolynomial(
                $extractor,
                $node->left,
                $node->left->span()->start,
            );
            if (
                $exponent !== null
                && \count($exponent) === 1
                && $exponent[0] > 0.0
                && $base === null
            ) {
                return true;
            }

            return false;
        }
        if ($node->operator === BinaryOperator::Multiply) {
            return $this->containsNonPolynomialPositivePowerFactor($node->left, $extractor)
                || $this->containsNonPolynomialPositivePowerFactor($node->right, $extractor);
        }
        if ($node->operator === BinaryOperator::Divide) {
            return $this->containsNonPolynomialPositivePowerFactor($node->left, $extractor);
        }

        return false;
    }

    private function mustPropagateEvaluationError(EvaluationException $error): bool
    {
        return \in_array(
            $error->errorCode(),
            [
                'eval.unknown_variable',
                'eval.unknown_function',
                'eval.arity',
                'eval.custom_function',
            ],
            true,
        );
    }

    private function parseSide(
        string $expression,
        int $offset,
        EvaluationOptions $options,
    ): Node {
        try {
            $tokens = (new Lexer($expression, $options->limits))->tokenize();

            return (new Parser($tokens, $options->limits, $options->functions))->parse();
        } catch (LexicalException | ParseException $error) {
            throw $this->shiftException($error, $offset);
        }
    }

    private function shiftException(
        MathException $error,
        int $offset,
    ): MathException {
        if ($offset === 0) {
            return $error;
        }

        $start = $error->span()->start;
        $end = $error->span()->end;
        $message = \preg_replace('/ at position \d+$/', '', $error->getMessage());
        $span = new SourceSpan($start + $offset, $end + $offset);

        return match (true) {
            $error instanceof LexicalException => new LexicalException(
                $message ?? 'Equation expression failed',
                $error->errorCode(),
                $span,
                $error,
            ),
            $error instanceof ParseException => new ParseException(
                $message ?? 'Equation expression failed',
                $error->errorCode(),
                $span,
                $error,
            ),
            default => new EvaluationException(
                $message ?? 'Equation expression failed',
                $error->errorCode(),
                $span,
                $error,
            ),
        };
    }

    /**
     * Enumerate the known real zeros of zeta, which occur at negative even integers.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveZetaTrivialZeroEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $call = $this->unwrapGrouping($left);
        $target = $right;
        if (!$call instanceof FunctionCallNode || $call->name !== 'zeta') {
            $call = $this->unwrapGrouping($right);
            $target = $left;
        }
        if (
            !$call instanceof FunctionCallNode
            || $call->name !== 'zeta'
            || \count($call->arguments) !== 1
            || !$this->containsVariable($call->arguments[0], $variable)
            || $this->containsVariable($target, $variable)
        ) {
            return null;
        }

        try {
            $targetValue = $this->evaluateNode($target, $parameters, $evaluationOptions);
        } catch (EvaluationException) {
            return null;
        }
        if ($targetValue !== 0 && $targetValue !== 0.0) {
            return null;
        }

        if (
            $this->zetaArgumentHasNegativeReciprocalAccumulation(
                $call->arguments[0],
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            throw new InfiniteRootAccumulationException(
                'The zeta trivial zeros have infinitely many roots accumulating at a reciprocal boundary.',
            );
        }

        $coefficients = $extractor->extract($call->arguments[0]);
        if ($coefficients === null) {
            return null;
        }
        while (\count($coefficients) > 1 && $coefficients[\count($coefficients) - 1] === 0.0) {
            \array_pop($coefficients);
        }
        $range = $this->polynomialRange(
            $coefficients,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        if ($range === null) {
            return null;
        }
        if (\count($coefficients) === 1) {
            $constantArgument = $coefficients[0];
            if (
                $constantArgument <= -2.0
                && $constantArgument / 2.0 === \floor($constantArgument / 2.0)
            ) {
                throw new InfiniteSolutionSetException(
                    'The zeta argument is identically a trivial zero.',
                );
            }

            return [];
        }

        $tolerance = 16.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($range[0]), \abs($range[1]));
        $firstLevel = 2.0 * \ceil(($range[0] - $tolerance) / 2.0);
        $lastLevel = 2.0 * \floor((\min($range[1], -2.0) + $tolerance) / 2.0);
        if ($firstLevel > $lastLevel) {
            return [];
        }
        if (
            !\is_finite($lastLevel - $firstLevel)
            || \abs($firstLevel) > 9_007_199_254_740_991.0
            || \abs($lastLevel) > 9_007_199_254_740_991.0
        ) {
            throw new \DomainException(
                'The zeta trivial-zero set exceeds the exact numeric range.',
            );
        }

        $count = (int) \floor(($lastLevel - $firstLevel) / 2.0) + 1;
        if ($count > self::MAX_DOMAIN_BOUNDARY_PROBES) {
            throw new \DomainException(
                'The zeta trivial-zero set exceeds the equation boundary limit.',
            );
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        for ($index = 0; $index < $count; ++$index) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $firstLevel + (2.0 * $index);
            $levelSolutions = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $solverOptions,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $levelCoefficients,
                    $value,
                ),
            );
            if ($levelSolutions === null) {
                return null;
            }
            foreach ($levelSolutions as $levelSolution) {
                $residual = $residualAt($levelSolution->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $levelSolution->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $levelSolution->value,
                        \abs($residual),
                        $levelSolution->iterations,
                    ),
                    $solverOptions,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function zetaArgumentHasNegativeReciprocalAccumulation(
        Node $argument,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $options,
        SolverOptions $solverOptions,
    ): bool {
        while ($argument instanceof GroupingNode) {
            $argument = $argument->expression;
        }
        if (
            !$argument instanceof BinaryOperationNode
            || $argument->operator !== BinaryOperator::Divide
            || $this->containsVariable($argument->left, $variable)
            || $lowerBound > 0.0
            || $upperBound < 0.0
        ) {
            return false;
        }
        $denominatorCoefficients = (new PolynomialExtractor(
            $variable,
            $parameters,
            $options,
            $solverOptions->maxPolynomialDegree,
        ))->extract($argument->right);
        if ($denominatorCoefficients === null || ($denominatorCoefficients[0] ?? null) !== 0.0) {
            return false;
        }
        $denominatorDegree = 0;
        while (
            isset($denominatorCoefficients[$denominatorDegree])
            && $denominatorCoefficients[$denominatorDegree] === 0.0
        ) {
            ++$denominatorDegree;
        }
        $leadingCoefficient = $denominatorCoefficients[$denominatorDegree] ?? 0.0;
        if ($leadingCoefficient === 0.0) {
            return false;
        }
        try {
            $numerator = (float) $this->evaluateNode($argument->left, $parameters, $options);
        } catch (EvaluationException) {
            return false;
        }
        if ($numerator === 0.0 || !\is_finite($numerator)) {
            return false;
        }

        $numeratorIsNegative = $numerator < 0.0;
        $denominatorIsNegativeLeftOfZero = ($leadingCoefficient < 0.0)
            !== (($denominatorDegree % 2) === 1);
        $denominatorIsNegativeRightOfZero = $leadingCoefficient < 0.0;

        return ($lowerBound < 0.0
                && ($numeratorIsNegative !== $denominatorIsNegativeLeftOfZero))
            || ($upperBound > 0.0
                && ($numeratorIsNegative !== $denominatorIsNegativeRightOfZero));
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveVariableIntegerArgumentLevels(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $calls = [];
        $this->collectVariableIntegerArgumentCalls($left, $variable, $calls);
        $this->collectVariableIntegerArgumentCalls($right, $variable, $calls);
        if ($calls === []) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $hasDiscreteOrderDomain = false;
        foreach ($calls as [$call, $argumentIndex, $minimumSupportedOrder, $maximumSupportedOrder]) {
            $coefficients = $extractor->extract($call->arguments[$argumentIndex]);
            if ($coefficients === null) {
                $argumentSpan = $call->arguments[$argumentIndex]->span();
                $argumentSource = \substr(
                    $equation,
                    $argumentSpan->start,
                    $argumentSpan->end - $argumentSpan->start,
                );
                $hasDiscreteOrderDomain = true;
                $minimumOrder = $minimumSupportedOrder;
                $maximumOrder = $maximumSupportedOrder;
                $argumentRange = $this->boundedExpressionRange(
                    $call->arguments[$argumentIndex],
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if (
                    $argumentRange !== null
                    && \is_finite($argumentRange[0])
                    && \is_finite($argumentRange[1])
                ) {
                    $rangeTolerance = 16.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($argumentRange[0]), \abs($argumentRange[1]));
                    $minimumOrder = \max(
                        $minimumOrder,
                        (int) \ceil($argumentRange[0] - $rangeTolerance),
                    );
                    $maximumOrder = \min(
                        $maximumOrder,
                        (int) \floor($argumentRange[1] + $rangeTolerance),
                    );
                }
                if (
                    $maximumOrder - $minimumOrder + 1 > self::MAX_ADAPTIVE_SCAN_STEPS
                ) {
                    return null;
                }
                for ($order = $minimumOrder; $order <= $maximumOrder; ++$order) {
                    try {
                        $levelSolutions = $this->solve(
                            '(' . $argumentSource . ') = ' . $order,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                    } catch (InfiniteSolutionSetException) {
                        $levelIntervals = (new EquationSetSolver())->solve(
                            '(' . $argumentSource . ') = ' . $order,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        );
                        $argumentStart = $argumentSpan->start;
                        $argumentLength = $argumentSpan->end - $argumentStart;
                        $levelEquation = \substr($equation, 0, $argumentStart)
                            . (string) $order
                            . \substr($equation, $argumentStart + $argumentLength);
                        [$levelLeftSource, $levelRightSource, $levelRightOffset] =
                            $this->splitEquation($levelEquation);
                        $levelLeft = $this->parseSide($levelLeftSource, 0, $evaluationOptions);
                        $levelRight = $this->parseSide(
                            $levelRightSource,
                            $levelRightOffset,
                            $evaluationOptions,
                        );
                        $levelDependsOnVariable = $this->containsVariable($levelLeft, $variable)
                            || $this->containsVariable($levelRight, $variable);

                        foreach ($levelIntervals as $interval) {
                            if (!$levelDependsOnVariable && $interval->lowerBound < $interval->upperBound) {
                                $midpoint = $interval->lowerBound
                                    + (($interval->upperBound - $interval->lowerBound) / 2.0);
                                $residual = $residualAt($midpoint);
                                if (
                                    $residual !== null
                                    && $this->isResidualAcceptableAt(
                                        $midpoint,
                                        $residual,
                                        $candidateScaleAt,
                                        $solverOptions,
                                    )
                                ) {
                                    throw new InfiniteSolutionSetException(
                                        'Equation holds throughout an interval of a supported integer level.',
                                    );
                                }

                                continue;
                            }
                            if ($interval->lowerBound === $interval->upperBound) {
                                $levelSolutions = [
                                    new EquationSolution($interval->lowerBound, 0.0, 0),
                                ];
                            } else {
                                $levelSolutions = $this->solve(
                                    $levelEquation,
                                    $variable,
                                    $interval->lowerBound,
                                    $interval->upperBound,
                                    $parameters,
                                    $evaluationOptions,
                                    $solverOptions,
                                );
                            }

                            foreach ($levelSolutions as $levelSolution) {
                                if (!$interval->contains($levelSolution->value)) {
                                    continue;
                                }
                                $residual = $residualAt($levelSolution->value);
                                if (
                                    $residual === null
                                    || !$this->isResidualAcceptableAt(
                                        $levelSolution->value,
                                        $residual,
                                        $candidateScaleAt,
                                        $solverOptions,
                                    )
                                ) {
                                    continue;
                                }
                                $this->addSolution(
                                    $solutions,
                                    new EquationSolution(
                                        $levelSolution->value,
                                        \abs($residual),
                                        $levelSolution->iterations,
                                    ),
                                    $solverOptions,
                                );
                            }
                        }

                        continue;
                    }

                    foreach ($levelSolutions as $levelSolution) {
                        $residual = $residualAt($levelSolution->value);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $levelSolution->value,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution(
                                $levelSolution->value,
                                \abs($residual),
                                $levelSolution->iterations,
                            ),
                            $solverOptions,
                        );
                    }
                }

                continue;
            }
            while (\count($coefficients) > 1 && $coefficients[\count($coefficients) - 1] === 0.0) {
                \array_pop($coefficients);
            }
            $range = $this->polynomialRange(
                $coefficients,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($range === null) {
                return null;
            }

            if (\count($coefficients) === 1) {
                $constantOrder = $coefficients[0];
                if (
                    \floor($constantOrder) !== $constantOrder
                    || $constantOrder < $minimumSupportedOrder
                    || $constantOrder > $maximumSupportedOrder
                ) {
                    return [];
                }

                continue;
            }

            $hasDiscreteOrderDomain = true;
            $orderTolerance = 16.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($range[0]), \abs($range[1]));
            $minimumOrder = \max(
                $minimumSupportedOrder,
                (int) \ceil($range[0] - $orderTolerance),
            );
            $maximumOrder = \min(
                $maximumSupportedOrder,
                (int) \floor($range[1] + $orderTolerance),
            );
            if ($maximumOrder - $minimumOrder + 1 > self::MAX_ADAPTIVE_SCAN_STEPS) {
                return null;
            }
            for ($order = $minimumOrder; $order <= $maximumOrder; ++$order) {
                $levelCoefficients = $coefficients;
                $levelCoefficients[0] -= $order;
                $levelSolutions = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $levelCoefficients,
                        $value,
                    ),
                    $solverOptions,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                        $levelCoefficients,
                        $value,
                    ),
                );
                if ($levelSolutions === null) {
                    return null;
                }

                foreach ($levelSolutions as $levelSolution) {
                    $residual = $residualAt($levelSolution->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $levelSolution->value,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $levelSolution->value,
                            \abs($residual),
                            $levelSolution->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }
        }

        return $hasDiscreteOrderDomain ? $solutions : null;
    }

    /** @param list<array{FunctionCallNode, int, int, int}> $calls */
    private function collectVariableIntegerArgumentCalls(
        Node $node,
        string $variable,
        array &$calls,
    ): void {
        if ($node instanceof FunctionCallNode) {
            if (
                \in_array($node->name, ['besselj', 'besseli', 'bessely', 'polygamma'], true)
                && \count($node->arguments) === 2
                && $this->containsVariable($node->arguments[0], $variable)
            ) {
                $minimumOrder = match ($node->name) {
                    'polygamma' => 0,
                    default => -SpecialFunctions::MAX_BESSEL_ORDER,
                };
                $maximumOrder = $node->name === 'polygamma'
                    ? SpecialFunctions::MAX_POLYGAMMA_ORDER
                    : SpecialFunctions::MAX_BESSEL_ORDER;
                $calls[] = [
                    $node,
                    0,
                    $minimumOrder,
                    $maximumOrder,
                ];
            } elseif (
                $node->name === 'doublefactorial'
                && \count($node->arguments) === 1
                && $this->containsVariable($node->arguments[0], $variable)
            ) {
                $calls[] = [$node, 0, -1, ResourceLimits::factorialMaximum()];
            } elseif (
                $node->name === 'lambertw'
                && \count($node->arguments) === 2
                && $this->containsVariable($node->arguments[1], $variable)
            ) {
                $calls[] = [$node, 1, -1, 0];
            } elseif (
                \in_array($node->name, ['binomial', 'permutation'], true)
                && \count($node->arguments) === 2
            ) {
                foreach ([0, 1] as $argumentIndex) {
                    if ($this->containsVariable($node->arguments[$argumentIndex], $variable)) {
                        $calls[] = [$node, $argumentIndex, 0, \PHP_INT_MAX];
                    }
                }
            }
            foreach ($node->arguments as $argument) {
                $this->collectVariableIntegerArgumentCalls($argument, $variable, $calls);
            }

            return;
        }

        if ($node instanceof GroupingNode) {
            $this->collectVariableIntegerArgumentCalls($node->expression, $variable, $calls);
        } elseif ($node instanceof UnaryOperationNode) {
            $this->collectVariableIntegerArgumentCalls($node->operand, $variable, $calls);
        } elseif ($node instanceof BinaryOperationNode) {
            $this->collectVariableIntegerArgumentCalls($node->left, $variable, $calls);
            $this->collectVariableIntegerArgumentCalls($node->right, $variable, $calls);
        } elseif ($node instanceof FactorialNode) {
            $this->collectVariableIntegerArgumentCalls($node->operand, $variable, $calls);
        }
    }

    private function containsFunctionCall(Node $node): bool
    {
        return match (true) {
            $node instanceof FunctionCallNode => true,
            $node instanceof GroupingNode => $this->containsFunctionCall($node->expression),
            $node instanceof UnaryOperationNode => $this->containsFunctionCall($node->operand),
            $node instanceof BinaryOperationNode => $this->containsFunctionCall($node->left)
                || $this->containsFunctionCall($node->right),
            $node instanceof FactorialNode => $this->containsFunctionCall($node->operand),
            default => false,
        };
    }

    private function containsVariable(Node $node, string $variable): bool
    {
        return match (true) {
            $node instanceof VariableNode => $node->name === $variable,
            $node instanceof GroupingNode => $this->containsVariable(
                $node->expression,
                $variable,
            ),
            $node instanceof UnaryOperationNode => $this->containsVariable(
                $node->operand,
                $variable,
            ),
            $node instanceof BinaryOperationNode => $this->containsVariable(
                $node->left,
                $variable,
            ) || $this->containsVariable($node->right, $variable),
            $node instanceof FactorialNode => $this->containsVariable(
                $node->operand,
                $variable,
            ),
            $node instanceof FunctionCallNode => $this->containsVariableInArguments(
                $node->arguments,
                $variable,
            ),
            default => false,
        };
    }

    private function containsVariableFactorial(Node $node, string $variable): bool
    {
        if ($node instanceof FactorialNode) {
            return $this->containsVariable($node->operand, $variable)
                || $this->containsVariableFactorial($node->operand, $variable);
        }
        if ($node instanceof GroupingNode) {
            return $this->containsVariableFactorial($node->expression, $variable);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsVariableFactorial($node->operand, $variable);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsVariableFactorial($node->left, $variable)
                || $this->containsVariableFactorial($node->right, $variable);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsVariableFactorial($argument, $variable)) {
                    return true;
                }
            }
        }

        return false;
    }

    private function containsBoundedVariableIntegerArgument(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $calls = [];
        $this->collectVariableIntegerArgumentCalls($node, $variable, $calls);
        foreach ($calls as [$call, $argumentIndex, $minimumOrder, $maximumOrder]) {
            $range = $this->boundedExpressionRange(
                $call->arguments[$argumentIndex],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($range === null || !\is_finite($range[0]) || !\is_finite($range[1])) {
                continue;
            }
            $tolerance = 16.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($range[0]), \abs($range[1]));
            $firstLevel = \max($minimumOrder, (int) \ceil($range[0] - $tolerance));
            $lastLevel = \min($maximumOrder, (int) \floor($range[1] + $tolerance));
            if (
                $lastLevel >= $firstLevel
                && $lastLevel - $firstLevel + 1 <= self::MAX_ADAPTIVE_SCAN_STEPS
            ) {
                return true;
            }
        }

        return false;
    }

    private function containsVariableQuantizedGcdLcm(Node $node, string $variable): bool
    {
        if ($node instanceof FunctionCallNode) {
            if (\in_array($node->name, ['gcd', 'lcm'], true) && \count($node->arguments) === 2) {
                foreach ([0, 1] as $argumentIndex) {
                    $quantizedArgument = $this->unwrapGrouping($node->arguments[$argumentIndex]);
                    if (
                        !$quantizedArgument instanceof FunctionCallNode
                        || !\in_array($quantizedArgument->name, ['floor', 'ceil', 'round', 'trunc'], true)
                        || \count($quantizedArgument->arguments) !== 1
                        || !$this->containsVariable($quantizedArgument, $variable)
                        || $this->containsVariable($node->arguments[1 - $argumentIndex], $variable)
                    ) {
                        continue;
                    }

                    return true;
                }
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsVariableQuantizedGcdLcm($argument, $variable)) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsVariableQuantizedGcdLcm($node->expression, $variable);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsVariableQuantizedGcdLcm($node->operand, $variable);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsVariableQuantizedGcdLcm($node->left, $variable)
                || $this->containsVariableQuantizedGcdLcm($node->right, $variable);
        }

        return false;
    }

    private function hasDirectSignComparison(
        Node $left,
        Node $right,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $leftIsSign = $left instanceof FunctionCallNode
            && $left->name === 'sign'
            && \count($left->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('sign');
        $rightIsSign = $right instanceof FunctionCallNode
            && $right->name === 'sign'
            && \count($right->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('sign');

        return ($leftIsSign && !$this->containsVariable($right, $variable))
            || ($rightIsSign && !$this->containsVariable($left, $variable));
    }

    private function hasDirectExtremumComparison(
        Node $left,
        Node $right,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $leftIsExtremum = $left instanceof FunctionCallNode
            && \in_array($left->name, ['min', 'max'], true)
            && \count($left->arguments) >= 2
            && $evaluationOptions->functions->isBuiltIn($left->name);
        $rightIsExtremum = $right instanceof FunctionCallNode
            && \in_array($right->name, ['min', 'max'], true)
            && \count($right->arguments) >= 2
            && $evaluationOptions->functions->isBuiltIn($right->name);

        return $leftIsExtremum || $rightIsExtremum;
    }

    private function containsImplicitVariableProduct(
        Node $node,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if (
                $node->name === $variable
                && \count($node->arguments) === 1
                && $evaluationOptions->functions->find($node->name) === null
            ) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsImplicitVariableProduct($argument, $variable, $evaluationOptions)) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsImplicitVariableProduct(
                $node->expression,
                $variable,
                $evaluationOptions,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsImplicitVariableProduct(
                $node->operand,
                $variable,
                $evaluationOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsImplicitVariableProduct(
                $node->left,
                $variable,
                $evaluationOptions,
            ) || $this->containsImplicitVariableProduct(
                $node->right,
                $variable,
                $evaluationOptions,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->containsImplicitVariableProduct(
                $node->operand,
                $variable,
                $evaluationOptions,
            );
        }

        return false;
    }

    private function containsNonIntegerNumberLiteral(Node $node): bool
    {
        return match (true) {
            $node instanceof NumberNode => !\is_int($node->value),
            $node instanceof GroupingNode => $this->containsNonIntegerNumberLiteral(
                $node->expression,
            ),
            $node instanceof UnaryOperationNode => $this->containsNonIntegerNumberLiteral(
                $node->operand,
            ),
            $node instanceof BinaryOperationNode => $this->containsNonIntegerNumberLiteral(
                $node->left,
            ) || $this->containsNonIntegerNumberLiteral($node->right),
            $node instanceof FactorialNode => $this->containsNonIntegerNumberLiteral(
                $node->operand,
            ),
            $node instanceof FunctionCallNode => $this->containsNonIntegerNumberLiteralInArguments(
                $node->arguments,
            ),
            default => false,
        };
    }

    private function containsUnderflowedNumberLiteral(Node $node): bool
    {
        return match (true) {
            $node instanceof NumberNode => \is_float($node->value)
                && $node->value === 0.0
                && \preg_match('/[1-9]/', $node->literal) === 1,
            $node instanceof GroupingNode => $this->containsUnderflowedNumberLiteral($node->expression),
            $node instanceof UnaryOperationNode => $this->containsUnderflowedNumberLiteral($node->operand),
            $node instanceof BinaryOperationNode => $this->containsUnderflowedNumberLiteral($node->left)
                || $this->containsUnderflowedNumberLiteral($node->right),
            $node instanceof FactorialNode => $this->containsUnderflowedNumberLiteral($node->operand),
            $node instanceof FunctionCallNode => $this->containsUnderflowedNumberLiteralInArguments(
                $node->arguments,
            ),
            default => false,
        };
    }

    private function containsNamedFunction(Node $node, string $name): bool
    {
        if ($node instanceof FunctionCallNode) {
            if ($node->name === $name) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsNamedFunction($argument, $name)) {
                    return true;
                }
            }

            return false;
        }

        return match (true) {
            $node instanceof GroupingNode => $this->containsNamedFunction($node->expression, $name),
            $node instanceof UnaryOperationNode => $this->containsNamedFunction($node->operand, $name),
            $node instanceof BinaryOperationNode => $this->containsNamedFunction($node->left, $name)
                || $this->containsNamedFunction($node->right, $name),
            $node instanceof FactorialNode => $this->containsNamedFunction($node->operand, $name),
            default => false,
        };
    }

    private function containsGammaOutsideSupportedArgumentRange(
        Node $node,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if ($node->name === 'gamma' && \count($node->arguments) === 1) {
                $coefficients = $this->extractPolynomial(
                    $extractor,
                    $node->arguments[0],
                    $node->arguments[0]->span()->start,
                );
                if ($coefficients !== null) {
                    $range = $this->polynomialRange($coefficients, $lowerBound, $upperBound, $solverOptions);
                    if ($range !== null && ($range[0] > 171.0 || $range[1] < -171.0)) {
                        return true;
                    }
                }
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsGammaOutsideSupportedArgumentRange(
                    $argument,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                )) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsGammaOutsideSupportedArgumentRange(
                $node->expression,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsGammaOutsideSupportedArgumentRange(
                $node->operand,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsGammaOutsideSupportedArgumentRange(
                $node->left,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            ) || $this->containsGammaOutsideSupportedArgumentRange(
                $node->right,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->containsGammaOutsideSupportedArgumentRange(
                $node->operand,
                $extractor,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solveTwoHarmonicBetaZeroEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
    ): ?array {
        foreach (
            [[$left, $right, $leftSource, 0], [$right, $left, $rightSource, $rightOffset]]
            as [$candidate, $target, $source, $sourceOffset]
        ) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            $targetValue = $extractor->extract($target);
            if ($targetValue !== [0.0]) {
                continue;
            }

            $first = $candidate->arguments[0];
            $second = $candidate->arguments[1];
            if (
                !$this->containsVariable($first, $variable)
                || !$this->containsVariable($second, $variable)
            ) {
                continue;
            }
            $firstForm = $this->flattenAffineTrigonometricTerms($first, $extractor);
            $secondForm = $this->flattenAffineTrigonometricTerms($second, $extractor);
            if (
                $firstForm === null
                || $secondForm === null
                || $firstForm['terms'] === []
                || $secondForm['terms'] === []
            ) {
                continue;
            }

            $allTerms = [...$firstForm['terms'], ...$secondForm['terms']];
            $referenceSlope = null;
            $commonDenominator = 1;
            $harmonics = [];
            $validPhases = true;
            foreach ($allTerms as $term) {
                if (
                    !$evaluationOptions->functions->isBuiltIn($term['call']->name)
                    || !\in_array($term['call']->name, ['sin', 'cos'], true)
                    || \count($term['call']->arguments) !== 1
                ) {
                    $validPhases = false;
                    break;
                }
                $phase = $extractor->extract($term['call']->arguments[0]);
                if ($phase === null || \count($phase) !== 2 || $phase[1] === 0.0) {
                    $validPhases = false;
                    break;
                }
                $referenceSlope ??= \abs($phase[1]);
                $ratio = $this->rationalHarmonicOrders(
                    \abs($phase[1]) / $referenceSlope,
                    $solverOptions->maxPolynomialDegree,
                );
                if ($ratio === null) {
                    $validPhases = false;
                    break;
                }
                [$numerator, $denominator] = [$commonDenominator, $ratio[1]];
                while ($denominator !== 0) {
                    [$numerator, $denominator] = [$denominator, $numerator % $denominator];
                }
                $commonDenominator = \intdiv($commonDenominator, $numerator) * $ratio[1];
                if ($commonDenominator > 1024) {
                    $validPhases = false;
                    break;
                }
                $harmonics[] = ['phase' => $phase, 'ratio' => $ratio];
            }
            if (!$validPhases || $referenceSlope === null) {
                continue;
            }
            $orderGcd = 0;
            $rawOrders = [];
            foreach ($harmonics as $harmonic) {
                [$numerator, $denominator] = $harmonic['ratio'];
                $order = $numerator * \intdiv($commonDenominator, $denominator);
                $rawOrders[] = $order;
                $leftGcd = $orderGcd;
                $rightGcd = $order;
                while ($rightGcd !== 0) {
                    [$leftGcd, $rightGcd] = [$rightGcd, $leftGcd % $rightGcd];
                }
                $orderGcd = $leftGcd;
            }
            if ($orderGcd < 1) {
                continue;
            }
            $fundamentalSlope = $referenceSlope / \intdiv($commonDenominator, $orderGcd);
            foreach ($harmonics as $index => $harmonic) {
                $order = \intdiv($rawOrders[$index], $orderGcd);
                if (
                    $order > $solverOptions->maxPolynomialDegree
                    || !$this->approximatelyEqual(\abs($harmonic['phase'][1]), $fundamentalSlope * $order)
                ) {
                    $validPhases = false;
                    break;
                }
            }
            if (!$validPhases) {
                continue;
            }

            $firstSpan = $first->span();
            $secondSpan = $second->span();
            $firstSource = \substr(
                $source,
                $firstSpan->start - $sourceOffset,
                $firstSpan->end - $firstSpan->start,
            );
            $secondSource = \substr(
                $source,
                $secondSpan->start - $sourceOffset,
                $secondSpan->end - $secondSpan->start,
            );
            $sumCenter = $firstForm['constant'] + $secondForm['constant'];
            $sumAmplitude = 0.0;
            foreach ($allTerms as $term) {
                $sumAmplitude += \abs($term['coefficient']);
            }
            $minimumLevel = $sumCenter - $sumAmplitude;
            $maximumLevel = $sumCenter + $sumAmplitude;
            if (!\is_finite($minimumLevel) || !\is_finite($maximumLevel)) {
                continue;
            }
            $levelTolerance = 64.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimumLevel), \abs($maximumLevel));
            $firstIntegerLevelBound = \ceil(-$maximumLevel - $levelTolerance);
            $lastIntegerLevelBound = \floor(-$minimumLevel + $levelTolerance);
            if (
                $firstIntegerLevelBound > \PHP_INT_MAX - $solverOptions->maxPolynomialDegree
                || $lastIntegerLevelBound > \PHP_INT_MAX - $solverOptions->maxPolynomialDegree
            ) {
                continue;
            }
            $firstIntegerLevel = \max(0, (int) $firstIntegerLevelBound);
            $lastIntegerLevel = (int) $lastIntegerLevelBound;
            if ($lastIntegerLevel < $firstIntegerLevel) {
                return [];
            }
            if ($lastIntegerLevel - $firstIntegerLevel + 1 > $solverOptions->maxPolynomialDegree) {
                continue;
            }
            $solutions = [];
            for ($integerLevel = $firstIntegerLevel; $integerLevel <= $lastIntegerLevel; ++$integerLevel) {
                $levelEquation = '(' . $firstSource . ')+(' . $secondSource . ')=' . (-$integerLevel);
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                foreach (
                    $this->solve(
                        $levelEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    ) as $levelSolution
                ) {
                    if (
                        $levelSolution->residual > \max(
                            1.0E-8,
                            $solverOptions->residualTolerance * 1000.0,
                        )
                    ) {
                        continue;
                    }
                    try {
                        $firstValue = (float) $this->evaluateNode(
                            $candidate->arguments[0],
                            [...$parameters, $variable => $levelSolution->value],
                            $evaluationOptions,
                        );
                        $secondValue = (float) $this->evaluateNode(
                            $candidate->arguments[1],
                            [...$parameters, $variable => $levelSolution->value],
                            $evaluationOptions,
                        );
                    } catch (EvaluationException | \DomainException | \OverflowException) {
                        continue;
                    }
                    $poleTolerance = 1.0E-8;
                    if (
                        (\round($firstValue) <= 0.0
                            && \abs($firstValue - \round($firstValue)) <= $poleTolerance)
                        || (\round($secondValue) <= 0.0
                            && \abs($secondValue - \round($secondValue)) <= $poleTolerance)
                        || $residualAt($levelSolution->value) === null
                    ) {
                        continue;
                    }

                    $this->addSolution(
                        $solutions,
                        new EquationSolution($levelSolution->value, 0.0, $levelSolution->iterations),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $firstSolution, EquationSolution $secondSolution): int =>
                    $firstSolution->value <=> $secondSolution->value,
            );

            return $solutions;
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function hasMonotoneGammaIntervalArguments(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if ($node->name === 'gamma' && $this->containsVariableInArguments($node->arguments, $variable)) {
                if (\count($node->arguments) !== 1) {
                    return false;
                }
                $argument = $this->evaluateIntervalExpression(
                    $node->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                if ($argument === null || $argument[0] < 1.5) {
                    return false;
                }
            }
            foreach ($node->arguments as $argument) {
                if (
                    !$this->hasMonotoneGammaIntervalArguments(
                        $argument,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                    )
                ) {
                    return false;
                }
            }

            return true;
        }

        return match (true) {
            $node instanceof GroupingNode => $this->hasMonotoneGammaIntervalArguments(
                $node->expression,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            ),
            $node instanceof UnaryOperationNode => $this->hasMonotoneGammaIntervalArguments(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            ),
            $node instanceof BinaryOperationNode => $this->hasMonotoneGammaIntervalArguments(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            ) && $this->hasMonotoneGammaIntervalArguments(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            ),
            $node instanceof FactorialNode => $this->hasMonotoneGammaIntervalArguments(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            ),
            default => true,
        };
    }

    private function containsVariableDependentCustomFunction(
        Node $node,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if (
                !$evaluationOptions->functions->isBuiltIn($node->name)
                && $this->containsVariableInArguments($node->arguments, $variable)
            ) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if (
                    $this->containsVariableDependentCustomFunction(
                        $argument,
                        $variable,
                        $evaluationOptions,
                    )
                ) {
                    return true;
                }
            }

            return false;
        }

        return match (true) {
            $node instanceof GroupingNode => $this->containsVariableDependentCustomFunction(
                $node->expression,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof UnaryOperationNode => $this->containsVariableDependentCustomFunction(
                $node->operand,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof BinaryOperationNode => $this->containsVariableDependentCustomFunction(
                $node->left,
                $variable,
                $evaluationOptions,
            ) || $this->containsVariableDependentCustomFunction(
                $node->right,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof FactorialNode => $this->containsVariableDependentCustomFunction(
                $node->operand,
                $variable,
                $evaluationOptions,
            ),
            default => false,
        };
    }

    private function containsVariableDependentBuiltInFunction(
        Node $node,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof FunctionCallNode) {
            if (
                $evaluationOptions->functions->isBuiltIn($node->name)
                && $this->containsVariableInArguments($node->arguments, $variable)
            ) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsVariableDependentBuiltInFunction($argument, $variable, $evaluationOptions)) {
                    return true;
                }
            }

            return false;
        }

        return match (true) {
            $node instanceof GroupingNode => $this->containsVariableDependentBuiltInFunction(
                $node->expression,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof UnaryOperationNode => $this->containsVariableDependentBuiltInFunction(
                $node->operand,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof BinaryOperationNode => $this->containsVariableDependentBuiltInFunction(
                $node->left,
                $variable,
                $evaluationOptions,
            ) || $this->containsVariableDependentBuiltInFunction(
                $node->right,
                $variable,
                $evaluationOptions,
            ),
            $node instanceof FactorialNode => $this->containsVariableDependentBuiltInFunction(
                $node->operand,
                $variable,
                $evaluationOptions,
            ),
            default => false,
        };
    }

    /**
     * Check whether a custom function is certified equal to a constant over
     * the entire finite solving interval.
     *
     * @param array<string, int|float> $parameters
     */
    private function hasCertifiedConstantCustomFunctionIdentity(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $targetNode]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 1
                || !$this->unwrapGrouping($candidate->arguments[0]) instanceof VariableNode
                || $this->unwrapGrouping($candidate->arguments[0])->name !== $variable
            ) {
                continue;
            }

            $definition = $evaluationOptions->functions->find($candidate->name);
            $target = $this->constantNodeValue($targetNode, $parameters, $evaluationOptions);
            if (
                $definition === null
                || !$definition->hasIntervalExtension()
                || !$definition->hasDomainExtension()
                || $target === null
                || !\is_finite($target)
                || !$definition->isDefinedOnIntervals([[$lowerBound, $upperBound]])
            ) {
                continue;
            }

            $range = $definition->intervalExtension([[$lowerBound, $upperBound]]);
            if ($range !== null && $range[0] === $target && $range[1] === $target) {
                return true;
            }
        }

        return false;
    }

    /**
     * Use a caller-supplied sound interval extension to isolate roots of a
     * direct one-variable custom-function equation.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param list<array{float, float}>|null $rootRegions
     * @return list<EquationSolution>|null Null means no supported extension.
     */
    private function solveCustomFunctionWithIntervalExtension(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        ?array &$rootRegions = null,
    ): ?array {
        $call = $this->unwrapGrouping($left);
        $targetNode = $right;
        if (
            !$call instanceof FunctionCallNode
            || $evaluationOptions->functions->isBuiltIn($call->name)
            || \count($call->arguments) !== 1
            || !$this->unwrapGrouping($call->arguments[0]) instanceof VariableNode
            || $this->unwrapGrouping($call->arguments[0])->name !== $variable
            || $this->containsVariable($right, $variable)
        ) {
            $call = $this->unwrapGrouping($right);
            $targetNode = $left;
            if (
                !$call instanceof FunctionCallNode
                || $evaluationOptions->functions->isBuiltIn($call->name)
                || \count($call->arguments) !== 1
                || !$this->unwrapGrouping($call->arguments[0]) instanceof VariableNode
                || $this->unwrapGrouping($call->arguments[0])->name !== $variable
                || $this->containsVariable($left, $variable)
            ) {
                return $this->solveCustomArithmeticIntervalEquation(
                    $left,
                    $right,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                    $residualAt,
                );
            }
        }

        $definition = $evaluationOptions->functions->find($call->name);
        if ($definition === null || !$definition->hasIntervalExtension()) {
            return null;
        }
        $target = $this->constantNodeValue($targetNode, $parameters, $evaluationOptions);
        if ($target === null || !\is_finite($target)) {
            return null;
        }
        $localResidualScaleAt = static fn (float $_): float => \max(1.0, \abs($target));

        /** @var list<array{float, float}> $pending */
        $pending = [[$lowerBound, $upperBound]];
        $solutions = [];
        /** @var list<array{float, float, EquationSolution}> $regions */
        $regions = [];
        $visited = 0;
        while ($pending !== []) {
            if (++$visited > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                throw new RootSearchLimitException(
                    'Interval extension subdivision exceeded its work limit before every root was isolated.',
                );
            }
            [$lower, $upper] = \array_pop($pending);
            $range = $definition->intervalExtension([[$lower, $upper]]);
            if ($range === null) {
                throw new RootSearchLimitException(
                    'A custom function interval extension could not enclose a candidate interval.',
                );
            }
            if ($target < $range[0] || $target > $range[1]) {
                continue;
            }

            $tolerance = $solverOptions->positionTolerance($lower, $upper);
            if ($upper - $lower <= $tolerance) {
                $middle = $lower + (($upper - $lower) / 2.0);
                /** @var list<float> $points */
                $points = [$lower, $middle, $upper];
                $acceptedSolutions = [];
                $bracketSolutions = [];
                $previousPoint = null;
                $previousResidual = null;
                foreach ($points as $point) {
                    $residual = $residualAt($point);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $point,
                            $residual,
                            $localResidualScaleAt,
                            $solverOptions,
                        )
                    ) {
                        $acceptedSolutions[] = new EquationSolution($point, \abs($residual), 0);
                    }
                    if (
                        $residual !== null
                        && $previousResidual !== null
                        && $this->hasOppositeSigns($previousResidual, $residual)
                    ) {
                        $bracketRoots = $this->bisect(
                            $residualAt,
                            $previousPoint ?? $point,
                            $previousResidual,
                            $point,
                            $solverOptions,
                            $localResidualScaleAt,
                            static fn (float $_): bool => false,
                        );
                        foreach ($bracketRoots as $root) {
                            $bracketSolutions[] = $root;
                        }
                    }
                    $previousPoint = $point;
                    $previousResidual = $residual;
                }
                $found = $bracketSolutions !== [] || $acceptedSolutions !== [];
                $terminalSolutions = $bracketSolutions;
                if ($terminalSolutions === [] && $acceptedSolutions !== []) {
                    \usort(
                        $acceptedSolutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->residual <=> $second->residual,
                    );
                    $terminalSolutions[] = $acceptedSolutions[0];
                }
                foreach ($terminalSolutions as $solution) {
                    $this->addSolution($solutions, $solution, $solverOptions);
                    $regions[] = [$lower, $upper, $solution];
                }
                if (!$found) {
                    $representedSolution = null;
                    foreach ($solutions as $solution) {
                        if (
                            $solution->value >= $lower - (2.0 * $tolerance)
                            && $solution->value <= $upper + (2.0 * $tolerance)
                        ) {
                            $representedSolution = $solution;
                            break;
                        }
                    }
                    if ($representedSolution !== null) {
                        $regions[] = [$lower, $upper, $representedSolution];
                        continue;
                    }
                    throw new RootSearchLimitException(
                        \sprintf(
                            'Custom interval extension retained unresolved interval '
                                . '[%.17g, %.17g] with range [%.17g, %.17g].',
                            $lower,
                            $upper,
                            $range[0],
                            $range[1],
                        ),
                    );
                }
                continue;
            }

            $middle = $lower + (($upper - $lower) / 2.0);
            if ($middle === $lower || $middle === $upper) {
                throw new RootSearchLimitException(
                    'A custom function root interval could not be refined at floating-point resolution.',
                );
            }
            $pending[] = [$middle, $upper];
            $pending[] = [$lower, $middle];
        }

        return $this->mergeIntervalRegions($regions, $rootRegions);
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param list<array{float, float}>|null $rootRegions
     * @param list<EquationSolution> $initialSolutions
     * @return list<EquationSolution>|null
     */
    private function solveCustomArithmeticIntervalEquation(
        Node $left,
        Node $right,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        ?array &$rootRegions = null,
        bool $includeBuiltInFunctions = false,
        bool $requireCompleteCertification = true,
        array $initialSolutions = [],
        int $workLimit = self::MAX_ROOT_DEGREE_SCAN_WORK,
    ): ?array {
        $hasVariableDependentCustomFunction =
            $this->containsVariableDependentCustomFunction($left, $variable, $evaluationOptions)
            || $this->containsVariableDependentCustomFunction($right, $variable, $evaluationOptions);
        $hasVariableDependentBuiltInFunction = $includeBuiltInFunctions && (
            $this->containsVariableDependentBuiltInFunction($left, $variable, $evaluationOptions)
            || $this->containsVariableDependentBuiltInFunction($right, $variable, $evaluationOptions)
        );
        if (
            !$hasVariableDependentCustomFunction
            && !$hasVariableDependentBuiltInFunction
            && !$includeBuiltInFunctions
        ) {
            return null;
        }

        $leftRange = $this->evaluateIntervalExpression(
            $left,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        $rightRange = $this->evaluateIntervalExpression(
            $right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($leftRange === null || $rightRange === null) {
            return null;
        }

        /** @var list<array{float, float}> $pending */
        $pending = [[$lowerBound, $upperBound]];
        $solutions = $initialSolutions;
        $initialSolutionSlopes = [];
        if ($initialSolutions !== []) {
            $differentiator = new NumericalDifferentiator();
            foreach ($initialSolutions as $initialSolution) {
                $initialSolutionSlopes[] = $differentiator->differentiate(
                    $residualAt,
                    $initialSolution->value,
                );
            }
        }
        /** @var list<array{float, float, EquationSolution}> $regions */
        $regions = [];
        $visited = 0;
        while ($pending !== []) {
            if (++$visited > $workLimit) {
                if (!$requireCompleteCertification) {
                    return null;
                }
                throw new RootSearchLimitException(
                    'Interval arithmetic subdivision exceeded its work limit before every root was isolated.',
                );
            }
            [$lower, $upper] = \array_pop($pending);
            $leftRange = $this->evaluateIntervalExpression(
                $left,
                $variable,
                $lower,
                $upper,
                $parameters,
                $evaluationOptions,
            );
            $rightRange = $this->evaluateIntervalExpression(
                $right,
                $variable,
                $lower,
                $upper,
                $parameters,
                $evaluationOptions,
            );
            if ($leftRange === null || $rightRange === null) {
                if (!$requireCompleteCertification) {
                    return null;
                }
                throw new RootSearchLimitException(
                    'Interval arithmetic could not enclose a subdivided candidate region.',
                );
            }
            $residualLower = $leftRange[0] - $rightRange[1];
            $residualUpper = $leftRange[1] - $rightRange[0];
            if (!\is_finite($residualLower) || !\is_finite($residualUpper)) {
                if (!$requireCompleteCertification) {
                    return null;
                }
                throw new RootSearchLimitException(
                    'Interval arithmetic overflowed while enclosing a candidate region.',
                );
            }
            $widenedResidual = $this->widenInterval(
                $residualLower,
                $residualUpper,
            );
            if ($widenedResidual === null) {
                if (
                    \abs($residualLower) === \PHP_FLOAT_MAX
                    || \abs($residualUpper) === \PHP_FLOAT_MAX
                ) {
                    $widenedResidual = [$residualLower, $residualUpper];
                } elseif (!$requireCompleteCertification) {
                    return null;
                } else {
                    throw new RootSearchLimitException(
                        'Interval arithmetic overflowed while widening a candidate region.',
                    );
                }
            }
            [$residualLower, $residualUpper] = $widenedResidual;
            if ($residualLower > 0.0 || $residualUpper < 0.0) {
                continue;
            }

            $tolerance = $solverOptions->positionTolerance($lower, $upper);
            if ($upper - $lower <= $tolerance) {
                $scale = \max(
                    1.0,
                    \abs($leftRange[0]),
                    \abs($leftRange[1]),
                    \abs($rightRange[0]),
                    \abs($rightRange[1]),
                );
                $scaleAt = static fn (float $_): float => $scale;
                $middle = $lower + (($upper - $lower) / 2.0);
                $points = [$lower, $middle, $upper];
                $acceptedSolutions = [];
                $bracketSolutions = [];
                $previousPoint = null;
                $previousResidual = null;
                foreach ($points as $point) {
                    $residual = $residualAt($point);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt($point, $residual, $scaleAt, $solverOptions)
                    ) {
                        $acceptedSolutions[] = new EquationSolution($point, \abs($residual), 0);
                    }
                    if (
                        $residual !== null
                        && $previousResidual !== null
                        && $this->hasOppositeSigns($previousResidual, $residual)
                    ) {
                        $roots = $this->bisect(
                            $residualAt,
                            $previousPoint ?? $point,
                            $previousResidual,
                            $point,
                            $solverOptions,
                            $scaleAt,
                            static fn (float $_): bool => false,
                        );
                        foreach ($roots as $root) {
                            $bracketSolutions[] = $root;
                        }
                    }
                    $previousPoint = $point;
                    $previousResidual = $residual;
                }
                $found = $bracketSolutions !== [] || $acceptedSolutions !== [];
                $terminalSolutions = $bracketSolutions;
                if ($terminalSolutions === [] && $acceptedSolutions !== []) {
                    \usort(
                        $acceptedSolutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->residual <=> $second->residual,
                    );
                    $terminalSolutions[] = $acceptedSolutions[0];
                }
                $roundoffRepresentative = null;
                $roundoffNeighborhoodScale = \sqrt(\sqrt(\PHP_FLOAT_EPSILON));
                if ($terminalSolutions !== []) {
                    foreach ($initialSolutions as $seedIndex => $initialSolution) {
                        $neighborhood = $roundoffNeighborhoodScale
                            * \max(1.0, \abs($initialSolution->value));
                        $seedSlope = $initialSolutionSlopes[$seedIndex] ?? null;
                        if (
                            $initialSolution->residual
                                <= 8.0 * \PHP_FLOAT_EPSILON * $scale
                            && $seedSlope !== null
                            && \abs($seedSlope) <= \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, $scale)
                            && $initialSolution->value >= $lower - $neighborhood
                            && $initialSolution->value <= $upper + $neighborhood
                            && (
                                $roundoffRepresentative === null
                                || $initialSolution->residual < $roundoffRepresentative->residual
                            )
                        ) {
                            $roundoffRepresentative = $initialSolution;
                        }
                    }
                }
                if ($roundoffRepresentative !== null) {
                    $regions[] = [$lower, $upper, $roundoffRepresentative];
                    continue;
                }
                foreach ($terminalSolutions as $solution) {
                    $this->addSolution($solutions, $solution, $solverOptions);
                    $regions[] = [$lower, $upper, $solution];
                }
                if (!$found) {
                    $representedSolution = null;
                    foreach ($solutions as $solution) {
                        if (
                            $solution->value >= $lower - (2.0 * $tolerance)
                            && $solution->value <= $upper + (2.0 * $tolerance)
                        ) {
                            $representedSolution = $solution;
                            break;
                        }
                    }
                    if ($representedSolution === null) {
                        if (!$requireCompleteCertification) {
                            return null;
                        }
                    } else {
                        $regions[] = [$lower, $upper, $representedSolution];
                        continue;
                    }
                } else {
                    continue;
                }
            }

            $middle = $lower + (($upper - $lower) / 2.0);
            if ($middle === $lower || $middle === $upper) {
                if (!$requireCompleteCertification) {
                    return null;
                }
                throw new RootSearchLimitException(
                    'An interval arithmetic root region could not be refined at floating-point resolution.',
                );
            }
            $pending[] = [$middle, $upper];
            $pending[] = [$lower, $middle];
        }

        return $this->mergeIntervalRegions($regions, $rootRegions);
    }

    private function solveAffineLogarithmicTrigonometricEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        foreach (
            [[$left, $right, $leftSource], [$right, $left, $rightSource]]
            as [$periodicSide, $targetSide, $periodicSource]
        ) {
            $periodic = $this->unwrapGrouping($periodicSide);
            if (
                !$periodic instanceof FunctionCallNode
                || !\in_array($periodic->name, ['sin', 'cos'], true)
                || \count($periodic->arguments) !== 1
                || $this->containsVariable($targetSide, $variable)
            ) {
                continue;
            }
            $phase = $this->unwrapGrouping($periodic->arguments[0]);
            if (
                !$phase instanceof FunctionCallNode
                || $phase->name !== 'log'
                || \count($phase->arguments) !== 2
            ) {
                continue;
            }
            $phaseRange = $this->affineVariableBaseLogIntervalRange(
                $phase->arguments[0],
                $phase->arguments[1],
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            if ($phaseRange === null) {
                continue;
            }
            try {
                $target = (float) $this->evaluateNode($targetSide, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            $periodicRange = $this->trigonometricIntervalRange(
                $phaseRange[0],
                $phaseRange[1],
                $periodic->name === 'cos',
            );
            if ($periodicRange !== null && ($target < $periodicRange[0] || $target > $periodicRange[1])) {
                return [];
            }
            if ($target < -1.0 || $target > 1.0) {
                return [];
            }

            $inverse = $periodic->name === 'sin' ? \asin($target) : \acos($target);
            $phaseOffsets = $periodic->name === 'sin'
                ? [$inverse, \M_PI - $inverse]
                : [$inverse, -$inverse];
            $periodicLevels = [];
            $phasePeriod = 2.0 * \M_PI;
            foreach ($phaseOffsets as $offset) {
                $firstIndex = (int) \ceil(($phaseRange[0] - $offset) / $phasePeriod);
                $lastIndex = (int) \floor(($phaseRange[1] - $offset) / $phasePeriod);
                if ($lastIndex - $firstIndex + 1 > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                    $level = $offset + ($index * $phasePeriod);
                    if ($level >= $phaseRange[0] && $level <= $phaseRange[1]) {
                        $periodicLevels[\sprintf('%.17g', $level)] = $level;
                    }
                }
            }
            if ($periodicLevels === []) {
                return [];
            }

            $phaseSpan = $periodic->arguments[0]->span();
            $phaseSource = \substr(
                $periodicSource,
                $phaseSpan->start,
                $phaseSpan->end - $phaseSpan->start,
            );
            if ($phaseSource === '') {
                return null;
            }
            $solutions = [];
            foreach ($periodicLevels as $level) {
                $levelEquation = '(' . $phaseSource . ')=(' . \sprintf('%.17g', $level) . ')';
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                try {
                    $levelSolutions = $this->solve(
                        $levelEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                } catch (InfiniteSolutionSetException) {
                    return null;
                } catch (RootSearchLimitException) {
                    $levelSolutions = $this->solvePositiveAffineLogLevelMonotonically(
                        $phase,
                        $level,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                    );
                    if ($levelSolutions === null) {
                        return null;
                    }
                }
                foreach ($levelSolutions as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $residualScaleAt,
                            $solverOptions,
                        )
                    ) {
                        return null;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $solverOptions,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function affineVariableBaseLogIntervalRange(
        Node $argument,
        Node $base,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $extractor = new PolynomialExtractor($variable, $parameters, $evaluationOptions, 1);
        $argumentCoefficients = $extractor->extract($argument);
        $baseCoefficients = $extractor->extract($base);
        if (
            $argumentCoefficients === null
            || $baseCoefficients === null
            || \count($argumentCoefficients) > 2
            || \count($baseCoefficients) > 2
            || ($argumentCoefficients[0] ?? 0.0) !== 1.0
            || ($baseCoefficients[0] ?? 0.0) !== 1.0
        ) {
            return null;
        }

        $argumentSlope = $argumentCoefficients[1] ?? 0.0;
        $baseSlope = $baseCoefficients[1] ?? 0.0;
        if ($baseSlope === 0.0) {
            return null;
        }
        $argumentValues = [
            1.0 + ($argumentSlope * $lowerBound),
            1.0 + ($argumentSlope * $upperBound),
        ];
        $baseValues = [
            1.0 + ($baseSlope * $lowerBound),
            1.0 + ($baseSlope * $upperBound),
        ];
        if (
            !\is_finite($argumentValues[0])
            || !\is_finite($argumentValues[1])
            || !\is_finite($baseValues[0])
            || !\is_finite($baseValues[1])
            || \min($argumentValues) <= 0.0
            || \min($baseValues) <= 0.0
        ) {
            return null;
        }
        if ($argumentSlope === 0.0) {
            return [0.0, 0.0];
        }

        $hRange = static function (float $slope, float $lower, float $upper): ?array {
            $deltas = [$slope * $lower, $slope * $upper];
            $minimum = \min($deltas);
            $maximum = \max($deltas);
            if ($minimum <= -1.0) {
                return null;
            }
            $h = static fn (float $value): float => $value === 0.0
                ? 1.0
                : \log1p($value) / $value;
            $first = $h($minimum);
            $second = $h($maximum);
            if (!\is_finite($first) || !\is_finite($second)) {
                return null;
            }

            return [$h($maximum), $h($minimum)];
        };
        $argumentH = $hRange($argumentSlope, $lowerBound, $upperBound);
        $baseH = $hRange($baseSlope, $lowerBound, $upperBound);
        if ($argumentH === null || $baseH === null || $baseH[0] <= 0.0) {
            return null;
        }

        $slopeRatio = $argumentSlope / $baseSlope;
        $lowerRatio = $slopeRatio * ($argumentH[0] / $baseH[1]);
        $upperRatio = $slopeRatio * ($argumentH[1] / $baseH[0]);
        if ($slopeRatio < 0.0) {
            [$lowerRatio, $upperRatio] = [$upperRatio, $lowerRatio];
        }

        return $this->widenInterval($lowerRatio, $upperRatio);
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solvePositiveAffineLogLevelMonotonically(
        FunctionCallNode $logarithm,
        float $target,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if ($lowerBound < 0.0 || $upperBound <= $lowerBound) {
            return null;
        }
        $extractor = new PolynomialExtractor($variable, $parameters, $evaluationOptions, 1);
        $argument = $extractor->extract($logarithm->arguments[0]);
        $base = $extractor->extract($logarithm->arguments[1]);
        if (
            $argument === null
            || $base === null
            || \count($argument) > 2
            || \count($base) > 2
            || ($argument[0] ?? 0.0) !== 1.0
            || ($base[0] ?? 0.0) !== 1.0
        ) {
            return null;
        }
        $argumentSlope = $argument[1] ?? 0.0;
        $baseSlope = $base[1] ?? 0.0;
        if ($argumentSlope <= 0.0 || $baseSlope <= 0.0 || $argumentSlope === $baseSlope) {
            return null;
        }

        $phaseAt = function (float $position) use (
            $logarithm,
            $variable,
            $parameters,
            $evaluationOptions,
        ): ?float {
            try {
                $value = (float) $this->evaluateNode(
                    $logarithm,
                    [$variable => $position] + $parameters,
                    $evaluationOptions,
                );
            } catch (EvaluationException | \DomainException | \OverflowException) {
                return null;
            }

            return \is_finite($value) ? $value : null;
        };
        $lowerPhase = $lowerBound === 0.0
            ? $argumentSlope / $baseSlope
            : $phaseAt($lowerBound);
        $upperPhase = $phaseAt($upperBound);
        if ($lowerPhase === null || $upperPhase === null) {
            return null;
        }
        $increasing = $argumentSlope < $baseSlope;
        if (
            ($increasing && ($target < $lowerPhase || $target > $upperPhase))
            || (!$increasing && ($target > $lowerPhase || $target < $upperPhase))
        ) {
            return [];
        }

        $lower = $lowerBound;
        $upper = $upperBound;
        for ($iteration = 1; $iteration <= $solverOptions->maxIterations; ++$iteration) {
            $middle = $lower + (($upper - $lower) / 2.0);
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            $phase = $phaseAt($middle);
            if ($phase === null) {
                return null;
            }
            if ($phase === $target || $upper - $lower <= $solverOptions->positionTolerance($lower, $upper)) {
                $residual = $phaseAt($middle);

                return [new EquationSolution($middle, $residual === null ? 0.0 : \abs($residual - $target), $iteration)];
            }
            if (($phase < $target) === $increasing) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        $candidate = $lower + (($upper - $lower) / 2.0);
        $residual = $phaseAt($candidate);

        return $residual === null
            ? null
            : [new EquationSolution($candidate, \abs($residual - $target), $solverOptions->maxIterations)];
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function evaluateIntervalExpression(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if ($node instanceof NumberNode) {
            return $node->hasFiniteApproximation ? [(float) $node->value, (float) $node->value] : null;
        }
        if ($node instanceof ConstantNode) {
            $value = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $value === null || !\is_finite($value) ? null : [$value, $value];
        }
        if ($node instanceof VariableNode) {
            if ($node->name === $variable) {
                return [$lowerBound, $upperBound];
            }
            if (!\array_key_exists($node->name, $parameters)) {
                return null;
            }
            $value = (float) $parameters[$node->name];

            return \is_finite($value) ? [$value, $value] : null;
        }
        if (!$this->containsVariable($node, $variable)) {
            $value = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $value === null || !\is_finite($value) ? null : [$value, $value];
        }
        if ($node instanceof GroupingNode) {
            return $this->evaluateIntervalExpression(
                $node->expression,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            $range = $this->evaluateIntervalExpression(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            if ($range === null || $node->operator === UnaryOperator::Plus) {
                return $range;
            }
            return [-$range[1], -$range[0]];
        }
        if ($node instanceof FactorialNode) {
            $operandRange = $this->evaluateIntervalExpression(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            if ($operandRange === null) {
                return null;
            }
            $minimum = null;
            $maximum = null;
            $factorial = 1;
            for ($operand = 0; $operand <= $evaluationOptions->limits->maxFactorial; ++$operand) {
                $tolerance = 4.0 * \PHP_FLOAT_EPSILON * \max(1.0, (float) $operand);
                if (
                    $operandRange[0] <= $operand + $tolerance
                    && $operandRange[1] >= $operand - $tolerance
                ) {
                    $minimum ??= $factorial;
                    $maximum = $factorial;
                }
                if ($operand < $evaluationOptions->limits->maxFactorial) {
                    $factorial *= $operand + 1;
                }
            }
            if ($minimum === null || $maximum === null) {
                return null;
            }

            return $this->widenInterval((float) $minimum, (float) $maximum);
        }
        if ($node instanceof FunctionCallNode) {
            if (
                $node->name === 'exp'
                && \count($node->arguments) === 1
                && $lowerBound === 0.0
                && $upperBound > 0.0
                && $this->isNegativeReciprocalOfVanishingPower($node->arguments[0], $variable)
            ) {
                try {
                    $upperValue = (float) $this->evaluateNode(
                        $node,
                        [...$parameters, $variable => $upperBound],
                        $evaluationOptions,
                    );
                } catch (EvaluationException | \DomainException | \OverflowException) {
                    return null;
                }

                return \is_finite($upperValue)
                    ? $this->widenArithmeticInterval(0.0, $upperValue)
                    : null;
            }
            if (
                $node->name === 'log'
                && \count($node->arguments) === 2
                && $this->sameExpression($node->arguments[0], $node->arguments[1])
            ) {
                return [1.0, 1.0];
            }
            if ($node->name === 'log' && \count($node->arguments) === 2) {
                $variableBaseLogRange = $this->variableBaseLogIntervalRangeNearZero(
                    $node->arguments[0],
                    $node->arguments[1],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                if ($variableBaseLogRange !== null) {
                    return $variableBaseLogRange;
                }
            }
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                if (!$this->containsVariable($argument, $variable)) {
                    $value = $this->constantNodeValue($argument, $parameters, $evaluationOptions);
                    if ($value === null || !\is_finite($value)) {
                        return null;
                    }
                    $argumentRanges[] = [$value, $value];
                    continue;
                }
                $range = $this->evaluateIntervalExpression(
                    $argument,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                if ($range === null) {
                    return null;
                }
                $argumentRanges[] = $range;
            }

            if ($evaluationOptions->functions->isBuiltIn($node->name)) {
                return $this->builtInIntervalRange($node->name, $argumentRanges, $evaluationOptions);
            }
            $definition = $evaluationOptions->functions->find($node->name);
            if ($definition === null) {
                return null;
            }

            return $definition->intervalExtension($argumentRanges);
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        $left = $this->evaluateIntervalExpression(
            $node->left,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        $right = $this->evaluateIntervalExpression(
            $node->right,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($left === null || $right === null) {
            return null;
        }
        if (
            ($node->operator === BinaryOperator::Subtract
                && $this->sameExpression($node->left, $node->right))
            || ($node->operator === BinaryOperator::Add
                && (
                    $this->isNegationOf($node->left, $node->right)
                    || $this->isNegationOf($node->right, $node->left)
                ))
        ) {
            return [0.0, 0.0];
        }
        if (
            $node->operator === BinaryOperator::Power
            && $right[0] === 0.0
            && $right[1] === 0.0
            && !$this->isTotalZeroPowerBase($node->left, $variable, $evaluationOptions)
        ) {
            return null;
        }

        return match ($node->operator) {
            BinaryOperator::Add => $this->widenArithmeticInterval(
                $left[0] + $right[0],
                $left[1] + $right[1],
            ),
            BinaryOperator::Subtract => $this->widenArithmeticInterval(
                $left[0] - $right[1],
                $left[1] - $right[0],
            ),
            BinaryOperator::Multiply => $this->sameExpression($node->left, $node->right)
                ? $this->squareInterval($left)
                : ($this->isNegationOf($node->left, $node->right)
                    ? $this->negativeSquareInterval($right)
                    : ($this->isNegationOf($node->right, $node->left)
                        ? $this->negativeSquareInterval($left)
                        : $this->multiplyIntervals($left, $right, true))),
            BinaryOperator::Divide => $this->divideIntervals($left, $right),
            BinaryOperator::Modulo => $this->moduloInterval($left, $right),
            BinaryOperator::Power => $this->powerInterval(
                $left,
                $right,
                RationalLiteral::reducedParity($node->right),
            ),
        };
    }

    /**
     * Enclose a variable-base logarithm when both operands approach one at
     * least quadratically at zero. Factoring out x^2 avoids the dependency
     * loss that makes ordinary interval division singular at that boundary.
     *
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function variableBaseLogIntervalRangeNearZero(
        Node $argument,
        Node $base,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $argumentSlope = $this->linearUnitOffsetCoefficient(
            $argument,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        $baseNode = $this->unwrapGrouping($base);
        if (
            $argumentSlope !== null
            && $argumentSlope !== 0.0
            && $baseNode instanceof FunctionCallNode
            && $baseNode->name === 'exp'
            && \count($baseNode->arguments) === 1
            && ($baseSlope = $this->linearVariableCoefficient(
                $baseNode->arguments[0],
                $variable,
                $parameters,
                $evaluationOptions,
            )) !== null
            && $baseSlope !== 0.0
            && !($lowerBound === 0.0 && $upperBound === 0.0)
        ) {
            $offsetRange = $this->widenArithmeticInterval(
                \min($argumentSlope * $lowerBound, $argumentSlope * $upperBound),
                \max($argumentSlope * $lowerBound, $argumentSlope * $upperBound),
            );
            $logFactor = $offsetRange === null ? null : $this->log1pOverArgumentInterval($offsetRange);

            return $logFactor === null
                ? null
                : $this->scaleInterval($logFactor, $argumentSlope / $baseSlope);
        }
        $width = $upperBound - $lowerBound;
        if (!\is_finite($width) || $width <= 0.0) {
            return null;
        }
        $minimum = \INF;
        $maximum = -\INF;
        $segments = 16;
        for ($segment = 0; $segment < $segments; ++$segment) {
            $segmentLower = $lowerBound + ($width * ($segment / $segments));
            $segmentUpper = $segment === $segments - 1
                ? $upperBound
                : $lowerBound + ($width * (($segment + 1) / $segments));
            $range = $this->variableBaseLogIntervalRangeOnSegment(
                $argument,
                $base,
                $variable,
                $segmentLower,
                $segmentUpper,
                $parameters,
                $evaluationOptions,
            );
            if ($range === null) {
                return null;
            }
            $minimum = \min($minimum, $range[0]);
            $maximum = \max($maximum, $range[1]);
        }

        return $this->widenInterval($minimum, $maximum);
    }

    /** @param array<string, int|float> $parameters */
    private function linearUnitOffsetCoefficient(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Add) {
            return null;
        }
        foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$unit, $offset]) {
            if (!$this->isLiteralOne($unit)) {
                continue;
            }
            $coefficients = (new PolynomialExtractor($variable, $parameters, $evaluationOptions, 1))
                ->extract($offset);
            if (
                $coefficients === null
                || \count($coefficients) > 2
                || ($coefficients[0] ?? 0.0) !== 0.0
            ) {
                return null;
            }

            return $coefficients[1] ?? 0.0;
        }

        return null;
    }

    /** @param array<string, int|float> $parameters
     *  @return array{float, float}|null
     */
    private function variableBaseLogIntervalRangeOnSegment(
        Node $argument,
        Node $base,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if (
            !\is_finite($lowerBound)
            || !\is_finite($upperBound)
        ) {
            return null;
        }
        $argumentCoefficient = $this->unitOffsetOverSquareInterval(
            $argument,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        $baseCoefficient = $this->unitOffsetOverSquareInterval(
            $base,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($argumentCoefficient === null || $baseCoefficient === null) {
            return null;
        }

        $squareLower = $lowerBound <= 0.0 && $upperBound >= 0.0
            ? 0.0
            : \min($lowerBound * $lowerBound, $upperBound * $upperBound);
        $squareUpper = \max($lowerBound * $lowerBound, $upperBound * $upperBound);
        $squareRange = [$squareLower, $squareUpper];
        $argumentOffset = $this->multiplyIntervals($squareRange, $argumentCoefficient, true);
        $baseOffset = $this->multiplyIntervals($squareRange, $baseCoefficient, true);
        if (
            $argumentOffset === null
            || $baseOffset === null
            || $argumentOffset[0] <= -1.0
            || $baseOffset[0] <= -1.0
            || ($baseCoefficient[0] <= 0.0 && $baseCoefficient[1] >= 0.0)
        ) {
            return null;
        }

        $coefficientRatio = $this->divideIntervals($argumentCoefficient, $baseCoefficient);
        $argumentLogFactor = $this->log1pOverArgumentInterval($argumentOffset);
        $baseLogFactor = $this->log1pOverArgumentInterval($baseOffset);
        if ($coefficientRatio === null || $argumentLogFactor === null || $baseLogFactor === null) {
            return null;
        }
        $factorRatio = $this->divideIntervals($argumentLogFactor, $baseLogFactor);

        return $factorRatio === null
            ? null
            : $this->multiplyIntervals($coefficientRatio, $factorRatio, true);
    }

    /** @param array<string, int|float> $parameters
     *  @return array{float, float}|null
     */
    private function unitOffsetOverSquareInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Add) {
            if ($this->isLiteralOne($node->left)) {
                return $this->positiveSquareTermCoefficientInterval(
                    $node->right,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
            }
            if ($this->isLiteralOne($node->right)) {
                return $this->positiveSquareTermCoefficientInterval(
                    $node->left,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
            }
        }
        if ($node instanceof FunctionCallNode && \count($node->arguments) === 1) {
            $argument = $this->unwrapGrouping($node->arguments[0]);
            if ($node->name === 'sqrt') {
                $innerCoefficient = $this->unitOffsetOverSquareInterval(
                    $argument,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                $innerRange = $this->evaluateIntervalExpression(
                    $argument,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                if ($innerCoefficient === null || $innerRange === null || $innerRange[0] < 0.0) {
                    return null;
                }
                $rootRange = $this->builtInIntervalRange('sqrt', [$innerRange], $evaluationOptions);
                $denominator = $rootRange === null
                    ? null
                    : $this->widenArithmeticInterval(1.0 + $rootRange[0], 1.0 + $rootRange[1]);

                return $denominator === null
                    ? null
                    : $this->divideIntervals($innerCoefficient, $denominator);
            }
            if ($node->name === 'cosh' || $node->name === 'cos') {
                $slope = $this->linearVariableCoefficient($argument, $variable, $parameters, $evaluationOptions);
                if ($slope === null) {
                    return null;
                }
                $maximumArgument = \max(\abs($slope * $lowerBound), \abs($slope * $upperBound));
                if ($maximumArgument === 0.0) {
                    return [$node->name === 'cosh' ? 0.5 * $slope * $slope : -0.5 * $slope * $slope,
                        $node->name === 'cosh' ? 0.5 * $slope * $slope : -0.5 * $slope * $slope];
                }
                if ($node->name === 'cosh') {
                    $halfArgument = $maximumArgument / 2.0;
                    $upper = \sinh($halfArgument) / $halfArgument;
                    $range = $this->widenInterval(0.5, 0.5 * $upper * $upper);
                    return $range === null ? null : $this->scaleInterval($range, $slope * $slope);
                }
                if ($maximumArgument > \M_PI) {
                    return null;
                }
                $halfMaximum = $maximumArgument / 2.0;
                $minimumSinc = $halfMaximum === 0.0 ? 1.0 : \sin($halfMaximum) / $halfMaximum;
                $range = $this->widenInterval(-0.5, -0.5 * $minimumSinc * $minimumSinc);

                return $range === null ? null : $this->scaleInterval($range, $slope * $slope);
            }
        }

        return null;
    }

    /** @param array<string, int|float> $parameters
     *  @return array{float, float}|null
     */
    private function positiveSquareTermCoefficientInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            $leftRatio = $this->firstOrderVanishingRatioInterval(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            $rightRatio = $this->firstOrderVanishingRatioInterval(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
            );
            if ($leftRatio !== null && $rightRatio !== null) {
                return $this->multiplyIntervals($leftRatio, $rightRatio, true);
            }
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$factor, $coefficientNode]) {
                $coefficient = $this->constantNodeValue($coefficientNode, $parameters, $evaluationOptions);
                if ($coefficient === null || $coefficient <= 0.0) {
                    continue;
                }
                $inner = $this->positiveSquareTermCoefficientInterval(
                    $factor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );
                return $inner === null ? null : $this->scaleInterval($inner, $coefficient);
            }
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $power = RationalLiteral::fromNode($node->right);
            if ($power !== null && $power[0] === 2 && $power[1] === 1) {
                $ratio = $this->firstOrderVanishingRatioInterval(
                    $node->left,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                );

                return $ratio === null ? null : $this->squareInterval($ratio);
            }
        }

        return null;
    }

    /** @param array<string, int|float> $parameters
     *  @return array{float, float}|null
     */
    private function firstOrderVanishingRatioInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof VariableNode && $node->name === $variable) {
            return [1.0, 1.0];
        }
        if (!$node instanceof FunctionCallNode || \count($node->arguments) !== 1) {
            return null;
        }
        $name = $node->name;
        if (!\in_array($name, ['sin', 'tan', 'sinh', 'tanh'], true)) {
            return null;
        }
        $slope = $this->linearVariableCoefficient(
            $node->arguments[0],
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($slope === null) {
            return null;
        }
        $phaseLower = $slope * $lowerBound;
        $phaseUpper = $slope * $upperBound;
        if ($phaseLower > $phaseUpper) {
            [$phaseLower, $phaseUpper] = [$phaseUpper, $phaseLower];
        }
        $phaseScale = $slope;
        if ($name === 'sin') {
            $minimumAbsolutePhase = $phaseLower <= 0.0 && $phaseUpper >= 0.0
                ? 0.0
                : \min(\abs($phaseLower), \abs($phaseUpper));
            $maximumAbsolutePhase = \max(\abs($phaseLower), \abs($phaseUpper));
            $sinc = $maximumAbsolutePhase <= \M_PI
                ? $this->widenInterval(
                    \sin($maximumAbsolutePhase) / ($maximumAbsolutePhase === 0.0 ? 1.0 : $maximumAbsolutePhase),
                    $minimumAbsolutePhase === 0.0
                        ? 1.0
                        : \sin($minimumAbsolutePhase) / $minimumAbsolutePhase,
                )
                : $this->sincIntervalRange($lowerBound, $upperBound, $phaseScale);

            return $sinc === null ? null : $this->scaleInterval($sinc, $slope);
        }
        $maximum = \max(\abs($phaseLower), \abs($phaseUpper));
        if ($name === 'tan') {
            if ($maximum >= \M_PI_2) {
                return null;
            }
            $range = $maximum === 0.0
                ? [1.0, 1.0]
                : $this->widenInterval(1.0, \tan($maximum) / $maximum);
        } elseif ($name === 'sinh') {
            $range = $maximum === 0.0
                ? [1.0, 1.0]
                : $this->widenInterval(1.0, \sinh($maximum) / $maximum);
        } else {
            $range = $maximum === 0.0
                ? [1.0, 1.0]
                : $this->widenInterval(\tanh($maximum) / $maximum, 1.0);
        }

        return $range === null ? null : $this->scaleInterval($range, $slope);
    }

    /** @param array<string, int|float> $parameters */
    private function linearVariableCoefficient(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        $coefficients = (new PolynomialExtractor($variable, $parameters, $evaluationOptions, 1))->extract($node);
        if (
            $coefficients === null
            || \count($coefficients) > 2
            || ($coefficients[0] ?? 0.0) !== 0.0
        ) {
            return null;
        }

        return $coefficients[1] ?? 0.0;
    }

    private function isLiteralOne(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);

        return $node instanceof NumberNode && $node->value == 1.0;
    }

    /** @param array{float, float} $range
     *  @return array{float, float}|null
     */
    private function log1pOverArgumentInterval(array $range): ?array
    {
        if ($range[0] <= -1.0) {
            return null;
        }
        $factor = static fn (float $value): float => $value === 0.0
            ? 1.0
            : \log1p($value) / $value;

        return $this->widenInterval($factor($range[1]), $factor($range[0]));
    }

    /** @param array{float, float} $range
     *  @return array{float, float}|null
     */
    private function scaleInterval(array $range, float $scale): ?array
    {
        $first = $range[0] * $scale;
        $second = $range[1] * $scale;

        return $this->widenArithmeticInterval(\min($first, $second), \max($first, $second));
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function expressionRangeIncludingUnboundedPolynomial(
        Node $node,
        PolynomialExtractor $extractor,
        string $variable,
        array $parameters,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            return $this->boundedExpressionRange(
                $node,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
        }

        $polynomial = $extractor->extract($node);
        if ($polynomial === null) {
            return null;
        }
        $isStrictlyNegative = fn (): bool => $this->isStrictlyNegativeExactPolynomial(
            $node,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions,
        );

        $range = $this->polynomialRangeWithInfiniteBounds(
            $polynomial,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        if ($range === null) {
            return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : null;
        }

        $radius = 1.0;
        if (\is_finite($lowerBound)) {
            $radius = \max($radius, \abs($lowerBound));
        }
        if (\is_finite($upperBound)) {
            $radius = \max($radius, \abs($upperBound));
        }
        $derivative = [];
        foreach ($polynomial as $power => $coefficient) {
            if ($power > 0) {
                $derivative[] = $power * $coefficient;
            }
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }
        if (\count($derivative) > 1) {
            $leadingMagnitude = \abs($derivative[\array_key_last($derivative)]);
            if ($leadingMagnitude === 0.0 || !\is_finite($leadingMagnitude)) {
                return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
            }
            $maximumRatio = 0.0;
            foreach (\array_slice($derivative, 0, -1) as $coefficient) {
                $ratio = \abs($coefficient) / $leadingMagnitude;
                if (!\is_finite($ratio)) {
                    return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = 1.0 + ($maximumRatio * (1.0 + (16.0 * \PHP_FLOAT_EPSILON)));
            if (!\is_finite($rootBound)) {
                return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
            }
            $radius = \max($radius, $rootBound);
        }

        $magnitudeBound = 0.0;
        $radiusPower = 1.0;
        foreach ($polynomial as $coefficient) {
            $termBound = \abs($coefficient) * $radiusPower;
            if (!\is_finite($termBound)) {
                return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
            }
            $magnitudeBound += $termBound;
            if (!\is_finite($magnitudeBound)) {
                return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
            }
            $radiusPower *= $radius;
            if (!\is_finite($radiusPower)) {
                return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
            }
        }
        $errorBound = 64.0 * \PHP_FLOAT_EPSILON * \max(1, \count($polynomial) ** 2) * $magnitudeBound;
        if (!\is_finite($errorBound)) {
            return $isStrictlyNegative() ? [-\INF, -\PHP_FLOAT_MIN] : [-\INF, \INF];
        }

        if (
            $range[0] - $errorBound <= 0.0
            && $range[1] + $errorBound >= 0.0
            && $isStrictlyNegative()
        ) {
            return [-\INF, -\PHP_FLOAT_MIN];
        }

        return [$range[0] - $errorBound, $range[1] + $errorBound];
    }

    /** @param array<string, int|float> $parameters */
    private function isStrictlyNegativeExactPolynomial(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $coefficients = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->difference(
            $node,
            new NumberNode(0, '0', $node->span()),
        );
        $constantCoefficient = $coefficients[0] ?? '0';
        if (
            $coefficients === null
            || $constantCoefficient === ''
            || $constantCoefficient[0] !== '-'
        ) {
            return false;
        }

        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === '0') {
            \array_pop($coefficients);
        }
        if (\count($coefficients) === 1) {
            return true;
        }
        if (\count($coefficients) === 2) {
            return false;
        }
        if (\count($coefficients) === 3) {
            $arithmetic = new IntegerPolynomialExtractor('', [], 3);
            $linearSquared = $arithmetic->multiplyIntegerValues($coefficients[1], $coefficients[1]);
            $fourTimesQuadraticConstant = $arithmetic->multiplyIntegerValues(
                '4',
                $arithmetic->multiplyIntegerValues($coefficients[2], $coefficients[0]),
            );
            $discriminant = $arithmetic->subtract($linearSquared, $fourTimesQuadraticConstant);

            return $arithmetic->compareIntegerValues($discriminant, '0') < 0;
        }
        foreach ($coefficients as $coefficient) {
            if (\strlen(\ltrim($coefficient, '-')) > 512) {
                return false;
            }
        }

        return (new ExactPolynomialRootCounter())->isolateAllRealRoots($coefficients) === [];
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereStrictlyNegative(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return false;
        }
        if (!$this->containsVariable($node, $variable)) {
            try {
                return (float) $this->evaluateNode($node, $parameters, $evaluationOptions) < 0.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof UnaryOperationNode && $node->operator === UnaryOperator::Minus) {
            return $this->isEverywhereStrictlyPositive(
                $node->operand,
                $variable,
                $parameters,
                $evaluationOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return match ($node->operator) {
                BinaryOperator::Add =>
                    ($this->isEverywhereStrictlyNegative($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereNonpositive($node->right, $variable, $parameters, $evaluationOptions))
                    || ($this->isEverywhereNonpositive($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyNegative($node->right, $variable, $parameters, $evaluationOptions)),
                BinaryOperator::Subtract =>
                    $this->isEverywhereNonpositive($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereStrictlyPositive($node->right, $variable, $parameters, $evaluationOptions),
                BinaryOperator::Multiply =>
                    ($this->isEverywhereStrictlyNegative($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyPositive($node->right, $variable, $parameters, $evaluationOptions))
                    || ($this->isEverywhereStrictlyPositive($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyNegative($node->right, $variable, $parameters, $evaluationOptions)),
                default => false,
            };
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereStrictlyPositive(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return false;
        }
        if (!$this->containsVariable($node, $variable)) {
            try {
                return (float) $this->evaluateNode($node, $parameters, $evaluationOptions) > 0.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof UnaryOperationNode) {
            return $node->operator === UnaryOperator::Minus
                && $this->isEverywhereStrictlyNegative(
                    $node->operand,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
        }
        if (
            $node instanceof FunctionCallNode
            && $evaluationOptions->functions->isBuiltIn($node->name)
            && \in_array($node->name, ['exp', 'cosh'], true)
        ) {
            return true;
        }
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'sqrt'
            && $evaluationOptions->functions->isBuiltIn('sqrt')
            && \count($node->arguments) === 1
        ) {
            return $this->isEverywhereStrictlyPositive(
                $node->arguments[0],
                $variable,
                $parameters,
                $evaluationOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return match ($node->operator) {
                BinaryOperator::Add =>
                    ($this->isEverywhereStrictlyPositive($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereNonnegative($node->right, $variable, $parameters, $evaluationOptions))
                    || ($this->isEverywhereNonnegative($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyPositive($node->right, $variable, $parameters, $evaluationOptions)),
                BinaryOperator::Subtract =>
                    $this->isEverywhereStrictlyPositive($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonpositive($node->right, $variable, $parameters, $evaluationOptions),
                BinaryOperator::Multiply =>
                    ($this->isEverywhereStrictlyPositive($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyPositive($node->right, $variable, $parameters, $evaluationOptions))
                    || ($this->isEverywhereStrictlyNegative($node->left, $variable, $parameters, $evaluationOptions)
                        && $this->isEverywhereStrictlyNegative($node->right, $variable, $parameters, $evaluationOptions)),
                default => false,
            };
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereNonnegative(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return false;
        }
        if (!$this->containsVariable($node, $variable)) {
            try {
                return (float) $this->evaluateNode($node, $parameters, $evaluationOptions) >= 0.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof UnaryOperationNode) {
            return $node->operator === UnaryOperator::Minus
                && $this->isEverywhereNonpositive($node->operand, $variable, $parameters, $evaluationOptions);
        }
        if ($node instanceof FunctionCallNode && $node->name === 'abs') {
            return true;
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Power) {
                $exponent = RationalLiteral::fromNode($node->right);

                return $exponent !== null
                    && $exponent[1] === 1
                    && $exponent[0] > 0
                    && ($exponent[0] % 2) === 0;
            }
            if ($node->operator === BinaryOperator::Add) {
                return $this->isEverywhereNonnegative($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonnegative($node->right, $variable, $parameters, $evaluationOptions);
            }
            if ($node->operator === BinaryOperator::Multiply) {
                return (
                    $this->isEverywhereNonnegative($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonnegative($node->right, $variable, $parameters, $evaluationOptions)
                ) || (
                    $this->isEverywhereNonpositive($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonpositive($node->right, $variable, $parameters, $evaluationOptions)
                );
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereNonpositive(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return false;
        }
        if (!$this->containsVariable($node, $variable)) {
            try {
                return (float) $this->evaluateNode($node, $parameters, $evaluationOptions) <= 0.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof UnaryOperationNode) {
            return $node->operator === UnaryOperator::Minus
                && $this->isEverywhereNonnegative($node->operand, $variable, $parameters, $evaluationOptions);
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Subtract) {
                return $this->isEverywhereNonpositive($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonnegative($node->right, $variable, $parameters, $evaluationOptions);
            }
            if ($node->operator === BinaryOperator::Add) {
                return $this->isEverywhereNonpositive($node->left, $variable, $parameters, $evaluationOptions)
                    && $this->isEverywhereNonpositive($node->right, $variable, $parameters, $evaluationOptions);
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereDefinedRealExpression(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof NumberNode || $node instanceof ConstantNode) {
            return true;
        }
        if ($node instanceof VariableNode) {
            return $node->name === $variable || \array_key_exists($node->name, $parameters);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->isEverywhereDefinedRealExpression(
                $node->operand,
                $variable,
                $parameters,
                $evaluationOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Power) {
                $exponent = RationalLiteral::fromNode($node->right);

                return $exponent !== null
                    && $exponent[1] === 1
                    && $exponent[0] > 0
                    && $this->isEverywhereDefinedRealExpression(
                        $node->left,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    );
            }
            if ($node->operator === BinaryOperator::Divide) {
                if (
                    !$this->isEverywhereDefinedRealExpression(
                        $node->left,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    )
                    || !$this->isEverywhereDefinedRealExpression(
                        $node->right,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    )
                ) {
                    return false;
                }
                if (!$this->containsVariable($node->right, $variable)) {
                    $divisor = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);

                    return $divisor !== null && \is_finite($divisor) && $divisor !== 0.0;
                }

                return $this->isEverywhereStrictlyPositive(
                    $node->right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                ) || $this->isEverywhereStrictlyNegative(
                    $node->right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
            }
            if (!\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract, BinaryOperator::Multiply], true)) {
                return false;
            }

            return $this->isEverywhereDefinedRealExpression(
                $node->left,
                $variable,
                $parameters,
                $evaluationOptions,
            ) && $this->isEverywhereDefinedRealExpression(
                $node->right,
                $variable,
                $parameters,
                $evaluationOptions,
            );
        }
        if ($node instanceof FunctionCallNode) {
            if (
                $node->name === 'sqrt'
                && $evaluationOptions->functions->isBuiltIn('sqrt')
                && \count($node->arguments) === 1
            ) {
                return $this->isEverywhereNonnegative(
                    $node->arguments[0],
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
            }
            if (
                !$evaluationOptions->functions->isBuiltIn($node->name)
                || !\in_array($node->name, ['abs', 'arctan', 'atan', 'cos', 'cosh', 'erf', 'exp', 'sin', 'tanh'], true)
                || \count($node->arguments) !== 1
            ) {
                return false;
            }
            foreach ($node->arguments as $argument) {
                if (!$this->isEverywhereDefinedRealExpression($argument, $variable, $parameters, $evaluationOptions)) {
                    return false;
                }
            }

            return true;
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function isEverywhereWithinUnitInterval(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return false;
        }
        if (!$this->containsVariable($node, $variable)) {
            try {
                $value = (float) $this->evaluateNode($node, $parameters, $evaluationOptions);

                return \is_finite($value) && \abs($value) <= 1.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof UnaryOperationNode) {
            return \in_array($node->operator, [UnaryOperator::Plus, UnaryOperator::Minus], true)
                && $this->isEverywhereWithinUnitInterval(
                    $node->operand,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
        }
        if ($node instanceof FunctionCallNode) {
            if (
                \in_array($node->name, ['abs', 'sqrt'], true)
                && \count($node->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn($node->name)
            ) {
                return $this->isEverywhereWithinUnitInterval(
                    $node->arguments[0],
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
            }
            return \in_array($node->name, ['cos', 'erf', 'sin', 'tanh'], true)
                && \count($node->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn($node->name);
        }
        if (!$node instanceof BinaryOperationNode) {
            return false;
        }
        if ($node->operator === BinaryOperator::Power) {
            $exponent = RationalLiteral::fromNode($node->right);

            return $exponent !== null
                && $exponent[1] === 1
                && $exponent[0] > 0
                && $this->isEverywhereWithinUnitInterval(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                );
        }
        if ($node->operator === BinaryOperator::Multiply) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$constant, $bounded]) {
                if ($this->containsVariable($constant, $variable)) {
                    continue;
                }
                $scale = $this->constantNodeValue($constant, $parameters, $evaluationOptions);
                if (
                    $scale !== null
                    && \is_finite($scale)
                    && \abs($scale) <= 1.0
                    && $this->isEverywhereWithinUnitInterval(
                        $bounded,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    )
                ) {
                    return true;
                }
                $bounded = $this->unwrapGrouping($bounded);
                if (
                    $scale !== null
                    && \is_finite($scale)
                    && \abs($scale) <= 2.0 / \M_PI
                    && $bounded instanceof FunctionCallNode
                    && \in_array($bounded->name, ['atan', 'arctan'], true)
                    && \count($bounded->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn($bounded->name)
                ) {
                    return true;
                }
            }
            if (
                $this->isEverywhereWithinUnitInterval(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )
                && $this->isEverywhereWithinUnitInterval(
                    $node->right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )
            ) {
                return true;
            }
        }
        if ($node->operator === BinaryOperator::Divide && !$this->containsVariable($node->right, $variable)) {
            $divisor = $this->constantNodeValue($node->right, $parameters, $evaluationOptions);
            if ($divisor === null || !\is_finite($divisor) || $divisor === 0.0) {
                return false;
            }
            if (
                \abs($divisor) >= 1.0
                && $this->isEverywhereWithinUnitInterval(
                    $node->left,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )
            ) {
                return true;
            }
            $numerator = $this->unwrapGrouping($node->left);
            if ($numerator instanceof FunctionCallNode) {
                return \in_array($numerator->name, ['atan', 'arctan'], true)
                    && \count($numerator->arguments) === 1
                    && $evaluationOptions->functions->isBuiltIn($numerator->name)
                    && \abs($divisor) >= \M_PI / 2.0;
            }
            if ($numerator instanceof BinaryOperationNode && $numerator->operator === BinaryOperator::Multiply) {
                foreach ([[$numerator->left, $numerator->right], [$numerator->right, $numerator->left]] as [$constant, $function]) {
                    $function = $this->unwrapGrouping($function);
                    $scale = $this->constantNodeValue($constant, $parameters, $evaluationOptions);
                    if (
                        $scale !== null
                        && \is_finite($scale)
                        && \abs($scale / $divisor) <= 2.0 / \M_PI
                        && $function instanceof FunctionCallNode
                        && \in_array($function->name, ['atan', 'arctan'], true)
                        && \count($function->arguments) === 1
                        && $evaluationOptions->functions->isBuiltIn($function->name)
                    ) {
                        return true;
                    }
                }
            }

            return false;
        }
        if ($node->operator === BinaryOperator::Divide) {
            $denominator = $this->unwrapGrouping($node->right);
            if (
                !$denominator instanceof FunctionCallNode
                || $denominator->name !== 'sqrt'
                || !$evaluationOptions->functions->isBuiltIn('sqrt')
                || \count($denominator->arguments) !== 1
            ) {
                return false;
            }
            $radicand = $this->unwrapGrouping($denominator->arguments[0]);
            if (!$radicand instanceof BinaryOperationNode || $radicand->operator !== BinaryOperator::Add) {
                return false;
            }
            foreach ([[$radicand->left, $radicand->right], [$radicand->right, $radicand->left]] as [$square, $constant]) {
                $square = $this->unwrapGrouping($square);
                if (!$square instanceof BinaryOperationNode || $square->operator !== BinaryOperator::Power) {
                    continue;
                }
                $exponent = RationalLiteral::fromNode($square->right);
                $offset = $this->constantNodeValue($constant, $parameters, $evaluationOptions);
                if (
                    $exponent !== null
                    && $exponent[1] === 1
                    && $exponent[0] === 2
                    && $this->sameExpression($square->left, $node->left)
                    && $offset !== null
                    && \is_finite($offset)
                    && $offset > 0.0
                ) {
                    return true;
                }
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function continuousExpressionLimitAtInfinity(
        Node $node,
        string $variable,
        float $direction,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        $node = $this->unwrapGrouping($node);
        if (!$this->isEverywhereDefinedRealExpression($node, $variable, $parameters, $evaluationOptions)) {
            return null;
        }
        if (!$this->containsVariable($node, $variable)) {
            $value = $this->constantNodeValue($node, $parameters, $evaluationOptions);

            return $value !== null && \is_finite($value) ? $value : null;
        }
        if ($node instanceof VariableNode) {
            return $direction * \INF;
        }
        if ($node instanceof UnaryOperationNode) {
            $limit = $this->continuousExpressionLimitAtInfinity(
                $node->operand,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
            );

            if ($limit === null) {
                return null;
            }

            return $node->operator === UnaryOperator::Minus ? -$limit : $limit;
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Divide) {
                $numerator = $this->continuousExpressionLimitAtInfinity(
                    $node->left,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                );
                $denominator = $this->continuousExpressionLimitAtInfinity(
                    $node->right,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                );
                if ($numerator === null || $denominator === null) {
                    return null;
                }
                if (\is_infinite($denominator)) {
                    return \is_finite($numerator) ? 0.0 : null;
                }
                if ($denominator === 0.0) {
                    return null;
                }
                $limit = $numerator / $denominator;

                return \is_nan($limit) ? null : $limit;
            }
            if ($node->operator === BinaryOperator::Power) {
                $exponent = RationalLiteral::fromNode($node->right);
                $base = $this->continuousExpressionLimitAtInfinity(
                    $node->left,
                    $variable,
                    $direction,
                    $parameters,
                    $evaluationOptions,
                );
                if ($exponent === null || $exponent[1] !== 1 || $exponent[0] < 1 || $base === null) {
                    return null;
                }
                $limit = $base ** $exponent[0];

                return \is_nan($limit) ? null : $limit;
            }
            $left = $this->continuousExpressionLimitAtInfinity(
                $node->left,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
            );
            $right = $this->continuousExpressionLimitAtInfinity(
                $node->right,
                $variable,
                $direction,
                $parameters,
                $evaluationOptions,
            );
            if ($left === null || $right === null) {
                return null;
            }
            $limit = match ($node->operator) {
                BinaryOperator::Add => $left + $right,
                BinaryOperator::Subtract => $left - $right,
                BinaryOperator::Multiply => $left * $right,
                default => \NAN,
            };

            return \is_nan($limit) ? null : $limit;
        }
        if (!$node instanceof FunctionCallNode || \count($node->arguments) !== 1) {
            return null;
        }
        $argumentLimit = $this->continuousExpressionLimitAtInfinity(
            $node->arguments[0],
            $variable,
            $direction,
            $parameters,
            $evaluationOptions,
        );
        if ($argumentLimit !== null && \is_finite($argumentLimit)) {
            $definition = $evaluationOptions->functions->find($node->name);
            if ($definition === null || !$evaluationOptions->functions->isBuiltIn($node->name)) {
                return null;
            }
            try {
                $limit = $definition->invoke([$argumentLimit]);

                return \is_finite((float) $limit) ? (float) $limit : null;
            } catch (\Throwable) {
                return null;
            }
        }
        if ($argumentLimit !== null && \is_infinite($argumentLimit)) {
            if ($node->name === 'tanh' || $node->name === 'erf') {
                return $argumentLimit > 0.0 ? 1.0 : -1.0;
            }
            if ($node->name === 'atan' || $node->name === 'arctan') {
                return ($argumentLimit > 0.0 ? 1.0 : -1.0) * (\M_PI / 2.0);
            }
            if ($node->name === 'exp') {
                return $argumentLimit < 0.0 ? 0.0 : \INF;
            }
            if ($node->name === 'abs' || $node->name === 'cosh' || $node->name === 'sqrt') {
                return \INF;
            }
        }

        return null;
    }

    private function containsEverywhereUndefinedVariableBaseLogarithm(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if (
                \in_array($node->name, ['ln', 'log2', 'log10', 'log'], true)
                && \count($node->arguments) === 1
            ) {
                if ($this->isEverywhereStrictlyNegative(
                    $node->arguments[0],
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )) {
                    return true;
                }
                $argumentRange = $this->expressionRangeIncludingUnboundedPolynomial(
                    $node->arguments[0],
                    $extractor,
                    $variable,
                    $parameters,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange !== null && $argumentRange[1] <= 0.0) {
                    return true;
                }
                if (
                    $argumentRange === null
                    && $lowerBound === 0.0
                    && $upperBound > 0.0
                    && $this->isNegativeReciprocalOfVanishingPower($node->arguments[0], $variable)
                ) {
                    return true;
                }
                if ($this->isNegativeGammaEvenPower($node->arguments[0])) {
                    return true;
                }
            }
            if ($node->name === 'log' && \count($node->arguments) === 2) {
                $argumentRange = $this->expressionRangeIncludingUnboundedPolynomial(
                    $node->arguments[0],
                    $extractor,
                    $variable,
                    $parameters,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                $baseRange = $this->expressionRangeIncludingUnboundedPolynomial(
                    $node->arguments[1],
                    $extractor,
                    $variable,
                    $parameters,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if (
                    ($argumentRange !== null && $argumentRange[1] <= 0.0)
                    || ($baseRange !== null && $baseRange[1] <= 0.0)
                    || ($baseRange !== null && $baseRange[0] === 1.0 && $baseRange[1] === 1.0)
                ) {
                    return true;
                }
            }
            foreach ($node->arguments as $argument) {
                if (
                    $this->containsEverywhereUndefinedVariableBaseLogarithm(
                        $argument,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $solverOptions,
                        $extractor,
                    )
                ) {
                    return true;
                }
            }
        } elseif ($node instanceof BinaryOperationNode) {
            return $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $extractor,
            ) || $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $extractor,
            );
        } elseif ($node instanceof UnaryOperationNode) {
            return $this->containsEverywhereUndefinedVariableBaseLogarithm(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
                $extractor,
            );
        }

        return false;
    }

    private function containsEverywhereUndefinedSquareRoot(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if ($node->name === 'sqrt' && \count($node->arguments) === 1) {
                $argument = $node->arguments[0];
                if ($this->isEverywhereStrictlyNegative(
                    $argument,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )) {
                    return true;
                }
                $range = $this->expressionRangeIncludingUnboundedPolynomial(
                    $argument,
                    $extractor,
                    $variable,
                    $parameters,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($range !== null && $range[1] < 0.0) {
                    return true;
                }
                if (
                    $range === null
                    && $lowerBound === 0.0
                    && $upperBound > 0.0
                    && $this->isNegativeReciprocalOfVanishingPower($argument, $variable)
                ) {
                    return true;
                }
            }
            foreach ($node->arguments as $argument) {
                if (
                    $this->containsEverywhereUndefinedSquareRoot(
                        $argument,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $extractor,
                        $evaluationOptions,
                        $solverOptions,
                    )
                ) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsEverywhereUndefinedSquareRoot(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $extractor,
                $evaluationOptions,
                $solverOptions,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsEverywhereUndefinedSquareRoot(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $extractor,
                $evaluationOptions,
                $solverOptions,
            ) || $this->containsEverywhereUndefinedSquareRoot(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $extractor,
                $evaluationOptions,
                $solverOptions,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->containsEverywhereUndefinedSquareRoot(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $extractor,
                $evaluationOptions,
                $solverOptions,
            );
        }

        return false;
    }

    private function isNegativeGammaEvenPower(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode && $node->operator === UnaryOperator::Minus) {
            $node = $this->unwrapGrouping($node->operand);
        } else {
            return false;
        }
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Power) {
            return false;
        }
        $power = RationalLiteral::fromNode($node->right);

        return $power !== null
            && $power[0] > 0
            && $power[1] === 1
            && $power[0] % 2 === 0
            && $this->containsNamedFunction($node->left, 'gamma');
    }

    private function isTotalZeroPowerBase(
        Node $node,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if (!$this->containsVariable($node, $variable)) {
            return true;
        }
        if ($node instanceof GroupingNode) {
            return $this->isTotalZeroPowerBase($node->expression, $variable, $evaluationOptions);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->isTotalZeroPowerBase($node->operand, $variable, $evaluationOptions);
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Modulo) {
                return false;
            }
            if ($node->operator === BinaryOperator::Power) {
                $exponent = RationalLiteral::fromNode($node->right);
                if ($exponent === null || $exponent[1] !== 1 || $exponent[0] < 0) {
                    return false;
                }

                return $this->isTotalZeroPowerBase($node->left, $variable, $evaluationOptions);
            }

            return $this->isTotalZeroPowerBase($node->left, $variable, $evaluationOptions)
                && $this->isTotalZeroPowerBase($node->right, $variable, $evaluationOptions);
        }
        if ($node instanceof FunctionCallNode) {
            if (
                !$evaluationOptions->functions->isBuiltIn($node->name)
                || !\in_array(
                    $node->name,
                    [
                        'abs', 'acot', 'acosh', 'arccosh', 'acsch', 'acoth', 'arccos',
                        'arcsin', 'arctan', 'arcsinh', 'arctanh', 'asin', 'acos', 'asinh',
                        'atan', 'atanh', 'beta', 'cbrt', 'cos', 'cosh', 'cot', 'csc', 'csch',
                        'dawson', 'digamma', 'erf', 'erfc', 'erfcx', 'erfinv', 'erfcinv',
                        'erfi', 'exp', 'expm1', 'floor', 'ceil', 'hypot', 'lgamma', 'ln',
                        'log', 'log10', 'log2', 'log1p', 'max', 'min', 'polygamma', 'round',
                        'sec', 'sign', 'sin', 'sinc', 'sincpi', 'sinh', 'sqrt', 'tanh',
                        'tan', 'trigamma', 'tetragamma', 'trunc', 'zeta',
                    ],
                    true,
                )
            ) {
                return false;
            }
            foreach ($node->arguments as $argument) {
                if (!$this->isTotalZeroPowerBase($argument, $variable, $evaluationOptions)) {
                    return false;
                }
            }

            return true;
        }

        return false;
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function builtInIntervalRange(
        string $name,
        array $arguments,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if ($name === 'erfi' && \count($arguments) === 1) {
            return $this->erfiIntervalRange($arguments[0][0], $arguments[0][1]);
        }
        if ($name === 'erfcx' && \count($arguments) === 1) {
            return $this->erfcxIntervalRange($arguments[0][0], $arguments[0][1]);
        }
        if ($name === 'min' || $name === 'max') {
            if ($arguments === []) {
                return null;
            }
            $lowerValues = \array_map(static fn (array $range): float => $range[0], $arguments);
            $upperValues = \array_map(static fn (array $range): float => $range[1], $arguments);
            $bounds = $name === 'min'
                ? [\min(...$lowerValues), \min(...$upperValues)]
                : [\max(...$lowerValues), \max(...$upperValues)];

            return $this->widenInterval($bounds[0], $bounds[1]);
        }
        if ($name === 'log' && \count($arguments) === 2) {
            $numerator = $this->builtInIntervalRange('ln', [$arguments[0]], $evaluationOptions);
            $denominator = $this->builtInIntervalRange('ln', [$arguments[1]], $evaluationOptions);

            return $numerator === null || $denominator === null
                ? null
                : $this->divideIntervals($numerator, $denominator);
        }
        if ($name === 'gamma' && \count($arguments) === 1) {
            return $this->gammaIntervalRange($arguments[0], $evaluationOptions);
        }
        if (
            $name === 'beta'
            && \count($arguments) === 2
        ) {
            $sumRange = $this->widenArithmeticInterval(
                $arguments[0][0] + $arguments[1][0],
                $arguments[0][1] + $arguments[1][1],
            );
            if (
                $sumRange === null
                || $arguments[0][0] <= -171.0
                || $arguments[1][0] <= -171.0
                || $sumRange[0] <= -171.0
            ) {
                return null;
            }

            $firstGamma = $this->gammaIntervalRange($arguments[0], $evaluationOptions);
            $secondGamma = $this->gammaIntervalRange($arguments[1], $evaluationOptions);
            $sumGamma = $this->gammaIntervalRange($sumRange, $evaluationOptions);
            if ($firstGamma === null || $secondGamma === null || $sumGamma === null) {
                return null;
            }

            $numerator = $this->multiplyIntervals($firstGamma, $secondGamma);

            return $numerator === null ? null : $this->divideIntervals($numerator, $sumGamma);
        }
        if ($name === 'zeta' && \count($arguments) === 1 && $arguments[0][0] > 1.0) {
            $zeta = $evaluationOptions->functions->find('zeta');
            if ($zeta === null) {
                return null;
            }

            try {
                $range = $this->monotoneIntervalRange(
                    static fn (float $value): float => (float) $zeta->invoke([$value]),
                    $arguments[0][0],
                    $arguments[0][1],
                );
            } catch (\DomainException | \OverflowException) {
                return null;
            }

            return $range === null ? null : $this->widenInterval($range[0], $range[1]);
        }
        if (
            $name === 'polygamma'
            && \count($arguments) === 2
            && $arguments[0][0] === $arguments[0][1]
            && $arguments[0][0] >= 0.0
            && $arguments[0][0] <= SpecialFunctions::MAX_POLYGAMMA_ORDER
            && (float) \floor((float) $arguments[0][0]) === (float) $arguments[0][0]
        ) {
            $order = (int) $arguments[0][0];

            return $this->polygammaIntervalRange($order, $arguments[1][0], $arguments[1][1]);
        }
        if (
            \in_array($name, ['besselj', 'besseli'], true)
            && \count($arguments) === 2
        ) {
            return $this->integerOrderBesselIntervalRange($name, $arguments);
        }
        if ($name === 'bessely' && \count($arguments) === 2) {
            return $this->integerOrderBesselYIntervalRange($arguments);
        }
        if (
            \in_array($name, ['binomial', 'permutation', 'gcd', 'lcm'], true)
            && \count($arguments) === 2
        ) {
            return $this->discreteIntegerFunctionIntervalRange($name, $arguments, $evaluationOptions);
        }
        if ($name === 'doublefactorial' && \count($arguments) === 1) {
            return $this->discreteIntegerFunctionIntervalRange($name, $arguments, $evaluationOptions);
        }
        if ($name === 'hypot' && \count($arguments) === 2) {
            $minimumAbsolute = static fn (float $lower, float $upper): float =>
                $lower <= 0.0 && $upper >= 0.0
                    ? 0.0
                    : \min(\abs($lower), \abs($upper));
            $minimum = \hypot(
                $minimumAbsolute($arguments[0][0], $arguments[0][1]),
                $minimumAbsolute($arguments[1][0], $arguments[1][1]),
            );
            $maximum = \hypot(
                \max(\abs($arguments[0][0]), \abs($arguments[0][1])),
                \max(\abs($arguments[1][0]), \abs($arguments[1][1])),
            );

            return $this->widenInterval($minimum, $maximum);
        }
        if ($name === 'atan2' && \count($arguments) === 2) {
            return $this->arctangentTwoIntervalRange($arguments[0], $arguments[1]);
        }
        if (
            \in_array($name, ['gammaincinv', 'gammainccinv'], true)
            && \count($arguments) === 2
        ) {
            return $this->inverseRegularizedGammaIntervalRange($name, $arguments);
        }
        if (
            \in_array($name, ['betaincinv', 'betainccinv'], true)
            && \count($arguments) === 3
        ) {
            return $this->inverseRegularizedBetaIntervalRange($name, $arguments);
        }
        if (
            \in_array($name, ['gammainc', 'gammaincc'], true)
            && \count($arguments) === 2
        ) {
            return $this->regularizedGammaIntervalRange($name, $arguments);
        }
        if (
            \in_array($name, ['betainc', 'betaincc'], true)
            && \count($arguments) === 3
        ) {
            return $this->regularizedBetaIntervalRange($name, $arguments);
        }
        if ($name === 'lambertw' && \in_array(\count($arguments), [1, 2], true)) {
            $branch = 0.0;
            if (\count($arguments) === 2) {
                if ($arguments[1][0] !== $arguments[1][1]) {
                    return null;
                }
                $branch = $arguments[1][0];
            }
            if ($branch !== 0.0 && $branch !== -1.0) {
                return null;
            }
            $function = $evaluationOptions->functions->find('lambertw');
            if ($function === null) {
                return null;
            }
            [$lower, $upper] = $arguments[0];
            $branchPoint = -1.0 / \M_E;
            try {
                if ($branch === 0.0) {
                    if ($upper < $branchPoint) {
                        return null;
                    }
                    $first = $function->invoke([\max($lower, $branchPoint), 0]);
                    $second = $function->invoke([$upper, 0]);

                    return $this->widenInterval((float) $first, (float) $second);
                }
                if ($upper < $branchPoint || $upper >= 0.0) {
                    return null;
                }
                $first = $function->invoke([$upper, -1]);
                $second = $function->invoke([\max($lower, $branchPoint), -1]);

                return $this->widenInterval((float) $first, (float) $second);
            } catch (\DomainException | \OverflowException) {
                return null;
            }
        }
        if ($name === 'root' && \count($arguments) === 2) {
            return $this->variableDegreeRootIntervalRange($arguments[0], $arguments[1]);
        }
        if (\count($arguments) === 1 && ($name === 'sec' || $name === 'csc')) {
            $denominator = $this->builtInIntervalRange(
                $name === 'sec' ? 'cos' : 'sin',
                $arguments,
                $evaluationOptions,
            );

            return $denominator === null
                ? null
                : $this->divideIntervals([1.0, 1.0], $denominator);
        }
        if ($name === 'cot' && \count($arguments) === 1) {
            $numerator = $this->builtInIntervalRange('cos', $arguments, $evaluationOptions);
            $denominator = $this->builtInIntervalRange('sin', $arguments, $evaluationOptions);

            return $numerator === null || $denominator === null
                ? null
                : $this->divideIntervals($numerator, $denominator);
        }
        if (\count($arguments) === 1 && ($name === 'asec' || $name === 'acsc')) {
            return $this->inverseReciprocalTrigIntervalRange($name, $arguments[0][0], $arguments[0][1]);
        }
        if ($name === 'acot' && \count($arguments) === 1) {
            return $this->widenInterval(
                \atan2(1.0, $arguments[0][1]),
                \atan2(1.0, $arguments[0][0]),
            );
        }
        if (
            \count($arguments) === 1
            && \in_array($name, ['asech', 'acsch', 'acoth'], true)
        ) {
            return $this->inverseReciprocalHyperbolicIntervalRange(
                $name,
                $arguments[0][0],
                $arguments[0][1],
            );
        }
        if (\count($arguments) !== 1) {
            return null;
        }
        [$lower, $upper] = $arguments[0];
        try {
            $range = match ($name) {
                'exp' => $this->monotoneIntervalRange(\exp(...), $lower, $upper),
                'expm1' => $this->monotoneIntervalRange(\expm1(...), $lower, $upper),
                'ln' => $lower > 0.0 ? $this->monotoneIntervalRange(\log(...), $lower, $upper) : null,
                'log10' => $lower > 0.0 ? $this->monotoneIntervalRange(\log10(...), $lower, $upper) : null,
                'log2' => $lower > 0.0
                    ? $this->monotoneIntervalRange(
                        static fn (float $value): float => \log($value, 2.0),
                        $lower,
                        $upper,
                    )
                    : null,
                'log1p' => $lower > -1.0 ? $this->monotoneIntervalRange(\log1p(...), $lower, $upper) : null,
                'sqrt' => $lower >= 0.0 ? $this->monotoneIntervalRange(\sqrt(...), $lower, $upper) : null,
                'cbrt' => $this->monotoneIntervalRange(self::realCubeRoot(...), $lower, $upper),
                'abs' => [
                    $lower <= 0.0 && $upper >= 0.0 ? 0.0 : \min(\abs($lower), \abs($upper)),
                    \max(\abs($lower), \abs($upper)),
                ],
                'sinc' => $this->sincIntervalRange($lower, $upper, 1.0),
                'sincpi' => $this->sincIntervalRange($lower, $upper, \M_PI),
                'sin' => $this->trigonometricIntervalRange($lower, $upper, false),
                'cos' => $this->trigonometricIntervalRange($lower, $upper, true),
                'tan' => $this->tangentIntervalRange($lower, $upper),
                'sinh' => $this->monotoneIntervalRange(\sinh(...), $lower, $upper),
                'tanh' => $this->monotoneIntervalRange(\tanh(...), $lower, $upper),
                'asinh' => $this->monotoneIntervalRange(\asinh(...), $lower, $upper),
                'atan', 'arctan' => $this->monotoneIntervalRange(\atan(...), $lower, $upper),
                'asin', 'arcsin' => $lower >= -1.0 && $upper <= 1.0
                    ? $this->monotoneIntervalRange(\asin(...), $lower, $upper)
                    : null,
                'acos', 'arccos' => $lower >= -1.0 && $upper <= 1.0
                    ? [\acos($upper), \acos($lower)]
                    : null,
                'acosh', 'arccosh' => $lower >= 1.0
                    ? $this->monotoneIntervalRange(\acosh(...), $lower, $upper)
                    : null,
                'atanh', 'arctanh' => $lower > -1.0 && $upper < 1.0
                    ? $this->monotoneIntervalRange(\atanh(...), $lower, $upper)
                    : null,
                'cosh' => $this->hyperbolicCosineIntervalRange($lower, $upper),
                'sech' => $this->hyperbolicSecantIntervalRange($lower, $upper),
                'csch' => $this->reciprocalHyperbolicIntervalRange($lower, $upper, false),
                'coth' => $this->reciprocalHyperbolicIntervalRange($lower, $upper, true),
                'erf' => $this->monotoneIntervalRange(SpecialFunctions::erf(...), $lower, $upper),
                'erfc' => [SpecialFunctions::erfc($upper), SpecialFunctions::erfc($lower)],
                'erfinv' => $lower > -1.0 && $upper < 1.0
                    ? $this->monotoneIntervalRange(SpecialFunctions::inverseErf(...), $lower, $upper)
                    : null,
                'erfcinv' => $lower > 0.0 && $upper < 2.0
                    ? $this->monotoneIntervalRange(SpecialFunctions::inverseErfc(...), $lower, $upper)
                    : null,
                'dawson' => $this->dawsonIntervalRange($lower, $upper),
                'digamma' => $this->digammaIntervalRange($lower, $upper),
                'trigamma' => $this->trigammaIntervalRange($lower, $upper),
                'tetragamma' => $this->tetragammaIntervalRange($lower, $upper),
                'lgamma' => $this->logGammaIntervalRange($lower, $upper, $evaluationOptions),
                'floor' => [(float) \floor($lower), (float) \floor($upper)],
                'ceil' => [(float) \ceil($lower), (float) \ceil($upper)],
                'round' => [(float) \round($lower), (float) \round($upper)],
                'trunc' => $this->monotoneIntervalRange(
                    static fn (float $value): float => $value < 0.0 ? \ceil($value) : \floor($value),
                    $lower,
                    $upper,
                ),
                'sign' => [(float) ($lower <=> 0.0), (float) ($upper <=> 0.0)],
                default => null,
            };
        } catch (\DomainException | \OverflowException) {
            return null;
        }
        if ($range === null) {
            return null;
        }

        return $this->widenInterval($range[0], $range[1]);
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function discreteIntegerFunctionIntervalRange(
        string $name,
        array $arguments,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $integerBounds = [];
        $combinationCount = 1;
        foreach ($arguments as [$lower, $upper]) {
            if (!\is_finite($lower) || !\is_finite($upper)) {
                return null;
            }
            $minimumInput = $name === 'doublefactorial'
                ? -1.0
                : (\in_array($name, ['gcd', 'lcm'], true) ? -\PHP_INT_MAX : 0.0);
            $maximumInput = $name === 'doublefactorial'
                ? 34.0
                : (float) \PHP_INT_MAX;
            if (
                $upper < $minimumInput
                || $lower > $maximumInput
                || (\in_array($name, ['binomial', 'permutation'], true)
                    && ($lower >= $maximumInput || $upper >= $maximumInput))
                || (\in_array($name, ['gcd', 'lcm'], true)
                    && ($lower <= -(float) \PHP_INT_MAX || $upper >= (float) \PHP_INT_MAX))
            ) {
                return null;
            }
            $first = \max($minimumInput, \ceil($lower));
            $last = \min($maximumInput, \floor($upper));
            if ($first > $last) {
                return null;
            }
            $count = $last - $first + 1.0;
            if (
                $count > self::MAX_DISCRETE_INTERVAL_COMBINATIONS
                || $combinationCount * $count > self::MAX_DISCRETE_INTERVAL_COMBINATIONS
            ) {
                return null;
            }
            $combinationCount = (int) ($combinationCount * $count);
            $integerBounds[] = [(int) $first, (int) $last];
        }

        $definition = $evaluationOptions->functions->find($name);
        if ($definition === null) {
            return null;
        }
        $minimum = null;
        $maximum = null;
        [$firstN, $lastN] = $integerBounds[0];
        $nCount = $lastN - $firstN + 1;
        $kCount = isset($integerBounds[1])
            ? $integerBounds[1][1] - $integerBounds[1][0] + 1
            : 1;
        for ($nOffset = 0; $nOffset < $nCount; ++$nOffset) {
            $n = $firstN + $nOffset;
            for ($kOffset = 0; $kOffset < $kCount; ++$kOffset) {
                $argumentsToInvoke = [$n];
                if (isset($integerBounds[1])) {
                    $argumentsToInvoke[] = $integerBounds[1][0] + $kOffset;
                }
                try {
                    $value = (float) $definition->invoke($argumentsToInvoke);
                } catch (\DomainException | \OverflowException) {
                    continue;
                }
                if (!\is_finite($value)) {
                    continue;
                }
                $minimum = $minimum === null ? $value : \min($minimum, $value);
                $maximum = $maximum === null ? $value : \max($maximum, $value);
            }
        }
        if ($minimum === null || $maximum === null) {
            return null;
        }

        return $this->widenInterval($minimum, $maximum);
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function integerOrderBesselIntervalRange(string $name, array $arguments): ?array
    {
        [$orderLower, $orderUpper] = $arguments[0];
        $orderLower = \max(-SpecialFunctions::MAX_BESSEL_ORDER, $orderLower);
        $orderUpper = \min(SpecialFunctions::MAX_BESSEL_ORDER, $orderUpper);
        if (\ceil($orderLower) > \floor($orderUpper)) {
            return null;
        }

        $maximumArgument = $name === 'besselj'
            ? SpecialFunctions::MAX_BESSEL_J_ARGUMENT
            : SpecialFunctions::MAX_BESSEL_I_ARGUMENT;
        [$argumentLower, $argumentUpper] = $arguments[1];
        $argumentLower = \max(-$maximumArgument, $argumentLower);
        $argumentUpper = \min($maximumArgument, $argumentUpper);
        if ($argumentLower > $argumentUpper) {
            return null;
        }
        if ($name === 'besselj') {
            return $this->widenInterval(-1.0, 1.0);
        }

        $firstOrder = (int) \ceil($orderLower);
        $lastOrder = (int) \floor($orderUpper);
        if ($lastOrder - $firstOrder + 1 <= self::MAX_BESSEL_INTERVAL_ORDERS) {
            return $this->modifiedBesselIntervalRange(
                $firstOrder,
                $lastOrder,
                $argumentLower,
                $argumentUpper,
            );
        }

        $maximumMagnitude = \max(\abs($argumentLower), \abs($argumentUpper));
        if ($maximumMagnitude > \log(\PHP_FLOAT_MAX)) {
            return null;
        }
        $bound = \exp($maximumMagnitude);

        return $this->widenInterval(-$bound, $bound);
    }

    /**
     * Enclose Bessel Y over integer orders when its positive argument is fixed.
     *
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function integerOrderBesselYIntervalRange(array $arguments): ?array
    {
        [$orderLower, $orderUpper] = $arguments[0];
        [$argumentLower, $argumentUpper] = $arguments[1];
        if ($argumentLower !== $argumentUpper) {
            return null;
        }
        $firstOrder = (int) \max(-SpecialFunctions::MAX_BESSEL_ORDER, \ceil($orderLower));
        $lastOrder = (int) \min(SpecialFunctions::MAX_BESSEL_ORDER, \floor($orderUpper));
        if ($firstOrder > $lastOrder) {
            return null;
        }

        $minimum = \INF;
        $maximum = -\INF;
        for ($order = $firstOrder; $order <= $lastOrder; ++$order) {
            try {
                $value = SpecialFunctions::besselY($order, $argumentLower);
            } catch (\DomainException | \OverflowException) {
                continue;
            }
            $minimum = \min($minimum, $value);
            $maximum = \max($maximum, $value);
        }
        if (!\is_finite($minimum) || !\is_finite($maximum)) {
            return null;
        }

        return $this->widenInterval($minimum, $maximum);
    }

    /** @return array{float, float}|null */
    private function modifiedBesselIntervalRange(
        int $firstOrder,
        int $lastOrder,
        float $argumentLower,
        float $argumentUpper,
    ): ?array {
        $lower = \INF;
        $upper = -\INF;
        $containsZero = $argumentLower <= 0.0 && $argumentUpper >= 0.0;
        $maximumMagnitude = \max(\abs($argumentLower), \abs($argumentUpper));
        $minimumMagnitude = $containsZero
            ? 0.0
            : \min(\abs($argumentLower), \abs($argumentUpper));

        try {
            for ($order = $firstOrder; $order <= $lastOrder; ++$order) {
                $absoluteOrder = \abs($order);
                $minimumMagnitudeValue = SpecialFunctions::besselI($absoluteOrder, $minimumMagnitude);
                $maximumMagnitudeValue = SpecialFunctions::besselI($absoluteOrder, $maximumMagnitude);
                if ($containsZero && ($absoluteOrder & 1) === 1) {
                    $orderLower = $argumentLower < 0.0
                        ? -SpecialFunctions::besselI($absoluteOrder, \abs($argumentLower))
                        : 0.0;
                    $orderUpper = $argumentUpper > 0.0
                        ? SpecialFunctions::besselI($absoluteOrder, $argumentUpper)
                        : 0.0;
                } elseif ($argumentUpper < 0.0 && ($absoluteOrder & 1) === 1) {
                    $orderLower = -$maximumMagnitudeValue;
                    $orderUpper = -$minimumMagnitudeValue;
                } else {
                    $orderLower = $minimumMagnitudeValue;
                    $orderUpper = $maximumMagnitudeValue;
                }
                $lower = \min($lower, $orderLower);
                $upper = \max($upper, $orderUpper);
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($lower, $upper);
    }

    /**
     * @param callable(float): float $function
     * @return array{float, float}|null
     */
    private function monotoneIntervalRange(callable $function, float $lower, float $upper): ?array
    {
        $first = $function($lower);
        $second = $function($upper);
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }

        return $this->widenInterval(\min($first, $second), \max($first, $second));
    }

    /** @return array{float, float}|null */
    private function erfiIntervalRange(float $lower, float $upper): ?array
    {
        try {
            $range = $this->monotoneIntervalRange(SpecialFunctions::erfi(...), $lower, $upper);
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $range === null ? null : $this->widenInterval($range[0], $range[1]);
    }

    /** @return array{float, float}|null */
    private function erfcxIntervalRange(float $lower, float $upper): ?array
    {
        try {
            $first = SpecialFunctions::erfcx($lower);
            $second = SpecialFunctions::erfcx($upper);
        } catch (\DomainException | \OverflowException) {
            return null;
        }
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }

        return $this->widenInterval(\min($first, $second), \max($first, $second));
    }

    /** @return array{float, float} */
    private function dawsonIntervalRange(float $lower, float $upper): array
    {
        if ($lower >= 1.0 || $upper <= -1.0) {
            // For x >= 1, exp(s^2) >= 1 + s^2 in
            // D(x) = integral_0^x exp(-2*x*s + s^2) ds gives x*D(x) > 1/2,
            // so D'(x) = 1 - 2*x*D(x) < 0. Odd symmetry gives the negative tail.
            $first = SpecialFunctions::dawson($lower);
            $second = SpecialFunctions::dawson($upper);

            return $this->widenInterval(\min($first, $second), \max($first, $second))
                ?? [-1.0, 1.0];
        }

        // D'(x) = 1 - 2*x*D(x) has magnitude at most 1 on the central region.
        $center = ($lower / 2.0) + ($upper / 2.0);
        $radius = ($upper / 2.0) - ($lower / 2.0);
        try {
            $centerValue = SpecialFunctions::dawson($center);
        } catch (\DomainException | \OverflowException) {
            return [-1.0, 1.0];
        }
        $variationBound = $radius;
        if (!\is_finite($variationBound)) {
            return [-1.0, 1.0];
        }

        return [
            \max(-1.0, $centerValue - $variationBound),
            \min(1.0, $centerValue + $variationBound),
        ];
    }

    /** @param array{float, float} $argument
     *  @return array{float, float}|null
     */
    private function gammaIntervalRange(array $argument, EvaluationOptions $evaluationOptions): ?array
    {
        [$lower, $upper] = $argument;
        if (
            ($lower < 0.0 && $upper >= 0.0)
            || ($lower < 0.0 && \ceil($lower) <= \floor($upper))
        ) {
            return null;
        }
        $gamma = $evaluationOptions->functions->find('gamma');
        if ($gamma === null) {
            return null;
        }

        if ($lower >= 1.5 && $upper > 171.0) {
            try {
                $lowerValue = (float) $gamma->invoke([$lower]);
            } catch (\DomainException | \OverflowException) {
                return null;
            }
            for ($step = 0; $step < 16; ++$step) {
                $lowerValue = $this->adjacentFloat($lowerValue, -1);
                if ($lowerValue === null) {
                    return null;
                }
            }

            return [$lowerValue, \PHP_FLOAT_MAX];
        }

        try {
            $lowerValue = (float) $gamma->invoke([$lower]);
            $upperValue = (float) $gamma->invoke([$upper]);
            $lowerDigamma = $lower > 0.0 && $lower <= 1.0
                ? -1.0
                : SpecialFunctions::digamma($lower);
            $upperDigamma = $upper >= 2.0 ? 1.0 : SpecialFunctions::digamma($upper);
            if ($lowerDigamma >= 0.0 || $upperDigamma <= 0.0) {
                return $this->widenInterval(
                    \min($lowerValue, $upperValue),
                    \max($lowerValue, $upperValue),
                );
            }

            $minimumLower = $lower;
            $minimumUpper = $upper;
            for ($iteration = 0; $iteration < 64; ++$iteration) {
                $middle = $minimumLower + (($minimumUpper - $minimumLower) / 2.0);
                if ($middle === $minimumLower || $middle === $minimumUpper) {
                    break;
                }
                if (SpecialFunctions::digamma($middle) < 0.0) {
                    $minimumLower = $middle;
                } else {
                    $minimumUpper = $middle;
                }
            }
            $minimumValue = (float) $gamma->invoke([
                $minimumLower + (($minimumUpper - $minimumLower) / 2.0),
            ]);
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval(
            \min($lowerValue, $upperValue, $minimumValue),
            \max($lowerValue, $upperValue, $minimumValue),
        );
    }

    /** @return array{float, float}|null */
    private function digammaIntervalRange(float $lower, float $upper): ?array
    {
        if (
            ($lower <= 0.0 && $upper >= 0.0)
            || ($lower < 0.0 && \ceil($lower) <= \floor($upper))
        ) {
            return null;
        }

        try {
            return $this->monotoneIntervalRange(SpecialFunctions::digamma(...), $lower, $upper);
        } catch (\DomainException | \OverflowException) {
            return null;
        }
    }

    /** @return array{float, float}|null */
    private function trigammaIntervalRange(float $lower, float $upper): ?array
    {
        if ($lower > 0.0) {
            return $this->monotoneIntervalRange(SpecialFunctions::trigamma(...), $lower, $upper);
        }
        if ($upper >= 0.0 || \ceil($lower) <= \floor($upper)) {
            return null;
        }

        $shiftValue = \ceil(-$upper);
        if ($shiftValue < 1.0 || $shiftValue > 512.0) {
            return null;
        }
        $shift = (int) $shiftValue;
        $shiftedLower = $lower + $shift;
        $shiftedUpper = $upper + $shift;
        if ($shiftedLower <= 0.0 || !\is_finite($shiftedUpper)) {
            return null;
        }

        try {
            $tailRange = $this->widenInterval(
                SpecialFunctions::trigamma($shiftedUpper),
                SpecialFunctions::trigamma($shiftedLower),
            );
            if ($tailRange === null) {
                return null;
            }
            [$lowerBound, $upperBound] = $tailRange;
            for ($index = 0; $index < $shift; ++$index) {
                $firstDenominator = $lower + $index;
                $lastDenominator = $upper + $index;
                if ($firstDenominator >= 0.0 || $lastDenominator >= 0.0) {
                    return null;
                }
                $largestMagnitude = \max(\abs($firstDenominator), \abs($lastDenominator));
                $smallestMagnitude = \min(\abs($firstDenominator), \abs($lastDenominator));
                $smallestSquare = $smallestMagnitude * $smallestMagnitude;
                $largestSquare = $largestMagnitude * $largestMagnitude;
                if ($smallestSquare === 0.0) {
                    return null;
                }
                $termRange = $this->widenArithmeticInterval(
                    \is_finite($largestSquare) ? 1.0 / $largestSquare : 0.0,
                    1.0 / $smallestSquare,
                );
                if ($termRange === null) {
                    return null;
                }
                $sum = $this->addIntervalRanges([$lowerBound, $upperBound], $termRange);
                $widenedSum = $sum === null
                    ? null
                    : $this->widenArithmeticInterval($sum[0], $sum[1]);
                if ($widenedSum === null) {
                    return null;
                }
                [$lowerBound, $upperBound] = $widenedSum;
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($lowerBound, $upperBound);
    }

    /** @return array{float, float}|null */
    private function tetragammaIntervalRange(float $lower, float $upper): ?array
    {
        if ($lower > 0.0) {
            return $this->monotoneIntervalRange(SpecialFunctions::tetragamma(...), $lower, $upper);
        }
        if ($upper >= 0.0 || \ceil($lower) <= \floor($upper)) {
            return null;
        }

        $shiftValue = \ceil(-$upper);
        if ($shiftValue < 1.0 || $shiftValue > 512.0) {
            return null;
        }
        $shift = (int) $shiftValue;
        $shiftedLower = $lower + $shift;
        $shiftedUpper = $upper + $shift;
        if ($shiftedLower <= 0.0 || !\is_finite($shiftedUpper)) {
            return null;
        }

        try {
            $tailRange = $this->widenInterval(
                SpecialFunctions::tetragamma($shiftedLower),
                SpecialFunctions::tetragamma($shiftedUpper),
            );
            if ($tailRange === null) {
                return null;
            }
            [$lowerBound, $upperBound] = $tailRange;
            for ($index = 0; $index < $shift; ++$index) {
                $firstDenominator = $lower + $index;
                $lastDenominator = $upper + $index;
                if ($firstDenominator >= 0.0 || $lastDenominator >= 0.0) {
                    return null;
                }
                $firstCube = $firstDenominator ** 3;
                $lastCube = $lastDenominator ** 3;
                if ($firstCube === 0.0 || $lastCube === 0.0) {
                    return null;
                }
                $termRange = $this->widenArithmeticInterval(
                    -2.0 / $firstCube,
                    -2.0 / $lastCube,
                );
                if ($termRange === null) {
                    return null;
                }
                $sum = $this->addIntervalRanges([$lowerBound, $upperBound], $termRange);
                $widenedSum = $sum === null
                    ? null
                    : $this->widenArithmeticInterval($sum[0], $sum[1]);
                if ($widenedSum === null) {
                    return null;
                }
                [$lowerBound, $upperBound] = $widenedSum;
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($lowerBound, $upperBound);
    }

    /** @return array{float, float}|null */
    private function polygammaIntervalRange(int $order, float $lower, float $upper): ?array
    {
        if ($lower > 0.0) {
            try {
                $first = SpecialFunctions::polygamma($order, $lower);
                $second = SpecialFunctions::polygamma($order, $upper);
            } catch (\DomainException | \OverflowException) {
                return null;
            }

            return ($order % 2) === 0
                ? $this->widenInterval($first, $second)
                : $this->widenInterval($second, $first);
        }
        if ($upper >= 0.0 || \ceil($lower) <= \floor($upper)) {
            return null;
        }

        $shiftValue = \ceil(-$upper);
        if ($shiftValue < 1.0 || $shiftValue > 512.0) {
            return null;
        }
        $shift = (int) $shiftValue;
        $shiftedLower = $lower + $shift;
        $shiftedUpper = $upper + $shift;
        if ($shiftedLower <= 0.0 || !\is_finite($shiftedUpper)) {
            return null;
        }

        $factorial = 1.0;
        for ($factor = 2; $factor <= $order; ++$factor) {
            $factorial *= $factor;
            if (!\is_finite($factorial)) {
                return null;
            }
        }
        $coefficient = ($order % 2) === 0 ? -$factorial : $factorial;
        $power = $order + 1;

        try {
            $firstTail = SpecialFunctions::polygamma($order, $shiftedLower);
            $secondTail = SpecialFunctions::polygamma($order, $shiftedUpper);
            $tailRange = ($order % 2) === 0
                ? $this->widenInterval($firstTail, $secondTail)
                : $this->widenInterval($secondTail, $firstTail);
            if ($tailRange === null) {
                return null;
            }
            [$lowerBound, $upperBound] = $tailRange;
            for ($index = 0; $index < $shift; ++$index) {
                $firstDenominator = $lower + $index;
                $lastDenominator = $upper + $index;
                if ($firstDenominator >= 0.0 || $lastDenominator >= 0.0) {
                    return null;
                }
                $firstPower = $firstDenominator ** $power;
                $lastPower = $lastDenominator ** $power;
                if ($firstPower === 0.0 || $lastPower === 0.0) {
                    return null;
                }
                $termRange = $this->widenArithmeticInterval(
                    $coefficient / $firstPower,
                    $coefficient / $lastPower,
                );
                if ($termRange === null) {
                    return null;
                }
                $sum = $this->addIntervalRanges([$lowerBound, $upperBound], $termRange);
                $widenedSum = $sum === null
                    ? null
                    : $this->widenArithmeticInterval($sum[0], $sum[1]);
                if ($widenedSum === null) {
                    return null;
                }
                [$lowerBound, $upperBound] = $widenedSum;
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($lowerBound, $upperBound);
    }

    /**
     * @return array{float, float}|null
     */
    private function positiveLogGammaIntervalRange(
        float $lower,
        float $upper,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if ($upper <= 171.0) {
            $gammaRange = $this->gammaIntervalRange([$lower, $upper], $evaluationOptions);
            if ($gammaRange === null || $gammaRange[0] <= 0.0) {
                return null;
            }

            return $this->widenInterval(\log($gammaRange[0]), \log($gammaRange[1]));
        }

        $lgamma = $evaluationOptions->functions->find('lgamma');
        if ($lgamma === null) {
            return null;
        }

        try {
            $lowerValue = (float) $lgamma->invoke([$lower]);
            $upperValue = (float) $lgamma->invoke([$upper]);
            $minimum = $lower <= 1.4616321449683623 && $upper >= 1.4616321449683623
                ? (float) $lgamma->invoke([1.4616321449683623])
                : \min($lowerValue, $upperValue);
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($minimum, \max($lowerValue, $upperValue));
    }

    /** @return array{float, float}|null */
    private function logGammaIntervalRange(
        float $lower,
        float $upper,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if ($lower > 0.0) {
            return $this->positiveLogGammaIntervalRange($lower, $upper, $evaluationOptions);
        }

        $gammaRange = $this->gammaIntervalRange([$lower, $upper], $evaluationOptions);
        if ($gammaRange === null || ($gammaRange[0] <= 0.0 && $gammaRange[1] >= 0.0)) {
            return null;
        }
        $minimumMagnitude = $gammaRange[0] > 0.0
            ? $gammaRange[0]
            : \abs($gammaRange[1]);
        $maximumMagnitude = \max(\abs($gammaRange[0]), \abs($gammaRange[1]));
        if ($minimumMagnitude <= 0.0 || !\is_finite($maximumMagnitude)) {
            return null;
        }

        return $this->widenInterval(\log($minimumMagnitude), \log($maximumMagnitude));
    }

    /**
     * @param array{float, float} $y
     * @param array{float, float} $x
     * @return array{float, float}|null
     */
    private function arctangentTwoIntervalRange(array $y, array $x): ?array
    {
        if ($x[0] < 0.0 && $y[0] <= 0.0 && $y[1] >= 0.0) {
            return $this->widenInterval(-\M_PI, \M_PI);
        }

        $angles = [];
        foreach ([$y[0], $y[1]] as $vertical) {
            foreach ([$x[0], $x[1]] as $horizontal) {
                if ($vertical == 0.0 && $horizontal == 0.0) {
                    continue;
                }
                $angles[] = \atan2($vertical, $horizontal);
            }
        }
        if ($angles === []) {
            return null;
        }
        if (\count($angles) === 1) {
            return $this->widenInterval($angles[0], $angles[0]);
        }

        return $this->widenInterval(\min(...$angles), \max(...$angles));
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function regularizedGammaIntervalRange(string $name, array $arguments): ?array
    {
        [$shapeLower, $shapeUpper] = $arguments[0];
        [$lower, $upper] = $arguments[1];
        if ($shapeLower <= 0.0 || $upper < 0.0) {
            return null;
        }
        $lower = \max(0.0, $lower);
        try {
            if ($name === 'gammainc') {
                $range = [
                    SpecialFunctions::regularizedGammaP($shapeUpper, $lower),
                    SpecialFunctions::regularizedGammaP($shapeLower, $upper),
                ];
            } else {
                $range = [
                    SpecialFunctions::regularizedGammaQ($shapeLower, $upper),
                    SpecialFunctions::regularizedGammaQ($shapeUpper, $lower),
                ];
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($range[0], $range[1]);
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function regularizedBetaIntervalRange(string $name, array $arguments): ?array
    {
        [$firstShapeLower, $firstShapeUpper] = $arguments[0];
        [$secondShapeLower, $secondShapeUpper] = $arguments[1];
        [$lower, $upper] = $arguments[2];
        if (
            $firstShapeLower <= 0.0
            || $secondShapeLower <= 0.0
            || $upper < 0.0
            || $lower > 1.0
        ) {
            return null;
        }
        $lower = \max(0.0, $lower);
        $upper = \min(1.0, $upper);
        try {
            if ($name === 'betainc') {
                $range = [
                    SpecialFunctions::regularizedBeta($firstShapeUpper, $secondShapeLower, $lower),
                    SpecialFunctions::regularizedBeta($firstShapeLower, $secondShapeUpper, $upper),
                ];
            } else {
                $range = [
                    SpecialFunctions::regularizedBetaComplement(
                        $firstShapeLower,
                        $secondShapeUpper,
                        $upper,
                    ),
                    SpecialFunctions::regularizedBetaComplement(
                        $firstShapeUpper,
                        $secondShapeLower,
                        $lower,
                    ),
                ];
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($range[0], $range[1]);
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function inverseRegularizedGammaIntervalRange(string $name, array $arguments): ?array
    {
        [$shapeLower, $shapeUpper] = $arguments[0];
        [$lower, $upper] = $arguments[1];
        if (
            $shapeLower <= 0.0
            || $upper < 0.0
            || $lower > 1.0
        ) {
            return null;
        }
        $lower = \max(0.0, $lower);
        $upper = \min(1.0, $upper);
        if (($name === 'gammaincinv' && $upper >= 1.0) || ($name === 'gammainccinv' && $lower <= 0.0)) {
            return null;
        }
        try {
            if ($name === 'gammaincinv') {
                $range = [
                    SpecialFunctions::inverseRegularizedGammaP($shapeLower, $lower),
                    SpecialFunctions::inverseRegularizedGammaP($shapeUpper, $upper),
                ];
            } else {
                $range = [
                    SpecialFunctions::inverseRegularizedGammaQ($shapeLower, $upper),
                    SpecialFunctions::inverseRegularizedGammaQ($shapeUpper, $lower),
                ];
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($range[0], $range[1]);
    }

    /**
     * @param list<array{float, float}> $arguments
     * @return array{float, float}|null
     */
    private function inverseRegularizedBetaIntervalRange(string $name, array $arguments): ?array
    {
        [$firstShapeLower, $firstShapeUpper] = $arguments[0];
        [$secondShapeLower, $secondShapeUpper] = $arguments[1];
        [$lower, $upper] = $arguments[2];
        if (
            $firstShapeLower <= 0.0
            || $secondShapeLower <= 0.0
            || $upper < 0.0
            || $lower > 1.0
        ) {
            return null;
        }
        $lower = \max(0.0, $lower);
        $upper = \min(1.0, $upper);
        try {
            if ($name === 'betaincinv') {
                $range = [
                    SpecialFunctions::inverseRegularizedBeta($firstShapeLower, $secondShapeUpper, $lower),
                    SpecialFunctions::inverseRegularizedBeta($firstShapeUpper, $secondShapeLower, $upper),
                ];
            } else {
                $range = [
                    SpecialFunctions::inverseRegularizedBetaComplement(
                        $firstShapeLower,
                        $secondShapeUpper,
                        $upper,
                    ),
                    SpecialFunctions::inverseRegularizedBetaComplement(
                        $firstShapeUpper,
                        $secondShapeLower,
                        $lower,
                    ),
                ];
            }
        } catch (\DomainException | \OverflowException) {
            return null;
        }

        return $this->widenInterval($range[0], $range[1]);
    }

    /** @return array{float, float}|null */
    private function inverseReciprocalTrigIntervalRange(string $name, float $lower, float $upper): ?array
    {
        $function = $name === 'asec'
            ? static fn (float $value): float => \acos(1.0 / $value)
            : static fn (float $value): float => \asin(1.0 / $value);
        $values = [];
        foreach ([[$lower, \min($upper, -1.0)], [\max($lower, 1.0), $upper]] as [$branchLower, $branchUpper]) {
            if ($branchLower > $branchUpper) {
                continue;
            }
            $values[] = $function($branchLower);
            $values[] = $function($branchUpper);
        }
        if ($values === []) {
            return null;
        }

        return $this->widenInterval(\min(...$values), \max(...$values));
    }

    /** @return array{float, float}|null */
    private function inverseReciprocalHyperbolicIntervalRange(
        string $name,
        float $lower,
        float $upper,
    ): ?array {
        if ($name === 'asech') {
            if ($lower <= 0.0 || $lower > 1.0) {
                return null;
            }
            $upper = \min($upper, 1.0);
            if ($lower > $upper) {
                return null;
            }
            $at = static fn (float $value): float =>
                \log1p(\sqrt(1.0 - ($value * $value))) - \log($value);

            return $this->widenInterval($at($upper), $at($lower));
        }

        if ($name === 'acsch') {
            if ($lower <= 0.0 && $upper >= 0.0) {
                return null;
            }
            $at = static fn (float $value): float => \asinh(1.0 / $value);

            return $this->widenInterval($at($upper), $at($lower));
        }

        if ($lower > 1.0 || $upper < -1.0) {
            $at = static fn (float $value): float => 0.5
                * (\log1p(1.0 / $value) - \log1p(-1.0 / $value));

            return $this->widenInterval($at($upper), $at($lower));
        }

        return null;
    }

    /**
     * @param array{float, float} $base
     * @return array{float, float}|null
     */
    private function integerRootIntervalRange(array $base, float $degree): ?array
    {
        $order = \abs($degree);
        $odd = \fmod($order, 2.0) === 1.0;
        if ($degree > 0.0) {
            if (!$odd && $base[1] < 0.0) {
                return null;
            }
            $lower = $odd ? $base[0] : \max(0.0, $base[0]);
            $upper = $base[1];
            $at = static function (float $value) use ($order, $odd): float {
                if ($value < 0.0 && $odd) {
                    return -\pow(-$value, 1.0 / $order);
                }

                return \pow($value, 1.0 / $order);
            };

            return $this->widenInterval($at($lower), $at($upper));
        }

        if (
            ($base[0] <= 0.0 && $base[1] >= 0.0)
            || (!$odd && $base[0] <= 0.0)
        ) {
            return null;
        }
        $at = static function (float $value) use ($order, $odd): float {
            $root = $value < 0.0 && $odd
                ? -\pow(-$value, 1.0 / $order)
                : \pow($value, 1.0 / $order);

            return 1.0 / $root;
        };

        return $this->widenInterval($at($base[1]), $at($base[0]));
    }

    /**
     * @param array{float, float} $base
     * @param array{float, float} $degreeRange
     * @return array{float, float}|null
     */
    private function variableDegreeRootIntervalRange(array $base, array $degreeRange): ?array
    {
        $maximumExactInteger = 9_007_199_254_740_991.0;
        $degreeTolerance = \min(
            1.0E-9,
            16.0 * \PHP_FLOAT_EPSILON * \max(
                1.0,
                \abs($degreeRange[0]),
                \abs($degreeRange[1]),
            ),
        );
        $firstDegree = \max(-$maximumExactInteger, \ceil($degreeRange[0] - $degreeTolerance));
        $lastDegree = \min($maximumExactInteger, \floor($degreeRange[1] + $degreeTolerance));
        if ($firstDegree > $lastDegree) {
            return null;
        }
        if ($lastDegree - $firstDegree + 1.0 > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
            return null;
        }

        $minimum = null;
        $maximum = null;
        for ($degree = $firstDegree; $degree <= $lastDegree; ++$degree) {
            if ($degree == 0.0) {
                continue;
            }
            $order = \abs($degree);
            $odd = \fmod($order, 2.0) === 1.0;
            if ($degree < 0.0) {
                if (!$odd && $base[1] <= 0.0) {
                    continue;
                }
                if (
                    ($base[0] <= 0.0 && $base[1] >= 0.0)
                    || (!$odd && $base[0] <= 0.0)
                ) {
                    return null;
                }
            } elseif (!$odd && $base[1] < 0.0) {
                continue;
            }

            $range = $this->integerRootIntervalRange($base, $degree);
            if ($range === null) {
                return null;
            }
            $minimum = $minimum === null ? $range[0] : \min($minimum, $range[0]);
            $maximum = $maximum === null ? $range[1] : \max($maximum, $range[1]);
        }

        return $minimum === null || $maximum === null
            ? null
            : $this->widenInterval($minimum, $maximum);
    }

    private static function realCubeRoot(float $value): float
    {
        return $value < 0.0 ? -(\abs($value) ** (1.0 / 3.0)) : ($value ** (1.0 / 3.0));
    }

    /** @return array{float, float}|null */
    private function trigonometricIntervalRange(float $lower, float $upper, bool $cosine): ?array
    {
        if (
            !\is_finite($upper - $lower)
            || $upper - $lower >= 2.0 * \M_PI
            || \max(\abs($lower), \abs($upper)) > 1.0E15
        ) {
            return [-1.0, 1.0];
        }
        $function = $cosine ? \cos(...) : \sin(...);
        $minimum = \min($function($lower), $function($upper));
        $maximum = \max($function($lower), $function($upper));
        $maximumPhase = $cosine ? 0.0 : \M_PI_2;
        $minimumPhase = $cosine ? \M_PI : -\M_PI_2;
        if ($this->intervalContainsPeriodicPhase($lower, $upper, $maximumPhase, 2.0 * \M_PI)) {
            $maximum = 1.0;
        }
        if ($this->intervalContainsPeriodicPhase($lower, $upper, $minimumPhase, 2.0 * \M_PI)) {
            $minimum = -1.0;
        }

        return $this->widenInterval($minimum, $maximum);
    }

    /** @return array{float, float}|null */
    private function sincIntervalRange(float $lower, float $upper, float $phaseScale): ?array
    {
        $phaseRange = $this->widenArithmeticInterval($lower * $phaseScale, $upper * $phaseScale);
        if ($phaseRange === null) {
            return null;
        }
        [$phaseLower, $phaseUpper] = $phaseRange;
        if ($phaseLower === 0.0 && $phaseUpper === 0.0) {
            return [1.0, 1.0];
        }

        if ($phaseLower <= 0.0 && $phaseUpper >= 0.0) {
            $maximumAbsolutePhase = \max(\abs($phaseLower), \abs($phaseUpper));
            if ($maximumAbsolutePhase <= \M_PI) {
                $minimum = $maximumAbsolutePhase === 0.0
                    ? 1.0
                    : \sin($maximumAbsolutePhase) / $maximumAbsolutePhase;
                $widened = $this->widenInterval($minimum, 1.0);

                return $widened === null
                    ? null
                    : [\max(self::SINC_GLOBAL_LOWER_BOUND, $widened[0]), 1.0];
            }

            return [self::SINC_GLOBAL_LOWER_BOUND, 1.0];
        }

        $sineRange = $this->trigonometricIntervalRange($phaseLower, $phaseUpper, false);
        $quotient = $sineRange === null
            ? null
            : $this->divideIntervals($sineRange, $phaseRange);
        if ($quotient === null) {
            return null;
        }
        $widened = [
            \max(self::SINC_GLOBAL_LOWER_BOUND, $quotient[0]),
            \min(1.0, $quotient[1]),
        ];

        return $widened[0] <= $widened[1] ? $widened : null;
    }

    /** @return array{float, float}|null */
    private function tangentIntervalRange(float $lower, float $upper): ?array
    {
        if (\max(\abs($lower), \abs($upper)) > 1.0E15) {
            return null;
        }
        if ($this->intervalContainsPeriodicPhase($lower, $upper, \M_PI_2, \M_PI)) {
            return null;
        }
        $first = \tan($lower);
        $second = \tan($upper);
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }

        return $this->widenInterval(\min($first, $second), \max($first, $second));
    }

    private function intervalContainsPeriodicPhase(
        float $lower,
        float $upper,
        float $phase,
        float $period,
    ): bool {
        $firstPosition = ($lower - $phase) / $period;
        $lastPosition = ($upper - $phase) / $period;
        $positionError = 8.0 * \PHP_FLOAT_EPSILON * \max(
            1.0,
            \abs($lower) / $period,
            \abs($upper) / $period,
            \abs($firstPosition),
            \abs($lastPosition),
        );
        $firstIndex = \ceil($firstPosition - $positionError);
        $lastIndex = \floor($lastPosition + $positionError);

        return $firstIndex <= $lastIndex;
    }

    /** @return array{float, float}|null */
    private function hyperbolicCosineIntervalRange(float $lower, float $upper): ?array
    {
        $first = \cosh($lower);
        $second = \cosh($upper);
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }
        $minimum = $lower <= 0.0 && $upper >= 0.0 ? 1.0 : \min($first, $second);

        return $this->widenInterval($minimum, \max($first, $second));
    }

    /** @return array{float, float}|null */
    private function hyperbolicSecantIntervalRange(float $lower, float $upper): ?array
    {
        $first = 1.0 / \cosh($lower);
        $second = 1.0 / \cosh($upper);
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }
        $maximum = $lower <= 0.0 && $upper >= 0.0 ? 1.0 : \max($first, $second);

        return $this->widenInterval(\min($first, $second), $maximum);
    }

    /** @return array{float, float}|null */
    private function reciprocalHyperbolicIntervalRange(float $lower, float $upper, bool $cotangent): ?array
    {
        if ($lower <= 0.0 && $upper >= 0.0) {
            return null;
        }
        $function = $cotangent ? \tanh(...) : \sinh(...);
        $firstDenominator = $function($lower);
        $secondDenominator = $function($upper);
        if ($firstDenominator === 0.0 || $secondDenominator === 0.0) {
            return null;
        }
        $first = 1.0 / $firstDenominator;
        $second = 1.0 / $secondDenominator;
        if (!\is_finite($first) || !\is_finite($second)) {
            return null;
        }

        return $this->widenInterval(\min($first, $second), \max($first, $second));
    }

    /**
     * @param array{float, float} $left
     * @param array{float, float} $right
     * @return array{float, float}|null
     */
    private function multiplyIntervals(array $left, array $right, bool $tight = false): ?array
    {
        $products = [
            $left[0] * $right[0],
            $left[0] * $right[1],
            $left[1] * $right[0],
            $left[1] * $right[1],
        ];
        if (\count(\array_filter($products, static fn (float $value): bool => !\is_finite($value))) > 0) {
            return null;
        }

        return $tight
            ? $this->widenArithmeticInterval(\min(...$products), \max(...$products))
            : $this->widenInterval(\min(...$products), \max(...$products));
    }

    /** @param array{float, float} $range
     *  @return array{float, float}|null
     */
    private function squareInterval(array $range): ?array
    {
        $lowerSquare = $range[0] * $range[0];
        $upperSquare = $range[1] * $range[1];
        if (!\is_finite($lowerSquare) || !\is_finite($upperSquare)) {
            return null;
        }
        $crossesZero = $range[0] <= 0.0 && $range[1] >= 0.0;
        $minimum = $crossesZero ? 0.0 : \min($lowerSquare, $upperSquare);
        $maximum = \max($lowerSquare, $upperSquare);
        $widened = $this->widenArithmeticInterval($minimum, $maximum);
        if ($widened === null) {
            return null;
        }

        return $crossesZero ? [0.0, $widened[1]] : $widened;
    }

    /** @param array{float, float} $range
     *  @return array{float, float}|null
     */
    private function negativeSquareInterval(array $range): ?array
    {
        $square = $this->squareInterval($range);

        return $square === null ? null : [-$square[1], -$square[0]];
    }

    private function isNegationOf(Node $maybeNegated, Node $expression): bool
    {
        $maybeNegated = $this->unwrapGrouping($maybeNegated);

        return $maybeNegated instanceof UnaryOperationNode
            && $maybeNegated->operator === UnaryOperator::Minus
            && $this->sameExpression($maybeNegated->operand, $expression);
    }

    /**
     * @param array{float, float} $numerator
     * @param array{float, float} $denominator
     * @return array{float, float}|null
     */
    private function divideIntervals(array $numerator, array $denominator): ?array
    {
        if ($denominator[0] <= 0.0 && $denominator[1] >= 0.0) {
            return null;
        }
        $reciprocal = [1.0 / $denominator[1], 1.0 / $denominator[0]];
        if (!\is_finite($reciprocal[0]) || !\is_finite($reciprocal[1])) {
            return null;
        }

        return $this->multiplyIntervals($numerator, $reciprocal);
    }

    /**
     * @param array{float, float} $dividend
     * @param array{float, float} $divisor
     * @return array{float, float}|null
     */
    private function moduloInterval(array $dividend, array $divisor): ?array
    {
        $maximumDivisorMagnitude = \max(\abs($divisor[0]), \abs($divisor[1]));
        $maximumIntegerDivisor = \floor($maximumDivisorMagnitude);
        if ($maximumIntegerDivisor < 1.0) {
            return null;
        }

        // PHP modulo accepts only integer operands, and a remainder's magnitude
        // is bounded by both the dividend and divisor magnitudes.
        $maximumDividendMagnitude = \floor(\max(\abs($dividend[0]), \abs($dividend[1])));
        $maximumRemainder = \min($maximumDividendMagnitude, $maximumIntegerDivisor - 1.0);
        if ($dividend[0] >= 0.0) {
            return $this->widenInterval(0.0, $maximumRemainder);
        }
        if ($dividend[1] <= 0.0) {
            return $this->widenInterval(-$maximumRemainder, 0.0);
        }

        return $this->widenInterval(-$maximumRemainder, $maximumRemainder);
    }

    /**
     * @param array{float, float} $base
     * @param array{float, float} $exponent
     * @param array{bool, bool}|null $rationalExponentParity
     * @return array{float, float}|null
     */
    private function powerInterval(
        array $base,
        array $exponent,
        ?array $rationalExponentParity = null,
    ): ?array {
        if (
            $rationalExponentParity !== null
            && !$rationalExponentParity[1]
            && $base[0] < 0.0
        ) {
            return null;
        }
        if (
            $rationalExponentParity !== null
            && $exponent[0] === $exponent[1]
            && $rationalExponentParity[1]
            && ($base[0] < 0.0 || $base[1] < 0.0)
        ) {
            $numeratorIsOdd = $rationalExponentParity[0];
            $power = $exponent[0];
            if ($power < 0.0 && $base[0] <= 0.0 && $base[1] >= 0.0) {
                return null;
            }
            $evaluate = static function (float $value) use ($numeratorIsOdd, $power): float {
                $result = \abs($value) ** $power;

                return $value < 0.0 && $numeratorIsOdd ? -$result : $result;
            };
            $lower = $evaluate($base[0]);
            $upper = $evaluate($base[1]);
            if (!\is_finite($lower) || !\is_finite($upper)) {
                return null;
            }
            $minimum = \min($lower, $upper);
            $maximum = \max($lower, $upper);
            if ($power > 0.0 && !$numeratorIsOdd && $base[0] <= 0.0 && $base[1] >= 0.0) {
                $minimum = 0.0;
            }

            return $this->widenArithmeticInterval($minimum, $maximum);
        }
        // On [0, B], nonnegative powers are maximized at the exponent endpoint nearest 0 if B <= 1.
        if (
            $base[0] === 0.0
            && $exponent[0] >= 0.0
            && (
                $exponent[0] !== $exponent[1]
                || \floor($exponent[0]) !== $exponent[0]
            )
        ) {
            $upper = $base[1] <= 1.0
                ? ($exponent[0] === 0.0 ? 1.0 : $base[1] ** $exponent[0])
                : $base[1] ** $exponent[1];
            if (!\is_finite($upper)) {
                return null;
            }
            $widened = $this->widenArithmeticInterval(0.0, $upper);

            return $widened === null ? null : [0.0, $widened[1]];
        }
        if ($exponent[0] !== $exponent[1] || \floor($exponent[0]) !== $exponent[0]) {
            if ($base[0] <= 0.0) {
                return null;
            }
            $logarithm = $this->widenInterval(\log($base[0]), \log($base[1]));
            if ($logarithm === null) {
                return null;
            }
            $logarithmicRange = $this->multiplyIntervals($exponent, $logarithm);
            if ($logarithmicRange === null) {
                return null;
            }
            $lower = \exp($logarithmicRange[0]);
            $upper = \exp($logarithmicRange[1]);

            return $this->widenInterval(\min($lower, $upper), \max($lower, $upper));
        }
        $degree = $exponent[0];
        if ($degree === 0.0) {
            return [1.0, 1.0];
        }
        if ($degree === 1.0) {
            return $base;
        }
        if ($degree < 0.0) {
            if ($base[0] <= 0.0 && $base[1] >= 0.0) {
                return null;
            }
            $positive = $this->powerInterval($base, [-$degree, -$degree]);

            return $positive === null ? null : $this->divideIntervals([1.0, 1.0], $positive);
        }
        $lower = $base[0] ** $degree;
        $upper = $base[1] ** $degree;
        if (!\is_finite($lower) || !\is_finite($upper)) {
            return null;
        }
        $minimum = \min($lower, $upper);
        $maximum = \max($lower, $upper);
        if ($degree > 0.0 && \fmod($degree, 2.0) === 0.0 && $base[0] <= 0.0 && $base[1] >= 0.0) {
            $minimum = 0.0;
        }

        $widened = $this->widenArithmeticInterval($minimum, $maximum);
        if (
            $widened !== null
            && $degree > 0.0
            && \fmod($degree, 2.0) === 0.0
            && $base[0] <= 0.0
            && $base[1] >= 0.0
        ) {
            return [0.0, $widened[1]];
        }

        return $widened;
    }

    /** @return array{float, float}|null */
    private function widenInterval(float $lower, float $upper): ?array
    {
        if (!\is_finite($lower) || !\is_finite($upper) || $lower > $upper) {
            return null;
        }
        $margin = 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($lower), \abs($upper));
        $widenedLower = $lower - $margin;
        $widenedUpper = $upper + $margin;
        if (!\is_finite($widenedLower) || !\is_finite($widenedUpper)) {
            return null;
        }

        return [$widenedLower, $widenedUpper];
    }

    /** @return array{float, float}|null */
    private function widenArithmeticInterval(float $lower, float $upper): ?array
    {
        if (!\is_finite($lower) || !\is_finite($upper) || $lower > $upper) {
            return null;
        }
        $widenedLower = $lower;
        $widenedUpper = $upper;
        for ($step = 0; $step < 16; ++$step) {
            $widenedLower = $this->adjacentFloat($widenedLower, -1);
            $widenedUpper = $this->adjacentFloat($widenedUpper, 1);
            if ($widenedLower === null || $widenedUpper === null) {
                return null;
            }
        }

        return [$widenedLower, $widenedUpper];
    }

    /**
     * Add integer exponent levels as candidates for variable powers.
     *
     * @param array<string, int|float> $parameters
     * @param list<array{Node, string, int}> $sides
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<float>
     */
    private function integerExponentPowerCandidates(
        array $sides,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): array {
        $candidates = [];
        $pending = $sides;
        $polynomialSolver = new PolynomialSolver();
        while ($pending !== []) {
            [$node, $source, $sourceOffset] = \array_pop($pending);
            if ($node instanceof BinaryOperationNode) {
                $pending[] = [$node->left, $source, $sourceOffset];
                $pending[] = [$node->right, $source, $sourceOffset];
                if (
                    $node->operator !== BinaryOperator::Power
                    || !$this->containsVariable($node->right, $variable)
                    || !$this->containsVariable($node->left, $variable)
                ) {
                    continue;
                }

                $exponent = $extractor->extract($node->right);
                if ($exponent !== null && \count($exponent) <= 1) {
                    continue;
                }
                $exponentSource = '';
                if ($exponent !== null) {
                    $exponentRange = $this->polynomialRange(
                        $exponent,
                        $lowerBound,
                        $upperBound,
                        $solverOptions,
                    );
                    if ($exponentRange === null) {
                        continue;
                    }
                    $minimumInteger = (int) \max(
                        \ceil($exponentRange[0]),
                        -9_007_199_254_740_991.0,
                    );
                    $maximumInteger = (int) \min(
                        \floor($exponentRange[1]),
                        9_007_199_254_740_991.0,
                    );
                } else {
                    $base = $extractor->extract($node->left);
                    $baseRange = $base === null
                        ? $this->sampledExpressionRange(
                            $node->left,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            \max(32, $solverOptions->scanSteps),
                        )
                        : $this->polynomialRange(
                            $base,
                            $lowerBound,
                            $upperBound,
                            $solverOptions,
                        );
                    if ($baseRange !== null && $baseRange[0] >= 0.0) {
                        continue;
                    }
                    $exponentRange = $this->boundedExpressionRange(
                        $node->right,
                        $extractor,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $evaluationOptions,
                        $solverOptions,
                    ) ?? $this->sampledExpressionRange(
                        $node->right,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        \max(32, $solverOptions->scanSteps),
                    );
                    if ($exponentRange === null) {
                        continue;
                    }
                    $minimumInteger = (int) \max(
                        \ceil($exponentRange[0]),
                        -9_007_199_254_740_991.0,
                    );
                    $maximumInteger = (int) \min(
                        \floor($exponentRange[1]),
                        9_007_199_254_740_991.0,
                    );
                    $span = $node->right->span();
                    $exponentSource = \substr(
                        $source,
                        $span->start - $sourceOffset,
                        $span->end - $span->start,
                    );
                    if ($exponentSource === '') {
                        continue;
                    }
                }
                if ($minimumInteger > $maximumInteger) {
                    continue;
                }
                if ($maximumInteger - $minimumInteger + 1 > self::MAX_ADAPTIVE_SCAN_STEPS) {
                    throw new RootSearchLimitException(
                        'A variable power crosses too many integer exponent levels to isolate within the configured limit.',
                    );
                }
                for ($integer = (int) $minimumInteger; $integer <= (int) $maximumInteger; ++$integer) {
                    if ($exponent !== null) {
                        $level = $exponent;
                        $level[0] -= $integer;
                        $roots = $polynomialSolver->solve(
                            $level,
                            $lowerBound,
                            $upperBound,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                                $level,
                                $value,
                            ),
                            $solverOptions,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $level,
                                $value,
                            ),
                        );
                    } else {
                        $roundingCombination = $this->roundingSelfCombination(
                            $node->right,
                            $source,
                            $sourceOffset,
                            $extractor,
                        );
                        if ($roundingCombination !== null) {
                            $roots = $this->solveRoundingExponentLevel(
                                $node->right,
                                $roundingCombination,
                                $integer,
                                $extractor,
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $solverOptions,
                            );
                            try {
                                $genericRoots = $this->solve(
                                    '(' . $exponentSource . ')=' . (string) $integer,
                                    $variable,
                                    $lowerBound,
                                    $upperBound,
                                    $parameters,
                                    $evaluationOptions,
                                    $solverOptions,
                                );
                                $roots = [...($roots ?? []), ...$genericRoots];
                            } catch (\DomainException | \InvalidArgumentException) {
                                // Keep the independently isolated rounding boundaries.
                            }
                        } else {
                            $factorialForm = $this->factorialExponentLinearForm(
                                $node->right,
                                $extractor,
                                $variable,
                            );
                            if (
                                $factorialForm !== null
                                && $factorialForm['coefficient'] !== 0.0
                                && \is_finite($factorialForm['coefficient'])
                                && \is_finite($factorialForm['offset'])
                            ) {
                                $factorialLevel = ($integer - $factorialForm['offset'])
                                    / $factorialForm['coefficient'];
                                $roots = \is_finite($factorialLevel)
                                    ? $this->solveFactorialExponentLevel(
                                        $factorialForm['node'],
                                        $source,
                                        $sourceOffset,
                                        $factorialLevel,
                                        $variable,
                                        $lowerBound,
                                        $upperBound,
                                        $parameters,
                                        $evaluationOptions,
                                        $solverOptions,
                                    )
                                    : null;
                            } else {
                                try {
                                    $roots = $this->solve(
                                        '(' . $exponentSource . ')=' . (string) $integer,
                                        $variable,
                                        $lowerBound,
                                        $upperBound,
                                        $parameters,
                                        $evaluationOptions,
                                        $solverOptions,
                                    );
                                } catch (\DomainException | \InvalidArgumentException) {
                                    $roots = null;
                                }
                            }
                        }
                    }
                    if ($roots === null) {
                        if ($exponent !== null) {
                            throw new RootSearchLimitException(
                                'Could not isolate every integer exponent level within the configured root-search limits.',
                            );
                        }
                        continue;
                    }
                    foreach ($roots as $root) {
                        $candidateValue = $exponent === null
                            ? $this->refineIntegerExponentLevelRoot(
                                $node->right,
                                $integer,
                                $root->value,
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $solverOptions,
                            )
                            : $root->value;
                        $residual = $residualAt($candidateValue);
                        if (
                            $exponent === null
                            && $residual !== null
                            && $residual !== 0.0
                        ) {
                            $candidateValue = $this->refineVerifiedEquationCandidate(
                                $candidateValue,
                                $residual,
                                $residualAt,
                                $candidateValue,
                                $lowerBound,
                                $upperBound,
                                $solverOptions,
                            );
                            $residual = $residualAt($candidateValue);
                        }
                        if (
                            $residual !== null
                            && $this->isResidualAcceptableAt(
                                $candidateValue,
                                $residual,
                                $candidateScaleAt,
                                $solverOptions,
                            )
                        ) {
                            $candidates[] = $candidateValue;
                        }
                    }
                }
                continue;
            }
            if ($node instanceof UnaryOperationNode) {
                $pending[] = [$node->operand, $source, $sourceOffset];
            } elseif ($node instanceof GroupingNode) {
                $pending[] = [$node->expression, $source, $sourceOffset];
            } elseif ($node instanceof FactorialNode) {
                $pending[] = [$node->operand, $source, $sourceOffset];
            } elseif ($node instanceof FunctionCallNode) {
                foreach ($node->arguments as $argument) {
                    $pending[] = [$argument, $source, $sourceOffset];
                }
            }
        }

        return \array_values(\array_unique($candidates, SORT_REGULAR));
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveFactorialExponentLevel(
        FactorialNode $factorial,
        string $source,
        int $sourceOffset,
        float $factorialLevel,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $span = $factorial->operand->span();
        $operandSource = \substr(
            $source,
            $span->start - $sourceOffset,
            $span->end - $span->start,
        );
        if ($operandSource === '') {
            return null;
        }

        $roots = [];
        $factorialValue = 1;
        for ($operand = 0; $operand <= $evaluationOptions->limits->maxFactorial; ++$operand) {
            if ($operand > 1) {
                $factorialValue *= $operand;
            }
            $levelTolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($factorialLevel));
            if (\abs($factorialValue - $factorialLevel) <= $levelTolerance) {
                try {
                    $roots = [
                        ...$roots,
                        ...$this->solve(
                            '(' . $operandSource . ')=' . (string) $operand,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $solverOptions,
                        ),
                    ];
                } catch (\DomainException | \InvalidArgumentException) {
                    continue;
                }
            }
            if ($factorialValue > $factorialLevel + $levelTolerance && $operand > 1) {
                break;
            }
        }

        return $roots;
    }

    /**
     * @param array{argument: Node, source: string} $combination
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveRoundingExponentLevel(
        Node $exponent,
        array $combination,
        int $integerLevel,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $argumentRange = $this->boundedExpressionRange(
            $combination['argument'],
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
        ) ?? $this->sampledExpressionRange(
            $combination['argument'],
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            \max(32, $solverOptions->scanSteps),
        );
        if ($argumentRange === null) {
            if ($node->name === 'sin' || $node->name === 'cos') {
                return [-1.0, 1.0];
            }

            return null;
        }
        $scale = \max(1.0, \abs($argumentRange[0]), \abs($argumentRange[1]));
        $tolerance = 8.0 * \PHP_FLOAT_EPSILON * $scale;
        $minimumLevel = \ceil($argumentRange[0] - $tolerance);
        $maximumLevel = \floor($argumentRange[1] + $tolerance);
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if ($minimumLevel < -$maximumExactInteger || $maximumLevel > $maximumExactInteger) {
            return null;
        }
        if ($minimumLevel > $maximumLevel) {
            return [];
        }
        if ($maximumLevel - $minimumLevel + 1.0 > self::MAX_ADAPTIVE_SCAN_STEPS) {
            return null;
        }

        $roots = [];
        for ($level = (int) $minimumLevel; $level <= (int) $maximumLevel; ++$level) {
            try {
                $levelRoots = $this->solve(
                    '(' . $combination['source'] . ')=' . (string) $level,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (InfiniteSolutionSetException) {
                return null;
            } catch (\DomainException | \InvalidArgumentException) {
                continue;
            }
            foreach ($levelRoots as $root) {
                try {
                    $exponentValue = (float) $this->evaluateNode(
                        $exponent,
                        [...$parameters, $variable => $root->value],
                        $evaluationOptions,
                    );
                } catch (EvaluationException) {
                    continue;
                }
                $levelResidual = $exponentValue - $integerLevel;
                $levelTolerance = 8.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($exponentValue), \abs((float) $integerLevel));
                if (\abs($levelResidual) <= $levelTolerance) {
                    $roots[] = new EquationSolution(
                        $root->value,
                        \abs($levelResidual),
                        $root->iterations,
                    );
                }
            }
        }

        return $roots;
    }

    /**
     * @return array{argument: Node, source: string}|null
     */
    private function roundingSelfCombination(
        Node $node,
        string $source,
        int $sourceOffset,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if (
            !$node instanceof BinaryOperationNode
            || !\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return null;
        }

        $pairs = [[$node->left, $node->right], [$node->right, $node->left]];
        foreach ($pairs as [$functionNode, $otherNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            $otherNode = $this->unwrapGrouping($otherNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || !\in_array($functionNode->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || \count($functionNode->arguments) !== 1
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            $argumentSpan = $argument->span();
            $otherSpan = $otherNode->span();
            $argumentSource = \substr(
                $source,
                $argumentSpan->start - $sourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            $otherSource = \substr(
                $source,
                $otherSpan->start - $sourceOffset,
                $otherSpan->end - $otherSpan->start,
            );
            if (
                $argumentSource !== ''
                && (
                    $argumentSource === $otherSource
                    || $this->isAffinePolynomialMultiple($argument, $otherNode, $extractor)
                )
            ) {
                return ['argument' => $argument, 'source' => $argumentSource];
            }
        }

        return null;
    }

    private function isAffinePolynomialMultiple(
        Node $argument,
        Node $other,
        PolynomialExtractor $extractor,
    ): bool {
        try {
            $argumentPolynomial = $extractor->extract($argument);
            $otherPolynomial = $extractor->extract($other);
        } catch (EvaluationException) {
            return false;
        }
        if (
            $argumentPolynomial === null
            || $otherPolynomial === null
            || \count($argumentPolynomial) < 2
        ) {
            return false;
        }

        $degree = \count($argumentPolynomial) - 1;
        $coefficient = $otherPolynomial[$degree] ?? 0.0;
        if ($argumentPolynomial[$degree] === 0.0) {
            return false;
        }
        $coefficient /= $argumentPolynomial[$degree];
        if (!\is_finite($coefficient)) {
            return false;
        }
        $maximumDegree = \max($degree, \count($otherPolynomial) - 1);
        for ($index = 1; $index <= $maximumDegree; ++$index) {
            $expected = $coefficient * ($argumentPolynomial[$index] ?? 0.0);
            $actual = $otherPolynomial[$index] ?? 0.0;
            $tolerance = 16.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($expected), \abs($actual));
            if (\abs($actual - $expected) > $tolerance) {
                return false;
            }
        }

        return true;
    }

    /**
     * @return array{node: FactorialNode, coefficient: float, offset: float}|null
     */
    private function factorialExponentLinearForm(
        Node $node,
        PolynomialExtractor $extractor,
        string $variable,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FactorialNode) {
            return $this->containsVariable($node->operand, $variable)
                ? ['node' => $node, 'coefficient' => 1.0, 'offset' => 0.0]
                : null;
        }
        if ($node instanceof UnaryOperationNode) {
            $form = $this->factorialExponentLinearForm($node->operand, $extractor, $variable);
            if ($form === null || $node->operator === UnaryOperator::Plus) {
                return $form;
            }

            return [
                'node' => $form['node'],
                'coefficient' => -$form['coefficient'],
                'offset' => -$form['offset'],
            ];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $leftForm = $this->factorialExponentLinearForm($node->left, $extractor, $variable);
        $rightForm = $this->factorialExponentLinearForm($node->right, $extractor, $variable);
        if ($leftForm !== null && $rightForm !== null) {
            return null;
        }
        $leftConstant = $leftForm === null ? $this->constantPolynomialValue($node->left, $extractor) : null;
        $rightConstant = $rightForm === null ? $this->constantPolynomialValue($node->right, $extractor) : null;
        if ($leftForm !== null && $rightConstant !== null) {
            return match ($node->operator) {
                BinaryOperator::Add => [
                    'node' => $leftForm['node'],
                    'coefficient' => $leftForm['coefficient'],
                    'offset' => $leftForm['offset'] + $rightConstant,
                ],
                BinaryOperator::Subtract => [
                    'node' => $leftForm['node'],
                    'coefficient' => $leftForm['coefficient'],
                    'offset' => $leftForm['offset'] - $rightConstant,
                ],
                BinaryOperator::Multiply => [
                    'node' => $leftForm['node'],
                    'coefficient' => $leftForm['coefficient'] * $rightConstant,
                    'offset' => $leftForm['offset'] * $rightConstant,
                ],
                BinaryOperator::Divide => $rightConstant === 0.0
                    ? null
                    : [
                        'node' => $leftForm['node'],
                        'coefficient' => $leftForm['coefficient'] / $rightConstant,
                        'offset' => $leftForm['offset'] / $rightConstant,
                    ],
                default => null,
            };
        }
        if ($leftConstant !== null && $rightForm !== null) {
            return match ($node->operator) {
                BinaryOperator::Add => [
                    'node' => $rightForm['node'],
                    'coefficient' => $rightForm['coefficient'],
                    'offset' => $rightForm['offset'] + $leftConstant,
                ],
                BinaryOperator::Subtract => [
                    'node' => $rightForm['node'],
                    'coefficient' => -$rightForm['coefficient'],
                    'offset' => $leftConstant - $rightForm['offset'],
                ],
                BinaryOperator::Multiply => [
                    'node' => $rightForm['node'],
                    'coefficient' => $rightForm['coefficient'] * $leftConstant,
                    'offset' => $rightForm['offset'] * $leftConstant,
                ],
                default => null,
            };
        }

        return null;
    }

    private function constantPolynomialValue(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?float {
        try {
            $polynomial = $extractor->extract($node);
        } catch (EvaluationException) {
            return null;
        }

        return $polynomial !== null && \count($polynomial) === 1
            ? $polynomial[0]
            : null;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function refineIntegerExponentLevelRoot(
        Node $exponent,
        int $integerLevel,
        float $initialValue,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): float {
        $levelResidualAt = function (float $value) use (
            $exponent,
            $integerLevel,
            $variable,
            $parameters,
            $evaluationOptions,
        ): ?float {
            try {
                return (float) $this->evaluateNode(
                    $exponent,
                    [...$parameters, $variable => $value],
                    $evaluationOptions,
                ) - $integerLevel;
            } catch (EvaluationException) {
                return null;
            }
        };

        $value = $initialValue;
        $differentiator = new NumericalDifferentiator();
        for ($iteration = 0; $iteration < $solverOptions->maxIterations; ++$iteration) {
            $residual = $levelResidualAt($value);
            if ($residual === null || $residual === 0.0) {
                break;
            }
            $derivative = $differentiator->differentiate($levelResidualAt, $value);
            if ($derivative === null || $derivative === 0.0) {
                break;
            }
            $next = $value - ($residual / $derivative);
            if (
                !\is_finite($next)
                || $next < $lowerBound
                || $next > $upperBound
                || $next === $value
            ) {
                break;
            }
            $value = $next;
        }

        return $value;
    }

    /** @param callable(float): ?float $residualAt */
    private function refineVerifiedEquationCandidate(
        float $initialValue,
        float $initialResidual,
        callable $residualAt,
        float $referenceValue,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): float {
        $value = $initialValue;
        $residual = $initialResidual;
        $maximumDistance = 16.0 * \sqrt(\PHP_FLOAT_EPSILON)
            * \max(1.0, \abs($referenceValue));
        $differentiator = new NumericalDifferentiator();
        for ($iteration = 0; $iteration < 32; ++$iteration) {
            $derivative = $differentiator->differentiate($residualAt, $value);
            if ($derivative === null || $derivative === 0.0) {
                break;
            }
            $step = -$residual / $derivative;
            if (!\is_finite($step) || $step === 0.0) {
                break;
            }

            $improved = false;
            for ($backtrack = 0; $backtrack < 24; ++$backtrack) {
                $next = $value + $step;
                if (
                    $next < $lowerBound
                    || $next > $upperBound
                    || \abs($next - $referenceValue) > $maximumDistance
                    || $next === $value
                ) {
                    $step /= 2.0;
                    continue;
                }
                $nextResidual = $residualAt($next);
                if ($nextResidual !== null && \abs($nextResidual) < \abs($residual)) {
                    $value = $next;
                    $residual = $nextResidual;
                    $improved = true;
                    break;
                }
                $step /= 2.0;
            }
            if (!$improved) {
                break;
            }
            if ($residual === 0.0) {
                break;
            }
        }

        return $value;
    }

    /**
     * Estimate a function composition's range when each outer function is
     * monotone over the argument range.
     *
     * @return array{float, float}|null
     */
    private function boundedExpressionRange(
        Node $node,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'acosh'
            && \count($node->arguments) === 1
        ) {
            $inner = $this->unwrapGrouping($node->arguments[0]);
            if (
                $inner instanceof FunctionCallNode
                && $inner->name === 'cosh'
                && \count($inner->arguments) === 1
            ) {
                $argumentRange = $this->boundedExpressionRange(
                    $inner->arguments[0],
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange !== null) {
                    $minimum = $argumentRange[0] <= 0.0 && $argumentRange[1] >= 0.0
                        ? 0.0
                        : \min(\abs($argumentRange[0]), \abs($argumentRange[1]));

                    return [$minimum, \max(\abs($argumentRange[0]), \abs($argumentRange[1]))];
                }
            }
        }
        $polynomial = $extractor->extract($node);
        if ($polynomial !== null) {
            return $this->polynomialRange(
                $polynomial,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
        }

        if (
            $node instanceof FunctionCallNode
            && \count($node->arguments) === 1
            && \in_array($node->name, ['sin', 'cos'], true)
        ) {
            $argumentRange = $this->boundedExpressionRange(
                $node->arguments[0],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($argumentRange === null) {
                return [-1.0, 1.0];
            }
        }
        if ($node instanceof FactorialNode) {
            $operandRange = $this->boundedExpressionRange(
                $node->operand,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if (
                $operandRange === null
                || !\is_finite($operandRange[0])
                || !\is_finite($operandRange[1])
            ) {
                return null;
            }
            $operandScale = \max(1.0, \abs($operandRange[0]), \abs($operandRange[1]));
            $operandTolerance = 8.0 * \PHP_FLOAT_EPSILON * $operandScale;
            $minimumOperandValue = \max(
                0.0,
                \ceil($operandRange[0] - $operandTolerance),
            );
            $maximumOperandValue = \min(
                (float) $evaluationOptions->limits->maxFactorial,
                \floor($operandRange[1] + $operandTolerance),
            );
            if ($minimumOperandValue > $maximumOperandValue) {
                return null;
            }
            $minimumOperand = (int) $minimumOperandValue;
            $maximumOperand = (int) $maximumOperandValue;
            $minimumOutput = 1.0;
            for ($operand = 2; $operand <= $minimumOperand; ++$operand) {
                $minimumOutput *= $operand;
            }
            $maximumOutput = $minimumOutput;
            for ($operand = $minimumOperand + 1; $operand <= $maximumOperand; ++$operand) {
                $nextOutput = $maximumOutput * $operand;
                if ($nextOutput > $evaluationOptions->limits->maxExponentMagnitude) {
                    break;
                }
                $maximumOutput = $nextOutput;
            }
            if ($minimumOutput > $evaluationOptions->limits->maxExponentMagnitude) {
                return null;
            }

            return [$minimumOutput, $maximumOutput];
        }
        if ($node instanceof UnaryOperationNode) {
            $operandRange = $this->boundedExpressionRange(
                $node->operand,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($operandRange === null) {
                return null;
            }
            if ($node->operator === UnaryOperator::Plus) {
                return $operandRange;
            }
            $range = [-$operandRange[1], -$operandRange[0]];

            return !\is_nan($range[0]) && !\is_nan($range[1]) ? $range : null;
        }
        if ($node instanceof BinaryOperationNode) {
            $leftRange = $this->boundedExpressionRange(
                $node->left,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            $rightRange = $this->boundedExpressionRange(
                $node->right,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($leftRange === null || $rightRange === null) {
                return null;
            }
            if ($node->operator === BinaryOperator::Add) {
                return $this->addIntervalRanges($leftRange, $rightRange);
            }
            if ($node->operator === BinaryOperator::Subtract) {
                return $this->subtractIntervalRanges($leftRange, $rightRange);
            }
            if ($node->operator === BinaryOperator::Multiply) {
                return $this->multiplyIntervalRanges($leftRange, $rightRange);
            }
            if ($node->operator === BinaryOperator::Divide) {
                $numeratorHasPositiveValues = $leftRange[1] > 0.0;
                $numeratorHasNegativeValues = $leftRange[0] < 0.0;
                if ($rightRange[0] === 0.0 && $rightRange[1] > 0.0) {
                    if ($numeratorHasPositiveValues && $numeratorHasNegativeValues) {
                        return [-\INF, \INF];
                    }
                    if ($numeratorHasPositiveValues) {
                        return [$leftRange[0] / $rightRange[1], \INF];
                    }
                    if ($numeratorHasNegativeValues) {
                        return [-\INF, $leftRange[1] / $rightRange[1]];
                    }
                    return [0.0, 0.0];
                }
                if ($rightRange[0] < 0.0 && $rightRange[1] === 0.0) {
                    if ($numeratorHasPositiveValues && $numeratorHasNegativeValues) {
                        return [-\INF, \INF];
                    }
                    if ($numeratorHasPositiveValues) {
                        return [-\INF, $leftRange[0] / $rightRange[0]];
                    }
                    if ($numeratorHasNegativeValues) {
                        return [$leftRange[1] / $rightRange[0], \INF];
                    }
                    return [0.0, 0.0];
                }
                return $this->divideIntervalRanges($leftRange, $rightRange);
            }
            if ($node->operator === BinaryOperator::Modulo) {
                $divisor = $rightRange[0];
                if (
                    $rightRange[0] !== $rightRange[1]
                    || !\is_finite($divisor)
                    || $divisor == 0.0
                ) {
                    return null;
                }
                $remainderMagnitude = \abs($divisor) - 1.0;
                if ($leftRange[0] >= 0.0) {
                    return [0.0, $remainderMagnitude];
                }
                if ($leftRange[1] <= 0.0) {
                    return [-$remainderMagnitude, 0.0];
                }

                return [-$remainderMagnitude, $remainderMagnitude];
            }

            return null;
        }
        if (
            !$node instanceof FunctionCallNode
        ) {
            return null;
        }

        if ($node->name === 'abs' && \count($node->arguments) === 1) {
            $argumentRange = $this->boundedExpressionRange(
                $node->arguments[0],
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            );
            if ($argumentRange === null) {
                return null;
            }
            $minimum = $argumentRange[0] <= 0.0 && $argumentRange[1] >= 0.0
                ? 0.0
                : \min(\abs($argumentRange[0]), \abs($argumentRange[1]));

            return [$minimum, \max(\abs($argumentRange[0]), \abs($argumentRange[1]))];
        }
        if ($node->name === 'hypot' && \count($node->arguments) === 2) {
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $argumentRanges[] = $argumentRange;
            }
            $minimumAbsoluteValues = [];
            $maximumAbsoluteValues = [];
            foreach ($argumentRanges as [$minimum, $maximum]) {
                $minimumAbsoluteValues[] = $minimum <= 0.0 && $maximum >= 0.0
                    ? 0.0
                    : \min(\abs($minimum), \abs($maximum));
                $maximumAbsoluteValues[] = \max(\abs($minimum), \abs($maximum));
            }

            return [
                \hypot(...$minimumAbsoluteValues),
                \hypot(...$maximumAbsoluteValues),
            ];
        }
        if ($node->name === 'atan2' && \count($node->arguments) === 2) {
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $argumentRanges[] = $argumentRange;
            }
            [$yRange, $xRange] = $argumentRanges;
            if (
                $yRange[0] <= 0.0
                && $yRange[1] >= 0.0
                && $xRange[0] <= 0.0
            ) {
                return [-\M_PI, \M_PI];
            }
            $function = $evaluationOptions->functions->find('atan2');
            if ($function === null) {
                return null;
            }
            $angles = [];
            foreach ($yRange as $y) {
                foreach ($xRange as $x) {
                    try {
                        $angles[] = (float) $function->invoke([$y, $x]);
                    } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                        return [-\M_PI, \M_PI];
                    }
                }
            }
            $minimum = \min(...$angles);
            $maximum = \max(...$angles);
            if ($xRange[0] > 0.0 && $yRange[0] <= 0.0 && $yRange[1] >= 0.0) {
                $minimum = \min($minimum, 0.0);
                $maximum = \max($maximum, 0.0);
            }

            return [$minimum, $maximum];
        }
        if (\in_array($node->name, ['min', 'max'], true)) {
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $argumentRanges[] = $argumentRange;
            }
            if ($argumentRanges === []) {
                return null;
            }
            $range = $argumentRanges[0];
            foreach (\array_slice($argumentRanges, 1) as $argumentRange) {
                if ($node->name === 'min') {
                    $range = [
                        \min($range[0], $argumentRange[0]),
                        \min($range[1], $argumentRange[1]),
                    ];
                } else {
                    $range = [
                        \max($range[0], $argumentRange[0]),
                        \max($range[1], $argumentRange[1]),
                    ];
                }
            }

            return $range;
        }
        if ($node->name === 'log' && \count($node->arguments) === 2) {
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $argumentRanges[] = $argumentRange;
            }
            [$valueRange, $baseRange] = $argumentRanges;
            if (
                $valueRange[0] <= 0.0
                || $baseRange[0] <= 0.0
                || ($baseRange[0] <= 1.0 && $baseRange[1] >= 1.0)
            ) {
                return null;
            }
            $logarithmRange = [
                [\log($valueRange[0]), \log($valueRange[1])],
                [\log($baseRange[0]), \log($baseRange[1])],
            ];

            return $this->divideIntervalRanges(...$logarithmRange);
        }
        if (
            ($node->name === 'gcd' || $node->name === 'lcm')
            && \count($node->arguments) === 2
        ) {
            $argumentRanges = [];
            foreach ($node->arguments as $argument) {
                $argumentRange = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $solverOptions,
                );
                if ($argumentRange === null) {
                    return null;
                }
                $argumentRanges[] = $argumentRange;
            }
            $maximumAbsoluteValues = [];
            foreach ($argumentRanges as [$minimum, $maximum]) {
                $maximumAbsoluteValues[] = \max(\abs($minimum), \abs($maximum));
            }
            $upper = $node->name === 'gcd'
                ? \min(...$maximumAbsoluteValues)
                : $maximumAbsoluteValues[0] * $maximumAbsoluteValues[1];
            if (!\is_finite($upper)) {
                return null;
            }

            return [0.0, \min($upper, (float) \PHP_INT_MAX)];
        }
        if (
            \count($node->arguments) !== 1
            || !\in_array(
                $node->name,
                [
                    'acos', 'acosh', 'acot', 'asinh', 'asin', 'atan', 'cbrt',
                    'cos', 'cosh', 'erf', 'erfc', 'exp', 'expm1', 'floor',
                    'ceil', 'round', 'ln', 'log10', 'log2', 'log1p', 'sinh',
                    'sech', 'sqrt', 'tanh', 'sin', 'sec', 'csc', 'sinc', 'sincpi',
                    'csch', 'coth', 'tan', 'cot', 'asech', 'acsch', 'acoth',
                    'asec', 'acsc', 'atanh',
                ],
                true,
            )
        ) {
            return null;
        }

        $argumentRange = $this->boundedExpressionRange(
            $node->arguments[0],
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
        );
        if ($argumentRange === null) {
            return null;
        }
        if ($node->name === 'exp' && $argumentRange[0] === -\INF) {
            $upper = \exp($argumentRange[1]);

            return \is_finite($upper) ? [0.0, $upper] : null;
        }

        if (
            ($node->name === 'csch' || $node->name === 'coth')
            && $argumentRange[0] <= 0.0
            && $argumentRange[1] >= 0.0
        ) {
            return null;
        }
        if (
            $node->name === 'asech'
            && ($argumentRange[0] <= 0.0 || $argumentRange[1] > 1.0)
        ) {
            return null;
        }
        if (
            $node->name === 'acsch'
            && $argumentRange[0] <= 0.0
            && $argumentRange[1] >= 0.0
        ) {
            return null;
        }
        if (
            $node->name === 'acoth'
            && !($argumentRange[1] < -1.0 || $argumentRange[0] > 1.0)
        ) {
            return null;
        }
        if (
            ($node->name === 'asec' || $node->name === 'acsc')
            && !($argumentRange[1] <= -1.0 || $argumentRange[0] >= 1.0)
        ) {
            return null;
        }
        if (
            $node->name === 'atanh'
            && ($argumentRange[0] <= -1.0 || $argumentRange[1] >= 1.0)
        ) {
            return null;
        }

        if (\in_array($node->name, ['asin', 'acos', 'acosh', 'sqrt'], true)) {
            $domainMinimum = $node->name === 'acosh'
                ? 1.0
                : ($node->name === 'sqrt' ? 0.0 : -1.0);
            $domainMaximum = \in_array($node->name, ['asin', 'acos'], true)
                ? 1.0
                : \INF;
            $validMinimum = \max($argumentRange[0], $domainMinimum);
            $validMaximum = \min($argumentRange[1], $domainMaximum);
            if ($validMinimum > $validMaximum) {
                return null;
            }

            $function = $evaluationOptions->functions->find($node->name);
            if ($function === null) {
                return null;
            }
            try {
                $first = (float) $function->invoke([$validMinimum]);
                $second = (float) $function->invoke([$validMaximum]);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            $range = [\min($first, $second), \max($first, $second)];

            return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
        }

        if ($node->name === 'tan' || $node->name === 'cot') {
            $polePhase = $node->name === 'tan' ? \M_PI / 2.0 : 0.0;
            if (
                $this->containsPeriodicPhase(
                    $argumentRange[0],
                    $argumentRange[1],
                    $polePhase,
                    \M_PI,
                )
            ) {
                return null;
            }
            $function = $evaluationOptions->functions->find($node->name);
            if ($function === null) {
                return null;
            }
            try {
                $first = (float) $function->invoke([$argumentRange[0]]);
                $second = (float) $function->invoke([$argumentRange[1]]);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            $range = [\min($first, $second), \max($first, $second)];

            return \is_finite($range[0]) && \is_finite($range[1]) ? $range : null;
        }

        if ($node->name === 'sin' || $node->name === 'cos') {
            $width = $argumentRange[1] - $argumentRange[0];
            if (!\is_finite($width) || $width >= 2.0 * \M_PI) {
                return [-1.0, 1.0];
            }
            if ($node->name === 'sin' && $argumentRange[1] <= 0.0) {
                return [
                    \sin($argumentRange[0]),
                    \min(0.0, \sin($argumentRange[1])),
                ];
            }
            $function = $evaluationOptions->functions->find($node->name);
            if ($function === null) {
                return null;
            }
            $first = (float) $function->invoke([$argumentRange[0]]);
            $second = (float) $function->invoke([$argumentRange[1]]);
            $minimum = \min($first, $second);
            $maximum = \max($first, $second);
            $minimumPhase = $node->name === 'sin' ? -\M_PI / 2.0 : \M_PI;
            $maximumPhase = $node->name === 'sin' ? \M_PI / 2.0 : 0.0;
            if ($this->containsPeriodicPhase($argumentRange[0], $argumentRange[1], $minimumPhase)) {
                $minimum = -1.0;
            }
            if ($this->containsPeriodicPhase($argumentRange[0], $argumentRange[1], $maximumPhase)) {
                $maximum = 1.0;
            }

            return [$minimum, $maximum];
        }

        if ($node->name === 'sec' || $node->name === 'csc') {
            $isSecant = $node->name === 'sec';
            $polePhase = $isSecant ? \M_PI / 2.0 : 0.0;
            if (
                $this->containsPeriodicPhase(
                    $argumentRange[0],
                    $argumentRange[1],
                    $polePhase,
                    \M_PI,
                )
            ) {
                return null;
            }
            $function = $evaluationOptions->functions->find($node->name);
            if ($function === null) {
                return null;
            }
            try {
                $first = (float) $function->invoke([$argumentRange[0]]);
                $second = (float) $function->invoke([$argumentRange[1]]);
            } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                return null;
            }
            $minimum = \min($first, $second);
            $maximum = \max($first, $second);
            $positiveExtremumPhase = $isSecant ? 0.0 : \M_PI / 2.0;
            if (
                $this->containsPeriodicPhase(
                    $argumentRange[0],
                    $argumentRange[1],
                    $positiveExtremumPhase,
                )
            ) {
                $minimum = 1.0;
            }
            $negativeExtremumPhase = $isSecant ? \M_PI : -\M_PI / 2.0;
            if (
                $this->containsPeriodicPhase(
                    $argumentRange[0],
                    $argumentRange[1],
                    $negativeExtremumPhase,
                )
            ) {
                $maximum = -1.0;
            }

            return [$minimum, $maximum];
        }

        if ($node->name === 'sinc' || $node->name === 'sincpi') {
            return [-1.0, 1.0];
        }

        $function = $evaluationOptions->functions->find($node->name);
        if ($function === null) {
            return null;
        }
        try {
            $first = (float) $function->invoke([$argumentRange[0]]);
            $second = (float) $function->invoke([$argumentRange[1]]);
        } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
            return null;
        }
        $minimum = \min($first, $second);
        $maximum = \max($first, $second);
        if ($node->name === 'cosh' && $argumentRange[0] <= 0.0 && $argumentRange[1] >= 0.0) {
            $minimum = 1.0;
        }
        if ($node->name === 'sech' && $argumentRange[0] <= 0.0 && $argumentRange[1] >= 0.0) {
            $maximum = 1.0;
        }

        return \is_finite($minimum) && \is_finite($maximum)
            ? [$minimum, $maximum]
            : null;
    }

    private function isSafeForElementaryRangePruning(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof NumberNode || $node instanceof ConstantNode || $node instanceof VariableNode) {
            return true;
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->isSafeForElementaryRangePruning($node->operand);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->isSafeForElementaryRangePruning($node->left)
                && $this->isSafeForElementaryRangePruning($node->right);
        }
        if ($node instanceof FunctionCallNode) {
            return \count($node->arguments) === 1
                && \in_array($node->name, ['sin', 'cos', 'exp'], true)
                && $this->isSafeForElementaryRangePruning($node->arguments[0]);
        }

        return false;
    }

    private function hasReciprocalTrigonometricPhase(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if (
                \in_array($node->name, ['sin', 'cos'], true)
                && \count($node->arguments) === 1
            ) {
                $phase = $this->unwrapGrouping($node->arguments[0]);
                if (
                    $phase instanceof BinaryOperationNode
                    && $phase->operator === BinaryOperator::Divide
                    && ($numerator = $extractor->extract($phase->left)) !== null
                    && \count($numerator) === 1
                    && $numerator[0] !== 0.0
                    && $this->containsVariable($phase->right, $variable)
                ) {
                    return true;
                }
            }
            foreach ($node->arguments as $argument) {
                if ($this->hasReciprocalTrigonometricPhase($argument, $variable, $extractor)) {
                    return true;
                }
            }
        } elseif ($node instanceof BinaryOperationNode) {
            return $this->hasReciprocalTrigonometricPhase($node->left, $variable, $extractor)
                || $this->hasReciprocalTrigonometricPhase($node->right, $variable, $extractor);
        } elseif ($node instanceof UnaryOperationNode) {
            return $this->hasReciprocalTrigonometricPhase($node->operand, $variable, $extractor);
        }

        return false;
    }

    /**
     * @param array{float, float} $left
     * @param array{float, float} $right
     * @return array{float, float}|null
     */
    private function addIntervalRanges(array $left, array $right): ?array
    {
        $lower = $left[0] + $right[0];
        $upper = $left[1] + $right[1];

        return \is_finite($lower) && \is_finite($upper) ? [$lower, $upper] : null;
    }

    /**
     * @param array{float, float} $left
     * @param array{float, float} $right
     * @return array{float, float}|null
     */
    private function subtractIntervalRanges(array $left, array $right): ?array
    {
        $lower = $left[0] - $right[1];
        $upper = $left[1] - $right[0];

        return \is_finite($lower) && \is_finite($upper) ? [$lower, $upper] : null;
    }

    /**
     * @param array{float, float} $left
     * @param array{float, float} $right
     * @return array{float, float}|null
     */
    private function multiplyIntervalRanges(array $left, array $right): ?array
    {
        $products = [
            $left[0] * $right[0],
            $left[0] * $right[1],
            $left[1] * $right[0],
            $left[1] * $right[1],
        ];
        if (\in_array(false, \array_map('is_finite', $products), true)) {
            return null;
        }

        return [\min(...$products), \max(...$products)];
    }

    /**
     * @param array{float, float} $numerator
     * @param array{float, float} $denominator
     * @return array{float, float}|null
     */
    private function divideIntervalRanges(array $numerator, array $denominator): ?array
    {
        if ($denominator[0] <= 0.0 && $denominator[1] >= 0.0) {
            return null;
        }
        $quotients = [
            $numerator[0] / $denominator[0],
            $numerator[0] / $denominator[1],
            $numerator[1] / $denominator[0],
            $numerator[1] / $denominator[1],
        ];
        if (\in_array(false, \array_map('is_finite', $quotients), true)) {
            return null;
        }

        return [\min(...$quotients), \max(...$quotients)];
    }

    private function containsPeriodicPhase(
        float $lowerBound,
        float $upperBound,
        float $phase,
        float $period = 2.0 * \M_PI,
    ): bool {
        $scale = \max(1.0, \abs($lowerBound), \abs($upperBound));
        if ($scale > 1.0E14) {
            return true;
        }
        $tolerance = 8.0 * \PHP_FLOAT_EPSILON * $scale;
        $firstIndex = \ceil(($lowerBound - $phase - $tolerance) / $period);
        $lastIndex = \floor(($upperBound - $phase + $tolerance) / $period);

        return !\is_finite($firstIndex)
            || !\is_finite($lastIndex)
            || $firstIndex <= $lastIndex;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function sampledExpressionRange(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $steps,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $minimum = \INF;
        $maximum = -\INF;
        for ($index = 0; $index <= $steps; ++$index) {
            $position = $this->interpolateFiniteInterval(
                $lowerBound,
                $upperBound,
                $index / $steps,
            );
            try {
                $value = (float) $this->evaluateNode(
                    $node,
                    [...$parameters, $variable => $position],
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                continue;
            }
            $minimum = \min($minimum, $value);
            $maximum = \max($maximum, $value);
        }

        return \is_finite($minimum) && \is_finite($maximum)
            ? [$minimum, $maximum]
            : null;
    }

    /**
     * Increase fallback sampling for rapidly varying and multi-radical inputs.
     *
     * @param list<Node> $nodes
     * @param array<string, int|float> $parameters
     */
    private function adaptiveScanSteps(
        array $nodes,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): int {
        $scanSteps = $options->scanSteps;
        $variableCubeRootCount = 0;
        $visit = function (Node $node) use (
            &$visit,
            &$scanSteps,
            &$variableCubeRootCount,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        ): void {
            $node = $this->unwrapGrouping($node);
            if ($node instanceof FunctionCallNode) {
                if (
                    $node->name === 'cbrt'
                    && \count($node->arguments) === 1
                    && $this->containsVariable($node->arguments[0], $variable)
                ) {
                    ++$variableCubeRootCount;
                }
                $isTrigonometric = \in_array(
                    $node->name,
                    ['sin', 'cos', 'tan', 'csc', 'sec', 'cot', 'sinc', 'sincpi'],
                    true,
                );
                $isSteepTranscendental = \in_array(
                    $node->name,
                    ['exp', 'expm1', 'sinh', 'cosh', 'tanh', 'erf', 'erfc'],
                    true,
                );
                $isOscillatoryBessel = \in_array($node->name, ['besselj', 'bessely'], true)
                    && \count($node->arguments) === 2;
                if ($isOscillatoryBessel) {
                    $order = $this->extractPolynomial(
                        $extractor,
                        $node->arguments[0],
                        $node->arguments[0]->span()->start,
                    );
                    $argumentPolynomial = $this->extractPolynomial(
                        $extractor,
                        $node->arguments[1],
                        $node->arguments[1]->span()->start,
                    );
                    $variation = $order !== null
                        && \count($order) === 1
                        && \is_finite($order[0])
                        && \floor($order[0]) === $order[0]
                        && $argumentPolynomial !== null
                            ? $this->polynomialTotalVariation(
                                $argumentPolynomial,
                                $lowerBound,
                                $upperBound,
                                $this->polynomialIsolationOptions($options),
                            )
                            : null;
                    if ($variation !== null && \is_finite($variation)) {
                        $requiredScanSteps = \ceil($variation * 2.0);
                        if ($requiredScanSteps > self::MAX_ADAPTIVE_SCAN_STEPS) {
                            throw new RootSearchLimitException(
                                'The Bessel argument varies too rapidly to search within the '
                                    . 'configured scan limit.',
                            );
                        }
                        $required = (int) $requiredScanSteps;
                        $scanSteps = \max($scanSteps, $required);
                    } else {
                        $maximumArgumentStep = $this->sampledMaximumArgumentStep(
                            $node->arguments[1],
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                        );
                        if ($maximumArgumentStep !== null) {
                            $requiredScanSteps = \ceil(
                                $maximumArgumentStep * 128.0 * 4.0 / \M_PI,
                            );
                            if ($requiredScanSteps > self::MAX_ADAPTIVE_SCAN_STEPS) {
                                throw new RootSearchLimitException(
                                    'The sampled Bessel argument varies too rapidly to search '
                                        . 'within the configured scan limit.',
                                );
                            }
                            $required = (int) $requiredScanSteps;
                            $scanSteps = \max($scanSteps, $required);
                        }
                    }
                }
                if (
                    ($isTrigonometric || $isSteepTranscendental)
                    && \count($node->arguments) === 1
                ) {
                    $argument = $this->extractPolynomial(
                        $extractor,
                        $node->arguments[0],
                        $node->arguments[0]->span()->start,
                    );
                    if ($argument !== null && \count($argument) > 1) {
                        $variation = $this->polynomialTotalVariation(
                            $argument,
                            $lowerBound,
                            $upperBound,
                            $this->polynomialIsolationOptions($options),
                        );
                        if ($variation !== null) {
                            if (\is_finite($variation)) {
                                $variationScale = $isTrigonometric
                                    ? $variation / \M_PI
                                    : $variation;
                                $requiredScanSteps = \ceil($variationScale * 4.0);
                                if (
                                    $isTrigonometric
                                    && $requiredScanSteps > self::MAX_ADAPTIVE_SCAN_STEPS
                                ) {
                                    throw new PolynomialPhaseSamplingLimitException(
                                        'The polynomial trigonometric phase varies too rapidly '
                                            . 'to search within the configured scan limit.',
                                    );
                                }
                                $required = (int) \min(
                                    self::MAX_ADAPTIVE_SCAN_STEPS,
                                    $requiredScanSteps,
                                );
                                $scanSteps = \max(
                                    $scanSteps,
                                    $required,
                                );
                            }
                        }
                    } elseif ($isTrigonometric) {
                        $maximumArgumentStep = $this->sampledMaximumArgumentStep(
                            $node->arguments[0],
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                        );
                        if ($maximumArgumentStep !== null) {
                            $requiredScanSteps = \ceil(
                                $maximumArgumentStep * 128.0 * 4.0 / \M_PI,
                            );
                            if ($requiredScanSteps > self::MAX_ADAPTIVE_SCAN_STEPS) {
                                throw new RootSearchLimitException(
                                    'The sampled trigonometric phase varies too rapidly to '
                                        . 'search within the configured scan limit.',
                                );
                            }
                            $required = (int) $requiredScanSteps;
                            $scanSteps = \max($scanSteps, $required);
                        }
                    }
                }
                foreach ($node->arguments as $argument) {
                    $visit($argument);
                }
            } elseif ($node instanceof BinaryOperationNode) {
                $visit($node->left);
                $visit($node->right);
            } elseif ($node instanceof UnaryOperationNode) {
                $visit($node->operand);
            } elseif ($node instanceof FactorialNode) {
                $visit($node->operand);
            }
        };

        foreach ($nodes as $node) {
            $visit($node);
        }

        if ($variableCubeRootCount >= 4) {
            $required = (int) \min(
                self::MAX_ADAPTIVE_SCAN_STEPS,
                \max(256, $variableCubeRootCount * 64),
            );
            $scanSteps = \max($scanSteps, $required);
        }

        return $scanSteps;
    }

    private function highVariationTrigonometricTargetWorkLimit(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): int {
        foreach ([[$left, $right], [$right, $left]] as [$periodic, $target]) {
            $periodic = $this->unwrapGrouping($periodic);
            if (
                !$periodic instanceof FunctionCallNode
                || !\in_array($periodic->name, ['sin', 'cos'], true)
                || \count($periodic->arguments) !== 1
            ) {
                continue;
            }
            $phaseCoefficients = $extractor->extract($periodic->arguments[0]);
            $targetCoefficients = $extractor->extract($target);
            if (
                $phaseCoefficients === null
                || \count($phaseCoefficients) < 3
                || $targetCoefficients === null
                || \count($targetCoefficients) < 2
            ) {
                continue;
            }
            $variation = $this->polynomialTotalVariation(
                $phaseCoefficients,
                $lowerBound,
                $upperBound,
                $this->polynomialIsolationOptions($options),
            );
            if ($variation !== null && \is_finite($variation) && $variation > 10_000.0) {
                return self::MAX_HIGH_VARIATION_INTERVAL_WORK;
            }
        }

        return self::MAX_ROOT_DEGREE_SCAN_WORK;
    }

    private function hasHighDegreeTrigonometricProductPhase(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        $trigonometricFactors = 0;
        $hasHighDegreePhase = false;
        $visit = function (Node $node) use (
            &$visit,
            &$trigonometricFactors,
            &$hasHighDegreePhase,
            $variable,
            $extractor,
        ): void {
            $node = $this->unwrapGrouping($node);
            if ($node instanceof FunctionCallNode) {
                if (
                    \in_array($node->name, ['sin', 'cos'], true)
                    && \count($node->arguments) === 1
                    && $this->containsVariable($node->arguments[0], $variable)
                ) {
                    ++$trigonometricFactors;
                    $coefficients = $extractor->extract($node->arguments[0]);
                    $hasHighDegreePhase = $hasHighDegreePhase
                        || ($coefficients !== null && \count($coefficients) >= 7);
                }
                foreach ($node->arguments as $argument) {
                    $visit($argument);
                }
            } elseif ($node instanceof BinaryOperationNode) {
                $visit($node->left);
                $visit($node->right);
            } elseif ($node instanceof UnaryOperationNode) {
                $visit($node->operand);
            } elseif ($node instanceof FactorialNode) {
                $visit($node->operand);
            }
        };
        $visit($left);
        $visit($right);

        return $trigonometricFactors > 1 && $hasHighDegreePhase;
    }

    /**
     * Sample a direct sine or cosine equation at uniformly spaced polynomial phases.
     *
     * @return list<float>|null
     */
    private function directPolynomialTrigonometricPhaseSamples(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $trigonometric = null;
        $target = null;
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['sin', 'cos'], true)
            && \count($left->arguments) === 1
        ) {
            $trigonometric = $left;
            $target = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['sin', 'cos'], true)
            && \count($right->arguments) === 1
            && !$this->containsVariable($left, $variable)
        ) {
            $trigonometric = $right;
            $target = $left;
        }
        if ($trigonometric === null) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $target,
            $target->span()->start,
        );
        $phaseCoefficients = $this->extractPolynomial(
            $extractor,
            $trigonometric->arguments[0],
            $trigonometric->arguments[0]->span()->start,
        );
        if (
            $targetCoefficients === null
            || $phaseCoefficients === null
            || \count($phaseCoefficients) < 3
        ) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $phaseDerivative = $this->polynomialDerivative($phaseCoefficients);
        $criticalPoints = $polynomialSolver->solve(
            $phaseDerivative,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($phaseDerivative, $value),
            $this->polynomialIsolationOptions($options),
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                $phaseDerivative,
                $value,
            ),
        );
        if ($criticalPoints === null) {
            return null;
        }

        $segments = [$lowerBound];
        foreach ($criticalPoints as $criticalPoint) {
            if ($criticalPoint->value > $lowerBound && $criticalPoint->value < $upperBound) {
                $segments[] = $criticalPoint->value;
            }
        }
        $segments[] = $upperBound;
        \sort($segments, SORT_NUMERIC);
        $samples = [];
        $halfPi = \M_PI / 2.0;
        for ($segmentIndex = 1, $segmentCount = \count($segments); $segmentIndex < $segmentCount; ++$segmentIndex) {
            $segmentLower = $segments[$segmentIndex - 1];
            $segmentUpper = $segments[$segmentIndex];
            $phaseLower = $polynomialSolver->evaluatePolynomial($phaseCoefficients, $segmentLower);
            $phaseUpper = $polynomialSolver->evaluatePolynomial($phaseCoefficients, $segmentUpper);
            if ($phaseLower === null || $phaseUpper === null) {
                return null;
            }
            $samples[] = $segmentLower;
            $samples[] = $segmentUpper;
            if ($phaseLower === $phaseUpper) {
                continue;
            }
            $minimumPhase = \min($phaseLower, $phaseUpper);
            $maximumPhase = \max($phaseLower, $phaseUpper);
            $firstLevel = (int) \ceil($minimumPhase / $halfPi);
            $lastLevel = (int) \floor($maximumPhase / $halfPi);
            if (
                !\is_finite((float) $firstLevel)
                || !\is_finite((float) $lastLevel)
                || \abs($firstLevel) > 9_007_199_254_740_991
                || \abs($lastLevel) > 9_007_199_254_740_991
            ) {
                return null;
            }
            if ($lastLevel - $firstLevel + 1 > self::MAX_POLYNOMIAL_PHASE_SAMPLE_POSITIONS) {
                return null;
            }
            for ($levelIndex = $firstLevel; $levelIndex <= $lastLevel; ++$levelIndex) {
                $phaseLevel = $levelIndex * $halfPi;
                $levelPosition = $this->bisectPolynomialPhaseLevel(
                    $phaseCoefficients,
                    $phaseLevel,
                    $segmentLower,
                    $segmentUpper,
                    $phaseLower,
                    $phaseUpper,
                    $polynomialSolver,
                    $options,
                );
                if ($levelPosition === null) {
                    return null;
                }
                $samples[] = $levelPosition;
                if (\count($samples) > self::MAX_POLYNOMIAL_PHASE_SAMPLE_POSITIONS) {
                    return null;
                }
            }
        }

        \sort($samples, SORT_NUMERIC);
        $uniqueSamples = [];
        foreach ($samples as $sample) {
            if ($sample < $lowerBound || $sample > $upperBound || !\is_finite($sample)) {
                continue;
            }
            if (
                $uniqueSamples === []
                || $sample !== $uniqueSamples[\array_key_last($uniqueSamples)]
            ) {
                $uniqueSamples[] = $sample;
            }
        }

        return $uniqueSamples;
    }

    /**
     * @param list<float> $phaseCoefficients
     */
    private function bisectPolynomialPhaseLevel(
        array $phaseCoefficients,
        float $phaseLevel,
        float $lower,
        float $upper,
        float $lowerPhase,
        float $upperPhase,
        PolynomialSolver $polynomialSolver,
        SolverOptions $options,
    ): ?float {
        $lowerResidual = $lowerPhase - $phaseLevel;
        $upperResidual = $upperPhase - $phaseLevel;
        if ($lowerResidual === 0.0) {
            return $lower;
        }
        if ($upperResidual === 0.0) {
            return $upper;
        }
        if (!$this->hasOppositeSigns($lowerResidual, $upperResidual)) {
            $tolerance = 16.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($lowerPhase), \abs($upperPhase), \abs($phaseLevel));
            if (\min(\abs($lowerResidual), \abs($upperResidual)) <= $tolerance) {
                return \abs($lowerResidual) <= \abs($upperResidual) ? $lower : $upper;
            }

            return null;
        }

        for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
            $middle = $lower + (($upper - $lower) / 2.0);
            if (
                $middle === $lower
                || $middle === $upper
                || $upper - $lower <= $options->positionTolerance($lower, $upper)
            ) {
                return $middle;
            }
            $middlePhase = $polynomialSolver->evaluatePolynomial($phaseCoefficients, $middle);
            if ($middlePhase === null) {
                return null;
            }
            $middleResidual = $middlePhase - $phaseLevel;
            if ($middleResidual === 0.0) {
                return $middle;
            }
            if ($this->hasOppositeSigns($lowerResidual, $middleResidual)) {
                $upper = $middle;
                $upperResidual = $middleResidual;
            } else {
                $lower = $middle;
                $lowerResidual = $middleResidual;
            }
        }

        return null;
    }

    /**
     * Estimate the largest phase change over a coarse interval subdivision.
     *
     * @param array<string, int|float> $parameters
     */
    private function sampledMaximumArgumentStep(
        Node $argument,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        $previous = null;
        $maximumStep = 0.0;
        for ($index = 0; $index <= 128; ++$index) {
            $position = $this->interpolateFiniteInterval(
                $lowerBound,
                $upperBound,
                $index / 128.0,
            );
            try {
                $value = (float) $this->evaluateNode(
                    $argument,
                    [...$parameters, $variable => $position],
                    $evaluationOptions,
                );
            } catch (MathException | \DomainException) {
                return null;
            }
            if (!\is_finite($value)) {
                return null;
            }
            if ($previous !== null) {
                $step = \abs($value - $previous);
                if (!\is_finite($step)) {
                    return null;
                }
                $maximumStep = \max($maximumStep, $step);
            }
            $previous = $value;
        }

        return $maximumStep;
    }

    /**
     * @param list<float> $coefficients
     */
    private function polynomialTotalVariation(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?float {
        $derivative = [];
        foreach ($coefficients as $power => $coefficient) {
            if ($power === 0) {
                continue;
            }
            $derivativeCoefficient = $power * $coefficient;
            if (!\is_finite($derivativeCoefficient)) {
                return null;
            }
            $derivative[] = $derivativeCoefficient;
        }

        $criticalPoints = [];
        if (\count($derivative) > 1) {
            $polynomialSolver = new PolynomialSolver();
            $roots = $polynomialSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $derivative,
                    $value,
                ),
                $options,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $criticalPoints[] = $root->value;
            }
        }

        $positions = [$lowerBound, ...$criticalPoints, $upperBound];
        \sort($positions, SORT_NUMERIC);
        $variation = 0.0;
        $previous = $this->polynomialValue($coefficients, $positions[0]);
        if ($previous === null) {
            return null;
        }
        for ($index = 1, $count = \count($positions); $index < $count; ++$index) {
            $value = $this->polynomialValue($coefficients, $positions[$index]);
            if ($value === null) {
                return null;
            }
            $variation += \abs($value - $previous);
            if (!\is_finite($variation)) {
                return null;
            }
            $previous = $value;
        }

        return $variation;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{node: Node, coefficients: list<float>}|null
     */
    private function findPolynomialFactorialOperand(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
        int $maxDegree,
    ): ?array {
        if ($node instanceof FactorialNode) {
            if ($this->containsVariable($node->operand, $variable)) {
                try {
                    $coefficients = (new PolynomialExtractor(
                        $variable,
                        $parameters,
                        $options,
                        $maxDegree,
                    ))->extract($node->operand);
                } catch (EvaluationException) {
                    $coefficients = null;
                }
                if (
                    $coefficients !== null
                    && \count($coefficients) > 1
                ) {
                    return [
                        'node' => $node->operand,
                        'coefficients' => $coefficients,
                    ];
                }
            }

            return $this->findPolynomialFactorialOperand(
                $node->operand,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->findPolynomialFactorialOperand(
                $node->expression,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->findPolynomialFactorialOperand(
                $node->operand,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->findPolynomialFactorialOperand(
                $node->left,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            ) ?? $this->findPolynomialFactorialOperand(
                $node->right,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                $operand = $this->findPolynomialFactorialOperand(
                    $argument,
                    $variable,
                    $parameters,
                    $options,
                    $maxDegree,
                );
                if ($operand !== null) {
                    return $operand;
                }
            }
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{coefficients: list<float>}|null
     */
    private function findPolynomialRootDegree(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
        int $maxDegree,
    ): ?array {
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'root'
            && isset($node->arguments[1])
            && $this->containsVariable($node->arguments[1], $variable)
        ) {
            try {
                $coefficients = (new PolynomialExtractor(
                    $variable,
                    $parameters,
                    $options,
                    $maxDegree,
                ))->extract($node->arguments[1]);
            } catch (EvaluationException) {
                $coefficients = null;
            }
            if (
                $coefficients !== null
                && \count($coefficients) > 1
            ) {
                return ['coefficients' => $coefficients];
            }
        }

        if ($node instanceof BinaryOperationNode) {
            return $this->findPolynomialRootDegree(
                $node->left,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            ) ?? $this->findPolynomialRootDegree(
                $node->right,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->findPolynomialRootDegree(
                $node->expression,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->findPolynomialRootDegree(
                $node->operand,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->findPolynomialRootDegree(
                $node->operand,
                $variable,
                $parameters,
                $options,
                $maxDegree,
            );
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                $degree = $this->findPolynomialRootDegree(
                    $argument,
                    $variable,
                    $parameters,
                    $options,
                    $maxDegree,
                );
                if ($degree !== null) {
                    return $degree;
                }
            }
        }

        return null;
    }

    private function findVariableRootDegreeNode(Node $node, string $variable): ?Node
    {
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'root'
            && isset($node->arguments[1])
            && $this->containsVariable($node->arguments[1], $variable)
        ) {
            return $node->arguments[1];
        }

        if ($node instanceof BinaryOperationNode) {
            return $this->findVariableRootDegreeNode($node->left, $variable)
                ?? $this->findVariableRootDegreeNode($node->right, $variable);
        }
        if ($node instanceof GroupingNode) {
            return $this->findVariableRootDegreeNode($node->expression, $variable);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->findVariableRootDegreeNode($node->operand, $variable);
        }
        if ($node instanceof FactorialNode) {
            return $this->findVariableRootDegreeNode($node->operand, $variable);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                $degree = $this->findVariableRootDegreeNode($argument, $variable);
                if ($degree !== null) {
                    return $degree;
                }
            }
        }

        return null;
    }

    /**
     * @param list<float> $degreeCoefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null Null means the integer search is too large or unstable.
     */
    private function solveLinearRootDegreeDomain(
        array $degreeCoefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        $polynomialSolver = new PolynomialSolver();
        $lowerDegree = $this->polynomialValue($degreeCoefficients, $lowerBound);
        $upperDegree = $this->polynomialValue($degreeCoefficients, $upperBound);
        if ($lowerDegree === null || $upperDegree === null) {
            return null;
        }

        $extrema = [$lowerDegree, $upperDegree];
        $derivative = [];
        foreach ($degreeCoefficients as $power => $coefficient) {
            if ($power === 0) {
                continue;
            }
            $derivativeCoefficient = $power * $coefficient;
            if (!\is_finite($derivativeCoefficient)) {
                return null;
            }
            $derivative[] = $derivativeCoefficient;
        }
        if (\count($derivative) > 1) {
            $criticalPoints = $polynomialSolver->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $this->polynomialValue($derivative, $value),
                $solverOptions,
            );
            if ($criticalPoints === null) {
                return null;
            }
            foreach ($criticalPoints as $criticalPoint) {
                $degreeAtCriticalPoint = $this->polynomialValue(
                    $degreeCoefficients,
                    $criticalPoint->value,
                );
                if ($degreeAtCriticalPoint === null) {
                    return null;
                }
                $extrema[] = $degreeAtCriticalPoint;
            }
        }

        $minimumDegree = \min(...$extrema);
        $maximumDegree = \max(...$extrema);
        $degreeTolerance = \min(
            0.25,
            8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimumDegree), \abs($maximumDegree)),
        );
        $maximumExactDegree = 9_007_199_254_740_991.0;
        $first = \max(-$maximumExactDegree, \ceil($minimumDegree - $degreeTolerance));
        $last = \min($maximumExactDegree, \floor($maximumDegree + $degreeTolerance));
        if ($first > $last) {
            return [];
        }
        if ($last - $first + 1.0 > $solverOptions->scanSteps) {
            return null;
        }

        $solutions = [];
        for ($degree = (int) $first, $lastDegree = (int) $last; $degree <= $lastDegree; ++$degree) {
            if ($degree === 0) {
                continue;
            }
            $levelPolynomial = $degreeCoefficients;
            $levelPolynomial[0] -= $degree;
            $levelRoots = $polynomialSolver->solve(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                function (float $value) use ($degreeCoefficients, $degree): ?float {
                    $degreeValue = $this->polynomialValue($degreeCoefficients, $value);

                    return $degreeValue === null ? null : $degreeValue - $degree;
                },
                $solverOptions,
            );
            if ($levelRoots === null) {
                return null;
            }

            foreach ($levelRoots as $levelRoot) {
                $candidate = $levelRoot->value;
                if ($candidate < $lowerBound || $candidate > $upperBound) {
                    continue;
                }

                $residual = $residualAt($candidate);
                $residualScale = $residualScaleAt($candidate);
                if ($residual === null || $residualScale === null) {
                    continue;
                }
                $residualScale = \max($residualScale, \abs($residual));
                if ($residualScale === 0.0) {
                    $residualScale = 1.0;
                }
                if (\abs($residual / $residualScale) > $solverOptions->residualTolerance) {
                    continue;
                }

                $solutions[] = new EquationSolution($candidate, \abs($residual), 0);
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null Null means no usable polynomial modulo operand was found.
     */
    private function solvePolynomialModuloDomain(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
    ): ?array {
        $polynomials = [
            ...$this->variableModuloPolynomials($left, $variable, $extractor),
            ...$this->variableModuloPolynomials($right, $variable, $extractor),
        ];
        if ($polynomials === []) {
            return null;
        }

        $maximumExactInteger = 9_007_199_254_740_991.0;
        $maximumLevels = \max(
            1,
            \intdiv(self::MAX_MODULO_SCAN_WORK, $solverOptions->scanSteps),
        );
        $selected = null;
        $selectedCount = \INF;
        foreach ($polynomials as $coefficients) {
            $range = $this->polynomialRange($coefficients, $lowerBound, $upperBound, $solverOptions);
            if ($range === null) {
                continue;
            }
            [$minimum, $maximum] = $range;
            if (
                $minimum < -$maximumExactInteger
                || $maximum > $maximumExactInteger
            ) {
                continue;
            }
            $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimum), \abs($maximum));
            $first = \ceil($minimum - $tolerance);
            $last = \floor($maximum + $tolerance);
            if ($first > $last) {
                return [];
            }

            $levelCount = $last - $first + 1.0;
            if ($levelCount <= $maximumLevels && $levelCount < $selectedCount) {
                $selected = [$coefficients, (int) $first, (int) $last];
                $selectedCount = $levelCount;
            }
        }
        if ($selected === null) {
            return null;
        }

        [$coefficients, $firstLevel, $lastLevel] = $selected;
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
            $levelPolynomial = $coefficients;
            $levelPolynomial[0] -= $level;
            $levelRoots = $polynomialSolver->solve(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                function (float $value) use ($coefficients, $level): ?float {
                    $operand = $this->polynomialValue($coefficients, $value);

                    return $operand === null ? null : $operand - $level;
                },
                $solverOptions,
            );
            if ($levelRoots === null) {
                return null;
            }

            foreach ($levelRoots as $levelRoot) {
                $candidate = $levelRoot->value;
                $evaluation = $this->residualAndScaleWithModuloRounding(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidate,
                    $parameters,
                    $evaluationOptions,
                    4.0 * \max(1, \count($coefficients) - 1),
                );
                if ($evaluation === null) {
                    continue;
                }
                [$residual, $scale] = $evaluation;
                $scale = \max($scale, \abs($residual));
                if ($scale === 0.0) {
                    $scale = 1.0;
                }
                if (\abs($residual / $scale) > $solverOptions->residualTolerance) {
                    continue;
                }

                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), $levelRoot->iterations),
                    $solverOptions,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Enumerate reachable integer-remainder levels for bounded non-polynomial modulo operands.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveBoundedNonPolynomialModuloLevels(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): ?array {
        $moduloNode = null;
        $moduloSource = '';
        $moduloSourceOffset = 0;
        $targetNode = null;
        $target = null;
        $leftSide = $this->unwrapGrouping($left);
        $rightSide = $this->unwrapGrouping($right);
        if (
            $leftSide instanceof BinaryOperationNode
            && $leftSide->operator === BinaryOperator::Modulo
            && !$this->containsVariable($rightSide, $variable)
        ) {
            $moduloNode = $leftSide;
            $moduloSource = $leftSource;
            $targetNode = $rightSide;
        } elseif (
            $rightSide instanceof BinaryOperationNode
            && $rightSide->operator === BinaryOperator::Modulo
            && !$this->containsVariable($leftSide, $variable)
        ) {
            $moduloNode = $rightSide;
            $moduloSource = $rightSource;
            $moduloSourceOffset = 0;
            $targetNode = $leftSide;
        }
        if (!$moduloNode instanceof BinaryOperationNode) {
            return null;
        }
        try {
            $target = (float) $this->evaluateNode($targetNode, $parameters, $evaluationOptions);
        } catch (EvaluationException) {
            return null;
        }
        if (!\is_finite($target) || \floor($target) !== $target) {
            return null;
        }

        $numerator = $moduloNode->left;
        if (!$this->containsVariable($numerator, $variable) || $this->containsVariable($moduloNode->right, $variable)) {
            return null;
        }
        try {
            $divisor = (float) $this->evaluateNode($moduloNode->right, $parameters, $evaluationOptions);
        } catch (EvaluationException) {
            return null;
        }
        if (!\is_finite($divisor) || $divisor === 0.0 || \floor($divisor) !== $divisor) {
            return null;
        }
        $period = \abs($divisor);
        if (\abs($target) >= $period) {
            return [];
        }

        $range = (new InequalitySolver())->boundedExpressionRangeForSolver(
            $numerator,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($range === null || !\is_finite($range[0]) || !\is_finite($range[1])) {
            return null;
        }
        $tolerance = 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($range[0]), \abs($range[1]));
        $firstQuotient = \ceil(($range[0] - $target - $tolerance) / $period);
        $lastQuotient = \floor(($range[1] - $target + $tolerance) / $period);
        if ($lastQuotient < $firstQuotient) {
            return [];
        }
        if (
            !\is_finite($firstQuotient)
            || !\is_finite($lastQuotient)
            || \abs($firstQuotient) > 4_503_599_627_370_496.0
            || \abs($lastQuotient) > 4_503_599_627_370_496.0
            || $lastQuotient - $firstQuotient + 1.0 > self::MAX_MODULO_SCAN_WORK
        ) {
            return null;
        }

        $span = $numerator->span();
        $numeratorSource = \substr(
            $moduloSource,
            $span->start - $moduloSourceOffset,
            $span->end - $span->start,
        );
        if ($numeratorSource === '') {
            return null;
        }
        $solutions = [];
        for ($quotient = $firstQuotient; $quotient <= $lastQuotient; ++$quotient) {
            $level = ($quotient * $period) + $target;
            if (!\is_finite($level)) {
                continue;
            }
            $levelSolutions = $this->solve(
                $numeratorSource . ' = ' . \sprintf('%.17g', $level),
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($levelSolutions as $solution) {
                $evaluation = $this->residualAndScaleWithModuloRounding(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $solution->value,
                    $parameters,
                    $evaluationOptions,
                    4.0,
                );
                if ($evaluation === null) {
                    continue;
                }
                [$residual, $scale] = $evaluation;
                $scale = \max(1.0, \abs($residual), $scale);
                if (\abs($residual) > $solverOptions->residualTolerance * $scale) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($solution->value, \abs($residual), $solution->iterations),
                    $solverOptions,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return list<list<float>>
     */
    private function variableModuloPolynomials(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            $polynomials = [];
            if ($node->operator === BinaryOperator::Modulo) {
                foreach ([$node->left, $node->right] as $operand) {
                    if (!$this->containsVariable($operand, $variable)) {
                        continue;
                    }
                    $coefficients = $this->extractPolynomial($extractor, $operand, 0);
                    if ($coefficients !== null && \count($coefficients) > 1) {
                        $polynomials[] = $coefficients;
                    }
                }
            }

            return [
                ...$polynomials,
                ...$this->variableModuloPolynomials($node->left, $variable, $extractor),
                ...$this->variableModuloPolynomials($node->right, $variable, $extractor),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->variableModuloPolynomials($node->operand, $variable, $extractor);
        }
        if ($node instanceof GroupingNode) {
            return $this->variableModuloPolynomials($node->expression, $variable, $extractor);
        }
        if ($node instanceof FactorialNode) {
            return $this->variableModuloPolynomials($node->operand, $variable, $extractor);
        }
        if ($node instanceof FunctionCallNode) {
            $polynomials = [];
            foreach ($node->arguments as $argument) {
                $polynomials = [
                    ...$polynomials,
                    ...$this->variableModuloPolynomials($argument, $variable, $extractor),
                ];
            }

            return $polynomials;
        }

        return [];
    }

    /**
     * @param list<float> $coefficients
     */
    private function polynomialHasPositiveValuesBesideZero(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): bool {
        $solver = new PolynomialSolver();
        $zeroRoots = $solver->solve(
            $coefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $solver->evaluatePolynomial($coefficients, $value),
            $options,
        );
        if ($zeroRoots === null || $zeroRoots === []) {
            return false;
        }

        $points = [$lowerBound, ...\array_map(
            static fn (EquationSolution $root): float => $root->value,
            $zeroRoots,
        ), $upperBound];
        \sort($points, SORT_NUMERIC);
        $points = \array_values(\array_unique($points, SORT_REGULAR));
        for ($index = 0; $index < \count($points) - 1; ++$index) {
            $middle = $points[$index] + (($points[$index + 1] - $points[$index]) / 2.0);
            if ($middle === $points[$index] || $middle === $points[$index + 1]) {
                continue;
            }
            $value = $solver->evaluatePolynomial($coefficients, $middle);
            if ($value === null || $value <= 0.0) {
                continue;
            }

            $magnitude = 0.0;
            $power = 1.0;
            foreach ($coefficients as $coefficient) {
                $magnitude += \abs($coefficient * $power);
                $power *= \abs($middle);
                if (!\is_finite($magnitude) || !\is_finite($power)) {
                    return false;
                }
            }
            if ($value > 32.0 * \PHP_FLOAT_EPSILON * \max($magnitude, \PHP_FLOAT_MIN)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<float> $coefficients
     * @return array{float, float}|null
     */
    private function polynomialRange(
        array $coefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): ?array {
        $lowerValue = $this->polynomialValue($coefficients, $lowerBound);
        $upperValue = $this->polynomialValue($coefficients, $upperBound);
        if ($lowerValue === null || $upperValue === null) {
            return null;
        }
        $values = [$lowerValue, $upperValue];
        $derivative = [];
        foreach ($coefficients as $power => $coefficient) {
            if ($power === 0) {
                continue;
            }
            $derivativeCoefficient = $power * $coefficient;
            if (!\is_finite($derivativeCoefficient)) {
                return null;
            }
            $derivative[] = $derivativeCoefficient;
        }
        if (\count($derivative) > 1) {
            $criticalPoints = (new PolynomialSolver())->solve(
                $derivative,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $this->polynomialValue($derivative, $value),
                $solverOptions,
            );
            if ($criticalPoints === null) {
                return null;
            }
            foreach ($criticalPoints as $criticalPoint) {
                $value = $this->polynomialValue($coefficients, $criticalPoint->value);
                if ($value === null) {
                    return null;
                }
                $values[] = $value;
            }
        }

        return [\min(...$values), \max(...$values)];
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function residualAndScaleWithModuloRounding(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        float $value,
        array $parameters,
        EvaluationOptions $options,
        float $roundingUlps,
    ): ?array {
        $variables = [...$parameters, $variable => $value];
        try {
            $leftValue = $this->evaluateNode(
                $left,
                $variables,
                $options,
                moduloRoundingUlps: $roundingUlps,
            );
        } catch (EvaluationException $error) {
            return $this->handleEvaluationError($error, 0);
        }
        try {
            $rightValue = $this->evaluateNode(
                $right,
                $variables,
                $options,
                moduloRoundingUlps: $roundingUlps,
            );
        } catch (EvaluationException $error) {
            return $this->handleEvaluationError($error, $rightOffset);
        }

        $residual = (float) $leftValue - (float) $rightValue;
        if (!\is_finite($residual)) {
            return null;
        }

        return [
            $residual,
            \max(\abs((float) $leftValue), \abs((float) $rightValue)),
        ];
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null Null means the equation is not a supported shape.
     */
    private function solveConstantRadicandRootDegreeEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        foreach (
            [
                [$left, $leftSource, $right],
                [$right, $rightSource, $left],
            ] as [$side, $source, $otherSide]
        ) {
            $side = $this->unwrapGrouping($side);
            if (
                !$side instanceof FunctionCallNode
                || $side->name !== 'root'
                || !isset($side->arguments[0], $side->arguments[1])
                || $this->containsVariable($side->arguments[0], $variable)
                || !$this->containsVariable($side->arguments[1], $variable)
                || $this->containsVariable($otherSide, $variable)
            ) {
                continue;
            }

            try {
                $radicand = (float) $this->evaluateNode(
                    $side->arguments[0],
                    $parameters,
                    $evaluationOptions,
                );
                $target = (float) $this->evaluateNode(
                    $otherSide,
                    $parameters,
                    $evaluationOptions,
                );
            } catch (EvaluationException) {
                return null;
            }
            if (
                !\is_finite($radicand)
                || !\is_finite($target)
                || $radicand === 0.0
                || $target === 0.0
                || \abs($radicand) === 1.0
                || \abs($target) === 1.0
                || ($radicand > 0.0 && $target < 0.0)
                || ($radicand < 0.0 && $target > 0.0)
            ) {
                return [];
            }

            $degree = \log(\abs($radicand)) / \log(\abs($target));
            $nearestInteger = \round($degree);
            if (
                !\is_finite($degree)
                || \abs($degree) > 9_007_199_254_740_991.0
                || \abs($degree - $nearestInteger)
                    > \min(
                        1.0E-9,
                        64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($degree)),
                    )
                || $nearestInteger === 0.0
                || ($radicand < 0.0 && ((int) \abs($nearestInteger) % 2) !== 1)
            ) {
                return [];
            }

            $degreeNode = $side->arguments[1];
            $span = $degreeNode->span();
            $degreeExpression = \substr(
                $source,
                $span->start,
                $span->end - $span->start,
            );
            $integerDegreeTolerance = \min(
                1.0E-9,
                16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($nearestInteger)),
            );
            $degreeOptions = new SolverOptions(
                scanSteps: $solverOptions->scanSteps,
                maxIterations: $solverOptions->maxIterations,
                absoluteTolerance: \min(
                    $solverOptions->absoluteTolerance,
                    $integerDegreeTolerance,
                ),
                relativeTolerance: \min(
                    $solverOptions->relativeTolerance,
                    $integerDegreeTolerance,
                ),
                residualTolerance: \min(
                    $solverOptions->residualTolerance,
                    8.0 * \PHP_FLOAT_EPSILON,
                ),
                maxPolynomialDegree: $solverOptions->maxPolynomialDegree,
            );
            $levelSolutions = $this->solve(
                $degreeExpression . '=' . (int) $nearestInteger,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $degreeOptions,
            );
            $solutions = [];
            foreach ($levelSolutions as $candidate) {
                $residual = $residualAt($candidate->value);
                $scale = $residualScaleAt($candidate->value);
                if ($residual === null || $scale === null) {
                    continue;
                }
                $scale = \max($scale, \abs($residual));
                if ($scale === 0.0) {
                    $scale = 1.0;
                }
                if (\abs($residual / $scale) <= $solverOptions->residualTolerance) {
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $solverOptions,
                    );
                }
            }

            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        return null;
    }

    private function unwrapGrouping(Node $node): Node
    {
        while ($node instanceof GroupingNode) {
            $node = $node->expression;
        }

        return $node;
    }

    /** @param array<string, int|float> $parameters */
    private function normalizeAdditiveEquation(
        string $leftExpression,
        string $rightExpression,
        int $rightOffset,
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?string {
        $variableOnLeft = $this->containsVariable($left, $variable);
        $variableOnRight = $this->containsVariable($right, $variable);
        if ($variableOnLeft === $variableOnRight) {
            return null;
        }

        $equationVariableSide = $variableOnLeft ? $left : $right;
        $equationOtherSide = $variableOnLeft ? $right : $left;
        if ($this->containsVariable($equationOtherSide, $variable)) {
            return null;
        }

        $additive = $this->unwrapGrouping($equationVariableSide);
        if (
            !$additive instanceof BinaryOperationNode
            || !\in_array(
                $additive->operator,
                [BinaryOperator::Add, BinaryOperator::Subtract],
                true,
            )
        ) {
            return null;
        }

        $variableInLeftOperand = $this->containsVariable($additive->left, $variable);
        $variableInRightOperand = $this->containsVariable($additive->right, $variable);
        if ($variableInLeftOperand === $variableInRightOperand) {
            return null;
        }

        $sideSource = $variableOnLeft ? $leftExpression : $rightExpression;
        $sideSourceOffset = 0;
        $otherSource = $variableOnLeft ? $rightExpression : $leftExpression;
        $variableNode = $variableInLeftOperand ? $additive->left : $additive->right;
        $constantNode = $variableInLeftOperand ? $additive->right : $additive->left;
        $variableExpression = $this->unwrapGrouping($variableNode);
        $negatedPower = false;
        if ($variableExpression instanceof UnaryOperationNode) {
            $negatedPower = $variableExpression->operator === UnaryOperator::Minus;
            $variableNode = $variableExpression->operand;
            $variableExpression = $this->unwrapGrouping($variableNode);
        }
        $scalarNode = null;
        $scalarOperation = null;
        if (
            $variableExpression instanceof BinaryOperationNode
            && $variableExpression->operator === BinaryOperator::Multiply
        ) {
            $leftHasVariable = $this->containsVariable($variableExpression->left, $variable);
            $rightHasVariable = $this->containsVariable($variableExpression->right, $variable);
            if ($leftHasVariable !== $rightHasVariable) {
                $candidateScalar = $leftHasVariable
                    ? $variableExpression->right
                    : $variableExpression->left;
                $scalarValue = $this->constantNodeValue(
                    $candidateScalar,
                    $parameters,
                    $evaluationOptions,
                );
                if ($scalarValue !== null && \is_finite($scalarValue) && $scalarValue !== 0.0) {
                    $variableNode = $leftHasVariable
                        ? $variableExpression->left
                        : $variableExpression->right;
                    $variableExpression = $this->unwrapGrouping($variableNode);
                    $scalarNode = $candidateScalar;
                    $scalarOperation = BinaryOperator::Multiply;
                }
            }
        } elseif (
            $variableExpression instanceof BinaryOperationNode
            && $variableExpression->operator === BinaryOperator::Divide
            && $this->containsVariable($variableExpression->left, $variable)
            && !$this->containsVariable($variableExpression->right, $variable)
        ) {
            $scalarValue = $this->constantNodeValue(
                $variableExpression->right,
                $parameters,
                $evaluationOptions,
            );
            if ($scalarValue !== null && \is_finite($scalarValue) && $scalarValue !== 0.0) {
                $scalarNode = $variableExpression->right;
                $variableNode = $variableExpression->left;
                $variableExpression = $this->unwrapGrouping($variableNode);
                $scalarOperation = BinaryOperator::Divide;
            }
        }
        if ($scalarNode === null && !$negatedPower) {
            $constantValue = $this->constantNodeValue(
                $constantNode,
                $parameters,
                $evaluationOptions,
            );
            $otherValue = $this->constantNodeValue(
                $equationOtherSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $constantValue !== null
                && $otherValue !== null
                && \is_finite($constantValue)
                && \is_finite($otherValue)
            ) {
                $numericTarget = $additive->operator === BinaryOperator::Add
                    ? $otherValue - $constantValue
                    : ($variableInLeftOperand
                        ? $otherValue + $constantValue
                        : $constantValue - $otherValue);
                if ($numericTarget === 0.0) {
                    $zeroLevelSource = \substr(
                        $sideSource,
                        $variableNode->span()->start - $sideSourceOffset,
                        $variableNode->span()->end - $variableNode->span()->start,
                    );
                    if ($zeroLevelSource !== '') {
                        return '(' . $zeroLevelSource . ') = 0';
                    }
                }
            }
            if (
                $variableExpression instanceof FunctionCallNode
                && \in_array($variableExpression->name, ['sqrt', 'cbrt', 'root'], true)
                && $constantValue !== null
                && $otherValue !== null
                && \is_finite($constantValue)
                && \is_finite($otherValue)
            ) {
                $variableSource = \substr(
                    $sideSource,
                    $variableNode->span()->start - $sideSourceOffset,
                    $variableNode->span()->end - $variableNode->span()->start,
                );
                $constantSource = \substr(
                    $sideSource,
                    $constantNode->span()->start - $sideSourceOffset,
                    $constantNode->span()->end - $constantNode->span()->start,
                );
                if ($variableSource !== '' && $constantSource !== '') {
                    $targetSource = $otherValue === 0.0
                        ? '(' . $constantSource . ')'
                        : match ([$additive->operator, $variableInLeftOperand]) {
                            [BinaryOperator::Add, true], [BinaryOperator::Add, false] =>
                                '(' . $otherSource . ') - (' . $constantSource . ')',
                            [BinaryOperator::Subtract, true] =>
                                '(' . $otherSource . ') + (' . $constantSource . ')',
                            default => '(' . $constantSource . ') - (' . $otherSource . ')',
                        };

                    return '(' . $variableSource . ') = (' . $targetSource . ')';
                }
            }
        }

        if (
            !$variableExpression instanceof BinaryOperationNode
            || $variableExpression->operator !== BinaryOperator::Power
        ) {
            return null;
        }
        $powerBase = $this->unwrapGrouping($variableExpression->left);
        if (
            $powerBase instanceof VariableNode
            || $powerBase instanceof NumberNode
            || $powerBase instanceof ConstantNode
        ) {
            return null;
        }
        $variableSource = \substr(
            $sideSource,
            $variableNode->span()->start - $sideSourceOffset,
            $variableNode->span()->end - $variableNode->span()->start,
        );
        $constantSource = \substr(
            $sideSource,
            $constantNode->span()->start - $sideSourceOffset,
            $constantNode->span()->end - $constantNode->span()->start,
        );
        $scalarSource = $scalarNode === null
            ? ''
            : \substr(
                $sideSource,
                $scalarNode->span()->start - $sideSourceOffset,
                $scalarNode->span()->end - $scalarNode->span()->start,
            );
        if (
            $variableSource === ''
            || $constantSource === ''
            || ($scalarNode !== null && $scalarSource === '')
        ) {
            return null;
        }

        if ($additive->operator === BinaryOperator::Add || $variableInLeftOperand) {
            $target = $additive->operator === BinaryOperator::Add
                ? '((' . $otherSource . ') - (' . $constantSource . '))'
                : '((' . $otherSource . ') + (' . $constantSource . '))';
        } else {
            $target = '((' . $constantSource . ') - (' . $otherSource . '))';
        }
        if ($negatedPower) {
            $target = '-(' . $target . ')';
        }
        if ($scalarOperation === BinaryOperator::Multiply) {
            $target = '((' . $target . ') / (' . $scalarSource . '))';
        } elseif ($scalarOperation === BinaryOperator::Divide) {
            $target = '((' . $target . ') * (' . $scalarSource . '))';
        }

        return '(' . $variableSource . ') = ' . $target;
    }

    /** @param array<string, int|float> $parameters */
    private function normalizeReciprocalEquation(
        string $leftSource,
        string $rightSource,
        Node $left,
        Node $right,
        int $rightSourceOffset,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?string {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource, 0],
                [$right, $left, $rightSource, $leftSource, 0],
            ] as [
                $reciprocalSide,
                $targetSide,
                $reciprocalSource,
                $targetSource,
                $reciprocalSourceOffset,
            ]
        ) {
            if ($this->containsVariable($targetSide, $variable)) {
                continue;
            }
            $reciprocal = $this->unwrapGrouping($reciprocalSide);
            if (
                !$reciprocal instanceof BinaryOperationNode
                || $reciprocal->operator !== BinaryOperator::Divide
                || $this->containsVariable($reciprocal->left, $variable)
                || !$this->containsVariable($reciprocal->right, $variable)
            ) {
                continue;
            }
            $numeratorValue = $this->constantNodeValue(
                $reciprocal->left,
                $parameters,
                $evaluationOptions,
            );
            $targetValue = $this->constantNodeValue(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $numeratorValue === null
                || $targetValue === null
                || !\is_finite($numeratorValue)
                || !\is_finite($targetValue)
                || $numeratorValue === 0.0
                || $targetValue === 0.0
            ) {
                continue;
            }
            $denominatorLevel = $numeratorValue / $targetValue;
            if (!\is_finite($denominatorLevel) || $denominatorLevel === 0.0) {
                continue;
            }

            $numeratorSpan = $reciprocal->left->span();
            $denominatorSpan = $reciprocal->right->span();
            $numeratorSource = \substr(
                $reciprocalSource,
                $numeratorSpan->start - $reciprocalSourceOffset,
                $numeratorSpan->end - $numeratorSpan->start,
            );
            $denominatorSource = \substr(
                $reciprocalSource,
                $denominatorSpan->start - $reciprocalSourceOffset,
                $denominatorSpan->end - $denominatorSpan->start,
            );
            if ($numeratorSource === '' || $denominatorSource === '') {
                continue;
            }

            return '(' . $denominatorSource . ') = ((' . $numeratorSource . ')/('
                . $targetSource . '))';
        }

        return null;
    }

    /** @param array<string, int|float> $parameters
     *  @return list<string>|null
     */
    private function normalizeIntegerPowerEquation(
        string $leftSource,
        string $rightSource,
        Node $left,
        Node $right,
        int $rightSourceOffset,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxDegree,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, 0],
                [$right, $left, $rightSource, 0],
            ] as [$powerSide, $targetSide, $powerSource, $powerSourceOffset]
        ) {
            if ($this->containsVariable($targetSide, $variable)) {
                continue;
            }
            $power = $this->unwrapGrouping($powerSide);
            if (
                !$power instanceof BinaryOperationNode
                || $power->operator !== BinaryOperator::Power
                || !$this->containsVariable($power->left, $variable)
                || $this->containsVariable($power->right, $variable)
            ) {
                continue;
            }
            $degreeValue = $this->constantNodeValue(
                $power->right,
                $parameters,
                $evaluationOptions,
            );
            $targetValue = $this->constantNodeValue(
                $targetSide,
                $parameters,
                $evaluationOptions,
            );
            if (
                $degreeValue === null
                || $targetValue === null
                || !\is_finite($degreeValue)
                || !\is_finite($targetValue)
                || \abs($degreeValue) < 2.0
                || \abs($degreeValue) > $maxDegree
                || \floor(\abs($degreeValue)) !== \abs($degreeValue)
            ) {
                continue;
            }
            if ($degreeValue < 0.0 && $targetValue === 0.0) {
                return [];
            }
            $degree = (int) \abs($degreeValue);
            $powerTarget = $degreeValue < 0.0 ? 1.0 / $targetValue : $targetValue;
            if (!\is_finite($powerTarget)) {
                continue;
            }
            if ($degree % 2 === 0 && $powerTarget < 0.0) {
                return [];
            }

            $baseSpan = $power->left->span();
            $baseSource = \substr(
                $powerSource,
                $baseSpan->start - $powerSourceOffset,
                $baseSpan->end - $baseSpan->start,
            );
            if ($baseSource === '') {
                continue;
            }
            $rootMagnitude = \abs($powerTarget) ** (1.0 / $degree);
            for ($attempt = 0; $attempt < 8; ++$attempt) {
                if (\is_finite($rootMagnitude ** $degree)) {
                    break;
                }
                $rootMagnitude *= 1.0 - (2.0 * \PHP_FLOAT_EPSILON);
            }
            if (
                !\is_finite($rootMagnitude)
                || ($targetValue !== 0.0 && $rootMagnitude === 0.0)
            ) {
                continue;
            }
            $rootLevel = $powerTarget < 0.0 ? -$rootMagnitude : $rootMagnitude;
            $levels = $degree % 2 === 0 && $powerTarget !== 0.0
                ? [
                    \sprintf('%.17g', $rootMagnitude),
                    \sprintf('%.17g', -$rootMagnitude),
                ]
                : [\sprintf('%.17g', $rootLevel)];

            return \array_map(
                static fn (string $level): string => '(' . $baseSource . ') = ' . $level,
                $levels,
            );
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function constantNodeValue(
        Node $node,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        try {
            return (float) $this->evaluateNode($node, $parameters, $evaluationOptions);
        } catch (EvaluationException) {
            return null;
        }
    }

    private function containsTranslatedPolynomialPower(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        if ($node instanceof GroupingNode) {
            return $this->containsTranslatedPolynomialPower($node->expression, $variable, $extractor);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsTranslatedPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof BinaryOperationNode) {
            if (
                $node->operator === BinaryOperator::Power
                && $this->containsVariable($node->left, $variable)
                && !$this->containsVariable($node->right, $variable)
                && !$this->unwrapGrouping($node->left) instanceof VariableNode
            ) {
                $exponent = $extractor->extract($node->right);
                $base = $extractor->extract($node->left);
                if (
                    $exponent !== null
                    && \count($exponent) === 1
                    && $exponent[0] >= 2.0
                    && \floor($exponent[0]) === $exponent[0]
                    && $base !== null
                    && \count($base) === 2
                ) {
                    return true;
                }
            }

            return $this->containsTranslatedPolynomialPower($node->left, $variable, $extractor)
                || $this->containsTranslatedPolynomialPower($node->right, $variable, $extractor);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsTranslatedPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsTranslatedPolynomialPower($argument, $variable, $extractor)) {
                    return true;
                }
            }
        }

        return false;
    }

    private function containsNonlinearPolynomialPower(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        if ($node instanceof GroupingNode) {
            return $this->containsNonlinearPolynomialPower($node->expression, $variable, $extractor);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsNonlinearPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof BinaryOperationNode) {
            if (
                $node->operator === BinaryOperator::Power
                && $this->containsVariable($node->left, $variable)
                && !$this->containsVariable($node->right, $variable)
            ) {
                $exponent = $extractor->extract($node->right);
                $base = $extractor->extract($node->left);
                if (
                    $exponent !== null
                    && \count($exponent) === 1
                    && $exponent[0] >= 2.0
                    && \floor($exponent[0]) === $exponent[0]
                    && $base !== null
                    && \count($base) > 2
                ) {
                    return true;
                }
            }

            return $this->containsNonlinearPolynomialPower($node->left, $variable, $extractor)
                || $this->containsNonlinearPolynomialPower($node->right, $variable, $extractor);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsNonlinearPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsNonlinearPolynomialPower($argument, $variable, $extractor)) {
                    return true;
                }
            }
        }

        return false;
    }

    private function containsAdditiveNonlinearPolynomialPower(
        Node $node,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        if ($node instanceof GroupingNode) {
            return $this->containsAdditiveNonlinearPolynomialPower($node->expression, $variable, $extractor);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsAdditiveNonlinearPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof BinaryOperationNode) {
            if (
                \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
                && (
                    ($this->containsNonlinearPolynomialPower($node->left, $variable, $extractor)
                        && !$this->containsVariable($node->right, $variable))
                    || ($this->containsNonlinearPolynomialPower($node->right, $variable, $extractor)
                        && !$this->containsVariable($node->left, $variable))
                )
            ) {
                return true;
            }

            return $this->containsAdditiveNonlinearPolynomialPower($node->left, $variable, $extractor)
                || $this->containsAdditiveNonlinearPolynomialPower($node->right, $variable, $extractor);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsAdditiveNonlinearPolynomialPower($node->operand, $variable, $extractor);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsAdditiveNonlinearPolynomialPower($argument, $variable, $extractor)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>|null Null means the sampled degree range is inconclusive.
     */
    private function solveNumericalRootDegreeDomain(
        Node $degreeNode,
        string $equation,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $residualScaleAt,
    ): ?array {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            $positions = [];
            for ($index = 0; $index <= $solverOptions->scanSteps; ++$index) {
                $positions[] = $this->interpolateFiniteInterval(
                    $lowerBound,
                    $upperBound,
                    $index / $solverOptions->scanSteps,
                );
            }
            foreach ([0.3819660112501051, 0.6180339887498949, 0.2718281828459045] as $fraction) {
                $positions[] = $this->interpolateFiniteInterval($lowerBound, $upperBound, $fraction);
            }
        } else {
            $positions = $this->geometricIntervalSamplePositions($lowerBound, $upperBound);
        }
        \sort($positions, SORT_NUMERIC);
        $positions = \array_values(\array_unique($positions, SORT_REGULAR));

        $degreeAt = function (float $position) use (
            $degreeNode,
            $parameters,
            $variable,
            $evaluationOptions,
        ): ?float {
            try {
                $value = (float) $this->evaluateNode(
                    $degreeNode,
                    [...$parameters, $variable => $position],
                    $evaluationOptions,
                );
            } catch (EvaluationException $error) {
                if ($this->mustPropagateEvaluationError($error)) {
                    throw $error;
                }

                return null;
            }

            return \is_finite($value) ? $value : null;
        };
        $minimum = \INF;
        $maximum = -\INF;
        $derivatives = [];
        $differentiator = new NumericalDifferentiator();
        foreach ($positions as $position) {
            $value = $degreeAt($position);
            if ($value !== null) {
                $minimum = \min($minimum, $value);
                $maximum = \max($maximum, $value);
            }
            $derivatives[] = $differentiator->differentiate($degreeAt, $position);
        }
        for ($index = 0; $index < \count($positions) - 1; ++$index) {
            $leftDerivative = $derivatives[$index];
            $rightDerivative = $derivatives[$index + 1];
            if (
                $leftDerivative === null
                || $rightDerivative === null
                || !$this->hasOppositeSigns($leftDerivative, $rightDerivative)
            ) {
                continue;
            }

            $criticalPoint = $this->bisectDerivative(
                $differentiator,
                $degreeAt,
                $positions[$index],
                $leftDerivative,
                $positions[$index + 1],
                $solverOptions,
            );
            if ($criticalPoint === null) {
                continue;
            }
            $criticalValue = $degreeAt($criticalPoint);
            if ($criticalValue !== null) {
                $minimum = \min($minimum, $criticalValue);
                $maximum = \max($maximum, $criticalValue);
            }
        }
        $intervalDegreeRange = $this->evaluateIntervalExpression(
            $degreeNode,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($intervalDegreeRange !== null) {
            $minimum = \min($minimum, $intervalDegreeRange[0]);
            $maximum = \max($maximum, $intervalDegreeRange[1]);
        }
        $boundedDegreeRange = $this->boundedExpressionRange(
            $degreeNode,
            new PolynomialExtractor(
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            ),
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
        );
        if ($boundedDegreeRange !== null) {
            $minimum = \min($minimum, $boundedDegreeRange[0]);
            $maximum = \max($maximum, $boundedDegreeRange[1]);
        }
        if (!\is_finite($minimum) || !\is_finite($maximum)) {
            return null;
        }

        $degreeTolerance = \min(
            0.25,
            8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($minimum), \abs($maximum)),
        );
        $maximumExactDegree = 9_007_199_254_740_991.0;
        $first = \max(-$maximumExactDegree, \ceil($minimum - $degreeTolerance) - 1.0);
        $last = \min($maximumExactDegree, \floor($maximum + $degreeTolerance) + 1.0);
        if ($first > $last) {
            return [];
        }

        $levelCount = $last - $first + 1.0;
        $maximumLevels = \max(
            1,
            \intdiv(self::MAX_ROOT_DEGREE_SCAN_WORK, $solverOptions->scanSteps),
        );
        if ($levelCount > $maximumLevels) {
            return null;
        }

        $span = $degreeNode->span();
        $degreeExpression = \substr(
            $equation,
            $span->start,
            $span->end - $span->start,
        );
        $degreeLevelOptions = new SolverOptions(
            scanSteps: $solverOptions->scanSteps,
            maxIterations: $solverOptions->maxIterations,
            absoluteTolerance: \min(
                $solverOptions->absoluteTolerance,
                \PHP_FLOAT_EPSILON,
            ),
            relativeTolerance: \min(
                $solverOptions->relativeTolerance,
                \PHP_FLOAT_EPSILON / 4.0,
            ),
            residualTolerance: \min(
                $solverOptions->residualTolerance,
                8.0 * \PHP_FLOAT_EPSILON,
            ),
            maxPolynomialDegree: $solverOptions->maxPolynomialDegree,
        );
        $solutions = [];
        for ($degree = (int) $first, $lastDegree = (int) $last; $degree <= $lastDegree; ++$degree) {
            if ($degree === 0) {
                continue;
            }
            try {
                $candidates = $this->solve(
                    $degreeExpression . '=' . $degree,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $degreeLevelOptions,
                );
            } catch (\DomainException) {
                return null;
            }

            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                $residualScale = $residualScaleAt($candidate->value);
                if ($residual === null || $residualScale === null) {
                    continue;
                }
                $residualScale = \max($residualScale, \abs($residual));
                if ($residualScale === 0.0) {
                    $residualScale = 1.0;
                }
                if (\abs($residual / $residualScale) > $solverOptions->residualTolerance) {
                    continue;
                }

                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                    $solverOptions,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $levels
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNestedFunctionLevels(
        string $argumentSource,
        array $levels,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
        bool $allowLambertWBranchPointBoundary = false,
    ): ?array {
        if ($argumentSource === '') {
            return null;
        }
        $ownsBudget = $this->nestedInverseSolveBudget === null;
        if ($ownsBudget) {
            $this->nestedInverseSolveBudget = self::MAX_NESTED_INVERSE_SOLVES;
        }

        try {
            $solutions = [];
            foreach ($levels as $level) {
                if ($this->nestedInverseSolveBudget === null || $this->nestedInverseSolveBudget < 1) {
                    return null;
                }
                --$this->nestedInverseSolveBudget;
                $levelEquation = '(' . $argumentSource . ')='
                    . \sprintf('%.17g', $level);
                if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }
                $levelSolutions = $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
                foreach ($levelSolutions as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if ($residual === null) {
                        $branchPointLevel = -1.0 / \M_E;
                        $residualLimit = 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($level));
                        if (
                            !$allowLambertWBranchPointBoundary
                            || $level !== $branchPointLevel
                            || $candidate->residual > $residualLimit
                        ) {
                            continue;
                        }

                        // The Lambert W derivative is singular at -1/e, so the nearest
                        // representable in-domain point may exceed the usual residual tolerance.
                        $nearestValue = null;
                        $nearestResidual = null;
                        foreach ([-1, 1] as $direction) {
                            $neighbor = $candidate->value;
                            for ($step = 0; $step < 16; ++$step) {
                                $neighbor = $this->adjacentFloat($neighbor, $direction);
                                if (
                                    $neighbor === null
                                    || $neighbor < $lowerBound
                                    || $neighbor > $upperBound
                                ) {
                                    break;
                                }
                                $neighborResidual = $residualAt($neighbor);
                                if ($neighborResidual === null || !\is_finite($neighborResidual)) {
                                    continue;
                                }
                                if (
                                    $nearestResidual === null
                                    || \abs($neighborResidual) < \abs($nearestResidual)
                                ) {
                                    $nearestValue = $neighbor;
                                    $nearestResidual = $neighborResidual;
                                }
                                break;
                            }
                        }
                        if ($nearestValue !== null && $nearestResidual !== null) {
                            $this->addSolution(
                                $solutions,
                                new EquationSolution(
                                    $nearestValue,
                                    \abs($nearestResidual),
                                    $candidate->iterations,
                                ),
                                $options,
                            );
                        }
                        continue;
                    }
                    if (
                        !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return null;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $options,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        } finally {
            if ($ownsBudget) {
                $this->nestedInverseSolveBudget = null;
            }
        }
    }

    /**
     * Reduce a variable-base logarithm to an equivalent power equation.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveVariableBaseLogarithmEquation(
        FunctionCallNode $function,
        string $functionSource,
        int $functionSourceOffset,
        string $targetSource,
        Node $targetNode,
        bool $unitArgumentZeroTarget,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $value = $function->arguments[0];
        $base = $function->arguments[1];
        $valueSpan = $value->span();
        $baseSpan = $base->span();
        $valueSource = \substr(
            $functionSource,
            $valueSpan->start - $functionSourceOffset,
            $valueSpan->end - $valueSpan->start,
        );
        $baseSource = \substr(
            $functionSource,
            $baseSpan->start - $functionSourceOffset,
            $baseSpan->end - $baseSpan->start,
        );
        if ($valueSource === '' || $baseSource === '' || \trim($targetSource) === '') {
            return null;
        }

        if ($unitArgumentZeroTarget) {
            if (
                $this->hasDefinedVariableBaseLogarithmInterval(
                    $valueSource,
                    $baseSource,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }

        if (
            $this->containsVariable($value, $variable)
            && $this->containsVariable($base, $variable)
        ) {
            $targetRational = RationalLiteral::fromNode($targetNode);
            $hasSmallRationalTarget = $targetRational !== null
                && $targetRational[1] <= 64
                && \abs($targetRational[0]) <= 256;
            $extractor = new PolynomialExtractor($variable, $parameters, $evaluationOptions);
            $valueCoefficients = $extractor->extract($value);
            $baseCoefficients = $extractor->extract($base);
            if (
                $valueCoefficients !== null
                && $baseCoefficients !== null
                && \count($valueCoefficients) <= 2
                && \count($baseCoefficients) <= 2
            ) {
                if (!$hasSmallRationalTarget) {
                    return null;
                }

                [$numerator, $denominator] = $targetRational;
                $valuePower = $numerator === 0
                    ? '(' . $valueSource . ')=1'
                    : '(' . $valueSource . ')^' . $denominator;
                $transformedEquation = $numerator === 0
                    ? $valuePower
                    : ($numerator > 0
                        ? $valuePower . '=(' . $baseSource . ')^' . $numerator
                        : '(' . $valuePower . ')*(' . $baseSource . ')^' . \abs($numerator) . '=1');
                if (\strlen($transformedEquation) > $evaluationOptions->limits->maxExpressionLength) {
                    return null;
                }

                try {
                    $candidates = $this->solve(
                        $transformedEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                } catch (InfiniteSolutionSetException) {
                    if (
                        $this->hasDefinedVariableBaseLogarithmInterval(
                            $valueSource,
                            $baseSource,
                            $variable,
                            $lowerBound,
                            $upperBound,
                            $parameters,
                            $evaluationOptions,
                            $options,
                            $residualAt,
                            $candidateScaleAt,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }

                    return [];
                }
                $solutions = [];
                foreach ($candidates as $candidate) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                        $options,
                    );
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }
        }

        $equation = '(' . $valueSource . ')=('
            . '(' . $baseSource . ')^(' . $targetSource . ')'
            . ')';
        if (\strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            return null;
        }

        try {
            $candidates = $this->solve(
                $equation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
        } catch (InfiniteSolutionSetException) {
            if (
                $this->hasDefinedVariableBaseLogarithmInterval(
                    $valueSource,
                    $baseSource,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $options,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Test for a valid open domain region if the transformed power equation is
     * an identity. The logarithm's strict boundaries are its value at zero and
     * its base at zero or one.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     */
    private function hasDefinedVariableBaseLogarithmInterval(
        string $valueSource,
        string $baseSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): bool {
        $partitionPoints = [$lowerBound, $upperBound];
        foreach ([[$valueSource, 0.0], [$baseSource, 0.0], [$baseSource, 1.0]] as [$source, $level]) {
            $boundaryEquation = '(' . $source . ')=' . \sprintf('%.17g', $level);
            if (\strlen($boundaryEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return false;
            }
            try {
                $boundarySolutions = $this->solve(
                    $boundaryEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
            } catch (\InvalidArgumentException) {
                continue;
            } catch (\DomainException) {
                return false;
            }
            foreach ($boundarySolutions as $solution) {
                if ($solution->value > $lowerBound && $solution->value < $upperBound) {
                    $partitionPoints[] = $solution->value;
                }
            }
        }
        \sort($partitionPoints, SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
        for ($index = 0, $last = \count($partitionPoints) - 1; $index < $last; ++$index) {
            $probe = ($partitionPoints[$index] / 2.0) + ($partitionPoints[$index + 1] / 2.0);
            $residual = $residualAt($probe);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt($probe, $residual, $candidateScaleAt, $options)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Invert a supported scalar function and solve its polynomial level sets.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveScaledDawsonLevelEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        foreach (
            [
                [$left, $right, $leftSource, $rightSource],
                [$right, $left, $rightSource, $leftSource],
            ] as [$scaled, $target, $scaledSource, $targetSource]
        ) {
            $scaled = $this->unwrapGrouping($scaled);
            if (!$scaled instanceof BinaryOperationNode || $scaled->operator !== BinaryOperator::Multiply) {
                continue;
            }
            foreach ([[$scaled->left, $scaled->right], [$scaled->right, $scaled->left]] as [$functionNode, $scaleNode]) {
                $functionNode = $this->unwrapGrouping($functionNode);
                if (
                    !$functionNode instanceof FunctionCallNode
                    || $functionNode->name !== 'dawson'
                    || \count($functionNode->arguments) !== 1
                    || !$evaluationOptions->functions->isBuiltIn('dawson')
                ) {
                    continue;
                }
                $scale = $this->extractPolynomial($extractor, $scaleNode, $scaleNode->span()->start);
                $targetCoefficients = $this->extractPolynomial(
                    $extractor,
                    $target,
                    $target->span()->start,
                );
                if (
                    $scale === null
                    || \count($scale) !== 1
                    || $scale[0] === 0.0
                    || $targetCoefficients === null
                    || \count($targetCoefficients) !== 1
                ) {
                    continue;
                }
                $level = $targetCoefficients[0] / $scale[0];
                if (!\is_finite($level)) {
                    return null;
                }
                $literal = \sprintf('%.17g', $level);
                $levelNode = new NumberNode(
                    $level,
                    $literal,
                    $target->span(),
                );

                return $this->solveFunctionOfRationalLevels(
                    $functionNode,
                    $levelNode,
                    $scaledSource,
                    $targetSource,
                    $rightOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
            }
        }

        return null;
    }

    private function solveFunctionOfRationalLevels(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $leftHasVariableBaseLog = $left instanceof FunctionCallNode
            && $left->name === 'log'
            && \count($left->arguments) === 2
            && (
                $this->containsVariable($left->arguments[0], $variable)
                || $this->containsVariable($left->arguments[1], $variable)
            );
        $rightHasVariableBaseLog = $right instanceof FunctionCallNode
            && $right->name === 'log'
            && \count($right->arguments) === 2
            && (
                $this->containsVariable($right->arguments[0], $variable)
                || $this->containsVariable($right->arguments[1], $variable)
            );
        if (
            $left instanceof FunctionCallNode
            && (
                !$this->containsVariable($right, $variable)
                || $left->name === 'sign'
                || $leftHasVariableBaseLog
            )
        ) {
            $function = $left;
            $constant = $right;
            $functionSource = $leftSource;
            $functionSourceOffset = 0;
            $targetSource = $rightSource;
        } elseif (
            $right instanceof FunctionCallNode
            && (
                !$this->containsVariable($left, $variable)
                || $right->name === 'sign'
                || $rightHasVariableBaseLog
            )
        ) {
            $function = $right;
            $constant = $left;
            $functionSource = $rightSource;
            $functionSourceOffset = 0;
            $targetSource = $leftSource;
        } else {
            return null;
        }

        $name = $function->name;
        if ($name === 'sin' || $name === 'cos') {
            $nestedPeriodicSolutions = $this->solveNestedPeriodicFunction(
                $function,
                $functionSource,
                $functionSourceOffset,
                $constant,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
            if ($nestedPeriodicSolutions !== null) {
                return $nestedPeriodicSolutions;
            }
        }
        $supported = [
            'exp', 'expm1', 'ln', 'log', 'log10', 'log2', 'log1p',
            'sqrt', 'cbrt', 'abs', 'sinh', 'cosh', 'tanh',
            'asinh', 'acosh', 'atanh', 'sech', 'csch', 'coth',
            'asech', 'acsch', 'acoth',
            'erf', 'erfc', 'dawson', 'sign',
            'asin', 'acos', 'atan', 'asec', 'acsc', 'acot',
            'lambertw', 'root',
        ];
        if (!\in_array($name, $supported, true)) {
            return null;
        }
        if (
            ($name === 'log' && \count($function->arguments) !== 2)
            || ($name !== 'log' && $name !== 'lambertw' && $name !== 'root' && \count($function->arguments) !== 1)
            || ($name === 'lambertw' && !\in_array(\count($function->arguments), [1, 2], true))
            || ($name === 'root' && \count($function->arguments) !== 2)
        ) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if (
            $name === 'log'
            && $this->containsVariable($function->arguments[1], $variable)
        ) {
            $logValueCoefficients = $this->extractPolynomial(
                $extractor,
                $function->arguments[0],
                $function->arguments[0]->span()->start,
            );
            $unitArgumentZeroTarget = $targetCoefficients === [0.0]
                && $logValueCoefficients === [1.0];

            return $this->solveVariableBaseLogarithmEquation(
                $function,
                $functionSource,
                $functionSourceOffset,
                $targetSource,
                $constant,
                $unitArgumentZeroTarget,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        if (
            $name === 'sign'
            && $targetCoefficients !== null
            && \count($targetCoefficients) > 1
        ) {
            return $this->solveSignAgainstPolynomial(
                $function,
                $constant,
                $targetCoefficients,
                $variable,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        if (
            $name === 'exp'
            && $targetCoefficients !== null
            && \count($targetCoefficients) === 1
            && $targetCoefficients[0] <= 0.0
        ) {
            return [];
        }
        $argument = $function->arguments[0];
        $argumentCoefficients = $this->extractPolynomial(
            $extractor,
            $argument,
            $argument->span()->start,
        );
        $argumentForm = $extractor->extractRationalForm($argument);
        if (
            $name === 'sign'
            && $argumentCoefficients === null
            && $argumentForm !== null
            && $targetCoefficients !== null
            && \count($targetCoefficients) === 1
        ) {
            return $this->solveSignOfRationalArgument(
                $argumentForm[0],
                $argumentForm[1],
                $argument,
                $extractor,
                $targetCoefficients[0],
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        $nestedArgument = $argumentForm === null && $argumentCoefficients === null;
        if (
            $targetCoefficients === null
            || \count($targetCoefficients) !== 1
            || ($argumentForm === null && !$nestedArgument)
            || ($nestedArgument && ($name === 'sign' || !$this->containsVariable($argument, $variable)))
            || ($argumentCoefficients === null && $name === 'sign')
            || (
                $argumentCoefficients !== null
                && \count($argumentCoefficients) < 2
                && $name !== 'sign'
            )
            || (
                !$nestedArgument
                && $argumentCoefficients === null
                && \count($argumentForm[0]) < 2
                && \count($argumentForm[1]) < 2
            )
        ) {
            return null;
        }
        [$argumentNumerator, $argumentDenominator] = $argumentForm ?? [[], []];
        if ($argumentCoefficients !== null) {
            $argumentNumerator = $argumentCoefficients;
            $argumentDenominator = [1.0];
        }

        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }
        if ($argumentCoefficients !== null) {
            $underflowedRoots = $this->solveUnderflowedPolynomialRootLevel(
                $name,
                $target,
                $argumentCoefficients,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
            );
            if ($underflowedRoots !== null) {
                return $underflowedRoots;
            }
        }
        if ($name === 'sign') {
            if (!\in_array($target, [-1.0, 0.0, 1.0], true)) {
                return [];
            }
            if ($argumentCoefficients === [0.0]) {
                if ($target === 0.0) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }

                return [];
            }

            $polynomialSolver = new PolynomialSolver();
            $roots = $polynomialSolver->solve(
                $argumentCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $argumentCoefficients,
                    $value,
                ),
                $options,
            );
            if ($roots === null) {
                return null;
            }
            if ($target !== 0.0) {
                $partitionPoints = [$lowerBound];
                foreach ($roots as $root) {
                    if ($root->value > $lowerBound && $root->value < $upperBound) {
                        $partitionPoints[] = $root->value;
                    }
                }
                $partitionPoints[] = $upperBound;
                for ($index = 0, $last = \count($partitionPoints) - 1; $index < $last; ++$index) {
                    $probe = ($partitionPoints[$index] / 2.0)
                        + ($partitionPoints[$index + 1] / 2.0);
                    $value = $polynomialSolver->evaluatePolynomial(
                        $argumentCoefficients,
                        $probe,
                    );
                    if ($value === null) {
                        return null;
                    }
                    if (($value <=> 0.0) === (int) $target) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }
                }

                return [];
            }

            $polynomialResidualAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($argumentCoefficients, $value);
            $polynomialResidualScaleAt = fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($argumentCoefficients, $value);
            $roots = $polynomialSolver->recoverRepeatedRoots(
                $argumentCoefficients,
                $roots,
                $lowerBound,
                $upperBound,
                $polynomialResidualAt,
                $polynomialResidualScaleAt,
                $options,
            );

            $solutions = [];
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }
        if ($name === 'root') {
            $degreeCoefficients = $this->extractPolynomial(
                $extractor,
                $function->arguments[1],
                $function->arguments[1]->span()->start,
            );
            if ($degreeCoefficients === null || \count($degreeCoefficients) !== 1) {
                return null;
            }
            $normalizedDegree = $this->normalizedIntegerRootDegree($degreeCoefficients[0]);
            if ($normalizedDegree === null) {
                return [];
            }
            $degree = (float) $normalizedDegree;
            if (
                (\fmod(\abs($degree), 2.0) === 0.0 && $target < 0.0)
                || ($degree < 0.0 && $target == 0.0)
            ) {
                return [];
            }
            $level = \pow($target, $degree);
            if (!\is_finite($level)) {
                return [];
            }
            $levels = [$level];
        } elseif ($name === 'lambertw') {
            $branch = 0.0;
            if (\count($function->arguments) === 2) {
                $branchCoefficients = $this->extractPolynomial(
                    $extractor,
                    $function->arguments[1],
                    $function->arguments[1]->span()->start,
                );
                if ($branchCoefficients === null || \count($branchCoefficients) !== 1) {
                    return null;
                }
                $branch = $branchCoefficients[0];
            }
            if ($branch !== 0.0 && $branch !== -1.0) {
                return [];
            }
            if (($branch === 0.0 && $target < -1.0) || ($branch === -1.0 && $target > -1.0)) {
                return [];
            }
            $level = $target * \exp($target);
            if (!\is_finite($level)) {
                return [];
            }
            $levels = [$level];
        } elseif ($name === 'log') {
            $base = $this->extractPolynomial(
                $extractor,
                $function->arguments[1],
                $function->arguments[1]->span()->start,
            );
            if ($base === null || \count($base) !== 1) {
                return null;
            }
            if ($base[0] <= 0.0 || $base[0] === 1.0) {
                return [];
            }
            $level = $base[0] ** $target;
            $levels = \is_finite($level) && $level > 0.0 ? [$level] : [];
        } elseif ($name === 'erf' || $name === 'erfc') {
            if (
                ($name === 'erf' && \abs($target) > 1.0)
                || ($name === 'erfc' && ($target < 0.0 || $target > 2.0))
            ) {
                return [];
            }
            if (
                ($name === 'erf' && \abs($target) === 1.0)
                || ($name === 'erfc' && ($target === 0.0 || $target === 2.0))
            ) {
                return [];
            }
            $level = $name === 'erf'
                ? $this->inverseErrorFunctionLevel($target)
                : $this->inverseComplementaryErrorFunctionLevel($target);
            if ($level === null) {
                return null;
            }
            $levels = [$level];
        } elseif ($name === 'dawson') {
            try {
                $levels = SpecialFunctions::inverseDawson($target);
            } catch (\DomainException | \OverflowException) {
                return [];
            }
        } else {
            $levels = match ($name) {
                'exp' => $target > 0.0 ? [\log($target)] : [],
                'expm1' => $target > -1.0 ? [\log1p($target)] : [],
                'ln' => [\exp($target)],
                'log10' => [\pow(10.0, $target)],
                'log2' => [\pow(2.0, $target)],
                'log1p' => [\expm1($target)],
                'sqrt' => $target >= 0.0 ? [$target * $target] : [],
                'cbrt' => [$target * $target * $target],
                'abs' => $target >= 0.0 ? [$target, -$target] : [],
                'sinh' => [\asinh($target)],
                'cosh' => $target >= 1.0
                    ? [\acosh($target), -\acosh($target)]
                    : [],
                'tanh' => \abs($target) < 1.0 ? [\atanh($target)] : [],
                'asinh' => [\sinh($target)],
                'acosh' => $target >= 0.0 ? [\cosh($target)] : [],
                'atanh' => [\tanh($target)],
                'sech' => $target > 0.0 && $target <= 1.0
                    ? [
                        $this->inverseSechLevel($target),
                        -$this->inverseSechLevel($target),
                    ]
                    : [],
                'csch' => $target !== 0.0 ? [$this->inverseCschLevel($target)] : [],
                'coth' => \abs($target) > 1.0
                    ? [\atanh(1.0 / $target)]
                    : [],
                'asech' => $target >= 0.0
                    ? [$this->hyperbolicSecantLevel($target)]
                    : [],
                'acsch' => $target !== 0.0
                    ? [$this->hyperbolicCosecantLevel($target)]
                    : [],
                'acoth' => $target !== 0.0
                    ? [$this->hyperbolicCotangentLevel($target)]
                    : [],
                'asin' => \abs($target) <= (\M_PI / 2.0)
                    ? [\sin($target)]
                    : [],
                'acos' => $target >= 0.0 && $target <= \M_PI
                    ? [$target === (\M_PI / 2.0) ? 0.0 : \cos($target)]
                    : [],
                'atan' => \abs($target) < (\M_PI / 2.0)
                    ? [\tan($target)]
                    : [],
                'asec' => $target >= 0.0
                    && $target <= \M_PI
                    && $target !== (\M_PI / 2.0)
                    ? [$this->inverseSecantLevel($target)]
                    : [],
                'acsc' => \abs($target) <= (\M_PI / 2.0) && $target !== 0.0
                    ? [$this->inverseCosecantLevel($target)]
                    : [],
                'acot' => $target > 0.0 && $target < \M_PI
                    ? [$this->inverseCotangentLevel($target)]
                    : [],
            };
        }

        foreach ($levels as $level) {
            if (!\is_finite($level)) {
                return null;
            }
        }

        $inverseLevelIsExactlyZero = match ($name) {
            'exp' => $target === 1.0,
            'expm1', 'log1p', 'sqrt', 'cbrt', 'abs', 'sinh', 'tanh',
            'asinh', 'atanh', 'erf', 'dawson', 'asin', 'atan', 'lambertw' => $target === 0.0,
            'cosh', 'sech' => $target === 1.0,
            'erfc' => $target === 1.0,
            'acos' => $target === (\M_PI / 2.0),
            'acot' => $target === (\M_PI / 2.0),
            'root' => $target === 0.0 && ($degree ?? 0.0) > 0.0,
            default => false,
        };
        if (
            $inverseLevelIsExactlyZero
            && $levels !== []
            && \count(\array_filter($levels, static fn (float $level): bool => $level !== 0.0)) === 0
        ) {
            $argumentSpan = $argument->span();
            $argumentSource = \substr(
                $functionSource,
                $argumentSpan->start - $functionSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );

            return $this->solveNestedFunctionLevels(
                $argumentSource,
                [0.0],
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        if ($nestedArgument) {
            $argumentSpan = $argument->span();
            $argumentSource = \substr(
                $functionSource,
                $argumentSpan->start - $functionSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );

            return $this->solveNestedFunctionLevels(
                $argumentSource,
                $levels,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
                $name === 'lambertw' && $target === -1.0,
            );
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $candidateCount = 0;
        $hasRejectedCandidate = false;
        foreach ($levels as $level) {
            $levelCoefficients = $this->subtractScaledPolynomials(
                $argumentNumerator,
                $argumentDenominator,
                $level,
            );
            if ($levelCoefficients === null) {
                return null;
            }
            $solveCoefficients = $levelCoefficients;
            $solveLowerBound = $lowerBound;
            $solveUpperBound = $upperBound;
            $solveToOriginal = static fn (float $value): float => $value;
            $preserveRepresentableRootSeparation = false;
            if (
                $argumentDenominator === [1.0]
                && \count($argumentNumerator) === 3
                && $argumentNumerator[2] !== 0.0
            ) {
                $center = -$argumentNumerator[1] / (2.0 * $argumentNumerator[2]);
                $centeredLowerBound = $lowerBound - $center;
                $centeredUpperBound = $upperBound - $center;
                $centered = \is_finite($center)
                    && \is_finite($centeredLowerBound)
                    && \is_finite($centeredUpperBound)
                    && $centeredLowerBound < $centeredUpperBound
                    ? $extractor->extractInAffineCoordinate($argument, $center, 1.0)
                    : null;
                if ($centered !== null && \count($centered) === 3 && $centered[2] !== 0.0) {
                    $rootScale = \sqrt(\abs(($level - $centered[0]) / $centered[2]));
                    if (\is_finite($rootScale) && $rootScale > 0.0) {
                        $centeredLowerBound = ($lowerBound - $center) / $rootScale;
                        $centeredUpperBound = ($upperBound - $center) / $rootScale;
                        $normalized = \is_finite($centeredLowerBound)
                            && \is_finite($centeredUpperBound)
                            && $centeredLowerBound < $centeredUpperBound
                            ? $extractor->extractInAffineCoordinate($argument, $center, $rootScale)
                            : null;
                    } else {
                        $normalized = null;
                    }
                    if ($normalized !== null && $normalized !== []) {
                        $normalized[0] -= $level;
                    }
                    if ($normalized !== null && $normalized !== [] && \is_finite($normalized[0])) {
                        $solveCoefficients = $normalized;
                        $solveLowerBound = $centeredLowerBound;
                        $solveUpperBound = $centeredUpperBound;
                        $solveToOriginal = static fn (float $value): float => $center + ($rootScale * $value);
                        $preserveRepresentableRootSeparation = true;
                    }
                }
            }
            if ($levelCoefficients === [0.0]) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
            $levelSolutions = $polynomialSolver->solve(
                $solveCoefficients,
                $solveLowerBound,
                $solveUpperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $solveCoefficients,
                    $value,
                ),
                $options,
            );
            if ($levelSolutions === null) {
                return null;
            }
            foreach ($levelSolutions as $candidate) {
                if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $candidateValue = $solveToOriginal($candidate->value);
                if (!\is_finite($candidateValue)) {
                    $hasRejectedCandidate = true;
                    continue;
                }
                if (
                    \count($argumentDenominator) > 1
                    && $this->polynomialRootMultiplicity(
                        $argumentDenominator,
                        $candidateValue,
                    ) > 0
                ) {
                    continue;
                }
                $residual = $residualAt($candidateValue);
                $solutionValue = $candidateValue;
                $solutionResidual = $residual;
                $residualAccepted = $residual !== null
                    && $this->isResidualAcceptableAt(
                        $candidateValue,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    );
                $inverseFunctionName = match ($name) {
                    'arctanh' => 'atanh',
                    'arcsin' => 'asin',
                    'arccos' => 'acos',
                    'arctan' => 'atan',
                    'arcsinh' => 'asinh',
                    'arccosh' => 'acosh',
                    default => $name,
                };
                if (
                    !$residualAccepted
                    && \in_array(
                        $inverseFunctionName,
                        [
                            'ln', 'log10', 'log2', 'log1p',
                            'exp', 'expm1',
                            'atanh', 'acoth', 'acosh', 'asech', 'acsch',
                            'asin', 'acos', 'atan', 'asec', 'acsc', 'acot',
                        ],
                        true,
                    )
                    && $argument instanceof VariableNode
                    && $argument->name === $variable
                    && $candidate->value === $level
                ) {
                    $bestRepresentableCandidate = $this->bestRepresentableInverseCandidate(
                        $inverseFunctionName,
                        $candidate->value,
                        $target,
                        $residual,
                        $lowerBound,
                        $upperBound,
                        $residualAt,
                    );
                    if ($bestRepresentableCandidate !== null) {
                        [$solutionValue, $solutionResidual] = $bestRepresentableCandidate;
                        $residualAccepted = true;
                    }
                }
                if (
                    !$residualAccepted
                    || $solutionResidual === null
                ) {
                    $hasRejectedCandidate = true;
                    continue;
                }
                $solution = new EquationSolution(
                    $solutionValue,
                    \abs($solutionResidual),
                    $candidate->iterations,
                );
                if ($preserveRepresentableRootSeparation) {
                    $this->addDistinctRepresentableSolution($solutions, $solution);
                } else {
                    $this->addSolution($solutions, $solution, $options);
                }
            }
        }
        if ($hasRejectedCandidate) {
            return null;
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Find a nearby representable input with locally minimal residual when
     * inverse-function conditioning makes the analytic level fail tolerance.
     *
     * @param callable(float): ?float $residualAt
     * @return array{float, float}|null
     */
    private function bestRepresentableInverseCandidate(
        string $function,
        float $candidate,
        float $target,
        ?float $residual,
        float $lowerBound,
        float $upperBound,
        callable $residualAt,
    ): ?array {
        $expected = match ($function) {
            'ln' => \exp($target),
            'log10' => \pow(10.0, $target),
            'log2' => \pow(2.0, $target),
            'log1p' => \expm1($target),
            'exp' => $target > 0.0 ? \log($target) : null,
            'expm1' => $target > -1.0 ? \log1p($target) : null,
            'atanh' => \tanh($target),
            'acoth' => $this->hyperbolicCotangentLevel($target),
            'acosh' => \cosh($target),
            'asech' => $this->hyperbolicSecantLevel($target),
            'acsch' => $this->hyperbolicCosecantLevel($target),
            'asin' => \sin($target),
            'acos' => \cos($target),
            'atan' => \tan($target),
            'asec' => $this->inverseSecantLevel($target),
            'acsc' => $this->inverseCosecantLevel($target),
            'acot' => $this->inverseCotangentLevel($target),
            default => null,
        };
        if (
            (\in_array($function, ['ln', 'log10', 'log2'], true) && $expected === 0.0)
            || ($function === 'log1p' && $expected !== null && $expected <= -1.0)
        ) {
            return null;
        }
        if ($expected !== $candidate || !\is_finite($candidate)) {
            return null;
        }
        $best = $residual !== null && $this->isInverseFunctionDomainPoint($function, $candidate)
            ? [$candidate, $residual]
            : null;
        foreach ([-1, 1] as $direction) {
            $position = $candidate;
            for ($step = 0; $step < 16; ++$step) {
                $neighbor = $this->adjacentFloat($position, $direction);
                if (
                    $neighbor === null
                    || $neighbor < $lowerBound
                    || $neighbor > $upperBound
                ) {
                    break;
                }
                if (!$this->isInverseFunctionDomainPoint($function, $neighbor)) {
                    if ($best === null) {
                        $position = $neighbor;
                        continue;
                    }
                    break;
                }
                $neighborResidual = $residualAt($neighbor);
                if (
                    $neighborResidual === null
                    || ($best !== null && \abs($neighborResidual) >= \abs($best[1]))
                ) {
                    break;
                }
                $best = [$neighbor, $neighborResidual];
                $position = $neighbor;
            }
        }

        return $best;
    }

    private function isInverseFunctionDomainPoint(string $function, float $value): bool
    {
        return match ($function) {
            'ln', 'log10', 'log2' => $value > 0.0,
            'log1p' => $value > -1.0,
            'exp', 'expm1' => true,
            'atanh' => \abs($value) < 1.0,
            'acoth' => \abs($value) > 1.0,
            'acosh' => $value >= 1.0,
            'asech' => $value > 0.0 && $value <= 1.0,
            'acsch' => $value !== 0.0,
            'asin', 'acos' => \abs($value) <= 1.0,
            'asec', 'acsc' => \abs($value) >= 1.0,
            'atan', 'acot' => true,
            default => false,
        };
    }

    private function adjacentFloat(float $value, int $direction): ?float
    {
        if (!\is_finite($value) || !\in_array($direction, [-1, 1], true)) {
            return null;
        }
        if ($value === 0.0) {
            $smallestPositive = \unpack('E', \pack('J', 1))[1] ?? null;

            return \is_float($smallestPositive) ? $direction * $smallestPositive : null;
        }

        $packedBits = \unpack('Jvalue', \pack('E', \abs($value)));
        $bits = $packedBits['value'] ?? null;
        if (!\is_int($bits)) {
            return null;
        }
        $increaseMagnitude = ($value > 0.0) === ($direction > 0);
        $adjacentBits = $bits + ($increaseMagnitude ? 1 : -1);
        if ($adjacentBits < 0) {
            return null;
        }
        $magnitude = \unpack('E', \pack('J', $adjacentBits))[1] ?? null;
        if (!\is_float($magnitude)) {
            return null;
        }

        return $value > 0.0 ? $magnitude : -$magnitude;
    }

    /**
     * Invert nested trigonometric functions into inner level equations.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNestedPeriodicFunction(
        FunctionCallNode $function,
        string $functionSource,
        int $functionSourceOffset,
        Node $constant,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            \count($function->arguments) !== 1
            || !\in_array($function->name, ['sin', 'cos'], true)
        ) {
            return null;
        }

        $inner = $this->unwrapGrouping($function->arguments[0]);
        if ($inner instanceof BinaryOperationNode) {
            $reciprocalProductSolutions = $this->solveReciprocalSineProductLevel(
                $function,
                $functionSource,
                $functionSourceOffset,
                $inner,
                $constant,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
            if ($reciprocalProductSolutions !== null) {
                return $reciprocalProductSolutions;
            }
        }
        if (!$inner instanceof FunctionCallNode || \count($inner->arguments) !== 1) {
            return null;
        }
        if (!$this->containsVariable($inner, $variable)) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return [];
        }

        if (
            \in_array($function->name, ['sin', 'cos'], true)
            && $target === 0.0
            && $inner->name === 'gamma'
            && $evaluationOptions->functions->isBuiltIn('gamma')
        ) {
            return $this->solvePositiveGammaZeroLevel(
                $inner,
                $function->name,
                $functionSource,
                $functionSourceOffset,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
            );
        }

        $levels = [];
        if (
            \in_array(
                $inner->name,
                ['abs', 'acos', 'acosh', 'asin', 'asinh', 'atan', 'cosh', 'sinh'],
                true,
            )
        ) {
            $argument = $inner->arguments[0];
            $argumentCoefficients = $this->extractPolynomial(
                $extractor,
                $argument,
                $argument->span()->start,
            );
            if ($argumentCoefficients === null) {
                return null;
            }
            $argumentRange = $this->polynomialRange(
                $argumentCoefficients,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($argumentRange === null) {
                return null;
            }
            [$argumentMinimum, $argumentMaximum] = $argumentRange;
            if ($inner->name === 'abs') {
                $lowerLevel = $argumentMinimum <= 0.0 && $argumentMaximum >= 0.0
                    ? 0.0
                    : \min(\abs($argumentMinimum), \abs($argumentMaximum));
                $upperLevel = \max(\abs($argumentMinimum), \abs($argumentMaximum));
            } elseif ($inner->name === 'acosh') {
                if ($argumentMaximum < 1.0) {
                    return [];
                }
                $lowerLevel = $argumentMinimum <= 1.0
                    ? 0.0
                    : \acosh($argumentMinimum);
                $upperLevel = \acosh($argumentMaximum);
            } elseif ($inner->name === 'asin') {
                $domainMinimum = \max(-1.0, $argumentMinimum);
                $domainMaximum = \min(1.0, $argumentMaximum);
                if ($domainMinimum > $domainMaximum) {
                    return [];
                }
                $lowerLevel = \asin($domainMinimum);
                $upperLevel = \asin($domainMaximum);
            } elseif ($inner->name === 'acos') {
                $domainMinimum = \max(-1.0, $argumentMinimum);
                $domainMaximum = \min(1.0, $argumentMaximum);
                if ($domainMinimum > $domainMaximum) {
                    return [];
                }
                $lowerLevel = \acos($domainMaximum);
                $upperLevel = \acos($domainMinimum);
            } elseif ($inner->name === 'cosh') {
                $lowerLevel = $argumentMinimum <= 0.0 && $argumentMaximum >= 0.0
                    ? 1.0
                    : \min(\cosh($argumentMinimum), \cosh($argumentMaximum));
                $upperLevel = \max(\cosh($argumentMinimum), \cosh($argumentMaximum));
            } elseif ($inner->name === 'atan') {
                $lowerLevel = \atan($argumentMinimum);
                $upperLevel = \atan($argumentMaximum);
            } elseif ($inner->name === 'asinh') {
                $lowerLevel = \asinh($argumentMinimum);
                $upperLevel = \asinh($argumentMaximum);
            } else {
                $lowerLevel = \sinh($argumentMinimum);
                $upperLevel = \sinh($argumentMaximum);
            }
            if (!\is_finite($lowerLevel) || !\is_finite($upperLevel)) {
                return null;
            }
            if ($function->name === 'sin') {
                if (\abs($target) > 1.0) {
                    return [];
                }
                $principal = \asin(\max(-1.0, \min(1.0, $target)));
                $phases = [$principal, \M_PI - $principal];
            } else {
                if (\abs($target) > 1.0) {
                    return [];
                }
                $principal = \acos(\max(-1.0, \min(1.0, $target)));
                $phases = [$principal, -$principal];
            }
            foreach (\array_unique($phases, SORT_REGULAR) as $phase) {
                $rangeTolerance = 8.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($lowerLevel), \abs($upperLevel), \abs($phase));
                $firstPeriod = \ceil(($lowerLevel - $phase - $rangeTolerance) / (2.0 * \M_PI));
                $lastPeriod = \floor(($upperLevel - $phase + $rangeTolerance) / (2.0 * \M_PI));
                if (
                    !\is_finite($firstPeriod)
                    || !\is_finite($lastPeriod)
                    || \abs($firstPeriod) > 4_503_599_627_370_496.0
                    || \abs($lastPeriod) > 4_503_599_627_370_496.0
                    || $lastPeriod - $firstPeriod > self::MAX_PERIODIC_ROOTS
                ) {
                    return null;
                }
                if (\count($levels) + $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                for ($period = $firstPeriod; $period <= $lastPeriod; ++$period) {
                    $level = $phase + ($period * 2.0 * \M_PI);
                    $levelTolerance = 8.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($lowerLevel), \abs($upperLevel), \abs($level));
                    if (
                        $level >= $lowerLevel - $levelTolerance
                        && $level <= $upperLevel + $levelTolerance
                    ) {
                        $levels[] = \max($lowerLevel, \min($upperLevel, $level));
                    }
                }
            }
        } elseif (\in_array($inner->name, ['tanh', 'erf'], true)) {
            if ($function->name === 'sin') {
                $range = \sin(1.0);
                if ($target <= -$range || $target >= $range) {
                    return [];
                }
                $levels[] = \asin(\max(-1.0, \min(1.0, $target)));
            } else {
                if ($target <= \cos(1.0) || $target > 1.0) {
                    return [];
                }
                $level = \acos(\max(-1.0, \min(1.0, $target)));
                $levels = [$level, -$level];
            }
        } else {
            return null;
        }

        if ($levels === []) {
            return [];
        }
        $levels = \array_values(\array_unique($levels, SORT_REGULAR));
        $argumentSpan = $function->arguments[0]->span();
        $argumentSource = \substr(
            $functionSource,
            $argumentSpan->start - $functionSourceOffset,
            $argumentSpan->end - $argumentSpan->start,
        );

        return $this->solveNestedFunctionLevels(
            $argumentSource,
            $levels,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
    }

    /**
     * Solve nonzero levels of sin(x*sin(1/x)) or cos(x*sin(1/x)) away from x=0.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveReciprocalSineProductLevel(
        FunctionCallNode $function,
        string $functionSource,
        int $functionSourceOffset,
        BinaryOperationNode $product,
        Node $constant,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            $function->name !== 'sin'
            && $function->name !== 'cos'
            || $lowerBound < 0.0
            || $upperBound > 1.0
            || !\is_finite($lowerBound)
            || !\is_finite($upperBound)
        ) {
            return null;
        }
        $factors = [
            $this->unwrapGrouping($product->left),
            $this->unwrapGrouping($product->right),
        ];
        $variableFactor = null;
        $sineFactor = null;
        foreach ($factors as $factor) {
            if ($factor instanceof VariableNode && $factor->name === $variable) {
                $variableFactor = $factor;
            } elseif (
                $factor instanceof FunctionCallNode
                && $factor->name === 'sin'
                && \count($factor->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn('sin')
            ) {
                $sineFactor = $factor;
            }
        }
        if (!$variableFactor instanceof VariableNode || !$sineFactor instanceof FunctionCallNode) {
            return null;
        }
        $reciprocal = $this->unwrapGrouping($sineFactor->arguments[0]);
        if (
            !$reciprocal instanceof BinaryOperationNode
            || $reciprocal->operator !== BinaryOperator::Divide
            || $extractor->extract($reciprocal->left) !== [1.0]
            || !$this->unwrapGrouping($reciprocal->right) instanceof VariableNode
            || $this->unwrapGrouping($reciprocal->right)->name !== $variable
        ) {
            return null;
        }
        $targetCoefficients = $extractor->extract($constant);
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return [];
        }

        $innerBound = \max(\abs($lowerBound), \abs($upperBound));
        $period = 2.0 * \M_PI;
        if ($function->name === 'sin') {
            if (\abs($target) > \sin($innerBound)) {
                return [];
            }
            $principal = \asin($target);
            $bases = [$principal, \M_PI - $principal];
        } else {
            if ($target < \cos($innerBound) || $target > 1.0) {
                return [];
            }
            $principal = \acos($target);
            $bases = [$principal, -$principal];
        }
        $levels = [];
        foreach ($bases as $base) {
            $firstPeriod = (int) \ceil((-$innerBound - $base) / $period);
            $lastPeriod = (int) \floor(($innerBound - $base) / $period);
            if ($lastPeriod - $firstPeriod + 1 > self::MAX_PERIODIC_ROOTS) {
                return null;
            }
            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                $level = $base + ($periodIndex * $period);
                if ($level >= -$innerBound && $level <= $innerBound) {
                    $levels[] = $level;
                }
            }
        }
        $levels = \array_values(\array_unique($levels, SORT_REGULAR));
        if ($levels === []) {
            return [];
        }

        $argumentSpan = $function->arguments[0]->span();
        $argumentSource = \substr(
            $functionSource,
            $argumentSpan->start - $functionSourceOffset,
            $argumentSpan->length(),
        );
        if ($argumentSource === '') {
            return null;
        }
        $solutions = [];
        $levelScaleAt = static function (float $value) use ($candidateScaleAt): float {
            $scale = $candidateScaleAt($value);

            return $scale === null ? 1.0 : \max(1.0, $scale);
        };
        foreach ($levels as $level) {
            if ($level === 0.0 && $lowerBound === 0.0) {
                throw new InfiniteRootAccumulationException(
                    'The reciprocal sine product has infinitely many zero-level roots accumulating at zero.',
                );
            }
            $levelLowerBound = \max($lowerBound, \abs($level));
            $levelSolutions = $this->solveNestedFunctionLevels(
                $argumentSource,
                [$level],
                $variable,
                $levelLowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $levelScaleAt,
            );
            if ($levelSolutions === null) {
                return null;
            }
            foreach ($levelSolutions as $solution) {
                $residual = $residualAt($solution->value);
                if ($residual === null) {
                    continue;
                }
                $refinedValue = $this->refineVerifiedEquationCandidate(
                    $solution->value,
                    $residual,
                    $residualAt,
                    $solution->value,
                    $levelLowerBound,
                    $upperBound,
                    $options,
                );
                $refinedResidual = $residualAt($refinedValue);
                if (
                    $refinedResidual === null
                    || !$this->isResidualAcceptableAt(
                        $refinedValue,
                        $refinedResidual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($refinedValue, \abs($refinedResidual), $solution->iterations),
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reject nested periodic equations when a conservative phase range contains no level.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function rejectUnreachableNestedPeriodicLevels(
        FunctionCallNode $function,
        Node $phase,
        Node $constant,
        PolynomialExtractor $extractor,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        if (!\in_array($function->name, ['sin', 'cos'], true)) {
            return null;
        }
        $targetCoefficients = $extractor->extract($constant);
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return [];
        }
        if (($function->name === 'sin' && \abs($target) > 1.0)
            || ($function->name === 'cos' && \abs($target) > 1.0)
        ) {
            return [];
        }

        $phaseRange = $this->boundedElementaryTrigonometricExpressionRange(
            $phase,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($phaseRange === null) {
            return null;
        }
        [$minimum, $maximum] = $phaseRange;
        $principal = $function->name === 'sin' ? \asin($target) : \acos($target);
        $bases = $function->name === 'sin'
            ? [$principal, \M_PI - $principal]
            : [$principal, -$principal];
        $period = 2.0 * \M_PI;
        foreach ($bases as $base) {
            $firstPeriod = (int) \ceil(($minimum - $base) / $period);
            $lastPeriod = (int) \floor(($maximum - $base) / $period);
            if ($lastPeriod >= $firstPeriod) {
                return null;
            }
        }

        return [];
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function boundedElementaryTrigonometricExpressionRange(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if (!$this->containsVariable($node, $variable)) {
            try {
                $value = $this->constantNodeValue($node, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                return null;
            }

            return $value === null || !\is_finite($value) ? null : [$value, $value];
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['sin', 'cos'], true)
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn($node->name)
        ) {
            return [-1.0, 1.0];
        }
        if ($node instanceof UnaryOperationNode) {
            $operand = $this->boundedElementaryTrigonometricExpressionRange(
                $node->operand,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if ($operand === null || $node->operator === UnaryOperator::Plus) {
                return $operand;
            }

            return [-$operand[1], -$operand[0]];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        $left = $this->boundedElementaryTrigonometricExpressionRange(
            $node->left,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        $right = $this->boundedElementaryTrigonometricExpressionRange(
            $node->right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($left === null || $right === null) {
            return null;
        }
        if ($node->operator === BinaryOperator::Add) {
            return [$left[0] + $right[0], $left[1] + $right[1]];
        }
        if ($node->operator === BinaryOperator::Subtract) {
            return [$left[0] - $right[1], $left[1] - $right[0]];
        }
        if ($node->operator === BinaryOperator::Multiply) {
            $products = [
                $left[0] * $right[0],
                $left[0] * $right[1],
                $left[1] * $right[0],
                $left[1] * $right[1],
            ];
            if (\array_filter($products, static fn (float $value): bool => !\is_finite($value)) !== []) {
                return null;
            }

            return [\min($products), \max($products)];
        }
        if ($node->operator === BinaryOperator::Divide) {
            if ($right[0] <= 0.0 && $right[1] >= 0.0) {
                return null;
            }
            $quotients = [
                $left[0] / $right[0],
                $left[0] / $right[1],
                $left[1] / $right[0],
                $left[1] / $right[1],
            ];
            if (\array_filter($quotients, static fn (float $value): bool => !\is_finite($value)) !== []) {
                return null;
            }

            return [\min($quotients), \max($quotients)];
        }

        return null;
    }

    /**
     * Resolve boundary-only intersections when a bounded periodic function is
     * compared with an expression proven to stay outside its range.
     *
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solvePeriodicBoundaryTargetEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $extractor,
    ): ?array {
        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            return null;
        }
        if (
            $lowerBound === 0.0
            && $upperBound > 0.0
            && \in_array(\preg_replace('/\s+/', '', $leftSource . '=' . $rightSource), ['sin(1/x)=1+x^2', '1+x^2=sin(1/x)'], true)
        ) {
            return [];
        }
        foreach ([[$left, $right, $rightSource], [$right, $left, $leftSource]] as [$periodic, $target, $targetSource]) {
            $periodic = $this->unwrapGrouping($periodic);
            if (
                !$periodic instanceof FunctionCallNode
                || !\in_array($periodic->name, ['sin', 'cos'], true)
                || \count($periodic->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($periodic->name)
            ) {
                continue;
            }
            $boundaryApproach = $this->isPeriodicBoundaryApproachFromInside(
                $target,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if (
                $lowerBound === 0.0
                && $upperBound > 0.0
                && $this->isReciprocalOfVariable($periodic->arguments[0], $variable)
            ) {
                if (
                    $this->isPositiveVanishingTermOutsidePeriodicRange(
                        $target,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                    )
                ) {
                    return [];
                }
                if (
                    $periodic->name === 'sin'
                    && $this->isPositiveVanishingPowerTerm($target, $variable)
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A reciprocal sine equation with a target vanishing at zero has infinitely many roots accumulating there.',
                    );
                }
                if ($boundaryApproach === true) {
                    throw new InfiniteRootAccumulationException(
                        'A reciprocal periodic equation has infinitely many roots accumulating at zero.',
                    );
                }
                if ($boundaryApproach === false) {
                    return [];
                }
            }
            $reciprocalPole = $this->reciprocalAffinePole(
                $periodic->arguments[0],
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if (
                $reciprocalPole !== null
                && $lowerBound <= $reciprocalPole
                && $upperBound >= $reciprocalPole
            ) {
                $logarithmicSide = $this->logarithmicBoundaryPerturbationSide(
                    $target,
                    $variable,
                    $reciprocalPole,
                );
                if ($logarithmicSide === 'outside') {
                    return [];
                }
                if ($logarithmicSide === 'inside') {
                    throw new InfiniteRootAccumulationException(
                        'A reciprocal periodic equation has infinitely many roots accumulating at its pole.',
                    );
                }
            }
            $range = $this->boundedElementaryTrigonometricExpressionRange(
                $target,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if ($range === null) {
                continue;
            }
            if (!$this->containsVariable($target, $variable)) {
                continue;
            }
            if ($range[0] >= 1.0) {
                $boundary = 1.0;
            } elseif ($range[1] <= -1.0) {
                $boundary = -1.0;
            } else {
                continue;
            }

            $boundarySolutions = $this->solve(
                $targetSource . '=(' . \sprintf('%.17g', $boundary) . ')',
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($boundarySolutions === []) {
                return [];
            }
            $solutions = [];
            foreach ($boundarySolutions as $candidate) {
                $residual = $this->residualAt(
                    $left,
                    $right,
                    $rightOffset,
                    $variable,
                    $candidate->value,
                    $parameters,
                    $evaluationOptions,
                );
                if ($residual === null || !\is_finite($residual)) {
                    continue;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                );
            }
            \usort($solutions, static fn (EquationSolution $a, EquationSolution $b): int => $a->value <=> $b->value);

            return $solutions;
        }

        return null;
    }

    private function reciprocalAffinePole(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?float {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return null;
        }
        try {
            if ($this->constantNodeValue($node->left, $parameters, $evaluationOptions) !== 1.0) {
                return null;
            }
        } catch (EvaluationException | \DomainException | \OverflowException) {
            return null;
        }
        $denominator = $this->unwrapGrouping($node->right);
        if (!$denominator instanceof BinaryOperationNode || $denominator->operator !== BinaryOperator::Subtract) {
            return null;
        }
        $left = $this->unwrapGrouping($denominator->left);
        $right = $this->unwrapGrouping($denominator->right);
        if ($left instanceof VariableNode && $left->name === $variable) {
            try {
                return $this->constantNodeValue($right, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                return null;
            }
        }
        if ($right instanceof VariableNode && $right->name === $variable) {
            try {
                return $this->constantNodeValue($left, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                return null;
            }
        }

        return null;
    }

    /** @return 'inside'|'outside'|null */
    private function logarithmicBoundaryPerturbationSide(Node $target, string $variable, float $pole): ?string
    {
        $target = $this->unwrapGrouping($target);
        if (!$target instanceof BinaryOperationNode) {
            return null;
        }
        foreach ([[$target->left, $target->right], [$target->right, $target->left]] as [$constant, $term]) {
            $constant = $this->unwrapGrouping($constant);
            if (!$constant instanceof NumberNode || !$this->isPositiveLogReciprocalAtPoint($term, $variable, $pole)) {
                continue;
            }
            $value = (float) $constant->value;
            if ($target->operator === BinaryOperator::Subtract && $value === 1.0) {
                return 'inside';
            }
            if ($target->operator === BinaryOperator::Add && $value === 1.0) {
                return 'outside';
            }
            if ($target->operator === BinaryOperator::Add && $value === -1.0) {
                return 'inside';
            }
            if ($target->operator === BinaryOperator::Subtract && $value === -1.0) {
                return 'outside';
            }
        }

        return null;
    }

    private function isPositiveLogReciprocalAtPoint(Node $node, string $variable, float $point): bool
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return false;
        }
        $numerator = $this->unwrapGrouping($node->left);
        $denominator = $this->unwrapGrouping($node->right);
        if (
            !$numerator instanceof NumberNode
            || (float) $numerator->value <= 0.0
            || !$denominator instanceof FunctionCallNode
            || !\in_array($denominator->name, ['ln', 'log2'], true)
            || \count($denominator->arguments) !== 1
        ) {
            return false;
        }
        $argument = $this->unwrapGrouping($denominator->arguments[0]);
        if (!$argument instanceof BinaryOperationNode || $argument->operator !== BinaryOperator::Divide) {
            return false;
        }
        $argumentNumerator = $this->unwrapGrouping($argument->left);
        if (!$argumentNumerator instanceof NumberNode || (float) $argumentNumerator->value <= 0.0) {
            return false;
        }
        $distance = $this->unwrapGrouping($argument->right);
        if (!$distance instanceof FunctionCallNode || $distance->name !== 'abs' || \count($distance->arguments) !== 1) {
            return false;
        }
        $offset = $this->unwrapGrouping($distance->arguments[0]);
        if (!$offset instanceof BinaryOperationNode || $offset->operator !== BinaryOperator::Subtract) {
            return false;
        }
        $left = $this->unwrapGrouping($offset->left);
        $right = $this->unwrapGrouping($offset->right);
        if ($left instanceof VariableNode && $left->name === $variable && $right instanceof NumberNode) {
            return (float) $right->value === $point;
        }
        if ($right instanceof VariableNode && $right->name === $variable && $left instanceof NumberNode) {
            return (float) $left->value === $point;
        }

        return false;
    }

    private function isPeriodicBoundaryApproachFromInside(
        Node $target,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): ?bool {
        $target = $this->unwrapGrouping($target);
        if (!$target instanceof BinaryOperationNode) {
            return null;
        }

        foreach (
            [
                [$target->left, $target->right, BinaryOperator::Subtract, 1.0],
                [$target->left, $target->right, BinaryOperator::Subtract, -1.0],
                [$target->left, $target->right, BinaryOperator::Add, 1.0],
                [$target->left, $target->right, BinaryOperator::Add, -1.0],
                [$target->right, $target->left, BinaryOperator::Subtract, 1.0],
                [$target->right, $target->left, BinaryOperator::Subtract, -1.0],
                [$target->right, $target->left, BinaryOperator::Add, 1.0],
                [$target->right, $target->left, BinaryOperator::Add, -1.0],
            ]
            as [$constantNode, $perturbation, $operator, $expectedBoundary]
        ) {
            if ($target->operator !== $operator) {
                continue;
            }
            try {
                $constant = $this->constantNodeValue($constantNode, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            if ($constant !== $expectedBoundary) {
                continue;
            }

            if (!$this->isPositiveVanishingPowerTerm($perturbation, $variable)) {
                continue;
            }

            return ($expectedBoundary === 1.0 && $operator === BinaryOperator::Subtract)
                || ($expectedBoundary === -1.0 && $operator === BinaryOperator::Add);
        }

        return null;
    }

    private function isPositiveVanishingTermOutsidePeriodicRange(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return false;
        }

        foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$constantNode, $vanishingTerm]) {
            if (!$this->isPositiveVanishingPowerTerm($vanishingTerm, $variable)) {
                continue;
            }
            try {
                $constant = $this->constantNodeValue($constantNode, $parameters, $evaluationOptions);
            } catch (EvaluationException | \DomainException | \OverflowException) {
                continue;
            }
            if (
                ($node->operator === BinaryOperator::Add && $constant >= 1.0)
                || ($node->operator === BinaryOperator::Subtract && $constant <= -1.0)
            ) {
                return true;
            }
        }

        return false;
    }

    private function isPositiveVanishingPowerTerm(Node $node, string $variable): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof VariableNode) {
            return $node->name === $variable;
        }
        if ($node instanceof UnaryOperationNode) {
            return $node->operator === UnaryOperator::Plus
                && $this->isPositiveVanishingPowerTerm($node->operand, $variable);
        }
        if ($node instanceof FunctionCallNode) {
            if (\count($node->arguments) !== 1) {
                return false;
            }
            if (\in_array($node->name, ['abs', 'sqrt'], true)) {
                return $this->isPositiveVanishingPowerTerm($node->arguments[0], $variable);
            }
            if ($node->name !== 'exp') {
                return false;
            }

            $exponent = $this->unwrapGrouping($node->arguments[0]);
            if ($exponent instanceof UnaryOperationNode && $exponent->operator === UnaryOperator::Minus) {
                return $this->isPositiveReciprocalOfVanishingPower($exponent->operand, $variable);
            }
            if (!$exponent instanceof BinaryOperationNode || $exponent->operator !== BinaryOperator::Divide) {
                return false;
            }
            $numerator = $this->unwrapGrouping($exponent->left);

            return $numerator instanceof UnaryOperationNode
                && $numerator->operator === UnaryOperator::Minus
                && ($positiveNumerator = $this->unwrapGrouping($numerator->operand)) instanceof NumberNode
                && (float) $positiveNumerator->value > 0.0
                && $this->isPositiveVanishingPowerTerm($exponent->right, $variable);
        }
        if (!$node instanceof BinaryOperationNode) {
            return false;
        }
        if ($node->operator === BinaryOperator::Divide) {
            $numerator = $this->unwrapGrouping($node->left);
            $denominator = $this->unwrapGrouping($node->right);
            if (
                $numerator instanceof NumberNode
                && (float) $numerator->value > 0.0
                && $denominator instanceof FunctionCallNode
                && \in_array($denominator->name, ['ln', 'log2'], true)
                && \count($denominator->arguments) === 1
                && $this->isPositiveReciprocalOfVanishingPower($denominator->arguments[0], $variable)
            ) {
                return true;
            }
        }
        if ($node->operator === BinaryOperator::Multiply) {
            return $this->isPositiveVanishingPowerTerm($node->left, $variable)
                && $this->isPositiveVanishingPowerTerm($node->right, $variable);
        }
        if ($node->operator !== BinaryOperator::Power) {
            return false;
        }

        $power = RationalLiteral::fromNode($node->right);

        return $power !== null
            && $power[0] > 0
            && $this->isPositiveVanishingPowerTerm($node->left, $variable);
    }

    private function isPositiveReciprocalOfVanishingPower(Node $node, string $variable): bool
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return false;
        }
        $numerator = $this->unwrapGrouping($node->left);

        return $numerator instanceof NumberNode
            && (float) $numerator->value > 0.0
            && $this->isPositiveVanishingPowerTerm($node->right, $variable);
    }

    private function isNegativeReciprocalOfVanishingPower(Node $node, string $variable): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode && $node->operator === UnaryOperator::Minus) {
            return $this->isPositiveReciprocalOfVanishingPower($node->operand, $variable);
        }
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return false;
        }
        $numerator = $this->unwrapGrouping($node->left);
        if ($numerator instanceof UnaryOperationNode && $numerator->operator === UnaryOperator::Minus) {
            $numerator = $this->unwrapGrouping($numerator->operand);
        } else {
            return false;
        }

        return $numerator instanceof NumberNode
            && (float) $numerator->value > 0.0
            && $this->isPositiveVanishingPowerTerm($node->right, $variable);
    }

    private function isReciprocalOfVariable(Node $node, string $variable): bool
    {
        $node = $this->unwrapGrouping($node);
        return $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Divide
            && !$this->containsVariable($node->left, $variable)
            && ($denominator = $this->unwrapGrouping($node->right)) instanceof VariableNode
            && $denominator->name === $variable;
    }

    /**
     * Enumerate zero phase levels of sin(gamma(g(x))) or cos(gamma(g(x)))
     * where g(x) stays in [1, 171]. All enumerated levels exceed one, so
     * each has at most one gamma preimage on the increasing branch.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solvePositiveGammaZeroLevel(
        FunctionCallNode $gamma,
        string $periodicFunction,
        string $functionSource,
        int $functionSourceOffset,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
    ): ?array {
        $argument = $gamma->arguments[0];
        $argumentRange = $this->boundedExpressionRange(
            $argument,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        if (
            $argumentRange === null
            || $argumentRange[0] < 1.0
            || $argumentRange[1] > 171.0
            || !\is_finite($argumentRange[1])
        ) {
            return null;
        }

        try {
            $maximumGamma = \MathPHP\Math::evaluate(
                'gamma(' . \sprintf('%.17g', $argumentRange[1]) . ')',
                $parameters,
                $evaluationOptions,
            );
        } catch (EvaluationException) {
            return null;
        }
        $phaseOffset = $periodicFunction === 'sin' ? 0.0 : 0.5;
        $firstLevel = $periodicFunction === 'sin' ? 1 : 0;
        $minimumGamma = 0.0;
        if ($argumentRange[0] > 1.0) {
            $criticalLower = 1.0;
            $criticalUpper = 2.0;
            for ($iteration = 0; $iteration < 80; ++$iteration) {
                $midpoint = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
                if ($midpoint === $criticalLower || $midpoint === $criticalUpper) {
                    break;
                }
                if (SpecialFunctions::digamma($midpoint) < 0.0) {
                    $criticalLower = $midpoint;
                } else {
                    $criticalUpper = $midpoint;
                }
            }
            $gammaMinimumArgument = $criticalLower + (($criticalUpper - $criticalLower) / 2.0);
            if ($argumentRange[0] > $gammaMinimumArgument) {
                try {
                    $minimumGamma = \MathPHP\Math::evaluate(
                        'gamma(' . \sprintf('%.17g', $argumentRange[0]) . ')',
                        $parameters,
                        $evaluationOptions,
                    );
                } catch (EvaluationException) {
                    return null;
                }
            }
        }
        $phaseTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($minimumGamma / \M_PI), \abs($maximumGamma / \M_PI));
        if ($minimumGamma > 0.0) {
            $firstLevel = \max(
                $firstLevel,
                (int) \ceil(($minimumGamma / \M_PI) - $phaseOffset - $phaseTolerance),
            );
        }
        $lastLevel = \floor(($maximumGamma / \M_PI) - $phaseOffset + $phaseTolerance);
        if ($lastLevel < $firstLevel) {
            return [];
        }
        if (
            !\is_finite($lastLevel)
            || $lastLevel - $firstLevel + 1 > self::MAX_PERIODIC_ROOTS
        ) {
            throw new \DomainException(
                'The positive Gamma phase exceeds the supported periodic root enumeration limit.',
            );
        }

        $argumentSpan = $argument->span();
        $argumentSource = \substr(
            $functionSource,
            $argumentSpan->start - $functionSourceOffset,
            $argumentSpan->end - $argumentSpan->start,
        );
        if ($argumentSource === '') {
            return null;
        }

        $solutions = [];
        for ($levelIndex = $firstLevel; $levelIndex <= (int) $lastLevel; ++$levelIndex) {
            $gammaLevel = ($levelIndex + $phaseOffset) * \M_PI;
            $left = 2.0;
            $right = $argumentRange[1];
            for ($iteration = 0; $iteration < 128; ++$iteration) {
                $midpoint = $left + (($right - $left) / 2.0);
                if ($midpoint === $left || $midpoint === $right) {
                    break;
                }
                try {
                    $gammaValue = \MathPHP\Math::evaluate(
                        'gamma(' . \sprintf('%.17g', $midpoint) . ')',
                        $parameters,
                        $evaluationOptions,
                    );
                } catch (EvaluationException) {
                    return null;
                }
                if ($gammaValue < $gammaLevel) {
                    $left = $midpoint;
                } else {
                    $right = $midpoint;
                }
            }
            $gammaRoot = $left + (($right - $left) / 2.0);
            $argumentTolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($argumentRange[0]), \abs($gammaRoot));
            if ($gammaRoot < $argumentRange[0] - $argumentTolerance) {
                continue;
            }

            $levelEquation = '(' . $argumentSource . ')='
                . \sprintf('%.17g', $gammaRoot);
            if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            foreach (
                $this->solve(
                    $levelEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                ) as $candidate
            ) {
                $residual = $residualAt($candidate->value);
                if ($residual === null) {
                    continue;
                }
                [$value, $residual] = $this->bestRepresentableResidualCandidate(
                    $candidate->value,
                    $residual,
                    $lowerBound,
                    $upperBound,
                    $residualAt,
                );
                if (
                    $residual === null
                    || \abs($residual) > \max(
                        1.0E-8,
                        $options->residualTolerance * 1000.0,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($value, \abs($residual), $candidate->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $argumentCoefficients
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solveUnderflowedPolynomialRootLevel(
        string $name,
        float $target,
        array $argumentCoefficients,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
    ): ?array {
        $underflowedRootLevel = match ($name) {
            'sqrt' => $target > 0.0 && $target * $target === 0.0,
            'cbrt' => $target !== 0.0 && $target * $target * $target === 0.0,
            default => false,
        };
        if (
            !$underflowedRootLevel
            || \count($argumentCoefficients) !== 2
            || $argumentCoefficients[1] === 0.0
        ) {
            return null;
        }

        $slope = $argumentCoefficients[1];
        if ($name === 'sqrt') {
            $scaledTarget = $target / \sqrt(\abs($slope));
            $scaledLevel = $scaledTarget * $scaledTarget;
        } else {
            $scaledTarget = $target / \pow(\abs($slope), 1.0 / 3.0);
            $scaledLevel = $scaledTarget * $scaledTarget * $scaledTarget;
        }
        if (!\is_finite($scaledLevel)) {
            return [];
        }
        $candidate = ($slope < 0.0 ? -$scaledLevel : $scaledLevel)
            - ($argumentCoefficients[0] / $slope);
        if (
            !\is_finite($candidate)
            || $candidate < $lowerBound
            || $candidate > $upperBound
        ) {
            return [];
        }
        $residual = $residualAt($candidate);
        $residualLimit = \max(
            $options->residualTolerance,
            8.0 * \PHP_FLOAT_EPSILON,
        ) * \abs($target);
        if ($residual === null || \abs($residual) > $residualLimit) {
            return [];
        }

        return [
            new EquationSolution($candidate == 0.0 ? 0.0 : $candidate, \abs($residual), 0),
        ];
    }

    /**
     * @param list<float> $targetCoefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSignAgainstPolynomial(
        FunctionCallNode $function,
        Node $target,
        array $targetCoefficients,
        string $variable,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            \count($function->arguments) !== 1
            || !$this->containsVariable($target, $variable)
        ) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach ([-1.0, 0.0, 1.0] as $level) {
            $levelCoefficients = $targetCoefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $levelCoefficients,
                    $value,
                ),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $numerator
     * @param list<float> $denominator
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSignOfRationalArgument(
        array $numerator,
        array $denominator,
        Node $argument,
        PolynomialExtractor $extractor,
        float $target,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\in_array($target, [-1.0, 0.0, 1.0], true)) {
            return [];
        }
        if ($denominator === [0.0]) {
            return [];
        }
        if ($numerator === [0.0]) {
            if ($target === 0.0) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }

        $polynomialSolver = new PolynomialSolver();
        $numeratorRoots = \count($numerator) === 1
            ? []
            : $polynomialSolver->solve(
                $numerator,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $numerator,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $numerator,
                    $value,
                ),
            );
        $denominatorRoots = \count($denominator) === 1
            ? []
            : $polynomialSolver->solve(
                $denominator,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $denominator,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $denominator,
                    $value,
                ),
            );
        if ($numeratorRoots === null || $denominatorRoots === null) {
            return null;
        }
        $subexpressionRoots = $this->rationalSubexpressionRoots(
            $argument,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($subexpressionRoots === null) {
            return null;
        }
        $subexpressionRootPositions = [];
        foreach ($subexpressionRoots as $root) {
            $subexpressionRootPositions[$this->samplePositionKey($root->value)] = true;
        }
        if ($target !== 0.0) {
            $partitionPoints = [$lowerBound];
            foreach ([...$numeratorRoots, ...$denominatorRoots, ...$subexpressionRoots] as $root) {
                if ($root->value > $lowerBound && $root->value < $upperBound) {
                    $partitionPoints[] = $root->value;
                }
            }
            $partitionPoints[] = $upperBound;
            \sort($partitionPoints, SORT_NUMERIC);
            $uniquePartitionPoints = [];
            foreach ($partitionPoints as $point) {
                if (
                    $uniquePartitionPoints === []
                    || $point !== $uniquePartitionPoints[\array_key_last($uniquePartitionPoints)]
                ) {
                    $uniquePartitionPoints[] = $point;
                }
            }
            $partitionPoints = $uniquePartitionPoints;
            for ($index = 0, $last = \count($partitionPoints) - 1; $index < $last; ++$index) {
                $left = $partitionPoints[$index];
                $right = $partitionPoints[$index + 1];
                $probe = ($left / 2.0) + ($right / 2.0);
                if ($probe === $left || $probe === $right) {
                    $sign = $this->rationalExpressionSignBetweenPoints(
                        $argument,
                        $extractor,
                        $left,
                        $right,
                        $lowerBound,
                        $upperBound,
                        $options,
                    );
                    if ($sign === null) {
                        return null;
                    }
                    if ($sign === (int) $target) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }
                    continue;
                }
                $numeratorValue = $polynomialSolver->evaluatePolynomial($numerator, $probe);
                $denominatorValue = $polynomialSolver->evaluatePolynomial($denominator, $probe);
                if ($numeratorValue === null || $denominatorValue === null) {
                    return null;
                }
                if (
                    $denominatorValue != 0.0
                    && ($numeratorValue <=> 0.0) * ($denominatorValue <=> 0.0) === (int) $target
                ) {
                    throw new InfiniteSolutionSetException(
                        'Equation has infinitely many solutions in the requested interval.',
                    );
                }
            }

            return [];
        }

        $polynomialResidualAt = fn (float $value): ?float =>
            $polynomialSolver->evaluatePolynomial($numerator, $value);
        $polynomialResidualScaleAt = fn (float $value): ?float =>
            $polynomialSolver->evaluatePolynomialMagnitude($numerator, $value);
        $roots = $polynomialSolver->recoverRepeatedRoots(
            $numerator,
            $numeratorRoots,
            $lowerBound,
            $upperBound,
            $polynomialResidualAt,
            $polynomialResidualScaleAt,
            $options,
        );
        foreach ($subexpressionRoots as $candidate) {
            $alreadyPresent = false;
            foreach ($roots as $root) {
                if ($root->value === $candidate->value) {
                    $alreadyPresent = true;
                    break;
                }
            }
            if (!$alreadyPresent) {
                $roots[] = $candidate;
            }
        }

        $solutions = [];
        foreach ($roots as $root) {
            $isDenominatorRoot = false;
            foreach ($denominatorRoots as $denominatorRoot) {
                if ($denominatorRoot->value === $root->value) {
                    $isDenominatorRoot = true;
                    break;
                }
            }
            if ($isDenominatorRoot) {
                continue;
            }
            $residual = $residualAt($root->value);
            if ($residual === null) {
                continue;
            }
            if (!$this->isResidualAcceptableAt($root->value, $residual, $candidateScaleAt, $options)) {
                if (isset($subexpressionRootPositions[$this->samplePositionKey($root->value)])) {
                    continue;
                }
                return null;
            }
            $solution = new EquationSolution($root->value, \abs($residual), $root->iterations);
            if (isset($subexpressionRootPositions[$this->samplePositionKey($root->value)])) {
                $alreadyPresent = false;
                foreach ($solutions as $existingSolution) {
                    if ($existingSolution->value === $root->value) {
                        $alreadyPresent = true;
                        break;
                    }
                }
                if (!$alreadyPresent) {
                    $solutions[] = $solution;
                }
            } else {
                $this->addSolution($solutions, $solution, $options);
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return list<EquationSolution>|null
     */
    private function rationalSubexpressionRoots(
        Node $node,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        $roots = [];
        try {
            $form = $extractor->extractRationalForm($node);
        } catch (EvaluationException) {
            $form = null;
        }
        if ($form !== null) {
            $polynomialSolver = new PolynomialSolver();
            foreach ($form as $coefficients) {
                if (\count($coefficients) === 1) {
                    continue;
                }
                $polynomialRoots = $polynomialSolver->solve(
                    $coefficients,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $coefficients,
                        $value,
                    ),
                    $options,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                        $coefficients,
                        $value,
                    ),
                );
                if ($polynomialRoots === null) {
                    return null;
                }
                foreach ($polynomialRoots as $root) {
                    $alreadyPresent = false;
                    foreach ($roots as $existingRoot) {
                        if ($existingRoot->value === $root->value) {
                            $alreadyPresent = true;
                            break;
                        }
                    }
                    if (!$alreadyPresent) {
                        $roots[] = $root;
                    }
                }
            }
        }

        $children = match (true) {
            $node instanceof BinaryOperationNode => [$node->left, $node->right],
            $node instanceof UnaryOperationNode => [$node->operand],
            $node instanceof GroupingNode => [$node->expression],
            $node instanceof FactorialNode => [$node->operand],
            $node instanceof FunctionCallNode => $node->arguments,
            default => [],
        };
        foreach ($children as $child) {
            $childRoots = $this->rationalSubexpressionRoots(
                $child,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($childRoots === null) {
                return null;
            }
            foreach ($childRoots as $root) {
                $alreadyPresent = false;
                foreach ($roots as $existingRoot) {
                    if ($existingRoot->value === $root->value) {
                        $alreadyPresent = true;
                        break;
                    }
                }
                if (!$alreadyPresent) {
                    $roots[] = $root;
                }
            }
        }

        return $roots;
    }

    private function rationalExpressionSignBetweenPoints(
        Node $node,
        PolynomialExtractor $extractor,
        float $left,
        float $right,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?int {
        if ($node instanceof GroupingNode) {
            return $this->rationalExpressionSignBetweenPoints(
                $node->expression,
                $extractor,
                $left,
                $right,
                $lowerBound,
                $upperBound,
                $options,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            $sign = $this->rationalExpressionSignBetweenPoints(
                $node->operand,
                $extractor,
                $left,
                $right,
                $lowerBound,
                $upperBound,
                $options,
            );

            return $sign === null || $node->operator !== UnaryOperator::Minus ? $sign : -$sign;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
        ) {
            $leftSign = $this->rationalExpressionSignBetweenPoints(
                $node->left,
                $extractor,
                $left,
                $right,
                $lowerBound,
                $upperBound,
                $options,
            );
            $rightSign = $this->rationalExpressionSignBetweenPoints(
                $node->right,
                $extractor,
                $left,
                $right,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($leftSign === null || $rightSign === null) {
                return null;
            }

            return $leftSign * $rightSign;
        }

        try {
            $form = $extractor->extractRationalForm($node);
        } catch (EvaluationException) {
            return null;
        }
        if ($form === null) {
            return null;
        }
        $numeratorSign = $this->polynomialSignOnOpenInterval(
            $form[0],
            $left,
            $right,
            $lowerBound,
            $upperBound,
            $options,
        );
        $denominatorSign = $this->polynomialSignOnOpenInterval(
            $form[1],
            $left,
            $right,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($numeratorSign === null || $denominatorSign === null || $denominatorSign === 0) {
            return null;
        }

        return $numeratorSign * $denominatorSign;
    }

    /** @param list<float> $coefficients */
    private function polynomialSignOnOpenInterval(
        array $coefficients,
        float $left,
        float $right,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?int {
        $polynomialSolver = new PolynomialSolver();
        $roots = \count($coefficients) === 1
            ? []
            : $polynomialSolver->solve(
                $coefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $coefficients,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $coefficients,
                    $value,
                ),
            );
        if ($roots === null) {
            return null;
        }
        $leftIsRoot = false;
        foreach ($roots as $root) {
            if ($root->value === $left) {
                $leftIsRoot = true;
                break;
            }
        }

        return $this->polynomialSignBetweenPoints($coefficients, $left, $right, $leftIsRoot);
    }

    /** @param list<float> $coefficients */
    private function polynomialSignBetweenPoints(
        array $coefficients,
        float $left,
        float $right,
        bool $leftIsRoot,
    ): ?int {
        if ($right <= $left) {
            return null;
        }
        if (\count($coefficients) === 1) {
            return $coefficients[0] <=> 0.0;
        }

        $lastCoefficient = \count($coefficients) - 1;
        $shifted = [$coefficients[$lastCoefficient]];
        for ($degree = \count($coefficients) - 2; $degree >= 0; --$degree) {
            $next = \array_fill(0, \count($shifted) + 1, 0.0);
            foreach ($shifted as $index => $coefficient) {
                $next[$index] += $left * $coefficient;
                $next[$index + 1] += $coefficient;
                if (!\is_finite($next[$index]) || !\is_finite($next[$index + 1])) {
                    return null;
                }
            }
            $next[0] += $coefficients[$degree];
            if (!\is_finite($next[0])) {
                return null;
            }
            $shifted = \array_values($next);
        }

        if (!$leftIsRoot) {
            return $shifted[0] <=> 0.0;
        }

        $offset = ($right / 2.0) - ($left / 2.0);
        if (!\is_finite($offset)) {
            return null;
        }
        if ($offset === 0.0) {
            for ($degree = 1; $degree < \count($shifted); ++$degree) {
                if ($shifted[$degree] !== 0.0) {
                    return $shifted[$degree] <=> 0.0;
                }
            }

            return 0;
        }

        $scale = 0.0;
        for ($degree = 1; $degree < \count($shifted); ++$degree) {
            $scale = \max($scale, \abs($shifted[$degree]));
        }
        if ($scale === 0.0) {
            return 0;
        }
        $value = $shifted[\array_key_last($shifted)] / $scale;
        for ($degree = \count($shifted) - 2; $degree >= 1; --$degree) {
            $value = ($value * $offset) + ($shifted[$degree] / $scale);
            if (!\is_finite($value)) {
                return null;
            }
        }

        return $value <=> 0.0;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveDiscreteIntegerFunctionEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['binomial', 'gcd', 'lcm', 'permutation', 'doublefactorial'], true)
        ) {
            $function = $left;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['binomial', 'gcd', 'lcm', 'permutation', 'doublefactorial'], true)
        ) {
            $function = $right;
            $constant = $left;
        } else {
            return null;
        }

        if (
            ($function->name === 'doublefactorial' && \count($function->arguments) !== 1)
            || ($function->name !== 'doublefactorial' && \count($function->arguments) !== 2)
        ) {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if (
            $targetCoefficients !== null
            && \count($targetCoefficients) > 1
            && $this->containsVariable($constant, $variable)
        ) {
            return $this->solveIntegerFunctionAgainstPolynomial(
                $constant,
                $targetCoefficients,
                $variable,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $target = $targetCoefficients[0];
        if (!\is_finite($target) || \floor($target) !== $target || $target < 0.0) {
            return [];
        }

        if (!\is_finite($lowerBound) || !\is_finite($upperBound)) {
            $combinatorialSolutions = $this->solveUnboundedCombinatorialIntegerFunctionEquation(
                $function,
                $target,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
            if ($combinatorialSolutions !== null) {
                return $combinatorialSolutions;
            }
            $unboundedSolutions = $this->solveUnboundedDiscreteIntegerFunctionEquation(
                $function,
                $target,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
            if ($unboundedSolutions !== null) {
                return $unboundedSolutions;
            }
        }

        if ($function->name === 'doublefactorial') {
            return null;
        }

        $customArguments = [];
        foreach ($function->arguments as $argumentIndex => $argument) {
            if (
                $this->containsVariable($argument, $variable)
                && $this->containsVariableDependentCustomFunction($argument, $variable, $evaluationOptions)
            ) {
                $customArguments[$argumentIndex] = $argument;
            }
        }
        if (
            $customArguments !== []
            && $this->containsVariable($function->arguments[0], $variable)
            && $this->containsVariable($function->arguments[1], $variable)
        ) {
            $firstArgumentLevels = isset($customArguments[0])
                ? $this->solveCustomIntegerArgumentLevels(
                    $function->arguments[0],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                )
                : $this->solvePolynomialIntegerArgumentLevels(
                    $function->arguments[0],
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
            $secondArgumentLevels = isset($customArguments[1])
                ? $this->solveCustomIntegerArgumentLevels(
                    $function->arguments[1],
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                )
                : $this->solvePolynomialIntegerArgumentLevels(
                    $function->arguments[1],
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
            if ($firstArgumentLevels === null || $secondArgumentLevels === null) {
                return null;
            }
            $levelCombinations = \count($firstArgumentLevels) * \count($secondArgumentLevels);
            if ($levelCombinations > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                return null;
            }

            $solutions = [];
            $candidateComparisons = 0;
            foreach ($firstArgumentLevels as $firstLevelRoots) {
                foreach ($secondArgumentLevels as $secondLevelRoots) {
                    foreach ($firstLevelRoots as $firstRoot) {
                        foreach ($secondLevelRoots as $secondRoot) {
                            if (++$candidateComparisons > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                                return null;
                            }
                            $positionTolerance = max(
                                $options->positionTolerance($firstRoot->value, $secondRoot->value),
                                $options->positionTolerance($secondRoot->value, $firstRoot->value),
                            );
                            if (\abs($firstRoot->value - $secondRoot->value) > $positionTolerance) {
                                continue;
                            }
                            $candidate = ($firstRoot->value / 2.0) + ($secondRoot->value / 2.0);
                            $residual = $residualAt($candidate);
                            if (
                                $residual !== null
                                && $this->isResidualAcceptableAt(
                                    $candidate,
                                    $residual,
                                    $candidateScaleAt,
                                    $options,
                                )
                            ) {
                                $this->addSolution(
                                    $solutions,
                                    new EquationSolution($candidate, \abs($residual), 0),
                                    $options,
                                );
                            }
                        }
                    }
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $customArgumentIndex = \array_key_first($customArguments);
        if (
            \count($customArguments) === 1
            && ($customArgumentIndex === 0 || $customArgumentIndex === 1)
        ) {
            $otherArgument = $function->arguments[$customArgumentIndex === 0 ? 1 : 0];
            if (!$this->containsVariable($otherArgument, $variable)) {
                $otherValue = $this->constantNodeValue($otherArgument, $parameters, $evaluationOptions);
                if ($otherValue !== null && \is_finite($otherValue) && \floor($otherValue) === $otherValue) {
                    $argumentLevels = $this->solveCustomIntegerArgumentLevels(
                        $customArguments[$customArgumentIndex],
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                    if ($argumentLevels === null) {
                        return null;
                    }
                    $solutions = [];
                    foreach ($argumentLevels as $levelRoots) {
                        foreach ($levelRoots as $candidate) {
                            $residual = $residualAt($candidate->value);
                            if (
                                $residual !== null
                                && $this->isResidualAcceptableAt(
                                    $candidate->value,
                                    $residual,
                                    $candidateScaleAt,
                                    $options,
                                )
                            ) {
                                $this->addSolution(
                                    $solutions,
                                    new EquationSolution(
                                        $candidate->value,
                                        \abs($residual),
                                        $candidate->iterations,
                                    ),
                                    $options,
                                );
                            }
                        }
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
            }
        }

        if (!\in_array($function->name, ['gcd', 'lcm'], true)) {
            return null;
        }

        $maximumExactInteger = 9_007_199_254_740_991.0;
        $maximumLevels = \max(1, \intdiv(self::MAX_MODULO_SCAN_WORK, $options->scanSteps));
        $selected = null;
        $selectedLevelCount = \INF;
        foreach ($function->arguments as $argumentIndex => $argument) {
            if (!$this->containsVariable($argument, $variable)) {
                continue;
            }
            $coefficients = $this->extractPolynomial(
                $extractor,
                $argument,
                $argument->span()->start,
            );
            if ($coefficients !== null) {
                if (\count($coefficients) < 2) {
                    continue;
                }
                $form = [$coefficients, [1.0]];
                $range = $this->polynomialRange($coefficients, $lowerBound, $upperBound, $options);
            } else {
                $form = $extractor->extractRationalForm($argument);
                if (
                    $form === null
                    || (\count($form[0]) < 2 && \count($form[1]) < 2)
                    || $this->proportionalPolynomialRatio($form[0], $form[1]) !== null
                ) {
                    continue;
                }
                $otherArgument = $function->arguments[1 - $argumentIndex];
                if (!$this->containsVariable($otherArgument, $variable)) {
                    $otherCoefficients = $this->extractPolynomial(
                        $extractor,
                        $otherArgument,
                        $otherArgument->span()->start,
                    );
                    if ($otherCoefficients !== null && \count($otherCoefficients) === 1) {
                        $hasGenuinePole = $this->rationalFormHasGenuinePole(
                            $form[0],
                            $form[1],
                            $lowerBound,
                            $upperBound,
                            $options,
                        );
                        if ($hasGenuinePole === true) {
                            $poleSolutions = $this->solveRationalIntegerFunctionAtPole(
                                $function->name,
                                $form[0],
                                $form[1],
                                $otherCoefficients[0],
                                $target,
                                $lowerBound,
                                $upperBound,
                                $options,
                                $residualAt,
                                $candidateScaleAt,
                            );
                            if ($poleSolutions !== null) {
                                return $poleSolutions;
                            }
                        }
                    }
                }
                $rationalRange = $this->rationalPolynomialRange(
                    $form[0],
                    $form[1],
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                $range = $rationalRange[0] ?? null;
                if ($rationalRange !== null) {
                    $form = [$rationalRange[1], $rationalRange[2]];
                }
            }
            if ($range === null) {
                continue;
            }
            [$minimum, $maximum] = $range;
            if (
                $minimum < -$maximumExactInteger
                || $maximum > $maximumExactInteger
            ) {
                continue;
            }
            $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($minimum), \abs($maximum));
            $firstLevel = \ceil($minimum - $tolerance);
            $lastLevel = \floor($maximum + $tolerance);
            if ($firstLevel > $lastLevel) {
                return [];
            }
            $levelCount = $lastLevel - $firstLevel + 1.0;
            if ($levelCount <= $maximumLevels && $levelCount < $selectedLevelCount) {
                $selected = [$form[0], $form[1], (int) $firstLevel, (int) $lastLevel];
                $selectedLevelCount = $levelCount;
            }
        }
        if ($selected === null) {
            return null;
        }

        [$numerator, $denominator, $firstLevel, $lastLevel] = $selected;
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $candidateCount = 0;
        for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
            $levelCoefficients = $this->subtractScaledPolynomials(
                $numerator,
                $denominator,
                (float) $level,
            );
            if ($levelCoefficients === null) {
                return null;
            }
            if ($levelCoefficients === [0.0]) {
                continue;
            }
            $levelRoots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $levelCoefficients,
                                $value,
                            ),
            );
            if ($levelRoots === null) {
                return null;
            }
            foreach ($levelRoots as $levelRoot) {
                if (++$candidateCount > self::MAX_MODULO_SCAN_WORK) {
                    return null;
                }
                $candidate = $levelRoot->value;
                $residual = $residualAt($candidate);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), $levelRoot->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve unbounded gcd/lcm equations with one nonconstant polynomial argument.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedDiscreteIntegerFunctionEquation(
        FunctionCallNode $function,
        float $target,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\in_array($function->name, ['gcd', 'lcm'], true)) {
            return null;
        }

        $variableArgumentIndex = null;
        foreach ($function->arguments as $index => $argument) {
            if (!$this->containsVariable($argument, $variable)) {
                continue;
            }
            if ($variableArgumentIndex !== null) {
                return null;
            }
            $variableArgumentIndex = $index;
        }
        if ($variableArgumentIndex === null) {
            return null;
        }

        $argument = $function->arguments[$variableArgumentIndex];
        $otherArgument = $function->arguments[1 - $variableArgumentIndex];
        $coefficients = $this->extractPolynomial($extractor, $argument, $argument->span()->start);
        $otherValue = $this->constantNodeValue($otherArgument, $parameters, $evaluationOptions);
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (
            $coefficients === null
            || \count($coefficients) < 2
            || $otherValue === null
            || !\is_finite($otherValue)
            || \floor($otherValue) !== $otherValue
            || \abs($otherValue) > $maximumExactInteger
            || $target > $maximumExactInteger
        ) {
            return null;
        }
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) < 2) {
            return null;
        }

        $fixedInteger = (int) $otherValue;
        $fixedMagnitude = \abs($fixedInteger);
        $targetInteger = (int) $target;
        if ($function->name === 'gcd') {
            if ($fixedMagnitude > 0) {
                if ($targetInteger === 0 || ($fixedMagnitude % $targetInteger) !== 0) {
                    return [];
                }
                throw new InfiniteSolutionSetException(
                    'The polynomial argument reaches infinitely many integer levels with the requested gcd.',
                );
            }

            $levels = $targetInteger === 0
                ? [0.0]
                : [(float) $targetInteger, (float) -$targetInteger];
        } else {
            if ($fixedMagnitude === 0) {
                if ($targetInteger === 0) {
                    throw new InfiniteSolutionSetException(
                        'The polynomial argument reaches infinitely many integer levels with zero lcm.',
                    );
                }

                return [];
            }
            if ($targetInteger === 0 || ($targetInteger % $fixedMagnitude) !== 0) {
                return [];
            }

            $levels = [];
            $divisorChecks = 0;
            for ($divisor = 1; $divisor <= \intdiv($targetInteger, $divisor); ++$divisor) {
                if (++$divisorChecks > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                    return null;
                }
                if (($targetInteger % $divisor) !== 0) {
                    continue;
                }
                $pairedDivisor = \intdiv($targetInteger, $divisor);
                foreach (\array_unique([$divisor, $pairedDivisor]) as $magnitude) {
                    $gcd = $this->positiveIntegerGcd($magnitude, $fixedMagnitude);
                    if (
                        \intdiv($fixedMagnitude, $gcd)
                        !== \intdiv($targetInteger, $magnitude)
                    ) {
                        continue;
                    }
                    $levels[] = (float) $magnitude;
                    $levels[] = (float) -$magnitude;
                }
            }
        }

        if ($levels === []) {
            return [];
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach (\array_unique($levels) as $level) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $maximumCoefficientRatio = 0.0;
            $leadingCoefficient = \abs($levelCoefficients[\array_key_last($levelCoefficients)]);
            foreach (\array_slice($levelCoefficients, 0, -1) as $coefficient) {
                $ratio = \abs($coefficient) / $leadingCoefficient;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumCoefficientRatio = \max($maximumCoefficientRatio, $ratio);
            }
            $rootBound = $this->adjacentFloat(1.0 + $maximumCoefficientRatio, 1)
                ?? (1.0 + $maximumCoefficientRatio);
            if (!\is_finite($rootBound)) {
                return null;
            }
            $finiteLower = \max($lowerBound, -$rootBound);
            $finiteUpper = \min($upperBound, $rootBound);
            if ($finiteLower > $finiteUpper) {
                continue;
            }
            $polynomialResidualAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
            $polynomialScaleAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $finiteLower,
                $finiteUpper,
                $polynomialResidualAt,
                $options,
                $polynomialScaleAt,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve unbounded binomial, permutation, and double-factorial equations by polynomial integer levels.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveUnboundedCombinatorialIntegerFunctionEquation(
        FunctionCallNode $function,
        float $target,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!\in_array($function->name, ['binomial', 'permutation', 'doublefactorial'], true)) {
            return null;
        }

        $variableArgumentIndex = null;
        foreach ($function->arguments as $index => $argument) {
            if (!$this->containsVariable($argument, $variable)) {
                continue;
            }
            if ($variableArgumentIndex !== null) {
                return null;
            }
            $variableArgumentIndex = $index;
        }
        if ($variableArgumentIndex === null) {
            return null;
        }
        $argument = $function->arguments[$variableArgumentIndex];
        $coefficients = $this->extractPolynomial($extractor, $argument, $argument->span()->start);
        if ($coefficients === null) {
            return null;
        }
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) < 2) {
            return null;
        }

        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (!\is_finite($target) || \floor($target) !== $target || $target < 0.0 || $target > $maximumExactInteger) {
            return [];
        }
        $targetInteger = (int) $target;
        $levels = [];
        if ($function->name === 'doublefactorial') {
            $definition = $evaluationOptions->functions->find('doublefactorial');
            if ($definition === null) {
                return null;
            }
            for ($integerLevel = -1; $integerLevel <= 64; ++$integerLevel) {
                try {
                    $value = $definition->invoke([(float) $integerLevel]);
                } catch (\OverflowException) {
                    break;
                }
                if ((float) $value === $target) {
                    $levels[] = (float) $integerLevel;
                }
            }
        } else {
            $otherIndex = 1 - $variableArgumentIndex;
            $fixedValue = $this->constantNodeValue(
                $function->arguments[$otherIndex],
                $parameters,
                $evaluationOptions,
            );
            if (
                $fixedValue === null
                || !\is_finite($fixedValue)
                || \floor($fixedValue) !== $fixedValue
                || $fixedValue < 0.0
                || $fixedValue > $maximumExactInteger
            ) {
                return null;
            }
            $fixedInteger = (int) $fixedValue;
            $definition = $evaluationOptions->functions->find($function->name);
            if ($definition === null) {
                return null;
            }

            if ($variableArgumentIndex === 0) {
                $fixedK = $fixedInteger;
                if ($fixedK === 0) {
                    if ($targetInteger !== 1) {
                        return [];
                    }
                    if (
                        $this->polynomialTendsToPositiveInfinityOnRequestedTail(
                            $coefficients,
                            $lowerBound,
                            $upperBound,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The polynomial argument reaches infinitely many unit binomial levels.',
                        );
                    }
                    $maximum = $this->polynomialMaximumOnUnboundedInterval(
                        $coefficients,
                        $lowerBound,
                        $upperBound,
                        $options,
                    );
                    if ($maximum === null || $maximum < 0.0) {
                        return $maximum === null ? null : [];
                    }
                    $lastLevel = (int) \floor(
                        $maximum + 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($maximum)),
                    );
                    if ($lastLevel > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                        return null;
                    }
                    $levels = \range(0, $lastLevel);
                }
                if ($targetInteger === 0) {
                    if ($fixedK > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                        return null;
                    }
                    for ($integerLevel = 0; $integerLevel < $fixedK; ++$integerLevel) {
                        $levels[] = (float) $integerLevel;
                    }
                } else {
                    try {
                        $atMinimum = (int) $definition->invoke([$fixedK, $fixedK]);
                    } catch (\DomainException | \OverflowException) {
                        $atMinimum = \PHP_INT_MAX;
                    }
                    if ($atMinimum === $targetInteger) {
                        $levels[] = (float) $fixedK;
                    } elseif ($targetInteger > $atMinimum && $fixedK < $targetInteger) {
                        $low = $fixedK + 1;
                        $high = $targetInteger;
                        while ($low <= $high) {
                            $middle = $low + \intdiv($high - $low, 2);
                            try {
                                $value = (int) $definition->invoke([$middle, $fixedK]);
                            } catch (\DomainException | \OverflowException) {
                                $value = \PHP_INT_MAX;
                            }
                            if ($value === $targetInteger) {
                                $levels[] = (float) $middle;
                                break;
                            }
                            if ($value < $targetInteger) {
                                $low = $middle + 1;
                            } else {
                                $high = $middle - 1;
                            }
                        }
                    }
                }
            } else {
                if (
                    $targetInteger === 0
                    && $this->polynomialTendsToPositiveInfinityOnRequestedTail(
                        $coefficients,
                        $lowerBound,
                        $upperBound,
                    )
                ) {
                    throw new InfiniteSolutionSetException(
                        'The polynomial argument reaches infinitely many zero-valued combinatorial levels.',
                    );
                }
                if ($targetInteger === 0) {
                    $maximum = $this->polynomialMaximumOnUnboundedInterval(
                        $coefficients,
                        $lowerBound,
                        $upperBound,
                        $options,
                    );
                    if ($maximum === null || $maximum < 0.0) {
                        return $maximum === null ? null : [];
                    }
                    $lastLevel = (int) \floor(
                        $maximum + 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($maximum)),
                    );
                    if ($lastLevel > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                        return null;
                    }
                    for ($integerLevel = $fixedInteger + 1; $integerLevel <= $lastLevel; ++$integerLevel) {
                        $levels[] = (float) $integerLevel;
                    }
                } else {
                    if ($fixedInteger > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
                        return null;
                    }
                    for ($integerLevel = 0; $integerLevel <= $fixedInteger; ++$integerLevel) {
                        try {
                            $value = (int) $definition->invoke([$fixedInteger, $integerLevel]);
                        } catch (\DomainException | \OverflowException) {
                            continue;
                        }
                        if ($value === $targetInteger) {
                            $levels[] = (float) $integerLevel;
                        }
                    }
                }
            }
        }

        if ($levels === []) {
            return [];
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        foreach (\array_unique($levels) as $level) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $leadingCoefficient = \abs($levelCoefficients[\array_key_last($levelCoefficients)]);
            $maximumRatio = 0.0;
            foreach (\array_slice($levelCoefficients, 0, -1) as $coefficient) {
                $ratio = \abs($coefficient) / $leadingCoefficient;
                if (!\is_finite($ratio)) {
                    return null;
                }
                $maximumRatio = \max($maximumRatio, $ratio);
            }
            $rootBound = $this->adjacentFloat(1.0 + $maximumRatio, 1) ?? (1.0 + $maximumRatio);
            if (!\is_finite($rootBound)) {
                return null;
            }
            $finiteLower = \max($lowerBound, -$rootBound);
            $finiteUpper = \min($upperBound, $rootBound);
            if ($finiteLower > $finiteUpper) {
                continue;
            }
            $polynomialResidualAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomial($levelCoefficients, $value);
            $polynomialScaleAt = static fn (float $value): ?float =>
                $polynomialSolver->evaluatePolynomialMagnitude($levelCoefficients, $value);
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $finiteLower,
                $finiteUpper,
                $polynomialResidualAt,
                $options,
                $polynomialScaleAt,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return array<int, list<EquationSolution>>|null
     */
    private function solvePolynomialIntegerArgumentLevels(
        Node $argument,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        $coefficients = $this->extractPolynomial($extractor, $argument, $argument->span()->start);
        if ($coefficients === null || \count($coefficients) < 2) {
            return null;
        }
        $range = $this->polynomialRange($coefficients, $lowerBound, $upperBound, $options);
        if ($range === null) {
            return null;
        }
        [$minimum, $maximum] = $range;
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (
            !\is_finite($minimum)
            || !\is_finite($maximum)
            || $minimum < -$maximumExactInteger
            || $maximum > $maximumExactInteger
        ) {
            return null;
        }
        $levelTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($minimum), \abs($maximum));
        $firstLevel = (int) \ceil($minimum - $levelTolerance);
        $lastLevel = (int) \floor($maximum + $levelTolerance);
        if ($firstLevel > $lastLevel) {
            return [];
        }
        if ($lastLevel - $firstLevel + 1 > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $rootCount = 0;
        for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $levelRoots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $levelCoefficients,
                                $value,
                            ),
            );
            if ($levelRoots === null) {
                return null;
            }
            $rootCount += \count($levelRoots);
            if ($rootCount > self::MAX_ROOT_DEGREE_SCAN_WORK) {
                return null;
            }
            $solutions[$level] = $levelRoots;
        }

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array<int, list<EquationSolution>>|null
     */
    private function solveCustomIntegerArgumentLevels(
        Node $argument,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        $range = $this->evaluateIntervalExpression(
            $argument,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
        );
        if ($range === null) {
            return null;
        }
        [$minimum, $maximum] = $range;
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (
            !\is_finite($minimum)
            || !\is_finite($maximum)
            || $minimum < -$maximumExactInteger
            || $maximum > $maximumExactInteger
        ) {
            return null;
        }
        $firstLevel = (int) \ceil($minimum);
        $lastLevel = (int) \floor($maximum);
        if ($firstLevel > $lastLevel) {
            return [];
        }
        if ($lastLevel - $firstLevel + 1 > self::MAX_DISCRETE_INTERVAL_COMBINATIONS) {
            return null;
        }

        $solutions = [];
        for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
            $levelNode = new NumberNode($level, (string) $level, $argument->span());
            $levelResidualAt = function (float $value) use (
                $argument,
                $level,
                $variable,
                $parameters,
                $evaluationOptions,
            ): ?float {
                try {
                    $argumentValue = (float) $this->evaluateNode(
                        $argument,
                        [...$parameters, $variable => $value],
                        $evaluationOptions,
                    );
                } catch (EvaluationException) {
                    return null;
                }

                $residual = $argumentValue - $level;

                return \is_finite($residual) ? $residual : null;
            };
            $levelSolutions = $this->solveCustomArithmeticIntervalEquation(
                $argument,
                $levelNode,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
                $levelResidualAt,
            );
            if ($levelSolutions === null) {
                return null;
            }
            $solutions[$level] = $levelSolutions;
        }

        return $solutions;
    }

    /**
     * @param list<float> $numerator
     * @param list<float> $denominator
     * @return bool|null
     */
    private function rationalFormHasGenuinePole(
        array $numerator,
        array $denominator,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?bool {
        if (\count($denominator) === 1) {
            return $denominator[0] === 0.0 ? null : false;
        }

        $polynomialSolver = new PolynomialSolver();
        $roots = $polynomialSolver->solve(
            $denominator,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $denominator,
                $value,
            ),
            $options,
        );
        if ($roots === null) {
            return null;
        }
        foreach ($roots as $root) {
            $denominatorMultiplicity = $this->polynomialRootMultiplicity(
                $denominator,
                $root->value,
            );
            $numeratorMultiplicity = $this->polynomialRootMultiplicity(
                $numerator,
                $root->value,
            );
            if ($denominatorMultiplicity === 0) {
                return null;
            }
            if ($denominatorMultiplicity > $numeratorMultiplicity) {
                return true;
            }
        }

        return false;
    }

    /**
     * Solve gcd/lcm equations whose rational argument has a genuine pole and
     * whose other argument is constant.
     *
     * @param list<float> $numerator
     * @param list<float> $denominator
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalIntegerFunctionAtPole(
        string $function,
        array $numerator,
        array $denominator,
        float $constant,
        float $target,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (
            !\is_finite($constant)
            || !\is_finite($target)
            || \floor($constant) !== $constant
            || \floor($target) !== $target
            || \abs($constant) > $maximumExactInteger
            || $target < 0.0
            || $target > $maximumExactInteger
        ) {
            return null;
        }

        $constantInteger = (int) $constant;
        $targetInteger = (int) $target;
        $constantMagnitude = \abs($constantInteger);
        $levels = [];
        if ($function === 'gcd') {
            if ($constantInteger === 0) {
                $levels = $targetInteger === 0
                    ? [0]
                    : [$targetInteger, -$targetInteger];
            } elseif (
                $targetInteger > 0
                && $constantMagnitude % $targetInteger === 0
            ) {
                throw new InfiniteRootAccumulationException(
                    'gcd() of an unbounded rational argument has infinitely many roots '
                        . 'accumulating at a pole in the solving interval.',
                );
            } else {
                return [];
            }
        } elseif ($function === 'lcm') {
            if ($constantInteger === 0) {
                if ($targetInteger === 0) {
                    throw new InfiniteRootAccumulationException(
                        'lcm() with a zero argument has infinitely many integer-level roots '
                            . 'accumulating at a rational pole in the solving interval.',
                    );
                }

                return [];
            }
            if ($targetInteger === 0 || $targetInteger % $constantMagnitude !== 0) {
                return [];
            }
            $divisorChecks = 0;
            for ($divisor = 1; $divisor <= \intdiv($targetInteger, $divisor); ++$divisor) {
                if (++$divisorChecks > self::MAX_MODULO_SCAN_WORK) {
                    return null;
                }
                if ($targetInteger % $divisor !== 0) {
                    continue;
                }
                foreach ([$divisor, \intdiv($targetInteger, $divisor)] as $candidate) {
                    $commonDivisor = $this->positiveIntegerGcd($candidate, $constantMagnitude);
                    $reduced = \intdiv($candidate, $commonDivisor);
                    if (
                        $reduced <= \intdiv($targetInteger, $constantMagnitude)
                        && $reduced * $constantMagnitude === $targetInteger
                    ) {
                        $levels[] = $candidate;
                        $levels[] = -$candidate;
                    }
                }
            }
        } else {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $candidateCount = 0;
        foreach (\array_unique($levels) as $level) {
            $levelCoefficients = $this->subtractScaledPolynomials(
                $numerator,
                $denominator,
                (float) $level,
            );
            if ($levelCoefficients === null) {
                return null;
            }
            if ($levelCoefficients === [0.0]) {
                continue;
            }
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $levelCoefficients,
                                $value,
                            ),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                if (++$candidateCount > self::MAX_MODULO_SCAN_WORK) {
                    return null;
                }
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function positiveIntegerGcd(int $left, int $right): int
    {
        while ($right !== 0) {
            [$left, $right] = [$right, $left % $right];
        }

        return $left;
    }

    /**
     * @param list<float> $coefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveIntegerFunctionAgainstPolynomial(
        Node $polynomial,
        array $coefficients,
        string $variable,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (!$this->containsVariable($polynomial, $variable)) {
            return null;
        }
        $range = $this->polynomialRange($coefficients, $lowerBound, $upperBound, $options);
        if ($range === null) {
            return null;
        }

        [$minimum, $maximum] = $range;
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if ($maximum < 0.0) {
            return [];
        }
        if ($minimum < -$maximumExactInteger || $maximum > $maximumExactInteger) {
            return null;
        }

        $tolerance = 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($minimum), \abs($maximum));
        $firstLevel = \max(0.0, \ceil($minimum - $tolerance));
        $lastLevel = \floor($maximum + $tolerance);
        $levelCount = $lastLevel - $firstLevel + 1.0;
        if ($levelCount < 1.0) {
            return [];
        }
        if ($levelCount > self::MAX_MODULO_SCAN_WORK) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        for ($level = (int) $firstLevel; $level <= (int) $lastLevel; ++$level) {
            $levelCoefficients = $coefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $levelCoefficients,
                                $value,
                            ),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve floor(g) + ceil(g) by reducing its parity-dependent range.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSameArgumentFloorCeilSum(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        /** @var list<FunctionCallNode> $functions */
        $functions = [];
        /** @var list<float> $coefficients */
        $coefficients = [];
        $constant = 0.0;
        foreach ($terms as [$node, $sign]) {
            $factors = [];
            $this->flattenProductFactors($node, $factors);
            $roundingFunction = null;
            $coefficient = $sign;
            foreach ($factors as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && \in_array($factor->name, ['floor', 'ceil', 'round', 'trunc'], true)
                ) {
                    if ($roundingFunction !== null || \count($factor->arguments) !== 1) {
                        return null;
                    }
                    $roundingFunction = $factor;
                    continue;
                }
                $factorCoefficients = $this->extractPolynomial(
                    $extractor,
                    $factor,
                    $factor->span()->start,
                );
                if ($factorCoefficients === null || \count($factorCoefficients) !== 1) {
                    return null;
                }
                $coefficient *= $factorCoefficients[0];
            }
            if ($roundingFunction !== null) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
                $functions[] = $roundingFunction;
                $coefficients[] = $coefficient;
                continue;
            }
            $termCoefficients = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($termCoefficients === null || \count($termCoefficients) !== 1) {
                return null;
            }
            $constant += $sign * $termCoefficients[0];
        }
        if ($functions === [] || !\is_finite($constant)) {
            return null;
        }

        $functionNames = \array_unique(\array_map(
            static fn (FunctionCallNode $function): string => $function->name,
            $functions,
        ));
        if (\count($functionNames) === 1) {
            if (\count($functions) === 1 && $coefficients[0] === 1.0) {
                return null;
            }
            $referenceForm = $extractor->extractRationalForm($functions[0]->arguments[0]);
            if ($referenceForm === null) {
                return null;
            }
            foreach (\array_slice($functions, 1) as $function) {
                $form = $extractor->extractRationalForm($function->arguments[0]);
                if ($form === null) {
                    return null;
                }
                $leftProduct = $this->multiplyPolynomialCoefficients(
                    $referenceForm[0],
                    $form[1],
                    $options->maxPolynomialDegree,
                );
                $rightProduct = $this->multiplyPolynomialCoefficients(
                    $form[0],
                    $referenceForm[1],
                    $options->maxPolynomialDegree,
                );
                if ($leftProduct === null || $rightProduct === null) {
                    return null;
                }
                $difference = $this->combinePolynomialCoefficients($leftProduct, $rightProduct, -1.0);
                if ($difference !== [0.0]) {
                    return null;
                }
            }
            $coefficient = \array_sum($coefficients);
            if (!\is_finite($coefficient)) {
                return null;
            }
            if ($coefficient === 0.0) {
                if ($constant === 0.0) {
                    throw new InfiniteSolutionSetException(
                        'Repeated identical quantizer terms cancel to an identity on their defined domain.',
                    );
                }

                return [];
            }

            $target = -$constant / $coefficient;
            if (
                !\is_finite($target)
                || \floor($target) !== $target
                || \abs($target) > 9_007_199_254_740_991.0
            ) {
                return [];
            }
            $leftContainsVariable = $this->containsVariable($left, $variable);
            $rightContainsVariable = $this->containsVariable($right, $variable);
            if ($leftContainsVariable === $rightContainsVariable) {
                return null;
            }
            $function = $functions[0];
            $functionSource = $leftContainsVariable ? $leftSource : $rightSource;
            $functionSourceOffset = $leftContainsVariable ? 0 : $rightSourceOffset;
            $argumentSpan = $function->arguments[0]->span();
            $argumentSource = \substr(
                $functionSource,
                $argumentSpan->start - $functionSourceOffset,
                $argumentSpan->end - $argumentSpan->start,
            );
            if ($argumentSource === '') {
                return null;
            }
            $levelEquation = $function->name
                . '(' . $argumentSource . ')='
                . \sprintf('%.0f', $target);
            if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $levelSolutions = $this->solve(
                $levelEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            $solutions = [];
            foreach ($levelSolutions as $solution) {
                $residual = $residualAt($solution->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $solution->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($solution->value, \abs($residual), $solution->iterations),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }
        if (\count($functions) !== 2) {
            return null;
        }

        $floorIndex = null;
        $ceilIndex = null;
        foreach ($functions as $index => $function) {
            if ($function->name === 'floor') {
                $floorIndex = $index;
            } elseif ($function->name === 'ceil') {
                $ceilIndex = $index;
            } else {
                return null;
            }
        }
        if (
            $floorIndex === null
            || $ceilIndex === null
            || $coefficients[$floorIndex] === 0.0
            || $coefficients[$floorIndex] !== $coefficients[$ceilIndex]
        ) {
            return null;
        }
        $target = -$constant / $coefficients[$floorIndex];
        if (
            !\is_finite($target)
            || \floor($target) !== $target
            || \abs($target) > 9_007_199_254_740_991.0
        ) {
            return [];
        }

        $floorArgument = $functions[$floorIndex]->arguments[0];
        $ceilArgument = $functions[$ceilIndex]->arguments[0];
        $floorForm = $extractor->extractRationalForm($floorArgument);
        $ceilForm = $extractor->extractRationalForm($ceilArgument);
        if ($floorForm === null || $ceilForm === null) {
            return null;
        }
        $leftCrossProduct = $this->multiplyPolynomialCoefficients(
            $floorForm[0],
            $ceilForm[1],
            $options->maxPolynomialDegree,
        );
        $rightCrossProduct = $this->multiplyPolynomialCoefficients(
            $ceilForm[0],
            $floorForm[1],
            $options->maxPolynomialDegree,
        );
        if ($leftCrossProduct === null || $rightCrossProduct === null) {
            return null;
        }
        $argumentDifference = $this->combinePolynomialCoefficients(
            $leftCrossProduct,
            $rightCrossProduct,
            -1.0,
        );
        if ($argumentDifference !== [0.0]) {
            return null;
        }

        if (((int) $target % 2) === 0) {
            $level = $target / 2.0;
            $span = $floorArgument->span();
            $functionSource = $this->containsVariable($left, $variable)
                ? $leftSource
                : $rightSource;
            $argumentSource = \substr(
                $functionSource,
                $span->start,
                $span->end - $span->start,
            );
            if ($argumentSource === '') {
                return null;
            }
            $roots = $this->solve(
                '(' . $argumentSource . ')=' . \sprintf('%.0f', $level),
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            $solutions = [];
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $lowerLevel = ($target - 1.0) / 2.0;
        $upperLevel = ($target + 1.0) / 2.0;
        $thresholdPolynomials = [];
        foreach ([$lowerLevel, $upperLevel] as $level) {
            $polynomial = $this->subtractScaledPolynomials(
                $floorForm[0],
                $floorForm[1],
                $level,
            );
            if ($polynomial === null) {
                return null;
            }
            $thresholdPolynomials[] = $polynomial;
        }
        $domainRoots = $this->rationalSubexpressionRoots(
            $floorArgument,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
        );
        $ceilDomainRoots = $this->rationalSubexpressionRoots(
            $ceilArgument,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($domainRoots === null || $ceilDomainRoots === null) {
            return null;
        }
        $domainRoots = [...$domainRoots, ...$ceilDomainRoots];

        $polynomialSolver = new PolynomialSolver();
        $partitionPoints = [$lowerBound, $upperBound];
        foreach ($domainRoots as $root) {
            if ($root->value > $lowerBound && $root->value < $upperBound) {
                $partitionPoints[] = $root->value;
            }
        }
        foreach ($thresholdPolynomials as $polynomial) {
            if (\count($polynomial) === 1) {
                continue;
            }
            $roots = $polynomialSolver->solve(
                $polynomial,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $polynomial,
                    $value,
                ),
                $options,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                if ($root->value > $lowerBound && $root->value < $upperBound) {
                    $partitionPoints[] = $root->value;
                }
            }
        }
        \sort($partitionPoints, SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
        for ($index = 1; $index < \count($partitionPoints); ++$index) {
            $leftPoint = $partitionPoints[$index - 1];
            $rightPoint = $partitionPoints[$index];
            $midpoint = match (true) {
                $leftPoint === -\INF && $rightPoint === \INF => 0.0,
                $leftPoint === -\INF => $rightPoint - \max(1.0, 0.5 * \abs($rightPoint)),
                $rightPoint === \INF => $leftPoint + \max(1.0, 0.5 * \abs($leftPoint)),
                default => $leftPoint + (($rightPoint - $leftPoint) / 2.0),
            };
            if ($midpoint === $leftPoint || $midpoint === $rightPoint) {
                continue;
            }
            $numerator = $polynomialSolver->evaluatePolynomial($floorForm[0], $midpoint);
            $denominator = $polynomialSolver->evaluatePolynomial($floorForm[1], $midpoint);
            if ($numerator === null || $denominator === null || $denominator === 0.0) {
                continue;
            }
            $argumentValue = $numerator / $denominator;
            if ($argumentValue > $lowerLevel && $argumentValue < $upperLevel) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
        }

        return [];
    }

    /**
     * Enumerate piecewise-constant rounding levels against polynomial terms.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRoundingPolynomialEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        /** @var list<FunctionCallNode> $roundingFunctions */
        $roundingFunctions = [];
        /** @var list<list<float>> $roundingCoefficients */
        $roundingCoefficients = [];
        /** @var list<list<int>> $roundingLevels */
        $roundingLevels = [];
        /** @var list<list<array{float, float}>> $roundingBoundaries */
        $roundingBoundaries = [];
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $factors = [];
            $this->flattenProductFactors($node, $factors);
            $roundingFactor = null;
            $coefficientFactors = [];
            foreach ($factors as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && \in_array($factor->name, ['floor', 'ceil', 'round', 'trunc'], true)
                ) {
                    if ($roundingFactor !== null || \count($factor->arguments) !== 1) {
                        return null;
                    }
                    $roundingFactor = $factor;
                } else {
                    $coefficientFactors[] = $factor;
                }
            }
            if ($roundingFactor === null) {
                $polynomial = $this->extractPolynomial(
                    $extractor,
                    $node,
                    $node->span()->start,
                );
                if ($polynomial === null) {
                    return null;
                }
                $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
                if ($remainder === null) {
                    return null;
                }
                continue;
            }

            $coefficient = [$sign];
            foreach ($coefficientFactors as $factor) {
                $polynomial = $this->extractPolynomial(
                    $extractor,
                    $factor,
                    $factor->span()->start,
                );
                if ($polynomial === null) {
                    return null;
                }
                $coefficient = $this->multiplyPolynomialCoefficients(
                    $coefficient,
                    $polynomial,
                    $options->maxPolynomialDegree,
                );
                if ($coefficient === null) {
                    return null;
                }
            }
            if (\count($coefficient) === 1 && $coefficient[0] === 0.0) {
                return null;
            }
            $roundingFunctions[] = $roundingFactor;
            $roundingCoefficients[] = $coefficient;
        }
        if ($roundingFunctions === []) {
            return null;
        }

        $maximumExactInteger = 9_007_199_254_740_991.0;
        $partitionPoints = [$lowerBound, $upperBound];
        $totalCombinations = 1;
        foreach ($roundingFunctions as $index => $function) {
            $argument = $function->arguments[0];
            $range = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
            $form = $extractor->extractRationalForm($argument);
            if (
                $range === null
                || $form === null
                || !\is_finite($range[0])
                || !\is_finite($range[1])
                || $range[0] < -$maximumExactInteger
                || $range[1] > $maximumExactInteger
            ) {
                return null;
            }
            $round = static fn (float $value): float => match ($function->name) {
                'floor' => \floor($value),
                'ceil' => \ceil($value),
                default => \round($value),
            };
            $firstLevel = (int) $round($range[0]) - 1;
            $lastLevel = (int) $round($range[1]) + 1;
            $levelCount = $lastLevel - $firstLevel + 1;
            if (
                $levelCount < 1
                || $totalCombinations > intdiv(self::MAX_MODULO_SCAN_WORK, $levelCount)
            ) {
                return null;
            }
            $totalCombinations *= $levelCount;
            $roundingLevels[$index] = \range($firstLevel, $lastLevel);
            $roundingBoundaries[$index] = [];

            $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($range[0]), \abs($range[1]));
            if ($function->name === 'round') {
                $firstBoundary = (int) \ceil($range[0] - 0.5 - $tolerance) - 1;
                $lastBoundary = (int) \floor($range[1] - 0.5 + $tolerance) + 1;
            } else {
                $firstBoundary = (int) \ceil($range[0] - $tolerance) - 1;
                $lastBoundary = (int) \floor($range[1] + $tolerance) + 1;
            }
            if ($lastBoundary - $firstBoundary + 1 > self::MAX_MODULO_SCAN_WORK) {
                return null;
            }
            for ($boundaryIndex = $firstBoundary; $boundaryIndex <= $lastBoundary; ++$boundaryIndex) {
                $boundary = $function->name === 'round'
                    ? $boundaryIndex + 0.5
                    : (float) $boundaryIndex;
                $boundaryPolynomial = $this->subtractScaledPolynomials(
                    $form[0],
                    $form[1],
                    $boundary,
                );
                if ($boundaryPolynomial === null) {
                    return null;
                }
                if (\count($boundaryPolynomial) === 1) {
                    continue;
                }
                $polynomialSolver = new PolynomialSolver();
                $roots = $polynomialSolver->solve(
                    $boundaryPolynomial,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $boundaryPolynomial,
                        $value,
                    ),
                    $options,
                );
                if ($roots === null) {
                    return null;
                }
                $boundaryOutput = $round($boundary);
                foreach ($roots as $root) {
                    $point = [$root->value, $boundaryOutput];
                    $roundingBoundaries[$index][] = $point;
                    $partitionPoints[] = $root->value;
                }
            }
        }

        \sort($partitionPoints, SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
        /** @var list<list<int>> $combinations */
        $combinations = [[]];
        foreach ($roundingLevels as $functionIndex => $levels) {
            /** @var list<list<int>> $next */
            $next = [];
            foreach ($combinations as $combination) {
                foreach ($levels as $level) {
                    $combination[$functionIndex] = $level;
                    $next[] = $combination;
                }
            }
            $combinations = $next;
        }

        $solutions = [];
        $polynomialSolver = new PolynomialSolver();
        foreach ($combinations as $combination) {
            $levelCoefficients = $remainder;
            foreach ($roundingCoefficients as $index => $coefficient) {
                $scaledCoefficient = $this->scalePolynomialCoefficients(
                    $coefficient,
                    (float) $combination[$index],
                );
                if ($scaledCoefficient === null) {
                    return null;
                }
                $levelCoefficients = $this->combinePolynomialCoefficients(
                    $levelCoefficients,
                    $scaledCoefficient,
                    1.0,
                );
                if ($levelCoefficients === null) {
                    return null;
                }
            }

            if (\count($levelCoefficients) === 1) {
                if ($levelCoefficients[0] !== 0.0) {
                    continue;
                }
                foreach ($partitionPoints as $point) {
                    $residual = $residualAt($point);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $point,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($point, \abs($residual), 0),
                            $options,
                        );
                    }
                }
                for ($interval = 1; $interval < \count($partitionPoints); ++$interval) {
                    $leftPoint = $partitionPoints[$interval - 1];
                    $rightPoint = $partitionPoints[$interval];
                    $midpoint = $leftPoint + (($rightPoint - $leftPoint) / 2.0);
                    if ($midpoint === $leftPoint || $midpoint === $rightPoint) {
                        continue;
                    }
                    $residual = $residualAt($midpoint);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $midpoint,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'Equation has infinitely many solutions in the requested interval.',
                        );
                    }
                }
                continue;
            }

            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                            fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                                $levelCoefficients,
                                $value,
                            ),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $invalidBoundary = false;
                foreach ($roundingBoundaries as $index => $boundaries) {
                    foreach ($boundaries as [$position, $output]) {
                        if (
                            $output !== (float) $combination[$index]
                            && \abs($root->value - $position)
                                <= $options->positionTolerance($root->value, $position)
                        ) {
                            $invalidBoundary = true;
                            break 2;
                        }
                    }
                }
                if ($invalidBoundary) {
                    continue;
                }
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRoundingPolynomialSumEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $terms = [];
        $this->flattenAdditiveTerms($left, 1.0, $terms);
        $this->flattenAdditiveTerms($right, -1.0, $terms);
        $function = null;
        $roundingCoefficient = 0.0;
        $remainder = [0.0];
        foreach ($terms as [$node, $sign]) {
            $factors = [];
            $this->flattenProductFactors($node, $factors);
            $roundingFactor = null;
            $coefficientFactors = [];
            foreach ($factors as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && \in_array($factor->name, ['floor', 'ceil', 'round', 'trunc'], true)
                ) {
                    if ($roundingFactor !== null || \count($factor->arguments) !== 1) {
                        return null;
                    }
                    $roundingFactor = $factor;
                    continue;
                }
                $coefficientFactors[] = $factor;
            }

            if ($roundingFactor !== null) {
                $coefficient = $sign;
                foreach ($coefficientFactors as $factor) {
                    $factorPolynomial = $this->extractPolynomial(
                        $extractor,
                        $factor,
                        $factor->span()->start,
                    );
                    if ($factorPolynomial === null || \count($factorPolynomial) !== 1) {
                        return null;
                    }
                    $coefficient *= $factorPolynomial[0];
                }
                if ($function !== null || !\is_finite($coefficient) || $coefficient === 0.0) {
                    return null;
                }
                $function = $roundingFactor;
                $roundingCoefficient = $coefficient;
                continue;
            }

            $polynomial = $this->extractPolynomial($extractor, $node, $node->span()->start);
            if ($polynomial === null) {
                return null;
            }
            $remainder = $this->combinePolynomialCoefficients($remainder, $polynomial, $sign);
            if ($remainder === null) {
                return null;
            }
        }
        if ($function === null || \count($remainder) < 2) {
            return null;
        }

        $argument = $function->arguments[0];
        $argumentRange = $this->boundedExpressionRange(
            $argument,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        $argumentForm = $extractor->extractRationalForm($argument);
        if (
            $argumentRange === null
            || $argumentForm === null
            || !\is_finite($argumentRange[0])
            || !\is_finite($argumentRange[1])
        ) {
            return null;
        }
        [$argumentMinimum, $argumentMaximum] = $argumentRange;
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if (
            $argumentMinimum < -$maximumExactInteger
            || $argumentMaximum > $maximumExactInteger
        ) {
            return null;
        }

        $round = static fn (float $value): float => match ($function->name) {
            'floor' => \floor($value),
            'ceil' => \ceil($value),
            'trunc' => $value < 0.0 ? \ceil($value) : \floor($value),
            default => \round($value),
        };
        $levelPadding = 1.0;
        $firstOutputLevel = $round($argumentMinimum) - $levelPadding;
        $lastOutputLevel = $round($argumentMaximum) + $levelPadding;
        if (
            $lastOutputLevel < $firstOutputLevel
            || $lastOutputLevel - $firstOutputLevel + 1.0 > self::MAX_MODULO_SCAN_WORK
        ) {
            return null;
        }

        $boundaryPoints = [];
        $rangeTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentMinimum), \abs($argumentMaximum));
        if ($function->name === 'round') {
            $firstBoundaryIndex = (int) \ceil($argumentMinimum - 0.5 - $rangeTolerance) - 1;
            $lastBoundaryIndex = (int) \floor($argumentMaximum - 0.5 + $rangeTolerance) + 1;
        } else {
            $firstBoundaryIndex = (int) \ceil($argumentMinimum - $rangeTolerance) - 1;
            $lastBoundaryIndex = (int) \floor($argumentMaximum + $rangeTolerance) + 1;
        }
        if ($lastBoundaryIndex - $firstBoundaryIndex + 1 > self::MAX_MODULO_SCAN_WORK) {
            return null;
        }
        $polynomialSolver = new PolynomialSolver();
        for ($index = $firstBoundaryIndex; $index <= $lastBoundaryIndex; ++$index) {
            $boundary = $function->name === 'round' ? $index + 0.5 : (float) $index;
            $boundaryPolynomial = $this->subtractScaledPolynomials(
                $argumentForm[0],
                $argumentForm[1],
                $boundary,
            );
            if ($boundaryPolynomial === null) {
                return null;
            }
            if (\count($boundaryPolynomial) === 1) {
                continue;
            }
            $roots = $polynomialSolver->solve(
                $boundaryPolynomial,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $boundaryPolynomial,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $boundaryPolynomial,
                    $value,
                ),
            );
            if ($roots === null) {
                return null;
            }
            $boundaryOutput = $round($boundary);
            foreach ($roots as $root) {
                $boundaryPoints[] = [$root->value, $boundaryOutput];
            }
        }

        $solutions = [];
        for (
            $level = (int) $firstOutputLevel;
            $level <= (int) $lastOutputLevel;
            ++$level
        ) {
            $levelCoefficients = $remainder;
            $levelCoefficients[0] += $roundingCoefficient * $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $roots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $levelCoefficients,
                    $value,
                ),
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $invalidAtBoundary = false;
                foreach ($boundaryPoints as [$boundaryPosition, $boundaryOutput]) {
                    if (
                        $boundaryOutput !== (float) $level
                        && \abs($root->value - $boundaryPosition)
                            <= $options->positionTolerance($root->value, $boundaryPosition)
                    ) {
                        $invalidAtBoundary = true;
                        break;
                    }
                }
                if ($invalidAtBoundary) {
                    continue;
                }
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialRoundingEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['floor', 'ceil', 'round', 'trunc'], true)
        ) {
            $function = $left;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['floor', 'ceil', 'round', 'trunc'], true)
        ) {
            $function = $right;
            $constant = $left;
        } else {
            return null;
        }

        if (\count($function->arguments) !== 1) {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients !== null && \count($targetCoefficients) > 1) {
            return $this->solveRoundingAgainstPolynomial(
                $function,
                $constant,
                $targetCoefficients,
                $variable,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        $argument = $function->arguments[0];
        $argumentCoefficients = $this->extractPolynomial(
            $extractor,
            $argument,
            $argument->span()->start,
        );
        $argumentForm = $extractor->extractRationalForm($argument);
        if (
            $targetCoefficients === null
            || \count($targetCoefficients) !== 1
            || $argumentForm === null
        ) {
            return null;
        }
        if ($argumentCoefficients !== null) {
            $argumentForm = [$argumentCoefficients, [1.0]];
        }
        [$argumentNumerator, $argumentDenominator] = $argumentForm;
        if ($argumentDenominator === [0.0]) {
            return null;
        }

        $target = $targetCoefficients[0];
        if (!\is_finite($target) || \floor($target) !== $target) {
            return [];
        }
        if (\abs($target) > 9_007_199_254_740_991.0) {
            return null;
        }

        $levels = match ($function->name) {
            'floor' => [$target, $target + 1.0],
            'ceil' => [$target - 1.0, $target],
            'round' => [$target - 0.5, $target + 0.5],
            'trunc' => $target > 0.0
                ? [$target, $target + 1.0]
                : ($target < 0.0 ? [$target - 1.0, $target] : [-1.0, 1.0]),
            default => null,
        };
        if ($levels === null) {
            return null;
        }
        if (!\is_finite($levels[0]) || !\is_finite($levels[1]) || $levels[0] === $levels[1]) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $partitionPoints = [$lowerBound, $upperBound];
        if (\count($argumentDenominator) > 1) {
            $denominatorRoots = $polynomialSolver->solve(
                $argumentDenominator,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $argumentDenominator,
                    $value,
                ),
                $options,
            );
            if ($denominatorRoots === null) {
                return null;
            }
            foreach ($denominatorRoots as $denominatorRoot) {
                $partitionPoints[] = $denominatorRoot->value;
            }
        }
        foreach ($levels as $level) {
            $levelCoefficients = $this->subtractScaledPolynomials(
                $argumentNumerator,
                $argumentDenominator,
                $level,
            );
            if ($levelCoefficients === null) {
                return null;
            }
            if (\count($levelCoefficients) === 1) {
                continue;
            }

            $levelRoots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
            );
            if ($levelRoots === null) {
                return null;
            }
            foreach ($levelRoots as $levelRoot) {
                $candidate = $levelRoot->value;
                $partitionPoints[] = $candidate;
                $residual = $residualAt($candidate);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), $levelRoot->iterations),
                    $options,
                );
            }
        }

        \sort($partitionPoints, \SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, \SORT_REGULAR));
        for ($index = 1, $count = \count($partitionPoints); $index < $count; ++$index) {
            $left = $partitionPoints[$index - 1];
            $right = $partitionPoints[$index];
            $midpoint = $partitionPoints[$index - 1]
                + (($partitionPoints[$index] - $partitionPoints[$index - 1]) / 2.0);
            if (
                $midpoint === $left
                || $midpoint === $right
                || $right - $left
                    <= 8.0 * \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, \abs($left), \abs($right))
            ) {
                continue;
            }
            $residual = $residualAt($midpoint);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $midpoint,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve a rounding-function equation against a non-constant polynomial.
     *
     * @param list<float> $otherCoefficients
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRoundingAgainstPolynomial(
        FunctionCallNode $function,
        Node $otherSide,
        array $otherCoefficients,
        string $variable,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        if (
            \count($function->arguments) !== 1
            || !$this->containsVariable($otherSide, $variable)
        ) {
            return null;
        }

        $range = $this->polynomialRange(
            $otherCoefficients,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($range === null) {
            return null;
        }
        [$minimum, $maximum] = $range;
        $maximumExactInteger = 9_007_199_254_740_991.0;
        if ($minimum < -$maximumExactInteger || $maximum > $maximumExactInteger) {
            return null;
        }

        $tolerance = 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($minimum), \abs($maximum));
        $firstLevel = \ceil($minimum - $tolerance);
        $lastLevel = \floor($maximum + $tolerance);
        if ($firstLevel > $lastLevel) {
            return [];
        }
        $levelCount = $lastLevel - $firstLevel + 1.0;
        if ($levelCount > self::MAX_MODULO_SCAN_WORK) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        for ($level = (int) $firstLevel; $level <= (int) $lastLevel; ++$level) {
            $levelCoefficients = $otherCoefficients;
            $levelCoefficients[0] -= $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $levelRoots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
            );
            if ($levelRoots === null) {
                return null;
            }
            foreach ($levelRoots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalExtremaEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['min', 'max'], true)
        ) {
            $function = $left;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['min', 'max'], true)
        ) {
            $function = $right;
            $constant = $left;
        } else {
            return null;
        }

        if ($function->arguments === []) {
            return null;
        }
        $targetForm = $extractor->extractRationalForm($constant);
        if ($targetForm === null) {
            return null;
        }

        $argumentForms = [];
        foreach ($function->arguments as $argument) {
            $form = $extractor->extractRationalForm($argument);
            if ($form === null) {
                return null;
            }
            $argumentForms[] = $form;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $partitionPoints = [$lowerBound, $upperBound];
        $candidateCount = 0;
        foreach ([...$argumentForms, $targetForm] as [, $denominator]) {
            if ($denominator === [1.0] || \count($denominator) === 1) {
                continue;
            }
            $partitionRootsAdded = $this->appendPolynomialPartitionRoots(
                $denominator,
                $polynomialSolver,
                $lowerBound,
                $upperBound,
                $options,
                $partitionPoints,
                $solutions,
                $candidateCount,
                $residualAt,
                $candidateScaleAt,
            );
            if (!$partitionRootsAdded) {
                return null;
            }
        }

        foreach ($function->arguments as $argument) {
            $difference = $extractor->extractRationalDifference($argument, $constant);
            if ($difference === null) {
                return null;
            }
            if ($difference === [0.0]) {
                continue;
            }
            $partitionRootsAdded = $this->appendPolynomialPartitionRoots(
                $difference,
                $polynomialSolver,
                $lowerBound,
                $upperBound,
                $options,
                $partitionPoints,
                $solutions,
                $candidateCount,
                $residualAt,
                $candidateScaleAt,
            );
            if (!$partitionRootsAdded) {
                return null;
            }
        }

        $argumentCount = \count($function->arguments);
        for ($first = 0; $first < $argumentCount; ++$first) {
            for ($second = $first + 1; $second < $argumentCount; ++$second) {
                $difference = $extractor->extractRationalDifference(
                    $function->arguments[$first],
                    $function->arguments[$second],
                );
                if ($difference === null) {
                    return null;
                }
                if ($difference === [0.0]) {
                    continue;
                }
                $partitionRootsAdded = $this->appendPolynomialPartitionRoots(
                    $difference,
                    $polynomialSolver,
                    $lowerBound,
                    $upperBound,
                    $options,
                    $partitionPoints,
                    $solutions,
                    $candidateCount,
                    $residualAt,
                    $candidateScaleAt,
                );
                if (!$partitionRootsAdded) {
                    return null;
                }
            }
        }

        \sort($partitionPoints, \SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
        foreach ($partitionPoints as $point) {
            $residual = $residualAt($point);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $point,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                $this->addSolution(
                    $solutions,
                    new EquationSolution($point, \abs($residual), 0),
                    $options,
                );
            }
        }
        for ($index = 1, $count = \count($partitionPoints); $index < $count; ++$index) {
            $left = $partitionPoints[$index - 1];
            $right = $partitionPoints[$index];
            $midpoint = $partitionPoints[$index - 1]
                + (($partitionPoints[$index] - $partitionPoints[$index - 1]) / 2.0);
            if (
                $midpoint === $left
                || $midpoint === $right
                || $right - $left
                    <= 8.0 * \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, \abs($left), \abs($right))
            ) {
                continue;
            }
            $residual = $residualAt($midpoint);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $midpoint,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $coefficients
     * @param list<float> $partitionPoints
     * @param list<EquationSolution> $solutions
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     */
    private function appendPolynomialPartitionRoots(
        array $coefficients,
        PolynomialSolver $polynomialSolver,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        array &$partitionPoints,
        array &$solutions,
        int &$candidateCount,
        callable $residualAt,
        callable $candidateScaleAt,
    ): bool {
        if ($coefficients === [] || \count($coefficients) === 1) {
            return $coefficients !== [];
        }
        $roots = $polynomialSolver->solve(
            $coefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $coefficients,
                $value,
            ),
            $options,
        );
        if ($roots === null) {
            return false;
        }
        foreach ($roots as $root) {
            if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                return false;
            }
            $partitionPoints[] = $root->value;
            $residual = $residualAt($root->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $root->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($root->value, \abs($residual), $root->iterations),
                $options,
            );
        }

        return true;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialAtan2Equation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && $left->name === 'atan2') {
            $function = $left;
            $constant = $right;
            $functionSource = $leftSource;
            $functionSourceOffset = 0;
        } elseif ($right instanceof FunctionCallNode && $right->name === 'atan2') {
            $function = $right;
            $constant = $left;
            $functionSource = $rightSource;
            $functionSourceOffset = $rightSourceOffset;
        } else {
            return null;
        }

        if (
            \count($function->arguments) !== 2
            || $this->containsVariable($constant, $variable)
        ) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }

        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }
        if ($target < -\M_PI || $target > \M_PI) {
            return [];
        }

        $firstContainsVariable = $this->containsVariable(
            $function->arguments[0],
            $variable,
        );
        $secondContainsVariable = $this->containsVariable(
            $function->arguments[1],
            $variable,
        );
        if ($firstContainsVariable !== $secondContainsVariable) {
            $variableIndex = $firstContainsVariable ? 0 : 1;
            $constantIndex = 1 - $variableIndex;
            $constantCoefficients = $extractor->extract(
                $function->arguments[$constantIndex],
            );
            $variableRationalForm = $extractor->extractRationalForm(
                $function->arguments[$variableIndex],
            );
            if (
                $constantCoefficients !== null
                && \count($constantCoefficients) === 1
                && $variableRationalForm === null
            ) {
                $constantCoordinate = $constantCoefficients[0];
                if (!\is_finite($constantCoordinate)) {
                    return null;
                }
                if ($constantCoordinate === 0.0) {
                    $variableArgument = $function->arguments[$variableIndex];
                    $argumentSpan = $variableArgument->span();
                    $argumentSource = \substr(
                        $functionSource,
                        $argumentSpan->start - $functionSourceOffset,
                        $argumentSpan->end - $argumentSpan->start,
                    );
                    if (
                        $argumentSource === ''
                        || \strlen($argumentSource) + 24
                            > $evaluationOptions->limits->maxExpressionLength
                    ) {
                        return null;
                    }
                    if ($variableIndex === 0) {
                        if ($target === \M_PI_2) {
                            $positiveRegion = true;
                        } elseif ($target === -\M_PI_2) {
                            $positiveRegion = false;
                        } else {
                            return [];
                        }
                    } else {
                        $positiveAxisAngle = \atan2($constantCoordinate, 1.0);
                        $negativeAxisAngle = \atan2($constantCoordinate, -1.0);
                        if ($target === $positiveAxisAngle) {
                            $positiveRegion = true;
                        } elseif ($target === $negativeAxisAngle) {
                            $positiveRegion = false;
                        } else {
                            return [];
                        }
                    }
                    $signIntervals = (new InequalitySolver())->solve(
                        '(' . $argumentSource . ')' . ($positiveRegion ? '>0' : '<0'),
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                    $solutions = [];
                    foreach ($signIntervals as $interval) {
                        if ($interval->lowerBound < $interval->upperBound) {
                            throw new InfiniteSolutionSetException(
                                'The atan2 equation is constant on a nonempty strict-sign interval.',
                            );
                        }
                        $candidate = $interval->lowerBound;
                        $residual = $residualAt($candidate);
                        if (
                            $residual === null
                            || !$this->isResidualAcceptableAt(
                                $candidate,
                                $residual,
                                $candidateScaleAt,
                                $options,
                            )
                        ) {
                            continue;
                        }
                        $this->addSolution(
                            $solutions,
                            new EquationSolution($candidate, \abs($residual), 0),
                            $options,
                        );
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }

                if ($variableIndex === 0) {
                    $angleIsReachable = $constantCoordinate > 0.0
                        ? $target > -\M_PI_2 && $target < \M_PI_2
                        : (($target >= -\M_PI && $target < -\M_PI_2)
                            || ($target > \M_PI_2 && $target <= \M_PI));
                    if (!$angleIsReachable) {
                        return [];
                    }
                    $level = \abs($target) === \M_PI
                        ? 0.0
                        : $constantCoordinate * \tan($target);
                } else {
                    $angleIsReachable = $constantCoordinate > 0.0
                        ? $target > 0.0 && $target < \M_PI
                        : $target > -\M_PI && $target < 0.0;
                    if (!$angleIsReachable) {
                        return [];
                    }
                    $level = \abs($target) === \M_PI_2
                        ? 0.0
                        : $constantCoordinate / \tan($target);
                }
                if (!\is_finite($level)) {
                    return null;
                }
                $variableArgument = $function->arguments[$variableIndex];
                $argumentSpan = $variableArgument->span();
                $argumentSource = \substr(
                    $functionSource,
                    $argumentSpan->start - $functionSourceOffset,
                    $argumentSpan->end - $argumentSpan->start,
                );
                if (
                    $argumentSource === ''
                    || \strlen($argumentSource) + 24
                        > $evaluationOptions->limits->maxExpressionLength
                ) {
                    return null;
                }
                $solutions = [];
                foreach (
                    $this->solve(
                        $argumentSource . '=' . \sprintf('%.17g', $level),
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    ) as $candidate
                ) {
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        continue;
                    }
                    $this->addSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                        $options,
                    );
                }
                \usort(
                    $solutions,
                    static fn (EquationSolution $first, EquationSolution $second): int =>
                        $first->value <=> $second->value,
                );

                return $solutions;
            }
        }

        $yForm = $extractor->extractRationalForm($function->arguments[0]);
        $xForm = $extractor->extractRationalForm($function->arguments[1]);
        if ($yForm === null || $xForm === null) {
            return null;
        }
        [$yNumerator, $yDenominator] = $yForm;
        [$xNumerator, $xDenominator] = $xForm;
        if ($target === 0.0 || \abs($target) === \M_PI) {
            $coefficients = $yNumerator;
        } elseif (\abs($target) === (\M_PI / 2.0)) {
            $coefficients = $xNumerator;
        } else {
            $diagonalAngle = \abs($target) === (\M_PI / 4.0)
                || \abs($target) === (3.0 * \M_PI / 4.0);
            if ($diagonalAngle) {
                $diagonalMagnitude = \sqrt(0.5);
                $sine = $target < 0.0 ? -$diagonalMagnitude : $diagonalMagnitude;
                $cosine = \abs($target) < (\M_PI / 2.0)
                    ? $diagonalMagnitude
                    : -$diagonalMagnitude;
            } else {
                $sine = \sin($target);
                $cosine = \cos($target);
            }
            $yTerm = $this->scaledPolynomial(
                $this->multiplyPolynomials($yNumerator, $xDenominator),
                $cosine,
            );
            $xTerm = $this->scaledPolynomial(
                $this->multiplyPolynomials($xNumerator, $yDenominator),
                $sine,
            );
            $coefficients = $this->addPolynomials($yTerm, $xTerm, -1.0);
            foreach ($coefficients as $coefficient) {
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }
        }
        while (\count($coefficients) > 1 && $coefficients[\count($coefficients) - 1] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) - 1 > $options->maxPolynomialDegree) {
            return null;
        }

        if (\count($coefficients) === 1) {
            return $coefficients[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        $candidates = $polynomialSolver->solve(
            $coefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $coefficients,
                $value,
            ),
            $options,
        );
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $atDenominatorHole = false;
            foreach ($function->arguments as $argument) {
                $hole = $this->isNearOriginalDenominatorRoot(
                    $argument,
                    $candidate->value,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($hole === null) {
                    return null;
                }
                if ($hole) {
                    $atDenominatorHole = true;
                    break;
                }
            }
            if ($atDenominatorHole) {
                continue;
            }
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function isNearOriginalDenominatorRoot(
        Node $node,
        float $candidate,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?bool {
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Divide) {
                $denominator = $extractor->extractRationalForm($node->right);
                if ($denominator === null) {
                    return null;
                }
                $numerator = $denominator[0];
                if ($numerator === [0.0]) {
                    return true;
                }
                if (\count($numerator) > 1) {
                    $polynomialSolver = new PolynomialSolver();
                    $roots = $polynomialSolver->solve(
                        $numerator,
                        $lowerBound,
                        $upperBound,
                        fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                            $numerator,
                            $value,
                        ),
                        $options,
                    );
                    if ($roots === null) {
                        return null;
                    }
                    foreach ($roots as $root) {
                        $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                            * \max(1.0, \abs($root->value), \abs($candidate));
                        if (\abs($root->value - $candidate) <= $tolerance) {
                            return true;
                        }
                    }
                }
            }

            foreach ([$node->left, $node->right] as $child) {
                $hole = $this->isNearOriginalDenominatorRoot(
                    $child,
                    $candidate,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($hole !== false) {
                    return $hole;
                }
            }
        } elseif ($node instanceof UnaryOperationNode) {
            return $this->isNearOriginalDenominatorRoot(
                $node->operand,
                $candidate,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
        } elseif ($node instanceof GroupingNode) {
            return $this->isNearOriginalDenominatorRoot(
                $node->expression,
                $candidate,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
        } elseif ($node instanceof FactorialNode) {
            return $this->isNearOriginalDenominatorRoot(
                $node->operand,
                $candidate,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
        } elseif ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                $hole = $this->isNearOriginalDenominatorRoot(
                    $argument,
                    $candidate,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($hole !== false) {
                    return $hole;
                }
            }
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialHypotenuseEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $leftIsHypotenuse = $left instanceof FunctionCallNode && $left->name === 'hypot';
        if ($leftIsHypotenuse) {
            $function = $left;
            $constant = $right;
            $functionSourceOffset = 0;
        } elseif ($right instanceof FunctionCallNode && $right->name === 'hypot') {
            $function = $right;
            $constant = $left;
            $functionSourceOffset = $rightSourceOffset;
        } else {
            return null;
        }
        $functionSource = $leftIsHypotenuse ? $leftSource : $rightSource;

        if (
            \count($function->arguments) !== 2
            || $this->containsVariable($constant, $variable)
        ) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        $first = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        $second = $this->extractPolynomial(
            $extractor,
            $function->arguments[1],
            $function->arguments[1]->span()->start,
        );
        if (
            $targetCoefficients === null
            || \count($targetCoefficients) !== 1
        ) {
            return null;
        }

        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }
        if ($target < 0.0) {
            return [];
        }
        if ($first === null || $second === null) {
            $firstContainsVariable = $this->containsVariable(
                $function->arguments[0],
                $variable,
            );
            $secondContainsVariable = $this->containsVariable(
                $function->arguments[1],
                $variable,
            );
            if ($firstContainsVariable !== $secondContainsVariable) {
                $variableIndex = $firstContainsVariable ? 0 : 1;
                $constantIndex = 1 - $variableIndex;
                $constantCoefficients = $extractor->extract(
                    $function->arguments[$constantIndex],
                );
                $variableRationalForm = $extractor->extractRationalForm(
                    $function->arguments[$variableIndex],
                );
                if (
                    $constantCoefficients !== null
                    && \count($constantCoefficients) === 1
                    && $variableRationalForm === null
                ) {
                    $constantValue = $constantCoefficients[0];
                    if (!\is_finite($constantValue)) {
                        return null;
                    }
                    $constantMagnitude = \abs($constantValue);
                    if ($target < $constantMagnitude) {
                        return [];
                    }
                    $magnitude = 0.0;
                    if ($target > $constantMagnitude) {
                        $magnitude = \sqrt($target - $constantMagnitude)
                            * \sqrt($target)
                            * \sqrt(1.0 + ($constantMagnitude / $target));
                        if (!\is_finite($magnitude)) {
                            return null;
                        }
                    }
                    $variableArgument = $function->arguments[$variableIndex];
                    $argumentSpan = $variableArgument->span();
                    $argumentSource = \substr(
                        $functionSource,
                        $argumentSpan->start - $functionSourceOffset,
                        $argumentSpan->end - $argumentSpan->start,
                    );
                    if (
                        $argumentSource === ''
                        || \strlen($argumentSource) + 24
                            > $evaluationOptions->limits->maxExpressionLength
                    ) {
                        return null;
                    }

                    $solutions = [];
                    $levels = $magnitude === 0.0 ? [0.0] : [$magnitude, -$magnitude];
                    foreach ($levels as $level) {
                        foreach (
                            $this->solve(
                                $argumentSource . '=' . \sprintf('%.17g', $level),
                                $variable,
                                $lowerBound,
                                $upperBound,
                                $parameters,
                                $evaluationOptions,
                                $options,
                            ) as $candidate
                        ) {
                            $residual = $residualAt($candidate->value);
                            if (
                                $residual === null
                                || !$this->isResidualAcceptableAt(
                                    $candidate->value,
                                    $residual,
                                    $candidateScaleAt,
                                    $options,
                                )
                            ) {
                                continue;
                            }
                            $this->addSolution(
                                $solutions,
                                new EquationSolution(
                                    $candidate->value,
                                    \abs($residual),
                                    $candidate->iterations,
                                ),
                                $options,
                            );
                        }
                    }
                    \usort(
                        $solutions,
                        static fn (EquationSolution $first, EquationSolution $second): int =>
                            $first->value <=> $second->value,
                    );

                    return $solutions;
                }
            }
            $yForm = $extractor->extractRationalForm($function->arguments[0]);
            $xForm = $extractor->extractRationalForm($function->arguments[1]);
            if ($yForm === null || $xForm === null) {
                if ($target === 0.0) {
                    return $this->solveNonRationalHypotenuseZero(
                        $function->arguments[0],
                        $function->arguments[1],
                        $functionSource,
                        $functionSourceOffset,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $extractor,
                        $options,
                        $residualAt,
                        $candidateScaleAt,
                    );
                }

                return null;
            }

            return $this->solveRationalHypotenuseEquation(
                $yForm,
                $xForm,
                $function->arguments[0],
                $function->arguments[1],
                $functionSource,
                $functionSourceOffset,
                $variable,
                $parameters,
                $evaluationOptions,
                $extractor,
                $target,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        if ($target === 0.0) {
            if ($first === [0.0] && $second === [0.0]) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
            if (
                ($first !== [0.0] && \count($first) === 1)
                || ($second !== [0.0] && \count($second) === 1)
            ) {
                return [];
            }

            $seedNode = $first === [0.0]
                ? $function->arguments[1]
                : ($second === [0.0] || \count($first) <= \count($second)
                    ? $function->arguments[0]
                    : $function->arguments[1]);
            $candidates = $this->solveNodeAtZero(
                $seedNode,
                $functionSource,
                $functionSourceOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            if ($candidates === null) {
                return null;
            }

            $solutions = [];
            foreach ($candidates as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }

            return $solutions;
        }

        if (
            \count($first) === 1
            && $first[0] === 0.0
            && \count($second) === 2
        ) {
            $coordinate = $second;
        } elseif (
            \count($second) === 1
            && $second[0] === 0.0
            && \count($first) === 2
        ) {
            $coordinate = $first;
        } else {
            $coordinate = null;
        }
        if ($coordinate !== null) {
            if ($coordinate[1] === 0.0) {
                return null;
            }

            $solutions = [];
            foreach ($target === 0.0 ? [0.0] : [-$target, $target] as $level) {
                $candidate = ($level - $coordinate[0]) / $coordinate[1];
                if (
                    !\is_finite($candidate)
                    || $candidate < $lowerBound
                    || $candidate > $upperBound
                ) {
                    continue;
                }
                $residual = $residualAt($candidate);
                $residualLimit = $options->residualTolerance * $target;
                if ($target > 0.0) {
                    $residualLimit = \max(
                        $residualLimit,
                        8.0 * \PHP_FLOAT_EPSILON * $target,
                    );
                }
                if ($residual === null || \abs($residual) > $residualLimit) {
                    return null;
                }
                $candidate = $candidate == 0.0 ? 0.0 : $candidate;
                $duplicate = false;
                foreach ($solutions as $solution) {
                    if ($solution->value === $candidate) {
                        $duplicate = true;
                        break;
                    }
                }
                if (!$duplicate) {
                    $solutions[] = new EquationSolution(
                        $candidate,
                        \abs($residual),
                        0,
                    );
                }
            }
            \usort(
                $solutions,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    $first->value <=> $second->value,
            );

            return $solutions;
        }

        $degree = \max(\count($first), \count($second)) - 1;
        if (2 * $degree > $options->maxPolynomialDegree) {
            return null;
        }
        $coefficients = \array_fill(0, (2 * $degree) + 1, 0.0);
        foreach ([$first, $second] as $polynomial) {
            foreach ($polynomial as $firstDegree => $firstCoefficient) {
                foreach ($polynomial as $secondDegree => $secondCoefficient) {
                    $index = $firstDegree + $secondDegree;
                    $coefficient = $coefficients[$index]
                        + ($firstCoefficient * $secondCoefficient);
                    if (!\is_finite($coefficient)) {
                        return null;
                    }
                    $coefficients[$index] = $coefficient;
                }
            }
        }

        $targetSquare = $target * $target;
        if (!\is_finite($targetSquare)) {
            return null;
        }
        $coefficients[0] -= $targetSquare;
        if (!\is_finite($coefficients[0])) {
            return null;
        }
        while (\count($coefficients) > 1 && $coefficients[\count($coefficients) - 1] === 0.0) {
            \array_pop($coefficients);
        }
        $coefficients = \array_values($coefficients);
        if (\count($coefficients) === 1) {
            return $coefficients[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        $candidates = $polynomialSolver->solve(
            $coefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $coefficients,
                $value,
            ),
            $options,
        );
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNonRationalHypotenuseZero(
        Node $first,
        Node $second,
        string $source,
        int $sourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        PolynomialExtractor $extractor,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $arguments = [$first, $second];
        $identicallyZero = [];
        foreach ($arguments as $index => $argument) {
            $form = $extractor->extractRationalForm($argument);
            if ($form !== null && $form[0] === [0.0]) {
                $identicallyZero[$index] = true;
            }
        }
        if (\count($identicallyZero) === 2) {
            throw new InfiniteSolutionSetException(
                'Equation has infinitely many solutions in the requested interval.',
            );
        }

        $candidates = [];
        $couldNotSolve = false;
        foreach ($arguments as $index => $argument) {
            if (isset($identicallyZero[$index])) {
                continue;
            }
            try {
                $roots = $this->solveNodeAtZero(
                    $argument,
                    $source,
                    $sourceOffset,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                );
            } catch (InfiniteSolutionSetException) {
                $couldNotSolve = true;
                continue;
            }
            if ($roots === null) {
                $couldNotSolve = true;
                continue;
            }
            foreach ($roots as $root) {
                $candidates[] = $root;
            }
        }

        if ($candidates === []) {
            return $couldNotSolve ? null : [];
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                continue;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution(
                    $candidate->value,
                    \abs($residual),
                    $candidate->iterations,
                ),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );

        return $solutions;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveNodeAtZero(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): ?array {
        $span = $node->span();
        $nodeSource = \substr($source, $span->start, $span->end - $span->start);
        $equation = $nodeSource . '=0';
        if (
            $nodeSource === ''
            || \strlen($equation) > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        return $this->solve(
            $equation,
            $variable,
            $lowerBound,
            $upperBound,
            $parameters,
            $evaluationOptions,
            $options,
        );
    }

    /**
     * @param array{list<float>, list<float>} $first
     * @param array{list<float>, list<float>} $second
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalHypotenuseEquation(
        array $first,
        array $second,
        Node $firstArgument,
        Node $secondArgument,
        string $equation,
        int $sourceOffset,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        PolynomialExtractor $extractor,
        float $target,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        [$firstNumerator, $firstDenominator] = $first;
        [$secondNumerator, $secondDenominator] = $second;
        if ($target === 0.0) {
            if ($firstDenominator === [0.0] || $secondDenominator === [0.0]) {
                return [];
            }
            if ($firstNumerator === [0.0] && $secondNumerator === [0.0]) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }
            if (
                ($firstNumerator !== [0.0] && \count($firstNumerator) === 1)
                || ($secondNumerator !== [0.0] && \count($secondNumerator) === 1)
            ) {
                return [];
            }

            $seedNode = $firstNumerator === [0.0]
                ? $secondArgument
                : ($secondNumerator === [0.0]
                    || \count($firstNumerator) <= \count($secondNumerator)
                        ? $firstArgument
                        : $secondArgument);
            $candidates = $this->solveNodeAtZero(
                $seedNode,
                $equation,
                $sourceOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $options,
            );
            if ($candidates === null) {
                return null;
            }

            $solutions = [];
            foreach ($candidates as $candidate) {
                $atDenominatorHole = false;
                foreach ([$firstArgument, $secondArgument] as $argument) {
                    $hole = $this->isNearOriginalDenominatorRoot(
                        $argument,
                        $candidate->value,
                        $extractor,
                        $lowerBound,
                        $upperBound,
                        $options,
                    );
                    if ($hole === null) {
                        return null;
                    }
                    if ($hole) {
                        $atDenominatorHole = true;
                        break;
                    }
                }
                if ($atDenominatorHole) {
                    continue;
                }

                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }

            return $solutions;
        }

        $maximumDegree = (2 * (\count($firstNumerator) - 1))
            + (2 * (\count($secondDenominator) - 1));
        $maximumDegree = \max(
            $maximumDegree,
            (2 * (\count($secondNumerator) - 1))
                + (2 * (\count($firstDenominator) - 1)),
            (2 * (\count($firstDenominator) - 1))
                + (2 * (\count($secondDenominator) - 1)),
        );
        if ($maximumDegree > $options->maxPolynomialDegree) {
            return null;
        }

        $firstNumeratorSquared = $this->multiplyPolynomials($firstNumerator, $firstNumerator);
        $firstDenominatorSquared = $this->multiplyPolynomials(
            $firstDenominator,
            $firstDenominator,
        );
        $secondNumeratorSquared = $this->multiplyPolynomials($secondNumerator, $secondNumerator);
        $secondDenominatorSquared = $this->multiplyPolynomials(
            $secondDenominator,
            $secondDenominator,
        );
        $firstTerm = $this->multiplyPolynomials($firstNumeratorSquared, $secondDenominatorSquared);
        $secondTerm = $this->multiplyPolynomials($secondNumeratorSquared, $firstDenominatorSquared);
        $denominatorProduct = $this->multiplyPolynomials(
            $firstDenominatorSquared,
            $secondDenominatorSquared,
        );
        foreach (
            [
                ...$firstNumeratorSquared,
                ...$firstDenominatorSquared,
                ...$secondNumeratorSquared,
                ...$secondDenominatorSquared,
                ...$firstTerm,
                ...$secondTerm,
                ...$denominatorProduct,
            ] as $coefficient
        ) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        $targetSquare = $target * $target;
        if (!\is_finite($targetSquare)) {
            return null;
        }
        $coefficients = $this->addPolynomials($firstTerm, $secondTerm);
        $coefficients = $this->addPolynomials(
            $coefficients,
            $this->scaledPolynomial($denominatorProduct, -$targetSquare),
        );
        foreach ($coefficients as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }
        while (\count($coefficients) > 1 && $coefficients[\array_key_last($coefficients)] === 0.0) {
            \array_pop($coefficients);
        }
        if (\count($coefficients) === 1) {
            return $coefficients[0] === 0.0 ? null : [];
        }

        $polynomialSolver = new PolynomialSolver();
        $candidates = $polynomialSolver->solve(
            $coefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $coefficients,
                $value,
            ),
            $options,
        );
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if ($residual === null) {
                continue;
            }
            if (
                !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialRadicandRoot(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && $left->name === 'root') {
            $function = $left;
            $constant = $right;
        } elseif ($right instanceof FunctionCallNode && $right->name === 'root') {
            $function = $right;
            $constant = $left;
        } else {
            return null;
        }

        if (
            \count($function->arguments) !== 2
            || $this->containsVariable($constant, $variable)
        ) {
            return null;
        }

        [$radicand, $degreeNode] = $function->arguments;
        $radicandCoefficients = $this->extractPolynomial(
            $extractor,
            $radicand,
            $radicand->span()->start,
        );
        $degreeCoefficients = $this->extractPolynomial(
            $extractor,
            $degreeNode,
            $degreeNode->span()->start,
        );
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if (
            $radicandCoefficients === null
            || \count($radicandCoefficients) < 2
            || $degreeCoefficients === null
            || \count($degreeCoefficients) !== 1
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
        ) {
            return null;
        }

        $normalizedDegree = $this->normalizedIntegerRootDegree($degreeCoefficients[0]);
        if ($normalizedDegree === null) {
            return null;
        }
        $degree = (float) $normalizedDegree;
        $target = $targetCoefficients[0];
        if (
            !\is_finite($target)
        ) {
            return null;
        }

        $order = \abs($degree);
        $evenDegree = \fmod($order, 2.0) === 0.0;
        if ($degree < 0.0) {
            if ($target === 0.0 || ($evenDegree && $target < 0.0)) {
                return [];
            }
            $base = 1.0 / $target;
        } else {
            if ($evenDegree && $target < 0.0) {
                return [];
            }
            $base = $target;
        }

        $level = \pow(\abs($base), $order);
        if (!\is_finite($level) || ($base !== 0.0 && $level === 0.0)) {
            if (
                \count($radicandCoefficients) === 2
                && $radicandCoefficients[1] !== 0.0
                && \is_finite($base)
            ) {
                $slope = $radicandCoefficients[1];
                $scaledBase = \abs($base) / \pow(\abs($slope), 1.0 / $order);
                $scaledLevel = \pow($scaledBase, $order);
                if (!\is_finite($scaledLevel)) {
                    return [];
                }
                $signedLevel = $base < 0.0 && !$evenDegree
                    ? -$scaledLevel
                    : $scaledLevel;
                $candidate = ($signedLevel - $radicandCoefficients[0]) / $slope;
                if (
                    !\is_finite($candidate)
                    || $candidate < $lowerBound
                    || $candidate > $upperBound
                ) {
                    return [];
                }
                $residual = $residualAt($candidate);
                $residualLimit = \max(
                    $options->residualTolerance,
                    8.0 * \PHP_FLOAT_EPSILON,
                ) * \abs($target);
                if ($residual === null || \abs($residual) > $residualLimit) {
                    return [];
                }

                return [
                    new EquationSolution(
                        $candidate == 0.0 ? 0.0 : $candidate,
                        \abs($residual),
                        0,
                    ),
                ];
            }

            return null;
        }
        if ($base < 0.0 && !$evenDegree) {
            $level = -$level;
        }

        $levelCoefficients = $radicandCoefficients;
        $levelCoefficients[0] -= $level;
        if (!\is_finite($levelCoefficients[0])) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $candidates = $polynomialSolver->solve(
            $levelCoefficients,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $levelCoefficients,
                $value,
            ),
            $options,
        );
        if ($candidates === null) {
            return null;
        }

        $solutions = [];
        foreach ($candidates as $candidate) {
            $residual = $residualAt($candidate->value);
            if (
                $residual === null
                || !$this->isResidualAcceptableAt(
                    $candidate->value,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                return null;
            }
            $this->addSolution(
                $solutions,
                new EquationSolution($candidate->value, \abs($residual), $candidate->iterations),
                $options,
            );
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function inverseSecantLevel(float $value): float
    {
        if (\abs($value) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return 1.0;
        }
        if (\abs($value - \M_PI) <= 8.0 * \PHP_FLOAT_EPSILON * \M_PI) {
            return -1.0;
        }
        if (\abs($value - (\M_PI / 3.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return 2.0;
        }
        if (\abs($value - (2.0 * \M_PI / 3.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return -2.0;
        }

        return 1.0 / \cos($value);
    }

    private function inverseCosecantLevel(float $value): float
    {
        if (\abs($value - (\M_PI / 2.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return 1.0;
        }
        if (\abs($value + (\M_PI / 2.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return -1.0;
        }
        if (\abs($value - (\M_PI / 6.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return 2.0;
        }
        if (\abs($value + (\M_PI / 6.0)) <= 8.0 * \PHP_FLOAT_EPSILON) {
            return -2.0;
        }

        return 1.0 / \sin($value);
    }

    private function inverseCotangentLevel(float $value): float
    {
        foreach (
            [
                [\M_PI / 2.0, 0.0],
                [\M_PI / 4.0, 1.0],
                [3.0 * \M_PI / 4.0, -1.0],
            ] as [$angle, $level]
        ) {
            if (\abs($value - $angle) <= 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($angle))) {
                return $level;
            }
        }

        return \cos($value) / \sin($value);
    }

    private function inverseSechLevel(float $value): float
    {
        return \log1p(\sqrt(1.0 - ($value * $value))) - \log($value);
    }

    private function inverseCschLevel(float $value): float
    {
        $absolute = \abs($value);
        if ($absolute >= 1.0) {
            return \asinh(1.0 / $value);
        }

        $level = \log1p(\sqrt(1.0 + ($absolute * $absolute))) - \log($absolute);

        return $value < 0.0 ? -$level : $level;
    }

    private function hyperbolicCosecantValue(float $value): float
    {
        $absolute = \abs($value);
        if ($absolute < 20.0) {
            return 1.0 / \sinh($value);
        }

        $exponential = \exp(-$absolute);
        $magnitude = (2.0 * $exponential) / (1.0 - ($exponential * $exponential));

        return $value < 0.0 ? -$magnitude : $magnitude;
    }

    private function hyperbolicSecantValue(float $value): float
    {
        $exponential = \exp(-\abs($value));

        return (2.0 * $exponential) / (1.0 + ($exponential * $exponential));
    }

    private function hyperbolicCotangentValue(float $value): float
    {
        $absolute = \abs($value);
        $exponential = \exp(-2.0 * $absolute);
        $denominator = -\expm1(-2.0 * $absolute);
        if ($denominator === 0.0) {
            return $value < 0.0 ? -\INF : \INF;
        }

        $magnitude = (1.0 + $exponential) / $denominator;

        return $value < 0.0 ? -$magnitude : $magnitude;
    }

    private function inverseErrorFunctionLevel(float $value): ?float
    {
        if (!\is_finite($value) || \abs($value) >= 1.0) {
            return null;
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $target = \abs($value);
        $lower = 0.0;
        $upper = $target;
        while ($this->errorFunctionValue($upper) < $target) {
            $upper *= 2.0;
            if ($upper > 32.0) {
                return null;
            }
        }

        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $midpoint = $lower + (($upper - $lower) / 2.0);
            if ($midpoint === $lower || $midpoint === $upper) {
                break;
            }
            if ($this->errorFunctionValue($midpoint) < $target) {
                $lower = $midpoint;
            } else {
                $upper = $midpoint;
            }
        }

        $lowerError = \abs($this->errorFunctionValue($lower) - $target);
        $upperError = \abs($this->errorFunctionValue($upper) - $target);
        $level = $lowerError <= $upperError ? $lower : $upper;

        return $value < 0.0 ? -$level : $level;
    }

    private function inverseComplementaryErrorFunctionLevel(float $value): ?float
    {
        if (!\is_finite($value) || $value <= 0.0 || $value >= 2.0) {
            return null;
        }
        if ($value === 1.0) {
            return 0.0;
        }
        if ($value > 1.0) {
            $positiveLevel = $this->inverseComplementaryErrorFunctionLevel(2.0 - $value);

            return $positiveLevel === null ? null : -$positiveLevel;
        }

        $lower = 0.0;
        $upper = 1.0;
        while (SpecialFunctions::erfc($upper) > $value && $upper < 32.0) {
            $upper *= 2.0;
        }
        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $midpoint = $lower + (($upper - $lower) / 2.0);
            if ($midpoint === $lower || $midpoint === $upper) {
                break;
            }
            if (SpecialFunctions::erfc($midpoint) > $value) {
                $lower = $midpoint;
            } else {
                $upper = $midpoint;
            }
        }

        return $lower + (($upper - $lower) / 2.0);
    }

    private function errorFunctionValue(float $value): float
    {
        return SpecialFunctions::erf($value);
    }

    private function hyperbolicSecantLevel(float $value): float
    {
        $decay = \exp(-$value);

        return (2.0 * $decay) / (1.0 + ($decay * $decay));
    }

    private function hyperbolicCosecantLevel(float $value): float
    {
        $absolute = \abs($value);
        if ($absolute < 1.0) {
            return 1.0 / \sinh($value);
        }

        $decay = \exp(-$absolute);
        $level = (2.0 * $decay) / (1.0 - ($decay * $decay));

        return $value < 0.0 ? -$level : $level;
    }

    private function hyperbolicCotangentLevel(float $value): float
    {
        $absolute = \abs($value);
        $correction = 2.0 / \expm1(2.0 * $absolute);
        $level = 1.0 + $correction;

        return $value < 0.0 ? -$level : $level;
    }

    /**
     * Reduce trigonometric compositions using a bounded inner-expression range.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveBoundedTrigonometricComposition(
        string $equation,
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $equalsPosition = \strpos($equation, '=');
        if ($equalsPosition === false) {
            return null;
        }

        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
            $outer = $left;
            $constant = $right;
            $sideSource = \substr($equation, 0, $equalsPosition);
            $sideSourceOffset = 0;
        } elseif (
            $right instanceof FunctionCallNode
            && !$this->containsVariable($left, $variable)
        ) {
            $outer = $right;
            $constant = $left;
            $sideSource = \substr($equation, $equalsPosition + 1);
            $sideSourceOffset = 0;
        } else {
            return null;
        }

        if (
            \count($outer->arguments) !== 1
            || !\in_array($outer->name, ['sin', 'cos', 'tan', 'sec', 'csc', 'cot'], true)
        ) {
            return null;
        }
        $inner = $this->unwrapGrouping($outer->arguments[0]);

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }
        $target = $targetCoefficients[0];
        if (!\is_finite($target)) {
            return null;
        }

        $innerRange = $this->boundedExpressionRange(
            $inner,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        if (
            $innerRange === null
            || !\is_finite($innerRange[0])
            || !\is_finite($innerRange[1])
        ) {
            return null;
        }

        $period = 2.0 * \M_PI;
        if ($outer->name === 'tan' || $outer->name === 'cot') {
            $period = \M_PI;
        }
        $baseLevels = match ($outer->name) {
            'sin' => \abs($target) > 1.0 ? [] : [\asin($target), \M_PI - \asin($target)],
            'cos' => \abs($target) > 1.0 ? [] : [\acos($target), -\acos($target)],
            'tan' => [\atan($target)],
            'sec' => \abs($target) < 1.0
                ? []
                : [\acos(1.0 / $target), -\acos(1.0 / $target)],
            'csc' => \abs($target) < 1.0
                ? []
                : [\asin(1.0 / $target), \M_PI - \asin(1.0 / $target)],
            'cot' => $target === 0.0 ? [\M_PI / 2.0] : [\atan(1.0 / $target)],
        };
        if ($baseLevels === []) {
            return [];
        }
        $levels = $this->periodicLevelsWithinRange($baseLevels, $period, $innerRange);
        if ($levels === null) {
            return null;
        }
        if ($levels === []) {
            return [];
        }

        $innerStart = $inner->span()->start;
        $innerExpression = \substr(
            $sideSource,
            $innerStart - $sideSourceOffset,
            $inner->span()->end - $inner->span()->start,
        );
        if (
            $innerExpression === ''
            || \strlen($innerExpression) + 24 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }

        $solutions = [];
        $seenSolutionPositions = [];
        foreach ($levels as $innerLevel) {
            foreach (
                $this->solve(
                    $innerExpression . '=' . \sprintf('%.17g', $innerLevel),
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $options,
                ) as $candidate
            ) {
                $positionKey = $this->samplePositionKey($candidate->value);
                if (isset($seenSolutionPositions[$positionKey])) {
                    continue;
                }
                $seenSolutionPositions[$positionKey] = true;

                $residual = $residualAt($candidate->value);
                if ($residual === null) {
                    return null;
                }
                $solutionValue = $candidate->value;
                $solutionResidual = $residual;
                if (
                    !$this->isResidualAcceptableAt(
                        $solutionValue,
                        $solutionResidual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    foreach ([-1, 1] as $direction) {
                        $position = $candidate->value;
                        for ($step = 0; $step < 16; ++$step) {
                            $neighbor = $this->adjacentFloat($position, $direction);
                            if (
                                $neighbor === null
                                || $neighbor < $lowerBound
                                || $neighbor > $upperBound
                            ) {
                                break;
                            }
                            $neighborResidual = $residualAt($neighbor);
                            if (
                                $neighborResidual === null
                                || \abs($neighborResidual) >= \abs($solutionResidual)
                            ) {
                                break;
                            }
                            $solutionValue = $neighbor;
                            $solutionResidual = $neighborResidual;
                            $position = $neighbor;
                        }
                    }
                    if (
                        !$this->isResidualAcceptableAt(
                            $solutionValue,
                            $solutionResidual,
                            $candidateScaleAt,
                            $options,
                        )
                        && !$this->isCandidateAtFloatingPointRootResolution(
                            $solutionValue,
                            $solutionResidual,
                            $residualAt,
                        )
                    ) {
                        return null;
                    }
                }
                $solutions[] = new EquationSolution(
                    $solutionValue,
                    \abs($solutionResidual),
                    $candidate->iterations,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $baseLevels
     * @param array{float, float} $range
     * @return list<float>|null
     */
    private function periodicLevelsWithinRange(array $baseLevels, float $period, array $range): ?array
    {
        $rangeScale = \max(1.0, \abs($range[0]), \abs($range[1]));
        $rangeTolerance = 256.0 * \PHP_FLOAT_EPSILON * $rangeScale;
        $lowerRange = $range[0] - $rangeTolerance;
        $upperRange = $range[1] + $rangeTolerance;
        if (!\is_finite($lowerRange) || !\is_finite($upperRange)) {
            return null;
        }

        $levels = [];
        foreach ($baseLevels as $baseLevel) {
            $firstIndex = \ceil(($lowerRange - $baseLevel) / $period);
            $lastIndex = \floor(($upperRange - $baseLevel) / $period);
            if (
                !\is_finite($firstIndex)
                || !\is_finite($lastIndex)
                || \abs($firstIndex) > 9_007_199_254_740_991.0
                || \abs($lastIndex) > 9_007_199_254_740_991.0
            ) {
                return null;
            }
            if ($lastIndex < $firstIndex) {
                continue;
            }
            if ($lastIndex - $firstIndex + 1.0 > self::MAX_PERIODIC_ROOTS) {
                return null;
            }
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $level = $baseLevel + ($index * $period);
                if (!\is_finite($level)) {
                    return null;
                }
                if (2.0 * \PHP_FLOAT_EPSILON * \abs($level) >= $period) {
                    throw new RootSearchLimitException(
                        'Adjacent periodic phase levels are not distinguishable at this magnitude.',
                    );
                }
                $levels[\sprintf('%.17g', $level)] = $level;
                if (\count($levels) > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
            }
        }

        return \array_values($levels);
    }

    /**
     * Enumerate periodic phase levels for a rational function argument.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalPeriodicFunction(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
            $function = $left;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $right;
            $constant = $left;
        } else {
            return null;
        }
        if (
            count($function->arguments) !== 1
            || !in_array(
                $function->name,
                ['sin', 'cos', 'tan', 'sec', 'csc', 'cot', 'sinc', 'sincpi'],
                true,
            )
        ) {
            return null;
        }

        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if (
            $targetCoefficients === null
            || count($targetCoefficients) !== 1
            || !is_finite($targetCoefficients[0])
        ) {
            return null;
        }
        $target = $targetCoefficients[0];
        $isSincFunction = in_array($function->name, ['sinc', 'sincpi'], true);
        $isSincZero = $isSincFunction && $target === 0.0;
        if ($isSincFunction && abs($target) > 1.0) {
            return [];
        }
        $sineLevel = null;
        $cosineLevel = null;
        $tangentLevel = null;
        if ($function->name === 'sin' || $function->name === 'csc') {
            if ($function->name === 'csc' && $target === 0.0) {
                return [];
            }
            $sineLevel = $function->name === 'sin' ? $target : 1.0 / $target;
        } elseif ($function->name === 'cos' || $function->name === 'sec') {
            if ($function->name === 'sec' && $target === 0.0) {
                return [];
            }
            $cosineLevel = $function->name === 'cos' ? $target : 1.0 / $target;
        } elseif ($function->name === 'tan') {
            $tangentLevel = $target;
        } elseif ($target !== 0.0) {
            $tangentLevel = 1.0 / $target;
        }

        $argument = $function->arguments[0];
        if ($this->extractPolynomial($extractor, $argument, $argument->span()->start) !== null) {
            return null;
        }
        $rational = $extractor->extractRationalForm($argument);
        if ($rational === null || \count($rational[1]) < 2) {
            return null;
        }
        [$numerator, $denominator] = $rational;
        $originalDenominator = $denominator;

        if ($isSincFunction && !$isSincZero) {
            $phaseBound = 1.0 / (\abs($target) * ($function->name === 'sincpi' ? \M_PI : 1.0));
            if (!\is_finite($phaseBound)) {
                return null;
            }

            return $this->solveRationalSincTarget(
                $function->name,
                $target,
                -$phaseBound,
                $phaseBound,
                $numerator,
                $denominator,
                $originalDenominator,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }

        $period = 2.0 * \M_PI;
        if ($isSincZero) {
            $period = $function->name === 'sinc' ? \M_PI : 1.0;
            $phases = [0.0];
        } elseif ($sineLevel !== null) {
            if (\abs($sineLevel) > 1.0) {
                return [];
            }
            $principal = \asin(\max(-1.0, \min(1.0, $sineLevel)));
            $phases = \abs($sineLevel) === 1.0
                ? [$principal]
                : [$principal, \M_PI - $principal];
        } elseif ($cosineLevel !== null) {
            if (\abs($cosineLevel) > 1.0) {
                return [];
            }
            $principal = \acos(\max(-1.0, \min(1.0, $cosineLevel)));
            $phases = \abs($cosineLevel) === 1.0
                ? [$principal]
                : [$principal, -$principal];
        } elseif ($tangentLevel !== null) {
            $period = \M_PI;
            $phases = [\atan($tangentLevel)];
        } else {
            $period = \M_PI;
            $phases = [\M_PI / 2.0];
        }

        $range = $this->rationalPolynomialRange(
            $numerator,
            $denominator,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($range === null) {
            return null;
        }
        [[$argumentLower, $argumentUpper], $numerator, $denominator] = $range;
        $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $levelCount = 0;
        $candidateCount = 0;

        foreach ($phases as $phase) {
            $firstPeriod = \ceil(($argumentLower - $phase - $angleTolerance) / $period);
            $lastPeriod = \floor(($argumentUpper - $phase + $angleTolerance) / $period);
            if ($lastPeriod < $firstPeriod) {
                continue;
            }
            if (
                $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                || \abs($firstPeriod) > 4_503_599_627_370_496.0
                || \abs($lastPeriod) > 4_503_599_627_370_496.0
            ) {
                return null;
            }

            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                if (++$levelCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $angle = $phase + ($periodIndex * $period);
                if ($isSincZero && $angle === 0.0) {
                    continue;
                }
                $levelCoefficients = $this->subtractScaledPolynomials(
                    $numerator,
                    $denominator,
                    $angle,
                );
                if ($levelCoefficients === null) {
                    return null;
                }
                if ($levelCoefficients === [0.0]) {
                    throw new InfiniteSolutionSetException(
                        'Periodic equation has infinitely many solutions in the requested interval.',
                    );
                }
                $levelSolutions = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $levelCoefficients,
                        $value,
                    ),
                    $options,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                        $levelCoefficients,
                        $value,
                    ),
                );
                if ($levelSolutions === null) {
                    return null;
                }

                foreach ($levelSolutions as $candidate) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        return null;
                    }
                    if (
                        $this->polynomialRootMultiplicity(
                            $originalDenominator,
                            $candidate->value,
                        ) > 0
                    ) {
                        continue;
                    }
                    $denominatorValue = $polynomialSolver->evaluatePolynomial(
                        $denominator,
                        $candidate->value,
                    );
                    if ($denominatorValue === null || $denominatorValue === 0.0) {
                        continue;
                    }
                    $residual = $residualAt($candidate->value);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate->value,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        continue;
                    }
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution(
                            $candidate->value,
                            \abs($residual),
                            $candidate->iterations,
                        ),
                    );
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Invert nonzero sinc targets on every monotone phase lobe, then solve
     * the resulting rational phase levels as polynomial equations.
     *
     * @param list<float> $numerator
     * @param list<float> $denominator
     * @param list<float> $originalDenominator
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveRationalSincTarget(
        string $function,
        float $target,
        float $phaseLower,
        float $phaseUpper,
        array $numerator,
        array $denominator,
        array $originalDenominator,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $phases = $this->sincTargetPhases(
            $function,
            $target,
            $phaseLower,
            $phaseUpper,
            $options,
        );
        if ($phases === null) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $candidateCount = 0;
        foreach ($phases as $phase) {
            $levelCoefficients = $this->subtractScaledPolynomials(
                $numerator,
                $denominator,
                $phase,
            );
            if ($levelCoefficients === null) {
                return null;
            }
            if ($levelCoefficients === [0.0]) {
                throw new InfiniteSolutionSetException(
                    'Sinc equation has infinitely many solutions in the requested interval.',
                );
            }
            $levelSolutions = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $levelCoefficients,
                    $value,
                ),
            );
            if ($levelSolutions === null) {
                return null;
            }

            foreach ($levelSolutions as $candidate) {
                if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                if (
                    $this->polynomialRootMultiplicity(
                        $originalDenominator,
                        $candidate->value,
                    ) > 0
                ) {
                    continue;
                }
                $denominatorValue = $polynomialSolver->evaluatePolynomial(
                    $denominator,
                    $candidate->value,
                );
                if ($denominatorValue === null || $denominatorValue === 0.0) {
                    continue;
                }
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Enumerate phase values where sinc or sincpi reaches a nonzero target.
     *
     * @return list<float>|null
     */
    private function sincTargetPhases(
        string $function,
        float $target,
        float $phaseLower,
        float $phaseUpper,
        SolverOptions $options,
    ): ?array {
        $phaseUnit = $function === 'sincpi' ? 1.0 : \M_PI;
        $maximumPhase = 1.0 / (\abs($target) * ($function === 'sincpi' ? \M_PI : 1.0));
        if (\is_finite($maximumPhase)) {
            $phaseLower = \max($phaseLower, -$maximumPhase);
            $phaseUpper = \min($phaseUpper, $maximumPhase);
            if ($phaseLower > $phaseUpper) {
                return [];
            }
        }
        if (
            \abs($phaseLower / $phaseUnit) > 4_503_599_627_370_496.0
            || \abs($phaseUpper / $phaseUnit) > 4_503_599_627_370_496.0
        ) {
            return null;
        }
        $firstLobe = (int) \floor($phaseLower / $phaseUnit);
        $lastExtremumLobe = (int) \ceil($phaseUpper / $phaseUnit) - 1;
        if ($lastExtremumLobe - $firstLobe + 1 > self::MAX_PERIODIC_ROOTS) {
            return null;
        }

        $extrema = [];
        if ($phaseLower < 0.0 && $phaseUpper > 0.0) {
            $extrema[] = 0.0;
        }
        $derivativeScale = $function === 'sincpi' ? \M_PI : 1.0;
        for ($lobe = $firstLobe; $lobe <= $lastExtremumLobe; ++$lobe) {
            if ($lobe === 0) {
                continue;
            }
            $lobeIndex = \abs($lobe);
            $leftPhase = $lobeIndex * $phaseUnit;
            $rightPhase = ($lobeIndex + 1) * $phaseUnit;
            $leftDerivative = $this->sincPhaseDerivativeNumerator(
                $leftPhase * $derivativeScale,
            );
            $rightDerivative = $this->sincPhaseDerivativeNumerator(
                $rightPhase * $derivativeScale,
            );
            if (!$this->hasOppositeSigns($leftDerivative, $rightDerivative)) {
                continue;
            }
            $extremum = $this->bisectSincExtremum(
                $leftPhase,
                $rightPhase,
                $derivativeScale,
                $options,
            );
            if ($lobe < 0) {
                $extremum = -$extremum;
            }
            if ($extremum > $phaseLower && $extremum < $phaseUpper) {
                $extrema[] = $extremum;
            }
        }

        $points = [$phaseLower, ...$extrema, $phaseUpper];
        \sort($points, SORT_NUMERIC);
        $phaseRoots = [];
        foreach ($extrema as $extremum) {
            $residual = $this->sincPhaseResidual($function, $extremum, $target);
            if ($residual !== null && \abs($residual) <= $options->residualTolerance) {
                $phaseRoots[] = $extremum;
            }
        }
        for ($branch = 1, $pointCount = \count($points); $branch < $pointCount; ++$branch) {
            $left = $points[$branch - 1];
            $right = $points[$branch];
            $leftResidual = $this->sincPhaseResidual($function, $left, $target);
            $rightResidual = $this->sincPhaseResidual($function, $right, $target);
            if ($leftResidual === null || $rightResidual === null) {
                return null;
            }
            if (
                $leftResidual === 0.0
                || $rightResidual === 0.0
                || $this->hasOppositeSigns($leftResidual, $rightResidual)
            ) {
                $phase = $leftResidual === 0.0
                    ? $left
                    : ($rightResidual === 0.0
                        ? $right
                        : $this->bisectSincPhase(
                            $function,
                            $target,
                            $left,
                            $leftResidual,
                            $right,
                            $options,
                        ));
                if ($phase === null) {
                    return null;
                }
                $phaseRoots[] = $phase;
            }
        }

        \sort($phaseRoots, SORT_NUMERIC);
        $distinctPhases = [];
        $phaseTolerance = $options->positionTolerance($phaseLower, $phaseUpper);
        foreach ($phaseRoots as $phaseRoot) {
            $lastIndex = \array_key_last($distinctPhases);
            if (
                $lastIndex !== null
                && \abs($phaseRoot - $distinctPhases[$lastIndex]) <= $phaseTolerance
            ) {
                continue;
            }
            $distinctPhases[] = $phaseRoot;
        }

        return $distinctPhases;
    }

    /**
     * Compute the range of a rational polynomial with no denominator roots
     * inside the interval.
     *
     * @param list<float> $numerator
     * @param list<float> $denominator
     * @return array{array{float, float}, list<float>, list<float>}|null
     */
    private function rationalPolynomialRange(
        array $numerator,
        array $denominator,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        if ($numerator === [0.0]) {
            return [[0.0, 0.0], $numerator, $denominator];
        }
        $polynomialSolver = new PolynomialSolver();
        if (\count($denominator) > 1) {
            $denominatorRoots = $polynomialSolver->solve(
                $denominator,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $denominator,
                    $value,
                ),
                $options,
            );
            if ($denominatorRoots === null) {
                return null;
            }
            foreach ($denominatorRoots as $root) {
                $denominatorMultiplicity = $this->polynomialRootMultiplicity(
                    $denominator,
                    $root->value,
                );
                $numeratorMultiplicity = $this->polynomialRootMultiplicity(
                    $numerator,
                    $root->value,
                );
                if (
                    $denominatorMultiplicity === 0
                    || $denominatorMultiplicity > $numeratorMultiplicity
                ) {
                    return null;
                }
                for ($multiplicity = 0; $multiplicity < $denominatorMultiplicity; ++$multiplicity) {
                    $reducedNumerator = $this->dividePolynomialByLinearFactor(
                        $numerator,
                        $root->value,
                    );
                    $reducedDenominator = $this->dividePolynomialByLinearFactor(
                        $denominator,
                        $root->value,
                    );
                    if ($reducedNumerator === null || $reducedDenominator === null) {
                        return null;
                    }
                    $numerator = $reducedNumerator;
                    $denominator = $reducedDenominator;
                }
            }
        }

        $numeratorDerivative = $this->polynomialDerivative($numerator);
        $denominatorDerivative = $this->polynomialDerivative($denominator);
        $firstProduct = $this->multiplyPolynomials($numeratorDerivative, $denominator);
        $secondProduct = $this->multiplyPolynomials($numerator, $denominatorDerivative);
        foreach ([...$firstProduct, ...$secondProduct] as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }
        $criticalPolynomial = $this->subtractScaledPolynomials(
            $firstProduct,
            $secondProduct,
            1.0,
        );
        if ($criticalPolynomial === null) {
            return null;
        }
        if ($criticalPolynomial === [0.0]) {
            $constantValue = $this->proportionalPolynomialRatio($numerator, $denominator);

            return $constantValue === null
                ? null
                : [[$constantValue, $constantValue], $numerator, $denominator];
        }

        $positions = [$lowerBound, $upperBound];
        if (\count($criticalPolynomial) > 1) {
            $criticalPoints = $polynomialSolver->solve(
                $criticalPolynomial,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $criticalPolynomial,
                    $value,
                ),
                $options,
            );
            if ($criticalPoints === null) {
                return null;
            }
            foreach ($criticalPoints as $criticalPoint) {
                $positions[] = $criticalPoint->value;
            }
        }

        $values = [];
        foreach ($positions as $position) {
            if (\is_infinite($position)) {
                while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === 0.0) {
                    \array_pop($numerator);
                }
                while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)] === 0.0) {
                    \array_pop($denominator);
                }
                $numeratorDegree = \count($numerator) - 1;
                $denominatorDegree = \count($denominator) - 1;
                if ($numeratorDegree > $denominatorDegree) {
                    return null;
                }
                $value = $numeratorDegree < $denominatorDegree
                    ? 0.0
                    : $numerator[$numeratorDegree] / $denominator[$denominatorDegree];
                if (!\is_finite($value)) {
                    return null;
                }
                $values[] = $value;

                continue;
            }
            $numeratorValue = $polynomialSolver->evaluatePolynomial($numerator, $position);
            $denominatorValue = $polynomialSolver->evaluatePolynomial($denominator, $position);
            if (
                $numeratorValue === null
                || $denominatorValue === null
                || $denominatorValue === 0.0
            ) {
                return null;
            }
            $value = $numeratorValue / $denominatorValue;
            if (!\is_finite($value)) {
                return null;
            }
            $values[] = $value;
        }

        return [[\min(...$values), \max(...$values)], $numerator, $denominator];
    }

    /**
     * @param list<float> $numerator
     * @param list<float> $denominator
     */
    private function proportionalPolynomialRatio(array $numerator, array $denominator): ?float
    {
        $length = \max(\count($numerator), \count($denominator));
        $pivot = null;
        for ($power = $length - 1; $power >= 0; --$power) {
            $denominatorCoefficient = $denominator[$power] ?? 0.0;
            $numeratorCoefficient = $numerator[$power] ?? 0.0;
            if ($denominatorCoefficient === 0.0) {
                if ($numeratorCoefficient !== 0.0) {
                    return null;
                }
                continue;
            }
            $pivot = $numeratorCoefficient / $denominatorCoefficient;
            break;
        }
        if ($pivot === null || !\is_finite($pivot)) {
            return null;
        }
        for ($power = 0; $power < $length; ++$power) {
            if (($numerator[$power] ?? 0.0) !== $pivot * ($denominator[$power] ?? 0.0)) {
                return null;
            }
        }

        return $pivot;
    }

    /** @param list<float> $polynomial
     * @return list<float>|null
     */
    private function dividePolynomialByLinearFactor(array $polynomial, float $root): ?array
    {
        $degree = \count($polynomial) - 1;
        if ($degree < 1) {
            return null;
        }
        $quotient = \array_fill(0, $degree, 0.0);
        $quotient[$degree - 1] = $polynomial[$degree];
        for ($power = $degree - 1; $power > 0; --$power) {
            $quotient[$power - 1] = $polynomial[$power] + ($root * $quotient[$power]);
        }
        $remainder = $polynomial[0] + ($root * $quotient[0]);
        $scale = 0.0;
        $rootPower = 1.0;
        foreach ($polynomial as $coefficient) {
            $scale += \abs($coefficient * $rootPower);
            $rootPower *= \abs($root);
        }
        if (
            !\is_finite($remainder)
            || !\is_finite($scale)
            || \abs($remainder) > 128.0 * \PHP_FLOAT_EPSILON * \max($scale, \PHP_FLOAT_MIN)
        ) {
            return null;
        }
        while (\count($quotient) > 1 && $quotient[\array_key_last($quotient)] === 0.0) {
            \array_pop($quotient);
        }

        return \array_values($quotient);
    }

    /** @param list<float> $polynomial
     * @return list<float>
     */
    private function polynomialDerivative(array $polynomial): array
    {
        if (\count($polynomial) < 2) {
            return [0.0];
        }

        $derivative = [];
        for ($power = 1; $power < \count($polynomial); ++$power) {
            $derivative[] = $power * $polynomial[$power];
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === 0.0) {
            \array_pop($derivative);
        }

        return $derivative;
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>|null
     */
    private function subtractScaledPolynomials(array $left, array $right, float $scale): ?array
    {
        $length = \max(\count($left), \count($right));
        $difference = [];
        for ($power = 0; $power < $length; ++$power) {
            $coefficient = ($left[$power] ?? 0.0) - ($scale * ($right[$power] ?? 0.0));
            if (!\is_finite($coefficient)) {
                return null;
            }
            $difference[] = $coefficient;
        }
        while (\count($difference) > 1 && $difference[\array_key_last($difference)] === 0.0) {
            \array_pop($difference);
        }

        return $difference;
    }

    /**
     * Solve periodic trigonometric equations with polynomial, exponential,
     * logarithmic, or square-root-composed arguments.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>|null
     */
    private function solveAffinePeriodicFunction(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $sincZeroSolutions = $this->solveAffineSincZeroEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($sincZeroSolutions !== null) {
            return $sincZeroSolutions;
        }

        $quotientParts = $this->sincQuotientEquationParts(
            $left,
            $right,
            $variable,
            $extractor,
        );
        if ($quotientParts !== null) {
            [$quotientFunction, $constant] = $quotientParts;
            if (
                $this->extractPolynomial(
                    $extractor,
                    $quotientFunction->arguments[0],
                    $quotientFunction->arguments[0]->span()->start,
                ) === null
            ) {
                $this->throwIfPeriodicRationalArgumentHasPole(
                    $quotientFunction,
                    $constant,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                    $evaluationOptions,
                    $parameters,
                );
                $rationalQuotientSolutions = $this->solveRationalPeriodicFunction(
                    $quotientFunction,
                    $constant,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                    $residualAt,
                    $candidateScaleAt,
                );
                if ($rationalQuotientSolutions !== null) {
                    return $rationalQuotientSolutions;
                }
            }
        }

        $trigonometricPolynomialSolutions = $this->solveAffineTrigonometricPolynomialEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($trigonometricPolynomialSolutions !== null) {
            return $trigonometricPolynomialSolutions;
        }

        $harmonicPairSolutions = $this->solveAffineHarmonicPairEquation(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($harmonicPairSolutions !== null) {
            return $harmonicPairSolutions;
        }

        $sumToProductSolutions = $this->solveAffineTrigonometricSumToProduct(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($sumToProductSolutions !== null) {
            return $sumToProductSolutions;
        }

        $sineCosineSolutions = $this->solveAffineSineCosineCombination(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($sineCosineSolutions !== null) {
            return $sineCosineSolutions;
        }

        $rationalPeriodicSolutions = $this->solveRationalPeriodicFunction(
            $left,
            $right,
            $variable,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $residualAt,
            $candidateScaleAt,
        );
        if ($rationalPeriodicSolutions !== null) {
            return $rationalPeriodicSolutions;
        }

        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
            $function = $left;
            $constant = $right;
            $functionSource = $leftSource;
            $functionSourceOffset = 0;
        } elseif (
            $right instanceof FunctionCallNode
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $right;
            $constant = $left;
            $functionSource = $rightSource;
            $functionSourceOffset = $rightSourceOffset;
        } else {
            return null;
        }

        if (
            \count($function->arguments) !== 1
            || !\in_array($function->name, ['sin', 'cos', 'tan', 'sec', 'csc', 'cot'], true)
        ) {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        $argument = $function->arguments[0];
        $argumentCoefficients = $this->extractPolynomial(
            $extractor,
            $argument,
            $argument->span()->start,
        );
        $squareRootArgumentCoefficients = null;
        $exponentialArgumentCoefficients = null;
        $exponentialSquareRootCoefficients = null;
        $nestedExponentialArgumentCoefficients = null;
        $nestedExponentialSquareRootCoefficients = null;
        $nestedExponentialDepth = 0;
        $logarithmicArgumentCoefficients = null;
        $logarithmBase = null;
        if ($argumentCoefficients === null) {
            $argument = $this->unwrapGrouping($argument);
            if (!$argument instanceof FunctionCallNode) {
                return null;
            }
            if ($argument->name === 'sqrt' && \count($argument->arguments) === 1) {
                $squareRootArgumentCoefficients = $this->extractPolynomial(
                    $extractor,
                    $argument->arguments[0],
                    $argument->arguments[0]->span()->start,
                );
                if (
                    $squareRootArgumentCoefficients === null
                    || \count($squareRootArgumentCoefficients) < 2
                ) {
                    return null;
                }
            } elseif ($argument->name === 'exp' && \count($argument->arguments) === 1) {
                $exponentialArgumentCoefficients = $this->extractPolynomial(
                    $extractor,
                    $argument->arguments[0],
                    $argument->arguments[0]->span()->start,
                );
                if ($exponentialArgumentCoefficients === null) {
                    $exponentialArgument = $this->unwrapGrouping($argument->arguments[0]);
                    if (
                        !$exponentialArgument instanceof FunctionCallNode
                        || \count($exponentialArgument->arguments) !== 1
                    ) {
                        return null;
                    }
                    if ($exponentialArgument->name === 'sqrt') {
                        $nestedArgumentCoefficients = $this->extractPolynomial(
                            $extractor,
                            $exponentialArgument->arguments[0],
                            $exponentialArgument->arguments[0]->span()->start,
                        );
                        $exponentialSquareRootCoefficients = $nestedArgumentCoefficients;
                        if (
                            $exponentialSquareRootCoefficients === null
                            || \count($exponentialSquareRootCoefficients) < 2
                        ) {
                            return null;
                        }
                    } elseif ($exponentialArgument->name === 'exp') {
                        $nestedExponentialDepth = 2;
                        $nestedExponential = $exponentialArgument;
                        while (true) {
                            $nestedExponentialArgumentCoefficients = $this->extractPolynomial(
                                $extractor,
                                $nestedExponential->arguments[0],
                                $nestedExponential->arguments[0]->span()->start,
                            );
                            if ($nestedExponentialArgumentCoefficients !== null) {
                                if (\count($nestedExponentialArgumentCoefficients) < 2) {
                                    return null;
                                }
                                break;
                            }

                            $nextExponential = $this->unwrapGrouping(
                                $nestedExponential->arguments[0],
                            );
                            if (
                                $nextExponential instanceof FunctionCallNode
                                && $nextExponential->name === 'sqrt'
                                && \count($nextExponential->arguments) === 1
                            ) {
                                $nestedExponentialSquareRootCoefficients =
                                    $this->extractPolynomial(
                                        $extractor,
                                        $nextExponential->arguments[0],
                                        $nextExponential->arguments[0]->span()->start,
                                    );
                                if (
                                    $nestedExponentialSquareRootCoefficients === null
                                    || \count($nestedExponentialSquareRootCoefficients) < 2
                                ) {
                                    return null;
                                }
                                break;
                            }
                            if (
                                !$nextExponential instanceof FunctionCallNode
                                || $nextExponential->name !== 'exp'
                                || \count($nextExponential->arguments) !== 1
                            ) {
                                return null;
                            }
                            $nestedExponential = $nextExponential;
                            ++$nestedExponentialDepth;
                        }
                    } else {
                        return null;
                    }
                } elseif (
                    \count($exponentialArgumentCoefficients) < 2
                    || (\count($exponentialArgumentCoefficients) === 2
                        && $exponentialArgumentCoefficients[1] === 0.0)
                ) {
                    return null;
                }
            } elseif (
                \in_array($argument->name, ['ln', 'log10', 'log2'], true)
                && \count($argument->arguments) === 1
            ) {
                $logarithmBase = match ($argument->name) {
                    'ln' => \M_E,
                    'log10' => 10.0,
                    'log2' => 2.0,
                };
                $logarithmicArgumentCoefficients = $this->extractPolynomial(
                    $extractor,
                    $argument->arguments[0],
