    }

    /** @param array<string, int|float> $parameters */
    private function throwIfPeriodicRationalArgumentHasPole(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): void {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $this->throwIfPeriodicTermWithFiniteOffsetAccumulates(
            $left,
            $right,
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
            $evaluationOptions,
            $parameters,
            $variable,
        );
        if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
            $function = $left;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $right;
            $constant = $left;
        } else {
            return;
        }
        if (
            \count($function->arguments) !== 1
            || !\in_array($function->name, ['sin', 'cos', 'tan', 'sinc', 'sincpi'], true)
        ) {
            return;
        }

        $target = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($target === null || \count($target) !== 1 || !\is_finite($target[0])) {
            return;
        }
        $isSincZero = \in_array($function->name, ['sinc', 'sincpi'], true)
            && $target[0] === 0.0;
        if (
            (\in_array($function->name, ['sinc', 'sincpi'], true) && !$isSincZero)
            || (!$isSincZero && $function->name !== 'tan' && \abs($target[0]) > 1.0)
        ) {
            return;
        }

        $phaseForm = $extractor->extractRationalForm($function->arguments[0]);
        if ($phaseForm !== null && \count($phaseForm[1]) > 1) {
            $polynomialSolver = new PolynomialSolver();
            $denominatorRoots = $polynomialSolver->solve(
                $phaseForm[1],
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $phaseForm[1],
                    $value,
                ),
                $options,
            );
            if ($denominatorRoots !== null) {
                foreach ($denominatorRoots as $pole) {
                    if (
                        $this->polynomialRootMultiplicity($phaseForm[1], $pole->value)
                        > $this->polynomialRootMultiplicity($phaseForm[0], $pole->value)
                    ) {
                        throw new InfiniteRootAccumulationException(
                            'A periodic equation with a rational phase has infinitely many roots '
                                . 'accumulating at an interior pole.',
                        );
                    }
                }
            }
        }

        $phaseLevels = $this->periodicPhaseLevelsForTarget($function->name, $target[0]);
        foreach ($phaseLevels as $phaseLevel) {
            $phase = $function->arguments[0];
            $level = new NumberNode($phaseLevel, \sprintf('%.17g', $phaseLevel), $phase->span());
            $this->throwIfPeriodicTermWithFiniteOffsetAccumulates(
                $phase,
                $level,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
                $evaluationOptions,
                $parameters,
                $variable,
            );
        }

        foreach ([[1, $lowerBound], [-1, $upperBound]] as [$direction, $boundary]) {
            $offsetAndAmplitude = $this->periodicPhaseOffsetAndAmplitudeAtBoundary(
                $function->arguments[0],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($offsetAndAmplitude !== null) {
                [$offset, $amplitude] = $offsetAndAmplitude;
                foreach (
                    $this->periodicPhaseLevelsNearOffset(
                        $function->name,
                        $target[0],
                        $offset,
                        $amplitude,
                    ) as $phaseLevel
                ) {
                    $periodicTerm = $offsetAndAmplitude[2];
                    $termLevel = $phaseLevel - $offset;
                    $level = new NumberNode(
                        $termLevel,
                        \sprintf('%.17g', $termLevel),
                        $periodicTerm->span(),
                    );
                    $this->throwIfPeriodicTermWithFiniteOffsetAccumulates(
                        $periodicTerm,
                        $level,
                        $extractor,
                        $lowerBound,
                        $upperBound,
                        $options,
                        $evaluationOptions,
                        $parameters,
                        $variable,
                    );
                }
            }

            $harmonicRange = $this->periodicHarmonicRangeAtBoundary(
                $function->arguments[0],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($harmonicRange !== null) {
                [$offset, $amplitude] = $harmonicRange;
                $principalLevels = $this->periodicPhaseLevelsForTarget($function->name, $target[0]);
                $period = $function->name === 'tan' ? \M_PI : 2.0 * \M_PI;
                foreach (
                    $principalLevels as $principalLevel
                ) {
                    $periodPosition = ($offset - $principalLevel) / $period;
                    foreach (
                        [(int) \floor($periodPosition), (int) \ceil($periodPosition)] as $periodIndex
                    ) {
                        $phaseLevel = $principalLevel + ($periodIndex * $period);
                        $phaseLevelTolerance = 64.0 * \PHP_FLOAT_EPSILON
                            * \max(1.0, \abs($phaseLevel), \abs($offset), $amplitude);
                        if (
                            \abs($phaseLevel - $offset) < $amplitude - $phaseLevelTolerance
                        ) {
                            throw new InfiniteRootAccumulationException(
                                'A nested harmonic phase has infinitely many roots accumulating at '
                                    . 'an interval boundary.',
                            );
                        }
                    }
                }
            }
        }

        $periodicArgument = $this->unwrapGrouping($function->arguments[0]);
        foreach ([[1, $lowerBound], [-1, $upperBound]] as [$direction, $boundary]) {
            if (
                $this->periodicHarmonicRangeAtBoundary(
                    $function->arguments[0],
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                ) !== null
            ) {
                continue;
            }
            $phaseDivergence = $this->periodicPhaseDivergesAtBoundary(
                $function->arguments[0],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($phaseDivergence !== null) {
                throw new InfiniteRootAccumulationException(
                    'A periodic equation with an unbounded phase has infinitely many roots '
                        . 'accumulating at an interval boundary.',
                );
            }
        }
        $phaseSingularities = $this->rationalSubexpressionRoots(
            $function->arguments[0],
            $extractor,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($phaseSingularities !== null) {
            foreach ($phaseSingularities as $singularity) {
                if (
                    $singularity->value <= $lowerBound
                    || $singularity->value >= $upperBound
                ) {
                    continue;
                }
                foreach ([-1, 1] as $direction) {
                    $phaseDivergence = $this->periodicPhaseDivergesAtBoundary(
                        $function->arguments[0],
                        $variable,
                        $singularity->value,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    );
                    if ($phaseDivergence !== null) {
                        throw new InfiniteRootAccumulationException(
                            'A periodic equation with an unbounded phase has infinitely many roots '
                                . 'accumulating at an interior singularity.',
                        );
                    }
                }
            }
        }
        if ($periodicArgument instanceof FunctionCallNode && \count($periodicArgument->arguments) === 1) {
            $poleOffset = match ($periodicArgument->name) {
                'tan', 'sec' => \M_PI / 2.0,
                'cot', 'csc' => 0.0,
                default => null,
            };
            $trigonometricPhase = $this->extractPolynomial(
                $extractor,
                $periodicArgument->arguments[0],
                $periodicArgument->arguments[0]->span()->start,
            );
            if ($poleOffset !== null && $trigonometricPhase !== null) {
                $phaseRange = $this->polynomialRange(
                    $trigonometricPhase,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($phaseRange !== null) {
                    $firstPole = \ceil(($phaseRange[0] - $poleOffset) / \M_PI);
                    $lastPole = \floor(($phaseRange[1] - $poleOffset) / \M_PI);
                    if ($firstPole <= $lastPole) {
                        throw new InfiniteRootAccumulationException(
                            'A periodic equation with a trigonometric pole in its argument has '
                                . 'infinitely many roots accumulating at that pole.',
                        );
                    }
                }
            }
        }
        $poleArgumentIndex = $periodicArgument instanceof FunctionCallNode
            ? match ($periodicArgument->name) {
                'gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma' => 0,
                'polygamma' => 1,
                default => null,
            }
            : null;
        if (
            $periodicArgument instanceof FunctionCallNode
            && $poleArgumentIndex !== null
            && isset($periodicArgument->arguments[$poleArgumentIndex])
            && $this->containsVariable(
                $periodicArgument->arguments[$poleArgumentIndex],
                $variable,
            )
        ) {
            $poleArgument = $periodicArgument->arguments[$poleArgumentIndex];
            $poleArgumentCoefficients = $this->extractPolynomial(
                $extractor,
                $poleArgument,
                $poleArgument->span()->start,
            );
            if ($poleArgumentCoefficients !== null) {
                $argumentRange = $this->polynomialRange(
                    $poleArgumentCoefficients,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($argumentRange !== null) {
                    $firstPole = \ceil($argumentRange[0]);
                    $lastPole = \min(0.0, \floor($argumentRange[1]));
                    if ($periodicArgument->name === 'gamma' || $periodicArgument->name === 'lgamma') {
                        $firstPole = \max(-171.0, $firstPole);
                    }
                    if ($firstPole <= $lastPole) {
                        throw new InfiniteRootAccumulationException(
                            'A periodic equation with a Gamma-family argument has infinitely many '
                                . 'roots accumulating at a pole in the solving interval.',
                        );
                    }
                }
            }
        }
        if ($periodicArgument instanceof FunctionCallNode) {
            $this->throwIfPeriodicLogarithmArgumentHasPole(
                $periodicArgument,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
        }

        $argument = $extractor->extractRationalForm($function->arguments[0]);
        if ($argument === null || \count($argument[1]) < 2) {
            return;
        }

        $polynomialSolver = new PolynomialSolver();
        $poles = $polynomialSolver->solve(
            $argument[1],
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $argument[1],
                $value,
            ),
            $options,
        );
        if ($poles === null) {
            return;
        }

        foreach ($poles as $pole) {
            $numeratorMultiplicity = $this->polynomialRootMultiplicity(
                $argument[0],
                $pole->value,
            );
            $denominatorMultiplicity = $this->polynomialRootMultiplicity(
                $argument[1],
                $pole->value,
            );
            if ($denominatorMultiplicity > $numeratorMultiplicity) {
                throw new InfiniteRootAccumulationException(
                    'A periodic equation with a rational argument has infinitely many roots '
                        . 'accumulating at a pole in the solving interval.',
                );
            }
        }
    }

    /** @return list<float> */
    private function periodicPhaseLevelsForTarget(string $function, float $target): array
    {
        if ($function === 'sin') {
            $principal = \asin($target);
            $bases = [$principal, \M_PI - $principal];
            $period = 2.0 * \M_PI;
        } elseif ($function === 'cos') {
            $principal = \acos($target);
            $bases = [$principal, -$principal];
            $period = 2.0 * \M_PI;
        } elseif ($function === 'tan') {
            $bases = [\atan($target)];
            $period = \M_PI;
        } else {
            return [];
        }

        $levels = [];
        for ($periodIndex = -2; $periodIndex <= 2; ++$periodIndex) {
            foreach ($bases as $base) {
                $level = $base + ($periodIndex * $period);
                if (!\in_array($level, $levels, true)) {
                    $levels[] = $level;
                }
            }
        }

        return $levels;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float, Node}|null
     */
    private function periodicPhaseOffsetAndAmplitudeAtBoundary(
        Node $node,
        string $variable,
        float $boundary,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        $parts = $this->periodicTermParts($node, $extractor);
        if ($parts !== null) {
            $amplitude = $this->rationalFormLimitAt($parts[1], $boundary);
            if ($amplitude === null || !\is_finite($amplitude)) {
                return null;
            }
            foreach ($parts[2] as $smoothScale) {
                $scaleLimit = $this->continuousExpressionLimitAt(
                    $smoothScale,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($scaleLimit === null || !\is_finite($scaleLimit)) {
                    return null;
                }
                $amplitude *= $scaleLimit;
            }

            return [0.0, \abs($amplitude), $node];
        }
        if ($node instanceof UnaryOperationNode) {
            $parts = $this->periodicPhaseOffsetAndAmplitudeAtBoundary(
                $node->operand,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );

            return $parts === null || $node->operator === UnaryOperator::Plus
                ? $parts
                : [-$parts[0], $parts[1], new UnaryOperationNode(UnaryOperator::Minus, $parts[2], $node->operatorSpan)];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $leftParts = $this->periodicPhaseOffsetAndAmplitudeAtBoundary(
            $node->left,
            $variable,
            $boundary,
            $direction,
            $extractor,
            $evaluationOptions,
            $parameters,
        );
        $rightParts = $this->periodicPhaseOffsetAndAmplitudeAtBoundary(
            $node->right,
            $variable,
            $boundary,
            $direction,
            $extractor,
            $evaluationOptions,
            $parameters,
        );
        if (($leftParts === null) === ($rightParts === null)) {
            return null;
        }
        $periodicParts = $leftParts ?? $rightParts;
        $otherNode = $leftParts === null ? $node->left : $node->right;
        $otherLimit = $this->continuousExpressionLimitAt(
            $otherNode,
            $variable,
            $boundary,
            $direction,
            $extractor,
            $evaluationOptions,
            $parameters,
        );
        if ($otherLimit === null || !\is_finite($otherLimit) || $periodicParts === null) {
            return null;
        }

        if ($node->operator === BinaryOperator::Add) {
            return [$periodicParts[0] + $otherLimit, $periodicParts[1], $periodicParts[2]];
        }
        if ($node->operator === BinaryOperator::Subtract) {
            return $leftParts !== null
                ? [$periodicParts[0] - $otherLimit, $periodicParts[1], $periodicParts[2]]
                : [
                    $otherLimit - $periodicParts[0],
                    $periodicParts[1],
                    new UnaryOperationNode(UnaryOperator::Minus, $periodicParts[2], $node->operatorSpan),
                ];
        }
        if ($node->operator === BinaryOperator::Multiply) {
            return [
                $periodicParts[0] * $otherLimit,
                $periodicParts[1] * \abs($otherLimit),
                new BinaryOperationNode(
                    BinaryOperator::Multiply,
                    $periodicParts[2],
                    $otherNode,
                    $node->operatorSpan,
                ),
            ];
        }
        if ($node->operator === BinaryOperator::Divide && $leftParts !== null && $otherLimit !== 0.0) {
            return [
                $periodicParts[0] / $otherLimit,
                $periodicParts[1] / \abs($otherLimit),
                new BinaryOperationNode(
                    BinaryOperator::Divide,
                    $periodicParts[2],
                    $otherNode,
                    $node->operatorSpan,
                ),
            ];
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{float, float}|null
     */
    private function periodicHarmonicRangeAtBoundary(
        Node $node,
        string $variable,
        float $boundary,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): ?array {
        $terms = [];
        $flatten = function (Node $current, float $sign = 1.0) use (&$flatten, &$terms): void {
            $current = $this->unwrapGrouping($current);
            if ($current instanceof UnaryOperationNode) {
                $flatten(
                    $current->operand,
                    $current->operator === UnaryOperator::Minus ? -$sign : $sign,
                );
                return;
            }
            if (
                $current instanceof BinaryOperationNode
                && \in_array($current->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
            ) {
                $flatten($current->left, $sign);
                $flatten(
                    $current->right,
                    $current->operator === BinaryOperator::Subtract ? -$sign : $sign,
                );
                return;
            }
            $terms[] = [$current, $sign];
        };
        $flatten($node);

        $offset = 0.0;
        $sineCoefficient = 0.0;
        $cosineCoefficient = 0.0;
        $phaseForm = null;
        $hasSine = false;
        $hasCosine = false;
        foreach ($terms as [$term, $sign]) {
            $parts = $this->periodicTermParts($term, $extractor);
            if ($parts === null) {
                $limit = $this->continuousExpressionLimitAt(
                    $term,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($limit === null || !\is_finite($limit)) {
                    return null;
                }
                $offset += $sign * $limit;
                continue;
            }

            [$function, $amplitudeForm, $smoothScales] = $parts;
            if (!\in_array($function->name, ['sin', 'cos'], true)) {
                return null;
            }
            $currentPhaseForm = $extractor->extractRationalForm($function->arguments[0]);
            if ($currentPhaseForm === null || ($phaseForm !== null && $currentPhaseForm !== $phaseForm)) {
                return null;
            }
            $phaseForm = $currentPhaseForm;
            $numeratorMultiplicity = $this->polynomialRootMultiplicity($phaseForm[0], $boundary);
            $denominatorMultiplicity = $this->polynomialRootMultiplicity($phaseForm[1], $boundary);
            if ($denominatorMultiplicity <= $numeratorMultiplicity) {
                return null;
            }
            $coefficient = $this->rationalFormLimitAt($amplitudeForm, $boundary);
            if ($coefficient === null || !\is_finite($coefficient)) {
                return null;
            }
            foreach ($smoothScales as $scale) {
                $scaleLimit = $this->continuousExpressionLimitAt(
                    $scale,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($scaleLimit === null || !\is_finite($scaleLimit)) {
                    return null;
                }
                $coefficient *= $scaleLimit;
            }
            if ($function->name === 'sin') {
                $sineCoefficient += $sign * $coefficient;
                $hasSine = true;
            } else {
                $cosineCoefficient += $sign * $coefficient;
                $hasCosine = true;
            }
        }

        if (!$hasSine || !$hasCosine || !\is_finite($offset)) {
            return null;
        }
        $amplitude = \hypot($sineCoefficient, $cosineCoefficient);
        if ($amplitude === 0.0 || !\is_finite($amplitude)) {
            return null;
        }

        return [$offset, $amplitude];
    }

    /** @return list<float> */
    private function periodicPhaseLevelsNearOffset(
        string $function,
        float $target,
        float $offset,
        float $amplitude,
    ): array {
        if ($function === 'sin') {
            $principal = \asin($target);
            $bases = [$principal, \M_PI - $principal];
            $period = 2.0 * \M_PI;
        } elseif ($function === 'cos') {
            $principal = \acos($target);
            $bases = [$principal, -$principal];
            $period = 2.0 * \M_PI;
        } elseif ($function === 'tan') {
            $bases = [\atan($target)];
            $period = \M_PI;
        } else {
            return [];
        }

        $tolerance = 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($offset));
        $levels = [];
        foreach ($bases as $base) {
            $periodPosition = ($offset - $base) / $period;
            foreach ([(int) \floor($periodPosition), (int) \ceil($periodPosition)] as $periodIndex) {
                $level = $base + ($periodIndex * $period);
                if (
                    \abs($level - $offset) <= $amplitude + $tolerance
                    && !\in_array($level, $levels, true)
                ) {
                    $levels[] = $level;
                }
            }
        }

        return $levels;
    }

    /** @param array<string, int|float> $parameters */
    private function hasReciprocalAlgebraicLogBoundaryPole(
        Node $phase,
        string $variable,
        float $lowerBound,
        float $upperBound,
        PolynomialExtractor $extractor,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): bool {
        $phase = $this->unwrapGrouping($phase);
        if (
            !$phase instanceof BinaryOperationNode
            || $phase->operator !== BinaryOperator::Divide
        ) {
            return false;
        }

        $denominatorFactors = [];
        $collectFactors = function (Node $node) use (&$collectFactors, &$denominatorFactors): void {
            $node = $this->unwrapGrouping($node);
            if (
                $node instanceof BinaryOperationNode
                && $node->operator === BinaryOperator::Multiply
            ) {
                $collectFactors($node->left);
                $collectFactors($node->right);
                return;
            }
            $denominatorFactors[] = $node;
        };
        $collectFactors($phase->right);

        foreach ($denominatorFactors as $algebraicFactor) {
            $algebraicForm = $extractor->extractRationalForm($algebraicFactor);
            if ($algebraicForm === null) {
                continue;
            }
            $algebraicZeros = $this->solvePolynomialRootsInInterval(
                $algebraicForm[0],
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($algebraicZeros === null || $algebraicZeros === []) {
                continue;
            }

            foreach ($denominatorFactors as $otherFactor) {
                if ($otherFactor === $algebraicFactor) {
                    continue;
                }
                $otherFactor = $this->unwrapGrouping($otherFactor);
                $logarithmicFactor = $otherFactor;
                $isPositiveIntegerLogPower = false;
                $logarithmPower = 1.0;
                if (
                    $logarithmicFactor instanceof BinaryOperationNode
                    && $logarithmicFactor->operator === BinaryOperator::Power
                ) {
                    $logarithmPower = $extractor->extract($logarithmicFactor->right);
                    if (
                        $logarithmPower !== null
                        && \count($logarithmPower) === 1
                        && $logarithmPower[0] > 0.0
                        && \floor($logarithmPower[0]) === $logarithmPower[0]
                    ) {
                        $isPositiveIntegerLogPower = true;
                        $logarithmPower = $logarithmPower[0];
                        $logarithmicFactor = $this->unwrapGrouping($logarithmicFactor->left);
                    }
                }
                $logarithmHasRationalArgument = $logarithmicFactor instanceof FunctionCallNode
                    && \count($logarithmicFactor->arguments) === 1
                    && \in_array($logarithmicFactor->name, ['ln', 'log2', 'log10'], true)
                    && ($isPositiveIntegerLogPower || $otherFactor === $logarithmicFactor)
                    && $extractor->extractRationalForm($logarithmicFactor->arguments[0]) !== null;
                foreach ($algebraicZeros as $zero) {
                    foreach ([-1, 1] as $direction) {
                        if (
                            ($direction < 0 && $zero->value <= $lowerBound)
                            || ($direction > 0 && $zero->value >= $upperBound)
                        ) {
                            continue;
                        }
                        $algebraicLimit = $this->continuousExpressionLimitAt(
                            $algebraicFactor,
                            $variable,
                            $zero->value,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        );
                        $otherLimit = $this->continuousExpressionLimitAt(
                            $otherFactor,
                            $variable,
                            $zero->value,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        );
                        $logarithmicBaseLimit = $logarithmHasRationalArgument
                            ? $this->continuousExpressionLimitAt(
                                $logarithmicFactor,
                                $variable,
                                $zero->value,
                                $direction,
                                $extractor,
                                $evaluationOptions,
                                $parameters,
                            )
                            : null;
                        $logarithmLimit = $logarithmHasRationalArgument
                            ? $logarithmicBaseLimit
                            : null;
                        if (
                            $logarithmLimit === null
                            && $logarithmHasRationalArgument
                            && $isPositiveIntegerLogPower
                        ) {
                            $baseLogLimit = $this->continuousExpressionLimitAt(
                                $logarithmicFactor,
                                $variable,
                                $zero->value,
                                $direction,
                                $extractor,
                                $evaluationOptions,
                                $parameters,
                            );
                            if ($baseLogLimit !== null && !\is_finite($baseLogLimit)) {
                                $logarithmLimit = $logarithmPower % 2 === 0
                                    ? \INF
                                    : $baseLogLimit;
                            }
                        }
                        if (
                            $algebraicLimit === 0.0
                            && (
                                $otherLimit !== null
                                    && \is_finite($otherLimit)
                                    && $otherLimit !== 0.0
                                || $logarithmHasRationalArgument
                                    && $otherFactor === $logarithmicFactor
                                    && $logarithmicBaseLimit === 0.0
                                || $logarithmHasRationalArgument
                                    && $logarithmLimit !== null
                                    && !\is_finite($logarithmLimit)
                            )
                        ) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function throwIfPeriodicTermWithFiniteOffsetAccumulates(
        Node $left,
        Node $right,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        string $variable,
    ): void {
        foreach ([[$left, $right], [$right, $left]] as [$side, $otherSide]) {
            $side = $this->unwrapGrouping($side);
            $offset = new NumberNode(0.0, '0', $side->span());
            $periodicTerm = $side;
            $periodicSign = 1.0;
            if (
                $side instanceof BinaryOperationNode
                && \in_array($side->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
            ) {
                $periodicTerm = $side->left;
                $offset = $side->right;
                if ($side->operator === BinaryOperator::Subtract) {
                    $periodicSign = 1.0;
                }
                $periodicParts = $this->periodicTermParts($periodicTerm, $extractor);
                if ($periodicParts === null) {
                    $periodicTerm = $side->right;
                    $offset = $side->left;
                    if ($side->operator === BinaryOperator::Subtract) {
                        $periodicSign = -1.0;
                    }
                    $periodicParts = $this->periodicTermParts($periodicTerm, $extractor);
                }
            } else {
                $periodicParts = $this->periodicTermParts($periodicTerm, $extractor);
            }
            if ($periodicParts === null) {
                continue;
            }
            [$function, $amplitudeForm, $smoothScales] = $periodicParts;
            if ($amplitudeForm[0] === [0.0]) {
                continue;
            }
            $phaseForm = $extractor->extractRationalForm($function->arguments[0]);
            if ($phaseForm === null) {
                $amplitude = $this->rationalFormConstant($amplitudeForm);
                $offsetValue = $this->rationalFormConstant(
                    $extractor->extractRationalForm($offset),
                );
                $otherValue = $this->rationalFormConstant(
                    $extractor->extractRationalForm($otherSide),
                );
                if (
                    $amplitude !== null
                    && $amplitude !== 0.0
                    && $offsetValue === 0.0
                    && $otherValue !== null
                    && $this->periodicFunctionHasInteriorTarget(
                        $function->name,
                        ($otherValue / $amplitude) * $periodicSign,
                    )
                    && $smoothScales === []
                    && $this->hasReciprocalAlgebraicLogBoundaryPole(
                        $function->arguments[0],
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $extractor,
                        $options,
                        $evaluationOptions,
                        $parameters,
                    )
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A periodic phase with an algebraic-logarithmic boundary pole has infinitely '
                            . 'many roots accumulating at that boundary.',
                    );
                }
                continue;
            }

            $otherForm = $extractor->extractRationalForm($otherSide);
            $offsetForm = $extractor->extractRationalForm($offset);
            $targetLimitForm = null;
            if ($otherForm !== null && $offsetForm !== null && $smoothScales === []) {
                $differenceNumerator = $this->addPolynomials(
                    $this->multiplyPolynomials($otherForm[0], $offsetForm[1]),
                    $this->multiplyPolynomials($offsetForm[0], $otherForm[1]),
                    -1.0,
                );
                $differenceDenominator = $this->multiplyPolynomials($otherForm[1], $offsetForm[1]);
                $targetNumerator = $this->multiplyPolynomials($differenceNumerator, $amplitudeForm[1]);
                $targetDenominator = $this->multiplyPolynomials($differenceDenominator, $amplitudeForm[0]);
                if ($periodicSign < 0.0) {
                    $targetNumerator = $this->scaledPolynomial($targetNumerator, -1.0);
                }
                foreach ([...$targetNumerator, ...$targetDenominator] as $coefficient) {
                    if (!\is_finite($coefficient)) {
                        continue 2;
                    }
                }
                $targetLimitForm = [$targetNumerator, $targetDenominator];
            }

            $phasePoles = $this->solvePolynomialRootsInInterval(
                $phaseForm[1],
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($phasePoles === null) {
                continue;
            }
            foreach ($phasePoles as $pole) {
                if (
                    $this->polynomialRootMultiplicity($phaseForm[1], $pole->value)
                    <= $this->polynomialRootMultiplicity($phaseForm[0], $pole->value)
                ) {
                    continue;
                }
                $targetLimit = $targetLimitForm === null
                    ? $this->continuousPeriodicTargetLimit(
                        $otherSide,
                        $offset,
                        $periodicSign,
                        $amplitudeForm,
                        $pole->value,
                        $evaluationOptions,
                        $parameters,
                        $smoothScales,
                        $variable,
                    )
                    : $this->rationalFormLimitAt($targetLimitForm, $pole->value);
                if ($targetLimit === null && $targetLimitForm === null) {
                    $boundaryDirections = [
                        [-1, $pole->value > $lowerBound],
                        [1, $pole->value < $upperBound],
                    ];
                    foreach ($boundaryDirections as [$direction, $hasSide]) {
                        if (
                            !$hasSide
                            || $this->periodicPhaseDivergesAtBoundary(
                                $function->arguments[0],
                                $variable,
                                $pole->value,
                                $direction,
                                $extractor,
                                $evaluationOptions,
                                $parameters,
                            ) === null
                        ) {
                            continue;
                        }
                        $otherLimit = $this->continuousExpressionLimitAt(
                            $otherSide,
                            $variable,
                            $pole->value,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        );
                        $offsetLimit = $this->continuousExpressionLimitAt(
                            $offset,
                            $variable,
                            $pole->value,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        );
                        $amplitude = $this->rationalFormLimitAt($amplitudeForm, $pole->value);
                        foreach ($smoothScales as $scale) {
                            $scaleLimit = $this->continuousExpressionLimitAt(
                                $scale,
                                $variable,
                                $pole->value,
                                $direction,
                                $extractor,
                                $evaluationOptions,
                                $parameters,
                            );
                            if ($scaleLimit === null || !\is_finite($scaleLimit)) {
                                $amplitude = null;
                                break;
                            }
                            $amplitude *= $scaleLimit;
                        }
                        if (
                            $otherLimit !== null
                            && \is_finite($otherLimit)
                            && $offsetLimit !== null
                            && \is_finite($offsetLimit)
                            && $amplitude !== null
                            && \is_finite($amplitude)
                            && $amplitude !== 0.0
                        ) {
                            $targetLimit = $periodicSign * ($otherLimit - $offsetLimit) / $amplitude;
                            if (!\is_finite($targetLimit)) {
                                $targetLimit = null;
                            }
                            if ($targetLimit !== null) {
                                break;
                            }
                        }
                    }
                }
                if (
                    $targetLimit === null
                    && $targetLimitForm === null
                    && $this->hasOneSidedExponentialZeroLimit(
                        $otherSide,
                        $pole->value,
                        $lowerBound,
                        $upperBound,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    )
                ) {
                    $amplitude = $this->rationalFormConstant($amplitudeForm);
                    $offsetValue = $this->rationalFormConstant($extractor->extractRationalForm($offset));
                    if ($amplitude !== null && $amplitude !== 0.0 && $offsetValue !== null) {
                        $targetLimit = -$periodicSign * $offsetValue / $amplitude;
                    }
                }
                if (
                    $targetLimit === null
                    && $targetLimitForm === null
                    && $this->isBoundaryConstantPlusOneSidedExponential(
                        $otherSide,
                        $pole->value,
                        $lowerBound,
                        $upperBound,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    )
                ) {
                    $amplitude = $this->rationalFormConstant($amplitudeForm);
                    $offsetValue = $this->rationalFormConstant($extractor->extractRationalForm($offset));
                    $otherValue = $this->constantTermOfAddSubtract($otherSide, $extractor);
                    if ($amplitude !== null && $amplitude !== 0.0 && $offsetValue !== null && $otherValue !== null) {
                        $targetLimit = $periodicSign * ($otherValue - $offsetValue) / $amplitude;
                    }
                }
                if ($targetLimit === null || !\is_finite($targetLimit)) {
                    continue;
                }
                $oscillationIsUnbounded = $targetLimitForm === null
                    ? $this->periodicFunctionHasInteriorTarget($function->name, $targetLimit)
                        || $this->periodicContinuousTargetHasBoundaryRoots(
                            $function->name,
                            $targetLimit,
                            $otherSide,
                            $offset,
                            $periodicSign,
                            $amplitudeForm,
                            $pole->value,
                            $lowerBound,
                            $upperBound,
                            $variable,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                            $smoothScales,
                        )
                    : $this->periodicTargetHasRootsNearLimit(
                        $function->name,
                        $targetLimit,
                        $targetLimitForm,
                        $pole->value,
                        $lowerBound,
                        $upperBound,
                    );
                if ($oscillationIsUnbounded) {
                    throw new InfiniteRootAccumulationException(
                        'A periodic term with a finite rational offset or scale has infinitely many '
                            . 'roots accumulating at a phase pole.',
                    );
                }
            }
        }
    }

    /** @param array{list<float>, list<float>} $amplitudeForm
     *  @param array<string, int|float> $parameters
     *  @param list<Node> $smoothScales
     */
    private function continuousPeriodicTargetLimit(
        Node $otherSide,
        Node $offset,
        float $periodicSign,
        array $amplitudeForm,
        float $pole,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        array $smoothScales,
        string $variable,
    ): ?float {
        if (
            !$this->isLocallyContinuous($otherSide, $pole, $evaluationOptions, $parameters, $variable)
            || !$this->isLocallyContinuous($offset, $pole, $evaluationOptions, $parameters, $variable)
        ) {
            return null;
        }
        $amplitude = $this->rationalFormLimitAt($amplitudeForm, $pole);
        if ($amplitude === null || $amplitude === 0.0) {
            return null;
        }
        foreach ($smoothScales as $scale) {
            if (!$this->isLocallyContinuous($scale, $pole, $evaluationOptions, $parameters, $variable)) {
                return null;
            }
            try {
                $amplitude *= (float) $this->evaluateNode(
                    $scale,
                    [...$parameters, $variable => $pole],
                    $evaluationOptions,
                );
            } catch (\Throwable) {
                return null;
            }
        }
        if ($amplitude === 0.0 || !\is_finite($amplitude)) {
            return null;
        }
        try {
            $otherValue = (float) $this->evaluateNode(
                $otherSide,
                [...$parameters, $variable => $pole],
                $evaluationOptions,
            );
            $offsetValue = (float) $this->evaluateNode(
                $offset,
                [...$parameters, $variable => $pole],
                $evaluationOptions,
            );
        } catch (\Throwable) {
            return null;
        }
        $limit = $periodicSign * ($otherValue - $offsetValue) / $amplitude;

        return \is_finite($limit) ? $limit : null;
    }

    /**
     * Prove pointwise continuity for supported arithmetic and built-in functions,
     * while checking every function domain at the candidate point.
     *
     * @param array<string, int|float> $parameters
     */
    private function isLocallyContinuous(
        Node $node,
        float $position,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        string $variable,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof NumberNode || $node instanceof \MathPHP\Ast\ConstantNode) {
            return true;
        }
        if ($node instanceof VariableNode) {
            return $node->name === $variable || \array_key_exists($node->name, $parameters);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->isLocallyContinuous($node->operand, $position, $evaluationOptions, $parameters, $variable);
        }
        if ($node instanceof BinaryOperationNode) {
            if (
                !$this->isLocallyContinuous($node->left, $position, $evaluationOptions, $parameters, $variable)
                || !$this->isLocallyContinuous($node->right, $position, $evaluationOptions, $parameters, $variable)
                || $node->operator === BinaryOperator::Modulo
            ) {
                return false;
            }
            if ($node->operator === BinaryOperator::Power) {
                if ($this->containsVariable($node->right, $variable)) {
                    return false;
                }
                try {
                    $exponent = (float) $this->evaluateNode(
                        $node->right,
                        [...$parameters, $variable => $position],
                        $evaluationOptions,
                    );
                    if (!\is_finite($exponent)) {
                        return false;
                    }
                    $base = (float) $this->evaluateNode(
                        $node->left,
                        [...$parameters, $variable => $position],
                        $evaluationOptions,
                    );
                    if ($base === 0.0) {
                        return $exponent > 0.0
                            && (\floor($exponent) === $exponent
                                || $this->isLocallyNonnegative(
                                    $node->left,
                                    $position,
                                    $evaluationOptions,
                                    $parameters,
                                    $variable,
                                ));
                    }

                    return $base > 0.0 || \floor($exponent) === $exponent;
                } catch (\Throwable) {
                    return false;
                }
            }
            if ($node->operator !== BinaryOperator::Divide) {
                return true;
            }
            try {
                return (float) $this->evaluateNode(
                    $node->right,
                    [...$parameters, $variable => $position],
                    $evaluationOptions,
                ) !== 0.0;
            } catch (\Throwable) {
                return false;
            }
        }
        if ($node instanceof FunctionCallNode) {
            if (!$evaluationOptions->functions->isBuiltIn($node->name)) {
                return false;
            }
            foreach ($node->arguments as $argument) {
                if (!$this->isLocallyContinuous($argument, $position, $evaluationOptions, $parameters, $variable)) {
                    return false;
                }
            }
            try {
                $this->evaluateNode($node, [...$parameters, $variable => $position], $evaluationOptions);
                if ($node->name === 'abs') {
                    return true;
                }
                if ($node->name === 'sqrt') {
                    $radicand = (float) $this->evaluateNode(
                        $node->arguments[0],
                        [...$parameters, $variable => $position],
                        $evaluationOptions,
                    );

                    return $radicand > 0.0
                        || ($radicand === 0.0 && $this->isLocallyNonnegative(
                            $node->arguments[0],
                            $position,
                            $evaluationOptions,
                            $parameters,
                            $variable,
                        ));
                }
                if (\in_array($node->name, ['floor', 'ceil', 'round', 'trunc', 'sign'], true)) {
                    $argument = (float) $this->evaluateNode(
                        $node->arguments[0],
                        [...$parameters, $variable => $position],
                        $evaluationOptions,
                    );
                    if ($node->name === 'sign') {
                        return $argument !== 0.0;
                    }
                    if ($node->name === 'round') {
                        $precision = isset($node->arguments[1])
                            ? (int) $this->evaluateNode(
                                $node->arguments[1],
                                [...$parameters, $variable => $position],
                                $evaluationOptions,
                            )
                            : 0;
                        $scaledArgument = $argument * (10.0 ** $precision);

                        return \is_finite($scaledArgument)
                            && $scaledArgument - \floor($scaledArgument) !== 0.5;
                    }
                    if ($node->name === 'trunc' && $argument === 0.0) {
                        return true;
                    }

                    return \floor($argument) !== $argument;
                }

                return !\in_array($node->name, [
                    'factorial',
                    'lambertw', 'root', 'mod', 'gcd', 'lcm',
                ], true);
            } catch (\Throwable) {
                return false;
            }
        }

        return false;
    }

    /**
     * Prove non-negativity for common continuous radicands at and around a point.
     *
     * @param array<string, int|float> $parameters
     */
    private function isLocallyNonnegative(
        Node $node,
        float $position,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        string $variable,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode && $node->name === 'abs' && \count($node->arguments) === 1) {
            return $this->isLocallyContinuous(
                $node->arguments[0],
                $position,
                $evaluationOptions,
                $parameters,
                $variable,
            );
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $exponent = RationalLiteral::fromNode($node->right);
            if ($exponent === null || $exponent[0] <= 0) {
                return false;
            }

            return ($exponent[1] === 1
                    && ($exponent[0] % 2) === 0
                    && $this->isLocallyContinuous(
                        $node->left,
                        $position,
                        $evaluationOptions,
                        $parameters,
                        $variable,
                    ))
                || $this->isLocallyNonnegative(
                    $node->left,
                    $position,
                    $evaluationOptions,
                    $parameters,
                    $variable,
                );
        }

        return false;
    }

    /**
     * @param array{list<float>, list<float>} $amplitudeForm
     * @param list<Node> $smoothScales
     *  @param array<string, int|float> $parameters
     */
    private function periodicContinuousTargetHasBoundaryRoots(
        string $function,
        float $targetLimit,
        Node $otherSide,
        Node $offset,
        float $periodicSign,
        array $amplitudeForm,
        float $pole,
        float $lowerBound,
        float $upperBound,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        array $smoothScales,
    ): bool {
        if (
            !\in_array($function, ['sin', 'cos'], true)
            || \abs(\abs($targetLimit) - 1.0) > 64.0 * \PHP_FLOAT_EPSILON
            || $periodicSign === 0.0
            || $smoothScales !== []
        ) {
            return false;
        }
        $amplitude = $this->rationalFormConstant($amplitudeForm);
        if (
            $amplitude !== null && $amplitude !== 0.0 && $this->isBoundaryConstantPlusOneSidedExponential(
                $otherSide,
                $pole,
                $lowerBound,
                $upperBound,
                $variable,
                $extractor,
                $evaluationOptions,
                $parameters,
            )
        ) {
            // The exponential perturbation has zero limit; the constant term
            // determines the target limit while its sign determines entry.
            $rawDifferenceSign = $this->simpleContinuousDifferenceSignNearPoint(
                $otherSide,
                $targetLimit,
                $pole,
                $lowerBound,
                $upperBound,
                $variable,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($rawDifferenceSign !== null) {
                $normalizedDifferenceSign = $rawDifferenceSign
                    * (($periodicSign / $amplitude) < 0.0 ? -1 : 1);
                return $targetLimit > 0.0
                    ? $normalizedDifferenceSign <= 0
                    : $normalizedDifferenceSign >= 0;
            }
        }
        $offsetValue = $this->rationalFormConstant($extractor->extractRationalForm($offset));
        if ($amplitude === null || $amplitude === 0.0 || $offsetValue === null) {
            return false;
        }
        $otherBoundaryValue = $offsetValue + (($targetLimit * $amplitude) / $periodicSign);
        if (!\is_finite($otherBoundaryValue)) {
            return false;
        }
        $rawDifferenceSign = $this->simpleContinuousDifferenceSignNearPoint(
            $otherSide,
            $otherBoundaryValue,
            $pole,
            $lowerBound,
            $upperBound,
            $variable,
            $extractor,
            $evaluationOptions,
            $parameters,
        );
        if ($rawDifferenceSign === null) {
            return false;
        }
        $normalizedDifferenceSign = $rawDifferenceSign
            * (($periodicSign / $amplitude) < 0.0 ? -1 : 1);

        return $targetLimit > 0.0
            ? $normalizedDifferenceSign <= 0
            : $normalizedDifferenceSign >= 0;
    }

    /** @param array<string, int|float> $parameters */
    private function simpleContinuousDifferenceSignNearPoint(
        Node $node,
        float $limit,
        float $position,
        float $lowerBound,
        float $upperBound,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
        int $direction = 1,
    ): ?int {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        if (!\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            return null;
        }
        foreach ([$node->left, $node->right] as $constantSide) {
            $term = $constantSide === $node->left ? $node->right : $node->left;
            $constant = $this->rationalFormConstant($extractor->extractRationalForm($constantSide));
            if (
                $constant === $limit
                && $this->continuousExpressionLimitAt(
                    $term,
                    $variable,
                    $position,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                ) === 0.0
            ) {
                $termSign = $this->expressionSignNearBoundary(
                    $term,
                    $variable,
                    $position,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($termSign !== null) {
                    return $node->operator === BinaryOperator::Subtract && $constantSide === $node->left
                        ? -$termSign
                        : $termSign;
                }
            }
            if (
                $constant === $limit && $this->hasOneSidedExponentialZeroLimit(
                    $term,
                    $position,
                    $lowerBound,
                    $upperBound,
                    $variable,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                )
            ) {
                return $node->operator === BinaryOperator::Add
                    ? 1
                    : ($constantSide === $node->left ? -1 : 1);
            }
        }
        try {
            $leftValue = (float) $this->evaluateNode(
                $node->left,
                [...$parameters, $variable => $position],
                $evaluationOptions,
            );
            $rightValue = (float) $this->evaluateNode(
                $node->right,
                [...$parameters, $variable => $position],
                $evaluationOptions,
            );
        } catch (EvaluationException) {
            return null;
        }

        if ($leftValue === $limit && $rightValue === 0.0) {
            $termIsPositive = $this->isStrictlyPositiveAwayFromPoint(
                $node->right,
                $position,
                $variable,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($termIsPositive) {
                return $node->operator === BinaryOperator::Add ? 1 : -1;
            }
        }
        if ($rightValue === $limit && $leftValue === 0.0) {
            $termIsPositive = $this->isStrictlyPositiveAwayFromPoint(
                $node->left,
                $position,
                $variable,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($termIsPositive) {
                return $node->operator === BinaryOperator::Add ? 1 : -1;
            }
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function hasOneSidedExponentialZeroLimit(
        Node $node,
        float $position,
        float $lowerBound,
        float $upperBound,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode && $node->operator === UnaryOperator::Minus) {
            return $this->hasOneSidedExponentialZeroLimit(
                $node->operand,
                $position,
                $lowerBound,
                $upperBound,
                $variable,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$exponential, $factor]) {
                $factorForm = $extractor->extractRationalForm($factor);
                if ($factorForm === null || $this->rationalFormLimitAt($factorForm, $position) !== 0.0) {
                    continue;
                }
                $factorSideSigns = [
                    $position < $upperBound ? $this->rationalFormSignOnSide(
                        $factorForm,
                        $position,
                        true,
                    ) : null,
                    $position > $lowerBound ? $this->rationalFormSignOnSide(
                        $factorForm,
                        $position,
                        false,
                    ) : null,
                ];
                $positiveRight = $factorSideSigns[0] === 1
                    && $this->hasOneSidedExponentialZeroLimit(
                        $exponential,
                        $position,
                        $position,
                        $upperBound,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    );
                $positiveLeft = $factorSideSigns[1] === 1
                    && $this->hasOneSidedExponentialZeroLimit(
                        $exponential,
                        $position,
                        $lowerBound,
                        $position,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    );
                if ($positiveRight || $positiveLeft) {
                    return true;
                }
            }

            return false;
        }
        if (!$node instanceof FunctionCallNode || $node->name !== 'exp' || \count($node->arguments) !== 1) {
            return false;
        }
        $argument = $this->unwrapGrouping($node->arguments[0]);
        $negativeOutside = $argument instanceof UnaryOperationNode
            && $argument->operator === UnaryOperator::Minus;
        $reciprocal = $negativeOutside ? $this->unwrapGrouping($argument->operand) : $argument;
        if (!$reciprocal instanceof BinaryOperationNode || $reciprocal->operator !== BinaryOperator::Divide) {
            return false;
        }
        $numeratorNode = $this->unwrapGrouping($reciprocal->left);
        $negativeNumerator = $numeratorNode instanceof UnaryOperationNode
            && $numeratorNode->operator === UnaryOperator::Minus;
        if ($negativeNumerator) {
            $numeratorNode = $this->unwrapGrouping($numeratorNode->operand);
        }
        $numerator = $this->rationalFormConstant($extractor->extractRationalForm($numeratorNode));
        $denominator = $extractor->extractRationalForm($reciprocal->right);
        $numeratorSign = ($negativeOutside xor $negativeNumerator) ? -1.0 : 1.0;
        if ($numerator === null || $numerator <= 0.0) {
            return false;
        }
        if ($denominator === null) {
            foreach ([[-1, $position > $lowerBound], [1, $position < $upperBound]] as [$direction, $hasSide]) {
                if (!$hasSide) {
                    continue;
                }
                $limit = $this->continuousExpressionLimitAt(
                    $reciprocal->right,
                    $variable,
                    $position,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                $positiveDenominator = $this->isLocallyNonnegative(
                    $reciprocal->right,
                    $position,
                    $evaluationOptions,
                    $parameters,
                    $variable,
                ) && $this->isStrictlyPositiveAwayFromPoint(
                    $reciprocal->right,
                    $position,
                    $variable,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                $denominator = $this->unwrapGrouping($reciprocal->right);
                if (
                    !$positiveDenominator
                    && $denominator instanceof FunctionCallNode
                    && $denominator->name === 'sqrt'
                    && \count($denominator->arguments) === 1
                ) {
                    $positiveDenominator = $this->expressionSignNearBoundary(
                        $denominator->arguments[0],
                        $variable,
                        $position,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    ) === 1;
                }
                if (
                    $limit === 0.0
                    && $positiveDenominator
                    && $numeratorSign < 0.0
                ) {
                    return true;
                }
            }

            return false;
        }
        $denominatorLimit = $this->rationalFormLimitAt($denominator, $position);
        if ($denominatorLimit !== 0.0) {
            return false;
        }
        $rootMultiplicity = $this->polynomialRootMultiplicity($denominator[0], $position);
        if ($rootMultiplicity <= 0) {
            return false;
        }
        $rightSign = $position < $upperBound ? $this->polynomialSignBetweenPoints(
            $denominator[0],
            $position,
            ($position + $upperBound) / 2.0,
            true,
        ) : null;
        $leftSign = $position > $lowerBound ? $this->polynomialSignBetweenPoints(
            $denominator[0],
            ($lowerBound + $position) / 2.0,
            $position,
            false,
        ) : null;
        if ($numeratorSign * (float) $rightSign >= 0.0 && $numeratorSign * (float) $leftSign >= 0.0) {
            return false;
        }

        return $this->isLocallyContinuous($reciprocal->right, $position, $evaluationOptions, $parameters, $variable);
    }

    /** @param array{list<float>, list<float>} $form */
    private function rationalFormSignOnSide(
        array $form,
        float $position,
        bool $rightSide,
    ): ?int {
        $numeratorSign = $this->polynomialSignImmediatelyAtRoot($form[0], $position, $rightSide);
        $denominatorSign = $this->polynomialSignImmediatelyAtRoot($form[1], $position, $rightSide);
        if ($numeratorSign === null || $denominatorSign === null || $denominatorSign === 0) {
            return null;
        }

        return $numeratorSign * $denominatorSign;
    }

    /** @param list<float> $polynomial */
    private function polynomialSignImmediatelyAtRoot(array $polynomial, float $position, bool $rightSide): ?int
    {
        $order = $this->polynomialRootMultiplicity($polynomial, $position);
        if ($order === 0) {
            $value = (new PolynomialSolver())->evaluatePolynomial($polynomial, $position);

            return $value === null ? null : ($value <=> 0.0);
        }
        $derivative = $polynomial;
        for ($index = 0; $index < $order; ++$index) {
            $derivative = $this->polynomialDerivative($derivative);
        }
        $leadingValue = (new PolynomialSolver())->evaluatePolynomial($derivative, $position);
        if ($leadingValue === null || $leadingValue === 0.0) {
            return null;
        }
        $sign = $leadingValue <=> 0.0;

        return !$rightSide && ($order % 2) === 1 ? -$sign : $sign;
    }

    /** @param array<string, int|float> $parameters */
    private function isBoundaryConstantPlusOneSidedExponential(
        Node $node,
        float $position,
        float $lowerBound,
        float $upperBound,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (
            !$node instanceof BinaryOperationNode
            || !\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return false;
        }
        foreach ([$node->left, $node->right] as $constantSide) {
            $term = $constantSide === $node->left ? $node->right : $node->left;
            if (
                $this->rationalFormConstant($extractor->extractRationalForm($constantSide)) !== null
                && $this->hasOneSidedExponentialZeroLimit(
                    $term,
                    $position,
                    $lowerBound,
                    $upperBound,
                    $variable,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    private function constantTermOfAddSubtract(Node $node, PolynomialExtractor $extractor): ?float
    {
        $node = $this->unwrapGrouping($node);
        if (
            !$node instanceof BinaryOperationNode
            || !\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return null;
        }
        foreach ([$node->left, $node->right] as $constantSide) {
            $constant = $this->rationalFormConstant($extractor->extractRationalForm($constantSide));
            if ($constant !== null) {
                return $constant;
            }
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function isStrictlyPositiveAwayFromPoint(
        Node $node,
        float $position,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode && $node->name === 'abs' && \count($node->arguments) === 1) {
            return $this->hasSimpleZeroAtPoint(
                $node->arguments[0],
                $position,
                $variable,
                $extractor,
            );
        }
        if ($node instanceof FunctionCallNode && $node->name === 'sqrt' && \count($node->arguments) === 1) {
            return $this->isLocallyNonnegative(
                $node->arguments[0],
                $position,
                $evaluationOptions,
                $parameters,
                $variable,
            )
                && $this->isStrictlyPositiveAwayFromPoint(
                    $node->arguments[0],
                    $position,
                    $variable,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $exponent = RationalLiteral::fromNode($node->right);
            if ($exponent === null || $exponent[0] <= 0) {
                return false;
            }

            return ($exponent[1] === 1
                    && ($exponent[0] % 2) === 0
                    && $this->hasSimpleZeroAtPoint(
                        $node->left,
                        $position,
                        $variable,
                        $extractor,
                    ))
                || (
                    $this->isLocallyNonnegative(
                        $node->left,
                        $position,
                        $evaluationOptions,
                        $parameters,
                        $variable,
                    ) && $this->isStrictlyPositiveAwayFromPoint(
                        $node->left,
                        $position,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    )
                );
        }

        return false;
    }

    private function hasSimpleZeroAtPoint(
        Node $node,
        float $position,
        string $variable,
        PolynomialExtractor $extractor,
    ): bool {
        if (!$this->containsVariable($node, $variable)) {
            return false;
        }
        $coefficients = $this->extractPolynomial($extractor, $node, 0);

        return $coefficients !== null
            && \count($coefficients) === 2
            && $coefficients[1] !== 0.0
            && ($coefficients[0] + ($coefficients[1] * $position)) === 0.0;
    }

    /** @param array<string, int|float> $parameters */
    private function periodicTargetIsStrictlyOutsideRange(
        Node $periodicSide,
        Node $targetSide,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $periodicSide = $this->unwrapGrouping($periodicSide);
        $targetSide = $this->unwrapGrouping($targetSide);
        if (
            !$periodicSide instanceof FunctionCallNode
            || !\in_array($periodicSide->name, ['sin', 'cos'], true)
            || \count($periodicSide->arguments) !== 1
            || !$targetSide instanceof BinaryOperationNode
            || !\in_array($targetSide->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return false;
        }
        $constantAndTermPairs = [
            [$targetSide->left, $targetSide->right],
            [$targetSide->right, $targetSide->left],
        ];
        foreach ($constantAndTermPairs as [$constantNode, $term]) {
            $constant = $this->rationalFormConstant(
                (new PolynomialExtractor($variable, $parameters, $evaluationOptions))
                    ->extractRationalForm($constantNode),
            );
            if ($constant === null || !$this->isStrictlyPositiveExpression($term)) {
                continue;
            }
            if (
                $targetSide->operator === BinaryOperator::Add && $constant >= 1.0
                || $targetSide->operator === BinaryOperator::Subtract && $constant <= -1.0
            ) {
                return true;
            }
        }

        return false;
    }

    private function isStrictlyPositiveExpression(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode && $node->name === 'exp' && \count($node->arguments) === 1) {
            return true;
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            return $this->isStrictlyPositiveExpression($node->left)
                && $this->isStrictlyPositiveExpression($node->right);
        }

        return false;
    }

    private function periodicFunctionHasInteriorTarget(string $function, float $target): bool
    {
        return match ($function) {
            'sin', 'cos' => \abs($target) < 1.0,
            'sec', 'csc' => \abs($target) > 1.0,
            'tan', 'cot' => true,
            default => false,
        };
    }

    /**
     * @param array{list<float>, list<float>} $targetForm
     */
    private function periodicTargetHasRootsNearLimit(
        string $function,
        float $limit,
        array $targetForm,
        float $pole,
        float $lowerBound,
        float $upperBound,
    ): bool {
        $absoluteLimit = \abs($limit);
        if (
            \in_array($function, ['sin', 'cos'], true)
            && $absoluteLimit < 1.0
        ) {
            return true;
        }
        if (
            \in_array($function, ['sec', 'csc'], true)
            && $absoluteLimit > 1.0
        ) {
            return true;
        }
        if (\in_array($function, ['tan', 'cot'], true)) {
            return true;
        }

        $isRangeBoundary = \abs($absoluteLimit - 1.0)
            <= 64.0 * \PHP_FLOAT_EPSILON * \max(1.0, $absoluteLimit);
        if (!$isRangeBoundary || !\in_array($function, ['sin', 'cos', 'sec', 'csc'], true)) {
            return false;
        }

        $boundaryLimit = $limit < 0.0 ? -1.0 : 1.0;
        $differenceFromBoundary = [
            $this->addPolynomials($targetForm[0], $targetForm[1], -$boundaryLimit),
            $targetForm[1],
        ];
        $allowedDifferenceSign = match ([$function, $limit > 0.0]) {
            ['sin', true], ['cos', true], ['sec', false], ['csc', false] => -1,
            default => 1,
        };
        foreach ([[-1, $pole > $lowerBound], [1, $pole < $upperBound]] as [$direction, $hasSide]) {
            if (!$hasSide) {
                continue;
            }
            $sign = $this->rationalFormSignNear($differenceFromBoundary, $pole, $direction);
            if ($sign === null || $sign === 0 || $sign === $allowedDifferenceSign) {
                return true;
            }
        }

        return false;
    }

    /** @param array{list<float>, list<float>} $form */
    private function rationalFormSignNear(array $form, float $position, int $direction): ?int
    {
        [$numerator, $denominator] = $form;
        if ($denominator === [0.0]) {
            return null;
        }
        if ($numerator === [0.0]) {
            return 0;
        }
        $numeratorOrder = $this->polynomialRootMultiplicity($numerator, $position);
        $denominatorOrder = $this->polynomialRootMultiplicity($denominator, $position);

        $numeratorDerivative = $numerator;
        $denominatorDerivative = $denominator;
        for ($order = 0; $order < $numeratorOrder; ++$order) {
            $numeratorDerivative = $this->polynomialDerivative($numeratorDerivative);
        }
        for ($order = 0; $order < $denominatorOrder; ++$order) {
            $denominatorDerivative = $this->polynomialDerivative($denominatorDerivative);
        }
        $solver = new PolynomialSolver();
        $numeratorValue = $solver->evaluatePolynomial($numeratorDerivative, $position);
        $denominatorValue = $solver->evaluatePolynomial($denominatorDerivative, $position);
        if (
            $numeratorValue === null
            || $denominatorValue === null
            || $numeratorValue === 0.0
            || $denominatorValue === 0.0
        ) {
            return null;
        }

        $sign = ($numeratorValue > 0.0) === ($denominatorValue > 0.0) ? 1 : -1;
        if (
            $direction < 0
            && \abs($numeratorOrder - $denominatorOrder) % 2 === 1
        ) {
            $sign = -$sign;
        }

        return $sign;
    }

    /**
     * @return array{FunctionCallNode, array{list<float>, list<float>}, list<Node>}|null
     */
    private function periodicTermParts(Node $node, PolynomialExtractor $extractor): ?array
    {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && \count($node->arguments) === 1
            && \in_array($node->name, ['sin', 'cos', 'tan', 'sec', 'csc', 'cot'], true)
        ) {
            return [$node, [[1.0], [1.0]], []];
        }
        if (
            $node instanceof UnaryOperationNode
            && $node->operator === UnaryOperator::Minus
        ) {
            $parts = $this->periodicTermParts($node->operand, $extractor);
            if ($parts !== null) {
                $parts[1][0] = $this->scaledPolynomial($parts[1][0], -1.0);
            }

            return $parts;
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        if ($node->operator === BinaryOperator::Multiply) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$term, $scale]) {
                $parts = $this->periodicTermParts($term, $extractor);
                $scaleForm = $extractor->extractRationalForm($scale);
                if ($parts === null) {
                    continue;
                }
                if ($scaleForm !== null) {
                    $parts[1] = [
                        $this->multiplyPolynomials($parts[1][0], $scaleForm[0]),
                        $this->multiplyPolynomials($parts[1][1], $scaleForm[1]),
                    ];
                } else {
                    $parts[2][] = $scale;
                }

                return $parts;
            }
        }
        if ($node->operator === BinaryOperator::Divide) {
            $parts = $this->periodicTermParts($node->left, $extractor);
            $denominator = $extractor->extractRationalForm($node->right);
            if ($parts !== null && $denominator !== null) {
                $parts[1] = [
                    $this->multiplyPolynomials($parts[1][0], $denominator[1]),
                    $this->multiplyPolynomials($parts[1][1], $denominator[0]),
                ];

                return $parts;
            }
        }

        return null;
    }

    /** @param array{list<float>, list<float>} $form */
    private function rationalFormLimitAt(array $form, float $position): ?float
    {
        [$numerator, $denominator] = $form;
        if ($denominator === [0.0]) {
            return null;
        }
        if ($numerator === [0.0]) {
            return 0.0;
        }
        $numeratorOrder = $this->polynomialRootMultiplicity($numerator, $position);
        $denominatorOrder = $this->polynomialRootMultiplicity($denominator, $position);
        if ($numeratorOrder < $denominatorOrder) {
            return null;
        }
        if ($numeratorOrder > $denominatorOrder) {
            return 0.0;
        }

        $numeratorDerivative = $numerator;
        $denominatorDerivative = $denominator;
        for ($order = 0; $order < $numeratorOrder; ++$order) {
            $numeratorDerivative = $this->polynomialDerivative($numeratorDerivative);
            $denominatorDerivative = $this->polynomialDerivative($denominatorDerivative);
        }
        $solver = new PolynomialSolver();
        $numeratorValue = $solver->evaluatePolynomial($numeratorDerivative, $position);
        $denominatorValue = $solver->evaluatePolynomial($denominatorDerivative, $position);
        if ($numeratorValue === null || $denominatorValue === null || $denominatorValue === 0.0) {
            return null;
        }
        $limit = $numeratorValue / $denominatorValue;

        return \is_finite($limit) ? $limit : null;
    }

    /** @param array<string, int|float> $parameters */
    private function periodicPhaseDivergesAtBoundary(
        Node $node,
        string $variable,
        float $boundary,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): ?int {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            $poleArgumentIndex = match ($node->name) {
                'gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma' => 0,
                'polygamma' => 1,
                default => null,
            };
            if ($poleArgumentIndex !== null && isset($node->arguments[$poleArgumentIndex])) {
                $poleArgument = $node->arguments[$poleArgumentIndex];
                if ($this->containsVariable($poleArgument, $variable)) {
                    $validOrder = true;
                    if ($node->name === 'polygamma') {
                        try {
                            $order = $this->evaluateNode(
                                $node->arguments[0],
                                $parameters,
                                $evaluationOptions,
                            );
                            $validOrder = $order >= 0
                                && $order <= SpecialFunctions::MAX_POLYGAMMA_ORDER
                                && \floor((float) $order) === (float) $order;
                        } catch (EvaluationException) {
                            $validOrder = false;
                        }
                    }
                    if ($validOrder) {
                        $argumentLimit = $this->continuousExpressionLimitAt(
                            $poleArgument,
                            $variable,
                            $boundary,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        );
                        if ($argumentLimit === -\INF) {
                            return -1;
                        }
                        if (
                            $argumentLimit === \INF
                            && \in_array($node->name, ['gamma', 'lgamma', 'digamma'], true)
                        ) {
                            return 1;
                        }
                        if ($argumentLimit === \INF && $node->name === 'polygamma') {
                            try {
                                $order = $this->evaluateNode(
                                    $node->arguments[0],
                                    $parameters,
                                    $evaluationOptions,
                                );
                                if ((float) $order === 0.0) {
                                    return 1;
                                }
                            } catch (EvaluationException) {
                                // The order was already validated above when possible.
                            }
                        }
                        if (
                            !\in_array($node->name, ['gamma', 'lgamma'], true)
                            && $argumentLimit !== null
                            && \is_finite($argumentLimit)
                        ) {
                            $pole = \round($argumentLimit);
                            if (
                                $argumentLimit <= 0.0
                                && \abs($argumentLimit - $pole) <= 1.0E-12
                                && $this->expressionDiffersFromConstantNearBoundary(
                                    $poleArgument,
                                    (float) $pole,
                                    $variable,
                                    $boundary,
                                    $direction,
                                    $extractor,
                                    $evaluationOptions,
                                    $parameters,
                                )
                            ) {
                                return -1;
                            }
                        }
                    }
                }
            }
        }

        $rational = $extractor->extractRationalForm($node);
        if ($rational !== null) {
            $numeratorOrder = $this->polynomialRootMultiplicity($rational[0], $boundary);
            $denominatorOrder = $this->polynomialRootMultiplicity($rational[1], $boundary);
            if ($denominatorOrder > $numeratorOrder) {
                return $this->rationalFormSignNear($rational, $boundary, $direction);
            }

            return null;
        }

        if ($node instanceof FunctionCallNode && \count($node->arguments) === 1) {
            $argument = $node->arguments[0];
            if (\in_array($node->name, ['exp', 'sqrt'], true)) {
                $argumentDivergence = $this->periodicPhaseDivergesAtBoundary(
                    $argument,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($argumentDivergence !== null && $argumentDivergence > 0) {
                    return 1;
                }
            }
            if (\in_array($node->name, ['asinh', 'acosh'], true)) {
                $argumentLimit = $this->continuousExpressionLimitAt(
                    $argument,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($argumentLimit === \INF || ($node->name === 'asinh' && $argumentLimit === -\INF)) {
                    return $argumentLimit > 0.0 ? 1 : -1;
                }
            }
            if (\in_array($node->name, ['ln', 'log2', 'log10'], true)) {
                $limit = $this->continuousExpressionLimitAt(
                    $node,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($limit === \INF) {
                    return 1;
                }
                if ($limit === -\INF) {
                    return -1;
                }
            }
        }

        if ($node instanceof FunctionCallNode && $node->name === 'log' && \count($node->arguments) === 2) {
            $argumentLimit = $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $baseLimit = $this->continuousExpressionLimitAt(
                $node->arguments[1],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if (
                $baseLimit !== null
                && \is_finite($baseLimit)
                && $baseLimit > 0.0
                && $baseLimit !== 1.0
            ) {
                if ($argumentLimit === \INF) {
                    return $baseLimit > 1.0 ? 1 : -1;
                }
                if (
                    $argumentLimit === 0.0
                    && $this->expressionSignNearBoundary(
                        $node->arguments[0],
                        $variable,
                        $boundary,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    ) === 1
                ) {
                    return $baseLimit > 1.0 ? -1 : 1;
                }
            }
        }

        if ($node instanceof FunctionCallNode && $node->name === 'lambertw') {
            $branch = 0.0;
            if (\count($node->arguments) === 2) {
                $branchLimit = $this->continuousExpressionLimitAt(
                    $node->arguments[1],
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($branchLimit === null || !\is_finite($branchLimit)) {
                    return null;
                }
                $branch = $branchLimit;
            } elseif (\count($node->arguments) !== 1) {
                return null;
            }
            $argumentLimit = $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($branch === 0.0 && $argumentLimit === \INF) {
                return 1;
            }
            if (
                $branch === -1.0
                && $argumentLimit === 0.0
                && $this->expressionSignNearBoundary(
                    $node->arguments[0],
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                ) === -1
            ) {
                return -1;
            }
        }

        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $numeratorLimit = $this->continuousExpressionLimitAt(
                $node->left,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $denominatorLimit = $this->continuousExpressionLimitAt(
                $node->right,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($numeratorLimit !== null && $numeratorLimit !== 0.0 && $denominatorLimit === 0.0) {
                $denominatorSign = $this->expressionSignNearBoundary(
                    $node->right,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($denominatorSign !== null) {
                    return ($numeratorLimit > 0.0 ? 1 : -1) * $denominatorSign;
                }
            }
        }

        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $numeratorDivergence = $this->periodicPhaseDivergesAtBoundary(
                $node->left,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($numeratorDivergence !== null) {
                $denominatorLimit = $this->continuousExpressionLimitAt(
                    $node->right,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($denominatorLimit !== null && \is_finite($denominatorLimit) && $denominatorLimit !== 0.0) {
                    return ($denominatorLimit > 0.0 ? 1 : -1) * $numeratorDivergence;
                }
                if ($denominatorLimit === 0.0) {
                    $denominatorSign = $this->expressionSignNearBoundary(
                        $node->right,
                        $variable,
                        $boundary,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    );
                    if ($denominatorSign !== null) {
                        return $denominatorSign * $numeratorDivergence;
                    }
                }
            }
        }

        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $leftDivergence = $this->periodicPhaseDivergesAtBoundary(
                $node->left,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $rightDivergence = $this->periodicPhaseDivergesAtBoundary(
                $node->right,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $rightScale = $node->operator === BinaryOperator::Subtract ? -1 : 1;
            if ($leftDivergence !== null && $rightDivergence !== null) {
                $combined = $leftDivergence + ($rightScale * $rightDivergence);
                if ($combined !== 0) {
                    return $combined > 0 ? 1 : -1;
                }
            } elseif ($leftDivergence !== null) {
                $rightLimit = $this->continuousExpressionLimitAt(
                    $node->right,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($rightLimit !== null && \is_finite($rightLimit)) {
                    return $leftDivergence;
                }
            } elseif ($rightDivergence !== null) {
                $leftLimit = $this->continuousExpressionLimitAt(
                    $node->left,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($leftLimit !== null && \is_finite($leftLimit)) {
                    return $rightScale * $rightDivergence;
                }
            }
        }

        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            $leftDivergence = $this->periodicPhaseDivergesAtBoundary(
                $node->left,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $rightDivergence = $this->periodicPhaseDivergesAtBoundary(
                $node->right,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($leftDivergence !== null && $rightDivergence !== null) {
                return $leftDivergence * $rightDivergence;
            }
            if ($leftDivergence !== null || $rightDivergence !== null) {
                $boundedNode = $leftDivergence !== null ? $node->right : $node->left;
                $boundedLimit = $this->continuousExpressionLimitAt(
                    $boundedNode,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                $unboundedSign = $leftDivergence ?? $rightDivergence;
                if (
                    $boundedLimit !== null
                    && \is_finite($boundedLimit)
                    && $boundedLimit !== 0.0
                ) {
                    return ($boundedLimit > 0.0 ? 1 : -1) * $unboundedSign;
                }
            }
        }

        return null;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveDecayingExponentialPeriodicEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof FunctionCallNode && !$this->containsVariable($right, $variable)) {
            $function = $left;
            $targetNode = $right;
        } elseif ($right instanceof FunctionCallNode && !$this->containsVariable($left, $variable)) {
            $function = $right;
            $targetNode = $left;
        } else {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $targetNode,
            $targetNode->span()->start,
        );
        if (
            !\in_array($function->name, ['sin', 'cos', 'tan'], true)
            || \count($function->arguments) !== 1
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
        ) {
            return null;
        }
        $phase = $this->unwrapGrouping($function->arguments[0]);
        $phaseScale = 1.0;
        if ($phase instanceof UnaryOperationNode && $phase->operator === UnaryOperator::Minus) {
            $phaseScale = -1.0;
            $phase = $this->unwrapGrouping($phase->operand);
        } elseif ($phase instanceof BinaryOperationNode && $phase->operator === BinaryOperator::Multiply) {
            foreach ([[$phase->left, $phase->right], [$phase->right, $phase->left]] as [$exponential, $scale]) {
                $scaleCoefficients = $this->extractPolynomial(
                    $extractor,
                    $scale,
                    $scale->span()->start,
                );
                $exponential = $this->unwrapGrouping($exponential);
                if (
                    $scaleCoefficients !== null
                    && \count($scaleCoefficients) === 1
                    && $exponential instanceof FunctionCallNode
                    && $exponential->name === 'exp'
                    && \count($exponential->arguments) === 1
                ) {
                    $phaseScale = $scaleCoefficients[0];
                    $phase = $exponential;
                    break;
                }
            }
        }
        if (
            !$phase instanceof FunctionCallNode
            || $phase->name !== 'exp'
            || \count($phase->arguments) !== 1
            || $phaseScale === 0.0
            || !\is_finite($phaseScale)
        ) {
            return null;
        }
        $exponentForm = $extractor->extractRationalForm($phase->arguments[0]);
        if (
            $exponentForm === null
            || !$this->rationalFormIsNonPositiveOnInterval(
                $exponentForm,
                $lowerBound,
                $upperBound,
                $options,
            )
        ) {
            return null;
        }
        $exponentMaximum = $this->rationalFormMaximumOnInterval(
            $exponentForm,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($exponentMaximum === null) {
            return null;
        }
        $maximumPhaseMagnitude = \abs($phaseScale) * \exp($exponentMaximum);
        if (!\is_finite($maximumPhaseMagnitude)) {
            return null;
        }

        $target = $targetCoefficients[0];
        $levelSpacing = match ([$function->name, $target]) {
            ['sin', 0.0], ['tan', 0.0] => \M_PI,
            ['cos', 1.0] => 2.0 * \M_PI,
            default => null,
        };
        if ($levelSpacing === null) {
            return null;
        }
        $levelCount = (int) \floor(
            ($maximumPhaseMagnitude / $levelSpacing)
                + (64.0 * \PHP_FLOAT_EPSILON * \max(1.0, $maximumPhaseMagnitude / $levelSpacing)),
        );
        if ($levelCount === 0) {
            return [];
        }
        if ($levelCount > self::MAX_PERIODIC_ROOTS) {
            return null;
        }

        $solutions = [];
        for ($level = 1; $level <= $levelCount; ++$level) {
            $targetExponent = \log(($level * $levelSpacing) / \abs($phaseScale));
            if (!\is_finite($targetExponent)) {
                continue;
            }
            $levelPolynomial = $this->addPolynomials(
                $exponentForm[0],
                $this->scaledPolynomial($exponentForm[1], $targetExponent),
                -1.0,
            );
            $roots = $this->solvePolynomialRootsInInterval(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($roots === null) {
                return null;
            }
            foreach ($roots as $root) {
                $residual = $residualAt($root->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $root->value,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    continue;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($root->value, \abs($residual), $root->iterations),
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /** @param array{list<float>, list<float>} $form */
    private function rationalFormIsNonPositiveOnInterval(
        array $form,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): bool {
        [$numerator, $denominator] = $form;
        if ($denominator === [0.0]) {
            return false;
        }
        $numeratorRoots = $this->solvePolynomialRootsInInterval(
            $numerator,
            $lowerBound,
            $upperBound,
            $options,
        );
        $denominatorRoots = $this->solvePolynomialRootsInInterval(
            $denominator,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($numeratorRoots === null || $denominatorRoots === null) {
            return false;
        }
        $points = [$lowerBound, $upperBound];
        foreach ([...$numeratorRoots, ...$denominatorRoots] as $root) {
            if ($root->value > $lowerBound && $root->value < $upperBound) {
                $points[] = $root->value;
            }
        }
        \sort($points, SORT_NUMERIC);
        $uniquePoints = [];
        foreach ($points as $point) {
            if ($uniquePoints === [] || $point !== $uniquePoints[\array_key_last($uniquePoints)]) {
                $uniquePoints[] = $point;
            }
        }
        $polynomialSolver = new PolynomialSolver();
        for ($index = 0, $last = \count($uniquePoints) - 1; $index < $last; ++$index) {
            $probe = ($uniquePoints[$index] / 2.0) + ($uniquePoints[$index + 1] / 2.0);
            if ($probe === $uniquePoints[$index] || $probe === $uniquePoints[$index + 1]) {
                return false;
            }
            $numeratorValue = $polynomialSolver->evaluatePolynomial($numerator, $probe);
            $denominatorValue = $polynomialSolver->evaluatePolynomial($denominator, $probe);
            if (
                $numeratorValue === null
                || $denominatorValue === null
                || $denominatorValue === 0.0
                || ($numeratorValue > 0.0 && $denominatorValue > 0.0)
                || ($numeratorValue < 0.0 && $denominatorValue < 0.0)
            ) {
                return false;
            }
        }

        return true;
    }

    /** @param array{list<float>, list<float>} $form */
    private function rationalFormMaximumOnInterval(
        array $form,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?float {
        [$numerator, $denominator] = $form;
        if (
            !$this->rationalFormIsNonPositiveOnInterval($form, $lowerBound, $upperBound, $options)
            || $denominator === [0.0]
        ) {
            return null;
        }
        $numeratorDerivative = $this->polynomialDerivative($numerator);
        $denominatorDerivative = $this->polynomialDerivative($denominator);
        $criticalPolynomial = $this->subtractScaledPolynomials(
            $this->multiplyPolynomials($numeratorDerivative, $denominator),
            $this->multiplyPolynomials($numerator, $denominatorDerivative),
            1.0,
        );
        if ($criticalPolynomial === null) {
            return null;
        }
        $criticalPoints = $criticalPolynomial === [0.0]
            ? []
            : $this->solvePolynomialRootsInInterval(
                $criticalPolynomial,
                $lowerBound,
                $upperBound,
                $options,
            );
        $denominatorRoots = $denominator === [1.0]
            ? []
            : $this->solvePolynomialRootsInInterval(
                $denominator,
                $lowerBound,
                $upperBound,
                $options,
            );
        if ($criticalPoints === null || $denominatorRoots === null) {
            return null;
        }
        $positions = [$lowerBound, $upperBound];
        foreach ([...$criticalPoints, ...$denominatorRoots] as $root) {
            $positions[] = $root->value;
        }
        $polynomialSolver = new PolynomialSolver();
        $maximum = null;
        foreach ($positions as $position) {
            $numeratorValue = $polynomialSolver->evaluatePolynomial($numerator, $position);
            $denominatorValue = $polynomialSolver->evaluatePolynomial($denominator, $position);
            if ($numeratorValue === null || $denominatorValue === null) {
                return null;
            }
            if ($denominatorValue === 0.0) {
                $limit = $this->rationalFormLimitAt($form, $position);
                if ($limit !== null) {
                    $maximum = $maximum === null ? $limit : \max($maximum, $limit);
                }
                continue;
            }
            $value = $numeratorValue / $denominatorValue;
            if (!\is_finite($value)) {
                return null;
            }
            $maximum = $maximum === null ? $value : \max($maximum, $value);
        }

        return $maximum;
    }

    /** @param array<string, int|float> $parameters */
    private function continuousExpressionLimitAt(
        Node $node,
        string $variable,
        float $position,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): ?float {
        $rational = $extractor->extractRationalForm($node);
        if ($rational !== null) {
            $limit = $this->rationalFormLimitAt($rational, $position);
            if ($limit !== null) {
                return $limit;
            }
            if (
                $this->polynomialRootMultiplicity($rational[0], $position)
                < $this->polynomialRootMultiplicity($rational[1], $position)
            ) {
                return match ($this->rationalFormSignNear($rational, $position, $direction)) {
                    1 => \INF,
                    -1 => -\INF,
                    default => null,
                };
            }

            return null;
        }
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $operandLimit = $this->continuousExpressionLimitAt(
                $node->operand,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );

            return $operandLimit === null || $node->operator === UnaryOperator::Plus
                ? $operandLimit
                : -$operandLimit;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array(
                $node->operator,
                [BinaryOperator::Add, BinaryOperator::Subtract, BinaryOperator::Multiply],
                true,
            )
        ) {
            $leftLimit = $this->continuousExpressionLimitAt(
                $node->left,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $rightLimit = $this->continuousExpressionLimitAt(
                $node->right,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if (
                $leftLimit !== null
                && $rightLimit !== null
                && \is_finite($leftLimit)
                && \is_finite($rightLimit)
            ) {
                $limit = match ($node->operator) {
                    BinaryOperator::Add => $leftLimit + $rightLimit,
                    BinaryOperator::Subtract => $leftLimit - $rightLimit,
                    BinaryOperator::Multiply => $leftLimit * $rightLimit,
                };

                return \is_finite($limit) ? $limit : null;
            }
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Power
        ) {
            $baseLimit = $this->continuousExpressionLimitAt(
                $node->left,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $exponent = $extractor->extract($node->right);
            if (
                $baseLimit !== null
                && $exponent !== null
                && \count($exponent) === 1
                && \is_finite($exponent[0])
                && !$this->containsVariable($node->right, $variable)
            ) {
                $power = $exponent[0];
                if (
                    $baseLimit === 0.0
                    && $power > 0.0
                    && (
                        \floor($power) === $power
                        || $this->expressionSignNearBoundary(
                            $node->left,
                            $variable,
                            $position,
                            $direction,
                            $extractor,
                            $evaluationOptions,
                            $parameters,
                        ) === 1
                    )
                    || $baseLimit > 0.0
                    || $baseLimit < 0.0 && \floor($power) === $power
                ) {
                    $limit = $baseLimit ** $power;

                    return \is_nan($limit) ? null : $limit;
                }
                if ($baseLimit === 0.0 && $power < 0.0) {
                    $baseSign = $this->expressionSignNearBoundary(
                        $node->left,
                        $variable,
                        $position,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    );
                    if (\floor($power) === $power) {
                        if ($baseSign === 1 || $baseSign === -1) {
                            return \fmod(\abs($power), 2.0) === 0.0
                                ? \INF
                                : ($baseSign > 0 ? \INF : -\INF);
                        }
                    } elseif ($baseSign === 1) {
                        return \INF;
                    }
                }
                if ($baseLimit === \INF && $power > 0.0) {
                    return \INF;
                }
                if ($baseLimit === \INF && $power < 0.0) {
                    return 0.0;
                }
                if ($baseLimit === -\INF && $power > 0.0 && \floor($power) === $power) {
                    return ((int) $power % 2) === 0 ? \INF : -\INF;
                }
                if ($baseLimit === -\INF && $power < 0.0 && \floor($power) === $power) {
                    return 0.0;
                }
            }
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $numeratorLimit = $this->continuousExpressionLimitAt(
                $node->left,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $denominatorLimit = $this->continuousExpressionLimitAt(
                $node->right,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if (
                $numeratorLimit !== null
                && \is_finite($numeratorLimit)
                && ($denominatorLimit === \INF || $denominatorLimit === -\INF)
            ) {
                return 0.0;
            }
            if (
                $numeratorLimit !== null
                && \is_finite($numeratorLimit)
                && $numeratorLimit !== 0.0
                && $denominatorLimit === 0.0
            ) {
                $denominatorSign = $this->expressionSignNearBoundary(
                    $node->right,
                    $variable,
                    $position,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if (
                    $denominatorSign === null
                    && $this->isStrictlyPositiveAwayFromPoint(
                        $node->right,
                        $position,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    )
                ) {
                    $denominatorSign = 1;
                }
                if ($denominatorSign !== null) {
                    return ($numeratorLimit > 0.0 ? 1 : -1) * $denominatorSign > 0 ? \INF : -\INF;
                }
            }
        }
        if ($node instanceof FunctionCallNode && $node->name === 'sqrt' && \count($node->arguments) === 1) {
            $argumentLimit = $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($argumentLimit !== null && $argumentLimit >= 0.0) {
                return \sqrt($argumentLimit);
            }
        }
        if ($node instanceof FunctionCallNode && $node->name === 'abs' && \count($node->arguments) === 1) {
            $argumentLimit = $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($argumentLimit !== null) {
                return \abs($argumentLimit);
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['exp', 'expm1'], true)
            && \count($node->arguments) === 1
        ) {
            $argumentLimit = $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($argumentLimit === -\INF) {
                return $node->name === 'exp' ? 0.0 : -1.0;
            }
            if ($argumentLimit === \INF) {
                return \INF;
            }
            if ($argumentLimit !== null) {
                return $node->name === 'exp' ? \exp($argumentLimit) : \expm1($argumentLimit);
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['ln', 'log2', 'log10'], true)
            && \count($node->arguments) === 1
        ) {
            $argument = $node->arguments[0];
            $argumentLimit = $this->continuousExpressionLimitAt(
                $argument,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if (
                $argumentLimit === 0.0
                && (
                    $this->expressionSignNearBoundary(
                        $argument,
                        $variable,
                        $position,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    ) === 1
                    || $this->isStrictlyPositiveAwayFromPoint(
                        $argument,
                        $position,
                        $variable,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    )
                )
            ) {
                return -\INF;
            }
            if ($argumentLimit === \INF) {
                return \INF;
            }
            if ($argumentLimit !== null && $argumentLimit > 0.0) {
                return match ($node->name) {
                    'ln' => \log($argumentLimit),
                    'log2' => \log($argumentLimit, 2.0),
                    'log10' => \log10($argumentLimit),
                };
            }
        }
        if ($node instanceof FunctionCallNode && $node->name === 'log' && \count($node->arguments) === 2) {
            $argument = $node->arguments[0];
            $argumentLimit = $this->continuousExpressionLimitAt(
                $argument,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $baseLimit = $this->continuousExpressionLimitAt(
                $node->arguments[1],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($baseLimit !== null && \is_finite($baseLimit) && $baseLimit > 0.0 && $baseLimit !== 1.0) {
                if ($argumentLimit === \INF) {
                    return $baseLimit > 1.0 ? \INF : -\INF;
                }
                if (
                    $argumentLimit === 0.0
                    && $this->expressionSignNearBoundary(
                        $argument,
                        $variable,
                        $position,
                        $direction,
                        $extractor,
                        $evaluationOptions,
                        $parameters,
                    ) === 1
                ) {
                    return $baseLimit > 1.0 ? -\INF : \INF;
                }
                if ($argumentLimit !== null && $argumentLimit > 0.0) {
                    return \log($argumentLimit, $baseLimit);
                }
            }
        }
        if (!$this->isLocallyContinuous($node, $position, $evaluationOptions, $parameters, $variable)) {
            return null;
        }
        try {
            return (float) $this->evaluateNode($node, [...$parameters, $variable => $position], $evaluationOptions);
        } catch (\Throwable) {
            return null;
        }
    }

    /** @param array<string, int|float> $parameters */
    private function expressionSignNearBoundary(
        Node $node,
        string $variable,
        float $position,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): ?int {
        $rational = $extractor->extractRationalForm($node);
        if ($rational !== null) {
            return $this->rationalFormSignNear($rational, $position, $direction);
        }
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $operandSign = $this->expressionSignNearBoundary(
                $node->operand,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );

            return $operandSign === null || $node->operator === UnaryOperator::Plus ? $operandSign : -$operandSign;
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $numeratorSign = $this->expressionSignNearBoundary(
                $node->left,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            $denominatorSign = $this->expressionSignNearBoundary(
                $node->right,
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
            if ($denominatorSign === null) {
                $denominatorLimit = $this->continuousExpressionLimitAt(
                    $node->right,
                    $variable,
                    $position,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
                if ($denominatorLimit === \INF || $denominatorLimit === -\INF) {
                    $denominatorSign = $denominatorLimit > 0.0 ? 1 : -1;
                }
            }
            if ($numeratorSign !== null && $denominatorSign !== null && $denominatorSign !== 0) {
                return $numeratorSign * $denominatorSign;
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \count($node->arguments) === 1
            && \in_array(
                $node->name,
                ['sin', 'sinh', 'tan', 'tanh', 'asinh', 'atan', 'asin', 'cbrt', 'erf'],
                true,
            )
            && $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            ) === 0.0
        ) {
            return $this->expressionSignNearBoundary(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
        }
        if ($node instanceof FunctionCallNode && $node->name === 'exp' && \count($node->arguments) === 1) {
            return $this->continuousExpressionLimitAt(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            ) !== null ? 1 : null;
        }
        if ($node instanceof FunctionCallNode && $node->name === 'sqrt' && \count($node->arguments) === 1) {
            return $this->expressionSignNearBoundary(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            ) === 1 ? 1 : null;
        }
        if (
            $node instanceof FunctionCallNode
            && (
                (\in_array($node->name, ['ln', 'log2', 'log10'], true) && \count($node->arguments) === 1)
                || ($node->name === 'log' && \count($node->arguments) === 2)
            )
        ) {
            $argumentForm = $extractor->extractRationalForm($node->arguments[0]);
            if ($argumentForm === null || $this->rationalFormLimitAt($argumentForm, $position) !== 1.0) {
                return null;
            }
            $differenceFromOne = [
                $this->addPolynomials($argumentForm[0], $argumentForm[1], -1.0),
                $argumentForm[1],
            ];

            $sign = $this->rationalFormSignNear($differenceFromOne, $position, $direction);
            if ($sign === null || $node->name !== 'log') {
                return $sign;
            }
            $baseNode = $node->arguments[1] ?? null;
            if (!$baseNode instanceof Node) {
                return null;
            }
            $base = $this->extractPolynomial(
                $extractor,
                $baseNode,
                $baseNode->span()->start,
            );
            if ($base === null || \count($base) !== 1 || $base[0] <= 0.0 || $base[0] === 1.0) {
                return null;
            }

            return $base[0] > 1.0 ? $sign : -$sign;
        }
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'log1p'
            && \count($node->arguments) === 1
        ) {
            return $this->expressionSignNearBoundary(
                $node->arguments[0],
                $variable,
                $position,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function expressionDiffersFromConstantNearBoundary(
        Node $node,
        float $constant,
        string $variable,
        float $boundary,
        int $direction,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
        array $parameters,
    ): bool {
        $rational = $extractor->extractRationalForm($node);
        if ($rational !== null) {
            $difference = [
                $this->addPolynomials(
                    $rational[0],
                    $this->scalePolynomialCoefficients($rational[1], $constant) ?? [0.0],
                    -1.0,
                ),
                $rational[1],
            ];

            return $this->rationalFormSignNear($difference, $boundary, $direction) !== null;
        }
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            return $this->expressionDiffersFromConstantNearBoundary(
                $node->operand,
                $node->operator === UnaryOperator::Minus ? -$constant : $constant,
                $variable,
                $boundary,
                $direction,
                $extractor,
                $evaluationOptions,
                $parameters,
            );
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $leftConstant = $this->rationalFormConstant($extractor->extractRationalForm($node->left));
            $rightConstant = $this->rationalFormConstant($extractor->extractRationalForm($node->right));
            if ($leftConstant !== null) {
                $rightTarget = $node->operator === BinaryOperator::Add
                    ? $constant - $leftConstant
                    : $leftConstant - $constant;

                return $this->expressionDiffersFromConstantNearBoundary(
                    $node->right,
                    $rightTarget,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
            }
            if ($rightConstant !== null) {
                $leftTarget = $node->operator === BinaryOperator::Add
                    ? $constant - $rightConstant
                    : $constant + $rightConstant;

                return $this->expressionDiffersFromConstantNearBoundary(
                    $node->left,
                    $leftTarget,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
            }
        }
        if ($node instanceof FunctionCallNode && \count($node->arguments) === 1) {
            $argument = $node->arguments[0];
            if ($node->name === 'sqrt' && $constant >= 0.0) {
                return $this->expressionDiffersFromConstantNearBoundary(
                    $argument,
                    $constant * $constant,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                );
            }
            if ($node->name === 'exp' && $constant === 0.0) {
                return $this->continuousExpressionLimitAt(
                    $argument,
                    $variable,
                    $boundary,
                    $direction,
                    $extractor,
                    $evaluationOptions,
                    $parameters,
                ) === -\INF;
            }
        }

        return false;
    }

    /** @param array{list<float>, list<float>}|null $rational */
    private function rationalFormConstant(?array $rational): ?float
    {
        if ($rational === null || \count($rational[0]) !== 1 || \count($rational[1]) !== 1 || $rational[1][0] === 0.0) {
            return null;
        }
        $constant = $rational[0][0] / $rational[1][0];

        return \is_finite($constant) ? $constant : null;
    }

    /** @param array{list<float>, list<float>}|null $rational */
    private function rationalFormConstantValue(?array $rational): ?float
    {
        if ($rational === null || $rational[1] === []) {
            return null;
        }
        $numerator = $this->trimPolynomialCoefficients($rational[0]);
        $denominator = $this->trimPolynomialCoefficients($rational[1]);
        if ($denominator === [] || ($denominator === [0.0])) {
            return null;
        }
        if ($numerator === [0.0]) {
            return 0.0;
        }

        $degree = \max(\count($numerator), \count($denominator));
        for ($index = 0; $index < $degree; ++$index) {
            $numeratorCoefficient = $numerator[$index] ?? 0.0;
            $denominatorCoefficient = $denominator[$index] ?? 0.0;
            if ($denominatorCoefficient === 0.0) {
                continue;
            }
            $constant = $numeratorCoefficient / $denominatorCoefficient;
            if (!\is_finite($constant)) {
                return null;
            }
            for ($coefficientIndex = 0; $coefficientIndex < $degree; ++$coefficientIndex) {
                $expectedNumerator = $constant * ($denominator[$coefficientIndex] ?? 0.0);
                if (($numerator[$coefficientIndex] ?? 0.0) !== $expectedNumerator) {
                    return null;
                }
            }

            return $constant;
        }

        return null;
    }

    /** @param list<float> $coefficients
     *  @return list<float>
     */
    private function trimPolynomialCoefficients(array $coefficients): array
    {
        while (\count($coefficients) > 1 && $coefficients[\count($coefficients) - 1] === 0.0) {
            \array_pop($coefficients);
        }

        return $coefficients;
    }

    private function isTrigonometricPole(string $function, float $argument): bool
    {
        $periodicOffset = match ($function) {
            'tan', 'sec' => 0.5,
            'csc', 'cot' => 0.0,
            default => null,
        };
        if ($periodicOffset === null) {
            return false;
        }
        $periodIndex = ($argument / \M_PI) - $periodicOffset;
        if (!\is_finite($periodIndex)) {
            return false;
        }
        $tolerance = 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($periodIndex));
        if ($tolerance > 1.0E-7) {
            return false;
        }

        return \abs($periodIndex - \round($periodIndex)) <= $tolerance;
    }

    private function throwIfPeriodicLogarithmArgumentHasPole(
        FunctionCallNode $logarithm,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        if (!\in_array($logarithm->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true)) {
            return;
        }
        if (
            ($logarithm->name === 'log' && \count($logarithm->arguments) !== 2)
            || ($logarithm->name !== 'log' && \count($logarithm->arguments) !== 1)
        ) {
            return;
        }
        if ($logarithm->name === 'log') {
            $base = $this->extractPolynomial(
                $extractor,
                $logarithm->arguments[1],
                $logarithm->arguments[1]->span()->start,
            );
            if ($base === null || \count($base) > 1) {
                $this->throwIfPeriodicVariableBaseLogarithmHasPole(
                    $logarithm->arguments[0],
                    $logarithm->arguments[1],
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                return;
            } elseif (
                !\is_finite($base[0])
                || $base[0] <= 0.0
                || $base[0] === 1.0
            ) {
                return;
            }
        }
        $argument = $logarithm->arguments[0];
        $signArgument = $argument;
        if ($logarithm->name === 'log1p') {
            $span = $argument->span();
            $operatorSpan = new SourceSpan($span->end, $span->end);
            $signArgument = new BinaryOperationNode(
                BinaryOperator::Add,
                $argument,
                new NumberNode(1.0, '1', $operatorSpan),
                $operatorSpan,
            );
        }
        try {
            $form = $extractor->extractRationalForm($signArgument);
        } catch (EvaluationException) {
            return;
        }
        if ($form === null) {
            $this->throwIfPeriodicGammaLogarithmArgumentHasPole(
                $signArgument,
                $extractor,
                $lowerBound,
                $upperBound,
                $options,
            );
            $phase = $this->extractSquaredFunctionPhase($signArgument, $extractor);
            if ($phase !== null) {
                $this->throwIfPeriodicSmoothLogarithmArgumentHasZero(
                    $phase,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
            }

            return;
        }
        [$numerator, $denominator] = $form;
        $numeratorRoots = $this->solvePolynomialRootsInInterval(
            $numerator,
            $lowerBound,
            $upperBound,
            $options,
        );
        $denominatorRoots = $this->solvePolynomialRootsInInterval(
            $denominator,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($numeratorRoots === null || $denominatorRoots === null) {
            return;
        }

        $boundaries = [];
        foreach ([...$numeratorRoots, ...$denominatorRoots] as $root) {
            $boundaries[] = $root->value;
        }
        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));
        foreach ($boundaries as $index => $boundary) {
            $numeratorMultiplicity = $this->polynomialRootMultiplicity($numerator, $boundary);
            $denominatorMultiplicity = $this->polynomialRootMultiplicity($denominator, $boundary);
            if ($numeratorMultiplicity === $denominatorMultiplicity) {
                continue;
            }

            $left = $index === 0 ? $lowerBound : $boundaries[$index - 1];
            $right = $boundaries[$index + 1] ?? $upperBound;
            foreach ([[$left, $boundary], [$boundary, $right]] as [$intervalLeft, $intervalRight]) {
                if ($intervalLeft >= $intervalRight) {
                    continue;
                }
                if (
                    $this->rationalExpressionSignBetweenPoints(
                        $signArgument,
                        $extractor,
                        $intervalLeft,
                        $intervalRight,
                        $lowerBound,
                        $upperBound,
                        $options,
                    ) === 1
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A periodic equation with a rational logarithm argument has infinitely '
                            . 'many roots accumulating at a logarithm singularity.',
                    );
                }
            }
        }
    }

    private function throwIfPeriodicGammaLogarithmArgumentHasPole(
        Node $argument,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        $gammaArguments = $this->gammaLogarithmArguments($argument);
        foreach ($gammaArguments as [$gammaArgument, $positiveNearPole]) {
            $form = $extractor->extractRationalForm($gammaArgument);
            if ($form === null) {
                continue;
            }
            [$numerator, $denominator] = $form;
            for ($pole = -171; $pole <= 0; ++$pole) {
                $polePolynomial = $this->addPolynomials(
                    $numerator,
                    $denominator,
                    -(float) $pole,
                );
                if ($polePolynomial === [0.0]) {
                    continue;
                }
                $roots = $this->solvePolynomialRootsInInterval(
                    $polePolynomial,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($roots === null) {
                    continue;
                }
                foreach ($roots as $root) {
                    $argumentOrder = $this->polynomialRootMultiplicity(
                        $polePolynomial,
                        $root->value,
                    ) - $this->polynomialRootMultiplicity($denominator, $root->value);
                    if ($argumentOrder <= 0) {
                        continue;
                    }
                    if (
                        $positiveNearPole
                        || $argumentOrder % 2 === 1
                    ) {
                        throw new InfiniteRootAccumulationException(
                            'A periodic equation with a logarithmic Gamma-family argument has '
                                . 'infinitely many roots accumulating at a Gamma pole.',
                        );
                    }
                }
            }
        }
    }

    /** @return list<array{Node, bool}> */
    private function gammaLogarithmArguments(Node $node): array
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        if (
            $node->name === 'lgamma'
            && \count($node->arguments) === 1
        ) {
            return [[$node->arguments[0], true]];
        }
        if (
            $node->name === 'abs'
            && \count($node->arguments) === 1
        ) {
            $magnitude = $this->unwrapGrouping($node->arguments[0]);
            if (
                $magnitude instanceof FunctionCallNode
                && $magnitude->name === 'gamma'
                && \count($magnitude->arguments) === 1
            ) {
                return [[$magnitude->arguments[0], true]];
            }
        }
        if ($node->name === 'gamma' && \count($node->arguments) === 1) {
            return [[$node->arguments[0], false]];
        }

        return [];
    }

    /** @return array{list<float>, int, float, float}|null */
    private function extractSquaredFunctionPhase(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$constantNode, $other]) {
                $constant = $this->extractPolynomial(
                    $extractor,
                    $constantNode,
                    $constantNode->span()->start,
                );
                if ($constant !== null && \count($constant) === 1 && $constant[0] > 0.0) {
                    return $this->extractSquaredFunctionPhase($other, $extractor);
                }
            }
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $denominator = $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            );
            if ($denominator !== null && \count($denominator) === 1 && $denominator[0] > 0.0) {
                return $this->extractSquaredFunctionPhase($node->left, $extractor);
            }
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Add
        ) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$constantNode, $other]) {
                if (
                    $this->extractPolynomial(
                        $extractor,
                        $constantNode,
                        $constantNode->span()->start,
                    ) === [0.0]
                ) {
                    return $this->extractSquaredFunctionPhase($other, $extractor);
                }
            }
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Subtract
            && $this->extractPolynomial(
                $extractor,
                $node->left,
                $node->left->span()->start,
            ) === [1.0]
        ) {
            $functionNode = $this->extractSquareFunctionNode($node->right, $extractor);
            if (
                $functionNode instanceof FunctionCallNode
                && \in_array($functionNode->name, ['sin', 'cos', 'tan', 'cot'], true)
            ) {
                return $this->squareFunctionLevelPhase($functionNode, 1.0, $extractor);
            }
        }

        $functionNode = $this->extractSquareFunctionNode($node, $extractor);
        if ($functionNode === null) {
            return null;
        }

        return $this->squareFunctionLevelPhase($functionNode, 0.0, $extractor);
    }

    private function extractSquareFunctionNode(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?FunctionCallNode {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }

        $functionNode = null;
        if (
            $node->operator === BinaryOperator::Power
            && $this->extractPolynomial(
                $extractor,
                $node->right,
                $node->right->span()->start,
            ) === [2.0]
        ) {
            $functionNode = $node->left;
        } elseif (
            $node->operator === BinaryOperator::Multiply
            && $this->sameExpression($node->left, $node->right)
        ) {
            $functionNode = $node->left;
        }
        $functionNode = $functionNode === null ? null : $this->unwrapGrouping($functionNode);
        if (
            !$functionNode instanceof FunctionCallNode
            || !\in_array(
                $functionNode->name,
                ['sin', 'cos', 'tan', 'cot', 'sinh', 'tanh'],
                true,
            )
            || \count($functionNode->arguments) !== 1
        ) {
            return null;
        }

        return $functionNode;
    }

    /** @return array{list<float>, int, float, float}|null */
    private function squareFunctionLevelPhase(
        FunctionCallNode $functionNode,
        float $level,
        PolynomialExtractor $extractor,
    ): ?array {
        $coefficients = $this->extractPolynomial(
            $extractor,
            $functionNode->arguments[0],
            $functionNode->arguments[0]->span()->start,
        );
        if ($coefficients === null || \count($coefficients) <= 1) {
            return null;
        }

        if ($level === 1.0) {
            return match ($functionNode->name) {
                'sin' => [$coefficients, 2, \M_PI / 2.0, \M_PI],
                'cos' => [$coefficients, 2, 0.0, \M_PI],
                'tan', 'cot' => [$coefficients, 1, \M_PI / 4.0, \M_PI / 2.0],
                default => null,
            };
        }

        return [
            $coefficients,
            2,
            \in_array($functionNode->name, ['cos', 'cot'], true) ? \M_PI / 2.0 : 0.0,
            \in_array($functionNode->name, ['sinh', 'tanh'], true) ? 0.0 : \M_PI,
        ];
    }

    /**
     * @param array{list<float>, int, float, float} $phase
     */
    private function throwIfPeriodicSmoothLogarithmArgumentHasZero(
        array $phase,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        [$coefficients, , $phaseOffset, $phasePeriod] = $phase;
        $phaseLevels = [$phaseOffset];
        if ($phasePeriod > 0.0) {
            $phaseRange = $this->polynomialRange(
                $coefficients,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($phaseRange === null) {
                return;
            }
            $firstLevel = \ceil(($phaseRange[0] - $phaseOffset) / $phasePeriod);
            $lastLevel = \floor(($phaseRange[1] - $phaseOffset) / $phasePeriod);
            if ($firstLevel > $lastLevel) {
                return;
            }
            if (
                !\is_finite($firstLevel)
                || !\is_finite($lastLevel)
                || \abs($firstLevel) > 4_503_599_627_370_496.0
                || \abs($lastLevel) > 4_503_599_627_370_496.0
                || $lastLevel - $firstLevel + 1.0 > self::MAX_PERIODIC_ROOTS
            ) {
                throw new RootSearchLimitException(
                    \sprintf(
                        'The interval requires checking more than %d periodic logarithm levels.',
                        self::MAX_PERIODIC_ROOTS,
                    ),
                );
            }

            $phaseLevels = [];
            for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
                $phaseLevels[] = $phaseOffset + ($level * $phasePeriod);
            }
        }

        foreach ($phaseLevels as $phaseLevel) {
            $roots = $this->solvePolynomialRootsInInterval(
                $this->addPolynomials($coefficients, [$phaseLevel], -1.0),
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($roots !== null && $roots !== []) {
                throw new InfiniteRootAccumulationException(
                    'A periodic equation with a smooth logarithm argument approaching zero '
                        . 'has infinitely many roots accumulating at a logarithmic singularity.',
                );
            }
        }
    }

    private function throwIfPeriodicVariableBaseLogarithmHasPole(
        Node $argument,
        Node $base,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        $one = static function (Node $node): Node {
            $span = $node->span();
            $operatorSpan = new SourceSpan($span->end, $span->end);

            return new BinaryOperationNode(
                BinaryOperator::Subtract,
                $node,
                new NumberNode(1.0, '1', $operatorSpan),
                $operatorSpan,
            );
        };
        try {
            $argumentForm = $extractor->extractRationalForm($argument);
            $baseForm = $extractor->extractRationalForm($base);
            $argumentMinusOne = $extractor->extractRationalForm($one($argument));
            $baseMinusOne = $extractor->extractRationalForm($one($base));
        } catch (EvaluationException) {
            return;
        }
        if ($baseForm === null) {
            $basePhase = $this->extractVariableLogarithmBasePhase($base, $extractor);
            if ($basePhase !== null) {
                $this->throwIfPeriodicSmoothBaseLogarithmHasPole(
                    $argument,
                    $basePhase[0],
                    $basePhase[1],
                    $basePhase[2],
                    $basePhase[3],
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
            }

            return;
        }
        if (
            $argumentForm === null
            || $argumentMinusOne === null
            || $baseMinusOne === null
            || $argumentMinusOne[0] === [0.0]
            || $baseMinusOne[0] === [0.0]
        ) {
            return;
        }

        $forms = [$argumentForm, $baseForm, $argumentMinusOne, $baseMinusOne];
        $boundaries = [];
        foreach ($forms as $form) {
            foreach ($form as $polynomial) {
                $roots = $this->solvePolynomialRootsInInterval(
                    $polynomial,
                    $lowerBound,
                    $upperBound,
                    $options,
                );
                if ($roots === null) {
                    return;
                }
                foreach ($roots as $root) {
                    $boundaries[] = $root->value;
                }
            }
        }
        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));

        foreach ($boundaries as $index => $position) {
            $argumentOrder = $this->polynomialRootMultiplicity(
                $argumentForm[0],
                $position,
            ) - $this->polynomialRootMultiplicity($argumentForm[1], $position);
            $baseOrder = $this->polynomialRootMultiplicity($baseForm[0], $position)
                - $this->polynomialRootMultiplicity($baseForm[1], $position);
            $argumentMinusOneOrder = $this->polynomialRootMultiplicity(
                $argumentMinusOne[0],
                $position,
            ) - $this->polynomialRootMultiplicity($argumentMinusOne[1], $position);
            $baseMinusOneOrder = $this->polynomialRootMultiplicity(
                $baseMinusOne[0],
                $position,
            ) - $this->polynomialRootMultiplicity($baseMinusOne[1], $position);

            $phaseDiverges = $baseOrder === 0
                && $baseMinusOneOrder > 0
                && ($argumentMinusOneOrder <= 0
                    || $argumentMinusOneOrder < $baseMinusOneOrder);
            $phaseDiverges = $phaseDiverges
                || ($baseOrder === 0 && $baseMinusOneOrder === 0 && $argumentOrder !== 0);
            if (!$phaseDiverges) {
                continue;
            }

            $left = $index === 0 ? $lowerBound : $boundaries[$index - 1];
            $right = $boundaries[$index + 1] ?? $upperBound;
            foreach ([[$left, $position], [$position, $right]] as [$intervalLeft, $intervalRight]) {
                if (
                    $intervalLeft >= $intervalRight
                    || $this->rationalExpressionSignBetweenPoints(
                        $argument,
                        $extractor,
                        $intervalLeft,
                        $intervalRight,
                        $lowerBound,
                        $upperBound,
                        $options,
                    ) !== 1
                    || $this->rationalExpressionSignBetweenPoints(
                        $base,
                        $extractor,
                        $intervalLeft,
                        $intervalRight,
                        $lowerBound,
                        $upperBound,
                        $options,
                    ) !== 1
                ) {
                    continue;
                }

                throw new InfiniteRootAccumulationException(
                    'A periodic equation with a variable-base logarithm has infinitely many '
                        . 'roots accumulating at a logarithmic singularity.',
                );
            }
        }
    }

    /** @return array{list<float>, int, float, float}|null */
    private function extractVariableLogarithmBasePhase(
        Node $base,
        PolynomialExtractor $extractor,
    ): ?array {
        $base = $this->unwrapGrouping($base);
        if (
            $base instanceof BinaryOperationNode
            && $base->operator === BinaryOperator::Add
        ) {
            $constant = $this->extractPolynomial(
                $extractor,
                $base->left,
                $base->left->span()->start,
            );
            $square = $base->right;
            if ($constant !== [1.0]) {
                $constant = $this->extractPolynomial(
                    $extractor,
                    $base->right,
                    $base->right->span()->start,
                );
                $square = $base->left;
            }
            if ($constant === [1.0]) {
                $phase = $this->extractSquaredFunctionPhase($square, $extractor);
                if ($phase !== null) {
                    return $phase;
                }
            }
        }
        $orderFactor = 1;
        if (
            $base instanceof FunctionCallNode
            && $base->name === 'sqrt'
            && \count($base->arguments) === 1
        ) {
            $radicand = $this->extractPolynomial(
                $extractor,
                $base->arguments[0],
                $base->arguments[0]->span()->start,
            );
            if ($radicand === null) {
                return $this->extractVariableLogarithmBasePhase(
                    $base->arguments[0],
                    $extractor,
                );
            }
            $phase = $this->addPolynomials($radicand, [1.0], -1.0);

            return \count($phase) > 1 ? [$phase, 1, 0.0, 0.0] : null;
        }
        if (
            $base instanceof FunctionCallNode
            && \in_array($base->name, ['sin', 'cos'], true)
            && \count($base->arguments) === 1
        ) {
            $coefficients = $this->extractPolynomial(
                $extractor,
                $base->arguments[0],
                $base->arguments[0]->span()->start,
            );

            return $coefficients !== null && \count($coefficients) > 1
                ? [$coefficients, 2, $base->name === 'sin' ? \M_PI / 2.0 : 0.0, 2.0 * \M_PI]
                : null;
        }
        if (
            $base instanceof FunctionCallNode
            && $base->name === 'exp'
            && \count($base->arguments) === 1
        ) {
            $exponent = $base->arguments[0];
        } elseif (
            $base instanceof BinaryOperationNode
            && $base->operator === BinaryOperator::Power
        ) {
            $constantBase = $this->extractPolynomial(
                $extractor,
                $base->left,
                $base->left->span()->start,
            );
            if (
                $constantBase === null
                || \count($constantBase) !== 1
                || !\is_finite($constantBase[0])
                || $constantBase[0] <= 0.0
                || $constantBase[0] === 1.0
            ) {
                return null;
            }
            $exponent = $base->right;
        } elseif (
            $base instanceof FunctionCallNode
            && \in_array($base->name, ['cosh', 'sech'], true)
            && \count($base->arguments) === 1
        ) {
            $exponent = $base->arguments[0];
            $orderFactor = 2;
        } else {
            return null;
        }

        $coefficients = $this->extractPolynomial(
            $extractor,
            $exponent,
            $exponent->span()->start,
        );

        return $coefficients !== null && \count($coefficients) > 1
            ? [$coefficients, $orderFactor, 0.0, 0.0]
            : null;
    }

    /**
     * @param list<float> $basePhase
     */
    private function throwIfPeriodicSmoothBaseLogarithmHasPole(
        Node $argument,
        array $basePhase,
        int $baseOrderFactor,
        float $phaseOffset,
        float $phasePeriod,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        $one = static function (Node $node): Node {
            $span = $node->span();
            $operatorSpan = new SourceSpan($span->end, $span->end);

            return new BinaryOperationNode(
                BinaryOperator::Subtract,
                $node,
                new NumberNode(1.0, '1', $operatorSpan),
                $operatorSpan,
            );
        };
        try {
            $argumentForm = $extractor->extractRationalForm($argument);
            $argumentMinusOne = $extractor->extractRationalForm($one($argument));
        } catch (EvaluationException) {
            return;
        }
        if (
            $argumentForm === null
            || $argumentMinusOne === null
            || $argumentMinusOne[0] === [0.0]
        ) {
            return;
        }

        $phaseLevels = [$phaseOffset];
        if ($phasePeriod > 0.0) {
            $phaseRange = $this->polynomialRange(
                $basePhase,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($phaseRange === null) {
                return;
            }
            $firstLevel = \ceil(($phaseRange[0] - $phaseOffset) / $phasePeriod);
            $lastLevel = \floor(($phaseRange[1] - $phaseOffset) / $phasePeriod);
            if ($firstLevel > $lastLevel) {
                return;
            }
            if (
                !\is_finite($firstLevel)
                || !\is_finite($lastLevel)
                || \abs($firstLevel) > 4_503_599_627_370_496.0
                || \abs($lastLevel) > 4_503_599_627_370_496.0
                || $lastLevel - $firstLevel + 1.0 > self::MAX_PERIODIC_ROOTS
            ) {
                throw new RootSearchLimitException(
                    \sprintf(
                        'The interval requires checking more than %d periodic logarithm-base levels.',
                        self::MAX_PERIODIC_ROOTS,
                    ),
                );
            }
            $phaseLevels = [];
            for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
                $phaseLevels[] = $phaseOffset + ($level * $phasePeriod);
            }
        }

        $phaseRoots = [];
        $phaseRootOrders = [];
        foreach ($phaseLevels as $phaseLevel) {
            $phasePolynomial = $this->addPolynomials($basePhase, [$phaseLevel], -1.0);
            $roots = $this->solvePolynomialRootsInInterval(
                $phasePolynomial,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($roots === null) {
                return;
            }
            foreach ($roots as $root) {
                $phaseRoots[] = $root;
                $phaseRootOrders[$this->samplePositionKey($root->value)] =
                    $baseOrderFactor * $this->polynomialRootMultiplicity(
                        $phasePolynomial,
                        $root->value,
                    );
            }
        }
        if ($phaseRoots === []) {
            return;
        }

        $argumentNumeratorRoots = $this->solvePolynomialRootsInInterval(
            $argumentForm[0],
            $lowerBound,
            $upperBound,
            $options,
        );
        $argumentDenominatorRoots = $this->solvePolynomialRootsInInterval(
            $argumentForm[1],
            $lowerBound,
            $upperBound,
            $options,
        );
        $argumentMinusOneNumeratorRoots = $this->solvePolynomialRootsInInterval(
            $argumentMinusOne[0],
            $lowerBound,
            $upperBound,
            $options,
        );
        $argumentMinusOneDenominatorRoots = $this->solvePolynomialRootsInInterval(
            $argumentMinusOne[1],
            $lowerBound,
            $upperBound,
            $options,
        );
        if (
            $argumentNumeratorRoots === null
            || $argumentDenominatorRoots === null
            || $argumentMinusOneNumeratorRoots === null
            || $argumentMinusOneDenominatorRoots === null
        ) {
            return;
        }

        $boundaries = [];
        foreach (
            [
                ...$phaseRoots,
                ...$argumentNumeratorRoots,
                ...$argumentDenominatorRoots,
                ...$argumentMinusOneNumeratorRoots,
                ...$argumentMinusOneDenominatorRoots,
            ] as $root
        ) {
            $boundaries[] = $root->value;
        }
        \sort($boundaries, SORT_NUMERIC);
        $boundaries = \array_values(\array_unique($boundaries, SORT_REGULAR));

        foreach ($phaseRoots as $phaseRoot) {
            $position = $phaseRoot->value;
            $baseOrder = $phaseRootOrders[$this->samplePositionKey($position)];
            $argumentOrder = $this->polynomialRootMultiplicity(
                $argumentMinusOne[0],
                $position,
            ) - $this->polynomialRootMultiplicity($argumentMinusOne[1], $position);
            if ($argumentOrder > 0 && $argumentOrder >= $baseOrder) {
                continue;
            }

            $index = \array_search($position, $boundaries, true);
            if ($index === false) {
                continue;
            }
            $left = $index === 0 ? $lowerBound : $boundaries[$index - 1];
            $right = $boundaries[$index + 1] ?? $upperBound;
            foreach ([[$left, $position], [$position, $right]] as [$intervalLeft, $intervalRight]) {
                if (
                    $intervalLeft < $intervalRight
                    && $this->rationalExpressionSignBetweenPoints(
                        $argument,
                        $extractor,
                        $intervalLeft,
                        $intervalRight,
                        $lowerBound,
                        $upperBound,
                        $options,
                    ) === 1
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A periodic equation with a smooth logarithm base approaching one '
                            . 'has infinitely many roots accumulating at the base singularity.',
                    );
                }
            }
        }
    }

    /**
     * @param list<float> $polynomial
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialRootsInInterval(
        array $polynomial,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): ?array {
        if (\count($polynomial) === 1) {
            return [];
        }

        $polynomialSolver = new PolynomialSolver();

        return $polynomialSolver->solve(
            $polynomial,
            $lowerBound,
            $upperBound,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                $polynomial,
                $value,
            ),
            $options,
        );
    }

    /** @param list<float> $polynomial */
    private function polynomialRootMultiplicity(array $polynomial, float $root): int
    {
        if ($polynomial === [0.0]) {
            return \PHP_INT_MAX;
        }

        $multiplicity = 0;
        while (\count($polynomial) > 1) {
            $degree = \count($polynomial) - 1;
            $quotient = \array_fill(0, $degree, 0.0);
            $quotient[$degree - 1] = $polynomial[$degree];
            for ($index = $degree - 1; $index > 0; --$index) {
                $quotient[$index - 1] = $polynomial[$index] + ($root * $quotient[$index]);
            }
            $remainder = $polynomial[0] + ($root * $quotient[0]);
            $scale = 0.0;
            $power = 1.0;
            foreach ($polynomial as $coefficient) {
                $scale += \abs($coefficient * $power);
                $power *= \abs($root);
            }
            if (
                !\is_finite($scale)
                || \abs($remainder) > 128.0 * \PHP_FLOAT_EPSILON * \max($scale, \PHP_FLOAT_MIN)
            ) {
                break;
            }
            while (\count($quotient) > 1 && $quotient[\array_key_last($quotient)] === 0.0) {
                \array_pop($quotient);
            }
            $polynomial = $quotient;
            ++$multiplicity;
        }

        return $multiplicity;
    }

    /**
     * Enumerate the exact phase levels of sinc and sincpi when their argument
     * is affine. The zero phase is excluded because both functions equal one
     * there.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineSincZeroEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $isQuotient = false;
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['sinc', 'sincpi'], true)
            && !$this->containsVariable($right, $variable)
        ) {
            $function = $left;
            $constant = $right;
        } elseif (
            !$this->containsVariable($right, $variable)
            && ($quotient = $this->sincQuotientFunction($left, $extractor)) !== null
        ) {
            $function = $quotient;
            $constant = $right;
            $isQuotient = true;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['sinc', 'sincpi'], true)
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $right;
            $constant = $left;
        } elseif (
            !$this->containsVariable($left, $variable)
            && ($quotient = $this->sincQuotientFunction($right, $extractor)) !== null
        ) {
            $function = $quotient;
            $constant = $left;
            $isQuotient = true;
        } else {
            return null;
        }
        if (\count($function->arguments) !== 1) {
            return null;
        }

        $target = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        $argument = $this->extractPolynomial(
            $extractor,
            $function->arguments[0],
            $function->arguments[0]->span()->start,
        );
        if (
            $target === null
            || \count($target) !== 1
            || $argument === null
            || \count($argument) < 2
        ) {
            return null;
        }

        $targetValue = $target[0];
        if (!\is_finite($targetValue) || \abs($targetValue) > 1.0) {
            return [];
        }
        if ($isQuotient && $targetValue === 1.0) {
            return [];
        }

        $phaseUnit = $function->name === 'sincpi' ? 1.0 : \M_PI;
        if ($targetValue === 0.0) {
            return $this->solvePolynomialSincZeroLevels(
                $argument,
                $phaseUnit,
                $lowerBound,
                $upperBound,
                $options,
                $residualAt,
                $candidateScaleAt,
            );
        }
        $argumentRange = $this->polynomialRange(
            $argument,
            $lowerBound,
            $upperBound,
            $options,
        );
        if ($argumentRange === null) {
            return null;
        }
        [$argumentLower, $argumentUpper] = $argumentRange;
        $phaseTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        if (
            \abs($argumentLower / $phaseUnit) > 4_503_599_627_370_496.0
            || \abs($argumentUpper / $phaseUnit) > 4_503_599_627_370_496.0
        ) {
            return null;
        }
        $firstLevel = \ceil(($argumentLower - $phaseTolerance) / $phaseUnit);
        $lastLevel = \floor(($argumentUpper + $phaseTolerance) / $phaseUnit);
        if ($targetValue === 0.0 && $lastLevel < $firstLevel) {
            return [];
        }
        $firstLobe = (int) \floor($argumentLower / $phaseUnit);
        $lastLobe = (int) \ceil($argumentUpper / $phaseUnit);
        if (
            ($targetValue === 0.0 && $lastLevel - $firstLevel + 1.0 > self::MAX_PERIODIC_ROOTS)
            || ($targetValue !== 0.0 && $lastLobe - $firstLobe + 1 > self::MAX_PERIODIC_ROOTS)
            || \abs($firstLevel) > 4_503_599_627_370_496.0
            || \abs($lastLevel) > 4_503_599_627_370_496.0
        ) {
            return null;
        }

        $positionTolerance = $options->positionTolerance($lowerBound, $upperBound);
        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $rejectedCandidate = false;
        $candidateCount = 0;
        $addCandidate = function (float $phase) use (
            &$solutions,
            &$rejectedCandidate,
            &$candidateCount,
            $argument,
            $polynomialSolver,
            $lowerBound,
            $upperBound,
            $positionTolerance,
            $residualAt,
            $candidateScaleAt,
            $options,
        ): void {
            /** @var list<array{float, int}> $phaseCandidates */
            $phaseCandidates = [];
            if (\count($argument) === 2) {
                if ($argument[1] === 0.0) {
                    return;
                }
                $phaseCandidates[] = [
                    ($phase - $argument[0]) / $argument[1],
                    0,
                ];
            } else {
                $levelCoefficients = $argument;
                $levelCoefficients[0] -= $phase;
                if (!\is_finite($levelCoefficients[0])) {
                    $rejectedCandidate = true;
                    return;
                }
                $levelRoots = $polynomialSolver->solve(
                    $levelCoefficients,
                    $lowerBound,
                    $upperBound,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                        $levelCoefficients,
                        $value,
                    ),
                    $options,
                    fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                        $levelCoefficients,
                        $value,
                    ),
                );
                if ($levelRoots === null) {
                    $rejectedCandidate = true;
                    return;
                }
                foreach ($levelRoots as $levelRoot) {
                    $phaseCandidates[] = [$levelRoot->value, $levelRoot->iterations];
                }
            }

            foreach ($phaseCandidates as [$candidate, $iterations]) {
                if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                    $rejectedCandidate = true;
                    return;
                }
                if (
                    !\is_finite($candidate)
                    || $candidate < $lowerBound - $positionTolerance
                    || $candidate > $upperBound + $positionTolerance
                ) {
                    continue;
                }
                $candidate = \max($lowerBound, \min($upperBound, $candidate));
                $residual = $residualAt($candidate);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    $rejectedCandidate = true;
                    return;
                }

                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), $iterations),
                    $options,
                );
            }
        };
        if ($targetValue === 0.0) {
            for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
                if ($level !== 0.0) {
                    $addCandidate($phaseUnit * $level);
                }
            }
        } else {
            $phaseLower = $argumentLower;
            $phaseUpper = $argumentUpper;
            $firstExtremumLobe = (int) \floor($phaseLower / $phaseUnit);
            $lastExtremumLobe = (int) \ceil($phaseUpper / $phaseUnit) - 1;
            if ($lastExtremumLobe - $firstExtremumLobe + 1 > self::MAX_PERIODIC_ROOTS) {
                return null;
            }
            $extrema = [];
            if ($phaseLower < 0.0 && $phaseUpper > 0.0) {
                $extrema[] = 0.0;
            }
            for ($lobe = $firstExtremumLobe; $lobe <= $lastExtremumLobe; ++$lobe) {
                if ($lobe === 0) {
                    continue;
                }
                $lobeIndex = \abs($lobe);
                $leftPhase = $lobeIndex * $phaseUnit;
                $rightPhase = ($lobeIndex + 1) * $phaseUnit;
                $derivativeScale = $function->name === 'sincpi' ? \M_PI : 1.0;
                $leftDerivative = $this->sincPhaseDerivativeNumerator($leftPhase * $derivativeScale);
                $rightDerivative = $this->sincPhaseDerivativeNumerator($rightPhase * $derivativeScale);
                if (!$this->hasOppositeSigns($leftDerivative, $rightDerivative)) {
                    continue;
                }
                $extremum = $this->bisectSincExtremum(
                    $leftPhase,
                    $rightPhase,
                    $derivativeScale,
                    $options,
                );
                if ($lobe < 0) {
                    $extremum = -$extremum;
                }
                if ($extremum > $phaseLower && $extremum < $phaseUpper) {
                    $extrema[] = $extremum;
                }
            }

            $points = [$phaseLower, ...$extrema, $phaseUpper];
            \sort($points, \SORT_NUMERIC);
            foreach ($extrema as $extremum) {
                $extremumResidual = $this->sincPhaseResidual(
                    $function->name,
                    $extremum,
                    $targetValue,
                );
                if (
                    $extremumResidual !== null
                    && \abs($extremumResidual) <= $options->residualTolerance
                ) {
                    $addCandidate($extremum);
                }
            }
            for ($branch = 1, $pointCount = \count($points); $branch < $pointCount; ++$branch) {
                $leftPhase = $points[$branch - 1];
                $rightPhase = $points[$branch];
                $leftResidual = $this->sincPhaseResidual($function->name, $leftPhase, $targetValue);
                $rightResidual = $this->sincPhaseResidual($function->name, $rightPhase, $targetValue);
                if ($leftResidual === null || $rightResidual === null) {
                    return null;
                }
                if (
                    $leftResidual === 0.0
                    || $rightResidual === 0.0
                    || $this->hasOppositeSigns($leftResidual, $rightResidual)
                ) {
                    $phase = $leftResidual === 0.0
                        ? $leftPhase
                        : ($rightResidual === 0.0
                            ? $rightPhase
                            : $this->bisectSincPhase(
                                $function->name,
                                $targetValue,
                                $leftPhase,
                                $leftResidual,
                                $rightPhase,
                                $options,
                            ));
                    if ($phase === null) {
                        return null;
                    }
                    $addCandidate($phase);
                }
            }
        }

        if ($rejectedCandidate) {
            return null;
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Recognize sin(p)/p as sinc(p) for supported polynomial or rational p,
     * retaining the original equation's domain during candidate validation.
     */
    private function sincQuotientFunction(
        Node $node,
        PolynomialExtractor $extractor,
        ?float &$quotientMultiplier = null,
    ): ?FunctionCallNode {
        $capturesSign = $quotientMultiplier !== null;
        $quotientMultiplier ??= 1.0;
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Divide) {
            return null;
        }
        $numerator = $this->unwrapGrouping($node->left);
        while ($numerator instanceof UnaryOperationNode) {
            if ($numerator->operator === UnaryOperator::Minus) {
                $quotientMultiplier *= -1.0;
            }
            $numerator = $this->unwrapGrouping($numerator->operand);
        }
        if (
            !$numerator instanceof FunctionCallNode
            || $numerator->name !== 'sin'
            || \count($numerator->arguments) !== 1
        ) {
            return null;
        }

        $argument = $numerator->arguments[0];
        $argumentForm = $extractor->extractRationalForm($argument);
        $denominatorForm = $extractor->extractRationalForm($node->right);
        if ($argumentForm === null || $denominatorForm === null) {
            return null;
        }
        $argumentCrossProduct = $this->multiplyPolynomialCoefficients(
            $argumentForm[0],
            $denominatorForm[1],
            64,
        );
        $denominatorCrossProduct = $this->multiplyPolynomialCoefficients(
            $denominatorForm[0],
            $argumentForm[1],
            64,
        );
        if ($argumentCrossProduct === null || $denominatorCrossProduct === null || \count($argumentCrossProduct) < 2) {
            return null;
        }
        $argumentRatio = $this->proportionalPolynomialRatio(
            $argumentCrossProduct,
            $denominatorCrossProduct,
        );
        if ($argumentRatio === null || $argumentRatio === 0.0) {
            return null;
        }
        if ($argumentRatio !== 1.0 && !$capturesSign) {
            return null;
        }
        $quotientMultiplier *= $argumentRatio;

        return new FunctionCallNode(
            'sinc',
            [$argument],
            $numerator->nameSpan,
            $node->span(),
        );
    }

    /**
     * @return array{FunctionCallNode, Node}|null
     */
    private function sincQuotientEquationParts(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            !$this->containsVariable($right, $variable)
            && ($function = $this->sincQuotientFunction($left, $extractor)) !== null
        ) {
            return [$function, $right];
        }
        if (
            !$this->containsVariable($left, $variable)
            && ($function = $this->sincQuotientFunction($right, $extractor)) !== null
        ) {
            return [$function, $left];
        }

        return null;
    }

    private function sameExpression(Node $left, Node $right): bool
    {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $leftRational = RationalLiteral::fromNode($left);
        $rightRational = RationalLiteral::fromNode($right);
        if ($leftRational !== null && $rightRational !== null) {
            return $leftRational === $rightRational;
        }
        if ($left::class !== $right::class) {
            return false;
        }
        if ($left instanceof NumberNode && $right instanceof NumberNode) {
            return $left->value === $right->value
                && $left->literal === $right->literal
                && $left->hasFiniteApproximation === $right->hasFiniteApproximation;
        }
        if ($left instanceof ConstantNode && $right instanceof ConstantNode) {
            return $left->name === $right->name;
        }
        if ($left instanceof VariableNode && $right instanceof VariableNode) {
            return $left->name === $right->name;
        }
        if ($left instanceof FactorialNode && $right instanceof FactorialNode) {
            return $this->sameExpression($left->operand, $right->operand);
        }
        if ($left instanceof UnaryOperationNode && $right instanceof UnaryOperationNode) {
            return $left->operator === $right->operator
                && $this->sameExpression($left->operand, $right->operand);
        }
        if ($left instanceof BinaryOperationNode && $right instanceof BinaryOperationNode) {
            return $left->operator === $right->operator
                && $this->sameExpression($left->left, $right->left)
                && $this->sameExpression($left->right, $right->right);
        }
        if ($left instanceof FunctionCallNode && $right instanceof FunctionCallNode) {
            if ($this->sameRootFunctionAlias($left, $right)) {
                return true;
            }
            $leftName = $this->canonicalFunctionAlias($left->name);
            $rightName = $this->canonicalFunctionAlias($right->name);
            if ($leftName !== $rightName || \count($left->arguments) !== \count($right->arguments)) {
                return false;
            }
            foreach ($left->arguments as $index => $argument) {
                if (!$this->sameExpression($argument, $right->arguments[$index])) {
                    return false;
                }
            }

            return true;
        }

        return false;
    }

    private function canonicalFunctionAlias(string $name): string
    {
        return match ($name) {
            'arcsin' => 'asin',
            'arccos' => 'acos',
            'arctan' => 'atan',
            'arcsinh' => 'asinh',
            'arccosh' => 'acosh',
            'arctanh' => 'atanh',
            default => $name,
        };
    }

    private function sameRootFunctionAlias(FunctionCallNode $left, FunctionCallNode $right): bool
    {
        $rootCall = $left->name === 'root' ? $left : $right;
        $otherCall = $left->name === 'root' ? $right : $left;
        $degree = match ($otherCall->name) {
            'sqrt' => 2,
            'cbrt' => 3,
            default => null,
        };
        if (
            $rootCall->name !== 'root'
            || $degree === null
            || \count($rootCall->arguments) !== 2
            || \count($otherCall->arguments) !== 1
        ) {
            return false;
        }
        return $this->rootDegreeLiteral($rootCall) === $degree
            && $this->sameExpression($rootCall->arguments[0], $otherCall->arguments[0]);
    }

    private function rootDegreeLiteral(FunctionCallNode $rootCall): ?int
    {
        if ($rootCall->name !== 'root' || \count($rootCall->arguments) !== 2) {
            return null;
        }
        $degreeFraction = RationalLiteral::fromNode($rootCall->arguments[1]);
        if ($degreeFraction === null) {
            return null;
        }
        return $this->normalizedIntegerRootDegree($degreeFraction[0] / $degreeFraction[1]);
    }

    private function normalizedIntegerRootDegree(float $degree): ?int
    {
        if (!\is_finite($degree)) {
            return null;
        }
        $nearestDegree = \round($degree);
        $tolerance = \min(
            1.0E-9,
            16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($degree)),
        );
        if (
            \abs($degree - $nearestDegree) > $tolerance
            || $nearestDegree == 0.0
            || \abs($nearestDegree) > 9_007_199_254_740_991.0
        ) {
            return null;
        }

        return (int) $nearestDegree;
    }

    private function containsRestrictedDomainCall(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if ($node->name === 'root') {
                $degree = $this->rootDegreeLiteral($node);
                if ($degree === null || $degree <= 0 || ($degree % 2) === 0) {
                    return true;
                }
            }
            if (
                \in_array(
                    $node->name,
                    [
                        'asin', 'arcsin', 'atanh', 'arctanh', 'erfinv', 'erfcinv', 'acos', 'arccos',
                        'acosh', 'arccosh', 'asec', 'asech', 'acsc', 'sqrt', 'csch', 'coth', 'acsch', 'acoth',
                        'ln', 'log', 'log10', 'log2', 'log1p',
                    ],
                    true,
                )
            ) {
                return true;
            }
            foreach ($node->arguments as $argument) {
                if ($this->containsRestrictedDomainCall($argument)) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsRestrictedDomainCall($node->operand);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsRestrictedDomainCall($node->left)
                || $this->containsRestrictedDomainCall($node->right);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsRestrictedDomainCall($node->operand);
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function sameExpressionOrNegation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($this->sameExpression($left, $right)) {
            return true;
        }

        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);

        if (
            ($left instanceof UnaryOperationNode
                && $left->operator === UnaryOperator::Minus
                && $this->sameExpression($left->operand, $right))
            || ($right instanceof UnaryOperationNode
                && $right->operator === UnaryOperator::Minus
                && $this->sameExpression($right->operand, $left))
        ) {
            return true;
        }

        $negatedRight = new UnaryOperationNode(UnaryOperator::Minus, $right, $left->span());

        return (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        ))->difference($left, $negatedRight) === ['0'];
    }

    /**
     * Enumerate all nonzero integer phase levels for a polynomial sinc argument.
     *
     * @param list<float> $argument
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solvePolynomialSincZeroLevels(
        array $argument,
        float $phaseUnit,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $range = $this->polynomialRange($argument, $lowerBound, $upperBound, $options);
        if ($range === null) {
            return null;
        }

        [$minimum, $maximum] = $range;
        $phaseMinimum = $minimum / $phaseUnit;
        $phaseMaximum = $maximum / $phaseUnit;
        if (
            !\is_finite($phaseMinimum)
            || !\is_finite($phaseMaximum)
            || \max(\abs($phaseMinimum), \abs($phaseMaximum)) > 4_503_599_627_370_496.0
        ) {
            return null;
        }

        $phaseTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($phaseMinimum), \abs($phaseMaximum));
        $firstLevel = (int) \ceil($phaseMinimum - $phaseTolerance);
        $lastLevel = (int) \floor($phaseMaximum + $phaseTolerance);
        if ($firstLevel > $lastLevel) {
            return [];
        }
        if ($lastLevel - $firstLevel + 1 > self::MAX_PERIODIC_ROOTS) {
            return null;
        }

        $polynomialSolver = new PolynomialSolver();
        $solutions = [];
        $candidateCount = 0;
        for ($level = $firstLevel; $level <= $lastLevel; ++$level) {
            if ($level === 0) {
                continue;
            }

            $levelCoefficients = $argument;
            $levelCoefficients[0] -= $phaseUnit * $level;
            if (!\is_finite($levelCoefficients[0])) {
                return null;
            }
            $levelRoots = $polynomialSolver->solve(
                $levelCoefficients,
                $lowerBound,
                $upperBound,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomial(
                    $levelCoefficients,
                    $value,
                ),
                $options,
                fn (float $value): ?float => $polynomialSolver->evaluatePolynomialMagnitude(
                    $levelCoefficients,
                    $value,
                ),
            );
            if ($levelRoots === null) {
                return null;
            }

            foreach ($levelRoots as $levelRoot) {
                if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $candidate = $levelRoot->value;
                $residual = $residualAt($candidate);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), $levelRoot->iterations),
                    $options,
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function sincPhaseResidual(string $function, float $phase, float $target): ?float
    {
        $argument = $function === 'sincpi' ? \M_PI * $phase : $phase;
        if (!\is_finite($argument)) {
            return null;
        }
        $value = $argument === 0.0 ? 1.0 : \sin($argument) / $argument;
        $residual = $value - $target;

        return \is_finite($residual) ? $residual : null;
    }

    private function sincPhaseDerivativeNumerator(float $phase): float
    {
        return ($phase * \cos($phase)) - \sin($phase);
    }

    private function bisectSincExtremum(
        float $left,
        float $right,
        float $derivativeScale,
        SolverOptions $options,
    ): float {
        $leftDerivative = $this->sincPhaseDerivativeNumerator($left * $derivativeScale);
        for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
            $midpoint = $left + (($right - $left) / 2.0);
            if ($midpoint === $left || $midpoint === $right) {
                return $midpoint;
            }
            $derivative = $this->sincPhaseDerivativeNumerator($midpoint * $derivativeScale);
            if ($derivative === 0.0) {
                return $midpoint;
            }
            if ($this->hasOppositeSigns($leftDerivative, $derivative)) {
                $right = $midpoint;
            } else {
                $left = $midpoint;
                $leftDerivative = $derivative;
            }
        }

        return $left + (($right - $left) / 2.0);
    }

    private function bisectSincPhase(
        string $function,
        float $target,
        float $left,
        float $leftResidual,
        float $right,
        SolverOptions $options,
    ): ?float {
        for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
            $midpoint = $left + (($right - $left) / 2.0);
            if ($midpoint === $left || $midpoint === $right) {
                return $midpoint;
            }
            $residual = $this->sincPhaseResidual($function, $midpoint, $target);
            if ($residual === null) {
                return null;
            }
            if ($residual === 0.0) {
                return $midpoint;
            }
            if ($this->hasOppositeSigns($leftResidual, $residual)) {
                $right = $midpoint;
            } else {
                $left = $midpoint;
                $leftResidual = $residual;
            }
        }

        return $left + (($right - $left) / 2.0);
    }

    /**
     * Solve additive trigonometric polynomials with affine rational frequencies.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineTrigonometricPolynomialEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($this->containsVariable($left, $variable) && !$this->containsVariable($right, $variable)) {
            $linearForm = $this->flattenAffineTrigonometricTerms($left, $extractor);
            $constant = $right;
        } elseif (
            $this->containsVariable($right, $variable)
            && !$this->containsVariable($left, $variable)
        ) {
            $linearForm = $this->flattenAffineTrigonometricTerms($right, $extractor);
            $constant = $left;
        } else {
            return null;
        }
        if ($linearForm === null || \count($linearForm['terms']) < 2) {
            return null;
        }
        $terms = $linearForm['terms'];
        if (
            \count($terms) === 2
            && $terms[0]['call']->name === $terms[1]['call']->name
        ) {
            return null;
        }
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($targetCoefficients === null || \count($targetCoefficients) !== 1) {
            return null;
        }

        $arguments = [];
        foreach ($terms as $term) {
            $argument = $this->extractPolynomial(
                $extractor,
                $term['call']->arguments[0],
                $term['call']->arguments[0]->span()->start,
            );
            if ($argument === null || \count($argument) !== 2 || $argument[1] === 0.0) {
                return null;
            }
            $arguments[] = $argument;
        }

        $referenceSlope = \abs($arguments[0][1]);
        $ratios = [];
        $commonDenominator = 1;
        foreach ($arguments as $argument) {
            $fraction = $this->rationalHarmonicOrders(
                \abs($argument[1]) / $referenceSlope,
                $options->maxPolynomialDegree,
            );
            if ($fraction === null) {
                return null;
            }
            $ratios[] = $fraction;
            [$numerator, $denominator] = [$commonDenominator, $fraction[1]];
            while ($denominator !== 0) {
                [$numerator, $denominator] = [$denominator, $numerator % $denominator];
            }
            $commonDenominator = \intdiv($commonDenominator, $numerator) * $fraction[1];
            if ($commonDenominator > 1024) {
                return null;
            }
        }

        $rawOrders = [];
        $orderGcd = 0;
        foreach ($ratios as [$numerator, $denominator]) {
            $order = $numerator * \intdiv($commonDenominator, $denominator);
            $rawOrders[] = $order;
            $leftGcd = $orderGcd;
            $rightGcd = $order;
            while ($rightGcd !== 0) {
                [$leftGcd, $rightGcd] = [$rightGcd, $leftGcd % $rightGcd];
            }
            $orderGcd = $leftGcd;
        }
        if ($orderGcd < 1) {
            return null;
        }
        $orders = \array_map(
            static fn (int $order): int => \intdiv($order, $orderGcd),
            $rawOrders,
        );
        $fundamentalSlope = $referenceSlope / \intdiv($commonDenominator, $orderGcd);
        if (!\is_finite($fundamentalSlope) || $fundamentalSlope === 0.0) {
            return null;
        }
        $maximumOrder = \max(...$orders);
        foreach ($arguments as $index => $argument) {
            if (
                $orders[$index] > $options->maxPolynomialDegree
                || !$this->approximatelyEqual(\abs($argument[1]), $fundamentalSlope * $orders[$index])
            ) {
                return null;
            }
        }

        $target = $targetCoefficients[0] - $linearForm['constant'];
        $maximumAmplitude = 0.0;
        foreach ($terms as $term) {
            $maximumAmplitude += \abs($term['coefficient']);
        }
        if (!\is_finite($target)) {
            return null;
        }
        if (\is_finite($maximumAmplitude) && \abs($target) > $maximumAmplitude) {
            return [];
        }
        $sineCoefficient = [0.0];
        $otherTerm = [0.0];
        $directCosine = true;
        foreach ($terms as $index => $term) {
            $frequency = $arguments[$index][1] < 0.0 ? -$orders[$index] : $orders[$index];
            $phase = \fmod($arguments[$index][0], 2.0 * \M_PI);
            $phaseSine = \sin($phase);
            $phaseCosine = \cos($phase);
            if (!\is_finite($phaseSine) || !\is_finite($phaseCosine)) {
                return null;
            }
            $cosineHarmonic = $this->chebyshevPolynomial($orders[$index], false);
            $sineHarmonic = $this->chebyshevPolynomial($orders[$index] - 1, true);
            $coefficient = $term['coefficient'];
            if ($term['call']->name === 'sin') {
                $sineCoefficient = $this->addPolynomials(
                    $sineCoefficient,
                    $this->scaledPolynomial(
                        $sineHarmonic,
                        $coefficient * $phaseCosine * ($frequency < 0 ? -1.0 : 1.0),
                    ),
                );
                $otherTerm = $this->addPolynomials(
                    $otherTerm,
                    $this->scaledPolynomial($cosineHarmonic, $coefficient * $phaseSine),
                );
                $directCosine = false;
            } else {
                $sineCoefficient = $this->addPolynomials(
                    $sineCoefficient,
                    $this->scaledPolynomial(
                        $sineHarmonic,
                        -$coefficient * $phaseSine * ($frequency < 0 ? -1.0 : 1.0),
                    ),
                );
                $otherTerm = $this->addPolynomials(
                    $otherTerm,
                    $this->scaledPolynomial($cosineHarmonic, $coefficient * $phaseCosine),
                );
                $directCosine = $directCosine
                    && \abs($phaseSine) <= 32.0 * \PHP_FLOAT_EPSILON;
            }
        }

        if (($directCosine ? $maximumOrder : 2 * $maximumOrder) > $options->maxPolynomialDegree) {
            return null;
        }
        if ($directCosine) {
            $coefficients = $this->addPolynomials($otherTerm, [$target], -1.0);
        } else {
            $rightSide = $this->addPolynomials([$target], $otherTerm, -1.0);
            $leftSquare = $this->multiplyPolynomials($sineCoefficient, $sineCoefficient);
            $leftTerm = [];
            for ($degree = 0; $degree < \count($leftSquare) + 2; ++$degree) {
                $leftTerm[] = ($leftSquare[$degree] ?? 0.0) - ($leftSquare[$degree - 2] ?? 0.0);
            }
            $coefficients = $this->addPolynomials(
                $leftTerm,
                $this->multiplyPolynomials($rightSide, $rightSide),
                -1.0,
            );
        }
        foreach ($coefficients as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $polynomialOptions = $this->polynomialIsolationOptions(
            $options,
            64.0 * \PHP_FLOAT_EPSILON,
        );
        $cosineLevels = $polynomialSolver->solve(
            $coefficients,
            -1.0,
            1.0,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($coefficients, $value),
            $polynomialOptions,
        );
        if ($cosineLevels === null) {
            return null;
        }
        $argumentAtLower = $fundamentalSlope * $lowerBound;
        $argumentAtUpper = $fundamentalSlope * $upperBound;
        if (!\is_finite($argumentAtLower) || !\is_finite($argumentAtUpper)) {
            return null;
        }
        $argumentLower = \min($argumentAtLower, $argumentAtUpper);
        $argumentUpper = \max($argumentAtLower, $argumentAtUpper);
        $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        $positionTolerance = $options->positionTolerance($lowerBound, $upperBound);
        $solutions = [];
        $candidateCount = 0;
        foreach ($cosineLevels as $cosineLevel) {
            $cosine = \max(-1.0, \min(1.0, $cosineLevel->value));
            if ($directCosine) {
                $principal = \acos($cosine);
                $phases = [$principal, -$principal];
            } else {
                $sineCoefficientValue = $this->polynomialValue($sineCoefficient, $cosine);
                $otherTermValue = $this->polynomialValue($otherTerm, $cosine);
                if ($sineCoefficientValue === null || $otherTermValue === null) {
                    return null;
                }
                $sine = $target - $otherTermValue;
                if (
                    \abs($sineCoefficientValue)
                    <= 32.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($target), \abs($otherTermValue))
                ) {
                    if (\abs($sine) > $options->residualTolerance * \max(1.0, \abs($target))) {
                        continue;
                    }
                    $principal = \acos($cosine);
                    $phases = [$principal, -$principal];
                } else {
                    $sine /= $sineCoefficientValue;
                    if (!\is_finite($sine) || \abs($sine) > 1.0 + 1.0E-10) {
                        continue;
                    }
                    $phases = [\atan2(\max(-1.0, \min(1.0, $sine)), $cosine)];
                }
            }
            foreach ($phases as $phase) {
                $period = 2.0 * \M_PI;
                $firstPeriod = \ceil(($argumentLower - $phase - $angleTolerance) / $period);
                $lastPeriod = \floor(($argumentUpper - $phase + $angleTolerance) / $period);
                if ($lastPeriod < $firstPeriod) {
                    continue;
                }
                if (
                    $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                    || \abs($firstPeriod) > 4_503_599_627_370_496.0
                    || \abs($lastPeriod) > 4_503_599_627_370_496.0
                ) {
                    return null;
                }
                for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        return null;
                    }
                    $candidate = ($phase + ($periodIndex * $period)) / $fundamentalSlope;
                    if (
                        !\is_finite($candidate)
                        || $candidate < $lowerBound - $positionTolerance
                        || $candidate > $upperBound + $positionTolerance
                    ) {
                        continue;
                    }
                    $candidate = \max($lowerBound, \min($upperBound, $candidate));
                    $residual = $residualAt($candidate);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return null;
                    }
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($residual), 0),
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return array{
     *     terms: list<array{call: FunctionCallNode, coefficient: float}>,
     *     constant: float,
     * }|null
     */
    private function flattenAffineTrigonometricTerms(
        Node $node,
        PolynomialExtractor $extractor,
        bool $includeExtendedPeriodicFunctions = false,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $sign = $node->operator === \MathPHP\Ast\UnaryOperator::Minus ? -1.0 : 1.0;
            $form = $this->flattenAffineTrigonometricTerms(
                $node->operand,
                $extractor,
                $includeExtendedPeriodicFunctions,
            );
            return $form === null
                ? null
                : [
                    'terms' => $this->scaledTrigonometricTerms($form['terms'], $sign),
                    'constant' => $form['constant'] * $sign,
                ];
        }
        if ($node instanceof BinaryOperationNode) {
            if (
                \in_array($node->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
            ) {
                $leftForm = $this->flattenAffineTrigonometricTerms(
                    $node->left,
                    $extractor,
                    $includeExtendedPeriodicFunctions,
                );
                $rightForm = $this->flattenAffineTrigonometricTerms(
                    $node->right,
                    $extractor,
                    $includeExtendedPeriodicFunctions,
                );
                if ($leftForm === null || $rightForm === null) {
                    return null;
                }
                if ($node->operator === BinaryOperator::Multiply) {
                    if ($leftForm['terms'] === []) {
                        return [
                            'terms' => $this->scaledTrigonometricTerms(
                                $rightForm['terms'],
                                $leftForm['constant'],
                            ),
                            'constant' => $leftForm['constant'] * $rightForm['constant'],
                        ];
                    }
                    if ($rightForm['terms'] === []) {
                        return [
                            'terms' => $this->scaledTrigonometricTerms(
                                $leftForm['terms'],
                                $rightForm['constant'],
                            ),
                            'constant' => $leftForm['constant'] * $rightForm['constant'],
                        ];
                    }

                    return null;
                }
                if ($rightForm['terms'] !== [] || $rightForm['constant'] === 0.0) {
                    return null;
                }
                $divisor = 1.0 / $rightForm['constant'];
                if (!\is_finite($divisor)) {
                    return null;
                }

                return [
                    'terms' => $this->scaledTrigonometricTerms($leftForm['terms'], $divisor),
                    'constant' => $leftForm['constant'] * $divisor,
                ];
            }
            if (!\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
                return null;
            }
            $leftForm = $this->flattenAffineTrigonometricTerms(
                $node->left,
                $extractor,
                $includeExtendedPeriodicFunctions,
            );
            $rightForm = $this->flattenAffineTrigonometricTerms(
                $node->right,
                $extractor,
                $includeExtendedPeriodicFunctions,
            );
            if ($leftForm === null || $rightForm === null) {
                return null;
            }
            $rightSign = $node->operator === BinaryOperator::Add ? 1.0 : -1.0;

            return [
                'terms' => [
                    ...$leftForm['terms'],
                    ...$this->scaledTrigonometricTerms($rightForm['terms'], $rightSign),
                ],
                'constant' => $leftForm['constant'] + ($rightSign * $rightForm['constant']),
            ];
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array(
                $node->name,
                $includeExtendedPeriodicFunctions
                    ? ['sin', 'cos', 'tan', 'sec', 'csc', 'cot']
                    : ['sin', 'cos'],
                true,
            )
            && \count($node->arguments) === 1
        ) {
            $argument = $this->extractPolynomial(
                $extractor,
                $node->arguments[0],
                $node->arguments[0]->span()->start,
            );
            if ($argument === null) {
                return null;
            }
            if (\count($argument) === 1) {
                $constant = match ($node->name) {
                    'sin' => \sin($argument[0]),
                    'cos' => \cos($argument[0]),
                    'tan' => \abs(\cos($argument[0])) > 32.0 * \PHP_FLOAT_EPSILON
                        ? \tan($argument[0])
                        : \NAN,
                    'sec' => \abs(\cos($argument[0])) > 32.0 * \PHP_FLOAT_EPSILON
                        ? 1.0 / \cos($argument[0])
                        : \NAN,
                    'csc' => \abs(\sin($argument[0])) > 32.0 * \PHP_FLOAT_EPSILON
                        ? 1.0 / \sin($argument[0])
                        : \NAN,
                    'cot' => \abs(\sin($argument[0])) > 32.0 * \PHP_FLOAT_EPSILON
                        ? \cos($argument[0]) / \sin($argument[0])
                        : \NAN,
                };

                return \is_finite($constant)
                    ? ['terms' => [], 'constant' => $constant]
                    : null;
            }

            return ['terms' => [['call' => $node, 'coefficient' => 1.0]], 'constant' => 0.0];
        }

        $constant = $this->extractPolynomial($extractor, $node, $node->span()->start);
        if ($constant === null || \count($constant) !== 1 || !\is_finite($constant[0])) {
            return null;
        }

        return ['terms' => [], 'constant' => $constant[0]];
    }

    /**
     * @param list<array{call: FunctionCallNode, coefficient: float}> $terms
     * @return list<array{call: FunctionCallNode, coefficient: float}>
     */
    private function scaledTrigonometricTerms(array $terms, float $scale): array
    {
        foreach ($terms as &$term) {
            $term['coefficient'] *= $scale;
        }
        unset($term);

        return $terms;
    }

    /**
     * Rewrite products of polynomial sine/cosine factors as a bounded sum.
     *
     * @return string|null
     */
    /**
     * Solve zero products by taking the union of each trigonometric factor's roots.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveTrigonometricProductZeroEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        try {
            $leftForm = $this->flattenTrigonometricProduct($left, $leftSource, 0, $extractor);
            $rightForm = $this->flattenTrigonometricProduct(
                $right,
                $rightSource,
                0,
                $extractor,
            );
            $leftTarget = $extractor->extract($left);
            $rightTarget = $extractor->extract($right);
        } catch (EvaluationException) {
            return null;
        }

        if (
            $leftForm !== null
            && \count($leftForm['factors']) > 1
            && $rightTarget === [0.0]
        ) {
            $productForm = $leftForm;
        } elseif (
            $rightForm !== null
            && \count($rightForm['factors']) > 1
            && $leftTarget === [0.0]
        ) {
            $productForm = $rightForm;
        } else {
            return null;
        }

        if ($productForm['coefficient'] === 0.0) {
            throw new InfiniteSolutionSetException(
                'Equation has every real number as a solution in the requested interval.',
            );
        }

        $solutions = [];
        foreach ($productForm['factors'] as $factor) {
            $factorExpression = $factor['name'] . '(' . $factor['argument'] . ')';
            $factorEquation = $factorExpression . '=0';
            if (\strlen($factorEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            try {
                $factorSolutions = $this->solve(
                    $factorEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (\InvalidArgumentException) {
                try {
                    $factorNode = $this->parseSide(
                        $factorExpression,
                        0,
                        $evaluationOptions,
                    );
                    $factorValue = $this->evaluateNode(
                        $factorNode,
                        $parameters,
                        $evaluationOptions,
                    );
                } catch (EvaluationException) {
                    return null;
                }
                if ((float) $factorValue === 0.0) {
                    throw new InfiniteSolutionSetException(
                        'Equation has every real number as a solution in the requested interval.',
                    );
                }
                continue;
            }

            foreach ($factorSolutions as $candidate) {
                $residual = $residualAt($candidate->value);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate->value,
                        $residual,
                        $candidateScaleAt,
                        $solverOptions,
                    )
                ) {
                    return null;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate->value,
                        \abs($residual),
                        $candidate->iterations,
                    ),
                );
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve bounded nonzero sine/cosine products using a phase-scaled grid.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveNonzeroTrigonometricProductEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        try {
            $leftForm = $this->flattenTrigonometricProduct($left, $leftSource, 0, $extractor);
            $rightForm = $this->flattenTrigonometricProduct(
                $right,
                $rightSource,
                0,
                $extractor,
            );
            $leftTarget = $extractor->extract($left);
            $rightTarget = $extractor->extract($right);
        } catch (EvaluationException) {
            return null;
        }
        if (
            $leftForm !== null
            && \count($leftForm['factors']) > 1
            && $rightTarget !== null
            && \count($rightTarget) === 1
        ) {
            $product = $leftForm;
            $target = $rightTarget[0];
        } elseif (
            $rightForm !== null
            && \count($rightForm['factors']) > 1
            && $leftTarget !== null
            && \count($leftTarget) === 1
        ) {
            $product = $rightForm;
            $target = $leftTarget[0];
        } else {
            return null;
        }

        $factorData = [];
        $phaseVariation = 0.0;
        foreach ($product['factors'] as $factor) {
            try {
                $argumentNode = $this->parseSide($factor['argument'], 0, $evaluationOptions);
            } catch (EvaluationException) {
                return null;
            }
            $argument = $this->extractPolynomial(
                $extractor,
                $argumentNode,
                $argumentNode->span()->start,
            );
            if ($argument === null) {
                return null;
            }
            if (\count($argument) === 1) {
                $constantFactor = $factor['name'] === 'sin'
                    ? \sin($argument[0])
                    : \cos($argument[0]);
                if (!\is_finite($constantFactor)) {
                    return null;
                }
                $product['coefficient'] *= $constantFactor;
                continue;
            }
            if (\count($argument) !== 2) {
                return null;
            }
            $factorData[] = [
                'name' => $factor['name'],
                'intercept' => $argument[0],
                'slope' => $argument[1],
            ];
            $phaseVariation += \abs($argument[1]) * ($upperBound - $lowerBound);
        }
        if (
            !\is_finite($target)
            || $target === 0.0
            || !\is_finite($phaseVariation)
            || $phaseVariation === 0.0
        ) {
            return null;
        }
        if ($product['coefficient'] === 0.0) {
            return [];
        }

        $residual = static function (float $position) use ($factorData, $product, $target): ?float {
            $value = $product['coefficient'];
            foreach ($factorData as $factor) {
                $phase = $factor['intercept'] + ($factor['slope'] * $position);
                $value *= $factor['name'] === 'sin' ? \sin($phase) : \cos($phase);
            }

            $value -= $target;

            return \is_finite($value) ? $value : null;
        };
        $derivative = static function (float $position) use ($factorData, $product): ?float {
            $sum = 0.0;
            foreach ($factorData as $index => $factor) {
                $phase = $factor['intercept'] + ($factor['slope'] * $position);
                $term = $factor['name'] === 'sin'
                    ? $factor['slope'] * \cos($phase)
                    : -$factor['slope'] * \sin($phase);
                foreach ($factorData as $otherIndex => $other) {
                    if ($otherIndex === $index) {
                        continue;
                    }
                    $otherPhase = $other['intercept'] + ($other['slope'] * $position);
                    $term *= $other['name'] === 'sin' ? \sin($otherPhase) : \cos($otherPhase);
                }
                $sum += $term;
            }
            $sum *= $product['coefficient'];

            return \is_finite($sum) ? $sum : null;
        };
        $stepsPerRadian = 16.0;
        $stepCount = (int) \ceil($phaseVariation * $stepsPerRadian);
        if ($stepCount < 1 || $stepCount > self::MAX_ADAPTIVE_SCAN_STEPS) {
            return null;
        }
        $solutions = [];
        $addBracketRoot = function (
            float $bracketLeft,
            float $bracketLeftResidual,
            float $bracketRight,
            float $bracketRightResidual,
        ) use (
            $residual,
            $residualAt,
            $candidateScaleAt,
            $options,
            &$solutions,
        ): ?bool {
            for ($iteration = 0; $iteration < 128; ++$iteration) {
                $midpoint = $bracketLeft + (($bracketRight - $bracketLeft) / 2.0);
                if ($midpoint === $bracketLeft || $midpoint === $bracketRight) {
                    break;
                }
                $midpointResidual = $residual($midpoint);
                if ($midpointResidual === null) {
                    return null;
                }
                if ($midpointResidual === 0.0) {
                    $bracketLeft = $midpoint;
                    $bracketRight = $midpoint;
                    break;
                }
                if ($this->hasOppositeSigns($bracketLeftResidual, $midpointResidual)) {
                    $bracketRight = $midpoint;
                    $bracketRightResidual = $midpointResidual;
                } else {
                    $bracketLeft = $midpoint;
                    $bracketLeftResidual = $midpointResidual;
                }
            }
            $rootValue = \abs($bracketLeftResidual) <= \abs($bracketRightResidual)
                ? $bracketLeft
                : $bracketRight;
            $originalResidual = $residualAt($rootValue);
            if (
                $originalResidual === null
                || !$this->isResidualAcceptableAt($rootValue, $originalResidual, $candidateScaleAt, $options)
            ) {
                return null;
            }
            $this->addDistinctSolution(
                $solutions,
                new EquationSolution($rootValue, \abs($originalResidual), 128),
            );

            return true;
        };
        $leftPosition = $lowerBound;
        $leftResidual = $residual($leftPosition);
        if ($leftResidual === null) {
            return null;
        }
        if ($leftResidual === 0.0) {
            $originalResidual = $residualAt($leftPosition);
            if (
                $originalResidual !== null
                && $this->isResidualAcceptableAt(
                    $leftPosition,
                    $originalResidual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($leftPosition, \abs($originalResidual), 0),
                );
            }
        }
        $leftDerivative = $derivative($leftPosition);
        if ($leftDerivative === null) {
            return null;
        }
        for ($index = 1; $index <= $stepCount; ++$index) {
            $rightPosition = $lowerBound + (($upperBound - $lowerBound) * $index / $stepCount);
            $rightResidual = $residual($rightPosition);
            if ($rightResidual === null) {
                return null;
            }
            $rightDerivative = $derivative($rightPosition);
            if ($rightDerivative === null) {
                return null;
            }
            $criticalPointFound = false;
            if (
                $leftDerivative === 0.0
                || $rightDerivative === 0.0
                || $this->hasOppositeSigns($leftDerivative, $rightDerivative)
            ) {
                $criticalLeft = $leftPosition;
                $criticalRight = $rightPosition;
                $criticalLeftDerivative = $leftDerivative;
                if ($leftDerivative === 0.0) {
                    $criticalRight = $criticalLeft;
                } elseif ($rightDerivative === 0.0) {
                    $criticalLeft = $criticalRight;
                } else {
                    for ($iteration = 0; $iteration < 128; ++$iteration) {
                        $midpoint = $criticalLeft + (($criticalRight - $criticalLeft) / 2.0);
                        if ($midpoint === $criticalLeft || $midpoint === $criticalRight) {
                            break;
                        }
                        $midpointDerivative = $derivative($midpoint);
                        if ($midpointDerivative === null) {
                            return null;
                        }
                        if ($midpointDerivative === 0.0) {
                            $criticalLeft = $midpoint;
                            $criticalRight = $midpoint;
                            break;
                        }
                        if ($this->hasOppositeSigns($criticalLeftDerivative, $midpointDerivative)) {
                            $criticalRight = $midpoint;
                        } else {
                            $criticalLeft = $midpoint;
                            $criticalLeftDerivative = $midpointDerivative;
                        }
                    }
                }
                $criticalPoint = $criticalLeft + (($criticalRight - $criticalLeft) / 2.0);
                $criticalResidual = $residual($criticalPoint);
                if ($criticalResidual === null) {
                    return null;
                }
                $criticalPointFound = true;
                if ($this->hasOppositeSigns($leftResidual, $criticalResidual)) {
                    $rootAdded = $addBracketRoot(
                        $leftPosition,
                        $leftResidual,
                        $criticalPoint,
                        $criticalResidual,
                    );
                    if ($rootAdded !== true) {
                        return null;
                    }
                }
                if ($this->hasOppositeSigns($criticalResidual, $rightResidual)) {
                    $rootAdded = $addBracketRoot(
                        $criticalPoint,
                        $criticalResidual,
                        $rightPosition,
                        $rightResidual,
                    );
                    if ($rootAdded !== true) {
                        return null;
                    }
                }
                $criticalTolerance = 64.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($target), \abs($product['coefficient']));
                if (\abs($criticalResidual) <= $criticalTolerance) {
                    $originalResidual = $residualAt($criticalPoint);
                    if (
                        $originalResidual !== null
                        && $this->isResidualAcceptableAt(
                            $criticalPoint,
                            $originalResidual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        $this->addDistinctSolution(
                            $solutions,
                            new EquationSolution($criticalPoint, \abs($originalResidual), 128),
                        );
                    }
                }
            }
            if (!$criticalPointFound && $this->hasOppositeSigns($leftResidual, $rightResidual)) {
                $rootAdded = $addBracketRoot(
                    $leftPosition,
                    $leftResidual,
                    $rightPosition,
                    $rightResidual,
                );
                if ($rootAdded !== true) {
                    return null;
                }
            }
            if ($rightResidual === 0.0) {
                $originalResidual = $residualAt($rightPosition);
                if (
                    $originalResidual !== null
                    && $this->isResidualAcceptableAt($rightPosition, $originalResidual, $candidateScaleAt, $options)
                ) {
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($rightPosition, \abs($originalResidual), 0),
                    );
                }
            }
            $leftPosition = $rightPosition;
            $leftResidual = $rightResidual;
            $leftDerivative = $rightDerivative;
        }
        $solutions = $this->mergeStationaryTrigonometricProductCandidates(
            $solutions,
            $derivative,
            $target,
            $product['coefficient'],
        );
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function extractZeroPowerFactor(
        Node $node,
        PolynomialExtractor $extractor,
    ): ?BinaryOperationNode {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            return $node;
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            $left = $this->extractPolynomial($extractor, $node->left, 0);
            if ($left !== null && \count($left) === 1 && $left[0] !== 0.0) {
                return $this->extractZeroPowerFactor($node->right, $extractor);
            }
            $right = $this->extractPolynomial($extractor, $node->right, 0);
            if ($right !== null && \count($right) === 1 && $right[0] !== 0.0) {
                return $this->extractZeroPowerFactor($node->left, $extractor);
            }
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Divide
        ) {
            $denominator = $this->extractPolynomial($extractor, $node->right, 0);
            if (
                $denominator !== null
                && \count($denominator) === 1
                && $denominator[0] !== 0.0
            ) {
                return $this->extractZeroPowerFactor($node->left, $extractor);
            }
        }

        return null;
    }

    /**
     * Improve a numerically isolated zero by checking nearby representable values.
     *
     * @param array<string, int|float> $parameters
     */
    private function refineRootCandidateByFloatSearch(
        Node $base,
        float $value,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): float {
        try {
            $bestResidual = \abs((float) $this->evaluateNode(
                $base,
                [...$parameters, $variable => $value],
                $evaluationOptions,
            ));
        } catch (EvaluationException) {
            return $value;
        }
        if ($bestResidual === 0.0) {
            return $value;
        }

        $bestValue = $value;
        for ($stepIndex = 0; $stepIndex < 4; ++$stepIndex) {
            $step = \PHP_FLOAT_EPSILON * \max(\abs($bestValue), \PHP_FLOAT_MIN);
            if ($step === 0.0) {
                break;
            }
            $improved = false;
            foreach ([-1.0, 1.0] as $direction) {
                $probe = $bestValue + ($direction * $step);
                if (
                    $probe === $bestValue
                    || $probe < $lowerBound
                    || $probe > $upperBound
                    || !\is_finite($probe)
                ) {
                    continue;
                }
                try {
                    $probeResidual = \abs((float) $this->evaluateNode(
                        $base,
                        [...$parameters, $variable => $probe],
                        $evaluationOptions,
                    ));
                } catch (EvaluationException) {
                    continue;
                }
                if ($probeResidual < $bestResidual) {
                    $bestValue = $probe;
                    $bestResidual = $probeResidual;
                    $improved = true;
                    if ($bestResidual === 0.0) {
                        return $bestValue;
                    }
                }
            }
            if (!$improved) {
                break;
            }
        }

        return $bestValue;
    }

    /**
     * @param list<EquationSolution> $solutions
     * @param callable(float): ?float $derivative
     * @return list<EquationSolution>
     */
    private function mergeStationaryTrigonometricProductCandidates(
        array $solutions,
        callable $derivative,
        float $target,
        float $coefficient,
    ): array {
        if (\count($solutions) < 2) {
            return $solutions;
        }
        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );
        $slopeTolerance = \sqrt(\PHP_FLOAT_EPSILON)
            * \max(1.0, \abs($target), \abs($coefficient));
        $merged = [];
        foreach ($solutions as $candidate) {
            $lastIndex = \count($merged) - 1;
            if ($lastIndex < 0) {
                $merged[] = $candidate;
                continue;
            }
            $previous = $merged[$lastIndex];
            $distanceTolerance = 8.0 * \sqrt(\PHP_FLOAT_EPSILON)
                * \max(1.0, \abs($candidate->value), \abs($previous->value));
            $previousSlope = $derivative($previous->value);
            $candidateSlope = $derivative($candidate->value);
            if (
                \abs($candidate->value - $previous->value) <= $distanceTolerance
                && $previousSlope !== null
                && $candidateSlope !== null
                && \abs($previousSlope) <= $slopeTolerance
                && \abs($candidateSlope) <= $slopeTolerance
            ) {
                if (
                    \abs($candidateSlope) < \abs($previousSlope)
                    || (\abs($candidateSlope) === \abs($previousSlope)
                        && \abs($candidate->residual) < \abs($previous->residual))
                ) {
                    $merged[$lastIndex] = $candidate;
                }
                continue;
            }
            $merged[] = $candidate;
        }

        return \array_values($merged);
    }

    private function rewriteAffineTrigonometricProductEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        PolynomialExtractor $extractor,
    ): ?string {
        $leftForm = $this->flattenTrigonometricProduct($left, $leftSource, 0, $extractor);
        $rightForm = $this->flattenTrigonometricProduct(
            $right,
            $rightSource,
            0,
            $extractor,
        );
        if (
            $leftForm !== null
            && \count($leftForm['factors']) > 1
            && $rightForm !== null
            && $rightForm['factors'] === []
        ) {
            $productForm = $leftForm;
            $targetSource = $rightSource;
        } elseif (
            $rightForm !== null
            && \count($rightForm['factors']) > 1
            && $leftForm !== null
            && $leftForm['factors'] === []
        ) {
            $productForm = $rightForm;
            $targetSource = $leftSource;
        } else {
            return null;
        }

        if ($productForm['coefficient'] === 0.0) {
            return null;
        }
        if (\count($productForm['factors']) > 9) {
            return null;
        }
        $terms = [[
            'name' => $productForm['factors'][0]['name'],
            'argument' => $productForm['factors'][0]['argument'],
            'coefficient' => $productForm['coefficient'],
        ]];
        for (
            $factorIndex = 1,
            $factorCount = \count($productForm['factors']);
            $factorIndex < $factorCount;
            ++$factorIndex
        ) {
            $factor = $productForm['factors'][$factorIndex];
            $expanded = [];
            foreach ($terms as $term) {
                $sum = '(' . $term['argument'] . ')+(' . $factor['argument'] . ')';
                $difference = '(' . $term['argument'] . ')-(' . $factor['argument'] . ')';
                if ($term['name'] === 'sin' && $factor['name'] === 'sin') {
                    $expanded[] = [
                        'name' => 'cos',
                        'argument' => $difference,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                    $expanded[] = [
                        'name' => 'cos',
                        'argument' => $sum,
                        'coefficient' => -0.5 * $term['coefficient'],
                    ];
                } elseif ($term['name'] === 'cos' && $factor['name'] === 'cos') {
                    $expanded[] = [
                        'name' => 'cos',
                        'argument' => $difference,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                    $expanded[] = [
                        'name' => 'cos',
                        'argument' => $sum,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                } elseif ($term['name'] === 'sin') {
                    $expanded[] = [
                        'name' => 'sin',
                        'argument' => $sum,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                    $expanded[] = [
                        'name' => 'sin',
                        'argument' => $difference,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                } else {
                    $expanded[] = [
                        'name' => 'sin',
                        'argument' => $sum,
                        'coefficient' => 0.5 * $term['coefficient'],
                    ];
                    $expanded[] = [
                        'name' => 'sin',
                        'argument' => $difference,
                        'coefficient' => -0.5 * $term['coefficient'],
                    ];
                }
            }
            $terms = $expanded;
        }

        $factorCount = \count($productForm['factors']);
        $normalization = (2.0 ** ($factorCount - 1)) / $productForm['coefficient'];
        $normalizedTerms = [];
        $orientation = 1.0;
        if (\is_finite($normalization)) {
            $orientation = $terms[0]['coefficient'] * $normalization < 0.0 ? -1.0 : 1.0;
            foreach ($terms as $term) {
                $coefficient = $term['coefficient'] * $normalization * $orientation;
                if (
                    !\is_finite($coefficient)
                    || \abs(\abs($coefficient) - 1.0) > 16.0 * \PHP_FLOAT_EPSILON
                ) {
                    $normalizedTerms = [];
                    break;
                }
                $normalizedTerms[] = [
                    'name' => $term['name'],
                    'argument' => $term['argument'],
                    'coefficient' => $coefficient,
                ];
            }
        }

        if ($normalizedTerms !== []) {
            $normalizedTargetScale = $orientation * $normalization;
            if (
                $factorCount === 2
                && $normalizedTerms[0]['name'] === $normalizedTerms[1]['name']
            ) {
                $firstTerm = $normalizedTerms[0]['name']
                    . '(' . $normalizedTerms[0]['argument'] . ')';
                $secondTerm = $normalizedTerms[1]['name']
                    . '(' . $normalizedTerms[1]['argument'] . ')';

                return '(' . $firstTerm
                    . ($normalizedTerms[1]['coefficient'] < 0.0 ? '-' : '+')
                    . $secondTerm . ')='
                    . '(' . $targetSource . ')*('
                    . \sprintf('%.17g', $normalizedTargetScale) . ')';
            }

            $sumSource = [];
            foreach ($normalizedTerms as $term) {
                $sumSource[] = '(' . \sprintf('%.17g', $term['coefficient']) . '*'
                    . $term['name'] . '(' . $term['argument'] . '))';
            }

            return '(' . \implode('+', $sumSource) . ')='
                . '(' . $targetSource . ')*('
                . \sprintf('%.17g', $normalizedTargetScale) . ')';
        }

        $sumSource = [];
        foreach ($terms as $term) {
            $coefficient = $term['coefficient'];
            if (!\is_finite($coefficient)) {
                return null;
            }
            $sumSource[] = '(' . \sprintf('%.17g', $coefficient) . '*'
                . $term['name'] . '(' . $term['argument'] . '))';
        }

        return '(' . \implode('+', $sumSource) . ')=' . $targetSource;
    }

    /**
     * @return array{
     *     factors: list<array{name: 'sin'|'cos', argument: string}>,
     *     coefficient: float,
     * }|null
     */
    private function flattenTrigonometricProduct(
        Node $node,
        string $source,
        int $sourceOffset,
        PolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $form = $this->flattenTrigonometricProduct($node->operand, $source, $sourceOffset, $extractor);
            if ($form === null) {
                return null;
            }
            if ($node->operator === \MathPHP\Ast\UnaryOperator::Minus) {
                $form['coefficient'] *= -1.0;
            }

            return $form;
        }
        if ($node instanceof BinaryOperationNode) {
            if ($node->operator === BinaryOperator::Multiply) {
                $left = $this->flattenTrigonometricProduct($node->left, $source, $sourceOffset, $extractor);
                $right = $this->flattenTrigonometricProduct($node->right, $source, $sourceOffset, $extractor);
                if ($left === null || $right === null) {
                    return null;
                }

                return [
                    'factors' => [...$left['factors'], ...$right['factors']],
                    'coefficient' => $left['coefficient'] * $right['coefficient'],
                ];
            }
            if ($node->operator === BinaryOperator::Divide) {
                $numerator = $this->flattenTrigonometricProduct($node->left, $source, $sourceOffset, $extractor);
                $denominator = $this->flattenTrigonometricProduct($node->right, $source, $sourceOffset, $extractor);
                if (
                    $numerator === null
                    || $denominator === null
                    || $denominator['factors'] !== []
                    || $denominator['coefficient'] === 0.0
                ) {
                    return null;
                }
                $numerator['coefficient'] /= $denominator['coefficient'];

                return $numerator;
            }
            if ($node->operator === BinaryOperator::Power) {
                $base = $this->flattenTrigonometricProduct($node->left, $source, $sourceOffset, $extractor);
                $exponent = $this->extractPolynomial(
                    $extractor,
                    $node->right,
                    $node->right->span()->start,
                );
                if (
                    $base === null
                    || $base['factors'] === []
                    || $exponent === null
                    || \count($exponent) !== 1
                    || $exponent[0] < 2.0
                    || \floor($exponent[0]) !== $exponent[0]
                    || \count($base['factors']) * $exponent[0] > 9
                ) {
                    return null;
                }
                $coefficient = $base['coefficient'] ** $exponent[0];
                if (!\is_finite($coefficient)) {
                    return null;
                }

                return [
                    'factors' => \array_merge(...\array_fill(
                        0,
                        (int) $exponent[0],
                        $base['factors'],
                    )),
                    'coefficient' => $coefficient,
                ];
            }
        }
        if (
            $node instanceof FunctionCallNode
            && \in_array($node->name, ['sin', 'cos'], true)
            && \count($node->arguments) === 1
        ) {
            $argumentCoefficients = $this->extractPolynomial(
                $extractor,
                $node->arguments[0],
                $node->arguments[0]->span()->start,
            );
            if ($argumentCoefficients === null) {
                return null;
            }
            $span = $node->arguments[0]->span();

            return [
                'factors' => [[
                    'name' => $node->name,
                    'argument' => \substr($source, $span->start - $sourceOffset, $span->end - $span->start),
                ]],
                'coefficient' => 1.0,
            ];
        }

        $constant = $this->extractPolynomial($extractor, $node, $node->span()->start);
        if ($constant === null || \count($constant) !== 1) {
            return null;
        }

        return ['factors' => [], 'coefficient' => $constant[0]];
    }

    /**
     * Isolate nonzero levels of sine/cosine equations using the first two harmonics.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineHarmonicPairEquation(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof BinaryOperationNode && !$this->containsVariable($right, $variable)) {
            $harmonics = $left;
            $constant = $right;
        } elseif (
            $right instanceof BinaryOperationNode
            && !$this->containsVariable($left, $variable)
        ) {
            $harmonics = $right;
            $constant = $left;
        } else {
            return null;
        }
        if (!\in_array($harmonics->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            return null;
        }

        $first = $this->unwrapGrouping($harmonics->left);
        $second = $this->unwrapGrouping($harmonics->right);
        if (
            !$first instanceof FunctionCallNode
            || !$second instanceof FunctionCallNode
            || $first->name !== $second->name
            || !\in_array($first->name, ['sin', 'cos'], true)
            || \count($first->arguments) !== 1
            || \count($second->arguments) !== 1
        ) {
            return null;
        }

        $firstArgument = $this->extractPolynomial(
            $extractor,
            $first->arguments[0],
            $first->arguments[0]->span()->start,
        );
        $secondArgument = $this->extractPolynomial(
            $extractor,
            $second->arguments[0],
            $second->arguments[0]->span()->start,
        );
        $target = $this->extractPolynomial($extractor, $constant, $constant->span()->start);
        if (
            $firstArgument === null
            || $secondArgument === null
            || \count($firstArgument) !== 2
            || \count($secondArgument) !== 2
            || $target === null
            || \count($target) !== 1
            || $target[0] === 0.0
            || $firstArgument[1] === 0.0
            || $secondArgument[1] === 0.0
        ) {
            return null;
        }

        $ratio = \abs($firstArgument[1] / $secondArgument[1]);
        $orders = $this->rationalHarmonicOrders($ratio, $options->maxPolynomialDegree);
        if ($orders === null || $orders[0] === $orders[1]) {
            return null;
        }
        [$firstOrder, $secondOrder] = $orders;
        $baseSlope = (
            (\abs($firstArgument[1]) / $firstOrder)
            + (\abs($secondArgument[1]) / $secondOrder)
        ) / 2.0;
        if (!\is_finite($baseSlope) || $baseSlope === 0.0) {
            return null;
        }
        $firstFrequency = $firstArgument[1] < 0.0 ? -$firstOrder : $firstOrder;
        $secondFrequency = $secondArgument[1] < 0.0 ? -$secondOrder : $secondOrder;
        $harmonicSign = $harmonics->operator === BinaryOperator::Add ? 1.0 : -1.0;
        $targetLevel = $target[0];
        if (!\is_finite($targetLevel) || \abs($targetLevel) > 2.0) {
            return [];
        }
        $firstPhase = \fmod($firstArgument[0], 2.0 * \M_PI);
        $secondPhase = \fmod($secondArgument[0], 2.0 * \M_PI);
        $firstPhaseSine = \sin($firstPhase);
        $firstPhaseCosine = \cos($firstPhase);
        $secondPhaseSine = \sin($secondPhase);
        $secondPhaseCosine = \cos($secondPhase);
        $directCosine = $first->name === 'cos'
            && \abs($firstPhaseSine) <= 32.0 * \PHP_FLOAT_EPSILON
            && \abs($secondPhaseSine) <= 32.0 * \PHP_FLOAT_EPSILON;
        $maximumOrder = \max($firstOrder, $secondOrder);
        $polynomialDegree = $directCosine ? $maximumOrder : 2 * $maximumOrder;
        if (
            $polynomialDegree > $options->maxPolynomialDegree
            || !\is_finite($firstPhaseSine)
            || !\is_finite($secondPhaseSine)
        ) {
            return null;
        }

        $firstCosineHarmonic = $this->chebyshevPolynomial($firstOrder, false);
        $secondCosineHarmonic = $this->chebyshevPolynomial($secondOrder, false);
        $firstSineHarmonic = $this->chebyshevPolynomial($firstOrder - 1, true);
        $secondSineHarmonic = $this->chebyshevPolynomial($secondOrder - 1, true);
        if ($directCosine) {
            $term = $this->addPolynomials(
                $this->scaledPolynomial($firstCosineHarmonic, $firstPhaseCosine),
                $this->scaledPolynomial(
                    $secondCosineHarmonic,
                    $harmonicSign * $secondPhaseCosine,
                ),
            );
            $coefficients = $this->addPolynomials($term, [$targetLevel], -1.0);
        } else {
            if ($first->name === 'sin') {
                $sineCoefficient = $this->addPolynomials(
                    $this->scaledPolynomial(
                        $firstSineHarmonic,
                        $firstPhaseCosine * ($firstFrequency < 0 ? -1.0 : 1.0),
                    ),
                    $this->scaledPolynomial(
                        $secondSineHarmonic,
                        $harmonicSign
                            * $secondPhaseCosine
                            * ($secondFrequency < 0 ? -1.0 : 1.0),
                    ),
                );
                $otherTerm = $this->addPolynomials(
                    $this->scaledPolynomial($firstCosineHarmonic, $firstPhaseSine),
                    $this->scaledPolynomial(
                        $secondCosineHarmonic,
                        $harmonicSign * $secondPhaseSine,
                    ),
                );
            } else {
                $sineCoefficient = $this->addPolynomials(
                    $this->scaledPolynomial(
                        $firstSineHarmonic,
                        -$firstPhaseSine * ($firstFrequency < 0 ? -1.0 : 1.0),
                    ),
                    $this->scaledPolynomial(
                        $secondSineHarmonic,
                        -$harmonicSign
                            * $secondPhaseSine
                            * ($secondFrequency < 0 ? -1.0 : 1.0),
                    ),
                );
                $otherTerm = $this->addPolynomials(
                    $this->scaledPolynomial($firstCosineHarmonic, $firstPhaseCosine),
                    $this->scaledPolynomial(
                        $secondCosineHarmonic,
                        $harmonicSign * $secondPhaseCosine,
                    ),
                );
            }
            $rightSide = $this->addPolynomials([$targetLevel], $otherTerm, -1.0);
            $leftSquare = $this->multiplyPolynomials($sineCoefficient, $sineCoefficient);
            $leftTerm = [];
            for ($degree = 0; $degree < \count($leftSquare) + 2; ++$degree) {
                $leftTerm[] = ($leftSquare[$degree] ?? 0.0) - ($leftSquare[$degree - 2] ?? 0.0);
            }
            $rightSquare = $this->multiplyPolynomials($rightSide, $rightSide);
            $coefficients = $this->addPolynomials($leftTerm, $rightSquare, -1.0);
        }
        foreach ($coefficients as $coefficient) {
            if (!\is_finite($coefficient)) {
                return null;
            }
        }

        $polynomialSolver = new PolynomialSolver();
        $polynomialOptions = $this->polynomialIsolationOptions(
            $options,
            64.0 * \PHP_FLOAT_EPSILON,
        );
        $cosineLevels = $polynomialSolver->solve(
            $coefficients,
            -1.0,
            1.0,
            fn (float $value): ?float => $polynomialSolver->evaluatePolynomial($coefficients, $value),
            $polynomialOptions,
        );
        if ($cosineLevels === null) {
            return null;
        }

        $argumentAtLower = $baseSlope * $lowerBound;
        $argumentAtUpper = $baseSlope * $upperBound;
        if (!\is_finite($argumentAtLower) || !\is_finite($argumentAtUpper)) {
            return null;
        }
        $argumentLower = \min($argumentAtLower, $argumentAtUpper);
        $argumentUpper = \max($argumentAtLower, $argumentAtUpper);
        $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        $positionTolerance = $options->positionTolerance($lowerBound, $upperBound);
        $solutions = [];
        $candidateCount = 0;
        foreach ($cosineLevels as $cosineLevel) {
            $cosine = \max(-1.0, \min(1.0, $cosineLevel->value));
            if ($directCosine) {
                $principal = \acos($cosine);
                $phases = [$principal, -$principal];
            } else {
                $sineCoefficientValue = $this->polynomialValue($sineCoefficient, $cosine);
                $otherTermValue = $this->polynomialValue($otherTerm, $cosine);
                if ($sineCoefficientValue === null || $otherTermValue === null) {
                    return null;
                }
                $sine = $targetLevel - $otherTermValue;
                if (
                    \abs($sineCoefficientValue)
                    <= 32.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($targetLevel), \abs($otherTermValue))
                ) {
                    if (
                        \abs($sine)
                        > $options->residualTolerance * \max(1.0, \abs($targetLevel))
                    ) {
                        continue;
                    }
                    $principal = \acos($cosine);
                    $phases = [$principal, -$principal];
                } else {
                    $sine /= $sineCoefficientValue;
                    if (!\is_finite($sine) || \abs($sine) > 1.0 + 1.0E-10) {
                        continue;
                    }
                    $phase = \atan2(\max(-1.0, \min(1.0, $sine)), $cosine);
                    $phases = [$phase];
                }
            }

            foreach ($phases as $phase) {
                $period = 2.0 * \M_PI;
                $firstPeriod = \ceil(($argumentLower - $phase - $angleTolerance) / $period);
                $lastPeriod = \floor(($argumentUpper - $phase + $angleTolerance) / $period);
                if ($lastPeriod < $firstPeriod) {
                    continue;
                }
                if (
                    $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                    || \abs($firstPeriod) > 4_503_599_627_370_496.0
                    || \abs($lastPeriod) > 4_503_599_627_370_496.0
                ) {
                    return null;
                }
                for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        return null;
                    }
                    $candidate = ($phase + ($periodIndex * $period)) / $baseSlope;
                    if (
                        !\is_finite($candidate)
                        || $candidate < $lowerBound - $positionTolerance
                        || $candidate > $upperBound + $positionTolerance
                    ) {
                        continue;
                    }
                    $candidate = \max($lowerBound, \min($upperBound, $candidate));
                    $residual = $residualAt($candidate);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return null;
                    }
                    $firstPhaseAtCandidate = $firstArgument[0]
                        + ($firstArgument[1] * $candidate);
                    $secondPhaseAtCandidate = $secondArgument[0]
                        + ($secondArgument[1] * $candidate);
                    $firstDerivative = $first->name === 'sin'
                        ? $firstArgument[1] * \cos($firstPhaseAtCandidate)
                        : -$firstArgument[1] * \sin($firstPhaseAtCandidate);
                    $secondDerivative = $second->name === 'sin'
                        ? $secondArgument[1] * \cos($secondPhaseAtCandidate)
                        : -$secondArgument[1] * \sin($secondPhaseAtCandidate);
                    $equationDerivative = $firstDerivative + ($harmonicSign * $secondDerivative);
                    $stationaryTolerance = \sqrt(\PHP_FLOAT_EPSILON)
                        * \max(1.0, \abs($firstArgument[1]), \abs($secondArgument[1]));
                    $roundoffResidualTolerance = 64.0 * \PHP_FLOAT_EPSILON
                        * \max(1.0, \abs($targetLevel), 2.0);
                    if (
                        \abs($equationDerivative) <= $stationaryTolerance
                        && \abs($residual) > $roundoffResidualTolerance
                    ) {
                        return null;
                    }
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($residual), 0),
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @return list<float>
     */
    private function chebyshevPolynomial(int $degree, bool $secondKind): array
    {
        if ($degree === 0) {
            return [1.0];
        }
        $previous = [1.0];
        $current = $secondKind ? [0.0, 2.0] : [0.0, 1.0];
        for ($order = 2; $order <= $degree; ++$order) {
            $next = \array_fill(0, \count($current) + 1, 0.0);
            foreach ($current as $power => $coefficient) {
                $next[$power + 1] += 2.0 * $coefficient;
            }
            foreach ($previous as $power => $coefficient) {
                $next[$power] -= $coefficient;
            }
            $previous = $current;
            $current = $next;
        }

        return \array_values($current);
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>
     */
    private function multiplyPolynomials(array $left, array $right): array
    {
        $product = \array_fill(0, \count($left) + \count($right) - 1, 0.0);
        foreach ($left as $leftPower => $leftCoefficient) {
            foreach ($right as $rightPower => $rightCoefficient) {
                $product[$leftPower + $rightPower] += $leftCoefficient * $rightCoefficient;
            }
        }

        return \array_values($product);
    }

    private function polynomialIsolationOptions(
        SolverOptions $options,
        ?float $residualTolerance = null,
    ): SolverOptions {
        return new SolverOptions(
            scanSteps: \max(256, $options->scanSteps),
            maxIterations: $options->maxIterations,
            absoluteTolerance: $options->absoluteTolerance,
            relativeTolerance: $options->relativeTolerance,
            residualTolerance: $residualTolerance === null
                ? $options->residualTolerance
                : \min($options->residualTolerance, $residualTolerance),
            maxPolynomialDegree: $options->maxPolynomialDegree,
        );
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>
     */
    private function addPolynomials(array $left, array $right, float $rightScale = 1.0): array
    {
        $sum = [];
        $length = \max(\count($left), \count($right));
        for ($degree = 0; $degree < $length; ++$degree) {
            $sum[] = ($left[$degree] ?? 0.0) + ($rightScale * ($right[$degree] ?? 0.0));
        }

        return $sum;
    }

    /**
     * @param list<float> $coefficients
     * @return list<float>
     */
    private function scaledPolynomial(array $coefficients, float $scale): array
    {
        return \array_map(
            static fn (float $coefficient): float => $coefficient * $scale,
            $coefficients,
        );
    }

    /**
     * @return array{int, int}|null Reduced numerator/denominator for the positive ratio.
     */
    private function rationalHarmonicOrders(float $ratio, int $maximumOrder): ?array
    {
        if (!\is_finite($ratio) || $ratio <= 0.0) {
            return null;
        }
        for ($denominator = 1; $denominator <= $maximumOrder; ++$denominator) {
            $numerator = (int) \round($ratio * $denominator);
            if ($numerator < 1 || $numerator > $maximumOrder) {
                continue;
            }
            $left = $numerator;
            $right = $denominator;
            while ($right !== 0) {
                [$left, $right] = [$right, $left % $right];
            }
            if (
                $left === 1
                && $this->approximatelyEqual($ratio, $numerator / $denominator)
            ) {
                return [$numerator, $denominator];
            }
        }

        return null;
    }

    private function approximatelyEqual(float $left, float $right): bool
    {
        return \is_finite($left)
            && \is_finite($right)
            && \abs($left - $right)
                <= 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($left), \abs($right));
    }

    private function hasInfiniteRootsFromAffineTrigonometricSumToProduct(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof BinaryOperationNode && !$this->containsVariable($right, $variable)) {
            $sum = $left;
            $constant = $right;
        } elseif ($right instanceof BinaryOperationNode && !$this->containsVariable($left, $variable)) {
            $sum = $right;
            $constant = $left;
        } else {
            return false;
        }
        if (!\in_array($sum->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            return false;
        }

        $first = $this->unwrapGrouping($sum->left);
        $second = $this->unwrapGrouping($sum->right);
        if (
            !$first instanceof FunctionCallNode
            || !$second instanceof FunctionCallNode
            || $first->name !== $second->name
            || !\in_array($first->name, ['sin', 'cos'], true)
            || !$evaluationOptions->functions->isBuiltIn($first->name)
            || \count($first->arguments) !== 1
            || \count($second->arguments) !== 1
        ) {
            return false;
        }

        $target = $this->extractPolynomial($extractor, $constant, $constant->span()->start);
        if ($target === null || \count($target) !== 1 || $target[0] !== 0.0) {
            return false;
        }
        foreach ([$first->arguments[0], $second->arguments[0]] as $phase) {
            $coefficients = $this->extractPolynomial($extractor, $phase, $phase->span()->start);
            if ($coefficients === null || \count($coefficients) > 2) {
                return false;
            }
            if (($coefficients[1] ?? 0.0) !== 0.0) {
                return true;
            }
        }

        return false;
    }

    /**
     * Solve zero-level sums and differences of two affine sine or cosine terms.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineTrigonometricSumToProduct(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof BinaryOperationNode && !$this->containsVariable($right, $variable)) {
            $sum = $left;
            $constant = $right;
        } elseif (
            $right instanceof BinaryOperationNode
            && !$this->containsVariable($left, $variable)
        ) {
            $sum = $right;
            $constant = $left;
        } else {
            return null;
        }
        if (!\in_array($sum->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)) {
            return null;
        }

        $first = $this->unwrapGrouping($sum->left);
        $second = $this->unwrapGrouping($sum->right);
        $target = $this->extractPolynomial($extractor, $constant, $constant->span()->start);
        if (
            !$first instanceof FunctionCallNode
            || !$second instanceof FunctionCallNode
            || $first->name !== $second->name
            || !\in_array($first->name, ['sin', 'cos'], true)
            || \count($first->arguments) !== 1
            || \count($second->arguments) !== 1
            || $target === null
            || \count($target) !== 1
        ) {
            return null;
        }

        $firstArgument = $this->extractPolynomial(
            $extractor,
            $first->arguments[0],
            $first->arguments[0]->span()->start,
        );
        $secondArgument = $this->extractPolynomial(
            $extractor,
            $second->arguments[0],
            $second->arguments[0]->span()->start,
        );
        if (
            $firstArgument === null
            || $secondArgument === null
            || \count($firstArgument) !== 2
            || \count($secondArgument) !== 2
        ) {
            return null;
        }

        $sumSlope = ($firstArgument[1] + $secondArgument[1]) / 2.0;
        $sumIntercept = ($firstArgument[0] + $secondArgument[0]) / 2.0;
        $differenceSlope = ($firstArgument[1] - $secondArgument[1]) / 2.0;
        $differenceIntercept = ($firstArgument[0] - $secondArgument[0]) / 2.0;
        if (
            !\is_finite($sumSlope)
            || !\is_finite($sumIntercept)
            || !\is_finite($differenceSlope)
            || !\is_finite($differenceIntercept)
        ) {
            return null;
        }

        $isSine = $first->name === 'sin';
        $isAddition = $sum->operator === BinaryOperator::Add;
        $factorSign = 1.0;
        if ($isSine && $isAddition) {
            $factors = [
                [$sumSlope, $sumIntercept, false],
                [$differenceSlope, $differenceIntercept, true],
            ];
        } elseif ($isSine) {
            $factors = [
                [$sumSlope, $sumIntercept, true],
                [$differenceSlope, $differenceIntercept, false],
            ];
        } elseif ($isAddition) {
            $factors = [
                [$sumSlope, $sumIntercept, true],
                [$differenceSlope, $differenceIntercept, true],
            ];
        } else {
            $factorSign = -1.0;
            $factors = [
                [$sumSlope, $sumIntercept, false],
                [$differenceSlope, $differenceIntercept, false],
            ];
        }

        $targetLevel = $target[0];
        $constantFactors = \array_filter($factors, static fn (array $factor): bool => $factor[0] === 0.0);
        if (\count($constantFactors) === 2) {
            $constantValue = 2.0 * $factorSign;
            foreach ($constantFactors as [, $intercept, $isCosine]) {
                $constantValue *= $isCosine ? \cos($intercept) : \sin($intercept);
            }
            if (!\is_finite($constantValue)) {
                return null;
            }
            $residual = $residualAt($lowerBound);
            if (
                $residual !== null
                && $this->isResidualAcceptableAt(
                    $lowerBound,
                    $residual,
                    $candidateScaleAt,
                    $options,
                )
            ) {
                throw new \DomainException(
                    'Equation has every real number as a solution and cannot be returned as a finite root list.',
                );
            }

            return [];
        }
        if (\count($constantFactors) === 1) {
            [, $constantIntercept, $constantIsCosine] = \array_values($constantFactors)[0];
            $phase = $constantIsCosine ? \M_PI / 2.0 : 0.0;
            $periodIndex = ($constantIntercept - $phase) / \M_PI;
            if (
                \is_finite($periodIndex)
                && \abs($periodIndex - \round($periodIndex))
                    <= 8.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($periodIndex))
            ) {
                return $targetLevel === 0.0
                    ? throw new \DomainException(
                        'Equation has every real number as a solution and cannot be returned as a finite root list.',
                    )
                    : [];
            }
            $constantValue = $constantIsCosine
                ? \cos($constantIntercept)
                : \sin($constantIntercept);
            if ($constantValue === 0.0 || !\is_finite($constantValue)) {
                return $targetLevel === 0.0
                    ? throw new \DomainException(
                        'Equation has every real number as a solution and cannot be returned as a finite root list.',
                    )
                    : [];
            }
            $targetLevel /= 2.0 * $factorSign * $constantValue;
            if (!\is_finite($targetLevel)) {
                return [];
            }
            $factorsToSolve = \array_values(\array_filter(
                $factors,
                static fn (array $factor): bool => $factor[0] !== 0.0,
            ));
        } elseif ($targetLevel === 0.0) {
            $factorsToSolve = $factors;
        } else {
            return null;
        }

        $solutions = [];
        $candidateCount = 0;
        $positionTolerance = $options->positionTolerance($lowerBound, $upperBound);
        foreach ($factorsToSolve as [$slope, $intercept, $isCosine]) {
            if ($isCosine) {
                if (\abs($targetLevel) > 1.0) {
                    return [];
                }
                $principal = \acos(\max(-1.0, \min(1.0, $targetLevel)));
                $phases = [$principal, -$principal];
            } else {
                if (\abs($targetLevel) > 1.0) {
                    return [];
                }
                $principal = \asin(\max(-1.0, \min(1.0, $targetLevel)));
                $phases = [$principal, \M_PI - $principal];
            }
            $angleAtLower = ($slope * $lowerBound) + $intercept;
            $angleAtUpper = ($slope * $upperBound) + $intercept;
            if (!\is_finite($angleAtLower) || !\is_finite($angleAtUpper)) {
                return null;
            }
            $angleLower = \min($angleAtLower, $angleAtUpper);
            $angleUpper = \max($angleAtLower, $angleAtUpper);
            $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
                * \max(1.0, \abs($angleLower), \abs($angleUpper));
            $period = 2.0 * \M_PI;
            foreach ($phases as $phase) {
                $firstPeriod = \ceil(($angleLower - $phase - $angleTolerance) / $period);
                $lastPeriod = \floor(($angleUpper - $phase + $angleTolerance) / $period);
                if ($lastPeriod < $firstPeriod) {
                    continue;
                }
                if (
                    $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                    || \abs($firstPeriod) > 4_503_599_627_370_496.0
                    || \abs($lastPeriod) > 4_503_599_627_370_496.0
                ) {
                    return null;
                }
                for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        return null;
                    }
                    $candidate = (($phase + ($periodIndex * $period)) - $intercept) / $slope;
                    if (
                        !\is_finite($candidate)
                        || $candidate < $lowerBound - $positionTolerance
                        || $candidate > $upperBound + $positionTolerance
                    ) {
                        continue;
                    }
                    $candidate = \max($lowerBound, \min($upperBound, $candidate));
                    $residual = $residualAt($candidate);
                    if (
                        $residual === null
                        || !$this->isResidualAcceptableAt(
                            $candidate,
                            $residual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        return null;
                    }
                    $this->addDistinctSolution(
                        $solutions,
                        new EquationSolution($candidate, \abs($residual), 0),
                    );
                }
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Reduce sums of sine and cosine terms that share any bounded phase.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveSharedPhaseTrigonometricCombination(
        string $leftSource,
        string $rightSource,
        Node $left,
        Node $right,
        int $rightSourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $terms = [];
        foreach (
            [[$left, 1.0, $leftSource, 0], [$right, -1.0, $rightSource, $rightSourceOffset]]
            as [$side, $sideSign, $sideSource, $sideSourceOffset]
        ) {
            $sideTerms = [];
            $this->flattenAdditiveTerms($side, $sideSign, $sideTerms);
            foreach ($sideTerms as [$term, $sign]) {
                $terms[] = [$term, $sign, $sideSource, $sideSourceOffset];
            }
        }
        $phaseNode = null;
        $phaseSource = null;
        $sineCoefficient = 0.0;
        $cosineCoefficient = 0.0;
        $constant = 0.0;
        $trigonometricTermCount = 0;
        foreach ($terms as [$term, $sign, $source, $sourceOffset]) {
            $factors = [];
            $this->flattenProductFactors($term, $factors);
            $function = null;
            $coefficient = $sign;
            foreach ($factors as $factor) {
                $factor = $this->unwrapGrouping($factor);
                if (
                    $factor instanceof FunctionCallNode
                    && \in_array($factor->name, ['sin', 'cos'], true)
                    && \count($factor->arguments) === 1
                    && $this->containsVariable($factor->arguments[0], $variable)
                ) {
                    if ($function !== null) {
                        return null;
                    }
                    $function = $factor;
                    continue;
                }
                $constantFactor = $this->extractPolynomial(
                    $extractor,
                    $factor,
                    $factor->span()->start,
                );
                if (
                    $constantFactor === null
                    || \count($constantFactor) !== 1
                    || !\is_finite($constantFactor[0])
                ) {
                    return null;
                }
                $coefficient *= $constantFactor[0];
                if (!\is_finite($coefficient)) {
                    return null;
                }
            }

            if ($function === null) {
                $constant += $coefficient;
                if (!\is_finite($constant)) {
                    return null;
                }
                continue;
            }

            $argument = $function->arguments[0];
            if (
                ($phaseNode !== null && !$this->sameExpression($phaseNode, $argument))
                || !$this->containsVariable($argument, $variable)
            ) {
                return null;
            }
            if ($phaseNode === null) {
                $span = $argument->span();
                $phaseSource = \substr($source, $span->start, $span->end - $span->start);
                $phaseNode = $argument;
            }
            if ($function->name === 'sin') {
                $sineCoefficient += $coefficient;
            } else {
                $cosineCoefficient += $coefficient;
            }
            if (!\is_finite($sineCoefficient) || !\is_finite($cosineCoefficient)) {
                return null;
            }
            ++$trigonometricTermCount;
        }
        if ($phaseNode === null || $trigonometricTermCount === 0) {
            return null;
        }

        $target = -$constant;
        $amplitude = \hypot($sineCoefficient, $cosineCoefficient);
        if ($amplitude === 0.0) {
            if ($target === 0.0) {
                throw new InfiniteSolutionSetException(
                    'Equation has infinitely many solutions in the requested interval.',
                );
            }

            return [];
        }

        $normalizedTarget = $target / $amplitude;
        if (!\is_finite($normalizedTarget) || \abs($normalizedTarget) > 1.0) {
            return [];
        }
        $phase = \atan2($cosineCoefficient, $sineCoefficient);
        $principal = \asin(\max(-1.0, \min(1.0, $normalizedTarget)));
        $phaseLevels = [$principal - $phase, \M_PI - $principal - $phase];
        $range = $this->boundedExpressionRange(
            $phaseNode,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        if (
            $range === null
            || !\is_finite($range[0])
            || !\is_finite($range[1])
        ) {
            return null;
        }

        if (
            $phaseSource === null
            || $phaseSource === ''
            || \strlen($phaseSource) + 24 > $evaluationOptions->limits->maxExpressionLength
        ) {
            return null;
        }
        $period = 2.0 * \M_PI;
        $argumentLower = \min($range[0], $range[1]);
        $argumentUpper = \max($range[0], $range[1]);
        $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        $affinePhase = $extractor->extract($phaseNode);
        if ($affinePhase !== null && (\count($affinePhase) !== 2 || $affinePhase[1] === 0.0)) {
            $affinePhase = null;
        }
        $solutions = [];
        $levelCount = 0;
        $candidateCount = 0;
        foreach ($phaseLevels as $phaseLevel) {
            $firstPeriod = \ceil(($argumentLower - $phaseLevel - $angleTolerance) / $period);
            $lastPeriod = \floor(($argumentUpper - $phaseLevel + $angleTolerance) / $period);
            if ($lastPeriod < $firstPeriod) {
                continue;
            }
            if (
                $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                || \abs($firstPeriod) > 4_503_599_627_370_496.0
                || \abs($lastPeriod) > 4_503_599_627_370_496.0
            ) {
                return null;
            }

            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                if (++$levelCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $level = $phaseLevel + ($periodIndex * $period);
                if ($affinePhase !== null) {
                    $phaseCandidates = [new EquationSolution(
                        ($level - $affinePhase[0]) / $affinePhase[1],
                        0.0,
                        0,
                    )];
                } else {
                    $levelEquation = $phaseSource . '=' . \sprintf('%.17g', $level);
                    if (\strlen($levelEquation) > $evaluationOptions->limits->maxExpressionLength) {
                        return null;
                    }
                    $phaseCandidates = $this->solve(
                        $levelEquation,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $parameters,
                        $evaluationOptions,
                        $options,
                    );
                }
                foreach ($phaseCandidates as $candidate) {
                    if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                        return null;
                    }
                    $residual = $residualAt($candidate->value);
                    if ($residual === null) {
                        return null;
                    }
                    $solutionValue = $candidate->value;
                    $solutionResidual = $residual;
                    if (
                        !$this->isResidualAcceptableAt(
                            $solutionValue,
                            $solutionResidual,
                            $candidateScaleAt,
                            $options,
                        )
                    ) {
                        foreach ([-1, 1] as $direction) {
                            $position = $candidate->value;
                            for ($step = 0; $step < 16; ++$step) {
                                $neighbor = $this->adjacentFloat($position, $direction);
                                if (
                                    $neighbor === null
                                    || $neighbor < $lowerBound
                                    || $neighbor > $upperBound
                                ) {
                                    break;
                                }
                                $neighborResidual = $residualAt($neighbor);
                                if (
                                    $neighborResidual === null
                                    || \abs($neighborResidual) >= \abs($solutionResidual)
                                ) {
                                    break;
                                }
                                $solutionValue = $neighbor;
                                $solutionResidual = $neighborResidual;
                                $position = $neighbor;
                            }
                        }
                        if (
                            !$this->isResidualAcceptableAt(
                                $solutionValue,
                                $solutionResidual,
                                $candidateScaleAt,
                                $options,
                            )
                            && !$this->isCandidateAtFloatingPointRootResolution(
                                $solutionValue,
                                $solutionResidual,
                                $residualAt,
                            )
                        ) {
                            return null;
                        }
                    }
                    $this->addDistinctRepresentableSolution(
                        $solutions,
                        new EquationSolution(
                            $solutionValue,
                            \abs($solutionResidual),
                            $candidate->iterations,
                        ),
                    );
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * Solve a sum or difference of sine and cosine terms sharing one affine argument.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAffineSineCosineCombination(
        Node $left,
        Node $right,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if ($left instanceof BinaryOperationNode && !$this->containsVariable($right, $variable)) {
            $combination = $left;
            $constant = $right;
        } elseif (
            $right instanceof BinaryOperationNode
            && !$this->containsVariable($left, $variable)
        ) {
            $combination = $right;
            $constant = $left;
        } else {
            return null;
        }
        $first = $this->unwrapGrouping($combination->left);
        $firstFunction = $first instanceof FunctionCallNode ? $first : null;
        $secondFunction = null;
        $doubleArgument = false;
        $doubleAngleTransform = 0;
        $isProduct = false;
        $sineCoefficient = 0.0;
        $cosineCoefficient = 0.0;
        if (
            \in_array($combination->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $second = $this->unwrapGrouping($combination->right);
            $secondFunction = $second instanceof FunctionCallNode ? $second : null;
            if (
                $firstFunction === null
                || $secondFunction === null
                || !\in_array($firstFunction->name, ['sin', 'cos'], true)
                || !\in_array($secondFunction->name, ['sin', 'cos'], true)
                || \count($firstFunction->arguments) !== 1
                || \count($secondFunction->arguments) !== 1
            ) {
                return null;
            }
            $sineCoefficient = $firstFunction->name === 'sin' ? 1.0 : 0.0;
            $cosineCoefficient = $firstFunction->name === 'cos' ? 1.0 : 0.0;
            $secondSign = $combination->operator === BinaryOperator::Add ? 1.0 : -1.0;
            if ($secondFunction->name === 'sin') {
                $sineCoefficient += $secondSign;
            } else {
                $cosineCoefficient += $secondSign;
            }
        } elseif ($combination->operator === BinaryOperator::Multiply) {
            $second = $this->unwrapGrouping($combination->right);
            $secondFunction = $second instanceof FunctionCallNode ? $second : null;
            if (
                $firstFunction === null
                || $secondFunction === null
                || !\in_array($firstFunction->name, ['sin', 'cos'], true)
                || !\in_array($secondFunction->name, ['sin', 'cos'], true)
                || \count($firstFunction->arguments) !== 1
                || \count($secondFunction->arguments) !== 1
            ) {
                return null;
            }
            $isProduct = true;
            $doubleArgument = true;
        } elseif ($combination->operator === BinaryOperator::Power) {
            $exponent = $this->extractPolynomial(
                $extractor,
                $combination->right,
                $combination->right->span()->start,
            );
            if (
                $firstFunction === null
                || !\in_array($firstFunction->name, ['sin', 'cos'], true)
                || \count($firstFunction->arguments) !== 1
                || $exponent !== [2.0]
            ) {
                return null;
            }
            $cosineCoefficient = 1.0;
            $doubleArgument = true;
        } else {
            return null;
        }

        $firstArgument = $this->extractPolynomial(
            $extractor,
            $firstFunction->arguments[0],
            $firstFunction->arguments[0]->span()->start,
        );
        $secondArgument = $secondFunction === null
            ? $firstArgument
            : $this->extractPolynomial(
                $extractor,
                $secondFunction->arguments[0],
                $secondFunction->arguments[0]->span()->start,
            );
        $targetCoefficients = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if (
            $firstArgument === null
            || \count($firstArgument) !== 2
            || $firstArgument[1] === 0.0
            || $secondArgument === null
            || \count($secondArgument) !== 2
            || $targetCoefficients === null
            || \count($targetCoefficients) !== 1
        ) {
            return null;
        }

        $oppositeArgument = \array_map(
            static fn (float $coefficient): float => -$coefficient,
            $firstArgument,
        );
        if ($isProduct) {
            $sameArgument = $firstArgument === $secondArgument;
            $oppositeArguments = $oppositeArgument === $secondArgument;
            if (!$sameArgument && !$oppositeArguments) {
                return null;
            }
            if ($firstFunction->name === 'sin' && $secondFunction->name === 'sin') {
                $cosineCoefficient = 1.0;
                $doubleAngleTransform = $sameArgument ? 1 : 5;
            } elseif ($firstFunction->name === 'cos' && $secondFunction->name === 'cos') {
                $cosineCoefficient = 1.0;
                $doubleAngleTransform = 2;
            } elseif ($firstFunction->name === 'cos' && $oppositeArguments) {
                $sineCoefficient = -1.0;
                $doubleAngleTransform = 0;
            } else {
                $sineCoefficient = 1.0;
                $doubleAngleTransform = 0;
            }
        } elseif ($firstArgument !== $secondArgument) {
            return null;
        }

        $target = $targetCoefficients[0];
        if ($doubleArgument && !$isProduct) {
            $doubleAngleTransform = $firstFunction->name === 'sin' ? 1 : 2;
        }
        if ($doubleArgument) {
            $target = match ($doubleAngleTransform) {
                1 => 1.0 - (2.0 * $target),
                2 => (2.0 * $target) - 1.0,
                5 => 1.0 + (2.0 * $target),
                default => 2.0 * $target,
            };
            $firstArgument = \array_map(
                static fn (float $coefficient): float => 2.0 * $coefficient,
                $firstArgument,
            );
        }
        $amplitude = \hypot($sineCoefficient, $cosineCoefficient);
        if ($amplitude === 0.0) {
            if ($target === 0.0) {
                throw new \DomainException(
                    'Equation has every real number as a solution and cannot be returned as a finite root list.',
                );
            }

            return [];
        }
        $normalizedTarget = $target / $amplitude;
        if (!\is_finite($normalizedTarget) || \abs($normalizedTarget) > 1.0) {
            return [];
        }

        $phase = \atan2($cosineCoefficient, $sineCoefficient);
        $principal = \asin(\max(-1.0, \min(1.0, $normalizedTarget)));
        $phases = [$principal - $phase, \M_PI - $principal - $phase];
        $intercept = $firstArgument[0];
        $slope = $firstArgument[1];
        $argumentAtLower = ($slope * $lowerBound) + $intercept;
        $argumentAtUpper = ($slope * $upperBound) + $intercept;
        if (!\is_finite($argumentAtLower) || !\is_finite($argumentAtUpper)) {
            return null;
        }

        $argumentLower = \min($argumentAtLower, $argumentAtUpper);
        $argumentUpper = \max($argumentAtLower, $argumentAtUpper);
        $period = 2.0 * \M_PI;
        $angleTolerance = 8.0 * \PHP_FLOAT_EPSILON
            * \max(1.0, \abs($argumentLower), \abs($argumentUpper));
        $positionTolerance = $options->positionTolerance($lowerBound, $upperBound);
        $solutions = [];
        $candidateCount = 0;
        foreach ($phases as $anglePhase) {
            $firstPeriod = \ceil(($argumentLower - $anglePhase - $angleTolerance) / $period);
            $lastPeriod = \floor(($argumentUpper - $anglePhase + $angleTolerance) / $period);
            if (
                $lastPeriod < $firstPeriod
                || $lastPeriod - $firstPeriod + 1.0 > self::MAX_PERIODIC_ROOTS
                || \abs($firstPeriod) > 4_503_599_627_370_496.0
                || \abs($lastPeriod) > 4_503_599_627_370_496.0
            ) {
                if ($lastPeriod < $firstPeriod) {
                    continue;
                }

                return null;
            }
            for ($periodIndex = $firstPeriod; $periodIndex <= $lastPeriod; ++$periodIndex) {
                if (++$candidateCount > self::MAX_PERIODIC_ROOTS) {
                    return null;
                }
                $candidate = (($anglePhase + ($periodIndex * $period)) - $intercept) / $slope;
                if (
                    !\is_finite($candidate)
                    || $candidate < $lowerBound - $positionTolerance
                    || $candidate > $upperBound + $positionTolerance
                ) {
                    continue;
                }
                $candidate = \max($lowerBound, \min($upperBound, $candidate));
                $residual = $residualAt($candidate);
                if (
                    $residual === null
                    || !$this->isResidualAcceptableAt(
                        $candidate,
                        $residual,
                        $candidateScaleAt,
                        $options,
                    )
                ) {
                    return null;
                }
                $this->addDistinctSolution(
                    $solutions,
                    new EquationSolution($candidate, \abs($residual), 0),
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<float> $coefficients
     */
    private function polynomialValue(array $coefficients, float $value): ?float
    {
        $result = 0.0;
        for ($index = \count($coefficients) - 1; $index >= 0; --$index) {
            $result = ($result * $value) + $coefficients[$index];
            if (!\is_finite($result)) {
                return null;
            }
        }

        return $result;
    }

    /**
     * Include the polynomial's term magnitudes when validating its roots
     * against the separately evaluated expression, which may cancel differently.
     *
     * @param list<float> $coefficients
     * @param callable(float): ?float $candidateScaleAt
     */
    private function polynomialCandidateScaleAt(
        array $coefficients,
        callable $candidateScaleAt,
        float $value,
    ): ?float {
        $candidateScale = $candidateScaleAt($value);
        if ($candidateScale === null) {
            return null;
        }

        $polynomialMagnitude = 0.0;
        $power = 1.0;
        foreach ($coefficients as $coefficient) {
            $term = \abs($coefficient * $power);
            if (!\is_finite($term)) {
                return null;
            }
            $polynomialMagnitude += $term;
            if (!\is_finite($polynomialMagnitude)) {
                return null;
            }
            $power *= \abs($value);
            if (!\is_finite($power)) {
                return null;
            }
        }

        return \max($candidateScale, $polynomialMagnitude);
    }

    /**
     * @param list<float> $factorialOperand
     * @param array<string, int|float> $parameters
     * @return list<EquationSolution>
     */
    private function solvePolynomialFactorialDomain(
        Node $left,
        Node $right,
        int $rightOffset,
        string $variable,
        Node $factorialOperandNode,
        string $factorialOperandSource,
        array $factorialOperand,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): array {
        $maximum = $evaluationOptions->limits->maxFactorial;
        $degree = \count($factorialOperand) - 1;
        $factorialRoundingUlps = 4.0 * \max(1, $degree);
        $rootOptions = new SolverOptions(
            scanSteps: $solverOptions->scanSteps,
            maxIterations: $solverOptions->maxIterations,
            absoluteTolerance: \min(
                $solverOptions->absoluteTolerance,
                \PHP_FLOAT_EPSILON / 4.0,
            ),
            relativeTolerance: \min(
                $solverOptions->relativeTolerance,
                \PHP_FLOAT_EPSILON / 4.0,
            ),
            residualTolerance: \min(
                $solverOptions->residualTolerance,
                8.0 * \PHP_FLOAT_EPSILON,
            ),
            maxPolynomialDegree: $solverOptions->maxPolynomialDegree,
        );
        $solutions = [];
        for ($operand = 0; $operand <= $maximum; ++$operand) {
            $roots = [];
            if ($degree === 1) {
                $candidate = ($operand - $factorialOperand[0]) / $factorialOperand[1];
                if (\is_finite($candidate)) {
                    $roots[] = $candidate;
                }
            } else {
                $span = $factorialOperandNode->span();
                $operandExpression = \substr(
                    $factorialOperandSource,
                    $span->start,
                    $span->end - $span->start,
                );
                $isolated = $this->solve(
                    $operandExpression . '=' . $operand,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $rootOptions,
                );
                foreach ($isolated as $root) {
                    $roots[] = $root->value;
                }
            }

            foreach ($roots as $candidate) {
                if ($candidate < $lowerBound || $candidate > $upperBound) {
                    continue;
                }
                $variables = [...$parameters, $variable => $candidate];
                try {
                    $leftValue = $this->evaluateNode(
                        $left,
                        $variables,
                        $evaluationOptions,
                        $factorialRoundingUlps,
                    );
                } catch (EvaluationException $error) {
                    if ($this->mustPropagateEvaluationError($error)) {
                        throw $error;
                    }
                    continue;
                }
                try {
                    $rightValue = $this->evaluateNode(
                        $right,
                        $variables,
                        $evaluationOptions,
                        $factorialRoundingUlps,
                    );
                } catch (EvaluationException $error) {
                    if ($this->mustPropagateEvaluationError($error)) {
                        throw $this->shiftException($error, $rightOffset);
                    }
                    continue;
                }

                $residual = (float) $leftValue - (float) $rightValue;
                if (!\is_finite($residual)) {
                    continue;
                }
                $scale = \max(
                    \abs((float) $leftValue),
                    \abs((float) $rightValue),
                    \abs($residual),
                );
                if ($scale === 0.0) {
                    $scale = 1.0;
                }
                if (\abs($residual / $scale) <= $solverOptions->residualTolerance) {
                    $solutions[] = new EquationSolution(
                        $candidate,
                        \abs($residual),
                        0,
                    );
                }
            }
        }

        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );

        return $solutions;
    }

    /**
     * @param list<Node> $arguments
     */
    private function containsVariableInArguments(
        array $arguments,
        string $variable,
    ): bool {
        foreach ($arguments as $argument) {
            if ($this->containsVariable($argument, $variable)) {
                return true;
            }
        }

        return false;
    }

    /** @param list<Node> $arguments */
    private function containsNonIntegerNumberLiteralInArguments(array $arguments): bool
    {
        foreach ($arguments as $argument) {
            if ($this->containsNonIntegerNumberLiteral($argument)) {
                return true;
            }
        }

        return false;
    }

    /** @param list<Node> $arguments */
    private function containsUnderflowedNumberLiteralInArguments(array $arguments): bool
    {
        foreach ($arguments as $argument) {
            if ($this->containsUnderflowedNumberLiteral($argument)) {
                return true;
            }
        }

        return false;
    }

    private function samplePositionKey(float $position): string
    {
        return \sprintf('%.17g', $position);
    }

    /**
     * @param list<array{float, ?float}> $samples
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     */
    private function hasSampledZeroInterval(
        array $samples,
        callable $residualAt,
        callable $residualScaleAt,
    ): bool {
        foreach ($samples as $index => [$left, $leftResidual]) {
            if ($index + 1 >= \count($samples) || $leftResidual === null) {
                continue;
            }
            [$right, $rightResidual] = $samples[$index + 1];
            if (
                $rightResidual === null
                || $right <= $left
                || $right - $left
                    <= 8.0 * \sqrt(\PHP_FLOAT_EPSILON)
                        * \max(1.0, \abs($left), \abs($right))
                || !$this->isRoundoffZeroAt($left, $leftResidual, $residualScaleAt)
                || !$this->isRoundoffZeroAt($right, $rightResidual, $residualScaleAt)
            ) {
                continue;
            }

            $allInteriorChecksAreZero = true;
            foreach ([0.2718281828459045, 0.3819660112501051, 0.5, 0.6180339887498949] as $fraction) {
                $position = $left + (($right - $left) * $fraction);
                $residual = $residualAt($position);
                if (
                    $residual === null
                    || !$this->isRoundoffZeroAt($position, $residual, $residualScaleAt)
                ) {
                    $allInteriorChecksAreZero = false;
                    break;
                }
            }
            if ($allInteriorChecksAreZero) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param callable(float): ?float $residualScaleAt
     */
    private function isRoundoffZeroAt(
        float $position,
        float $residual,
        callable $residualScaleAt,
        float $epsilonFactor = 8.0,
    ): bool {
        $scale = $residualScaleAt($position);
        if ($scale === null) {
            return false;
        }

        return \abs($residual) <= $epsilonFactor * \PHP_FLOAT_EPSILON * $scale;
    }

    /**
     * Find branch crossings for piecewise functions in a general equation.
     *
     * @return list<string>
     */
    private function piecewiseBranchBoundaryEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->piecewiseBranchBoundaryEquations($node->left, $source, $sourceOffset, $variable),
                ...$this->piecewiseBranchBoundaryEquations($node->right, $source, $sourceOffset, $variable),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->piecewiseBranchBoundaryEquations($node->operand, $source, $sourceOffset, $variable);
        }
        if ($node instanceof GroupingNode) {
            return $this->piecewiseBranchBoundaryEquations($node->expression, $source, $sourceOffset, $variable);
        }
        if ($node instanceof FactorialNode) {
            return $this->piecewiseBranchBoundaryEquations($node->operand, $source, $sourceOffset, $variable);
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        $argumentSources = [];
        foreach ($node->arguments as $argument) {
            $span = $argument->span();
            $argumentSources[] = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);
            $equations = [
                ...$equations,
                ...$this->piecewiseBranchBoundaryEquations($argument, $source, $sourceOffset, $variable),
            ];
        }

        if ($node->name === 'abs' && isset($node->arguments[0], $argumentSources[0])) {
            if ($this->containsVariable($node->arguments[0], $variable)) {
                $equations[] = $argumentSources[0] . '=0';
            }
        } elseif (\in_array($node->name, ['min', 'max'], true)) {
            for ($first = 0, $count = \count($node->arguments); $first < $count; ++$first) {
                for ($second = $first + 1; $second < $count; ++$second) {
                    if (
                        !$this->containsVariable($node->arguments[$first], $variable)
                        && !$this->containsVariable($node->arguments[$second], $variable)
                    ) {
                        continue;
                    }
                    $equations[] = $argumentSources[$first] . '=' . $argumentSources[$second];
                }
            }
        }

        return $equations;
    }

    /** @return list<array{equation: string, numerator: Node, denominator: Node}> */
    private function variableDenominators(
        Node $node,
        string $source,
        string $variable,
        int $sourceOffset = 0,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            $equations = [];
            if (
                $node->operator->value === '/'
                && $this->containsVariable($node->right, $variable)
            ) {
                $denominator = \substr(
                    $source,
                    $node->right->span()->start - $sourceOffset,
                    $node->right->span()->end - $node->right->span()->start,
                );
                $equations[] = [
                    'equation' => $denominator . '=0',
                    'numerator' => $node->left,
                    'denominator' => $node->right,
                ];
            }

            return [
                ...$equations,
                ...$this->variableDenominators($node->left, $source, $variable, $sourceOffset),
                ...$this->variableDenominators($node->right, $source, $variable, $sourceOffset),
            ];
        }

        if ($node instanceof UnaryOperationNode) {
            return $this->variableDenominators($node->operand, $source, $variable, $sourceOffset);
        }
        if ($node instanceof GroupingNode) {
            return $this->variableDenominators($node->expression, $source, $variable, $sourceOffset);
        }
        if ($node instanceof FactorialNode) {
            return $this->variableDenominators($node->operand, $source, $variable, $sourceOffset);
        }
        if ($node instanceof FunctionCallNode) {
            $equations = [];
            foreach ($node->arguments as $argument) {
                $equations = [
                    ...$equations,
                    ...$this->variableDenominators($argument, $source, $variable, $sourceOffset),
                ];
            }

            return $equations;
        }

        return [];
    }

    /**
     * @return list<string>
     */
    private function betaIntegerSumEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->betaIntegerSumEquations(
                    $node->left,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
                ...$this->betaIntegerSumEquations(
                    $node->right,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
            ];
        }
        if (
            $node instanceof UnaryOperationNode
            || $node instanceof GroupingNode
            || $node instanceof FactorialNode
        ) {
            $child = match (true) {
                $node instanceof UnaryOperationNode => $node->operand,
                $node instanceof GroupingNode => $node->expression,
                default => $node->operand,
            };

            return $this->betaIntegerSumEquations(
                $child,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        foreach ($node->arguments as $argument) {
            $equations = [
                ...$equations,
                ...$this->betaIntegerSumEquations(
                    $argument,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
            ];
        }
        if (
            $node->name !== 'beta'
            || !isset($node->arguments[0], $node->arguments[1])
            || (!$this->containsVariable($node->arguments[0], $variable)
                && !$this->containsVariable($node->arguments[1], $variable))
        ) {
            return $equations;
        }

        $firstRange = $this->boundedExpressionRange(
            $node->arguments[0],
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        $secondRange = $this->boundedExpressionRange(
            $node->arguments[1],
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $options,
        );
        if (
            $firstRange === null
            || $secondRange === null
            || !\is_finite($firstRange[0])
            || !\is_finite($secondRange[0])
            || !\is_finite($firstRange[1])
            || !\is_finite($secondRange[1])
        ) {
            return $equations;
        }

        $minimumSum = \max(-342.0, $firstRange[0] + $secondRange[0]);
        $maximumSum = \min(0.0, $firstRange[1] + $secondRange[1]);
        $firstIntegerSum = (int) \ceil($minimumSum);
        $lastIntegerSum = (int) \floor($maximumSum);
        if ($firstIntegerSum > $lastIntegerSum) {
            return $equations;
        }
        if ($lastIntegerSum - $firstIntegerSum + 1 > self::MAX_DOMAIN_BOUNDARY_PROBES) {
            throw new \DomainException(
                'The beta-function integer-sum set exceeds the equation boundary limit.',
            );
        }

        $first = \substr(
            $source,
            $node->arguments[0]->span()->start - $sourceOffset,
            $node->arguments[0]->span()->end - $node->arguments[0]->span()->start,
        );
        $second = \substr(
            $source,
            $node->arguments[1]->span()->start - $sourceOffset,
            $node->arguments[1]->span()->end - $node->arguments[1]->span()->start,
        );
        for ($sum = $firstIntegerSum; $sum <= $lastIntegerSum; ++$sum) {
            $equations[] = '(' . $first . ')+(' . $second . ')=' . $sum;
        }

        return $equations;
    }

    /**
     * @return list<string>
     */
    private function gammaBoundaryEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $options,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->gammaBoundaryEquations(
                    $node->left,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
                ...$this->gammaBoundaryEquations(
                    $node->right,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->gammaBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->gammaBoundaryEquations(
                $node->expression,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->gammaBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $extractor,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        $argumentIndex = match ($node->name) {
            'gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma' => 0,
            'polygamma' => 1,
            default => null,
        };
        if (
            $argumentIndex !== null
            && isset($node->arguments[$argumentIndex])
            && $this->containsVariable($node->arguments[$argumentIndex], $variable)
        ) {
            $argument = $node->arguments[$argumentIndex];
            $range = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
            if (
                $range !== null
                && \is_finite($range[0])
                && \is_finite($range[1])
            ) {
                [$minimum, $maximum] = $range;
                $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($minimum), \abs($maximum));
                $expression = \substr(
                    $source,
                    $argument->span()->start - $sourceOffset,
                    $argument->span()->end - $argument->span()->start,
                );
                $firstPole = \ceil($minimum - $tolerance);
                $lastPole = \min(0.0, \floor($maximum + $tolerance));
                if ($firstPole <= $lastPole) {
                    if ($node->name === 'gamma' || $node->name === 'lgamma') {
                        $firstPole = \max(-171.0, $firstPole);
                    } elseif ($lastPole - $firstPole + 1.0 > self::MAX_DOMAIN_BOUNDARY_PROBES) {
                        throw new \DomainException(
                            'The polygamma-family pole set exceeds the equation boundary limit.',
                        );
                    }
                    if ($firstPole < \PHP_INT_MIN || $lastPole > \PHP_INT_MAX) {
                        throw new \DomainException(
                            'The polygamma-family pole set exceeds the equation boundary integer range.',
                        );
                    }
                    $firstPoleIndex = (int) $firstPole;
                    $lastPoleIndex = (int) $lastPole;
                    for ($pole = $firstPoleIndex; $pole <= $lastPoleIndex; ++$pole) {
                        $equations[] = $expression . '=' . (int) $pole;
                    }
                }
                if ($node->name === 'gamma' || $node->name === 'lgamma') {
                    foreach ([-171.0, 171.0] as $limit) {
                        if ($limit >= $minimum - $tolerance && $limit <= $maximum + $tolerance) {
                            $equations[] = $expression . '=' . $limit;
                        }
                    }
                }
            }
        }

        if ($node->name === 'beta') {
            foreach ($node->arguments as $argument) {
                if (!$this->containsVariable($argument, $variable)) {
                    continue;
                }
                $range = $this->boundedExpressionRange(
                    $argument,
                    $extractor,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                );
                if ($range === null || !\is_finite($range[0]) || !\is_finite($range[1])) {
                    continue;
                }

                [$minimum, $maximum] = $range;
                $tolerance = 8.0 * \PHP_FLOAT_EPSILON
                    * \max(1.0, \abs($minimum), \abs($maximum));
                $expression = \substr(
                    $source,
                    $argument->span()->start - $sourceOffset,
                    $argument->span()->end - $argument->span()->start,
                );
                $firstPole = \max(-171.0, \ceil($minimum - $tolerance));
                $lastPole = \min(0.0, \floor($maximum + $tolerance));
                if ($lastPole >= $firstPole) {
                    if ($lastPole - $firstPole + 1.0 > self::MAX_DOMAIN_BOUNDARY_PROBES) {
                        throw new \DomainException(
                            'The beta-function pole set exceeds the equation boundary limit.',
                        );
                    }
                    for ($pole = $firstPole; $pole <= $lastPole; ++$pole) {
                        $equations[] = $expression . '=' . (int) $pole;
                    }
                }
                $negativeRangeBoundary = -171.0;
                if (
                    $negativeRangeBoundary >= $minimum - $tolerance
                    && $negativeRangeBoundary <= $maximum + $tolerance
                ) {
                    $equations[] = $expression . '=' . $negativeRangeBoundary;
                }
            }

            if (\count($node->arguments) === 2) {
                $argumentRanges = [];
                $argumentSources = [];
                foreach ($node->arguments as $argument) {
                    $range = $this->boundedExpressionRange(
                        $argument,
                        $extractor,
                        $variable,
                        $lowerBound,
                        $upperBound,
                        $evaluationOptions,
                        $options,
                    );
                    if ($range === null || !\is_finite($range[0]) || !\is_finite($range[1])) {
                        $argumentRanges = [];
                        break;
                    }
                    $argumentRanges[] = $range;
                    $argumentSources[] = \substr(
                        $source,
                        $argument->span()->start - $sourceOffset,
                        $argument->span()->end - $argument->span()->start,
                    );
                }
                if (\count($argumentRanges) === 2 && $argumentSources[0] !== '' && $argumentSources[1] !== '') {
                    $sumRange = $this->widenArithmeticInterval(
                        $argumentRanges[0][0] + $argumentRanges[1][0],
                        $argumentRanges[0][1] + $argumentRanges[1][1],
                    );
                    if ($sumRange !== null) {
                        $firstSumPole = \max(-171.0, \ceil($sumRange[0]));
                        $lastSumPole = \min(0.0, \floor($sumRange[1]));
                        if ($lastSumPole >= $firstSumPole) {
                            if ($lastSumPole - $firstSumPole + 1.0 > self::MAX_DOMAIN_BOUNDARY_PROBES) {
                                throw new \DomainException(
                                    'The beta sum-pole set exceeds the equation boundary limit.',
                                );
                            }
                            for ($pole = $firstSumPole; $pole <= $lastSumPole; ++$pole) {
                                $equations[] = '(' . $argumentSources[0] . ')+('
                                    . $argumentSources[1] . ')=' . (int) $pole;
                            }
                        }
                    }
                }
            }
        }

        if (
            $node->name === 'zeta'
            && isset($node->arguments[0])
            && $this->containsVariable($node->arguments[0], $variable)
        ) {
            $argument = $node->arguments[0];
            $range = $this->boundedExpressionRange(
                $argument,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $options,
            );
            if ($range !== null && $range[0] <= 1.0 && $range[1] >= 1.0) {
                $expression = \substr(
                    $source,
                    $argument->span()->start - $sourceOffset,
                    $argument->span()->end - $argument->span()->start,
                );
                $equations[] = $expression . '=1';
            }
        }

        foreach ($node->arguments as $argument) {
            $equations = [
                ...$equations,
                ...$this->gammaBoundaryEquations(
                    $argument,
                    $source,
                    $sourceOffset,
                    $variable,
                    $extractor,
                    $lowerBound,
                    $upperBound,
                    $evaluationOptions,
                    $options,
                ),
            ];
        }

        return $equations;
    }

    /** @return list<string> */
    private function variableLogBaseOneBoundaryEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->variableLogBaseOneBoundaryEquations($node->left, $source, $sourceOffset, $variable),
                ...$this->variableLogBaseOneBoundaryEquations($node->right, $source, $sourceOffset, $variable),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->variableLogBaseOneBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->variableLogBaseOneBoundaryEquations(
                $node->expression,
                $source,
                $sourceOffset,
                $variable,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->variableLogBaseOneBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        if (
            $node->name === 'log'
            && \count($node->arguments) === 2
            && $this->containsVariable($node->arguments[1], $variable)
        ) {
            $base = $node->arguments[1];
            $expression = \substr(
                $source,
                $base->span()->start - $sourceOffset,
                $base->span()->end - $base->span()->start,
            );
            $equations[] = $expression . '=1';
        }
        foreach ($node->arguments as $argument) {
            $equations = [
                ...$equations,
                ...$this->variableLogBaseOneBoundaryEquations($argument, $source, $sourceOffset, $variable),
            ];
        }

        return $equations;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @return list<EquationSolution>|null
     */
    private function solveGammaCompositionEquation(
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        callable $residualAt,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && \in_array($left->name, ['gamma', 'lgamma'], true)
            && \count($left->arguments) === 1
            && !$this->containsVariable($right, $variable)
        ) {
            $function = $left;
            $functionSource = $leftSource;
            $functionSourceOffset = 0;
            $constant = $right;
        } elseif (
            $right instanceof FunctionCallNode
            && \in_array($right->name, ['gamma', 'lgamma'], true)
            && \count($right->arguments) === 1
            && !$this->containsVariable($left, $variable)
        ) {
            $function = $right;
            $functionSource = $rightSource;
            $functionSourceOffset = 0;
            $constant = $left;
        } else {
            return null;
        }

        $target = $this->extractPolynomial(
            $extractor,
            $constant,
            $constant->span()->start,
        );
        if ($target === null && !$this->containsVariable($constant, $variable)) {
            try {
                $constantValue = $this->evaluateNode($constant, $parameters, $evaluationOptions);
                $target = [(float) $constantValue];
            } catch (EvaluationException | \DomainException | \OverflowException) {
                $target = null;
            }
        }
        if ($target === null || \count($target) !== 1 || !\is_finite($target[0])) {
            return null;
        }
        if ($function->name === 'gamma' && $target[0] === 0.0) {
            return [];
        }

        $input = $function->arguments[0];
        if (!$this->containsVariable($input, $variable)) {
            return null;
        }

        if (
            $this->gammaCompositionHasEmptyLogarithmDomain(
                $input,
                $extractor,
                $variable,
                $lowerBound,
                $upperBound,
                $evaluationOptions,
                $solverOptions,
            )
        ) {
            return [];
        }

        $this->throwIfGammaCompositionArgumentHasTangentPole(
            $input,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );
        $this->throwIfGammaCompositionArgumentApproachesNegativeInfinity(
            $input,
            $extractor,
            $lowerBound,
            $upperBound,
            $solverOptions,
        );

        $inputSpan = $input->span();
        $inputSource = \substr(
            $functionSource,
            $inputSpan->start - $functionSourceOffset,
            $inputSpan->end - $inputSpan->start,
        );
        $levelVariable = 'mathphp_gamma_level';
        while (
            $levelVariable === $variable
            || \array_key_exists($levelVariable, $parameters)
            || \in_array($levelVariable, ['pi', 'e', 'tau', 'phi', 'eulerGamma', 'catalan', 'apery'], true)
        ) {
            $levelVariable = '_' . $levelVariable;
        }
        $gammaLevelLowerBound = -171.0;
        $gammaLevelUpperBound = 171.0;
        $hasBoundedGammaInputRange = false;
        $inputRange = $this->boundedExpressionRange(
            $input,
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
        );
        $unwrappedInput = $this->unwrapGrouping($input);
        if (
            $unwrappedInput instanceof FunctionCallNode
            && $unwrappedInput->name === 'lambertw'
            && \count($unwrappedInput->arguments) === 2
        ) {
            $branch = $this->extractPolynomial(
                $extractor,
                $unwrappedInput->arguments[1],
                $unwrappedInput->arguments[1]->span()->start,
            );
            if ($branch !== null && \count($branch) === 1 && $branch[0] === -1.0) {
                $inputRange = [-171.0, -1.0];
            }
        }
        if (
            $inputRange !== null
            && \is_finite($inputRange[0])
            && \is_finite($inputRange[1])
        ) {
            $rangePadding = static fn (float $bound): float => \max(
                1.0E-12,
                64.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($bound)),
            );
            $gammaLevelLowerBound = \max(
                $gammaLevelLowerBound,
                $inputRange[0] - $rangePadding($inputRange[0]),
            );
            $gammaLevelUpperBound = \min(
                $gammaLevelUpperBound,
                $inputRange[1] + $rangePadding($inputRange[1]),
            );
            if (
                $function->name === 'lgamma'
                && $inputRange[0] > 171.0
                && \is_finite($inputRange[1] + $rangePadding($inputRange[1]))
            ) {
                $gammaLevelUpperBound = $inputRange[1] + $rangePadding($inputRange[1]);
            }
            if ($gammaLevelLowerBound > $gammaLevelUpperBound) {
                return [];
            }
            $hasBoundedGammaInputRange =
                $gammaLevelLowerBound >= -171.0
                && $gammaLevelUpperBound <= 171.0;
        }
        if ($input instanceof VariableNode && !$hasBoundedGammaInputRange) {
            return null;
        }
        if ($gammaLevelLowerBound >= $gammaLevelUpperBound) {
            $gammaLevelLowerBound = -171.0;
            $gammaLevelUpperBound = 171.0;
        }

        $targetSource = \sprintf('%.17g', $target[0]);
        $gammaFunction = $evaluationOptions->functions->find($function->name);
        if ($gammaFunction === null) {
            return null;
        }
        if ($hasBoundedGammaInputRange) {
            $gammaAt = static fn (float $value): float => (float) $gammaFunction->invoke([$value]);
            $gammaLevels = $function->name === 'gamma'
                ? $this->invertGammaFunctionLevels(
                    $target[0],
                    $gammaLevelLowerBound,
                    $gammaLevelUpperBound,
                    $gammaAt,
                    $solverOptions,
                )
                : $this->invertLogGammaFunctionLevels(
                    $target[0],
                    $gammaLevelLowerBound,
                    $gammaLevelUpperBound,
                    $gammaAt,
                    $solverOptions,
                );
            if ($gammaLevels === null) {
                return null;
            }
            $gammaLevelSolutions = [];
            foreach ($gammaLevels as $gammaLevel) {
                try {
                    $levelResidual = $gammaAt($gammaLevel) - $target[0];
                } catch (\DomainException | \OverflowException | \InvalidArgumentException) {
                    continue;
                }
                if (\is_finite($levelResidual)) {
                    $gammaLevelSolutions[] = new EquationSolution(
                        $gammaLevel,
                        \abs($levelResidual),
                        0,
                    );
                }
            }
        } else {
            $gammaLevelSolutions = $this->solve(
                $function->name . '(' . $levelVariable . ')=' . $targetSource,
                $levelVariable,
                $gammaLevelLowerBound,
                $gammaLevelUpperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
        }
        if ($gammaFunction !== null) {
            $constantFunction = $this->unwrapGrouping($constant);
            if (
                $constantFunction instanceof FunctionCallNode
                && $constantFunction->name === $function->name
                && \count($constantFunction->arguments) === 1
                && !$this->containsVariable($constantFunction->arguments[0], $variable)
            ) {
                $exactLevel = $extractor->extract($constantFunction->arguments[0]);
                if (
                    $exactLevel !== null
                    && \count($exactLevel) === 1
                    && \is_finite($exactLevel[0])
                    && $exactLevel[0] >= $gammaLevelLowerBound
                    && $exactLevel[0] <= $gammaLevelUpperBound
                ) {
                    try {
                        $exactLevelValue = (float) $gammaFunction->invoke([$exactLevel[0]]);
                    } catch (\DomainException | \OverflowException) {
                        $exactLevelValue = null;
                    }
                    if (
                        $exactLevelValue !== null
                        && \abs($exactLevelValue - $target[0])
                            <= 16.0 * \PHP_FLOAT_EPSILON * \max(1.0, \abs($target[0]))
                    ) {
                        $exactLevelTolerance = 1.0E-10 * \max(1.0, \abs($exactLevel[0]));
                        $gammaLevelSolutions = \array_values(\array_filter(
                            $gammaLevelSolutions,
                            static fn (EquationSolution $solution): bool =>
                                \abs($solution->value - $exactLevel[0]) > $exactLevelTolerance,
                        ));
                        $this->addSolution(
                            $gammaLevelSolutions,
                            new EquationSolution($exactLevel[0], 0.0, 0),
                            $solverOptions,
                        );
                    }
                }
            }

            $firstIntegerLevel = 1;
            $lastIntegerLevel = 171;
            for ($integerLevel = $firstIntegerLevel; $integerLevel <= $lastIntegerLevel; ++$integerLevel) {
                try {
                    $integerValue = (float) $gammaFunction->invoke([$integerLevel]);
                } catch (\DomainException | \OverflowException) {
                    continue;
                }
                if ($integerValue === $target[0]) {
                    $integerTolerance = 1.0E-10 * \max(1.0, (float) $integerLevel);
                    $gammaLevelSolutions = \array_values(\array_filter(
                        $gammaLevelSolutions,
                        static fn (EquationSolution $solution): bool =>
                            \abs($solution->value - $integerLevel) > $integerTolerance,
                    ));
                    $this->addSolution(
                        $gammaLevelSolutions,
                        new EquationSolution($integerLevel, 0.0, 0),
                        $solverOptions,
                    );
                }
            }
        }
        $solutions = [];
        foreach ($gammaLevelSolutions as $gammaLevelSolution) {
            $gammaArgument = $gammaLevelSolution->value;
            if ($gammaArgument < -171.0 || $gammaArgument > 171.0) {
                continue;
            }
            $inputEquation = '(' . $inputSource . ')=('
                . \sprintf('%.17g', $gammaArgument)
                . ')';
            if (\strlen($inputEquation) > $evaluationOptions->limits->maxExpressionLength) {
                return null;
            }
            $inputSolutions = $this->solve(
                $inputEquation,
                $variable,
                $lowerBound,
                $upperBound,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($inputSolutions as $inputSolution) {
                $candidate = $inputSolution->value;
                $residual = $residualAt($candidate);
                [$candidate, $residual] = $this->bestRepresentableResidualCandidate(
                    $candidate,
                    $residual,
                    $lowerBound,
                    $upperBound,
                    $residualAt,
                );
                $compositionResidualTolerance = $function->name === 'gamma'
                    ? \max(1.0E-10, $solverOptions->residualTolerance * 10.0)
                    : \max(1.0E-8, $solverOptions->residualTolerance * 1000.0);
                if (
                    $residual === null
                    || !\is_finite($residual)
                    || \abs($residual) > $compositionResidualTolerance * \max(1.0, \abs($target[0]))
                ) {
                    continue;
                }
                $this->addSolution(
                    $solutions,
                    new EquationSolution(
                        $candidate,
                        \abs($residual),
                        $inputSolution->iterations,
                    ),
                    $solverOptions,
                );
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function throwIfGammaCompositionArgumentHasTangentPole(
        Node $input,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
    ): void {
        $input = $this->unwrapGrouping($input);
        if (
            !$input instanceof FunctionCallNode
            || $input->name !== 'tan'
            || \count($input->arguments) !== 1
        ) {
            return;
        }

        $phase = $this->extractPolynomial(
            $extractor,
            $input->arguments[0],
            $input->arguments[0]->span()->start,
        );
        if ($phase === null) {
            return;
        }
        $phaseRange = $this->polynomialRange($phase, $lowerBound, $upperBound, $solverOptions);
        if ($phaseRange === null || !\is_finite($phaseRange[0]) || !\is_finite($phaseRange[1])) {
            return;
        }

        $firstPoleIndex = (int) \ceil(($phaseRange[0] - (\M_PI / 2.0)) / \M_PI);
        $lastPoleIndex = (int) \floor(($phaseRange[1] - (\M_PI / 2.0)) / \M_PI);
        if ($firstPoleIndex > $lastPoleIndex) {
            return;
        }
        if ($lastPoleIndex - $firstPoleIndex > self::MAX_PERIODIC_ROOTS) {
            throw new RootSearchLimitException(
                'The tangent phase crosses too many poles to certify gamma-composition roots.',
            );
        }

        foreach (\range($firstPoleIndex, $lastPoleIndex) as $poleIndex) {
            $poleLevel = (\M_PI / 2.0) + ($poleIndex * \M_PI);
            $levelPolynomial = $phase;
            $levelPolynomial[0] -= $poleLevel;
            $poleRoots = $this->solvePolynomialRootsInInterval(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                $solverOptions,
            );
            if ($poleRoots === null) {
                continue;
            }
            foreach ($poleRoots as $root) {
                if (
                    $root->value > $lowerBound
                    && $root->value < $upperBound
                    && $this->polynomialRootMultiplicity($levelPolynomial, $root->value) % 2 === 1
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A gamma composition with a tangent argument has infinitely many roots '
                            . 'accumulating at a tangent pole.',
                    );
                }
            }
        }
    }

    private function gammaCompositionHasEmptyLogarithmDomain(
        Node $input,
        PolynomialExtractor $extractor,
        string $variable,
        float $lowerBound,
        float $upperBound,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
    ): bool {
        $input = $this->unwrapGrouping($input);
        if (
            !$input instanceof FunctionCallNode
            || !\in_array($input->name, ['ln', 'log1p', 'log10', 'log2'], true)
            || \count($input->arguments) !== 1
        ) {
            return false;
        }
        $argumentRange = $this->boundedExpressionRange(
            $input->arguments[0],
            $extractor,
            $variable,
            $lowerBound,
            $upperBound,
            $evaluationOptions,
            $solverOptions,
        );
        if ($argumentRange === null) {
            return false;
        }

        return $input->name === 'log1p'
            ? $argumentRange[1] <= -1.0
            : $argumentRange[1] <= 0.0;
    }

    private function throwIfGammaCompositionArgumentApproachesNegativeInfinity(
        Node $input,
        PolynomialExtractor $extractor,
        float $lowerBound,
        float $upperBound,
        SolverOptions $options,
    ): void {
        $input = $this->unwrapGrouping($input);
        if (
            !$input instanceof FunctionCallNode
            || !\in_array($input->name, ['ln', 'log1p', 'log10', 'log2'], true)
            || \count($input->arguments) !== 1
        ) {
            return;
        }
        $innerExpression = $this->unwrapGrouping($input->arguments[0]);
        $innerSign = 1.0;
        if ($innerExpression instanceof UnaryOperationNode) {
            if ($innerExpression->operator === UnaryOperator::Minus) {
                $innerSign = -1.0;
            }
            $innerExpression = $this->unwrapGrouping($innerExpression->operand);
        }
        $inner = $innerExpression;
        if (
            !$inner instanceof FunctionCallNode
            || !\in_array($inner->name, ['sin', 'cos'], true)
            || \count($inner->arguments) !== 1
        ) {
            return;
        }
        $phase = $this->extractPolynomial(
            $extractor,
            $inner->arguments[0],
            $inner->arguments[0]->span()->start,
        );
        if ($phase === null || \count($phase) <= 1) {
            return;
        }
        $phaseRange = $this->polynomialRange($phase, $lowerBound, $upperBound, $options);
        if ($phaseRange === null) {
            return;
        }
        $isLogOnePlus = $input->name === 'log1p';
        if ($isLogOnePlus) {
            $baseLevel = match ([$inner->name, $innerSign]) {
                ['sin', 1.0] => -\M_PI / 2.0,
                ['sin', -1.0] => \M_PI / 2.0,
                ['cos', 1.0] => \M_PI,
                ['cos', -1.0] => 0.0,
            };
        } else {
            $baseLevel = $inner->name === 'sin' ? 0.0 : \M_PI / 2.0;
        }
        $period = $isLogOnePlus ? 2.0 * \M_PI : \M_PI;
        $levels = $this->periodicLevelsWithinRange([$baseLevel], $period, $phaseRange);
        if ($levels === null) {
            return;
        }
        foreach ($levels as $level) {
            $levelPolynomial = $phase;
            $levelPolynomial[0] -= $level;
            $roots = $this->solvePolynomialRootsInInterval(
                $levelPolynomial,
                $lowerBound,
                $upperBound,
                $options,
            );
            if ($roots === null || $roots === []) {
                continue;
            }
            foreach ($roots as $root) {
                $multiplicity = $this->polynomialRootMultiplicity($levelPolynomial, $root->value);
                $hasPositiveLogDomain = $multiplicity % 2 === 1;
                if (!$isLogOnePlus && !$hasPositiveLogDomain) {
                    $localCoefficient = $this->polynomialLocalCoefficientSign(
                        $levelPolynomial,
                        $root->value,
                        $multiplicity,
                    );
                    if ($localCoefficient !== 0) {
                        $levelIndex = $inner->name === 'sin'
                            ? (int) \round($level / \M_PI)
                            : (int) \round(($level - (\M_PI / 2.0)) / \M_PI);
                        $trigonometricSign = $inner->name === 'sin'
                            ? (($levelIndex % 2 === 0) ? 1 : -1)
                            : (($levelIndex % 2 === 0) ? -1 : 1);
                        $hasPositiveLogDomain = $innerSign * $localCoefficient * $trigonometricSign > 0;
                    }
                }
                if (
                    $isLogOnePlus
                    || $hasPositiveLogDomain
                ) {
                    throw new InfiniteRootAccumulationException(
                        'A gamma composition with a logarithmic trigonometric argument has '
                            . 'infinitely many roots accumulating where its argument approaches '
                            . 'negative infinity.',
                    );
                }
            }
        }
    }

    /** @param list<float> $polynomial */
    private function polynomialLocalCoefficientSign(
        array $polynomial,
        float $root,
        int $multiplicity,
    ): int {
        for ($order = 0; $order < $multiplicity; ++$order) {
            $degree = \count($polynomial) - 1;
            if ($degree < 1) {
                return 0;
            }
            $quotient = \array_fill(0, $degree, 0.0);
            $quotient[$degree - 1] = $polynomial[$degree];
            for ($index = $degree - 1; $index > 0; --$index) {
                $quotient[$index - 1] = $polynomial[$index] + ($root * $quotient[$index]);
            }
            $polynomial = $quotient;
        }

        $coefficient = $this->polynomialValue($polynomial, $root);
        if ($coefficient === null || $coefficient === 0.0) {
            return 0;
        }

        return $coefficient > 0.0 ? 1 : -1;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @return array{float, ?float}
     */
    private function bestRepresentableResidualCandidate(
        float $value,
        ?float $residual,
        float $lowerBound,
        float $upperBound,
        callable $residualAt,
    ): array {
        $bestValue = $value;
        $bestResidual = $residual !== null && \is_finite($residual) ? $residual : null;
        foreach ([-1, 1] as $direction) {
            $position = $value;
            for ($step = 0; $step < 16; ++$step) {
                $neighbor = $this->adjacentFloat($position, $direction);
                if ($neighbor === null || $neighbor < $lowerBound || $neighbor > $upperBound) {
                    break;
                }
                $neighborResidual = $residualAt($neighbor);
                if (
                    $neighborResidual !== null
                    && \is_finite($neighborResidual)
                    && ($bestResidual === null || \abs($neighborResidual) < \abs($bestResidual))
                ) {
                    $bestValue = $neighbor;
                    $bestResidual = $neighborResidual;
                }
                $position = $neighbor;
            }
        }

        return [$bestValue, $bestResidual];
    }

    /**
     * @param list<string> $includedBoundaryEquations
     * @return list<string>
     */
    private function variableFunctionBoundaryEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array &$includedBoundaryEquations,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->variableFunctionBoundaryEquations(
                    $node->left,
                    $source,
                    $sourceOffset,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $includedBoundaryEquations,
                ),
                ...$this->variableFunctionBoundaryEquations(
                    $node->right,
                    $source,
                    $sourceOffset,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $includedBoundaryEquations,
                ),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->variableFunctionBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $includedBoundaryEquations,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->variableFunctionBoundaryEquations(
                $node->expression,
                $source,
                $sourceOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $includedBoundaryEquations,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->variableFunctionBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $lowerBound,
                $upperBound,
                $includedBoundaryEquations,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        $arguments = [];
        foreach ($node->arguments as $argument) {
            $arguments[] = \substr(
                $source,
                $argument->span()->start - $sourceOffset,
                $argument->span()->end - $argument->span()->start,
            );
            $equations = [
                ...$equations,
                ...$this->variableFunctionBoundaryEquations(
                    $argument,
                    $source,
                    $sourceOffset,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $includedBoundaryEquations,
                ),
            ];
        }

        $conditions = match ($node->name) {
            'csch', 'coth', 'acsch', 'ln', 'log10', 'log2' => [[0, '0', false]],
            'asech' => [[0, '0', false], [0, '1', true]],
            'sqrt' => [[0, '0', true]],
            'asin', 'acos', 'asec', 'acsc' => [
                [0, '-1', true],
                [0, '1', true],
            ],
            'acosh' => [[0, '1', true]],
            'lambertw' => [[0, '-1/e', true]],
            'acoth', 'atanh' => [[0, '-1', false], [0, '1', false]],
            'log1p' => [[0, '-1', false]],
            'log' => [[0, '0', false], [1, '0', false], [1, '1', false]],
            'tan', 'sec' => isset($arguments[0])
                ? [['cos(' . $arguments[0] . ')', '0', false]]
                : [],
            'csc', 'cot' => isset($arguments[0])
                ? [['sin(' . $arguments[0] . ')', '0', false]]
                : [],
            default => [],
        };
        foreach ($conditions as [$argumentIndex, $value, $included]) {
            $argumentNode = \is_int($argumentIndex)
                ? ($node->arguments[$argumentIndex] ?? null)
                : ($node->arguments[0] ?? null);
            if ($argumentNode === null || !$this->containsVariable($argumentNode, $variable)) {
                continue;
            }
            $expression = \is_int($argumentIndex)
                ? ($arguments[$argumentIndex] ?? null)
                : $argumentIndex;
            if ($expression !== null) {
                $boundaryEquation = $expression . '=' . $value;
                $equations[] = $boundaryEquation;
                if ($included) {
                    $includedBoundaryEquations[] = $boundaryEquation;
                }
            }
        }

        if (
            \in_array($node->name, ['gamma', 'lgamma'], true)
            && isset($node->arguments[0], $arguments[0])
        ) {
            $orientation = $this->signedVariableOrientation(
                $node->arguments[0],
                $variable,
            );
            if ($orientation !== null) {
                $firstPole = \max(
                    -171,
                    (int) \ceil(\min(
                        $orientation * $lowerBound,
                        $orientation * $upperBound,
                    )),
                );
                $lastPole = \min(
                    0,
                    (int) \floor(\max(
                        $orientation * $lowerBound,
                        $orientation * $upperBound,
                    )),
                );
                for ($pole = $firstPole; $pole <= $lastPole; ++$pole) {
                    $equations[] = $arguments[0] . '=' . $pole;
                }
            }
        }

        return $equations;
    }

    /**
     * Resample polynomial/rational Bessel arguments separately on each valid
     * domain component so a wide invalid tail cannot hide roots near a boundary.
     *
     * @param array<string, int|float> $parameters
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $candidateScaleAt
     * @return list<EquationSolution>|null
     */
    private function solveAcrossBesselArgumentDomains(
        string $equation,
        Node $left,
        Node $right,
        string $leftSource,
        string $rightSource,
        string $variable,
        float $lowerBound,
        float $upperBound,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        PolynomialExtractor $polynomialExtractor,
        RationalPolynomialExtractor $rationalPolynomialExtractor,
        callable $residualAt,
        callable $candidateScaleAt,
    ): ?array {
        $boundaryEquations = \array_unique([
            ...$this->besselArgumentBoundaryEquations(
                $left,
                $leftSource,
                0,
                $variable,
                $polynomialExtractor,
                $rationalPolynomialExtractor,
            ),
            ...$this->besselArgumentBoundaryEquations(
                $right,
                $rightSource,
                0,
                $variable,
                $polynomialExtractor,
                $rationalPolynomialExtractor,
            ),
        ]);
        if ($boundaryEquations === []) {
            return null;
        }

        $partitionPoints = [$lowerBound, $upperBound];
        foreach ($boundaryEquations as $boundaryEquation) {
            try {
                $boundaries = $this->solve(
                    $boundaryEquation,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $parameters,
                    $evaluationOptions,
                    $solverOptions,
                );
            } catch (\DomainException | \InvalidArgumentException) {
                return null;
            }
            foreach ($boundaries as $boundary) {
                if ($boundary->value > $lowerBound && $boundary->value < $upperBound) {
                    $partitionPoints[] = $boundary->value;
                }
            }
            if (\count($partitionPoints) > self::MAX_BESSEL_DOMAIN_SEGMENTS + 1) {
                return null;
            }
        }
        if (\count($partitionPoints) === 2) {
            return null;
        }

        \sort($partitionPoints, SORT_NUMERIC);
        $partitionPoints = \array_values(\array_unique($partitionPoints, SORT_REGULAR));
        if (\count($partitionPoints) - 1 > self::MAX_BESSEL_DOMAIN_SEGMENTS) {
            return null;
        }

        $solutions = [];
        for ($index = 1, $count = \count($partitionPoints); $index < $count; ++$index) {
            $segmentLower = $partitionPoints[$index - 1];
            $segmentUpper = $partitionPoints[$index];
            if (
                $this->hasBesselArgumentOutsideDomainOnInterval(
                    $left,
                    $variable,
                    $segmentLower,
                    $segmentUpper,
                    $solverOptions,
                    $polynomialExtractor,
                )
                || $this->hasBesselArgumentOutsideDomainOnInterval(
                    $right,
                    $variable,
                    $segmentLower,
                    $segmentUpper,
                    $solverOptions,
                    $polynomialExtractor,
                )
            ) {
                foreach ([$segmentLower, $segmentUpper] as $endpoint) {
                    $residual = $residualAt($endpoint);
                    if (
                        $residual !== null
                        && $this->isResidualAcceptableAt(
                            $endpoint,
                            $residual,
                            $candidateScaleAt,
                            $solverOptions,
                        )
                    ) {
                        $this->addDistinctSolution(
                            $solutions,
                            new EquationSolution($endpoint, \abs($residual), 0),
                        );
                    }
                }
                continue;
            }
            $segmentSolutions = $this->solve(
                $equation,
                $variable,
                $segmentLower,
                $segmentUpper,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            foreach ($segmentSolutions as $solution) {
                $this->addDistinctSolution($solutions, $solution);
            }
        }
        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    private function hasBesselArgumentOutsideDomainOnInterval(
        Node $node,
        string $variable,
        float $lowerBound,
        float $upperBound,
        SolverOptions $solverOptions,
        PolynomialExtractor $polynomialExtractor,
    ): bool {
        if ($node instanceof BinaryOperationNode) {
            return $this->hasBesselArgumentOutsideDomainOnInterval(
                $node->left,
                $variable,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $polynomialExtractor,
            ) || $this->hasBesselArgumentOutsideDomainOnInterval(
                $node->right,
                $variable,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $polynomialExtractor,
            );
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->hasBesselArgumentOutsideDomainOnInterval(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $polynomialExtractor,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->hasBesselArgumentOutsideDomainOnInterval(
                $node->expression,
                $variable,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $polynomialExtractor,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->hasBesselArgumentOutsideDomainOnInterval(
                $node->operand,
                $variable,
                $lowerBound,
                $upperBound,
                $solverOptions,
                $polynomialExtractor,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return false;
        }

        $limit = match ($node->name) {
            'besselj' => SpecialFunctions::MAX_BESSEL_J_ARGUMENT,
            'besseli' => SpecialFunctions::MAX_BESSEL_I_ARGUMENT,
            'bessely' => SpecialFunctions::MAX_BESSEL_Y_ARGUMENT,
            default => null,
        };
        $argument = $node->arguments[1] ?? null;
        if (
            $limit !== null
            && $argument !== null
            && $this->containsVariable($argument, $variable)
        ) {
            $coefficients = $polynomialExtractor->extract($argument);
            if ($coefficients !== null) {
                $range = $this->polynomialRange(
                    $coefficients,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                );
                if (
                    $range !== null
                    && (
                        (
                            $node->name === 'bessely'
                            && ($range[0] < 0.0 || $range[1] <= 0.0 || $range[1] > $limit)
                        )
                        || (
                            $node->name !== 'bessely'
                            && (
                                ($range[0] >= $limit && $range[1] > $limit)
                                || ($range[1] <= -$limit && $range[0] < -$limit)
                            )
                        )
                    )
                ) {
                    return true;
                }
            }
        }
        foreach ($node->arguments as $argument) {
            if (
                $this->hasBesselArgumentOutsideDomainOnInterval(
                    $argument,
                    $variable,
                    $lowerBound,
                    $upperBound,
                    $solverOptions,
                    $polynomialExtractor,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return list<string>
     */
    private function besselArgumentBoundaryEquations(
        Node $node,
        string $source,
        int $sourceOffset,
        string $variable,
        PolynomialExtractor $polynomialExtractor,
        RationalPolynomialExtractor $rationalPolynomialExtractor,
    ): array {
        if ($node instanceof BinaryOperationNode) {
            return [
                ...$this->besselArgumentBoundaryEquations(
                    $node->left,
                    $source,
                    $sourceOffset,
                    $variable,
                    $polynomialExtractor,
                    $rationalPolynomialExtractor,
                ),
                ...$this->besselArgumentBoundaryEquations(
                    $node->right,
                    $source,
                    $sourceOffset,
                    $variable,
                    $polynomialExtractor,
                    $rationalPolynomialExtractor,
                ),
            ];
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->besselArgumentBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $polynomialExtractor,
                $rationalPolynomialExtractor,
            );
        }
        if ($node instanceof GroupingNode) {
            return $this->besselArgumentBoundaryEquations(
                $node->expression,
                $source,
                $sourceOffset,
                $variable,
                $polynomialExtractor,
                $rationalPolynomialExtractor,
            );
        }
        if ($node instanceof FactorialNode) {
            return $this->besselArgumentBoundaryEquations(
                $node->operand,
                $source,
                $sourceOffset,
                $variable,
                $polynomialExtractor,
                $rationalPolynomialExtractor,
            );
        }
        if (!$node instanceof FunctionCallNode) {
            return [];
        }

        $equations = [];
        $argument = $node->arguments[1] ?? null;
        $limit = match ($node->name) {
            'besselj' => SpecialFunctions::MAX_BESSEL_J_ARGUMENT,
            'besseli' => SpecialFunctions::MAX_BESSEL_I_ARGUMENT,
            'bessely' => SpecialFunctions::MAX_BESSEL_Y_ARGUMENT,
            default => null,
        };
        if (
            $argument !== null
            && $limit !== null
            && $this->containsVariable($argument, $variable)
            && (
                $polynomialExtractor->extract($argument) !== null
                || $rationalPolynomialExtractor->extract($argument) !== null
            )
        ) {
            $span = $argument->span();
            $argumentSource = \substr($source, $span->start - $sourceOffset, $span->end - $span->start);
            if ($node->name === 'bessely') {
                $equations[] = $argumentSource . '=0';
                $equations[] = $argumentSource . '=' . \sprintf('%.17g', $limit);
            } else {
                $equations[] = $argumentSource . '=' . (string) $limit;
                $equations[] = $argumentSource . '=-' . (string) $limit;
            }
        }
        foreach ($node->arguments as $child) {
            $equations = [
                ...$equations,
                ...$this->besselArgumentBoundaryEquations(
                    $child,
                    $source,
                    $sourceOffset,
                    $variable,
                    $polynomialExtractor,
                    $rationalPolynomialExtractor,
                ),
            ];
        }

        return $equations;
    }

    private function signedVariableOrientation(Node $node, string $variable): ?float
    {
        if ($node instanceof VariableNode && $node->name === $variable) {
            return 1.0;
        }
        if ($node instanceof GroupingNode) {
            return $this->signedVariableOrientation($node->expression, $variable);
        }
        if ($node instanceof UnaryOperationNode) {
            $orientation = $this->signedVariableOrientation($node->operand, $variable);
            if ($orientation !== null && $node->operator->value === '-') {
                return -$orientation;
            }

            return $orientation;
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function isPolynomialNonzeroAt(
        Node $node,
        string $variable,
        float $value,
        array $parameters,
        EvaluationOptions $options,
        int $maxDegree,
    ): bool {
        $coefficients = $this->extractPolynomial(
            new PolynomialExtractor($variable, $parameters, $options, $maxDegree),
            $node,
            0,
        );
        if ($coefficients === null) {
            return false;
        }

        try {
            $numerator = (float) $this->evaluateNode(
                $node,
                [...$parameters, $variable => $value],
                $options,
            );
        } catch (EvaluationException) {
            return false;
        }

        $scale = 0.0;
        $power = 1.0;
        foreach ($coefficients as $coefficient) {
            $term = \abs($coefficient * $power);
            if (!\is_finite($term)) {
                return false;
            }
            $scale += $term;
            if (!\is_finite($scale)) {
                return false;
            }
            $power *= \abs($value);
        }

        return $scale === 0.0
            ? $numerator !== 0.0
            : \abs($numerator) > 8.0 * \PHP_FLOAT_EPSILON * $scale;
    }

    /**
     * @param callable(float): ?float $residualAt
     * @param callable(float): bool $isCustomDomainFailureAt
     * @return list<EquationSolution>
     */
    private function bisect(
        callable $residualAt,
        float $left,
        float $leftResidual,
        float $right,
        SolverOptions $options,
        callable $residualScaleAt,
        callable $isCustomDomainFailureAt,
        int $domainRecoveryDepth = 0,
    ): array {
        for ($iteration = 1; $iteration <= $options->maxIterations; ++$iteration) {
            $midpoint = $left + (($right - $left) / 2.0);
            if ($midpoint === $left || $midpoint === $right) {
                $residual = $residualAt($midpoint);

                return $residual !== null
                    && $this->isResidualAcceptableAt(
                        $midpoint,
                        $residual,
                        $residualScaleAt,
                        $options,
                    )
                    ? [new EquationSolution($midpoint, \abs($residual), $iteration)]
                    : [];
            }

            $residual = $residualAt($midpoint);
            if ($residual === null) {
                if (
                    !$isCustomDomainFailureAt($midpoint)
                    || $domainRecoveryDepth >= self::MAX_DOMAIN_RECOVERY_DEPTH
                ) {
                    return [];
                }

                $leftBoundary = $this->nearestDefinedSampleAtTransition(
                    $residualAt,
                    $left,
                    $leftResidual,
                    $midpoint,
                    null,
                    $options,
                );
                $rightResidual = $residualAt($right);
                $rightBoundary = $rightResidual === null
                    ? null
                    : $this->nearestDefinedSampleAtTransition(
                        $residualAt,
                        $midpoint,
                        null,
                        $right,
                        $rightResidual,
                        $options,
                    );
                $solutions = [];
                if (
                    $leftBoundary !== null
                    && $this->hasOppositeSigns($leftResidual, $leftBoundary[1])
                ) {
                    $solutions = \array_merge(
                        $solutions,
                        $this->bisect(
                            $residualAt,
                            $left,
                            $leftResidual,
                            $leftBoundary[0],
                            $options,
                            $residualScaleAt,
                            $isCustomDomainFailureAt,
                            $domainRecoveryDepth + 1,
                        ),
                    );
                }
                if (
                    $rightBoundary !== null
                    && $this->hasOppositeSigns($rightBoundary[1], $rightResidual)
                ) {
                    $solutions = \array_merge(
                        $solutions,
                        $this->bisect(
                            $residualAt,
                            $rightBoundary[0],
                            $rightBoundary[1],
                            $right,
                            $options,
                            $residualScaleAt,
                            $isCustomDomainFailureAt,
                            $domainRecoveryDepth + 1,
                        ),
                    );
                }

                return $solutions;
            }

            if ($residual === 0.0) {
                return [new EquationSolution($midpoint, \abs($residual), $iteration)];
            }

            if (
                $right - $left
                <= $options->positionTolerance($left, $right)
                && $this->isResidualAcceptableAt(
                    $midpoint,
                    $residual,
                    $residualScaleAt,
                    $options,
                )
            ) {
                return [new EquationSolution($midpoint, \abs($residual), $iteration)];
            }

            if ($this->hasOppositeSigns($leftResidual, $residual)) {
                $right = $midpoint;
            } else {
                $left = $midpoint;
                $leftResidual = $residual;
            }
        }

        $midpoint = $left + (($right - $left) / 2.0);
        $residual = $residualAt($midpoint);

        return $residual !== null
            && $this->isResidualAcceptableAt(
                $midpoint,
                $residual,
                $residualScaleAt,
                $options,
            )
            ? [new EquationSolution($midpoint, \abs($residual), $options->maxIterations)]
            : [];
    }

    /**
     * Refine a sampled local minimum of the absolute residual, which can find
     * roots that touch zero without changing sign.
     *
     * @param callable(float): ?float $residualAt
     */
    private function minimizeResidual(
        callable $residualAt,
        float $left,
        float $right,
        SolverOptions $options,
        callable $residualScaleAt,
        callable $derivativeAt,
    ): ?EquationSolution {
        $ratio = (\sqrt(5.0) - 1.0) / 2.0;
        $first = $right - $ratio * ($right - $left);
        $second = $left + $ratio * ($right - $left);
        $firstResidual = $residualAt($first);
        $secondResidual = $residualAt($second);

        $bestPosition = null;
        $bestResidual = \INF;
        $iterations = 0;
        for ($iteration = 1; $iteration <= $options->maxIterations; ++$iteration) {
            $iterations = $iteration;
            foreach ([[$first, $firstResidual], [$second, $secondResidual]] as [$candidate, $candidateResidual]) {
                if ($candidateResidual !== null && \abs($candidateResidual) < $bestResidual) {
                    $bestPosition = $candidate;
                    $bestResidual = \abs($candidateResidual);
                }
            }
            if ($right - $left <= $options->positionTolerance($left, $right)) {
                break;
            }
            $firstMagnitude = $firstResidual === null ? \INF : \abs($firstResidual);
            $secondMagnitude = $secondResidual === null ? \INF : \abs($secondResidual);
            if ($firstMagnitude <= $secondMagnitude) {
                $right = $second;
                $second = $first;
                $secondResidual = $firstResidual;
                $first = $right - $ratio * ($right - $left);
                $firstResidual = $residualAt($first);
            } else {
                $left = $first;
                $first = $second;
                $firstResidual = $secondResidual;
                $second = $left + $ratio * ($right - $left);
                $secondResidual = $residualAt($second);
            }
        }

        return $bestPosition !== null
            && $this->isRootLikeResidualAt(
                $bestPosition,
                $bestResidual,
                $residualScaleAt,
                $options,
                $derivativeAt,
            )
            ? new EquationSolution($bestPosition, $bestResidual, $iterations)
            : null;
    }

    /**
     * Accept stationary candidates only at roundoff, while allowing a
     * tolerance-level residual when the candidate is a simple crossing.
     *
     * @param callable(float): ?float $residualScaleAt
     * @param callable(float): ?float $derivativeAt
     */
    private function isRootLikeResidualAt(
        float $position,
        float $residual,
        callable $residualScaleAt,
        SolverOptions $options,
        callable $derivativeAt,
    ): bool {
        if (!$this->isResidualAcceptableAt($position, $residual, $residualScaleAt, $options)) {
            return false;
        }

        $derivative = $derivativeAt($position);
        $scale = $residualScaleAt($position);

        return $derivative !== null
            && $scale !== null
            && \abs($derivative) > \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, $scale);
    }

    /** @param callable(float): ?float $residualScaleAt */
    private function candidateResidualScaleAt(
        callable $residualScaleAt,
        float $position,
        float $lowerBound,
        float $upperBound,
        int $scanSteps,
    ): ?float {
        $scale = $residualScaleAt($position);
        if ($scale === null) {
            return null;
        }

        $localDistance = 0.01 * \max(1.0, \abs($position));
        $maxProbeDistance = \min(($upperBound - $lowerBound) / $scanSteps, $localDistance);
        foreach ([0.3819660112501051, 0.6180339887498949] as $fraction) {
            $probeDistance = $maxProbeDistance * $fraction;
            $probeScales = [];
            foreach ([-1.0, 1.0] as $direction) {
                $probe = $position + ($direction * $probeDistance);
                if ($probe <= $lowerBound || $probe >= $upperBound) {
                    continue;
                }
                $probeScale = $residualScaleAt($probe);
                if ($probeScale !== null) {
                    $probeScales[] = $probeScale;
                }
            }
            if ($probeScales !== []) {
                $localScale = \count($probeScales) === 2
                    ? \sqrt($probeScales[0]) * \sqrt($probeScales[1])
                    : $probeScales[0];
                $scale = \max($scale, $localScale);
            }
        }

        return $scale === 0.0 ? 1.0 : $scale;
    }

    /**
     * Accept a verified transformed root when its Newton correction is below
     * the resolution of the floating-point variable representation.
     *
     * @param callable(float): ?float $residualAt
     */
    private function isCandidateAtFloatingPointRootResolution(
        float $value,
        float $residual,
        callable $residualAt,
    ): bool {
        $resolution = \PHP_FLOAT_EPSILON * \max(\abs($value), \PHP_FLOAT_MIN);
        $leftValue = $value - $resolution;
        $rightValue = $value + $resolution;
        $leftResidual = $leftValue === $value ? null : $residualAt($leftValue);
        $rightResidual = $rightValue === $value ? null : $residualAt($rightValue);
        if ($leftResidual === null || $rightResidual === null) {
            return false;
        }
        if (
            \abs($residual) > \abs($leftResidual)
            || \abs($residual) > \abs($rightResidual)
        ) {
            return false;
        }

        $derivative = ($rightResidual - $leftResidual) / ($rightValue - $leftValue);
        if ($derivative === 0.0 || !\is_finite($derivative)) {
            return false;
        }

        $correction = \abs($residual / $derivative);

        return \is_finite($correction) && $correction <= (0.5 * $resolution);
    }

    /** @param callable(float): ?float $residualScaleAt */
    private function isResidualAcceptableAt(
        float $position,
        float $residual,
        callable $residualScaleAt,
        SolverOptions $options,
    ): bool {
        $scale = $residualScaleAt($position);
        if ($scale === null || !\is_finite($scale)) {
            return false;
        }
        $scale = \max($scale, \abs($residual));
        if ($scale === 0.0) {
            $scale = 1.0;
        }

        return \abs($residual / $scale)
            <= $options->residualTolerance + (8.0 * \PHP_FLOAT_EPSILON);
    }

    /** @param callable(float): ?float $residualScaleAt */
    private function isResidualAtNumericalZero(
        float $position,
        float $residual,
        callable $residualScaleAt,
    ): bool {
        $scale = $residualScaleAt($position);
        if ($scale === null || !\is_finite($scale)) {
            return false;
        }

        return \abs($residual)
            <= 32.0 * \PHP_FLOAT_EPSILON * \max(1.0, $scale, \abs($residual));
    }

    private function hasOppositeSigns(float $left, float $right): bool
    {
        return ($left < 0.0 && $right > 0.0)
            || ($left > 0.0 && $right < 0.0);
    }

    /**
     * @param callable(float): ?float $residualAt
     * @return list<array{float, ?float}>
     */
    private function offGridSamples(
        callable $residualAt,
        float $lowerBound,
        float $upperBound,
    ): array {
        $residuals = [];
        foreach ($this->intervalProbePositions($lowerBound, $upperBound) as $position) {
            $residuals[] = [$position, $residualAt($position)];
        }

        return $residuals;
    }

    /** @return list<float> */
    private function intervalProbePositions(float $lowerBound, float $upperBound): array
    {
        if (\is_finite($lowerBound) && \is_finite($upperBound)) {
            $positions = [];
            foreach ([0.125, 0.375, 0.625, 0.875] as $fraction) {
                $positions[] = $this->interpolateFiniteInterval($lowerBound, $upperBound, $fraction);
            }

            return \array_values(\array_unique($positions, SORT_REGULAR));
        }

        $positions = $this->geometricIntervalSamplePositions($lowerBound, $upperBound);
        \sort($positions, SORT_NUMERIC);
        $positionCount = \count($positions);

        return $positionCount === 0
            ? []
            : \array_values(\array_unique([
                $positions[0],
                $positions[intdiv($positionCount, 2)],
                $positions[$positionCount - 1],
            ], SORT_REGULAR));
    }

    /**
     * Refine a scan interval with one defined and one undefined endpoint.
     *
     * @param callable(float): ?float $residualAt
     * @return array{float, float}|null Nearest defined point and its residual.
     */
    private function nearestDefinedSampleAtTransition(
        callable $residualAt,
        float $left,
        ?float $leftResidual,
        float $right,
        ?float $rightResidual,
        SolverOptions $options,
    ): ?array {
        if (($leftResidual === null) === ($rightResidual === null)) {
            return null;
        }

        $leftIsDefined = $leftResidual !== null;
        for ($iteration = 0; $iteration < self::MAX_DOMAIN_TRANSITION_BISECTIONS; ++$iteration) {
            if ($right - $left <= $options->positionTolerance($left, $right)) {
                break;
            }
            $middle = $left + (($right - $left) / 2.0);
            if ($middle === $left || $middle === $right) {
                break;
            }
            $middleResidual = $residualAt($middle);
            if ($leftIsDefined) {
                if ($middleResidual === null) {
                    $right = $middle;
                } else {
                    $left = $middle;
                    $leftResidual = $middleResidual;
                }
            } elseif ($middleResidual === null) {
                $left = $middle;
            } else {
                $right = $middle;
                $rightResidual = $middleResidual;
            }
        }

        if ($leftIsDefined) {
            return [$left, $leftResidual];
        }

        return $rightResidual === null ? null : [$right, $rightResidual];
    }

    /**
     * @param callable(float): ?float $function
     * @param (callable(float): ?float)|null $derivativeAt
     */
    private function bisectDerivative(
        NumericalDifferentiator $differentiator,
        callable $function,
        float $left,
        float $leftDerivative,
        float $right,
        SolverOptions $options,
        ?callable $derivativeAt = null,
    ): ?float {
        for ($iteration = 0; $iteration < $options->maxIterations; ++$iteration) {
            $middle = $left + (($right - $left) / 2.0);
            if ($middle === $left || $middle === $right) {
                return $middle;
            }
            $derivative = $derivativeAt === null
                ? $differentiator->differentiate($function, $middle)
                : $derivativeAt($middle);
            if ($derivative === null) {
                return null;
            }
            if ($derivative === 0.0) {
                return $middle;
            }

            if ($this->hasOppositeSigns($leftDerivative, $derivative)) {
                $right = $middle;
            } else {
                $left = $middle;
                $leftDerivative = $derivative;
            }
        }

        return null;
    }

    /**
     * Merge contiguous terminal boxes from interval root isolation.
     *
     * @param list<array{float, float, EquationSolution}> $regions
     * @param list<array{float, float}>|null $rootBounds
     * @param-out list<array{float, float}> $rootBounds
     * @return list<EquationSolution>
     */
    private function mergeIntervalRegions(array $regions, ?array &$rootBounds = null): array
    {
        if ($regions === []) {
            $rootBounds = [];

            return [];
        }
        \usort(
            $regions,
            static fn (array $first, array $second): int =>
                ($first[0] <=> $second[0]) ?: ($first[1] <=> $second[1]),
        );

        /** @var list<array{float, float, list<EquationSolution>}> $mergedRegions */
        $mergedRegions = [];
        foreach ($regions as [$lower, $upper, $solution]) {
            $lastIndex = \count($mergedRegions) - 1;
            if ($lastIndex < 0) {
                $mergedRegions[] = [$lower, $upper, [$solution]];
                continue;
            }
            // Subdivision siblings share exact midpoint floats; gaps must not merge distinct roots.
            if ($lower > $mergedRegions[$lastIndex][1]) {
                $mergedRegions[] = [$lower, $upper, [$solution]];
                continue;
            }
            [$mergedLower, $mergedUpper, $mergedCandidates] = $mergedRegions[$lastIndex];
            $mergedRegions[$lastIndex] = [
                $mergedLower,
                \max($mergedUpper, $upper),
                [...$mergedCandidates, $solution],
            ];
        }

        $solutions = [];
        $rootBounds = [];
        foreach ($mergedRegions as [$lower, $upper, $candidates]) {
            $rootBounds[] = [$lower, $upper];
            $middle = $lower + (($upper - $lower) / 2.0);
            \usort(
                $candidates,
                static fn (EquationSolution $first, EquationSolution $second): int =>
                    ($first->residual <=> $second->residual)
                    ?: (\abs($first->value - $middle) <=> \abs($second->value - $middle)),
            );
            $this->addDistinctSolution($solutions, $candidates[0]);
        }

        \usort(
            $solutions,
            static fn (EquationSolution $first, EquationSolution $second): int =>
                $first->value <=> $second->value,
        );

        return $solutions;
    }

    /**
     * @param list<EquationSolution> $solutions
     */
    private function addSolution(
        array &$solutions,
        EquationSolution $candidate,
        SolverOptions $options,
    ): void {
        foreach ($solutions as $index => $solution) {
            if (
                ($solution->value < 0.0 && $candidate->value > 0.0)
                || ($solution->value > 0.0 && $candidate->value < 0.0)
            ) {
                continue;
            }

            $deduplicationTolerance = $options->positionTolerance(
                $solution->value,
                $candidate->value,
            );
            if ($solution->residual === 0.0 && $candidate->residual === 0.0) {
                $rootScale = \max(
                    \abs($solution->value),
                    \abs($candidate->value),
                );
                if ($options->absoluteTolerance >= \PHP_FLOAT_EPSILON) {
                    $rootScale = \max(1.0, $rootScale);
                } else {
                    $rootScale = \max(\PHP_FLOAT_MIN, $rootScale);
                }
                $deduplicationTolerance = \max(
                    $deduplicationTolerance,
                    \sqrt(\PHP_FLOAT_EPSILON) * $rootScale,
                );
            }
            if (
                \abs($solution->value - $candidate->value)
                <= $deduplicationTolerance
            ) {
                if (
                    \abs($candidate->residual) < \abs($solution->residual)
                    || (
                        $candidate->residual === $solution->residual
                        && $candidate->iterations < $solution->iterations
                    )
                ) {
                    $solutions[$index] = $candidate;
                }

                return;
            }
        }

        $solutions[] = $candidate;
    }

    /** @param list<EquationSolution> $solutions */
    private function addDistinctRepresentableSolution(
        array &$solutions,
        EquationSolution $candidate,
    ): void {
        foreach ($solutions as $index => $solution) {
            $scale = \max(\abs($solution->value), \abs($candidate->value));
            $next = $this->adjacentFloat($scale, 1);
            $ulp = $next === null ? \PHP_FLOAT_EPSILON * $scale : $next - $scale;
            $tolerance = 8.0 * \max($ulp, \PHP_FLOAT_MIN);
            if (\abs($solution->value - $candidate->value) <= $tolerance) {
                if (\abs($candidate->residual) < \abs($solution->residual)) {
                    $solutions[$index] = $candidate;
                }

                return;
            }
        }

        $solutions[] = $candidate;
    }

    /**
     * Merge same-sign neighboring candidates when their floating-point root
     * uncertainty intervals overlap. Opposite-sign roots remain distinct.
     *
     * @param list<EquationSolution> $solutions
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     * @return list<EquationSolution>
     */
    private function mergeNumericallyIndistinguishableRoots(
        array $solutions,
        callable $residualAt,
        callable $residualScaleAt,
    ): array {
        if (\count($solutions) < 2) {
            return $solutions;
        }

        \usort(
            $solutions,
            static fn (EquationSolution $left, EquationSolution $right): int =>
                $left->value <=> $right->value,
        );
        $differentiator = new NumericalDifferentiator();
        $merged = [];
        foreach ($solutions as $candidate) {
            $lastIndex = \count($merged) - 1;
            if ($lastIndex < 0) {
                $merged[] = $candidate;
                continue;
            }

            $previous = $merged[$lastIndex];
            if (
                ($previous->value < 0.0 && $candidate->value > 0.0)
                || ($previous->value > 0.0 && $candidate->value < 0.0)
            ) {
                $merged[] = $candidate;
                continue;
            }

            $distance = \abs($candidate->value - $previous->value);
            $positionScale = \max(1.0, \abs($candidate->value), \abs($previous->value));
            if ($distance > 8.0 * \sqrt(\PHP_FLOAT_EPSILON) * $positionScale) {
                $merged[] = $candidate;
                continue;
            }

            $previousUncertainty = $this->rootRoundingUncertainty(
                $previous->value,
                $residualAt,
                $residualScaleAt,
                $differentiator,
            );
            $candidateUncertainty = $this->rootRoundingUncertainty(
                $candidate->value,
                $residualAt,
                $residualScaleAt,
                $differentiator,
            );
            if (
                $previousUncertainty === null
                || $candidateUncertainty === null
                || $distance > $previousUncertainty + $candidateUncertainty
            ) {
                $merged[] = $candidate;
                continue;
            }

            if (\abs($candidate->residual) < \abs($previous->residual)) {
                $merged[$lastIndex] = $candidate;
            }
        }

        return \array_values($merged);
    }

    /**
     * Estimate the input uncertainty caused by rounding the equation residual.
     *
     * @param callable(float): ?float $residualAt
     * @param callable(float): ?float $residualScaleAt
     */
    private function rootRoundingUncertainty(
        float $value,
        callable $residualAt,
        callable $residualScaleAt,
        NumericalDifferentiator $differentiator,
    ): ?float {
        $scale = $residualScaleAt($value);
        $slope = $differentiator->differentiate($residualAt, $value);
        if (
            $scale === null
            || !\is_finite($scale)
            || $slope === null
            || !\is_finite($slope)
            || \abs($slope) <= \sqrt(\PHP_FLOAT_EPSILON) * \max(1.0, $scale)
        ) {
            return null;
        }

        $uncertainty = 4.0 * \PHP_FLOAT_EPSILON * \max(1.0, $scale) / \abs($slope);

        return \is_finite($uncertainty) ? $uncertainty : null;
    }

    /** @param list<EquationSolution> $solutions */
    private function addDistinctSolution(
        array &$solutions,
        EquationSolution $candidate,
    ): void {
        foreach ($solutions as $index => $solution) {
            if ($solution->value !== $candidate->value) {
                continue;
            }
            if ($candidate->residual < $solution->residual) {
                $solutions[$index] = $candidate;
            }

            return;
        }

        $solutions[] = $candidate;
    }
}
